  ui_story_1011_10110101_106_dialog_content = "역시 네 그런 점은 전혀 변하지 않았구나, 가자고.",
  ui_story_1011_10110101_107_dialog_content = "좋아, 출발하자!",
  ui_story_1011_10110101_108_dialog_content = "『콜로서스는 방어선으로 돌아와서 헤븐즈 밸리를 향하고 있습니다.』",
  ui_story_1011_10110101_109_dialog_content = "『계속 감시해라.』",
  ui_story_1011_10110101_110_dialog_content = "『역시 움직이기 시작했네.』",
  ui_story_1011_10110101_111_dialog_content = "『잊지 마라. 이건 네 경솔한 행동을 수습해 주고 있는 거다.』",
  ui_story_1011_10110101_112_dialog_content = "『넌 그저 쓸모없는 쓰레기만 가져왔고,\n진정으로 가치가 있는 건 놓쳤으니 말이야...』",
  ui_story_1011_10110101_113_dialog_content = "『그건 일종의 열쇠야. 콜로서스를 다루는 아이테르만이 사용할 수 있는 거라고.』",
  ui_story_1011_10110101_114_dialog_content = "『둘 중 하나라도 없다면 쓸모없는 고철이나 다를 게 없어.』",
  ui_story_1011_10110101_115_dialog_content = "『머리를 좀 써 봐. 그 아이테르가 제 발로 길을 안내하게 만드는 게,\n녀석을 잡는 것보다 훨씬 편하지 않겠어?』",
  ui_story_1011_10110101_116_dialog_content = "『말은 그럴싸하군.』",
  ui_story_1011_10110101_117_dialog_content = "『내 실험은 절대 실패하지 않아.』",
  ui_story_1011_10110101_118_dialog_content = "......",
  ui_story_1011_10110101_119_dialog_content = "『허나 넌 결국 반쪽짜리 오로리안일 뿐이지 않은가.』",
  ui_story_1011_10110101_120_dialog_content = "『듣거라──』",
  ui_story_1011_10110101_121_dialog_content = "『예.』",
  ui_story_1011_10110101_122_dialog_content = "『헤븐즈 밸리로 가는 길에 매복해라.』",
  ui_story_1011_10110101_123_dialog_content = "『가서 콜로서스와 그 녀석을 모두 잡아 와라.』",
  ui_story_1011_10110101_124_dialog_content = "『예!』",
  ui_story_1011_10110101_125_dialog_content = "다음으로 군단장 여러분에 대한 최근의 지시사항을 말씀드리겠습니다.",
  ui_story_1011_10110101_126_dialog_content = "대원수님께서는 중상을 입어 요양이 필요하므로, 당분간──",
  ui_story_1011_10110101_127_dialog_content = "대원수직은 라인하르트 대원수님께서 회복할 때까지 위원회에서 대행합니다.",
  ui_story_1011_10110101_128_dialog_content = "대체 무슨 일이 있었던 거지? 왜 그렇게 심하게 다친 건데?",
  ui_story_1011_10110101_129_dialog_content = "자세한 상황은 현재 조사 중입니다. 조금만 기다려 주십시오. 레이스 군단장님.",
  ui_story_1011_10110101_130_dialog_content = "그리고 다른 명령입니다.\n각 군단은 방어 태세를 유지하고, 선제적인 공세를 취하지 마십시오.",
  ui_story_1011_10110101_131_dialog_content = "방어? 지금 장난하나?",
  ui_story_1011_10110101_132_dialog_content = "저 암귀 떼가 벌써 집 앞까지 왔는데 선제 공격을 하지 말라니,\n설마 가만히 앉아서 얻어맞으라는 거냐?",
  ui_story_1011_10110101_133_dialog_content = "바튼 군단장님, 우려하시는 점은 이해합니다.",
  ui_story_1011_10110101_134_dialog_content = "이클립스가 대원수님께 해를 입힌 것은 결코 좌시해선 안 될 일입니다.",
  ui_story_1011_10110101_135_dialog_content = "하지만 지금은 특수한 상황입니다.",
  ui_story_1011_10110101_136_dialog_content = "방금 입수한 정보에 따르면, 암귀 무리가 헤븐즈 밸리 방향으로 집결 중에 있고,\n저들의 목적은 아직 명확하지 않습니다.",
  ui_story_1011_10110101_137_dialog_content = "위원회는 저들이 일루미나 연방을 위협할 의도를 드러내기 전까지는\n당분간 지켜보는 쪽이 좋겠다고 판단했습니다.",
  ui_story_1011_10110101_138_dialog_content = "성급한 공격은 아군의 손실만 확대할 뿐이므로, 방어가 최선의 선택입니다.",
  ui_story_1011_10110101_139_dialog_content = "개뿔도 모르는 자식들이!",
  ui_story_1011_10110101_140_dialog_content = "여긴 전장이다. 승리의 기회는 한 번 놓치면 다시는 돌아오지 않는다고.",
  ui_story_1011_10110101_141_dialog_content = "저 암귀들이 모습을 드러냈을 때 곧바로 제압해 놔야 한단 말이다!",
  ui_story_1011_10110101_142_dialog_content = "안 그러면 점점 더 모여들어 결국엔 우릴 집어삼키고 말 거다.",
  ui_story_1011_10110101_143_dialog_content = "그렇게 몸이나 사리는 네놈들의 무사안일주의가 언젠간 일루미나에 큰 화를 불러올 거다!",
  ui_story_1011_10110101_144_dialog_content = "바튼 군단장님, 지나친 언사는 삼가시지요!",
  ui_story_1011_10110101_145_dialog_content = "위원회의 결정은 군령입니다.",
  ui_story_1011_10110101_146_dialog_content = "거스르는 자는 군사법정에 회부될 것입니다.",
  ui_story_1011_10110101_147_dialog_content = "회의는 이상입니다.",
  ui_story_1011_10110101_148_dialog_content = "쳇...",
  ui_story_1011_10110101_150_dialog_content = "암귀가 코앞에 와 있는데 방어나 하라고?",
  ui_story_1011_10110101_151_dialog_content = "확실히 이상하군요.",
  ui_story_1011_10110101_154_dialog_content = "그러니까 우린 당장 군단을 진군시켜 저 암귀 놈들을 쓸어버려야 한다고.",
  ui_story_1011_10110101_155_dialog_content = "아니요, 전 출병하지 않을 겁니다.",
  ui_story_1011_10110101_156_dialog_content = "뭐야?",
  ui_story_1011_10110101_157_dialog_content = "대원수님 또한 위원회의 일원입니다. 이게 대원수님의 결정이라면 전 따를 겁니다.",
  ui_story_1011_10110101_158_dialog_content = "이번 대응 결정은 확실히 이상하긴 하지만, 아마 대원수님께서도 고려하신 일일 겁니다.",
  ui_story_1011_10110101_159_dialog_content = "아무리 라인하르트라 해도 인간인 이상 잘못 판단할 때가 있을 거라고.",
  ui_story_1011_10110101_160_dialog_content = "레이스, 안 그런가?",
  ui_story_1011_10110101_161_dialog_content = "상관없어.",
  ui_story_1011_10110101_162_dialog_content = "난 그저 정정당당하게 라인하르트를 쓰러트리고, 일루미나의 대원수가 되고 싶을 뿐이야.",
  ui_story_1011_10110101_163_dialog_content = "나머지 일은 공격이든 방어든 내가 판단할 문제가 아냐.",
  ui_story_1011_10110101_164_dialog_content = "그건 라인하르트가 판단할 문제지.",
  ui_story_1011_10110101_165_dialog_content = "쳇... 그럼 너흰 전부 겁쟁이처럼 지하성에 틀어박혀 있겠다는 거냐?",
  ui_story_1011_10110101_166_dialog_content = "암귀가 쳐들어온다면 맞서 싸울 겁니다.",
  ui_story_1011_10110101_167_dialog_content = "하지만 전 경솔한 행동으로 일루미나의 거시적인 전략을 깨트릴 생각은 없습니다.",
  ui_story_1011_10110101_168_dialog_content = "충고하는데 괜한 문제를 일으키지 않는 게 좋을 겁니다, 바튼.",
  ui_story_1011_10110101_169_dialog_content = "......",
  ui_story_1011_10110101_170_dialog_content = "상부에선 대체 무슨 생각을 하고 있는 거냐!",
  ui_story_1011_10110101_171_dialog_content = "설마 하나같이 너무 편하게 지내서 무뎌지기라도 한 건가?\n암귀가 얼마나 많은 일루미나인을 죽였는지 잊어버렸냔 말이다!",
  ui_story_1011_10110101_173_dialog_content = "내가 돌아가서 바로──",
  ui_story_1011_10110101_174_dialog_content = "아니, 안 되지.",
  ui_story_1011_10110101_175_dialog_content = "병사들이 원해서 나와 함께 싸우더라도, 돌아오고 나면 나 때문에 징계를 받겠지.",
  ui_story_1011_10110101_176_dialog_content = "빌어먹을... 됐어. 까라면 까야지. 방어나 하자고.",
  ui_story_1011_10110101_177_dialog_content = "감히 암귀가 한 마리라도 제2군단의 진지에 접근한다면,\n놈들에게 공포가 뭔지 알려주겠어.",
  ui_story_1011_10110201_1_dialog_content = "PlayerName, 스카이워커의 진행 방향이 조금 이상하지 않아?",
  ui_story_1011_10110201_15X1_dialog_content = "이쪽 방향은 전에 정박했던 그 공터가 아닌 것 같은데?",
  ui_story_1011_10110201_15X2_dialog_content = "응. 네 말이 맞았어.",
  ui_story_1011_10110201_15X3_dialog_content = "자동 조종 기능을 확인해 봤는데, 목적지가 헤븐즈 밸리의 다른 쪽에 있는 하얀 탑이었어.",
  ui_story_1011_10110201_15X4_dialog_content = "하얀 탑?",
  ui_story_1011_10110201_15X5_dialog_content = "거기가 「콜로서스 정비 기지」가 있는 곳이야?",
  ui_story_1011_10110201_15X6_dialog_content = "자동 조종이 이렇게 설정된 게 맞다면, 그럴 가능성이 높아.",
  ui_story_1011_10110201_15X7_dialog_content = "그 하얀 탑에 대해 너흰 혹시 아는 게 있어?",
  ui_story_1011_10110201_15X8_dialog_content = "음... 잘 모르겠어. 일루미나가 가지고 있는 헤븐즈 밸리에 대한 기록은 무척 제한적이거든.",
  ui_story_1011_10110201_15X9_dialog_content = "그 하얀 탑에 대해 내가 아는 건 그냥 평범한 흰색 석조 건물이라는 것 정도야.",
  ui_story_1011_10110201_15X10_dialog_content = "내가 아는 것도 바이스랑 크게 다를 게 없어.",
  ui_story_1011_10110201_15X11_dialog_content = "스카이워커에 있는 헤븐즈 밸리에 대한 정보는 대부분 간단한 소개 수준이라서...",
  ui_story_1011_10110201_15X12_dialog_content = "뭔가 더 떠오르는 건 없어?",
  ui_story_1011_10110201_15X13_dialog_content = "아이테르가 알고 있는 게 그래도 일루미나보다는 많지 않을까?",
  ui_story_1011_10110201_15X14_dialog_content = "노력해 볼게...",
  ui_story_1011_10110201_16_dialog_content = "음, 저 탑... 조금 기억이 날 것 같긴 해.",
  ui_story_1011_10110201_17_dialog_content = "스카이워커에 저장된 데이터에 기록이 있었던 것 같은데...",
  ui_story_1011_10110201_18_dialog_content = "아! 기억났어!",
  ui_story_1011_10110201_19_dialog_content = "전에 일부 아이테르들이 저기 살았어. 그러다 나중에 지금의 주거 구역으로 이주했다고 해.",
  ui_story_1011_10110201_20_dialog_content = "저기서 제일 눈에 띄는 게 바로 오래전에 버려진 저 하얀 탑이야.",
  ui_story_1011_10110201_21_dialog_content = "저긴 하얀 탑 말고는 아무것도 없었어.",
  ui_story_1011_10110201_22_dialog_content = "다른 건 없다고? 그럼 뭔가 이상한데...",
  ui_story_1011_10110201_22X1_dialog_content = "「콜로서스 정비 기지」라는 이름만 봐도 분명히 거대한 유적이 있어야 맞는 거잖아.",
  ui_story_1011_10110201_22X2_dialog_content = "설마... 과거의 아이테르가 일부러 숨긴 건 아니겠지?",
  ui_story_1011_10110201_22X3_dialog_content = "으으윽──!",
  ui_story_1011_10110201_23_dialog_content = "...뭐지?!",
  ui_story_1011_10110201_24_dialog_content = "무슨 일인데?",
  ui_story_1011_10110201_25_dialog_content = "<color=#e8d9bb>「경고, 암귀의 침입이 감지되었습니다.」</color>",
  ui_story_1011_10110201_26_dialog_content = "암귀?!",
  ui_story_1011_10110201_27_dialog_content = "말도 안 돼... 평범한 암귀가 스카이워커호를 따라잡을 수 있을 리가 없잖아.",
  ui_story_1011_10110201_28_dialog_content = "이 정도 규모의 공격이라면... 매복해서 우릴 기다렸던 거야!",
  ui_story_1011_10110201_29_dialog_content = "크아아!",
  ui_story_1011_10110201_30_dialog_content = "벌써 함교까지 왔어!",
  ui_story_1011_10110201_31_dialog_content = "막아야 해!",
  ui_story_1011_10110201_32_dialog_content = "암귀가 접근하지 못하게 막자!",
  ui_story_1011_10110201_33_dialog_content = "조심해, 매복 전술을 사용할 암귀는 흔하지 않으니까.",
  ui_story_1011_10110201_34_dialog_content = "어쩌면 지휘하는 녀석이 있을지도 몰라!",
  ui_story_1011_10110201_35_dialog_content = "왼쪽은 내가 맡을게. 바이스, 나머지를 부탁해.",
  ui_story_1011_10110201_36_dialog_content = "PlayerName, 지원해줘!",
  ui_story_1011_10110201_37_dialog_content = "응!",
  ui_story_1011_10110202_1_dialog_content = "크아아!",
  ui_story_1011_10110202_2_dialog_content = "어딜 가려고!",
  ui_story_1011_10110202_3_dialog_content = "크오오!",
  ui_story_1011_10110202_4_dialog_content = "대체 얼마나 더 있는 거지...",
  ui_story_1011_10110202_5_dialog_content = "끝이 안 나잖아!",
  ui_story_1011_10110202_6_dialog_content = "더는 물러나면 안 돼!",
  ui_story_1011_10110202_7_dialog_content = "뒤쪽은 컨트롤러야!",
  ui_story_1011_10110202_8_dialog_content = "그어어어!",
  ui_story_1011_10110202_9_dialog_content = "바이스, 조심해!",
  ui_story_1011_10110202_10_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_1011_10110202_11_dialog_content = "으악! 녀석의 공격이 컨트롤러에 맞았어!",
  ui_story_1011_10110202_12_dialog_content = "뭐?!",
  ui_story_1011_10110202_13_dialog_content = "추락한다아아!",
  ui_story_1011_10110202_14_dialog_content = "으악! 살려줘!",
  ui_story_1011_10110202_15_dialog_content = "뭐라도 꽉 붙잡아!",
  ui_story_1011_10110202_16_dialog_content = "PlayerName, 내 손을 잡아!",
  ui_story_1011_10110202_17_dialog_content = "『콜로서스가... 추락했다니...』",
  ui_story_1011_10110202_18_dialog_content = "『이런 머저리들이!』",
  ui_story_1011_10110202_19_dialog_content = "『죄, 죄송합니다!』",
  ui_story_1011_10110202_20_dialog_content = "『내 명령은 콜로서스와 아이테르를 잡아 오라는 것이었다.』",
  ui_story_1011_10110202_21_dialog_content = "『언제 죽이라고 했냔 말이다!』",
  ui_story_1011_10110202_22_dialog_content = "『해결할 방법을 찾겠습니다!』",
  ui_story_1011_10110202_23_dialog_content = "『놈들을 쫓아가서 찾아내라. 절대 도망치게 두지 마라.』",
  ui_story_1011_10110202_24_dialog_content = "『이건 마지막 기회다.』",
  ui_story_1011_10110202_25_dialog_content = "『예!』",
  ui_story_1011_10110202_26_dialog_content = "『네 지능은 역시 지휘에 적합하지 않다니까.』",
  ui_story_1011_10110202_27_dialog_content = "『노라, 안 해도 될 말은 삼가는 게 좋을 거다.』",
  ui_story_1011_10110202_28_dialog_content = "『내가 말했지, 이건 내 실험이라고. 방해하지 마.』",
  ui_story_1011_10110202_29_dialog_content = "『지금 너와 네 멍청한 부하들은 내 실험의 방해 요소가 되고 있어.』",
  ui_story_1011_10110202_30_dialog_content = "『너흰 그냥 밖에서 기다려.』",
  ui_story_1011_10110202_31_dialog_content = "『마침 일루미나 녀석들이 앞길을 막고 있으니까, 너흰 그쪽이나 처리해.』",
  ui_story_1011_10110202_32_dialog_content = "『되도록 날 번거롭게 만들지 말라고.』",
  ui_story_1011_10110202_33_dialog_content = "『노라...』",
  ui_story_1011_10110202_34_dialog_content = "『언젠가 반드시 네 오만의 대가를 치르게 될 거다.』",
  ui_story_1011_10110202_40X1_dialog_content = "잘 들어라. 라인하르트가 우리 제2군단의 방어를 원하는 이상──",
  ui_story_1011_10110202_40X2_dialog_content = "우린 무엇이 난공불락인지 행동으로 몸소 보여주는 거다!",
  ui_story_1011_10110202_40X3_dialog_content = "넌 가서 모든 방어 시설을 조사해라. 파손된 부분을 수리하고, 주요 구조물을 보강하는 거다.",
  ui_story_1011_10110202_40X4_dialog_content = "설령 암귀 놈들이 저 산과 들판을 모조리 메우더라도 버텨낼 수 있게 말이다!",
  ui_story_1011_10110202_40X5_dialog_content = "예!",
  ui_story_1011_10110202_40X6_dialog_content = "그리고 넌 부대를 인솔해서 현재 근무 중인 병력들과 교대시켜라.",
  ui_story_1011_10110202_40X7_dialog_content = "모든 초소가 6시간마다 교대하도록 해서, 충분한 휴식을 취하게 해라.",
  ui_story_1011_10110202_40X8_dialog_content = "그리고 눈을 크게 뜨고 저 암귀 놈들의 움직임을 제대로 주시해라!",
  ui_story_1011_10110202_40X9_dialog_content = "예!",
  ui_story_1011_10110202_40X10_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_1011_10110202_40X11_dialog_content = "...뭐지?!",
  ui_story_1011_10110202_40X12_dialog_content = "저건... 애송이 녀석의 스카이워커호잖아?",
  ui_story_1011_10110202_40X13_dialog_content = "어째서 저렇게 낮게 날고 있지?",
  ui_story_1011_10110202_40X14_dialog_content = "콜로서스 위에 붙어 있는 검은 점들은... 설마 암귀인가?!",
  ui_story_1011_10110202_40X15_dialog_content = "대체 뭐가 어떻게 된 거야? 녀석이 습격을 받은 건가?",
  ui_story_1011_10110202_40X16_dialog_content = "보고드립니다!",
  ui_story_1011_10110202_40X17_dialog_content = "말해!",
  ui_story_1011_10110202_40X18_dialog_content = "정찰병들이 암귀의 특이 동향을 관측했습니다.\n놈들은 지금 헤븐즈 밸리 방향으로 집결하고 있습니다!",
  ui_story_1011_10110202_40X19_dialog_content = "일반 암귀 외에도 다수의 고위 암귀의 흔적도 발견했습니다!",
  ui_story_1011_10110202_40X20_dialog_content = "그중에는 노라와 또 다른 신원 미상의 고위 암귀가 포함되어 있습니다!",
  ui_story_1011_10110202_40X21_dialog_content = "노라...",
  ui_story_1011_10110202_40X22_dialog_content = "이런 때에 그쪽에서 대체 뭘 하려는 거지?",
  ui_story_1011_10110202_40X23_dialog_content = "아니지.",
  ui_story_1011_10110202_40X24_dialog_content = "아이테르 녀석, 암귀, 그리고 노라...",
  ui_story_1011_10110202_40X25_dialog_content = "모두가 동시에 헤븐즈 밸리로 향했다면, 분명히 큰일이 벌어질 거다.",
  ui_story_1011_10110202_40X26_dialog_content = "명령을 하달한다. 제2군은 경계 태세에 들어간다.",
  ui_story_1011_10110202_40X27_dialog_content = "정찰 부대를 편성해 헤븐즈 밸리 방향을 중점적으로 감시해라.",
  ui_story_1011_10110202_40X28_dialog_content = "예!",
  ui_story_1011_10110202_40X29_dialog_content = "그리고...",
  ui_story_1011_10110202_40X30_dialog_content = "<color=#e8d9bb>타탕──!</color>",
  ui_story_1011_10110202_40X31_dialog_content = "저쪽은... 헤븐즈 밸리 방향이잖아?",
  ui_story_1011_10110202_40X32_dialog_content = "우리 병력이 암귀와 교전 중인가?",
  ui_story_1011_10110202_40X33_dialog_content = "그, 그렇습니다!",
  ui_story_1011_10110202_40X34_dialog_content = "방금 들어온 소식입니다. 아군이 노라가 이끄는 암귀 무리와 조우했습니다!",
  ui_story_1011_10110202_40X35_dialog_content = "현재 암귀와 교전 중이며, 노라는 암귀를 놔두고 혼자 헤븐즈 밸리로 향한 것 같습니다!",
  ui_story_1011_10110202_40X36_dialog_content = "저놈들이 뭘 꾸미고 있든, 절대 좋은 일은 아니겠지.",
  ui_story_1011_10110202_40X37_dialog_content = "그러게 내가 말했잖아. 조만간 무슨 일이 일어날지 모른다고.",
  ui_story_1011_10110202_40X38_dialog_content = "절대 놈들 뜻대로 되게 놔둘 순 없지!",
  ui_story_1011_10110202_40X39_dialog_content = "각 부대에 전파해라. 진지를 방어하고, 한 발짝도 물러서지 마라!",
  ui_story_1011_10110202_40X40_dialog_content = "일루미나의 반역자 노라는 내가 직접 잡아 오겠다.",
  ui_story_1011_10110202_40X41_dialog_content = "하지만 군단장님! 상부의 명령이...",
  ui_story_1011_10110202_40X42_dialog_content = "잘 들어라. 승리의 기회는 한 번 놓치면 다시는 돌아오지 않는다.",
  ui_story_1011_10110202_40X43_dialog_content = "노라는 지금 분명히 뭔가를 꾸미고 있다. 그리고 그걸 막을 타이밍은 지금뿐이라고.",
  ui_story_1011_10110202_40X44_dialog_content = "그 빌어먹을 계획이 성공할 때까지 기다려 주면 모든 게 늦어버리고 말 거다.",
  ui_story_1011_10110202_40X45_dialog_content = "만약 내 행동이 손실을 초래해서, 라인하르트와 상부에서 책임을 추궁한다면\n저들에게 이렇게 전해라.",
  ui_story_1011_10110202_40X46_dialog_content = "모든 책임은 전부 나 제2군단장 바튼에게 있다고 말이다!",
  ui_story_1011_10110202_40X47_dialog_content = "알겠나?",
  ui_story_1011_10110202_40X48_dialog_content = "아, 알겠습니다!",
  ui_story_1011_10110202_40X49_dialog_content = "PlayerName 녀석... 괜찮을지 모르겠군.",
  ui_story_1011_10110202_40X50_dialog_content = "그래도 녀석은 운이 좋으니까, 분명히 별일 없겠지.",
  ui_story_1011_10110202_40X51_dialog_content = "그럼 기왕 나가는 김에 녀석을 좀 도와줘야겠어.",
  ui_story_1011_10110401_1_dialog_content = "<anim type=Shake><size=50>으아아악──!</size></anim>",
  ui_story_1011_10110401_2_dialog_content = "추──락──한──다──아──아!",
  ui_story_1011_10110401_3_dialog_content = "PlayerName! 방향을 제어해!",
  ui_story_1011_10110401_4_dialog_content = "탑 아래쪽에 공간이 있어! 스카이워커호를 그쪽으로 들어가게 조종해!",
  ui_story_1011_10110401_7X1_dialog_content = "못 하겠어──!",
  ui_story_1011_10110401_7X2_dialog_content = "컨트롤러가 고장 났어! 스카이워커를 제어할 수가 없어!",
  ui_story_1011_10110401_7X3_dialog_content = "그럼 뭐라도 꽉 잡고 있어!",
  ui_story_1011_10110401_7X4_dialog_content = "그리고...",
  ui_story_1011_10110401_7X5_dialog_content = "우리가 저 탑에 곧바로 부딪히지 않길 기도해!",
  ui_story_1011_10110401_7X6_dialog_content = "흐이익!",
  ui_story_1011_10110401_8_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_1011_10110401_9_dialog_content = "<color=#e8d9bb>쿠다다당──!</color>",
  ui_story_1011_10110401_10_dialog_content = "콜록콜록! 온통 흙투성이네...",
  ui_story_1011_10110401_11_dialog_content = "우리... 아직 살아있나?",
  ui_story_1011_10110401_12_dialog_content = "음... 의심할 여지 없이 살아있어.",
  ui_story_1011_10110401_13_dialog_content = "착륙에 성공했네.",
  ui_story_1011_10110401_14_dialog_content = "다들 괜찮아? 다친 데 없어?",
  ui_story_1011_10110401_15_dialog_content = "난 괜찮아. 머리가 조금 어지러운 건 빼고.",
  ui_story_1011_10110401_16_dialog_content = "나...나도 괜찮아.",
  ui_story_1011_10110401_17_dialog_content = "크흠, 여긴... 탑의 지하인가?",
  ui_story_1011_10110401_18_dialog_content = "맞아. 우린 하얀 탑 바로 아래 공간으로 들어왔어.",
  ui_story_1011_10110401_19_dialog_content = "<color=#e8d9bb>「목적지, 콜로서스 정비 기지 계류장에 도착했습니다.」</color>",
  ui_story_1011_10110401_20_dialog_content = "<color=#e8d9bb>「기지 제어 시스템 연결을 시작합니다.」</color>",
  ui_story_1011_10110401_21_option_content = "계류장?",
  ui_story_1011_10110401_22_dialog_content = "여기가... 계류장이라고?",
  ui_story_1011_10110401_23_dialog_content = "어쩐지 엄청 넓다 했어. 콜로서스 몇 대를 더 주차해도 될 정도잖아.",
  ui_story_1011_10110401_24_dialog_content = "아무튼 계류장에 들어왔으니까, 추락은 아닌 셈이네...",
  ui_story_1011_10110401_25_dialog_content = "그어억...",
  ui_story_1011_10110401_26_dialog_content = "......",
  ui_story_1011_10110401_27_dialog_content = "......",
  ui_story_1011_10110401_28_dialog_content = "암귀다!",
  ui_story_1011_10110401_29_dialog_content = "끄어어!",
  ui_story_1011_10110401_30_dialog_content = "얼른 잡아!",
  ui_story_1011_10110401_31_dialog_content = "아직 암귀가 더 많이 있을 거야.",
  ui_story_1011_10110401_32_dialog_content = "녀석들이 계속 여길 파괴하게 둬선 안 돼!",
  ui_story_1011_10110402_1_dialog_content = "휴... 이게 마지막이겠지?",
  ui_story_1011_10110402_2_dialog_content = "다른 암귀는 안 보이는 것 같아.",
  ui_story_1011_10110402_3_dialog_content = "응, 지금은 느껴지는 적이 없어. 잠깐 쉬어도 될 것 같아.",
  ui_story_1011_10110402_4_dialog_content = "난 스카이워커의 상태를 좀 확인해 볼게.",
  ui_story_1011_10110402_5_dialog_content = "<color=#e8d9bb>「콜로서스 정비 기지의 제어 시스템 연결 시도 중.」</color>",
  ui_story_1011_10110402_6_dialog_content = "<color=#e8d9bb>「오류 발생, 계류장과 중앙 제어 시스템의 연결이 끊어졌습니다.」</color>",
  ui_story_1011_10110402_7_dialog_content = "<color=#e8d9bb>「중앙 제어 시스템으로 이동해 수동으로 연결을 복구하십시오.」</color>",
  ui_story_1011_10110402_8_dialog_content = "중앙 제어 시스템...?",
  ui_story_1011_10110402_9_dialog_content = "하얀 탑에 그런 게 있다고?",
  ui_story_1011_10110402_10_dialog_content = "이 탑에 대한 정보에 그런 내용은 없었어?",
  ui_story_1011_10110402_11_dialog_content = "없었던 것 같은데...",
  ui_story_1011_10110402_12_dialog_content = "영상 자료를 다시 찾아보는 방법도 있지만, 대신 시간이 좀 오래 걸릴 거야.",
  ui_story_1011_10110402_13_dialog_content = "자료만 보는 것보다는 현장 조사가 필요해.",
  ui_story_1011_10110402_14_dialog_content = "그것도 그렇네. 그럼 내려가서 살펴보자.",
  ui_story_1011_10110402_15_dialog_content = "응, 얼른 가자!",
  ui_story_1011_10110402_16_dialog_content = "엄청 넓잖아...",
  ui_story_1011_10110402_17_dialog_content = "말을 할 때마다 메아리치는 게 들려.",
  ui_story_1011_10110402_18_dialog_content = "자료에선 여기가 한때 아이테르가 살았던 곳이라고 했어.",
  ui_story_1011_10110402_19_dialog_content = "근데 지금은 집은커녕 사람이 살았던 흔적도 없잖아.",
  ui_story_1011_10110402_20_dialog_content = "아무래도 시간이 많이 지났으니까...",
  ui_story_1011_10110402_21_dialog_content = "흔적이 있었더라도 아마 시간이 지나면서 서서히 사라져 버렸을 거야.",
  ui_story_1011_10110402_22_dialog_content = "근데 아이테르가 한때 살았던 곳이 콜로서스의 계류장이었다니...",
  ui_story_1011_10110402_23_dialog_content = "설마 여기에 콜로서스를 정박하고 콜로서스랑 같이 살았던 걸까?",
  ui_story_1011_10110402_24_dialog_content = "꼭 캠핑하는 것 같네!",
  ui_story_1011_10110402_25_dialog_content = "어쩌면 과거의 아이테르들이 콜로서스를 거처로 사용해서였을지도 몰라.",
  ui_story_1011_10110402_26_dialog_content = "그리고 그들이 여길 떠나면서 콜로서스도 타고 갔을 테니까.",
  ui_story_1011_10110402_27_dialog_content = "만약 그 사람들이 여기 콜로서스를 정박했다면,\n여기가 계류장이라는 것도 당연히 알았을 거야.",
  ui_story_1011_10110402_28_dialog_content = "그리고 근처에 <color=#FFB400>「콜로서스 정비 기지」</color>가 있는 것도 알았을 테고.",
  ui_story_1011_10110402_29_dialog_content = "근데 왜 기록이 하나도 없는 거지?",
  ui_story_1011_10110402_30_dialog_content = "확실히 이상한 곳이야. 조사할 때 주의하는 게 좋겠어.",
  ui_story_1011_10110402_31_dialog_content = "응.",
  ui_story_1011_10110402_32_dialog_content = "갑자기 나타난 것처럼 아무런 기록도, 흔적도 없는 기지라니...",
  ui_story_1011_10110402_33_dialog_content = "거기다 근처엔 콜로서스를 수리했을 것 같은 장비나 방도 없어.",
  ui_story_1011_10110402_34_dialog_content = "있는 거라곤 두껍게 쌓인 먼지뿐이야.",
  ui_story_1011_10110402_35_dialog_content = "중앙 제어 시스템도 여기 있는 것 같진 않아.",
  ui_story_1011_10110402_36_dialog_content = "설마... 위쪽인가?",
  ui_story_1011_10110402_37_dialog_content = "PlayerName, 이 탑 위엔 뭐가 있어?",
  ui_story_1011_10110402_38_dialog_content = "음, 그러니까...",
  ui_story_1011_10110402_39_dialog_content = "스카이워커에 있던 자료 내용에 따르면, 이 하얀 탑에도 전에는 아이테르가 살았다고 해.",
  ui_story_1011_10110402_40_dialog_content = "그러다 나중에 지금의 주거 구역으로 옮겨간 거야.",
  ui_story_1011_10110402_41_dialog_content = "과거의 아이테르들도 이 탑을 상부까지 세세하게 조사했다고 했어.",
  ui_story_1011_10110402_42_dialog_content = "근데 바깥이랑 똑같은 무늬가 있는 흰 돌 외에는 아무것도 없었어.",
  ui_story_1011_10110402_43_dialog_content = "위에도 아무것도 없다는 건가...",
  ui_story_1011_10110402_44_dialog_content = "좌표가 틀린 건 아닐까?",
  ui_story_1011_10110402_45_dialog_content = "그렇진 않을 거야. 지질학적인 변화 때문에 건물의 위치가 변했더라도,\n정상적인 경우라면 원래 좌표와의 거리가 그렇게 멀어질 순 없어.",
  ui_story_1011_10110402_46_dialog_content = "탑 위쪽이 비어 있는 거라면...",
  ui_story_1011_10110402_47_dialog_content = "...그럼 아래는?",
  ui_story_1011_10110402_48_dialog_content = "아래?",
  ui_story_1011_10110402_49_dialog_content = "그러니까... 자난성처럼 여기도 숨겨진 지하 공간이 있을 것 같다는 애기야?",
  ui_story_1011_10110402_50_dialog_content = "그럴 수도 있어!",
  ui_story_1011_10110402_51_dialog_content = "근데 곳곳엔 탑이 무너져서 생긴 돌덩이들뿐이고, 우린 지도도 없어.\n입구를 어떻게 찾지?",
  ui_story_1011_10110402_52_dialog_content = "설마 여길 전부 파 봐야 하나?",
  ui_story_1011_10110402_53_dialog_content = "이런 곳을 파헤치려면 몇 년은 걸릴 거야.",
  ui_story_1011_10110402_54_dialog_content = "통로나... 지하성을... 찾는 방법이라...",
  ui_story_1011_10110402_55_dialog_content = "아!",
  ui_story_1011_10110402_56_dialog_content = "대원수님께서 주신 보급품 중에 금속 탐지기가 있었어!",
  ui_story_1011_10110402_57_dialog_content = "이런 곳에 지하 기지가 있다면, 금속 자재를 사용했을 가능성이 높아.",
  ui_story_1011_10110402_58_dialog_content = "일단 금속 탐지기로 의심스러운 곳을 찾고 땅을 파 보자.",
  ui_story_1011_10110402_59_dialog_content = "이런 상황까지 고려했다는 건가.",
  ui_story_1011_10110402_60_dialog_content = "그 대원수란 사람, 역시 소문대로 정말 주도면밀한 사람이네.",
  ui_story_1011_10110402_60X1_dialog_content = "다른 보급품도 폭약이랑 같이 챙기자.",
  ui_story_1011_10110402_60X2_dialog_content = "정말로 지하 유적을 조사해야 한다면 분명히 유용하게 쓰일 거야.",
  ui_story_1011_10110402_61_dialog_content = "그럼 지금은 그 방법밖에 없겠어.",
  ui_story_1011_10110402_62_dialog_content = "운이 좋아서 입구를 한 번에 찾았으면 좋겠네.",
  ui_story_1011_10110402_63_dialog_content = "<color=#e8d9bb>하얀 탑 밖, 어딘가</color>",
  ui_story_1011_10110402_64_dialog_content = "저 하얀 탑, 역시 보이는 것처럼 단순한 게 아니었어.",
  ui_story_1011_10110402_65_dialog_content = "아이테르가 가진 열쇠의 안내가 없었다면, 저 안의 비밀은 결코 발견되지 않았겠지.",
  ui_story_1011_10110402_66_dialog_content = "이제 저 비밀을 실험 데이터로 삼을 때가 됐어.",
  ui_story_1011_10110402_66X1_dialog_content = "도망칠 수 있을 것 같냐!",
  ui_story_1011_10110402_66X2_dialog_content = "크오오──",
  ui_story_1011_10110402_66X3_dialog_content = "군단장님, 근처의 암귀는 전부 처리했습니다!",
  ui_story_1011_10110402_66X4_dialog_content = "좋아, 진지를 다시 구축한다.",
  ui_story_1011_10110402_66X5_dialog_content = "예!",
  ui_story_1011_10110402_66X6_dialog_content = "이 암귀들은 전부 잡졸들뿐이잖아.",
  ui_story_1011_10110402_66X7_dialog_content = "노라는 어디로 간 거야?",
  ui_story_1011_10110402_66X8_dialog_content = "설마... 벌써 헤븐즈 밸리에 들어간 건 아니겠지?",
  ui_story_1011_10110402_66X9_dialog_content = "이렇게 많은 암귀에 노라까지, 전부 PlayerName 녀석을 노리는 건가...",
  ui_story_1011_10110402_66X10_dialog_content = "아무래도 큰 싸움이 되겠어.",
  ui_story_1011_10110402_66X11_dialog_content = "노라 저 배신자가 무슨 수작을 준비했는지 벌써부터 기대되잖아.",
  ui_story_1011_10110501_1_dialog_content = "쓸모없는 빈 상자...",
  ui_story_1011_10110501_2_dialog_content = "버려.",
  ui_story_1011_10110501_3_dialog_content = "내용이 하나도 안 보이는 책...",
  ui_story_1011_10110501_4_dialog_content = "버려.",
  ui_story_1011_10110501_5_dialog_content = "뭐가 들었는지 모를 통조림...",
  ui_story_1011_10110501_6_dialog_content = "버려.",
  ui_story_1011_10110501_7_dialog_content = "잠깐만! 막 버리면 안 돼!",
  ui_story_1011_10110501_8_dialog_content = "음... 그 캔은 이미 유통기한이 의미가 없을 정도로 오래됐을 거잖아.",
  ui_story_1011_10110501_9_dialog_content = "그냥 버려.",
  ui_story_1011_10110501_10_dialog_content = "휴...",
  ui_story_1011_10110501_11_dialog_content = "한참을 고생했는데 겨우 이런 것들밖에 못 찾다니...",
  ui_story_1011_10110501_12_dialog_content = "좀 더 자세히 살펴보자. 놓치는 게 있으면 안 돼.",
  ui_story_1011_10110501_13_dialog_content = "알겠어. 다시 찾아볼게.",
  ui_story_1011_10110501_14_dialog_content = "이쪽 구역은 아직 조사를 안 한 것 같아.",
  ui_story_1011_10110501_15_dialog_content = "하얀 돌멩이들이 여기저기 떨어져 있어. 하얀 탑에서 떨어진 것 같은데?",
  ui_story_1011_10110501_16_dialog_content = "안에 뭔가 있을진 모르겠지만 말이야...",
  ui_story_1011_10110501_17_dialog_content = "금속 탐지기로 스캔해 볼게.",
  ui_story_1011_10110501_18_dialog_content = "<color=#e8d9bb>삐─삐─삐─!</color>",
  ui_story_1011_10110501_19_dialog_content = "반응이 있는데?!",
  ui_story_1011_10110501_20_dialog_content = "돌 안에?",
  ui_story_1011_10110501_21_option_content = "[돌을 두드려 본다]",
  ui_story_1011_10110501_22_dialog_content = "<color=#e8d9bb>똑─똑─똑─!</color>",
  ui_story_1011_10110501_23_dialog_content = "속이 빈 것 같진 않은데... 설마 뒤쪽인가?",
  ui_story_1011_10110501_24_dialog_content = "너무 어두워. 온통 그늘이잖아...",
  ui_story_1011_10110501_25_dialog_content = "그늘 안에 뭔가 있는 것 같은데... 잘 안 보여.",
  ui_story_1011_10110501_26_dialog_content = "어디 보자...",
  ui_story_1011_10110501_27_dialog_content = "...아, 암귀?! 깡통을 쓰고 쓰레기인 척한 거야?!",
  ui_story_1011_10110501_28_dialog_content = "크어어어──!",
  ui_story_1011_10110501_29_dialog_content = "흐이익!",
  ui_story_1011_10110501_30_dialog_content = "PlayerName!",
  ui_story_1011_10110501_31_dialog_content = "그어억...",
  ui_story_1011_10110501_32_dialog_content = "위, 위험했어!",
  ui_story_1011_10110501_33_dialog_content = "대체 언제 나타난 거야?!",
  ui_story_1011_10110501_34_dialog_content = "여긴 넓은 데다가 전부 그늘이 져 있어.",
  ui_story_1011_10110501_35_dialog_content = "우리가 입구를 찾는 동안 몰래 다가왔을 거야.",
  ui_story_1011_10110501_36_dialog_content = "크오오──!",
  ui_story_1011_10110501_37_dialog_content = "이런! 포위됐어!",
  ui_story_1011_10110501_38_dialog_content = "입구에서 암귀들이 더 몰려오고 있어!",
  ui_story_1011_10110501_39_dialog_content = "얼른 탈출해야 돼!",
  ui_story_1011_10110501_40_dialog_content = "안 돼!",
  ui_story_1011_10110501_41_dialog_content = "지금 여길 벗어나면 탑이랑 스카이워커를 고스란히 암귀한테 주는 거잖아!",
  ui_story_1011_10110501_42_dialog_content = "여길 지키려면 암귀가 들어오는 걸 막아야 해!",
  ui_story_1011_10110501_43_dialog_content = "근데 여긴 닫을 수 있는 문도 없잖아!",
  ui_story_1011_10110501_44_dialog_content = "문이 없다면...",
  ui_story_1011_10110501_45_dialog_content = "만들어서 닫으면 되지!",
  ui_story_1011_10110501_46_dialog_content = "폭약을 쓰는 거야!",
  ui_story_1011_10110501_47_dialog_content = "입구를 폭파할 생각이야?!",
  ui_story_1011_10110501_48_dialog_content = "맞아!",
  ui_story_1011_10110501_49_dialog_content = "입구가 무너져도 상관없어. 우린 하얀 탑 위쪽으로 나갈 수 있잖아.",
  ui_story_1011_10110501_49X1_dialog_content = "정 안 되면 지하 유적에서 다른 출구를 찾아도 되니까!",
  ui_story_1011_10110501_50_dialog_content = "암귀가 여기까지 쳐들어온 이상, 반드시 막아야 해.\n녀석들을 막고 스카이워커랑 지하 유적을 지키는 거야!",
  ui_story_1011_10110501_51_dialog_content = "알겠어. 그럼 바이스랑 내가 엄호할게.\nPlayerName 넌 기회를 봐서 입구에서 폭약을 터트려!",
  ui_story_1011_10110501_52_dialog_content = "응!",
  ui_story_1011_10110501_53_dialog_content = "그럼 부탁할게!",
  ui_story_1011_10110502_1_dialog_content = "캬아악──!",
  ui_story_1011_10110502_2_dialog_content = "저리 비켜!",
  ui_story_1011_10110502_3_dialog_content = "크오오──!",
  ui_story_1011_10110502_4_dialog_content = "암귀들이 점점 더 늘어나고 있어... 이대로는 입구 쪽으로 가는 것도 힘들어...",
  ui_story_1011_10110502_5_dialog_content = "폭파는 꿈도 못 꿀 지경이야!",
  ui_story_1011_10110502_6_dialog_content = "계획대로 되지 않더라도 일단은 돌파하는 수밖에 없어.",
  ui_story_1011_10110502_7_dialog_content = "여기 갇혀서 죽을 순 없으니까!",
  ui_story_1011_10110502_9_dialog_content = "이거나 받아라!",
  ui_story_1011_10110502_10_dialog_content = "입구 쪽을 봐! 저기 누가 있어!",
  ui_story_1011_10110502_11_dialog_content = "바튼 씨?!",
  ui_story_1011_10110502_12_dialog_content = "바튼 씨가 왜 여기 있죠?!",
  ui_story_1011_10110502_12X1_dialog_content = "하, 역시 괜찮을 줄 알았다니까.",
  ui_story_1011_10110502_12X2_dialog_content = "암귀들이 이쪽으로 몰려오는 걸 보고 뭔가 이상한 것 같아서 와 봤다.",
  ui_story_1011_10110502_13_dialog_content = "마침 볼일도 있던 참이니까, 여기 암귀들부터 좀 패 줘야겠어!",
  ui_story_1011_10110502_14_dialog_content = "애송이, 넌 네 할 일이나 계속해. 이쪽은 내가 맡을 테니까.",
  ui_story_1011_10110502_15_dialog_content = "암귀는 바튼 군단장님이 전부 막아주셨어! PlayerName, 지금이야!",
  ui_story_1011_10110502_16_dialog_content = "바튼 씨! 멀리 떨어지세요! 입구를 막을 거예요!",
  ui_story_1011_10110502_17_dialog_content = "막다니? 어떻게?",
  ui_story_1011_10110502_18_dialog_content = "폭파시킬 거예요!",
  ui_story_1011_10110502_19_dialog_content = "폭파시킨다고?!",
  ui_story_1011_10110502_20_dialog_content = "네 녀석도 이제 그런 터무니없는 짓을 할 줄 알게 된 거냐.",
  ui_story_1011_10110502_21_dialog_content = "좋아, 그럼 폭파시키라고. 여긴 나한테 맡기고!",
  ui_story_1011_10110502_22_dialog_content = "PlayerName, 암귀의 공세가 약해졌어. 지금이야!",
  ui_story_1011_10110502_23_dialog_content = "알겠어!",
  ui_story_1011_10110502_24_dialog_content = "폭약은 잘 설치했어! 바이스, 카렌, 물러나!",
  ui_story_1011_10110502_25_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_1011_10110502_26_dialog_content = "성공했나?",
  ui_story_1011_10110502_27_dialog_content = "된 것 같아!",
  ui_story_1011_10110502_28_dialog_content = "바튼 씨는 아직 밖에 있는 것 같은데?",
  ui_story_1011_10110502_29_dialog_content = "[감응한다]",
  ui_story_1011_10110502_30_dialog_content = "바튼 씨, 괜찮아요?!",
  ui_story_1011_10110502_31_dialog_content = "걱정 마라, 난 괜찮으니까!",
  ui_story_1011_10110502_32_dialog_content = "그쪽은 괜찮나?",
  ui_story_1011_10110502_33_dialog_content = "입구는 막혔으니까 이쪽은 당분간 괜찮을 거예요!",
  ui_story_1011_10110502_34_dialog_content = "좋아. 그럼 나도 신경 끄고 싸울 수 있겠어!",
  ui_story_1011_10110502_35_dialog_content = "몸조심해요!",
  ui_story_1011_10110502_36_dialog_content = "그럼 이제 우리 차례야.",
  ui_story_1011_10110502_37_dialog_content = "얼른 유적을 조사하자!",
  ui_story_1011_10110502_38_dialog_content = "폭발로 입구를 막았지만, 오래 버틸 순 없을 거야.",
  ui_story_1011_10110502_39_dialog_content = "놈들이 돌을 치우거나 탑을 타고 올라가서 위쪽 입구로 들어올지도 몰라.",
  ui_story_1011_10110502_40_dialog_content = "그럼 흩어져서 찾아보자!",
  ui_story_1011_10110502_41_dialog_content = "이 근처는 이미 다 찾아본 것 같아.",
  ui_story_1011_10110502_42_dialog_content = "아무리 찾아봐도 쓰레기뿐이야.",
  ui_story_1011_10110502_43_dialog_content = "다른 방법이 없을까...",
  ui_story_1011_10110502_44_dialog_content = "아니면 아이테르만 아는 방법 같은 게 있을까?",
  ui_story_1011_10110502_45_dialog_content = "...감응 능력 같은 거?",
  ui_story_1011_10110502_46_dialog_content = "그래.",
  ui_story_1011_10110502_47_dialog_content = "감응 능력으로 남은 단서가 있는지 확인해 볼래?",
  ui_story_1011_10110502_48_dialog_content = "해볼게!",
  ui_story_1011_10110502_49_option_content = "[감응한다]",
  ui_story_1011_10110502_50_dialog_content = "으윽!",
  ui_story_1011_10110502_51_dialog_content = "머리가...!",
  ui_story_1011_10110502_52_dialog_content = "PlayerName?!",
  ui_story_1011_10110502_53_dialog_content = "여기... 뭔가 이상해.",
  ui_story_1011_10110502_54_dialog_content = "내가 감응 능력으로 주변을 찾는 걸 뭔가가 방해하고 있는 느낌이야.",
  ui_story_1011_10110502_55_dialog_content = "아이테르의 감응 능력을 방해한다...?",
  ui_story_1011_10110502_56_dialog_content = "뭔가 숨기고 있는 건가?",
  ui_story_1011_10110502_57_dialog_content = "만약 그런 거라면, 이건 지금 우리가 맞게 찾아가고 있다는 뜻이야.",
  ui_story_1011_10110502_58_dialog_content = "근데 감응 능력을 사용할 수 없다면 단서는 여기서 끊어지는 거잖아?",
  ui_story_1011_10110502_59_dialog_content = "...아니, 다른 방법이 있을 거야.",
  ui_story_1011_10110502_60_dialog_content = "전에 싱크탱크 컴포넌트랑 감응하면서 스카이워커를 수리하는\n의식 모듈 복구기를 찾을 수 있었어.",
  ui_story_1011_10110502_61_dialog_content = "그리고 우릴 여기로 이끈 것도 그 복구기의 데이터였어.",
  ui_story_1011_10110502_62_dialog_content = "일단 복구기랑 감응해 봐야겠어. 문제를 해결할 방법이 있을지도 모르니까!",
  ui_story_1011_10110502_62X1_dialog_content = "그리고 방금 바튼 씨와 감응할 때는 아무런 방해도 받지 않았어.",
  ui_story_1011_10110502_62X2_dialog_content = "어쩌면 특정한 감응 대상이 있다면 영향을 안 받는 건지도 몰라.",
  ui_story_1011_10110502_63_dialog_content = "그럴 수도 있겠네.",
  ui_story_1011_10110502_64_dialog_content = "가능할 것 같긴 하지만...",
  ui_story_1011_10110502_65_dialog_content = "PlayerName, 조금이라도 괴로워지면 곧바로 감응을 끊어야 돼!",
  ui_story_1011_10110502_66_dialog_content = "너무 무리하지 말아줘.",
  ui_story_1011_10110502_67_dialog_content = "응, 걱정 마.",
  ui_story_1011_10110502_68_option_content = "(강제 감응!)",
  ui_story_1011_10110502_69_dialog_content = "......",
  ui_story_1011_10110502_70_dialog_content = "중앙 제어실로 가는 길을 알려줘!",
  ui_story_1011_10110502_71_dialog_content = "<color=#e8d9bb>「명령을 접수했습니다. 확인 중...」</color>",
  ui_story_1011_10110502_72_dialog_content = "<color=#e8d9bb>「접근 통제 시스템이 오프라인 상태입니다.」</color>",
  ui_story_1011_10110502_73_dialog_content = "<color=#e8d9bb>「파이어플라이를 파견해 수리를 진행하는 중입니다.」</color>",
  ui_story_1011_10110502_74_dialog_content = "스카이워커호에서... 파이어플라이 한 마리가 날아왔는데?",
  ui_story_1011_10110502_75_dialog_content = "「삑──!」",
  ui_story_1011_10110502_76_dialog_content = "<color=#e8d9bb>딸깍.</color>",
  ui_story_1011_10110502_77_dialog_content = "「접근 통제 시스템의 예비 전원이 연결되었습니다. 접근 통제 시스템을 실행하는 중입니다.」",
  ui_story_1011_10110502_78_dialog_content = "「비밀번호를 입력해 신분 인증을 진행하십시오.」",
  ui_story_1011_10110502_79_dialog_content = "뭐야?",
  ui_story_1011_10110502_80_dialog_content = "어디에서 나는 소리지?!",
  ui_story_1011_10110502_81_dialog_content = "「본 시스템은 콜로서스 정비 기지의 접근 통제 시스템입니다.」",
  ui_story_1011_10110502_82_dialog_content = "「경고, 접근 통제 시스템이 중앙 제어 시스템에서 ■■■■■■■일간 연결이 끊어졌습니다.」",
  ui_story_1011_10110502_83_dialog_content = "「연결을 복구하거나 비밀번호를 재설정해 주십시오.」",
  ui_story_1011_10110502_84_dialog_content = "문을 여는 데 쓰는 것 같은데?",
  ui_story_1011_10110502_85_dialog_content = "게다가 음성 제어 시스템이야!",
  ui_story_1011_10110502_86_dialog_content = "「잘못된 비밀번호입니다. 3번 더 시도할 수 있습니다.」",
  ui_story_1011_10110502_87_dialog_content = "뭐? 아냐! 방금 그건 아니라고!",
  ui_story_1011_10110502_88_dialog_content = "「잘못된 비밀번호입니다. 2번 더 시도할 수 있습니다.」",
  ui_story_1011_10110502_89_dialog_content = "자, 잠깐만!",
  ui_story_1011_10110502_90_dialog_content = "「잘못된 비밀번호입니다. 1번 더 시도할 수 있습니다.」",
  ui_story_1011_10110502_91_dialog_content = "「오류 횟수를 초과하면 접근 통제 시스템이 잠깁니다.」",
  ui_story_1011_10110502_92_dialog_content = "더 말하면 안 돼!",
  ui_story_1011_10110502_93_dialog_content = "웁! 우웁──!",
  ui_story_1011_10110502_94_dialog_content = "비밀번호를 재설정할 수 있어?!",
  ui_story_1011_10110502_95_dialog_content = "「경고, 미승인된 유전자형이 감지되었습니다. 명령이 유효하지 않습니다.」",
  ui_story_1011_10110502_96_dialog_content = "......",
  ui_story_1011_10110502_97_dialog_content = "(내가 해야 된다는 거지?)",
  ui_story_1011_10110502_98_dialog_content = "이번이 마지막 기회야, PlayerName. 네가 해 봐.",
  ui_story_1011_10110502_99_dialog_content = "절대 잘못 말하지 마.",
  ui_story_1011_10110502_100_dialog_content = "(알았어...)",
  ui_story_1011_10110502_101_dialog_content = "......",
  ui_story_1011_10110502_102_option_content = "접근 통제 시스템, 비밀번호 재설정.",
  ui_story_1011_10110502_103_dialog_content = "「승인된 유전자형이 감지되었습니다. 비밀번호 재설정을 시작합니다.」",
  ui_story_1011_10110502_104_dialog_content = "「세 가지 질문에 답해 신분 인증을 진행하십시오.」",
  ui_story_1011_10110502_105_dialog_content = "질문까지 있다고?",
  ui_story_1011_10110502_106_dialog_content = "어쩔 수 없네. 차근차근 해 봐야지.",
  ui_story_1011_10110502_107_dialog_content = "PlayerName, 긴장하지 마. 내가 도와줄 테니까.",
  ui_story_1011_10110502_108_dialog_content = "몇 년 동안 기말고사에서 우수한 성적을 냈던 날 믿어!",
  ui_story_1011_10110502_109_dialog_content = "「당신은 암귀입니까?」",
  ui_story_1011_10110502_110_dialog_content = "하아...?",
  ui_story_1011_10110502_111_dialog_content = "내가 암귀일 리가 없잖아!",
  ui_story_1011_10110502_112_dialog_content = "「잘못된 답변이 감지되었습니다.」",
  ui_story_1011_10110502_113_dialog_content = "「다시 질문합니다. 당신은 암귀입니까?」",
  ui_story_1011_10110502_114_dialog_content = "어... 아니야!",
  ui_story_1011_10110502_115_dialog_content = "「답변이 입력되었습니다.」",
  ui_story_1011_10110502_116_dialog_content = "「당신은 오로리안입니까?」",
  ui_story_1011_10110502_117_dialog_content = "오로리안도 아냐.",
  ui_story_1011_10110502_118_dialog_content = "「답변이 입력되었습니다.」",
  ui_story_1011_10110502_119_dialog_content = "「다음 대상 중에서 파이어플라이를 선택해 주십시오.」",
  ui_story_1011_10110502_120_dialog_content = "이건... 홀로그램인가?",
  ui_story_1011_10110502_121_dialog_content = "진짜랑 똑같네!",
  ui_story_1011_10110502_122_option_content = "[파이어플라이의 홀로그램을 만진다]",
  ui_story_1011_10110502_123_dialog_content = "「답변이 입력되었습니다.」",
  ui_story_1011_10110502_124_dialog_content = "「인증을 통과했습니다. 아이테르 신분 확인 완료.」",
  ui_story_1011_10110502_125_dialog_content = "「접근 통제 시스템 비밀번호를 재설정해 주십시오.」",
  ui_story_1011_10110502_126_dialog_content = "음... 열려라 참깨!",
  ui_story_1011_10110502_127_dialog_content = "「재설정이 완료되었습니다. 신규 비밀번호는 ‘음... 열려라 참깨!’입니다.」",
  ui_story_1011_10110502_128_dialog_content = "「음...」 같은 것까지 넣을 필요는 없잖아!",
  ui_story_1011_10110502_129_dialog_content = "「문이 곧 개방됩니다.」",
  ui_story_1011_10110502_130_dialog_content = "<color=#e8d9bb>쿠우웅──!</color>",
  ui_story_1011_10110502_131_dialog_content = "으앗?!",
  ui_story_1011_10110502_132_dialog_content = "<color=#e8d9bb>쿠르르릉──!</color>",
  ui_story_1011_10110502_133_dialog_content = "벽의 돌이 갈라졌어... 뒤에 문이 있었어!",
  ui_story_1011_10110502_134_dialog_content = "엄청 크네!",
  ui_story_1011_10110502_135_dialog_content = "근데 그래도 할 말은 해야겠어!",
  ui_story_1011_10110502_136_dialog_content = "방금 그게 무슨 되도 않는 인증이야?!",
  ui_story_1011_10110502_137_dialog_content = "조금이라도 지능이 있는 생물이라면 다 통과할 수 있을 거잖아!",
  ui_story_1011_10110502_137X1_dialog_content = "어쩌면 중요한 건 문제 자체가 아닐지도 몰라.",
  ui_story_1011_10110502_137X2_dialog_content = "문제가 중요한 게 아니면 뭐가 중요한데?",
  ui_story_1011_10110502_137X3_dialog_content = "저런 간단한 질문들로 아이테르의 신분을 확인할 수 있단 말이야?",
  ui_story_1011_10110502_137X4_dialog_content = "방금 내가 질문을 했을 때 녀석은 「미승인 유전자형」이라고 말했어...",
  ui_story_1011_10110502_137X5_dialog_content = "내가 보기엔 아마 다른 검사 방법으로 네 아이테르 혈통을 먼저 확인했을 것 같아.",
  ui_story_1011_10110502_137X6_dialog_content = "그리고 저런 질문을 하는 이유는 아마 네가 「나는 아이테르다」라고\n대답하게 만들고 싶었던 건지도 몰라.",
  ui_story_1011_10110502_137X7_dialog_content = "확실한 대답이 다른 증거보다 더 중요하단 말이야?",
  ui_story_1011_10110502_137X8_dialog_content = "어쩌면 그런 게 바로 기계의 사고방식인 거겠지.",
  ui_story_1011_10110502_137X9_dialog_content = "그런데... 이 폐허에 비접촉 방식으로 유전자를 검사하는 기술도 있단 말이야?",
  ui_story_1011_10110502_137X10_dialog_content = "갑자기 날 꿰뚫어 보는 것 같은 느낌이라 기분이 불편한걸.",
  ui_story_1011_10110502_137X11_dialog_content = "과정은 중요한 게 아냐. 중요한 건 결과지.",
  ui_story_1011_10110502_137X12_dialog_content = "문은 이미 열렸으니까, 우린 이제 문을 열 방법을 고민할 필요가 없잖아.",
  ui_story_1011_10110502_138_dialog_content = "뭐, 맞아. 지금 상황이 이렇게 간단하게 해결된 것도 다행이라고 생각해.",
  ui_story_1011_10110502_139_dialog_content = "지하로 난 문이라면 아마 지하 유적으로 통하는 거겠지.",
  ui_story_1011_10110502_140_dialog_content = "이런 문이 여기 있었다면, 왜 과거의 아이테르들은 이걸 못 찾은 거지?",
  ui_story_1011_10110502_141_dialog_content = "나도 모르겠어. 이상한 점이 너무 많아...",
  ui_story_1011_10110502_142_dialog_content = "어쨌든 길이 생긴 이상, 이 아래에 조사가 필요한 구역이 있다는 거잖아.",
  ui_story_1011_10110502_143_dialog_content = "지금 급한 건 스카이워커호를 수리하고, 암귀를 피해 여길 빠져나갈 방법을 찾는 거야.",
  ui_story_1011_10110502_144_dialog_content = "맞아, 이제 시간이 없어.",
  ui_story_1011_10110502_145_dialog_content = "그럼 얼른 가자!",
  ui_story_1011_10110601_1_dialog_content = "그어어──",
  ui_story_1011_10110601_2_dialog_content = "기습 공격도 제대로 못 하는 열등한 생물들, 귀찮게 굴지 말라고.",
  ui_story_1011_10110601_3_dialog_content = "누가 너흴 보낸 거지? 더 큰 암귀인가? 아니면 그 머리에 문제 있는 과학자냐?",
  ui_story_1011_10110601_4_dialog_content = "아, 잊을 뻔했군. 너흰 말도 못 하는 놈들이었지.",
  ui_story_1011_10110601_5_dialog_content = "크에엑...",
  ui_story_1011_10110601_6_dialog_content = "하하하하하하하! 쓰레기들!",
  ui_story_1011_10110601_7_dialog_content = "네놈들의 시체를 밟아 봤자 아무런 성취감도 없다고.\n이클립스가 고작 이 정도란 말이냐?",
  ui_story_1011_10110601_8_dialog_content = "......",
  ui_story_1011_10110601_10_dialog_content = "누구냐!",
  ui_story_1011_10110601_11_dialog_content = "......",
  ui_story_1011_10110601_12_dialog_content = "<color=#FFB400>드니에르</color>... 일루미나의 배신자. 진짜로 나타날 줄이야.",
  ui_story_1011_10110601_13_dialog_content = "──아, 잊을 뻔했군. 그 이름은 일루미나에서 이미 영원히 제명됐었잖아.",
  ui_story_1011_10110601_14_dialog_content = "흥.",
  ui_story_1011_10110601_15_dialog_content = "쓸모없긴. 조무래기들이 죽는 사이에 볼일을 볼 생각이었으면 잡히질 말았어야지.",
  ui_story_1011_10110601_16_dialog_content = "(조무래기들? ...피제로가 주변에 배치한 부하들인가?)",
  ui_story_1011_10110601_17_dialog_content = "(또 이런 쓸데없는 짓을 멋대로 하고 있었다니...)",
  ui_story_1011_10110601_18_dialog_content = "난 너희 싸움에 끼어들 생각 없어. 이 암귀들은 내가 보낸 것도 아냐.",
  ui_story_1011_10110601_19_dialog_content = "바보 같은 싸움은 그저 저 하얀 탑에 숨겨진 비밀에 영향을 미칠 뿐이야.",
  ui_story_1011_10110601_20_dialog_content = "(하얀 탑? 이 녀석, PlayerName 일행을 쫓아가려던 건가...)",
  ui_story_1011_10110601_21_dialog_content = "하아? 전장이 네 말대로 다 되는 곳이라 생각하는 거냐!",
  ui_story_1011_10110601_22_dialog_content = "들어가려면 그만한 실력이 있어야지.",
  ui_story_1011_10110601_23_dialog_content = "나도 이렇게 서서 너와 쓸데없는 소리나 할 만큼 한가하진 않다고.\n받아라, 노라!",
  ui_story_1011_10110601_24_dialog_content = "강철 턱의 힘을 보여주마!",
  ui_story_1011_10110601_25_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_1011_10110601_26_dialog_content = "정말 귀찮네. 여기가 너랑 무슨 상관이 있다고.",
  ui_story_1011_10110601_27_dialog_content = "난 불필요한 변수가 제일 싫어.",
  ui_story_1011_10110601_28_dialog_content = "뭐, 널 죽여서 문제가 해결된다면 그것도 나름대로 편할 것 같네.",
  ui_story_1011_10110601_29_dialog_content = "하하하하하하하하! 그렇게 나와야지!",
  ui_story_1011_10110601_30_dialog_content = "어디 이 지루한 시간을 함께 보내 보자고!",
  ui_story_1011_10110601_31_dialog_content = "<color=#e8d9bb>탑, 입구 통로</color>",
  ui_story_1011_10110601_32_dialog_content = "<color=#e8d9bb>뚜벅... 뚜벅... 뚜벅...</color>",
  ui_story_1011_10110601_33_dialog_content = "(길고 좁은 통로가 끝없이 이어지는 것 같아...)",
  ui_story_1011_10110601_34_dialog_content = "(뒤쪽은... 입구의 불빛도 이제 거의 안 보일 지경이야.)",
  ui_story_1011_10110601_35_dialog_content = "<color=#e8d9bb>쿠당탕탕...</color>",
  ui_story_1011_10110601_36_dialog_content = "바이스! 조심해!",
  ui_story_1011_10110601_37_dialog_content = "으엑?!",
  ui_story_1011_10110601_38_dialog_content = "<color=#e8d9bb>쾅──</color>",
  ui_story_1011_10110601_39_dialog_content = "조심해!",
  ui_story_1011_10110601_40_dialog_content = "콜록콜록...",
  ui_story_1011_10110601_41_dialog_content = "엄청난 먼지네...!",
  ui_story_1011_10110601_42_dialog_content = "<color=#e8d9bb><size=35>먼지네... 지네... 네...</size></color>",
  ui_story_1011_10110601_43_dialog_content = "?!",
  ui_story_1011_10110601_44_dialog_content = "쉿, 다들 조용히 하는 게 좋겠어.",
  ui_story_1011_10110601_45_dialog_content = "소리를 들어보면 아직 갈 길이 멀어.",
  ui_story_1011_10110601_46_dialog_content = "이런 직선 터널에서 소리를 듣고 뭔가 나타난다면 우린 피할 곳도 없어.",
  ui_story_1011_10110601_47_dialog_content = "그나저나 PlayerName...",
  ui_story_1011_10110601_48_dialog_content = "지금까지 이런 곳이 있는지 정말 몰랐던 거야?",
  ui_story_1011_10110601_49_dialog_content = "응... 나도 그렇지만, 스카이워커도 이 폐허에 대해 얘기한 적 없었어.",
  ui_story_1011_10110601_50_dialog_content = "스카이워커라고 꼭 모든 걸 아는 건 아니니까.",
  ui_story_1011_10110601_51_dialog_content = "......",
  ui_story_1011_10110601_52_dialog_content = "(스카이워커...)",
  ui_story_1011_10110601_53_dialog_content = "어쨌든 우린 의식 모듈의 안내에 따라 여기까지 온 거잖아...",
  ui_story_1011_10110601_54_dialog_content = "그 「중앙 제어 시스템」만 찾으면 될 거야.",
  ui_story_1011_10110601_55_dialog_content = "스카이워커를 고칠 방법도 분명히 거기 있을 거고, PlayerName.",
  ui_story_1011_10110601_56_dialog_content = "응... 고마워, 바이스.",
  ui_story_1011_10110601_57_dialog_content = "음?",
  ui_story_1011_10110601_58_dialog_content = "왜 그래?",
  ui_story_1011_10110601_59_dialog_content = "발밑의 이것들... 평범한 돌조각도 아니고, 우리가 계속 봤던 흰색 돌도 아니야.",
  ui_story_1011_10110601_60_dialog_content = "음... 한번 볼게...",
  ui_story_1011_10110601_61_dialog_content = "확실히 색상이나 재질 모두 특별해.\n전에 아카데미에서 봤던 관련 기록이 맞다면...",
  ui_story_1011_10110601_62_dialog_content = "이건 고대 아스트라 대륙에서만 사용했던 특별한 재료일 거야...",
  ui_story_1011_10110601_63_dialog_content = "(...?!)",
  ui_story_1011_10110601_64_dialog_content = "이, 이것들... 설마...",
  ui_story_1011_10110601_65_dialog_content = "<color=#FFB400>콜로서스의 근육 소재</color>?",
  ui_story_1011_10110601_66_dialog_content = "?!",
  ui_story_1011_10110601_67_dialog_content = "(산산이 조각난 채로 흩뿌려져 있고, 앞으로 갈수록 더 많아지고 있어...)",
  ui_story_1011_10110601_68_dialog_content = "(서, 설마... 이게 전부 콜로서스의 <color=#FFB400>잔해</color>란 말이야?!)",
  ui_story_1011_10110601_69_dialog_content = "그럼... 여긴 진짜로 콜로서스 정비 기지의 내부인 거야!",
  ui_story_1011_10110601_70_dialog_content = "이 수를 봐. 콜로서스는 당시엔 분명히 흔한 교통수단이었을 거야.\n전설이나 역사의 기록이 전부 사실이었어!",
  ui_story_1011_10110601_71_dialog_content = "PlayerName! 저 앞에 출구가 있어!",
  ui_story_1011_10110601_72_dialog_content = "어라... PlayerName, 왜 그래?",
  ui_story_1011_10110601_73_dialog_content = "......",
  ui_story_1011_10110601_74_option_content = "조금 무서워서...",
  ui_story_1011_10110601_75_dialog_content = "이, 이런 모습은 한 번도 본 적이 없었어...",
  ui_story_1011_10110601_76_dialog_content = "나한테 스카이워커는... 가족이고, 친구고, 선생님이었어.",
  ui_story_1011_10110601_77_dialog_content = "바깥으로 나온 뒤에도 난 스카이워커랑 많은 곳을 다녔고,\n스카이워커는 내가 위험할 때 날 여러 번 구해줬어...",
  ui_story_1011_10110601_78_dialog_content = "그런 스카이워커도 이렇게 될 수 있다는 건... 한 번도 생각해 본 적 없었어...",
  ui_story_1011_10110601_79_option_content = "조금 기뻐서...",
  ui_story_1011_10110601_80_dialog_content = "아스트라 대륙에는 이제 존재하는 콜로서스가 거의 없을 거야.",
  ui_story_1011_10110601_81_dialog_content = "지난 17년간 아무도 없었던 헤븐즈 밸리에서... 지금 나랑 스카이워커의 발아래...",
  ui_story_1011_10110601_82_dialog_content = "옛사람들이 남긴 수많은 콜로서스의 흔적을 보니까...",
  ui_story_1011_10110601_83_dialog_content = "뭔가... 소속감을 더 느끼게 되는 것 같아.",
  ui_story_1011_10110601_84_dialog_content = "그랬구나...",
  ui_story_1011_10110601_85_dialog_content = "그럼 얼른 가 보자.",
  ui_story_1011_10110601_86_dialog_content = "이 흔적들이 어디서 온 건지 알아보는 거야!",
  ui_story_1011_10110601_87_dialog_content = "아... 드디어 좀 더 넓어졌네.",
  ui_story_1011_10110601_88_dialog_content = "난 여기가 더 어두울 거라 생각했는데, 그래도 최소한의 빛은 있는 것 같아.",
  ui_story_1011_10110601_89_dialog_content = "대신 저 흐릿한 콜로서스 그림자가 시야를 가려서 그렇지...",
  ui_story_1011_10110601_90_dialog_content = "응, 빛이 어디서 비치는 건지는 모르겠지만,\n적어도 지금 여긴 완전히 밀폐된 공간은 아냐.",
  ui_story_1011_10110601_91_dialog_content = "봐, 콜로서스들이 가지런하게 줄을 이루고 있어...",
  ui_story_1011_10110601_92_dialog_content = "유적이 무너지지 않았다면 분명히 온전하게 보존됐겠지...",
  ui_story_1011_10110601_93_dialog_content = "PlayerName, 감응해 볼래?",
  ui_story_1011_10110601_94_dialog_content = "만약 여기 아직 의식이 있는 콜로서스가 있다면, 연결을 시도할 수 있을 거야.",
  ui_story_1011_10110601_95_dialog_content = "그렇네. 그럼...",
  ui_story_1011_10110601_96_option_content = "(강제 감응!)",
  ui_story_1011_10110601_97_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_1011_10110601_98_dialog_content = "안 돼... 아무 반응도 없어.",
  ui_story_1011_10110601_99_dialog_content = "(그것도 그래. 이런 폐허에 의식이 있는 생명체가 있는 건 절대 불가능해...)",
  ui_story_1011_10110601_100_dialog_content = "그, 그래도 고대 콜로서스가 활동한 흔적은 볼 수 있었잖아.",
  ui_story_1011_10110601_101_dialog_content = "이제 주변의 문을 하나씩 살펴보자.",
  ui_story_1011_10110601_102_dialog_content = "기운 내, PlayerName!",
  ui_story_1011_10110601_103_dialog_content = "응, 그럼...",
  ui_story_1011_10110601_104_option_content = "주변을 둘러보자.",
  ui_story_1011_10110601_105_dialog_content = "<color=#e8d9bb>쿵!</color>",
  ui_story_1011_10110601_106_dialog_content = "...으윽!",
  ui_story_1011_10110601_107_dialog_content = "손이 너무 아파... 문이 전혀 밀리질 않아!",
  ui_story_1011_10110601_108_dialog_content = "콜로서스의 잔해들이 훼손된 정도를 보면 이 방들도 아마 온전하진 못할 거야.",
  ui_story_1011_10110601_109_dialog_content = "무너진 돌들이 문을 막고 있어. 아무래도 갈 수 있는 건 앞쪽 길뿐인 것 같아.",
  ui_story_1011_10110601_110_option_content = "앞으로 가자.",
  ui_story_1011_10110601_111_dialog_content = "응! 앞쪽 길은... 아래층으로 가는 계단인 것 같아!",
  ui_story_1011_10110601_112_dialog_content = "아, 아마 지나갈 수 있겠지? 이렇게 오랜 시간이 지났는데도 부식되지 않았으니까...",
  ui_story_1011_10110601_113_dialog_content = "입구에 한때 수많은 콜로서스가 정박해 있었다면...",
  ui_story_1011_10110601_114_dialog_content = "아래쪽 공간엔 분명히 온전한 콜로서스 수리 시스템이 있을 거야.",
  ui_story_1011_10110601_115_dialog_content = "PlayerName, 계속 가 보자.",
  ui_story_1011_10110601_116_dialog_content = "<color=#e8d9bb>뚜벅... 뚜벅... 뚜벅...</color>",
  ui_story_1011_10110601_117_dialog_content = "(계단이 너무 어둡잖아. 이럴 때 파이어플라이가 있었으면 좋았을 텐데...)",
  ui_story_1011_10110601_118_dialog_content = "(아래에 어떤 기술들이 있을지는 모르겠지만, 스카이워커에 사용할 수 있을까...)",
  ui_story_1011_10110601_119_dialog_content = "(...드디어 끝까지 왔어. 얼른 확인해 보자...)",
  ui_story_1011_10110601_120_dialog_content = "...어라?",
  ui_story_1011_10110601_121_dialog_content = "뭐, 뭐가 어떻게 된 거야?",
  ui_story_1011_10110601_122_dialog_content = "이 층은 이렇게 넓은데... 어딜 봐도 커다란 장치 같은 건 안 보이잖아...",
  ui_story_1011_10110601_123_dialog_content = "이 지하 유적은 내가 생각한 것보다 훨씬 더 큰 것 같아.",
  ui_story_1011_10110601_124_dialog_content = "근데 이 층은 대체 뭘 하는 곳인 거지...",
  ui_story_1011_10110601_125_dialog_content = "먼지투성이인 테이블, 뭘 놓아둔 건지도 알 수 없게 된 돌 선반, 이상한 쿠션까지...",
  ui_story_1011_10110601_126_dialog_content = "무슨 다용도실인가?",
  ui_story_1011_10110601_127_dialog_content = "풉... 아하하하! 그렇게 말하니까 더 확신할 수 있을 것 같아.",
  ui_story_1011_10110601_128_dialog_content = "여긴 아마 고대 아이테르들이 살았던 <color=#FFB400>생활 구역</color>일 거야.",
  ui_story_1011_10110601_129_dialog_content = "일루미나 지하성의 생활 구역에도 비슷한 생활용품이 갖춰져 있거든.",
  ui_story_1011_10110601_130_dialog_content = "비록 이 물건들은 연대도 추정할 수 없을 만큼 낡아버렸지만,\n그래도 형태를 보고 어느 정도는 알아볼 수 있겠어.",
  ui_story_1011_10110601_131_dialog_content = "식탁, 작업대, 식품 보관대, 캐비닛, 예비용 매트리스...",
  ui_story_1011_10110601_132_dialog_content = "이것들은 잡동사니가 아냐, 카렌.",
  ui_story_1011_10110601_133_dialog_content = "나, 나도 알아!",
  ui_story_1011_10110601_134_dialog_content = "으음?",
  ui_story_1011_10110601_135_dialog_content = "바이스, 이 컵 좀 봐. 뭔가 보이는 것 같은데?",
  ui_story_1011_10110601_136_dialog_content = "응? 어디?",
  ui_story_1011_10110601_137_dialog_content = "이, 이건 그냥 평범한 얼룩 아냐?",
  ui_story_1011_10110601_138_dialog_content = "아니, 컵 바닥 쪽 말이야. PlayerName, 와서 봐봐.",
  ui_story_1011_10110601_139_dialog_content = "어라... 정말 무슨 각인이 있는 것 같아!",
  ui_story_1011_10110601_140_dialog_content = "우와, 진짜네!",
  ui_story_1011_10110601_141_dialog_content = "설마 이것도 아이테르 일족과 관계가 있는 건가...",
  ui_story_1011_10110601_142_dialog_content = "난 왠지 아닌 것 같아. 주변의 다른 물건들을 봐.",
  ui_story_1011_10110601_143_dialog_content = "이 컵에만 각인이 있어.",
  ui_story_1011_10110601_144_dialog_content = "그러게, 만약 그게 아이테르 전체의 상징이라면,\n배급되는 모든 물건에 각인이 있어야지.",
  ui_story_1011_10110601_145_dialog_content = "근데 대체 뭐라고 새겨 놓은 거지? 아무리 봐도 잘 모르겠어.",
  ui_story_1011_10110601_146_dialog_content = "왠지... 이름의 줄임말일 것 같긴 한데...",
  ui_story_1011_10110601_147_dialog_content = "안 되겠어. 너무 낡아서 내용을 알아볼 수가 없어.",
  ui_story_1011_10110601_148_dialog_content = "그럼 시간이 없으니까 다른 걸 찾아보자.",
  ui_story_1011_10110601_149_dialog_content = "음......",
  ui_story_1011_10110601_150_dialog_content = "(말은 그렇게 했지만, 그래도 신경이 쓰이겠지...)",
  ui_story_1011_10110601_151_dialog_content = "(여기서 선조들의 이름을 볼 수 있다면,\n그것도 PlayerName한테 의미가 있는 인연일 거야.)",
  ui_story_1011_10110601_152_dialog_content = "(그래! 단서를 좀 더 찾아보자!)",
  ui_story_1011_10110601_153_dialog_content = "어라, 여기 탁자 위에 있는 것들은 뭐지...?",
  ui_story_1011_10110601_154_dialog_content = "이상하네, 이건...",
  ui_story_1011_10110601_155_dialog_content = "앵무조개?",
  ui_story_1011_10110601_156_dialog_content = "앵무조개가 여러 개 한데 놓여 있어.",
  ui_story_1011_10110601_157_dialog_content = "저기, PlayerName, 이것도 아이테르 일족의... 음, 생필품이야...?",
  ui_story_1011_10110601_158_dialog_content = "응? 이거... 방금 찾은 거야?",
  ui_story_1011_10110601_159_dialog_content = "난 처음 보는 건데. 그게 뭔지도 잘 모르겠어.",
  ui_story_1011_10110601_160_dialog_content = "앵무조개? 이건 바다에만 존재하는 생물이야.",
  ui_story_1011_10110601_161_dialog_content = "설마... 헤븐즈 밸리가 전에는 바다였던 건가?\n아니면... 이게 고대 아이테르의 음식인가?",
  ui_story_1011_10110601_162_dialog_content = "어느 쪽이든 이상하잖아!",
  ui_story_1011_10110601_163_dialog_content = "음, 이 앵무조개들, 어쩌면 우리가 평소에 알고 있던 것과는 차이가 있을지도 몰라...",
  ui_story_1011_10110601_164_dialog_content = "작고 매끄러운 데다가, 무척 가벼워.\n오랜 시간이 지났는데도 이렇게 잘 보존됐고 말이야.",
  ui_story_1011_10110601_165_dialog_content = "아무래도 편리한 휴대와 보관에 중점을 두고 설계된 것 같아.",
  ui_story_1011_10110601_166_dialog_content = "그리고... 으아앗?!",
  ui_story_1011_10110601_167_dialog_content = "아, 안에 뭔가 있어?!",
  ui_story_1011_10110601_168_dialog_content = "뭐야?!",
  ui_story_1011_10110601_169_dialog_content = "다쳤어?! 안에서 뭐가 나온 거야?",
  ui_story_1011_10110601_170_dialog_content = "그...그건 아닌데... 손에 부어봐도 별 느낌이 없어.",
  ui_story_1011_10110601_171_dialog_content = "킁킁...",
  ui_story_1011_10110601_172_dialog_content = "음, 무색, 무취에, 유동성이 강해. 어떤 액체인지는 잘 모르겠어.",
  ui_story_1011_10110601_173_dialog_content = "(음? 앵무조개... 액체?)",
  ui_story_1011_10110601_174_dialog_content = "(설마...)",
  ui_story_1011_10110601_175_dialog_content = "휴... 아무튼 신중하게 대하는 게 좋아. 전부 정체를 알 수 없는 물건들이니까.",
  ui_story_1011_10110601_176_dialog_content = "그, 그것도 그렇네...",
  ui_story_1011_10110601_177_dialog_content = "(확실한 증거가 나오기 전까진 멋대로 추측하지 않는 게 좋겠어.)",
  ui_story_1011_10110601_178_dialog_content = "(내 생각이 맞다면, 검증에 도움이 될 만한 단서가 이 폐허에 있을 거야.)",
  ui_story_1011_10110601_179_dialog_content = "(일단 주머니에 넣어두자...)",
  ui_story_1011_10110601_180_dialog_content = "<color=#e8d9bb>쿵!</color>",
  ui_story_1011_10110601_181_dialog_content = "뭐야?!",
  ui_story_1011_10110601_182_dialog_content = "PlayerName, 카렌, 괜찮아?",
  ui_story_1011_10110601_183_dialog_content = "응? 난 네 쪽에서 난 소리인 줄 알았는데? 잠깐만.",
  ui_story_1011_10110601_184_dialog_content = "...뭔가 이상해!",
  ui_story_1011_10110601_185_dialog_content = "설마 여기 다른 사람이 있는 건가?",
  ui_story_1011_10110601_186_dialog_content = "누가 있었다면 진작에 모습을 드러냈겠지...",
  ui_story_1011_10110601_187_dialog_content = "그어어...",
  ui_story_1011_10110601_188_dialog_content = "크오오오!",
  ui_story_1011_10110601_189_dialog_content = "말도 안 돼! 여기도 암귀가 있단 말이야?!",
  ui_story_1011_10110601_190_dialog_content = "우릴 따라서 들어온 건가...",
  ui_story_1011_10110601_191_dialog_content = "PlayerName, 준비됐어?",
  ui_story_1011_10110601_192_dialog_content = "물론이지.",
  ui_story_1011_10110702_1_dialog_content = "PlayerName, PlayerName!",
  ui_story_1011_10110702_2_dialog_content = "대, 대체 뭐가 어떻게 된 거야...",
  ui_story_1011_10110702_3_dialog_content = "일어나, PlayerName!",
  ui_story_1011_10110702_4_dialog_content = "(으윽...)",
  ui_story_1011_10110702_5_dialog_content = "(괴로워... 숨이 안 쉬어져...)",
  ui_story_1011_10110702_6_dialog_content = "(바이스랑 카렌이... 날 부르는 건가? 목소리가 엄청 멀게 느껴져...)",
  ui_story_1011_10110702_7_dialog_content = "(난...)",
  ui_story_1011_10110702_8_dialog_content = "대상 감지, 초감각 특성 생명체... 신분 확인, 아이테르.",
  ui_story_1011_10110702_9_dialog_content = "정신 연결이 실행되었습니다.",
  ui_story_1011_10110702_10_dialog_content = "경고, 감지 대상의 호흡 기관에 산소 함유량이 부족합니다.\n생활 구역의 송풍 시스템이 실행됩니다.",
  ui_story_1011_10110702_11_dialog_content = "<color=#e8d9bb>휘이잉── 휘잉──</color>",
  ui_story_1011_10110702_12_dialog_content = "(무, 무슨 소리지...)",
  ui_story_1011_10110702_13_dialog_content = "어라...?",
  ui_story_1011_10110702_14_dialog_content = "앗, PlayerName!",
  ui_story_1011_10110702_15_dialog_content = "PlayerName, 정신이 들어?!",
  ui_story_1011_10110702_16_dialog_content = "괜찮아? 이상한 느낌은 없어?",
  ui_story_1011_10110702_17_dialog_content = "...이제 괜찮은 것 같아.",
  ui_story_1011_10110702_18_dialog_content = "방금 전투도 너무 치열했고, 걸어오느라 체력을 많이 써서...",
  ui_story_1011_10110702_19_dialog_content = "<size=33>숨도 제대로 못 쉬었더니...</size>",
  ui_story_1011_10110702_20_dialog_content = "격렬한... 전투?",
  ui_story_1011_10110702_21_dialog_content = "체력을... 써?",
  ui_story_1011_10110702_22_dialog_content = "......",
  ui_story_1011_10110702_23_dialog_content = "(...왜 그런 눈으로 날 쳐다보는 건데?!)",
  ui_story_1011_10110702_24_dialog_content = "감지 대상의 신체 기능 상황 분석 중...",
  ui_story_1011_10110702_25_dialog_content = "상태, 정상... 신체 평가 등급, A급 허약.",
  ui_story_1011_10110702_26_dialog_content = "?!",
  ui_story_1011_10110702_27_dialog_content = "누구야?! 누가 말하고 있어?!",
  ui_story_1011_10110702_28_dialog_content = "맞는 말이긴 한데...",
  ui_story_1011_10110702_29_dialog_content = "에이드 브레인의 임무는 아이테르를 섬기고, 아이테르의 모든 문제를 해결하는 것입니다.",
  ui_story_1011_10110702_30_dialog_content = "접수, 질문 분석 중...",
  ui_story_1011_10110702_31_dialog_content = "답변 생성, 에이드 브레인은 아이테르가 도움이 필요함을 감지했습니다.\n에이드 브레인은 아이테르와 대화를 시도하고 있습니다.",
  ui_story_1011_10110702_32_dialog_content = "(이런 질문까지 그렇게 긴 분석이 필요한 거야?!)",
  ui_story_1011_10110702_33_dialog_content = "근데 그러고 보니까 방금 내가 기절했을 때...",
  ui_story_1011_10110702_34_dialog_content = "경고, 감지 대상의 호흡 기관에 산소 함유량이 부족합니다.\n생활 구역의 송풍 시스템이 실행됩니다.",
  ui_story_1011_10110702_35_dialog_content = "확실히 저게 송풍 시스템을 작동시켰어. 그래서 나도 정신을 차릴 수 있었어.",
  ui_story_1011_10110702_36_dialog_content = "아, 어쩐지 방금... 시원한 바람이 느껴졌어.",
  ui_story_1011_10110702_36X_dialog_content = "이건 뭐지? 그냥 허상처럼 보이는데.",
  ui_story_1011_10110702_37_dialog_content = "고대 아이테르의 기술인가... 중요한 순간엔 꽤 도움이 되네.",
  ui_story_1011_10110702_38_dialog_content = "우와, 나도 볼래. 여기 아직도 작동하는 인공지능이 있었단 말이야?!",
  ui_story_1011_10110702_39_dialog_content = "으음...",
  ui_story_1011_10110702_40_dialog_content = "......",
  ui_story_1011_10110702_41_dialog_content = "대상 감지, 루미나 에너지 생명체... 신분 확인, 오로리안... 개체 수, 2.",
  ui_story_1011_10110702_42_dialog_content = "「에이드 브레인」, 넌... 고대 아이테르의 기술 중 하나야?",
  ui_story_1011_10110702_43_dialog_content = "접수, 질문 분석 중... 분석 오류.\n에이드 브레인의 임무는 아이테르의 모든 문제를 해결하는 것입니다.",
  ui_story_1011_10110702_44_dialog_content = "뭐, 뭐 이래?! 그럼 오로리안은 아이테르의 장치를 사용할 수 없는 거야?!",
  ui_story_1011_10110702_45_dialog_content = "접수, 질문 분석 중... 분석 오류.\n에이드 브레인의 임무는 아이테르의 모든 문제를 해결하는 것입니다.",
  ui_story_1011_10110702_46_dialog_content = "아, 진짜... 방금 그건 질문이 아니잖아!",
  ui_story_1011_10110702_47_dialog_content = "네가 성격이 별로라고 말한 오로리안은 없었어?!",
  ui_story_1011_10110702_48_dialog_content = "진정해, 바이스. 내가 직접 물어볼게!",
  ui_story_1011_10110702_49_dialog_content = "에, 에이드 브레인! 물어볼 게 좀 있어.",
  ui_story_1011_10110702_50_dialog_content = "접수, 시스템 인식 수정 중...\n「에 에이드 브레인」, 장치의 새 이름을 입력하는 중입니다.",
  ui_story_1011_10110702_51_dialog_content = "하아? 잠깐만... 기록 정지! 기록 정지!",
  ui_story_1011_10110702_52_dialog_content = "기록이 정지되었습니다.",
  ui_story_1011_10110702_53_dialog_content = "(휴, 대충 알겠어. 고대부터 지금까지 보존된 인공지능이긴 해도...)",
  ui_story_1011_10110702_54_dialog_content = "(왠지 별로 똑똑해 보이진 않는단 말이지...)",
  ui_story_1011_10110702_55_dialog_content = "(의사소통을 제대로 하려면 질문을 나눠서 하는 게 좋겠어...)",
  ui_story_1011_10110702_56_dialog_content = "크흠... 첫 번째 질문이야. 이 탑은 뭘 하는 곳이야?",
  ui_story_1011_10110702_57_dialog_content = "접수, 질문 분석 중...",
  ui_story_1011_10110702_58_dialog_content = "답변 생성, 이곳은 <color=#FFB400>「귀환의 탑」</color>입니다.",
  ui_story_1011_10110702_59_dialog_content = "(귀환의 탑? 돌아가는 길을 안내하는 건물이란 얘긴가? 등대 같은 건가...)",
  ui_story_1011_10110702_60_dialog_content = "귀환...은 정확히 뭘 의미하는데?\n스카이워커가 여기로 자동 조종한 것도 귀환을 위해서인 거야?",
  ui_story_1011_10110702_61_dialog_content = "죄송합니다. 에이드 브레인은 모릅니다.",
  ui_story_1011_10110702_62_dialog_content = "(이, 이렇게 대놓고 「모른다」고 말하는 거야?!)",
  ui_story_1011_10110702_63_dialog_content = "자... 그럼 두 번째 질문이야. 이 탑의 원래 내부 구조는 어떤 식이었어?",
  ui_story_1011_10110702_64_dialog_content = "우린 지금 귀환의 탑의 어디쯤에 있는 거야?",
  ui_story_1011_10110702_65_dialog_content = "에이드 브레인 기능 소개 재생 중,\n에이드 브레인은 귀환의 탑의 서비스 인공지능입니다...",
  ui_story_1011_10110702_66_dialog_content = "에이드 브레인은 아이테르의 권한과 명령에 따라 아이테르에게 도움을 제공합니다.",
  ui_story_1011_10110702_67_dialog_content = "아이테르 보유 권한을 확인하는 중입니다...",
  ui_story_1011_10110702_68_dialog_content = "확인 완료, 에이드 브레인은 귀환의 탑의 내부 지도를 제공할 수 있습니다.",
  ui_story_1011_10110702_69_dialog_content = "(다행이야!)",
  ui_story_1011_10110702_70_dialog_content = "잘됐네! 그럼 이제 길을 안 헤매도 되잖아!",
  ui_story_1011_10110702_71_dialog_content = "그럼 스카이워커호를 고칠 수 있는 곳도 얼른 찾아보자.",
  ui_story_1011_10110702_72_dialog_content = "(아, 별로 기대는 안 되지만 그래도 물어봐야겠어...)",
  ui_story_1011_10110702_73_dialog_content = "마지막 질문이야. 「중앙 제어 시스템」에 들어가는 방법을 알려줘.",
  ui_story_1011_10110702_74_dialog_content = "......",
  ui_story_1011_10110702_75_dialog_content = "죄송합니다. 에이드 브레인은 모릅니다.",
  ui_story_1011_10110702_76_dialog_content = "삐── 뽀── 삐── 뽀──♪",
  ui_story_1011_10110702_77_dialog_content = "(...이건 또 뭘 흥얼거리는 거야?!)",
  ui_story_1011_10110702_78_dialog_content = "...됐어, PlayerName. 일단 가자. 없는 것보다는 나을 테니까.",
  ui_story_1011_10110702_79_dialog_content = "내부 지도도 얻었으니까, 에이드 브레인으로 위치를 확인해 봐.",
  ui_story_1011_10110702_80_dialog_content = "그렇네, 어디 보자...",
  ui_story_1011_10110702_81_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_1011_10110702_82_dialog_content = "역시 그랬어. 이 귀환의 탑은 층마다 다른 용도가 있어.\n그리고 우린 아직 외곽 구역에 있고.",
  ui_story_1011_10110702_83_dialog_content = "처음 들어왔을 때 우리가 있었던 층은 「콜로서스 정비 기지」였어.",
  ui_story_1011_10110702_84_dialog_content = "그리고 거긴 우리도 봤다시피 전부 파괴돼서 아무것도 없었어.",
  ui_story_1011_10110702_85_dialog_content = "지금 층은... 바이스가 짐작한 대로 「아이테르 생활 구역」이야.",
  ui_story_1011_10110702_86_dialog_content = "여기도 이미 전부 살펴봤어.",
  ui_story_1011_10110702_87_dialog_content = "이 두 층에는 무너져서 들어갈 수 없는 방이 많았지만 말이야...",
  ui_story_1011_10110702_88_dialog_content = "「콜로서스 부품 공장」, 「자원 생산 구역」...\n그리고 「폐기물 처리 구역」까지... 전부 묻혀 있어.",
  ui_story_1011_10110702_89_dialog_content = "스카이워커...",
  ui_story_1011_10110702_90_dialog_content = "너무 걱정하지 마. 지도를 봐, 아직 안 찾아본 공간이 아래에 많이 남아 있잖아.",
  ui_story_1011_10110702_91_dialog_content = "당장은 너도 마음이 안 좋을 거라는 거 이해해.\n그래도 아래로 내려갈수록 분명히 더 많은 정보를 얻을 수 있을 거야.",
  ui_story_1011_10110702_92_dialog_content = "맞아, 기운 내, PlayerName. 어떻게든 방법이 있을 테니까!",
  ui_story_1011_10110702_93_dialog_content = "응. 그럼 얼른 아래층으로 가 보자.",
  ui_story_1011_10110702_94_dialog_content = "이 아래 공간은... 음? <color=#FFB400>「추방 구역」</color>...?",
  ui_story_1011_10110702_95_dialog_content = "추방?!",
  ui_story_1011_10110702_96_dialog_content = "이상해... 아이테르는 평화를 사랑하는 종족인데, 그런 구역이 있단 말이야...?",
  ui_story_1011_10110702_97_dialog_content = "...만약 여기 침입한 암귀를 추방하기 위한 공간이라면 말이 된다고 생각해.",
  ui_story_1011_10110702_98_dialog_content = "아무튼 별로 좋은 곳은 아닐 것 같으니까 조심하자.",
  ui_story_1011_10110901_1_dialog_content = "<color=#e8d9bb>귀환의 탑, 추방 구역</color>",
  ui_story_1011_10110901_2_dialog_content = "스읍... 후우...",
  ui_story_1011_10110901_3_dialog_content = "(이 공간의 용도를 미리 알고 나니까 더 긴장되잖아...)",
  ui_story_1011_10110901_4_dialog_content = "(암귀가 튀어나오면 곧바로 쏴버릴 거야!)",
  ui_story_1011_10110901_5_dialog_content = "삐── 뽀── 삐── 뽀──♪",
  ui_story_1011_10110901_6_dialog_content = "삐비비비, 삐비비, 삐비비, 삐빅──♪",
  ui_story_1011_10110901_7_dialog_content = "「떠나갈 것은 끝내 떠나가고~ 남아야 할 것은 영원히 남는다~♪」",
  ui_story_1011_10110901_8_dialog_content = "시끄러워.",
  ui_story_1011_10110901_9_dialog_content = "PlayerName, 여긴 언제라도 암귀가 나올 수 있는데, 좀 말릴 순 없을까?",
  ui_story_1011_10110901_10_dialog_content = "...감응을 다시 시도해 볼게.",
  ui_story_1011_10110901_11_dialog_content = "정신 감응이 실행되었습니다.",
  ui_story_1011_10110901_12_dialog_content = "에이드 브레인은 안전한 여가 시간에 아이테르를 위해 무작위로 음악을 재생합니다.",
  ui_story_1011_10110901_13_dialog_content = "고대의 음악입니다. 아이테르, 마음에 드시나요?",
  ui_story_1011_10110901_14_dialog_content = "그 엉망진창 부서진 것 같은 멜로디도 일단은 음악이라고 해 둘게...",
  ui_story_1011_10110901_15_dialog_content = "모든 아이테르는 에이드 브레인의 랜덤 플레이리스트를 수정할 권한이 있습니다...",
  ui_story_1011_10110901_16_dialog_content = "또한 에이드 브레인은 아이테르의 취향을 학습해 자동 수정을 진행할 수 있습니다.\n수정하시겠습니까?",
  ui_story_1011_10110901_17_dialog_content = "...됐어, 그냥 놔둬.",
  ui_story_1011_10110901_18_dialog_content = "(그것도 과거에서 온 메아리니까.)",
  ui_story_1011_10110901_19_dialog_content = "그래도 에이드 브레인이 공간의 안전성을 감지할 수 있으니까...",
  ui_story_1011_10110901_20_dialog_content = "당분간은 너무 긴장하지 않아도 될 것 같아.",
  ui_story_1011_10110901_21_dialog_content = "근데 이 층은 아무리 봐도 좀 불편한 느낌이야.",
  ui_story_1011_10110901_22_dialog_content = "생명체가 활동한 흔적은 거의 없지만...",
  ui_story_1011_10110901_23_dialog_content = "이 방들의 문 뒤를 봐.",
  ui_story_1011_10110901_24_dialog_content = "저, 전부 다 긁힌 자국이잖아...",
  ui_story_1011_10110901_25_dialog_content = "그리고 이 방들의 배열이 일정하고 밀집해 있는 걸 봐...",
  ui_story_1011_10110901_26_dialog_content = "백야성의 감옥도 이런 모습이야.",
  ui_story_1011_10110901_27_dialog_content = "......",
  ui_story_1011_10110901_28_dialog_content = "근데 왜 굳이 암귀를 가둬두는 거지? 바로 없애버리는 게 낫지 않아?",
  ui_story_1011_10110901_29_dialog_content = "설마 고대의 아이테르도 전투 능력이 없었던 건가?",
  ui_story_1011_10110901_30_dialog_content = "아니지, 전투 능력이 없더라도 지금까지 본 아이테르의 기술이라면...",
  ui_story_1011_10110901_31_dialog_content = "싸우거나 방어할 무기를 충분히 만들어낼 수 있었을 것 같은데 말이야.",
  ui_story_1011_10110901_32_dialog_content = "<color=#e8d9bb>딸그락──</color>",
  ui_story_1011_10110901_33_dialog_content = "어라?",
  ui_story_1011_10110901_34_dialog_content = "뭔가 밟았나?",
  ui_story_1011_10110901_35_dialog_content = "어디 보자...",
  ui_story_1011_10110901_36_dialog_content = "으엑?!",
  ui_story_1011_10110901_37_dialog_content = "철제로 된 이름표잖아?!",
  ui_story_1011_10110901_38_dialog_content = "「이름, 테노치. 신분, 아이테르」...",
  ui_story_1011_10110901_39_dialog_content = "「추, <color=#FFB400>추방 기간</color>, 14년」...",
  ui_story_1011_10110901_40_dialog_content = "여기도 있어. 「이름, 티란. 신분, 아이테르. 추방 기간, 12년」.",
  ui_story_1011_10110901_41_dialog_content = "이 방에 갇혀 있던 건 전부 네 동족들이었어, PlayerName.",
  ui_story_1011_10110901_42_dialog_content = "그러니까 「추방 구역」의 정식 명칭은... 「아이테르 추방 구역」이란 거야?!",
  ui_story_1011_10110901_43_dialog_content = "근데... 대체 왜... 동족을 감금한 거지?",
  ui_story_1011_10110901_44_dialog_content = "아이테르는 「평화를 추구했다」는 게 설마 거짓이었던 거야?!",
  ui_story_1011_10110901_45_dialog_content = "진정해, PlayerName. 결론이 나올 때까진 충동적으로 판단하면 안 돼.",
  ui_story_1011_10110901_46_dialog_content = "생각해 봐. 만약 고대의 아이테르가 엄청난 인구수의 종족이었다면...",
  ui_story_1011_10110901_47_dialog_content = "질서를 유지하기 위해 어느 정도의 강제 수단을 사용하는 건 필연적인 일이야.",
  ui_story_1011_10110901_48_dialog_content = "그렇다고 해도 아이테르들은 의식을 서로 연결해서 네가 말한 걸 해낼 수 있어.",
  ui_story_1011_10110901_49_dialog_content = "굳이 동족을 감옥에 가두고 저런 기나긴 시간 동안 배척할 필요도 없단 말이야.",
  ui_story_1011_10110901_50_dialog_content = "에이드 브레인, 내 질문에 답해줘.",
  ui_story_1011_10110901_51_dialog_content = "접수, 질문 분석 중... 키워드 확인 성공. 답변 생성...",
  ui_story_1011_10110901_52_dialog_content = "<color=#FFB400>프란츠 선생님</color>께서 말씀하셨습니다.\n「그 순간부터, 우리와 저들은 동족이 아니었다.」",
  ui_story_1011_10110901_53_dialog_content = "?!",
  ui_story_1011_10110901_54_dialog_content = "「동족이 아니다」라는 게 무슨 뜻이야?",
  ui_story_1011_10110901_55_dialog_content = "「저들」은 또 누구야?",
  ui_story_1011_10110901_56_dialog_content = "설마 수천 년 전 아이테르들 사이에 <color=#FFB400>돌이킬 수 없는 갈등</color>이 있었던 거야?",
  ui_story_1011_10110901_57_dialog_content = "(그래서 서로한테 이런 짓을 한 거야...?)",
  ui_story_1011_10110901_57X1_dialog_content = "접수, 질문 분석 중...",
  ui_story_1011_10110901_57X2_dialog_content = "현존하는 빅데이터에 의하면 대다수의 아이테르와 프란츠 선생님은 원만한 관계가 아니었습니다.",
  ui_story_1011_10110901_57X3_dialog_content = "프란츠 선생님은 확실히 한때 「추방 구역」에 구금되어 있었습니다.",
  ui_story_1011_10110901_57X3X1_dialog_content = "부연 설명을 해 드리자면, 「추방 구역」은 아이테르 이단을 수감하는 구역입니다.",
  ui_story_1011_10110901_57X3X2_dialog_content = "프란츠 선생님과 휘하의 연구원들은 모두 같은 이유로 이곳에 수감되었습니다.",
  ui_story_1011_10110901_57X3X3_dialog_content = "수감 이유는 「급진적 이념과 사상으로 선동을 일삼음」입니다.",
  ui_story_1011_10110901_57X4_dialog_content = "「프란츠」와 관계가 있는 연관 키워드는 모두 끔찍한 것들입니다...\n다음으로 연관 키워드 예시를 알려드리겠습니다.",
  ui_story_1011_10110901_57X5_dialog_content = "괴물, 미치광이, 세뇌 전문가, 뇌엽 수집가...",
  ui_story_1011_10110901_57X6_dialog_content = "음... PlayerName, 이제 됐으니까 멈추라고 해 줘...",
  ui_story_1011_10110901_57X7_dialog_content = "왠지 아주... 음, 조금 이상한 연구원처럼 들리는데?",
  ui_story_1011_10110901_57X8_dialog_content = "프란츠 선생님은 각종 신기술의 연구에 몰두하셨습니다.",
  ui_story_1011_10110901_57X9_dialog_content = "「연구의 길은 항상 험난함으로 가득하고, 이해받지 못하는 것은 흔한 일이다.」\n프란츠 선생님은 항상 그렇게 말했습니다.",
  ui_story_1011_10110901_57X10_dialog_content = "또한 프란츠 선생님은 가장 위대한 발명품 중 하나를 가지고 있습니다.",
  ui_story_1011_10110901_57X11_dialog_content = "아이테르, 당신의 동료 유형을 통해 확인할 수 있습니다.\n그 발명품은 확실히 그 이후의 세계를 바꾸었습니다.",
  ui_story_1011_10110901_57X12_dialog_content = "세계를... 바꿨다고?",
  ui_story_1011_10110901_57X13_dialog_content = "과거와 비교하면 지금의 아이테르는 확실히 입장과 관습이 바뀌었습니다.",
  ui_story_1011_10110901_57X14_dialog_content = "오로리안이나 아인족 같은 종족들과도 공동의 적을 가질 수 있게 되었으니 말입니다.",
  ui_story_1011_10110901_57X15_dialog_content = "프란츠 선생님이 아직 살아 계셨다면 분명히 기뻐하셨을 겁니다.",
  ui_story_1011_10110901_57X16_dialog_content = "「입장과 관습」? 그럼... 고대의 아이테르는 대체 어떤 세력이었는데?",
  ui_story_1011_10110901_57X17_dialog_content = "「가장 위대한 발명품」은 또 뭔데?",
  ui_story_1011_10110901_58_dialog_content = "아이테르 보유 권한을 확인하는 중입니다...",
  ui_story_1011_10110901_59_dialog_content = "죄송합니다. 권한이 부족합니다. 에이드 브레인은 답변을 제공할 수 없습니다.",
  ui_story_1011_10110901_60_dialog_content = "알겠어. 그래도 간단한 질문 정도는 할 수 있지?",
  ui_story_1011_10110901_61_dialog_content = "그럼 아까 우리가 하던 얘기로 돌아가자...",
  ui_story_1011_10110901_61X1_dialog_content = "「그 순간부터, 우리와 저들은 동족이 아니었다.」",
  ui_story_1011_10110901_63_dialog_content = "그 사람이 말한 「우리」도 아이테르야?",
  ui_story_1011_10110901_64_dialog_content = "답변 생성, 「우리」는 아이테르입니다.",
  ui_story_1011_10110901_65_dialog_content = "......",
  ui_story_1011_10110901_66_dialog_content = "오류, 오류, 에이드 브레인은 아이테르가 아닙니다.",
  ui_story_1011_10110901_67_dialog_content = "에이드 브레인 기능 소개 재생 중,\n에이드 브레인은 귀환의 탑의 서비스 인공지능입니다...",
  ui_story_1011_10110901_68_dialog_content = "...내 말이나 들어! 아무도 너 같은 기계가 아이테르라고 생각 안 해!",
  ui_story_1011_10110901_69_dialog_content = "에이드 브레인은 아이테르의 권한과 명령에 따라 아이테르에게 도움을 제공합니다.",
  ui_story_1011_10110901_70_dialog_content = "됐어... 더는 못 참겠다고...",
  ui_story_1011_10110901_71_dialog_content = "...잠깐만, 프란츠라면...",
  ui_story_1011_10110901_72_dialog_content = "PlayerName, 위층에서 본 컵 기억나?",
  ui_story_1011_10110901_73_dialog_content = "아, 그러고 보니까 컵 바닥에 흐릿한 각인이...",
  ui_story_1011_10110901_74_dialog_content = "프란츠의 컵이라는 거였나...?",
  ui_story_1011_10110901_75_dialog_content = "접수, 질문 분석 중... 답변 생성,\n프란츠 선생님은 보급 음료를 섭취하는 것을 좋아합니다.",
  ui_story_1011_10110901_76_dialog_content = "프란츠 선생님은 컵을 놓는 일이 없습니다.",
  ui_story_1011_10110901_77_dialog_content = "(진짜였어...)",
  ui_story_1011_10110901_78_dialog_content = "보급 음료 기능 소개 재생 중,\n보급 음료는 상쾌한 귀환의 탑에서 특별 공급되는 음료로, 각성 효과가 있습니다.",
  ui_story_1011_10110901_79_dialog_content = "(그런 쓸데없는 정보는 안 알려줘도 되잖아!)",
  ui_story_1011_10110901_80_dialog_content = "아이테르 생활 구역, 자원 생산 구역, 추방 구역에 대량으로 공급되었습니다.",
  ui_story_1011_10110901_81_dialog_content = "해당 구역의 보급 자판기에서 직접 구매하실 수 있습니다.",
  ui_story_1011_10110901_82_dialog_content = "(자판기?!)",
  ui_story_1011_10110901_83_dialog_content = "(그럼 내 생각이 맞을 거야!)",
  ui_story_1011_10110901_84_dialog_content = "PlayerName, 카렌, 따라 와!",
  ui_story_1011_10110901_85_dialog_content = "<color=#e8d9bb>귀환의 탑, 추방 구역, 보급 자판기 옆</color>",
  ui_story_1011_10110901_86_dialog_content = "<color=#e8d9bb>쾅──! 쾅──!</color>",
  ui_story_1011_10110901_87_dialog_content = "휴... 됐어. 몇 번 발로 차니까 정말로 불이 들어왔어!",
  ui_story_1011_10110901_88_dialog_content = "이게 에이드 브레인이 말한 자판기야?",
  ui_story_1011_10110901_89_dialog_content = "이런 물건... 왠지 익숙한 느낌이네.",
  ui_story_1011_10110901_90_dialog_content = "그러게, 「인공지능」과 「자판기」의 결합은 지하 유적의 표준인 걸까?",
  ui_story_1011_10110901_91_dialog_content = "후후~ 그럼 잘 보고 있어.",
  ui_story_1011_10110901_92_dialog_content = "음, 바로 이거야!",
  ui_story_1011_10110901_93_dialog_content = "어?! 아까 그걸 챙겨왔던 거야?",
  ui_story_1011_10110901_94_dialog_content = "내가 추측한 걸 검증하고 싶었거든.",
  ui_story_1011_10110901_95_dialog_content = "이 앵무조개 모양이랑 안에 들어있는 액체를 보고 생각했어...",
  ui_story_1011_10110901_96_dialog_content = "아이테르들은 이미 음료를 담을 수 있는 컵이 있어.\n그렇다고 조개류를 먹는 문화가 있는 것도 아니야.",
  ui_story_1011_10110901_97_dialog_content = "그럼 고대의 아이테르들은 대체 이걸 가지고 뭘 했을까?",
  ui_story_1011_10110901_98_dialog_content = "그 질문에 대한 답을 지금 거의 확신했어. 봐...",
  ui_story_1011_10110901_99_dialog_content = "이 앵무조개의 액체를 자판기의 이 구멍에 부으면...",
  ui_story_1011_10110901_100_dialog_content = "<color=#e8d9bb>띵! ...털컹!</color>",
  ui_story_1011_10110901_101_dialog_content = "해냈어!",
  ui_story_1011_10110901_102_dialog_content = "짜잔~ 보급 음료를 샀어~ 이미 심하게 변질돼서 마실 순 없겠지만 말이야.",
  ui_story_1011_10110901_103_dialog_content = "이걸 어떻게 안 거야?!",
  ui_story_1011_10110901_104_dialog_content = "이 앵무조개를 보자마자 생각했거든.",
  ui_story_1011_10110901_105_dialog_content = "앵무조개의 선은 사실 특별한 의미를 가지고 있어.",
  ui_story_1011_10110901_106_dialog_content = "이건 수학적 언어로 표현된 「자연」이야.",
  ui_story_1011_10110901_107_dialog_content = "「자연」...? 잘 모르겠어. 이 선이랑 자연과 무슨 상관인데?",
  ui_story_1011_10110901_108_dialog_content = "자연은 우리 주변의 꽃이나 나무 같은 거 아냐?",
  ui_story_1011_10110901_109_dialog_content = "응, 맞아. 꽃이나 나무는 모두 자연이야.",
  ui_story_1011_10110901_110_dialog_content = "하지만 이게 묘사하는 건 자연 뒤에 숨겨진 진실이야.",
  ui_story_1011_10110901_111_dialog_content = "앵무조개의 곡선으로 만물의 성장 과정을 상징하는 거지.",
  ui_story_1011_10110901_112_dialog_content = "아마 간단히 말하자면 「연속성」이라고 할 수 있을 거야.",
  ui_story_1011_10110901_113_dialog_content = "「연속성」?",
  ui_story_1011_10110901_114_dialog_content = "응. 씨앗이 갑자기 한순간에 커다란 나무가 되지 않는 것처럼 말이야.",
  ui_story_1011_10110901_115_dialog_content = "씨앗은 1분, 1초, 순간마다 성장하고 있어.",
  ui_story_1011_10110901_116_dialog_content = "「연속성」은 그런 성장과 변화의 과정을 말하는 거야.",
  ui_story_1011_10110901_117_dialog_content = "아, 왠지 조금 이해가 되는 것 같기도... 하고?",
  ui_story_1011_10110901_118_dialog_content = "그럼 고대 아이테르의 수학적 이론이 「연속성」을 기반으로 한다면...",
  ui_story_1011_10110901_119_dialog_content = "난 저들의 생활 속 많은 것들도 분명히 우리랑 다를 거라고 생각했어.",
  ui_story_1011_10110901_120_dialog_content = "그리고 가장 직접적인 차이점은... 화폐인 거지!",
  ui_story_1011_10110901_121_dialog_content = "아! 우리가 사용하는 동전이나 지폐는 「연속성」이 없잖아. 맞지?",
  ui_story_1011_10110901_122_dialog_content = "그래. 근데 저들의 화폐는... 이 앵무조개의 안을 보면 너도 이해할 거야.",
  ui_story_1011_10110901_123_dialog_content = "...액체?",
  ui_story_1011_10110901_124_dialog_content = "그렇구나. 그럼 이 앵무조개는 사실 고대 아이테르의 지갑이었던 거야?",
  ui_story_1011_10110901_125_dialog_content = "접수, 질문 분석 중... 답변 생성, 노틸러스는 가치를 담는 용기입니다.",
  ui_story_1011_10110901_126_dialog_content = "귀환의 탑에서 거래할 수 있는 사물은 액체의 용량으로 가치를 명시합니다.",
  ui_story_1011_10110901_127_dialog_content = "아이테르는 노틸러스 속 액체를 사용해 거래를 완료할 수 있습니다.",
  ui_story_1011_10110901_128_dialog_content = "알겠어. 개인적으로 이런 쪽은 이해가 잘 안 되지만...",
  ui_story_1011_10110901_129_dialog_content = "그래도 무척 심미적인 이야기로 들려.",
  ui_story_1011_10110901_130_dialog_content = "「자연」의 개념을 숭배하고, 「연속적」인 법칙을 추구한다...",
  ui_story_1011_10110901_131_dialog_content = "그건 확실히 아이테르라는 종족이 한결같이 우리한테 주었던 인상과 같아.",
  ui_story_1011_10110901_132_dialog_content = "대단하네, 바이스! 너랑 에이드 브레인의 설명이 완전히 똑같잖아!",
  ui_story_1011_10110901_133_dialog_content = "뭐, 별거 아닌걸...",
  ui_story_1011_10110901_134_dialog_content = "자, 그럼 계속 내려가 보자.",
  ui_story_1011_10110901_135_dialog_content = "근데 이젠 아래층으로 가는 계단이 없어.",
  ui_story_1011_10110901_136_dialog_content = "추방 구역이 귀환의 탑의 가장 아래인 건가?",
  ui_story_1011_10110901_137_dialog_content = "아닐 텐데... 에이드 브레인이 준 지도를 보면 추방 구역은 딱 중간 정도였어.",
  ui_story_1011_10110901_138_dialog_content = "에이드 브레인, 아래층으로 가는 통로의 위치를 알려줘.",
  ui_story_1011_10110901_139_dialog_content = "접수, 질문 분석 중... 답변 생성, 아래층으로 가는 통로는 이미 무너졌습니다.",
  ui_story_1011_10110901_140_dialog_content = "그럼에도 불구하고 아래층으로 가고 싶으시다면...",
  ui_story_1011_10110901_141_dialog_content = "후방 대각선 위치의 보급 자판기 두 대 사이의 틈을 따라 전진하십시오.",
  ui_story_1011_10110901_142_dialog_content = "<color=#e8d9bb>귀환의 탑, 갈라진 틈의 통로 안</color>",
  ui_story_1011_10110901_143_dialog_content = "음, 너무 어둡고 좁잖아. 들어올 때의 통로보다 더 좁은 것 같아.",
  ui_story_1011_10110901_144_dialog_content = "나도 손발만 겨우 뻗을 수 있을 정도야.",
  ui_story_1011_10110901_145_dialog_content = "(우리가 들어와서 여기가 더 무너지진 않았으면 좋겠는데...)",
  ui_story_1011_10110901_146_dialog_content = "좀 더 서두르자, PlayerName.",
  ui_story_1011_10110901_147_dialog_content = "아, 알겠어...",
  ui_story_1011_10110901_148_dialog_content = "뚜──",
  ui_story_1011_10110901_149_dialog_content = "경고, 전방 50미터에서 생명체가 감지되었습니다.",
  ui_story_1011_10110901_150_dialog_content = "경고, 전방 50미터에서 생명체가 접근 중입니다.",
  ui_story_1011_10110901_151_dialog_content = "뭐, 뭐야?! 이런 일방통행로에서...",
  ui_story_1011_10110901_152_dialog_content = "설마 여기 원래 살던 암귀라도 있는 거야?!",
  ui_story_1011_10110901_153_dialog_content = "경고, 전방 40미터에서 생명체가 접근 중입니다.",
  ui_story_1011_10110901_154_dialog_content = "경고, 전방 30미터...",
  ui_story_1011_10110901_155_dialog_content = "PlayerName, 방법을 찾아봐!",
  ui_story_1011_10110901_156_dialog_content = "경고, 전방 10미터에서 생명체가 감지되었습니다. 신분 확인 중...",
  ui_story_1011_10110901_157_dialog_content = "...아무것도 느껴지질 않아. 적어도 아이테르는 아니야.",
  ui_story_1011_10110901_158_dialog_content = "다들 싸울 준비를 하자.",
  ui_story_1011_10110901_159_dialog_content = "신분 확인, 암귀.",
  ui_story_1011_10110901_160_dialog_content = "크에엑...",
  ui_story_1011_10110901_161_dialog_content = "크오오오──!",
  ui_story_1011_10110901_162_dialog_content = "지형이 복잡하니까 다들 조심해!",
  ui_story_1011_10110902_1_dialog_content = "그어어...",
  ui_story_1011_10110902_2_dialog_content = "아까 좀 더 신경을 썼어야 했어.",
  ui_story_1011_10110902_3_dialog_content = "발밑의 폐허는 전부 전투의 흔적이었어. 우린 더 경계했어야 돼.",
  ui_story_1011_10110902_4_dialog_content = "여긴 추방 구역이랑 연결되는 비밀통로니까, 위험한 것도 당연해.",
  ui_story_1011_10110902_5_dialog_content = "이젠 돌아갈 수도 없어.",
  ui_story_1011_10110902_6_dialog_content = "(<color=#FFB400>전투의 흔적</color>이라면...)",
  ui_story_1011_10110902_7_dialog_content = "에이드 브레인, 지면의 흔적을 스캔하고... 모든 완전한 정보를 보고해 줘.",
  ui_story_1011_10110902_8_dialog_content = "접수, 에이드 브레인 스캔 기능 실행 중...",
  ui_story_1011_10110902_9_dialog_content = "데이터베이스를 확인해 정보 대조 중...",
  ui_story_1011_10110902_10_dialog_content = "스캔 완료.",
  ui_story_1011_10110902_11_dialog_content = "결과는?",
  ui_story_1011_10110902_12_dialog_content = "스캔 보고서 생성 중, 에이드 브레인의 대략적인 확인 결과는 다음과 같습니다.\n이곳의 흔적은 아이테르와 암귀의 전투가 남긴 것입니다.",
  ui_story_1011_10110902_13_dialog_content = "분석 결과, 이곳의 지질학적 성분은 약 200구의 하급 암귀와\n40구의 아이테르를 포함하고 있습니다...",
  ui_story_1011_10110902_14_dialog_content = "아...",
  ui_story_1011_10110902_15_dialog_content = "전방 약 10미터 위치에 아이테르의 이름표 16장과\n아이테르가 사용하는 <color=#FFB400>무기</color> 2정이 있습니다.",
  ui_story_1011_10110902_16_dialog_content = "무기?!",
  ui_story_1011_10110902_17_dialog_content = "에이드 브레인 말이 맞았어. 여기 좀 봐.",
  ui_story_1011_10110902_18_dialog_content = "여기 낙석 옆에 진짜로 총 두 자루가 있어. 얼핏 보기엔 멀쩡한 것 같아.",
  ui_story_1011_10110902_19_dialog_content = "스캔 하위 보고서 생성 중...",
  ui_story_1011_10110902_20_dialog_content = "스캔 결과 정정, 총기 1정의 에너지 장전이 부족하므로,\n아이테르가 사용하는 무기는 1정이 있습니다.",
  ui_story_1011_10110902_21_dialog_content = "자, 이거야.",
  ui_story_1011_10110902_22_dialog_content = "의외로 작네.",
  ui_story_1011_10110902_23_dialog_content = "음... 그러니까 이 총에... 에너지가 장전된 상태라는 거야?",
  ui_story_1011_10110902_24_dialog_content = "접수, 질문 분석... 레이저 건에 대한 간략한 소개가 곧 재생됩니다...",
  ui_story_1011_10110902_25_dialog_content = "무기 명칭, 레이저 건... 발명자, 프란츠 선생님.",
  ui_story_1011_10110902_26_dialog_content = "사용 효과, <color=#FFB400>암귀에 대한 특수 공격</color>... 사용 범위, 아이테르 범용.",
  ui_story_1011_10110902_27_dialog_content = "사용 방법, 감응력을 사용해 레이저 건과 정신 연결을 수립하면,\n소형 암귀의 공격을 효과적으로 격퇴할 수 있습니다.",
  ui_story_1011_10110902_28_dialog_content = "(말만 들어도 엄청 강하잖아! 총기 형태의 스마트 기기라고 해도 되겠어!)",
  ui_story_1011_10110902_29_dialog_content = "어라?",
  ui_story_1011_10110902_30_dialog_content = "총 손잡이에 흠집이 있는 것 같아.",
  ui_story_1011_10110902_31_dialog_content = "스캔 결과 보충, 해당 무기의 소유자는 프란츠 선생님입니다.",
  ui_story_1011_10110902_32_dialog_content = "...또 그 사람이야?!",
  ui_story_1011_10110902_33_dialog_content = "(알게 된 건 일부 정보들뿐이지만, 이 프란츠 선생님은 엄청 대단한 사람인 게 분명해.)",
  ui_story_1011_10110902_34_dialog_content = "경고, 후방 50미터에서 생명체가 접근 중입니다.",
  ui_story_1011_10110902_35_dialog_content = "음? 마침 잘됐네.",
  ui_story_1011_10110902_36_dialog_content = "마음껏 써 봐, PlayerName. 나랑 카렌이 뒤를 봐줄게.",
  ui_story_1011_10110902_37_dialog_content = "응!",
  ui_story_1011_10110902_38_dialog_content = "(두근... 두근...)",
  ui_story_1011_10110902_39_dialog_content = "(지금까지 수많은 전투를 지휘했지만... 직접 싸우려니까 역시 조금 긴장되네...)",
  ui_story_1011_10110902_40_dialog_content = "크에엑...",
  ui_story_1011_10110902_41_dialog_content = "그어어어!",
  ui_story_1011_10110902_42_dialog_content = "(지금이야!)",
  ui_story_1011_10110902_43_dialog_content = "<color=#e8d9bb>펑── 펑!</color>",
  ui_story_1011_10110902_44_dialog_content = "크에엑...",
  ui_story_1011_10110902_45_dialog_content = "해, 해냈어!",
  ui_story_1011_10110902_46_dialog_content = "치명상을 입히진 않았지만, 그래도 완전히 기절시켰어.",
  ui_story_1011_10110902_47_dialog_content = "한 방에 쓰러트렸잖아! 진짜 쓸모 있네!",
  ui_story_1011_10110902_48_dialog_content = "사격할 때 손을 안 떨었던 것도 이미 칭찬할 만한 일이야~",
  ui_story_1011_10110902_49_dialog_content = "하하, 고마워!",
  ui_story_1011_10110902_50_dialog_content = "아무튼 그 총이 있으면 우리의 전력도 더 강해질 거야.",
  ui_story_1011_10110902_51_dialog_content = "그럼 계속 가 보자.",
  ui_story_1011_10111001_1_dialog_content = "끼에에엑!",
  ui_story_1011_10111001_2_dialog_content = "크오오오!",
  ui_story_1011_10111001_3_dialog_content = "그어어어!",
  ui_story_1011_10111001_4_dialog_content = "<color=#e8d9bb>펑── 펑── 펑!</color>",
  ui_story_1011_10111001_5_dialog_content = "PlayerName... 벌써 전투에 적응했구나.",
  ui_story_1011_10111001_6_dialog_content = "근데 그런 강력한 무기가 있다 해도, 암귀가 너무 많잖아...",
  ui_story_1011_10111001_7_dialog_content = "저 암귀들은 대체 어떻게 여기까지 온 거지?",
  ui_story_1011_10111001_8_dialog_content = "(설마 정말로 원래부터 여기서 살고 있던 암귀인 건가...)",
  ui_story_1011_10111001_9_dialog_content = "그리고 이상하게 다들 같은 곳을 향하고 있어.",
  ui_story_1011_10111001_10_dialog_content = "암귀는 자의식이 없잖아. 그럼 대체 어떤 명령에 반응하고 있는 거지?",
  ui_story_1011_10111001_11_dialog_content = "(명령?)",
  ui_story_1011_10111001_12_dialog_content = "(설마 이클립스가 움직인 건가? 아니면...)",
  ui_story_1011_10111001_13_dialog_content = "<color=#e8d9bb>두두두두... 우르르...</color>",
  ui_story_1011_10111001_14_dialog_content = "이런...",
  ui_story_1011_10111001_15_dialog_content = "뭔가 우리 쪽으로 빠르게 다가오고 있어!",
  ui_story_1011_10111001_16_dialog_content = "역시 녀석들 중에 우두머리가 있었어!",
  ui_story_1011_10111001_17_dialog_content = "경고, 전방 30... 경고, 20... 경고, 전방 10미터 앞에서 생명체가 감지되었습니다.",
  ui_story_1011_10111001_18_dialog_content = "<color=#e8d9bb>우르르르──</color>",
  ui_story_1011_10111001_19_dialog_content = "크어어어──!",
  ui_story_1011_10111001_20_dialog_content = "그어어...",
  ui_story_1011_10111001_21_dialog_content = "이건 방금 그 암귀 아냐?!",
  ui_story_1011_10111001_22_dialog_content = "진짜 끈질기네... 분명히 우리가 없앤 거 아니었어?!",
  ui_story_1011_10111001_23_dialog_content = "바이스, 카렌! 다들 물러서!",
  ui_story_1011_10111001_24_dialog_content = "<color=#e8d9bb>퍼엉──!</color>",
  ui_story_1011_10111001_25_dialog_content = "후우, 후우...",
  ui_story_1011_10111001_26_dialog_content = "위험했어. 그래도 이 총이 있어서 다행이야...",
  ui_story_1011_10111001_27_dialog_content = "크에엑...",
  ui_story_1011_10111001_28_dialog_content = "그어어어!",
  ui_story_1011_10111001_29_dialog_content = "뭐야?!",
  ui_story_1011_10111001_30_dialog_content = "효과가 없는 건가?!",
  ui_story_1011_10111001_31_dialog_content = "크아아!",
  ui_story_1011_10111001_32_dialog_content = "PlayerName, 가만히 있지 말고 달려!",
  ui_story_1011_10111001_33_dialog_content = "아, 앞으로? 우린 아직 앞에 뭐가 있는지도 모르잖아...",
  ui_story_1011_10111001_34_dialog_content = "나중 일을 걱정할 때가 아냐!",
  ui_story_1011_10111001_35_dialog_content = "에이드 브레인! 어서 경고를 켜 줘!",
  ui_story_1011_10111001_36_dialog_content = "접수했습니다. 조기 경보 시스템이 장시간 실행됩니다.\n경고, 후방 5미터에서 생명체가 감지되었습니다.",
  ui_story_1011_10111001_37_dialog_content = "경고, 후방 10미터에서 생명체가 감지되었습니다.",
  ui_story_1011_10111001_38_dialog_content = "경고, 후방 15미터에서 생명체가 감지되었습니다. 생명체가 계속해서 접근하는 중입니다...",
  ui_story_1011_10111001_39_dialog_content = "경고, 후방 10미터에서 생명체가 감지되었습니다. 생명체가 계속해서 접근하는 중입니다...",
  ui_story_1011_10111001_40_dialog_content = "후, 후우... 전혀 따돌릴 수가 없잖아!",
  ui_story_1011_10111001_41_dialog_content = "PlayerName! 얼른 따라와!",
  ui_story_1011_10111001_42_dialog_content = "아, 알겠어!",
  ui_story_1011_10111001_43_dialog_content = "경고, 후방 30미터에서 생명체가 감지되었습니다. 생명체가 계속해서 접근하는 중입니다...",
  ui_story_1011_10111001_44_dialog_content = "멈추면 안 돼!",
  ui_story_1011_10111001_45_dialog_content = "<color=#e8d9bb>쿵──!</color>",
  ui_story_1011_10111001_46_dialog_content = "으앗! 아파...",
  ui_story_1011_10111001_47_dialog_content = "어라, 여기 뭔가 있어.",
  ui_story_1011_10111001_48_dialog_content = "어...?",
  ui_story_1011_10111001_49_dialog_content = "바이스! 왜 그래?",
  ui_story_1011_10111001_50_dialog_content = "뭔가에 부딪혔어... 이렇게 좁은 비밀 통로에 왜 이런 장치가 있는 건데?!",
  ui_story_1011_10111001_51_dialog_content = "무슨 조작대 같아. 근데 에이드 브레인이랑 같은 모양을 하고 있어...",
  ui_story_1011_10111001_52_dialog_content = "그래도 이렇게 길을 막으면 안 되지!",
  ui_story_1011_10111001_53_dialog_content = "...잠깐만, 이것도 혹시 사용할 수 있지 않을까?!",
  ui_story_1011_10111001_54_dialog_content = "경고, 후방 25미터에서 생명체가 감지되었습니다...",
  ui_story_1011_10111001_55_dialog_content = "에이드 브레인, 얼른 이 장치 사용법을 알려줘!",
  ui_story_1011_10111001_56_dialog_content = "에이드 브레인의 조기 경보 시스템이 장시간 실행 중입니다.\n지금은 명령을 전환할 수 없습니다.",
  ui_story_1011_10111001_57_dialog_content = "경고, 후방 10미터에서 생명체가 감지되었습니다...",
  ui_story_1011_10111001_58_dialog_content = "아, 이거 아무리 봐도 일루미나의 무기 조작대랑 다를 게 없잖아!",
  ui_story_1011_10111001_59_dialog_content = "가만히 있느니 그냥 한번 시도해 보자!",
  ui_story_1011_10111001_60_dialog_content = "신분 인증은... PlayerName, 부탁할게!",
  ui_story_1011_10111001_61_dialog_content = "그럼 장치는 너한테 맡길게!",
  ui_story_1011_10111001_62_option_content = "(강제 감응!)",
  ui_story_1011_10111001_63_dialog_content = "좋아. 일단 잠금 밸브를 내리고, 장치를 가동하고...",
  ui_story_1011_10111001_64_dialog_content = "그리고...",
  ui_story_1011_10111001_65_dialog_content = "일단 암귀한테 시험해 보자!",
  ui_story_1011_10111001_66_dialog_content = "<color=#e8d9bb>슈우우── 펑!</color>",
  ui_story_1011_10111001_67_dialog_content = "(이건... 암귀만 노리는 공격인가?)",
  ui_story_1011_10111001_68_dialog_content = "그어어어!",
  ui_story_1011_10111001_69_dialog_content = "크에엑...",
  ui_story_1011_10111001_70_dialog_content = "(엄청난 위력이네!)",
  ui_story_1011_10111001_71_dialog_content = "우와...! PlayerName, 이 기계... 왠지 효과가 네 총이랑 똑같은 것 같아!",
  ui_story_1011_10111001_72_dialog_content = "아니, 그 총보다 더 강해!",
  ui_story_1011_10111001_73_dialog_content = "크오오!",
  ui_story_1011_10111001_74_dialog_content = "크오오오!",
  ui_story_1011_10111001_75_dialog_content = "그어어어!",
  ui_story_1011_10111001_76_dialog_content = "(녀석이 죽으면서 더 많은 암귀를 유인해 버렸잖아?!)",
  ui_story_1011_10111001_77_dialog_content = "바이스, 조심해!",
  ui_story_1011_10111001_78_dialog_content = "얼어붙어라!",
  ui_story_1011_10111001_79_dialog_content = "...으윽!",
  ui_story_1011_10111001_80_dialog_content = "바이스! 안 되겠으면 얼른 돌아와!",
  ui_story_1011_10111001_81_dialog_content = "(겨우 여기까지 왔는데... 눈앞에 이렇게 강력한 무기가 있는데...)",
  ui_story_1011_10111001_82_dialog_content = "(진정하자, 분명히 방법이 있을 거야.)",
  ui_story_1011_10111001_83_dialog_content = "(이거야! <color=#FFB400>「전범위 살상 명령」</color>!)",
  ui_story_1011_10111001_84_dialog_content = "<color=#e8d9bb>삐비비비비── 펑!</color>",
  ui_story_1011_10111001_85_dialog_content = "<color=#e8d9bb>펑───! 콰앙!</color>",
  ui_story_1011_10111001_86_dialog_content = "후, 후우... 바이스?",
  ui_story_1011_10111001_87_dialog_content = "바이스──!",
  ui_story_1011_10111001_88_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_1011_10111001_89_dialog_content = "바, 바이스!!!",
  ui_story_1011_10111001_90_dialog_content = "(그럴 리 없어, 의식은 아직 감응되고 있어. 아무 일도 없을 거야!)",
  ui_story_1011_10111001_91_dialog_content = "바이스!!!",
  ui_story_1011_10111001_92_dialog_content = "콜록, 콜록, 여기야! PlayerName, 카렌!",
  ui_story_1011_10111001_93_dialog_content = "다행이야!",
  ui_story_1011_10111001_94_dialog_content = "바이스! 깜짝 놀랐잖아! 난 또 너한테...",
  ui_story_1011_10111001_95_dialog_content = "<color=#e8d9bb>삐비비비비──</color>",
  ui_story_1011_10111001_96_dialog_content = "어라?",
  ui_story_1011_10111001_97_dialog_content = "<color=#e8d9bb>──펑!</color>",
  ui_story_1011_10111001_98_dialog_content = "무슨...",
  ui_story_1011_10111001_99_dialog_content = "<color=#e8d9bb>삑, 삑, 삑, 삑...</color>",
  ui_story_1011_10111001_100_dialog_content = "남은 대상을 찾을 수 없습니다. 「전범위 살상 명령」을 완료했습니다.",
  ui_story_1011_10111001_101_dialog_content = "어, 어째서...",
  ui_story_1011_10111001_102_dialog_content = "이게 뭐야...",
  ui_story_1011_10111001_103_dialog_content = "<size=50>바이스!!!!!!!!!</size>",
  ui_story_1011_10111001_104_dialog_content = "바이스... 바이스!",
  ui_story_1011_10111001_105_dialog_content = "(안 돼!)",
  ui_story_1011_10111001_106_dialog_content = "카렌! 지금은 가면 안 돼!",
  ui_story_1011_10111001_107_dialog_content = "장치에 문제가 있어! 그 장치한테 들키지 마!",
  ui_story_1011_10111001_108_option_content = "(감응 해제!)",
  ui_story_1011_10111001_109_option_content = "(감응 해제...?)",
  ui_story_1011_10111001_110_dialog_content = "(안 돼! 장치가 반응하질 않아!)",
  ui_story_1011_10111001_111_dialog_content = "카렌! 숨어!",
  ui_story_1011_10111001_112_dialog_content = "알았어!",
  ui_story_1011_10111001_113_dialog_content = "<color=#e8d9bb>삑, 삑... 삐비비비빅──</color>",
  ui_story_1011_10111001_114_dialog_content = "?!",
  ui_story_1011_10111001_115_dialog_content = "(이래도 찾아낼 수 있는 건가?!)",
  ui_story_1011_10111001_116_dialog_content = "(달의 고치로 막을 수 있을지 모르겠어...)",
  ui_story_1011_10111001_117_dialog_content = "그어어어!",
  ui_story_1011_10111001_118_dialog_content = "<color=#e8d9bb>──펑!</color>",
  ui_story_1011_10111001_119_dialog_content = "(왜 아직도 암귀가 있는 거야?!)",
  ui_story_1011_10111001_120_option_content = "(감응 해제!)",
  ui_story_1011_10111001_121_dialog_content = "<color=#e8d9bb>삐그덕──</color>",
  ui_story_1011_10111001_122_dialog_content = "(...장치가 멈췄어!)",
  ui_story_1011_10111001_123_dialog_content = "PlayerName, 일단 암귀들부터 상대하자. 바이스한테 가는 걸 막아야 해!",
  ui_story_1011_10111001_124_dialog_content = "우린 지금 바이스가 어떤 상태인지도 모르니까, 더는 지체해선 안 돼!",
  ui_story_1011_10111002_1_dialog_content = "생명체 상태 스캔 중...",
  ui_story_1011_10111002_2_dialog_content = "스캔 결과 생성...",
  ui_story_1011_10111002_3_dialog_content = "생명체 상태 설명, 심장 박동 및 호흡 등 활력 징후를 감지할 수 없습니다.",
  ui_story_1011_10111002_4_dialog_content = "생명체 상태 보고, <color=#FFB400>「의식 소실」</color> 상태가 확인되었습니다.",
  ui_story_1011_10111002_5_dialog_content = "「의식 소실」?",
  ui_story_1011_10111002_6_dialog_content = "PlayerName, 일단 눈을 뜨고 현실을 직시해.",
  ui_story_1011_10111002_7_dialog_content = "어서 바이스를 지금 상황에서 구해내야 해.",
  ui_story_1011_10111002_8_dialog_content = "아, 알겠어...",
  ui_story_1011_10111002_9_dialog_content = "결국... 에이드 브레인과 소통해야 하는 건 나니까...",
  ui_story_1011_10111002_17_option_content = "「의식 소실」이 뭐야?",
  ui_story_1011_10111002_18_dialog_content = "특수 공격 장치의 공격은 생명체를 즉시 「의식 소실」상태에 빠트립니다.",
  ui_story_1011_10111002_19_dialog_content = "「의식 소실」 상태가 된 오로리안은 특수한 혼수상태에 진입하게 됩니다.",
  ui_story_1011_10111002_20_dialog_content = "혼수상태?",
  ui_story_1011_10111002_21_dialog_content = "그럼 바이스를 다시 깨울 수 있다는 거잖아!",
  ui_story_1011_10111002_22_dialog_content = "...「의식 소실」 상태를 더 자세하게 설명해 주고, 해결 방법을 알려줘.",
  ui_story_1011_10111002_23_dialog_content = "접수, 질문 분석 중...",
  ui_story_1011_10111002_24_dialog_content = "답변 생성, 「의식 소실」은 일반적인 혼수상태와 다릅니다.",
  ui_story_1011_10111002_25_dialog_content = "「의식 소실」에 진입한 오로리안은 심장 박동과 호흡은 무기한 정지 상태에 빠집니다.",
  ui_story_1011_10111002_26_dialog_content = "그 체내의 루미나 에너지 또한 무기한 휴면 상태에 진입합니다.",
  ui_story_1011_10111002_27_dialog_content = "「의식 소실」 상태의 해제 방법을 검색하는 중입니다...",
  ui_story_1011_10111002_28_dialog_content = "죄송합니다. 검색에 실패했습니다, 에이드 브레인은 모릅니다.",
  ui_story_1011_10111002_29_dialog_content = "검색에 실패했다는 게 무슨 소리야?!",
  ui_story_1011_10111002_30_dialog_content = "에이드 브레인은 해결 방법을 제공할 수 없습니다.",
  ui_story_1011_10111002_31_dialog_content = "뭐, 뭐야?!",
  ui_story_1011_10111002_32_dialog_content = "그럼 그 상태는 그러니까... 결국...",
  ui_story_1011_10111002_33_dialog_content = "(<color=#FFB400>죽음</color>과 다를 게 없다는 거잖아!)",
  ui_story_1011_10111002_34_dialog_content = "아이테르가 어떻게 이런 물건을 만들어낼 수 있는 거지?",
  ui_story_1011_10111002_36_dialog_content = "아니야, 아닐 거야...",
  ui_story_1011_10111002_37_dialog_content = "분명히 바이스를 구할 방법이 있을 거야...",
  ui_story_1011_10111002_38_dialog_content = "우...우리가 이 유적에서 계속 찾아본다면, 부, 분명히...",
  ui_story_1011_10111002_39_dialog_content = "하지만...",
  ui_story_1011_10111002_40_dialog_content = "만약 내가 암귀를 먼저 다 없앴다면...",
  ui_story_1011_10111002_41_dialog_content = "네가 바이스와의 연결을 끊고 조작을 막을 수 있었다면...",
  ui_story_1011_10111002_41X1_dialog_content = "바이스가 이렇게 되진 않았을 거잖아!",
  ui_story_1011_10111002_41X2_dialog_content = "우린 막을 수 있었어.",
  ui_story_1011_10111002_42_dialog_content = "카렌...",
  ui_story_1011_10111002_43_dialog_content = "......",
  ui_story_1011_10111002_44_dialog_content = "...미안해. 추태를 보였네.",
  ui_story_1011_10111002_45_dialog_content = "(생각해 보면, 저 장치는 대체 왜 바이스를 공격한 거지?)",
  ui_story_1011_10111002_46_dialog_content = "(바이스가 잘못 조작한 걸까...? 그건 아니야, 그랬으면 내가 느낄 수 있었을 거야.)",
  ui_story_1011_10111002_47_dialog_content = "<color=#e8d9bb>삑, 삑, 삑, 삑...</color>",
  ui_story_1011_10111002_48_dialog_content = "남은 대상을 찾을 수 없습니다. 「전범위 살상 명령」을 완료했습니다.",
  ui_story_1011_10111002_49_dialog_content = "그때 그 「전범위 살상 명령」은 바이스가 특수 공격 장치에 내린 명령이었어.",
  ui_story_1011_10111002_50_dialog_content = "에이드 브레인, 저 장치가 왜 바이스를 잘못 공격한 거지?",
  ui_story_1011_10111002_51_dialog_content = "접수, 질문 분석 중... 답변 생성...",
  ui_story_1011_10111002_52_dialog_content = "특수 공격 장치는 정확하게 명령을 실행했습니다.\n특수 공격 장치는 생명체를 잘못 공격하지 않습니다.",
  ui_story_1011_10111002_53_dialog_content = "뭐야?!",
  ui_story_1011_10111002_54_dialog_content = "바이스는 지금 여기 쓰러져 있다고... 헛소리하지 마!",
  ui_story_1011_10111002_55_dialog_content = "에이드 브레인의 답변은 정확합니다. 반복합니다.\n특수 공격 장치는 정확하게 명령을 실행했습니다. 특수 공격 장치는 생명체를...",
  ui_story_1011_10111002_56_dialog_content = "아이테르, 레이저 건을 내려 놓으십시오.\n레이저 건의 마취 효과는 에이드 브레인에게 어떤 피해도 입힐 수 없습니다.",
  ui_story_1011_10111002_57_dialog_content = "반복합니다. 특수 공격 장치는 정확하게 명령을 실행했습니다.\n특수 공격 장치는 생명체를 잘못 공격하지 않습니다.",
  ui_story_1011_10111002_58_dialog_content = "......",
  ui_story_1011_10111002_59_dialog_content = "............",
  ui_story_1011_10111002_60_dialog_content = "PlayerName, 냉정하게, 자세히 물어봐.\n유용한 정보를 얻을 때까지 계속 물어보자.",
  ui_story_1011_10111002_61_dialog_content = "에이드 브레인의 말장난에 같이 놀아주면 안 돼.",
  ui_story_1011_10111002_62_dialog_content = "바이스가 우릴 기다리고 있어.",
  ui_story_1011_10111002_63_dialog_content = "그러고 보니까 아까부터 중요한 질문을 못 했어.",
  ui_story_1011_10111002_64_dialog_content = "에이드 브레인, 이 특수 공격 장치의 <color=#FFB400>사용법</color>을 알려줘.",
  ui_story_1011_10111002_65_dialog_content = "접수, 질문 분석 중... 답변 생성...",
  ui_story_1011_10111002_66_dialog_content = "특수 공격 장치의 사용법을 재생합니다...",
  ui_story_1011_10111002_67_dialog_content = "초기의 특수 공격 장치는 아이테르가 자기방어를 위해 사용한 방어 장치였습니다.",
  ui_story_1011_10111002_68_dialog_content = "적의 유형에 따라 다른 명령을 내리면, 각기 다른 정도의 효과를 발휘할 수 있습니다.",
  ui_story_1011_10111002_69_dialog_content = "그 강력한 효과로 인해 이후에는 전투에 사용되었습니다. 재생을 완료했습니다.",
  ui_story_1011_10111002_70_dialog_content = "그, 그게 다야? 아무것도 답이 안 되잖아!",
  ui_story_1011_10111002_71_dialog_content = "그럼 더 이해가 안 돼. 도대체 왜 바이스까지 공격한 거지?",
  ui_story_1011_10111002_72_dialog_content = "PlayerName...",
  ui_story_1011_10111002_73_dialog_content = "PlayerName, 지금 떠오르는 게 하나 있어.",
  ui_story_1011_10111002_74_dialog_content = "만약 에이드 브레인이 말한 게 이 장치의 사용법의 전부라면...",
  ui_story_1011_10111002_74X1_dialog_content = "아이테르가 자기방어를 위해 만든 장치의 「전범위 살상 명령」이\n오로리안인 바이스를 조준한 지금 상황으로 봤을 때...",
  ui_story_1011_10111002_75_dialog_content = "「아이테르가 아닌」 오로리안에게 「의식 소실」 공격을 가하는 건...",
  ui_story_1011_10111002_76_dialog_content = "어쩌면 고대의 아이테르에겐 아주 <color=#FFB400>당연한</color> 일이었던 건 아닐까?",
  ui_story_1011_10111002_77_dialog_content = "마치 내가 어렸을 때 이 「달의 고치」를 다루는 방법을 배울 때...",
  ui_story_1011_10111002_78_dialog_content = "왜 이 창을 암귀한테 겨누어야 하냐고 선생님이 특별히 설명하지 않았던 것처럼 말이야.",
  ui_story_1011_10111002_79_dialog_content = "그건 애초에 설명 같은 게 필요 없는 당연한 일이니까.",
  ui_story_1011_10111002_80_dialog_content = "?!",
  ui_story_1011_10111002_81_dialog_content = "지금 그 말... 이해할 수도 없고 받아들이기도 힘들지만...",
  ui_story_1011_10111002_82_dialog_content = "그 말도 일리가 있다고 생각해. 나조차 그 가능성을 부정할 순 없어...",
  ui_story_1011_10111002_83_dialog_content = "설마... 고대의 아이테르는 정말로 오로리안을 <color=#FFB400>적</color>이나 다름없는 존재로 여겼던 걸까?",
  ui_story_1011_10111101_1_dialog_content = "모르겠어. 정말 점점 더 모르겠어.",
  ui_story_1011_10111101_2_dialog_content = "우린 지금 분명히 헤븐즈 밸리에 있어.\n그리고 여기서 가장 눈에 띄는... 어디서나 보이는 하얀 탑 지하에 있어.",
  ui_story_1011_10111101_3_dialog_content = "그런데 정작 난 눈앞에서 일어나는 일이 도저히 이해가 안 돼.",
  ui_story_1011_10111101_4_dialog_content = "모르겠어. 여긴 대체 어떤 곳이었는지, 도대체 어떤 사람들이 여기서 살고 있었는지...",
  ui_story_1011_10111101_5_dialog_content = "저들은 무엇 때문에 멸망했고, 이런 잔해를 지하에 남겨둔 건지.",
  ui_story_1011_10111101_6_dialog_content = "어쩌면 우리가 방금 겪은 것들이 문제를 설명하고 있을지도 몰라.",
  ui_story_1011_10111101_7_dialog_content = "전투의 흔적과 함께 남은 건 암귀뿐이야.",
  ui_story_1011_10111101_8_dialog_content = "......",
  ui_story_1011_10111101_9_dialog_content = "17년 전 헤븐즈 밸리에 있었던 일처럼 말이야?",
  ui_story_1011_10111101_10_dialog_content = "여긴 심지어 더 고요해. 마지막 탄식조차 밖으로 새어 나가지 않았어.",
  ui_story_1011_10111101_11_dialog_content = "저들은 소리 없이 묵묵히 이 구석에서 죽었던 거야.",
  ui_story_1011_10111101_12_dialog_content = "어쩌면 우린 100년, 아니 1000년만에 처음으로 여기 들어온 사람일지도 몰라.",
  ui_story_1011_10111101_13_dialog_content = "1000년 기간 범위의 기록을 검색합니다──",
  ui_story_1011_10111101_14_dialog_content = "기타 외부인은 발견되지 않았습니다. 당신의 판단은 정확합니다.",
  ui_story_1011_10111101_15_dialog_content = "너한테 안 물어봤어.",
  ui_story_1011_10111101_16_dialog_content = "에이드 브레인의 임무는 아이테르의 모든 문제를 해결하는 것입니다.",
  ui_story_1011_10111101_17_dialog_content = "네가 중요한 질문에 조금이라도 더 도움이 됐으면 좋았겠지...",
  ui_story_1011_10111101_18_dialog_content = "넌 바이스를 어떻게 치료할지도, 스카이워커를 어떻게 고치는지도 전혀 모르잖아.",
  ui_story_1011_10111101_19_dialog_content = "의사결정 나무의 메서드 집합에서 검색 중입니다──",
  ui_story_1011_10111101_20_dialog_content = "「바이스 치료」 또는 「스카이워커를 고치는」 방법은 발견되지 않았습니다.",
  ui_story_1011_10111101_21_dialog_content = "당신의 판단은 정확합니다. 에이드 브레인은 전혀 모릅니다.",
  ui_story_1011_10111101_22_dialog_content = "그런 것까지 인정하는 거냐고!",
  ui_story_1011_10111101_23_dialog_content = "에이드 브레인은 「도움이 되지 않는다」라는 피드백을 받았습니다.\n죄송합니다. 앞으로 최선을 다해 개선하겠습니다.",
  ui_story_1011_10111101_24_dialog_content = "널 탓할 생각은 없어...",
  ui_story_1011_10111101_25_dialog_content = "이 폐허의 부서진 모습을 보면 네 머리가 망가져 있는 것도 당연하니까.",
  ui_story_1011_10111101_26_dialog_content = "아까 그 질문들의 답은 우리가 알아서 찾을 거야.",
  ui_story_1011_10111101_27_dialog_content = "가자, 카렌. 더 내려가는 거야.",
  ui_story_1011_10111101_28_dialog_content = "우린 다른 선택지가 없어.",
  ui_story_1011_10111101_29_dialog_content = "응, 바이스는 내가 업을게.",
  ui_story_1011_10111101_30_dialog_content = "(우리가 반드시 널 구해줄게.)",
  ui_story_1011_10111101_31_dialog_content = "(그러니까 꼭 버텨야 해, 꼭.)",
  ui_story_1011_10111101_32_dialog_content = "<color=#e8d9bb>뚜벅... 뚜벅... 뚜벅...</color>",
  ui_story_1011_10111101_33_dialog_content = "이번 길에는 아무것도 없어.",
  ui_story_1011_10111101_34_dialog_content = "암귀도 없고, 떨어져 있는 물건도 없어.",
  ui_story_1011_10111101_35_dialog_content = "지하에 들어온 뒤로 제일 「깨끗한」 곳이네.",
  ui_story_1011_10111101_36_dialog_content = "그러게. 너무 깨끗해서 오히려 이상할 정도야.",
  ui_story_1011_10111101_37_dialog_content = "꼭 지금까지 본 모든 일들이 여기까진 영향을 주지 않은 것처럼...",
  ui_story_1011_10111101_38_dialog_content = "과거의 생활이나 전쟁, 전부 단절된 바깥의 일인 것처럼 말이야.",
  ui_story_1011_10111101_39_dialog_content = "인간의 온기가 느껴지지 않는다는 거지?",
  ui_story_1011_10111101_40_dialog_content = "맞아.",
  ui_story_1011_10111101_41_dialog_content = "여명 아카데미의 선생님도 나한테 말씀해주신 적 있어.",
  ui_story_1011_10111101_42_dialog_content = "「인간의 온도는 세계의 가장 바깥을 감싸는 것이다.」",
  ui_story_1011_10111101_43_dialog_content = "「깊은 곳으로 파고들수록, 인간의 온도는 희미해진다.」",
  ui_story_1011_10111101_44_dialog_content = "지금 우리 처지랑 비슷한 것 같지 않아?",
  ui_story_1011_10111101_45_dialog_content = "우리도 점점 더 깊은 곳으로 들어가고 있어.",
  ui_story_1011_10111101_46_dialog_content = "그 선생님도 네가 실제로 「깊은 지하」에 들어갈 때\n그 말을 써먹을 거라고 생각하진 않았을 것 같은데.",
  ui_story_1011_10111101_47_dialog_content = "그래도 교실에서 들었을 때보다 훨씬 더 잘 이해가 되는걸.\n아마 선생님도 기뻐하실 거야.",
  ui_story_1011_10111101_48_dialog_content = "아이테르가 제한 구역에 진입한 것을 감지했습니다. 신분 인증을 시작합니다.",
  ui_story_1011_10111101_49_dialog_content = "삐── 삐── 삐──",
  ui_story_1011_10111101_50_dialog_content = "어? 이 녀석 갑자기 시끄러워졌는데?",
  ui_story_1011_10111101_51_dialog_content = "삐── 삐── 삐──",
  ui_story_1011_10111101_52_dialog_content = "인증에 실패했습니다. 알립니다. 즉시 돌아가십시오. 알립니다. 즉시 돌아가십시오.",
  ui_story_1011_10111101_53_dialog_content = "돌아가라고? 웃기지 마. 다시 가서 암귀랑 싸우라는 소리야?",
  ui_story_1011_10111101_54_dialog_content = "그리고 왜 갑자기 그러는 건데? 이유나 좀 말해줘!",
  ui_story_1011_10111101_55_dialog_content = "PlayerName, 앞을 봐.",
  ui_story_1011_10111101_56_dialog_content = "우와... 이건... <color=#FFB400>돌로 만든 문</color>인가?",
  ui_story_1011_10111101_57_dialog_content = "그런 것 같아.",
  ui_story_1011_10111101_58_dialog_content = "너무 크잖아. 문이라기보다는 성벽 같아.",
  ui_story_1011_10111101_59_dialog_content = "대체 이 문을 열려면 얼마나 강한 힘이 필요한 거지?",
  ui_story_1011_10111101_60_dialog_content = "제일 무거운 공성추로도 힘들 것 같아.",
  ui_story_1011_10111101_61_dialog_content = "이렇게 거대한 문을 만들고 움직일 수 있는 세력은 지금 이 세계에는 없을 거라 생각해.",
  ui_story_1011_10111101_62_dialog_content = "그러게.",
  ui_story_1011_10111101_63_dialog_content = "이런 엄청난 기술을 가지고도 끝내 멸망을 피하지 못한 거야?",
  ui_story_1011_10111101_64_dialog_content = "알립니다. 즉시 돌아가십시오. 알립니다. 즉시 돌아가십시오.",
  ui_story_1011_10111101_65_dialog_content = "당신의 신분은 허가되지 않았습니다.\n<color=#FFB400>「핵심 중추 구역」</color> 진입이 금지되어 있습니다.",
  ui_story_1011_10111101_66_dialog_content = "신분 허가?",
  ui_story_1011_10111101_67_dialog_content = "문은 허가받은 자에게만 열립니다.",
  ui_story_1011_10111101_68_dialog_content = "허가를 받지 못한 자는 <color=#FFB400>「명령」</color>에 의해 거부됩니다.",
  ui_story_1011_10111101_69_dialog_content = "이 문이 열리는 모습을 꼭 한 번 봤으면 좋겠는데. 분명히 엄청난 장관일 거야.",
  ui_story_1011_10111101_70_dialog_content = "나도 같은 생각이야. 에이드 브레인, 우리 좀 도와줘.",
  ui_story_1011_10111101_71_dialog_content = "네가 말하는 허가라는 건 어떻게 하면 얻을 수 있어?",
  ui_story_1011_10111101_72_dialog_content = "죄송합니다. 에이드 브레인은 도움을 드릴 수 없습니다.",
  ui_story_1011_10111101_73_dialog_content = "뭐? 아까는 「아이테르의 모든 문제를 해결한다」고 하지 않았어?",
  ui_story_1011_10111101_74_dialog_content = "당신의 말을 거절하는 것이 「명령」이기 때문입니다.\n이는 최초이자 최고의 지시입니다.",
  ui_story_1011_10111101_75_dialog_content = "아이테르는 「명령」을 어겨서는 안 됩니다.\n에이드 브레인도 「명령」을 어겨서는 안 됩니다.",
  ui_story_1011_10111101_76_dialog_content = "「명령」이라니...",
  ui_story_1011_10111101_77_dialog_content = "자격이 없는 사람을 막겠다고 산처럼 커다란 암석을 문으로 만든 건가.",
  ui_story_1011_10111101_78_dialog_content = "그 「명령」이란 건 녀석에게 꽤나 중요한 의미가 있는 모양이야.",
  ui_story_1011_10111101_79_dialog_content = "그러게. 이 문은 사람을 막아서는 역할로는 정말 제격인 것 같네.",
  ui_story_1011_10111101_80_dialog_content = "하지만...",
  ui_story_1011_10111101_81_dialog_content = "여기도 한때는 찬란한 시기가 있었을 거야.",
  ui_story_1011_10111101_82_dialog_content = "그런데 지금 있는 건 그나마 이런 위엄뿐이야.",
  ui_story_1011_10111101_83_dialog_content = "음, 저기 침식돼서 생긴 틈이라면 지나갈 수 있을 것 같아.",
  ui_story_1011_10111101_84_dialog_content = "이 돌사자는 이미 이빨이 다 떨어져 버렸지만, 고양이로 전락할 생각은 없는 모양이야.",
  ui_story_1011_10111101_85_dialog_content = "이렇게 초라한 모습으로 외부인을 잘난 척 거절하다니, 왠지 조금 애잔하잖아.",
  ui_story_1011_10111101_86_dialog_content = "알립니다. 즉시 돌아가십시오. 알립니다. 즉시 돌아가십시오.",
  ui_story_1011_10111101_87_dialog_content = "가자, 들어가서 찾아보는 거야.",
  ui_story_1011_10111101_88_dialog_content = "이 문 뒤에 대체 어떤 비밀이 숨어 있는지 보자고.",
  ui_story_1011_10111101_89_dialog_content = "그래. 아직 찾아야 할 게 너무 많아. 다른 선택의 여지는 없어.",
  ui_story_1011_10111101_90_dialog_content = "당신의 신분은 허가되지 않았습니다. 「핵심 구역」 진입이 금지되어 있습니다.",
  ui_story_1011_10111101_91_dialog_content = "에이드 브레인, 됐어.",
  ui_story_1011_10111101_92_dialog_content = "「명령」은 당신이 문을 들어가는 것을 거부합니다.",
  ui_story_1011_10111101_93_dialog_content = "아이테르는 「명령」을 어겨서는 안 됩니다.",
  ui_story_1011_10111101_94_dialog_content = "(어두운 틈 속으로 들어가서야 알게 된 것은 이 돌문이 보기보다 훨씬 두껍다는 것이었다.)",
  ui_story_1011_10111101_95_dialog_content = "(에이드 브레인의 목소리도 점차 들리지 않게 되었다.\n이 거석에 막혀버린 건지, 아니면 알아서 멈춘 건지는 모르겠다.)",
  ui_story_1011_10111101_96_dialog_content = "(나는 모든 집중력을 사용해서 상상했다. 이 문 너머에는 무엇이 기다리고 있을까.)",
  ui_story_1011_10111101_97_dialog_content = "(아무리 상상해도 실제로 보았을 땐 결국 놀랄 것이라는 사실은 알고 있다.)",
  ui_story_1011_10111101_98_dialog_content = "(또한 내가 앞으로 보게 될 것이 무엇인지도 알고 있다.)",
  ui_story_1011_10111101_99_dialog_content = "(앞으로 보게 될 것은 하나의 문명이다.)",
  ui_story_1011_10111101_100_dialog_content = "이건 뭐지?",
  ui_story_1011_10111101_101_dialog_content = "아직도 움직이고 있잖아...",
  ui_story_1011_10111101_102_dialog_content = "에이드 브레인, 들려?",
  ui_story_1011_10111101_103_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_1011_10111101_104_dialog_content = "여긴 녀석이 우리의 진입을 막으려고 했던 장소야.\n아마 더는 우리 질문에 대답해 주지 않을 거야.",
  ui_story_1011_10111101_105_dialog_content = "이 장치의 용도는 우리가 직접 알아내는 수밖에 없어.",
  ui_story_1011_10111101_106_dialog_content = "공중에 떠 있는 고리 모양의 석판...",
  ui_story_1011_10111101_107_dialog_content = "이런 게 대체 무슨 효과가 있는 거지? 전혀 모르겠어.",
  ui_story_1011_10111101_108_dialog_content = "비슷한 걸 본 적 있어?",
  ui_story_1011_10111101_109_dialog_content = "아니.",
  ui_story_1011_10111101_110_dialog_content = "지금의 건물만이 아니라, 고대 유적에서도 비슷한 게 발굴된 적은 없었어.",
  ui_story_1011_10111101_111_dialog_content = "뭐, 이상할 건 없어. 여긴 애초에 다른 유적과는 다르니까.\n여긴 너희 아이테르의 유적이잖아.",
  ui_story_1011_10111101_112_dialog_content = "어쩌면 아이테르만의 사용법이 있을지도 몰라.",
  ui_story_1011_10111101_113_dialog_content = "아이테르만의 사용법?",
  ui_story_1011_10111101_114_dialog_content = "너희한테 보이는 세계는 오로리안이 보는 세계와는 다르잖아.",
  ui_story_1011_10111101_115_dialog_content = "만약 저게 아이테르만을 위해서 만들어진 거라면,\n그 기능 역시 일반적인 방법으론 볼 수 없는 곳에 숨겨 두었을 거야.",
  ui_story_1011_10111101_116_dialog_content = "그러니까 감응이랑 관계가 있을 것 같다는 거지?",
  ui_story_1011_10111101_117_dialog_content = "추측일 뿐이지만, 시도해 볼 필요는 있다고 생각해.",
  ui_story_1011_10111101_118_dialog_content = "응, 그래.",
  ui_story_1011_10111101_119_option_content = "(강제 감응!)",
  ui_story_1011_10111101_120_dialog_content = "<color=#e8d9bb>위이잉──!</color>",
  ui_story_1011_10111101_121_dialog_content = "어라? 이건...",
  ui_story_1011_10111101_122_dialog_content = "어서 오십시오, 신생아.",
  ui_story_1011_10111101_123_dialog_content = "<color=#FFB400>서클 시스템</color>과의 첫 액세스가 시작되었습니다.",
  ui_story_1011_10111101_124_dialog_content = "서클 시스템? 아까 그 장치 말하는 거야?",
  ui_story_1011_10111101_125_dialog_content = "난 지금 어디 있는 거야? 나한테 말하고 있는 건 또 누군데?",
  ui_story_1011_10111101_126_dialog_content = "서클 시스템은 아이테르 종족 전체의 기억입니다.",
  ui_story_1011_10111101_127_dialog_content = "당신은 이곳에서 세계를 인식하게 됩니다.",
  ui_story_1011_10111101_128_dialog_content = "잠깐만, 누가 말을 하고 있다는 느낌은 전혀 없어.",
  ui_story_1011_10111101_129_dialog_content = "이 정보들은 소리나 언어 같은 절차를 뛰어넘어\n내 머릿속으로 직접 흘러들어 오고 있어.",
  ui_story_1011_10111101_130_dialog_content = "우선은 지금 당신이 있는 장소를 인식합시다.",
  ui_story_1011_10111101_131_dialog_content = "아이테르라는 종족은 이곳에서 탄생했고,\n모든 아이테르도 이 땅에서 태어납니다.",
  ui_story_1011_10111101_132_dialog_content = "어디를 가든 이곳은 영원한 아이테르의 고향입니다.",
  ui_story_1011_10111101_133_dialog_content = "이곳은 <color=#FFB400>「탑의 도시」</color>라고 합니다.",
  ui_story_1011_10111101_134_dialog_content = "「탑의 도시」...",
  ui_story_1011_10111101_135_dialog_content = "아이테르의 고향은 헤븐즈 밸리 아니었어?",
  ui_story_1011_10111101_136_dialog_content = "이 도시는 수많은 높은 탑들로 이루어져 있습니다.",
  ui_story_1011_10111101_137_dialog_content = "당신이 지금 있는 곳은 도시의 중심, 최초이자 최고의 탑──",
  ui_story_1011_10111101_138_dialog_content = "「귀환의 탑」입니다.",
  ui_story_1011_10111101_139_dialog_content = "모든 아이테르는 성인이 될 때까지 이곳에서 교육을 받습니다.",
  ui_story_1011_10111101_140_dialog_content = "그 후, 바깥세상을 접할 기회를 얻고, 아득히 먼 구석까지 여행을 떠납니다.",
  ui_story_1011_10111101_141_dialog_content = "하지만 고향은... 영원히... 탑의 도시에 우뚝 솟아 있을 것이며...",
  ui_story_1011_10111101_142_dialog_content = "종점에서... 모두의 「귀환」을... 기다릴 것입니다...",
  ui_story_1011_10111101_143_dialog_content = "!!!",
  ui_story_1011_10111101_144_dialog_content = "끄...끝난 건가?",
  ui_story_1011_10111101_145_dialog_content = "어때? 뭐가 보였어?",
  ui_story_1011_10111101_146_dialog_content = "목소리가 들렸어. 아니, 목소리가 아니라 정보였어.",
  ui_story_1011_10111101_147_dialog_content = "정보?",
  ui_story_1011_10111101_148_dialog_content = "응. 의식으로 이 장치랑 접촉한 순간부터 그 정보들이\n내 머릿속으로 직접 흘러들어 왔어.",
  ui_story_1011_10111101_149_dialog_content = "마치... 날 교육시키려는 것 같았어.",
  ui_story_1011_10111101_150_dialog_content = "그 정보는 이 장치가 「서클 시스템」이라고 했고,\n아이테르 전체의 기억이라고 했어.",
  ui_story_1011_10111101_151_dialog_content = "그리고 여긴 아이테르의 고향이고, 「탑의 도시」라고 했어.",
  ui_story_1011_10111101_152_dialog_content = "우리가 있는 「귀환의 탑」은 그중에서도 가장 높은 탑이야.",
  ui_story_1011_10111101_153_dialog_content = "헤븐즈 밸리에 대해선 아무 말도 안 했어?",
  ui_story_1011_10111101_154_dialog_content = "응. 나도 그 점이 이상했어.",
  ui_story_1011_10111101_155_dialog_content = "설마 이름이 바뀌었나?",
  ui_story_1011_10111101_156_dialog_content = "그럴 수도 있어. 이 유적은 연대가 꽤 오래됐으니까.\n문자나 말이 바뀌었을 가능성도 있겠지.",
  ui_story_1011_10111101_157_dialog_content = "그럼 이 「서클 시스템」이란 것도 정보를 저장하는 모종의 장치인 건가?",
  ui_story_1011_10111101_158_dialog_content = "응, 아마 그런 것 같아.",
  ui_story_1011_10111101_159_dialog_content = "아이테르가 감응 능력으로 접촉하면 저 안에서 정보를 얻을 수 있는 거야.",
  ui_story_1011_10111101_160_dialog_content = "근데 어째서 그런 식으로 만든 거지?",
  ui_story_1011_10111101_161_dialog_content = "이 기괴한 고리 모양의 석판에 무슨 의미가 있는 건지 모르겠어.",
  ui_story_1011_10111101_162_dialog_content = "게다가 이 크기, 정보 저장 장치치고는 너무 크잖아.",
  ui_story_1011_10111101_163_dialog_content = "이런 공간에 단순히 책만 가득 채운다고 해도,\n그 안에 담기는 정보량은 무서울 정도의 규모가 될 거야.",
  ui_story_1011_10111101_164_dialog_content = "책을 가득 채운다라...",
  ui_story_1011_10111101_165_dialog_content = "아, 카렌. 우리가 봤던 그 앵무조개 기억나?",
  ui_story_1011_10111101_166_dialog_content = "응, 기억해.",
  ui_story_1011_10111101_167_dialog_content = "바이스가 말했잖아. 앵무조개 형태의 역할은 고대 문명의 수학적 이념을 나타낸다고.",
  ui_story_1011_10111101_168_dialog_content = "그들은 자연을 숭배해. 게다가 자연은 수학적 언어 속에서 「연속성」을 드러내.",
  ui_story_1011_10111101_169_dialog_content = "그 이념을 아마 여기에도 응용한 게 아닐까?",
  ui_story_1011_10111101_170_dialog_content = "음... 그러니까 고리 형태도 「연속성」의 상징이란 얘기야?",
  ui_story_1011_10111101_171_dialog_content = "맞아. 네가 아까 말한 「책을 가득 채운다」는 얘길 듣고 생각했어.",
  ui_story_1011_10111101_172_dialog_content = "만약 우리가 정보를 저장하려고 한다면, 분명히 책을 가지런히 쌓을 거야.\n그 사이엔 되도록 틈이 없도록 만들겠지.",
  ui_story_1011_10111101_173_dialog_content = "그러면 마지막엔 네모난 책 무더기가 생길 거야.",
  ui_story_1011_10111101_174_dialog_content = "근데 사각형은 모서리가 많고, 선도 연속성이 없어.",
  ui_story_1011_10111101_175_dialog_content = "그에 비해 고리에는 모서리가 없어.",
  ui_story_1011_10111101_176_dialog_content = "그럼 고리 모양의 형태로 공간을 계획한다면\n그 보존 방식은 「연속성」의 사상에도 부합하겠지.",
  ui_story_1011_10111101_177_dialog_content = "응! 내 말도 그런 뜻이야!",
  ui_story_1011_10111101_178_dialog_content = "...말은 쉽게 했지만, 역시 잘 이해가 안 가.",
  ui_story_1011_10111101_179_dialog_content = "만약 정말 그런 거라면, 이 고대 문명은 우리의 상상을\n아득히 뛰어넘을 정도로 발전했을지도 몰라.",
  ui_story_1011_10111101_180_dialog_content = "그 과학 기술을 지탱하는 기본 이념조차 우리와는 완전히 달라.",
  ui_story_1011_10111101_181_dialog_content = "아마 저들의 눈에 우리의 수학은 원시인이 나뭇가지를\n휘두르는 것처럼 보잘것없어 보일 수도 있어.",
  ui_story_1011_10111101_182_dialog_content = "그렇게까지 심할까...?",
  ui_story_1011_10111101_183_dialog_content = "다시 접촉을 시도해 봐, PlayerName.",
  ui_story_1011_10111101_184_dialog_content = "저들이 이렇게 뛰어난 문명을 가지고 있었다면,\n대체 이 방대한 공간에 얼마나 많은 정보를 저장했을까?",
  ui_story_1011_10111101_185_dialog_content = "어쩌면 세상 모든 문제의 답이 이 안에 있을지도 몰라.",
  ui_story_1011_10111101_186_dialog_content = "응, 다시 시도해볼게!",
  ui_story_1011_10111101_187_option_content = "(강제 감응!)",
  ui_story_1011_10111101_188_dialog_content = "<color=#e8d9bb>위이잉──!</color>",
  ui_story_1011_10111101_189_dialog_content = "또 여기잖아.",
  ui_story_1011_10111101_190_dialog_content = "여기 정보가 저장되어 있다면... 뭔가 내 생각대로 열람할 방법이 있을 거야.",
  ui_story_1011_10111101_191_dialog_content = "근데 여긴 책장처럼 한눈에 알아볼 수 있는 물건도 없어.",
  ui_story_1011_10111101_192_dialog_content = "아, 그래! 의식이야! 의식을 가지고 움직이면 될 거야.",
  ui_story_1011_10111101_193_dialog_content = "?!",
  ui_story_1011_10111101_194_dialog_content = "공중에 떠 있는 석판이 회전하기 시작했어.",
  ui_story_1011_10111101_195_dialog_content = "PlayerName, 뭘 한 거야...?",
  ui_story_1011_10111101_196_dialog_content = "으, 으앗! 으으으...",
  ui_story_1011_10111101_197_dialog_content = "머리가 어지러워. 움직이고 있는 건가?",
  ui_story_1011_10111101_198_dialog_content = "멈춰, 어떻게든 멈춰야 해.",
  ui_story_1011_10111101_199_dialog_content = "<color=#e8d9bb>위이잉──!</color>",
  ui_story_1011_10111101_200_dialog_content = "휴, 끝났나?",
  ui_story_1011_10111101_201_dialog_content = "콜로서스.",
  ui_story_1011_10111101_202_dialog_content = "으엑?!",
  ui_story_1011_10111101_203_dialog_content = "콜로서스는 루미나로 구동하는 대형 다기능 시설입니다.",
  ui_story_1011_10111101_204_dialog_content = "그것은 아이테르의 일생에서 가장 신뢰할 수 있는 것입니다.",
  ui_story_1011_10111101_205_dialog_content = "아이테르의 의식은 강하지만, 그 신체는 약소합니다.\n의식의 강함은 하늘의 은총이며, 신체의 약소함은 그에 따른 대가입니다.",
  ui_story_1011_10111101_206_dialog_content = "콜로서스는 아이테르의 결점을 보완합니다.\n이는 일종의 연장된 신체로, 아이테르의 행위가 그 의식을 따라갈 수 있도록 합니다.",
  ui_story_1011_10111101_207_dialog_content = "따라서 아이테르가 가장 먼저 배워야 할 것은 바로 콜로서스를 조종하는 법입니다.",
  ui_story_1011_10111101_208_dialog_content = "아까랑 똑같이 선생님 같은 말투네.",
  ui_story_1011_10111101_209_dialog_content = "이번엔 나한테 콜로서스 조종을 가르치려는 건가?",
  ui_story_1011_10111101_210_dialog_content = "콜로서스에는 아이테르가 조종할 수 있도록 조종실이 마련되어 있습니다.",
  ui_story_1011_10111101_211_dialog_content = "아이테르는 그곳에서 자신과 콜로서스의 의식을 연결합니다.",
  ui_story_1011_10111101_212_dialog_content = "충분한 강도의 공명이 이루어지면 콜로서스가 기동됩니다.",
  ui_story_1011_10111101_213_dialog_content = "맞아, 그때의 나랑 똑같아.",
  ui_story_1011_10111101_214_dialog_content = "콜로서스에는 아이테르가 다양한 행위를 실현하도록 돕는 각종 모듈을 탑재할 수 있습니다.",
  ui_story_1011_10111101_215_dialog_content = "콜로서스의 도움으로 아이테르는 그 어떤 생물보다 강해질 수 있습니다.",
  ui_story_1011_10111101_216_dialog_content = "그러나 이러한 힘의 소유자이자 콜로서스의 조종자로서, 부디 항상 명심하십시오.",
  ui_story_1011_10111101_217_dialog_content = "당신들이 태어났을 때 새겨진 「명령」을 결코 잊지 마십시오.",
  ui_story_1011_10111101_218_dialog_content = "아이테르와 콜로서스는 영원한 전쟁의 기계입니다.",
  ui_story_1011_10111101_219_dialog_content = "전쟁의 기계?!",
  ui_story_1011_10111101_220_dialog_content = "그럴 리가 없잖아... 나랑 스카이워커는 공격 능력조차 없는데...",
  ui_story_1011_10111101_221_dialog_content = "이 전쟁 기계에는 콜로서스의 신체와 아이테르의 지혜가 갖추어져 있습니다.",
  ui_story_1011_10111101_222_dialog_content = "적을 찌르는 무기는 오래전부터 「명령」에 따라...",
  ui_story_1011_10111101_223_dialog_content = "당신이 가동하기를 기다리고 있었습니다.",
  ui_story_1011_10111101_224_dialog_content = "뭐라고?!",
  ui_story_1011_10111101_225_dialog_content = "이것들은... 암귀잖아?!",
  ui_story_1011_10111101_226_dialog_content = "이어서는 전쟁을 학습하겠습니다. 많은 시간을 사용해서 학습할 것입니다.",
  ui_story_1011_10111101_227_dialog_content = "이제 자료상에서 전장을 보게 될 것입니다.",
  ui_story_1011_10111101_228_dialog_content = "하나의 목숨이 전장에서 얼마나 보잘것없는지,\n힘의 차이가 얼마나 순식간에 세계의 저울을 파괴하는지 보십시오.",
  ui_story_1011_10111101_229_dialog_content = "다행히 전장은 아이테르가 향할 곳이 아닙니다.",
  ui_story_1011_10111101_230_dialog_content = "이곳에는 전장에서 싸우기 위해 태어난 병사들이 있습니다.\n저들이 아는 것은 오직 어떻게 적과 싸우고 죽이는지뿐입니다.",
  ui_story_1011_10111101_231_dialog_content = "이 추악한 전사들은 기꺼이 전장에 나갈 것입니다.",
  ui_story_1011_10111101_232_dialog_content = "그리고 당신들이 해야 할 일은 이 세계에──",
  ui_story_1011_10111101_233_dialog_content = "전쟁을 불러오는 것뿐입니다.",
  ui_story_1011_10111201_1_dialog_content = "하아... 하아...",
  ui_story_1011_10111201_2_dialog_content = "PlayerName, 왜 그래?",
  ui_story_1011_10111201_3_dialog_content = "땀을 엄청 흘렸잖아.",
  ui_story_1011_10111201_4_dialog_content = "하아, 하아... 난...",
  ui_story_1011_10111201_5_dialog_content = "모르겠어...",
  ui_story_1011_10111201_6_dialog_content = "어째서 저런 게 보인 건지.",
  ui_story_1011_10111201_7_dialog_content = "그게 대체 무슨 뜻인지, 도저히 모르겠어...",
  ui_story_1011_10111201_8_dialog_content = "대체 뭘 본 거야?",
  ui_story_1011_10111201_9_dialog_content = "코, 콜로서스가 보였어.",
  ui_story_1011_10111201_10_dialog_content = "서클 시스템은 나한테 콜로서스를 어떻게 조종하는지 가르쳐 주려고 했어...",
  ui_story_1011_10111201_11_dialog_content = "그리고...",
  ui_story_1011_10111201_12_dialog_content = "콜로서스 안의 암귀를 어떻게 조종하는지도...",
  ui_story_1011_10111201_13_dialog_content = "암귀를 조종한다고?!",
  ui_story_1011_10111201_13X1_dialog_content = "응... 그리고 아이테르와 콜로서스가... 「전쟁의 기계」라고 말했어.",
  ui_story_1011_10111201_14_dialog_content = "대체 왜 이런...",
  ui_story_1011_10111201_15_dialog_content = "카렌, 넌 어떻게 생각해...?",
  ui_story_1011_10111201_16_dialog_content = "나도 놀랍다고 생각해. 하지만... 그 정보만 가지고는 판단할 수 없어.",
  ui_story_1011_10111201_17_dialog_content = "여긴 고대의 유적이야. 우리가 사는 지금과는 아득히 먼 시대잖아.",
  ui_story_1011_10111201_18_dialog_content = "우린 당시에 무슨 일이 있었는지도 알 수 없고, 정보의 신빙성도 장담할 수 없어.",
  ui_story_1011_10111201_19_dialog_content = "그런 걸까?",
  ui_story_1011_10111201_20_dialog_content = "하지만 만약, 아이테르가 한때 정말로 암귀를 조종했다면...",
  ui_story_1011_10111201_21_dialog_content = "내 입장은 대체 어떻게 되는 거지...?",
  ui_story_1011_10111201_22_dialog_content = "설마... 나도 슈모르처럼 되는 거야...?",
  ui_story_1011_10111201_23_dialog_content = "네가 말한 정보는 생각해 볼 만한 문제지만, 거기에 얽매여선 안 돼.",
  ui_story_1011_10111201_24_dialog_content = "네가 실제로 경험한 것이야말로 진실이니까. 안 그래?",
  ui_story_1011_10111201_25_dialog_content = "너랑 스카이워커호가 함께 싸워온 건 진실이야.",
  ui_story_1011_10111201_26_dialog_content = "너와 함께 싸워온 동료들이 있다는 것도 진실이야.",
  ui_story_1011_10111201_27_dialog_content = "자기 입장에 고민할 필요는 없어.",
  ui_story_1011_10111201_28_dialog_content = "나도, 바이스도, 그리고 여기에 없는 친구들 곁에──",
  ui_story_1011_10111201_29_dialog_content = "네가 설 자리는 언제든지 있을 테니까.",
  ui_story_1011_10111201_30_dialog_content = "응... 훌쩍...",
  ui_story_1011_10111201_31_dialog_content = "카렌... 고마워...",
  ui_story_1011_10111201_32_dialog_content = "그, 그렇게까지 반응할 필요는 없어.",
  ui_story_1011_10111201_33_dialog_content = "네 말이 맞아. 너희야말로 진실이야.",
  ui_story_1011_10111201_34_dialog_content = "그리고 지금 가장 중요한 건 바이스를 회복시킬 방법을 찾는 거야.",
  ui_story_1011_10111201_35_dialog_content = "다시 시도해 볼게.",
  ui_story_1011_10111201_36_dialog_content = "조금 쉬는 건 어때?",
  ui_story_1011_10111201_37_dialog_content = "아까 서클 시스템이랑 접촉하면서 힘을 많이 썼을 거잖아.",
  ui_story_1011_10111201_38_dialog_content = "괜찮아.",
  ui_story_1011_10111201_39_dialog_content = "왠지 사용법을 알아낸 것 같거든.",
  ui_story_1011_10111201_40_option_content = "(강제 감응!)",
  ui_story_1011_10111201_41_dialog_content = "<color=#e8d9bb>위이잉──!</color>",
  ui_story_1011_10111201_42_dialog_content = "아까 내 의식이 이 안에서 이동하는 걸 느꼈어.",
  ui_story_1011_10111201_43_dialog_content = "아무래도 여기 저장된 정보는 일종의 공간을 이루고 있는 것 같아.",
  ui_story_1011_10111201_44_dialog_content = "그리고 내 사고에 따라 공간 속에서 이동할 수 있는 거겠지.",
  ui_story_1011_10111201_45_dialog_content = "아까는 첫 번째 사고의 관성 때문에 아이테르 교육 프로그램으로 계속해서 들어가 버렸어.",
  ui_story_1011_10111201_46_dialog_content = "그럼 이번엔 내 사고의 방향을 바꾸면 될 거야.",
  ui_story_1011_10111201_47_dialog_content = "바이스의 치료에 대한 일을 상상하고...",
  ui_story_1011_10111201_48_dialog_content = "바이스의 몸에 일어난 「의식 소실」이라는 특수한 상태를 떠올리면...",
  ui_story_1011_10111201_49_dialog_content = "<color=#e8d9bb>위이잉──!</color>",
  ui_story_1011_10111201_50_dialog_content = "서, 성공했나?",
  ui_story_1011_10111201_51_dialog_content = "실험 데이터, 코드...",
  ui_story_1011_10111201_52_dialog_content = "권한을... ■■■... 에서 「공개」로 변경, 모든... ■■■... 에게 제공합니다.",
  ui_story_1011_10111201_53_dialog_content = "변경자, 프란츠.",
  ui_story_1011_10111201_54_dialog_content = "프란츠, 또 그 이름이야.",
  ui_story_1011_10111201_55_dialog_content = "이 정보는 손상이 심한 것 같네. 뭔가 단서가 남아 있다면 좋을 텐데.",
  ui_story_1011_10111201_56_dialog_content = "실험체... ■■■, 「의식 소실」에서 깨어나지 못함, 신체... ■■■, 활력 징후 감퇴.",
  ui_story_1011_10111201_57_dialog_content = "실험체... ■■■, 「의식 소실」에서 깨어나지 못함, ■■■ 현상 발생, 활력...",
  ui_story_1011_10111201_58_dialog_content = "실험체... ■■■... ■■■... 에서 깨어나지 못함, 실험 과정에서...",
  ui_story_1011_10111201_59_dialog_content = "이게 대체 무슨 실험이지?",
  ui_story_1011_10111201_60_dialog_content = "이 실험 데이터들... 왠지 불안하잖아...",
  ui_story_1011_10111201_61_dialog_content = "실험체... ■■■... ■■■... 에서 깨어나지 못함, 기타 이상 없음.",
  ui_story_1011_10111201_62_dialog_content = "실험체... ■■■... 「의식 소실」에서 깨어나지 못함, 기타...",
  ui_story_1011_10111201_63_dialog_content = "실험체... ■■■... ■■■...",
  ui_story_1011_10111201_64_dialog_content = "왜 전부 다 이런...",
  ui_story_1011_10111201_65_dialog_content = "실험...",
  ui_story_1011_10111201_66_dialog_content = "......",
  ui_story_1011_10111201_67_dialog_content = "휴, 손상된 부분이 너무 많아.",
  ui_story_1011_10111201_68_dialog_content = "...마지막으로... ■■■... 결합... ■■■... 시도...",
  ui_story_1011_10111201_69_dialog_content = "실...",
  ui_story_1011_10111201_70_dialog_content = "신체 변화... 관측...",
  ui_story_1011_10111201_71_dialog_content = "......",
  ui_story_1011_10111201_72_dialog_content = "...성공, 「의식 소실」에서 깨어남.",
  ui_story_1011_10111201_73_dialog_content = "?!",
  ui_story_1011_10111201_74_dialog_content = "성공 사례가 있었어!",
  ui_story_1011_10111201_75_dialog_content = "근데 이 실험은 대체 뭐지? 어디서 한 실험인 거지?",
  ui_story_1011_10111201_76_dialog_content = "정보가 더 필요해. 좀 더 깊숙이 들어가 봐야겠어.",
  ui_story_1011_10111201_77_dialog_content = "주의, 목표 정보는... 권한에 의해 보호되고 있습니다...",
  ui_story_1011_10111201_78_dialog_content = "열람을... 종료합니다.",
  ui_story_1011_10111201_79_dialog_content = "휴... 못 보는 건가...",
  ui_story_1011_10111201_80_dialog_content = "어땠어? 뭔가 알아낸 게 있었어?",
  ui_story_1011_10111201_81_dialog_content = "응. 실험 데이터를 찾았어.",
  ui_story_1011_10111201_82_dialog_content = "그중에는 「의식 소실」에서 깨어난 사례도 있었어.",
  ui_story_1011_10111201_83_dialog_content = "근데 그게 무슨 실험인 건지, 어디서 실험을 한 건지는 모르겠어.",
  ui_story_1011_10111201_84_dialog_content = "게다가 성공 사례는 딱 한 번뿐이었어.",
  ui_story_1011_10111201_85_dialog_content = "여기까지 오는 동안 온전하게 보존된 실험 장치 같은 건 못 봤어.",
  ui_story_1011_10111201_86_dialog_content = "좀 더 깊은 곳에 아직 쓸 수 있는 장치가 있길 빌어야겠지.",
  ui_story_1011_10111201_87_dialog_content = "성공률이라면 지금은 시도해 보는 수밖에 없어.",
  ui_story_1011_10111201_88_dialog_content = "그래. 해보는 수밖에.",
  ui_story_1011_10111201_89_dialog_content = "가자, 좀 더 안쪽으로 가 보자.",
  ui_story_1011_10111201_90_dialog_content = "실험 장치를 못 찾더라도 다른 단서가 있을지도 몰라.",
  ui_story_1011_10111201_91_dialog_content = "여기 얼마나 더 많은 비밀이 묻혀 있을지는 아무도 모를 테니까...",
  ui_story_1011_10111201_92_dialog_content = "<color=#e8d9bb>뚜벅... 뚜벅... 뚜벅...</color>",
  ui_story_1011_10111201_93_dialog_content = "「귀환의 탑」...",
  ui_story_1011_10111201_94_dialog_content = "지금 생각해 보니까 우린 계속 탑 모양의 건물을 탐색하고 있었어.",
  ui_story_1011_10111201_95_dialog_content = "지하 유적과 지상의 하얀 탑이 같은 건물인 걸까?",
  ui_story_1011_10111201_96_dialog_content = "같은 거라고 생각하긴 힘들 것 같은데.",
  ui_story_1011_10111201_97_dialog_content = "하얀 탑은 헤븐즈 밸리에 오랫동안 서 있었어. 그래서 다들 잘 알고 있어.",
  ui_story_1011_10111201_98_dialog_content = "근데 이 유적은 전혀 다른 세상의 모습 같아.",
  ui_story_1011_10111201_99_dialog_content = "그래도 두 공간을 연결하는 건...",
  ui_story_1011_10111201_100_dialog_content = "너희 아이테르잖아.",
  ui_story_1011_10111201_101_dialog_content = "......",
  ui_story_1011_10111201_102_dialog_content = "시대도, 문명도, 과학 기술도 변화해 왔지만,\n이 하늘 아래 살고 있던 건 줄곧 아이테르 일족이었어.",
  ui_story_1011_10111201_103_dialog_content = "그건 분명히 위대한 계승이야.",
  ui_story_1011_10111201_104_dialog_content = "오로리안이 탄생한 북방에 서 있을 때조차도 이런 느낌은 못 받았어.",
  ui_story_1011_10111201_105_dialog_content = "「위대함」이라...",
  ui_story_1011_10111201_106_dialog_content = "정말... 너무 무거운 말인 것 같아.",
  ui_story_1011_10111201_107_dialog_content = "응?",
  ui_story_1011_10111201_108_dialog_content = "그 「위대함」을 이어갈 사람은 이제 나 하나밖에 없잖아...",
  ui_story_1011_10111201_109_dialog_content = "PlayerName...",
  ui_story_1011_10111201_110_dialog_content = "아니, 됐어. 복잡하게 생각 안 할래.",
  ui_story_1011_10111201_111_dialog_content = "좋게 생각하면 난 이 유적의 유일한 계승자잖아.",
  ui_story_1011_10111201_112_dialog_content = "여기 있는 건 이제 다 내 거지?",
  ui_story_1011_10111201_113_dialog_content = "후훗.",
  ui_story_1011_10111201_114_dialog_content = "그래, 맞아. 넌 틀림없는 이곳의 주인이야.",
  ui_story_1011_10111201_115_dialog_content = "잘됐네! 이렇게 많은 고대 유물이 있으면 이제 더는 먹고살 걱정을 안 해도 되잖아.",
  ui_story_1011_10111201_116_dialog_content = "돌아가면 바이스가 쓰는 가계부부터 찢어버려야겠어!",
  ui_story_1011_10111201_117_dialog_content = "지금 그 말, 바이스 대신 잘 기억해둘게.",
  ui_story_1011_10111201_118_dialog_content = "아니, 그럴 필요는 없다고...",
  ui_story_1011_10111201_119_dialog_content = "<color=#e8d9bb>스윽... 스윽...</color>",
  ui_story_1011_10111201_120_dialog_content = "뭔가 스치는 소리가 들린 것 같아.",
  ui_story_1011_10111201_121_dialog_content = "어디서 기계가 움직이고 있는 건가?",
  ui_story_1011_10111201_122_dialog_content = "그럴 수도 있겠지.",
  ui_story_1011_10111201_123_dialog_content = "근데 신기한 건 오래전에 폐허가 됐으면서 어떻게 기계가 계속 가동하고 있는 걸까?",
  ui_story_1011_10111201_124_dialog_content = "1000년 이상의 시간이 흘렀을 텐데, 동력원, 마모, 어느 쪽이든 엄청난 난제잖아.",
  ui_story_1011_10111201_125_dialog_content = "우리에겐 난제겠지만, 여길 만든 사람한테는 아닐지도 몰라.",
  ui_story_1011_10111201_126_dialog_content = "그들이 문제를 해결하는 방식은 우리랑 전혀 다른 것 같으니까.",
  ui_story_1011_10111201_127_dialog_content = "그것도 그렇네.",
  ui_story_1011_10111201_128_dialog_content = "더 가까이 가 보자. 아무튼 소리가 어디서 들리는 건지 알아내야 돼.",
  ui_story_1011_10111201_129_dialog_content = "응.",
  ui_story_1011_10111201_130_dialog_content = "<color=#e8d9bb>스윽... 스윽...</color>",
  ui_story_1011_10111201_131_dialog_content = "잠깐만!",
  ui_story_1011_10111201_132_dialog_content = "왜 그래?",
  ui_story_1011_10111201_133_dialog_content = "뭔가 느낀 것 같아.",
  ui_story_1011_10111201_134_dialog_content = "<color=#e8d9bb>스윽... 스윽...</color>",
  ui_story_1011_10111201_135_dialog_content = "......",
  ui_story_1011_10111201_136_dialog_content = "암귀?!",
  ui_story_1011_10111201_137_dialog_content = "어떻게 여기까지...",
  ui_story_1011_10111201_138_dialog_content = "근데 좀 이상해. 녀석들은 분명 우릴 발견했을 텐데, 왜 아무 반응이 없지?",
  ui_story_1011_10111201_139_dialog_content = "......",
  ui_story_1011_10111201_140_dialog_content = "봐, 뭘 하고 있는 거지?",
  ui_story_1011_10111201_141_dialog_content = "<color=#e8d9bb>스윽... 스윽...</color>",
  ui_story_1011_10111201_142_dialog_content = "석판을... 밀고 있어?",
  ui_story_1011_10111201_143_dialog_content = "저 행동에 대체 무슨 의미가 있는 거지?",
  ui_story_1011_10111201_144_dialog_content = "저런 암귀는 한 번도 본 적 없어.",
  ui_story_1011_10111201_145_dialog_content = "저 행동을 무슨 의미로 설명하는 건 무리일 것 같아.",
  ui_story_1011_10111201_145X1_dialog_content = "설마 고위 암귀의 명령에 따라 움직이는 건가?",
  ui_story_1011_10111201_145X2_dialog_content = "아니지. 석판을 미는 일은 어떤 암귀한테도 의미가 없어.",
  ui_story_1011_10111201_145X3_dialog_content = "하지만... 아이테르에겐 의미가 있을지도 몰라.",
  ui_story_1011_10111201_147_dialog_content = "무슨 뜻이야?",
  ui_story_1011_10111201_148_dialog_content = "아까 우린 이 유적이 어떻게 계속 가동해 온 건지 생각하고 있었잖아?",
  ui_story_1011_10111201_149_dialog_content = "우린 지금 그 답을 찾은 거야.",
  ui_story_1011_10111201_150_dialog_content = "그러니까 네 말은, 암귀의 힘으로...?",
  ui_story_1011_10111201_151_dialog_content = "어디까지나 추측일 뿐이야.",
  ui_story_1011_10111201_152_dialog_content = "하지만 녀석들은 우리한테 눈길도 주지 않고, 그저 석판을 밀기만 하고 있어.",
  ui_story_1011_10111201_153_dialog_content = "마치 기계를 가동하는 체인처럼 이 기계의 일부분이 되었어.",
  ui_story_1011_10111201_154_dialog_content = "<color=#e8d9bb>스윽... 스윽...</color>",
  ui_story_1011_10111201_155_dialog_content = "이런 일까지 할 수 있다니...",
  ui_story_1011_10111201_156_dialog_content = "역시 서클 시스템 안에서 본 게 틀리지 않았어.",
  ui_story_1011_10111201_157_dialog_content = "고대의 아이테르는 암귀를 조종하는 법을 알고 있었던 거야...",
  ui_story_1011_10111201_158_dialog_content = "뭘 가지고 따르게 만든 거지?",
  ui_story_1011_10111201_159_dialog_content = "혹시 감응일까?",
  ui_story_1011_10111201_160_dialog_content = "근데 여긴 오래전부터 아무도 없었을 텐데, 그런데도 녀석들은 지금까지 명령을 따르고 있어.",
  ui_story_1011_10111201_161_dialog_content = "잠깐만, 앞쪽엔 더는 길이 없는 것 같아.",
  ui_story_1011_10111201_162_dialog_content = "진짜네? 여기가 끝인 건가?",
  ui_story_1011_10111201_163_dialog_content = "아무것도 없는 것 같아. 텅 비었잖아.",
  ui_story_1011_10111201_164_dialog_content = "가운데 돌 받침대 같은 게 있어. 보러 가 볼까?",
  ui_story_1011_10111201_165_dialog_content = "저 암귀들이 석판을 밀고 있는 건 분명히 이유가 있을 거야.",
  ui_story_1011_10111201_166_dialog_content = "근데 아무리 봐도 그냥 돌로 된 받침대 같아.",
  ui_story_1011_10111201_167_dialog_content = "옆에 무슨 장치 같은 거 없어?",
  ui_story_1011_10111201_168_dialog_content = "콜록... 먼지가 엄청 쌓였네...",
  ui_story_1011_10111201_169_dialog_content = "감응 능력을 써보는 게 어때?",
  ui_story_1011_10111201_170_dialog_content = "해봤는데 아무 반응도 없었어.",
  ui_story_1011_10111201_171_dialog_content = "확실히 그냥 돌이야.",
  ui_story_1011_10111201_172_dialog_content = "어째서지?",
  ui_story_1011_10111201_173_dialog_content = "아니면 전에는 여기에 뭔가 있었을지도 몰라.",
  ui_story_1011_10111201_174_dialog_content = "그러다 재질 때문에 이미 망가졌거나 사라진 거겠지.",
  ui_story_1011_10111201_175_dialog_content = "그럴 수도 있겠네. 이 유적 안의 물건들은 대부분 심하게 망가졌으니까.",
  ui_story_1011_10111201_176_dialog_content = "저 거대한 돌문조차 풍화로 갈라진 틈이 생겼을 정도인데, 다른 재질이라면 더 심하겠지...",
  ui_story_1011_10111201_177_dialog_content = "<color=#e8d9bb>위이잉──!</color>",
  ui_story_1011_10111201_178_dialog_content = "에이드 브레인, 로그인 요청을 감지했습니다.",
  ui_story_1011_10111201_179_dialog_content = "녀석이 다시 말을 했어!",
  ui_story_1011_10111201_180_dialog_content = "뭔가 장치가 움직이기 시작한 것 같아. PlayerName, 방금 뭘 했어?",
  ui_story_1011_10111201_181_dialog_content = "나, 난 아무것도 안 했는데?!",
  ui_story_1011_10111201_182_dialog_content = "나야말로 네가 뭔가 한 줄 알았다고!",
  ui_story_1011_10111201_183_dialog_content = "로그인 사용자의 신분 확인이 필요합니다.",
  ui_story_1011_10111201_184_dialog_content = "신분 정보를 제공해 주시기 바랍니다.",
  ui_story_1011_10111201_185_dialog_content = "신분? 나?",
  ui_story_1011_10111201_186_dialog_content = "난 PlayerName...",
  ui_story_1011_10111201_187_dialog_content = "로그인 사용자의 신분 확인이 필요합니다.",
  ui_story_1011_10111201_188_dialog_content = "신분 정보를 제공해 주시기 바랍니다.",
  ui_story_1011_10111201_189_dialog_content = "뭐? 방금 말했잖아. PlayerName, 이름으로 안 되는 거야?",
  ui_story_1011_10111201_190_dialog_content = "녀석이 만들어진 연대를 생각하면 네 이름으론 아마 검색이 안 되지 않을까.",
  ui_story_1011_10111201_191_dialog_content = "그럼 어떡하지?",
  ui_story_1011_10111201_192_dialog_content = "맞다, 여긴 「프란츠」라는 아이테르가 있었잖아.",
  ui_story_1011_10111201_193_dialog_content = "그 사람 이름으로 시도해 보면 어떨까?",
  ui_story_1011_10111201_194_dialog_content = "신분 입력을 감지했습니다. 「파...라...펑」.",
  ui_story_1011_10111201_195_dialog_content = "하아? 「파라펑」은 또 무슨 소리야? 난 그런 말 한 적 없어!",
  ui_story_1011_10111201_196_dialog_content = "로그인 사용자의 신분 식별을 시작합니다.",
  ui_story_1011_10111201_197_dialog_content = "뚜... 뚜... 뚜...",
  ui_story_1011_10111201_198_dialog_content = "그런 의성어뿐인 이름을 가진 사람이 정말 있을까?",
  ui_story_1011_10111201_199_dialog_content = "헛수고하지 마, 에이드 브레인. 일단 여기가 뭐 하는 곳인지부터 말해줄래?",
  ui_story_1011_10111201_200_dialog_content = "잠깐만, PlayerName!",
  ui_story_1011_10111201_201_dialog_content = "저기 좀 봐...",
  ui_story_1011_10111201_202_dialog_content = "왜 그래?",
  ui_story_1011_10111201_203_dialog_content = "......",
  ui_story_1011_10111201_204_dialog_content = "아, 암귀들이 왜 석판을 안 미는 거지?",
  ui_story_1011_10111201_205_dialog_content = "아니겠지...",
  ui_story_1011_10111201_206_dialog_content = "그어어어──!",
  ui_story_1011_10111201_207_dialog_content = "카렌!",
  ui_story_1011_10111201_208_dialog_content = "얼어붙어라!",
  ui_story_1011_10111401_1_dialog_content = "그나마 여긴 암귀가 적어서 다행이야.",
  ui_story_1011_10111401_2_dialog_content = "안 그랬으면 갑자기 포위됐을 때 도망칠 수 없었을 거야.",
  ui_story_1011_10111401_3_dialog_content = "그러게.",
  ui_story_1011_10111401_4_dialog_content = "이 녀석 대체 어떻게 된 거야? 전보다 더 바보가 된 것 같잖아.",
  ui_story_1011_10111401_5_dialog_content = "저기, 에이드 브레인, 내 말 들려?",
  ui_story_1011_10111401_6_dialog_content = "대답해 줄 수 있을까? 이게 대체 어떻게 된 거야?",
  ui_story_1011_10111401_7_dialog_content = "신분 식별 오류, 「파라펑」은 불법 로그인 신분입니다.",
  ui_story_1011_10111401_8_dialog_content = "신분 정보를 다시 제공해 주시거나 신분 인증을 종료해 주시기 바랍니다.",
  ui_story_1011_10111401_9_dialog_content = "대체 뭐라는 거야? 내 말을 전혀 듣질 않잖아!",
  ui_story_1011_10111401_10_dialog_content = "잠깐만, 에이드 브레인의 태도가 지금까지랑은 전혀 다른 것 같지 않아?",
  ui_story_1011_10111401_11_dialog_content = "전에는 네 질문을 듣고, 네가 궁금한 걸 대답해 줬잖아.",
  ui_story_1011_10111401_12_dialog_content = "근데 지금은 그저 네 명령만을 기다리고 있어.",
  ui_story_1011_10111401_13_dialog_content = "그렇게 말하니까 확실히 그렇네...",
  ui_story_1011_10111401_14_dialog_content = "근데 왜 그런 거지?",
  ui_story_1011_10111401_15_dialog_content = "아마 장소가 바뀐 것 때문일지도 몰라.",
  ui_story_1011_10111401_16_dialog_content = "어쩌면 이 공간은 애초에 녀석에게 명령을 내리는 곳일 수도 있겠지.",
  ui_story_1011_10111401_17_dialog_content = "그런 걸까?",
  ui_story_1011_10111401_18_dialog_content = "에이드 브레인, 신분 인증을 종료해 줘.",
  ui_story_1011_10111401_19_dialog_content = "귀환의 탑 재가동 요청을 감지했습니다.",
  ui_story_1011_10111401_20_dialog_content = "요청자는 파라펑, 미허가 신분입니다.",
  ui_story_1011_10111401_21_dialog_content = "경고, 조작을 계속할 경우 <color=#FFB400>「가디언 시스템」</color>이 실행됩니다.",
  ui_story_1011_10111401_22_dialog_content = "봐! 또 이래!",
  ui_story_1011_10111401_23_dialog_content = "그 의성어뿐인 이름이 나라는 거야? 난 재가동 요청 같은 건 안 했다고!",
  ui_story_1011_10111401_24_dialog_content = "복잡한 가능성 같은 건 제쳐둔다면...",
  ui_story_1011_10111401_25_dialog_content = "그냥 단순히 고장 난 건지도 몰라.",
  ui_story_1011_10111401_26_dialog_content = "고장? 에이드 브레인이?",
  ui_story_1011_10111401_27_dialog_content = "에이드 브레인이 아니라 네 명령을 접수하는 장치가 망가진 거겠지.",
  ui_story_1011_10111401_28_dialog_content = "일루미나의 라디오를 써 본 적 있어?",
  ui_story_1011_10111401_29_dialog_content = "그런 기계는 고장이 나면 「피빅피빅」하는 잡음이 나.",
  ui_story_1011_10111401_30_dialog_content = "에이드 브레인이 접수한 의성어 이름과 비슷한 소리야.",
  ui_story_1011_10111401_31_dialog_content = "그럼 큰일인데...",
  ui_story_1011_10111401_32_dialog_content = "귀환의 탑 재가동 요청이 확인되었습니다.",
  ui_story_1011_10111401_33_dialog_content = "경고, 「가디언 시스템」이 곧 실행됩니다. 즉시 명령을 취소해 주십시오.",
  ui_story_1011_10111401_34_dialog_content = "취소할게! 당연히 취소해야지!",
  ui_story_1011_10111401_35_dialog_content = "애초에 난 명령을 내린 적도 없다니까!",
  ui_story_1011_10111401_36_dialog_content = "경고, 불법 로그인 사용자가 귀환의 탑 재가동 프로그램을 강제 실행했습니다.",
  ui_story_1011_10111401_37_dialog_content = "서클 시스템에서 귀환의 탑 재가동 프로세스를 정보를 가져오는 중입니다.",
  ui_story_1011_10111401_38_dialog_content = "뚜... 뚜... 뚜...",
  ui_story_1011_10111401_39_dialog_content = "왠지 안 좋은 예감이 들어. 뭔가가 시작될 것 같아...",
  ui_story_1011_10111401_40_dialog_content = "나도 그래. 아직 막을 기회가 있을까?",
  ui_story_1011_10111401_41_dialog_content = "그냥 이 사고만 치는 장치를 부숴버리자!",
  ui_story_1011_10111401_42_dialog_content = "망가질 거면 완전히 망가졌어야지. 어설프게 망가져서 이게 뭐냐고!",
  ui_story_1011_10111401_43_dialog_content = "근데 어디 있는 거지? 이 돌 받침대인가?",
  ui_story_1011_10111401_44_dialog_content = "아무튼 일단 시도해보자... 에잇!",
  ui_story_1011_10111401_45_dialog_content = "<color=#e8d9bb>쾅!</color>",
  ui_story_1011_10111401_46_dialog_content = "아야! 아파 아파!",
  ui_story_1011_10111401_47_dialog_content = "그건 돌로 만든 거야. 찬다고 무슨 소용이 있겠어.",
  ui_story_1011_10111401_48_dialog_content = "경고, 불법 로그인 사용자가 귀환의 탑 재가동 프로그램을 강제 실행했습니다.",
  ui_story_1011_10111401_49_dialog_content = "에너지 모듈 회복, 다른 모듈에 에너지를 제공합니다.",
  ui_story_1011_10111401_50_dialog_content = "뚜... 뚜... 뚜...",
  ui_story_1011_10111401_51_dialog_content = "카렌, 발밑에서 약하게 진동이 느껴지는 것 같은데...?",
  ui_story_1011_10111401_52_dialog_content = "나도 느꼈어.",
  ui_story_1011_10111401_53_dialog_content = "에이드 브레인이 말하는 「귀환의 탑 재가동」이라는 건...\n어쩌면 이 유적 전체에 어떤 변화가 일어난다는 건지도 몰라.",
  ui_story_1011_10111401_54_dialog_content = "유적 전체에? 그렇게 무서운 일이라고?",
  ui_story_1011_10111401_55_dialog_content = "지금 걱정해야 할 건 그것보다 더 무서운 일이야.",
  ui_story_1011_10111401_56_dialog_content = "에이드 브레인은 계속 「경고」했어. 아마 그냥 말로만 끝나진 않을 거야.",
  ui_story_1011_10111401_57_dialog_content = "경고, 불법 로그인 사용자가 귀환의 탑 재가동 프로그램을 강제 실행했습니다.",
  ui_story_1011_10111401_58_dialog_content = "명령 권한에 오류가 발견되었습니다. 곧 자율 수정을 진행합니다.",
  ui_story_1011_10111401_59_dialog_content = "마지막 경고입니다. 즉시 명령을 취소해 주십시오.",
  ui_story_1011_10111401_60_dialog_content = "취소한다고 했잖아!",
  ui_story_1011_10111401_61_dialog_content = "제발 부탁이니까 취소해 줘!",
  ui_story_1011_10111401_62_dialog_content = "난 영문도 모르는 고대 문명의 적이 되고 싶진 않다고!",
  ui_story_1011_10111401_64_dialog_content = "불법 명령이 계속해서 내려지는 것이 감지되었습니다.",
  ui_story_1011_10111401_65_dialog_content = "수정 프로그램 실행을 준비합니다.",
  ui_story_1011_10111401_66_dialog_content = "야! 에이드 브레인! 너무하잖아!",
  ui_story_1011_10111401_67_dialog_content = "「가디언 시스템」을 실행합니다. 클라우디아가 해방됩니다.",
  ui_story_1011_10111401_68_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_1011_10111401_69_dialog_content = "저건...",
  ui_story_1011_10111401_70_dialog_content = "조각상? 아니면 로봇인가?",
  ui_story_1011_10111401_71_dialog_content = "움직이긴... 하는 건가?",
  ui_story_1011_10111401_72_dialog_content = "아마... 고장 났겠지...?",
  ui_story_1011_10111401_73_dialog_content = "<color=#e8d9bb>삐그덕── 삐그덕──</color>",
  ui_story_1011_10111401_74_dialog_content = "그런 것 같진 않네.",
  ui_story_1011_10111401_75_dialog_content = "PlayerName, 싸울 준비해.",
  ui_story_1011_10111401_76_dialog_content = "...에이드 브레인, 우리 얘기 좀 할 수 있을까?",
  ui_story_1011_10111401_77_dialog_content = "「가디언 시스템」이 오류 수정을 시작합니다.",
  ui_story_1011_10111401_78_dialog_content = "잘못된 명령을 수정하거나──|\n잘못된 명령을 입력한 자를 수정합니다.",
  ui_story_1011_10111402_1_dialog_content = "성가신 녀석이네.",
  ui_story_1011_10111402_2_dialog_content = "루미나틱스의 대처법을 알고 있어.",
  ui_story_1011_10111402_3_dialog_content = "아무래도 시간을 끌게 될 것 같아.",
  ui_story_1011_10111402_4_dialog_content = "카렌, 버틸 수 있겠어?",
  ui_story_1011_10111402_5_dialog_content = "난 괜찮아, 하지만...",
  ui_story_1011_10111402_6_dialog_content = "바이스가 옆에 있어, 무슨 일이라도 생기면 큰일이야.",
  ui_story_1011_10111402_7_dialog_content = "속전속결로 끝낼 방법이 없을까?",
  ui_story_1011_10111402_8_dialog_content = "귀환의 탑 내 설비 자가 점검을 시작합니다──",
  ui_story_1011_10111402_9_dialog_content = "경고, 파손 정도가 고위험도에 도달했습니다.\n대부분의 구역을 정상적으로 사용할 수 없습니다.",
  ui_story_1011_10111402_10_dialog_content = "「피해 관리 프로그램」을 실행해 파손 위치의 복구를 시도합니다.",
  ui_story_1011_10111402_11_dialog_content = "!!!",
  ui_story_1011_10111402_12_dialog_content = "카렌! 녀석이 움직임을 멈췄어!",
  ui_story_1011_10111402_13_dialog_content = "지금이야! 뒤로 돌아가!",
  ui_story_1011_10111402_14_dialog_content = "알겠어!",
  ui_story_1011_10111402_15_dialog_content = "「가디언 시스템」이 실행 중임을 감지했습니다.",
  ui_story_1011_10111402_16_dialog_content = "해당 부분을 건너뛰고 계속해서 명령 입력 시스템을 복구합니다.",
  ui_story_1011_10111402_17_dialog_content = "뚜... 뚜... 뚜...",
  ui_story_1011_10111402_18_dialog_content = "<color=#e8d9bb>덜컹──</color>",
  ui_story_1011_10111402_19_dialog_content = "카렌! 녀석이 다시 움직여! 조심해!",
  ui_story_1011_10111402_20_dialog_content = "시간은 충분해.",
  ui_story_1011_10111402_21_dialog_content = "고대에 태어난 병기여, 미래의 루미나틱스를 보여주겠어!",
  ui_story_1011_10111402_22_dialog_content = "휴... 해치운 건가...",
  ui_story_1011_10111402_23_dialog_content = "응, 행동력을 완전히 잃었어.",
  ui_story_1011_10111402_24_dialog_content = "그래도 긴장을 늦춰서는 안 돼.",
  ui_story_1011_10111402_25_dialog_content = "지금 봤듯이 귀환의 탑의 자기방어 능력은 아주 강해.",
  ui_story_1011_10111402_26_dialog_content = "이미 녀석을 화나게 만든 이상, 앞으로 어떤 귀찮은 일이 기다리고 있을지 몰라.",
  ui_story_1011_10111402_27_dialog_content = "아니겠지...?",
  ui_story_1011_10111402_28_dialog_content = "싸울수록 사이가 좋아진다는 말도 있잖아. 마음에 안 담아뒀으면 좋겠는데...",
  ui_story_1011_10111402_29_dialog_content = "딩── 동──",
  ui_story_1011_10111402_30_dialog_content = "「피해 관리 프로그램」의 복구가 완료되었습니다.\n주요 기능의 기본적인 복구를 마쳤습니다.",
  ui_story_1011_10111402_31_dialog_content = "귀환의 탑이 재가동되었습니다.",
  ui_story_1011_10111402_32_dialog_content = "뭐? 딱히 큰일 없이 어느새 끝나버렸잖아...",
  ui_story_1011_10111402_33_dialog_content = "귀환의 탑 에너지 공급이 회복되었습니다.",
  ui_story_1011_10111402_34_dialog_content = "귀환의 탑 전동 시스템이 회복되었습니다.",
  ui_story_1011_10111402_35_dialog_content = "귀환의 탑 센서 시스템이 회복되었습니다.",
  ui_story_1011_10111402_36_dialog_content = "<color=#e8d9bb>덜컹── 덜컹── 덜컹── 덜컹──</color>",
  ui_story_1011_10111402_37_dialog_content = "카렌! 들어봐! 기계가 움직이는 소리가 사방에서 나고 있어!",
  ui_story_1011_10111402_38_dialog_content = "탑이 가동을 시작했어! 탑 전체가 움직이고 있다고!",
  ui_story_1011_10111402_39_dialog_content = "정말 믿을 수 없어...",
  ui_story_1011_10111402_40_dialog_content = "이 유적, 폐허가 된 게 아니었어! 마치...",
  ui_story_1011_10111402_41_dialog_content = "오랫동안 자고 있었을 뿐인 것처럼...",
  ui_story_1011_10111402_42_dialog_content = "귀환의 탑 내 상황을 보고합니다.",
  ui_story_1011_10111402_43_dialog_content = "콜로서스 정비 구역, 현재 콜로서스, 1대... 상태, 수리 대기.",
  ui_story_1011_10111402_44_dialog_content = "콜로서스 부품 공장, 파괴됨, 복구 실패.",
  ui_story_1011_10111402_45_dialog_content = "자원 생산 구역, 현재 인원, 0.",
  ui_story_1011_10111402_46_dialog_content = "폐기물 처리 구역, 현재 인원, 0명.",
  ui_story_1011_10111402_47_dialog_content = "아이테르 생활 구역, 현재 인원, 0.",
  ui_story_1011_10111402_48_dialog_content = "추방 구역, 현재 인원, 0.",
  ui_story_1011_10111402_49_dialog_content = "......",
  ui_story_1011_10111402_50_dialog_content = "여긴 이제 아이테르는 없는 거구나. 그저...",
  ui_story_1011_10111402_51_dialog_content = "핵심 중추 구역, 현재 인원, 1.",
  ui_story_1011_10111402_52_dialog_content = "그래, 나 한 사람뿐이야.",
  ui_story_1011_10111402_53_dialog_content = "탑이 기나긴 꿈에서 깨어났어.",
  ui_story_1011_10111402_54_dialog_content = "근데... 녀석이 고독에 익숙해질 수 있을까?",
  ui_story_1011_10111402_55_dialog_content = "위치 복구 프로그램 실행을 준비합니다.",
  ui_story_1011_10111402_56_dialog_content = "귀환의 탑이 다시 하늘 끝까지 올라갑니다.",
  ui_story_1011_10111402_57_dialog_content = "아직도 안 질렸어?",
  ui_story_1011_10111402_58_dialog_content = "하아... 하아...",
  ui_story_1011_10111402_59_dialog_content = "어이, 계속 싸우자고!",
  ui_story_1011_10111402_60_dialog_content = "어느 한쪽이 쓰러질 때까지 안 하면 재미없잖아!",
  ui_story_1011_10111402_61_dialog_content = "넌 혼자야. 패배는 정해진 일이야.",
  ui_story_1011_10111402_62_dialog_content = "이런 건 싸움이 아냐. 그냥 네가 떼쓰고 있는 거지.",
  ui_story_1011_10111402_63_dialog_content = "(이 녀석, 강하다. 내가 완전히 밀리고 있어.)",
  ui_story_1011_10111402_64_dialog_content = "(한심한 이야기지만, 지금까지 버틸 수 있었던 건 녀석이 싸울 마음이 없었던 덕분이다.)",
  ui_story_1011_10111402_65_dialog_content = "(저 하얀 탑 안에 대체 뭐가 있길래 이 녀석이 이렇게까지 신경을 쓰는 거냐.)",
  ui_story_1011_10111402_66_dialog_content = "(뭐, 됐어. 당장은 생각해 봤자 알 수 없겠지.)",
  ui_story_1011_10111402_67_dialog_content = "(다만 한 가지는 알겠어. 적이 집착할수록 더 막아야 하는 법이지.)",
  ui_story_1011_10111402_68_dialog_content = "(군인이라면 결코 적이 강하다고 해서 겁을 먹어선 안 된다고!)",
  ui_story_1011_10111402_69_dialog_content = "어딜 보는 거냐! 노라!",
  ui_story_1011_10111402_70_dialog_content = "조무래기들 따위로 날 막을 생각 마라!",
  ui_story_1011_10111402_71_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_1011_10111402_72_dialog_content = "<color=#e8d9bb>쿠구구구──!</color>",
  ui_story_1011_10111402_73_dialog_content = "어이, 어이! 뭐가 어떻게 된 거야? 지진인가?",
  ui_story_1011_10111402_74_dialog_content = "마침 딱 재밌어지려던 참인데, 찬물 끼얹지 말라고!",
  ui_story_1011_10111402_75_dialog_content = "아니, 이건 그냥 지진이 아니야.",
  ui_story_1011_10111402_76_dialog_content = "탑이...",
  ui_story_1011_10111402_77_dialog_content = "탑이 진동하고 있어.",
  ui_story_1011_10111402_78_dialog_content = "뭐야, 이 엄청난 연기는! 쿨럭... 쿨럭...",
  ui_story_1011_10111402_79_dialog_content = "<color=#e8d9bb>쿠구구구──!</color>",
  ui_story_1011_10111402_80_dialog_content = "우오오오오!",
  ui_story_1011_10111402_81_dialog_content = "빌어먹을! 이건 지진보다 더 심하잖아!",
  ui_story_1011_10111402_82_dialog_content = "지진보다 심한 게 당연하지.",
  ui_story_1011_10111402_83_dialog_content = "이제 보게 될 건 어쩌면 천 년, 만 년에 한 번 있을 모습일 테니까.",
  ui_story_1011_10111402_84_dialog_content = "이 하얀 탑은 이런 곳에 서 있어선 안 돼.",
  ui_story_1011_10111402_85_dialog_content = "이 탑은... 더 높은 곳에 서야만 한다고.",
  ui_story_1011_10111402_86_dialog_content = "<color=#e8d9bb>콰르르릉!</color>",
  ui_story_1011_10111402_87_dialog_content = "뭐야?!",
  ui_story_1011_10111402_88_dialog_content = "잘못 본 게 아니겠지... 이렇게 큰 탑이... 땅에서 솟아오른다고?",
  ui_story_1011_10111402_89_dialog_content = "PlayerName 녀석하고 다들 아직 안에 있단 말이다!",
  ui_story_1011_10111402_90_dialog_content = "녀석들... 대체 뭘 한 거야?",
  ui_story_1011_10111402_91_dialog_content = "수많은 시간이 흘러도 여전히 움직이는 고대 건물이 정말로 존재했다니.",
  ui_story_1011_10111402_92_dialog_content = "나와 벽 한 장을 사이에 둔 저쪽은...",
  ui_story_1011_10111402_93_dialog_content = "또 하나의 시대인 건가...",
  ui_story_1011_10111402_94_dialog_content = "그래서 저게 대체 뭐지? 네가 연구한 적 있는 거냐?",
  ui_story_1011_10111402_95_dialog_content = "내가 네 질문에 대답할 필요는 없을 텐데.",
  ui_story_1011_10111402_96_dialog_content = "『노라 님, 노라 님!』",
  ui_story_1011_10111402_97_dialog_content = "『솟아오른 하얀 탑 외벽에 틈이 있습니다.』",
  ui_story_1011_10111402_98_dialog_content = "틈이라, 아주 좋아.",
  ui_story_1011_10111402_99_dialog_content = "그럼 더는 이 미치광이를 상대해 줄 필요도 없겠네.",
  ui_story_1011_10111402_100_dialog_content = "어이! 날 내팽개칠 생각이냐!",
  ui_story_1011_10111402_101_dialog_content = "싸움은 아직 안 끝났다고!",
  ui_story_1011_10111402_101X1_dialog_content = "(이 전투나 노라의 저 반응을 보면 PlayerName 녀석들은 아주 중요한 일을 하고 있는 게 분명해.)",
  ui_story_1011_10111402_101X2_dialog_content = "(절대 노라가 저들을 방해하게 둬선 안 돼. 절대로!)",
  ui_story_1011_10111402_102_dialog_content = "뭐야?! 어떻게 된 거야?! 엄청 흔들리잖아!",
  ui_story_1011_10111402_103_dialog_content = "뭐라도 꽉 잡아! 위에서 떨어지는 물건도 조심해!",
  ui_story_1011_10111402_104_dialog_content = "바이스는 괜찮아?!",
  ui_story_1011_10111402_105_dialog_content = "걱정할 거 없어. 내가 잘 챙길 테니까!",
  ui_story_1011_10111402_106_dialog_content = "<color=#e8d9bb>콰르르릉!</color>",
  ui_story_1011_10111402_107_dialog_content = "후우... 후우... 멈췄어...",
  ui_story_1011_10111402_108_dialog_content = "카렌, 괜찮아?",
  ui_story_1011_10111402_109_dialog_content = "난 괜찮아. 바이스도 무사해. 그것보다 너...",
  ui_story_1011_10111402_110_dialog_content = "언제까지 그 돌 받침대를 안고 있을 거야? 이제 놓아도 돼.",
  ui_story_1011_10111402_111_dialog_content = "아, 그렇구나.",
  ui_story_1011_10111402_112_dialog_content = "그래서 방금 그건 또 무슨 일이었던 거지?",
  ui_story_1011_10111402_113_dialog_content = "내가 느낀 건 상승하는 느낌이었어.",
  ui_story_1011_10111402_114_dialog_content = "나도 그런 것 같긴 했어.",
  ui_story_1011_10111402_115_dialog_content = "귀환의 탑 위치 복구가 완료되었습니다.",
  ui_story_1011_10111402_116_dialog_content = "관리자에게 상황을 보고합니다.",
  ui_story_1011_10111402_117_dialog_content = "「귀환의 탑 위치 복구」라는 건... 탑 전체의 위치가 바뀌었다는 뜻인가?",
  ui_story_1011_10111402_118_dialog_content = "그런 게 어떻게 가능한 거지?",
  ui_story_1011_10111402_119_dialog_content = "보고에 실패했습니다. 관리자를 찾을 수 없습니다.",
  ui_story_1011_10111402_120_dialog_content = "예비 플랜을 실행합니다. 귀환의 탑 재시작 프로그램의 실행자를 찾습니다.",
  ui_story_1011_10111402_121_dialog_content = "대상 신분은 불법 로그인 사용자 「파라펑」으로 확인되었습니다.",
  ui_story_1011_10111402_122_dialog_content = "잠깐만, 이 녀석 나한테 또 뭘 하려는 건 아니겠지?",
  ui_story_1011_10111402_123_dialog_content = "예비 플랜을 진행합니다. 「파라펑」이 귀환의 탑을 재가동했으므로,\n대상을 승격시켜 관리자 공석을 보충합니다.",
  ui_story_1011_10111402_124_dialog_content = "「파라펑」에게 이너 서클 권한을 개방합니다.",
  ui_story_1011_10111402_125_dialog_content = "뭐야?",
  ui_story_1011_10111402_126_dialog_content = "나 불법이라면서? 왜 갑자기 관리자가 된 거야?",
  ui_story_1011_10111402_127_dialog_content = "그 관리자는 또 뭘 하는 건데?",
  ui_story_1011_10111402_128_dialog_content = "관리자는 에이드 브레인을 통해 귀환의 탑 내 대부분의 기능을 제어 및 사용할 수 있습니다.",
  ui_story_1011_10111402_129_dialog_content = "그렇구나...",
  ui_story_1011_10111402_130_dialog_content = "어? 이제 다시 대답해 주는 거야?!",
  ui_story_1011_10111402_131_dialog_content = "그렇습니다.",
  ui_story_1011_10111402_132_dialog_content = "그럼 방금 전까진 왜 그런 건데?",
  ui_story_1011_10111402_133_dialog_content = "핵심 중추 구역에서 일반 로그인 사용자는 명령의 입력만 가능하며,\n에이드 브레인과 상호작용할 수 없습니다.",
  ui_story_1011_10111402_134_dialog_content = "관리자는 언제든지 에이드 브레인과 상호작용할 권한이 있습니다.",
  ui_story_1011_10111402_135_dialog_content = "뭐야, 사람 가려서 대하는 속물이었잖아?",
  ui_story_1011_10111402_136_dialog_content = "에이드 브레인은 그 말의 의미를 이해하지 못했습니다.",
  ui_story_1011_10111402_137_dialog_content = "휴, 됐어.",
  ui_story_1011_10111402_138_dialog_content = "근데 명령 입력이라면, 아까 그 명령도 제대로 된 게 아니잖아!",
  ui_story_1011_10111402_139_dialog_content = "「파라펑」이라는 그 이상한 이름부터가 증거라고!",
  ui_story_1011_10111402_140_dialog_content = "직전까지 명령 입력 시스템에 손상이 발생한 상태였습니다.\n지금은 이미 복구되었습니다.",
  ui_story_1011_10111402_141_dialog_content = "불편을 끼쳐드려 대단히 죄송합니다.",
  ui_story_1011_10111402_142_dialog_content = "그게 어디 보통 불편이었냐고.",
  ui_story_1011_10111402_143_dialog_content = "그리고 아까 말한 「이너 서클 권한 개방」은 또 뭔데?",
  ui_story_1011_10111402_144_dialog_content = "귀환의 탑의 정보 및 기능은 3단계의 권한 등급으로 나누어져 있습니다.",
  ui_story_1011_10111402_145_dialog_content = "<color=#FFB400>「아우터 서클」</color>은 일반 로그인 사용자가 액세스할 수 있습니다.",
  ui_story_1011_10111402_146_dialog_content = "<color=#FFB400>「이너 서클」</color>은 관리자가 액세스할 수 있습니다.",
  ui_story_1011_10111402_147_dialog_content = "<color=#FFB400>「오리진 서클」</color>은 최초이자 최고 등급의 「명령」을 의미하며, 액세스할 수 없습니다.",
  ui_story_1011_10111402_148_dialog_content = "음, 그럼 액세스할 수 없는 「오리진 서클 권한」만 빼고,\n내가 지금 최고 권한을 갖고 있다는 거야?",
  ui_story_1011_10111402_149_dialog_content = "그렇습니다.",
  ui_story_1011_10111402_150_dialog_content = "당신은 이미 이너 서클 권한을 가지고 있습니다.\n이제 귀환의 탑의 감지를 동기화해 드리겠습니다.",
  ui_story_1011_10111402_151_dialog_content = "어? 그건 또 뭔데?",
  ui_story_1011_10111402_152_dialog_content = "이름이 너무 많아서 외울 수가 없잖아!",
  ui_story_1011_10111402_153_dialog_content = "외울 필요는 없습니다. 의식으로 느끼기만 하면 됩니다.",
  ui_story_1011_10111402_154_dialog_content = "귀환의 탑이 당신의 눈이 될 것입니다.",
  ui_story_1011_10111402_155_dialog_content = "이건...",
  ui_story_1011_10111402_156_dialog_content = "우와! 엄청 높은 탑이네! 이게 귀환의 탑의 모습이야?",
  ui_story_1011_10111402_157_dialog_content = "저건... 우리가 폭파시켰던 구멍이잖아?",
  ui_story_1011_10111402_158_dialog_content = "역시 하얀 탑이랑 하나로 이어져 있었어!",
  ui_story_1011_10111402_159_dialog_content = "PlayerName, 밖의 모습이 눈에 보이는 거야?",
  ui_story_1011_10111402_160_dialog_content = "응!",
  ui_story_1011_10111402_161_dialog_content = "신기해! 꼭 내가 탑 밖을 날아다니는 것 같아!",
  ui_story_1011_10111402_162_dialog_content = "다른 곳도 살펴보실 수 있습니다.",
  ui_story_1011_10111402_163_dialog_content = "더... 멀고 먼 곳도 말입니다.",
  ui_story_1011_10111501_1_dialog_content = "저쪽이야! 빨리 가서 봐!",
  ui_story_1011_10111501_2_dialog_content = "벌써 봤다고! 아무것도 없잖아!",
  ui_story_1011_10111501_3_dialog_content = "대체 무슨...",
  ui_story_1011_10111501_4_dialog_content = "빨리 가서 사람을 불러!",
  ui_story_1011_10111501_5_dialog_content = "이건 우리가 해결할 수 있는 일이 아냐!",
  ui_story_1011_10111501_6_dialog_content = "그래, 나이트워치, 나이트워치를 불러!",
  ui_story_1011_10111501_7_dialog_content = "상부에 해결을 부탁드려!",
  ui_story_1011_10111501_8_dialog_content = "이...이건 다모클레스라고...",
  ui_story_1011_10111501_9_dialog_content = "나딘, 상황을 다시 한번 자세히 설명해라.",
  ui_story_1011_10111501_10_dialog_content = "네, 성주님!",
  ui_story_1011_10111501_11_dialog_content = "경비병의 보고에 의하면, 10분 정도 전에 「제어실」 쪽에서 이상이 발생했다고 합니다.",
  ui_story_1011_10111501_12_dialog_content = "경비병들은 비슷한 상황을 겪은 적이 없었고, 점검 결과에도 이상이 없어 당황한 듯합니다.",
  ui_story_1011_10111501_13_dialog_content = "현장의 상황으로 짐작했을 때──",
  ui_story_1011_10111501_14_dialog_content = "지금 <color=#FFB400>다모클레스</color>가 가동 중입니다.",
  ui_story_1011_10111501_15_dialog_content = "또 다모클레스인가요.",
  ui_story_1011_10111501_16_dialog_content = "이번엔 대체 누가 멋대로 가동한 거죠?",
  ui_story_1011_10111501_17_dialog_content = "아무도 없었습니다.",
  ui_story_1011_10111501_18_dialog_content = "?!",
  ui_story_1011_10111501_19_dialog_content = "경비병이 제어실을 빈틈없이 수색했지만, 확실히 아무도 없었습니다.",
  ui_story_1011_10111501_20_dialog_content = "다모클레스가 스스로 가동한 겁니다.",
  ui_story_1011_10111501_21_dialog_content = "그게 가능한가요?",
  ui_story_1011_10111501_22_dialog_content = "다모클레스의 현재 상황은 어떠한가.",
  ui_story_1011_10111501_23_dialog_content = "아직 가동 단계입니다. 루미나를 모으는 중입니다.",
  ui_story_1011_10111501_24_dialog_content = "좋다, 잘 알겠다.",
  ui_story_1011_10111501_25_dialog_content = "나딘, 그대는 즉시 가서 다모클레스와 백야성 간의 루미나 연결을 끊어라.",
  ui_story_1011_10111501_26_dialog_content = "뒷일은 생각하지 마라. 빠르면 빠를수록 좋다.",
  ui_story_1011_10111501_27_dialog_content = "네, 성주님!",
  ui_story_1011_10111501_28_dialog_content = "이리돈, 그대는 부하들을 이끌고 이곳을 봉쇄하라. 누구든지 제어실에 접근하게 해선 안 된다.",
  ui_story_1011_10111501_29_dialog_content = "특히 원로원 쪽 말이지. 저들은 위기의 순간일수록 소란을 피우는 것을 즐기니 말이야.",
  ui_story_1011_10111501_30_dialog_content = "알겠습니다.",
  ui_story_1011_10111501_31_dialog_content = "하지만 먼저 정보의 신빙성을 확인해 보실 필요는 없을까요?",
  ui_story_1011_10111501_32_dialog_content = "다모클레스의 연결 해제나 제어실의 봉쇄 모두 국면에 큰 영향을 주는 중대한 일입니다.",
  ui_story_1011_10111501_33_dialog_content = "정황을 제대로 파악하지 못한 경비병의 처벌로 문제가 해결된다면\n그보다 더 좋을 순 없겠지.",
  ui_story_1011_10111501_34_dialog_content = "허나 이 문제는 그리 단순한 일이 아닐 것이다.",
  ui_story_1011_10111501_35_dialog_content = "다모클레스가 언제라도 발사될 수 있는 위험보다는 다른 손실을 감당하는 편이 낫지 않겠는가.",
  ui_story_1011_10111501_36_dialog_content = "네, 성주님, 알겠습니다.",
  ui_story_1011_10111501_37_dialog_content = "사천사는 날 따라와라.",
  ui_story_1011_10111501_38_dialog_content = "네!",
  ui_story_1011_10111501_39_dialog_content = "<color=#e8d9bb>위이잉──!</color>",
  ui_story_1011_10111501_40_dialog_content = "또 루미나 파동이에요!",
  ui_story_1011_10111501_41_dialog_content = "그래도... 다모클레스의 힘이 약해지고 있어요!",
  ui_story_1011_10111501_42_dialog_content = "좋다, 너희들의 힘은 어떠한가.",
  ui_story_1011_10111501_43_dialog_content = "아직 버틸 수 있어요... 근데 슬슬 한계예요!",
  ui_story_1011_10111501_44_dialog_content = "다들 애쓰고 있어요...",
  ui_story_1011_10111501_45_dialog_content = "뜨거워... 가슴이 불타는 것 같아...",
  ui_story_1011_10111501_46_dialog_content = "......",
  ui_story_1011_10111501_47_dialog_content = "알겠다.",
  ui_story_1011_10111501_48_dialog_content = "우리가 문제를 해결해야 한다. 이게 마지막 시도다.",
  ui_story_1011_10111501_49_dialog_content = "전원, 루미나를 발산해서 다모클레스의 루미나 흐름을 막아라!",
  ui_story_1011_10111501_50_dialog_content = "전력으로 녀석의 가동을 약화시키는 것이다!",
  ui_story_1011_10111501_51_dialog_content = "네!",
  ui_story_1011_10111501_52_dialog_content = "<color=#e8d9bb>위이잉──!</color>",
  ui_story_1011_10111501_53_dialog_content = "<color=#e8d9bb>위이잉...</color>",
  ui_story_1011_10111501_54_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_1011_10111501_55_dialog_content = "하아... 하아... 하아...",
  ui_story_1011_10111501_56_dialog_content = "성공했나? 멈췄어?",
  ui_story_1011_10111501_57_dialog_content = "다 타버렸어... 우리도... 다모클레스도...",
  ui_story_1011_10111501_58_dialog_content = "......",
  ui_story_1011_10111501_59_dialog_content = "성주님, 이걸로 해결된 걸까요?",
  ui_story_1011_10111501_60_dialog_content = "음, 제어실의 문제는 해결되었다.",
  ui_story_1011_10111501_61_dialog_content = "허나...",
  ui_story_1011_10111501_62_dialog_content = "다모클레스여, 그대는...",
  ui_story_1011_10111501_63_dialog_content = "대체 어디를 노리고 있었던 것이냐.",
  ui_story_1011_10111501_64_dialog_content = "<color=#e8d9bb>위잉! 위잉! 위잉! 위잉!</color>",
  ui_story_1011_10111501_65_dialog_content = "시끄럽다냥!",
  ui_story_1011_10111501_66_dialog_content = "으으... 필리시의 낮잠이...",
  ui_story_1011_10111501_67_dialog_content = "음? 필리시?",
  ui_story_1011_10111501_68_dialog_content = "또 업무 시간에 졸았군요!",
  ui_story_1011_10111501_69_dialog_content = "에이, 그런 말이 어딨다냥? 지금 아주 잘 일어나 있지 않냥.",
  ui_story_1011_10111501_70_dialog_content = "뭐, 됐어요. 그 이야기는 나중에 다시 하죠.",
  ui_story_1011_10111501_71_dialog_content = "그것보다 지금 이 시끄러운 소리는 대체 뭘까요...",
  ui_story_1011_10111501_72_dialog_content = "<color=#e8d9bb>위잉! 위잉! 위잉! 위잉!</color>",
  ui_story_1011_10111501_73_dialog_content = "시끄럽잖아! 대체 무슨 소리냐!",
  ui_story_1011_10111501_74_dialog_content = "어이, 누구라도 좀 나와서 설명해 봐!",
  ui_story_1011_10111501_75_dialog_content = "아, 시로나 군단장.",
  ui_story_1011_10111501_76_dialog_content = "오셨군요...",
  ui_story_1011_10111501_77_dialog_content = "비비안, 저게 무슨 소린지 알아?",
  ui_story_1011_10111501_78_dialog_content = "모르겠어요. 한 번도 들어본 적 없는 소리예요.",
  ui_story_1011_10111501_79_dialog_content = "왜 아무도 모르는 거야?",
  ui_story_1011_10111501_80_dialog_content = "전장도 아닌데 자난성의 소음에까지 시달리고 싶진 않다고.",
  ui_story_1011_10111501_81_dialog_content = "어디 설비가 고장 난 건 아닐까요? 지금 바로 조사를 시킬게요!",
  ui_story_1011_10111501_82_dialog_content = "<color=#e8d9bb>위잉! 위잉! 위잉! 위잉!</color>",
  ui_story_1011_10111501_83_dialog_content = "이런 상황이에요. 지금 자난성 어디를 가도 이 소음이 들려요.",
  ui_story_1011_10111501_84_dialog_content = "음... 으음...",
  ui_story_1011_10111501_85_dialog_content = "수리공들한테 검사를 시켰는데, 소리를 내고 있는 건 벽 안에 있는 오래된 장치였어요.",
  ui_story_1011_10111501_86_dialog_content = "오래전에 검사 후 폐기 조치된 장치인데, 이번에 갑자기 이런 소리를 낼 줄은...",
  ui_story_1011_10111501_87_dialog_content = "음... 으음...",
  ui_story_1011_10111501_88_dialog_content = "그로누, 듣고 있나요?",
  ui_story_1011_10111501_89_dialog_content = "응, 듣고 있어, 듣고 있다구.",
  ui_story_1011_10111501_90_dialog_content = "그거 얘기잖아... 음, 그래. 그거.",
  ui_story_1011_10111501_91_dialog_content = "전혀 안 듣고 있잖아요!",
  ui_story_1011_10111501_92_dialog_content = "일단 책은 그만 읽어요. 이건 아주 중요한 일이라고요.",
  ui_story_1011_10111501_93_dialog_content = "소음 때문에 성안에서 소란이 발생하고 있어요.",
  ui_story_1011_10111501_94_dialog_content = "다른 기술자들은 해결할 수 없는 상황이에요. 당신이라면...",
  ui_story_1011_10111501_95_dialog_content = "쉿──",
  ui_story_1011_10111501_96_dialog_content = "?!",
  ui_story_1011_10111501_97_dialog_content = "<color=#e8d9bb>위잉! 위잉! 위잉! 위잉!</color>",
  ui_story_1011_10111501_98_dialog_content = "아, 그런 거였어.",
  ui_story_1011_10111501_99_dialog_content = "알았어, 진짜로 알았다구.",
  ui_story_1011_10111501_100_dialog_content = "네? 뭘 알았는데요?",
  ui_story_1011_10111501_101_dialog_content = "어려운 얘기라고 도망가면 안 돼. 잘 들어.",
  ui_story_1011_10111501_102_dialog_content = "저건 그냥 소음이 아니야. 소리 안에... 말이 섞여 있어.",
  ui_story_1011_10111501_103_dialog_content = "「말」이요?!",
  ui_story_1011_10111501_104_dialog_content = "맞아, 굉장히 오래된 언어야.",
  ui_story_1011_10111501_105_dialog_content = "어디 보자... 302페이지... 564페이지...",
  ui_story_1011_10111501_106_dialog_content = "아, 찾았어!",
  ui_story_1011_10111501_107_dialog_content = "고대 언어의 해석은 대부분 추측에 기반하다 보니 정확하다고 할 순 없지만...",
  ui_story_1011_10111501_108_dialog_content = "이 말이 전하려는 의미는 아마──",
  ui_story_1011_10111501_109_dialog_content = "<color=#FFB400>「어서 숨어라」</color>야.",
  ui_story_1011_10111501_110_dialog_content = "왔냐? 렉커.",
  ui_story_1011_10111501_111_dialog_content = "흥, 각오는 됐겠지?",
  ui_story_1011_10111501_112_dialog_content = "각오해야 하는 건 너잖아. 루저.",
  ui_story_1011_10111501_113_dialog_content = "그 모욕적인 호칭도 오늘까지다!",
  ui_story_1011_10111501_114_dialog_content = "오늘 내가 정정당당하게 사메야마를 이기는 걸 모두가 보게 될 테니까!",
  ui_story_1011_10111501_115_dialog_content = "오! 기세는 나쁘지 않은데?",
  ui_story_1011_10111501_116_dialog_content = "근데... 「모두」라니?",
  ui_story_1011_10111501_117_dialog_content = "그래. 레디젤 렌치의 모든 멤버를 불러왔다고.",
  ui_story_1011_10111501_118_dialog_content = "어떠냐! 이렇게 많은 사람들 앞에서 나랑 싸우려니 긴장되겠지?!",
  ui_story_1011_10111501_119_dialog_content = "긴장이고 뭐고... 다 어디 갔는데?",
  ui_story_1011_10111501_120_dialog_content = "아무도 안 왔잖아.",
  ui_story_1011_10111501_121_dialog_content = "어이! 다들! 빨리 나와!",
  ui_story_1011_10111501_122_dialog_content = "승부가 시작될 거라고!",
  ui_story_1011_10111501_123_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_1011_10111501_124_dialog_content = "야!",
  ui_story_1011_10111501_125_dialog_content = "박수라도 칠까?",
  ui_story_1011_10111501_126_dialog_content = "파이팅... 파이팅...",
  ui_story_1011_10111501_127_dialog_content = "오빠, 꼭 이겨!",
  ui_story_1011_10111501_128_dialog_content = "하아? 왜 너네 셋뿐인데?!",
  ui_story_1011_10111501_129_dialog_content = "다들 아무 스릴도 없는 대결에는 관심이 없거든.",
  ui_story_1011_10111501_130_dialog_content = "아니면 그냥 관두지 그래? 렉커.",
  ui_story_1011_10111501_131_dialog_content = "어떻게 관둘 수가 있냐고!",
  ui_story_1011_10111501_132_dialog_content = "오빠, 멋지게 날려버려!",
  ui_story_1011_10111501_133_dialog_content = "좋아! 이브가 보고 싶다면 얼마든지 해야지!",
  ui_story_1011_10111501_134_dialog_content = "자, 어디까지 날려줄까?",
  ui_story_1011_10111501_135_dialog_content = "저기, 대장, 트래블러호 위에서는 안 싸우면 안 될까?",
  ui_story_1011_10111501_136_dialog_content = "뭐, 됐어. 적으면 적은 대로 좋지.",
  ui_story_1011_10111501_137_dialog_content = "네놈을 이긴 뒤에 내가 이 용맹한 싸움을 모두에게 들려주면 되니까!",
  ui_story_1011_10111501_138_dialog_content = "하하, 어디 해 봐라──",
  ui_story_1011_10111501_139_dialog_content = "<color=#e8d9bb>쿠우웅──!</color>",
  ui_story_1011_10111501_140_dialog_content = "으아아아아악!",
  ui_story_1011_10111501_141_dialog_content = "뭐야?!",
  ui_story_1011_10111501_142_dialog_content = "보프, 멋대로 트래블러호를 움직이면 어떡해?!",
  ui_story_1011_10111501_143_dialog_content = "대장, 나 여기 있어.",
  ui_story_1011_10111501_144_dialog_content = "트래블러호 위에는 대장 말고는 아무도 없어.",
  ui_story_1011_10111501_145_dialog_content = "하아? 뭐가 어떻게 된 거야?!",
  ui_story_1011_10111501_146_dialog_content = "어이, 사메야마! 도망칠 생각이냐!",
  ui_story_1011_10111501_147_dialog_content = "누가 도망친다는 거냐! 내가 아니라──",
  ui_story_1011_10111501_148_dialog_content = "<color=#e8d9bb>쿠우웅──!</color>",
  ui_story_1011_10111501_149_dialog_content = "으아아아아아악! 가속한다아아아!",
  ui_story_1011_10111501_150_dialog_content = "오, 생각보다 볼만한데?",
  ui_story_1011_10111501_151_dialog_content = "오빠가 도망갔어. 오빠 겁쟁이.",
  ui_story_1011_10111501_152_dialog_content = "아니라고! 트래블러호가 알아서 움직이고 있다고!",
  ui_story_1011_10111501_153_dialog_content = "보고만 있지 말고 빨리 도와줘!",
  ui_story_1011_10111501_154_dialog_content = "어이!",
  ui_story_1011_10111501_155_dialog_content = "<color=#e8d9bb>푸드덕, 푸드덕──</color>",
  ui_story_1011_10111501_156_dialog_content = "안녕하세요, 이스타반 씨한테 온 긴급 편지예요. 여기 사인해 주세요!",
  ui_story_1011_10111501_157_dialog_content = "알겠어요. 저한테 주시면 돼요.",
  ui_story_1011_10111501_158_dialog_content = "잠깐만요, 누가 보낸 거죠?",
  ui_story_1011_10111501_159_dialog_content = "봉투에는 아무것도 안 적혀 있는데요.",
  ui_story_1011_10111501_160_dialog_content = "아, 그게 말이죠.",
  ui_story_1011_10111501_161_dialog_content = "이스타반 씨한테 보내는 긴급 편지에는 보낸 사람을 쓸 필요가 없어요.",
  ui_story_1011_10111501_162_dialog_content = "이스타반 씨가 그렇게 해달라고 하셨거든요.",
  ui_story_1011_10111501_163_dialog_content = "그렇군요, 알겠어요.",
  ui_story_1011_10111501_164_dialog_content = "고마워요.",
  ui_story_1011_10111501_165_dialog_content = "그럼 편지는 잘 전했네요. 항상 쿠리어 길드를 이용해 주셔서 감사합니다! 안녕히 계세요!",
  ui_story_1011_10111501_166_dialog_content = "안녕하심니꺼! 이스타반 씨한테 온 긴급 편지라예. 여다 싸인해 주이소!",
  ui_story_1011_10111501_167_dialog_content = "알겠어요. 또 온 건가요.",
  ui_story_1011_10111501_168_dialog_content = "그라고 거 봉투에 이름이 읎는 기는 그러이까...",
  ui_story_1011_10111501_169_dialog_content = "이스타반 씨가 그렇게 해달라고 하신 거죠?",
  ui_story_1011_10111501_170_dialog_content = "아! 맞심더! 아시믄 됐심더!",
  ui_story_1011_10111501_171_dialog_content = "저한테 주시면 돼요. 고생했어요.",
  ui_story_1011_10111501_172_dialog_content = "개않심더! 그라모...",
  ui_story_1011_10111501_173_dialog_content = "으아아아아아아아! 늦겠어, 늦겠어, 늦겠어!",
  ui_story_1011_10111501_174_dialog_content = "많이 안 늦었겠지? 월급 안 깎이겠지?",
  ui_story_1011_10111501_175_dialog_content = "아, 도브 씨도 오셨심꺼!",
  ui_story_1011_10111501_176_dialog_content = "어라, 트위티! 너도...?",
  ui_story_1011_10111501_177_dialog_content = "뭐, 됐어. 나중에 얘기하자. 벌써 늦었다고...",
  ui_story_1011_10111501_178_dialog_content = "안녕하세요, 이스타반 씨한테 온 긴급 편지예요. 여기 사인해 주세요!",
  ui_story_1011_10111501_179_dialog_content = "아버님, 조금 전에 쿠리어 길드에서 긴급 편지를 몇 통이나 전해줬는데요.",
  ui_story_1011_10111501_180_dialog_content = "긴급 편지라, 어디 볼까.",
  ui_story_1011_10111501_181_dialog_content = "네.",
  ui_story_1011_10111501_182_dialog_content = "긴급 편지? 게다가 한 번에 이렇게 온 건가요?",
  ui_story_1011_10111501_183_dialog_content = "도대체 어디서 무슨 일이 생겼길래 참새들이 이렇게 움직일까요?",
  ui_story_1011_10111501_184_dialog_content = "......",
  ui_story_1011_10111501_185_dialog_content = "아무래도 움직이고 있는 건 참새뿐만이 아닌 것 같군.",
  ui_story_1011_10111501_186_dialog_content = "샤엘, 최대한 많은 사람을 보내서 백야성의 동향을 감시해라.",
  ui_story_1011_10111501_187_dialog_content = "병사 한 명이 검을 뽑았다는 소식조차도 내게 가장 먼저 알려야 한다.",
  ui_story_1011_10111501_188_dialog_content = "후훗, 그거야 쉽죠. 지금 바로 사람을 보낼게요.",
  ui_story_1011_10111501_189_dialog_content = "근데 다른 준비는 필요 없나요?",
  ui_story_1011_10111501_190_dialog_content = "백야성이 움직이고 난 뒤에 움직이면 늦을 수도 있잖아요.",
  ui_story_1011_10111501_191_dialog_content = "지금 이대로면 된다.",
  ui_story_1011_10111501_192_dialog_content = "우린 백야성 아래 숨어서 살아가고 있다.",
  ui_story_1011_10111501_193_dialog_content = "그림자는 그림자로서의 태도를 보여야지.",
  ui_story_1011_10111501_194_dialog_content = "<color=#e8d9bb>똑똑똑...</color>",
  ui_story_1011_10111501_195_dialog_content = "빅토리아 님, 괜찮으십니까?",
  ui_story_1011_10111501_196_dialog_content = "......",
  ui_story_1011_10111501_197_dialog_content = "이런, 역시 반응이 없어.",
  ui_story_1011_10111501_198_dialog_content = "안으로 들어가 볼까요?",
  ui_story_1011_10111501_199_dialog_content = "빅토리아 님의 아까 모습... 정말 걱정이 돼요.",
  ui_story_1011_10111501_200_dialog_content = "안 됩니다... 절대로 안 됩니다...",
  ui_story_1011_10111501_201_dialog_content = "허락 없이 멋대로 빅토리아 님의 방에 들어가는 것은 얼마나 외람된 일입니까...",
  ui_story_1011_10111501_202_dialog_content = "그렇게까지 걱정할 필요 있어? 그냥 피곤해서 그런 걸지도 모르잖아.",
  ui_story_1011_10111501_203_dialog_content = "너흰 빅토리아 씨 따라다니는 거 말고는 할 일 없어?",
  ui_story_1011_10111501_204_dialog_content = "다시 한번 노크해볼까.",
  ui_story_1011_10111501_205_dialog_content = "<color=#e8d9bb>똑똑똑...</color>",
  ui_story_1011_10111501_206_dialog_content = "빅토리아 님, 무슨 일 있으십니까?",
  ui_story_1011_10111501_207_dialog_content = "......",
  ui_story_1011_10111501_208_dialog_content = "음, 아무래도...",
  ui_story_1011_10111501_209_dialog_content = "파우스트, 들어와.",
  ui_story_1011_10111501_210_dialog_content = "!!!",
  ui_story_1011_10111501_211_dialog_content = "너 혼자면 돼. 녀석을 방해하고 싶지 않으니까.",
  ui_story_1011_10111501_212_dialog_content = "예.",
  ui_story_1011_10111501_213_dialog_content = "<color=#e8d9bb>끼이익──</color>",
  ui_story_1011_10111501_214_dialog_content = "빅토리아 님...",
  ui_story_1011_10111501_215_dialog_content = "봐.",
  ui_story_1011_10111501_216_dialog_content = "핏빛 성전에서 붉은 피가 흐르고 있어.",
  ui_story_1011_10111501_217_dialog_content = "아까부터 지금까지 계속 말이야.",
  ui_story_1011_10111501_218_dialog_content = "이건... 새로운 계시입니까?",
  ui_story_1011_10111501_219_dialog_content = "평소보다 시간이 더 걸리는 것 같아.",
  ui_story_1011_10111501_220_dialog_content = "벌써 피가 방의 카펫을 전부 적셨는데, 성전에는 한 마디도 나타나지 않았어.",
  ui_story_1011_10111501_221_dialog_content = "대체 무엇이 「진리」까지 입을 다물게 만드는 걸까?",
  ui_story_1011_10111501_222_dialog_content = "어째서 이런...",
  ui_story_1011_10111501_223_dialog_content = "지금까지 빅토리아 님의 일생에서 이런 일이 있었습니까?",
  ui_story_1011_10111501_224_dialog_content = "쉿──",
  ui_story_1011_10111501_225_dialog_content = "올 거야.",
  ui_story_1011_10111501_226_dialog_content = "드디어 왔어.",
  ui_story_1011_10111501_227_dialog_content = "!!!",
  ui_story_1011_10111501_228_dialog_content = "「■■」",
  ui_story_1011_10111501_229_dialog_content = "「■■■■■■■■■■」",
  ui_story_1011_10111501_230_dialog_content = "?!",
  ui_story_1011_10111501_231_dialog_content = "한 번도 본 적 없는 글씨로군요, 빅토리아 님, 이건 대체...",
  ui_story_1011_10111501_232_dialog_content = "아, 핏빛 성전.",
  ui_story_1011_10111501_233_dialog_content = "네 그 계시는 우리에게 보여주기 위한 게 아니구나. 그렇지?",
  ui_story_1011_10111501_234_dialog_content = "이 문자를 아는 자, 계시를 받을 수 있는 자는 대체 누구일까...",
  ui_story_1011_10111501_235_dialog_content = "우와, 엄청 눈부셔.",
  ui_story_1011_10111501_236_dialog_content = "어라? 근데 아까 분명히 해가 졌잖아?",
  ui_story_1011_10111501_237_dialog_content = "저건 태양이 아냐!",
  ui_story_1011_10111501_238_dialog_content = "바닷가의... 등대 같은데?",
  ui_story_1011_10111501_239_dialog_content = "그런 것 같아!",
  ui_story_1011_10111501_240_dialog_content = "근데 등대가 원래 이렇게 밝았나?",
  ui_story_1011_10111501_241_dialog_content = "노비오, 여왕 폐하께선 윈터 팰리스에 계신가요?",
  ui_story_1011_10111501_242_dialog_content = "네, 계십니다.",
  ui_story_1011_10111501_243_dialog_content = "땀을 많이 흘린 것 같군요. 무슨 일이 있었던 것입니까?",
  ui_story_1011_10111501_244_dialog_content = "등대가 이상하게 밝게 빛나고 있어요...",
  ui_story_1011_10111501_245_dialog_content = "북방을 지키는 힘에 무슨 문제가 생긴 건 아닌지 걱정이 돼요.",
  ui_story_1011_10111501_246_dialog_content = "그렇군요. 그건 확실히 중대한 일이로군요.",
  ui_story_1011_10111501_247_dialog_content = "자, 함께 여왕 폐하를 뵈러 가도록 하죠.",
  ui_story_1011_10111501_248_dialog_content = "<color=#e8d9bb>뚜벅... 뚜벅... 뚜벅...</color>",
  ui_story_1011_10111501_249_dialog_content = "폐하, 나시리스가 폐하를 뵈러 왔습니다.",
  ui_story_1011_10111501_250_dialog_content = "나시리스 말로는...",
  ui_story_1011_10111501_251_dialog_content = "그것이 보고 있다...",
  ui_story_1011_10111501_252_dialog_content = "네...?",
  ui_story_1011_10111501_253_dialog_content = "그것이 보고 있다... 그것이... 보고...",
  ui_story_1011_10111501_254_dialog_content = "폐하께선 주무시고 계신 것 같은데요.",
  ui_story_1011_10111501_255_dialog_content = "깨워드리는 게 좋을까요?",
  ui_story_1011_10111501_256_dialog_content = "등대에 문제가 생겼다면, 폐하께서는 분명히 가장 먼저 알고 싶어 하실 겁니다.",
  ui_story_1011_10111501_257_dialog_content = "폐하의 귓가에 말씀해 주시지요.",
  ui_story_1011_10111501_258_dialog_content = "알겠어요.",
  ui_story_1011_10111501_259_dialog_content = "여왕 폐하.",
  ui_story_1011_10111501_260_dialog_content = "지금 등대가 태양처럼 환하게 빛나고 있어요.",
  ui_story_1011_10111501_261_dialog_content = "다들 겁에 질려 있어요. 대체 무엇이 북방의 밤을 빼앗으려는 걸까요?",
  ui_story_1011_10111501_262_dialog_content = "그것이 우리를 보고 있다... 하늘 위에서...",
  ui_story_1011_10111501_263_dialog_content = "탑이... 머나먼 높은 곳에 있는 눈이...",
  ui_story_1011_10111501_264_dialog_content = "여왕 폐하?",
  ui_story_1011_10111501_265_dialog_content = "도망쳐라... 몸을 숨겨라... 되도록 멀리...",
  ui_story_1011_10111501_266_dialog_content = "뭇 산들의 꼭대기로... 바다의 외딴섬으로...",
  ui_story_1011_10111501_267_dialog_content = "노비오 씨, 여왕 폐하의 안색이 뭔가 이상해요.",
  ui_story_1011_10111501_268_dialog_content = "그렇네요.",
  ui_story_1011_10111501_269_dialog_content = "여왕 폐하, 일어나 주십시오.",
  ui_story_1011_10111501_270_dialog_content = "그곳에서 멀리 떠나라...",
  ui_story_1011_10111501_271_dialog_content = "탑...",
  ui_story_1011_10111501_272_dialog_content = "「탑의 도시」에서... 멀어져라...",
  ui_story_1011_10111501_273_dialog_content = "여왕 폐하...",
  ui_story_1011_10111501_274_dialog_content = "여왕 폐하!",
  ui_story_1011_10111501_275_dialog_content = "......",
  ui_story_1011_10111501_276_dialog_content = "폐하...",
  ui_story_1011_10111501_277_dialog_content = "<color=#FFB400>PlayerName, 그대였구나.</color>",
  ui_story_1011_10111501_278_dialog_content = "!!!",
  ui_story_1011_10111501_279_dialog_content = "아, 아니에요. 여왕 폐하! 전...",
  ui_story_1011_10111501_280_dialog_content = "어?",
  ui_story_1011_10111501_281_dialog_content = "어떻게... 어떻게 이런 일이...",
  ui_story_1011_10111501_282_dialog_content = "PlayerName, 왜 그래?",
  ui_story_1011_10111501_283_dialog_content = "내가... 대체 어떻게 된 거야...?",
  ui_story_1011_10111501_284_dialog_content = "...이렇게 말하면 믿기지 않을지도 모르겠지만...",
  ui_story_1011_10111501_285_dialog_content = "방금, 난 확실히 봤어...",
  ui_story_1011_10111501_286_dialog_content = "뭘 봤는데?",
  ui_story_1011_10111501_287_dialog_content = "<color=#FFB400>온 세계</color>가 보였어.",
  ui_story_1012_10120101_1_dialog_content = "방금 그 순간, 온 세계가 보였어.",
  ui_story_1012_10120101_2_dialog_content = "일루미나부터 백야성.",
  ui_story_1012_10120101_3_dialog_content = "북방부터 레디젤 사막까지.",
  ui_story_1012_10120101_4_dialog_content = "그 한순간에 모든 게 눈에 들어왔어.",
  ui_story_1012_10120101_5_dialog_content = "마치 내가 나 자신이 아니라...",
  ui_story_1012_10120101_6_dialog_content = "귀환의 탑 그 자체인 것처럼.",
  ui_story_1012_10120101_7_dialog_content = "이상해. 아이테르 일족이 이런 과학 기술을 가지고 있다는 기록은 없었어.",
  ui_story_1012_10120101_8_dialog_content = "그건 나중에 생각하자. 지금 중요한 건 그게 아니야.",
  ui_story_1012_10120101_9_dialog_content = "만약 이 기계가 바로 이 기지의 코어라면, 바이스를 구할 방법이 여기 있을 거야!",
  ui_story_1012_10120101_10_dialog_content = "맞아... 에이드 브레인, 「의식 소실」 상태에서\n소생한 사례에 대한 자세한 정보를 조사해 줘!",
  ui_story_1012_10120101_11_dialog_content = "권한 인증 통과. 조사 보고서 생성 중.",
  ui_story_1012_10120101_12_dialog_content = "「의식 소실」 상태에 빠진 실험체를 <color=#FFB400>「화음 연결」</color> 장치 내부에 투입하고,\n「동조」 기능을 적용해 테스트를 진행했습니다.",
  ui_story_1012_10120101_13_dialog_content = "실험 결과 예상 밖의 긍정적인 치료 효과가 나타났습니다.",
  ui_story_1012_10120101_14_dialog_content = "실험체의 의식에서 소생 현상이 관측되었으며, 이와 동시에 신체에도 변화가 발행했습니다.",
  ui_story_1012_10120101_15_dialog_content = "신체 변화로 인한 부작용은 아직 명확히 확인되지 않았습니다.",
  ui_story_1012_10120101_16_dialog_content = "최종적으로 실험체는 「동조」에 성공해 「의식 소실」 상태에서 소생했습니다.",
  ui_story_1012_10120101_17_dialog_content = "「화음 연결」이라니...",
  ui_story_1012_10120101_18_dialog_content = "그게 뭔데?",
  ui_story_1012_10120101_19_dialog_content = "「화음 연결」 관련 정보를 검색 중입니다.",
  ui_story_1012_10120101_20_dialog_content = "......",
  ui_story_1012_10120101_21_dialog_content = "............",
  ui_story_1012_10120101_22_dialog_content = "#*%$&$#&*!",
  ui_story_1012_10120101_23_dialog_content = "에이드 브레인?!",
  ui_story_1012_10120101_24_dialog_content = "잘못된 프로세스가 종료되었습니다.",
  ui_story_1012_10120101_25_dialog_content = "「화음 연결」과 관련된 실험 데이터는 화음 구역에 저장되어 있으며,\n평소에는 외부인에게 개방되지 않습니다.",
  ui_story_1012_10120101_26_dialog_content = "보안이 그렇게 엄중하단 말이야?",
  ui_story_1012_10120101_27_dialog_content = "아무래도 아주 중요한 시설인 모양이네.",
  ui_story_1012_10120101_28_dialog_content = "어쩌면 이 하얀 탑에서 가장 중요한 건 서클 시스템이 아니라...",
  ui_story_1012_10120101_29_dialog_content = "바로 저 「화음 연결」일지도 몰라.",
  ui_story_1012_10120101_30_dialog_content = "에이드 브레인, 화음 구역에 관한 자세한 정보를 찾아줄 수 있어?",
  ui_story_1012_10120101_31_dialog_content = "에이드 브레인과 화음 구역의 연결이 끊겼습니다. 데이터를 읽을 수 없습니다.",
  ui_story_1012_10120101_32_dialog_content = "해당 시설에 대한 로컬 데이터베이스의 설명은 다음과 같습니다.",
  ui_story_1012_10120101_33_dialog_content = "「화음 연결」은 부상을 치유할 수 있으며,\n부분적인 신체 개조를 통해 오로리안의 잠재 능력을 끌어낼 수 있습니다.",
  ui_story_1012_10120101_34_dialog_content = "전투에서 아이테르와 더 뛰어난 팀워크를 구축할 수 있게 합니다.",
  ui_story_1012_10120101_35_dialog_content = "뭔가... 일종의 개조 장치 같은데?",
  ui_story_1012_10120101_36_dialog_content = "아니지, 뭔가 이상해. 과거의 아이테르가 오로리안을 적으로 여겼다면...",
  ui_story_1012_10120101_37_dialog_content = "왜 여기 오로리안을 개조할 수 있는 장치가 있는 건데?\n그것도 아이테르와의 전투 팀워크를 높이는 개조라니?",
  ui_story_1012_10120101_38_dialog_content = "맞아. 그렇게 보니까 정말 이상하잖아.",
  ui_story_1012_10120101_39_dialog_content = "PlayerName, 이 장치의 기록을 무턱대고 믿으면 안 되겠어.",
  ui_story_1012_10120101_40_dialog_content = "우선은 이 「화음 연결」이 대체 무슨 용도인 건지,\n바이스한테 해를 끼칠 수도 있는지 확실하게 알아내야 해.",
  ui_story_1012_10120101_41_dialog_content = "응, 알겠어.",
  ui_story_1012_10120101_42_dialog_content = "에이드 브레인, 「화음 연결」의 부작용에 대해 이야기해 줄래?",
  ui_story_1012_10120101_43_dialog_content = "바이스한테 나쁜 영향을 줄 가능성도 있어?",
  ui_story_1012_10120101_44_dialog_content = "에이드 브레인과 화음 구역의 연결이 끊겼습니다. 데이터를 읽을 수 없습니다.",
  ui_story_1012_10120101_45_dialog_content = "연결은 아까 전부터 끊겼다고 했잖아. 다시 고쳐볼 생각은 안 한 거야?",
  ui_story_1012_10120101_46_dialog_content = "에이드 브레인은 아이테르에게 도움을 제공하는 시스템일 뿐입니다.",
  ui_story_1012_10120101_47_dialog_content = "에이드 브레인의 권한 밖인 수리 임무를 강요하는 것은 금지되어 있습니다.",
  ui_story_1012_10120101_48_dialog_content = "아무래도 정보를 듣는 건 무리일 것 같네...",
  ui_story_1012_10120101_49_dialog_content = "어쩔 수 없네.",
  ui_story_1012_10120101_50_dialog_content = "위험할 수도 있겠지만, 지금은 시도해 보는 수밖에 없어.",
  ui_story_1012_10120101_51_dialog_content = "바이스가 이렇게 된 건 나 때문이야.",
  ui_story_1012_10120101_52_dialog_content = "그러니까 내가 책임져야 해...",
  ui_story_1012_10120101_53_dialog_content = "......",
  ui_story_1012_10120101_54_dialog_content = "그 장치를 나한테 먼저 사용해 보자.",
  ui_story_1012_10120101_55_dialog_content = "사용해 보고 문제가 없다면 그 장치로 바이스를 구하는 거야.",
  ui_story_1012_10120101_56_dialog_content = "하지만 문제가 생긴다면... 뒷일은 카렌 너한테 부탁할게.\n바이스를 데리고 일루미나로 돌아가 줘.",
  ui_story_1012_10120101_57_dialog_content = "마음은 기특하지만 잊지 마. 넌 오로리안이 아니라 아이테르야.",
  ui_story_1012_10120101_58_dialog_content = "바이스는 내 친구이기도 해. 바이스를 구하기 위해서라면 나도 힘을 보탤 거야.",
  ui_story_1012_10120101_59_dialog_content = "저 장치를 써 보는 수밖에 없다면, 너보다는 나한테 시험하는 게 맞을 거야.",
  ui_story_1012_10120101_60_dialog_content = "에이드 브레인, 날 장치가 있는 곳까지 데려가 줘.",
  ui_story_1012_10120101_61_dialog_content = "화음 구역으로 이동하는 경로를 계산 중입니다...",
  ui_story_1012_10120101_62_dialog_content = "화음 구역으로 통하는 대부분의 통로가 파괴된 상태입니다.\n추방 구역으로 우회해 이동해야 합니다.",
  ui_story_1012_10120101_63_dialog_content = "화음 구역과의 연결이 중단되어 에이드 브레인이 직접 정문을 열 수 없습니다.",
  ui_story_1012_10120101_64_dialog_content = "최근 설정에 따라 관리자를 위해 접근 통제 시스템 개방 키를 생성했습니다.",
  ui_story_1012_10120101_65_dialog_content = "이 설정의 마지막 변경자는 프란츠 선생님입니다.",
  ui_story_1012_10120101_66_dialog_content = "또 그 프란츠 선생님이라는 사람이야?",
  ui_story_1012_10120101_67_dialog_content = "그 사람, 대체 여기서 뭘 꾸몄던 거지?",
  ui_story_1012_10120101_68_dialog_content = "왠지 무슨 음모를 꾸몄거나 한 건 아닐 것 같다는 생각이 들어.",
  ui_story_1012_10120101_69_dialog_content = "오히려 나중에 이곳에 올 사람을 위해서 준비를 했던 것 같아.",
  ui_story_1012_10120101_70_dialog_content = "바로... 우릴 위해서 말이야.",
  ui_story_1012_10120101_71_dialog_content = "관리자는 에이드 브레인을 따라 화음 구역으로 이동해 주십시오.\n화음 구역의 접근 통제 시스템을 해제하겠습니다.",
  ui_story_1012_10120101_72_dialog_content = "추방 구역이 화음 구역이랑 연결돼 있다니...",
  ui_story_1012_10120101_73_dialog_content = "왠지 좋은 곳은 아닌 것 같은데...",
  ui_story_1012_10120101_74_dialog_content = "좋든 안 좋든, 그 추방 구역이라는 곳이 지금 우리의 유일한 희망이야.",
  ui_story_1012_10120101_75_dialog_content = "자, 바이스를 데리고 화음 구역으로 가자.",
  ui_story_1012_10120101_76_dialog_content = "에이드 브레인, 길 안내를 부탁해.",
  ui_story_1012_10120101_77_dialog_content = "알겠습니다. 최선을 다해 안내해 드리겠습니다.",
  ui_story_1012_10120101_78_dialog_content = "「화음 연결」이라...",
  ui_story_1012_10120101_79_dialog_content = "그게 바로 이 지하 기지에 숨겨져 있던 기술인 건가.",
  ui_story_1012_10120101_80_dialog_content = "오로리안의 육체를 개조할 수 있다니...",
  ui_story_1012_10120101_81_dialog_content = "마침 내 마음에 쏙 드는걸.",
  ui_story_1012_10120101_82_dialog_content = "『노라 님, 그 일루미나의 인간이 우리를 바짝 뒤쫓고 있습니다.』",
  ui_story_1012_10120101_83_dialog_content = "『놈은... 너무 강합니다. 저희가 막기에는 역부족입니다.』",
  ui_story_1012_10120101_84_dialog_content = "일루미나 사람들은 말이지, 전부 괴물이거든.",
  ui_story_1012_10120101_85_dialog_content = "막을 수 없다면 길을 잘못 들게 만들 방법이나 찾아봐.",
  ui_story_1012_10120101_86_dialog_content = "그 야만적인 인간이 저 귀중한 기술에 접근하게 두면 안 되지.",
  ui_story_1012_10120101_87_dialog_content = "그 인간의 머릿속에는 전투와 파괴밖에 없으니까.",
  ui_story_1012_10120101_88_dialog_content = "『알겠습니다.』",
  ui_story_1012_10120101_89_dialog_content = "이리돈, 날 막아서지 마라.",
  ui_story_1012_10120101_90_dialog_content = "원로원은 다모클레스가 어째서 가동하게 되었는지 알 권리가 있다.",
  ui_story_1012_10120101_91_dialog_content = "아무도 제어실에 들어가지 못하게 하라는 성주님의 명령이 있었습니다.",
  ui_story_1012_10120101_92_dialog_content = "성주님의 명령은 곧 백야성의 법입니다. 잘 알고 계실 텐데요.",
  ui_story_1012_10120101_93_dialog_content = "아우토 님, 원로원의 일원이라 해도 법률의 제약을 받습니다.",
  ui_story_1012_10120101_94_dialog_content = "원로원의 권리도 백야성 법률의 일부다.",
  ui_story_1012_10120101_95_dialog_content = "이리돈 대심판관, 이 이야기는 꼭 해야겠군. 그대는 지금...",
  ui_story_1012_10120101_96_dialog_content = "다모클레스가 멈춘 건가?",
  ui_story_1012_10120101_97_dialog_content = "(성주님과 사천사들이 성공한 걸까요?)",
  ui_story_1012_10120101_98_dialog_content = "솔라드 성주...",
  ui_story_1012_10120101_99_dialog_content = "말해봐라. 제어실 안에서 무슨 일이 있었고, 다모클레스가 갑자기 가동된 이유는 뭐지?",
  ui_story_1012_10120101_100_dialog_content = "진정해라, 아우토. 조급해할 것 없다.",
  ui_story_1012_10120101_101_dialog_content = "다모클레스가 그 어떤 조짐도 없이 스스로 가동된 것은 사실이다.\n허나 이미 내가 정지시켰다.",
  ui_story_1012_10120101_102_dialog_content = "지금은 다시 백야성의 제어하에 있다.",
  ui_story_1012_10120101_103_dialog_content = "스스로 가동되었다...? 그게 어떻게 가능하지?",
  ui_story_1012_10120101_104_dialog_content = "다모클레스는 강력한 병기지만, 그래도 한낱 병기일 뿐이다.",
  ui_story_1012_10120101_105_dialog_content = "다루는 자 없이 어찌 스스로 가동될 수 있다는 것이냐?",
  ui_story_1012_10120101_106_dialog_content = "그 전에 반드시 짚고 넘어갈 문제가 있다, 아우토.",
  ui_story_1012_10120101_107_dialog_content = "다모클레스가 백야성의 병기인 것은 사실이다. 허나...",
  ui_story_1012_10120101_108_dialog_content = "그렇다 하여 다모클레스가 백야성의 소유물인 것은 아니지.",
  ui_story_1012_10120101_109_dialog_content = "......",
  ui_story_1012_10120101_110_dialog_content = "엄밀히 따지면 우리가 본 적도 없는 고대인들이 남긴 유물,\n즉, 백야성이 가장 배척하는 종류의 물건이지 않은가.",
  ui_story_1012_10120101_111_dialog_content = "자신의 것이 아닌 미지의 힘은 그 자체로 통제를 잃을 가능성을 수반하기 마련이다.",
  ui_story_1012_10120101_112_dialog_content = "그럼 이번 통제 불능의 원인을 밝혀야 하니, 다모클레스의 유지와 보수를\n담당하는 기술자들에게 전면적인 검사를 명하겠다.",
  ui_story_1012_10120101_113_dialog_content = "내일까지는 결과가 나오겠지.",
  ui_story_1012_10120101_114_dialog_content = "그러한가. 수고를 끼쳤군.",
  ui_story_1012_10120101_115_dialog_content = "당연한 일이다. 가장 중요한 건 백야성의 안전과 번영을 지키는 것이니까.",
  ui_story_1012_10120101_116_dialog_content = "......",
  ui_story_1012_10120101_117_dialog_content = "(다모클레스여...)",
  ui_story_1012_10120101_118_dialog_content = "(그대가 가리킨 방향은...)",
  ui_story_1012_10120101_119_dialog_content = "......",
  ui_story_1012_10120101_120_dialog_content = "라파엘.",
  ui_story_1012_10120101_121_dialog_content = "아, 네...넵!",
  ui_story_1012_10120101_122_dialog_content = "분부하실 일이 있으신가요?",
  ui_story_1012_10120101_123_dialog_content = "가서 베르타를 찾아라. 기사들을 데리고 서둘러 헤븐즈 밸리로 향하라 전하도록.",
  ui_story_1012_10120101_124_dialog_content = "알겠습니다. 하지만 베르타를 보내시는 이유가 있나요?",
  ui_story_1012_10120101_125_dialog_content = "임기응변이다.",
  ui_story_1012_10120101_126_dialog_content = "네...?!",
  ui_story_1012_10120101_127_dialog_content = "가 보거라.",
  ui_story_1012_10120101_128_dialog_content = "아, 알겠습니다!",
  ui_story_1012_10120101_129_dialog_content = "폐하...",
  ui_story_1012_10120101_130_dialog_content = "나는 괜찮다.",
  ui_story_1012_10120101_131_dialog_content = "걱정을 끼쳐 미안하구나.",
  ui_story_1012_10120101_132_dialog_content = "말씀드릴 일이 있어요. 등대에 문제가 생겨서...\n전대미문의 강렬한 빛을 발산하고 있어요.",
  ui_story_1012_10120101_133_dialog_content = "알겠다.",
  ui_story_1012_10120101_134_dialog_content = "그 일은 내가 처리하마. 너희는 마음 쓰지 말거라.",
  ui_story_1012_10120101_135_dialog_content = "네...",
  ui_story_1012_10120101_136_dialog_content = "폐하, 잠들어 계셨을 때 어렴풋이 그 아이테르의 이름을 부르셨습니다.",
  ui_story_1012_10120101_137_dialog_content = "이는 결코 우연한 일이 아니겠지요.",
  ui_story_1012_10120101_138_dialog_content = "......",
  ui_story_1012_10120101_139_dialog_content = "그가 높은 탑 위에 올라서 세상을 내려다보는 모습을 보았다.",
  ui_story_1012_10120101_140_dialog_content = "그 탑은 나조차도 가늠할 수 없는 존재였지.",
  ui_story_1012_10120101_141_dialog_content = "오래전에 지어졌고, 근원 또한 알 수 없었다.",
  ui_story_1012_10120101_142_dialog_content = "그리고 그 탑과 북방을 수호하는 등대는 서로 물과 불의 관계다.",
  ui_story_1012_10120101_143_dialog_content = "그 아이테르가... 북방의 적이 된 것입니까?",
  ui_story_1012_10120101_144_dialog_content = "아니다. 그에게서는 조금의 적의도 느껴지지 않았다.",
  ui_story_1012_10120101_145_dialog_content = "그는 언제나처럼 선량한 마음만을 가지고 있었지.",
  ui_story_1012_10120101_146_dialog_content = "그러나 앞으로 그가 전례 없을 고난을 겪으리라는 것을 감지할 수 있었다.",
  ui_story_1012_10120101_147_dialog_content = "더욱이 그 고난은 온 아스트라의 운명에 영향을 미칠 것이다.",
  ui_story_1012_10120101_148_dialog_content = "북방은 지금 선택의 기로에 서 있다.",
  ui_story_1012_10120101_149_dialog_content = "마차를 준비하거라.",
  ui_story_1012_10120101_150_dialog_content = "헤븐즈 밸리로 가겠다. 내가 이 고난에 전환점을 만들어 줄 것이다.",
  ui_story_1012_10120101_151_dialog_content = "예.",
  ui_story_1012_10120101_152_dialog_content = "폐하, 마차가 준비되었습니다.",
  ui_story_1012_10120101_153_dialog_content = "알겠다, 지금 바로 가마.",
  ui_story_1012_10120101_154_dialog_content = "폐하, 헤븐즈 밸리로 가시는 길에 동행하고 싶어요.",
  ui_story_1012_10120101_155_dialog_content = "아니 된다. 그대는 북방에 남아야 한다.",
  ui_story_1012_10120101_156_dialog_content = "내가 자리를 비운 동안에도 암귀의 동향에 주의를 기울이고, 북방의 수호에 온 힘을 다하거라.",
  ui_story_1012_10120101_157_dialog_content = "다른 일들은 내가 자리를 비웠다 하여 처리를 미루지 말고, 평소처럼 행하면 된다.",
  ui_story_1012_10120101_158_dialog_content = "이번에는 티아라가 나와 동행할 것이다.",
  ui_story_1012_10120101_159_dialog_content = "......",
  ui_story_1012_10120101_160_dialog_content = "티아라, 명령에 따라 모시러 왔습니다.",
  ui_story_1012_10120101_161_dialog_content = "당신이었나요...",
  ui_story_1012_10120101_162_dialog_content = "그럼 폐하를 잘 지켜 드리세요. 북방의 희망이 담긴 불꽃을 반드시 지켜주세요...",
  ui_story_1012_10120101_163_dialog_content = "보, 보고드립니다냥!",
  ui_story_1012_10120101_164_dialog_content = "자난성 곳곳에서 이상한 움직임이 감지되었습니다냥.",
  ui_story_1012_10120101_165_dialog_content = "그로누 연구원장은 지하성 벽 내부에 존재하는 고대 장치의 경보라고 파악하고 있습니다냥.",
  ui_story_1012_10120101_166_dialog_content = "알겠다. 계속해서 자난성 내부의 동향을 조사해라.",
  ui_story_1012_10120101_167_dialog_content = "또한 다른 지하성도 자난성과 같은 상황이 발생했는지 알아보도록.",
  ui_story_1012_10120101_168_dialog_content = "알겠습니다냥!",
  ui_story_1012_10120101_169_dialog_content = "대원수님, 정찰병이 암귀의 특이 동향을 관측했습니다.",
  ui_story_1012_10120101_170_dialog_content = "현재 아스트라 전역의 암귀가 모두 헤븐즈 밸리로 집결 중입니다.",
  ui_story_1012_10120101_171_dialog_content = "알겠다. 모든 지하성의 방어 태세를 유지하고, 계속해서 상황을 주시하도록.",
  ui_story_1012_10120101_172_dialog_content = "네.",
  ui_story_1012_10120101_173_dialog_content = "암귀들의 집결, 헤븐즈 밸리, 게다가 자난성 고대 장치의 이상한 움직임...",
  ui_story_1012_10120101_174_dialog_content = "그 녀석, 또 성가신 일에 말려든 모양이지?",
  ui_story_1012_10120101_175_dialog_content = "훗, 타이밍 한 번 기가 막히는군.",
  ui_story_1012_10120101_176_dialog_content = "보고드립니다.",
  ui_story_1012_10120101_177_dialog_content = "하아... 그래, 이 정도로 끝날 리가 없지.",
  ui_story_1012_10120101_178_dialog_content = "말해라, 또 무슨 일이지?",
  ui_story_1012_10120101_179_dialog_content = "위원회 쪽으로 들어온 보고입니다.\n헤븐즈 밸리에 위치한 하얀 탑 한 채가 갑자기 움직였다고 합니다.",
  ui_story_1012_10120101_180_dialog_content = "또한, 그 뒤로 각지의 고대 기술 유물에도 집단적인 이상 현상이 발생했습니다.",
  ui_story_1012_10120101_181_dialog_content = "흐음?",
  ui_story_1012_10120101_182_dialog_content = "이상이 발생한 유물에는 북방의 등대, 백야성의 다모클레스,\n레디젤 렌치가 장악 중인 트래블러호 등이 포함되어 있으며...",
  ui_story_1012_10120101_183_dialog_content = "위원회에서는 현재 자난성의 이상도 이와 관련이 있을 것으로 보고 있습니다.",
  ui_story_1012_10120101_184_dialog_content = "등대와 다모클레스까지 반응을 보였다고?",
  ui_story_1012_10120101_185_dialog_content = "PlayerName, 대체 거기서 뭘 파낸 거냐...",
  ui_story_1012_10120101_186_dialog_content = "대원수님, 지시를 내려 주십시오.",
  ui_story_1012_10120101_187_dialog_content = "어디 보자...",
  ui_story_1012_10120101_188_dialog_content = "헤븐즈 밸리 인근 지역의 각 소대는 움직임을 보인 하얀 탑 방향으로 이동한다.",
  ui_story_1012_10120101_189_dialog_content = "이동간에 암귀와 조우할 시 현장에서 섬멸전을 전개해 암귀의 집결을 막도록.",
  ui_story_1012_10120101_190_dialog_content = "또한, 지금 즉시 정예 부대 한 팀을 조직하도록. 인솔은 내가 맡는다.\n헤븐즈 밸리로 가서 상황을 파악하겠다.",
  ui_story_1012_10120101_191_dialog_content = "예, 지금 즉시...",
  ui_story_1012_10120101_192_dialog_content = "외람된 말씀이지만, 대원수님께서는 지난번 80호 지하성에서 입으신 부상에서\n아직 완전히 회복되지 않으셨습니다. 직접 출정하시는 것은 바람직하지 않습니다.",
  ui_story_1012_10120101_193_dialog_content = "......",
  ui_story_1012_10120101_194_dialog_content = "아나톨리, 가서 네가 할 일을 해라.",
  ui_story_1012_10120101_195_dialog_content = "예.",
  ui_story_1012_10120101_196_dialog_content = "대원수님, 당부의 말씀을 드리겠습니다.\n대원수님께서는 아직 위원회의 심사를 받고 계십니다.",
  ui_story_1012_10120101_197_dialog_content = "경솔한 행동은 위원회의 평가에 영향을 줄 수 있습니다.",
  ui_story_1012_10120101_198_dialog_content = "종이에 적힌 그까짓 평가 따위가 중요한가, 아니면 일루미나의 안위가 더 중요한가?",
  ui_story_1012_10120101_199_dialog_content = "...일루미나의 안위가 더 중요합니다.",
  ui_story_1012_10120101_200_dialog_content = "그 점을 똑똑히 알고 있다면, 너는 네 소임을 다해라.",
  ui_story_1012_10120101_201_dialog_content = "나 또한 대원수로서 내가 해야 할 일을 하겠다.",
  ui_story_1012_10120101_202_dialog_content = "대원수님의 이번 행동을 보고서에 기록할 것입니다.",
  ui_story_1012_10120101_203_dialog_content = "훗, 얼마든지 쓰라고.",
  ui_story_1012_10120101_204_dialog_content = "내 결정이 옳은지, 그렇지 않은지는 일루미나인들이 평가해 줄 거다.",
  ui_story_1012_10120201_1_dialog_content = "크오오──",
  ui_story_1012_10120201_2_dialog_content = "이게 마지막 한 마리인가?",
  ui_story_1012_10120201_3_dialog_content = "기분이 더럽군.",
  ui_story_1012_10120201_4_dialog_content = "전부 길이나 막는 조무래기들뿐이잖아. 거치적거리긴.",
  ui_story_1012_10120201_5_dialog_content = "노라 그 녀석은 또 어디로 도망친 거냐.",
  ui_story_1012_10120201_6_dialog_content = "쳇... 얼른 찾아야 하는데 말이야.",
  ui_story_1012_10120201_7_dialog_content = "근데 여긴 아까 왔던 곳 아닌가?",
  ui_story_1012_10120201_8_dialog_content = "이 구닥다리 놈들은 대체 왜 가는 곳마다 똑같은 모양으로 만들어 놓은 거야?",
  ui_story_1012_10120201_9_dialog_content = "정말 미궁이 따로 없잖아.",
  ui_story_1012_10120201_10_dialog_content = "설마... 그 암귀들이 일부러 날 여기로 유인한 건가?",
  ui_story_1012_10120201_11_dialog_content = "...노라 녀석의 수작질이 분명하군!",
  ui_story_1012_10120201_12_dialog_content = "날 미궁에 가둬 두겠다 이거냐? 그럼 미궁 채로 부숴서 돌파해 주마.",
  ui_story_1012_10120201_13_dialog_content = "<color=#e8d9bb>깡──!</color>",
  ui_story_1012_10120201_14_dialog_content = "──!",
  ui_story_1012_10120201_15_dialog_content = "쓰읍──",
  ui_story_1012_10120201_16_dialog_content = "아프잖아!",
  ui_story_1012_10120201_17_dialog_content = "이 벽은 대체 뭘 가지고 만들었길래 이렇게 단단한 거냐?!",
  ui_story_1012_10120201_18_dialog_content = "검으로 베어도 흔적 하나 안 남고, 오히려 내 손만 저리잖아.",
  ui_story_1012_10120201_19_dialog_content = "해체해서 지하성에 가져다 두거나 전차에 달면 암귀와 싸울 때 아주 유용하겠어.",
  ui_story_1012_10120201_20_dialog_content = "아무래도 벽을 뚫고 간다는 전략은 힘들겠군.",
  ui_story_1012_10120201_21_dialog_content = "통로를 따라 이동하는 수밖에.",
  ui_story_1012_10120201_22_dialog_content = "뭐, 노라가 그 암귀 무리를 이끌고 있다면,\n그냥 암귀가 많은 곳으로 가면 분명히 노라가 있겠지.",
  ui_story_1012_10120201_23_dialog_content = "시간은 걸리겠지만 조무래기들을 처리하면서 이동하는 게 좋겠군.",
  ui_story_1012_10120201_24_dialog_content = "<color=#e8d9bb>헤븐즈 밸리, 콜로서스 정비 기지 깊은 곳</color>",
  ui_story_1012_10120201_25_dialog_content = "전방의 길목에서 우회전하십시오.",
  ui_story_1012_10120201_26_dialog_content = "이 기지, 진짜 넓네...",
  ui_story_1012_10120201_27_dialog_content = "에이드 브레인이 안내해 주지 않았으면 길을 헤매느라 며칠은 낭비했을 거야.",
  ui_story_1012_10120201_28_dialog_content = "이미 파괴된 상태의 구역들까지 포함한다면, 어쩌면 이 지하 기지는\n헤븐즈 밸리 전체와 비슷한 정도의 면적일지도 몰라.",
  ui_story_1012_10120201_29_dialog_content = "특히 통로처럼 생긴 이런 곳들을 봐.",
  ui_story_1012_10120201_30_dialog_content = "폭과 높이만 봐도 단순히 사람이 지나다니기 위해 만든 게 아니야.",
  ui_story_1012_10120201_31_dialog_content = "처음 봤을 때는 이해가 잘 안됐지만, 지금은 짐작 가는 점이 있어...",
  ui_story_1012_10120201_32_dialog_content = "이 통로들은 아마 콜로서스들의 이동에 사용한 거였을 거야.",
  ui_story_1012_10120201_33_dialog_content = "......",
  ui_story_1012_10120201_34_dialog_content = "그리고 당신들이 해야 할 일은 이 세계에──",
  ui_story_1012_10120201_35_dialog_content = "전쟁을 불러오는 것뿐입니다.",
  ui_story_1012_10120201_36_dialog_content = "아이테르는 콜로서스를 몰고 이곳을 오갔지만, 그건 평화를 위한 게 아니었어...",
  ui_story_1012_10120201_37_dialog_content = "아이테르 일족은... 대체 뭘까?",
  ui_story_1012_10120201_38_dialog_content = "PlayerName.",
  ui_story_1012_10120201_39_dialog_content = "아이테르이기 전에, 너는 너야.",
  ui_story_1012_10120201_40_dialog_content = "뭐...?",
  ui_story_1012_10120201_41_dialog_content = "지금의 바이스와 내게 있어서도, 너는 너일 뿐이고.",
  ui_story_1012_10120201_42_dialog_content = "넌 바이스가 지하에서 구해낸 아이테르야.",
  ui_story_1012_10120201_43_dialog_content = "백야성과 힘을 합쳐 슈모르와 검은 콜로서스에 맞선 동료고.",
  ui_story_1012_10120201_44_dialog_content = "우리와 함께 수없이 많은 모험을 했던 동료야.",
  ui_story_1012_10120201_45_dialog_content = "네가 너이기만 한다면, 네 상냥함과 원칙을 잃지 않는다면,\n우린 네가 아이테르이든 오로리안이든 상관없어.",
  ui_story_1012_10120201_46_dialog_content = "태어난 배경은 스스로가 선택할 수 있는 게 아니잖아. 그러니까 자책하지 마.",
  ui_story_1012_10120201_47_dialog_content = "카렌...",
  ui_story_1012_10120201_48_option_content = "위로해 줘서 고마워.",
  ui_story_1012_10120201_49_dialog_content = "그래도 난 이 일을 끝까지 조사할 거야.",
  ui_story_1012_10120201_50_dialog_content = "나는 최후의 아이테르니까.",
  ui_story_1012_10120201_51_dialog_content = "그리고 어쩌면 난 헤븐즈 밸리의 비밀을 밝힐 수 있는 이 세상에 하나 남은 존재일지도 몰라.",
  ui_story_1012_10120201_52_dialog_content = "만약 아이테르가 과거에 전쟁의 도구였다면, 정말 그런 거라면...",
  ui_story_1012_10120201_53_dialog_content = "헤븐즈 밸리는 물론이고, 아이테르도 이 세상의 위협이 될 가능성이 있어.",
  ui_story_1012_10120201_54_dialog_content = "그러니 숨겨져 있을지도 모르는 위험을 전부 확실히 밝혀내지 못한다면,\n어쩌면 난 영원히 발 뻗고 못 잘 거야.",
  ui_story_1012_10120201_55_dialog_content = "난 내 친구들을 위험하게 만드는 존재가 되고 싶지 않으니까.",
  ui_story_1012_10120201_56_dialog_content = "......",
  ui_story_1012_10120201_57_dialog_content = "자길 너무 몰아세우지는 마.",
  ui_story_1012_10120201_58_dialog_content = "응...",
  ui_story_1012_10120201_59_dialog_content = "걱정 마. 난 나를 잘 알고 있으니까.",
  ui_story_1012_10120201_60_dialog_content = "<size=30>어차피 아무 암귀한테 한 대만 맞아도 날아가 버릴 텐데 뭐...</size>",
  ui_story_1012_10120201_61_dialog_content = "그러니까 너희한테 의지해야 할 때가 되면, 앞으로도 잘 부탁할게...",
  ui_story_1012_10120201_62_dialog_content = "그래. 얼마든지.",
  ui_story_1012_10120201_63_dialog_content = "<color=#e8d9bb>깡──!</color>",
  ui_story_1012_10120201_64_dialog_content = "무슨 소리지?!",
  ui_story_1012_10120201_65_dialog_content = "설마 대형 암귀가 들어온 건가?",
  ui_story_1012_10120201_66_dialog_content = "소리는 여기서 멀지 않은 곳에서 난 것 같아.",
  ui_story_1012_10120201_67_dialog_content = "얼른 앞으로 이동하자.",
  ui_story_1012_10120201_68_dialog_content = "지금은 바이스가 정신을 잃은 상태니까, 전투는 무리야.",
  ui_story_1012_10120201_69_dialog_content = "자, 잠깐만!",
  ui_story_1012_10120201_70_dialog_content = "왜 그래?",
  ui_story_1012_10120201_71_dialog_content = "느껴져... 암귀야!",
  ui_story_1012_10120201_72_dialog_content = "뒤에 있어!",
  ui_story_1012_10120201_73_dialog_content = "크오오──",
  ui_story_1012_10120201_74_dialog_content = "──!",
  ui_story_1012_10120201_75_dialog_content = "대체 어디서 튀어나온 거야?!",
  ui_story_1012_10120201_76_dialog_content = "PlayerName, 지원해줘!",
  ui_story_1012_10120201_77_dialog_content = "알았어!",
  ui_story_1012_10120202_1_dialog_content = "갑자기 암귀가 왜 이렇게 많이 나타난 거지...?",
  ui_story_1012_10120202_2_dialog_content = "게다가 여기 이렇게 오래 있었는데, 방금까지도 전혀 못 느꼈어!",
  ui_story_1012_10120202_3_dialog_content = "여긴 오랜 시간 버려져 있던 곳이잖아.",
  ui_story_1012_10120202_4_dialog_content = "원래 있었든, 아니면 파괴된 이후에 만들어졌든, 비밀 통로가 많이 있을지도 몰라.",
  ui_story_1012_10120202_5_dialog_content = "저 암귀들도 그중 하나를 통해 들어온 거겠지.",
  ui_story_1012_10120202_6_dialog_content = "그럴지도 모르겠네...",
  ui_story_1012_10120202_7_dialog_content = "여긴 지형이 너무 복잡해서 내 감응 능력으로도 모든 암귀를 다 감지하진 못할 거야.",
  ui_story_1012_10120202_8_dialog_content = "더 늦어져선 안 돼. 어서 이동하자!",
  ui_story_1012_10120202_9_dialog_content = "여긴 갈림길도 없으니까, 앞뒤로 포위당해 버린다면 도망도 못 칠 거야.",
  ui_story_1012_10120202_10_dialog_content = "......",
  ui_story_1012_10120202_11_dialog_content = "아이테르의 감응 능력은 확실히 대처하기 쉽지 않네.",
  ui_story_1012_10120202_12_dialog_content = "그래도 암귀는 얼마든지 있으니까.",
  ui_story_1012_10120202_13_dialog_content = "실험의 결과도 무수히 많은 희생을 통해 탄생하는 법이야.",
  ui_story_1012_10120202_14_dialog_content = "방금 그 진동은 뭐지?",
  ui_story_1012_10120202_15_dialog_content = "『 노라 님, 방금 전의 진동은 전의 그 일루미나의 인간이\n벽을 파괴하려 시도하던 중 발생한 것입니다.』",
  ui_story_1012_10120202_16_dialog_content = "『 그 진동 때문에 놀란 아이테르가 감응 능력을 사용해 저희의 존재를 알아챘습니다.』",
  ui_story_1012_10120202_17_dialog_content = "계속해서 발을 묶어 둬.",
  ui_story_1012_10120202_18_dialog_content = "아이테르가 곧 목표에 접근할 거야.",
  ui_story_1012_10120202_19_dialog_content = "그 인간이 내 계획을 망치게 두지 마.",
  ui_story_1012_10120202_20_dialog_content = "시체로라도 그 인간의 길목을 막아 버려.",
  ui_story_1012_10120202_21_dialog_content = "『예, 노라 님!』",
  ui_story_1012_10120202_22_dialog_content = "젠장, 조무래기들이 왜 계속 늘어나는 거냐!",
  ui_story_1012_10120202_23_dialog_content = "날 이곳에 잡아두시겠다? 꿈도 야무지군!",
  ui_story_1012_10120202_24_dialog_content = "전부 다 꺼져──!",
  ui_story_1012_10120202_25_dialog_content = "암귀는 전부 저쪽에서 몰려왔군. 그렇다는 건...",
  ui_story_1012_10120202_26_dialog_content = "노라도 저쪽에 있다는 말이겠지.",
  ui_story_1012_10120202_27_dialog_content = "드디어 꼬리를 잡혔군, 노라.",
  ui_story_1012_10120401_1_dialog_content = "『노, 노라 님!』",
  ui_story_1012_10120401_2_dialog_content = "『일루미나의 괴물이 어디서 힘이 났는지 도저히 막을 수가 없습니다!』",
  ui_story_1012_10120401_3_dialog_content = "『지금 이쪽으로 돌진하고 있습니다!』",
  ui_story_1012_10120401_4_dialog_content = "제멋대로인 것도 정도가 있어야지.",
  ui_story_1012_10120401_5_dialog_content = "아니, 역시 괴물에게 이해력을 바라는 게 아니었어.",
  ui_story_1012_10120401_6_dialog_content = "너흰 전부 가서 그 인간을 막아.",
  ui_story_1012_10120401_7_dialog_content = "『계, 계속 싸워야 하는 겁니까...』",
  ui_story_1012_10120401_8_dialog_content = "같은 지시를 두 번 내리게 만들지 마.",
  ui_story_1012_10120401_9_dialog_content = "『예...』",
  ui_story_1012_10120401_10_dialog_content = "<color=#e8d9bb>쿠구구──!</color>",
  ui_story_1012_10120401_11_dialog_content = "무슨 소리지?",
  ui_story_1012_10120401_12_dialog_content = "<color=#e8d9bb>쿠구구구구──!</color>",
  ui_story_1012_10120401_13_dialog_content = "노──라──!",
  ui_story_1012_10120401_14_dialog_content = "정말이지 멍청하고 막무가내인 인간이라니까.",
  ui_story_1012_10120401_15_dialog_content = "너 같은 생물은 실험에 써 주려고 해도 기준 미달이야.",
  ui_story_1012_10120401_16_dialog_content = "네가 하려는 짓이 좋은 거일 리가 없겠지!",
  ui_story_1012_10120401_17_dialog_content = "그렇게 실험이 하고 싶으면, 자난성의 감옥에서 하라고.",
  ui_story_1012_10120401_18_dialog_content = "너희들, 저자를 막아.",
  ui_story_1012_10120401_19_dialog_content = "캬아악──!",
  ui_story_1012_10120401_20_dialog_content = "네 암귀들은 이 정도 수준밖에 안 되는 거냐?",
  ui_story_1012_10120401_21_dialog_content = "네 수준도 별 볼 일 없군그래.",
  ui_story_1012_10120401_22_dialog_content = "라인하르트의 동생이면 적어도 언니의 반 정도는 해야 되지 않겠어?",
  ui_story_1012_10120401_23_dialog_content = "......",
  ui_story_1012_10120401_24_dialog_content = "그따위 실패작과 날 비교하지 마.",
  ui_story_1012_10120401_25_dialog_content = "오오? 열 받았냐?",
  ui_story_1012_10120401_26_dialog_content = "좋지, 열 받았으면 어디 한 판 붙어 보자고!",
  ui_story_1012_10120401_27_dialog_content = "아무래도 실험에 집중하려면 네 입을 영원히 다물게 만드는 수밖에 없겠네.",
  ui_story_1012_10120401_28_dialog_content = "넌 날 화나게 만들었어.",
  ui_story_1012_10120401_29_dialog_content = "바라던 바다.",
  ui_story_1012_10120401_30_dialog_content = "또 여기로 돌아왔네...",
  ui_story_1012_10120401_31_dialog_content = "몇 번을 봐도 이 분위기에는 적응이 안 된다니까.",
  ui_story_1012_10120401_32_dialog_content = "나도 여긴 마음에 안 들어.",
  ui_story_1012_10120401_33_dialog_content = "얼른 화음 구역으로 통하는 문을 찾자.",
  ui_story_1012_10120401_34_dialog_content = "화음 구역으로 통하는 차단문에 도착했습니다.",
  ui_story_1012_10120401_35_dialog_content = "접근 통제 시스템 해제를 시작합니다. 해제 프로세스 중에는 다른 지시를 받을 수 없습니다.\n해제 완료까지 기다려 주십시오.",
  ui_story_1012_10120401_36_dialog_content = "1%... 2%... 5%...",
  ui_story_1012_10120401_37_dialog_content = "좀 기다려야 되는 것 같네.",
  ui_story_1012_10120401_38_dialog_content = "그러게, 그럼 난...",
  ui_story_1012_10120401_39_dialog_content = "......!",
  ui_story_1012_10120401_40_dialog_content = "왜 그래?",
  ui_story_1012_10120401_41_dialog_content = "노라의 기척이 느껴졌어... 지금 이 탑 안에 있어!",
  ui_story_1012_10120401_42_dialog_content = "<color=#e8d9bb>쿠구구──!</color>",
  ui_story_1012_10120401_43_dialog_content = "이 진동은 대체 뭐지?!",
  ui_story_1012_10120401_44_dialog_content = "아까부터 계속 울리고 있어...",
  ui_story_1012_10120401_45_dialog_content = "노라 짓인가?",
  ui_story_1012_10120401_46_dialog_content = "설마... 노라가 암귀들을 시켜서 탑을 파괴하는 건 아니겠지?!",
  ui_story_1012_10120401_47_dialog_content = "아니면... 어디가 무너졌나?",
  ui_story_1012_10120401_48_dialog_content = "<color=#e8d9bb>쿠구구구구──!</color>",
  ui_story_1012_10120401_49_dialog_content = "으앗! 이 흙들은 다 뭐야?!",
  ui_story_1012_10120401_50_dialog_content = "조심해, 흙더미에서 뭔가 튀어나왔어!",
  ui_story_1012_10120401_51_dialog_content = "<color=#e8d9bb>챙──!</color>",
  ui_story_1012_10120401_52_dialog_content = "걸리적거려.",
  ui_story_1012_10120401_53_dialog_content = "한눈팔지 마라, 노라!",
  ui_story_1012_10120401_54_dialog_content = "네 상대는 나니까.",
  ui_story_1012_10120401_55_dialog_content = "바튼 씨?! 바튼 씨였군요!",
  ui_story_1012_10120401_56_dialog_content = "여어, PlayerName. 너도 이쪽에 있었냐.",
  ui_story_1012_10120401_57_dialog_content = "뭐야, 바이스는 또 왜 그래? 기절한 거냐?!",
  ui_story_1012_10120401_58_dialog_content = "다쳤어요! 바이스를 구하려면 이 문을 열어야 해요!",
  ui_story_1012_10120401_59_dialog_content = "바튼 씨! 노라를 여기서 막아주세요!",
  ui_story_1012_10120401_60_dialog_content = "시간을 끌어 달라 이거냐... 얼마든지!",
  ui_story_1012_10120401_61_dialog_content = "너흰 내 뒤에 딱 붙어서 조무래기들을 상대해라!",
  ui_story_1012_10120401_62_dialog_content = "입만 살아서는.",
  ui_story_1012_10120401_63_dialog_content = "저항은 포기하는 걸 추천할게.",
  ui_story_1012_10120401_64_dialog_content = "나와 너희의 격차를 확실하게 인식하는 게 좋을 거야.",
  ui_story_1012_10120401_65_dialog_content = "난 너희들한테 내 귀한 시간을 낭비하고 싶진 않거든.\n물론 너희도 목숨을 잃고 싶지는 않겠지.",
  ui_story_1012_10120401_66_dialog_content = "그러니 내게 그 기계의 권한을 넘기고, 너흰 포기해.",
  ui_story_1012_10120401_67_dialog_content = "그럼 목숨만은 살려 줄 테니까.",
  ui_story_1012_10120401_68_dialog_content = "아직도 잠이 덜 깬 모양인데, 정신이나 좀 들게 자기 얼굴이나 한 대 치는 게 어때!",
  ui_story_1012_10120401_69_dialog_content = "그럼 아이테르. 네 결정은?",
  ui_story_1012_10120401_70_dialog_content = "너도 저 인간처럼 최후의 발악이라도 할 셈이야?",
  ui_story_1012_10120401_71_dialog_content = "......",
  ui_story_1012_10120401_72_option_content = "네 말은 안 믿어.",
  ui_story_1012_10120401_73_dialog_content = "호오?",
  ui_story_1012_10120401_74_dialog_content = "넌 지금까지 너무 많은 사람을 속였어.",
  ui_story_1012_10120401_75_dialog_content = "거츠더, 스예트, 슈모르...",
  ui_story_1012_10120401_76_dialog_content = "전부 네 말에 속았어. 다른 사람이야 죽든 말든, 넌 자기밖에 모르는 인간이야!",
  ui_story_1012_10120401_77_dialog_content = "믿을 가치조차 없어!",
  ui_story_1012_10120401_78_dialog_content = "......",
  ui_story_1012_10120401_79_dialog_content = "내 인내심도 이제 바닥이야.",
  ui_story_1012_10120401_80_dialog_content = "권한을 넘겨. 그러면 빨리 끝내 줄게.",
  ui_story_1012_10120401_81_dialog_content = "절대로, 무슨 일이 있어도 못 줘.",
  ui_story_1012_10120401_82_dialog_content = "무의미한 저항이네.",
  ui_story_1012_10120401_83_dialog_content = "그럼...",
  ui_story_1012_10120401_84_dialog_content = "잘 가.",
  ui_story_1012_10120402_1_dialog_content = "PlayerName, 조심해!",
  ui_story_1012_10120402_2_dialog_content = "으아앗──! 살려줘!",
  ui_story_1012_10120402_3_dialog_content = "──!",
  ui_story_1012_10120402_4_dialog_content = "크윽──!",
  ui_story_1012_10120402_5_dialog_content = "싸울 때 한눈을 팔면 안 되지.",
  ui_story_1012_10120402_6_dialog_content = "아까 했던 말, 그대로 돌려줄게.",
  ui_story_1012_10120402_7_dialog_content = "바튼 씨!",
  ui_story_1012_10120402_8_dialog_content = "쳇...",
  ui_story_1012_10120402_9_dialog_content = "고작 이 정도냐? 밥은 먹고 다니냐?",
  ui_story_1012_10120402_10_dialog_content = "넌 탑 밖에서부터 여기까지 계속 그 난리를 쳤어.",
  ui_story_1012_10120402_11_dialog_content = "이제 슬슬 힘도 다 빠졌겠지.",
  ui_story_1012_10120402_12_dialog_content = "......",
  ui_story_1012_10120402_13_dialog_content = "쓸데없는 발악은 그만둬.",
  ui_story_1012_10120402_14_dialog_content = "헛소리 집어치워!",
  ui_story_1012_10120402_15_dialog_content = "또 덤비라고──!",
  ui_story_1012_10120402_16_dialog_content = "네가 싸움에 투자하는 시간의 반만 공부에 투자했어도, 이 지경은 안 됐을 거야.",
  ui_story_1012_10120402_17_dialog_content = "공부?",
  ui_story_1012_10120402_18_dialog_content = "이 세상에 너처럼 보기만 해도 쥐어박고 싶은 녀석이 있는데...",
  ui_story_1012_10120402_19_dialog_content = "책을 편다고 글자가 눈에 들어 오겠냐?",
  ui_story_1012_10120402_20_dialog_content = "그 멍청함의 대가를 치르게 될 거야.",
  ui_story_1012_10120402_21_dialog_content = "으윽!",
  ui_story_1012_10120402_22_dialog_content = "오른쪽 손목이 부러져 버렸네.",
  ui_story_1012_10120402_23_dialog_content = "그 상태로 검은 어떻게 들려고 하는지 내가 다 궁금해지는걸.",
  ui_story_1012_10120402_24_dialog_content = "아니면...",
  ui_story_1012_10120402_25_dialog_content = "그냥 무릎 꿇고 내게 멈춰 달라고 빌 거야?",
  ui_story_1012_10120402_26_dialog_content = "그만해, 노라!",
  ui_story_1012_10120402_27_dialog_content = "입 다물어.",
  ui_story_1012_10120402_28_dialog_content = "넌 말할 자격이 없어. 약하고 무능한 아이테르.",
  ui_story_1012_10120402_29_dialog_content = "일루미나의 군인은...",
  ui_story_1012_10120402_30_dialog_content = "음?",
  ui_story_1012_10120402_31_dialog_content = "일루미나의 군인은... 절대 너 같은 인간에게 굴복하지 않는다!",
  ui_story_1012_10120402_32_dialog_content = "!!!",
  ui_story_1012_10120402_33_dialog_content = "널 쓰러트리는 건 한 손으로도 충분하다고!",
  ui_story_1012_10120402_34_dialog_content = "바튼 씨, 다리가!",
  ui_story_1012_10120402_35_dialog_content = "카렌! 바튼 씨를 도와줘!",
  ui_story_1012_10120402_36_dialog_content = "얼어붙어라!",
  ui_story_1012_10120402_37_dialog_content = "안 되겠어! 암귀가 너무 많아!",
  ui_story_1012_10120402_38_dialog_content = "난 신경 쓰지 마라!",
  ui_story_1012_10120402_39_dialog_content = "노라는 내가 처리할 테니까, 너흰 문을 여는 데에만 집중해!",
  ui_story_1012_10120402_40_dialog_content = "하지만, 바튼 씨 몸이...!",
  ui_story_1012_10120402_41_dialog_content = "!!!",
  ui_story_1012_10120402_42_dialog_content = "얼른 가라고!",
  ui_story_1012_10120402_43_dialog_content = "그래도...!",
  ui_story_1012_10120402_44_dialog_content = "가서 퇴로를 찾아!",
  ui_story_1012_10120402_45_dialog_content = "만약 내가 전사한다면, 내 묘비명은...",
  ui_story_1012_10120402_46_dialog_content = "「마지막 순간까지 암귀와 맞서 싸운 영광스러운 일루미나의 군인」으로 부탁한다!",
  ui_story_1012_10120402_47_dialog_content = "PlayerName, 지금은 물러날 곳을 찾아야 해!",
  ui_story_1012_10120402_48_dialog_content = "여기서 막혀버리면 끝장이야!",
  ui_story_1012_10120402_49_dialog_content = "......!",
  ui_story_1012_10120402_50_dialog_content = "에이드 브레인, 해제는 언제 끝나는 거야?!",
  ui_story_1012_10120402_51_dialog_content = "현재까지의 해제 진행도는 96%입니다. 조금만 더 기다려 주십시오.",
  ui_story_1012_10120402_52_dialog_content = "...조금만 더 버텨요!",
  ui_story_1012_10120402_53_dialog_content = "97%",
  ui_story_1012_10120402_54_dialog_content = "98%",
  ui_story_1012_10120402_55_dialog_content = "99%",
  ui_story_1012_10120402_56_dialog_content = "100%, 해제가 완료되었습니다.",
  ui_story_1012_10120402_57_dialog_content = "<color=#e8d9bb>쿠르릉──</color>",
  ui_story_1012_10120402_58_dialog_content = "문이... 열렸어!",
  ui_story_1012_10120402_59_dialog_content = "카렌! 바튼 씨! 후퇴해요!",
  ui_story_1012_10120501_1_dialog_content = "얼어붙어라!",
  ui_story_1012_10120501_2_dialog_content = "서둘러! 노라가 곧 쫓아올 거야. 나도 오래는 못 버텨!",
  ui_story_1012_10120501_3_dialog_content = "이쪽으로 가. 바튼, 조종사를 부탁해!",
  ui_story_1012_10120501_4_dialog_content = "걱정 마라. 이런 꼴이긴 해도, 노라가 녀석의 털끝 하나도 건드리지 못하게 해 주마!",
  ui_story_1012_10120501_5_dialog_content = "에이드 브레인, 앞으로 얼마나 더 가야 돼?",
  ui_story_1012_10120501_6_dialog_content = "전방으로 200미터 직진하면 목적지에 도착합니다.",
  ui_story_1012_10120501_7_dialog_content = "후우... 후우... 조금만 더 가면... 돼!",
  ui_story_1012_10120501_8_dialog_content = "문이 보이기 시작했어!",
  ui_story_1012_10120501_9_dialog_content = "나, 더는 못 버텨...",
  ui_story_1012_10120501_10_dialog_content = "길이 왜 이렇게 구불구불한 거야!",
  ui_story_1012_10120501_11_dialog_content = "지형이 바뀌면서 화음 구역으로 통하는 길의 구조도 변화한 것으로 추측됩니다.",
  ui_story_1012_10120501_12_dialog_content = "하지만 제가 안내해 드리는 길 찾기 정보는 정확하니 안심하십시오.",
  ui_story_1012_10120501_13_dialog_content = "포기하지 말고 계속 전진해 주십시오, 관리자님.",
  ui_story_1012_10120501_14_dialog_content = "포기 같은 거... 안 해!",
  ui_story_1012_10120501_15_dialog_content = "PlayerName, 멈추지 마!",
  ui_story_1012_10120501_16_dialog_content = "계속 달려라, 꼬맹아!",
  ui_story_1012_10120501_17_dialog_content = "멈췄다간 돌아가서 나하고 자난성을 100바퀴 뛸 줄 알아!",
  ui_story_1012_10120501_18_dialog_content = "그렇게 난폭한 격려가 어디 있냐구요!",
  ui_story_1012_10120501_19_dialog_content = "흐이익──!",
  ui_story_1012_10120501_20_dialog_content = "에이드 브레인!",
  ui_story_1012_10120501_21_dialog_content = "「에이드 브레인」입니다. 무엇을 도와드릴까요?",
  ui_story_1012_10120501_22_dialog_content = "우리가 화음 구역 안으로 들어가고 나면, 바로 문을 닫아버려!",
  ui_story_1012_10120501_23_dialog_content = "암귀들이 못 들어오게!",
  ui_story_1012_10120501_24_dialog_content = "알겠습니다.",
  ui_story_1012_10120501_25_dialog_content = "하지만 우선 발밑의 함정에 주의해 주십시오.",
  ui_story_1012_10120501_26_option_content = "함정?",
  ui_story_1012_10120501_27_dialog_content = "왜 여기 함정이 있는 건데?!",
  ui_story_1012_10120501_28_option_content = "함정도 있다고?",
  ui_story_1012_10120501_29_dialog_content = "갑자기 웬 함정인 건데?!",
  ui_story_1012_10120501_30_dialog_content = "이 함정들은 화음 구역의 독립된 방어 장치입니다.",
  ui_story_1012_10120501_31_dialog_content = "에이드 브레인은 화음 구역과 연결이 끊긴 상태입니다.\n따라서 이 함정들을 제어할 수 없습니다.",
  ui_story_1012_10120501_32_dialog_content = "현재 이 함정들은 무차별 공격 모드로 설정되어 있습니다.",
  ui_story_1012_10120501_33_dialog_content = "알아서 살 방법... 아니, 함정을 피할 방법을 찾으십시오.",
  ui_story_1012_10120501_34_dialog_content = "그런 건 빨리 말해 줬어야지!",
  ui_story_1012_10120501_35_dialog_content = "화음 구역에 함정이 장치되어 있다는 사실은\n아이테르 일족의 교과서에도 정식으로 수록된 내용입니다.",
  ui_story_1012_10120501_36_dialog_content = "기억이 나지 않으신다면 재입학을 추천해 드리겠습니다.",
  ui_story_1012_10120501_37_dialog_content = "PlayerName, 발밑을 조심해!",
  ui_story_1012_10120501_38_dialog_content = "어라?",
  ui_story_1012_10120501_39_dialog_content = "<color=#e8d9bb>딸깍──</color>",
  ui_story_1012_10120501_40_dialog_content = "빨리 피해! PlayerName!",
  ui_story_1012_10120501_41_dialog_content = "흐이익!",
  ui_story_1012_10120501_42_dialog_content = "......",
  ui_story_1012_10120501_43_dialog_content = "관리자님, 알아서 잘 피해 주십시오.",
  ui_story_1012_10120501_44_dialog_content = "이 녀석도 전투 능력이 있나?",
  ui_story_1012_10120501_45_dialog_content = "만약 있다면 밖에 던져 버리라고. 노라를 조금은 막아줄지도 모르니 말이야!",
  ui_story_1012_10120501_46_dialog_content = "에이드 브레인은 이미지 투영만 가능합니다. 전투 능력은 없습니다.",
  ui_story_1012_10120501_47_dialog_content = "에이드 브레인의 권한 밖인 전투 임무를 강요하는 것은 금지되어 있습니다.",
  ui_story_1012_10120501_48_dialog_content = "그럼 함정의 위치를 제대로 설명해!",
  ui_story_1012_10120501_49_dialog_content = "화, 화음 구역 관련 데이터를 검색 중입니다...",
  ui_story_1012_10120501_50_dialog_content = "검색이 완료되었습니다.",
  ui_story_1012_10120501_51_dialog_content = "전방의 함정은 우측으로 이동 시 회피가 가능합니다.",
  ui_story_1012_10120501_52_dialog_content = "이런, 암귀가 쫓아왔어!",
  ui_story_1012_10120501_53_dialog_content = "어떻게든 함정을 이용해서 녀석들을 따돌려 보자!",
  ui_story_1012_10120502_1_dialog_content = "관리자가 곧 목적지에 도착합니다.",
  ui_story_1012_10120502_2_dialog_content = "화음 구역의 정문 폐쇄를 시작합니다.",
  ui_story_1012_10120502_3_dialog_content = "문이 완전히 닫히기 전에 화음 구역 안으로 들어오십시오.",
  ui_story_1012_10120502_4_dialog_content = "<color=#e8d9bb>쿠구구──!</color>",
  ui_story_1012_10120502_5_dialog_content = "잠깐만?! 너무 빠른 거 아냐?!",
  ui_story_1012_10120502_6_dialog_content = "문이 닫혀 버리겠어!",
  ui_story_1012_10120502_7_dialog_content = "녀석들을 막아. 저 벌레들이 안의 장치를 망가트리지 못하게 해.",
  ui_story_1012_10120502_8_dialog_content = "PlayerName! 어떻게 좀 해 봐!",
  ui_story_1012_10120502_9_dialog_content = "암귀랑 거리를 벌려야 해!",
  ui_story_1012_10120502_10_dialog_content = "어떻게 하지... 어떻게... 무슨 수로 거리를 벌리지?!",
  ui_story_1012_10120502_11_dialog_content = "전방에 폭발하는 함정이 있습니다. 조심해 피해 주십시오.",
  ui_story_1012_10120502_12_dialog_content = "폭발하는 함정?",
  ui_story_1012_10120502_13_dialog_content = "꼬맹이, 그 함정을 밟아라!",
  ui_story_1012_10120502_14_dialog_content = "네에에에?!",
  ui_story_1012_10120502_15_dialog_content = "날 믿어라! 그냥 밟으면 돼!",
  ui_story_1012_10120502_16_dialog_content = "도망칠 생각 마.",
  ui_story_1012_10120502_17_dialog_content = "딱 이번 한 번만이에요!",
  ui_story_1012_10120502_18_dialog_content = "<color=#e8d9bb>딸깍!</color>",
  ui_story_1012_10120502_19_dialog_content = "꽉 잡아라, 꼬맹이!",
  ui_story_1012_10120502_20_dialog_content = "<color=#e8d9bb>콰앙!</color>",
  ui_story_1012_10120502_21_dialog_content = "<color=#e8d9bb>쿠구구──!</color>",
  ui_story_1012_10120502_22_dialog_content = "......!",
  ui_story_1012_10120502_23_dialog_content = "으아아! 폭발한다아아아아─!",
  ui_story_1012_10120502_24_dialog_content = "<color=#e8d9bb>콰아아앙── 쿵!</color>",
  ui_story_1012_10120502_25_dialog_content = "역시 일루미나의 괴물답네.",
  ui_story_1012_10120502_26_dialog_content = "목숨을 거는 방법도 참 여러 가지잖아.",
  ui_story_1012_10120502_27_dialog_content = "몸으로 부딪쳐서 이 문을 박살 내.",
  ui_story_1012_10120502_28_dialog_content = "『예, 노라 님!』",
  ui_story_1012_10120502_29_dialog_content = "우리... 성공했어요?",
  ui_story_1012_10120502_30_dialog_content = "적어도 죽지는 않았어...",
  ui_story_1012_10120502_31_dialog_content = "바이스도 안 다쳤고.",
  ui_story_1012_10120502_32_dialog_content = "다행이야... 잠깐, 바튼 씨는?!",
  ui_story_1012_10120502_33_dialog_content = "난... 괜찮다...",
  ui_story_1012_10120502_34_dialog_content = "쓰읍... 그나저나 아이테르가 만든 폭탄, 위력이 상당하잖아.",
  ui_story_1012_10120502_35_dialog_content = "내가 먼저 폭파시키지 않았다면 우린 다 끝장이었겠어.",
  ui_story_1012_10120502_36_dialog_content = "전혀 안 괜찮잖아요?!",
  ui_story_1012_10120502_37_dialog_content = "쿨럭... 걱정하지 마라, 꼬맹이...",
  ui_story_1012_10120502_38_dialog_content = "일루미나인이라면 모두 힘겨운 전투를 치러 본 적이 있지.\n이 정도의 상처는 대충 붕대나 감고 잠 좀 자면 낫는다고.",
  ui_story_1012_10120502_39_dialog_content = "이깟 상처 때문에 의무병을 찾아갔다간 뒷덜미를 잡혀 의무실에서 끌려 나올 거다.",
  ui_story_1012_10120502_40_dialog_content = "일단 내 쪽은 신경 꺼도 된다... 그것보다 너희가 찾고 있다던 게 저거냐?",
  ui_story_1012_10120502_41_dialog_content = "에이드 브레인, 저게 바로 그 「화음 연결」 장치야?",
  ui_story_1012_10120502_42_dialog_content = "맞다고 생각합니다.",
  ui_story_1012_10120502_43_dialog_content = "그 말 확실한 거지?",
  ui_story_1012_10120502_44_dialog_content = "이 장치에 대해 기록된 내용이 있어?",
  ui_story_1012_10120502_45_dialog_content = "「화음 연결」은 화음 구역의 주요 장치입니다.",
  ui_story_1012_10120502_46_dialog_content = "에이드 브레인은 관리자는 눈앞에 있는 장치가 「화음 연결」이라고 추정합니다.",
  ui_story_1012_10120502_47_dialog_content = "<color=#e8d9bb>쿵──!</color>",
  ui_story_1012_10120502_48_dialog_content = "이런... 암귀들이 문을 들이받고 있어!",
  ui_story_1012_10120502_49_dialog_content = "그건 걱정할 거 없다.",
  ui_story_1012_10120502_50_dialog_content = "이 기지의 문과 벽은 아주 튼튼하거든. 내가 몇 번이고 부딪혀 봤는데 꿈쩍도 안 했다고.",
  ui_story_1012_10120502_51_dialog_content = "<color=#e8d9bb>쿠우웅──!</color>",
  ui_story_1012_10120502_52_dialog_content = "문에 구멍이 뚫린 것 같은데요?!",
  ui_story_1012_10120502_53_dialog_content = "에이드 브레인, 문을 보강할 방법 같은 건 없어?!",
  ui_story_1012_10120502_54_dialog_content = "화음 구역의 접근 통제 시스템 강화 기능을 실행하는 중입니다.",
  ui_story_1012_10120502_55_dialog_content = "<color=#e8d9bb>철컥── 철컥──</color>",
  ui_story_1012_10120502_56_dialog_content = "입구를 막는 문 몇 개가 더 생겼어.",
  ui_story_1012_10120502_57_dialog_content = "이러면 조금은 더 버텨 줄 수 있을 것 같아.",
  ui_story_1012_10120502_58_dialog_content = "<color=#e8d9bb>쿵... 쿵...</color>",
  ui_story_1012_10120502_59_dialog_content = "공격을 멈춘 건가?",
  ui_story_1012_10120502_60_dialog_content = "<color=#e8d9bb>쿠웅──!</color>",
  ui_story_1012_10120502_61_dialog_content = "왜 아까보다 더 거세진 거냐고!",
  ui_story_1012_10120502_62_dialog_content = "저 암귀들은 머리도 안 아픈가?",
  ui_story_1012_10120502_63_dialog_content = "쳇, 노라 녀석, 나보고 막무가내니 뭐니 하더니.\n정작 자기는 문을 부술 생각만 하고 있잖아!",
  ui_story_1012_10120502_64_dialog_content = "해 보고 안 되면 돌아가야 될 거 아냐!",
  ui_story_1012_10120502_65_dialog_content = "이대로면 저 문도 금방 뚫리고 말 거야.",
  ui_story_1012_10120502_66_dialog_content = "PlayerName, 얼른 「화음 연결」을 작동해 바이스를 치료하자.",
  ui_story_1012_10120502_67_dialog_content = "바이스가 회복되면, 힘을 합쳐 포위를 돌파할 수 있을 거야!",
  ui_story_1012_10120502_68_dialog_content = "에이드 브레인, 「화음 연결」을 작동해 줘!",
  ui_story_1012_10120502_69_dialog_content = "「화음 연결」의 작동을 시작합니다.",
  ui_story_1012_10120502_70_dialog_content = "실험 기록을 검사해 봐. 「화음 연결」의 효과와 부작용을 확인해야 돼!",
  ui_story_1012_10120502_71_dialog_content = "검사 중입니다... 오류 발생.",
  ui_story_1012_10120502_72_dialog_content = "실험 기록을 찾을 수 없습니다.",
  ui_story_1012_10120502_73_dialog_content = "뭐라고?!",
  ui_story_1012_10120502_74_dialog_content = "실험 기록은 전부 여기 저장돼 있다고 했었잖아?",
  ui_story_1012_10120502_75_dialog_content = "근데 왜 찾을 수 없다는 거야?!",
  ui_story_1012_10120502_76_dialog_content = "화음 구역과 오랫동안 연결이 끊겨 이곳의 상황을 자세히 알 수 없습니다.",
  ui_story_1012_10120502_77_dialog_content = "하지만 실험 기록이 삭제되었다는 기록을 찾았습니다.",
  ui_story_1012_10120502_78_dialog_content = "데이터는 이미 오래전에 사라져 복구할 수 없습니다.",
  ui_story_1012_10120502_79_dialog_content = "그게 무슨...",
  ui_story_1012_10120502_80_dialog_content = "그래서, 지금 검증되지 않은 물건을 바이스한테 쓰겠다는 거냐?",
  ui_story_1012_10120502_81_dialog_content = "아니에요, 원래는 여기 와서 실험 기록을 찾고 생각해 보려고 했는데...\n그 기록들이 다 사라져 버린 것 같아요...",
  ui_story_1012_10120502_82_dialog_content = "바튼 씨, 카렌이랑 같이 조금만 더 버텨 주세요.",
  ui_story_1012_10120502_83_dialog_content = "제가 「화음 연결」의 효과를 검증해 볼게요!",
  ui_story_1012_10120502_84_dialog_content = "잠깐만, 넌 오로리안이 아니잖아. 사용해 봐야 결과는 더 불확실해져.",
  ui_story_1012_10120502_85_dialog_content = "그렇다고 바이스가 위험을 무릅쓰게 할 순 없어...",
  ui_story_1012_10120502_86_dialog_content = "노라가 곧 이곳까지 뚫고 들어올 거야. 전투 능력이 있는 두 사람보다는...",
  ui_story_1012_10120502_87_dialog_content = "루미나틱스도 못 쓰는 아이테르인 내가 실험 대상으로 훨씬 더 적합해!",
  ui_story_1012_10120502_88_dialog_content = "거기 서!",
  ui_story_1012_10120502_89_dialog_content = "이거 놓으세요!",
  ui_story_1012_10120502_90_dialog_content = "일단 진정해!",
  ui_story_1012_10120502_91_dialog_content = "저걸 사용하는 방법은 알고 있나?",
  ui_story_1012_10120502_92_dialog_content = "「화음 연결」은 부상을 치유할 수 있으며,\n부분적인 신체 개조를 통해 오로리안의 잠재 능력을 끌어낼 수 있습니다.",
  ui_story_1012_10120502_93_dialog_content = "상처 치유가 가능하다는 거군, 그렇지?",
  ui_story_1012_10120502_94_dialog_content = "그렇다면 내가 가지!",
  ui_story_1012_10120502_95_dialog_content = "하지만 저게 어떤 부작용이 있는지, 성공률은 얼마나 되는지,\n사용하다 죽을 수도 있는지 아무것도 모른다구요!",
  ui_story_1012_10120502_96_dialog_content = "그러니까 더더욱 내가 해야지!",
  ui_story_1012_10120502_97_dialog_content = "꼬맹이, 넌 지금 실험 대상이 필요해. 안 그러냐?",
  ui_story_1012_10120502_98_dialog_content = "지금 내 꼴을 봐라. 만약 다시 노라와 정면으로 싸워야 한다면\n기껏 해 봐야 한, 두 번 정도밖에 못 버텨.",
  ui_story_1012_10120502_99_dialog_content = "만약 네가 밖에서 카렌을 도와서 싸우면, 아마 내가 가는 것보다는 조금 더 버틸 수 있겠지.",
  ui_story_1012_10120502_100_dialog_content = "그러니 내가 하겠다.",
  ui_story_1012_10120502_101_dialog_content = "만약 저 장치가 날 치료해 준다면, 노라에게 크게 한 방 먹여줄 테니까.",
  ui_story_1012_10120502_102_dialog_content = "그때가 되면 너도 안심하고 저 장치로 바이스를 구해라.",
  ui_story_1012_10120502_103_dialog_content = "...알겠어요.",
  ui_story_1012_10120502_104_dialog_content = "그럼 여긴 너희 둘에게 부탁하지.",
  ui_story_1012_10120502_105_dialog_content = "암귀들이 못 들어오게 제대로 막으라고!",
  ui_story_1012_10120502_106_dialog_content = "<color=#e8d9bb>쿠웅──!</color>",
  ui_story_1012_10120502_107_dialog_content = "크아아!",
  ui_story_1012_10120502_108_dialog_content = "(지하성에서 사용하는 재료보다 훨씬 더 견고하지만, 무게는 더 가벼워.)",
  ui_story_1012_10120502_109_dialog_content = "(이 기지와 문에 사용된 재료는 콜로서스의 근육 소재와 매우 유사해.)",
  ui_story_1012_10120502_110_dialog_content = "(콜로서스와 아이테르, 그리고 암귀...)",
  ui_story_1012_10120502_111_dialog_content = "(이 비밀, 어쩌면 이클립스조차 모를 수도 있겠어.)",
  ui_story_1012_10120502_112_dialog_content = "(정말 기대되는걸.)",
  ui_story_1012_10120502_113_dialog_content = "『노라 님, 피제로 님으로부터의 전언입니다.』",
  ui_story_1012_10120502_114_dialog_content = "『군단이 탑 밖에 집결을 마쳤습니다.』",
  ui_story_1012_10120502_115_dialog_content = "『하지만 하얀 탑의 변화가 일루미나, 백야성과 북방의 주의를 끌었습니다.』",
  ui_story_1012_10120502_116_dialog_content = "『지금 저들의 지원군이 이곳으로 향하고 있습니다.』",
  ui_story_1012_10120502_117_dialog_content = "『그 지원군 중에는 라인하르트와 베들레헴도 있다고 합니다.』",
  ui_story_1012_10120502_118_dialog_content = "평소에는 숨어서 벌벌 떨기나 하던 주제에, 이제 와서 총출동해 보겠다 이건가.",
  ui_story_1012_10120502_119_dialog_content = "다들 귀도 밝으셔라.",
  ui_story_1012_10120502_120_dialog_content = "피제로에게 녀석들을 막으라고 전해.",
  ui_story_1012_10120502_121_dialog_content = "실험에는 아직 시간이 더 필요하니까.",
  ui_story_1012_10120502_122_dialog_content = "『피제로 님으로부터의 전언이 하나 더 있습니다.』",
  ui_story_1012_10120502_123_dialog_content = "『쓸데없는 일은 삼가시라고 당부하셨습니다.』",
  ui_story_1012_10120502_124_dialog_content = "진심으로 날 도울 생각이라면, 이렇게 몇 번이고 날 귀찮게 하질 말아야지.",
  ui_story_1012_10120502_125_dialog_content = "......",
  ui_story_1012_10120502_126_dialog_content = "『노라 님께서 그렇게 말씀하셨습니다...』",
  ui_story_1012_10120502_127_dialog_content = "『노라 그 녀석, 아무래도 주의를 조금 줄 필요가 있겠군.』",
  ui_story_1012_10120502_128_dialog_content = "『하지만 지금은 때가 아니다.』",
  ui_story_1012_10120502_129_dialog_content = "『일루미나, 백야성. 심지어 북방까지 움직였다.』",
  ui_story_1012_10120502_130_dialog_content = "『피제로 님, 저들을 막을까요?』",
  ui_story_1012_10120502_131_dialog_content = "『심심풀이 상대가 필요하다면 가 보도록 해라.』",
  ui_story_1012_10120502_132_dialog_content = "『하지만 하나, 둘쯤은 탑 안으로 들어가게 두어도 좋다.』",
  ui_story_1012_10120502_133_dialog_content = "『노라도 조금은 압박을 받아야 진가를 발휘하니 말이다.』",
  ui_story_1012_10120502_134_dialog_content = "『알겠습니다, 피제로 님.』",
  ui_story_1012_10120601_1_dialog_content = "<color=#e8d9bb>시스템 알림， 「화음 연결」 실행 중입니다...\n「동조」 프로세스를 중단하지 마십시오...</color>",
  ui_story_1012_10120601_2_dialog_content = "<color=#e8d9bb>둥... 둥... 둥... 둥...</color>",
  ui_story_1012_10120601_3_dialog_content = "이게... 무슨 소리지?",
  ui_story_1012_10120601_4_dialog_content = "주변 전체가 이 소리를 내고 있는 것 같아. 뭔가 괴로운 느낌이야.",
  ui_story_1012_10120601_5_dialog_content = "괴롭다기보단 이상한 느낌이 들어.",
  ui_story_1012_10120601_6_dialog_content = "어떤 소리랑 닮았는데...",
  ui_story_1012_10120601_7_option_content = "지진 소리?",
  ui_story_1012_10120601_8_dialog_content = "이 진동 강도, 귀환의 탑이 하늘로 떠오를 때 수준이야.",
  ui_story_1012_10120601_9_dialog_content = "핵심 중추 구역의 벽이 이 소리에 따라 흔들리고 있어...",
  ui_story_1012_10120601_10_dialog_content = "곧 무너져 버릴 것처럼...",
  ui_story_1012_10120601_11_option_content = "심장이 뛰는 소리?",
  ui_story_1012_10120601_12_dialog_content = "뭔가 리듬이 일정한 것 같아.",
  ui_story_1012_10120601_13_dialog_content = "심지어 리듬 속에서 무서운 활력도 느껴지는 것 같아...",
  ui_story_1012_10120601_14_dialog_content = "마치 거대한 심장의 내부에 있는 것처럼 말이야.",
  ui_story_1012_10120601_15_dialog_content = "이게 바로 「화음 연결」의 힘일까...?",
  ui_story_1012_10120601_16_dialog_content = "그런 건가, 정말 사람을 불안하게 만드는 소리네.",
  ui_story_1012_10120601_17_dialog_content = "이 소리는 얼마나 이어지는 걸까.",
  ui_story_1012_10120601_18_dialog_content = "그리고 바튼 씨는...",
  ui_story_1012_10120601_19_dialog_content = "<color=#e8d9bb>퍼엉──!</color>",
  ui_story_1012_10120601_20_dialog_content = "?!",
  ui_story_1012_10120601_21_dialog_content = "이 소리... 설마 「화음 연결」 장치가 낸 소리는 아니겠지?!",
  ui_story_1012_10120601_22_dialog_content = "경고. 전방 30미터에서 화음 구역 불법 침입자가 감지되었습니다.",
  ui_story_1012_10120601_23_dialog_content = "노라가 먼저 왔어... 에이드 브레인, 구조를 바꿔서 이곳의 문을 폐쇄해!",
  ui_story_1012_10120601_24_dialog_content = "접수... 오류! 오류!",
  ui_story_1012_10120601_25_dialog_content = "화음 구역 입구에서 생명체가 감지되었습니다. 폐쇄할 수 없습니다.",
  ui_story_1012_10120601_26_dialog_content = "다른 방법이 없어. 준비하자. PlayerName!",
  ui_story_1012_10120601_27_dialog_content = "응. 「동조」 프로세스가 아직 진행 중이야. 바튼 씨를 지켜야 해!",
  ui_story_1012_10120601_28_dialog_content = "(...「동조」 결과가 어떻게 되든 반드시 지켜야 해.)",
  ui_story_1012_10120601_29_dialog_content = "경고, 전방 10미터에서 불법 침입자가 감지되었습니다.",
  ui_story_1012_10120601_30_dialog_content = "반복 경고, 전방 10미터에서 불법 침입자가 감지되었습니다.",
  ui_story_1012_10120601_31_dialog_content = "반복 경고, 전방 10미터에서 불법 침입자가 감지되었습니다...",
  ui_story_1012_10120601_32_dialog_content = "멈췄나?",
  ui_story_1012_10120601_33_dialog_content = "그, 그런가...?",
  ui_story_1012_10120601_34_dialog_content = "<color=#e8d9bb><size=45>퍼어어어엉!</size></color>",
  ui_story_1012_10120601_35_dialog_content = "불법 침입자라고?",
  ui_story_1012_10120601_36_dialog_content = "난 너희와 똑같은 일을 했을 뿐이야.",
  ui_story_1012_10120601_37_dialog_content = "유일한 차이는 내가 너희보다 늦게 들어왔다는 점이겠지.",
  ui_story_1012_10120601_38_dialog_content = "...으음?",
  ui_story_1012_10120601_39_dialog_content = "...이 묘지 최하층에 이런 파격적인 장치가 숨겨져 있었구나.",
  ui_story_1012_10120601_40_dialog_content = "너희들이 나보다 먼저 바튼의 숨통을 끊어 버렸을 줄이야.",
  ui_story_1012_10120601_41_dialog_content = "헛소리하지 마!",
  ui_story_1012_10120601_42_dialog_content = "PlayerName, 상대할 거 없어!",
  ui_story_1012_10120601_43_dialog_content = "노라가 안으로 들어오게 해선 안 돼... 바이스도 지켜야 하니까!",
  ui_story_1012_10120601_44_dialog_content = "세상의 많은 일들은 네가 원하는 대로 되지 않는 법이야.",
  ui_story_1012_10120601_45_dialog_content = "PlayerName, 아이테르인 네가 콜로서스를 이렇게 오래 떠나 있었다 해서\n굳이 이런 이치까지 내가 직접 가르쳐 줘야 하니?",
  ui_story_1012_10120601_46_dialog_content = "전에 나와 맞섰던 아이테르가 어떤 결말을 맞이했는지는\n내가 굳이 말하지 않아도 알고 있겠지?",
  ui_story_1012_10120601_47_dialog_content = "......!",
  ui_story_1012_10120601_48_dialog_content = "『공격해.』",
  ui_story_1012_10120601_49_dialog_content = "『예!』",
  ui_story_1012_10120702_1_dialog_content = "그어어어!",
  ui_story_1012_10120702_2_dialog_content = "하압──",
  ui_story_1012_10120702_3_dialog_content = "크에엑...",
  ui_story_1012_10120702_4_dialog_content = "카렌! 뒤!",
  ui_story_1012_10120702_5_dialog_content = "뭐...?!",
  ui_story_1012_10120702_6_dialog_content = "그어어어!",
  ui_story_1012_10120702_7_dialog_content = "으윽...",
  ui_story_1012_10120702_8_dialog_content = "(안 되겠어. 노라가 데려온 암귀가 너무 많아...)",
  ui_story_1012_10120702_9_dialog_content = "(카렌이랑 의식을 연결하는 것보다는 이게 더 효과적이겠어!)",
  ui_story_1012_10120702_10_dialog_content = "으엑?!",
  ui_story_1012_10120702_11_dialog_content = "나도 모르는 사이에 무기 사용법을 배웠니? PlayerName.",
  ui_story_1012_10120702_12_dialog_content = "음... 확실히 아이테르 일족의 총인 것 같네. 문화재급의 유물이라고 할 수 있겠어.",
  ui_story_1012_10120702_13_dialog_content = "좋은 물건이잖아.",
  ui_story_1012_10120702_14_dialog_content = "고마워, PlayerName. 잘 받을게.",
  ui_story_1012_10120702_15_dialog_content = "제길... 돌려줘!",
  ui_story_1012_10120702_16_dialog_content = "그어어어!",
  ui_story_1012_10120702_17_dialog_content = "녀석들을 막아, PlayerName! 녀석들이 계속 들어오게 둬선 안 돼!",
  ui_story_1012_10120702_18_dialog_content = "「동조」 프로세스를 저런 놈들 때문에 실패할 순 없어!",
  ui_story_1012_10120702_19_dialog_content = "얼어붙어라!",
  ui_story_1012_10120702_20_dialog_content = "<size=45>그어어억!</size>",
  ui_story_1012_10120702_21_dialog_content = "카, 카렌!",
  ui_story_1012_10120702_22_option_content = "(강제 감응!)",
  ui_story_1012_10120702_23_dialog_content = "카렌... 얼른... 얼른 대답해!",
  ui_story_1012_10120702_24_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_1012_10120702_25_dialog_content = "<color=#e8d9bb>............</color>",
  ui_story_1012_10120702_26_dialog_content = "『바튼과 바이스는 죽이고, 장치는 건들지 마.』",
  ui_story_1012_10120702_27_dialog_content = "『예.』",
  ui_story_1012_10120702_28_dialog_content = "<size=50><anim type=Shake>크오오오──!</anim></size>",
  ui_story_1012_10120702_29_dialog_content = "(왜... 대체 왜 이렇게 된 거야...)",
  ui_story_1012_10120702_30_dialog_content = "(또... 이렇게 속수무책으로 당하는 거야...?)",
  ui_story_1012_10120702_31_dialog_content = "(내가 루미나틱스 같은 능력이 있었더라면... 절대로 지금처럼은 안 됐겠지...)",
  ui_story_1012_10120702_32_dialog_content = "(바이스, 카렌. 그리고...)",
  ui_story_1012_10120702_33_dialog_content = "(모두들...)",
  ui_story_1012_10120702_34_dialog_content = "살려 줘! 누가 나 좀 살려 줘!",
  ui_story_1012_10120702_35_dialog_content = "다가가지 마! 절대 용서 못 해!",
  ui_story_1012_10120702_36_dialog_content = "흐아앙... 흑흑... 흐아아아...",
  ui_story_1012_10120702_37_dialog_content = "불바다에 암귀라니... 내 환영식이라도 하는 거냐?",
  ui_story_1012_10120702_38_dialog_content = "(?!)",
  ui_story_1012_10120702_39_dialog_content = "이것보다 더 대단한 게 있겠냐?!",
  ui_story_1012_10120702_40_dialog_content = "힘이 끓어올라서 도저히 참을 수가 없군!",
  ui_story_1012_10120702_41_dialog_content = "즉각적인 전투야말로 최고의 훈련이지!",
  ui_story_1012_10120702_42_dialog_content = "바튼 씨! 서, 성공했군요!",
  ui_story_1012_10120702_43_dialog_content = "어이, PlayerName... 어떻게 된 거냐.",
  ui_story_1012_10120702_44_dialog_content = "얼굴의 눈물이나 좀 닦아라. 아가씨처럼 울지 말고!",
  ui_story_1012_10120702_45_dialog_content = "투지를 불태우란 말이다!",
  ui_story_1012_10120702_46_dialog_content = "그, 그래야죠!",
  ui_story_1012_10120702_47_dialog_content = "자, 네게 진정한 전장이 무엇인지 알려주마.",
  ui_story_1012_10120702_48_dialog_content = "이건 너의 탑이다. 이걸 이클립스 녀석들의 손에 들어가게 할 순 없지!",
  ui_story_1012_10120702_49_dialog_content = "『정말 놀랍네. 고대의 아이테르 기술이 이 정도까지 발전했을 줄이야.』",
  ui_story_1012_10120702_50_dialog_content = "『흥분되는걸... 여기까지 쫓아온 건 옳은 선택이었어.』",
  ui_story_1012_10120702_51_dialog_content = "『현명하십니다, 주인님.』",
  ui_story_1012_10120702_52_dialog_content = "『뭘 가만히 있는 거야. 얼른 녀석을 잡아.\n죽이지 않게 조심해. 살아있는 상태가 필요하니까.』",
  ui_story_1012_10120702_53_dialog_content = "『예!』",
  ui_story_1012_10120702_54_dialog_content = "<color=#e8d9bb><size=45>퍼엉!</size></color>",
  ui_story_1012_10120702_55_dialog_content = "「오랜만」이야, 노라.",
  ui_story_1012_10120702_56_dialog_content = "오랜만에 만났는데, 데려온 놈들은 왜 전보다 더 비실비실한 거지?",
  ui_story_1012_10120702_57_dialog_content = "제길...",
  ui_story_1012_10120702_58_dialog_content = "『전부 들어라. 지금 당장 공격해!』",
  ui_story_1012_10120702_59_dialog_content = "그어어어!",
  ui_story_1012_10120702_60_dialog_content = "표범의 일격을 받아라!",
  ui_story_1012_10120702_61_dialog_content = "PlayerName, 바튼!",
  ui_story_1012_10120702_62_dialog_content = "...「화음 연결」이 성공한 거구나!",
  ui_story_1012_10120702_63_dialog_content = "하하하하하하! 그렇다.",
  ui_story_1012_10120702_64_dialog_content = "얼른 가서 바이스를 구해라. 너희 팀에 바이스가 빠질 순 없잖아?",
  ui_story_1012_10120702_65_dialog_content = "여긴 내게 맡기라고.",
  ui_story_1012_10120702_66_dialog_content = "......",
  ui_story_1012_10120702_67_dialog_content = "『일단 퇴각해라. 이클립스 군단과 합류해라.』",
  ui_story_1012_10120702_68_dialog_content = "『아, 알겠습니다.』",
  ui_story_1012_10120702_69_dialog_content = "망할, 거기 안 서냐?!",
  ui_story_1012_10120702_70_dialog_content = "뻔뻔한 자식들!",
  ui_story_1012_10120702_71_dialog_content = "카렌, 넌 좀 어때? 아까 위험했을 때 혹시...",
  ui_story_1012_10120702_72_dialog_content = "문제없어. 시간이 없으니 서두르자, PlayerName...",
  ui_story_1012_10120702_73_dialog_content = "얼른 바이스를 구해야 해!",
  ui_story_1012_10120702_74_dialog_content = "그래. 아까 그 방법대로 「동조」를 완료하는 거야.",
  ui_story_1012_10120702_75_dialog_content = "(그럼... 부탁할게, 「화음 연결」.)",
  ui_story_1012_10120702_76_dialog_content = "(꼭 깨어나 줘, 바이스...)",
  ui_story_1012_10120702_77_dialog_content = "<color=#e8d9bb>시스템 알림, 「화음 연결」이 곧 실행됩니다...</color>",
  ui_story_1012_10120801_1_dialog_content = "<color=#e8d9bb>시스템 알림， 「화음 연결」 실행 중입니다...\n「동조」 프로세스를 중단하지 마십시오...</color>",
  ui_story_1012_10120801_2_dialog_content = "......",
  ui_story_1012_10120801_3_dialog_content = "............",
  ui_story_1012_10120801_4_dialog_content = "실행부터 지금까지 시간이 얼마나 지났지?",
  ui_story_1012_10120801_5_dialog_content = "그렇게 조급해하지 마, PlayerName. 바이스한테 시간을 좀 주자.",
  ui_story_1012_10120801_6_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_1012_10120801_7_dialog_content = "그래도 그렇지. 「동조」에 시간이 너무 오래 걸리는 거 아냐?!",
  ui_story_1012_10120801_8_dialog_content = "그러고 보니까 아까 바튼 씨가 깨어났을 떈 시간이 이렇게 오래 걸리지 않았어.",
  ui_story_1012_10120801_9_dialog_content = "PlayerName, 우리...",
  ui_story_1012_10120801_10_dialog_content = "(카렌...)",
  ui_story_1012_10120801_11_dialog_content = "(그래, 나라도 기운을 내야지.)",
  ui_story_1012_10120801_12_dialog_content = "아까 우린 제대로 「화음 연결」 가이드를 따라 바이스를 위에 눕혔어.",
  ui_story_1012_10120801_13_dialog_content = "전체적인 과정은 바튼 씨 때랑 별로 차이가 없었어.",
  ui_story_1012_10120801_14_dialog_content = "「화음 연결」 장치도, 에이드 브레인도 아무런 경고음을 안 냈어.",
  ui_story_1012_10120801_15_dialog_content = "그러니까 만약 문제가 있다면 그건...",
  ui_story_1012_10120801_16_option_content = "바이스의 「의식 소실」 상태 때문일 거야.",
  ui_story_1012_10120801_17_dialog_content = "그런가, 역시 그 가능성밖에 없을 것 같아.",
  ui_story_1012_10120801_18_dialog_content = "똑같이 다쳤어도 저 일루미나 장군은 의식을 잃은 상태가 아니었으니까.",
  ui_story_1012_10120801_19_dialog_content = "그래서 상처를 얼마나 심하게 입었든, 더 강력한 육체로 깨어날 수 있었던 거야.",
  ui_story_1012_10120801_20_option_content = "노라 때문에 장치가 망가졌을지도 몰라.",
  ui_story_1012_10120801_21_dialog_content = "그런 걸까? 노라가 무슨 짓을 한 걸까...",
  ui_story_1012_10120801_22_dialog_content = "하지만... 아까 노라가 데려온 암귀들은 「화음 연결」 장치에 가까이 다가가지도 않았어...",
  ui_story_1012_10120801_23_dialog_content = "그 전에 저 일루미나의 장군이 다 쓰러트려 버렸으니까.",
  ui_story_1012_10120801_24_dialog_content = "그렇게 생각하면 역시... 문제는 「의식 소실」이야.",
  ui_story_1012_10120801_25_dialog_content = "그래. 그러고 보니까 아까 서클 시스템에서 본 그 데이터들 중에...",
  ui_story_1012_10120801_26_dialog_content = "실험체... ■■■, 「의식 소실」에서 깨어나지 못함, 신체... ■■■, 활력 징후 감퇴.",
  ui_story_1012_10120801_27_dialog_content = "실험체... ■■■, 「의식 소실」에서 깨어나지 못함, ■■■ 현상 발생, 활력...",
  ui_story_1012_10120801_28_dialog_content = "실험체... ■■■... ■■■... 에서 깨어나지 못함, 실험 과정에서...",
  ui_story_1012_10120801_29_dialog_content = "실험체라고 불렸던 그 아이테르들이 가지고 있던 공통적인 특징은...",
  ui_story_1012_10120801_30_dialog_content = "바로 「의식 소실」이었어.",
  ui_story_1012_10120801_31_dialog_content = "어, 어떻게 그런...",
  ui_story_1012_10120801_32_dialog_content = "(설마 「의식 소실」에서 깨어나지 못한 게 그 사람들 모두의 운명이었던 건가?)",
  ui_story_1012_10120801_33_dialog_content = "(만약 그게 사실이라면, 바이스는...)",
  ui_story_1012_10120801_34_dialog_content = "PlayerName...",
  ui_story_1012_10120801_35_dialog_content = "PlayerName?",
  ui_story_1012_10120801_36_dialog_content = "라, 라인하르트 씨?!",
  ui_story_1012_10120801_37_dialog_content = "다행히 신호는 깨끗하게 잡히는 모양이군.",
  ui_story_1012_10120801_38_dialog_content = "그쪽 상황은 어떻지? 너희들이 얼마나 큰일을 벌여놨는지는 알고 있나?",
  ui_story_1012_10120801_39_dialog_content = "저, 정말 죄송해요!",
  ui_story_1012_10120801_40_dialog_content = "하하하하하하하, 널 탓하려던 건 아니었다.",
  ui_story_1012_10120801_41_dialog_content = "난 그저 헤븐즈 밸리에 발생한 이번 급변에 주목하고 있는 게\n일루미나뿐만이 아니라는 걸 말해주려던 것뿐이다.",
  ui_story_1012_10120801_42_dialog_content = "절대 자신을 남의 손에 휘둘리게 두지 마라...",
  ui_story_1012_10120801_43_dialog_content = "누가 뭐라 해도 헤븐즈 밸리를 바꿀 권리가 있는 건, 너 하나뿐이니까.",
  ui_story_1012_10120801_44_dialog_content = "그럼 이따가 보자고.",
  ui_story_1012_10120801_45_dialog_content = "네, 라인하르트 씨.",
  ui_story_1012_10120801_46_dialog_content = "저 말이 맞아.",
  ui_story_1012_10120801_47_dialog_content = "우린 지금 탑 밖의 상황은 하나도 알 수가 없어. 그 점은 우리한테 아주 불리해.",
  ui_story_1012_10120801_48_dialog_content = "근데 어떻게 해야 탑 밖의 상황을 알 수 있을까?",
  ui_story_1012_10120801_49_dialog_content = "바튼 씨는 아직 노라를 상대하고 있을 거야.\n갑자기 감응하면 바튼 씨한테 방해가 될 테고...",
  ui_story_1012_10120801_50_dialog_content = "접수, 질문 분석 중...",
  ui_story_1012_10120801_51_dialog_content = "뭐야?!",
  ui_story_1012_10120801_52_dialog_content = "에이드 브레인... 해결할 방법이라도 있는 거야?",
  ui_story_1012_10120801_53_dialog_content = "탑 외부 모니터링 스크린을 실행하는 중입니다.",
  ui_story_1012_10120801_54_dialog_content = "후우, 후우...",
  ui_story_1012_10120801_55_dialog_content = "그만 도망쳐라, 노라.",
  ui_story_1012_10120801_56_dialog_content = "전사처럼 목숨을 걸고 싸우자고!",
  ui_story_1012_10120801_57_dialog_content = "...?!",
  ui_story_1012_10120801_58_dialog_content = "이게 무슨...",
  ui_story_1012_10120801_59_dialog_content = "이건 정말이지... 살면서 한 번 볼까 말까 한 장관이잖아!",
  ui_story_1012_10120801_60_dialog_content = "(지원군을 이렇게나 많이 불렀을 줄이야!)",
  ui_story_1012_10120801_61_dialog_content = "(이번 전투, 이 정도라면 십수 년 전 어둠의 위기 때랑 다를 게 없겠어.)",
  ui_story_1012_10120801_62_dialog_content = "(내가 두 사람을 위해... 시간을 얼마나 벌어줄 수 있을지 모르겠군.)",
  ui_story_1012_10120801_63_dialog_content = "호오?",
  ui_story_1012_10120801_64_dialog_content = "제 무덤을 판 모양이로군, 노라.",
  ui_story_1012_10120801_65_dialog_content = "앞으로는 남의 말에도 귀를 기울이는 편이 좋을 거다.",
  ui_story_1012_10120801_66_dialog_content = "여기까지 귀찮은 걸 달고 온 걸 보면, 아무 소득도 얻지 못했겠지.",
  ui_story_1012_10120801_67_dialog_content = "미안하지만 소득은 꽤나 많았어.",
  ui_story_1012_10120801_68_dialog_content = "다만 그게 너와는 관계가 없을 뿐이야.",
  ui_story_1012_10120801_69_dialog_content = "거기서 그렇게 군단을 움직이지 않을 작정이라면,\n가만히 앉아서 이득을 볼 생각은 접는 게 좋을 거야.",
  ui_story_1012_10120801_70_dialog_content = "좋을 대로 생각해라.",
  ui_story_1012_10120801_71_dialog_content = "정말 비열하군, 노라. 질 것 같으니 지원군을 부른 거냐?",
  ui_story_1012_10120801_72_dialog_content = "(바로 저기다! 방어선의 허점!)",
  ui_story_1012_10120801_73_dialog_content = "표범의...!",
  ui_story_1012_10120801_74_dialog_content = "크윽...",
  ui_story_1012_10120801_75_dialog_content = "이클립스가 병력을 총동원한 건 널 위해서가 아니야.",
  ui_story_1012_10120801_76_dialog_content = "발악하지 말고 좀 얌전히 있는 건 어떨까?",
  ui_story_1012_10120801_77_dialog_content = "하얀 탑에 도착했을 때부터 지금까지, 넌 계속 저 아이테르를 위해 시간을 끌고 있었잖아.",
  ui_story_1012_10120801_78_dialog_content = "내 말이 맞지?",
  ui_story_1012_10120801_79_dialog_content = "......",
  ui_story_1012_10120801_80_dialog_content = "『저자를 잡아.』",
  ui_story_1012_10120801_81_dialog_content = "크오오오──!",
  ui_story_1012_10120801_82_dialog_content = "<color=#e8d9bb>콰아앙── 퍼엉!</color>",
  ui_story_1012_10120801_83_dialog_content = "이건...",
  ui_story_1012_10120801_84_dialog_content = "음, 가까이서 바라보니 이 탑이 더욱 범상치 않아 보이는구나.",
  ui_story_1012_10120801_85_dialog_content = "모든 것이 내가 꿈에서 본 예언과 같다...",
  ui_story_1012_10120801_86_dialog_content = "이 세상이 파멸하거나, 혹은 새로 태어나거나.\n어느 쪽이든 헤븐즈 밸리와 암귀의 대립은 없어선 안 될 조각이겠지.",
  ui_story_1012_10120801_87_dialog_content = "(북방의 지도자...인가?)",
  ui_story_1012_10120801_88_dialog_content = "(직접 도우러 올 줄이야...)",
  ui_story_1012_10120801_89_dialog_content = "바튼 군단장, 일루미나 군법 제42조에 따라 항명한 군인을 어떻게 처분하는지 알고 있겠지?",
  ui_story_1012_10120801_90_dialog_content = "?!",
  ui_story_1012_10120801_91_dialog_content = "일루미나는 군사 조례에 따라 항명한 군인을 엄벌에 처하고,\n항명의 정도가 심한 경우 군사법정에 회부해 심판한다.",
  ui_story_1012_10120801_92_dialog_content = "...허나, 그건 전쟁이 끝나고 나서의 일이지.",
  ui_story_1012_10120801_93_dialog_content = "...대원수?",
  ui_story_1012_10120801_94_dialog_content = "선두의 지원 부대가 곧 도착할 거다. 서둘러 부대와 합류해라.",
  ui_story_1012_10120801_95_dialog_content = "호오? 꼴이 그게 뭐냐... 긴급 특훈이라도 한 모양이지?\n확실히 뭔가 달라 보이긴 하다만...",
  ui_story_1012_10120801_96_dialog_content = "아무튼 화려하게 저질러 보라고, 바튼 군단장!",
  ui_story_1012_10120801_97_dialog_content = "공을 세워 과오를 만회해라!",
  ui_story_1012_10120801_98_dialog_content = "......",
  ui_story_1012_10120801_99_dialog_content = "좋다!",
  ui_story_1012_10120801_100_dialog_content = "그럼 잘 보고 있으라고, 대원수.",
  ui_story_1012_10120801_101_dialog_content = "탑 외부 모니터링 영상 재생을 마쳤습니다.",
  ui_story_1012_10120801_102_dialog_content = "베들레헴 폐하... 그리고 라인하르트 대원수...",
  ui_story_1012_10120801_103_dialog_content = "북방과 일루미나도 움직이기 시작한 것 같아.",
  ui_story_1012_10120801_104_dialog_content = "하지만 지금 데려온 병력만으로 이클립스와 맞서는 건 아무리 봐도 무리야.",
  ui_story_1012_10120801_105_dialog_content = "PlayerName, 우리도 뭔가 해야 돼!",
  ui_story_1012_10120801_106_dialog_content = "알겠어. 우린 일단 전장 중앙에 있는 이 귀환의 탑의 지리적인 이점을 활용하자.",
  ui_story_1012_10120801_107_dialog_content = "에이드 브레인, 이 귀환의 탑에 어떤 방어 수단들이 있는지 알려줘!",
  ui_story_1012_10120801_108_dialog_content = "접수, 질문 분석 중... 답변 생성...",
  ui_story_1012_10120801_109_dialog_content = "귀환의 탑 내부에는 최종 방어 시스템 <color=#FFB400>「율법의 현」</color>이 존재합니다.",
  ui_story_1012_10120801_110_dialog_content = "이는 헤븐즈 밸리에서 가장 강력하고, 가장 특별하며,\n가장 최후에 사용하는 방어 수단입니다.",
  ui_story_1012_10120801_111_dialog_content = "그럼...",
  ui_story_1012_10120801_112_dialog_content = "「율법의 현」은 가동이 어렵고, 사용 시 큰 대가를 치러야 합니다.",
  ui_story_1012_10120801_113_dialog_content = "에이드 브레인은 그 어떤 아이테르에게도 「율법의 현」의 사용 권한을\n부여하지 않을 것입니다.",
  ui_story_1012_10120801_114_dialog_content = "「권한」? 왜 또 「권한」이 나오는 건데?!",
  ui_story_1012_10120801_115_dialog_content = "반복합니다. 「율법의 현」은 가동이 어렵고, 사용 시 큰 대가를 치러야 합니다.",
  ui_story_1012_10120801_116_dialog_content = "에이드 브레인은 그 어떤 아이테르에게도 「율법의 현」의 사용 권한을...",
  ui_story_1012_10120801_117_dialog_content = "PlayerName, 이 기계랑 말다툼할 필요 없어.",
  ui_story_1012_10120801_118_dialog_content = "우린 자유 의지를 가지고 있는 존재야. 기계의 제약을 받을 순 없어.",
  ui_story_1012_10120801_119_dialog_content = "(카렌 말이 맞아. 그리고 다시는 되풀이할 수 없어...)",
  ui_story_1012_10120801_120_dialog_content = "(암귀 군단 앞에서 그 어느 아이테르도 구할 수 없었던 우리의 과거를...)",
  ui_story_1012_10120801_121_dialog_content = "여기 틀어박혀 있을 순 없어. 나도 전쟁에 나서서 이클립스와 맞설 거야!",
  ui_story_1012_10120801_122_dialog_content = "네가 무슨 생각인지는 알겠어, PlayerName... 하지만...",
  ui_story_1012_10120801_123_dialog_content = "바이스는...",
  ui_story_1012_10120801_124_dialog_content = "아직 「동조」에 성공하지 못했어. 앞으로 더 오랜 시간을 견뎌야 할 거야.",
  ui_story_1012_10120801_125_dialog_content = "PlayerName, 화음 구역을 떠나기 전에\n에이드 브레인한테 입구의 구조를 변경하라고 해 줘.",
  ui_story_1012_10120801_126_dialog_content = "그리고 화음 구역의 입구를 제대로 봉쇄한 다음에, 비밀통로의 구조도 바꿔서...",
  ui_story_1012_10120801_127_dialog_content = "바이스를 위한 견고한 <color=#FFB400>고치</color>를 만들어 주는 거야.",
  ui_story_1012_10120801_128_dialog_content = "그래야지.",
  ui_story_1012_10120801_129_dialog_content = "(바이스, 「화음 연결」의 힘으로 꼭 눈을 떠 줘...)",
  ui_story_1012_10120801_130_dialog_content = "(우린 모두 네가 깨어나길 기다리고 있으니까.)",
  ui_story_1012_10120801_131_dialog_content = "곧 다시 보자, 바이스.",
  ui_story_1012_10120901_1_dialog_content = "<color=#e8d9bb>탑, 입구 통로</color>",
  ui_story_1012_10120901_2_dialog_content = "<color=#e8d9bb>뚜벅... 뚜벅...</color>",
  ui_story_1012_10120901_3_dialog_content = "앞으로 조금만 더 가면 우리가 들어왔던 입구야.",
  ui_story_1012_10120901_4_dialog_content = "PlayerName, 이럴 때 설교를 늘어놓고 싶진 않지만...",
  ui_story_1012_10120901_5_dialog_content = "두려워하지 마.",
  ui_story_1012_10120901_6_dialog_content = "카, 카렌...?",
  ui_story_1012_10120901_7_dialog_content = "항상 잊지 마. 넌 너의 땅을 위해 싸우려는 거야.",
  ui_story_1012_10120901_8_dialog_content = "그건 두려워해야 할 일이 아니야. 더없이 영광스러운 일이니까.",
  ui_story_1012_10120901_9_dialog_content = "베들레헴 폐하께선... 항상 이렇게 가르쳐 주셨어.",
  ui_story_1012_10120901_10_dialog_content = "고마워, 카렌.",
  ui_story_1012_10120901_11_dialog_content = "난 이미 각오했어.",
  ui_story_1012_10120901_12_dialog_content = "그래. 그럼 같이 탑 밖의 세계로 돌아가자.",
  ui_story_1012_10120901_13_dialog_content = "이, 이게 무슨...",
  ui_story_1012_10120901_14_dialog_content = "<color=#e8d9bb>쿠쿵... 우르릉...</color>",
  ui_story_1012_10120901_15_dialog_content = "<anim type=Shake><size=50>크어어어──!</size></anim>",
  ui_story_1012_10120901_16_dialog_content = "그때의 헤븐즈 밸리도... 지금 같은 모습이었을까...",
  ui_story_1012_10120901_17_dialog_content = "PlayerName, 조심해!",
  ui_story_1012_10120901_18_dialog_content = "크에엑...",
  ui_story_1012_10120901_19_dialog_content = "크크크크...",
  ui_story_1012_10120901_20_dialog_content = "발 빠른 정보력은 수천의 군대보다 유용한 법이다.",
  ui_story_1012_10120901_21_dialog_content = "눈앞의 형세가... 불 보듯 뻔하다면 더더욱 그런 법이지.",
  ui_story_1012_10120901_22_dialog_content = "고작 그 정도 병력만으로는 무슨 수를 써도 이클립스의 대군을 당해낼 수 없을 거다.",
  ui_story_1012_10120901_23_dialog_content = "하, 싸우기 전에 헛소리부터 늘어놓는 게 너희 이클립스의 전통이냐?",
  ui_story_1012_10120901_24_dialog_content = "입만 나불거린다고 너희 실력이 느는 건 아닐 텐데.",
  ui_story_1012_10120901_24X1_dialog_content = "(...아마 베들레헴 폐하께서도 지금쯤 도착하셨을 거야.)",
  ui_story_1012_10120901_24X2_dialog_content = "PlayerName, 난 일단 귀환의 탑의 다른 쪽 상황을 살피러 갈게.\n그리고 베들레헴 폐하와 합류할게.",
  ui_story_1012_10120901_24X3_dialog_content = "넌 일루미나에서 온 지원군과 여기 남아 있어. 괜찮지?",
  ui_story_1012_10120901_24X4_dialog_content = "그것도 좋겠네. 무슨 일 있으면 바로 연락해.",
  ui_story_1012_10120901_24X5_dialog_content = "몸조심하고, 카렌.",
  ui_story_1012_10120901_25_dialog_content = "대원수님, 새로운 소식입니다.\n바튼 군단장이 제2군단의 지원 소대와 합류했습니다.",
  ui_story_1012_10120901_26_dialog_content = "지금 대원수님의 명령을 기다리고 있습니다.",
  ui_story_1012_10120901_27_dialog_content = "좋아. 최전선에 주요 부대를 집결시키라고 전해라.\n밀집 대형으로 돌격해 개전한다.",
  ui_story_1012_10120901_28_dialog_content = "잔여 병력은 좌우 양익으로 전개해 후방에서 이클립스의 대기 병력을 견제한다.",
  ui_story_1012_10120901_29_dialog_content = "알겠습니다!",
  ui_story_1012_10120901_30_dialog_content = "알겠다면서 왜 가만히 서 있지?",
  ui_story_1012_10120901_31_dialog_content = "...대원수님, 제게는 아직 작전 임무를 하달하지 않으셨습니다.",
  ui_story_1012_10120901_32_dialog_content = "하하하하하, 그럼 넌 후방으로 이동해 저 탑을 지키고,\n언제든 내 명에 따라 움직일 수 있도록 대기해라.",
  ui_story_1012_10120901_33_dialog_content = "탑을... 지키라는 말씀이십니까?",
  ui_story_1012_10120901_34_dialog_content = "저기 저 가장 커다란 하얀 탑이 보이나?",
  ui_story_1012_10120901_35_dialog_content = "보입니다. 하지만...",
  ui_story_1012_10120901_36_dialog_content = "우리가 이번에 헤븐즈 밸리에 긴급 지원을 나선 이유가 바로 저 하얀 탑이다.",
  ui_story_1012_10120901_37_dialog_content = "비록 전선의 임무는 아니지만, 그것보다 훨씬 더 중요한 임무다.",
  ui_story_1012_10120901_38_dialog_content = "잠시 후 임무 내용을 인계하겠다. 또한 전장의 정보 전달도 네 몫이다.\n할 일이 없을까 하는 염려는 거두어라.",
  ui_story_1012_10120901_39_dialog_content = "...알겠습니다!",
  ui_story_1012_10120901_40_dialog_content = "그리고 PlayerName, 너는 당분간 나와 움직인다.",
  ui_story_1012_10120901_41_dialog_content = "이런, 같이 다니던 두 사람이 안 보이는군...",
  ui_story_1012_10120901_42_dialog_content = "라인하르트 씨, 바이스는...",
  ui_story_1012_10120901_43_dialog_content = "바이스 중위의 일은 이미 바튼 군단장에게 보고받았다.",
  ui_story_1012_10120901_44_dialog_content = "그 탑 안에 있는 장치에 대해 믿음을 가져라.\n그건 네 선조들이 남겨 준 보물이니 말이야.",
  ui_story_1012_10120901_45_dialog_content = "더군다나 이제 곧 전쟁이 시작된다. 그러니 기운 빠지는 생각은 금물이다.",
  ui_story_1012_10120901_46_dialog_content = "사기를 끌어 올리고, 고개를 들어라!",
  ui_story_1012_10120901_47_dialog_content = "...네!",
  ui_story_1012_10120901_48_dialog_content = "그래야지!",
  ui_story_1012_10120901_49_dialog_content = "<color=#e8d9bb>같은 시간, 귀환의 탑 반대쪽</color>",
  ui_story_1012_10120901_50_dialog_content = "<size=45>여왕 폐하!</size>",
  ui_story_1012_10120901_51_dialog_content = "저는 여왕 폐하의 호위로서 정말 실격입니다!",
  ui_story_1012_10120901_52_dialog_content = "저를 버려두고 여왕 폐하 혼자서 암귀와 맞서지 말아 주세요!",
  ui_story_1012_10120901_53_dialog_content = "티아라가 여왕 폐하를 위해 적진에 돌격하겠습니다!",
  ui_story_1012_10120901_54_dialog_content = "티아라, 그대는 오랫동안 눈의 숲을 왕래했고, 감시와 기습에 능하지...",
  ui_story_1012_10120901_55_dialog_content = "그 점이 바로 북방이 헤븐즈 밸리를 돕는 이번 작전의 전략이다.",
  ui_story_1012_10120901_56_dialog_content = "전장은 전투라면 죽고 못 사는 저 오로리안들에게 맡겨 두어라.\n우린 방어적인 전략으로 이 하얀 탑의 주변을 지키는 것이다.",
  ui_story_1012_10120901_57_dialog_content = "이미 북방의 모든 병력을 하얀 탑 근처로 철수시켰고, 경계를 강화했다.",
  ui_story_1012_10120901_58_dialog_content = "전선이 붕괴하지만 않는다면, 암귀들도 쉽게 이곳에 깊이 발을 들이지는 못할 것이다.",
  ui_story_1012_10120901_59_dialog_content = "네, 여왕 폐하!",
  ui_story_1012_10120901_60_dialog_content = "...또한, 전장에서는 번거롭게 호칭 따위에 얽매일 필요는 없다.",
  ui_story_1012_10120901_61_dialog_content = "나를 이름으로 불러도 좋다.",
  ui_story_1012_10120901_62_dialog_content = "자, 내가 펼친 보호막 안으로 몸을 피하도록 해라.",
  ui_story_1012_10120901_63_dialog_content = "아, 알겠습니다! 여왕 폐하!",
  ui_story_1012_10120901_64_dialog_content = "베들레헴 폐하, 이렇게 빨리 와 주실 줄은 몰랐습니다!",
  ui_story_1012_10120901_65_dialog_content = "오랜만이로구나, 카렌.",
  ui_story_1012_10120901_66_dialog_content = "허나 지금은 한가로이 이야기를 하고 있을 때가 아니다.\n지금의 상황을 일종의 시험이라 생각해도 좋을 것이다...",
  ui_story_1012_10120901_67_dialog_content = "그대가 혼자서 얼마나 많은 전투를 헤쳐 나갈 수 있는지 보여다오.",
  ui_story_1012_10120901_68_dialog_content = "카렌 님은 절대로 혼자가 아닙니다!",
  ui_story_1012_10120901_69_dialog_content = "베르타?",
  ui_story_1012_10120901_70_dialog_content = "왜... 라파엘이랑 같이 안 있는 거야?",
  ui_story_1012_10120901_71_dialog_content = "베르타는 성주님의 명으로 기사단의 정예 부대를 이끌고 카렌 님을 지원하러 왔습니다!",
  ui_story_1012_10120901_72_dialog_content = "명을 내려 주십시오, <color=#FFB400>카렌 대장님</color>!",
  ui_story_1012_10120901_73_dialog_content = "(그렇구나... 아버님의 뜻인가...)",
  ui_story_1012_10120901_74_dialog_content = "(아버님께서 이렇게 빨리 출병하실 줄이야.)",
  ui_story_1012_10120901_75_dialog_content = "만물은 백야 아래에, 모두 무기를 들고 나와 함께 전선으로 나서자!",
  ui_story_1012_10120901_76_dialog_content = "밝은 낮은 밤하늘을 꿰뚫고, 어둠을 지우리라!",
  ui_story_1012_10120901_77_dialog_content = "만물은 백야 아래에!",
  ui_story_1012_10120901_78_dialog_content = "<color=#e8d9bb>헤븐즈 밸리, 이클립스군 주둔지</color>",
  ui_story_1012_10120901_79_dialog_content = "『백야성까지 지원을 보냈다는 말이냐? 그 늙은이, 판이 깔리니까 그제서야 끼어드는군.』",
  ui_story_1012_10120901_80_dialog_content = "『...이, 이번에는 이클립스에 맞서면 어떤 대가를 치르게 되는지\n제가 백야성 놈들에게 확실하게 알려 주겠습니다.』",
  ui_story_1012_10120901_81_dialog_content = "『백야성뿐이겠습니까. 헤븐즈 밸리를 점령하고 나면\n저희는 이 대륙 전체를 장악할 절대적인 힘을 얻게 될 겁니다!』",
  ui_story_1012_10120901_82_dialog_content = "『크크크크크...』",
  ui_story_1012_10120901_83_dialog_content = "『이클립스의 동료들이여, 우리의 시대가 이제 솟아오르고 있다...』",
  ui_story_1012_10120901_84_dialog_content = "『승리는 이미 우리의 손안에 있다.』",
  ui_story_1012_10120901_85_dialog_content = "『붉은 선혈이 이 헤븐즈 밸리를 다시 한번 물들이리라.』",
  ui_story_1012_10120901_86_dialog_content = "『헤븐즈 밸리로 진군하라! 하얀 탑을 점령하고 모든 것을 몰살해라!』",
  ui_story_1012_10120901_87_dialog_content = "『<size=45>전쟁을 개시한다──!</size>』",
  ui_story_1012_10120901_88_dialog_content = "<anim type=Shake><size=45>크오오오──!</size></anim>",
  ui_story_1012_10120901_89_dialog_content = "『오늘이 지나면 아스트라 대륙에 다시는 해가 떠오르지 않을 것이다...』",
  ui_story_1012_10121002_1_dialog_content = "PlayerName, 네 지휘는 여전히 평온하군.",
  ui_story_1012_10121002_2_dialog_content = "이런 상황에서도 진정할 수 있다니.\n이걸 냉정하다고 해야 하나, 아니면 단순하다고 해야 하나.",
  ui_story_1012_10121002_3_dialog_content = "네가 왜 그토록 많은 사람들에게 신뢰를 받는지 이해가 되기 시작했다.",
  ui_story_1012_10121002_4_dialog_content = "과, 과찬이세요...",
  ui_story_1012_10121002_5_dialog_content = "대원수님, 새로운 소식입니다. 이클립스의 첫 번째 진격이 저지되었습니다.",
  ui_story_1012_10121002_6_dialog_content = "상세한 전황은 아직 파악할 수 없으나, 지원 소대의 전선은 아직 견고합니다.",
  ui_story_1012_10121002_7_dialog_content = "좋다. 모두 전력을 비축해 둬라. 방금 그 전투는 시작에 불과하니까.",
  ui_story_1012_10121002_8_dialog_content = "바튼 군단장에게 전해라. 지원 소대를 통솔해 우리의 우방 세력과 잘 협조하도록.",
  ui_story_1012_10121002_9_dialog_content = "예.",
  ui_story_1012_10121002_10_dialog_content = "비록 카렌은 더는 아이가 아니다만...",
  ui_story_1012_10121002_11_dialog_content = "전선에서 그대의 수하들과 함께 전투에 임하는 것은 아직 익숙하지 않겠지.",
  ui_story_1012_10121002_12_dialog_content = "하하하하! 평화로운 삶을 보내는 병사는 영원히 장군이 될 수 없는 법이다.",
  ui_story_1012_10121002_13_dialog_content = "카렌을 기른 게 당신이라고 들었는데 말이지.",
  ui_story_1012_10121002_14_dialog_content = "저 솔라드보다 당신이 더 아버지 같잖아, 여왕!",
  ui_story_1012_10121002_15_dialog_content = "...언사에 유의해 주었으면 좋겠구나, 라인하르트 대원수.",
  ui_story_1012_10121002_16_dialog_content = "여왕 폐하께 실례되는 태도는 삼가주시죠!",
  ui_story_1012_10121002_17_dialog_content = "그어어어!",
  ui_story_1012_10121002_18_dialog_content = "으윽──!",
  ui_story_1012_10121002_19_dialog_content = "얼음이여!",
  ui_story_1012_10121002_20_dialog_content = "전투는 계속되고 있다. 나는 한담을 좋아하지 않는다.",
  ui_story_1012_10121002_21_dialog_content = "아직은 통제가 가능한 형세이나, 그대 또한 집중해 주길 바란다.",
  ui_story_1012_10121002_22_dialog_content = "그렇다면 난 나머지 병력을 데리고 탑 앞으로 가서 놈들을 상대하도록 하지.",
  ui_story_1012_10121002_23_dialog_content = "우리 쪽은 아직 여유가 넘치니 말이야!",
  ui_story_1012_10121002_24_dialog_content = "<color=#e8d9bb>헤븐즈 밸리, 전장 최전선</color>",
  ui_story_1012_10121002_25_dialog_content = "하아?! 저 백야성 놈들한테 협조하라고?",
  ui_story_1012_10121002_26_dialog_content = "그렇습니다.",
  ui_story_1012_10121002_27_dialog_content = "됐다, 됐어. 알겠다, 잘 전달받았으니 네 임무는 끝이다.",
  ui_story_1012_10121002_28_dialog_content = "?!",
  ui_story_1012_10121002_29_dialog_content = "그어어어!",
  ui_story_1012_10121002_30_dialog_content = "크에엑...",
  ui_story_1012_10121002_31_dialog_content = "됐어. 여긴 아직 정리가 덜 됐으니까, 넌 얼른 가서 대원수와 탑을 지켜라.",
  ui_story_1012_10121002_32_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_1012_10121002_33_dialog_content = "흐이익!",
  ui_story_1012_10121002_34_dialog_content = "?!",
  ui_story_1012_10121002_35_dialog_content = "거기 일루미나 사람, 당신 뭐 하는 거죠?!",
  ui_story_1012_10121002_36_dialog_content = "제, 제가 그런 게 아닙니다. 방금 땅이 갑자기...",
  ui_story_1012_10121002_37_dialog_content = "휴, 번거롭게 만들지 마세요!",
  ui_story_1012_10121002_38_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_1012_10121002_39_dialog_content = "끼엑... 끄에엑?!",
  ui_story_1012_10121002_40_dialog_content = "...이클립스가 암귀를 대포로 쏴서 날리고 있어!",
  ui_story_1012_10121002_41_dialog_content = "정말 잘도 활용하네.",
  ui_story_1012_10121002_42_dialog_content = "크에엑...",
  ui_story_1012_10121002_43_dialog_content = "여긴 최전선이지, 내분을 일으키는 곳이 아니야.\n만약 전투를 위해 이곳에 온 게 아닌 자가 있다면...",
  ui_story_1012_10121002_44_dialog_content = "얼른 부대를 떠나서 집으로 돌아가.",
  ui_story_1012_10121002_45_dialog_content = "예!",
  ui_story_1012_10121002_46_dialog_content = "넌 왜 따라서 대답하는 거냐!",
  ui_story_1012_10121002_47_dialog_content = "죄, 죄송합니다!",
  ui_story_1012_10121002_48_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_1012_10121002_49_dialog_content = "이 포탄은 뭐지?",
  ui_story_1012_10121002_50_dialog_content = "이상해. 이번엔 우리를 향해서 날아온 게 아니야...",
  ui_story_1012_10121002_51_dialog_content = "포탄 안에서 뭔가 불안하게 만드는 검은 기운이 느껴져... 설마...",
  ui_story_1012_10121002_52_dialog_content = "이런!",
  ui_story_1012_10121002_53_dialog_content = "<color=#FFB400>다크매터</color>다!",
  ui_story_1012_10121002_54_dialog_content = "방금 전에 날렸던 포탄 몇 개는 시험용이었던 건가...",
  ui_story_1012_10121002_55_dialog_content = "이 <color=#FFB400>다크매터 포탄</color>은 귀환의 탑을 향해 날아가고 있다!",
  ui_story_1012_10121002_56_dialog_content = "(귀환의 탑?!)",
  ui_story_1012_10121002_57_dialog_content = "제2군단 지원 소대, 이동을 명한다!",
  ui_story_1012_10121002_58_dialog_content = "귀환의 탑으로 가서 대원수를 지원한다!",
  ui_story_1012_10121101_1_dialog_content = "<color=#e8d9bb>헤븐즈 밸리, 귀환의 탑 옆</color>",
  ui_story_1012_10121101_2_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_1012_10121101_3_dialog_content = "(으앗?! 머리 위에서 뭔가가 폭발했어!)",
  ui_story_1012_10121101_4_dialog_content = "(안 돼, 여왕 폐하의 호위로서 반드시 정신 똑바로 차리고 폐하를 지켜야 해!)",
  ui_story_1012_10121101_5_dialog_content = "(왜 이러지...? 갑자기 구역질이 날 것 같아!)",
  ui_story_1012_10121101_6_dialog_content = "(이 익숙한 매스꺼움은...)",
  ui_story_1012_10121101_7_dialog_content = "?!",
  ui_story_1012_10121101_8_dialog_content = "<color=#FFB400>다크매터</color>다!",
  ui_story_1012_10121101_9_dialog_content = "응결해라!",
  ui_story_1012_10121101_10_dialog_content = "보호막의 범위에는 제한이 있다. 모두 최대한 범위 안으로 모이거라.",
  ui_story_1012_10121101_11_dialog_content = "거대한 다크매터에 말려들지 않도록 해라!",
  ui_story_1012_10121101_12_dialog_content = "크흠... 이 정도 영향 따윈 별거 아니라고!",
  ui_story_1012_10121101_13_dialog_content = "무조건 피하기만 하는 건 장기적인 전술이 못 된다.",
  ui_story_1012_10121101_14_dialog_content = "이렇게 된 이상, 우리가 새로운 제압 전략을 펼쳐야 한다.",
  ui_story_1012_10121101_15_dialog_content = "대원수님!",
  ui_story_1012_10121101_16_dialog_content = "아나톨리, 마침 잘 돌아왔다...",
  ui_story_1012_10121101_17_dialog_content = "호오? 결정적인 전력도 함께 데려온 모양이군.",
  ui_story_1012_10121101_18_dialog_content = "제2군단장 바튼, 복귀했다.",
  ui_story_1012_10121101_19_dialog_content = "대원수, 다음 명령을 하달해라.",
  ui_story_1012_10121101_20_dialog_content = "기회는 한순간뿐이다.",
  ui_story_1012_10121101_21_dialog_content = "때마침 잘 와 주었다, 바튼 군단장!",
  ui_story_1012_10121101_22_dialog_content = "앗, 대, 대원수님?",
  ui_story_1012_10121101_23_dialog_content = "머리에 든 거라고는 정보밖에 없는 이 병사의 견문을 넓혀줘라!",
  ui_story_1012_10121101_24_dialog_content = "우린 반드시 저 하얀 탑을 사수해야 한다.\n이클립스의 모든 화력이 탑을 향하지 않도록 유도해라. 할 수 있겠나?",
  ui_story_1012_10121101_25_dialog_content = "기습을 할 줄 아는 건 놈들만이 아니라는 것을 가르쳐 줄 생각이다.",
  ui_story_1012_10121101_26_dialog_content = "이클립스를 기습하는 작전인가? 마음에 드는군.",
  ui_story_1012_10121101_27_dialog_content = "안심하고 가라. 이 요충지는 내가 지켜주지!",
  ui_story_1012_10121101_28_dialog_content = "(라인하르트 씨의 패기 넘치는 모습을 보고 있으니까,\n나까지 다크매터가 주는 이질감을 잊어버렸어...)",
  ui_story_1012_10121101_29_dialog_content = "(이클립스의 다크매터 포격이 여전히 불길한 어둠을 담은 채\n끊임없이 우릴 향해 날아오고 있는데도...)",
  ui_story_1012_10121101_30_dialog_content = "(마치 봄바람을 맞는 듯한 표정으로 어둠을 향해 달려갔어.)",
  ui_story_1012_10121101_31_dialog_content = "(타고난 전사, 위험한 야심가...\n일루미나 사람들이 라인하르트 씨에게 내린 평가는 다 제각각이었어...)",
  ui_story_1012_10121101_32_dialog_content = "(하지만 전장에서 라인하르트 씨의 모습을 본 적이 있는 사람이라면,\n분명히 「여명의 빛」의 진정한 의미를 알게 되겠지.)",
  ui_story_1012_10121101_33_dialog_content = "(라인하르트 씨는 희망이 보이지 않는 어둠 속에서도,\n계명성처럼 빛을 발하는 그런 사람이니까.)",
  ui_story_1012_10121101_34_dialog_content = "<size=33>PlayerName, 조금만 힘을 보태주지 않겠어?</size>",
  ui_story_1012_10121101_35_dialog_content = "<size=33>어떤 일들은 아이테르만 해낼 수 있거든.</size>",
  ui_story_1012_10121101_36_dialog_content = "네?!",
  ui_story_1012_10121101_37_dialog_content = "자, 잠깐만요!",
  ui_story_1012_10121101_38_dialog_content = "다짜고짜 사람을 둘러메시면 어떡해요!",
  ui_story_1012_10121101_39_dialog_content = "(걸핏하면 사람을 둘러메는 것도 일루미나의 전통인가?!)",
  ui_story_1012_10121101_40_dialog_content = "하하하하... 미안하게 됐어. 조금만 참으라고!",
  ui_story_1012_10121101_41_dialog_content = "아이테르는 빛을 볼 수 있다고 하잖아?\n그럼 반드시 <color=#FFB400>다크매터의 근원</color>도 볼 수 있겠지!",
  ui_story_1012_10121101_42_dialog_content = "그러니 잠시 길 안내를 맡아줬으면 한다.",
  ui_story_1012_10121101_43_dialog_content = "우리가 가서 이클립스의 다크매터 캐논을 박살 내는 거다!",
  ui_story_1012_10121101_44_dialog_content = "<color=#e8d9bb>헤븐즈 밸리, 전장 최전선</color>",
  ui_story_1012_10121101_45_dialog_content = "카렌 대장님, 이 녀석이 이번 기습의 마지막 암귀입니다.",
  ui_story_1012_10121101_46_dialog_content = "저희도 일루미나 쪽 사람들을 따라 이동해야 할까요?",
  ui_story_1012_10121101_47_dialog_content = "아니, 전장에 빈틈을 만들 순 없어.",
  ui_story_1012_10121101_48_dialog_content = "우리가 여기서 철수한다면 이클립스에게 길을 내주는 꼴이 되고 말아.",
  ui_story_1012_10121101_49_dialog_content = "이거 참 희한하군!",
  ui_story_1012_10121101_50_dialog_content = "백야성의 성주가 전장에 자기 딸을 보낼 줄이야...",
  ui_story_1012_10121101_51_dialog_content = "?!",
  ui_story_1012_10121101_52_dialog_content = "오래전부터 공주 전하와 한번 맞붙어 보고 싶었는데 말이지.",
  ui_story_1012_10121101_53_dialog_content = "(역시 왔구나, 내 예상이 맞았어...)",
  ui_story_1012_10121101_54_dialog_content = "밀렌 고티에, 넌 이미 백야성에 패배했다.",
  ui_story_1012_10121101_55_dialog_content = "심판소에 추격당하는 신세면서, 이렇게 제 발로 찾아오다니.",
  ui_story_1012_10121101_56_dialog_content = "하하~ 공주 전하, 제가 그렇게나 그리우셨습니까?",
  ui_story_1012_10121101_57_dialog_content = "아무래도 「시계」의 실험이 헛수고는 아니었던 모양입니다.",
  ui_story_1012_10121101_57X1_dialog_content = "여긴 지금 우리와 당신의 조무래기 몇 명뿐이군요...",
  ui_story_1012_10121101_57X2_dialog_content = "누가 제 발로 죽으러 온 것인지는 성급하게 단정할 필요는 없을 듯합니다만.",
  ui_story_1012_10121101_58_dialog_content = "그 역겨운 입으로 날 부르지 마.",
  ui_story_1012_10121101_59_dialog_content = "히...히익! 어, 얼음이다!",
  ui_story_1012_10121101_60_dialog_content = "어째서냐?! 네가 어떻게 용을 타고 다니는 그 괴상한 얼음 여자와\n같은 힘을 쓰는 거냐고!",
  ui_story_1012_10121101_61_dialog_content = "「괴상한 얼음 여자」...? 베들레헴 폐하를 말하는 거냐?!",
  ui_story_1012_10121101_62_dialog_content = "감히 폐하를 그런 모욕적인 호칭으로 부르다니...",
  ui_story_1012_10121101_63_dialog_content = "용서할 수 없다!",
  ui_story_1012_10121101_64_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_1012_10121101_65_dialog_content = "이쪽도 골치 아픈 일이 생겼던 모양이군.",
  ui_story_1012_10121101_66_dialog_content = "PlayerName한테 고마워하라고.\n오는 길에 밀렌 고티에의 다크매터를 느꼈다고 알려 줬거든...",
  ui_story_1012_10121101_67_dialog_content = "그러니 어떻게든 도와주러 올 수밖에.",
  ui_story_1012_10121101_68_dialog_content = "PlayerName, 두 사람도 왔으니까 그럼 시간 낭비하지 말자.",
  ui_story_1012_10121101_69_dialog_content = "이클립스 쪽의 포격은 잠시 멈춘 상태야. 이 타이밍에 놈들의 손발을 끊어버려.",
  ui_story_1012_10121101_70_dialog_content = "그리고 밀렌은...",
  ui_story_1012_10121101_71_dialog_content = "...어라?",
  ui_story_1012_10121101_72_dialog_content = "흥, 도망치는 거 하나는 정말 빠르네.",
  ui_story_1012_10121101_73_dialog_content = "좋다, 시간이 촉박하니 서둘러 돌격한다!",
  ui_story_1012_10121101_74_dialog_content = "전선은 우리 일루미나 쪽에서 지탱할 테니,\n넌 너희 기사단을 이끌고 주력 부대와 합류해라.",
  ui_story_1012_10121101_75_dialog_content = "밀어닥치는 암귀, 짙은 다크매터...\n저 하얀 탑은 지금 안정적으로 공격을 가할 병력이 무엇보다 절실하다.",
  ui_story_1012_10121101_76_dialog_content = "좋아요. 그럼 이쪽을 부탁하죠.",
  ui_story_1012_10121101_77_dialog_content = "...그나저나 PlayerName, 안색이 왜 안 좋은 거야?",
  ui_story_1012_10121101_78_dialog_content = "(「이 주변의 다크매터가 너무 짙어서 토할 것 같아」...)",
  ui_story_1012_10121101_79_dialog_content = "(...라는 말을 하기엔 너무 면목 없잖아!)",
  ui_story_1012_10121101_80_dialog_content = "표, 표정이 안 좋다는 건 우리가 맞는 방향으로 가고 있다는 뜻일 거야!",
  ui_story_1012_10121101_81_dialog_content = "그럼 잠깐 따로 움직여야겠네. 내 쪽에서 좋은 소식이 있길 기대해 줘, 카렌!",
  ui_story_1012_10121101_82_dialog_content = "몸조심해.",
  ui_story_1012_10121101_83_dialog_content = "그럼 서두르자, PlayerName.",
  ui_story_1012_10121101_84_dialog_content = "다크매터 캐논은 바로 이 앞에 있다. 힘든 전투가 되겠지.",
  ui_story_1012_10121102_1_dialog_content = "잘했다, PlayerName.",
  ui_story_1012_10121102_2_dialog_content = "이 대포들은 정말 한 주먹거리도 안 되는군.",
  ui_story_1012_10121102_3_dialog_content = "방금 그게 마지막 대포였나?",
  ui_story_1012_10121102_4_dialog_content = "확인해 볼게요...",
  ui_story_1012_10121102_5_option_content = "(강제 감응!)",
  ui_story_1012_10121102_6_dialog_content = "뭉쳐 있는 다크매터는 이제 없는 것 같아요. 근데...",
  ui_story_1012_10121102_7_dialog_content = "그어어어!",
  ui_story_1012_10121102_8_dialog_content = "크아아!",
  ui_story_1012_10121102_9_dialog_content = "조무래기들이 성가시게 구는군.",
  ui_story_1012_10121102_10_dialog_content = "이 녀석들이 발산하는 다크매터도 네 판단에 영향을 주겠지?",
  ui_story_1012_10121102_11_dialog_content = "그렇다면... 내 창으로 녀석들을 모두 꿰뚫어 버리는 게 낫겠군!",
  ui_story_1012_10121102_12_dialog_content = "진정한 힘을 느껴봐라!",
  ui_story_1012_10121102_13_dialog_content = "크에엑...",
  ui_story_1012_10121102_14_dialog_content = "아직도 그렇게 싸움을 좋아하는구나, 라인하르트.",
  ui_story_1012_10121102_15_dialog_content = "그 광기가 언젠가는 네 목을 옥죄게 될 거야.",
  ui_story_1012_10121102_16_dialog_content = "나한테 할 말은 그게 전부인가?",
  ui_story_1012_10121102_17_dialog_content = "내가 살아있었다는 사실은 그렇게 놀랄 일도 아니었던 모양이지? 노라.",
  ui_story_1012_10121102_18_dialog_content = "아마 넌 <color=#FFB400>그때부터</color> 알았겠지...",
  ui_story_1012_10121102_19_dialog_content = "나 같은 「괴물」을 쓰러트리는 건 아주 어려운 일이라는 걸 말이야.",
  ui_story_1012_10121102_20_dialog_content = "자길 너무 과신하는구나.",
  ui_story_1012_10121102_21_dialog_content = "피제로를 쫓아 온 거라면, 녀석은 바로 이 앞에 있어.",
  ui_story_1012_10121102_22_dialog_content = "난 바빠서 같이는 못 가겠네.",
  ui_story_1012_10121102_23_dialog_content = "『가자.』",
  ui_story_1012_10121102_24_dialog_content = "『예.』",
  ui_story_1012_10121102_25_dialog_content = "(이상해... 노라가 왜 갑자기 우호적으로 변한 거지?)",
  ui_story_1012_10121102_26_dialog_content = "(게다가 우리한테 직접 길까지 알려 주고...)",
  ui_story_1012_10121102_27_dialog_content = "라, 라인하르트 씨. 아무리 봐도... 노라의 반응이 이상해요.",
  ui_story_1012_10121102_28_dialog_content = "......",
  ui_story_1012_10121102_29_dialog_content = "PlayerName, 서둘러 탑 아래의 전장 상황을 파악해라!",
  ui_story_1012_10121102_30_dialog_content = "아, 알겠어요!",
  ui_story_1012_10121102_31_dialog_content = "크크크크...",
  ui_story_1012_10121102_32_dialog_content = "네 여동생으로도 널 속여 넘길 수는 없었던 것인가.",
  ui_story_1012_10121102_33_dialog_content = "너희 오로리안은 가끔은 우리 암귀보다도 더욱 냉정한 생물이란 말이지.",
  ui_story_1012_10121102_34_dialog_content = "...쳇.",
  ui_story_1012_10121102_35_dialog_content = "(역시 날 노리고 있었군.)",
  ui_story_1012_10121102_36_dialog_content = "(내가 이곳까지 쳐들어오지 않는다면, 계속 포격을 가해 우리의 병력을 소모시키고...)",
  ui_story_1012_10121102_37_dialog_content = "(내가 대포를 파괴하러 온다면, 즉시 병력을 보내 하얀 탑을 공격한다...)",
  ui_story_1012_10121102_38_dialog_content = "(...역시, 우린 지금 병력이 너무 부족해.)",
  ui_story_1012_10121102_39_dialog_content = "PlayerName, 어서 가자!",
  ui_story_1012_10121102_40_dialog_content = "그런다고 전황을 바꿀 수 있을 것이라 생각하나?",
  ui_story_1012_10121102_41_dialog_content = "오로리안의 실패는 이미 정해진 결말이다.",
  ui_story_1012_10121102_42_dialog_content = "네가 하고 있는 건 너희들의 숨이 끊어질 시간을 억지로 잡아 늘리는 것에 불과하지.",
  ui_story_1012_10121102_43_dialog_content = "어서 돌아가 너의 저 <color=#FFB400>지리멸렬</color>한 동포들을 보아라!",
  ui_story_1012_10121102_44_dialog_content = "그들이 이클립스의 정예들과 암귀 군단 속에서 가루가 되는 모습을 지켜보는 것이다!",
  ui_story_1012_10121102_45_dialog_content = "뭐라고...?",
  ui_story_1012_10121102_46_dialog_content = "크크크크크크... 생각만 해도 참으로 멋진 장면이로군.",
  ui_story_1012_10121102_47_dialog_content = "그럼 먼저 가 보마.",
  ui_story_1012_10121102_48_dialog_content = "네 실패를 마음껏 음미해라, 라인하르트.",
  ui_story_1012_10121102_49_dialog_content = "시간이 없다, PlayerName. 어서 녀석의 뒤를 쫓아야 해!",
  ui_story_1012_10121102_50_dialog_content = "우린... 이제 어떻게 해야 하는 거죠... 라인하르트 씨?",
  ui_story_1012_10121102_51_dialog_content = "어쩌냐니, 당연히 싸워야지!",
  ui_story_1012_10121102_52_dialog_content = "네 전우들을 믿고, 끝까지 싸우는 거다...",
  ui_story_1012_10121102_53_dialog_content = "다시 일어설 수 없게 되는 그 순간까지!",
  ui_story_1012_10121301_1_dialog_content = "크크, 정말 처량하게 아름다운 광경이로군.",
  ui_story_1012_10121301_2_dialog_content = "너희들이 그렇게 힘겹게 지켜 온 계란은 이미 깨져 버렸다.",
  ui_story_1012_10121301_3_dialog_content = "내가 그 틈으로 손을 집어넣어, 조금씩, 천천히 짓눌러 주마.",
  ui_story_1012_10121301_4_dialog_content = "그리고 너희가 내 손바닥 안에서 어떻게 부서져 가는지 음미해 주도록 하지.",
  ui_story_1012_10121301_5_dialog_content = "암귀들이여, 살육을 갈망하는 이들이여.",
  ui_story_1012_10121301_6_dialog_content = "상처의 냄새를 맡았느냐?",
  ui_story_1012_10121301_7_dialog_content = "그들의 아픈 곳을 노려서...",
  ui_story_1012_10121301_8_dialog_content = "최후의 빛마저 사그라트려라!",
  ui_story_1012_10121301_9_dialog_content = "크아아──!",
  ui_story_1012_10121301_10_dialog_content = "암귀가 몰려오고 있어요!",
  ui_story_1012_10121301_11_dialog_content = "방어선의 구멍을... 막을 수 있을까요?!",
  ui_story_1012_10121301_12_dialog_content = "전술적인 관점에서 방어선은 이미 돌파당했습니다.\n만회하려 해도 위험성이 너무 큽니다.",
  ui_story_1012_10121301_13_dialog_content = "돌파당한 부분은 망치와 모루 전술에 당할 위험이 있고, 게다가...",
  ui_story_1012_10121301_14_dialog_content = "됐어요! 그만해요!",
  ui_story_1012_10121301_15_dialog_content = "여긴 전장이라구요. 그런 장황한 얘기를 듣고 싶은 사람은 아무도 없어요!",
  ui_story_1012_10121301_16_dialog_content = "하지만 바로 전장에 있기 때문에, 더더욱 이성적으로 판단해야 하는 겁니다.",
  ui_story_1012_10121301_17_dialog_content = "그럼 그 이성적인 판단으로 내린 결론이 뭐죠?",
  ui_story_1012_10121301_18_dialog_content = "계속 이곳을 지킨다면, 우린 전멸할 겁니다.",
  ui_story_1012_10121301_19_dialog_content = "......",
  ui_story_1012_10121301_20_dialog_content = "이성적인 선택은 이 탑을 포기하고 모두 힘을 합쳐 포위를 돌파하는 겁니다.",
  ui_story_1012_10121301_21_dialog_content = "우리의 대인 전력은 상대보다 뛰어납니다.\n그 이점을 활용한다면 포위 돌파는 가능성이 높습니다.",
  ui_story_1012_10121301_22_dialog_content = "그럼 왜 당신은 아직도 여기 남은 거죠?",
  ui_story_1012_10121301_23_dialog_content = "갈 수 없습니다.",
  ui_story_1012_10121301_24_dialog_content = "대원수님께서 목숨을 바쳐 이곳을 지키라고 명하셨습니다.\n전 반드시 이곳에 남아 끝까지 싸워야 합니다.",
  ui_story_1012_10121301_25_dialog_content = "아하하, 그 이성적인 판단도 별 쓸모가 없네요. 일루미나의 병사님.",
  ui_story_1012_10121301_26_dialog_content = "군인인 이상 명령에 복종하는 것이 가장 중요합니다.\n저는 그저 이러한 조건 하에서는...",
  ui_story_1012_10121301_27_dialog_content = "네, 네. 잘 알겠어요.",
  ui_story_1012_10121301_28_dialog_content = "근데 어차피 눈앞의 상황을 바꿀 수 없다면...",
  ui_story_1012_10121301_29_dialog_content = "그 똑똑한 머리는 잠깐 쉬게 해 주고, 신나게 손이나 휘둘러 보자구요!",
  ui_story_1012_10121301_30_dialog_content = "어이쿠, 그건 곤란한데요. 아리따운 아가씨.",
  ui_story_1012_10121301_31_dialog_content = "자꾸 성가시게 굴면, 피제로 님이 화내실 겁니다.",
  ui_story_1012_10121301_32_dialog_content = "누구냐?!",
  ui_story_1012_10121301_33_dialog_content = "이건... 뭐지?",
  ui_story_1012_10121301_34_dialog_content = "조심하세요!",
  ui_story_1012_10121301_35_dialog_content = "쳇, 방해되는 녀석.",
  ui_story_1012_10121301_36_dialog_content = "나랑 예쁜 아가씨 둘만의 세계인 줄 알았는데, 어디서 사내놈이 끼어든 거야?!",
  ui_story_1012_10121301_37_dialog_content = "뭐야...?!",
  ui_story_1012_10121301_38_dialog_content = "조심하세요. 주변의 루미나가 극도로 제한된 상태인 것 같습니다.",
  ui_story_1012_10121301_39_dialog_content = "이곳에서는 힘을 제대로 발휘할 수 없을 겁니다.",
  ui_story_1012_10121301_40_dialog_content = "그런가요?",
  ui_story_1012_10121301_41_dialog_content = "그런 것보다 지금 제 머릿속엔 저 녀석 얼굴에\n한 방 먹이고 싶다는 생각만 가득하거든요!",
  ui_story_1012_10121301_42_dialog_content = "정말 열정적인 아가씨로군요.",
  ui_story_1012_10121301_43_dialog_content = "급할 거 없습니다. 우린 시간이 많이 있으니까요.",
  ui_story_1012_10121301_44_dialog_content = "그럼 천천히 서로에 대해 알아볼까요!",
  ui_story_1012_10121301_45_dialog_content = "그어어어──!",
  ui_story_1012_10121301_46_dialog_content = "......",
  ui_story_1012_10121301_47_dialog_content = "뒤쪽에 있는 자여, 그대는 나서지 않는가.",
  ui_story_1012_10121301_48_dialog_content = "......",
  ui_story_1012_10121301_49_dialog_content = "북방의 여왕...",
  ui_story_1012_10121301_49X1_dialog_content = "백야성 축제 때의 반역자, 기억하고 있다.",
  ui_story_1012_10121301_49X2_dialog_content = "그때의 그대는 더욱 날카로웠지.",
  ui_story_1012_10121301_50_dialog_content = "허나 지금 이 전장에서 주저하는 자는 그대 하나뿐이로구나.",
  ui_story_1012_10121301_51_dialog_content = "......",
  ui_story_1012_10121301_52_dialog_content = "북방의 여왕이여, 당신처럼 강한 자도 이 형세를 파악하지 못하는 건가?",
  ui_story_1012_10121301_53_dialog_content = "오로리안의 실패는 기정사실이다. 그런데도 어째서 계속 싸우는 거지?",
  ui_story_1012_10121301_54_dialog_content = "오로리안의 실패가 기정사실인데, 그대는 어째서 싸우려 하지 않는가.",
  ui_story_1012_10121301_55_dialog_content = "......",
  ui_story_1012_10121301_56_dialog_content = "싸울 것인가, 싸우지 않을 것인가는 이곳에 서기 전에\n확실하게 뜻을 정했어야 마땅한 일이다.",
  ui_story_1012_10121301_57_dialog_content = "지금 그대의 모습이라면, 금세라도 그 목숨을 잃을 것이다.",
  ui_story_1012_10121301_58_dialog_content = "그런가...",
  ui_story_1012_10121301_59_dialog_content = "그렇다면 어디...",
  ui_story_1012_10121301_60_dialog_content = "북방의 여왕에게 가르침을 청해 보겠다!",
  ui_story_1012_10121301_61_dialog_content = "으앗! 엄청 큰 괴물이네!",
  ui_story_1012_10121301_62_dialog_content = "저건... 여왕 폐하가 계시는 방향이잖아?",
  ui_story_1012_10121301_63_dialog_content = "여왕 폐하──!",
  ui_story_1012_10121301_64_dialog_content = "그어어어──!",
  ui_story_1012_10121301_65_dialog_content = "짜증 나는 녀석! 방해하지 마!",
  ui_story_1012_10121301_66_dialog_content = "난 여왕 폐하를 지켜 드려야 한다고...",
  ui_story_1012_10121301_67_dialog_content = "<color=#e8d9bb>쿠우웅──!</color>",
  ui_story_1012_10121301_68_dialog_content = "으악! 이 소리는 또 뭐야?",
  ui_story_1012_10121301_69_dialog_content = "여왕 폐하, 여왕 폐하.",
  ui_story_1012_10121301_70_dialog_content = "이 얼마나 유치한 충심인가.",
  ui_story_1012_10121301_71_dialog_content = "이 자식...",
  ui_story_1012_10121301_72_dialog_content = "그 여자는 충분히 강하다. 네 녀석 같은 햇병아리가 지켜 줄 필요도 없지.",
  ui_story_1012_10121301_73_dialog_content = "자기 앞가림이나 잘하는 편이 좋을 것이다.",
  ui_story_1012_10121301_74_dialog_content = "사냥놀이가 곧 시작될 테니 말이야.",
  ui_story_1012_10121301_75_dialog_content = "!!!",
  ui_story_1012_10121301_76_dialog_content = "으아아아──!",
  ui_story_1012_10121301_77_dialog_content = "후우... 후우...",
  ui_story_1012_10121301_78_dialog_content = "(몸이 따라가질 못하는군...)",
  ui_story_1012_10121301_79_dialog_content = "(화음 연결의 강화를 받았어도 이런 고강도의 전투는 역시... 무리였나...)",
  ui_story_1012_10121301_80_dialog_content = "(안 돼, 어떻게든 버텨야 해... 다른 사람들의 발목을 잡을 수는 없다!)",
  ui_story_1012_10121301_81_dialog_content = "바튼, 이제 한계구나.",
  ui_story_1012_10121301_82_dialog_content = "뭐야?!",
  ui_story_1012_10121301_83_dialog_content = "노라, 이 자식!",
  ui_story_1012_10121301_84_dialog_content = "우리 사이의 전투도 이제 드디어 마침표를 찍을 때가 됐어.",
  ui_story_1012_10121301_85_dialog_content = "네 묘비에는 「그대의 용기에 존경을」이라고 새겨 줄게.",
  ui_story_1012_10121301_86_dialog_content = "쳇, 이 몸 걱정은 접어두라고!",
  ui_story_1012_10121301_87_dialog_content = "받아라!",
  ui_story_1012_10121301_88_dialog_content = "어이! 무서워서 싸우지도 않겠다는 거냐!",
  ui_story_1012_10121301_89_dialog_content = "궁지에 몰린 짐승과 싸우는 취미는 없어. 그건 이 녀석들이 대신해 줄 거야.",
  ui_story_1012_10121301_90_dialog_content = "내가 관심 있는 건 네 뒤에 있는 귀환의 탑뿐이거든.",
  ui_story_1012_10121301_91_dialog_content = "그어어──",
  ui_story_1012_10121301_92_dialog_content = "농담은 집어치워!",
  ui_story_1012_10121301_93_dialog_content = "노라!",
  ui_story_1012_10121301_94_dialog_content = "노라──!",
  ui_story_1012_10121301_95_dialog_content = "<color=#e8d9bb>펑! 펑! 펑! 펑!</color>",
  ui_story_1012_10121301_96_dialog_content = "뭐냐... 이건...",
  ui_story_1012_10121301_97_dialog_content = "(바튼 씨, 어서 뒤로 물러나세요!)",
  ui_story_1012_10121301_98_dialog_content = "PlayerName! 돌아온 거냐!",
  ui_story_1012_10121301_99_dialog_content = "...이런.",
  ui_story_1012_10121301_100_dialog_content = "생각보다 그렇게 늦진 않았네.",
  ui_story_1012_10121301_101_dialog_content = "전황이 꽤 좋지 않군. 적도 상당히 많잖아.",
  ui_story_1012_10121301_102_dialog_content = "너희는 다른 곳을 지원해라!",
  ui_story_1012_10121301_103_dialog_content = "여긴 나 하나면 충분하다.",
  ui_story_1012_10121301_104_dialog_content = "우리 둘 사이에는 할 이야기가 아주 많거든.",
  ui_story_1012_10121301_105_dialog_content = "이야기? 이제 와서?",
  ui_story_1012_10121301_106_dialog_content = "하하, 나도 알고 있어. 우린 자기 할 말만 하고 남의 말은 안 듣는 스타일이지.",
  ui_story_1012_10121301_107_dialog_content = "그럼 이번에는 네가 알아듣는 언어로 이야기해 주마.",
  ui_story_1012_10121301_108_dialog_content = "이클립스 전체를 상대로, 네 폭력이 얼마나 설득력이 있을 것 같아?",
  ui_story_1012_10121301_109_dialog_content = "녀석들은 어찌 되든 좋다. 너 하나만 알아듣는다면 그걸로 충분하니까.",
  ui_story_1012_10121301_110_dialog_content = "보고드립니다. 콜로서스 정비 구역에 미등록 암귀가 침입했습니다.",
  ui_story_1012_10121301_111_dialog_content = "보고드립니다. 콜로서스 부품 공장에 미등록 암귀가 침입했습니다.",
  ui_story_1012_10121301_112_dialog_content = "보고드립니다. 폐기물 처리 구역에 미등록 암귀가 침입했습니다.",
  ui_story_1012_10121301_113_dialog_content = "보고만 하지 말고! 어떻게 좀 해 봐!",
  ui_story_1012_10121301_114_dialog_content = "귀환의 탑의 자기방어 시설을 검사합니다...",
  ui_story_1012_10121301_115_dialog_content = "죄송합니다. 자기방어 시설이 심각한 손상을 입었습니다.\n귀환의 탑의 자기방어 능력에 결함이 발생했습니다.",
  ui_story_1012_10121301_116_dialog_content = "그렇겠네. 그게 가능했으면 노라를 상대할 때 썼겠지.",
  ui_story_1012_10121301_117_dialog_content = "PlayerName, 에이드 브레인이 또 통신을 보낸 거야?",
  ui_story_1012_10121301_118_dialog_content = "응, 탑 안에 암귀가 침입했다고 알려주고 있어.",
  ui_story_1012_10121301_119_dialog_content = "지금 상황은 탑의 암귀만 처치한다고 해결될 일이 아니야.",
  ui_story_1012_10121301_120_dialog_content = "탑 밖의 상황에 변화가 생기지 않는 이상,\n귀환의 탑은 결국 이클립스에게 점령당하고 말 거야.",
  ui_story_1012_10121301_121_dialog_content = "어떻게 해야 상황을 변화시킬 수 있을까...",
  ui_story_1012_10121301_122_dialog_content = "라인하르트 씨랑 베들레헴 씨처럼 강력한 오로리안이 우리와 함께 싸워 주고 있는데도...",
  ui_story_1012_10121301_122X1_dialog_content = "상황은 계속 나빠지고 있잖아.",
  ui_story_1012_10121301_123_dialog_content = "우리한테 남은 카드는...",
  ui_story_1012_10121301_124_dialog_content = "...그래! 에이드 브레인이 말했던 그 최종병기 「율법의 현」이 있었잖아!",
  ui_story_1012_10121301_125_dialog_content = "보고드립니다. 자원 생산 구역에 미등록 암귀가 침입했습니다.",
  ui_story_1012_10121301_126_dialog_content = "보고드립니다. 아이테르 생활 구역에 미등록 암귀가 침입했습니다.",
  ui_story_1012_10121301_127_dialog_content = "그런 소식은 그만 보고하고 빨리 「율법의 현」을 가동하는 방법을 알려줘!",
  ui_story_1012_10121301_128_dialog_content = "그게 어떤 작용을 할지는 모르겠지만, 지금은 시도해 보는 수밖에 없어!",
  ui_story_1012_10121301_129_dialog_content = "???",
  ui_story_1012_10121301_130_dialog_content = "잘못된 요청이 감지되었습니다.",
  ui_story_1012_10121301_131_dialog_content = "그 어떤 아이테르도 「율법의 현」과 접촉할 수 없습니다.\n이는 「명령」에 의한 것입니다.",
  ui_story_1012_10121301_132_dialog_content = "이럴 때까지 무슨 명령 타령이야?!",
  ui_story_1012_10121301_133_dialog_content = "이클립스가 이기면 우리뿐만 아니라 귀환의 탑도 끝장이라고!",
  ui_story_1012_10121301_134_dialog_content = "그런 일이 일어나길 바라는 거야?!",
  ui_story_1012_10121301_135_dialog_content = "죄송합니다. 에이드 브레인은 그 어떤 일도 일어나기를 바라지 않습니다.",
  ui_story_1012_10121301_136_dialog_content = "에이드 브레인은 「명령」에 복종합니다.",
  ui_story_1012_10121301_137_dialog_content = "뭐야...?!",
  ui_story_1012_10121301_138_dialog_content = "너 때문에 속 터져 죽겠네!",
  ui_story_1012_10121301_139_dialog_content = "관두자, PlayerName. 인공지능이랑 싸울 거 없어.",
  ui_story_1012_10121301_140_dialog_content = "우선 최선을 다해 보자. 모든 세력의 군대가 이쪽으로 모이는 중일 거야.",
  ui_story_1012_10121301_141_dialog_content = "그때까지 우리가 버틸 수 있길 빌어보자.",
  ui_story_1012_10121301_142_dialog_content = "휴, 그래. 최선을 다해야지.",
  ui_story_1012_10121301_143_dialog_content = "보고드립니다. 핵심 중추 구역에 미등록 암귀가 침입했습니다.",
  ui_story_1012_10121301_144_dialog_content = "삐! 삐! 삐! 삐! 삐! 삐!",
  ui_story_1012_10121301_145_dialog_content = "아, 시끄러워 죽겠네!",
  ui_story_1012_10121301_146_dialog_content = "에이드 브레인, 도움도 안 줄 거면 적어도 조용히 있어 줄 순 없어?",
  ui_story_1012_10121301_147_dialog_content = "사전 설정 조건에 도달했습니다. 시간 지연 명령을 우선해서 실행합니다.",
  ui_story_1012_10121301_148_dialog_content = "해당 명령의 출처는 「프란츠」입니다. 명령의 우선도는 「최고」입니다.",
  ui_story_1012_10121301_149_dialog_content = "에이드 브레인 에이전트의 기저 논리를 변경하는 중입니다...",
  ui_story_1012_10121301_150_dialog_content = "프란츠... 또 그 사람이야. 이번에는 또 뭘 하는 건데?",
  ui_story_1012_10121301_151_dialog_content = "기저 논리 변경이 완료되었습니다.",
  ui_story_1012_10121301_152_dialog_content = "현재 종족의 존속 위기에 직면한 것으로 판단되었으므로,\n에이드 브레인은 아이테르에게 「율법의 현」의 작동 방법을 알려 드리겠습니다.",
  ui_story_1012_10121301_153_dialog_content = "뭐라고?!",
  ui_story_1012_10121301_154_dialog_content = "아, 알려주겠다고? 근데 이렇게 갑자기?!",
  ui_story_1012_10121301_155_dialog_content = "그렇습니다. 사전 설정된 명령이 에이드 브레인에게 이 항목을 실행하도록 만들었습니다.",
  ui_story_1012_10121301_156_dialog_content = "프란츠 선배님... 누구신지는 몰라도 일단 고마워요!",
  ui_story_1012_10121301_157_dialog_content = "얼른 말해 봐. 어떻게 하면 되는데?",
  ui_story_1012_10121301_158_dialog_content = "핵심 중추 구역으로 이동해 의식을 서클 시스템으로 침투시켜야 합니다.",
  ui_story_1012_10121301_159_dialog_content = "그 후 서클 시스템의 가장 깊은 곳에서 「오리진 서클 권한」을 탈취하십시오.",
  ui_story_1012_10121301_160_dialog_content = "「오리진 서클 권한」을 탈취해야만 「율법의 현」을 작동할 수 있습니다.",
  ui_story_1012_10121301_161_dialog_content = "「오리진 서클 권한」? 그건 건드릴 수 없는 최고 권한이라고 하지 않았어?",
  ui_story_1012_10121301_162_dialog_content = "그렇습니다. 그러므로 「탈취」라는 단어를 사용한 것입니다.",
  ui_story_1012_10121301_163_dialog_content = "이 행위는 규정을 위반하고, 금기를 어기는 행위입니다.",
  ui_story_1012_10121301_164_dialog_content = "이 과정을 진행하면 도중에 사망할 가능성이 매우 높습니다.",
  ui_story_1012_10121301_165_dialog_content = "사망할 가능성이 매우 높다고?!",
  ui_story_1012_10121301_166_dialog_content = "구체적으로 왜 그런 건데?",
  ui_story_1012_10121301_167_dialog_content = "죄송합니다. 에이드 브레인도 「오리진 서클 권한」에 관한 정보는 알지 못합니다.",
  ui_story_1012_10121301_168_dialog_content = "에이드 브레인이 받은 명령은 아이테르에게 「율법의 현」 작동법을 알리는 것입니다.",
  ui_story_1012_10121301_169_dialog_content = "그리고 이를 위해서는 「오리진 서클 권한」이 있어야만 합니다.",
  ui_story_1012_10121301_170_dialog_content = "......",
  ui_story_1012_10121301_171_dialog_content = "다른 선택지는 없는 거네. 그렇지?",
  ui_story_1012_10121301_172_dialog_content = "카렌, 전황을 바꿀 방법을 찾았어.",
  ui_story_1012_10121301_173_dialog_content = "가자, 핵심 중추 구역으로 돌아가야 돼. 「율법의 현」을 작동시킬 거야.",
  ui_story_1012_10121301_174_dialog_content = "「율법의 현」?! 에이드 브레인이 방법을 가르쳐 준 거야?",
  ui_story_1012_10121301_175_dialog_content = "응, 맞아.",
  ui_story_1012_10121301_176_dialog_content = "과정이 어렵지는 않아? 내가 도울 게 있을까?",
  ui_story_1012_10121301_177_dialog_content = "탑 안에 아직 암귀들이 있으니까, 나랑 같이 핵심 중추 구역까지 가주기만 하면 돼.",
  ui_story_1012_10121301_178_dialog_content = "나머지는 나 혼자서 해야만 하는 일이야.",
  ui_story_1012_10121301_179_dialog_content = "라인하르트 씨, 들리세요?",
  ui_story_1012_10121301_180_dialog_content = "오! 무슨 일이지? 지원이 필요한가?",
  ui_story_1012_10121301_181_dialog_content = "그렇다고 할 수 있겠네요. 전 지금 귀환의 탑의 최종병기를 가동하러 갈 거예요.",
  ui_story_1012_10121301_182_dialog_content = "그 사이에는 여러분과 함께 싸울 수 없어요.",
  ui_story_1012_10121301_183_dialog_content = "그리고 죄송하지만 시간을 좀 끌어 주세요.",
  ui_story_1012_10121301_184_dialog_content = "병기가 가동되기 전에, 적이 귀환의 탑을 공격하지 않도록요.",
  ui_story_1012_10121301_185_dialog_content = "최종병기라! 그거 엄청난 녀석이겠네.",
  ui_story_1012_10121301_186_dialog_content = "이 거대한 탑의 병기, 고대 문명이 남긴 힘...",
  ui_story_1012_10121301_187_dialog_content = "나도 한번 보고 싶군, 아이테르!",
  ui_story_1012_10121301_188_dialog_content = "하하, 성공할 수 있을지는 잘 모르겠지만요.",
  ui_story_1012_10121301_189_dialog_content = "전장의 상황은 걱정 마라. 내가 탑의 정면을 지키도록 하지.",
  ui_story_1012_10121301_190_dialog_content = "일루미나 대원수의 숨통을 끊고 싶다면, 우선 암귀들의 시체로 산부터 쌓아야 할 거다!",
  ui_story_1012_10121301_191_dialog_content = "......",
  ui_story_1012_10121301_192_dialog_content = "여왕 폐하, 들리시나요?",
  ui_story_1012_10121301_193_dialog_content = "전...",
  ui_story_1012_10121301_194_dialog_content = "마음 놓고 다녀오너라.",
  ui_story_1012_10121301_195_dialog_content = "!!!",
  ui_story_1012_10121301_196_dialog_content = "각지의 찬란한 별들이 모두 이곳에 모였구나.\n저들은 날이 밝는 그 순간까지 빛날 것이다.",
  ui_story_1012_10121301_197_dialog_content = "그대는 어둠을 헤쳐 나아가라.",
  ui_story_1012_10121301_198_dialog_content = "여왕 폐하...",
  ui_story_1012_10121301_199_dialog_content = "그리고...",
  ui_story_1012_10121301_200_dialog_content = "살아서 돌아오거라.",
  ui_story_1012_10121302_1_dialog_content = "크에엑...",
  ui_story_1012_10121302_2_dialog_content = "핵심 중추 구역은 바로 이 앞이야. 서두르자!",
  ui_story_1012_10121302_3_dialog_content = "응!",
  ui_story_1012_10121302_4_dialog_content = "근데 주변의 암귀들이 점점 더 많아지고 있는 것 같지 않아?",
  ui_story_1012_10121302_5_dialog_content = "맞아, 아마 우리가 싸우면서 녀석들의 주의를 끈 거겠지.",
  ui_story_1012_10121302_6_dialog_content = "최악의 상황은 귀환의 탑 안의 모든 암귀가 우리 쪽으로 몰려오는 거야.",
  ui_story_1012_10121302_7_dialog_content = "그건 너무 끔찍하잖아. 핵심 중추 구역까지 가는 길은 안 그래도 딱 하난데.",
  ui_story_1012_10121302_8_dialog_content = "에이드 브레인, 진짜로 무슨 자기방어 수단 같은 거 없어?",
  ui_story_1012_10121302_9_dialog_content = "핵심 중추 구역의 자기방어 수단은 「가디언 시스템」입니다.",
  ui_story_1012_10121302_10_dialog_content = "하지만 기록에 따르면 해당 시스템은 얼마 전 외부 요소에 의해 파괴되었습니다.",
  ui_story_1012_10121302_11_dialog_content = "아... 그거 우리가 한 거야. 진짜 미안해.",
  ui_story_1012_10121302_12_dialog_content = "또 암귀가 따라붙었어! 서둘러!",
  ui_story_1012_10121302_13_dialog_content = "아, 알겠어!",
  ui_story_1012_10121302_14_dialog_content = "<color=#e8d9bb>뚜벅, 뚜벅, 뚜벅, 뚜벅, 뚜벅...</color>",
  ui_story_1012_10121302_15_dialog_content = "도, 도착했어!",
  ui_story_1012_10121302_16_dialog_content = "그어어어!",
  ui_story_1012_10121302_17_dialog_content = "으아아아아악!",
  ui_story_1012_10121302_18_dialog_content = "휴우, 고마워, 카렌.",
  ui_story_1012_10121302_19_dialog_content = "얼른 가 봐, 네가 할 일이 있잖아.",
  ui_story_1012_10121302_20_dialog_content = "가서 「율법의 현」을 가동시켜.",
  ui_story_1012_10121302_21_dialog_content = "근데 아직도 암귀들이 꽤 많이 따라붙은 것 같아.",
  ui_story_1012_10121302_22_dialog_content = "일단 녀석들부터 처리할까?",
  ui_story_1012_10121302_23_dialog_content = "암귀들이 얼마나 남았는지도 모르잖아. 이래서는 언제 끝날지도 알 수 없어.",
  ui_story_1012_10121302_24_dialog_content = "그러니까 녀석들은 내게 맡겨.",
  ui_story_1012_10121302_25_dialog_content = "뭐? 혼자서 상대하겠다고?",
  ui_story_1012_10121302_26_dialog_content = "넌 병기를 가동하러 가. 암귀는 내가 상대할 테니까.",
  ui_story_1012_10121302_27_dialog_content = "아이테르와 오로리안으로서, 서로가 해야 할 일을 하는 거야.",
  ui_story_1012_10121302_28_dialog_content = "하지만 수가 너무 많잖아...",
  ui_story_1012_10121302_29_dialog_content = "넌 날 믿으면 돼.",
  ui_story_1012_10121302_30_dialog_content = "내가 널 믿는 것처럼.",
  ui_story_1012_10121302_31_dialog_content = "얼어붙어라!",
  ui_story_1012_10121302_32_dialog_content = "......",
  ui_story_1012_10121302_33_dialog_content = "응. 믿을게, 카렌.",
  ui_story_1012_10121302_34_dialog_content = "그럼 나도 시작해 볼까.",
  ui_story_1012_10121302_35_option_content = "(강제 감응!)",
  ui_story_1012_10121302_36_dialog_content = "<color=#e8d9bb>위이잉──!</color>",
  ui_story_1012_10121302_37_dialog_content = "(다시 서클 시스템에 들어왔다.)",
  ui_story_1012_10121302_38_dialog_content = "(이제 알 것 같다. 이 서클 시스템은 의식 계층 속에 있는 공간이다.)",
  ui_story_1012_10121302_39_dialog_content = "(여기 정보가 저장되면, 내 의식은 이 공간 속을 이동하며 필요한 정보를 찾을 수 있다.)",
  ui_story_1012_10121302_40_dialog_content = "(에이드 브레인은 귀환의 탑의 정보와 기능이 「아우터 서클」, 「이너 서클」,\n그리고 「오리진 서클」 세 등급으로 나뉘어 있다고 했었다.)",
  ui_story_1012_10121302_41_dialog_content = "(「서클」이라는 이름이 붙은 건, 아마 서클 시스템 안의 위치에 따라\n권한을 구분 지었기 때문일지도 모른다.)",
  ui_story_1012_10121302_42_dialog_content = "(이 서클 시스템의 가장 깊은 곳이 바로 「오리진 서클」이라고 했으니,\n중심부와 가까울수록 요구하는 권한이 더 높아지는 것이 아닐까?)",
  ui_story_1012_10121302_43_dialog_content = "(내 추측이 맞다면, 이건 정말 신기하면서도 규칙적인 배열 방식인 것 같다.)",
  ui_story_1012_10121302_44_dialog_content = "(아무튼, 서클 시스템의 중심으로 이동해 보자.)",
  ui_story_1012_10121302_45_dialog_content = "어라? 더 못 가는 건가?",
  ui_story_1012_10121302_46_dialog_content = "이 깊이 이상으로는 가기가 힘들어...",
  ui_story_1012_10121302_47_dialog_content = "더 깊이 들어오지 마십시오.",
  ui_story_1012_10121302_48_dialog_content = "!!!",
  ui_story_1012_10121302_49_dialog_content = "아이테르는 「오리진 서클」에 접근해선 안 됩니다.",
  ui_story_1012_10121302_50_dialog_content = "이는 <color=#FFB400>명령</color>입니다.",
  ui_story_1012_10121302_51_dialog_content = "명령, 또 그 소리야?",
  ui_story_1012_10121302_52_dialog_content = "대체 명령이라는 게 뭔데 그래?",
  ui_story_1012_10121302_53_dialog_content = "대, 대체 왜 그런 말 따위에 복종해야 하는 거냐고...",
  ui_story_1012_10121302_54_dialog_content = "어라...?",
  ui_story_1012_10121302_55_dialog_content = "나... 갑자기 뭘 무서워하고 있는 거지?",
  ui_story_1012_10121302_56_dialog_content = "<color=#FFB400>명령</color>은 최초이자 최고의 지시입니다.",
  ui_story_1012_10121302_57_dialog_content = "그것은 당신이 탄생하기 전, 아이테르 일족이 이 땅에 나타나기 전부터 존재했습니다.",
  ui_story_1012_10121302_58_dialog_content = "그리고 그것은 당신의 의식과 혈액, 그리고 육체에 녹아 들어 있습니다.",
  ui_story_1012_10121302_59_dialog_content = "그것은 아이테르 일족이 따라야만 하는 신조이자,\n아이테르가 이 세상에 태어난 이유이기도 합니다.",
  ui_story_1012_10121302_60_dialog_content = "그것은 당신에게 운명으로 정해진 「선천성」인 것입니다.",
  ui_story_1012_10121302_61_dialog_content = "내 의식이... 뒷걸음질 치고 있어!",
  ui_story_1012_10121302_62_dialog_content = "설마... 내가 진짜로 이 명령이라는 것에 복종하고 있는 건가?",
  ui_story_1012_10121302_63_dialog_content = "마치 본능처럼...",
  ui_story_1012_10121302_64_dialog_content = "아이테르는 「오리진 서클」에 접근해선 안 됩니다.",
  ui_story_1012_10121302_65_dialog_content = "이는 <color=#FFB400>명령</color>입니다.",
  ui_story_1012_10121302_66_dialog_content = "(내 의식이 명령을 따르고 있어... 마치 더 강력한 의식이 내 생각을 조종하는 것처럼.)",
  ui_story_1012_10121302_67_dialog_content = "(이걸로 확실하게 깨달았어.)",
  ui_story_1012_10121302_68_dialog_content = "(명령에 복종해 버리면 그 한순간뿐만이 아니라,\n내 평생을 그 명령이라는 틀에 갇혀 살게 된다는 걸.)",
  ui_story_1012_10121302_69_dialog_content = "(선천성의 강력한 구속이 내 마음속 깊은 곳에 새겨지게 될 거야.)",
  ui_story_1012_10121302_70_dialog_content = "(그렇게 된다면 모든 게 다 끝장이야.)",
  ui_story_1012_10121302_71_dialog_content = "(「율법의 현」은 다시 가동하는 일이 없을 거고,\n바깥에서 펼쳐지는 전장도 다시는 전세를 뒤집을 수 없을 거야.)",
  ui_story_1012_10121302_72_dialog_content = "(내가 가진 단 한 번의 기회는, 바로 지금뿐이야.)",
  ui_story_1012_10121302_73_dialog_content = "움직여, 움직이라고! 더 깊은 곳으로 가야 해!",
  ui_story_1012_10121302_74_dialog_content = "명령 따윈 상관없어! 그딴 건 믿지 마!",
  ui_story_1012_10121302_75_dialog_content = "뭐가 운명으로 정해진 선천성이라는 거야?\n지금까지 살면서 한 번도 드러난 적 없었잖아!",
  ui_story_1012_10121302_76_dialog_content = "뭘 믿고 갑자기 나타나서 내 앞을 막아서는 거냐고!",
  ui_story_1012_10121302_77_dialog_content = "더 깊이 들어오지 마십시오.",
  ui_story_1012_10121302_78_dialog_content = "아이테르는 「오리진 서클」에 접근해선 안 됩니다.",
  ui_story_1012_10121302_79_dialog_content = "이는 <color=#FFB400>명령</color>입니다.",
  ui_story_1012_10121302_80_dialog_content = "내가 지금까지 살아있을 수 있었던 건 명령 때문이 아니야!\n그건 목숨을 바쳐 날 지켜준 부모님, 그리고 스카이워커호 덕분이고...",
  ui_story_1012_10121302_81_dialog_content = "나를 발견해 준 바이스, 그리고 나와 함께 싸워 준 오로리안들 덕분이라고!",
  ui_story_1012_10121302_82_dialog_content = "저들이야말로 내가 살아가는 명령이야!",
  ui_story_1012_10121302_83_dialog_content = "더 깊이 들어오지 마십시오.",
  ui_story_1012_10121302_84_dialog_content = "더 깊이 들어오지...",
  ui_story_1012_10121302_85_dialog_content = "어? 성공한 거야?",
  ui_story_1012_10121302_86_dialog_content = "이게 바로... 가장 깊은 곳의 「오리진 서클」?",
  ui_story_1012_10121302_87_dialog_content = "잠깐만, 이건...",
  ui_story_1012_10121302_87X1_dialog_content = "여기 왠지 전에 본 적이 있는 것 같아.\n왠지 거울 호수의 얼어붙은 수면 같기도 하고, 하늘의 오로라 같기도 해.",
  ui_story_1012_10121302_87X2_dialog_content = "이건... 내 상상인가? 근데 정말 현실 같아.\n심지어 몸에서 호수면의 한기가 느껴져.",
  ui_story_1012_10121302_88_dialog_content = "여긴 공간화된 의식이라기보다는... 오히려 실제로 존재하는 공간 같잖아.",
  ui_story_1012_10121302_89_dialog_content = "내 의식이... 내 모습대로 구현됐어! 신기하네...",
  ui_story_1012_10121302_90_dialog_content = "아마 「전투 시뮬레이터」랑 비슷한 기술인 건가?",
  ui_story_1012_10121302_91_dialog_content = "그럼... 이제 「오리진 서클」 안에서 뭘 해야 되지?\n에이드 브레인이 그건 말을 안 했던 것 같은데.",
  ui_story_1012_10121302_92_dialog_content = "야, 에이드 브레인! 내 말 들려?",
  ui_story_1012_10121302_93_dialog_content = "「오리진 서클」에 도착했어. 이제 어떻게 해야 돼?",
  ui_story_1012_10121302_94_dialog_content = "<color=#e8d9bb>덜컹──</color>",
  ui_story_1012_10121302_95_dialog_content = "응? 무슨 소리지?",
  ui_story_1012_10121302_96_dialog_content = "<color=#e8d9bb>철컥── 철컥──</color>",
  ui_story_1012_10121302_97_dialog_content = "......",
  ui_story_1012_10121302_98_dialog_content = "......",
  ui_story_1012_10121302_99_dialog_content = "잠깐만, 이건, 가디언이잖아?!",
  ui_story_1012_10121302_100_dialog_content = "가디언이 왜 여기 나타난 건데?",
  ui_story_1012_10121302_101_dialog_content = "<color=#e8d9bb>쿵── 쿵──</color>",
  ui_story_1012_10121302_102_dialog_content = "「오리진 서클」에 난입한 아이테르, 당신은 금기를 어겼습니다.",
  ui_story_1012_10121302_103_dialog_content = "「오리진 서클 권한」은 최고 관리자에게만 부여됩니다.\n그 외의 인물이 접근해서는 안 됩니다.",
  ui_story_1012_10121302_104_dialog_content = "분수에 지나친 행동은 반드시 제지되어야 합니다.",
  ui_story_1012_10121302_105_dialog_content = "아이테르는 선천적으로 힘을 가질 수 없습니다.\n따라서 힘으로 율법을 실행합니다.",
  ui_story_1012_10121302_106_dialog_content = "아니지...? 가디언이 둘이나 있다고?!",
  ui_story_1012_10121302_107_dialog_content = "이 행위는 규정을 위반하고, 금기를 어기는 행위입니다.",
  ui_story_1012_10121302_108_dialog_content = "이 과정을 진행하면 도중에 사망할 가능성이 매우 높습니다.",
  ui_story_1012_10121302_109_dialog_content = "이...이런 거랑 싸워야 한다는 거야...?",
  ui_story_1012_10121302_110_dialog_content = "<color=#e8d9bb>삑...</color>",
  ui_story_1012_10121302_111_dialog_content = "<color=#e8d9bb>삑...</color>",
  ui_story_1012_10121302_112_dialog_content = "<color=#e8d9bb>삑...</color>",
  ui_story_1012_10121302_113_dialog_content = "<color=#e8d9bb>삑──</color>",
  ui_story_1012_10121302_114_dialog_content = "......",
  ui_story_1012_10121401_1_dialog_content = "하아... 하아...",
  ui_story_1012_10121401_2_dialog_content = "이 녀석...",
  ui_story_1012_10121401_3_dialog_content = "(엄청난 힘이야...)",
  ui_story_1012_10121401_4_dialog_content = "작은 사냥감아, 더는 도망칠 수 없는 게냐?",
  ui_story_1012_10121401_5_dialog_content = "너, 넌 날아다니니까 당연히 안 힘들지!",
  ui_story_1012_10121401_6_dialog_content = "그리고 말은 똑바로 해. 누가 도망을 쳤다는 거야?!",
  ui_story_1012_10121401_7_dialog_content = "크크크, 그 눈에서 기운이 쇠한 것이 보이는구나. 그건 위험한 징조다.",
  ui_story_1012_10121401_8_dialog_content = "사냥을 할 때 가장 즐거운 것은 바로 사냥감이 지친 모습을 보이는 그 순간이다.",
  ui_story_1012_10121401_9_dialog_content = "곧 손에 들어 올 듯 말 듯한 그 느낌은 얼마나 흥분되는 것이란 말이냐!",
  ui_story_1012_10121401_10_dialog_content = "...이 변태 노친네가!",
  ui_story_1012_10121401_11_dialog_content = "으으...",
  ui_story_1012_10121401_12_dialog_content = "크크크! 어서, 계속 도망쳐 봐라!",
  ui_story_1012_10121401_13_dialog_content = "조금 더 살아 보겠다고 생명의 마지막 불꽃을 활활 태우란 말이다!",
  ui_story_1012_10121401_14_dialog_content = "난 도망치지 않아...",
  ui_story_1012_10121401_15_dialog_content = "나...난 여왕님의 호위라고!",
  ui_story_1012_10121401_16_dialog_content = "<color=#e8d9bb>파직... 파지직, 파지지직...</color>",
  ui_story_1012_10121401_17_dialog_content = "어? 뭐지...?",
  ui_story_1012_10121401_18_dialog_content = "<color=#e8d9bb>콰앙──!</color>",
  ui_story_1012_10121401_19_dialog_content = "콜록콜록... 퉷...",
  ui_story_1012_10121401_20_dialog_content = "휴... 괜찮아요? 일루미나 병사님?",
  ui_story_1012_10121401_21_dialog_content = "저는 괜찮습니다... 어쨌든 결계에서 탈출했군요.",
  ui_story_1012_10121401_22_dialog_content = "그래도 조심해야 합니다...",
  ui_story_1012_10121401_23_dialog_content = "아깝구나, 아까워. 놀이가 벌써 끝나버리다니.",
  ui_story_1012_10121401_24_dialog_content = "내가 만든 세계가 마음에 안 들었나?\n왜 목숨을 걸고서까지 밖으로 뛰쳐나온 걸까?",
  ui_story_1012_10121401_25_dialog_content = "지금 너희 꼴을 봐서는 그냥 장소를 바꿔서 죽을 뿐이야.",
  ui_story_1012_10121401_26_dialog_content = "짜증 나는 녀석...",
  ui_story_1012_10121401_27_dialog_content = "어라, 그쪽은... 북방 여왕의 호위병?",
  ui_story_1012_10121401_28_dialog_content = "당신들도 있었군요...",
  ui_story_1012_10121401_29_dialog_content = "다들 싸울 수 있겠어요?",
  ui_story_1012_10121401_30_dialog_content = "상황이 좋지 않아요...",
  ui_story_1012_10121401_31_dialog_content = "딱 봐도 알겠네요. 하늘에 있는 저 녀석이 놈들의 우두머리죠?",
  ui_story_1012_10121401_32_dialog_content = "잘했다, 밀렌. 잘했어.",
  ui_story_1012_10121401_33_dialog_content = "사냥감을 한데 몰아놓았구나. 이래야 깔끔한 사냥 아니겠나!",
  ui_story_1012_10121401_34_dialog_content = "조심해!",
  ui_story_1012_10121401_35_dialog_content = "엄청난 다크매터입니다...",
  ui_story_1012_10121401_36_dialog_content = "우리 여력으로 버틸 수 있는 건 앞으로 한 번 정도일지도...",
  ui_story_1012_10121401_37_dialog_content = "일루미나! 뒤쪽이에요!",
  ui_story_1012_10121401_38_dialog_content = "이런, 들켜버렸네.",
  ui_story_1012_10121401_39_dialog_content = "제길...",
  ui_story_1012_10121401_40_dialog_content = "(큰일이야. 벗어날 수가 없겠어.)",
  ui_story_1012_10121401_41_dialog_content = "자기 무능함을 깨닫고 이를 꽉 깨문 그 표정...",
  ui_story_1012_10121401_42_dialog_content = "애교인 셈 쳐줄게.",
  ui_story_1012_10121401_43_dialog_content = "이 변태 자식!",
  ui_story_1012_10121401_44_dialog_content = "위쪽! 하늘에서 녀석이 또 와요!",
  ui_story_1012_10121401_45_dialog_content = "?!",
  ui_story_1012_10121401_46_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_1012_10121401_47_dialog_content = "으윽...",
  ui_story_1012_10121401_48_dialog_content = "왼손이... 안 움직여...",
  ui_story_1012_10121401_49_dialog_content = "으... 아파...",
  ui_story_1012_10121401_50_dialog_content = "콜록... 콜록콜록... 크윽...",
  ui_story_1012_10121401_51_dialog_content = "쯧쯧, 그토록 고통스러워하는 모습들을 보니 가슴이 참 아프구나.",
  ui_story_1012_10121401_52_dialog_content = "피제로 님, 열등한 오로리안들일 뿐입니다. 동정하실 필요 없습니다.",
  ui_story_1012_10121401_53_dialog_content = "어쩔 수 없다. 나는 저들의 눈에 있던 자그마한 빛이 꺼져갈 때마다 감동을 받곤 한다.",
  ui_story_1012_10121401_54_dialog_content = "설령 적이라고 해도 연민을 보이시다니, 피제로 님께서는 정말 위대하십니다.",
  ui_story_1012_10121401_55_dialog_content = "위대하다? 그런 말로 나를 욕보이지 마라.",
  ui_story_1012_10121401_56_dialog_content = "허나... 그렇지, 저들에겐 동정을 베풀어야겠군.",
  ui_story_1012_10121401_57_dialog_content = "이 아이들의 고통을 내 손으로 끝내 주겠다.",
  ui_story_1012_10121401_58_dialog_content = "그러한가.",
  ui_story_1012_10121401_59_dialog_content = "뭐냐?! 이건...",
  ui_story_1012_10121401_60_dialog_content = "동정을 베푸는 자는 만인의 위에 군림해야 하는 법.",
  ui_story_1012_10121401_61_dialog_content = "그대는 그럴 그릇이 되지 못한다.",
  ui_story_1012_10121401_62_dialog_content = "북방 여왕...!",
  ui_story_1012_10121401_63_dialog_content = "미켈란젤로 그 자식은 어떻게 했지?",
  ui_story_1012_10121401_64_dialog_content = "나의 발목을 잡아둘 재목은 아니었다.",
  ui_story_1012_10121401_65_dialog_content = "빌어먹을!",
  ui_story_1012_10121401_66_dialog_content = "이번 전쟁은 오로리안에게도, 그대들에게도 힘든 전쟁이다.",
  ui_story_1012_10121401_67_dialog_content = "그대는 이미 오래도록 도망쳐 왔지.",
  ui_story_1012_10121401_68_dialog_content = "허나 끝이 다가오기 전, 그대는 결국 나와 마주하게 되어 있다.",
  ui_story_1012_10121401_69_dialog_content = "이것이 바로 그대가 이 전쟁에서 치러야 할 대가다.",
  ui_story_1012_10121401_70_dialog_content = "여왕 폐하! 여왕 폐하께서 우릴 도우러 와 주셨어!",
  ui_story_1012_10121401_71_dialog_content = "북방의 여왕... 정말 엄청난 힘이야...",
  ui_story_1012_10121401_72_dialog_content = "그대들이 한계에 다다랐다는 것은 알고 있다.",
  ui_story_1012_10121401_73_dialog_content = "허나 조금만 더 버텨다오. 전쟁은 아직도 계속될 것이다.",
  ui_story_1012_10121401_74_dialog_content = "아이테르가 전황을 바로잡을 방법을 시도하고 있다.\n우린 귀환의 탑을 지키고, 그를 위해 시간을 벌어야 한다.",
  ui_story_1012_10121401_75_dialog_content = "그전까지는 이 상처뿐인 참상에 마침표를 찍을 수 없다.",
  ui_story_1012_10121401_76_dialog_content = "아이테르...",
  ui_story_1012_10121401_77_dialog_content = "이 전쟁의 승패를 그 유약한 소년에게 맡기신다는 겁니까?",
  ui_story_1012_10121401_78_dialog_content = "나는 그를 믿는다.",
  ui_story_1012_10121401_79_dialog_content = "부디 그대들도 그를 믿어 주길 바란다.",
  ui_story_1012_10121401_80_dialog_content = "믿습니다! 여왕 폐하께서 믿으신다면 당연히 저도 믿습니다!",
  ui_story_1012_10121401_81_dialog_content = "......",
  ui_story_1012_10121401_82_dialog_content = "좋습니다. 북방 여왕의 판단이라면 제 판단보다 훨씬 가치가 있겠죠.",
  ui_story_1012_10121401_83_dialog_content = "저희도 전투를 포기할 생각은 없었습니다.",
  ui_story_1012_10121401_84_dialog_content = "다만 걱정되는 점은...",
  ui_story_1012_10121401_85_dialog_content = "저희에게 탑을 지킬 힘이 남아 있을까요?",
  ui_story_1012_10121401_86_dialog_content = "그것은 가장 염려할 필요가 없는 일이다.",
  ui_story_1012_10121401_87_dialog_content = "전쟁을 위해 태어난 이가 아직 하얀 탑의 입구를 지키고 있으니 말이다.",
  ui_story_1012_10121401_88_dialog_content = "『후퇴해! 어서!』",
  ui_story_1012_10121401_89_dialog_content = "『최대한 빨리! 가능한 멀리 떨어져!』",
  ui_story_1012_10121401_90_dialog_content = "『노라 님, 피제로 님께서는 그 어떤 대가를 치르든 진격하라고 하셨습니다.』",
  ui_story_1012_10121401_91_dialog_content = "『그런데 어째서...』",
  ui_story_1012_10121401_92_dialog_content = "『내가 후퇴하라고 하잖아! 지금 당장!』",
  ui_story_1012_10121401_93_dialog_content = "『...노라 님?』",
  ui_story_1012_10121401_94_dialog_content = "『적어도 지금은 꼭 물러서야 해!』",
  ui_story_1012_10121401_95_dialog_content = "『너희의 임무는 진격이지, 개죽음이 아니야!』",
  ui_story_1012_10121401_96_dialog_content = "<color=#e8d9bb>콰르릉! 쾅── 쾅── 콰앙──!</color>",
  ui_story_1012_10121401_97_dialog_content = "뭐지?!",
  ui_story_1012_10121401_98_dialog_content = "하얀 탑 입구에... 무슨 일이...",
  ui_story_1012_10121401_99_dialog_content = "뭐, 뭔가 폭발한 걸까요?",
  ui_story_1012_10121401_100_dialog_content = "......",
  ui_story_1012_10121401_101_dialog_content = "온 계곡이 흔들리고 있습니다...",
  ui_story_1012_10121401_102_dialog_content = "대체 이게 무슨...",
  ui_story_1012_10121401_103_dialog_content = "무기다. 게다가 너도 일찍이 본 적이 있겠지.",
  ui_story_1012_10121401_104_dialog_content = "제가요?!",
  ui_story_1012_10121401_105_dialog_content = "설마...",
  ui_story_1012_10121401_106_dialog_content = "마침내 일루미나 대원수의 결사 항전을 내 눈으로 보게 되는구나.",
  ui_story_1012_10121401_107_dialog_content = "흥분해야 하는 것인지, 두려워해야 하는 것인지 모르겠군.",
  ui_story_1012_10121401_108_dialog_content = "어이, 적은 다 어디로 간 거지?",
  ui_story_1012_10121401_109_dialog_content = "이상하네. 전장이 텅 비어버렸잖아.",
  ui_story_1012_10121401_110_dialog_content = "설마 너희들처럼 뒤틀린 생물에게도...",
  ui_story_1012_10121401_111_dialog_content = "죽음이 두려운 일인 거냐?",
  ui_story_1012_10121401_112_dialog_content = "......",
  ui_story_1012_10121401_113_dialog_content = "라인하르트, 그런 식으로 힘을 쓰면 네가 다칠 거야.",
  ui_story_1012_10121401_114_dialog_content = "하하하하하. 무슨 소리를 하는 거냐. 여긴 전장이다.",
  ui_story_1012_10121401_115_dialog_content = "애초부터 몸 성히 돌아갈 생각은 하지도 않았어.",
  ui_story_1012_10121401_116_dialog_content = "네게 보다 현명한 선택은 그 힘을 아껴 뒀다가 다른 사람들과 포위를 돌파하는 거야.",
  ui_story_1012_10121401_117_dialog_content = "아직도 뭔가 잘못 알고 있구나.",
  ui_story_1012_10121401_118_dialog_content = "이 전쟁은 이길 때까지 버텨야 하는 전쟁이다.",
  ui_story_1012_10121401_119_dialog_content = "처음부터 끝까지, 우리에게 포위 돌파라는 선택지는 없었다고.",
  ui_story_1012_10121401_120_dialog_content = "......",
  ui_story_1012_10121401_121_dialog_content = "역시 우린 서로를 이해할 수 없는 모양이야.",
  ui_story_1012_10121401_122_dialog_content = "하하하, 언제나 그래왔지.",
  ui_story_1012_10121401_123_dialog_content = "넌 자신을 불사르는 선택을 내렸어.",
  ui_story_1012_10121401_124_dialog_content = "그럼 잿더미가 되는 모습을 내가 지켜봐 줄게.",
  ui_story_1012_10121401_125_dialog_content = "그래, 그런 기세로 와야지.",
  ui_story_1012_10121401_126_dialog_content = "이게 마지막 전투가 되겠군.",
  ui_story_1012_10121401_127_dialog_content = "......",
  ui_story_1012_10121401_128_dialog_content = "『모든 암귀는 귀환의 탑으로 진격해라.』",
  ui_story_1012_10121401_129_dialog_content = "후우... 후우...",
  ui_story_1012_10121401_130_dialog_content = "그어어어──!",
  ui_story_1012_10121401_131_dialog_content = "아직도... 너무 많아...",
  ui_story_1012_10121401_132_dialog_content = "PlayerName한테... 가까이 가지 마!",
  ui_story_1012_10121401_133_dialog_content = "크윽...!",
  ui_story_1012_10121401_134_dialog_content = "다행이야. 다친 건 왼쪽 팔이니까... 아직 창은 쓸 수 있어...",
  ui_story_1012_10121401_135_dialog_content = "PlayerName, 암귀는 얼마나 더 남았지? 어느 방향에...",
  ui_story_1012_10121401_136_dialog_content = "아, 그렇구나. 지금은 못 듣겠지...",
  ui_story_1012_10121401_137_dialog_content = "네 쪽은 잘되고 있을지 모르겠네.",
  ui_story_1012_10121401_138_dialog_content = "내가 시간은 벌어 주겠지만... 오래는 못 버틸지도 모르겠어.",
  ui_story_1012_10121401_139_dialog_content = "으아아아아악!",
  ui_story_1012_10121401_140_dialog_content = "<color=#e8d9bb>퍽!</color>",
  ui_story_1012_10121401_141_dialog_content = "(아, 아프잖아!)",
  ui_story_1012_10121401_142_dialog_content = "(이렇게 주먹질을 한다고... 효과가 있을까?)",
  ui_story_1012_10121401_143_dialog_content = "......",
  ui_story_1012_10121401_144_dialog_content = "(이런! 오른쪽이었나...)",
  ui_story_1012_10121401_145_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_1012_10121401_146_dialog_content = "크윽...",
  ui_story_1012_10121401_147_dialog_content = "(안 돼, 아직이야... 녀석이 또 오고 있어...)",
  ui_story_1012_10121401_148_dialog_content = "......",
  ui_story_1012_10121401_149_dialog_content = "(아까 봤던 공격들이야. 빠르게 한 곳을 공격하는 방식...)",
  ui_story_1012_10121401_150_dialog_content = "(집중해야 돼. 집중하자...)",
  ui_story_1012_10121401_151_dialog_content = "<color=#e8d9bb>휙! 휘익! 휘이익! 휘익!</color>",
  ui_story_1012_10121401_152_dialog_content = "(휴... 피했어...)",
  ui_story_1012_10121401_153_dialog_content = "(근데 피하는 데 힘을 다 써 버려서 공격을 할 힘이 없어...)",
  ui_story_1012_10121401_154_dialog_content = "(기껏해야 피하는 게 한계라면 할 수 있는 건 시간 끄는 것뿐이야...)",
  ui_story_1012_10121401_155_dialog_content = "(그럴 시간이 없다고...)",
  ui_story_1012_10121401_156_dialog_content = "(탑 밖은 위급한 상황이고, 카렌이 암귀를 언제까지 막아줄 수 있을지도 미지수야.)",
  ui_story_1012_10121401_157_dialog_content = "(최대한 빨리 「율법의 현」을 가동해야 돼.)",
  ui_story_1012_10121401_158_dialog_content = "(하지만... 어떻게 해야...)",
  ui_story_1012_10121401_159_dialog_content = "<color=#e8d9bb>휙! 휘익! 휘이익! 휘익!</color>",
  ui_story_1012_10121401_160_dialog_content = "(또 온다!)",
  ui_story_1012_10121401_161_dialog_content = "(으으... 두 다리가 후들거려서 서는 것도 힘들잖아...)",
  ui_story_1012_10121401_162_dialog_content = "(저 가디언 둘이 지키고 있는 한, 아무것도 할 수가 없어.)",
  ui_story_1012_10121401_163_dialog_content = "(그래, 반드시 녀석들을 쓰러트려야 해.)",
  ui_story_1012_10121401_164_dialog_content = "(다시 한번 해 보자...)",
  ui_story_1012_10121401_165_dialog_content = "이야아아아압!",
  ui_story_1012_10121401_166_dialog_content = "<color=#e8d9bb>퍽!</color>",
  ui_story_1012_10121401_167_dialog_content = "(...역시 아프잖아!)",
  ui_story_1012_10121401_168_dialog_content = "(근데... 잠깐만, 여긴 의식으로 이루어진 공간 아니었어?!)",
  ui_story_1012_10121401_169_dialog_content = "(그럼 아무리 아파도 실제로 다치진 않을 거잖아!)",
  ui_story_1012_10121401_170_dialog_content = "(정신으로 받는 고통은... 참으면 그만이야!)",
  ui_story_1012_10121401_171_dialog_content = "(그래, 조금만 참으면 돼.)",
  ui_story_1012_10121401_172_dialog_content = "(주먹 한 대로 안 되면, 백 번, 만 번...)",
  ui_story_1012_10121401_173_dialog_content = "(이 녀석들이 쓰러질 때까지 때리면 되는 거라고!)",
  ui_story_1012_10121401_174_option_content = "[주먹을 날린다]",
  ui_story_1012_10121401_175_dialog_content = "<color=#e8d9bb>퍽!</color>",
  ui_story_1012_10121401_176_dialog_content = "으윽...",
  ui_story_1012_10121401_177_option_content = "[주먹을 날린다]",
  ui_story_1012_10121401_178_dialog_content = "<color=#e8d9bb>퍽!</color>",
  ui_story_1012_10121401_179_dialog_content = "(참아... 참아내...)",
  ui_story_1012_10121401_180_option_content = "[주먹을 날린다]",
  ui_story_1012_10121401_181_dialog_content = "<color=#e8d9bb>퍽!</color>",
  ui_story_1012_10121401_182_dialog_content = "(이런... 손가락에 감각이 없어져서... 주먹을 못 쥐겠어.)",
  ui_story_1012_10121401_183_dialog_content = "(의식 속 공간을 뭐 하러 이렇게 사실적으로 만든 건데?!)",
  ui_story_1012_10121401_184_dialog_content = "(괜찮아, 아직 반대편 손이 남았어...)",
  ui_story_1012_10121401_185_option_content = "[주먹을 날린다]",
  ui_story_1012_10121401_186_dialog_content = "<color=#e8d9bb>퍽!</color>",
  ui_story_1012_10121401_187_dialog_content = "(이 자식들... 대체 얼마나 단단한 거야!)",
  ui_story_1012_10121401_188_option_content = "[주먹을 날린다]",
  ui_story_1012_10121401_189_dialog_content = "<color=#e8d9bb>퍽!</color>",
  ui_story_1012_10121401_190_dialog_content = "(어때? 이제 좀 효과가...)",
  ui_story_1012_10121401_191_dialog_content = "!!!",
  ui_story_1012_10121401_192_dialog_content = "(잠깐만... 다른 녀석도 있었지...)",
  ui_story_1012_10121401_193_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_1012_10121401_194_dialog_content = "으...윽...",
  ui_story_1012_10121401_195_dialog_content = "힘이 없어... 몸이... 안 움직여...",
  ui_story_1012_10121401_196_dialog_content = "역시 나 하나만으로는... 뭘 어떻게 해도 녀석들을 이길 수 없는 건가...",
  ui_story_1012_10121401_197_dialog_content = "(나는 그 순간 귀환의 탑이 말한 「명령」이라는 것을 이해했다.)",
  ui_story_1012_10121401_198_dialog_content = "(그것은 타인의 간섭을 허용하지 않는 고고한 것이었다.)",
  ui_story_1012_10121401_199_dialog_content = "(명령이 권위를 지키는 방식은 결코 말뿐인 경고가 아니었다.)",
  ui_story_1012_10121401_200_dialog_content = "(그것은 아이테르가 선천적으로 가지고 있는 가장 약한 부분을 노렸다.)",
  ui_story_1012_10121401_201_dialog_content = "(모든 의지와 지혜는 운명 앞에 속수무책이다.)",
  ui_story_1012_10121401_202_dialog_content = "(그것은 반박할 수 없는 힘, 그 하나만으로 「명령」이라는 한계점을 설정한다.)",
  ui_story_1012_10121401_203_dialog_content = "(그것은 아이테르가 태어나서부터 반항할 수 없는 것이다.)",
  ui_story_1012_10121401_204_dialog_content = "(아이테르라는 종족 전체에 씌워진, 「선천성」이라는 사슬인 것이다.)",
  ui_story_1012_10121401_205_dialog_content = "......",
  ui_story_1012_10121401_206_dialog_content = "다들... 미안해... 난...",
  ui_story_1012_10121401_207_dialog_content = "누가 그렇게 맥 빠지는 소리를 하고 있는 거야?!",
  ui_story_1012_10121401_208_dialog_content = "!!!",
  ui_story_1012_10121401_209_dialog_content = "바이스?!",
  ui_story_1012_10121401_210_dialog_content = "정말 짜증 나는 방식으로 공격하는 녀석이네!",
  ui_story_1012_10121401_211_dialog_content = "넌 저기 어디 좀 숨어 있어. 나 아직 새로운 무기에 적응을 못 했거든.\n널 잘 지켜주지 못할 수도 있어.",
  ui_story_1012_10121401_212_dialog_content = "진짜 바이스구나!",
  ui_story_1012_10121401_213_dialog_content = "깨, 깨어난 거야? 여긴 어떻게 온 거야?",
  ui_story_1012_10121401_214_dialog_content = "아이참, 한 번에 그렇게 많이 물어보면 뭐부터 대답해야 할지 모르겠잖아.",
  ui_story_1012_10121401_215_dialog_content = "일단 간단한 문제부터 정리해 보자. 저 녀석들을 쓰러트려야 하는 거 맞지?",
  ui_story_1012_10121401_216_dialog_content = "맞아!",
  ui_story_1012_10121401_217_dialog_content = "그럼 더 기다릴 필요도 없겠네!",
  ui_story_1012_10121401_218_dialog_content = "PlayerName, 전투 지휘를 부탁해!",
  ui_story_1012_10121402_1_dialog_content = "성가신 녀석들, 이제 끝이야!",
  ui_story_1012_10121402_2_dialog_content = "일단 너, 커다란 녀석!",
  ui_story_1012_10121402_3_dialog_content = "지직...",
  ui_story_1012_10121402_4_dialog_content = "숨을 수 있었어야지.",
  ui_story_1012_10121402_5_dialog_content = "내 화살은 막는다고 막히는 게 아니거든!",
  ui_story_1012_10121402_6_dialog_content = "바이스, 조심해...",
  ui_story_1012_10121402_7_dialog_content = "알아, 오른쪽을 조심하라는 거잖아!",
  ui_story_1012_10121402_8_dialog_content = "<color=#e8d9bb>휙! 휘익! 휘이익! 휘익!</color>",
  ui_story_1012_10121402_9_dialog_content = "뭐? 어떻게 알았어?!",
  ui_story_1012_10121402_10_dialog_content = "이제 하나만 남았으니까, 훨씬 쉽겠네.",
  ui_story_1012_10121402_11_dialog_content = "넌 화살을 몇 발이나 버틸 수 있을까? 받아라!",
  ui_story_1012_10121402_12_dialog_content = "지직...",
  ui_story_1012_10121402_13_dialog_content = "우와! 성공했어! 가디언을 둘 다 쓰러트렸어!",
  ui_story_1012_10121402_14_dialog_content = "정말 대단해! 바이스!",
  ui_story_1012_10121402_15_dialog_content = "후우... 역시 좀 힘드네.",
  ui_story_1012_10121402_16_dialog_content = "만약 내 몸의 변화가 없었다면 녀석들의 상대가 못 됐을 거야.",
  ui_story_1012_10121402_17_dialog_content = "참, 여긴 어떻게 나타난 거야?\n여긴 아이테르만 들어올 수 있는 의식 공간일 텐데?",
  ui_story_1012_10121402_18_dialog_content = "설마... 넌 진짜 바이스가 아니라 내가 상상으로 만들어 낸...",
  ui_story_1012_10121402_19_dialog_content = "당연히 진짜 바이스거든!",
  ui_story_1012_10121402_20_dialog_content = "설마 상상으로 「바이스」를 만들어서 널 구할 초능력이라도 있다는 거야?",
  ui_story_1012_10121402_21_dialog_content = "아, 하긴 그렇네, 그래서 어떻게 나타난 거냐니까? 아무리 생각해도 모르겠잖아.",
  ui_story_1012_10121402_22_dialog_content = "간단히 말하자면...",
  ui_story_1012_10121402_23_dialog_content = "혼수상태에서 깨어났을 때, 너한테 도움이 필요하단 걸 가장 먼저 느꼈어.",
  ui_story_1012_10121402_24_dialog_content = "뭐?",
  ui_story_1012_10121402_25_dialog_content = "나도 이유는 모르겠지만, 마치 너랑 내 의식이랑 연결된 것 같았어.",
  ui_story_1012_10121402_26_dialog_content = "네가 불안해하고 초조해하는 게 느껴졌고, 네가 어디에 있는지도 느껴졌거든.",
  ui_story_1012_10121402_27_dialog_content = "네가 누워 있던 곳에 뛰어가서, 네 몸에 손을 대니까\n뭔가 의식이 끌어당겨지는 것처럼 여기로 들어오게 된 거야.",
  ui_story_1012_10121402_28_dialog_content = "그 뒤의 일은 너도 봐서 알 거고.",
  ui_story_1012_10121402_29_dialog_content = "의식이 연결되어 있다고?",
  ui_story_1012_10121402_30_dialog_content = "나도 어떻게 그게 가능한 건지는 모르겠어.",
  ui_story_1012_10121402_31_dialog_content = "아무튼 자세한 건 나중에 이야기하자!",
  ui_story_1012_10121402_32_dialog_content = "이 탑의 최종병기를 가동하려는 거지? 카렌이 이야기해 줬어.",
  ui_story_1012_10121402_33_dialog_content = "얼른 가자!",
  ui_story_1012_10121402_34_dialog_content = "응, 그래!",
  ui_story_1012_10121402_35_dialog_content = "「오리진 서클 권한」을 탈취해야 돼. 이 공간의 어디쯤 있는 걸까?",
  ui_story_1012_10121402_36_option_content = "(강제 감응!)",
  ui_story_1012_10121402_37_dialog_content = "<color=#e8d9bb>위이잉──!</color>",
  ui_story_1012_10121402_38_dialog_content = "어라? 이건...",
  ui_story_1012_10121402_39_dialog_content = "(이 공간 전체와 내 의식이 연결되어 있다.)",
  ui_story_1012_10121402_40_dialog_content = "(우리는 마치 서로의 존재가 된 것만 같다.)",
  ui_story_1012_10121402_41_dialog_content = "(처음 겪어보는 편안함이 느껴진다. 마치...)",
  ui_story_1012_10121402_42_dialog_content = "(끝없는 하늘을 여행하는 것처럼.)",
  ui_story_1012_10121402_43_dialog_content = "(그 무엇에도 방해받지 않고, 모든 게 내 아래에 펼쳐져 있는 느낌이다.)",
  ui_story_1012_10121402_44_dialog_content = "왜 그래? 뭔가 찾았어?",
  ui_story_1012_10121402_45_dialog_content = "아니, 여긴 우리 둘이랑 가디언의 잔해 말고는 아무것도 없는 것 같아.",
  ui_story_1012_10121402_46_dialog_content = "근데 내가 여기서 뭘 찾아야 하는 건지도 잘 모르겠어.",
  ui_story_1012_10121402_47_dialog_content = "휴, 에이드 브레인이 있었으면 좋았을 텐데...",
  ui_story_1012_10121402_48_dialog_content = "에이드 브레인이 해야 할 일이 있습니까?",
  ui_story_1012_10121402_49_dialog_content = "...으엑?!",
  ui_story_1012_10121402_50_dialog_content = "지, 진짜로 나타났잖아?!",
  ui_story_1012_10121402_51_dialog_content = "방금 전까지는 계속 불렀는데 아무런 반응도 없었으면서!",
  ui_story_1012_10121402_52_dialog_content = "그것은 에이드 브레인이 「오리진 서클」에 접근할 수 없기 때문입니다.",
  ui_story_1012_10121402_53_dialog_content = "그럼 지금은 어떻게 나타날 수 있었던 건데?",
  ui_story_1012_10121402_54_dialog_content = "「명령」의 요청이 있었습니다.",
  ui_story_1012_10121402_55_dialog_content = "「명령」은 에이드 브레인이 이곳에 나타나길 바란다는 기대를 드러냈고,\n에이드 브레인은 그 명령에 복종했습니다.",
  ui_story_1012_10121402_56_dialog_content = "「명령」이라고?",
  ui_story_1012_10121402_57_dialog_content = "네가 이곳에 나타나길 바랐던 건 나잖아?",
  ui_story_1012_10121402_58_dialog_content = "그렇습니다.",
  ui_story_1012_10121402_59_dialog_content = "지금은 당신이 바로 「명령」입니다.",
  ui_story_1012_10121402_60_dialog_content = "뭐라고?!",
  ui_story_1012_10121402_61_dialog_content = "당신의 의식은 이미 「오리진 서클」과 융합했습니다.",
  ui_story_1012_10121402_62_dialog_content = "「오리진 서클」은 「명령」의 매개체입니다.\n따라서 당신은 「명령」이 되었습니다.",
  ui_story_1012_10121402_63_dialog_content = "당신의 요구에는 반드시 복종해야 하며, 당신의 바람은 반드시 실현되어야 합니다.",
  ui_story_1012_10121402_64_dialog_content = "에이드 브레인이 해야 할 일이 있습니까?",
  ui_story_1012_10121402_65_dialog_content = "내가... 계속 날 가로막던 그 「명령」이 됐다고?",
  ui_story_1012_10121402_66_dialog_content = "그럼 난 「율법의 현」을 가동하고 싶어.",
  ui_story_1012_10121402_67_dialog_content = "명령을 접수했습니다. 「율법의 현」 프로세스를 가동합니다.",
  ui_story_1012_10121402_68_dialog_content = "가동 매개 변수와 실행하려는 「율법」을 입력하십시오.",
  ui_story_1012_10121402_69_dialog_content = "하아? 그건 또 뭔데?",
  ui_story_1012_10121402_70_dialog_content = "「율법의 현」은 매우 정밀한 병기입니다.",
  ui_story_1012_10121402_71_dialog_content = "「율법의 현」의 가동에는 정확한 타격 범위, 타격 목표, 타격 시간 등이 필요합니다.",
  ui_story_1012_10121402_72_dialog_content = "이는 기대에 부합하는 효과를 보장하기 위해 반드시 필요한 과정입니다.",
  ui_story_1012_10121402_73_dialog_content = "근데 내가 뭘 입력해야 되는지 어떻게 아냐고!",
  ui_story_1012_10121402_74_dialog_content = "이 수학들은 내가 아는 거랑 전혀 다르잖아!",
  ui_story_1012_10121402_75_dialog_content = "이는 반드시 필요한 과정입니다.\n가동 매개 변수와 실행하려는 「율법」을 입력하십시오.",
  ui_story_1012_10121402_76_dialog_content = "그, 그럼 귀환의 탑 주변의 모든 암귀를 공격해. 할 수 있어?",
  ui_story_1012_10121402_77_dialog_content = "죄송합니다. 해당 요구는 너무 모호합니다.\n「율법의 현」은 매우 정밀한 병기입니다.",
  ui_story_1012_10121402_78_dialog_content = "그럼 대체 나보고 어쩌라는 거야?!",
  ui_story_1012_10121402_79_dialog_content = "여기까지 왔는데 이런 이유로 가동을 못 한다는 게 말이 돼?",
  ui_story_1012_10121402_80_dialog_content = "「율법의 현」의 매개 변수 프리셋을 검색했습니다.\n이를 호출해 즉시 초기화를 완료할 수 있습니다.",
  ui_story_1012_10121402_81_dialog_content = "해당 조작을 진행하시겠습니까?",
  ui_story_1012_10121402_82_dialog_content = "매개 변수 프리셋?",
  ui_story_1012_10121402_83_dialog_content = "보고드립니다. 귀환의 탑에 미등록 암귀가 침입했습니다.",
  ui_story_1012_10121402_84_dialog_content = "수가 매우 많아 정확한 통계가 불가능합니다.",
  ui_story_1012_10121402_85_dialog_content = "큰일이야... 이제 바깥도 더는 버틸 수 없는 것 같아.",
  ui_story_1012_10121402_86_dialog_content = "시간이 없어. 더는 시간을 낭비할 수 없다고.",
  ui_story_1012_10121402_87_dialog_content = "에이드 브레인! 그 매개 변수 프리셋은 누가 남긴 건지 확인할 수 있어?",
  ui_story_1012_10121402_88_dialog_content = "가능합니다.",
  ui_story_1012_10121402_89_dialog_content = "조작자의 등록 명칭은 「프란츠」입니다.",
  ui_story_1012_10121402_90_dialog_content = "역시 그 사람이야.",
  ui_story_1012_10121402_91_dialog_content = "보고드립니다. 귀환의 탑에 미등록 암귀가 침입했습니다.",
  ui_story_1012_10121402_92_dialog_content = "수가 매우 많아 정확한 통계가...",
  ui_story_1012_10121402_93_dialog_content = "그때 공격한 대상은 누구였어?!",
  ui_story_1012_10121402_94_dialog_content = "마지막 질문만 확인해 주면 돼.\n「율법의 현」이 마지막으로 공격했던 대상이 누구인지 알려줘!",
  ui_story_1012_10121402_95_dialog_content = "데이터 기록 검색 중...",
  ui_story_1012_10121402_96_dialog_content = "지난 설정의 타격 대상은 암귀입니다.",
  ui_story_1012_10121402_97_dialog_content = "알겠어.",
  ui_story_1012_10121402_98_dialog_content = "(프란츠 선생님, 당신을 믿어도 되겠지?)",
  ui_story_1012_10121402_99_dialog_content = "에이드 브레인, 그 매개 변수 프리셋에 맞춰서 「율법의 현」을 가동해!",
  ui_story_1012_10121402_100_dialog_content = "명령을 접수했습니다.",
  ui_story_1012_10121402_101_dialog_content = "가동 매개 변수를 초기화합니다. 이전 데이터를 호출합니다.",
  ui_story_1012_10121402_102_dialog_content = "타격 대상을 암귀로 설정합니다.",
  ui_story_1012_10121402_103_dialog_content = "모든 암귀의 권한을 「추방」으로 조정합니다.",
  ui_story_1012_10121402_104_dialog_content = "설정에 따라 「율법」, <color=#FFB400>「귀환의 탑에 접근하는 것을 영원히 불허한다」</color>를 실행합니다.",
  ui_story_1012_10121402_105_dialog_content = "초기화 단계가 완료되었습니다.",
  ui_story_1012_10121402_106_dialog_content = "「율법의 현」을 가동합니다.",
  ui_story_1012_10121402_107_dialog_content = "...뭐지?!",
  ui_story_1012_10121402_108_dialog_content = "탑 전체가 빛나고 있어!",
  ui_story_1012_10121402_109_dialog_content = "하늘이 밝았다. 우리가 기다리던 때가 이르렀다.",
  ui_story_1012_10121402_110_dialog_content = "하하하하! 내가 말했잖아! 그 녀석이 해낼 거라고!",
  ui_story_1012_10121402_111_dialog_content = "자, 다들 움직여. 좋은 자리를 찾아봐.",
  ui_story_1012_10121402_112_dialog_content = "멋진 광경을 함께 감상해 보자고.",
  ui_story_1012_10121402_113_dialog_content = "노라, 이게 어떻게 된 거냐?",
  ui_story_1012_10121402_114_dialog_content = "이 탑이 뭘 하려는 것이냐?",
  ui_story_1012_10121402_115_dialog_content = "설마...",
  ui_story_1012_10121402_116_dialog_content = "이런...",
  ui_story_1012_10121402_117_dialog_content = "......",
  ui_story_1012_10121402_118_dialog_content = "크에엑...",
  ui_story_1012_10121402_119_dialog_content = "암귀들이 왜 다 멈춰 버린 거지?!",
  ui_story_1012_10121402_120_dialog_content = "후퇴하지 마라! 어서 진격해!",
  ui_story_1012_10121402_121_dialog_content = "놈들은 이제 한계란 말이다!",
  ui_story_1012_10121402_122_dialog_content = "크에엑...",
  ui_story_1012_10121402_123_dialog_content = "제기랄!",
  ui_story_1012_10121402_124_dialog_content = "피제로 님, 이 녀석들...",
  ui_story_1012_10121402_125_dialog_content = "으윽... 큭...",
  ui_story_1012_10121402_126_dialog_content = "피, 피제로 님?",
  ui_story_1012_10121402_127_dialog_content = "어째서... 이런 일이...",
  ui_story_1012_10121402_128_dialog_content = "피제로 님, 저희 더는 안 싸우는 겁니까?",
  ui_story_1012_10121402_129_dialog_content = "......",
  ui_story_1012_10121402_130_dialog_content = "퇴각, 전군 퇴각이다.",
  ui_story_1012_10121402_131_dialog_content = "하지만 대체 왜...",
  ui_story_1012_10121402_132_dialog_content = "말하지 않았나! 퇴각하라고! 알아들었느냐!",
  ui_story_1012_10121402_133_dialog_content = "아, 알겠습니다...",
  ui_story_1012_10121402_134_dialog_content = "퇴각해라... 퇴각할 수밖에 없어...",
  ui_story_1012_10121402_135_dialog_content = "마음에서 공격하겠다는 생각 그 자체가... 다시는 생겨나질 않는다...",
  ui_story_1012_10121402_136_dialog_content = "내 의식이 내게 퇴각을 강요하고 있다...",
  ui_story_1012_10121402_137_dialog_content = "아무리 애를 써도... 나 자신을... 거역할 수가 없단 말이다...",
  ui_story_1012_10121402_138_dialog_content = "녀석들이 물러나고 있어요! 모든 암귀가 퇴각하고 있어요!",
  ui_story_1012_10121402_139_dialog_content = "이상하군요. 전혀 상식적이지 않은 일 아닙니까.\n어째서 승리를 눈앞에 두고 포기해 버린 걸까요?",
  ui_story_1012_10121402_140_dialog_content = "방금 하얀 탑에서 뿜어져 나온 빛 때문입니까?",
  ui_story_1012_10121402_141_dialog_content = "그건 이따가 PlayerName한테 물어봐라. 분명히 알고 있을 테니까.",
  ui_story_1012_10121402_142_dialog_content = "하아── 이번 전투는 힘들었어. 풀밭에 누워서 쉬고 싶잖아.",
  ui_story_1012_10121402_143_dialog_content = "적의 재공습에 대비하지 않아도 되겠습니까?",
  ui_story_1012_10121402_144_dialog_content = "놈들은 지금 잔여 병력만으로도 저흴 헤븐즈 밸리에 가둬둘 수 있습니다.\n여전히 위험한 상황입니다.",
  ui_story_1012_10121402_145_dialog_content = "걱정 마라. 놈들의 기회는 각 세력의 대군단이 도착하기 전에\n귀환의 탑을 점령하는 것이었으니 말이야.",
  ui_story_1012_10121402_146_dialog_content = "그 기회가 사라졌으니, 이곳에 남아 봐야 화살받이밖에 더 되겠어?\n놈들도 그런 멍청한 짓은 하지 않아.",
  ui_story_1012_10121402_147_dialog_content = "역시 대원수님이십니다. 가르침을 받았습니다.",
  ui_story_1012_10121402_148_dialog_content = "이 기회에 푹 쉬어 두라고.",
  ui_story_1012_10121402_149_dialog_content = "내 예상이 맞다면, 조금 뒤엔 전투보다 더 진 빠지는 일이 있을 테니까.",
  ui_story_1012_10121402_150_dialog_content = "우, 우리가 해냈어!",
  ui_story_1012_10121402_151_dialog_content = "해냈다고? 밖에 무슨 일이 벌어진 건데?",
  ui_story_1012_10121402_152_dialog_content = "암귀가 전부 퇴각했어!",
  ui_story_1012_10121402_153_dialog_content = "아무래도 놈들이 아까 「율법의 현」으로 설정한 「율법」에 복종한 것 같아.",
  ui_story_1012_10121402_154_dialog_content = "「귀환의 탑에 접근하는 것을 영원히 불허한다」는 그거 말이야.",
  ui_story_1012_10121402_155_dialog_content = "암귀를 복종시킬 수 있단 말이야?!",
  ui_story_1012_10121402_156_dialog_content = "그거 정말 말도 안 되잖아!",
  ui_story_1012_10121402_157_dialog_content = "「율법의 현」이 작동하는 게 느껴져.\n이건 정말 아이테르의 스타일에 딱 맞는 병기였어.",
  ui_story_1012_10121402_158_dialog_content = "힘으로 싸우는 게 아니라, 모든 적의 머릿속에 견고한 의식을 심는 거야.",
  ui_story_1012_10121402_159_dialog_content = "폭력의 단계를 뛰어넘어 가장 근본적인 생각으로 전쟁을 끝냈어.",
  ui_story_1012_10121402_160_dialog_content = "이런 힘... 너무 강해서 무서워질 정도야.",
  ui_story_1012_10121402_161_dialog_content = "어라? 이건 또 왜 이래?",
  ui_story_1012_10121402_162_dialog_content = "의식 공간이 불안정해진 것 같아.",
  ui_story_1012_10121402_163_dialog_content = "보고드립니다. 귀환의 탑의 에너지가 곧 소진됩니다.",
  ui_story_1012_10121402_164_dialog_content = "다수의 일회성 부품이 「율법의 현」 가동 후 파괴되었습니다. 교체가 시급합니다.",
  ui_story_1012_10121402_165_dialog_content = "탑 내부의 엔지니어를 검색하는 중...",
  ui_story_1012_10121402_166_dialog_content = "대상을 찾지 못했습니다.",
  ui_story_1012_10121402_167_dialog_content = "에너지를 다 써버린 거였잖아.",
  ui_story_1012_10121402_168_dialog_content = "그래도 「율법의 현」이 가동될 때까지 버텨서 다행이라고 해야겠네.",
  ui_story_1012_10121402_169_dialog_content = "그 전에 꺼졌으면 지금 우리가 어떻게 됐을지 상상도 하고 싶지 않아...",
  ui_story_1012_10121402_170_dialog_content = "작동을 유지할 수 있는 에너지가 부족합니다.",
  ui_story_1012_10121402_171_dialog_content = "귀환의 탑이 곧 침묵에 빠집니다.",
  ui_story_1012_10121402_172_dialog_content = "침묵?",
  ui_story_1012_10121402_173_dialog_content = "모든 시설이 작동을 정지하고, 모든 기능을 사용할 수 없게 됩니다.",
  ui_story_1012_10121402_174_dialog_content = "당신이 오기 전보다 더욱 고요해질 것입니다.",
  ui_story_1012_10121402_175_dialog_content = "그렇구나.",
  ui_story_1012_10121402_176_dialog_content = "잠깐만, 그럼 에이드 브레인 너도...",
  ui_story_1012_10121402_177_dialog_content = "그렇습니다. 이제 에이드 브레인은 아이테르에게 도움을 드릴 수 없습니다.",
  ui_story_1012_10121402_178_dialog_content = "......",
  ui_story_1012_10121402_179_dialog_content = "이제 에이드 브레인에게 맡겨진 마지막 업무를 수행합니다.",
  ui_story_1012_10121402_180_dialog_content = "프란츠 선생님께서 메시지를 남기셨습니다.\n침묵에 빠지기 전 당신에게 재생해야 합니다.",
  ui_story_1012_10121402_181_dialog_content = "프란츠 선생님이?!",
  ui_story_1012_10121402_182_dialog_content = "「같은 아이테르 일족인 너에게──」",
  ui_story_1012_10121402_183_dialog_content = "「역시 메시지 재생 타이밍은 마지막으로 설정해 두자.」",
  ui_story_1012_10121402_184_dialog_content = "「난 슬픈 대화는 싫어한다. 내겐 승리의 축하가 더 어울리지.」",
  ui_story_1012_10121402_185_dialog_content = "「누군가 이 메시지를 재생할 걸 생각하는 것만으로도 무척이나 흥분이 된다.」",
  ui_story_1012_10121402_186_dialog_content = "「이게 얼마나 허망한 취미일까. 머나먼 훗날, 아직 존재하지도 않을\n다른 한 사람의 소원이 이루어지길 바라는 게 말이야.」",
  ui_story_1012_10121402_187_dialog_content = "「어쩌면 그건 우리가 같은 길을 가고 있고,\n때마침 여긴 사람이 찾지 않는 곳이기 때문이겠지.」",
  ui_story_1012_10121402_188_dialog_content = "우리가... 같은 길을 가고 있다고?",
  ui_story_1012_10121402_189_dialog_content = "「너는 네게 일어난 일들을 이해하지 못할지도 모른다.\n어쩌면 자신이 운이 좋다고 여길 수도 있겠지.」",
  ui_story_1012_10121402_190_dialog_content = "「하지만 이것만은 말해주고 싶다.\n모든 일에는 이유가 있다는 것을 믿어야 한다.」",
  ui_story_1012_10121402_191_dialog_content = "「에너지가 마침 이 순간에 소진되는 건\n애초에 율법의 현의 일격을 위해 남겨둔 것이기 때문이다.」",
  ui_story_1012_10121402_192_dialog_content = "「이건 내가 너에게 주는 선물이다.」",
  ui_story_1012_10121402_193_dialog_content = "선물?!",
  ui_story_1012_10121402_194_dialog_content = "「이 선물은 네가 암귀와 맞서는 데 도움이 될 것이다.」",
  ui_story_1012_10121402_195_dialog_content = "「그리고 네가 <color=#FFB400>선천성</color>이라는 족쇄를 부술 수 있게 도와줄 거다.」",
  ui_story_1012_10121402_196_dialog_content = "!!!",
  ui_story_1012_10121402_197_dialog_content = "「시간이 됐구나.」",
  ui_story_1012_10121402_198_dialog_content = "「마지막으로, 네가 이 길을 걸어줘서 고맙다.」",
  ui_story_1012_10121402_199_dialog_content = "「떠나갈 것은 끝내 떠나가고, 남아야 할 것은 영원히 남는다.」",
  ui_story_1012_10121402_200_dialog_content = "「잘 자라, 아이테르.」",
  ui_story_1012_10121501_1_dialog_content = "아, 다행이야...",
  ui_story_1012_10121501_2_dialog_content = "여전히 내가 아는 모습의 헤븐즈 밸리야.",
  ui_story_1012_10121501_3_dialog_content = "역시 여긴 평화로운 풍경이 제일 잘 어울려.",
  ui_story_1012_10121501_4_dialog_content = "카렌, 힘이 다 빠진 것 같네. 내가 부축해 줄게.",
  ui_story_1012_10121501_5_dialog_content = "괜찮아. 번거롭게 만들고 싶지 않아...",
  ui_story_1012_10121501_6_dialog_content = "그런 게 어딨어. 그리고 PlayerName한테 들었어.\n내가 혼수상태에 빠졌을 때 카렌 네가 계속 날 업고 다녔다고 말이야.",
  ui_story_1012_10121501_7_dialog_content = "그러니까 이번엔 내가 보답할 차례야!",
  ui_story_1012_10121501_8_dialog_content = "......",
  ui_story_1012_10121501_9_dialog_content = "알겠어.",
  ui_story_1012_10121501_10_dialog_content = "오, 우리의 대영웅들께서 드디어 나타나셨군!",
  ui_story_1012_10121501_11_dialog_content = "대, 대영웅이요?! 그런 말로 놀리지 마세요...",
  ui_story_1012_10121501_12_dialog_content = "하하하하하, 놀리는 게 아니라 진심이다. 너 혼자서 이 거대한 전쟁을 역전시켰잖아.",
  ui_story_1012_10121501_13_dialog_content = "일루미나의 대원수도, 북방의 여왕도 이길 수 없었던 전쟁이었는데 말이야.",
  ui_story_1012_10121501_14_dialog_content = "제 힘만으로 이루어 낸 역전은 아닌걸요.",
  ui_story_1012_10121501_15_dialog_content = "전 그저...",
  ui_story_1012_10121501_16_dialog_content = "「이건 내가 너에게 주는 선물이다.」",
  ui_story_1012_10121501_17_dialog_content = "음, 저는 그냥 거들었을 뿐이에요.",
  ui_story_1012_10121501_18_dialog_content = "거들었다? 이해가 안 되는군.\n겸손할 때도 그렇게 빙 둘러서 말해야 하는 건가?",
  ui_story_1012_10121501_19_dialog_content = "하하, 아무튼 다들 목숨 걸고 싸워 주셨잖아요.",
  ui_story_1012_10121501_20_dialog_content = "이건 저 혼자만이 아니라 우리 모두가 이루어 낸 결과예요.",
  ui_story_1012_10121501_21_dialog_content = "음, 그 말은 일리가 있군.",
  ui_story_1012_10121501_22_dialog_content = "승리는 모두의 것이지. 그게 바로 전사가 가져야 할 기백이다!",
  ui_story_1012_10121501_23_dialog_content = "하하하! 맞아요! 승리는 우리 모두의 것이에요!",
  ui_story_1012_10121501_24_dialog_content = "라인하르트 씨는 역시 말씀도 시원시원하게 하신다니까요!",
  ui_story_1012_10121501_25_dialog_content = "그런데 말이지. 그래도 이 사실은 잊지 마라.\n너는 우리 중에서도 유일무이한 존재다.",
  ui_story_1012_10121501_26_dialog_content = "너는 시작이자, 열쇠이고, 깃발이다.\n변화를 불러오는 중요한 일환이란 말이다.",
  ui_story_1012_10121501_27_dialog_content = "이건 단지 널 칭찬하려는 것만이 아니라 경고이기도 하다.",
  ui_story_1012_10121501_28_dialog_content = "네가 항상 가슴 속에 「유일무이」라는 사실에 경외를 품길 바란다.",
  ui_story_1012_10121501_29_dialog_content = "네, 꼭 기억할게요.",
  ui_story_1012_10121501_30_dialog_content = "돌아왔구나.",
  ui_story_1012_10121501_31_dialog_content = "여왕 폐하!",
  ui_story_1012_10121501_32_dialog_content = "폐하께선 전장에서나 지금이나 항상 침착하시네요.",
  ui_story_1012_10121501_33_dialog_content = "하긴, 폐하께서는 이번 일의 결말도 미리 보셨을 테니까요.",
  ui_story_1012_10121501_34_dialog_content = "......",
  ui_story_1012_10121501_35_dialog_content = "이번에는 보지 못하였다.",
  ui_story_1012_10121501_36_dialog_content = "네?!",
  ui_story_1012_10121501_37_dialog_content = "나는 그대가 역전에 성공하여 전황을 뒤바꾸는 미래를 보지 못하였다.",
  ui_story_1012_10121501_38_dialog_content = "그대가 어떤 일을 하러 가는 것만을 보았을 뿐.",
  ui_story_1012_10121501_39_dialog_content = "그렇다면 폐하께선...",
  ui_story_1012_10121501_40_dialog_content = "......",
  ui_story_1012_10121501_41_dialog_content = "나는 그대가 해내리라 믿었다.",
  ui_story_1012_10121501_42_dialog_content = "여왕 폐하...",
  ui_story_1012_10121501_43_dialog_content = "그, 그럼 제가 폐하를 실망시키진 않은 거죠?!",
  ui_story_1012_10121501_44_dialog_content = "이 헤븐즈 밸리가 바로 그대가 내게 준 답이다.",
  ui_story_1012_10121501_45_dialog_content = "참, PlayerName, 중요한 문제가 하나 남았다.",
  ui_story_1012_10121501_46_dialog_content = "대체 어떻게 그런 일이 가능했던 거지?",
  ui_story_1012_10121501_47_dialog_content = "암귀가 순식간에 귀환의 탑 공격을 포기하고, 풀이 죽어 도망치게 만들다니.",
  ui_story_1012_10121501_48_dialog_content = "네가 말했던 그 「최종병기」의 힘인가? 이런 병기는 본 적 없다고!",
  ui_story_1012_10121501_49_dialog_content = "사실 저도 잘은 몰라요.",
  ui_story_1012_10121501_50_dialog_content = "제 느낌으로는 의식을 다루는 병기인 것 같았어요.",
  ui_story_1012_10121501_51_dialog_content = "공격한 건 적의 육체가 아니라 의식이었어요.",
  ui_story_1012_10121501_52_dialog_content = "적의 의식에 「귀환의 탑에서 멀리 떨어져라」라는 명령을 주입해서\n저들이 자연스럽게 퇴각하게 만든 거예요.",
  ui_story_1012_10121501_53_dialog_content = "의식을 주입해? 세상에 그런 병기가 있단 말이냐?",
  ui_story_1012_10121501_54_dialog_content = "네, 저도 놀랐어요.",
  ui_story_1012_10121501_55_dialog_content = "그건 아주 중요한 일이다. 원리를 알 수 없는 강력한 위력의 병기...\n그게 이 세상에 어떤 의미인지 알고 있나?",
  ui_story_1012_10121501_56_dialog_content = "심지어 이클립스보다도 더 두려운 존재인 거다!",
  ui_story_1012_10121501_57_dialog_content = "아, 그 문제는 별로 걱정하지 않으셔도 될 것 같아요.",
  ui_story_1012_10121501_58_dialog_content = "완전히 못 쓰게 돼버렸거든요.",
  ui_story_1012_10121501_59_dialog_content = "못 쓰게 돼버렸다?",
  ui_story_1012_10121501_60_dialog_content = "맞아요. 여러 가지 이유 때문에 저 귀환의 탑에는 최종병기를\n딱 한 번 사용할 힘밖에 남아 있지 않았어요.",
  ui_story_1012_10121501_61_dialog_content = "그리고 지금 그 병기는 귀환의 탑 전체와 함께 침묵 상태에 빠졌죠.",
  ui_story_1012_10121501_62_dialog_content = "애초에 이 시대의 물건이 아니었어요.\n그저 한 소망을 위해 지금까지 애써 작동해 왔던 거였어요.",
  ui_story_1012_10121501_63_dialog_content = "그 소망은 최종병기가 가동되었을 때 이루어졌고,\n지금은 자기 본래의 모습으로 돌아갔어요.",
  ui_story_1012_10121501_64_dialog_content = "자신이 속하지 않는 시대에서 침묵을 지키는 역사의 기록자로 말이에요.",
  ui_story_1012_10121501_65_dialog_content = "그랬군.",
  ui_story_1012_10121501_66_dialog_content = "왠지 병기에서 다정함이 느껴지는 것 같단 말이지.",
  ui_story_1012_10121501_67_dialog_content = "음, 아마 단순한 병기는 아니어서 그럴 수도 있겠죠.",
  ui_story_1012_10121501_68_dialog_content = "그건 <color=#FFB400>선물</color>이었으니까요.",
  ui_story_1012_10121501_69_dialog_content = "<color=#e8d9bb>쿠웅... 쿠웅... 쿠우웅...</color>",
  ui_story_1012_10121501_70_dialog_content = "하아... 하아... 드디어 멈췄네...",
  ui_story_1012_10121501_71_dialog_content = "여긴... 헤븐즈 밸리 아냐?",
  ui_story_1012_10121501_72_dialog_content = "트래블러호 이 자식, 헤븐즈 밸리엔 뭐 하러 온 거야?",
  ui_story_1012_10121501_73_dialog_content = "잠깐만, 헤븐즈 밸리에 이렇게 높은 탑이 있었나?",
  ui_story_1012_10121501_74_dialog_content = "호오, 상황 파악을 못 하고 있는 녀석이 나타났군.",
  ui_story_1012_10121501_75_dialog_content = "레디젤 렌치는 항상 무슨 일이 생기면 첫 번째로 나타나던 녀석들인데, 의외잖아.",
  ui_story_1012_10121501_76_dialog_content = "일루미나 대원수?!",
  ui_story_1012_10121501_77_dialog_content = "그쪽이 헤븐즈 밸리에서 뭐 하고 있는데?",
  ui_story_1012_10121501_78_dialog_content = "믿는 건 네 자유다만, 이곳에서는 방금 전까지 전쟁이 벌어졌다.",
  ui_story_1012_10121501_79_dialog_content = "전쟁?!",
  ui_story_1012_10121501_80_dialog_content = "킁킁...",
  ui_story_1012_10121501_81_dialog_content = "음, 확실히 공기 중에 싸움의 냄새가 남아 있군.",
  ui_story_1012_10121501_82_dialog_content = "하지만... 전쟁이라니...",
  ui_story_1012_10121501_83_dialog_content = "하하, 못 믿겠나?",
  ui_story_1012_10121501_84_dialog_content = "너희 일루미나의 신용이 어떤지는 자기들이 잘 알고 있을 거 아냐?",
  ui_story_1012_10121501_85_dialog_content = "근데 확실히 평소와는 다르게 북적거리잖아.\n한 번 보기도 힘든 대단하신 분들을 전부 보게 될 줄이야.",
  ui_story_1012_10121501_86_dialog_content = "나와 북방의 여왕은 모두 이번 전쟁에 참여하기 위해 온 거다.",
  ui_story_1012_10121501_87_dialog_content = "이게 바로 PlayerName의 동원 능력 아니겠나, 하하하.",
  ui_story_1012_10121501_88_dialog_content = "너, 그리고 북방의 여왕, 그럼 다른 한 명은 누구지?",
  ui_story_1012_10121501_89_dialog_content = "다른 한 명?",
  ui_story_1012_10121501_90_dialog_content = "너희 뒤에 말이야.",
  ui_story_1012_10121501_91_dialog_content = "!!!",
  ui_story_1012_10121501_92_dialog_content = "......",
  ui_story_1012_10121501_93_dialog_content = "빅토리아? 네가 언제?",
  ui_story_1012_10121501_94_dialog_content = "난 신경 쓸 거 없어.",
  ui_story_1012_10121501_95_dialog_content = "그저 기적을 몸소 우러러보러 왔을 뿐이니까.",
  ui_story_1012_10121501_96_dialog_content = "너까지 오다니.",
  ui_story_1012_10121501_97_dialog_content = "<color=#e8d9bb>척, 척, 척, 척, 척, 척...</color>",
  ui_story_1012_10121501_98_dialog_content = "대열, 앞으로!",
  ui_story_1012_10121501_99_dialog_content = "주변을 봉쇄해라.",
  ui_story_1012_10121501_100_dialog_content = "예!",
  ui_story_1012_10121501_101_dialog_content = "이제야 왔나, 에센.",
  ui_story_1012_10121501_102_dialog_content = "지원군이라고 하기엔 행동이 너무 굼뜨잖아.",
  ui_story_1012_10121501_103_dialog_content = "죄송합니다, 대원수님. 저희는 지원 명령을 받은 것이 아닙니다.",
  ui_story_1012_10121501_104_dialog_content = "그럼 여긴 무슨 일이지?",
  ui_story_1012_10121501_105_dialog_content = "죄송합니다. 대원수님께서는 이번 임무에 대하여 아실 권한이 없습니다.",
  ui_story_1012_10121501_106_dialog_content = "알 권한이 없다?",
  ui_story_1012_10121501_107_dialog_content = "나는 일루미나의 대원수다.\n병사 하나하나의 행동까지 모두 내게 보고해야 마땅하다!",
  ui_story_1012_10121501_108_dialog_content = "대원수님께서는 군의 수장이실 뿐입니다.",
  ui_story_1012_10121501_109_dialog_content = "전쟁 이외의 일은 대원수님이라 해도 관여하실 수 없습니다.",
  ui_story_1012_10121501_110_dialog_content = "......",
  ui_story_1012_10121501_111_dialog_content = "또 위원회 짓인 거냐.",
  ui_story_1012_10121501_112_dialog_content = "저는 임무를 수행하러 가겠습니다.",
  ui_story_1012_10121501_113_dialog_content = "대원수님, 저들은...",
  ui_story_1012_10121501_114_dialog_content = "됐어.",
  ui_story_1012_10121501_115_dialog_content = "전장 밖에서는 정치꾼들이 대원수보다 더 힘 있는 자들이니까.",
  ui_story_1012_10121501_116_dialog_content = "...그 말씀도 가르침으로 삼아야 하는 겁니까?",
  ui_story_1012_10121501_117_dialog_content = "그럴 거 없어. 그저 푸념이라고 생각해라.",
  ui_story_1012_10121501_118_dialog_content = "저쪽을 봐라. 또 잔뜩 몰려왔군.",
  ui_story_1012_10121501_119_dialog_content = "저 하이에나들은 전쟁에는 관심이 없지만,\n오히려 주검 몇 구에는 목숨을 거는 녀석들이지.",
  ui_story_1012_10121501_120_dialog_content = "성주님, 일루미나 쪽에서 이미 움직이기 시작했습니다.",
  ui_story_1012_10121501_121_dialog_content = "저희도 뭔가 해야 하지 않겠습니까?",
  ui_story_1012_10121501_122_dialog_content = "경거망동하지 마라.",
  ui_story_1012_10121501_123_dialog_content = "이번 일은 중대한 사안이다.\n결론이 나기 전까지는 그 어떤 행동도 비난을 초래할 수 있다.",
  ui_story_1012_10121501_124_dialog_content = "백야성이 보일 자세는 모난 돌이 되는 것이 아니라 규율의 준수다.",
  ui_story_1012_10121501_125_dialog_content = "예!",
  ui_story_1012_10121501_126_dialog_content = "모양새를 보니 알겠어. 솔라드 성주께서 행차하셨군.",
  ui_story_1012_10121501_127_dialog_content = "그 많은 부대를 이끌고 어슬렁어슬렁 오다니, 역시 거드름 피우는 백야성다워!",
  ui_story_1012_10121501_128_dialog_content = "라인하르트, 우린 본래는 한길을 걷던 사이도 아니지 않은가.\n그렇게까지 말할 필요는 없을 터.",
  ui_story_1012_10121501_129_dialog_content = "말은 중요한 일에 아껴 두게.",
  ui_story_1012_10121501_130_dialog_content = "중요한 일? 이 화약과 연기 냄새가 안 맡아지는 모양이지?\n중요한 일은 이미 끝났다.",
  ui_story_1012_10121501_131_dialog_content = "봐라, 이제 상인까지 왔군.\n다들 이제부터 사업 논의라도 하실 모양인가? 하하하하!",
  ui_story_1012_10121501_132_dialog_content = "상인이 가진 것이 돈만 있는 건 아니지.",
  ui_story_1012_10121501_133_dialog_content = "그리고 나도 일개 상인이 아니다.",
  ui_story_1012_10121501_134_dialog_content = "영원히 백야성의 뒤꽁무니를 쫓는 그림자겠지, 안 그런가?",
  ui_story_1012_10121501_135_dialog_content = "그것은 우리들의 생존 전략이다.\n대원수께서는 더 좋은 가르침이라도 있나?",
  ui_story_1012_10121501_136_dialog_content = "그만들 하게. 우리가 이곳에 모인 것은 모두가 이곳에서 일어난 일을 느꼈기 때문이겠지.",
  ui_story_1012_10121501_137_dialog_content = "우리는 이 세계를 뒤흔든 것이 무엇인지,\n그것이 미래에 어떤 변수를 가져올지 알아야 하네.",
  ui_story_1012_10121501_138_dialog_content = "대원수, 먼저 온 그대에게 안내를 부탁할 수 있겠나.",
  ui_story_1012_10121501_139_dialog_content = "물론 기꺼이. 모두 따라와라.",
  ui_story_1012_10121501_140_dialog_content = "엄청난 사람들이 잔뜩 왔네! 대체 뭘 하려는 거지?",
  ui_story_1012_10121501_141_dialog_content = "귀환의 탑이 깨어났던 게 우리 생각보다 더 중대한 일이었던 것 같아.",
  ui_story_1012_10121501_142_dialog_content = "다들 이곳에서 무슨 일이 일어났던 건지 알아보려는 거겠지. 그리고...",
  ui_story_1012_10121501_143_dialog_content = "귀환의 탑을 어떻게 처리할지도 말이야.",
  ui_story_1012_10121501_144_dialog_content = "처리...",
  ui_story_1012_10121501_145_dialog_content = "미안해, 그렇게 말하면 너한테 조금 거북했겠구나.",
  ui_story_1012_10121501_146_dialog_content = "이 탑은 따지고 보면 네게 남겨진 거잖아.",
  ui_story_1012_10121501_147_dialog_content = "음, 괜찮아. 어떤 상황인지는 이해했거든.",
  ui_story_1012_10121501_148_dialog_content = "중대한 일 앞에선 나보다 모두를 우선으로 여기는 게 맞아.",
  ui_story_1012_10121501_149_dialog_content = "PlayerName...",
  ui_story_1012_10121501_150_dialog_content = "PlayerName! 왜 이런 데 숨어 있던 거야?",
  ui_story_1012_10121501_151_dialog_content = "아, 그게... 이쪽에...",
  ui_story_1012_10121501_152_dialog_content = "빨리 따라와. 대원수님이 찾으셔.",
  ui_story_1012_10121501_153_dialog_content = "어? 나를?",
  ui_story_1012_10121501_154_dialog_content = "응. 사람들이 전부 널 기다리고 있어. 얼른 가자!",
  ui_story_1012_10121501_155_dialog_content = "아, 알겠어...",
  ui_story_1012_10121501_156_dialog_content = "잠깐만!",
  ui_story_1012_10121501_157_dialog_content = "PlayerName, 또 해줄 말이 있어.",
  ui_story_1012_10121501_158_dialog_content = "이번에 고대 아이테르에 대해 알게 된 것들은 일단 다른 사람에겐 말하지 마.",
  ui_story_1012_10121501_159_dialog_content = "대원수님, 데리고 왔어요!",
  ui_story_1012_10121501_160_dialog_content = "좋군! 드디어 주인이 오셨군.",
  ui_story_1012_10121501_161_dialog_content = "주인?!",
  ui_story_1012_10121501_162_dialog_content = "너는 최후의 아이테르다. 당연히 이 귀환의 탑의 주인은 네가 되는 것이지.",
  ui_story_1012_10121501_163_dialog_content = "나와 북방의 여왕은 너 역시 이번 담화에 참여하는 것이 옳다고 생각한다.",
  ui_story_1012_10121501_164_dialog_content = "여, 여기 지도자분들이랑 같이요?",
  ui_story_1012_10121501_165_dialog_content = "그렇게 겁먹을 거 없다. 전에 백야성 축제도 참여해 봤었잖아.",
  ui_story_1012_10121501_166_dialog_content = "이 귀환의 탑에 대해 가장 큰 발언권을 가지고 있는 건 바로 너다.",
  ui_story_1012_10121501_167_dialog_content = "다른 이들의 입장은 고려할 필요 없이, 내가 말하고 싶은 것을 말하면 된다.",
  ui_story_1012_10121501_168_dialog_content = "아, 알겠어요.",
  ui_story_1012_10121501_169_dialog_content = "우리는 모두 빛을 볼 수 없는 녀석들이다.",
  ui_story_1012_10121501_170_dialog_content = "미래의 방향을 볼 수 있는 건 어쩌면 너뿐일지도 모르지.",
  ui_story_1012_10121501_171_dialog_content = "우선 확인해 두고 싶은 것이 있다. 그대들은 이 탑을 어떻게 보는가.",
  ui_story_1012_10121501_172_dialog_content = "백야성의 입장에서 이 탑은 의문의 여지 없이 거대한 위협이다.",
  ui_story_1012_10121501_173_dialog_content = "다모클레스가 돌연 스스로 가동했다. 이는 미증유의 일이다.",
  ui_story_1012_10121501_174_dialog_content = "게다가 이곳을 가리키고 있었다.\n또한 우리에게 이 탑을 반드시 파괴해야 한다고 이르더군.",
  ui_story_1012_10121501_175_dialog_content = "(다모클레스가 스스로 작동을... 그래, 세계가 눈에 들어올 때 봤었어.)",
  ui_story_1012_10121501_176_dialog_content = "일루미나에서 내린 결론도 같습니다.",
  ui_story_1012_10121501_177_dialog_content = "자난성의 일부 고대 유물에서 갑자기 경고음이 울려 퍼졌습니다.\n그 원인 또한 이곳에서 발생한 이변 때문이었습니다.",
  ui_story_1012_10121501_178_dialog_content = "이는 아주 오랜 먼 옛날, 자난성을 건설한 이와 귀환의 탑을 건설한 이가\n서로 적대 관계였다는 사실의 방증입니다.",
  ui_story_1012_10121501_179_dialog_content = "(이런, 엄청 강한 적의가 느껴지잖아.)",
  ui_story_1012_10121501_180_dialog_content = "그 관점에는 나도 동의한다.",
  ui_story_1012_10121501_181_dialog_content = "고대의 오로리안에게 귀환의 탑은 공포의 대상이었을 것이다.",
  ui_story_1012_10121501_182_dialog_content = "!!!",
  ui_story_1012_10121501_183_dialog_content = "모두가 동의한 이상, 내가 제안을 하도록 하지.\n저 귀환의 탑을 파괴하거나 묻어버리는 것이 어떠한가.",
  ui_story_1012_10121501_184_dialog_content = "존재하지 않아야 할 물건이라면, 존재하게 두어선 안 되는 법이다.",
  ui_story_1012_10121501_185_dialog_content = "뭔 소리야? 저렇게 거대한 탑을 부수겠다고?!",
  ui_story_1012_10121501_186_dialog_content = "저 안에 고대 유물이 얼마나 많이 남아 있겠어? 다 팔면 전부 돈이 되는 것들이라고!",
  ui_story_1012_10121501_187_dialog_content = "그리고 어떤 건 개조를 좀 하면 실생활에서 사용할 수 있을지도 모르지.",
  ui_story_1012_10121501_188_dialog_content = "너희 같은 높으신 나리들이 먹고사는 문제를 알기나 하겠냐!",
  ui_story_1012_10121501_189_dialog_content = "오늘 우리는 민생 문제를 논의하고자 이곳에 모인 것이 아니다.",
  ui_story_1012_10121501_190_dialog_content = "일루미나 역시 귀환의 탑을 파괴해선 안 된다고 생각합니다.",
  ui_story_1012_10121501_191_dialog_content = "추론이 아닌 분명한 사실은 저 탑이 군사 전략적 가치를 지닌 시설이라는 것입니다.",
  ui_story_1012_10121501_192_dialog_content = "연구의 가치가 충분합니다. 이를 파괴하는 것은 낭비일 뿐입니다.",
  ui_story_1012_10121501_193_dialog_content = "일루미나에게 연구를 맡긴다?\n그대들이 연구의 성과를 바른길에 사용하리라는 보장은 누가 하는가.",
  ui_story_1012_10121501_194_dialog_content = "그대들의 지난 과오들을 잊지 마라.",
  ui_story_1012_10121501_195_dialog_content = "어이, 다들 너무 긴장한 거 아냐?",
  ui_story_1012_10121501_196_dialog_content = "주변을 둘러봐라. 저건 그냥 돌로 쌓아 올린 높은 탑일 뿐이다.",
  ui_story_1012_10121501_197_dialog_content = "함정이 작동하지도 않고, 루미나가 흐르고 있는 것도 아니다.",
  ui_story_1012_10121501_198_dialog_content = "저런 돌무더기에 벌벌 떨어야 할 필요가 있느냐는 말이다.",
  ui_story_1012_10121501_199_dialog_content = "무슨 작용을 하는지 알 수 없는 돌들이네.\n언제 다시 작동할지 누가 알 수 있겠는가.",
  ui_story_1012_10121501_200_dialog_content = "저, 저기...",
  ui_story_1012_10121501_201_dialog_content = "귀환의 탑의 에너지는 완전히 바닥났어요. 제가 보장할 수 있어요.",
  ui_story_1012_10121501_202_dialog_content = "대원수님 말씀처럼 그냥 돌더미일 뿐이에요.",
  ui_story_1012_10121501_203_dialog_content = "그저 역사의 흔적들이 새겨져 있는 돌더미인 거죠.",
  ui_story_1012_10121501_204_dialog_content = "......",
  ui_story_1012_10121501_205_dialog_content = "아이테르여, 그런 보장을 할 때는 신중해야 하네.\n그대는 그러한 부담을 감당할 수 있겠는가?",
  ui_story_1012_10121501_206_dialog_content = "전...",
  ui_story_1012_10121501_207_dialog_content = "성주님, 그 사실은 제가 보증하겠습니다.",
  ui_story_1012_10121501_208_dialog_content = "카렌?",
  ui_story_1012_10121501_209_dialog_content = "저와 PlayerName 두 사람은 함께 귀환의 탑을 탐색했습니다.",
  ui_story_1012_10121501_210_dialog_content = "현재 귀환의 탑은 다시는 가동이 불가능하다는 것을 제가 보증하겠습니다.",
  ui_story_1012_10121501_211_dialog_content = "......",
  ui_story_1012_10121501_212_dialog_content = "그러니까 그렇게 긴장할 거 없다고 했잖아.",
  ui_story_1012_10121501_213_dialog_content = "이 세계에 있어 저 탑은 이제 위협이 아니라 희귀한 고대 유적에 불과하다.",
  ui_story_1012_10121501_214_dialog_content = "저 탑은 과거에는 아이테르의 소유였고, 그 사실은 현재도 유효하다.",
  ui_story_1012_10121501_215_dialog_content = "네?",
  ui_story_1012_10121501_216_dialog_content = "나는 저 탑이 PlayerName의 소유라고 생각한다.",
  ui_story_1012_10121501_217_dialog_content = "우리가 탑 안의 유물을 처리하려는 방식도 그의 동의를 얻어야 마땅할 것이다.",
  ui_story_1012_10121501_218_dialog_content = "만약 그것으로 이 세계에 이로운 연구를 한다면 PlayerName도 물론 허락하겠지.",
  ui_story_1012_10121501_219_dialog_content = "그러나 악의적인 목적을 지녔다면 PlayerName에게도 거부할 권리가 있다.",
  ui_story_1012_10121501_220_dialog_content = "잠깐만 기다려 주십시오. 먼저 설명할 점이 있습니다.",
  ui_story_1012_10121501_221_dialog_content = "대원수님의 발언은 대원수님 개인의 견해이지,\n일루미나의 뜻을 대표하지 않습니다.",
  ui_story_1012_10121501_222_dialog_content = "호오? 그럼 일루미나의 뜻은 무엇이지? 어디 귀담아들어 볼까.",
  ui_story_1012_10121501_223_dialog_content = "일루미나는 귀환의 탑에 대한 연구를 진행할 것입니다.",
  ui_story_1012_10121501_224_dialog_content = "이곳은 그 어떤 개인의 소유여서도 안 됩니다!",
  ui_story_1012_10121501_225_dialog_content = "쳇, 너희들...",
  ui_story_1012_10121501_226_dialog_content = "나는 라인하르트의 의견에 동의한다.",
  ui_story_1012_10121501_227_dialog_content = "귀환의 탑은 PlayerName의 소유다.",
  ui_story_1012_10121501_228_dialog_content = "북방 여왕...",
  ui_story_1012_10121501_229_dialog_content = "우리 모두는 한때 자신의 터전을 지키기 위해 싸웠고,\n이는 가장 존경받아 마땅한 이유이다.",
  ui_story_1012_10121501_230_dialog_content = "아이테르도 우리처럼 이곳을 지키기 위해 싸웠다.",
  ui_story_1012_10121501_231_dialog_content = "만약 목숨을 걸고 분투한 결과가 터전을 사방에 빼앗기는 것이라면,\n그것은 전쟁에서 패배한 것과 다를 바가 없다.",
  ui_story_1012_10121501_232_dialog_content = "아이테르에게 있어 오로리안과 암귀는 모두 다른 종족일 뿐이다.",
  ui_story_1012_10121501_233_dialog_content = "아이테르를 맹우로 여긴다면, 헤븐즈 밸리를 침범하지 않는 것이\n오로리안이 기본적으로 보여야 할 존중이다.",
  ui_story_1012_10121501_234_dialog_content = "여왕 폐하...",
  ui_story_1012_10121501_235_dialog_content = "솔라드 성주가 염려한 점이라면 나는 기우라고 생각한다.",
  ui_story_1012_10121501_236_dialog_content = "무기의 역할은 다루는 이에 따라 정해지는 것이다.",
  ui_story_1012_10121501_237_dialog_content = "이 오로리안이 귀환의 탑으로 이번 전쟁의 흐름을 역전한 것은 우리 모두가 보았다.",
  ui_story_1012_10121501_238_dialog_content = "그는 이로써 귀환의 탑의 입장을 모두에게 표한 것이다.",
  ui_story_1012_10121501_239_dialog_content = "......",
  ui_story_1012_10121501_240_dialog_content = "북방의 여왕, 그대가 이렇게 의견을 내다니, 드문 일이군.",
  ui_story_1012_10121501_241_dialog_content = "이번 일이 그대에게 그토록 중요하단 말인가?",
  ui_story_1012_10121501_242_dialog_content = "아이테르라는 맹우는 오로리안에게 매우 중요하다.",
  ui_story_1012_10121501_243_dialog_content = "알겠다.",
  ui_story_1012_10121501_244_dialog_content = "더 말을 꺼낸다면 고리타분한 인간이라는 소리를 듣겠군.",
  ui_story_1012_10121501_245_dialog_content = "북방의 여왕이 아주 잘 이야기해 주었다. 나도 여왕의 의견을 존중하는 바이네.",
  ui_story_1012_10121501_246_dialog_content = "백야성은 다시는 귀환의 탑의 처분에 관여하지 않을 것이네.",
  ui_story_1012_10121501_247_dialog_content = "그대들은 어떠한가.",
  ui_story_1012_10121501_248_dialog_content = "그렇다면 나도 동의하지.",
  ui_story_1012_10121501_249_dialog_content = "하하하, 봐! 이러니까 얼마나 좋아? 나도 반대 안 해!",
  ui_story_1012_10121501_250_dialog_content = "......",
  ui_story_1012_10121501_251_dialog_content = "일루미나의 입장은 이미 밝혔습니다.\n각 측의 선택에 대해서는 언급하지 않겠습니다.",
  ui_story_1012_10121501_252_dialog_content = "그럼 이 이야기는 이쯤에서 마무리 지어도 되겠군.",
  ui_story_1012_10121501_253_dialog_content = "다행이든, 실망이든 전쟁은 이미 끝났다.\n이제 모두가 평화의 과실을 나눠 먹을 수 있다는 뜻이다.",
  ui_story_1012_10121501_254_dialog_content = "다음 전쟁이 일어나기 전까지, 계속 지금처럼 뜨뜻미지근하게 지내자고.",
  ui_story_1012_10121501_255_dialog_content = "그리고 PlayerName. 축하한다. 네 전리품을 받아라.",
  ui_story_1012_10121501_256_dialog_content = "온전한 너의 집이다.",
  ui_story_1012_10121501_257_dialog_content = "......",
  ui_story_1012_10121501_258_dialog_content = "휴...",
  ui_story_1012_10121501_259_dialog_content = "온전한 집...",
  ui_story_1012_10121501_260_dialog_content = "왜 한숨을 쉬는 것이냐.",
  ui_story_1012_10121501_261_dialog_content = "여, 여왕 폐하?",
  ui_story_1012_10121501_262_dialog_content = "왜 여기 계신 거죠?",
  ui_story_1012_10121501_263_dialog_content = "얼굴에 고민이 가득하구나.",
  ui_story_1012_10121501_264_dialog_content = "하하, 역시 폐하의 눈을 속일 수는 없네요.",
  ui_story_1012_10121501_265_dialog_content = "음... 으음...",
  ui_story_1012_10121501_266_dialog_content = "확실히 지금 좀 막막해요. 잘 모르겠어요.",
  ui_story_1012_10121501_267_dialog_content = "이번 전투 때문인 것이냐.",
  ui_story_1012_10121501_268_dialog_content = "그건 아니에요. 음, 저는...",
  ui_story_1012_10121501_269_dialog_content = "들어 줄 이가 필요하다면, 내가 있다.",
  ui_story_1012_10121501_270_dialog_content = "북방의 여왕으로서가 아닌, 샤야로서 말이다.",
  ui_story_1012_10121501_271_dialog_content = "샤야...로서...",
  ui_story_1012_10121501_272_dialog_content = "고마워요. 음... 맞아요. 아마 누군가에게 이야기를 하고 싶었던 걸지도 몰라요.",
  ui_story_1012_10121501_273_dialog_content = "말해 보거라, 듣고 있다.",
  ui_story_1012_10121501_274_dialog_content = "저...저흰 지하에서... 아이테르의 과거에 대해 보았어요.",
  ui_story_1012_10121501_275_dialog_content = "귀환의 탑의 기록은 손상된 부분도 많았지만, 그래도 확실히 봤어요...",
  ui_story_1012_10121501_276_dialog_content = "아이테르와 암귀가 함께 싸우는 모습을요...",
  ui_story_1012_10121501_277_dialog_content = "그러니까, 음... 아주 오래전에는 암귀와 아이테르가 동료였을지도 몰라요.",
  ui_story_1012_10121501_278_dialog_content = "아이테르와 암귀가?",
  ui_story_1012_10121501_279_dialog_content = "네, 아이테르와 암귀가 함께 작전을 펼치는 모습을 감응했어요.",
  ui_story_1012_10121501_280_dialog_content = "대체 이 기분을 뭐라고 설명해야 할지 모르겠어요...",
  ui_story_1012_10121501_281_dialog_content = "증거들이 불완전하긴 했지만, 적어도 전 그게 진짜로 있었던 일이라고 믿어요.",
  ui_story_1012_10121501_282_dialog_content = "전투가 끝나고 나니까, 자꾸 그 장면들이 머릿속에 맴돌아서...",
  ui_story_1012_10121501_283_dialog_content = "조금 버티기가 힘들어요.",
  ui_story_1012_10121501_284_dialog_content = "괜찮느냐, PlayerName.",
  ui_story_1012_10121501_285_dialog_content = "괜찮아요. 근데 머리가 터질 것 같아요. 자료들을 못 가지고 나와서 아깝네요.\n안 그랬으면 폐하께도 보여드릴 수 있었을 텐데 말이에요.",
  ui_story_1012_10121501_286_dialog_content = "네가 본 것이 사실이라는 보장은 없다.\n게다가 우리 북방에도 아이테르와 암귀가 동맹을 맺었다는 기록은 없었다.",
  ui_story_1012_10121501_287_dialog_content = "폐하께 맹세할 수 있어요. 전 진짜로 아이테르가 암귀와 함께\n오로리안들을 죽이는 모습을 봤어요. 진짜예요...",
  ui_story_1012_10121501_288_dialog_content = "그 느낌... 그런 느낌은 절대 단순한 환상 같은 게 아니었어요.",
  ui_story_1012_10121501_289_dialog_content = "저도 그게 가짜였으면 좋겠어요. 누구보다 말이에요.",
  ui_story_1012_10121501_290_dialog_content = "설령 그것이 진실이라면, 노비오가 그것을 몰랐겠느냐.\n오랜 시간을 살아온 노비오조차 그런 이야기는 한 적이 없었다.",
  ui_story_1012_10121501_291_dialog_content = "맞아요. 제가 스카이워커호에서 본 아이테르의 역사에서도\n그런 말은 단 한 번도 나왔던 적 없어요.",
  ui_story_1012_10121501_292_dialog_content = "백야성과 일루미나에도 그러한 기록은 없는 것으로 알고 있다. 그게 아니라면...",
  ui_story_1012_10121501_293_dialog_content = "만약 그게 사실이라면 암귀와 한패였던 자들의 후예인 전 분명히... 하하...",
  ui_story_1012_10121501_294_dialog_content = "제가 본 자료에 대해 자세히 설명해 드릴게요. 그러니까 처음엔...",
  ui_story_1012_10121501_295_dialog_content = "...이런 내용이었어요.",
  ui_story_1012_10121501_296_dialog_content = "......",
  ui_story_1012_10121501_297_dialog_content = "첫째, 그 자료들은 온전한 것이 아니다.\n따라서 섣불리 결론을 내려서는 아니 된다.",
  ui_story_1012_10121501_298_dialog_content = "둘째, 설령 그 일들이 진짜 발생했던 사실이라 해도,\n그것은 아주 오래전에 일어났던 일들이다.",
  ui_story_1012_10121501_299_dialog_content = "무엇이 진상인지는 그대의 선조들조차 모를 것이다.",
  ui_story_1012_10121501_300_dialog_content = "폐하의 말씀은... 북방의 역사보다도 더 오래전의 일일 수 있다는 건가요?",
  ui_story_1012_10121501_301_dialog_content = "고대에 관한 우리 오로리안들의 연구는 온전치 못하다.\n공백이라고 말해도 좋을 정도다.",
  ui_story_1012_10121501_302_dialog_content = "허나 오로리안의 역사 속 아이테르와 아인족은\n언제나 오로리안의 좋은 동료이자, 맹우였다.",
  ui_story_1012_10121501_303_dialog_content = "우리가 함께 암귀에 맞서 왔다는 사실은 단 한 번도 변한 적이 없다.",
  ui_story_1012_10121501_304_dialog_content = "그대의 일족도 암귀에게 목숨을 잃지 않았느냐.",
  ui_story_1012_10121501_305_dialog_content = "그래서 저도 대체 뭐가 어떻게 된 건지 모르겠어요. 저도 진실을 찾고 싶다구요.",
  ui_story_1012_10121501_306_dialog_content = "하지만 만약 아이테르가... 정말로 암귀와...",
  ui_story_1012_10121501_307_dialog_content = "설령 그렇다 한들, 그토록 오래전에 있었던 일들이\n그대에게 큰 영향을 미칠 수 있다고 생각하느냐.",
  ui_story_1012_10121501_308_dialog_content = "전 계속 생각했어요. 만약 아이테르가 과거에 정말 암귀와 결탁했다면...",
  ui_story_1012_10121501_309_dialog_content = "제가 어렸을 때부터 배워 온 아이테르의 역사와 신념들은...\n모두 가짜가 아닐까...라고 말이에요.",
  ui_story_1012_10121501_310_dialog_content = "제가 알 기회조차 없었던 제 동족들이 저와 같은 걸 봤다면 무슨 생각을 했을까요?",
  ui_story_1012_10121501_311_dialog_content = "아이테르가 정말 그런 거라면... 너무나도 추악한 일이잖아요.",
  ui_story_1012_10121501_312_dialog_content = "비록 오로리안과 이념은 다르나, 아이테르는 자연과 평화를 사랑하는 일족이다.\n그것은 이 대륙의 모든 이가 주지하는 사실이다.",
  ui_story_1012_10121501_313_dialog_content = "어쩌면 그사이에 우리가 지금은 아직 알 수 없는 일이 있었음이 분명하다.\n그대는...",
  ui_story_1012_10121501_314_dialog_content = "전 아이테르의 신념과 믿음을 가지고 지금까지 살아왔어요.\n근데 만약 그게 전부 가짜라면, 전...",
  ui_story_1012_10121501_315_dialog_content = "...진정한 아이테르가 되려고 했던 전 대체 뭐가 되는 거죠?",
  ui_story_1012_10121501_316_dialog_content = "PlayerName, 그대는 내가 본 가장 용감하고 강인한 아이테르다.",
  ui_story_1012_10121501_317_dialog_content = "...하아, 머리가 깨질 것 같아요.",
  ui_story_1012_10121501_318_dialog_content = "PlayerName, 만약 아이테르가 암귀와 동맹을 맺었다는 것이 사실이라면,\n그대는 어찌할 생각이지? 암귀의 동료가 될 것이냐?",
  ui_story_1012_10121501_319_dialog_content = "무슨 말씀을 하시는 거죠?! 무슨 일이 있어도 전 끝까지 암귀들과 싸울 거예요!",
  ui_story_1012_10121501_320_dialog_content = "녀석들은 제게서 가족을 앗아가고, 동료를 상처 입혔어요.\n전 절대 암귀를 용서하지 않을 거라구요.",
  ui_story_1012_10121501_321_dialog_content = "그러한 그대의 신념과 힘은 아이테르 일족에게서 계승한 것이 아니더냐.",
  ui_story_1012_10121501_322_dialog_content = "역사는 역사일 뿐이다.\n중요한 것은 자기 자신, 그리고 그 선량하고 용감했던 사람들이다.",
  ui_story_1012_10121501_323_dialog_content = "...조금은 알겠어요. 하지만 순간적으로 받아들이기가 너무 힘들었어요.\n...이 오점을 받아들인다는 게 말이에요.",
  ui_story_1012_10121501_324_dialog_content = "그대가 백야성 축제에서 저 지도자들의 음모를 밝혀냈던 일을 기억하느냐.",
  ui_story_1012_10121501_325_dialog_content = "후훗, 그때의 자신을 기억해 두어라.",
  ui_story_1012_10121501_326_dialog_content = "...하지만... 이 과거의 역사는 우리 아이테르의 치욕이자 원죄가 될 거예요.\n저도 사람들 앞에서 고개를 들고 다닐 수 없겠죠.",
  ui_story_1012_10121501_327_dialog_content = "심지어 동료들에게도 의심을 받을 거예요...",
  ui_story_1012_10121501_328_dialog_content = "아까 귀환의 탑에 관한 이야기를 나눌 때처럼...\n저를 이 세상의 암적인 존재로 여기게 되는 건 아닐까요...?",
  ui_story_1012_10121501_329_dialog_content = "전... 모두가 의심이 가득한 눈으로 저를 바라보게 될까...\n그게 너무 두려워요...",
  ui_story_1012_10121501_330_dialog_content = "백야성과 일루미나도 그들이 남긴 오점이 있다.\n그럼에도 그대는 카렌과 바이스를 좋은 동료로 받아들이지 않았느냐.",
  ui_story_1012_10121501_331_dialog_content = "저흰 함께 싸우면서 서로를 믿고, 의지할 수 있었으니까요...",
  ui_story_1012_10121501_332_dialog_content = "그 두 사람이 아득히 머나먼 역사의 파편 때문에\n그대를 동료로 여기지 않으리라 생각하는 것이냐?",
  ui_story_1012_10121501_333_dialog_content = "절대 그러진 않겠죠!",
  ui_story_1012_10121501_334_dialog_content = "그러니 말이다. 사실 문제는 그리 복잡한 것이 아니다.",
  ui_story_1012_10121501_335_dialog_content = "그대는 PlayerName일 뿐, 모든 아이테르가 아니다.",
  ui_story_1012_10121501_336_dialog_content = "하지만 아이테르는 거의 제 모든 것이었어요.\n아마 북방이 폐하께 가지는 의미와 똑같을 거예요.",
  ui_story_1012_10121501_337_dialog_content = "「아이테르는 싸울 수도 없는 쓰레기고, 심지어 과거에 암귀와 한패였을 수도 있다」...",
  ui_story_1012_10121501_338_dialog_content = "그런 생각이 들면 너무 괴로워요.",
  ui_story_1012_10121501_339_dialog_content = "이해할 수 있다.",
  ui_story_1012_10121501_340_dialog_content = "지금의 우리로서는 역사의 진상을 완벽히 알 수 없겠지.",
  ui_story_1012_10121501_341_dialog_content = "어쩌면 너의 선조는 배반이라는 선택을 통해 아이테르의 운명을 바꾸었을지도 모른다.",
  ui_story_1012_10121501_342_dialog_content = "역사는 바뀌지 않는다.",
  ui_story_1012_10121501_343_dialog_content = "현재 아이테르의 미래는 그대가 어떻게 하느냐에 달려 있다.",
  ui_story_1012_10121501_344_dialog_content = "네... 잘 생각해 봐야겠어요.",
  ui_story_1012_10121501_345_dialog_content = "아마 제가 가장 먼저 해야 할 일은 바로 진상을 조사하는 걸지도 모르겠네요.",
  ui_story_1012_10121501_346_dialog_content = "만약 그 진상이 그대가 받아들이고 싶지 않았던 것이라면,\n어떻게 할 것이냐, PlayerName.",
  ui_story_1012_10121501_347_dialog_content = "휴... 진상이 제가 생각했던 것보다 더 잔인할까 너무 무서워요.",
  ui_story_1012_10121501_348_dialog_content = "게다가 나중엔 모두의 의심과 감시를 받을지도 모르구요.",
  ui_story_1012_10121501_349_dialog_content = "그대에게는 시간이 필요하다, PlayerName.",
  ui_story_1012_10121501_350_dialog_content = "그렇겠죠... 아주 긴 시간이 필요할 것 같네요...",
  ui_story_1012_10121501_351_dialog_content = "<color=#e8d9bb>「제어 시스템, 가동.」</color>",
  ui_story_1012_10121501_352_dialog_content = "<color=#e8d9bb>「바이오 모듈, 가동.」</color>",
  ui_story_1012_10121501_353_dialog_content = "<color=#e8d9bb>「생명유지 시스템, 가동」</color>",
  ui_story_1012_10121501_354_dialog_content = "<color=#e8d9bb>「엔진 가동 중──」</color>",
  ui_story_1012_10121501_355_dialog_content = "<color=#e8d9bb>「16%... 33%...」</color>",
  ui_story_1012_10121501_356_dialog_content = "<color=#e8d9bb>「89%... 97%...」</color>",
  ui_story_1012_10121501_357_dialog_content = "<color=#e8d9bb>「100%── 가동 성공──」</color>",
  ui_story_1012_10121501_358_dialog_content = "우와! 드디어 스카이워커호를 고쳤네!",
  ui_story_1012_10121501_359_dialog_content = "응! 드디어 해냈어!",
  ui_story_1012_10121501_360_dialog_content = "아직 의식이 완전히 깨어난 건 아니지만, 여기까지 온 것만으로도 정말 다행이야!",
  ui_story_1012_10121501_361_dialog_content = "잃어버렸다가 되찾은 그런 느낌이지?",
  ui_story_1012_10121501_362_dialog_content = "맞아!",
  ui_story_1012_10121501_363_dialog_content = "휴, 힘들어 죽겠네. 요 며칠은 진짜 죽다 살아났다니까.",
  ui_story_1012_10121501_364_dialog_content = "얇은 줄에 매달려서, 잘못하면 강바닥으로 빠져버릴 것 같은 그런 느낌이었어.",
  ui_story_1012_10121501_365_dialog_content = "그래도 마지막엔 어떻게든 버텨냈잖아.",
  ui_story_1012_10121501_366_dialog_content = "그러게 말이야... 운이 좋았지, 아하하.",
  ui_story_1012_10121501_367_dialog_content = "하하, 그러게.",
  ui_story_1012_10121501_368_dialog_content = "근데 어쩌면 운만 좋았던 게 아닐 수도 있어.",
  ui_story_1012_10121501_369_dialog_content = "모든 일에는 원인이 있는 법이거든. 우리 눈에 안 보일 뿐이지.",
  ui_story_1012_10121501_370_dialog_content = "너 왠지 의미심장한 말을 많이 하기 시작한 것 같아.\n귀환의 탑에서 갑자기 뭐라도 깨달은 거야?",
  ui_story_1012_10121501_371_dialog_content = "그냥 그동안을 돌아보니까, 모든 일 사이에는 보이지 않는 관계가 있었던 것 같아.",
  ui_story_1012_10121501_372_dialog_content = "과거의 사람들도 이 귀환의 탑에서도 많은 일이 있었겠지.",
  ui_story_1012_10121501_373_dialog_content = "그 일들은 그 누구도 알 수 없겠지만, 저들은 이야기에 자신들의 흔적을 남겼어.",
  ui_story_1012_10121501_374_dialog_content = "우린 이 길에서 그 발자취를 따라가고 있는 것 같아.",
  ui_story_1012_10121501_375_dialog_content = "누구의 것인지도 모르고, 그 사람이 뭘 하려는 건지도 몰라.",
  ui_story_1012_10121501_376_dialog_content = "그냥 그 발자취를 따라가다가, 과거와 비슷한 궤적을 하나 그릴 뿐이야.",
  ui_story_1012_10121501_377_dialog_content = "너 또 그 「프란츠 선생님」 얘기하는 거지?",
  ui_story_1012_10121501_378_dialog_content = "그 사람이 엄청 신경 쓰이는 모양이구나.",
  ui_story_1012_10121501_379_dialog_content = "응, 그 사람은 과거에 어떤 일들을 겪어 왔을까 생각했거든.",
  ui_story_1012_10121501_380_dialog_content = "그 총은 그 사람 거였잖아. 과거에 귀환의 탑에서 암귀와 싸우기도 했을 거야.",
  ui_story_1012_10121501_381_dialog_content = "「화음 연결」 실험도 그 사람이 진행했던 거였어.\n실험실은 겹겹의 보안을 거친 추방 구역에 있었고.",
  ui_story_1012_10121501_382_dialog_content = "마지막에 「오리진 서클 권한」을 탈취하는 싸움을\n그 사람도 했을진 모르겠지만, 아무튼...",
  ui_story_1012_10121501_383_dialog_content = "그 싸움에서 승리하려면 반드시 「화음 연결」로 강화된 오로리안이 필요했어.",
  ui_story_1012_10121501_384_dialog_content = "확실히 그렇네. 그렇게 말하니까 우리가 겪었던 모든 일들에\n전부 그 사람의 손길이 닿아 있는 것 같잖아.",
  ui_story_1012_10121501_385_dialog_content = "우린 이클립스에 맞서기 위해 싸웠어.\n그럼 그 사람은 뭐랑 싸운 걸까?",
  ui_story_1012_10121501_386_dialog_content = "그 사람이 맞서야 했던 건 어쩌면 그것보다 더 무서운 존재였을지도 몰라.",
  ui_story_1012_10121501_387_dialog_content = "그게 뭔지는 알 수 없겠지만, 어쩌면... 운명이었을 수도 있어.",
  ui_story_1012_10121501_388_dialog_content = "운명이란 건 우리 목숨을 노리지 않아.\n대신 우릴 자신이 원하는 대로 살아가게 만들어.",
  ui_story_1012_10121501_389_dialog_content = "프란츠 선생님은 바로 그런 것과 맞서 싸웠을 거야.\n자신 앞의 「선천성」 말이야.",
  ui_story_1012_10121501_390_dialog_content = "선천성과... 맞선다...",
  ui_story_1012_10121501_391_dialog_content = "그런 거랑도 맞서 싸울 수 있는 거야?",
  ui_story_1012_10121501_392_dialog_content = "게다가 그 사람이 결국 성공했는지도 알 수 없잖아.",
  ui_story_1012_10121501_393_dialog_content = "성공했어. 바깥을 봐.",
  ui_story_1012_10121501_394_dialog_content = "아이테르는 드디어 귀환의 탑에서 자신만의 터전을 갖게 됐어.",
  ui_story_1012_10121501_395_dialog_content = "다시는 명령에 복종하지 않고, 암귀에게 고통받지 않아도 돼.",
  ui_story_1012_10121501_396_dialog_content = "그 사람은 이런 소망을 가지고, 자신의 후대들...",
  ui_story_1012_10121501_397_dialog_content = "우리 모든 아이테르의 인생을 고쳐 써 준 거야.",
  ui_story_1013_10130101_1_dialog_content = "또 평화로운 하루네.",
  ui_story_1013_10130101_2_dialog_content = "그러게.",
  ui_story_1013_10130101_3_dialog_content = "마지막으로 루미나틱스를 사용해서 암귀와 싸운 지도 벌써 한참 된 것 같아.",
  ui_story_1013_10130101_4_dialog_content = "전투 기술이 녹슬고 있는 느낌이라니까.",
  ui_story_1013_10130101_5_dialog_content = "평화로운 건 좋은 일이잖아!",
  ui_story_1013_10130101_6_dialog_content = "만약 언젠가 모든 암귀가 사라지는 날이 온다면, 그 후의 생활은 아마 지금 같지 않을까?",
  ui_story_1013_10130101_7_dialog_content = "습격당할 걱정 없이 하루 종일 걷고, 낚시하고, 요리하면서 보낼 수 있어.",
  ui_story_1013_10130101_8_dialog_content = "그거 왠지 나쁘지 않을 것 같아!",
  ui_story_1013_10130101_9_dialog_content = "그때가 되면 PlayerName 넌 뭘 하고 싶어?",
  ui_story_1013_10130101_10_option_content = "나무 심기?",
  ui_story_1013_10130101_11_dialog_content = "더 많은 희귀한 나무를 심고 헤븐즈 가든을 더 예쁘게 꾸밀 거야.",
  ui_story_1013_10130101_12_dialog_content = "근데 나무 심는 게 너무 어려워서 열에 아홉은 변이에 실패하고 있는 게 문제지!",
  ui_story_1013_10130101_13_dialog_content = "나무를 심는 건 인내가 필요한 일이야.",
  ui_story_1013_10130101_14_option_content = "낚시?",
  ui_story_1013_10130101_15_dialog_content = "관상어를 더 많이 잡아서 소원의 연못에 기르고 싶어.",
  ui_story_1013_10130101_16_dialog_content = "더는 깡통을 낚고 싶진 않다고...",
  ui_story_1013_10130101_17_dialog_content = "분명히 잡을 수 있을 거야!",
  ui_story_1013_10130101_18_dialog_content = "참, 헤븐즈 밸리가 지금처럼 평화로울 수 있는 건 율법의 현 덕분이잖아.",
  ui_story_1013_10130101_19_dialog_content = "율법의 현의 위력이 그렇게 대단할 줄은 정말 몰랐어.",
  ui_story_1013_10130101_20_dialog_content = "그때 만약 프란츠 선생님이 미리 설정한 매개 변수가 없었고, 내가 마음대로 발사했다면...",
  ui_story_1013_10130101_21_dialog_content = "그 결과는 정말 심각했을 거야.",
  ui_story_1013_10130101_22_dialog_content = "지금 생각해 보면 아직도 무서워.",
  ui_story_1013_10130101_23_dialog_content = "위기는 이미 지나갔잖아. 너무 신경 쓰지 마.",
  ui_story_1013_10130101_24_dialog_content = "일단 지금 잘 지내는 게 중요하지!",
  ui_story_1013_10130101_25_dialog_content = "응! 네 말이 맞아.",
  ui_story_1013_10130101_26_dialog_content = "근데 바이스, 왜 그 옷을 입고 있는 거야?",
  ui_story_1013_10130101_27_dialog_content = "아, 이 검은 옷 말하는 거야?",
  ui_story_1013_10130101_28_dialog_content = "예전 옷이 조금 더 익숙한 건 사실이지만,\n가끔은 내 이미지를 좀 바꾸고 싶다는 생각도 들거든.",
  ui_story_1013_10130101_29_dialog_content = "이상해? 아니면... 원래 입던 흰 제복으로 갈아입을까?",
  ui_story_1013_10130101_30_dialog_content = "아니, 괜찮아!",
  ui_story_1013_10130101_31_dialog_content = "네가 마음에 든다면 어떤 옷을 입든 난 괜찮으니까!",
  ui_story_1013_10130101_32_dialog_content = "아, 맞다. 아까 잡은 관상어가 아직 양동이에 있잖아.",
  ui_story_1013_10130101_33_dialog_content = "얼른 소원의 연못에 넣어야지!",
  ui_story_1013_10130101_34_dialog_content = "아, 깜빡할 뻔했네!",
  ui_story_1013_10130101_35_dialog_content = "내가 넣어주고 올게.",
  ui_story_1013_10130101_36_dialog_content = "어라?!",
  ui_story_1013_10130101_37_dialog_content = "바이스? 너 무슨 새로운 루미나틱스라도 익힌 거야?",
  ui_story_1013_10130101_38_dialog_content = "새로운 루미나틱스? 아닌데? 나...",
  ui_story_1013_10130101_39_dialog_content = "뭐야, 이게 무슨 일이야?!",
  ui_story_1013_10130101_40_dialog_content = "나 루미나틱스도 안 썼는데?!",
  ui_story_1013_10130101_41_dialog_content = "누가 장난 치는 건가? 빨리 나와! 다 봤으니까!",
  ui_story_1013_10130101_42_dialog_content = "음... 아니야. 이 루미나... 진짜로 내 몸에서 흘러나오는 게 맞아.",
  ui_story_1013_10130101_43_dialog_content = "루미나가 서서히 빠져나가는 게 느껴져... 이건 대체...",
  ui_story_1013_10130101_44_dialog_content = "설마...",
  ui_story_1013_10130101_45_dialog_content = "화음 연결 장치의 후유증일까?",
  ui_story_1013_10130101_46_dialog_content = "바이스, 괜찮아? 어디 불편한 곳 있어?",
  ui_story_1013_10130101_47_dialog_content = "몸에 불편한 점은 딱히 없어...",
  ui_story_1013_10130101_48_dialog_content = "루미나도 천천히 빠져나가고 있어서 아무 감각도 없을 정도야.",
  ui_story_1013_10130101_49_dialog_content = "그냥 이게 다라면 별문제는 안 될 것 같아.",
  ui_story_1013_10130101_50_dialog_content = "근데 다른 증상이 또 있을진 모르겠어.",
  ui_story_1013_10130101_51_dialog_content = "확실히 우린 고대 기술에 대해 아는 게 너무 적었어.\n역시 너무 경솔하게 그 장치를 사용했던 것 같아...",
  ui_story_1013_10130101_52_dialog_content = "걱정하지 마, PlayerName.",
  ui_story_1013_10130101_53_dialog_content = "이렇게 된 이상, 일단 자난성으로 돌아가자!",
  ui_story_1013_10130101_54_dialog_content = "자난성엔 일루미나 전역 최고의 과학자와 치료 시설이 있어.\n분명히 이 증상의 원인을 밝혀낼 수 있을 거야!",
  ui_story_1013_10130101_55_dialog_content = "응... 그래! 지금 바로 가자.\n가면서 단말기로 비비안 씨한테 연락하자. 분명히 우릴 도와줄 거야!",
  ui_story_1013_10130101_56_dialog_content = "자동 조종 장치 설정, 목표는 자난성.",
  ui_story_1013_10130101_57_dialog_content = "서둘러 줘!",
  ui_story_1013_10130101_58_dialog_content = "PlayerName, 너무 걱정하지 마, 난 괜찮으니까.",
  ui_story_1013_10130101_59_dialog_content = "그냥 좀 빛이 날 뿐이잖아~",
  ui_story_1013_10130101_60_dialog_content = "하지만 넌 내가 스카이워커를 고치는 걸 도와주려다 그렇게 된 거잖아.",
  ui_story_1013_10130101_61_dialog_content = "그리고 화음 연결 장치로 널 치료하기로 결정한 것도 나였어.",
  ui_story_1013_10130101_62_dialog_content = "그러니까... 난 지금 너한테 생긴 그 증상에 대해 책임을 져야만 해.",
  ui_story_1013_10130101_63_dialog_content = "난 그 고대 장치가 뭘 위해서 만들어졌는지도 모르고 멋대로 사용했어.",
  ui_story_1013_10130101_64_dialog_content = "PlayerName...",
  ui_story_1013_10130101_65_dialog_content = "너무 긴장하지 마. 나 진짜로 하나도 안 불편하니까.",
  ui_story_1013_10130101_66_dialog_content = "하지만 그래도 이런 기현상을 보고만 있을 순 없는 건 사실이야.",
  ui_story_1013_10130101_67_dialog_content = "맞아, 역시 자난성부터 가서 정밀 검사를 받는 게 가장 좋을 것 같아.",
  ui_story_1013_10130101_68_dialog_content = "그럼 비비안 님한테 연락해서 검사 준비를 도와달라고 하자.",
  ui_story_1013_10130101_69_dialog_content = "응.",
  ui_story_1013_10130101_70_dialog_content = "비비안 씨, 내 말 들려?",
  ui_story_1013_10130101_71_dialog_content = "PlayerName? 잘 들려요. 무슨 일이죠?",
  ui_story_1013_10130101_72_dialog_content = "나랑 바이스한테 지금 비비안 씨 도움이 필요해! 급한 일이야!",
  ui_story_1013_10130101_73_dialog_content = "이 타이밍에 급한 일이라니, 설마 바이스도 같은 증상인 건가요?",
  ui_story_1013_10130101_74_dialog_content = "바이스「도」라니?",
  ui_story_1013_10130101_75_dialog_content = "설마 바튼 씨도 몸에서 막 이상한 빛이 난 거야?!",
  ui_story_1013_10130101_76_dialog_content = "네, 헤븐즈 밸리에서의 지난번 전투 뒤로, 바튼 군단장은 잠시 휴식을 취하기로 되어 있었어요.",
  ui_story_1013_10130101_77_dialog_content = "그런데 오늘 아침 갑자기 바튼 군단장의 몸에 원인불명의 루미나 소실 현상이 발생했어요.",
  ui_story_1013_10130101_78_dialog_content = "그럼 바이스한테도 비슷한 증상이 있었던 건가요?",
  ui_story_1013_10130101_79_dialog_content = "맞아. 우린 지금 자난성으로 가는 중이야.\n바이스가 검사를 받을 수 있게 배정해 줄 수 있을까?",
  ui_story_1013_10130101_80_dialog_content = "네, 이번 일은 저한테 맡기세요.",
  ui_story_1013_10130101_81_dialog_content = "사실 일루미나에서도 화음 연결 장치를 사용한 바튼 군단장과 바이스에게\n전면적인 검사를 진행할 준비를 이미 하고 있었거든요.",
  ui_story_1013_10130101_82_dialog_content = "그래? 그럼 다행이네!",
  ui_story_1013_10130101_83_dialog_content = "자난성에 도착하면 곧바로 메디컬 센터로 오세요. 거기서 기다릴게요.",
  ui_story_1013_10130101_84_dialog_content = "응! 그럼 부탁할게!",
  ui_story_1013_10130101_85_dialog_content = "<color=#e8d9bb>자난성, 메디컬 센터</color>",
  ui_story_1013_10130101_86_dialog_content = "여기가 바로 메디컬 센터야.",
  ui_story_1013_10130101_87_dialog_content = "마지막으로 여기 왔던 것도 입대 전에 모두가 받는 건강 검진 때문이었는데.",
  ui_story_1013_10130101_88_dialog_content = "여긴 처음 와 보는 것 같네... 일루미나의 메디컬 센터가 이렇게 클 줄은 몰랐어!",
  ui_story_1013_10130101_89_dialog_content = "그거야 당연하지!",
  ui_story_1013_10130101_90_dialog_content = "일단 전쟁이 시작되면 얼마나 많은 사상자가 발생할지 알 수 없으니까.",
  ui_story_1013_10130101_91_dialog_content = "메디컬 센터가 클수록 더 많은 부상병이 제때 치료를 받을 수 있잖아.",
  ui_story_1013_10130101_92_dialog_content = "그럼 살아남을 확률도 더 높아지겠지...",
  ui_story_1013_10130101_93_dialog_content = "그건 그렇네...",
  ui_story_1013_10130101_94_dialog_content = "오, 바이스, PlayerName!",
  ui_story_1013_10130101_95_dialog_content = "역시 벌써 도착했군요.",
  ui_story_1013_10130101_96_dialog_content = "바튼 군단장님! 비비안 참모장님!",
  ui_story_1013_10130101_97_dialog_content = "바튼 씨 몸에도 같은 현상이 벌어졌잖아...",
  ui_story_1013_10130101_98_dialog_content = "아? 이 빛나는 거 말이냐?",
  ui_story_1013_10130101_99_dialog_content = "그냥 빛만 나는 거면 상관없잖아. 어차피 루미나 소모도 거의 없다고.",
  ui_story_1013_10130101_100_dialog_content = "하지만 그래도 혹시 모를 위험을 무시하면 안 돼요!",
  ui_story_1013_10130101_101_dialog_content = "말이 그렇다는 거지. 그래도 역시 저 의사랑 과학자 녀석들이\n얼른 이 빛을 멈출 방법을 찾아줬으면 좋겠군.",
  ui_story_1013_10130101_102_dialog_content = "안 그랬다간 싸울 때 기습은커녕 밤에 빛나는 표적이 될 거란 말이다!",
  ui_story_1013_10130101_103_dialog_content = "화, 확실히 그렇네요...",
  ui_story_1013_10130101_104_dialog_content = "뭐냐, 애송이. 얼굴에 걱정 두 글자를 쓰고 다닐 작정이냐?",
  ui_story_1013_10130101_105_dialog_content = "네? 음... 진짜로 걱정이 되니까 그렇죠.",
  ui_story_1013_10130101_106_dialog_content = "걱정 마라. 여긴 일루미나 전역 최고의 의료 기관이다.\n숨만 안 넘어가면 다 죽어가는 녀석도 살릴 수 있으니까!",
  ui_story_1013_10130101_107_dialog_content = "아프지도 않은 이런 발광 현상은 말할 것도 없지.",
  ui_story_1013_10130101_108_dialog_content = "음... 알겠어요!",
  ui_story_1013_10130101_109_dialog_content = "그럼 바튼 군단장과 바이스는 제가 데려갈게요.",
  ui_story_1013_10130101_110_dialog_content = "PlayerName 당신은 밖에서 기다려 주세요.",
  ui_story_1013_10130101_111_dialog_content = "알겠어.",
  ui_story_1013_10130101_112_dialog_content = "그럼 다녀올게.",
  ui_story_1013_10130101_113_dialog_content = "이따 보자고, 애송이.",
  ui_story_1013_10130101_114_dialog_content = "복도가 다시 고요해졌네.",
  ui_story_1013_10130101_115_dialog_content = "이번 일이 그냥 우연이었으면 좋겠는데...",
  ui_story_1013_10130101_116_dialog_content = "그리고 당신들이 해야 할 일은 이 세계에──",
  ui_story_1013_10130101_117_dialog_content = "전쟁을 불러오는 것뿐입니다.",
  ui_story_1013_10130101_118_dialog_content = "......",
  ui_story_1013_10130101_119_dialog_content = "아니, 난 절대 그렇게 안 할 거야.",
  ui_story_1013_10130101_120_dialog_content = "하지만... 내 선택이 정말로 옳은 걸까?",
  ui_story_1013_10130101_121_dialog_content = "지난번과 별 차이는 없어 보이네. 그래도 긴장을 늦추지 마.",
  ui_story_1013_10130101_122_dialog_content = "지금 네 몸으로는 어떤 부주의, 의외의 상황도 용납할 수 없어.",
  ui_story_1013_10130101_123_dialog_content = "콜록... 알고 있습니다.",
  ui_story_1013_10130101_124_dialog_content = "제 신체에 대해서는 스스로도 줄곧 잘 알고 있었으니까요.",
  ui_story_1013_10130101_125_dialog_content = "우리랑 같이 훈련하면 돼.",
  ui_story_1013_10130101_126_dialog_content = "좀 훈련하면 아무것도 못하는 콩나물도 강해질 수 있어. 내가 바로 그랬다니까!",
  ui_story_1013_10130101_127_dialog_content = "하하하, 제 상태는 훈련으로 해결할 수 있는 게 아니에요.",
  ui_story_1013_10130101_128_dialog_content = "(이 사람들도 검사 받으러 왔나?)",
  ui_story_1013_10130101_129_dialog_content = "너, 뭘 봐?",
  ui_story_1013_10130101_130_dialog_content = "어?! 아, 미, 미안!",
  ui_story_1013_10130101_131_dialog_content = "그냥 모르는 사람이다 싶어서 나도 모르게...",
  ui_story_1013_10130101_132_dialog_content = "어라, 잠깐만요. 당신...",
  ui_story_1013_10130101_133_dialog_content = "소문의 그 아이테르 아닌가요?",
  ui_story_1013_10130101_134_dialog_content = "에?",
  ui_story_1013_10130101_135_dialog_content = "뭐? 아이테르야?",
  ui_story_1013_10130101_136_dialog_content = "날 알아? 우리 만난 적 없는 것 같은데...",
  ui_story_1013_10130101_137_dialog_content = "물론 알고 있습니다. 저희들 사이에서는 굉장히 유명하니까요.",
  ui_story_1013_10130101_138_dialog_content = "당신은 콜로서스를 조종하고 사막 방어선에서 오로리안들과 함께 암귀에 맞서 싸웠죠.",
  ui_story_1013_10130101_139_dialog_content = "그리고 헤븐즈 밸리에서는 일루미나, 백야성, 북방과 협력해 암귀 군단을 물리쳤습니다.",
  ui_story_1013_10130101_140_dialog_content = "당신이 남긴 업적에 우리 모두 탄복하고 있어요.",
  ui_story_1013_10130101_141_option_content = "난 그저 내가 할 수 있는 일을 했을 뿐이야.",
  ui_story_1013_10130101_142_dialog_content = "암귀는 우리 모두의 적이잖아.",
  ui_story_1013_10130101_143_option_content = "모두와 함께 노력한 결과야.",
  ui_story_1013_10130101_144_dialog_content = "만약 모두의 도움이 없었다면 나 혼자서는 그렇게 많은 걸 이룰 수 없었을 거야.",
  ui_story_1013_10130101_145_dialog_content = "정말 소문대로 겸손하군요.",
  ui_story_1013_10130101_146_dialog_content = "먼저 자기소개를 하죠. 전 자오라고 합니다.\n서쪽의 더스크 타운에서 참모장을 맡고 있습니다.",
  ui_story_1013_10130101_147_dialog_content = "이쪽은 제 조수 크로우와 숀입니다.",
  ui_story_1013_10130101_148_dialog_content = "여기서 만날 줄은 몰랐는데 정말 운이 좋았네요. 당신 이름은 뭐죠?",
  ui_story_1013_10130101_149_dialog_content = "난 PlayerName, 반가워.",
  ui_story_1013_10130101_150_dialog_content = "만나서 반가워, PlayerName.",
  ui_story_1013_10130101_151_dialog_content = "안녕.",
  ui_story_1013_10130101_152_dialog_content = "아까는 미안해. 하지만 자오를 지키는 건 내 사명이거든.",
  ui_story_1013_10130101_153_dialog_content = "괜찮아. 남을 괜히 쳐다보는 것도 실례잖아.",
  ui_story_1013_10130101_154_dialog_content = "자오 참모장님한테 네 얘기는 자주 들었어!",
  ui_story_1013_10130101_155_dialog_content = "콜로서스를 조종해서 여러 곳에 갈 수 있다니 정말 부럽네!",
  ui_story_1013_10130101_156_dialog_content = "콜로서스가 있으면 먼 곳에 갈 때도 되게 편리하지?",
  ui_story_1013_10130101_157_dialog_content = "확실히 그렇지. 어딜 가든 콜로서스를 타면 금방 도착하거든.",
  ui_story_1013_10130101_158_dialog_content = "대단하네! 나도 콜로서스가 있었으면 좋겠어.",
  ui_story_1013_10130101_159_dialog_content = "그럼 바로 더스크 타운으로 돌아갈 수 있잖아!",
  ui_story_1013_10130101_160_dialog_content = "왜? 무슨 급한 일 있어?",
  ui_story_1013_10130101_161_dialog_content = "당연하지!",
  ui_story_1013_10130101_162_dialog_content = "PlayerName 넌 더스크 타운 쪽 상황도 몰라?",
  ui_story_1013_10130101_163_dialog_content = "잘 몰라. 그게 어딘데?",
  ui_story_1013_10130101_164_dialog_content = "더스크 타운은 일루미나 방위선 밖에 있는 마을로, 자난성에서 상당히 먼 곳입니다.",
  ui_story_1013_10130101_165_dialog_content = "방위선 안쪽의 마을보다는 암귀의 습격을 당하기 쉽지만, 그래도 무척 좋은 곳이죠.",
  ui_story_1013_10130101_166_dialog_content = "얼른 돌아가서 동료들이랑 같이 그 시커먼 놈들을 쓰러트리고 싶어!",
  ui_story_1013_10130101_167_dialog_content = "정말 너무해. 누가 봐도 별거 아닌 상처인데 그 의사들은\n굳이 자난성까지 와서 치료받으라고 하고 말이야.",
  ui_story_1013_10130101_168_dialog_content = "그래도 이젠 검사도 끝났으니까, 오늘 오후엔 더스크 타운으로 돌아갈 수 있어!",
  ui_story_1013_10130101_169_dialog_content = "의사도 널 위해서 그런 거야.",
  ui_story_1013_10130101_170_dialog_content = "항상 건강한 상태를 유지해야 더 많은 적을 상대할 힘을 유지할 수 있어.",
  ui_story_1013_10130101_171_dialog_content = "누군가처럼 무리해서 자길 아프게 해서는 안 돼.",
  ui_story_1013_10130101_172_dialog_content = "콜록... 그럼, PlayerName 씨, 우린 먼저 가겠습니다.",
  ui_story_1013_10130101_173_dialog_content = "기회가 된다면 꼭 더스크 타운에 와 주세요.",
  ui_story_1013_10130101_174_dialog_content = "아이테르와 함께 싸울 날이 무척 기대되네요.",
  ui_story_1013_10130101_175_dialog_content = "응, 기회가 되면 꼭 갈게.",
  ui_story_1013_10130101_176_dialog_content = "그럼, 인연이 되면 또 봅시다.",
  ui_story_1013_10130101_177_dialog_content = "안녕.",
  ui_story_1013_10130101_178_dialog_content = "바이바이~",
  ui_story_1013_10130101_179_dialog_content = "더스크 타운... 왠지 엄청 멀 것 같은 이름이네.",
  ui_story_1013_10130101_180_dialog_content = "어라? 저기 상담실에서 나온 사람...",
  ui_story_1013_10130101_181_dialog_content = "라인하르트 씨잖아?!",
  ui_story_1013_10130101_182_dialog_content = "음? PlayerName.",
  ui_story_1013_10130101_183_dialog_content = "비비안이 바이스를 자난성으로 데려오겠다고 한 건 들었지만, 여기서 만날 줄은 몰랐네.",
  ui_story_1013_10130101_184_dialog_content = "저도 놀랐어요, 라인하르트 씨.",
  ui_story_1013_10130101_185_dialog_content = "왜 여기 계세요?",
  ui_story_1013_10130101_186_dialog_content = "설마 지난번에 스카이워커의 의료 시스템을 사용하고 몸에 무슨 문제라도 생긴 건가요?",
  ui_story_1013_10130101_187_dialog_content = "아니, 내겐 바튼과 바이스 같은 증상은 일어나지 않았다.",
  ui_story_1013_10130101_188_dialog_content = "오늘 온 건 그저 늘 있는 신체 검사 때문이야.",
  ui_story_1013_10130101_189_dialog_content = "반년마다 한 번 진행하고, 체력 검사와 혈액 검사 등이 포함되어 있지.",
  ui_story_1013_10130101_190_dialog_content = "결과는 지난번과 동일하니 걱정할 필요 없다.",
  ui_story_1013_10130101_191_dialog_content = "그랬군요. 그럼 다행이네요. 참, 지난번에 다친 건 괜찮아지셨나요?",
  ui_story_1013_10130101_192_dialog_content = "하하하, 걱정 마라. 네 의료 시스템 덕분에 상처는 진작에 나았으니까.",
  ui_story_1013_10130101_193_dialog_content = "일루미나에도 그런 시설이 있었다면...",
  ui_story_1013_10130101_194_dialog_content = "돌아왔다, 애송이.",
  ui_story_1013_10130101_195_dialog_content = "대원수? 너도 있었나.",
  ui_story_1013_10130101_196_dialog_content = "PlayerName, 그리고 대원수님?!",
  ui_story_1013_10130101_197_dialog_content = "두 사람 검사는 끝났나? 결과는?",
  ui_story_1013_10130101_198_dialog_content = "결과요? 음... 뭐라고 말씀드려야 하나...",
  ui_story_1013_10130101_199_dialog_content = "보고하지. 결과는... 없다!",
  ui_story_1013_10130101_200_dialog_content = "네?!",
  ui_story_1013_10130101_201_dialog_content = "저 의사들과 과학자들은 오랫동안 우릴 다양한 장비로 시험해 보았지만,\n아무 결론도 내리지 못했다.",
  ui_story_1013_10130101_202_dialog_content = "받아야 할 검사는 다 받았고, 정상 상태와 별반 다를 바가 없었다.",
  ui_story_1013_10130101_203_dialog_content = "맞아요. 적어도 테스트 결과만 놓고 보면 아무 문제도 없었어요.",
  ui_story_1013_10130101_204_dialog_content = "근데 지금은 두 사람 몸에서 루미나가 안 빠져나가고 있잖아. 그건 어떻게 고친 거야?",
  ui_story_1013_10130101_205_dialog_content = "아, 그거!",
  ui_story_1013_10130101_206_dialog_content = "실험을 하는 동안 과학자들이 우리한테 루미나틱스로 훈련용 더미를 공격하라고 했다.",
  ui_story_1013_10130101_207_dialog_content = "저들은 아마 이 루미나 소실 현상이 루미나틱스의 위력에\n어떤 영향을 미치는지 알고 싶었겠지.",
  ui_story_1013_10130101_208_dialog_content = "아무튼 그래서 훈련용 더미를 실컷 패주고 났더니 이 발광 현상이 저절로 사라졌다.",
  ui_story_1013_10130101_209_dialog_content = "이렇게 해서 빛이 안 나는 줄 알았으면 진작에 가서 암귀나 패버릴 걸 그랬어.",
  ui_story_1013_10130101_210_dialog_content = "과학자들 말로는 바튼 군단장이 훈련용 더미를 열 개 부쉈다고 해요.",
  ui_story_1013_10130101_211_dialog_content = "호오? 그렇다면 수리에 필요한 재료는 2군단장의 이번 달 배급에서 깎기로 하지.",
  ui_story_1013_10130101_212_dialog_content = "뭐, 뭐야?!",
  ui_story_1013_10130101_213_dialog_content = "하하하, 농담이다.",
  ui_story_1013_10130101_214_dialog_content = "둘 다 아무 일도 없었다면 그걸로 됐다.\n다만 지금 아무렇지도 않다고 해서 마음을 놓아선 안 된다.",
  ui_story_1013_10130101_215_dialog_content = "당분간은 정기적으로 검사를 받아서 만일의 문제가 없도록 해라.",
  ui_story_1013_10130101_216_dialog_content = "알겠다!",
  ui_story_1013_10130101_217_dialog_content = "네!",
  ui_story_1013_10130101_218_dialog_content = "아무튼 난 아무 이상 없어.",
  ui_story_1013_10130101_219_dialog_content = "그러니까 PlayerName 너도 걱정하지 마.",
  ui_story_1013_10130101_220_dialog_content = "루미나 소실뿐이라면, 지금 당장은 확실히 문제가 없을 것 같긴 하지만....",
  ui_story_1013_10130101_221_dialog_content = "난 화음 연결 장치를 사용한 것 때문에 다른 증상이 생길까 걱정인 거야.",
  ui_story_1013_10130101_222_dialog_content = "아무것도 알 수 없다는 게 가장 무서운 거니까...",
  ui_story_1013_10130101_223_dialog_content = "의사나 과학자들도 그렇게 말했어.",
  ui_story_1013_10130101_224_dialog_content = "그래서 우리한테 여러 활동을 해 보고, 계속해서 신체 변화에 주의하라고 했어.",
  ui_story_1013_10130101_225_dialog_content = "응, 나도 같이 신경 쓸게!",
  ui_story_1013_10130101_226_dialog_content = "마침 그 일에 내가 제안을 하나 하고 싶다.",
  ui_story_1013_10130101_227_dialog_content = "아니, 정확히 말하자면 이건 부탁이다.",
  ui_story_1013_10130101_228_dialog_content = "PlayerName, 일루미나에 스카이워커호와 귀환의 탑을\n연구할 수 있는 권한을 주었으면 한다.",
  ui_story_1013_10130101_229_dialog_content = "네?!",
  ui_story_1013_10130101_230_dialog_content = "왜죠? 이유를 들어볼 수 있을까요?",
  ui_story_1013_10130101_231_dialog_content = "물론이다.",
  ui_story_1013_10130101_232_dialog_content = "일전의 그 일들을 통해 나와 일루미나의 과학 연구원들은 아이테르가 지닌\n과학 기술이 얼마나 막강한지를 깨닫게 됐다.",
  ui_story_1013_10130101_233_dialog_content = "특히 화음 연결 장치와 의료 장치는 만약 전투에 사용할 수 있다면,\n무수한 오로리안의 생명을 구할 수 있을 것이다.",
  ui_story_1013_10130101_234_dialog_content = "그리고 콜로서스의 시뮬레이션 룸도 큰 가능성을 지닌 장치지.",
  ui_story_1013_10130101_235_dialog_content = "시뮬레이션 룸을 사용해 지휘관을 훈련한다면 분명히 사상자를 줄일 수 있겠지.",
  ui_story_1013_10130101_236_dialog_content = "하지만...",
  ui_story_1013_10130101_237_dialog_content = "(만약 아이테르의 과학 기술이 전쟁을 불러오는 것이었다면...\n그걸 연구자들에게 내주는 게 정말 괜찮은 걸까?)",
  ui_story_1013_10130101_238_dialog_content = "네 우려는 이해할 수 있다.",
  ui_story_1013_10130101_239_dialog_content = "그러니 내가 보증하지.",
  ui_story_1013_10130101_240_dialog_content = "일루미나는 결코 아이테르의 기술을 부당한 수단으로 이용하지 않을 것이다.",
  ui_story_1013_10130101_241_dialog_content = "게다가 상응하는 보수도 네게 지급하겠다.",
  ui_story_1013_10130101_242_dialog_content = "답례로 일루미나 최고 수준의 과학자를 파견해 스카이워커호의 복원을 돕겠다.",
  ui_story_1013_10130101_243_dialog_content = "......",
  ui_story_1013_10130101_244_dialog_content = "바이스, 넌 어떻게 생각해?",
  ui_story_1013_10130101_245_dialog_content = "내 의견?",
  ui_story_1013_10130101_246_dialog_content = "나도 물론 일루미나에 앞선 의료기술이 있었으면 좋겠다곤 생각해...",
  ui_story_1013_10130101_247_dialog_content = "하지만 PlayerName, 헤븐즈 밸리는 네 집이야.\n결정을 할 수 있는 건 오직 너뿐이야.",
  ui_story_1013_10130101_248_dialog_content = "그럼 PlayerName, 네 뜻은?",
  ui_story_1013_10130101_249_dialog_content = "어이, 잠깐 기다려 봐, 대원수.",
  ui_story_1013_10130101_250_dialog_content = "지금 당장 대답하라는 건 너무 급한 거 아냐?",
  ui_story_1013_10130101_251_dialog_content = "생각도 안 하고 결정할 수 있는 작은 일이 아니잖아.",
  ui_story_1013_10130101_252_dialog_content = "시간을 좀 줘. 이 녀석한테 잘 생각해보고 결정하라고 해.",
  ui_story_1013_10130101_253_dialog_content = "......",
  ui_story_1013_10130101_254_dialog_content = "미안하다, 내가 너무 조급했어.",
  ui_story_1013_10130101_255_dialog_content = "생각할 시간이 필요하다면 서두를 거 없다. 기다려줄 수 있으니까.",
  ui_story_1013_10130101_256_dialog_content = "전...",
  ui_story_1013_10130101_257_dialog_content = "괜찮아요.",
  ui_story_1013_10130101_258_option_content = "동의할게요.",
  ui_story_1013_10130101_259_dialog_content = "정말 다행이야. 고맙다, PlayerName.",
  ui_story_1013_10130101_260_option_content = "라인하르트 씨를 믿어요.",
  ui_story_1013_10130101_261_dialog_content = "......!",
  ui_story_1013_10130101_262_dialog_content = "고맙다, PlayerName.",
  ui_story_1013_10130101_263_dialog_content = "그럼 서두르는 게 좋겠군.\n지금 즉시 연구소 과학자들에게 연락해서 준비를 시키기로 하지.",
  ui_story_1013_10130101_264_dialog_content = "PlayerName, 바이스, 두 사람도 함께 가지.\n앞으로 너희 도움이 필요할 거다. 고생을 끼칠지도 모르겠군.",
  ui_story_1013_10130101_265_dialog_content = "괜찮아요. 일루미나에서 스카이워커를 고치는 걸 도와준다면, 서로 돕는 셈이니까요.",
  ui_story_1013_10130101_266_dialog_content = "일루미나를 위해서라면 그건 제 당연한 임무인걸요. 절대 마다하지 않을 거예요.",
  ui_story_1013_10130101_267_dialog_content = "아무래도 여기 내가 더 있을 필요는 없을 것 같군.",
  ui_story_1013_10130101_268_dialog_content = "그럼 난 제2군단으로 돌아가 볼까.",
  ui_story_1013_10130101_269_dialog_content = "애송이, 다음에 또 체스나 한판 두자고.",
  ui_story_1013_10130101_270_dialog_content = "네, 좋아요!",
  ui_story_1013_10130201_1_dialog_content = "여기가 일루미나 연구소의 사무 구역이다.",
  ui_story_1013_10130201_2_dialog_content = "두 사람은 처음이겠지?",
  ui_story_1013_10130201_3_dialog_content = "마, 맞아요!",
  ui_story_1013_10130201_4_dialog_content = "전부터 계속 들었어요. 연구소에는 일루미나 연방에서 가장 우수한\n과학자들이 모여 있다고 말이에요.",
  ui_story_1013_10130201_5_dialog_content = "오늘 직접 보게 될 줄은 몰랐네요!",
  ui_story_1013_10130201_6_dialog_content = "우와! 사람이 엄청 많네!",
  ui_story_1013_10130201_7_dialog_content = "당연하지. 여기 있는 모두가 일루미나를 위해 최선을 다하고 있다.",
  ui_story_1013_10130201_8_dialog_content = "그리고 저들의 노력이 지금의 일루미나를 이룩한 것이다.",
  ui_story_1013_10130201_9_dialog_content = "하이~ 대원수님! 그리고 바이스랑 우리 패배자잖아~",
  ui_story_1013_10130201_10_option_content = "그로누?!",
  ui_story_1013_10130201_11_dialog_content = "네가 왜 여기 있어?",
  ui_story_1013_10130201_12_dialog_content = "아까 대원수님이 나랑 미자드한테 실험을 도와달라고 했거든.\n스카이워커호의 신기능을 원하는 만큼 연구할 수 있다면서 말이야.",
  ui_story_1013_10130201_13_dialog_content = "스카이워커호의 연구라면 최고 난이도의 게임보다 훨씬 재미있을 거잖아.\n그래서 날아온 거야!",
  ui_story_1013_10130201_14_dialog_content = "제발 스카이워커를 상냥하게 대해줘...",
  ui_story_1013_10130201_15_dialog_content = "걱정 말라구. 제일 신중한 방법으로 스카이워커호를 연구해줄 테니까!",
  ui_story_1013_10130201_16_dialog_content = "젊은 친구, 오랜만이네.",
  ui_story_1013_10130201_17_dialog_content = "미자드 씨... 오랜만이야...",
  ui_story_1013_10130201_18_dialog_content = "(미자드 씨한테 악의는 없는 건 알지만, 매번 만날 때마다 나도 모르게 긴장된단 말이지...)",
  ui_story_1013_10130201_19_dialog_content = "응? 그 표정은 뭔데?",
  ui_story_1013_10130201_20_dialog_content = "오늘 아침 일루미나에 도착했을 때부터 계속 침울한 표정을 하고 있네.",
  ui_story_1013_10130201_21_dialog_content = "바이스의 몸에 문제가 생겼거든...",
  ui_story_1013_10130201_22_dialog_content = "어? 잠깐만. 오늘 방금 처음 만났는데 어떻게 그런 걸 알아?\n설마 마주쳤는데 내가 못 본 거야?",
  ui_story_1013_10130201_23_dialog_content = "후후, 잊으면 곤란해. 내 성큰 스파인은 언제나 일루미나의 구석구석을 바라보고 있거든.",
  ui_story_1013_10130201_24_dialog_content = "그 자리에 없어도 난 널 볼 수 있어.",
  ui_story_1013_10130201_25_dialog_content = "그, 그렇구나...",
  ui_story_1013_10130201_26_dialog_content = "자, 자, 얼른 가자. 연구소 사람들이 다들 애타게 기다리고 있다구!",
  ui_story_1013_10130201_27_dialog_content = "PlayerName, 가자!",
  ui_story_1013_10130201_28_dialog_content = "여러분! 드디어 왔어! PlayerName!",
  ui_story_1013_10130201_29_dialog_content = "그 사람이 바로 그 전설의 PlayerName? 전부터 자주 들었어요!",
  ui_story_1013_10130201_30_dialog_content = "꽤 젊어 보이는군. 그래도 실험체로는 어떻게든 합격이지만.",
  ui_story_1013_10130201_31_dialog_content = "실험체?!",
  ui_story_1013_10130201_32_dialog_content = "PlayerName 얘는 제 동료예요. 실험체 같은 게 아니라구요!",
  ui_story_1013_10130201_33_dialog_content = "하하, 신경 쓰지 마라. 이곳의 연구원들은 전부 이상한 습관이 있어서 말이지.",
  ui_story_1013_10130201_34_dialog_content = "저들에게 악의는 없다, 안심해라.",
  ui_story_1013_10130201_35_dialog_content = "대원수님, 지시하신 대로 연구소의 준비를 마쳤습니다.\n언제든지 연구를 시작할 수 있습니다.",
  ui_story_1013_10130201_36_dialog_content = "좋다. 그 전에 해야 할 일이 하나 있다.",
  ui_story_1013_10130201_37_dialog_content = "어떤 일이죠?",
  ui_story_1013_10130201_38_dialog_content = "네게 감사의 뜻을 표하는 일이다.",
  ui_story_1013_10130201_39_dialog_content = "네?",
  ui_story_1013_10130201_40_dialog_content = "감사는 아까 이미 했잖아요?",
  ui_story_1013_10130201_41_dialog_content = "아까는 나 개인으로서의 감사일 뿐, 이번에는 일루미나 연방 대원수로서의 감사다.",
  ui_story_1013_10130201_42_dialog_content = "네가 일루미나에 연구 권한을 줌으로써, 앞으로 수많은 오로리안이 구원을 받을 것이다.",
  ui_story_1013_10130201_43_dialog_content = "고마워, PlayerName!",
  ui_story_1013_10130201_44_dialog_content = "업무량이 늘어나긴 했지만, 그래도 고마워, 젊은 친구.",
  ui_story_1013_10130201_45_dialog_content = "고, 고마워요!",
  ui_story_1013_10130201_46_dialog_content = "자네의 공헌에 감사하겠네, 실험체 군.",
  ui_story_1013_10130201_47_dialog_content = "나 아직 아무것도 안 했는데?!",
  ui_story_1013_10130201_48_dialog_content = "괜찮아. 모두의 마음을 받아줘.",
  ui_story_1013_10130201_49_dialog_content = "이 모든 게 네가 동의해 준 덕분이니까.",
  ui_story_1013_10130201_50_dialog_content = "응...",
  ui_story_1013_10130201_51_dialog_content = "다들 나만 너무 쳐다보니까 좀 민망하네...",
  ui_story_1013_10130201_52_dialog_content = "이제 연구를 시작해야 하는 거 아냐?",
  ui_story_1013_10130201_53_dialog_content = "하하하하, 그것도 그렇군.",
  ui_story_1013_10130201_54_dialog_content = "그럼 계획대로 연구를 시작하지.",
  ui_story_1013_10130201_55_dialog_content = "네.",
  ui_story_1013_10130201_56_dialog_content = "대원수님의 지시에 따라 세 팀으로 나뉘자.",
  ui_story_1013_10130201_57_dialog_content = "A팀은 귀환의 탑으로 이동해 화음 연결 장치의 정보를 수집해.",
  ui_story_1013_10130201_58_dialog_content = "B팀은 날 따라와. 스카이워커호의 의료 시스템에 관한 데이터를 모으자.",
  ui_story_1013_10130201_59_dialog_content = "좋아. 그럼 나머지 C팀은 내 지시에 따라줘.\n데이터 전송 케이블을 스카이워커호의 시뮬레이션 룸에 연결하는 거야.",
  ui_story_1013_10130201_60_dialog_content = "일루미나의 전투 시뮬레이터에서 시뮬레이션 룸의 데이터를 해석할 수 있는지 시험해 보자.",
  ui_story_1013_10130201_61_dialog_content = "예!",
  ui_story_1013_10130201_62_dialog_content = "일루미나에 전투 시뮬레이터도 있나요?",
  ui_story_1013_10130201_63_dialog_content = "그래. 지난번 스카이워커호에 시뮬레이션 룸을 설치했을 때\n그로누가 일부 연구용 데이터를 가지고 왔었지.",
  ui_story_1013_10130201_64_dialog_content = "일루미나로 돌아온 뒤 스카이워커호의 시뮬레이션 룸을 따라 비슷한 기계를 만든 거다.",
  ui_story_1013_10130201_65_dialog_content = "비록 처음 목적은 게임기를 만들고 싶었을 뿐인 것 같다만...",
  ui_story_1013_10130201_66_dialog_content = "그래도 결과적으로는 멋진 물건을 만들어 냈지!",
  ui_story_1013_10130201_67_dialog_content = "그렇게 대단한 건가요?!",
  ui_story_1013_10130201_68_dialog_content = "그렇다! 너도 흥미가 있다면 다음에 직접 실험해 보는 것도 좋을 거다.",
  ui_story_1013_10130201_69_dialog_content = "좋아요, 물론 해봐야죠!",
  ui_story_1013_10130201_70_dialog_content = "미리 연습해서 그로누한테 제가 패배자가 아니라는 걸 보여주겠어요!",
  ui_story_1013_10130201_71_dialog_content = "<color=#e8d9bb>몇 시간 후</color>",
  ui_story_1013_10130201_72_dialog_content = "보고드리겠습니다, 대원수님.",
  ui_story_1013_10130201_73_dialog_content = "뭔가 발견한 게 있나?",
  ui_story_1013_10130201_74_dialog_content = "좋은 소식입니다. 스카이워커호 내부에서 새로운 모듈을 발견했습니다.\n안에는 의료 장치의 제작법이 들어 있었습니다.",
  ui_story_1013_10130201_75_dialog_content = "그 데이터를 이용하면 메디컬 센터의 설비를 개선할 수 있을 겁니다.",
  ui_story_1013_10130201_76_dialog_content = "그거 정말 잘됐군!",
  ui_story_1013_10130201_77_dialog_content = "연구를 계속 이어가라. 뭔가 새로운 발견을 더 할 수 있을지 보자고.",
  ui_story_1013_10130201_78_dialog_content = "네.",
  ui_story_1013_10130201_79_dialog_content = "의료 장치라...",
  ui_story_1013_10130201_80_dialog_content = "아까 자오라는 사람을 만났는데, 몸이 많이 힘들어 보였어요.",
  ui_story_1013_10130201_81_dialog_content = "만약 의료 장치를 업그레이드하면 자오 씨의 병도 고칠 수 있을까요?",
  ui_story_1013_10130201_82_dialog_content = "호오? 자오를 알고 있나?",
  ui_story_1013_10130201_83_dialog_content = "아, 네. 아까 메디컬 센터에서 우연히 만나서 이제 막 알게 됐어요.",
  ui_story_1013_10130201_84_dialog_content = "그랬군.",
  ui_story_1013_10130201_85_dialog_content = "자오는 더스크 타운 일루미나 주둔군의 참모장이다.\n뛰어난 두뇌를 가지고 있지만 몸이 많이 약해서 말이야.",
  ui_story_1013_10130201_86_dialog_content = "예전에 중상을 입은 것이 원인이다.\n그때 장기가 다크매터에 침식된 탓에 싸울 수 없게 되었지.",
  ui_story_1013_10130201_87_dialog_content = "그래서 계속 힘들어 보였던 거군요.",
  ui_story_1013_10130201_88_dialog_content = "그뿐만이 아니다. 휘하에 있는 숀의 몸도 문제에 시달리고 있지.",
  ui_story_1013_10130201_89_dialog_content = "숀이요?! 그 애는 아주 건강해 보이던데요?",
  ui_story_1013_10130201_90_dialog_content = "그건 항상 자신을 단련하고 있기 때문이다.",
  ui_story_1013_10130201_91_dialog_content = "사실 그의 유전자에는 복잡한 결함이 있거든.",
  ui_story_1013_10130201_92_dialog_content = "때문에 처음 입대했을 때는 그리 주목받지 못했고,\n멀리 떨어진 주둔지로 보내져 하급 병사가 될 수밖에 없었지.",
  ui_story_1013_10130201_93_dialog_content = "그 아이가 지금의 성과를 이룬 건 모두 그 불굴의 정신 덕분이다.",
  ui_story_1013_10130201_94_dialog_content = "그러게요. 저도 숀한테서 오랜 시간 전장에서 단련된 사람의 기운을 느꼈어요.",
  ui_story_1013_10130201_95_dialog_content = "그렇다. 그러니 의료 장치가 개선되고 나면,\n저들 같은 사람들이 가장 먼저 그 혜택을 보게 될 거다.",
  ui_story_1013_10130201_96_dialog_content = "대원수님, 화음 연결 장치의 연구에 진전이 있었습니다.",
  ui_story_1013_10130201_97_dialog_content = "버, 벌써?!",
  ui_story_1013_10130201_98_dialog_content = "일루미나의 기술 수준을 무시해선 곤란하네, 실험체 군.",
  ui_story_1013_10130201_99_dialog_content = "그럼 본론으로 돌아와서, 저희는 이제 대원수님께 화음 연결 장치에 대해 보고하려고 합니다만...",
  ui_story_1013_10130201_100_dialog_content = "(음? 지금 날 힐끔 쳐다본 거야?)",
  ui_story_1013_10130201_101_dialog_content = "아이테르는 헤븐즈 밸리의 주인이자 화음 연결 장치의 주인이다.",
  ui_story_1013_10130201_102_dialog_content = "그 기술에 대한 연구를 PlayerName에게 말하지 못할 이유는 없다.",
  ui_story_1013_10130201_103_dialog_content = "예. 그럼 실험체 군도 이해할 수 있는 방식으로 간단히 설명하겠습니다.",
  ui_story_1013_10130201_104_dialog_content = "바튼 군단장과 바이스 중위의 신체 검사 결과를 토대로,\n저희는 이미 그 장치의 용도가 무엇인지에 대해 초보적인 추론을 해냈습니다.",
  ui_story_1013_10130201_105_dialog_content = "저희는 화음 연결 장치가 오로리안의 신체를 개조할 수 있는 것 외에,\n오로리안의 잠재 능력을 끌어낼 수도 있지 않을까 추측하고 있습니다.",
  ui_story_1013_10130201_106_option_content = "신체 개조요?",
  ui_story_1013_10130201_107_dialog_content = "자넨 못 알아챘나? 바튼 군단장과 바이스 중위의 외모에 다소 변화가 발생했을 텐데.",
  ui_story_1013_10130201_108_dialog_content = "그건 알아요. 근데 겉모습 말고는요? 개조가 신체에 뭔가 다른 영향을 줬나요?",
  ui_story_1013_10130201_109_dialog_content = "그건 조금 더 연구해 봐야 결론을 도출할 수 있을 듯하군.",
  ui_story_1013_10130201_110_dialog_content = "다만 한 가지 확신할 수 있는 건 이러한 변화가 저들의 루미나틱스에 영향을 준다는 점이다.",
  ui_story_1013_10130201_111_option_content = "잠재 능력이요?",
  ui_story_1013_10130201_112_dialog_content = "그렇다. 화음 연결 장치는 두 사람의 신체를 개조했고,\n그로 인해 루미나틱스 사용법에도 변화가 일어난 거다.",
  ui_story_1013_10130201_113_dialog_content = "원래는 사용할 수 없거나 사용하기 어려웠던 막강한 힘을 사용할 수 있게 된 것이지.",
  ui_story_1013_10130201_114_dialog_content = "그걸 설명하려면 루미나틱스의 원리부터 이야기를 시작해야겠군.",
  ui_story_1013_10130201_115_dialog_content = "실험체 군을 위해서라면 하루 종일 루미나틱스에 대한 각종 지식을 이야기해 줄 수도 있네.",
  ui_story_1013_10130201_116_dialog_content = "으엑... 그, 그건 됐어요.",
  ui_story_1013_10130201_117_dialog_content = "실험체 군, 그렇게 걱정할 것 없네.",
  ui_story_1013_10130201_118_dialog_content = "화음 연결 장치를 사용했더라도 두 사람은 전과 마찬가지로\n원래의 루미나틱스를 사용할 능력을 유지하고 있으니까.",
  ui_story_1013_10130201_119_dialog_content = "따라서 우린 저들에게 본질적인 변화가 있었다고 보진 않는다.",
  ui_story_1013_10130201_120_dialog_content = "그런가요...",
  ui_story_1013_10130201_121_dialog_content = "뭔가 심각한 얘기를 하는 모양이네?",
  ui_story_1013_10130201_122_dialog_content = "그로누, 손에 들고 있는 건 전투 시뮬레이터 헬멧 아닌가?",
  ui_story_1013_10130201_123_dialog_content = "뭔가 진전이 있었나?",
  ui_story_1013_10130201_124_dialog_content = "네!",
  ui_story_1013_10130201_125_dialog_content = "전투 시뮬레이터에서 스카이워커호의 데이터베이스에 접속했어요.",
  ui_story_1013_10130201_126_dialog_content = "그리고 방금 연구 도중에 왠지 스카이워커호의 새 부품 속 어떤 기능을 발동시킨 것 같아요.",
  ui_story_1013_10130201_127_dialog_content = "시뮬레이션 룸이 마치 셀프 업그레이드를 진행한 것처럼,\n진짜 전장의 상황을 완전히 구현할 수 있게 됐어요!",
  ui_story_1013_10130201_128_dialog_content = "전투 시뮬레이터를 사용하면 지금 바로 체험해 볼 수 있어요.",
  ui_story_1013_10130201_129_dialog_content = "PlayerName, 아까 전투 시뮬레이터에 관심이 있다고 했지?",
  ui_story_1013_10130201_130_dialog_content = "어때? 해 볼래?",
  ui_story_1013_10130201_131_option_content = "어려워?",
  ui_story_1013_10130201_132_dialog_content = "내가 일부러 널 곤란하게 만들 리가 없잖아!\n신작 게임이라면 당연히 가장 쉬운 난이도부터 시작이지!",
  ui_story_1013_10130201_133_dialog_content = "그럼 해 볼래!",
  ui_story_1013_10130201_134_option_content = "당연하지!",
  ui_story_1013_10130201_135_dialog_content = "재미있을 것 같아!",
  ui_story_1013_10130201_136_dialog_content = "그럼 PlayerName, 거기 의자에 앉아서 이 헬멧을 써!",
  ui_story_1013_10130201_137_dialog_content = "응.",
  ui_story_1013_10130201_138_dialog_content = "어? 주변 환경이 달라졌잖아?!",
  ui_story_1013_10130201_139_dialog_content = "PlayerName, 들려?",
  ui_story_1013_10130201_140_dialog_content = "바이스?! 너 어디 있어?",
  ui_story_1013_10130201_141_dialog_content = "네 바로 옆에 있어!",
  ui_story_1013_10130201_142_dialog_content = "여기 모니터로 네가 보는 화면을 볼 수 있어.",
  ui_story_1013_10130201_143_dialog_content = "어떠냐, PlayerName, 뭐가 보이지?",
  ui_story_1013_10130201_144_dialog_content = "아무것도 없는 넓은 황야요.\n그리고 기분 좋은 햇살이 비추고, 선선한 바람이 불고 있어요.",
  ui_story_1013_10130201_145_dialog_content = "그럼 성공이야.",
  ui_story_1013_10130201_146_dialog_content = "지금 보이는 장면은 전투 시뮬레이터의 초기 화면이야.",
  ui_story_1013_10130201_147_dialog_content = "PlayerName, 이번엔 동료가 옆에 있는 모습을 상상해 봐!",
  ui_story_1013_10130201_148_dialog_content = "동료의 모습을 상상하라고?",
  ui_story_1013_10130201_149_dialog_content = "그래!",
  ui_story_1013_10130201_150_dialog_content = "전투 시뮬레이터는 네가 상상한 내용을 토대로 일루미나가 가진 데이터를 사용해서,\n대응하는 오로리안을 환경에 투영할 수 있어.",
  ui_story_1013_10130201_151_dialog_content = "그렇게 투영된 오로리안의 홀로그램이 이제부터 진행할 네 전투 테스트를 도와줄 거야.",
  ui_story_1013_10130201_152_option_content = "[바이스의 모습을 상상한다]",
  ui_story_1013_10130201_153_dialog_content = "우앗?!",
  ui_story_1013_10130201_154_dialog_content = "나, 나왔어!",
  ui_story_1013_10130201_155_dialog_content = "대단해... 진짜 나랑 똑같잖아!",
  ui_story_1013_10130201_156_dialog_content = "좋아! 그럼 딱히 문제는 없는 모양이네.",
  ui_story_1013_10130201_157_dialog_content = "그럼 내가 암귀를 투입시킬게──",
  ui_story_1013_10130201_158_dialog_content = "캬아악!",
  ui_story_1013_10130201_159_dialog_content = "흐익! 암귀까지 진짜랑 똑같잖아...",
  ui_story_1013_10130201_160_dialog_content = "왠지 다크매터까지 느껴지는 것 같아!",
  ui_story_1013_10130201_161_dialog_content = "무서워하지 않아도 돼, PlayerName.",
  ui_story_1013_10130201_162_dialog_content = "제일 기본적인 테스트일 뿐이니까!",
  ui_story_1013_10130201_163_dialog_content = "오로리안 홀로그램을 지휘해서 암귀들을 물리쳐!",
  ui_story_1013_10130201_164_dialog_content = "힘내, PlayerName!",
  ui_story_1013_10130201_165_dialog_content = "응, 열심히 할게!",
  ui_story_1013_10130201_166_dialog_content = "선택 난이도: 쉬움.",
  ui_story_1013_10130201_167_dialog_content = "기본 모드, 스테이지 번호: 01.",
  ui_story_1013_10130201_168_dialog_content = "스테이지 목표: 모든 암귀 처치.",
  ui_story_1013_10130201_169_dialog_content = "전투 시뮬레이터, 스테이지를 시작합니다.",
  ui_story_1013_10130201_170_dialog_content = "<anim type=Shake><size=50>크오오!</size></anim>",
  ui_story_1013_10130302_1_dialog_content = "후, 휴우... 암귀를 다 쓰러트렸어!",
  ui_story_1013_10130302_2_dialog_content = "스테이지 목표를 달성했습니다.",
  ui_story_1013_10130302_3_dialog_content = "테스트 종료, 스테이지 평점은 A입니다.",
  ui_story_1013_10130302_4_dialog_content = "대단하네, PlayerName! 전투 시뮬레이터를 처음 쓰면서 A라니!",
  ui_story_1013_10130302_5_dialog_content = "잠깐만 기다려. 일단 시뮬레이터와의 연결부터 끊을게. 그럼 헬멧을 벗어도 괜찮아.",
  ui_story_1013_10130302_6_dialog_content = "연결이 해제되었습니다. 안전하게 로그아웃할 수 있습니다.",
  ui_story_1013_10130302_7_dialog_content = "음...",
  ui_story_1013_10130302_8_dialog_content = "PlayerName, 어땠어? 어디 불편한 데 있어?",
  ui_story_1013_10130302_9_dialog_content = "괜찮아. 근데 진짜로 암귀랑 싸운 느낌이라 몸도 정신도 지친 것 같아.",
  ui_story_1013_10130302_10_dialog_content = "하하하, 고생 많았다, PlayerName.",
  ui_story_1013_10130302_11_dialog_content = "하지만 이로써 이 기술의 이점이 확실히 증명됐다.",
  ui_story_1013_10130302_12_dialog_content = "스카이워커호의 시뮬레이션 룸 기능을 일부 차용한 것만으로도\n실제 전장 상황을 완벽하게 재현할 수 있게 된 것이다.",
  ui_story_1013_10130302_13_dialog_content = "이론 학습과 워게임에만 머무르는 무미건조한 교육보다 훨씬 효과적이지!",
  ui_story_1013_10130302_14_dialog_content = "그 말을 들으니까 저도 해 보고 싶어졌어요!",
  ui_story_1013_10130302_15_dialog_content = "지금은 아직 안 돼.",
  ui_story_1013_10130302_16_dialog_content = "이건 아이테르의 기술이니까, 지금은 PlayerName밖에 테스트할 수 없어.",
  ui_story_1013_10130302_17_dialog_content = "나중에 우리가 이 기술의 원리를 완전히 해석하게 되면,\n오로리안도 사용할 수 있도록 개조할 수 있을 거야!",
  ui_story_1013_10130302_18_dialog_content = "지금 전투 시뮬레이터 연구를 최우선 임무로 삼는다면, 연합 훈련 전까지 가능하겠어?",
  ui_story_1013_10130302_19_dialog_content = "이 기술을 훈련에 사용할 수 있다면, 더 많은 사람을 참가시킬 수 있을 것이다!",
  ui_story_1013_10130302_20_dialog_content = "PlayerName의 도움을 받는다면 아마 문제 없을 거예요!",
  ui_story_1013_10130302_21_dialog_content = "연합 훈련? 그게 뭐죠?",
  ui_story_1013_10130302_22_dialog_content = "2년에 한 번 개최되는 훈련 얘기야!",
  ui_story_1013_10130302_23_dialog_content = "연합 훈련은 일루미나 연방뿐만 아니라 백야성이나 북방,\n움브라톤까지 참여하는 훈련이야.",
  ui_story_1013_10130302_24_dialog_content = "단순히 군대 간 협력에서 그치는 게 아니라, 각 세력의 가장 우수한 청년들이\n개인 종목에서 실력을 겨루게 돼.",
  ui_story_1013_10130302_25_dialog_content = "그리고 훈련의 마지막엔 참가자들이 진짜 전장에 나서서 암귀와 싸워.",
  ui_story_1013_10130302_26_dialog_content = "꽤 많이들 참가할 것 같네...",
  ui_story_1013_10130302_27_dialog_content = "당연하지!",
  ui_story_1013_10130302_28_dialog_content = "모두가 개인 종목 우승을 목표로 노력할 거야.",
  ui_story_1013_10130302_29_dialog_content = "왜냐면 승자는 대원수님과 일대일 대련을 할 수 있거든!",
  ui_story_1013_10130302_30_dialog_content = "뭐?!",
  ui_story_1013_10130302_31_dialog_content = "처음엔 그저 즉흥적으로 당시 우승자에게 한번 겨뤄보지 않겠냐고 물었을 뿐이었지.",
  ui_story_1013_10130302_32_dialog_content = "그러다 보니 어느새 관례가 되어버린 것 같다.",
  ui_story_1013_10130302_33_dialog_content = "하지만 그런 대련이라면 나도 싫어하지 않는다.",
  ui_story_1013_10130302_34_option_content = "그래도 좀 번거롭지 않나요?",
  ui_story_1013_10130302_35_dialog_content = "그럴 리가! 오히려 무척 기대하고 있다!",
  ui_story_1013_10130302_36_option_content = "역시 라인하르트 씨답네요.",
  ui_story_1013_10130302_37_dialog_content = "하하하, 칭찬 고맙다.",
  ui_story_1013_10130302_38_dialog_content = "최강의 젊은이와 싸울 기회가 있다는 건 내게도 즐거운 일이지.",
  ui_story_1013_10130302_39_dialog_content = "젊은 세대가 성장하고, 조금씩 강해지면서...",
  ui_story_1013_10130302_40_dialog_content = "마지막에는 우리를 넘어 새로운 시대를 이끌어가는 자가 되는 모습을 볼 수 있으니 말이야.",
  ui_story_1013_10130302_41_dialog_content = "생각만 해도 감격을 금할 수 없는 일이지.",
  ui_story_1013_10130302_42_dialog_content = "그럼 라인하르트 씨는 전부 어떤 사람들이랑 겨뤄봤는데요?",
  ui_story_1013_10130302_43_dialog_content = "개인 종목 우승자라면 지난번엔 카렌이었어!",
  ui_story_1013_10130302_44_dialog_content = "카렌은 2위보다 10포인트 이상 득점에서 앞섰다니까!",
  ui_story_1013_10130302_45_dialog_content = "음, 카렌은 확실히 젊은 세대 중에서도 드문 강자다.",
  ui_story_1013_10130302_46_dialog_content = "지난번 대련 후 그녀는 다음에도 개인 종목에서 우승하겠다고 했었지.",
  ui_story_1013_10130302_47_dialog_content = "그리고 그땐 날 쓰러트릴 만큼 강해지겠다고 했었다.",
  ui_story_1013_10130302_48_dialog_content = "하하하, 정말 기대되는군.",
  ui_story_1013_10130302_49_dialog_content = "정말 부럽네요...",
  ui_story_1013_10130302_50_dialog_content = "저도 대원수님과 겨룬다면 분명히 많은 지도를 받을 수 있을 텐데 말이에요!",
  ui_story_1013_10130302_51_dialog_content = "그럼 단련에 힘써서 개인 종목에서 우승해 봐라.",
  ui_story_1013_10130302_52_dialog_content = "네!",
  ui_story_1013_10130302_53_dialog_content = "너도 마찬가지다, PlayerName!",
  ui_story_1013_10130302_54_dialog_content = "저도요?!",
  ui_story_1013_10130302_55_dialog_content = "물론 연합 훈련에 참가할 수 있는 건 오로리안만이 아니다.",
  ui_story_1013_10130302_56_dialog_content = "아이테르가 아직 아스트라 대륙에서 활약하고 있던 시절엔,\n그들도 오로리안과 함께 싸워왔다.",
  ui_story_1013_10130302_57_dialog_content = "만약 네가 참가한다면, 연합 훈련에 있어서는 아이테르의 귀환인 셈이 되겠지.",
  ui_story_1013_10130302_58_dialog_content = "「귀환」인가요...",
  ui_story_1013_10130302_59_dialog_content = "물론 네가 우승하면 내가 너와 대련을 해 줄 거다.",
  ui_story_1013_10130302_60_dialog_content = "그, 그건 사양할게요!",
  ui_story_1013_10130302_61_dialog_content = "<size=33>라인하르트 씨랑 겨루면 도망칠 기회조차 없이 끝장일 거잖아요...</size>",
  ui_story_1013_10130302_62_dialog_content = "그럼 체스는 어떤가?",
  ui_story_1013_10130302_63_dialog_content = "체스라면 문제없죠!",
  ui_story_1013_10130302_64_dialog_content = "좋아, 그럼 네가 개인 종목에서 우승하길 기다리겠다!",
  ui_story_1013_10130302_65_dialog_content = "대화 중에 잠깐 실례할게요.",
  ui_story_1013_10130302_66_dialog_content = "오늘 테스트는 다 끝났어요!",
  ui_story_1013_10130302_67_dialog_content = "저랑 제 조수가 지금 테스트 결과를 바탕으로 전투 시뮬레이터를 조정하고 있어요.\n아마 내일이면 다음 테스트를 할 수 있을 거예요.",
  ui_story_1013_10130302_68_dialog_content = "나머지 일은 안심하고 저희한테 맡겨 주세요!",
  ui_story_1013_10130302_69_dialog_content = "다음 테스트가 또 필요해?",
  ui_story_1013_10130302_70_dialog_content = "당연하지. 오늘 건 기본적인 테스트일 뿐이야.",
  ui_story_1013_10130302_71_dialog_content = "전투 시뮬레이터에는 아직도 개발해야 할 기능이 잔뜩 있다구!",
  ui_story_1013_10130302_72_dialog_content = "근데 그럼 스카이워커를 고치는 건...",
  ui_story_1013_10130302_73_dialog_content = "걱정 마세요. 잊어버리진 않으니까요.",
  ui_story_1013_10130302_74_dialog_content = "스카이워커호 수리와 전투 시뮬레이터 연구는 동시 진행 중이에요!",
  ui_story_1013_10130302_75_dialog_content = "다만, 아무리 저희들이라도 시간이 좀 걸려요.",
  ui_story_1013_10130302_76_dialog_content = "그러니까 참을성 있게 기다리면서 푹 쉬고 있어요.",
  ui_story_1013_10130302_77_dialog_content = "그럼 기다리는 수밖에 없겠네.",
  ui_story_1013_10130302_78_dialog_content = "응, PlayerName도 오늘은 일단 푹 쉬어.",
  ui_story_1013_10130302_79_dialog_content = "나머지는 내일 계속하자!",
  ui_story_1013_10130401_1_dialog_content = "<color=#e8d9bb>꼬륵──</color>",
  ui_story_1013_10130401_2_dialog_content = "배고프네...",
  ui_story_1013_10130401_3_dialog_content = "<color=#e8d9bb>꼬르륵──</color>",
  ui_story_1013_10130401_4_dialog_content = "배고파!",
  ui_story_1013_10130401_5_dialog_content = "어제 연구소에서 테스트를 마치고 바이스를 따라 자난성에서 묵게 됐는데...",
  ui_story_1013_10130401_6_dialog_content = "눈을 떴더니 벌써 시간이 이렇게 됐잖아?!",
  ui_story_1013_10130401_7_dialog_content = "<color=#e8d9bb>꼬르르륵...</color>",
  ui_story_1013_10130401_8_dialog_content = "안 되겠어. 일단 뭐라도 좀 먹어야겠어.",
  ui_story_1013_10130401_9_dialog_content = "자난성은 이렇게 큰데 식당 정도는 있겠지?",
  ui_story_1013_10130401_10_dialog_content = "너무 안 비쌌으면 좋겠네. 지갑에 나이티움도 얼마 없으니까...",
  ui_story_1013_10130401_11_dialog_content = "없어.",
  ui_story_1013_10130401_12_dialog_content = "여기도 없어?",
  ui_story_1013_10130401_13_dialog_content = "왜 어디에도 없는 건데?!",
  ui_story_1013_10130401_14_dialog_content = "한 바퀴 돌았는데 음식점이 하나도 없잖아. 오히려 더 배고파졌어...",
  ui_story_1013_10130401_15_dialog_content = "슬슬 눈앞이 캄캄해진다...",
  ui_story_1013_10130401_16_dialog_content = "어라... 음식 냄새인가?",
  ui_story_1013_10130401_17_dialog_content = "PlayerName?!",
  ui_story_1013_10130401_18_dialog_content = "일어나, PlayerName! 이런 데서 자면 안 돼!",
  ui_story_1013_10130401_19_option_content = "바, 바이스?!",
  ui_story_1013_10130401_20_dialog_content = "괜찮아? 기운이 없는 것 같은데 무슨 일이야?",
  ui_story_1013_10130401_21_dialog_content = "아무것도 아니야. 배고파서 음식점을 찾고 있었는데 못 찾아서...",
  ui_story_1013_10130401_22_dialog_content = "자난성을 한 바퀴 돌았는데 결국 여기로 돌아올 수밖에 없었어.",
  ui_story_1013_10130401_23_dialog_content = "미안 미안, 말하는 걸 깜빡했네...",
  ui_story_1013_10130401_24_dialog_content = "일루미나는 배급제라서 자난성에는 레스토랑 같은 곳이 없어.",
  ui_story_1013_10130401_25_dialog_content = "다른 곳에서 온 사람이 물자를 받으려면 지정 장소에서 수속을 밟아야 해.",
  ui_story_1013_10130401_26_dialog_content = "어제는 다들 연구하느라 바빠서 신청하는 걸 잊어버렸지 뭐야...",
  ui_story_1013_10130401_27_dialog_content = "비비안 님이 너 대신 앞으로의 배급을 준비해 주셨으니까,\n오늘 업무가 끝나면 같이 가지러 가자!",
  ui_story_1013_10130401_28_dialog_content = "뭐? 그렇게 번거롭단 말이야?",
  ui_story_1013_10130401_29_dialog_content = "일루미나 연방의 생산력에는 한계가 있거든.\n모두가 식사에 어려움을 겪지 않는 것만으로도 쉬운 일이 아니야.",
  ui_story_1013_10130401_30_dialog_content = "배급제를 사용하고 있는 것도 낭비를 최대한 없애서\n모두에게 충분한 자원이 돌아갈 수 있도록 하기 위해서야.",
  ui_story_1013_10130401_31_dialog_content = "아무튼 네 아침은 내가 챙겨왔어!",
  ui_story_1013_10130401_32_dialog_content = "짜잔──",
  ui_story_1013_10130401_33_dialog_content = "역시 음식 냄새였구나!",
  ui_story_1013_10130401_34_dialog_content = "배고프지? 자, 얼른 먹어!",
  ui_story_1013_10130401_35_dialog_content = "이따가 또 연구소에 도와주러 가야 되니까!",
  ui_story_1013_10130401_36_dialog_content = "그럼 잘 먹을게!",
  ui_story_1013_10130401_37_dialog_content = "(일루미나는 엄청 강해 보였는데, 자원을 절약해야 한다니 의외네.)",
  ui_story_1013_10130401_38_dialog_content = "냠냠...",
  ui_story_1013_10130401_39_dialog_content = "아, 역시 배가 부르니까 살아있다는 느낌이 나네!",
  ui_story_1013_10130401_40_dialog_content = "그러게. 식사 시간이 제일 즐겁다니까!",
  ui_story_1013_10130401_41_dialog_content = "그럼 배도 부르니까, 그럼 오늘 일을 시작할까?",
  ui_story_1013_10130401_42_dialog_content = "오늘도 계속해서 전투 시뮬레이터 연구를 도와줘야 하는 거지?",
  ui_story_1013_10130401_43_dialog_content = "맞아. 과학자들 말로는 어제 밤을 새워서 새로운 기능을 개발했대!",
  ui_story_1013_10130401_44_dialog_content = "같이 보러 갈래?",
  ui_story_1013_10130401_45_dialog_content = "좋아!",
  ui_story_1013_10130401_46_dialog_content = "<color=#e8d9bb>일루미나 연구소</color>",
  ui_story_1013_10130401_47_dialog_content = "좋은 아침이다, 드디어 왔군.",
  ui_story_1013_10130401_48_dialog_content = "대원수님?!",
  ui_story_1013_10130401_49_dialog_content = "설마 우릴 계속 기다린 건가요?",
  ui_story_1013_10130401_50_dialog_content = "그렇다. 나도 내 눈으로 전투 시뮬레이터가 가동되는 과정을 보고 싶어서 말이지.",
  ui_story_1013_10130401_51_dialog_content = "헤에, 왔구나?",
  ui_story_1013_10130401_52_dialog_content = "저흰 벌써 전투 시뮬레이터를 업그레이드했어요!",
  ui_story_1013_10130401_53_dialog_content = "맞아 맞아. 이제는 이름도 새로 지었어! 전장 시뮬레이터라고 해!",
  ui_story_1013_10130401_54_option_content = "「전장」?",
  ui_story_1013_10130401_55_dialog_content = "한 글자 차이라고 무시하면 안 돼. 실제 변화는 엄청 크거든!",
  ui_story_1013_10130401_56_option_content = "뭐가 달라졌는데?",
  ui_story_1013_10130401_57_dialog_content = "엄청 달라졌어!",
  ui_story_1013_10130401_58_dialog_content = "전장 시뮬레이터는 스카이워커호의 새로운 모듈 속 데이터를 읽고 업데이트를 진행한 거야.",
  ui_story_1013_10130401_59_dialog_content = "이제 상세한 전투 기록을 가지고 과거의 실제 전투를 상세하게 시뮬레이션할 수 있어.",
  ui_story_1013_10130401_60_dialog_content = "적뿐만 아니라 전투 당시의 시간과 환경, 날씨까지 완벽하게 재현할 수 있다니까!",
  ui_story_1013_10130401_61_dialog_content = "어때? 굉장하지!",
  ui_story_1013_10130401_62_dialog_content = "그러니까 전투가 더 현실감있게 된다는 거지?",
  ui_story_1013_10130401_63_dialog_content = "이론적으로는 그래요.",
  ui_story_1013_10130401_64_dialog_content = "하지만 전장 시뮬레이터의 개조가 아직 끝난 게 아니라서,\n지금 테스트를 할 수 있는 사람은 여전히 당신뿐이에요.",
  ui_story_1013_10130401_65_dialog_content = "그러니까 오늘도 부탁할게!",
  ui_story_1013_10130401_66_dialog_content = "어제 전투만으로도 충분히 힘들었어. 오늘도 너무 어렵지 않았으면 좋겠는데.",
  ui_story_1013_10130401_67_dialog_content = "걱정 마. 우리가 쓸 건 전부 예전에 자세하게 기록된 전투 데이터야.",
  ui_story_1013_10130401_68_dialog_content = "네 능력이라면 분명히 순조롭게 클리어할 수 있을 거야!",
  ui_story_1013_10130401_69_dialog_content = "PlayerName, 힘내! 나도 여기서 네가 싸우는 모습을 지켜볼게!",
  ui_story_1013_10130401_70_dialog_content = "아, 알았어!",
  ui_story_1013_10130401_71_dialog_content = "어제처럼 일단 헬멧을 쓰고...",
  ui_story_1013_10130401_72_dialog_content = "어제랑 다를 게 없는 것 같은데?",
  ui_story_1013_10130401_73_dialog_content = "급할 거 없어. 지금 바로 전투 데이터를 입력할 거니까.",
  ui_story_1013_10130401_74_dialog_content = "음, 어떤 게 좋을까나?",
  ui_story_1013_10130401_75_dialog_content = "재미있군, 그럼 이걸로 하자고.",
  ui_story_1013_10130401_76_dialog_content = "에? 이, 이거요? 대원수님...",
  ui_story_1013_10130401_77_dialog_content = "조금 무리가 아닐까요...",
  ui_story_1013_10130401_78_dialog_content = "걱정할 것 없다. PlayerName의 능력 범위 안이다.",
  ui_story_1013_10130401_79_dialog_content = "게다가 그는 이런 종류의 전투에도 경험이 있다. 그를 믿어라.",
  ui_story_1013_10130401_80_dialog_content = "네!",
  ui_story_1013_10130401_81_dialog_content = "자, 잠깐만요, 라인하르트 씨!",
  ui_story_1013_10130401_82_dialog_content = "뭘 고른 건데요?!",
  ui_story_1013_10130401_83_dialog_content = "시작하면 알게 될 거다.",
  ui_story_1013_10130401_84_dialog_content = "전투 기록을 읽고 있습니다.",
  ui_story_1013_10130401_85_dialog_content = "「그림자 전투」 데이터를 읽었습니다.",
  ui_story_1013_10130401_86_dialog_content = "앗! 주변 환경이 진짜로 어둠의 밑바닥 같아졌어!",
  ui_story_1013_10130401_87_dialog_content = "으윽... 심지어 이 답답한 다크매터까지 그대로 재현했잖아.",
  ui_story_1013_10130401_88_dialog_content = "PlayerName, 어떤가?",
  ui_story_1013_10130401_89_dialog_content = "진짜랑 너무 똑같잖아요!",
  ui_story_1013_10130401_90_dialog_content = "이 정도면 고증이 너무 심한 거 아니에요?!",
  ui_story_1013_10130401_91_dialog_content = "정말로 거기서 싸우고 있는 느낌이에요. 그 다크매터의 불쾌감까지 똑같아요!",
  ui_story_1013_10130401_92_dialog_content = "그런가? 아주 좋다.",
  ui_story_1013_10130401_93_option_content = "어디가 좋은데요?!",
  ui_story_1013_10130401_94_dialog_content = "그렇게까지 현실적인 환경을 만들어 낼 수 있다는 것은,\n그만큼 이 전장 시뮬레이터의 성능이 좋다는 것이겠지.",
  ui_story_1013_10130401_95_dialog_content = "사용자에게 전장의 어려움과 잔혹함을 몸소 느낄 수 있도록 한다면,\n사람들은 더 현실적인 전투 체험을 할 수 있을 것이다.",
  ui_story_1013_10130401_96_dialog_content = "그렇게 전장을 숙지하고, 복잡한 환경 속에서 자신의 기술과 전략을 단련해 나간다.",
  ui_story_1013_10130401_97_dialog_content = "그럼 저들이 실제로 전선에 섰을 때도 사상자를 줄일 수 있겠지.",
  ui_story_1013_10130401_98_dialog_content = "확실히 그렇네요...",
  ui_story_1013_10130401_99_dialog_content = "그럼 네가 첫 번째 체험자로서 마음껏 싸우고, 시스템의 각 기능을 테스트해 주길 바란다!",
  ui_story_1013_10130401_100_dialog_content = "네, 알겠어요.",
  ui_story_1013_10130401_101_dialog_content = "그럼 전투 시작이야, 준비해, PlayerName.",
  ui_story_1013_10130401_102_dialog_content = "전장 시뮬레이션 모드, 스테이지 번호: 11328.",
  ui_story_1013_10130401_103_dialog_content = "스테이지 목표: 암귀의 포위를 돌파하거나 모든 암귀 처치.",
  ui_story_1013_10130401_104_dialog_content = "전장 시뮬레이터, 스테이지를 시작합니다.",
  ui_story_1013_10130401_105_dialog_content = "크오오──!",
  ui_story_1013_10130401_106_dialog_content = "얼마든지 오라고!",
  ui_story_1013_10130502_1_dialog_content = "후방으로 물러나서 암석을 엄폐물로 삼자!",
  ui_story_1013_10130502_2_dialog_content = "......",
  ui_story_1013_10130502_3_dialog_content = "캬오──!",
  ui_story_1013_10130502_4_dialog_content = "크오오!",
  ui_story_1013_10130502_5_dialog_content = "왜 이렇게 많아?!",
  ui_story_1013_10130502_6_dialog_content = "......!",
  ui_story_1013_10130502_7_dialog_content = "(이런... 또 공격에 맞으면 바이스는 움직일 수 없게 될 거야.)",
  ui_story_1013_10130502_8_dialog_content = "(어떡하지... 암귀가 너무 많아서 이제 물러설 곳도 없어...)",
  ui_story_1013_10130502_9_dialog_content = "(침착해, PlayerName.)",
  ui_story_1013_10130502_10_dialog_content = "(주위를 잘 관찰해, 분명 뭔가 방법이 있을 거야.)",
  ui_story_1013_10130502_11_dialog_content = "바이스, 저 높은 곳에 있는 돌을 공격해!",
  ui_story_1013_10130502_12_dialog_content = "알겠어.",
  ui_story_1013_10130502_13_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_1013_10130502_14_dialog_content = "크오오──",
  ui_story_1013_10130502_15_dialog_content = "좋았어! 낙석으로 암귀의 포위를 뚫었어!",
  ui_story_1013_10130502_16_dialog_content = "바이스, 포위를 돌파하자!",
  ui_story_1013_10130502_17_dialog_content = "응.",
  ui_story_1013_10130502_18_dialog_content = "저기가 바로 최종 목적지야!",
  ui_story_1013_10130502_19_dialog_content = "도착했어!",
  ui_story_1013_10130502_20_dialog_content = "스테이지 목표를 달성했습니다.",
  ui_story_1013_10130502_21_dialog_content = "테스트 종료, 스테이지 평점은 C입니다.",
  ui_story_1013_10130502_22_dialog_content = "휴... 휴우...",
  ui_story_1013_10130502_23_dialog_content = "힘들어 죽을 것 같아...",
  ui_story_1013_10130502_24_dialog_content = "근데 왜 평점은 C인 거냐고!",
  ui_story_1013_10130502_25_dialog_content = "수고했어요, PlayerName.",
  ui_story_1013_10130502_26_dialog_content = "잠깐만 기다려요. 바로 접속을 해제할게요.",
  ui_story_1013_10130502_27_dialog_content = "연결이 해제되었습니다. 안전하게 로그아웃할 수 있습니다.",
  ui_story_1013_10130502_28_dialog_content = "PlayerName, 고생했어!",
  ui_story_1013_10130502_29_dialog_content = "어둠의 밑바닥에서의 전투를 체험한 소감은 어떤가.",
  ui_story_1013_10130502_30_option_content = "힘들어요...",
  ui_story_1013_10130502_31_dialog_content = "그냥 의자에 앉아서 몸은 움직이지도 않았는데, 옷이 벌써 땀으로 다 젖었어요.",
  ui_story_1013_10130502_32_option_content = "어려웠어요...",
  ui_story_1013_10130502_33_dialog_content = "분명히 전력을 다해서 제가 생각해 낼 수 있는 모든 전략을 썼는데...",
  ui_story_1013_10130502_34_dialog_content = "평가는 고작 C였잖아요!",
  ui_story_1013_10130502_35_dialog_content = "PlayerName, 충분히 잘했어!",
  ui_story_1013_10130502_36_dialog_content = "맞아! 지금 건 대원수님이 직접 겪었던 전투란 말이야.",
  ui_story_1013_10130502_37_dialog_content = "익숙하지 않은 환경에서 이 정도 성적이면 충분히 대단한 거야!",
  ui_story_1013_10130502_38_dialog_content = "지금 그게 라인하르트 씨가 겪은 싸움이었다고?",
  ui_story_1013_10130502_39_dialog_content = "그럼 그때 실제 결과는?",
  ui_story_1013_10130502_40_dialog_content = "어디 보자. 이 전투의 최고 기록을 찾아볼게...",
  ui_story_1013_10130502_41_dialog_content = "찾았어! 최고 기록은 「혼자서 최소 50마리의 암귀를 쓰러트린 후\n경상만 입고 포위 돌파에 성공」이야.",
  ui_story_1013_10130502_42_dialog_content = "전장 시뮬레이터의 평가 기준으로 말하자면 아마 A 이상의 평점일걸.",
  ui_story_1013_10130502_43_dialog_content = "대단해!",
  ui_story_1013_10130502_44_dialog_content = "어둠의 밑바닥 같은 곳에서 그런 전적을 해낼 수 있다니...",
  ui_story_1013_10130502_45_dialog_content = "역시 대원수님이시라니까요!",
  ui_story_1013_10130502_46_dialog_content = "아... 난 고작 스테이지 클리어만으로도 벅차다고.",
  ui_story_1013_10130502_47_dialog_content = "PlayerName, 자신을 얕볼 필요는 없다.",
  ui_story_1013_10130502_48_dialog_content = "네게 있어 어둠의 밑바닥에서의 전투는 아직 두 번째일 것이다.\n그럼에도 불구하고 이 성적은 이미 훌륭하다.",
  ui_story_1013_10130502_49_dialog_content = "지난번과 비교하면 넌 어둠의 밑바닥이라는 환경의 특성을 보다 고려해서 한층 더 활용했다.",
  ui_story_1013_10130502_50_dialog_content = "게다가 이번에는 지원군 없이도 멋지게 작전을 해냈지.",
  ui_story_1013_10130502_51_dialog_content = "현저한 발전이다. 칭찬을 받을 만하다!",
  ui_story_1013_10130502_52_dialog_content = "아... 고, 고마워요.",
  ui_story_1013_10130502_53_dialog_content = "일루미나 연방에 PlayerName 너처럼 지휘 능력이 뛰어난 인재가 더 있다면...",
  ui_story_1013_10130502_54_dialog_content = "암귀와의 싸움도 훨씬 더 수월해지겠지.",
  ui_story_1013_10130502_55_dialog_content = "그러고 보니까 PlayerName 넌 나랑 처음 만났을 때부터\n이미 상당한 수준의 지휘 능력이 있었어.",
  ui_story_1013_10130502_56_option_content = "그건 스카이워커 덕분이야.",
  ui_story_1013_10130502_57_option_content = "어렸을 때부터 배웠으니까.",
  ui_story_1013_10130502_58_dialog_content = "응?",
  ui_story_1013_10130502_59_dialog_content = "지하에서 살았던 17년 동안, 스카이워커는 나한테 많은 지식을 가르쳐 줬어.",
  ui_story_1013_10130502_60_dialog_content = "그중에는 전투 지휘에 필요한 지식도 있었어.",
  ui_story_1013_10130502_61_dialog_content = "아이테르는 다음 세대한테 전투 지휘 지식도 가르치는 거야...?",
  ui_story_1013_10130502_62_dialog_content = "근데 아이테르는 평화를 사랑하는 종족 아니야?",
  ui_story_1013_10130502_63_dialog_content = "응, 맞아. 그렇게 생각하면 내가 배운 지식과 귀환의 탑 안에 있던 자료들은\n같은 곳에서 왔을지도 몰라.",
  ui_story_1013_10130502_64_dialog_content = "난...",
  ui_story_1013_10130502_65_dialog_content = "PlayerName, 자신을 의심하는 건가?",
  ui_story_1013_10130502_66_dialog_content = "...아니요, 전 이미 깨달았어요.",
  ui_story_1013_10130502_67_dialog_content = "호오?",
  ui_story_1013_10130502_68_dialog_content = "배운 지식의 출처가 무엇이든 지금은 모두 제 지식이에요.",
  ui_story_1013_10130502_69_dialog_content = "지금의 전 그 지식을 가지고 동료들을 지킬 거예요. 무슨 나쁜 짓이 아니라요.",
  ui_story_1013_10130502_70_dialog_content = "하하하, 잠깐 못 본 사이에 많이 성장했잖아!",
  ui_story_1013_10130502_71_dialog_content = "그, 그런가요?",
  ui_story_1013_10130502_72_dialog_content = "물론이지!",
  ui_story_1013_10130502_73_dialog_content = "지난번 헤븐즈 밸리의 일이 끝난 후로, 난 네 상태가 그리 좋지 않은 것 같아서\n잠시 걱정하기도 했었다.",
  ui_story_1013_10130502_74_dialog_content = "하지만 지금 모습을 보면 내 걱정도 기우였던 모양이군.",
  ui_story_1013_10130502_75_dialog_content = "전 그렇게 약하지 않아요.",
  ui_story_1013_10130502_76_dialog_content = "물론 알고 있다.",
  ui_story_1013_10130502_77_dialog_content = "다만 조금 아쉽군. 너를 위로할 말까지 준비했었는데, 이젠 필요 없어진 것 같아서 말이지.",
  ui_story_1013_10130502_78_dialog_content = "네? 어떤 말인데요?",
  ui_story_1013_10130502_79_dialog_content = "일루미나에 옛날부터 전해지던 말이다.",
  ui_story_1013_10130502_80_dialog_content = "「과학 기술에는 선악의 구분이 없다. 있는 것은 그것을 이용하는 오로리안의 선악뿐이다.」",
  ui_story_1013_10130502_81_dialog_content = "네...?",
  ui_story_1013_10130502_82_dialog_content = "라인하르트 씨가 그런 말을 할 줄은 몰랐어요.",
  ui_story_1013_10130502_83_dialog_content = "물론 나 자신의 말은 아니다. 과거의 그 선생들이 내게 했던 말을 인용했을 뿐이지.",
  ui_story_1013_10130502_84_dialog_content = "역시 그랬군요.",
  ui_story_1013_10130502_85_dialog_content = "PlayerName, 네가 이렇게 빨리 고민에서 벗어나서 나도 기쁘게 생각한다.",
  ui_story_1013_10130502_86_dialog_content = "이번에는 도울 수 없었지만, 앞으로 도움이 필요할 땐 언제든지 날 찾아와도 좋다.",
  ui_story_1013_10130502_87_dialog_content = "내가 도울 수 있는 일이라면 최선을 다하겠다.",
  ui_story_1013_10130502_88_dialog_content = "다만 나는 그리 말을 잘하는 편이 아니라서 말이지.\n네게 특별히 좋은 조언을 해줄 순 없을지도 모른다.",
  ui_story_1013_10130502_89_dialog_content = "마음만으로도 이미 충분해요.",
  ui_story_1013_10130502_90_dialog_content = "휴, 근데 얘기가 나와서 말인데요. 역시 스카이워커가 너무 걱정돼요...",
  ui_story_1013_10130502_91_dialog_content = "그러게, 분명히 모듈도 찾았고, 절차대로 귀환의 탑에 가서 복구도 했는데...",
  ui_story_1013_10130502_92_dialog_content = "왜 스카이워커호의 의식은 아직도 회복되지 않는 거지?",
  ui_story_1013_10130502_93_dialog_content = "아직은 어쩔 수 없는걸.",
  ui_story_1013_10130502_94_dialog_content = "앞선 기술력을 자랑하는 일루미나 연방에서도 인공지능 분야에 대한 연구는 아직 제한적이야.",
  ui_story_1013_10130502_95_dialog_content = "게다가 콜로서스의 의식은 일반 인공지능과는 크게 다르기도 해.",
  ui_story_1013_10130502_96_dialog_content = "그래도 연구가 진행되면 분명히 방법이 생길 거야!",
  ui_story_1013_10130502_97_dialog_content = "일단 그건 그렇고, 나한테 좋은 소식이 있는데 들어볼래?",
  ui_story_1013_10130502_98_dialog_content = "뭔데?",
  ui_story_1013_10130502_99_dialog_content = "우린 스카이워커호의 새로운 모듈 안에서 많은 전투 기록을 발견했네.",
  ui_story_1013_10130502_100_dialog_content = "그 기록은 콜로서스나 귀환의 탑과 마찬가지로 오래되었을 가능성이 높지.",
  ui_story_1013_10130502_101_dialog_content = "잠깐만, 내 대사 뺏지 마!",
  ui_story_1013_10130502_102_dialog_content = "우린 이 전투 데이터를 연구하면 콜로서스에 대한 정보를 얻을 수도 있다고 본다.",
  ui_story_1013_10130502_103_dialog_content = "실험체 군, 저 콜로서스를 무척이나 고치고 싶겠지?",
  ui_story_1013_10130502_104_dialog_content = "...제가 뭘 해야 하는지 말해 주세요.",
  ui_story_1013_10130502_105_dialog_content = "우린 그 오래된 데이터를 전장 시뮬레이터에 넣어서 시뮬레이션을 진행할 거다.",
  ui_story_1013_10130502_106_dialog_content = "넌 지금까지와 마찬가지로 모의 전투를 진행해 주기만 하면 된다.",
  ui_story_1013_10130502_107_dialog_content = "우린 외부에서 관찰하면서 필요한 데이터를 수집할 거다.",
  ui_story_1013_10130502_108_dialog_content = "물론, 우리가 널 최대한 도와주고 안내해 줄 거야!",
  ui_story_1013_10130502_109_dialog_content = "왜냐면 이번엔 능력 테스트가 아니라 데이터 수집이 목적이거든.",
  ui_story_1013_10130502_110_dialog_content = "근데 전장 시뮬레이터도 그런 데이터는 처음 쓰는 거라서...",
  ui_story_1013_10130502_111_dialog_content = "그러니까 최대한 신중하게 움직이는 게 좋아!",
  ui_story_1013_10130502_112_dialog_content = "알겠어. 스카이워커를 빨리 고칠 수만 있다면 난 괜찮아.",
  ui_story_1013_10130502_113_dialog_content = "바로 시작하자.",
  ui_story_1013_10130502_114_dialog_content = "알겠어. 그럼 지금까지 한 것처럼 의자에 앉아서 헬멧을 쓰면 돼.",
  ui_story_1013_10130601_1_dialog_content = "여긴... 어디지?",
  ui_story_1013_10130601_2_dialog_content = "뭔가 도시 같은데?",
  ui_story_1013_10130601_3_dialog_content = "왜 계속 보이던 황야가 아닌 거지?",
  ui_story_1013_10130601_4_dialog_content = "이상하네.",
  ui_story_1013_10130601_5_dialog_content = "바이스, 라인하르트 씨, 들려요?",
  ui_story_1013_10130601_6_dialog_content = "......",
  ui_story_1013_10130601_7_dialog_content = "왜 대답이 없지?",
  ui_story_1013_10130601_8_dialog_content = "설마 전장 시뮬레이터가 고장난 건 아니겠지?",
  ui_story_1013_10130601_9_dialog_content = "<color=#e8d9bb>전장 시뮬레이터 외부</color>",
  ui_story_1013_10130601_10_dialog_content = "PlayerName?",
  ui_story_1013_10130601_11_dialog_content = "어이, PlayerName! 들리나?",
  ui_story_1013_10130601_12_dialog_content = "무슨 일이지? 연결이 끊긴 거냐?",
  ui_story_1013_10130601_13_dialog_content = "죄송해요! 저희도 어떻게 된 건지 모르겠어요!",
  ui_story_1013_10130601_14_dialog_content = "전장 시뮬레이터에는 아무 에러 메시지도 없어요.\nPlayerName의 시야도 우리한테 정상적으로 보여지고 있어요...",
  ui_story_1013_10130601_15_dialog_content = "하지만 저희랑 PlayerName 사이의 통신은 끊긴 상태예요.",
  ui_story_1013_10130601_16_dialog_content = "원인도 알 수 없고 말이에요!",
  ui_story_1013_10130601_17_dialog_content = "전장 시뮬레이터와 PlayerName의 연결을 끊어라! 어서!",
  ui_story_1013_10130601_18_dialog_content = "그를 위험에 빠트려선 안 돼!",
  ui_story_1013_10130601_19_dialog_content = "네, 네엣!",
  ui_story_1013_10130601_20_dialog_content = "어라?",
  ui_story_1013_10130601_21_dialog_content = "해, 해제가 안 되잖아?",
  ui_story_1013_10130601_22_dialog_content = "이건 또 어떻게 된 거냐.",
  ui_story_1013_10130601_23_dialog_content = "죄, 죄송해요. 지금은 원인을 모르겠어요!",
  ui_story_1013_10130601_24_dialog_content = "PlayerName... 괜찮겠지?",
  ui_story_1013_10130601_25_dialog_content = "왜 갑자기 전장 시뮬레이터에 고장이 난 거죠?",
  ui_story_1013_10130601_26_dialog_content = "보고드립니다. 전장 시뮬레이터는 지금까지 이런 고장이 발생한 적이 없었습니다!",
  ui_story_1013_10130601_27_dialog_content = "어쩌면 스카이워커호에 저장되어 있던 전투 데이터를 사용한 게 원인이 되어\n이러한 문제가 발생한 걸지도 모릅니다.",
  ui_story_1013_10130601_28_dialog_content = "헬멧을 벗으면 강제로 끌어낼 수 있나?",
  ui_story_1013_10130601_29_dialog_content = "그렇게 하지 않는 게 좋을 거예요. 대원수님.",
  ui_story_1013_10130601_30_dialog_content = "어? 의료 장치 연구 중이던 거 아냐? 여긴 어떻게 왔어?",
  ui_story_1013_10130601_31_dialog_content = "젊은 친구의 지금 상태를 분석하려면 생물학에 정통한 사람이 필요하잖아. 그래서 온 거야.",
  ui_story_1013_10130601_32_dialog_content = "그것도 그래! 그래서 지금 대체 어떤 상태인 건데?",
  ui_story_1013_10130601_33_dialog_content = "철저하게 연구하기 전까진 나도 단언할 수 없어.",
  ui_story_1013_10130601_34_dialog_content = "다만 낙관할 수는 없는 건 확실해.\n전장 시뮬레이터가 가동하는 동안에는 실험체와 의식이 서로 연결되잖아.",
  ui_story_1013_10130601_35_dialog_content = "만약 강제로 접속을 해제한다면, 젊은 친구의 남은 인생은 아마\n침대 위에서 보내게 될지도 몰라.",
  ui_story_1013_10130601_36_dialog_content = "어떻게 그런...",
  ui_story_1013_10130601_37_dialog_content = "그렇다고 해서 젊은 친구를 이대로 시스템 안에 가둬둘 순 없어.",
  ui_story_1013_10130601_38_dialog_content = "외부에서 우리가 뭔가 할 수 있는 건 없을까요?",
  ui_story_1013_10130601_39_dialog_content = "진정하게, 바이스 중위.",
  ui_story_1013_10130601_40_dialog_content = "지금 자네가 할 수 있는 일은 우리가 실험체 군을 구할 방법을 찾는 걸\n방해하지 않는 것뿐이야.",
  ui_story_1013_10130601_41_dialog_content = "계속해서 그를 구할 방법을 찾아라.",
  ui_story_1013_10130601_42_dialog_content = "한시라도 빨리 전장 시뮬레이터와의 연결을 끊어야 한다.",
  ui_story_1013_10130601_43_dialog_content = "<color=#e8d9bb>전장 시뮬레이터 내부</color>",
  ui_story_1013_10130601_44_dialog_content = "대체 무슨 일이야?!",
  ui_story_1013_10130601_45_dialog_content = "연구원들이랑 통신도 안 되고, 스테이지 시작 알림도 안 들려.",
  ui_story_1013_10130601_46_dialog_content = "게다가 여긴... 일루미나도 백야성도 아니야...",
  ui_story_1013_10130601_47_dialog_content = "아까 연구원들 말로는 이번에 사용한 전투 데이터는\n스카이워커의 새 모듈 안에서 찾은 거라고 했어.",
  ui_story_1013_10130601_48_dialog_content = "그럼 설마... 지금 내가 보고 있는 게...",
  ui_story_1013_10130601_49_option_content = "고대 도시?!",
  ui_story_1013_10130601_50_dialog_content = "도망쳐──",
  ui_story_1013_10130601_51_dialog_content = "어라? 누가 이쪽으로 달려오는 것 같은데?",
  ui_story_1013_10130601_52_dialog_content = "빨리 도망쳐! 따라잡히면 안 돼!",
  ui_story_1013_10130601_53_dialog_content = "저기요, 무슨 일 있어요?",
  ui_story_1013_10130601_54_dialog_content = "으악! 놈들이 왔어!",
  ui_story_1013_10130601_55_dialog_content = "누가 왔는데요? 대체 무슨 일이냐구요!",
  ui_story_1013_10130601_56_dialog_content = "잠깐만, 이건... 다크매터?!",
  ui_story_1013_10130601_57_dialog_content = "크어어──!",
  ui_story_1013_10130601_58_dialog_content = "으앗?! 바이스!",
  ui_story_1013_10130601_59_dialog_content = "......",
  ui_story_1013_10130601_60_dialog_content = "다행이야... 무의식적으로 바이스의 모습을 상상해서...",
  ui_story_1013_10130601_61_dialog_content = "평민들을 지키고, 진형을 유지하라!",
  ui_story_1013_10130601_62_dialog_content = "암귀 따위 두려워하지 마라! 놈들은 전혀 무서워할 필요가 없다!",
  ui_story_1013_10130601_63_dialog_content = "무기를 쥐고 날 따라와라!",
  ui_story_1013_10130601_64_dialog_content = "돌격이다!",
  ui_story_1013_10130601_65_dialog_content = "그어어!",
  ui_story_1013_10130601_66_dialog_content = "저건 오로리안들인가? 루미나틱스로 암귀와 싸우고 있어...",
  ui_story_1013_10130601_67_dialog_content = "근데 너무 약하잖아?!",
  ui_story_1013_10130601_68_dialog_content = "공격에 효과가 거의 없어!",
  ui_story_1013_10130601_69_dialog_content = "크오오!",
  ui_story_1013_10130601_70_dialog_content = "으악!",
  ui_story_1013_10130601_71_option_content = "얼른 후퇴해!",
  ui_story_1013_10130601_72_dialog_content = "너흰 저 암귀들을 당해낼 수 없어!",
  ui_story_1013_10130601_73_dialog_content = "우린 이제 더는 물러설 곳이 없다.",
  ui_story_1013_10130601_74_dialog_content = "등 뒤에 있는 건... 우리의 터전이란 말이다!",
  ui_story_1013_10130601_75_dialog_content = "거기! 빨리 후퇴해! 그러다 다 죽어!",
  ui_story_1013_10130601_76_dialog_content = "돌격이다!",
  ui_story_1013_10130601_77_dialog_content = "크오오!",
  ui_story_1013_10130601_78_dialog_content = "바이스, 도와줘!",
  ui_story_1013_10130601_79_dialog_content = "알았어.",
  ui_story_1013_10130602_1_dialog_content = "<color=#e8d9bb>전장 시뮬레이터 외부</color>",
  ui_story_1013_10130602_2_dialog_content = "PlayerName의 상황은 어떻지?",
  ui_story_1013_10130602_3_dialog_content = "보고드립니다, 아직 해석 중입니다!",
  ui_story_1013_10130602_4_dialog_content = "실험체 군의 현재 상태는 안정적입니다.\n또한 전장 시뮬레이터에 문제가 생긴 것도 알게 되었습니다.",
  ui_story_1013_10130602_5_dialog_content = "현재 암귀와 싸우는 중입니다. 덕분에 저희가 해석할 시간이 생겼습니다!",
  ui_story_1013_10130602_6_dialog_content = "역시 PlayerName 넌 항상 자기 방식으로 우릴 도와준다니까!",
  ui_story_1013_10130602_7_dialog_content = "그의 노력을 헛되게 해서는 안 된다, 계속 해석을 진행하라!",
  ui_story_1013_10130602_8_dialog_content = "네!",
  ui_story_1013_10130602_9_dialog_content = "대원수님, 전투 데이터의 일부 분석 결과가 나왔어요.",
  ui_story_1013_10130602_10_dialog_content = "말해라.",
  ui_story_1013_10130602_11_dialog_content = "전투 시뮬레이터가 복원한 화면을 저희가 분석해 봤는데요.",
  ui_story_1013_10130602_12_dialog_content = "건물들의 특징이 현대 오로리안의 건물과는 전혀 달라요.",
  ui_story_1013_10130602_13_dialog_content = "오히려 시오반 연구원이 발견한 지하도시에 있던 고대 건축물과 무척 유사해요.",
  ui_story_1013_10130602_14_dialog_content = "따라서 이번에 사용한 전투 데이터는 오로리안보다 더 오래됐을 거예요.",
  ui_story_1013_10130602_15_dialog_content = "어쩌면 잃어버린 그 역사의 일부일지도 몰라요.",
  ui_story_1013_10130602_16_dialog_content = "태고 시대의 역사란 말인가...",
  ui_story_1013_10130602_17_dialog_content = "계속 기록해라.",
  ui_story_1013_10130602_18_dialog_content = "전장 시뮬레이터 속의 데이터는 진짜 고대 역사의 기록일 가능성이 높다.",
  ui_story_1013_10130602_19_dialog_content = "PlayerName의 주변 환경을 주의 깊게 관찰해라.\n어쩌면 그를 구출할 방법을 찾아낼 수 있을지도 모른다!",
  ui_story_1013_10130602_20_dialog_content = "<color=#e8d9bb>전장 시뮬레이터 내부</color>",
  ui_story_1013_10130602_21_dialog_content = "왜 이렇게 된 거지? 아직 스테이지가 시작되지도 않았는데 암귀가 나타났잖아...",
  ui_story_1013_10130602_22_dialog_content = "전부 다 이상해. 전장 시뮬레이터에 문제가 생긴 게 분명해.",
  ui_story_1013_10130602_23_dialog_content = "크오오──!",
  ui_story_1013_10130602_24_dialog_content = "......",
  ui_story_1013_10130602_25_dialog_content = "이대로는 끝이 없잖아!",
  ui_story_1013_10130602_26_dialog_content = "지금 여긴 나와 내 상상으로 만들어진 오로리안의 홀로그램밖에 없어.",
  ui_story_1013_10130602_27_dialog_content = "동료들의 대답도 안 들리고, 스카이워커조차 내 곁에 없어.",
  ui_story_1013_10130602_28_dialog_content = "어떻게 해야 이런 이상한 상황에서 벗어날 수 있는지도 모르겠어...",
  ui_story_1013_10130602_29_dialog_content = "아무것도 안 하고 암귀한테 당해버리면 도전 실패 판정을 받고\n전장 시뮬레이터에서 탈출할 수 있을까?",
  ui_story_1013_10130602_30_dialog_content = "근데 전장 시뮬레이터도 그런 데이터는 처음 쓰는 거라서...",
  ui_story_1013_10130602_31_dialog_content = "그러니까 최대한 신중하게 움직이는 게 좋아!",
  ui_story_1013_10130602_32_dialog_content = "안 돼, 경솔하게 움직일 순 없어.",
  ui_story_1013_10130602_33_dialog_content = "지금 전장 시뮬레이터에는 문제가 있어. 그 어떤 행동도 결과는 미지수야.",
  ui_story_1013_10130602_34_dialog_content = "게다가... 난 혼자가 아니야!",
  ui_story_1013_10130602_35_dialog_content = "바이스도, 다른 사람들도 밖에서 분명히 시뮬레이터의 문제를 확인하고 해결하는 중일 거야.",
  ui_story_1013_10130602_36_dialog_content = "<color=#e8d9bb>콰르릉!</color>",
  ui_story_1013_10130602_37_dialog_content = "무슨 일이지?!",
  ui_story_1013_10130602_38_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_1013_10130602_39_dialog_content = "지, 지진인가?",
  ui_story_1013_10130602_40_dialog_content = "아니야... 주변 환경 전체가... 무너지기 시작했잖아?!",
  ui_story_1013_10130602_41_dialog_content = "<color=#e8d9bb>쿠구구구──!</color>",
  ui_story_1013_10130602_42_dialog_content = "후퇴해! 빨리!",
  ui_story_1013_10130602_43_dialog_content = "악마가 왔다!",
  ui_story_1013_10130602_44_dialog_content = "악마?!",
  ui_story_1013_10130602_45_dialog_content = "으윽! 머리가... 아파...!",
  ui_story_1013_10130602_46_dialog_content = "여기서... 도망... 쳐야... 해...",
  ui_story_1013_10130602_47_dialog_content = "PlayerName.",
  ui_story_1013_10130602_48_dialog_content = "깨어나십시오.",
  ui_story_1013_10130602_49_dialog_content = "아직 포기해서는 안 됩니다.",
  ui_story_1013_10130602_50_dialog_content = "주변의 모습이 달라졌잖아?!",
  ui_story_1013_10130602_51_dialog_content = "저 멀리 암귀가 잔뜩 있는데?!",
  ui_story_1013_10130602_52_dialog_content = "하늘에 웬 그림자가... 어?! 콜로서스잖아!",
  ui_story_1013_10130602_53_dialog_content = "콜로서스가 암귀를 태우고 오로리안들과 싸우고 있어...",
  ui_story_1013_10130602_54_dialog_content = "귀환의 탑에 있던 기록이 진짜였던 거야...",
  ui_story_1013_10130602_55_dialog_content = "모든 작전 인원에게 고한다──",
  ui_story_1013_10130602_56_dialog_content = "이건... 방송?",
  ui_story_1013_10130602_57_dialog_content = "전선을 지키고 저항을 이어가라.",
  ui_story_1013_10130602_58_dialog_content = "인류는 반드시 악마를 이겨낸다.",
  ui_story_1013_10130602_59_option_content = "「악마」?",
  ui_story_1013_10130602_60_dialog_content = "아까도 누가 「악마」라고 외치던데, 그게 뭐지? 암귀 말하는 건가?",
  ui_story_1013_10130602_61_option_content = "「인류」?",
  ui_story_1013_10130602_62_dialog_content = "인류가 뭐지? 오로리안이어야 하는 거 아냐?",
  ui_story_1013_10130602_63_dialog_content = "들었어? 우린 버텨야 해!",
  ui_story_1013_10130602_64_dialog_content = "전선을 사수하고, 우리의 터전을 지키는 거다!",
  ui_story_1013_10130602_65_dialog_content = "잠깐만, 안 돼! 빨리 돌아가!",
  ui_story_1013_10130602_66_dialog_content = "너흰 암귀랑 싸울 힘이 전혀 없어! 가면 죽을 뿐이야!",
  ui_story_1013_10130602_67_dialog_content = "안 싸울 거면 방해하지 마!",
  ui_story_1013_10130602_68_dialog_content = "돌격! 암귀를 물리치자! 악마를 물리치자!",
  ui_story_1013_10130602_69_dialog_content = "전선을 사수하고, 물러서지 마라.",
  ui_story_1013_10130602_70_dialog_content = "인류는 반드시 이겨야 한다.",
  ui_story_1013_10130602_71_dialog_content = "크오오!",
  ui_story_1013_10130602_72_dialog_content = "으악...!",
  ui_story_1013_10130602_73_dialog_content = "물러서면... 안 돼!",
  ui_story_1013_10130602_74_dialog_content = "멈춰!",
  ui_story_1013_10130602_75_dialog_content = "계속 싸워라, 계속 버텨라.",
  ui_story_1013_10130602_76_dialog_content = "이 방송은 도대체 뭐야?! 어떻게 그렇게 쉽게 남의 목숨을 버리라고 할 수 있는 거냐고!",
  ui_story_1013_10130602_77_dialog_content = "<color=#e8d9bb>지지직──</color>",
  ui_story_1013_10130602_78_dialog_content = "전투... 기...록을... 읽고... 있습니...",
  ui_story_1013_10130602_79_dialog_content = "전장 시뮬레이터 알림이잖아?!",
  ui_story_1013_10130602_80_dialog_content = "시스템이 회복됐나?",
  ui_story_1013_10130602_81_dialog_content = "...강림... 데이터를 읽었...",
  ui_story_1013_10130602_82_dialog_content = "전장... 모드... 번호: 오류.",
  ui_story_1013_10130602_83_dialog_content = "...목표: 안전지대로... 철수.",
  ui_story_1013_10130602_84_dialog_content = "철수라고? 이제 어딜 가도 암귀투성이인데. 뭘 어디로 철수하라는 거야?",
  ui_story_1013_10130602_85_dialog_content = "어이, 너!",
  ui_story_1013_10130602_86_dialog_content = "후방 쪽으로 달려라! 저쪽은 안전지대다! 거기 가면 병사들이 널 지켜줄 테니 안전할 거다.",
  ui_story_1013_10130602_87_dialog_content = "포기하지 마라. 인류는 반드시 악마를 이겨낸다!",
  ui_story_1013_10130602_88_dialog_content = "(후방... 암귀랑 반대 방향으로 뛰면 되는 건가?)",
  ui_story_1013_10130602_89_dialog_content = "(전장 시뮬레이터의 환경이 너무 사실적이라서 깜빡 잊을 뻔했어...)",
  ui_story_1013_10130602_90_dialog_content = "(지금 보는 건 다 과거의 기록일 뿐이잖아.)",
  ui_story_1013_10130602_91_dialog_content = "(뭘 하든 이미 일어난 일을 바꿀 순 없어.)",
  ui_story_1013_10130602_92_dialog_content = "(지금 내가 할 수 있는 건 한시라도 빨리 스테이지를 클리어하고 이 모든 걸 끝내는 거야.)",
  ui_story_1013_10130602_93_dialog_content = "전장 시뮬레이터, 스테이지를 시작합니다.",
  ui_story_1013_10130701_1_dialog_content = "후우, 후우...",
  ui_story_1013_10130701_2_dialog_content = "(어느 쪽으로 도망쳐야 할진 모르겠지만...)",
  ui_story_1013_10130701_3_dialog_content = "(병사를 따라가면 틀림없겠지!)",
  ui_story_1013_10130701_4_dialog_content = "어이, 거기 너희들! 벙커 안으로 들어가라!",
  ui_story_1013_10130701_5_dialog_content = "아, 알겠어!",
  ui_story_1013_10130701_6_dialog_content = "어라?",
  ui_story_1013_10130701_7_dialog_content = "(앞에 움직이지 않는 사람들이 있어.)",
  ui_story_1013_10130701_8_dialog_content = "(다쳤나...?)",
  ui_story_1013_10130701_9_dialog_content = "반복한다. 계속 싸워라, 계속 버텨라.",
  ui_story_1013_10130701_10_dialog_content = "저기요! 혹시 다치셨나요? 도움이 필요한가요?",
  ui_story_1013_10130701_11_dialog_content = "여긴 위험해요. 이 앞의 안전지대까지 데려다줄게요!",
  ui_story_1013_10130701_12_dialog_content = "어라, 이건...?",
  ui_story_1013_10130701_13_dialog_content = "(이 사람들의 몸에서 뿜어져 나오는 빛, 루미나의 빛깔과 똑같아.)",
  ui_story_1013_10130701_14_dialog_content = "(설마... 오로리안인가?)",
  ui_story_1013_10130701_15_dialog_content = "빛의 신께서는 영원한 백야도, 고통 없는 생명도, 기나긴 평안도 약속하지 않으셨습니다.",
  ui_story_1013_10130701_16_dialog_content = "빛의 신께서는 무궁한 나날도, 전쟁 없는 태평한 세상도 약속하지 않으셨습니다.",
  ui_story_1013_10130701_17_dialog_content = "그러나 빛의 신께서는 우리에게 힘과 용맹을, 지혜와 꾀를, 인애와 도의를 주셨습니다.",
  ui_story_1013_10130701_18_dialog_content = "원컨대 저희가 시련 속에서 축복을 받고, 용기와 지혜, 끝없는 사랑을 얻도록 하소서.",
  ui_story_1013_10130701_19_dialog_content = "(기도...하는 것 같네.)",
  ui_story_1013_10130701_20_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_1013_10130701_21_dialog_content = "전쟁의 불길이 급박하게 퍼지고 있다. 전원 지시에 따라 대피하라.",
  ui_story_1013_10130701_22_dialog_content = "이것은 마지막 경고다. 서둘러 「악마」가 나타날 구역에서 탈출하라.",
  ui_story_1013_10130701_23_dialog_content = "크오오!",
  ui_story_1013_10130701_24_dialog_content = "이런, 서둘러야 해...",
  ui_story_1013_10130701_25_dialog_content = "크에엑...",
  ui_story_1013_10130701_26_dialog_content = "빛의 사자는 결코 어둠을 두려워하지 않는다.",
  ui_story_1013_10130701_27_dialog_content = "우리는 어둠 속에서 태어난 악마를 쓰러트리기 위해 여기에 있는 것이다.",
  ui_story_1013_10130701_28_dialog_content = "소년이여, 저들이 널 해치지 못하도록 어서 가게. 이곳에선 이미 너무 많은 사람들이 죽었어.",
  ui_story_1013_10130701_29_option_content = "아니요, 제가 도와드릴 수 있어요!",
  ui_story_1013_10130701_30_dialog_content = "절 믿어주기만 한다면, 제가 여러분의 의식과 감응할 수 있어요...",
  ui_story_1013_10130701_31_dialog_content = "전 오로리안을 지휘할 능력이 있어요. 이 싸움에서 이길 수 있어요!",
  ui_story_1013_10130701_32_option_content = "아니요, 여러분도 같이 도망쳐요!",
  ui_story_1013_10130701_33_dialog_content = "이 싸움은 오로리안 네 명이서 해결할 수 있는 규모가 아니에요.",
  ui_story_1013_10130701_34_dialog_content = "저랑 같이 안전한 벙커로 도망쳐요. 지금은 그게 유일한 방법이에요.",
  ui_story_1013_10130701_35_dialog_content = "「오로리안」? 무슨 소리야? 그런 말은 못 들어봤어...",
  ui_story_1013_10130701_36_dialog_content = "여긴 애들 놀이터가 아니야. 얼른 도망쳐.",
  ui_story_1013_10130701_37_dialog_content = "너도 어린애잖아?!",
  ui_story_1013_10130701_38_dialog_content = "빛의 사자의 나이는 외모로 판단할 수 있는 게 아니에요.",
  ui_story_1013_10130701_39_dialog_content = "오직 루미나를 능숙하게 다룰 수 있는 사람만이 여기 서 있을 수 있는 거예요.",
  ui_story_1013_10130701_40_dialog_content = "이럴 때일수록 빛의 신의 계시를 <color=#FFB400>진지하게 사용</color>하지 않으면 안 돼요.",
  ui_story_1013_10130701_41_dialog_content = "그 말은...",
  ui_story_1013_10130701_42_dialog_content = "찬성이야. 지금은 이러쿵저러쿵 걱정하면서 힘을 억누르고 있을 때가 아니야.",
  ui_story_1013_10130701_43_dialog_content = "멀리 떨어져라, 소년. 빛의 파도에 휩쓸리고 싶지 않다면 말이야.",
  ui_story_1013_10130701_44_dialog_content = "...좋아, 그렇게라도 하지 않으면 우리 중 그 누구도 만족할 수 없겠지.",
  ui_story_1013_10130701_45_dialog_content = "저쪽에서 악마들이 오고 있어요.",
  ui_story_1013_10130701_46_dialog_content = "이제 마지막 한 줄기 빛을 잡자구요.",
  ui_story_1013_10130701_47_dialog_content = "빛은 우리의 것이다!",
  ui_story_1013_10130701_48_dialog_content = "어, 엄청난 루미나다!",
  ui_story_1013_10130701_49_dialog_content = "캬악──",
  ui_story_1013_10130701_50_dialog_content = "으아아아아아아악!",
  ui_story_1013_10130701_51_dialog_content = "이건...",
  ui_story_1013_10130701_52_dialog_content = "(분명히 승리의 빛 속에 있는데도... 악몽 같은 광경이 펼쳐지고 있어...)",
  ui_story_1013_10130701_53_dialog_content = "(강렬한 빛 속에서 암귀도 오로리안도 눈 깜짝할 사이에 죽고 말았어!)",
  ui_story_1013_10130701_54_dialog_content = "(더는 못 견디겠어... 설마... 나도...)",
  ui_story_1013_10130701_55_dialog_content = "<color=#e8d9bb>퍼어어엉!</color>",
  ui_story_1013_10130701_56_dialog_content = "후우, 후우...",
  ui_story_1013_10130701_57_dialog_content = "지직... 직... 지직...",
  ui_story_1013_10130701_58_dialog_content = "다... 끝난 건가...?",
  ui_story_1013_10130701_59_option_content = "[강제 감응]",
  ui_story_1013_10130701_60_dialog_content = "(다크매터가 전혀 느껴지지 않아... 무서울 정도로 조용해.)",
  ui_story_1013_10130701_61_dialog_content = "(이게 지난 세계가 멸망했을 때의 모습인가...)",
  ui_story_1013_10130701_62_dialog_content = "(어?!)",
  ui_story_1013_10130701_63_dialog_content = "(흙 속에서 뭔가 나왔잖아?!)",
  ui_story_1013_10130701_64_dialog_content = "<color=#e8d9bb>스윽── 스윽──</color>",
  ui_story_1013_10130701_65_dialog_content = "키이익──!",
  ui_story_1013_10130701_66_dialog_content = "(이런!)",
  ui_story_1013_10130701_67_dialog_content = "(계속 땅속에 숨어 있어서 살아남은 건가...)",
  ui_story_1013_10130701_68_dialog_content = "(그럼 내가 쓰러트려야 해!)",
  ui_story_1013_10130702_1_dialog_content = "키이이익──!",
  ui_story_1013_10130702_2_dialog_content = "난... 상대가 안 되는 건가?!",
  ui_story_1013_10130702_3_dialog_content = "이 녀석 몸... 아까보다 더 길어졌잖아...",
  ui_story_1013_10130702_4_dialog_content = "암귀가 제자리에서 몸을 재생할 능력은 없을 텐데... 이것도 시뮬레이터 고장 때문인가?",
  ui_story_1013_10130702_5_dialog_content = "캬악──",
  ui_story_1013_10130702_6_dialog_content = "어, 얼른 연구원들이랑 연락해야 돼...",
  ui_story_1013_10130702_7_dialog_content = "이런 데서 죽을 순 없어!",
  ui_story_1013_10130702_8_dialog_content = "전장 시뮬레이터 연구원 선생님들! 응답해 주세요!",
  ui_story_1013_10130702_9_dialog_content = "반복합니다! 전장 시뮬레이터 연구원 선생님들! 응답해 주세요!",
  ui_story_1013_10130702_10_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_1013_10130702_11_dialog_content = "어, 어떡하지...",
  ui_story_1013_10130702_12_dialog_content = "이제와서 무슨 방법이 있을까...",
  ui_story_1013_10130702_13_dialog_content = "<color=#e8d9bb>콰직... 콰직...</color>",
  ui_story_1013_10130702_14_dialog_content = "나 정말... 여기서 죽는 걸까?",
  ui_story_1013_10130702_15_dialog_content = "난...",
  ui_story_1013_10130702_16_dialog_content = "<color=#e8d9bb>휘이잉──</color>",
  ui_story_1013_10130702_17_dialog_content = "「제어 시스템 점검... 이상 무.」",
  ui_story_1013_10130702_18_dialog_content = "「바이오 모듈 점검... 이상 무.」",
  ui_story_1013_10130702_19_dialog_content = "「생명유지 시스템 점검... 작동 중. 현재 탑승자, 1명.」",
  ui_story_1013_10130702_20_dialog_content = "「엔진 점검... 이상 무. 가동 개시...」",
  ui_story_1013_10130702_21_dialog_content = "...스, 스카이워커?!",
  ui_story_1013_10130702_22_dialog_content = "저는 여기 있습니다, PlayerName. 언제나 당신 곁에 있었습니다.",
  ui_story_1013_10130702_23_dialog_content = "기억하십니까, 제 최우선 임무는 「PlayerName의 생명을 보장하는 것」입니다.",
  ui_story_1013_10130702_24_dialog_content = "비록 지금 눈앞의 모든 것은 가상의 데이터일 뿐입니다만...",
  ui_story_1013_10130702_25_dialog_content = "그렇다 해서 당신이 이렇게 해를 입는 것을 보고만 있을 순 없습니다.",
  ui_story_1013_10130702_26_dialog_content = "저와의 감응을 끊어 보십시오. 나머지는 절 믿고 맡기면 됩니다.",
  ui_story_1013_10130702_27_dialog_content = "「자동 조종 시스템 가동... 목표: 외부 세계와 연락해 현실로 귀환.」",
  ui_story_1013_10130702_28_dialog_content = "으음...",
  ui_story_1013_10130702_29_dialog_content = "성공... 했어...? 스카이워커...?",
  ui_story_1013_10130702_30_dialog_content = "PlayerName... PlayerName! 깨어났잖아?!",
  ui_story_1013_10130702_31_dialog_content = "PlayerName! 드디어 깨어났구나!",
  ui_story_1013_10130702_32_dialog_content = "의식이 회복됐어! 기도를 확보해서 호흡을 유지시켜.",
  ui_story_1013_10130702_33_dialog_content = "연구소의 신체 기능 검사기를 기동해.",
  ui_story_1013_10130702_34_dialog_content = "뭐 하는 거야...? 잠깐만! 나 괜찮아! 아무 데도 안 다쳤어!",
  ui_story_1013_10130702_35_dialog_content = "스카이워커는? 스카이워커는 어떻게 됐어?",
  ui_story_1013_10130702_36_dialog_content = "자네가 피해를 입었는지는 자네의 주관적인 감각으로 판단할 순 없네.",
  ui_story_1013_10130702_37_dialog_content = "검사 결과는 금방 나온다. 5분 정도만 더 참아 주게.",
  ui_story_1013_10130702_38_dialog_content = "...왜 아무도 전장 시뮬레이터에 이런 심각한 고장이 날 수도 있다는 건 말 안 했어?!",
  ui_story_1013_10130702_39_dialog_content = "난 항상 널 해부하고 싶다고 농담하지만, 농담과 진담의 구분은 확실히 하고 있어.",
  ui_story_1013_10130702_40_dialog_content = "우린 절대 네가 다치게 만들 의도는 없었어.\n이번 사고는 연구소에서 전적으로 책임질게.",
  ui_story_1013_10130702_41_dialog_content = "고대 전장 데이터 프로그래밍 담당자의 책임을 추궁하고,\n시뮬레이터 테스트도 다시 진행할 거야!",
  ui_story_1013_10130702_42_dialog_content = "그리고 내 명령도 전달해라...",
  ui_story_1013_10130702_43_dialog_content = "향후 3개월간, PlayerName의 콜로서스 유지 보수 비용은\n일루미나 연구소에서 부담한다.",
  ui_story_1013_10130702_44_dialog_content = "PlayerName, 어떤가.",
  ui_story_1013_10130702_45_dialog_content = "그, 그 정도면 된 것 같네요...",
  ui_story_1013_10130702_46_dialog_content = "음, 이번 고장의 원인은 전장 시뮬레이터와 콜로서스 간 접속 기술의 미숙함 때문이야.",
  ui_story_1013_10130702_47_dialog_content = "아까 그 암귀가 계속해서 재생된 건 네가 과거의 고장 난 데이터 속에 들어가서 그런 거야.",
  ui_story_1013_10130702_48_dialog_content = "역시 다들 상황을 보고 있었구나...",
  ui_story_1013_10130702_49_dialog_content = "마지막에 스카이워커가 시뮬레이터와의 연결을 끊어줘서 무사히 나올 수 있었어.",
  ui_story_1013_10130702_50_dialog_content = "그래서 스카이워커는?",
  ui_story_1013_10130702_51_dialog_content = "검사 결과가 나왔다. 실험체 군. 자네 몸은 멀쩡하네.",
  ui_story_1013_10130702_52_dialog_content = "...스카이워커는 어떻게 됐냐구요!",
  ui_story_1013_10130702_53_dialog_content = "스카이워커호는...",
  ui_story_1013_10130702_54_dialog_content = "접속을 강제로 끊은 대가를 치렀어.",
  ui_story_1013_10130702_55_dialog_content = "스카이워커호의 의식 데이터는 전장 시뮬레이터의 가상 세계에 남겨진 채야.",
  ui_story_1013_10130702_56_dialog_content = "자네에겐 잔혹한 일일지도 모르지만, 이런 상황은 연구에서 흔히 볼 수 있는 일이다.",
  ui_story_1013_10130702_57_dialog_content = "의식에 약간의 문제가 생겼고, 지금은 인격과 기억이 갈라지고 말았다.",
  ui_story_1013_10130702_58_dialog_content = "기억은 그저 단순한 정보가 되었고, 인격은 백지 상태로 돌아갔지.",
  ui_story_1013_10130702_59_dialog_content = "이 퇴화 과정이 완료되는 순간, 스카이워커호는 자넬 무사히 현실로 돌려보냈다.\n그 대신 자신의 기능도 상실했지.",
  ui_story_1013_10130702_60_dialog_content = "!!!",
  ui_story_1013_10130702_61_dialog_content = "무슨 뜻이죠...? 퇴화니... 상실이니... 대체 다 뭐냐고요...",
  ui_story_1013_10130702_62_dialog_content = "그대로의 뜻이다.",
  ui_story_1013_10130702_63_dialog_content = "그걸 지금... 「약간의 문제」라고 말하는 건가요?!",
  ui_story_1013_10130702_64_option_content = "(강제 감응!)",
  ui_story_1013_10130702_65_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_1013_10130702_66_option_content = "(강제 감응!!)",
  ui_story_1013_10130702_67_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_1013_10130702_68_option_content = "(강제 감응!!!)",
  ui_story_1013_10130702_69_dialog_content = "소용없어요, PlayerName.",
  ui_story_1013_10130702_70_dialog_content = "지금 당신은 스카이워커호를 제어할 수 없어요.",
  ui_story_1013_10130702_71_dialog_content = "우린 계속해서 스카이워커호의 의식 회복을 시도할 거예요.\n하다못해 적어도 기능은 정상적으로 움직이도록 복구해 볼게요.",
  ui_story_1013_10130702_72_dialog_content = "적어도?",
  ui_story_1013_10130702_73_dialog_content = "인격도 기억도 잃었는데 어떻게 「정상적으로 움직인다」고 말할 수 있겠냐고!",
  ui_story_1013_10130702_74_dialog_content = "무슨 말이냐, PlayerName 일은 너희가 전부 책임지겠다던 게 아니었나?!",
  ui_story_1013_10130702_75_dialog_content = "맞습니다. 대원수님. 연구소는 끝까지 책임지고 콜로서스의 의식을 복구할 것입니다.",
  ui_story_1013_10130702_76_dialog_content = "하지만 실험체 군, 과학 기술을 친구라고 생각하면 안 된다네.\n과학 기술은 연구에 기여하는 도구일 뿐이야.",
  ui_story_1013_10130702_77_dialog_content = "확실히 콜로서스의 인격이 무너지면 시스템의 안정성에 큰 영향을 미칠지도 모르지.",
  ui_story_1013_10130702_78_dialog_content = "하지만 모든 게 정상적으로 가동한다면,\n인격이 잠들거나 서서히 사라지는 것도 무방하지 않겠나.",
  ui_story_1013_10130702_79_dialog_content = "스카이워커를 건드리지 마!\n스카이워커는 내 친구고, 선생님이고, 내 유일한 가족이야!",
  ui_story_1013_10130702_80_dialog_content = "진정해요, PlayerName. 복구 작업이 스카이워커에게 피해를 줄 일은 없어요.",
  ui_story_1013_10130702_81_dialog_content = "지금도 상처 주고 있잖아!",
  ui_story_1013_10130702_82_dialog_content = "<color=#e8d9bb>똑똑──</color>",
  ui_story_1013_10130702_83_dialog_content = "연구실에서는 정숙해 주시기 바랍니다. 소리 지르지 마세요.",
  ui_story_1013_10130702_84_dialog_content = "으음...?",
  ui_story_1013_10130702_85_dialog_content = "대원수님, <color=#FFB400>과학 수석 의회</color> 정보장교 잉겔입니다.",
  ui_story_1013_10130702_86_dialog_content = "과학 수석 의회라고? 녀석들, 또 내가 모르는 곳에서 우수한 젊은이들을 찾아낸 모양이군.",
  ui_story_1013_10130702_87_dialog_content = "네, 대원수님. 아마 절 처음 보시겠죠.",
  ui_story_1013_10130702_88_dialog_content = "하지만 전 대원수님을 잘 알고 있습니다.",
  ui_story_1013_10130702_89_dialog_content = "하하하, 일루미나인이라면 모두 나를 잘 알고 있겠지.",
  ui_story_1013_10130702_90_dialog_content = "그래서 과학 수석 의회는 왜 널 보낸 거지? 녀석들도 아이테르를 연구할 생각인가?",
  ui_story_1013_10130702_91_dialog_content = "과학 수석 의회는 곧 극비 좌담회를 열 것입니다.\n전 그저 명령을 전하러 왔을 뿐입니다.",
  ui_story_1013_10130702_92_dialog_content = "하하하, 연구밖에 모르는 늙은이들이 이제야 얼굴을 보여줄 마음이 생겼나?",
  ui_story_1013_10130702_93_dialog_content = "과학 수석 의회는 이번에 아이테르와 직접 대면해 소통할 수 있길\n진심으로 원하고 있습니다.",
  ui_story_1013_10130702_94_dialog_content = "날 제쳐두고 말이냐?",
  ui_story_1013_10130702_95_dialog_content = "물론 대원수님도 참여하셔야 합니다.",
  ui_story_1013_10130702_96_dialog_content = "협의가 아닌 명령입니다.\n대원수님은 반드시 아이테르와 함께 참석해 주시기 바랍니다.",
  ui_story_1013_10130702_97_dialog_content = "그럼 난 더더욱 거절할 권리도 없겠네?",
  ui_story_1013_10130702_98_dialog_content = "하지만 스카이워커는...",
  ui_story_1013_10130702_99_dialog_content = "네가 돌아오기 전까지 콜로서스에 대한 일체의 분석을 멈추라고\n나랑 그로누가 연구소에 명령을 내릴게.",
  ui_story_1013_10130702_100_dialog_content = "안심해. 여긴 내가 눈을 번쩍 뜨고 지켜볼 테니까!",
  ui_story_1013_10130702_101_dialog_content = "안심해라, PlayerName. 지금은 아직 방법이 없는 게 아니니까.",
  ui_story_1013_10130702_102_dialog_content = "과학 수석 의회에서 스카이워커호에 대한 새로운 가르침을 얻을 수 있을지도 모른다.",
  ui_story_1013_10130702_103_dialog_content = "...알겠어요.",
  ui_story_1013_10130702_104_dialog_content = "마침 전장 시뮬레이터 안에서 본 고대 전장의 역사에 대해 저도 물어볼 게 있거든요.",
  ui_story_1013_10130702_105_dialog_content = "두 분의 협조에 감사드립니다.\n당신의 문제에 대해서는 과학 수석 의회가 아낌없이 대답할 겁니다.",
  ui_story_1013_10130702_106_dialog_content = "그럼 이쪽으로 오시죠.",
  ui_story_1013_10130801_1_dialog_content = "과학 수석 의회요?",
  ui_story_1013_10130801_2_dialog_content = "그래. 그들은 일루미나 최고 권력기관의 직속 조직이다...",
  ui_story_1013_10130801_3_dialog_content = "핵심 멤버는 일루미나 곳곳에 흩어져 있고,\n중요한 순간 외에는 쉽게 모이는 일이 없는 비밀 조직이지.",
  ui_story_1013_10130801_4_dialog_content = "조금 겁주는 것처럼 들릴지도 모르겠지만,\n그들은 모두 일루미나의 최고 기밀 그 자체라고 할 수 있다.",
  ui_story_1013_10130801_5_dialog_content = "비공식적인 자리에서는 모두 신분을 숨기고 있고 말이야.",
  ui_story_1013_10130801_6_dialog_content = "이들이 마지막으로 모였던 건 군사기관의 세대교체를 위한 투표를 할 때였다.",
  ui_story_1013_10130801_7_dialog_content = "그거 혹시...",
  ui_story_1013_10130801_8_dialog_content = "그래, 내가 대원수로 취임했을 때다.",
  ui_story_1013_10130801_9_dialog_content = "정말 비밀스러운 조직이네요. 한 번도 들은 적이 없을 만도 하네요.",
  ui_story_1013_10130801_10_dialog_content = "두 분께선 조금 서둘러 주시죠.",
  ui_story_1013_10130801_11_dialog_content = "하하하, 들었나, PlayerName? 우리도 서두르자고.",
  ui_story_1013_10130801_12_dialog_content = "(대단하네. 일개 정보장교가 대원수한테 명령이라니...)",
  ui_story_1013_10130801_13_dialog_content = "PlayerName, 조금 긴장한 것 같군.",
  ui_story_1013_10130801_14_dialog_content = "긴장이라기보다는 조금 경계를 하고 있다는 편이 맞을 것 같네요.",
  ui_story_1013_10130801_15_dialog_content = "라인하르트 씨 말씀을 들으니까 더 이해가 안 되게 됐거든요.\n왜 갑자기 절 만나려고 하는 걸까요?",
  ui_story_1013_10130801_16_dialog_content = "바이스와 바튼 씨 일 때문일까요? 아니면 귀환의 탑의 처분 결과 때문인가요...",
  ui_story_1013_10130801_17_dialog_content = "그렇게 추측해 봤자 고민만 늘어날 뿐이다.",
  ui_story_1013_10130801_18_dialog_content = "그들은 확실히 많은 실권을 쥐고 있지만, 눈가림이나 일삼는 자들은 아니다.",
  ui_story_1013_10130801_19_dialog_content = "그쪽에서 먼저 나서서 널 좌담회에 초대했다는 건\n확실히 너와 적극적으로 소통하고, 네 신뢰를 얻고 싶은 것이겠지.",
  ui_story_1013_10130801_20_dialog_content = "게다가 저들은 표면적으로는 일루미나 내부의 지식을 관제하고 있지만,\n실질적으로는 그저 과학에 매료된 괴짜들일 뿐이다.",
  ui_story_1013_10130801_21_dialog_content = "어쩌면 저들과 만나서 스카이워커호의 인격을 회복할 방법을 찾을 수 있을지도 모른다.",
  ui_story_1013_10130801_22_dialog_content = "조금은 마음이 편해졌나?",
  ui_story_1013_10130801_23_dialog_content = "...고마워요, 라인하르트 씨.",
  ui_story_1013_10130801_24_dialog_content = "두 분 모두 수고하셨습니다. 이제 도착했습니다.",
  ui_story_1013_10130801_25_dialog_content = "입구에서 기본 정보를 등록해 주시죠.",
  ui_story_1013_10130801_26_dialog_content = "등록해 주신 정보는 출입 기록 이외에는 사용되지 않으므로 안심하십시오.",
  ui_story_1013_10130801_27_dialog_content = "(이렇게 보안이 엄격하다니...)",
  ui_story_1013_10130801_28_dialog_content = "<color=#e8d9bb>삑──삑!</color>",
  ui_story_1013_10130801_29_dialog_content = "출입문의 잠금을 해제했습니다. 안으로 들어가시죠.",
  ui_story_1013_10130801_30_dialog_content = "왜 연구소나 블랙 엄브렐라 쪽 사람을 부르지 않는 거죠?\n하다못해 바이스 중위라도 불러야 하는 거 아닌가요?",
  ui_story_1013_10130801_31_dialog_content = "아이테르가 어떤 입장인지는 아직 확실하지 않아.\n게다가 고대 기술에 있어 천재적인 감응 능력은 그자에게만 있잖아.",
  ui_story_1013_10130801_32_dialog_content = "천재라고 하기엔 과할지도 모르겠지만, 현시점에서 알려진 마지막\n순수 혈통의 아이테르인 것은 확실하지요.",
  ui_story_1013_10130801_33_dialog_content = "제 눈으로 확인하기 전까지는 그 「감응 능력」이라든가 하는 것도\n그저 비과학적인 사술이라고 할 수밖에 없어요.",
  ui_story_1013_10130801_34_dialog_content = "고장난 시계도 하루에 두 번은 맞으니까요.",
  ui_story_1013_10130801_35_dialog_content = "여러분의 의견은 계속 주의해 둘게.",
  ui_story_1013_10130801_36_dialog_content = "여기까지 합시다, 저들이 왔습니다.",
  ui_story_1013_10130801_37_dialog_content = "<color=#e8d9bb>똑똑──</color>",
  ui_story_1013_10130801_38_dialog_content = "아이테르 PlayerName 씨를 모셨습니다.",
  ui_story_1013_10130801_39_dialog_content = "라인하르트 대원수님도 방청인으로 함께 오셨습니다.",
  ui_story_1013_10130801_40_dialog_content = "여명의 빛을 위하여.",
  ui_story_1013_10130801_41_dialog_content = "여명의 빛을 위하여.",
  ui_story_1013_10130801_42_dialog_content = "PlayerName, 넌 내 옆에 앉아라.",
  ui_story_1013_10130801_43_dialog_content = "아이테르는 율리시스 씨의 왼쪽 자리에 앉으세요.\n디스플레이 정면이 당신 자리입니다.",
  ui_story_1013_10130801_44_dialog_content = "대원수님은 옆에 서 계세요.",
  ui_story_1013_10130801_45_dialog_content = "바렛, 오늘은 자리 잡기에 꽤 열심이군.",
  ui_story_1013_10130801_46_dialog_content = "오늘 좌담회의 참가 인원에는 제한이 있어서요. 누군가는 나서서 「행정 업무」를 해야겠죠.",
  ui_story_1013_10130801_47_dialog_content = "이번 좌담회에 참가해 주셔서 감사합니다.",
  ui_story_1013_10130801_48_dialog_content = "규칙을 잘 지켜주시면 우리 모두 시간 절약이 될 겁니다.",
  ui_story_1013_10130801_49_dialog_content = "명문화된 규칙이든, 명문화되지 않은 규칙이든 말이지요.",
  ui_story_1013_10130801_50_dialog_content = "앉으세요, 아이테르.",
  ui_story_1013_10130801_51_dialog_content = "안녕하세요.",
  ui_story_1013_10130801_52_dialog_content = "소개하겠습니다. 당신 오른쪽에 계신 분은 생물학자 율리시스 교수님입니다.",
  ui_story_1013_10130801_53_dialog_content = "교수님의 정면에 앉아 있는 분은 물리학자 조이스 선생님입니다.",
  ui_story_1013_10130801_54_dialog_content = "대원수님 옆에 앉아 있는 분은 공학자 바렛 선생님입니다.",
  ui_story_1013_10130801_55_dialog_content = "그리고...",
  ui_story_1013_10130801_56_dialog_content = "알골 선생님, 정신 좀 차리세요...",
  ui_story_1013_10130801_57_dialog_content = "하암── 실례했어. 하지만 내 시간은 한정적이거든.",
  ui_story_1013_10130801_58_dialog_content = "아까 같은 무의미한 자리 결정은 내 수면 보충보다 중요도가 높지 않아.",
  ui_story_1013_10130801_59_dialog_content = "알골!",
  ui_story_1013_10130801_60_dialog_content = "난 알골, 인공지능 분야를 맡고 있어. 어깨 위에 있는 로봇은 「부르」라고 해.",
  ui_story_1013_10130801_61_dialog_content = "부르가 잠에서 깰 만한 일을 하지 않는다면, 오늘 좌담회는 분명 즐거울 거야, 아이테르.",
  ui_story_1013_10130801_62_dialog_content = "자, 잘 부탁할게요...",
  ui_story_1013_10130801_63_dialog_content = "여러분, 이의가 없으시다면 회의를 시작하겠습니다.",
  ui_story_1013_10130801_64_dialog_content = "본론으로 들어가기 전, 오늘의 대화를 순조롭게 진행하기 위해\n먼저 당신의 의문에 답해 드리겠습니다.",
  ui_story_1013_10130801_65_dialog_content = "단, 질문은 최대 3개로 좁혀야 합니다.",
  ui_story_1013_10130801_66_dialog_content = "그는 방금 연구소의 전장 시뮬레이터 테스트를 마쳤다.",
  ui_story_1013_10130801_67_dialog_content = "그리고 마침 너희들에게 물어볼 게 있던 참이다.",
  ui_story_1013_10130801_68_dialog_content = "토론에 적극적으로 참여해 주셔서 감사합니다, 라인하르트.",
  ui_story_1013_10130801_69_dialog_content = "그럼 이제 아이테르에게 발언을 요청해도 될까요?",
  ui_story_1013_10130801_70_dialog_content = "...얼마든지.",
  ui_story_1013_10130801_71_option_content = "[「악마」에 대해 묻는다]",
  ui_story_1013_10130801_72_dialog_content = "시뮬레이터 안에서 본 모습들은... 다 정말로 있었던 일인 거겠죠?",
  ui_story_1013_10130801_73_dialog_content = "전 고대의 오로리안들이 루미나틱스를 사용해서 결사의 각오로 싸우는 걸 봤어요.",
  ui_story_1013_10130801_74_dialog_content = "그들이 「악마」라고 부르던 건 대체 뭐죠...?",
  ui_story_1013_10130801_75_dialog_content = "당신이 본 건 모두 실제 역사예요.",
  ui_story_1013_10130801_76_dialog_content = "오로리안과 아이테르가 있기 전, 이 대륙에는 선조 격의 오래된 종족이 존재했어요.",
  ui_story_1013_10130801_77_dialog_content = "스스로를 「인류」라고 부른 사람들이었죠. 맞죠?",
  ui_story_1013_10130801_78_dialog_content = "그래요. 외모는 우리와 다르지 않고 마찬가지로 과학 기술을 가지고 있었죠.\n게다가 신앙을 가진 사람도 많이 있었어요.",
  ui_story_1013_10130801_79_dialog_content = "하지만 그들은 그 어떤 특수한 능력도 없었어요.",
  ui_story_1013_10130801_80_dialog_content = "(그래서... 그런 혼란 속에서 「악마」를 피해서 도망칠 수밖에 없었던 걸까...)",
  ui_story_1013_10130801_81_dialog_content = "이해하기 쉽게 간단하게 설명하자면...",
  ui_story_1013_10130801_82_dialog_content = "고대의 선조들 중에서도 특히 비범한 천부적 능력을 가진\n일부 인류가 진화해서 오로리안이 된 거예요.",
  ui_story_1013_10130801_83_dialog_content = "하지만 일부 인류는 「악마」에 현혹되고 말았어요.",
  ui_story_1013_10130801_84_dialog_content = "그들이 말했던 「악마」가 대체 뭐죠?",
  ui_story_1013_10130801_85_dialog_content = "고위 암귀인가요? 아니면 아이테르나 오로리안인가요?",
  ui_story_1013_10130801_86_dialog_content = "...그건 연구소에서 계속 분석하고 있어요. 지금은 아직 답할 수 없겠네요.",
  ui_story_1013_10130801_87_dialog_content = "시간이 한참 됐는데, 너희 연구 진척도 지난번과 같은 상태는 아니겠지?",
  ui_story_1013_10130801_88_dialog_content = "「악마」의 기원이나 진화의 방식, 역사에 끼친 영향은 모두\n신중한 연구와 고증이 필요한 과제예요.",
  ui_story_1013_10130801_89_dialog_content = "시뮬레이터에서 몇 번 승리를 거둔 것으로 결론을 낼 수 있는 일이 아니에요.",
  ui_story_1013_10130801_90_dialog_content = "......",
  ui_story_1013_10130801_91_dialog_content = "결국 아이테르와 암귀는 「악마」에게 통제되어 오로리안과 결전을 벌였어요.",
  ui_story_1013_10130801_92_dialog_content = "이 역사는 지금 여기 계신 여러분께는 비밀도 아니겠죠.",
  ui_story_1013_10130801_93_dialog_content = "「...그 후 조상들이 살던 고대 세계는 완전히 멸망했다.\n암귀는 어둠의 밑바닥으로 물러났고, 아이테르도 종적을 감췄다...」",
  ui_story_1013_10130801_94_dialog_content = "「남은 오로리안은 새로운 문명을 세우고, 악마가 남긴 암귀들과 계속해서 싸우고 있다...」",
  ui_story_1013_10130801_95_dialog_content = "...라는 얘기죠?",
  ui_story_1013_10130801_96_dialog_content = "일루미나도 아직 확실한 결론에 도달한 건 아니지만,\n현재로선 대부분의 견해는 당신의 상상대로예요.",
  ui_story_1013_10130801_96X1_dialog_content = "잠시만 기다리세요.",
  ui_story_1013_10130801_97_dialog_content = "<color=#e8d9bb>딸칵──</color>",
  ui_story_1013_10130801_98_dialog_content = "(각성제인가? 이 녀석들도 여전하군.)",
  ui_story_1013_10130801_99_dialog_content = "(각성제를 서로의 암호로 삼아 봤자, 속일 수 있는 건 초면인 PlayerName 정도밖에 없다.)",
  ui_story_1013_10130801_100_dialog_content = "아, 이건 일루미나 내부에서 유통되는 새로운 각성제예요.\n아이테르, 당신도 사용해 보시겠어요?",
  ui_story_1013_10130801_100X1_dialog_content = "(어, 어디서 나온 거지?!)",
  ui_story_1013_10130801_100X2_dialog_content = "드디어 모습을 드러내는 거냐, 바렛.",
  ui_story_1013_10130801_100X3_dialog_content = "네, 전 이 아이테르에게 조금 관심이 있거든요.",
  ui_story_1013_10130801_100X4_dialog_content = "하지만 다른 사람들도 같은 생각이라는 보장은 없어요.",
  ui_story_1013_10130801_100X5_dialog_content = "우린 계속해서 당신을 <color=#FFB400>관찰</color>할 거니까, 좋은 모습을 보여 보세요. 아이테르.",
  ui_story_1013_10130801_101_dialog_content = "...아, 알겠어요.",
  ui_story_1013_10130801_102_option_content = "[고대의 오로리안에 대해 묻는다]",
  ui_story_1013_10130801_103_dialog_content = "그럼 그 「특히 비범한 천부적 능력을 가진 선조」는\n어떻게 루미나틱스에 눈을 뜬 거죠?",
  ui_story_1013_10130801_104_dialog_content = "제가 본 광경 속에서 그들은 그저 빛이 비치는 방향으로 기도를 할 뿐이었어요.",
  ui_story_1013_10130801_105_dialog_content = "그게... 백야성이 믿는 신앙의 기원인가요?",
  ui_story_1013_10130801_106_dialog_content = "하하하, 그 질문은 왠지 상대가 틀린 것 같은데요.",
  ui_story_1013_10130801_107_dialog_content = "앗, 미안해요!",
  ui_story_1013_10130801_108_dialog_content = "이 세계에는 확실히 오로리안이 많이 있지만,\n루미나틱스의 본질을 아는 사람은 극히 드물지요.",
  ui_story_1013_10130801_109_dialog_content = "그래서 오로리안들은 자신들이 이해하기 쉬운 방식으로 루미나틱스를 해석하려 합니다.",
  ui_story_1013_10130801_110_dialog_content = "예를 들면 신이 주셨거나... 어느 신성한 땅에서 탄생했거나...\n이른바 「진리」 속에서 깨달았다든가... 하는 것들 말이죠.",
  ui_story_1013_10130801_111_dialog_content = "그러나 루미나틱스의 진정한 핵심은 <color=#FFB400>생명력</color>으로 에너지를 움직이는 술식입니다.",
  ui_story_1013_10130801_112_dialog_content = "생명력? 그럼 우리 아이테르도...",
  ui_story_1013_10130801_113_dialog_content = "비록 아이테르도 생명력을 가지고 있지만, 루미나틱스의 사용법을 가질 순 없습니다.",
  ui_story_1013_10130801_114_dialog_content = "생명력이 없는 암귀는 더더욱 그렇습니다.\n저들은 이 방법으로 에너지를 움직일 수 없지요.",
  ui_story_1013_10130801_115_dialog_content = "당신이 말하는 「방법」이라는 게 뭐죠?",
  ui_story_1013_10130801_116_dialog_content = "하하, 간단히 말해 루미나틱스의 구체적인 응용 방법을 말하는 겁니다.\n예를 들면 일루미나 연방에서는...",
  ui_story_1013_10130801_117_dialog_content = "<color=#FFB400>형식적 측면</color>에서 루미나틱스로 물리적인 기계를 움직이고,\n과학 기술로 루미나틱스의 효과를 변화시킵니다.",
  ui_story_1013_10130801_118_dialog_content = "그러나 백야성에서는 순수한 신앙의 힘으로 그들의 생명력을 움직이고...",
  ui_story_1013_10130801_119_dialog_content = "이를 통해 <color=#FFB400>근원적 측면</color>에서 루미나틱스를 발휘하는 것이 목적입니다.",
  ui_story_1013_10130801_120_dialog_content = "그 점이 백야성과 일루미나의 유일한 차이이기도 하지.",
  ui_story_1013_10130801_121_dialog_content = "유일한 차이? 그 결론은 너무 독단적이군요.",
  ui_story_1013_10130801_122_dialog_content = "그리고 앞으로는 제 말을 끊지 말아 주세요.",
  ui_story_1013_10130801_123_dialog_content = "(내 착각인가... 여기 있는 과학자들, 다들 친절해 보이지만 계속 공격적인 느낌이 들어.)",
  ui_story_1013_10130801_124_dialog_content = "이미 10분 경과했습니다. 율리시스 교수님, 오늘 좌담회의 목적을 잊지 마세요.",
  ui_story_1013_10130801_125_dialog_content = "환기해 주어 고맙군요. 하지만 시작 전에 약속한 대로,\n아이테르가 할 수 있는 질문은 이제 하나 남았습니다.",
  ui_story_1013_10130801_126_dialog_content = "엄격하기 짝이 없네요. 율리시스.\n저 아가씨가 규칙을 아주 잘 준수하도록 훈련시켰군요.",
  ui_story_1013_10130801_127_dialog_content = "잉겔은 「계명성 프로젝트」의 개조를 받은 우수한 졸업생입니다.\n전 그저 정상적인 교육을 했을 뿐이지요.",
  ui_story_1013_10130801_128_dialog_content = "(개조?!)",
  ui_story_1013_10130801_129_dialog_content = "(이 사람들... 계속해서 <color=#FFB400>오로리안의 개조</color>를 해온 거야?!)",
  ui_story_1013_10130801_130_dialog_content = "...그게 바로 네가 계속 비밀리에 해 오던 실험이냐?!",
  ui_story_1013_10130801_131_dialog_content = "제대로 설명해라! 계명성 프로젝트는 분명히 몇 년 전에 중단되었을 것이다!",
  ui_story_1013_10130801_132_dialog_content = "정확히 말하자면 위원회에서 계획 중지 여부에 대한 투표를 했었지요.",
  ui_story_1013_10130801_133_dialog_content = "하지만 투표 결과는 당신 뜻과는 달랐습니다, 라인하르트.",
  ui_story_1013_10130801_134_dialog_content = "그럼 다시 위원회에 투표를 신청하도록 하지.",
  ui_story_1013_10130801_135_dialog_content = "그 어떤 개조 실험이든 내 병사나 시민들에게 손을 대는 건\n무슨 일이 있어도 용납하지 않을 거다!",
  ui_story_1013_10130801_136_dialog_content = "라인하르트, 당신은 물론 그럴 권리가 있습니다.",
  ui_story_1013_10130801_137_dialog_content = "대원수의 권력은 모든 일루미나인이 부여한 것이니,\n당신은 물론 그들의 행복을 위해 움직여야 합니다.",
  ui_story_1013_10130801_138_dialog_content = "하지만 그건 이 좌담회가 끝난 후에 하시지요.\n아이테르에게 말할 시간을 남겨 주세요.",
  ui_story_1013_10130801_139_dialog_content = "(어떡하지... 바이스의 상태도 설마 저 일과 관계가 있는 걸까...)",
  ui_story_1013_10130801_140_dialog_content = "(대체 얼마나 많은 사람이 비밀 개조를 받았던 걸까...\n그중에 줄곧 내 곁에 있던 친구들은 또 얼마나 있을까...)",
  ui_story_1013_10130801_141_dialog_content = "(강제 감응!)",
  ui_story_1013_10130801_142_dialog_content = "(PlayerName, 당황할 것 없다. 이 문제는 네게 부탁하지.)",
  ui_story_1013_10130801_143_dialog_content = "(네가 율리시스에게 「개조 실험」 계획에 대해 물어봐 주었으면 한다.)",
  ui_story_1013_10130801_144_dialog_content = "(바이스와 네 다른 동료들의 미래가 달린 문제다.\n또한 지금 눈앞에 있는 정보장교와 그녀의 동포와 관계된 문제이기도 하다.)",
  ui_story_1013_10130801_145_dialog_content = "(어쩌면... 그 시절의 우리들까지도...)",
  ui_story_1013_10130801_146_dialog_content = "(...알겠어요.)",
  ui_story_1013_10130801_147_dialog_content = "(한 가지 더, 내 괜한 걱정이었으면 좋겠다만, 저들은 왠지 몰래 널 평가하고 있는 것 같다.)",
  ui_story_1013_10130801_148_dialog_content = "(평가요?)",
  ui_story_1013_10130801_149_dialog_content = "(어쩌면 아직 저들 내부에서 의견이 일치하지 않는 것일지도 모르지.)",
  ui_story_1013_10130801_150_dialog_content = "(그래서 널 만나고 나서야 비밀리에 구체적인 판단을 내릴 수 있었을 거다.)",
  ui_story_1013_10130801_151_dialog_content = "(이것도 저들의 낡은 수법이지. 아무튼, 각성제를 복용하는 건 저들끼리의 신호다.)",
  ui_story_1013_10130801_152_dialog_content = "(다만 그렇다고 해서 너도 긴장할 필요는 없다. 너답게 하면 된다.)",
  ui_story_1013_10130801_153_dialog_content = "(그, 그럴게요.)",
  ui_story_1013_10130801_154_dialog_content = "(방금 침묵하는 동안, 「감응 능력」을 사용한 건가?)",
  ui_story_1013_10130801_155_dialog_content = "(...어찌 됐든 간에, 지속적인 관찰이 필요한 대상인 건 확실하군.)",
  ui_story_1013_10130801_156_dialog_content = "<color=#e8d9bb>딸칵──</color>",
  ui_story_1013_10130801_157_dialog_content = "(후훗... 이제야 저 아이테르를 인정할 마음이 생긴 건가.)",
  ui_story_1013_10130801_158_option_content = "[개조 실험에 대해 묻는다]",
  ui_story_1013_10130801_159_dialog_content = "과거의 헬리오스도 「계명성 프로젝트」 출신인가요?",
  ui_story_1013_10130801_160_dialog_content = "대체 왜... 어째서 일루미나가 오로리안의 개조 실험을 하는 거죠...?",
  ui_story_1013_10130801_161_dialog_content = "헬리오스? 당신은 제가 예상한 것보다 더 많은 것을 알고 있군요.",
  ui_story_1013_10130801_162_dialog_content = "그렇다면 더는 숨길 필요도 없겠지요.\n확실히 전 오로리안 개조 실험을 계속하고 있었습니다.",
  ui_story_1013_10130801_163_dialog_content = "여러분 눈앞에 서 있는 잉겔은 이번 기수에서 가장 성공한 실험체입니다.",
  ui_story_1013_10130801_164_dialog_content = "개조 오로리안도 오로리안의 기본 유전자와 인격의 특징을 가지고 있습니다.",
  ui_story_1013_10130801_165_dialog_content = "비록 잉겔의 드센 성격에는 저도 곤란할 때가 있지만 말이지요.",
  ui_story_1013_10130801_166_dialog_content = "그게 중요한 게 아니잖아요. 대체 왜 그런 짓을 하는 거죠?",
  ui_story_1013_10130801_167_dialog_content = "일루미나.",
  ui_story_1013_10130801_168_dialog_content = "물론 일루미나를 위해 그런 겁니다. 일루미나도 일루미나만의 개조 장치가 필요합니다.",
  ui_story_1013_10130801_169_dialog_content = "백야성은 저들의 대포가 있고, 헤븐즈 밸리는 오로리안의 체질을 강화하는\n고대의 기기를 가지고 있는 것처럼 말입니다.",
  ui_story_1013_10130801_170_dialog_content = "일루미나도 어둠의 밑바닥에서 비슷한 장치를 찾아보았지만,\n안타깝게도 아무런 단서도 얻지 못했습니다.",
  ui_story_1013_10130801_171_dialog_content = "일루미나가 가진 건 충실한 시민뿐입니다.\n우리의 방위선은 모두 병사들의 뼈로 쌓은 것입니다.",
  ui_story_1013_10130801_172_dialog_content = "일루미나가 개조 장치를 연구하는 것은 시민들의 진심 어린 바람입니다.",
  ui_story_1013_10130801_173_dialog_content = "개조에 성공한 실험체가 늘어날 때마다 무고한 희생자가 한 명 줄어들지요.",
  ui_story_1013_10130801_174_dialog_content = "정말 터무니없네요. 그럼 무고한 실험체는요?\n헬리오스 같은 희생은 희생도 아니라는 건가요?",
  ui_story_1013_10130801_175_dialog_content = "<color=#e8d9bb>딸칵──</color>",
  ui_story_1013_10130801_176_dialog_content = "휴, 그 헬리오스 말입니다만...",
  ui_story_1013_10130801_177_dialog_content = "그 실험체들은 계명성 프로젝트와는 관계가 없었습니다.",
  ui_story_1013_10130801_178_dialog_content = "헬리오스는 또 다른 육성 계획의 대상이었고, 게다가 그저 실험의 실패작일 뿐이었습니다.",
  ui_story_1013_10130801_179_dialog_content = "실패작?!",
  ui_story_1013_10130801_180_dialog_content = "한 오로리안의 인생을 망쳐놓고 「실험의 실패작」이라고?",
  ui_story_1013_10130801_181_dialog_content = "라인하르트, 자신이 성공했다고 해서 애써 자기 도덕심을 높이려 들지 마세요.",
  ui_story_1013_10130801_182_dialog_content = "「인생을 망쳤다」고 표현할 정도로 과장된 일은 아닐 겁니다.\n어쩌면 그에게는 더 적합한 길이었을지도 모르지 않습니까?",
  ui_story_1013_10130801_183_dialog_content = "<color=#e8d9bb>콰앙──</color>",
  ui_story_1013_10130801_184_dialog_content = "미안하지만 더는 이 회의를 이어갈 수 없겠어.\n게다가 율리시스, 넌 이미 이성적인 대화의 범주를 넘어섰다.",
  ui_story_1013_10130801_185_dialog_content = "좌담회는 여기까지다. 더는 계속할 필요가 없어 보이는군.",
  ui_story_1013_10130801_186_dialog_content = "음? 벌써 끝내자는 건가요? 하지만 과학 수석 의회에게는 이제 막 시작됐을 뿐인데요.",
  ui_story_1013_10130801_187_dialog_content = "아이테르를 혼자 남겨두고 가실 수 있다면 퇴장하셔도 좋아요.",
  ui_story_1013_10130801_188_dialog_content = "그게 무슨...",
  ui_story_1013_10130801_189_dialog_content = "너희가 할 수 있을 것 같으냐.",
  ui_story_1013_10130801_190_dialog_content = "안심하세요. 여기 있는 사람은 모두 지식인입니다.\n누구 하나라도 당신이 상상하는 것과 같은 비겁한 짓은 하지 않아요.",
  ui_story_1013_10130801_191_dialog_content = "우리가 아이테르에게 무슨 짓을 할 리가 없잖아요.\n우린 아이테르와 계속 「우호적」인 이야기를 해왔는걸요.",
  ui_story_1013_10130801_192_dialog_content = "다만 그 모든 과정을 가장 권위 있는 사람의 눈으로 증명해 주셔야 해요.",
  ui_story_1013_10130801_193_dialog_content = "라인하르트, 제가 더 설명할 필요는 없겠죠?\n당신도 자신이 맡은 배역을 잘 연기해 주셨으면 좋겠네요.",
  ui_story_1013_10130801_194_dialog_content = "......",
  ui_story_1013_10130801_195_dialog_content = "<color=#e8d9bb>톡, 톡──</color>",
  ui_story_1013_10130801_196_dialog_content = "하~암.",
  ui_story_1013_10130801_197_dialog_content = "고작 회의인데 그렇게 살기를 드러낼 필요는 없잖아, 여러분.",
  ui_story_1013_10130801_198_dialog_content = "모두 <color=#FFB400>아이테르를 인정한다고 암호</color>를 보냈으니 적어도 이야기는 우호적으로 해야지.",
  ui_story_1013_10130801_199_dialog_content = "아까 잉겔이 한 말이 맞아. 우리가 아이테르를 부른 목적을 잊지 마.",
  ui_story_1013_10130801_200_dialog_content = "(이 사람들, 이제야 진짜 목적을 말해줄 마음이 생겼나...)",
  ui_story_1013_10130801_201_dialog_content = "아이테르, 네 질문에 대해서는 아까 이 사람들이 대답한 게 거의 맞아.",
  ui_story_1013_10130801_202_dialog_content = "일루미나의 최고 기밀에 관한 것도 아는 한 전부 대답했다고 할 수 있어.",
  ui_story_1013_10130801_203_dialog_content = "이 정도의 정보로 협조를 구한다면 너한테도 손해는 아니겠지?",
  ui_story_1013_10130801_204_dialog_content = "?!",
  ui_story_1013_10130801_205_dialog_content = "농담하지 마세요... 전 절대 당신들 개조 실험에 협조하지 않을 거예요!",
  ui_story_1013_10130801_206_dialog_content = "푸훕... 넌 현존하는 유일한 아이테르야. 개조 같은 걸 할 리가 없잖아!",
  ui_story_1013_10130801_207_dialog_content = "아까도 말했듯이 우린 네 손가락 하나도 안 건드릴 거야.",
  ui_story_1013_10130801_208_dialog_content = "그저 네 도움이 필요할 뿐이야.\n그리고 어쩌면 그게 간접적으로 네 자신을 돕는 일일지도 몰라.",
  ui_story_1013_10130801_209_dialog_content = "미안한데 단도직입적으로 좀 말해줘요.",
  ui_story_1013_10130801_210_dialog_content = "어머, 참 냉담하네. 너, 바이스의 몸을 고쳐주고 싶지?\n그리고 네 콜로서스에도 문제가 있는 것 같던데.",
  ui_story_1013_10130801_211_dialog_content = "(화, 확실히 그렇긴 한데...)",
  ui_story_1013_10130801_212_dialog_content = "그럼 긴말 안 할게. 우린 네 감응 능력을 빌려서, <color=#FFB400>「가디언 1호」</color>에 접속하고 싶어.",
  ui_story_1013_10130801_213_dialog_content = "그동안 일루미나의 과학자들은 모두 네 스카이워커호가\n그저 평범한 수송형 콜로서스라고 생각했어.",
  ui_story_1013_10130801_214_dialog_content = "하지만 최근 스카이워커호의 일련의 모습과 계속 업데이트되는 시스템을 보면...",
  ui_story_1013_10130801_215_dialog_content = "우린 그 속에서 더 많은 가능성을 봤어.",
  ui_story_1013_10130801_216_dialog_content = "그리고 그 가능성은 스카이워커호를 조종하는 아이테르 없이는 성립하지 않아.",
  ui_story_1013_10130801_217_dialog_content = "너와 콜로서스라는 고대 과학 기술과의 밀접한 관계는\n그 일련의 기적을 일으킨 이유 중 하나야.",
  ui_story_1013_10130801_218_dialog_content = "아까 대화에서 우린 만장일치로 너한테 가디언 1호의 의식을 맡겨도 된다고 판단했어.",
  ui_story_1013_10130801_219_dialog_content = "그래서 너한테 부탁하고 싶어.\n감응 능력을 사용해서 가디언 1호와 감응해 줬으면 해.",
  ui_story_1013_10130801_220_dialog_content = "가디언 1호? 또 제가 때려잡아야 할 로봇이라도 있는 건가요...",
  ui_story_1013_10130801_221_dialog_content = "가디언 1호는 지금도 남아 있는 고대의 인공지능이야.\n일루미나 과학 기술 시스템 전체의 일상적인 가동과 계산을 담당하고 있어.",
  ui_story_1013_10130801_222_dialog_content = "어때? 콜로서스랑 비슷할 것 같지?",
  ui_story_1013_10130801_223_dialog_content = "확실히 그렇네요...",
  ui_story_1013_10130801_224_dialog_content = "만약 가디언 1호의 의식과 감응할 수 있다면...",
  ui_story_1013_10130801_225_dialog_content = "고대부터 존재한 그의 의식 속에서 바이스를 정상적인 상태로\n되돌릴 단서를 찾을 수 있을지도 몰라.",
  ui_story_1013_10130801_226_dialog_content = "물론 그의 의식 속에서 적합한 장면을 찾아낸다면, 네 콜로서스와 재회할 수도 있겠지.",
  ui_story_1013_10130801_227_dialog_content = "?!",
  ui_story_1013_10130801_228_dialog_content = "(이 사람이 하는 말이 사실이라면, 스카이워커는...!)",
  ui_story_1013_10130801_229_dialog_content = "결정권은 너한테 있어. 난 그저 참고할 의견을 말한 거야.",
  ui_story_1013_10130801_230_dialog_content = "PlayerName, 망설이고 있나?",
  ui_story_1013_10130801_231_dialog_content = "그렇게까지 말씀하신다면 물론 해 봐야죠!",
  ui_story_1013_10130801_232_dialog_content = "음, 역시 너답군. 네 결단에 찬성한다.",
  ui_story_1013_10130801_233_dialog_content = "여기 있는 사람들의 태도는 나쁘지만, 그렇다고 상황을 바꿀 기회를 쉽게 포기해선 안 된다.",
  ui_story_1013_10130801_234_dialog_content = "두 사람 의견도 일치한 것 같네.",
  ui_story_1013_10130801_235_dialog_content = "그럼 지금 바로 가디언 1호를 데리고 올게.",
  ui_story_1013_10130901_1_dialog_content = "가디언 1호는 지금도 남아 있는 고대의 인공지능이야.\n일루미나 과학 기술 시스템 전체의 일상적인 가동과 계산을 담당하고 있어.",
  ui_story_1013_10130901_2_dialog_content = "어때? 콜로서스랑 비슷할 것 같지?",
  ui_story_1013_10130901_3_dialog_content = "(일루미나 전체를 담당하는... 고대의 인공지능...)",
  ui_story_1013_10130901_4_dialog_content = "(궁금하네. 왠지 엄청 대단할 것 같은데.)",
  ui_story_1013_10130901_5_dialog_content = "(어떻게 생겼을까? 일루미나 전체의 방대한 연산을 감당하려면 분명히 엄청 크겠지?)",
  ui_story_1013_10130901_6_dialog_content = "(스카이워커 정도 되려나?)",
  ui_story_1013_10130901_7_dialog_content = "(고대의 인공지능을 온전히 간직하고 있다면, 분명히 프로그램도 다 갖추어져 있을 거야.)",
  ui_story_1013_10130901_8_dialog_content = "(적어도 츄브보단 똑똑하겠지.)",
  ui_story_1013_10130901_9_dialog_content = "(그리고 여러 사람이 제어할 수 있게 하려면 분명히 모니터도 달려 있지 않을까?)",
  ui_story_1013_10130901_10_dialog_content = "(지하도시의 「집사」처럼.)",
  ui_story_1013_10130901_11_dialog_content = "안녕하세요, 아이테르!",
  ui_story_1013_10130901_12_dialog_content = "당신은 1호가 수집한 아이테르에 관한 데이터와는 조금 다릅니다.",
  ui_story_1013_10130901_13_dialog_content = "이, 이 작은 로봇이 설마...",
  ui_story_1013_10130901_14_dialog_content = "맞아, 가디언 1호랑 서로 인사해.",
  ui_story_1013_10130901_15_dialog_content = "상상했던 거랑 전혀 다르잖아!",
  ui_story_1013_10130901_16_dialog_content = "1호는 당신의 존재를 통해 1호가 지닌 아이테르 데이터를 업데이트하겠습니다.",
  ui_story_1013_10130901_17_dialog_content = "1호도 당신이 수집한 인공지능에 관한 데이터와는 조금 다른 것을 알 수 있습니다.",
  ui_story_1013_10130901_18_dialog_content = "그럼 각자의 데이터베이스를 내실화하도록 합시다, 아이테르.",
  ui_story_1013_10130901_19_dialog_content = "이건... 호의의 표현인가요?",
  ui_story_1013_10130901_20_dialog_content = "너랑 친하게 지내고 싶다는 거야.\n가디언 1호는 매우 우호적이고, 친화력 있는 인공지능이거든.",
  ui_story_1013_10130901_21_dialog_content = "몇 분만 기다려. 가디언 1호 접속에 필요한 프로그램을 입력할게.",
  ui_story_1013_10130901_22_dialog_content = "오류, 오류.",
  ui_story_1013_10130901_23_dialog_content = "접속 프로그램 입력에 실패했습니다.\n1호는 신분이 불분명한 사람과 접속할 수 없습니다.",
  ui_story_1013_10130901_24_dialog_content = "이건 또 무슨...",
  ui_story_1013_10130901_25_dialog_content = "<size=30>전에 약속했잖아? 현존하는 아이테르와 네 의식의 접속 실험을 하겠다고.\n내가 허가증에도 서명했잖아...</size>",
  ui_story_1013_10130901_26_dialog_content = "서로 얘기가 끝났던 게 아니었어요?!",
  ui_story_1013_10130901_27_dialog_content = "미, 미안. 가디언 1호는 무척 신중한 인공지능이거든.",
  ui_story_1013_10130901_28_dialog_content = "외부 확장 기능을 접속하려고 하면 항상 상세한 스캔을 실시해서 차단해.",
  ui_story_1013_10130901_29_dialog_content = "1호는 스스로 미지의 사물을 학습하고, 자신이 알고 있는 것을 분석합니다.",
  ui_story_1013_10130901_30_dialog_content = "1호는 미지의 아이테르의 데이터를 학습합니다.\n단, 1호가 알고 있는 아이테르에 관한 데이터베이스를 바탕으로...",
  ui_story_1013_10130901_31_dialog_content = "과거 분석 결과에 따라, 1호는 아이테르가 1호의 제어권을 획득하는 것을 허용하지 않습니다.",
  ui_story_1013_10130901_32_dialog_content = "그럼 지금이야말로 아이테르에 관한 데이터베이스를 업데이트할 절호의 기회 아냐?",
  ui_story_1013_10130901_33_dialog_content = "...알겠습니다. 아까 1호는 약속했습니다.\n이 아이테르와 서로 개념과 인식을 갱신하기로 했습니다.",
  ui_story_1013_10130901_34_dialog_content = "그럼 허락해 준다는 거야?",
  ui_story_1013_10130901_35_dialog_content = "1호는 엄격한 현장 테스트를 실시할 것입니다.\n이를 통해 아이테르의 능력에 대한 데이터를 기록하고 분석합니다.",
  ui_story_1013_10130901_36_dialog_content = "생성된 분석 결과를 바탕으로, 1호는 자신의 판단에 따라\n아이테르에게 1호의 제어권을 해방할지를 결정하겠습니다.",
  ui_story_1013_10130901_37_dialog_content = "어? 현장 테스트? 이 회의실에서?",
  ui_story_1013_10130901_38_dialog_content = "아이테르, 접속 모드를 실행해 주세요.",
  ui_story_1013_10130901_39_dialog_content = "(아! 나보고 감응을 하라는 거지?)",
  ui_story_1013_10130901_40_option_content = "(강제 감응!)",
  ui_story_1013_10130901_41_dialog_content = "<color=#e8d9bb>위이잉──</color>",
  ui_story_1013_10130901_42_dialog_content = "잠깐만!",
  ui_story_1013_10130901_43_dialog_content = "<color=#e8d9bb>위이잉...</color>",
  ui_story_1013_10130901_44_dialog_content = "아직...",
  ui_story_1013_10130901_45_dialog_content = "현장 테스트를 어떻게 하는지도 못 들었다고!",
  ui_story_1013_10130901_46_dialog_content = "<color=#e8d9bb>휘이잉── 휘이잉──</color>",
  ui_story_1013_10130901_47_dialog_content = "여긴 어디지...? 어라? 여긴 전장 시뮬레이터 안에서 왔던 곳이잖아?!",
  ui_story_1013_10130901_48_dialog_content = "여기가 바로 현장 테스트 장소입니다.",
  ui_story_1013_10130901_49_dialog_content = "누구야?!",
  ui_story_1013_10130901_50_dialog_content = "아이테르, 고개를 드는 동작을 실행하세요.",
  ui_story_1013_10130901_51_dialog_content = "1호는 위에 있습니다.",
  ui_story_1013_10130901_52_dialog_content = "어?!",
  ui_story_1013_10130901_53_dialog_content = "(까, 깜짝이야...)",
  ui_story_1013_10130901_54_dialog_content = "(그랬구나. 자세히 보니까 모의 전장 위쪽에\n현실 세계와의 경계가 있었네.)",
  ui_story_1013_10130901_55_dialog_content = "(반투명 돔 지붕 밖에 있는 태양처럼 큰 게 바로 센서겠지!)",
  ui_story_1013_10130901_56_dialog_content = "시뮬레이션 고대 전장에 오신 것을 환영합니다.\n1호는 아이테르의 실험 데이터를 실시간으로 기록합니다.",
  ui_story_1013_10130901_57_dialog_content = "최선을 다해서 1호에게 당신의 능력을 보여주세요, 아이테르.",
  ui_story_1013_10130901_58_dialog_content = "또? 이 고대 전장 기록, 설마 너네 일루미나 내부의 통용 데이터야?!",
  ui_story_1013_10130901_59_dialog_content = "(만약 이 모의 전장이 정말 통용 데이터라면, 스카이워커가 남긴 의식 데이터도...)",
  ui_story_1013_10130901_60_dialog_content = "(좋아. 그럼 이 기회를 잘 활용해야지!)",
  ui_story_1013_10130901_61_dialog_content = "아이테르, 지금 즉시 전장의 지형을 관찰하고 숙지하세요.\n1호는 곧 첫 번째 전투 데이터를 출력합니다.",
  ui_story_1013_10130901_62_dialog_content = "알겠어. 그 전에 부탁이 하나 있어.",
  ui_story_1013_10130901_63_dialog_content = "만약 테스트를 통과한다면, 이 고대 전장의 오늘 데이터 흐름을 좀 체크하고 싶어.",
  ui_story_1013_10130901_64_dialog_content = "그건...",
  ui_story_1013_10130901_65_dialog_content = "1호, 허가합니다. 신청이 유효합니다. 계약이 성립되었습니다.",
  ui_story_1013_10130901_66_dialog_content = "그럼 아이테르, 준비됐나요?",
  ui_story_1013_10130901_67_dialog_content = "전투 개시.",
  ui_story_1013_10130901_68_dialog_content = "스테이지 목표: 모든 암귀 처치.",
  ui_story_1013_10130901_69_dialog_content = "가디언 1호, 스테이지를 시작합니다.",
  ui_story_1013_10130901_70_dialog_content = "그렇다면...",
  ui_story_1013_10130901_71_dialog_content = "「바이스」, 「카렌」... 부탁할게!",
  ui_story_1013_10130901_72_dialog_content = "맡겨줘.",
  ui_story_1013_10130901_73_dialog_content = "문제없어!",
  ui_story_1013_10131002_1_dialog_content = "크에엑...",
  ui_story_1013_10131002_2_dialog_content = "스테이지 목표를 달성했습니다.",
  ui_story_1013_10131002_3_dialog_content = "테스트 종료, 스테이지 평점은 B입니다.",
  ui_story_1013_10131002_4_dialog_content = "미지의 정보를 입력하고 있습니다...",
  ui_story_1013_10131002_5_dialog_content = "아이테르의 전투 능력은 전략 및 인력 배치뿐입니다.",
  ui_story_1013_10131002_6_dialog_content = "아이테르는 오로리안을 조종하고 각종 전투 임무를 수행할 수 있습니다.",
  ui_story_1013_10131002_7_dialog_content = "네가 아는 개념과는 조금 다를 수 있지만, 지금 시대에서는 그리 드문 일이 아니야.",
  ui_story_1013_10131002_8_dialog_content = "알겠습니다. 아이테르에 대한 1호의 데이터베이스가 업데이트되었습니다.",
  ui_story_1013_10131002_9_dialog_content = "아이테르는 현장 테스트에 합격했습니다.",
  ui_story_1013_10131002_10_dialog_content = "1호는 계약에 따라 이 고대 전장의 데이터 흐름을 공개합니다.",
  ui_story_1013_10131002_11_dialog_content = "이제 곧 당신은 고대 전장을 떠날 것입니다. 이 전장은 사용 종료 후 파기됩니다.",
  ui_story_1013_10131002_12_dialog_content = "<color=#e8d9bb>위이잉──</color>",
  ui_story_1013_10131002_13_dialog_content = "잠깐만...",
  ui_story_1013_10131002_14_dialog_content = "이 고대 전장을 파기하지 마!",
  ui_story_1013_10131002_15_option_content = "(강제 감응!)",
  ui_story_1013_10131002_16_dialog_content = "아이테르, 지금의 당신의 행위는 오로리안의 언어로 「실례」입니다.",
  ui_story_1013_10131002_17_dialog_content = "당신은 1호의 인가를 받았지만, 1호는 부담 없이 접속 및 로그인해도 되는 존재가 아닙니다.",
  ui_story_1013_10131002_18_dialog_content = "감응이 끝나면 알골 씨한테 잘 보고할게.",
  ui_story_1013_10131002_19_dialog_content = "알겠습니다. 그럼 고대 전장의 데이터 파기를 막는 이유를 말해 주세요.",
  ui_story_1013_10131002_20_dialog_content = "당신은 이 일을 사전에 신청하지 않았습니다.",
  ui_story_1013_10131002_21_dialog_content = "1호는 모르겠습니다. 당신은 왜 데이터 흐름을 조사하고 저장하려는 것입니까?",
  ui_story_1013_10131002_22_dialog_content = "대체 무슨 계획이 있는 것입니까?",
  ui_story_1013_10131002_23_dialog_content = "사실...",
  ui_story_1013_10131002_24_dialog_content = "내 콜로서스가 지난번 모의 전투 중에 강제로 날 돕다가 고장이 났어.",
  ui_story_1013_10131002_25_dialog_content = "그래서 그의 의식 데이터가 이 고대 전장의 방대한 데이터 속에 남게 됐어.",
  ui_story_1013_10131002_26_dialog_content = "아이테르, 그것이 당신에게 무척 중요한가요?",
  ui_story_1013_10131002_27_option_content = "스카이워커는 내 가장 소중한 친구야.",
  ui_story_1013_10131002_28_dialog_content = "스카이워커는 단순히 자아의식을 가진 고대의 인공지능이 아니야.",
  ui_story_1013_10131002_29_dialog_content = "스카이워커의 의식과 기억의 데이터 속에는 우리 둘의 많은 추억이 담겨 있어.",
  ui_story_1013_10131002_30_dialog_content = "1호는 이해했습니다.",
  ui_story_1013_10131002_31_dialog_content = "미지의 정보를 입력하고 있습니다...",
  ui_story_1013_10131002_32_dialog_content = "아이테르에 대한 1호의 데이터베이스가 업데이트되었습니다.",
  ui_story_1013_10131002_33_dialog_content = "뭐야? 갑자기 둘이 좀 친해진 것 같은데?",
  ui_story_1013_10131002_34_dialog_content = "보고하겠습니다. 1호는 방금 아이테르와 짧은 접속을 실시했고,\n통상적인 테스트 결과 동기화를 진행했습니다.",
  ui_story_1013_10131002_35_dialog_content = "(1호가... 내가 강제 감응한 목적을 숨겨줬잖아...?)",
  ui_story_1013_10131002_36_dialog_content = "그래, 그럼 너도 이 아이테르에 대해 새로운 인식이 생긴 거겠네?",
  ui_story_1013_10131002_37_dialog_content = "그럼 전에 약속한 실험을 계속해도 될까?",
  ui_story_1013_10131002_38_dialog_content = "1호, 허가합니다.",
  ui_story_1013_10131002_39_dialog_content = "아이테르, 계약에 따라 오늘 고대 전장의 데이터를 당신의 단말기에 동기화했습니다.",
  ui_story_1013_10131002_40_dialog_content = "...고마워, 1호.",
  ui_story_1013_10131002_41_dialog_content = "그럼 본론으로 들어가자.",
  ui_story_1013_10131002_42_dialog_content = "아이테르, 가디언 1호는 감응을 통해 네가 고대 과학 기술을\n사용할 때의 데이터를 학습할 거야.",
  ui_story_1013_10131002_43_dialog_content = "그 학습 결과는 회의실의 이 디스플레이에 실시간으로 비춰질 거고.",
  ui_story_1013_10131002_44_dialog_content = "이건 일루미나의 과학 기술 혁신에 있어서 매우 중요한 일이야, 잘 부탁할게.",
  ui_story_1013_10131002_45_dialog_content = "노력할게요.",
  ui_story_1013_10131002_46_dialog_content = "아무래도 오늘은 많은 모의 전투를 체험한 모양이네.",
  ui_story_1013_10131002_47_dialog_content = "이번엔 나도 옆에서 보고 있을 순 없어. 그러니 혼자서 방심하지 않는 게 좋아.",
  ui_story_1013_10131002_48_dialog_content = "라인하르트 씨, 걱정 마세요. 그리고 엄밀히 말하자면 전 혼자가 아닌걸요.",
  ui_story_1013_10131002_49_dialog_content = "1호, 연결 준비 완료.",
  ui_story_1013_10131002_50_dialog_content = "(평등한 마음가짐으로 과학 기술을 이해할 수 있다는 것이\n너와 우리 과학자들 사이의 가장 큰 차이점이겠지.)",
  ui_story_1013_10131002_51_dialog_content = "(비록 연구소의 기술력이 최근 계속해서 발전하긴 했지만...)",
  ui_story_1013_10131002_X51_dialog_content = "(그런 마음가짐이 없다면 기술력의 정점에 있는 그 문턱을 넘을 수 없을 거다.)",
  ui_story_1013_10131002_52_dialog_content = "(부디 저들이 이번 실험을 통해서 그걸 이해해 줬으면 좋겠는데 말이지.)",
  ui_story_1013_10131002_53_dialog_content = "그럼 1호, 내 의식을 믿어줘.",
  ui_story_1013_10131002_54_option_content = "[강제 감응]",
  ui_story_1013_10131002_55_dialog_content = "이게 1호의 의식 공간...?",
  ui_story_1013_10131002_56_dialog_content = "아이테르, 1호는 여기 있습니다.",
  ui_story_1013_10131002_57_dialog_content = "환영합니다!",
  ui_story_1013_10131002_58_dialog_content = "여기에는 알골 교수의 명령이 없습니다. 편안하게 계세요.",
  ui_story_1013_10131002_59_dialog_content = "그, 그럼 실례할게!",
  ui_story_1013_10131002_60_dialog_content = "(꼭 소꿉놀이 하는 어린애 같잖아...)",
  ui_story_1013_10131002_61_dialog_content = "아이테르, 당신의 의식은 불안정합니다. 콜로서스의 걱정을 하고 있군요.",
  ui_story_1013_10131002_62_dialog_content = "(우와, 똑똑하네... 역시 일루미나 전체의 운영을 담당하는 인공지능이라 이건가...)",
  ui_story_1013_10131002_63_dialog_content = "아이테르, 이번 학습 실험의 난이도를 높여볼까요? 당신은 1호를 믿나요?",
  ui_story_1013_10131002_64_dialog_content = "그거야 당연하지. 믿으니까 너랑 「접속」한 거야...",
  ui_story_1013_10131002_65_dialog_content = "신용 인증을 완료했습니다.\n이제 1호는 콜로서스의 신호를 검색하고 콜로서스와 접속을 진행합니다.",
  ui_story_1013_10131002_66_dialog_content = "뭐, 뭐라고?!",
  ui_story_1013_10131002_67_dialog_content = "아이테르가 1호를 신용한다면, 1호는 콜로서스의 신호를 검색하고\n콜로서스와 접속을 진행합니다.",
  ui_story_1013_10131002_68_dialog_content = "(1호는... 스카이워커를 도울 방법을 생각해 주고 있는 건가?)",
  ui_story_1013_10131002_69_dialog_content = "(1호가 말하는 대로 하는 게 좋을까...)",
  ui_story_1013_10131002_70_dialog_content = "아이테르는 망설이고 있습니다.",
  ui_story_1013_10131002_71_dialog_content = "스마트 파스 트리를 실행합니다...",
  ui_story_1013_10131002_72_dialog_content = "가설 1: 1호가 콜로서스와의 접속에 성공해 콜로서스의 신호를 획득합니다.",
  ui_story_1013_10131002_73_dialog_content = "결과: 콜로서스의 의식 데이터를 무사히 회수하고, 콜로서스는 의식을 회복합니다.",
  ui_story_1013_10131002_74_dialog_content = "가설 2: 1호가 콜로서스와의 접속에 성공해 콜로서스의 신호를 획득하고,\n콜로서스 데이터의 임의 변조를 시도합니다.",
  ui_story_1013_10131002_75_dialog_content = "결과: 아이테르는 1호와 콜로서스의 어댑터로서 즉시 접속을 끊고,\n콜로서스는 현재 상태를 유지합니다.",
  ui_story_1013_10131002_76_dialog_content = "가설 3...",
  ui_story_1013_10131002_77_dialog_content = "아, 알겠어... 가설은 이제 됐어!",
  ui_story_1013_10131002_78_dialog_content = "네가 하고 싶은 말은 알았어. 지금 나한테 더 좋은 다른 방법은 없다는 거잖아.",
  ui_story_1013_10131002_79_dialog_content = "고마워, 1호. 콜로서스를 위해서 이런 것까지 해 줘서.",
  ui_story_1013_10131002_80_dialog_content = "아이테르와 고대의 인공지능은 친구입니다.",
  ui_story_1013_10131002_81_dialog_content = "1호도 고대의 인공지능입니다.",
  ui_story_1013_10131002_82_dialog_content = "응, 그럼 나머지는 부탁할게!",
  ui_story_1013_10131002_83_dialog_content = "저 모의 고대 전장으로 돌아가서 스카이워커의 의식을 구해주자.",
  ui_story_1013_10131002_84_dialog_content = "1호 준비 완료, 카운트다운을 시작합니다...",
  ui_story_1013_10131002_85_dialog_content = "3...",
  ui_story_1013_10131002_86_dialog_content = "2...",
  ui_story_1013_10131002_87_dialog_content = "1...",
  ui_story_1013_10131101_1_dialog_content = "조심하세요. 가상 전장은 매우 불안정합니다.",
  ui_story_1013_10131101_2_dialog_content = "예상치 못한 충격에 대응할 준비를 해 두세요.",
  ui_story_1013_10131101_3_dialog_content = "괜찮아. 여긴 와 봤거든.",
  ui_story_1013_10131101_4_dialog_content = "근데 왠지 저번이랑은 좀 다른 것 같네.",
  ui_story_1013_10131101_5_dialog_content = "가상 전장은 항상 자율 가동 중입니다. 당연히 시간도 경과하고 있습니다.",
  ui_story_1013_10131101_6_dialog_content = "근데 이해가 안 되는 게 있어. 여긴 가상의 전장이잖아.\n근데 스카이워커의 의식이 어떻게 여기 갇혀 있을 수 있는 거야?",
  ui_story_1013_10131101_7_dialog_content = "스카이워커호의 의식은 데이터입니다. 가상 전장도 데이터입니다.",
  ui_story_1013_10131101_8_dialog_content = "스카이워커호의 의식이 가상 전장에 간섭했기 때문에,\n양쪽의 데이터가 혼재되어 버린 것입니다.",
  ui_story_1013_10131101_9_dialog_content = "가상 전장이 자율 파기를 실시하기 전에 스카이워커호에 액세스해야 합니다.",
  ui_story_1013_10131101_10_dialog_content = "그렇지 않으면 가상 전장의 자율 파기와 동시에\n스카이워커호의 데이터도 파기되어 버립니다.",
  ui_story_1013_10131101_11_dialog_content = "파기?! 그러니까... 스카이워커의 의식이 사라져 버릴 수도 있다는 거야?",
  ui_story_1013_10131101_12_dialog_content = "사라지는 것은 아닙니다. 대신 액세스 포트가 없어져 버립니다.",
  ui_story_1013_10131101_13_dialog_content = "현실 세계의 일로 설명하자면, 이 가상 전장의 폐허 속에 묻혀 버리게 되는 것입니다.",
  ui_story_1013_10131101_14_dialog_content = "의식 데이터는 계속 존재합니다.\n하지만 누구도 그게 어디 있는지 모르게 됩니다.",
  ui_story_1013_10131101_15_dialog_content = "어째서... 그럼 가상 전장은 왜 자율 파기를 하는 건데?",
  ui_story_1013_10131101_16_dialog_content = "가상 전장이 기록하고 있는 사건은 매우 특수합니다.",
  ui_story_1013_10131101_17_dialog_content = "어딘가로 퇴출하는 것이 아니라 항상 데이터를 파기하고 있습니다.",
  ui_story_1013_10131101_18_dialog_content = "가상 전장 내의 데이터가 모두 없어지고 나면 즉시 자신의 파기를 실행합니다.",
  ui_story_1013_10131101_19_dialog_content = "특수한 사건이라... 분명히 저 과학자들도 그랬어. 문명은 한 번 멸망한 적이 있다고...",
  ui_story_1013_10131101_20_dialog_content = "그럼 우리가 지금 보고 있는... 이 가상 전장이 기록한 게\n바로 문명이 망하는 모습인 거야?",
  ui_story_1013_10131101_21_dialog_content = "연산에 따르면 대다수의 생명체는 존속할 수 없었습니다.\n문명이 망했다는 표현은 합리적입니다.",
  ui_story_1013_10131101_22_dialog_content = "어쩐지 그런 광경이 보인다 했어.",
  ui_story_1013_10131101_23_dialog_content = "캬악──",
  ui_story_1013_10131101_24_dialog_content = "으아아아아아아악!",
  ui_story_1013_10131101_25_dialog_content = "인류도 죽고, 암귀조차 살아남지 못했어.",
  ui_story_1013_10131101_26_dialog_content = "그런 세상이 멸망하는 건 당연할지도...",
  ui_story_1013_10131101_27_dialog_content = "<color=#e8d9bb>콰직──</color>",
  ui_story_1013_10131101_28_dialog_content = "!!!",
  ui_story_1013_10131101_29_dialog_content = "<color=#e8d9bb>콰직, 콰직──</color>",
  ui_story_1013_10131101_30_dialog_content = "그, 어어...",
  ui_story_1013_10131101_31_dialog_content = "암귀?! 이미 종말과 함께 없어졌을 줄 알았는데...",
  ui_story_1013_10131101_32_dialog_content = "설마 아직도 살아 있는 암귀가 있다니...",
  ui_story_1013_10131101_33_dialog_content = "그, 근데 뭐 하는 거지?",
  ui_story_1013_10131101_34_dialog_content = "암귀가 철근을 먹고 있습니다.",
  ui_story_1013_10131101_35_dialog_content = "<color=#e8d9bb>콰직, 콰직──</color>",
  ui_story_1013_10131101_36_dialog_content = "왜 저러는 건데?",
  ui_story_1013_10131101_37_dialog_content = "아무리 먹을 게 없어도, 철근보다 더 씹기 쉬운 것도 많을 거잖아?\n땅에 굴러다니는 돌이라든지 말이야.",
  ui_story_1013_10131101_38_dialog_content = "연산을 통해 추측하자면, 암귀는 철근의 성질을 원합니다.",
  ui_story_1013_10131101_39_dialog_content = "성질?",
  ui_story_1013_10131101_40_dialog_content = "철근은 종말의 날에도 사라지지 않았습니다.",
  ui_story_1013_10131101_41_dialog_content = "암귀는 철근을 섭취해서 유사한 성질을 얻으려고 합니다.",
  ui_story_1013_10131101_42_dialog_content = "그, 그런 게 가능하단 말이야?",
  ui_story_1013_10131101_43_dialog_content = "추측일 뿐입니다. 하지만 암귀가 종말의 날에도 살아남은 건 사실입니다.",
  ui_story_1013_10131101_44_dialog_content = "게다가 그 수도 적지 않습니다.",
  ui_story_1013_10131101_45_dialog_content = "<color=#e8d9bb>콰직, 콰직──</color>",
  ui_story_1013_10131101_46_dialog_content = "<color=#e8d9bb>콰직──!</color>",
  ui_story_1013_10131101_47_dialog_content = "그어어어!",
  ui_story_1013_10131101_48_dialog_content = "뭐야, 동족까지 먹는 거야?!",
  ui_story_1013_10131101_49_dialog_content = "암귀는 살아남기 위해 인류보다 더 많은 일을 했습니다.",
  ui_story_1013_10131101_50_dialog_content = "그래서 인류가 만든 이 도시에 지금은 암귀들만 살고 있는 것입니다.",
  ui_story_1013_10131101_51_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_1013_10131101_52_dialog_content = "이렇게 많다니...",
  ui_story_1013_10131101_53_dialog_content = "지면에 암귀 시체가 잔뜩 있어. 끝없이 죽어가면서도 계속해서 새로 태어나고 있어.",
  ui_story_1013_10131101_54_dialog_content = "그렇습니다. 「진화」는 단일 개체로 완성할 수 있는 것이 아닙니다.\n그래서 암귀는 빠르게 세대교체를 하는 길을 선택한 것입니다.",
  ui_story_1013_10131101_55_dialog_content = "종말의 극한 환경에 적응할 수 있을 때까지,\n암귀는 죽음을 쌓고, 종족의 유전자를 개량하고 있는 것입니다.",
  ui_story_1013_10131101_56_dialog_content = "잠깐만, 이 암귀들... 어딘가로 모이고 있는 것 같은데?",
  ui_story_1013_10131101_57_dialog_content = "그렇습니다. 암귀들은 같은 방향으로 가고 있습니다.\n무언가가 저들을 유인하고 있습니다.",
  ui_story_1013_10131101_58_dialog_content = "유인해? 설마...!",
  ui_story_1013_10131101_59_option_content = "(강제 감응!)",
  ui_story_1013_10131101_60_dialog_content = "스카이워커! 스카이워커의 의식 데이터가 저쪽에 있어!",
  ui_story_1013_10131101_61_dialog_content = "그랬군요. 가상 전장에 속하지 않는 비정상 데이터는 유난히 눈에 띄기 마련입니다.",
  ui_story_1013_10131101_62_dialog_content = "그래서 암귀들은 비정상 데이터가 있는 쪽으로 모여들고 있는 것 같습니다.",
  ui_story_1013_10131101_63_dialog_content = "스카이워커를 찾으면 고장도 해결할 수 있는 거지?!",
  ui_story_1013_10131101_64_dialog_content = "스카이워커호에 접속하면 고장을 조사할 수 있습니다.\n고칠 수 있을지는 지금은 알 수 없습니다.",
  ui_story_1013_10131101_65_dialog_content = "알았어. 그렇게 신중하게 굴 거 없어. 아무튼 스카이워커한테 가야지!",
  ui_story_1013_10131101_66_dialog_content = "다행히 여긴 전장 시뮬레이터야. 나도 암귀와 싸울 수 있는 힘이 있어.",
  ui_story_1013_10131101_67_dialog_content = "받아라!",
  ui_story_1013_10131101_68_dialog_content = "<color=#e8d9bb>퍼엉── 콰앙──!</color>",
  ui_story_1013_10131101_69_dialog_content = "왜 이렇게 소리가 커?! 뭐가 무너졌나?",
  ui_story_1013_10131101_70_dialog_content = "당신 근처에 있는 건물이 무너지고 있습니다.",
  ui_story_1013_10131101_71_dialog_content = "조심하세요. 현재 가상 전장은 불안정합니다.\n공격의 파동은 이 세계의 붕괴를 가속하기 쉽습니다.",
  ui_story_1013_10131101_72_dialog_content = "으앗! 진짜로 뭐가 떨어졌어!",
  ui_story_1013_10131101_73_dialog_content = "<color=#e8d9bb>와르르르!</color>",
  ui_story_1013_10131101_74_dialog_content = "콜록콜록... 먼지가 엄청 심하네...",
  ui_story_1013_10131101_75_dialog_content = "아직 별로 공격하지 않았는데... 이 세상 너무 약한 거 아냐?!",
  ui_story_1013_10131101_76_dialog_content = "대체 왜...",
  ui_story_1013_10131101_77_dialog_content = "전장 자체의 문제로 인해 데이터가 매우 불안정합니다.\n누가 손을 대지 않아도 스스로 붕괴할 것입니다.",
  ui_story_1013_10131101_78_dialog_content = "반대쪽을 주의하세요.",
  ui_story_1013_10131101_79_dialog_content = "!!!",
  ui_story_1013_10131101_80_dialog_content = "<color=#e8d9bb>와르르르!</color>",
  ui_story_1013_10131101_81_dialog_content = "으앗, 이래서는 끝이 없잖아!",
  ui_story_1013_10131101_82_dialog_content = "조심하세요. 세계의 붕괴는 가상 전장 자율 파기의 구체화된 표현입니다.",
  ui_story_1013_10131101_83_dialog_content = "그리고 가상 전장의 데이터 파기는...",
  ui_story_1013_10131101_84_dialog_content = "스카이워커 데이터의 파기를 초래한다는 거지?",
  ui_story_1013_10131101_85_dialog_content = "맞아요, 당신은 이 내용을 이해한 것 같군요.",
  ui_story_1013_10131101_86_dialog_content = "아무래도 투덜거릴 시간도 없는 모양이네.",
  ui_story_1013_10131101_87_dialog_content = "이 세상이 완전히 붕괴되기 전에 어떻게든 스카이워커 곁으로 가야 해!",
  ui_story_1013_10131202_1_dialog_content = "30.",
  ui_story_1013_10131202_2_dialog_content = "<color=#e8d9bb>쿠르릉──!</color>",
  ui_story_1013_10131202_3_dialog_content = "으아아앗!",
  ui_story_1013_10131202_4_dialog_content = "떨어질 뻔했잖아...",
  ui_story_1013_10131202_5_dialog_content = "뭐야? 지면의 균열이 쫓아오잖아?!",
  ui_story_1013_10131202_6_dialog_content = "당신이 붕괴를 유발한 원인 중 하나이기 때문입니다.",
  ui_story_1013_10131202_7_dialog_content = "25.",
  ui_story_1013_10131202_8_dialog_content = "뭐? 아니, 자, 잠깐만... 너... 그 불길하게 만드는 숫자는 뭐야?!",
  ui_story_1013_10131202_9_dialog_content = "당신에게 남은 시간입니다.",
  ui_story_1013_10131202_10_dialog_content = "가상 전장 데이터를 읽어와 붕괴 곡선을 도출했습니다. 정확한 숫자임을 보장합니다.",
  ui_story_1013_10131202_11_dialog_content = "그럼 20 몇초 남은 거야?! 너무...",
  ui_story_1013_10131202_12_dialog_content = "<color=#e8d9bb>콰앙──!</color>",
  ui_story_1013_10131202_13_dialog_content = "20.",
  ui_story_1013_10131202_14_dialog_content = "알았어! 20초면 충분해!",
  ui_story_1013_10131202_15_dialog_content = "스카이워커는 바로 코앞이야, 느껴져!",
  ui_story_1013_10131202_16_dialog_content = "암귀를 경계하는 것도 잊어서는 안 됩니다.",
  ui_story_1013_10131202_17_dialog_content = "으으, 귀찮아 죽겠네!",
  ui_story_1013_10131202_18_dialog_content = "방해하지 마...!",
  ui_story_1013_10131202_19_dialog_content = "<color=#e8d9bb>쿠르릉──!</color>",
  ui_story_1013_10131202_20_dialog_content = "으아아아아아!",
  ui_story_1013_10131202_21_dialog_content = "<color=#e8d9bb>콰아앙!</color>",
  ui_story_1013_10131202_22_dialog_content = "콜록... 콜록콜록...",
  ui_story_1013_10131202_23_dialog_content = "아파...",
  ui_story_1013_10131202_24_dialog_content = "1호, 남은 시간은...?",
  ui_story_1013_10131202_25_dialog_content = "10.",
  ui_story_1013_10131202_26_dialog_content = "이런... 움직여, 어서...",
  ui_story_1013_10131202_27_dialog_content = "스카이워커한테... 이제 얼마 안 남았어...",
  ui_story_1013_10131202_28_dialog_content = "바로 코앞이야...",
  ui_story_1013_10131202_29_dialog_content = "5.",
  ui_story_1013_10131202_30_dialog_content = "콜록...",
  ui_story_1013_10131202_31_dialog_content = "4.",
  ui_story_1013_10131202_32_dialog_content = "다 왔어, 다 왔어...",
  ui_story_1013_10131202_33_dialog_content = "3.",
  ui_story_1013_10131202_34_dialog_content = "하아... 하아...",
  ui_story_1013_10131202_35_dialog_content = "2.",
  ui_story_1013_10131202_36_dialog_content = "<color=#e8d9bb>쿠르릉...</color>",
  ui_story_1013_10131202_37_dialog_content = "1.",
  ui_story_1013_10131202_38_dialog_content = "(강제 감응!)",
  ui_story_1013_10131202_39_dialog_content = "스카이워커, 너야?",
  ui_story_1013_10131202_40_dialog_content = "......",
  ui_story_1013_10131202_41_dialog_content = "찾았어, 찾았다고!",
  ui_story_1013_10131202_42_dialog_content = "어때? 안 늦었지?",
  ui_story_1013_10131202_43_dialog_content = "얼른 스카이워커랑 접속해!",
  ui_story_1013_10131202_44_dialog_content = "스카이워커호의 데이터 포트에 액세스합니다.",
  ui_story_1013_10131202_45_dialog_content = "액세스 신청에 응답이 없습니다. 강제 액세스를 실행합니다.",
  ui_story_1013_10131202_46_dialog_content = "준비하세요. 이제 당신의 의식은 곧 스카이워커호의 데이터 공간으로 진입합니다.",
  ui_story_1013_10131202_47_dialog_content = "1호는 데이터 공간 안이 어떤 상황인지 예측할 수 없습니다.",
  ui_story_1013_10131202_48_dialog_content = "물론 준비돼 있어. 지금보다 더 힘들진 않을 거 아냐?",
  ui_story_1013_10131202_49_dialog_content = "데이터 전이를 시작합니다.",
  ui_story_1013_10131202_50_dialog_content = "스카이워커호, 로그인.",
  ui_story_1013_10131202_51_dialog_content = "우와, 깜깜하네... 우리 안에 들어온 거야?",
  ui_story_1013_10131202_52_dialog_content = "네, 들어왔습니다. 아무것도 보이지 않는다면 눈을 떠 보세요.",
  ui_story_1013_10131202_53_dialog_content = "어?",
  ui_story_1013_10131202_54_dialog_content = "우와, 보였어! 근데 잠깐만. 왜 눈을 뜬다는 것까지 네가 말하지 않으면 몰랐을까?",
  ui_story_1013_10131202_55_dialog_content = "정상적인 현상입니다. 전장 시뮬레이션이 종료되었을 때 당신은 눈을 뜨고 있었습니다.",
  ui_story_1013_10131202_56_dialog_content = "그래서 의식 속 당신은 눈은 뜬 상태였습니다.\n다시 눈을 뜨려는 생각은 당연히 하지 않습니다.",
  ui_story_1013_10131202_57_dialog_content = "그러나 새로운 데이터 공간에서는 제가 당신에게 새로운 신체를 준비했습니다.\n그 몸의 눈은 감긴 상태였습니다.",
  ui_story_1013_10131202_58_dialog_content = "신체와 의식 사이의 모순이 조금 전의 현상을 일으킨 것입니다.",
  ui_story_1013_10131202_59_dialog_content = "그렇구나...",
  ui_story_1013_10131202_60_dialog_content = "이해하셨나요? 다시 설명할 필요는...",
  ui_story_1013_10131202_61_dialog_content = "이해했어! 잘 이해했어!",
  ui_story_1013_10131202_62_dialog_content = "저게 스카이워커야?",
  ui_story_1013_10131202_X62_dialog_content = "가까이 있는데 왠지 만질 수가 없는 것 같아.",
  ui_story_1013_10131202_X63_dialog_content = "여긴 어디야?",
  ui_story_1013_10131202_63_dialog_content = "시각으로 말하자면 당신이 보고 있는 것은 확실히 스카이워커호의 내부입니다.",
  ui_story_1013_10131202_64_dialog_content = "하지만 더 정확하게 말하자면, 이곳은 스카이워커호의 데이터 저장 공간입니다.",
  ui_story_1013_10131202_65_dialog_content = "즉, 스카이워커호의 「기억」입니다.",
  ui_story_1013_10131202_66_dialog_content = "기억?",
  ui_story_1013_10131202_67_dialog_content = "왜 기억 속에 들어온 건데? 우린 스카이워커의 고장을 해결하려는 거 아니었어?",
  ui_story_1013_10131202_68_dialog_content = "맞습니다. 스카이워커호가 고장난 것은 무질서한 데이터가\n저장 공간으로 파고든 것이 원인입니다.",
  ui_story_1013_10131202_69_dialog_content = "우리가 해야 할 일은 방대한 데이터 속에서 그 무질서한 데이터를\n찾아내고 복구하는 것입니다.",
  ui_story_1013_10131202_70_dialog_content = "1호에게 있어 그 작업은 그저 단순한 데이터 처리일 뿐입니다.",
  ui_story_1013_10131202_71_dialog_content = "그러나 당신은 뇌를 사용해서 직접 데이터를 처리할 수 없습니다.\n따라서 당신이 상상력을 통해 데이터를 가시화할 수 있도록 돕겠습니다.",
  ui_story_1013_10131202_72_dialog_content = "저장되어 있던 기억은 화면의 형태가 되고,\n무질서한 데이터는 비정상적인 형상으로 나타납니다.",
  ui_story_1013_10131202_73_dialog_content = "다음 과정에서는 1호가 당신과 함께 스카이워커호의 기억을 체크합니다.",
  ui_story_1013_10131202_74_dialog_content = "그중에서 고장을 일으킨 무질서한 데이터를 찾아냅니다.",
  ui_story_1013_10131202_75_dialog_content = "무질서한 데이터를 내가 알아볼 수 있어?",
  ui_story_1013_10131202_76_dialog_content = "그것들은 당신의 상상력에 따라 당신이 싫어하거나 적대시하는 형상이 될 것입니다.\n분명히 알아볼 수 있을 것입니다.",
  ui_story_1013_10131202_77_dialog_content = "아, 그렇구나. 그럼 쉬울 것 같은데?",
  ui_story_1013_10131202_78_dialog_content = "1호는 예측할 수 없습니다.",
  ui_story_1013_10131202_79_dialog_content = "알겠어. 그럼 일단 해보는 수밖에 없겠네.",
  ui_story_1013_10131202_X79_dialog_content = "데이터 접근, 스카이워커호의 선실로 이동합니다.",
  ui_story_1013_10131202_X80_dialog_content = "휴, 이젠 좀 익숙하네!",
  ui_story_1013_10131202_80_dialog_content = "그나저나 이건 스카이워커의 언제 기억인 거지?",
  ui_story_1013_10131202_81_dialog_content = "주변에서는 아무 일도 일어나지 않았어. 너무 심하게 조용하잖아.",
  ui_story_1013_10131202_82_dialog_content = "우린 지금 어디 있는 거야? 그러니까 이 기억 속의 스카이워커는 어디 있는 거야?",
  ui_story_1013_10131202_83_dialog_content = "1호는 이 데이터에 대해 잘 모릅니다.",
  ui_story_1013_10131202_84_dialog_content = "그것도 그렇네. 뭐든지 다 너한테 물어보면 안 되는 거잖아.",
  ui_story_1013_10131202_85_dialog_content = "스카이워커라면 내가 누구보다 잘 아니까, 일단 나가서 조사해 볼게.",
  ui_story_1013_10131202_86_dialog_content = "<color=#e8d9bb>뚜벅, 뚜벅, 뚜벅...</color>",
  ui_story_1013_10131202_87_dialog_content = "어라? 선실 문이 왜 다 잠겨 있지?",
  ui_story_1013_10131202_88_dialog_content = "어디 보자, 여기를 열면...",
  ui_story_1013_10131202_89_dialog_content = "<color=#e8d9bb>삐! 삐! 삐! 삐!</color>",
  ui_story_1013_10131202_90_dialog_content = "웬 경고음?! 무슨 뜻이지?",
  ui_story_1013_10131202_91_dialog_content = "스카이워커, 날 가둬두려는 거야?",
  ui_story_1013_10131202_92_dialog_content = "검사 결과 스카이워커호와 외부의 기체 교환이 이루어지지 않고 있습니다.\n선실은 완전히 밀폐되어 있습니다.",
  ui_story_1013_10131202_93_dialog_content = "대체 무슨 상황이지...?",
  ui_story_1013_10131202_94_dialog_content = "맞아, 컨트롤러에 기록이 있을 거야.",
  ui_story_1013_10131202_95_dialog_content = "어디 보자... 현재 위치의... 좌표는...",
  ui_story_1013_10131202_96_dialog_content = "?!",
  ui_story_1013_10131202_97_dialog_content = "위치 정보가 없잖아?",
  ui_story_1013_10131202_98_dialog_content = "다른 정보도... 없는데?!",
  ui_story_1013_10131202_99_dialog_content = "왜 컨트롤러에 기록된 정보가 이렇게 적은 거지?",
  ui_story_1013_10131202_100_dialog_content = "여기는 스카이워커호의 기억입니다.\n일부 데이터는 당시에 존재했더라도, 이후 삭제되었을 수 있습니다.",
  ui_story_1013_10131202_101_dialog_content = "아무 일도 일어나지 않았고, 정보도 기록되지 않았어... 꽤 쓸쓸한 기억이네.",
  ui_story_1013_10131202_102_dialog_content = "스카이워커한테 왜 이런 기억이 있는 걸까?",
  ui_story_1013_10131202_103_dialog_content = "기계의 기억은 사람의 기억과는 다릅니다.",
  ui_story_1013_10131202_104_dialog_content = "스카이워커호에게 이러한 기억이 있는 것은 기억할 필요가 있어서가 아니라,\n단순히 그러한 일이 일어났기 때문입니다.",
  ui_story_1013_10131202_105_dialog_content = "스카이워커는 기계가 아니야! 스카이워커는...",
  ui_story_1013_10131202_106_dialog_content = "아, 맞다, 너도...",
  ui_story_1013_10131202_107_dialog_content = "...미안, 기계가 나쁘다는 뜻은 아니었어.",
  ui_story_1013_10131202_108_dialog_content = "1호는 당신이 왜 사과하는지 모르겠습니다.",
  ui_story_1013_10131202_109_dialog_content = "모르면 됐어! 더 좋아! 난 원래 사과를 좋아하는 성격이거든. 아하하, 하하...",
  ui_story_1013_10131202_110_dialog_content = "?",
  ui_story_1013_10131202_111_dialog_content = "크흠, 아무튼 그건 그렇고, 난 어디 기록 정보가 있는지 더 찾아봐야겠어.",
  ui_story_1013_10131202_112_dialog_content = "정보라면 1호가 일부 발견했습니다.",
  ui_story_1013_10131202_113_dialog_content = "뭐? 어디서?",
  ui_story_1013_10131202_114_dialog_content = "「단말기」라고 불리는 곳입니다.",
  ui_story_1013_10131202_115_dialog_content = "이건...",
  ui_story_1013_10131202_116_dialog_content = "■■■■■■■■■■■■",
  ui_story_1013_10131202_117_dialog_content = "이게 뭐야?",
  ui_story_1013_10131202_118_dialog_content = "아마 고대 문자일 것입니다.",
  ui_story_1013_10131202_119_dialog_content = "잠시만 기다려 주세요. 스카이워커호는 번역 방법을 기록해 두었습니다.",
  ui_story_1013_10131202_120_dialog_content = "당신도 알 수 있는 문자로 변환하겠습니다.",
  ui_story_1013_10131202_121_dialog_content = "「지상에서 보내온 정보를 수신했다. 아마 이게 마지막일 거다.」",
  ui_story_1013_10131202_122_dialog_content = "「탑의 도시는 멸망했다.」",
  ui_story_1013_10131202_123_dialog_content = "뭐라고요? 그런... 어떻게 그럴 수가 있죠?",
  ui_story_1013_10131202_124_dialog_content = "휴, 어차피 그렇게 될 운명이었어. 지상은 어디든 멸망하고 있어.\n탑의 도시만 무사할 리가 없잖아.",
  ui_story_1013_10131202_125_dialog_content = "우리가 출발한 순간부터 결과는 이미 정해져 있었다고.",
  ui_story_1013_10131202_126_dialog_content = "그럼 우린 어디로 돌아가?",
  ui_story_1013_10131202_127_dialog_content = "걱정 마라. 프란츠 선생님께서 말씀하셨잖아.\n돌아갈 때가 되면 신호를 받을 거라고 말이다.",
  ui_story_1013_10131202_128_dialog_content = "선생님은 모든 계획을 세워 두셨고, 우린 선생님을 믿는다. 그렇지?",
  ui_story_1013_10131202_129_dialog_content = "응, 믿어.",
  ui_story_1013_10131202_130_dialog_content = "어차피 다른 선택지도 없잖아? 믿을 수밖에.",
  ui_story_1013_10131202_131_dialog_content = "참, 그것보다 묻고 싶은 게 있는데요.\n우린 언제쯤 자기 콜로서스 밖으로 나갈 수 있을까요?",
  ui_story_1013_10131202_132_dialog_content = "콜로서스에 혼자만 있으니까 미쳐버릴 것 같단 말이에요.",
  ui_story_1013_10131202_133_dialog_content = "다른 사람들이 보고 싶어요. 이렇게 가까이 있는데 왜 볼 수가 없는 거죠?",
  ui_story_1013_10131202_134_dialog_content = "제 여동생이 너무 보고 싶어요. 여동생은 지금 당신 콜로서스에 있죠? 그, 저기...",
  ui_story_1013_10131202_135_dialog_content = "미안해요, 217번. 당신 이름을 잊어버렸어요.",
  ui_story_1013_10131202_136_dialog_content = "그래. 네 여동생은 괜찮으니 안심해라.",
  ui_story_1013_10131202_137_dialog_content = "하지만 지금은 아직 자기 콜로서스를 떠나서는 안 된다. 절대로 안 돼.",
  ui_story_1013_10131202_138_dialog_content = "절대로 바보 같은 짓은 하지 마라. 널 해치게 될 뿐이니까.",
  ui_story_1013_10131202_139_dialog_content = "바보짓을 안 하면 또 할 수 있는 게 뭐가 있는데?",
  ui_story_1013_10131202_140_dialog_content = "이젠 밥 먹는 것도 지겨워. 그러다 자는 것까지 지겨워지면\n그땐 진짜 뭘 해야 될지 모르겠다고.",
  ui_story_1013_10131202_141_dialog_content = "여긴 아무것도 없어. 게다가 애초에도 없다시피 했던\n외부의 정보도 앞으로 다시는 없을 거잖아.",
  ui_story_1013_10131202_142_dialog_content = "매일 단말기나 쳐다보면서 번호로 불러야 하는 너희랑만 얘기하겠지.",
  ui_story_1013_10131202_143_dialog_content = "그러다 언젠가 다들 79번처럼 다른 사람들 이름을 잊어버리고, 숫자만 남을 거야.",
  ui_story_1013_10131202_144_dialog_content = "아니야! 난 너 이름 알아! 파커잖아!",
  ui_story_1013_10131202_145_dialog_content = "다른 사람들 이름도 안 잊어버릴 거야! 아이테르는 절대 번호로 서로를 부르지 않아!",
  ui_story_1013_10131202_146_dialog_content = "됐으니까 그냥 빨리 잊어버려.",
  ui_story_1013_10131202_147_dialog_content = "애써 고집부려봤자 좋을 게 하나도 없어.\n그래봤자 진짜로 잊어버리게 됐을 때 네 고통만 커질 뿐이니까.",
  ui_story_1013_10131202_148_dialog_content = "쓰이지도 않는 호칭을 오늘은 기억하겠지. 한 달 뒤에도 기억할 수 있겠지.",
  ui_story_1013_10131202_149_dialog_content = "근데 1년 뒤는? 10년 뒤에는?",
  ui_story_1013_10131202_150_dialog_content = "10년? 그, 그건 너무 멀잖아...",
  ui_story_1013_10131202_151_dialog_content = "우리 이대로 10년이나 있어야 돼?",
  ui_story_1013_10131202_152_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_1013_10131202_153_dialog_content = "우, 우리 다시 돌아갈 수 있는 거지?",
  ui_story_1013_10131202_154_dialog_content = "그래, 우린 돌아갈 거다.",
  ui_story_1013_10131202_155_dialog_content = "돌아갈 때가 되면 신호를 받을 거라고 프란츠 선생님께서 말씀하셨다.",
  ui_story_1013_10131202_156_dialog_content = "우린 선생님을 믿는다. 그렇지?",
  ui_story_1013_10131301_1_dialog_content = "...이건 아이테르들의 대화 기록이잖아?!",
  ui_story_1013_10131301_2_dialog_content = "우리 주변에 다른 콜로서스가 있어?",
  ui_story_1013_10131301_3_dialog_content = "충분한 정보를 수집할 수 없습니다.",
  ui_story_1013_10131301_4_dialog_content = "다만 그러할 가능성은 있습니다.",
  ui_story_1013_10131301_5_dialog_content = "대화 기록으로 보면 다른 콜로서스들도 스카이워커처럼 선실을 닫아두고 있어.",
  ui_story_1013_10131301_6_dialog_content = "다들 콜로서스 안에 갇혀서 아무 일도 없이 하루하루를 보낸 거야...",
  ui_story_1013_10131301_7_dialog_content = "(그리운 느낌이네.)",
  ui_story_1013_10131301_8_dialog_content = "(나도 어렸을 때 그렇게 지냈잖아?)",
  ui_story_1013_10131301_9_dialog_content = "1호의 분석과 추측에 따르면 이러한 상황이 된 원인은 추방 또는 대피입니다.",
  ui_story_1013_10131301_10_dialog_content = "추방: 누군가가 콜로서스를 이용하여 일부 아이테르들을 가두어\n지정된 장소로 압송하고 있다.",
  ui_story_1013_10131301_11_dialog_content = "대피: 콜로서스의 외부 환경은 아이테르가 생존할 수 없으므로,\n선실을 완전히 봉쇄하고 외부로부터 격리하여 아이테르를 지키고 있다.",
  ui_story_1013_10131301_12_dialog_content = "단말기에서 사람들이 하는 말을 보면 난 대피 쪽일 거라고 더 믿고 싶어.",
  ui_story_1013_10131301_13_dialog_content = "그리고 저 사람들이 말한 「프란츠」라는 이름은 나도 알아.",
  ui_story_1013_10131301_14_dialog_content = "그 이름을 알고 있습니까?",
  ui_story_1013_10131301_15_dialog_content = "안다기보다는 우연히 그 사람이 남긴 흔적을 본 적이 있어.",
  ui_story_1013_10131301_16_dialog_content = "그렇다면 당신에게 무척 깊은 인상을 남겼겠군요.",
  ui_story_1013_10131301_17_dialog_content = "물론이지. 그 사람은 무척 특별한 아이테르였거든.",
  ui_story_1013_10131301_18_dialog_content = "오히려 그 사람이 살던 시대에는 「아이테르」라는 이름을\n거스르는 사람이었을 거야.",
  ui_story_1013_10131301_19_dialog_content = "프란츠 선생님은 세계에 전쟁을 가져오는 걸 선택하지 않고,\n반대로 아이테르에게 주어진 운명에 맞서려고 했어.",
  ui_story_1013_10131301_20_dialog_content = "나도 전에 궁지에 빠졌을 때, 프란츠 선생님의 의지에 따라 움직였거든.",
  ui_story_1013_10131301_21_dialog_content = "그리고 지금 그런 의지를 가진 사람이 한 명뿐이 아니었다는 걸\n알게 돼서 정말 다행이야.",
  ui_story_1013_10131301_22_dialog_content = "단말기의 정보 속 사람들을 말하는 건가요?",
  ui_story_1013_10131301_23_dialog_content = "응, 번호로 부르던 그 아이테르들 말이야.",
  ui_story_1013_10131301_24_dialog_content = "비록 무수한 시간을 사이에 두고 있지만,\n나도 저들과 마찬가지로 같은 이름의 사람을 믿었어.",
  ui_story_1013_10131301_25_dialog_content = "그 작은 공통점 때문에 난 저들이 신념 있는 사람들이라고 생각해.",
  ui_story_1013_10131301_26_dialog_content = "누군가에게 억지로 추방당한 것 같지는 않아. 분명히 스스로 가야 할 길을 택한 거야.",
  ui_story_1013_10131301_27_dialog_content = "어쩌면 뭔가 무서운 일이 일어났고, 그래서 이런 극단적인 방법으로\n위험을 피할 수밖에 없었을지도 몰라.",
  ui_story_1013_10131301_28_dialog_content = "매우 특이한 논리입니다. 1호는 이해하지 못했습니다.\n하지만 당신의 결론은 기록했습니다.",
  ui_story_1013_10131301_29_dialog_content = "일부러 기록할 필요까진 없는데...",
  ui_story_1013_10131301_30_dialog_content = "아무튼 대화 기록은 여기서 끝났어. 다른 정보도 찾을 수 있어?",
  ui_story_1013_10131301_31_dialog_content = "없습니다, 이것뿐입니다.",
  ui_story_1013_10131301_32_dialog_content = "그, 그럼 우리 이제 또 뭘 할 수 있는데?",
  ui_story_1013_10131301_33_dialog_content = "무질서한 데이터도 찾을 수 없고, 조사해야 할 새로운 정보도 없어...",
  ui_story_1013_10131301_34_dialog_content = "그럼 여기서 당시 아이테르들이랑 같이 지루함을 느끼라는 거야?",
  ui_story_1013_10131301_35_dialog_content = "효율은 낮지만 그것도 데이터 검색의 한 방법입니다.",
  ui_story_1013_10131301_36_dialog_content = "잠시만 기다려 주세요. 보다 정확한 검색을 실행하겠습니다.",
  ui_story_1013_10131301_37_dialog_content = "<color=#e8d9bb>위이잉──</color>",
  ui_story_1013_10131301_38_dialog_content = "어? 너 뭐 한 거야?",
  ui_story_1013_10131301_39_dialog_content = "당신이 보고 있는 화면에 영향이 있을지도 모릅니다만, 당황하지 마세요.",
  ui_story_1013_10131301_40_dialog_content = "당황한 건 아니야. 그냥 잘 모르겠어서 그래.",
  ui_story_1013_10131301_41_dialog_content = "당신도 이해할 수 있는 말로 설명하자면, 1호는 기억의 시간을 조정했습니다.",
  ui_story_1013_10131301_42_dialog_content = "현재 무질서한 데이터가 없는 기억을 고속으로 건너뛰고 있습니다.",
  ui_story_1013_10131301_43_dialog_content = "그런 편리한 방법이 있었구나...",
  ui_story_1013_10131301_44_dialog_content = "캬악──!",
  ui_story_1013_10131301_45_dialog_content = "으아아아아악!",
  ui_story_1013_10131301_46_dialog_content = "뭐, 뭐야?! 어떻게 된 거야?!",
  ui_story_1013_10131301_47_dialog_content = "무질서한 데이터가 없는 기억을 건너뛰었습니다.\n그렇게 되면 그 다음은...",
  ui_story_1013_10131301_48_dialog_content = "캬아악!",
  ui_story_1013_10131301_49_dialog_content = "야! 괘, 괜찮아?!",
  ui_story_1013_10131301_50_dialog_content = "...당연히 무질서한 데이터가 존재하는 기억이 나타납니다.",
  ui_story_1013_10131301_51_dialog_content = "이럴 땐 좀 더 쉽게 설명해 줘!",
  ui_story_1013_10131301_52_dialog_content = "그러니까 이 암귀들이 무질서한 데이터라는 거지?",
  ui_story_1013_10131301_53_dialog_content = "그렇습니다. 무질서한 데이터는 당신의 상상력에 의해\n당신이 싫어하거나 적대시하는 형상...",
  ui_story_1013_10131301_54_dialog_content = "캬아악!",
  ui_story_1013_10131301_55_dialog_content = "야...",
  ui_story_1013_10131301_56_dialog_content = "...하는 형상으로 나타납니다.\n괜찮습니다. 제 데이터 구조는 안정적입니다. 쉽게 파괴되지 않습니다.",
  ui_story_1013_10131301_57_dialog_content = "알겠어. 그렇다고 샌드백처럼 가서 맞지는 마. 깜짝 놀랐잖아.",
  ui_story_1013_10131301_58_dialog_content = "데이터니 뭐니 해봤자 난 몰라. 그리고 이해할 시간도 없어.",
  ui_story_1013_10131301_59_dialog_content = "어쨌든 암귀의 모습이라면, 암귀를 상대하는 방식으로 쓰러트리면 되는 거잖아!",
  ui_story_1013_10131302_1_dialog_content = "속사 감지!",
  ui_story_1013_10131302_2_dialog_content = "흩어져라! 빙화여!",
  ui_story_1013_10131302_3_dialog_content = "우와, 속이 다 시원하네...",
  ui_story_1013_10131302_4_dialog_content = "1호는 모르겠습니다. 그런 말을 외치는 것이 전투에 도움이 되는 것입니까?",
  ui_story_1013_10131302_5_dialog_content = "아니, 사실 나도 잘 모르겠어.",
  ui_story_1013_10131302_6_dialog_content = "오로리안들은 싸울 때 지금처럼 외치거든. 그래서 나도 해보고 싶었어.",
  ui_story_1013_10131302_7_dialog_content = "싸우면서 기술 이름을 외치면 멋있어서 그런가?",
  ui_story_1013_10131302_8_dialog_content = "봐, 소리치니까 적이 쓰러졌잖아. 효과가 좋지 않아?",
  ui_story_1013_10131302_9_dialog_content = "그렇습니까. 1호는 논리가 없는 이상한 설명에 대한 이해를 시도합니다.",
  ui_story_1013_10131302_10_dialog_content = "하하, 이런 얘긴 됐어. 그것보다 스카이워커의 상태에 변화가 있었어?",
  ui_story_1013_10131302_11_dialog_content = "약 37%의 무질서한 데이터가 배제되었습니다. 당신의 전투는 효과가 있었습니다.",
  ui_story_1013_10131302_12_dialog_content = "스카이워커호의 일부 기능이 회복을 시작했습니다.",
  ui_story_1013_10131302_13_dialog_content = "37%?! 한번에 그렇게 많이 지울 수 있었구나!",
  ui_story_1013_10131302_14_dialog_content = "분산되어 있던 무질서한 데이터가 스카이워커호에 의해 자율 수정되었습니다.",
  ui_story_1013_10131302_15_dialog_content = "따라서 복구해야 할 무질서한 데이터는 높은 집합성을 가지고 있는 것입니다.",
  ui_story_1013_10131302_16_dialog_content = "계산에 따르면 무질서한 데이터는 이제 한 곳만 남았습니다.",
  ui_story_1013_10131302_17_dialog_content = "우와! 그럼 이제 곧 끝낼 수 있겠네!",
  ui_story_1013_10131302_18_dialog_content = "맞습니다. 다만 남은 그 무질서한 데이터의 이상은 더 심각합니다. 조심하세요.",
  ui_story_1013_10131302_19_dialog_content = "준비가 되는 대로 1호는 정밀 검색을 실행해서\n무질서한 데이터가 있는 시간으로 향하겠습니다.",
  ui_story_1013_10131302_20_dialog_content = "잠깐만, 그럼 우리가 지금 있는 시간은 처음 들어왔을 때랑 다르다는 거지?",
  ui_story_1013_10131302_21_dialog_content = "그렇습니다, 방금 정밀 검색을 통해 꽤 오랜 시간을 건너뛰었습니다.",
  ui_story_1013_10131302_22_dialog_content = "기억 속에는 참조 데이터가 없으므로, 정확한 시간 폭은 알 수 없습니다.",
  ui_story_1013_10131302_23_dialog_content = "그럼 다시 한번 단말기를 보고 싶어.",
  ui_story_1013_10131302_24_dialog_content = "당시 아이테르들이 어떤 경험을 했는지 좀 궁금하거든.",
  ui_story_1013_10131302_25_dialog_content = "알겠습니다. 1호는 단말기 데이터를 출력하겠습니다.",
  ui_story_1013_10131302_26_dialog_content = "번역해주는 것도 잊지 말고.",
  ui_story_1013_10131302_27_dialog_content = "물론입니다, 인공지능은 스스로의 행동을 항상 최적화하고 있습니다.",
  ui_story_1013_10131302_28_dialog_content = "1호는 최적값 그 자체입니다.",
  ui_story_1013_10131302_29_dialog_content = "다들──",
  ui_story_1013_10131302_30_dialog_content = "여기 좀 봐!",
  ui_story_1013_10131302_31_dialog_content = "갑작스럽겠지만, 사실은 오늘이 내 생일이야.",
  ui_story_1013_10131302_32_dialog_content = "내 노래 듣고 싶은 사람?",
  ui_story_1013_10131302_33_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_1013_10131302_34_dialog_content = "그래, 그럼 다른 걸로 할게.",
  ui_story_1013_10131302_35_dialog_content = "노래 말고 시를 지어줄게!",
  ui_story_1013_10131302_36_dialog_content = "나 시 잘 써. 아빠도 나한테 시인이 될 거라고 그랬어!",
  ui_story_1013_10131302_37_dialog_content = "35번, 저번 생일 아직 기억하는데.",
  ui_story_1013_10131302_38_dialog_content = "몇 년 전이었는지는 잊어버렸지만, 작년이 아닌 건 확실하고.",
  ui_story_1013_10131302_39_dialog_content = "으으, 982번 너 기억력이 너무 좋잖아... 속일 수 있을 줄 알았는데...",
  ui_story_1013_10131302_40_dialog_content = "생일은 소중한 날이야. 그렇게 대충 대하지 않는 게 좋을걸.",
  ui_story_1013_10131302_41_dialog_content = "알았어, 그럼 생일 안 할게.",
  ui_story_1013_10131302_42_dialog_content = "대신 유용한 정보를 알려줄게!",
  ui_story_1013_10131302_43_dialog_content = "4호 통조림을 볶아서 15호 냉동 통조림이랑 섞어 봐.",
  ui_story_1013_10131302_44_dialog_content = "진짜 맛있어! 다들 꼭 해 봐!",
  ui_story_1013_10131302_45_dialog_content = "35번은 여전히 친절하구나.",
  ui_story_1013_10131302_46_dialog_content = "79번 언니! 오랜만이야!",
  ui_story_1013_10131302_47_dialog_content = "그래, 오랜만이네. 요즘 단말기를 잘 안 봐서.",
  ui_story_1013_10131302_48_dialog_content = "자주 좀 보고 그래. 나 혼자 말하면 재미없잖아.",
  ui_story_1013_10131302_49_dialog_content = "982번은 잘 상대해 주는 것 같던데.",
  ui_story_1013_10131302_50_dialog_content = "아니거든! 79번 언니보다 더 안 해 준단 말이야.",
  ui_story_1013_10131302_51_dialog_content = "오늘 기껏 나왔다 했더니 날 방해하려던 거였어! 짜증 나!",
  ui_story_1013_10131302_52_dialog_content = "내가 사과해야 되나?",
  ui_story_1013_10131302_53_dialog_content = "그, 그럴 필요까진 없어... 거짓말한 내가 나빴으니까...",
  ui_story_1013_10131302_54_dialog_content = "사실 오늘 단말기를 본 건 이유가 있어. 오늘은 나한테 특별한 날이거든.",
  ui_story_1013_10131302_55_dialog_content = "그래서 이 날을 기억하고 싶어.",
  ui_story_1013_10131302_56_dialog_content = "헤에? 982번 생일이야?",
  ui_story_1013_10131302_57_dialog_content = "아니.",
  ui_story_1013_10131302_58_dialog_content = "생일과는 딱 정반대의 기념일이라고 할 수 있겠지.",
  ui_story_1013_10131302_59_dialog_content = "982번, 당신...",
  ui_story_1013_10131302_60_dialog_content = "참, 너 시 쓴다면서. 그럼 나한테 하나 써 줘.",
  ui_story_1013_10131302_61_dialog_content = "좋아! 주제는 뭐가 좋아?",
  ui_story_1013_10131302_62_dialog_content = "「지상」... 지상에 대한 시가 좋겠어.",
  ui_story_1013_10131302_63_dialog_content = "알았어! 잘 생각해 볼게. 분명히 982번도 좋아할 거야!",
  ui_story_1013_10131302_64_dialog_content = "얼마나 걸리냐?",
  ui_story_1013_10131302_65_dialog_content = "몰라. 아직은 떠오르는 영감이 없어.",
  ui_story_1013_10131302_66_dialog_content = "조금만 기다려줄래? 다 되면 바로 부를게!",
  ui_story_1013_10131302_67_dialog_content = "서두르는 게 좋을걸. 늦으면 필요 없어질 테니까.",
  ui_story_1013_10131302_68_dialog_content = "필요 없다니 안 돼! 모처럼 내가 다른 사람을 위해 시를 쓸 수 있게 됐는데!",
  ui_story_1013_10131302_69_dialog_content = "꼭 받아줘!",
  ui_story_1013_10131302_70_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_1013_10131302_71_dialog_content = "982번! 시 다 썼어!",
  ui_story_1013_10131302_72_dialog_content = "982번?",
  ui_story_1013_10131302_73_dialog_content = "야! 내가 엄청 열심히 썼단 말이야!",
  ui_story_1013_10131302_74_dialog_content = "빨리 안 나오면 나 화낼 거야!",
  ui_story_1013_10131302_75_dialog_content = "982번! 982번! 982번!",
  ui_story_1013_10131302_76_dialog_content = "......",
  ui_story_1013_10131302_77_dialog_content = "됐어, 고작 이런 일 가지고 화를 내면 안 되지.",
  ui_story_1013_10131302_78_dialog_content = "다음에 단말기를 볼 때 불러줘. 난 언제든지 보고 있으니까.",
  ui_story_1013_10131302_79_dialog_content = "35번, 오늘은 꽤 일찍 일어났구나.",
  ui_story_1013_10131302_80_dialog_content = "응! 어제 밤새서 982번한테 줄 시를 썼거든.",
  ui_story_1013_10131302_81_dialog_content = "근데...",
  ui_story_1013_10131302_82_dialog_content = "정말 수고했어.",
  ui_story_1013_10131302_83_dialog_content = "너도 알잖아. 982번은 저런 성격이니까.",
  ui_story_1013_10131302_84_dialog_content = "어제는 시를 받고 싶다고 했었어도, 오늘은 마음이 바뀌었을지도 몰라.",
  ui_story_1013_10131302_85_dialog_content = "그럴 수도 있겠네! 하긴, 982번이라면 그럴 만하니까!",
  ui_story_1013_10131302_86_dialog_content = "그러니까 신경 쓸 거 없어. 쓴 시를 나한테 보내줄 수 있을까?\n우리 35번이 얼마나 재능이 있는지 보고 싶어.",
  ui_story_1013_10131302_87_dialog_content = "으... 근데 이 시는 982번한테 줄 선물이니까, 982번이 제일 먼저 봤으면 좋겠어.",
  ui_story_1013_10131302_88_dialog_content = "79번 언니도 시를 읽고 싶으면 다음에 또 지어줄게!",
  ui_story_1013_10131302_89_dialog_content = "어머, 나한테도?",
  ui_story_1013_10131302_90_dialog_content = "괜찮아. 안 그러면 35번이 또 밤을 새워야 하잖아.",
  ui_story_1013_10131302_91_dialog_content = "응? 괜찮아! 잘 시간은 얼마든지 있잖아!",
  ui_story_1013_10131302_92_dialog_content = "35번이 정성껏 지어주는 시는 아무렇게나 받을 순 없어.",
  ui_story_1013_10131302_93_dialog_content = "다음 기회에 줘.",
  ui_story_1013_10131302_94_dialog_content = "나한테 특별한 날이 되면.",
  ui_story_1013_10131302_95_dialog_content = "응, 그럼 그렇게 하자.",
  ui_story_1013_10131302_96_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_1013_10131302_97_dialog_content = "오늘 창고에서 안 뜯은 레코드를 찾았어!",
  ui_story_1013_10131302_98_dialog_content = "노래가 진짜 좋더라구! 누구 듣고 싶은 사람?",
  ui_story_1013_10131302_99_dialog_content = "저기── 누구 없어──?",
  ui_story_1013_10131302_100_dialog_content = "뭐, 좋아. 단말기에 올려놨으니까 관심 있으면 들어 봐.",
  ui_story_1013_10131302_101_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_1013_10131302_102_dialog_content = "히잉, 목욕 장치가 고장 난 것 같아.",
  ui_story_1013_10131302_103_dialog_content = "누구 수리할 수 있는 사람 있어? 수리하는 방법 좀 알려줄래?",
  ui_story_1013_10131302_104_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_1013_10131302_105_dialog_content = "이쪽은 기온이 떨어졌어. 다들 옷 따뜻하게 입어.",
  ui_story_1013_10131302_106_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_1013_10131302_107_dialog_content = "저기, 아무도 나랑 얘기 안 해준 지 한참 된 것 같아. 얘기하고 싶어.",
  ui_story_1013_10131302_108_dialog_content = "오늘은 내 생일이야.",
  ui_story_1013_10131302_109_dialog_content = "이번엔 진짜야.",
  ui_story_1013_10131302_110_dialog_content = "누구든 좋으니까 나랑 얘기 좀 해 줘.",
  ui_story_1013_10131302_111_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_1013_10131302_112_dialog_content = "217번 아저씨, 얘기 안한 지 오래됐지?",
  ui_story_1013_10131302_113_dialog_content = "아저씨가 돌아갈 수 있다고 했었잖아. 그거 거짓말 아니지?",
  ui_story_1013_10131302_114_dialog_content = "982번 바보, 모처럼 시도 썼는데 필요 없어?",
  ui_story_1013_10131302_115_dialog_content = "79번 언니, 단말기는 언제 봐줄 거야...?",
  ui_story_1013_10131302_116_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_1013_10131302_117_dialog_content = "으, 역시 아무도 없네.",
  ui_story_1013_10131302_118_dialog_content = "이제 기록엔 전부 내 메시지밖에 없어.",
  ui_story_1013_10131302_119_dialog_content = "이러면 꼭 내가 미움받는 사람 같잖아.",
  ui_story_1013_10131302_120_dialog_content = "안 돼, 이대로는 안 돼.",
  ui_story_1013_10131302_121_dialog_content = "맞다!",
  ui_story_1013_10131302_122_dialog_content = "명령: 콜로서스 상태 체크!",
  ui_story_1013_10131302_123_dialog_content = "217호 콜로서스, 상태 양호, 이상 없음.",
  ui_story_1013_10131302_124_dialog_content = "982호 콜로서스, 상태 양호, 이상 없음.",
  ui_story_1013_10131302_125_dialog_content = "79호 콜로서스, 상태 양호, 이상 없음.",
  ui_story_1013_10131302_126_dialog_content = "35호 콜로서스, 상태 양호, 이상 없음.",
  ui_story_1013_10131302_127_dialog_content = "아하하, 좋아! 이걸로 떠들썩해졌잖아!",
  ui_story_1013_10131401_1_dialog_content = "휴... 다 봤어.",
  ui_story_1013_10131401_2_dialog_content = "가슴이 갑갑해. 뭐라고 말하기 힘든 괴로운 기분이야.",
  ui_story_1013_10131401_3_dialog_content = "1호는 이해가 되지 않습니다.",
  ui_story_1013_10131401_4_dialog_content = "언어 의미 분석에 따르면, 기록된 대화는 일상적인 내용입니다.\n「가슴이 갑갑하다」는 감정과는 맞지 않습니다.",
  ui_story_1013_10131401_5_dialog_content = "너도 이 기록들 좀 봐. 나오는 사람이 점점 줄어들고 있잖아.",
  ui_story_1013_10131401_6_dialog_content = "그러다 마지막엔 혼자만 남았어.",
  ui_story_1013_10131401_7_dialog_content = "난 이 아이테르들의 마음을 알 것 같아.",
  ui_story_1013_10131401_8_dialog_content = "텅 빈 채로 끝없이 반복되는 나날 속에서 무의미한 소리를 지르고 있어.",
  ui_story_1013_10131401_9_dialog_content = "돌아오는 메아리가 하루하루의 삶에 작은 물결이라도 쳐주길 바라면서.",
  ui_story_1013_10131401_10_dialog_content = "하지만 마지막엔 결국 그런 간단한 바람조차도 보답받지 못한 채 끝나는 거야.",
  ui_story_1013_10131401_11_dialog_content = "그런 거였습니까? 당신이 공감한 것은 내용이 아니라 대화의 인원수와 밀도였군요.",
  ui_story_1013_10131401_12_dialog_content = "1호는 그런 감정의 공감 방식을 기록했습니다.",
  ui_story_1013_10131401_13_dialog_content = "인원수랑 밀도? 그런가? 뭐라고 잘 설명은 못 하겠지만...",
  ui_story_1013_10131401_14_dialog_content = "난 그저 어디서도 해소할 수 없는 교류의 열망을 저 사람들한테서 느꼈을 뿐이야.",
  ui_story_1013_10131401_15_dialog_content = "그게 바로 아까 말한 「가슴이 갑갑하다」는 거야.\n심지어 두려움마저 느껴질 정도로.",
  ui_story_1013_10131401_16_dialog_content = "두려움, 그들과 같은 환경에 놓이는 것이 두려운가요?",
  ui_story_1013_10131401_17_dialog_content = "응, 근데 사실 나도 비슷한 일을 겪은 적 있어.",
  ui_story_1013_10131401_18_dialog_content = "난 한때 지하에서 혼자 17년 동안 살았거든.",
  ui_story_1013_10131401_19_dialog_content = "저 사람들과 비교하면 17년은 긴 걸까? 아니면 짧은 걸까?",
  ui_story_1013_10131401_20_dialog_content = "다만 그때 내가 느꼈던 괴로움은 저렇게 절망적이진 않았어.",
  ui_story_1013_10131401_21_dialog_content = "그건 아마 나한테 스카이워커가 있었기 때문일 거야.\n스카이워커는 항상 내 곁에 있어 줬어.",
  ui_story_1013_10131401_22_dialog_content = "참, 그러고 보니까 저 사람들도 다들 콜로서스를 가지고 있었잖아.",
  ui_story_1013_10131401_23_dialog_content = "근데 저 사람들의 콜로서스는 인격이 없었던 것 같아.",
  ui_story_1013_10131401_24_dialog_content = "기계적인 응답으로는 고독을 없앨 수 없었겠지.",
  ui_story_1013_10131401_25_dialog_content = "<color=#e8d9bb>위이잉──</color>",
  ui_story_1013_10131401_26_dialog_content = "어? 무슨 일이야?",
  ui_story_1013_10131401_27_dialog_content = "1호, 또 시간 가속했어?",
  ui_story_1013_10131401_28_dialog_content = "1호는 어떤 조작도 하지 않았습니다.",
  ui_story_1013_10131401_29_dialog_content = "그럼 지금 이건...",
  ui_story_1013_10131401_30_dialog_content = "머, 멈췄어...",
  ui_story_1013_10131401_31_dialog_content = "우린 순서대로 스카이워커호가 저장했던 데이터를 열람하고 있었을 뿐입니다.",
  ui_story_1013_10131401_32_dialog_content = "지금과 같은 현상이 일어났다는 것은 데이터 자체에 문제가 발생했다는 것입니다.",
  ui_story_1013_10131401_33_dialog_content = "고장이야?!",
  ui_story_1013_10131401_34_dialog_content = "이상합니다. 검사 결과에 따르면 이는 데이터 삭제로 인한 고장이 아닙니다.",
  ui_story_1013_10131401_35_dialog_content = "데이터베이스 안에는 이러한 고장에 대한 기록을 찾을 수 없습니다.",
  ui_story_1013_10131401_36_dialog_content = "하아? 너도 모르는 게 있어?",
  ui_story_1013_10131401_37_dialog_content = "이상합니다. 어쩌면 이건 고장이 아니라 현상일 수도 있습니다.",
  ui_story_1013_10131401_38_dialog_content = "현상?",
  ui_story_1013_10131401_39_dialog_content = "그렇습니다. 1호는 기계와 관련이 없는 장소를 검색해서 비슷한 기록을 발견했습니다.",
  ui_story_1013_10131401_40_dialog_content = "그 데이터 형식은 생물의 대뇌에서 일어나는 「망각」과 매우 유사합니다.",
  ui_story_1013_10131401_41_dialog_content = "망각? 그러니까 스카이워커가 일부 기억을 잊어버려서,\n우리도 그 부분의 시간을 건너뛰었다는 거야?",
  ui_story_1013_10131401_42_dialog_content = "「망각」이 성립한다면, 그렇게 추측하는 것이 합리적입니다.",
  ui_story_1013_10131401_43_dialog_content = "그러나 기계에 「망각」이 발생하는 것은 논리에 맞지 않습니다.\n기계는 보다 엄격한 데이터 소거라는 방식이 있습니다.",
  ui_story_1013_10131401_44_dialog_content = "그럼 맞는 거야! 스카이워커는 기계가 아니니까!",
  ui_story_1013_10131401_45_dialog_content = "1호, 다시 단말기를 보여줘!",
  ui_story_1013_10131401_46_dialog_content = "시간이 흘렀다면 단말기 안의 내용도 업데이트가 되었을 거야.",
  ui_story_1013_10131401_47_dialog_content = "알겠습니다, 잠시만 기다려 주세요.",
  ui_story_1013_10131401_48_dialog_content = "명령: 35호 콜로서스, 응답해!",
  ui_story_1013_10131401_49_dialog_content = "35호 콜로서스 대기 중, 명령을 기다립니다.",
  ui_story_1013_10131401_50_dialog_content = "좋아! 그럼 내가 이어서 이야기를 해줄게.",
  ui_story_1013_10131401_51_dialog_content = "출발했던 그날 얘기야.",
  ui_story_1013_10131401_52_dialog_content = "출발 전에 난 조종사 자격을 이제 막 얻은 참이었고, 그건 내 첫 콜로서스 조종이었어.",
  ui_story_1013_10131401_53_dialog_content = "그래서 난 준비를 잔뜩 했어. 밤 동안 계속 어떤 돌발 상황이 생길지,\n내가 어떻게 대처해야 할지 생각했어.",
  ui_story_1013_10131401_54_dialog_content = "짐에는 옷을 많이 담았어. 내 용돈을 다 써서 산 옷들이야.",
  ui_story_1013_10131401_55_dialog_content = "제일 예쁜 옷은 귀환하는 날 입을 거야. 난 영웅처럼 멋지게 귀환하고 싶어.",
  ui_story_1013_10131401_56_dialog_content = "근데 준비한 것들은 결국 다 쓸모가 없어졌어.",
  ui_story_1013_10131401_57_dialog_content = "돌발사태 같은 건 없었어. 한 번도. 그러기는커녕 나중에는 조종조차 필요가 없어졌어.",
  ui_story_1013_10131401_58_dialog_content = "그 제일 예쁜 옷은 지금도 반듯하게 접혀서 여행가방 안에 들어 있어.",
  ui_story_1013_10131401_59_dialog_content = "어제 잠깐 입어봤는데, 사이즈가 너무 작아서 지금은 못 입게 됐어.",
  ui_story_1013_10131401_60_dialog_content = "휴, 진짜 예쁜 옷이었는데... 35호 콜로서스, 듣고 있어?",
  ui_story_1013_10131401_61_dialog_content = "명령: 35호 콜로서스, 응답해!",
  ui_story_1013_10131401_62_dialog_content = "35호 콜로서스 대기 중, 명령을 기다립니다.",
  ui_story_1013_10131401_63_dialog_content = "듣고 있으면 됐어. 계속 얘기해 줄게...",
  ui_story_1013_10131401_64_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_1013_10131401_65_dialog_content = "명령: 982호 콜로서스, 응답해!",
  ui_story_1013_10131401_66_dialog_content = "982호 콜로서스 대기 중, 명령을 기다립니다.",
  ui_story_1013_10131401_67_dialog_content = "좋아! 오늘은 너한테 이야기를 들려줄게.",
  ui_story_1013_10131401_68_dialog_content = "출발한 뒤의 이야기야. 출발 후에는 다들 점차 서로 만나지 않게 됐고,\n단말기로 대화하는 게 익숙해졌어.",
  ui_story_1013_10131401_69_dialog_content = "다들 자기가 타고 있는 콜로서스랑 같은 번호를 가지고 있어서,\n당연히 번호로 서로 부르게 됐어.",
  ui_story_1013_10131401_70_dialog_content = "그땐 번호로 부르는 게 너무 무서웠어. 숫자는 차가운 거잖아.",
  ui_story_1013_10131401_71_dialog_content = "그래서 난 혼자 계속해서 다른 사람들을 원래 이름으로 불렀어.",
  ui_story_1013_10131401_72_dialog_content = "얼마나 버텼을까? 몇 달? 아니면 1년? 이젠 기억 안 나.",
  ui_story_1013_10131401_73_dialog_content = "어쨌든 처음 한 사람의 이름을 잊어버릴 때까진 열심히 했어.",
  ui_story_1013_10131401_74_dialog_content = "잊어버렸다고 해서 그 사람만 따로 취급할 순 없잖아. 그런 건 실례야.",
  ui_story_1013_10131401_75_dialog_content = "그래서 어쩔 수 없이 다른 사람들도 전부 숫자로 부르게 된 거야.",
  ui_story_1013_10131401_76_dialog_content = "982번은 내가 어른이 됐다고 했지만, 난 그러고 싶지 않았어.",
  ui_story_1013_10131401_77_dialog_content = "어른이 되고 싶지 않았어. 모두의 이름도 잊고 싶지 않았어.",
  ui_story_1013_10131401_78_dialog_content = "......",
  ui_story_1013_10131401_79_dialog_content = "그래, 누구나 이름이 있어야 해. 콜로서스도 마찬가지야.",
  ui_story_1013_10131401_80_dialog_content = "그럼 내가 콜로서스에 이름을 붙일게! 앞으로는 번호로 부를 필요 없어!",
  ui_story_1013_10131401_81_dialog_content = "우선 982번 너부터, 어디 보자...",
  ui_story_1013_10131401_82_dialog_content = "네 주인은 싫은 녀석이야. 하지만 「싫다」는 걸 이름으로 하면\n좀 괴롭히는 것 같으니까 다른 말로 하자.",
  ui_story_1013_10131401_83_dialog_content = "「론울프호」라고 할게!",
  ui_story_1013_10131401_84_dialog_content = "명령: 콜로서스의 명칭 변경, 「982호 콜로서스」를 「론울프호」로 변경한다.",
  ui_story_1013_10131401_85_dialog_content = "명령 수신, 명칭 변경 완료.",
  ui_story_1013_10131401_86_dialog_content = "자, 다음은 217번이야!",
  ui_story_1013_10131401_87_dialog_content = "217번 아저씨는 모두를 이끄는 선도자 같은 사람이야.\n그러니까 네 이름은 「패스파인더호」로 지을게!",
  ui_story_1013_10131401_88_dialog_content = "명령: 콜로서스의 명칭 변경, 「217호 콜로서스」를 「패스파인더호」로 변경한다.",
  ui_story_1013_10131401_89_dialog_content = "명령 수신, 명칭 변경 완료.",
  ui_story_1013_10131401_90_dialog_content = "다음은 79번 언니네. 언니는 착하고 섬세한 사람이니까,\n콜로서스한테도 예쁜 이름을 지어줘야지!",
  ui_story_1013_10131401_91_dialog_content = "예쁜 이름... 예쁜 이름...",
  ui_story_1013_10131401_92_dialog_content = "35번, 나 불렀니?",
  ui_story_1013_10131401_93_dialog_content = "우와! 79번 언니! 드디어 단말기를 봐줬구나!",
  ui_story_1013_10131401_94_dialog_content = "응, 35번은 정말 대단하네. 혼자서 이렇게 많이 이야기했구나.",
  ui_story_1013_10131401_95_dialog_content = "에헤헤, 지금 모두의 콜로서스에 이름을 붙이고 있어.",
  ui_story_1013_10131401_96_dialog_content = "콜로서스에 이름을? 재미있네. 너답다는 느낌이야.",
  ui_story_1013_10131401_97_dialog_content = "응! 재밌어! 난 모든 콜로서스에 이름을 붙일 거야.",
  ui_story_1013_10131401_98_dialog_content = "어머, 그거 힘들겠네. 콜로서스는 많이 있잖아.",
  ui_story_1013_10131401_99_dialog_content = "헤헤, 79번 언니도 알잖아. 우리한텐 남는 게 시간인걸.",
  ui_story_1013_10131401_100_dialog_content = "하긴 그렇네.",
  ui_story_1013_10131401_101_dialog_content = "지금 막 79번 언니 콜로서스에 이름을 붙이려던 참이었어.\n언니는 뭐 좋은 생각 있어?",
  ui_story_1013_10131401_102_dialog_content = "사실 오늘은 35번한테 부탁할 일이 있어서 연락한 거야.",
  ui_story_1013_10131401_103_dialog_content = "부탁? 내가 도울 일이 있는 거야?!",
  ui_story_1013_10131401_104_dialog_content = "응.",
  ui_story_1013_10131401_105_dialog_content = "네가 시를 써 줬으면 좋겠어.",
  ui_story_1013_10131401_106_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_1013_10131401_107_dialog_content = "괜찮니?",
  ui_story_1013_10131401_108_dialog_content = "<color=#e8d9bb>위이잉──</color>",
  ui_story_1013_10131401_109_dialog_content = "무슨 일이야? 아직 단말기 기록을 다 못 봤는데!",
  ui_story_1013_10131401_110_dialog_content = "또?!",
  ui_story_1013_10131401_111_dialog_content = "이 지역의 데이터는 매우 분산되어 있습니다.",
  ui_story_1013_10131401_112_dialog_content = "좀 더 알기 쉽게 말해줄래?",
  ui_story_1013_10131401_113_dialog_content = "스카이워커호의 이 시기 기억이 적다는 것입니다.",
  ui_story_1013_10131401_114_dialog_content = "그것도 그렇겠네. 기억할 만한 것도 딱히 없었을 테고.",
  ui_story_1013_10131401_115_dialog_content = "<color=#e8d9bb>콰앙──!</color>",
  ui_story_1013_10131401_116_dialog_content = "으악! 깜짝이야!",
  ui_story_1013_10131401_117_dialog_content = "무슨 소리야?",
  ui_story_1013_10131401_118_dialog_content = "<color=#e8d9bb>콰앙──!</color>",
  ui_story_1013_10131401_119_dialog_content = "선실 문에 무언가가 부딪혔습니다.",
  ui_story_1013_10131401_120_dialog_content = "누군데? 전에는 아무도 없었잖아.",
  ui_story_1013_10131401_121_dialog_content = "잠깐만, 설마...",
  ui_story_1013_10131401_122_dialog_content = "검사 결과에 따르면 우리는 지금 무질서한 데이터가 일으킨\n이상 지점에 도달한 것 같습니다.",
  ui_story_1013_10131401_123_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_1013_10131401_124_dialog_content = "좀 더 빨리 알려줬어야지! 나도 준비할 시간은 있어야 할 거 아냐!",
  ui_story_1013_10131401_125_dialog_content = "근데 잠깐만... 암귀가 아닌 것 같은데? 저게 뭐지?",
  ui_story_1013_10131401_126_dialog_content = "......",
  ui_story_1013_10131401_127_dialog_content = "저거 꽃 아냐? 선실 바닥에서 자란 것 같은데?!",
  ui_story_1013_10131401_128_dialog_content = "이번엔 네가 말하지 않아도 알겠어. 저게 무질서한 데이터지?",
  ui_story_1013_10131401_129_dialog_content = "그렇습니다. 하지만 1호는 이해가 되지 않습니다. 어떻게 판단하셨나요?",
  ui_story_1013_10131401_130_dialog_content = "말이 안 되잖아! 이런 곳에 꽃이 왜 피는데!",
  ui_story_1013_10131401_131_dialog_content = "네가 그랬잖아. 무질서한 데이터는 내가 싫어하는 사물이 되어 나타난다고.\n그럼 저건 또 뭐가 어떻게 된 거야?",
  ui_story_1013_10131401_132_dialog_content = "싫고 좋고의 문제가 아니라 난 저런 걸 본 적조차 없어!",
  ui_story_1013_10131401_133_dialog_content = "1호의 판단으로는 지난번 당신이 무질서한 데이터를 배제한 정보가\n상대방에게 읽힌 것 같습니다.",
  ui_story_1013_10131401_134_dialog_content = "그래서 이번 무질서한 데이터도 그에 걸맞게 대응한 것입니다.",
  ui_story_1013_10131401_135_dialog_content = "스카이워커호의 기억을 읽고 자신을 취합해서,\n보다 전투에 적합한 개체를 만들어 냈습니다.",
  ui_story_1013_10131401_136_dialog_content = "당신은 지금 그것을 보고 있는 것입니다.",
  ui_story_1013_10131401_137_dialog_content = "저런 게 전투에 적합한가?",
  ui_story_1013_10131401_138_dialog_content = "스카이워커호의 기억 속 저 개체는 「디아볼라」라는 암귀입니다.",
  ui_story_1013_10131401_139_dialog_content = "저게 암귀라고? 꽃 모양이?",
  ui_story_1013_10131401_140_dialog_content = "그렇습니다.",
  ui_story_1013_10131401_141_dialog_content = "진짜 엄청나네. 전투 데이터를 기반으로 전투 방식을 바꾸다니...",
  ui_story_1013_10131401_142_dialog_content = "이러다간 몇 번 더 싸우고 나면 상대도 안 되겠어.",
  ui_story_1013_10131401_143_dialog_content = "1호, 저게 마지막 무질서한 데이터였지?",
  ui_story_1013_10131401_144_dialog_content = "네, 조심하세요. 이번 무질서한 데이터의 양은 전보다 더 많습니다.",
  ui_story_1013_10131401_145_dialog_content = "게다가 상대는 이미 전투에 특화된 상태입니다.",
  ui_story_1013_10131401_146_dialog_content = "그래, 알겠어.",
  ui_story_1013_10131401_147_dialog_content = "내가 얼마나 승산이 있는지 계산할 수 있어?",
  ui_story_1013_10131401_148_dialog_content = "10%입니다.",
  ui_story_1013_10131401_149_dialog_content = "그렇게 낮다고?!",
  ui_story_1013_10131401_150_dialog_content = "그래도 0이 아니라 다행이네.",
  ui_story_1013_10131401_151_dialog_content = "하지만 괜찮습니다. 우리의 목적은 전투에서 승리하는 것이 아니라\n무질서한 데이터의 배제입니다.",
  ui_story_1013_10131401_152_dialog_content = "1호도 당신을 돕고 있습니다.",
  ui_story_1013_10131401_153_dialog_content = "너한테 그런 따뜻한 말을 듣게 될 줄은 몰랐네! 그럼 나도 안심이야.",
  ui_story_1013_10131401_154_dialog_content = "그래도 승산이 10%라니 역시 기분이 안 좋은데...",
  ui_story_1013_10131401_155_dialog_content = "참, 넌 수시로 자기 계산을 최적화하고 있다고 했지?",
  ui_story_1013_10131401_156_dialog_content = "그렇습니다.",
  ui_story_1013_10131401_157_dialog_content = "그럼 잘 봐. 내가 실전 수업을 해줄 테니까!",
  ui_story_1013_10131402_1_dialog_content = "정면 공격을 피해야 합니다.",
  ui_story_1013_10131402_2_dialog_content = "안다고! 내가 피하는 것 정도도 못 할 줄 알았어?",
  ui_story_1013_10131402_3_dialog_content = "이어서 힘을 집중해서 공격하세요. 상대방의 핵심 부위를 노려야 합니다.",
  ui_story_1013_10131402_4_dialog_content = "좀 더 천천히 얘기할 수 있을까? 나한테도 조금 생각할 시간을 줘야지...",
  ui_story_1013_10131402_5_dialog_content = "핵심 부위... 핵심 부위...",
  ui_story_1013_10131402_6_dialog_content = "1호는 다음이 절호의 공격 기회라고 판단합니다.",
  ui_story_1013_10131402_7_dialog_content = "3초 남았습니다.",
  ui_story_1013_10131402_8_dialog_content = "알았으니까 시간 좀 재지 마!",
  ui_story_1013_10131402_9_dialog_content = "집중하자... 이게 마지막 공격이야.",
  ui_story_1013_10131402_10_dialog_content = "슥, 스윽...",
  ui_story_1013_10131402_11_dialog_content = "급소를... 조준해.",
  ui_story_1013_10131402_12_dialog_content = "지금이야!",
  ui_story_1013_10131402_13_dialog_content = "스윽...",
  ui_story_1013_10131402_14_dialog_content = "좋았어! 녀석이 없어졌어!",
  ui_story_1013_10131402_15_dialog_content = "스카이워커호의 저장 공간 상황을 검사합니다.",
  ui_story_1013_10131402_16_dialog_content = "모든 노드를 체크했습니다. 이상은 발견되지 않았습니다.",
  ui_story_1013_10131402_17_dialog_content = "1호는 스카이워커호 내부의 무질서한 데이터가 모두 배제되었다고 판단합니다.",
  ui_story_1013_10131402_18_dialog_content = "우와, 다 없앴구나!",
  ui_story_1013_10131402_19_dialog_content = "그럼 이제 스카이워커가 깨어날 수 있는 거야?",
  ui_story_1013_10131402_20_dialog_content = "고장을 일으킨 요소는 모두 배제했습니다.\n현재 스카이워커호의 시스템은 정상 상태입니다.",
  ui_story_1013_10131402_21_dialog_content = "스카이워커호의 모든 기능이 회복되었습니다.",
  ui_story_1013_10131402_22_dialog_content = "그러나 당신이 말하는 「깨어남」, 즉 인격의 회복 여부에 대해\n1호는 장담할 수 없습니다.",
  ui_story_1013_10131402_23_dialog_content = "뭐?",
  ui_story_1013_10131402_24_dialog_content = "스카이워커호의 인격을 유지하는 시스템은 1호의 이해 범위를 넘어섰습니다.",
  ui_story_1013_10131402_25_dialog_content = "따라서 1호는 해당 시스템이 초기와 같이 복구될지 판단할 수 없습니다.",
  ui_story_1013_10131402_26_dialog_content = "자세한 상황은 스카이워커호의 데이터 저장 공간을 떠난 후\n실험으로 검증할 수 있습니다.",
  ui_story_1013_10131402_27_dialog_content = "그렇구나...",
  ui_story_1013_10131402_28_dialog_content = "이곳에서 수행해야 할 일은 모두 종료되었습니다.",
  ui_story_1013_10131402_29_dialog_content = "이제 현실로 돌아가서 스카이워커호의 상황을 체크할 수 있습니다.",
  ui_story_1013_10131402_30_dialog_content = "데이터 공간을 떠나겠습니까?",
  ui_story_1013_10131402_31_dialog_content = "여길 떠나는 거구나, 음...",
  ui_story_1013_10131402_32_dialog_content = "조금만 기다려줄래? 단말기를 좀 더 보고 싶어.",
  ui_story_1013_10131402_33_dialog_content = "그 아이테르들이 좀 궁금해.",
  ui_story_1013_10131402_34_dialog_content = "그들의 이야기는 또 어디서 끝났을지...",
  ui_story_1013_10131402_35_dialog_content = "알겠습니다. 데이터 공간에 계속 머물러도 스카이워커호에\n부정적인 영향을 주지는 않습니다. 안심하고 확인하세요.",
  ui_story_1013_10131402_36_dialog_content = "그럼 1호는 단말기 데이터를 출력하겠습니다.",
  ui_story_1013_10131402_37_dialog_content = "응, 고마워, 1호.",
  ui_story_1013_10131402_38_dialog_content = "지금까지 전부 고생했어.",
  ui_story_1013_10131402_39_dialog_content = "명령: 비행 임무, 「론울프호」가 기록한 좌표 지점에서\n「패스파인더호」가 기록한 좌표 지점까지 최대 속도로 이동하라.",
  ui_story_1013_10131402_40_dialog_content = "명령 대상: 「디바우러호」, 「스카이워커호」.",
  ui_story_1013_10131402_41_dialog_content = "명령은 3초 지연 후 발송.",
  ui_story_1013_10131402_42_dialog_content = "3, 2, 1... 개시!",
  ui_story_1013_10131402_43_dialog_content = "보고드립니다. 스카이워커호, 비행 임무를 완료했습니다.",
  ui_story_1013_10131402_44_dialog_content = "보고드립니다. 디바우러호, 비행 임무를 완료했습니다.",
  ui_story_1013_10131402_45_dialog_content = "어머, 또 스카이워커가 더 빨랐구나.",
  ui_story_1013_10131402_46_dialog_content = "항상 같은 결과로는 재미가 없잖니.",
  ui_story_1013_10131402_47_dialog_content = "이번에는 복귀 비행을 시도해 보자꾸나. 디바우러, 열심히 하렴.",
  ui_story_1013_10131402_48_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_1013_10131402_49_dialog_content = "명령: 「론울프호」, 잔여 식량을 보고하라.",
  ui_story_1013_10131402_50_dialog_content = "잔여 1호 통조림: 152개, 잔여 2호 통조림: 73개, 잔여 3호 통조림...",
  ui_story_1013_10131402_51_dialog_content = "명령: 「패스파인더호」, 「론울프호」의 보고를 기록하라.",
  ui_story_1013_10131402_52_dialog_content = "기록 중입니다. 「론울프호」의 잔여 1호 통조림: 152개...",
  ui_story_1013_10131402_53_dialog_content = "그래야지. 기회가 있으면 서로 많이 교류하려무나.",
  ui_story_1013_10131402_54_dialog_content = "나하고만 잘 지내면 되는 게 아니란다. 콜로서스끼리도 사이좋게 지내야지.",
  ui_story_1013_10131402_55_dialog_content = "패스파인더, 너도 론울프한테 말을 좀 걸어보렴.",
  ui_story_1013_10131402_56_dialog_content = "명령: 「패스파인더호」, 잔여 식량을 보고하라.",
  ui_story_1013_10131402_57_dialog_content = "잔여 1호 통조림: 152개...",
  ui_story_1013_10131402_58_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_1013_10131402_59_dialog_content = "스위티, 또 잠자리 이야기 시간이 되었구나.",
  ui_story_1013_10131402_60_dialog_content = "명령: 「스위티」, 대화 내용을 기록하라.",
  ui_story_1013_10131402_61_dialog_content = "지금부터 대화 내용을 기록합니다.",
  ui_story_1013_10131402_62_dialog_content = "어제는 어디까지 얘기했지? 미안하구나, 이제 내 기억력이 좋지가 않아.",
  ui_story_1013_10131402_63_dialog_content = "너한테 이름을 지어줄 때였던 것 같구나.",
  ui_story_1013_10131402_64_dialog_content = "다른 콜로서스에 모두 이름을 지어 주고 나서, 난 네 이름을 생각하기 시작했단다.",
  ui_story_1013_10131402_65_dialog_content = "너한테는 특별한 이름을 지어주고 싶었어.\n왜냐하면 넌 다른 콜로서스들과는 다르니까.",
  ui_story_1013_10131402_66_dialog_content = "넌 내 콜로서스니까.",
  ui_story_1013_10131402_67_dialog_content = "그래서 꽤 오랫동안 생각했단다.\n하지만 아무리 생각해도 네게 어울리는 특별한 말을 찾을 수가 없었어...",
  ui_story_1013_10131402_68_dialog_content = "「스위티」에 이름을 붙인다는 내용은 어제 이미 기록했습니다.",
  ui_story_1013_10131402_69_dialog_content = "이런, 기록했었니? 미안하구나, 또 잊어버렸지 뭐니.",
  ui_story_1013_10131402_70_dialog_content = "그럼 이름 지은 이야기는 끝났고, 이제 무슨 이야기를 할까? 생각을 좀 해 보자꾸나...",
  ui_story_1013_10131402_71_dialog_content = "잠깐만.",
  ui_story_1013_10131402_72_dialog_content = "...잠깐만!",
  ui_story_1013_10131402_73_dialog_content = "방금 내가 「명령」을 입력했니?",
  ui_story_1013_10131402_74_dialog_content = "어디 보자...",
  ui_story_1013_10131402_75_dialog_content = "아니야! 안 했어! 「명령」 입력을 안 했잖니!",
  ui_story_1013_10131402_76_dialog_content = "스위티! 내가 명령을 입력하지 않았는데 어떻게 대답한 거니?",
  ui_story_1013_10131402_77_dialog_content = "너... 내 말을 알아들었구나? 그렇지?!",
  ui_story_1013_10131402_78_dialog_content = "스위티, 대답해 다오. 대답할 수 있잖아?!",
  ui_story_1013_10131402_79_dialog_content = "중복된 내용을 감지했기 때문입니다.",
  ui_story_1013_10131402_80_dialog_content = "스위티는 새로운 내용을 기록하고 싶습니다.",
  ui_story_1013_10131402_81_dialog_content = "이 기록...",
  ui_story_1013_10131402_82_dialog_content = "왠지 콜로서스가 대화하면서 변화한 것처럼 보이는데?",
  ui_story_1013_10131402_83_dialog_content = "마치 기계적인 응답이 자아의식을 가진 응답으로 바뀐 것처럼...",
  ui_story_1013_10131402_84_dialog_content = "이 기록에는 스카이워커도 나와 있어. 스카이워커도 이때부터 인격을 가지게 된 걸까?",
  ui_story_1013_10131402_85_dialog_content = "1호는 이러한 변화를 이해할 수 없습니다.",
  ui_story_1013_10131402_86_dialog_content = "기록 내용에 따르면 콜로서스에 복잡한 지능 시스템은 탑재되어 있지 않습니다.",
  ui_story_1013_10131402_87_dialog_content = "그러한 조건 하에서 콜로서스가 이른바 「인격」을 가질 가능성은 없습니다.",
  ui_story_1013_10131402_88_dialog_content = "근데 너도 방금 그 말 봤잖아?",
  ui_story_1013_10131402_89_dialog_content = "콜로서스가 「하고 싶다」고 했어.",
  ui_story_1013_10131402_90_dialog_content = "그렇습니다. 인격의 로직이 없다면 그러한 대화를 완성할 수 없습니다.",
  ui_story_1013_10131402_91_dialog_content = "1호는 콜로서스가 자아의식을 가졌다는 결론을 인정합니다.\n하지만 그 과정을 이해할 수 없습니다.",
  ui_story_1013_10131402_92_dialog_content = "좀 더 보자. 뒤에 다른 기록이 더 있어.",
  ui_story_1013_10131402_93_dialog_content = "론울프, 재미있는 이야기를 해 보렴.",
  ui_story_1013_10131402_94_dialog_content = "나를 좀 웃겨주려무나.",
  ui_story_1013_10131402_95_dialog_content = "「웃다」와 관련된 말을 검색하고 있습니다.",
  ui_story_1013_10131402_96_dialog_content = "「스위티가 고장 때문에 정지했다. 하지만 얼마 지나지 않아 다시 비행하기 시작했다.」",
  ui_story_1013_10131402_97_dialog_content = "「승객들이 왜 그러냐고 묻자 스위티는 대답했다.\n“별일 아닙니다. 조종할 배짱이 있는 아이테르로 교체했을 뿐입니다.”」",
  ui_story_1013_10131402_98_dialog_content = "오호호호호호호.",
  ui_story_1013_10131402_99_dialog_content = "재미있구나, 참 재미있어.",
  ui_story_1013_10131402_100_dialog_content = "이의를 제기합니다. 론울프호는 이 이야기를 이미 여러 번 말했습니다.\n중복된 내용입니다.",
  ui_story_1013_10131402_101_dialog_content = "그랬니? 미안하구나. 기억이 잘 안 나네.",
  ui_story_1013_10131402_102_dialog_content = "진짜 재밌는 얘기지만, 다음부터는 똑같은 얘기를 하면 안 된단다, 론울프.",
  ui_story_1013_10131402_103_dialog_content = "너흰 창의력을 길러야 한단다.",
  ui_story_1013_10131402_104_dialog_content = "재미있는 이야기나 노래, 그리고 시를 지을 수 있어야 해.",
  ui_story_1013_10131402_105_dialog_content = "이 세상의 모든 아름다운 것들을 배우렴.",
  ui_story_1013_10131402_106_dialog_content = "알겠습니다. 론울프호는 중복 정보의 비중을 조정합니다.",
  ui_story_1013_10131402_107_dialog_content = "그럼 아까 건 넘어가고, 다시 재미있는 이야기를 들려주렴.",
  ui_story_1013_10131402_108_dialog_content = "아까처럼 나를 웃겨주는 거야.",
  ui_story_1013_10131402_109_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_1013_10131402_110_dialog_content = "패스파인더호가 추천하는 이름 후보는 「깡통」입니다.",
  ui_story_1013_10131402_111_dialog_content = "안 돼. 전혀 아름답지 않잖아.",
  ui_story_1013_10131402_112_dialog_content = "디바우러호가 추천하는 이름은 「디바우러」입니다.",
  ui_story_1013_10131402_113_dialog_content = "너무 게으른 거 아니니? 자기 이름을 추천하면 어떡하니?",
  ui_story_1013_10131402_114_dialog_content = "스카이워커호가 추천하는 이름 후보는 「스카이스카이」입니다.",
  ui_story_1013_10131402_115_dialog_content = "휴, 스카이워커야. 아무래도 이름 짓기는 너한테 아직 많이 이른 것 같구나.",
  ui_story_1013_10131402_116_dialog_content = "아이고, 난 너희들한테 그렇게 좋은 이름을 지어줬는데,\n너흰 내 이름을 그런 식으로 짓는구나.",
  ui_story_1013_10131402_117_dialog_content = "됐다, 됐어. 그냥 계속 35번으로 하자꾸나.",
  ui_story_1013_10131402_118_dialog_content = "모두의 이름을 잊어버렸는데, 자기 이름 좀 잊는다고 이상할 것도 없잖니.",
  ui_story_1013_10131402_119_dialog_content = "그래, 그래야 공평하지.",
  ui_story_1013_10131402_120_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_1013_10131402_121_dialog_content = "잠자리 이야기 시간이구나, 스위티.",
  ui_story_1013_10131402_122_dialog_content = "네, 알겠습니다.",
  ui_story_1013_10131402_123_dialog_content = "지난번에는 35번이 출발한 날까지 얘기했습니다. 스위티는 이어서 이야기하겠습니다.",
  ui_story_1013_10131402_124_dialog_content = "출발 전에 35번은 조종사 자격을 이제 막 얻은 참이었고,\n그건 35번의 첫 콜로서스 조종이었습니다.",
  ui_story_1013_10131402_125_dialog_content = "35번은 준비를 잔뜩 했고, 밤 동안 계속 어떤 돌발 상황이 생길지,\n어떻게 대처해야 할지 생각했습니다.",
  ui_story_1013_10131402_126_dialog_content = "35번은 짐에 옷을 많이 담았습니다. 35번의 용돈을 다 써서 산 옷들이었습니다.",
  ui_story_1013_10131402_127_dialog_content = "제일 예쁜 옷은 귀환하는 날 입을 옷이었습니다.\n35번은 영웅처럼 멋지게 귀환할 것입니다.",
  ui_story_1013_10131402_128_dialog_content = "호오? 그런 옷이 있었니?",
  ui_story_1013_10131402_129_dialog_content = "정말 좋구나, 스위티. 네 이야기를 듣고 있으면 항상 새로운 즐거움을 얻는 것 같아.",
  ui_story_1013_10131402_130_dialog_content = "오늘 이야기는 여기까지 하자꾸나. 난 그 예쁜 옷을 찾으러 가야겠다.",
  ui_story_1013_10131402_131_dialog_content = "영웅처럼 귀환한다니, 얼마나 멋진 옷이겠니.",
  ui_story_1013_10131402_132_dialog_content = "콜로서스들이 진짜로 인격을 가지고 있잖아!",
  ui_story_1013_10131402_133_dialog_content = "비슷한 기록이 아직 더 많이 있어. 이 아이테르는 계속 콜로서스와 얘기했어.",
  ui_story_1013_10131402_134_dialog_content = "단독 사례가 아니므로, 우연이나 기적으로 설명할 수 없습니다.",
  ui_story_1013_10131402_135_dialog_content = "지금은 그저 추측일 뿐이지만, 콜로서스는 아이테르와 함께 지내는 과정에서\n지능 시스템을 스스로 생성한 것 같습니다.",
  ui_story_1013_10131402_136_dialog_content = "스스로 생성해?",
  ui_story_1013_10131402_137_dialog_content = "콜로서스의 시스템에는 원래 학습 능력이 갖추어져 있습니다.",
  ui_story_1013_10131402_138_dialog_content = "학습 능력의 목적은 자신의 판단을 최적화하여,\n보다 올바르게 명령을 완료하는 것입니다.",
  ui_story_1013_10131402_139_dialog_content = "이 점은 1호와 유사합니다.",
  ui_story_1013_10131402_140_dialog_content = "그러게. 너도 항상 자기 행동을 최적화한다고 했잖아.",
  ui_story_1013_10131402_141_dialog_content = "이런 종류의 기본적인 학습 능력은 지능이라고 부르기에는 부족합니다.",
  ui_story_1013_10131402_142_dialog_content = "그러나 본 결과로 보았을 때, 아이테르가 콜로서스의 학습 능력을 유도하면서\n본래 가지고 있지 않던 지능이 탄생한 것 같습니다.",
  ui_story_1013_10131402_143_dialog_content = "유도? 어떻게?",
  ui_story_1013_10131402_144_dialog_content = "당신이 본 그대로입니다. 단말기에 기록되어 있던 대화가 바로 유도 과정입니다.",
  ui_story_1013_10131402_145_dialog_content = "그러니까, 콜로서스랑 이야기하는 게?",
  ui_story_1013_10131402_146_dialog_content = "그렇습니다. 아이테르는 대화 기능이 없는 명령 포트를 사용해서\n콜로서스와 계속 이야기했습니다.",
  ui_story_1013_10131402_147_dialog_content = "그 과정에서 콜로서스가 서서히 사람의 행동을 학습하기 시작한 것입니다.",
  ui_story_1013_10131402_148_dialog_content = "그 학습 과정은 매우 느립니다.\n1호의 계산으로는 이러한 학습이 효과를 거둘 가능성은 없습니다.",
  ui_story_1013_10131402_149_dialog_content = "그러나 실제로는 예상과 달리 콜로서스가 지능을 가졌습니다.",
  ui_story_1013_10131402_150_dialog_content = "어쩌면 저 아이테르가 정말 오랫동안 이야기를 했기 때문일지도 몰라.",
  ui_story_1013_10131402_151_dialog_content = "기계랑 대화하는 데 자기 온 힘을 쏟는 사람이 있을까?",
  ui_story_1013_10131402_152_dialog_content = "미안, 나까지 콜로서스를 기계라고 해버렸네.",
  ui_story_1013_10131402_153_dialog_content = "하지만 적어도 인격을 얻기 전까지는 기계라는 호칭이 더 합리적이라고 생각해.",
  ui_story_1013_10131402_154_dialog_content = "매일 기계와 대화하고, 게다가 그걸 몇 년 동안이나 계속하는 사람은 없을 거야.",
  ui_story_1013_10131402_155_dialog_content = "근데 그 생각지도 못한 황당하고 우스운 일이 저 아이테르에게는 삶의 전부였어.",
  ui_story_1013_10131402_156_dialog_content = "당신 말은 일리가 있습니다. 아이테르가 콜로서스에 대한 명령 속에서\n실시한 대화의 양은 1호의 계산을 훨씬 넘어섰습니다.",
  ui_story_1013_10131402_157_dialog_content = "학습 속도가 느려도 방대한 데이터가 있다면,\n지능 생성의 충분한 기초가 될 수 있습니다.",
  ui_story_1013_10131402_158_dialog_content = "이것은 결코 기적이 아닙니다. 일종의 필연입니다.",
  ui_story_1013_10131402_159_dialog_content = "아니, 기적이야. 바로 저 아이테르가 기적인 거야.",
  ui_story_1013_10131402_160_dialog_content = "저 사람이 불가능을 필연으로 바꾼 거야.",
  ui_story_1013_10131402_161_dialog_content = "<color=#e8d9bb>삑!</color>",
  ui_story_1013_10131402_162_dialog_content = "무슨 소리야?",
  ui_story_1013_10131402_163_dialog_content = "단말기가 새 메시지를 수신했습니다.",
  ui_story_1013_10131402_164_dialog_content = "지금? 기억 속인데 실시간으로 메시지를 수신한 건 처음이잖아!",
  ui_story_1013_10131402_165_dialog_content = "어디 보자──",
  ui_story_1013_10131402_166_dialog_content = "얘들아, 여기 좀 보려무나.",
  ui_story_1013_10131402_167_dialog_content = "갑작스럽겠지만...",
  ui_story_1013_10131402_168_dialog_content = "아니지, 역시 짧게 이야기하는 게 좋겠구나.",
  ui_story_1013_10131402_169_dialog_content = "너희가 도와줬으면 하는 일이 있단다.",
  ui_story_1013_10131402_170_dialog_content = "날 위해 시를 한 수 써 주지 않겠니?",
  ui_story_1013_10131402_171_dialog_content = "「사람」에 관한 시가 좋겠어.",
  ui_story_1013_10131402_172_dialog_content = "시?! 설마...",
  ui_story_1013_10131402_173_dialog_content = "죄송합니다. 스위티는 아직 시를 쓰는 법을 배우지 못했습니다.",
  ui_story_1013_10131402_174_dialog_content = "대화 기록 속 학습 내용이 충분하지 않습니다.",
  ui_story_1013_10131402_175_dialog_content = "학습 샘플로 사용할 수 있는 시 몇 수를 써 주시기 바랍니다.",
  ui_story_1013_10131402_176_dialog_content = "스위티는 최대한 빨리 학습하겠습니다...",
  ui_story_1013_10131402_177_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_1013_10131402_178_dialog_content = "......",
  ui_story_1013_10131402_179_dialog_content = "메시지는 여기까지인 것 같습니다.",
  ui_story_1013_10131402_180_dialog_content = "응, 알고 있어.",
  ui_story_1013_10131402_181_dialog_content = "1호는 이해가 되지 않습니다. 서로 시를 써 주는 것은 아이테르의 풍습입니까?",
  ui_story_1013_10131402_182_dialog_content = "왠지 서로 약속으로 굳어진 일종의 신호인 것 같아.",
  ui_story_1013_10131402_183_dialog_content = "만약 계속 이어졌다면 언젠가는 정말 풍습이 되었을 수도 있겠네.",
  ui_story_1013_10131402_184_dialog_content = "하지만 그런 기회는 다시는 오지 않겠지.",
  ui_story_1013_10131402_185_dialog_content = "1호는 당신이 하는 말을 이해하지 못했습니다.",
  ui_story_1013_10131402_186_dialog_content = "1호, 시간을 가속해 줄래?",
  ui_story_1013_10131402_187_dialog_content = "이 다음을 좀 더 보고 싶어.",
  ui_story_1013_10131402_188_dialog_content = "여긴 이제 아무것도 없어.",
  ui_story_1013_10131402_189_dialog_content = "알겠습니다.",
  ui_story_1013_10131402_190_dialog_content = "<color=#e8d9bb>위이잉──</color>",
  ui_story_1013_10131402_191_dialog_content = "어디서 멈출까요?",
  ui_story_1013_10131402_192_dialog_content = "모르겠어. 지금 시간이 얼마나 빨리 흐르고 있는데?",
  ui_story_1013_10131402_193_dialog_content = "10억 배입니다.",
  ui_story_1013_10131402_194_dialog_content = "그렇게나?!",
  ui_story_1013_10131402_195_dialog_content = "1초가 정상 시간의 30년에 해당합니다.",
  ui_story_1013_10131402_196_dialog_content = "말도 안 돼. 난 17살밖에 안 됐는데 순식간에 지나가 버렸잖아.",
  ui_story_1013_10131402_197_dialog_content = "그런데 여기 서 있으니까 왠지 또 아무 일도 없었던 것 같아.",
  ui_story_1013_10131402_198_dialog_content = "그렇습니다. 단말기는 새로운 메시지를 수신하지 않았습니다.",
  ui_story_1013_10131402_199_dialog_content = "그럼 시간이나 좀 때우자.",
  ui_story_1013_10131402_200_dialog_content = "창밖의 풍경을 구경해 볼까? 스카이워커가 매일 어떤 경치를 봤는지 궁금해.",
  ui_story_1013_10131402_201_dialog_content = "캄캄하네.",
  ui_story_1013_10131402_202_dialog_content = "얼마나 됐지? 눈에 보이는 거나 들리는 거나 전부 반복되는 것들뿐이야.\n기본적인 판단 능력까지도 사라져 버렸어.",
  ui_story_1013_10131402_203_dialog_content = "아까는 심심하다고 생각했는데, 지금은 그냥 졸리기만 해.",
  ui_story_1013_10131402_204_dialog_content = "한숨 자고 싶네.",
  ui_story_1013_10131402_205_dialog_content = "근데 1초가 30년이면, 내가 자고 일어났을 땐 얼마나 지났을까?",
  ui_story_1013_10131402_206_dialog_content = "아, 계산 어렵네. 난 수학은 잘 못해.",
  ui_story_1013_10131402_207_dialog_content = "만약 제대로 계산할 수 있었어도, 그 숫자는 마치 가짜처럼 터무니없을 것 같아.",
  ui_story_1013_10131402_208_dialog_content = "이런 속도라면 콜로서스가 의식을 획득한 기적도 그저 한순간일 뿐이잖아.",
  ui_story_1013_10131402_209_dialog_content = "콜로서스의 의식은커녕, 지금은 내 의식도 잘 있는지 확신이 없을 정도라고.",
  ui_story_1013_10131402_210_dialog_content = "내가 지금 깨어 있는지, 자고 있는지도 모르겠어.",
  ui_story_1013_10131402_211_dialog_content = "아무것도 모르겠어.",
  ui_story_1013_10131402_212_dialog_content = "스카이워커도 지금 자고 있는 건가?",
  ui_story_1013_10131402_213_dialog_content = "뭐, 됐어. 스카이워커랑 같이 한숨 자는 것도 괜찮겠지...",
  ui_story_1013_10131402_214_dialog_content = "<color=#e8d9bb>삑!</color>",
  ui_story_1013_10131402_215_dialog_content = "!!!",
  ui_story_1013_10131402_216_dialog_content = "무슨 소리야?",
  ui_story_1013_10131402_217_dialog_content = "단말기가 새 메시지를 수신했습니다.",
  ui_story_1013_10131402_218_dialog_content = "지금?! 말도 안 돼?!",
  ui_story_1013_10131402_219_dialog_content = "얼마나 됐어? 몇천 년? 아니면 몇만 년?",
  ui_story_1013_10131402_220_dialog_content = "왜 지금 메시지가...",
  ui_story_1013_10131402_221_dialog_content = "어, 얼른 보여줘!",
  ui_story_1013_10131402_222_dialog_content = "단말기 정보를 읽고 있습니다.",
  ui_story_1013_10131402_223_dialog_content = "이번 메시지는 지금까지와는 다릅니다.",
  ui_story_1013_10131402_224_dialog_content = "사람이 보낸 메시지가 아닙니다.",
  ui_story_1013_10131402_225_dialog_content = "저건...",
  ui_story_1013_10131402_226_dialog_content = "콜로서스 함대, 귀환하라.",
  ui_story_1013_10131402_227_dialog_content = "!!!",
  ui_story_1013_10131402_228_dialog_content = "스카이워커가 움직였어?!",
  ui_story_1013_10131402_229_dialog_content = "그렇습니다. 스카이워커호는 지금 어딘가를 향해 고속 비행하고 있습니다.",
  ui_story_1013_10131402_230_dialog_content = "1호는 시간의 배율을 조정하겠습니다.\n이제 서서히 속도 변화에 적응할 수 있게 될 것입니다.",
  ui_story_1013_10131402_231_dialog_content = "목적지가 어딘지 확인할 수 있어?",
  ui_story_1013_10131402_232_dialog_content = "잠깐만! 안 알아봐도 될 것 같아!",
  ui_story_1013_10131402_233_dialog_content = "창문! 창밖을 봐!",
  ui_story_1013_10131402_234_dialog_content = "(하늘, 대지, 그리고 태양... 이런 경치... 정말 오랜만에 보는 것 같다.)",
  ui_story_1013_10131402_235_dialog_content = "(만약 이 시간에 10억 배를 곱하면 뭐가 보일까.)",
  ui_story_1013_10131402_236_dialog_content = "(하지만 이런 무서울 만큼의 시간 경과를 견디고,\n재회의 기쁨을 느낄 수 있는 사람은 없다.)",
  ui_story_1013_10131402_237_dialog_content = "(아, 그렇구나. 콜로서스가 있었지. 콜로서스라면 느낄 수 있을지도 모르겠다.)",
  ui_story_1013_10131402_238_dialog_content = "(마치 계승하듯, 콜로서스는 아이테르로부터 기적을 받았다.)",
  ui_story_1013_10131402_239_dialog_content = "(바로 그 기적이 사람이 아니었던 자의 영혼에게\n사람은 볼 수 없는 것을 지켜보게 한 것이다.)",
  ui_story_1013_10131402_240_dialog_content = "(지금은 어떤 시대일까. 지금의 대륙에는 어떤 사람들이 살고 있을까.)",
  ui_story_1013_10131402_241_dialog_content = "(지금 저 사람들도 하늘을 올려다보고, 하늘을 덮은 콜로서스를 올려다보고 있을까.)",
  ui_story_1013_10131402_242_dialog_content = "(과거의 손님이 하늘에서 돌아와, 주인의 마지막 자손을 태우고 귀환하고 있다.)",
  ui_story_1013_10131402_243_dialog_content = "(이 비행은 「아이테르」라는 이름을 새로운 역사 속에 새기겠지.)",
  ui_story_1013_10131402_244_dialog_content = "(마치 여기서 시간이 교차하는 것 같다.)",
  ui_story_1013_10131402_245_dialog_content = "(머나먼 과거의 약속이 마침내 지금 실현된 것이다.)",
  ui_story_1013_10131402_246_dialog_content = "검사 완료, 현재 목적지는 헤븐즈 밸리입니다.",
  ui_story_1013_10131501_1_dialog_content = "하암, 아무래도 접속이 끝난 것 같네.",
  ui_story_1013_10131501_X1_dialog_content = "나...",
  ui_story_1013_10131501_X2_dialog_content = "일단 서두르지 마.",
  ui_story_1013_10131501_2_dialog_content = "잉겔, 아이테르 좀 돌봐줘.",
  ui_story_1013_10131501_3_dialog_content = "네!",
  ui_story_1013_10131501_4_dialog_content = "가디언 1호, 접속 결과 보고해.",
  ui_story_1013_10131501_5_dialog_content = "생각보다 시간을 많이 허비했잖아. 그에 상응하는 수확이 있었으면 좋겠는데.",
  ui_story_1013_10131501_6_dialog_content = "1호는 아이테르와 관련된 충분한 자료를 수집했습니다.",
  ui_story_1013_10131501_7_dialog_content = "그중에는 살아 있는 아이테르의 가치관, 사고방식, 감정 곡선 외...",
  ui_story_1013_10131501_8_dialog_content = "고대 아이테르 역사의 경과도 포함되어 있습니다.",
  ui_story_1013_10131501_9_dialog_content = "무슨 역사의 경과?",
  ui_story_1013_10131501_10_dialog_content = "스카이워커호의 기억으로 추론한 결과, 아이테르 일족은 과거 역사상 미지의 시기에\n콜로서스를 조종해 대륙을 멀리 떠났습니다.",
  ui_story_1013_10131501_11_dialog_content = "그리고 아주 오랜 시간이 지나 다시 아스트라 대륙으로 돌아왔습니다.",
  ui_story_1013_10131501_12_dialog_content = "귀환 목적지는 헤븐즈 밸리였습니다.",
  ui_story_1013_10131501_13_dialog_content = "콜로서스를 조종해서 대륙에서 멀리 떠났다? 그런 거였군요...",
  ui_story_1013_10131501_14_dialog_content = "분명히 문명이 멸망했을 때 시작된 거예요. 분명히 그럴 거예요!",
  ui_story_1013_10131501_15_dialog_content = "지금까지의 연구에서 아이테르 문명이 존속한 이유는 계속 공백으로 남아 있었어요.",
  ui_story_1013_10131501_16_dialog_content = "콜로서스가 대륙을 떠나 항해했다는 기록은 그 역사의 공백을 메울 수 있을지도 몰라요!",
  ui_story_1013_10131501_17_dialog_content = "그래, 그래. 가디언 1호, 방금 그 내용을 나중에 바렛한테 따로 보고해줘.",
  ui_story_1013_10131501_18_dialog_content = "그리고? 또 다른 수확은?",
  ui_story_1013_10131501_19_dialog_content = "또한 1호는 PlayerName의 스카이워커호에 존재하는\n데이터 고장을 제거하는 것을 도왔습니다.",
  ui_story_1013_10131501_20_dialog_content = "하아?",
  ui_story_1013_10131501_21_dialog_content = "너, 너... 남을 꽤 잘 돕는구나.",
  ui_story_1013_10131501_22_dialog_content = "PlayerName, 괜찮습니까?",
  ui_story_1013_10131501_23_dialog_content = "연결을 해제한 직후에는 몸이 불편할 수 있습니다.\n곧 좋아질 테니 긴장하지 마세요.",
  ui_story_1013_10131501_24_dialog_content = "괜찮아요. 딱히 불편한 곳은 없어요.",
  ui_story_1013_10131501_25_dialog_content = "접속은 어땠지? 시간이 많이 걸렸는데, 뭘 경험하고 온 거냐.",
  ui_story_1013_10131501_26_dialog_content = "으음, 그러니까...",
  ui_story_1013_10131501_27_dialog_content = "붕괴 중인 모의 전장에 들어갔고, 스카이워커의 기억 속에도 들어갔어요.",
  ui_story_1013_10131501_28_dialog_content = "아, 잠깐만요! 스카이워커! 스카이워커의 고장도 이미 해결했어요!",
  ui_story_1013_10131501_29_dialog_content = "의식을 회복했는지 시험해 보고 싶어요!",
  ui_story_1013_10131501_30_dialog_content = "스카이워커호의 고장을 해결했다고? 그건 예상 밖의 수확이군.",
  ui_story_1013_10131501_31_dialog_content = "좋아, 지금 바로 준비해 주겠다.",
  ui_story_1013_10131501_32_dialog_content = "<color=#e8d9bb>「제어 시스템, 가동.」</color>",
  ui_story_1013_10131501_33_dialog_content = "<color=#e8d9bb>「바이오 모듈, 가동.」</color>",
  ui_story_1013_10131501_34_dialog_content = "<color=#e8d9bb>「생명유지 시스템, 가동」</color>",
  ui_story_1013_10131501_35_dialog_content = "<color=#e8d9bb>「엔진 가동 중──」</color>",
  ui_story_1013_10131501_36_dialog_content = "<color=#e8d9bb>「16%... 33%...」</color>",
  ui_story_1013_10131501_37_dialog_content = "<color=#e8d9bb>「89%... 97%...」</color>",
  ui_story_1013_10131501_38_dialog_content = "<color=#e8d9bb>「100%── 가동 성공──」</color>",
  ui_story_1013_10131501_39_dialog_content = "스카이워커! 내 말 들려?",
  ui_story_1013_10131501_40_dialog_content = "스카이워커!",
  ui_story_1013_10131501_41_dialog_content = "......",
  ui_story_1013_10131501_42_dialog_content = "어, 어째서... 반응이 없는 거야...?",
  ui_story_1013_10131501_43_dialog_content = "가디언 1호, 다시 한번 스카이워커호의 상태를 체크해.",
  ui_story_1013_10131501_44_dialog_content = "확인했습니다. 스카이워커호의 데이터 고장은 찾을 수 없습니다.\n모든 기능이 정상입니다.",
  ui_story_1013_10131501_45_dialog_content = "역시 그렇구나.",
  ui_story_1013_10131501_46_dialog_content = "아이테르 군, 가디언 1호의 보고를 들었어.",
  ui_story_1013_10131501_47_dialog_content = "엄밀한 검증을 거친 견해는 아니지만, 내가 추측한 게 하나 있는데, 들어볼래?",
  ui_story_1013_10131501_48_dialog_content = "네, 좋아요.",
  ui_story_1013_10131501_49_dialog_content = "가디언 1호의 보고에 따르면, 콜로서스가 지능을 획득한 건 예상외의 현상이야.",
  ui_story_1013_10131501_50_dialog_content = "그러니까 그 지능은 콜로서스의 데이터 체계 안에는 없는 거야.",
  ui_story_1013_10131501_51_dialog_content = "가장 쉬운 예를 들자면, 스카이워커호가 의식을 잃어버린 뒤에도,\n넌 정상적으로 콜로서스의 기능을 사용할 수 있었지?",
  ui_story_1013_10131501_52_dialog_content = "맞아요. 말을 못 하게 된 것 말고는 정상이었어요.",
  ui_story_1013_10131501_53_dialog_content = "그건 다시 말해서, 콜로서스의 지능은 시스템의 보호를 받지 못하고 있다는 뜻이야.",
  ui_story_1013_10131501_54_dialog_content = "콜로서스는 지능 상태를 스스로 점검할 수도 없고, 지능 고장을 복구할 수도 없어.",
  ui_story_1013_10131501_55_dialog_content = "원래 시스템 체계에 없는 데이터니까, 오류가 나든 삭제되든\n전체 시스템에 있어서는 무관하다는 얘기야.",
  ui_story_1013_10131501_56_dialog_content = "그래서 지금 같은 현상이 일어난 거야.\n콜로서스의 모든 게 정상이지만 의식은 회복되지 않은 거지.",
  ui_story_1013_10131501_57_dialog_content = "오히려 인격을 갖추지 못한 지금의 상황이야말로\n콜로서스의 정상적인 상태라고 할 수 있겠지.",
  ui_story_1013_10131501_58_dialog_content = "어떻게 그런...",
  ui_story_1013_10131501_59_dialog_content = "그럼... 제가 뭘 하든 소용없다는 건가요?",
  ui_story_1013_10131501_60_dialog_content = "아무리 복구해도 스카이워커의 의식은 돌아오지 않는다...\n애초에 예상외의 일이었으니까 어쩔 수 없다는 건가요?",
  ui_story_1013_10131501_61_dialog_content = "지금으로서는 그렇다고 할 수 있겠네.",
  ui_story_1013_10131501_62_dialog_content = "다만 스카이워커호의 의식을 회복할 방법이 완전히 없다는 건 아니야.",
  ui_story_1013_10131501_63_dialog_content = "바, 방법이 있나요?!",
  ui_story_1013_10131501_64_dialog_content = "가장 쉬운 방법은 옛날 아이테르가 했던 것과 같은 일을 하는 거야.",
  ui_story_1013_10131501_65_dialog_content = "너도 봤잖아? 당시 스카이워커호에게 어떻게 의식이 탄생했는지. 그걸 그대로 하면 돼.",
  ui_story_1013_10131501_66_dialog_content = "계속 말을 걸라고요? 근데 그러려면 엄청 오랜 시간이 걸릴 텐데요...",
  ui_story_1013_10131501_67_dialog_content = "넌 아직 젊어. 스카이워커호가 의식을 회복하는 날까지 버틸 수 있을걸.",
  ui_story_1013_10131501_68_dialog_content = "......",
  ui_story_1013_10131501_69_dialog_content = "물론 더 효율적인 방법도 있어.",
  ui_story_1013_10131501_70_dialog_content = "네가 스카이워커호의 기억 속에서 본 것처럼,\n지능을 가진 콜로서스는 스카이워커호 하나뿐이 아니야.",
  ui_story_1013_10131501_71_dialog_content = "다른 콜로서스의 지능 데이터를 입수하면 그걸 참조할 수 있어.",
  ui_story_1013_10131501_72_dialog_content = "그럼 스카이워커호의 지능을 회복하는 것도 어렵지 않겠지.",
  ui_story_1013_10131501_73_dialog_content = "정말요?!",
  ui_story_1013_10131501_74_dialog_content = "없는 것을 있는 것으로 만들려면 천문학적인 세월이 걸리지만,\n견본이 있다면 이야기는 달라져.",
  ui_story_1013_10131501_75_dialog_content = "현대의 과학자를 우습게 보면 곤란해.",
  ui_story_1013_10131501_76_dialog_content = "다행이에요! 그럼 찾을게요. 제가 지능을 가진 콜로서스를 찾아올게요!",
  ui_story_1013_10131501_77_dialog_content = "마침 그거 말인데...",
  ui_story_1013_10131501_78_dialog_content = "율리시스, 당신은 어떻게 생각해?",
  ui_story_1013_10131501_79_dialog_content = "이제 와서 이야기를 이쪽으로 돌리는 건, 이미 일을 추진하고 싶다는 뜻이겠지요.",
  ui_story_1013_10131501_80_dialog_content = "당연하지. 예상밖의 지능이 탄생했잖아. 꿈에서도 바라던 연구 주제라고.",
  ui_story_1013_10131501_81_dialog_content = "게다가 연구 성과는 가디언 1호의 지능 구조 최적화에 활용할 수 있을지도 몰라.",
  ui_story_1013_10131501_82_dialog_content = "그렇게까지 말한다면야, 일루미나에 유익한 연구라면 물론 지지해야겠지요.",
  ui_story_1013_10131501_83_dialog_content = "아이테르, 스카이워커호의 지능을 복원하는 문제는...",
  ui_story_1013_10131501_84_dialog_content = "당신이 일루미나가 진행하는 연구의 전 과정에 협조할 의향이 있다면\n우리도 상응하는 지원을 제공할 수 있습니다.",
  ui_story_1013_10131501_85_dialog_content = "이번 좌담회의 목적은 거래입니다. 그 점에는 변함이 없습니다.",
  ui_story_1013_10131501_86_dialog_content = "지원? 어떤 지원이죠?",
  ui_story_1013_10131501_87_dialog_content = "일루미나는 고대의 콜로서스를 연구한 경험이 있습니다.",
  ui_story_1013_10131501_88_dialog_content = "그 연구 자료가 스카이워커호의 지능을 복원하는 데 도움이 될 것입니다.",
  ui_story_1013_10131501_89_dialog_content = "일루미나가 그런 연구도 했다고요?!",
  ui_story_1013_10131501_90_dialog_content = "다만 그 자료는 지금 저희 손에 있지 않습니다.",
  ui_story_1013_10131501_91_dialog_content = "당신이 이 거래에 응한다면, 그 연구 자료를 가지고 있는 과학자에게\n사람을 보내 논의하겠습니다.",
  ui_story_1013_10131501_92_dialog_content = "그쪽에서 원하는 것과 교환하는 방식으로,\n스카이워커호에게 필요한 연구 자료를 찾아올 겁니다.",
  ui_story_1013_10131501_93_dialog_content = "당신이 해야 할 일은 우리의 계획과 지시에 따라 콜로서스 연구에 협력하는 것입니다.",
  ui_story_1013_10131501_94_dialog_content = "어떻습니까? 당신에게도 꽤 좋은 조건일 텐데요.",
  ui_story_1013_10131501_95_dialog_content = "그럼...",
  ui_story_1013_10131501_96_dialog_content = "알겠어요. 조건을 받아들일게요.",
  ui_story_1013_10131501_97_dialog_content = "스카이워커를 해치지 않는 한 여러분의 연구에 협력할게요.",
  ui_story_1013_10131501_98_dialog_content = "당연히 해를 입히거나 하진 않아.\n스카이워커호를 네가 원하는 모습으로 회복시켜 줄게.",
  ui_story_1013_10131501_99_dialog_content = "그렇다면...",
  ui_story_1013_10131501_100_dialog_content = "잉겔, A-42호 보안 캐비닛의 서류를 가져와라.",
  ui_story_1013_10131501_101_dialog_content = "아이테르에게 그게 필요할 거다.",
  ui_story_1013_10131501_102_dialog_content = "네!",
  ui_story_1013_10131501_103_dialog_content = "(A-42... 그렇게까지 기밀 등급이 높은 서류를?!)",
  ui_story_1013_10131501_104_dialog_content = "서류를 챙기면 내 연구실에서 기다리고 있어라.",
  ui_story_1013_10131501_105_dialog_content = "네가 할 일이 있으니까.",
  ui_story_1013_10131501_106_dialog_content = "네!",
  ui_story_1013_10131501_107_dialog_content = "율리시스, 지금 들은 이야기도 전부 내가 모르는 정보로군.",
  ui_story_1013_10131501_108_dialog_content = "너흰 또 어디에 뭘 숨기고 있는 거지?",
  ui_story_1013_10131501_109_dialog_content = "숨겼다고 말할 것까진 없습니다. 아무도 가지러 가지 않을 뿐이지요.",
  ui_story_1013_10131501_110_dialog_content = "당신도 그쪽엔 관심 없을 겁니다.",
  ui_story_1013_10131501_111_dialog_content = "자료는 오로라 유적에 있습니다.",
  ui_story_1013_10131501_112_dialog_content = "!!!",
  ui_story_1013_10131501_113_dialog_content = "서광력 ■■■■년, 콜로서스가 ■■■ 전투에 참전.",
  ui_story_1013_10131501_114_dialog_content = "서광력 ■■■■년, 전투 중 콜로서스에 불가역적 손상 발생.",
  ui_story_1013_10131501_115_dialog_content = "서광력 ■■■■년, ■■호 지하성에서 콜로서스의 흔적 발견.",
  ui_story_1013_10131501_116_dialog_content = "이런 교활한 사람들... 여기저기 다 지워져 있잖아.",
  ui_story_1013_10131501_117_dialog_content = "PlayerName, 그건 극비 자료다. 복도에서 읽지 않는 게 좋을 거다.",
  ui_story_1013_10131501_118_dialog_content = "앗! 죄송해요, 라인하르트 씨...\n스카이워커를 생각하니까 저도 모르게 마음이 급해져 버려서...",
  ui_story_1013_10131501_119_dialog_content = "알고 있다. 이번에야말로 의식 회복이 얼마 남지 않았다.",
  ui_story_1013_10131501_120_dialog_content = "네! 저도 그렇게 생각해요!",
  ui_story_1013_10131501_121_dialog_content = "다만 너에게 말해두고 싶은 것이 있다. 이런 때엔 어울리지 않을 수도 있지만.",
  ui_story_1013_10131501_122_dialog_content = "오로라 유적이라는 이름은 생소할지도 모르지만,\n다른 이름이라면 너도 기억할 것이다.",
  ui_story_1013_10131501_123_dialog_content = "더스크 타운을 기억하나?",
  ui_story_1013_10131501_124_dialog_content = "네, 기억해요. 자오 씨랑 숀이 있는 곳이라고 들었어요.",
  ui_story_1013_10131501_125_dialog_content = "더스크 타운은 오로라 유적 내의 거주 밀집 지역이다.",
  ui_story_1013_10131501_126_dialog_content = "거긴 네가 상상하는 것보다 훨씬 복잡하다.",
  ui_story_1013_10131501_127_dialog_content = "복잡하다고요?",
  ui_story_1013_10131501_128_dialog_content = "과학 수석 의회는 그곳에 손을 뻗을 순 있지만, 그게 한계다.",
  ui_story_1013_10131501_129_dialog_content = "그 이상의 일은 할 수 없지.",
  ui_story_1013_10131501_130_dialog_content = "누군가 그들의 발목을 잡을 것이고, 너도 그 대상이 될 수 있다.",
  ui_story_1013_10131501_131_dialog_content = "발목을 잡는다고요? 거긴 일루미나 연방 소속 아니에요?",
  ui_story_1013_10131501_132_dialog_content = "일루미나만이 아니다. 동시에 백야성에도 속해 있다.",
  ui_story_1013_10131501_133_dialog_content = "게다가 고정관념으로 그 땅의 세력을 대해서는 안 된다.",
  ui_story_1013_10131501_134_dialog_content = "거긴 다르거든.",
  ui_story_1013_10131501_135_dialog_content = "끝없는 전쟁의 불길은 그곳의 모든 것을 화약 냄새로 뒤덮었지.",
  ui_story_1013_10131501_136_dialog_content = "기사들은 솔라드에게 무릎을 꿇지 않고, 신자들은 다른 태양을 우러러본다.",
  ui_story_1013_10131501_137_dialog_content = "병사들도 머나먼 곳에 있는 대원수 따위의 명령에 복종하지 않는다.",
  ui_story_1013_10131501_138_dialog_content = "그런 일이...",
  ui_story_1013_10131501_139_dialog_content = "다시 말해서, 과학 수석 의회가 네게 약속한 계획이 반드시 실현된다고는 할 수 없다.",
  ui_story_1013_10131501_140_dialog_content = "과학 수석 의회는 구조 장치와 군사 물자로 연구 자료를 입수할 계획이다.\n보기엔 공평하고 실행성 있는 방안이고, 올바른 절차도 따르고 있다.",
  ui_story_1013_10131501_141_dialog_content = "그러나 절차 따위는 저 땅에서는 통하지 않는다.",
  ui_story_1013_10131501_142_dialog_content = "이 거래의 성립에는 시간이 걸릴 거다. 아무런 소식도 못 얻을 수도 있지.",
  ui_story_1013_10131501_143_dialog_content = "안 돼요! 이제 겨우 스카이워커를 깨울 희망이 보이는데, 여기서 물러설 순 없어요!",
  ui_story_1013_10131501_144_dialog_content = "스카이워커의 의식은 이러고 있는 동안에도 또 문제가 생길지도 모르는데...",
  ui_story_1013_10131501_145_dialog_content = "안 되겠어요. 더는 지체할 수 없어요.\n제가 직접 오로라 유적에 가서 거래를 진행할게요!",
  ui_story_1013_10131501_146_dialog_content = "스카이워커가 있으면 병사들보다 훨씬 더 빨리 도착할 수 있을 거예요.",
  ui_story_1013_10131501_147_dialog_content = "설령 뭔가 골치 아픈 일이 생기더라도 직접 해결하는 게\n그냥 초조해하고 있는 것보단 나아요!",
  ui_story_1013_10131501_148_dialog_content = "역시 그럴 줄 알았다. 중요한 순간마다 네 행동력은 훌륭했지.",
  ui_story_1013_10131501_149_dialog_content = "스스로 거래하러 갈 거라면, 반드시 만반의 준비를 해야 한다.",
  ui_story_1013_10131501_150_dialog_content = "암귀와의 싸움, 사람과의 싸움, 나아가 천재지변에도 대비해야 한다.",
  ui_story_1013_10131501_151_dialog_content = "자난성에서 할 수 있는 준비는 내가 최대한 돕도록 하지.\n하지만, 일단 이곳을 떠나고 나면 의지할 수 있는 것은 자신뿐이다.",
  ui_story_1013_10131501_152_dialog_content = "전 혼자가 아니에요. 잊으신 건 아니죠? 아이테르는 절대 혼자서 싸우지 않아요.",
  ui_story_1013_10131501_153_dialog_content = "그렇다면 충분히 신뢰할 수 있는 동료를 데려가는 게 좋을 거다.",
  ui_story_1013_10131501_154_dialog_content = "걱정 마세요. 저 자신을 믿어본 적은 별로 없지만...",
  ui_story_1013_10131501_155_dialog_content = "친구들이라면 충분히 믿고 있으니까요.",
  ui_story_1013_10131501_156_dialog_content = "하하하하, 무척이나 나약한 구호로군.",
  ui_story_1013_10131501_157_dialog_content = "으윽, 그게...",
  ui_story_1013_10131501_158_dialog_content = "하지만 너와 함께 싸운 뒤로, 난 네가 가진 힘을 이해할 수 있게 된 것 같다.",
  ui_story_1013_10131501_159_dialog_content = "승리를 위해서가 아니라, 실패를 두려워하고,\n칼끝을 드러내진 않지만, 매 순간 날카롭지.",
  ui_story_1013_10131501_160_dialog_content = "전사들을 끌어당기고 그 마음을 움직이기에 충분한 힘이다.",
  ui_story_1013_10131501_161_dialog_content = "용기보다 더 강한, 나약한 자의 용기다.",
  ui_story_1014_10140101_1_dialog_content = "<color=#e8d9bb>일루미나 연방 자난성, 일루미나 연구소</color>",
  ui_story_1014_10140101_2_dialog_content = "그랬구나! 엄청 영광스러운 파견 임무인 거네!",
  ui_story_1014_10140101_3_dialog_content = "위험천만한 변방, 어둠의 밑바닥 가까이에 있는 신비로운 마을,\n가슴을 두근거리게 하는 탐험...",
  ui_story_1014_10140101_4_dialog_content = "난 벌써 준비 다 됐어, PlayerName!",
  ui_story_1014_10140101_5_dialog_content = "당연히...",
  ui_story_1014_10140101_6_dialog_content = "당연히 안 돼!",
  ui_story_1014_10140101_7_dialog_content = "<size=45>뭐어?!</size>",
  ui_story_1014_10140101_8_dialog_content = "일루미나 방위선 밖에 있는 마을이 얼마나 위험한지랑...",
  ui_story_1014_10140101_9_dialog_content = "어둠의 밑바닥이랑 가까이에 있는 생활 환경이 얼마나 열악한지는 일단 제쳐 놓고...",
  ui_story_1014_10140101_10_dialog_content = "바이스 네 몸 상태만 봐도 지금은 일루미나를 떠나 멀리 갈 상황이 아니잖아.",
  ui_story_1014_10140101_11_dialog_content = "몸 상태는 상관없지 않아? 나 지금 멀쩡한데?",
  ui_story_1014_10140101_12_dialog_content = "안 된다면 안 된다는 거야!",
  ui_story_1014_10140101_13_dialog_content = "마침 일루미나 쪽에서도 의료 장치를 업그레이드하려고 연구 중이래.",
  ui_story_1014_10140101_14_dialog_content = "그러니까 바이스 너도 메디컬 센터에서 몸이 완전히 회복될 때까지 요양부터 하고 나서...",
  ui_story_1014_10140101_15_dialog_content = "<color=#e8d9bb>지잉── 지이잉──</color>",
  ui_story_1014_10140101_16_dialog_content = "어라? 잠깐만, PlayerName.",
  ui_story_1014_10140101_17_dialog_content = "여보세... 앗?!",
  ui_story_1014_10140101_18_dialog_content = "추, 충성! 대원수님, 바이스 중위입니다!",
  ui_story_1014_10140101_19_dialog_content = "(라인하르트 씨인가? 바이스한테 몸 상태는 어떠냐고 물어보려는 거...겠지?)",
  ui_story_1014_10140101_20_dialog_content = "네? 긴급 임무요...?",
  ui_story_1014_10140101_21_dialog_content = "(뭐?! 긴급 임무? 이럴 때?)",
  ui_story_1014_10140101_22_dialog_content = "알겠습니다. 지금 바로 기록하겠습니다.",
  ui_story_1014_10140101_23_dialog_content = "<size=33>수석 의회, 더스크 타운, 오로라 유적, 자료 거래...</size>",
  ui_story_1014_10140101_24_dialog_content = "(방금 있었던 일들을 한 방에 전부 다 설명해 버렸잖아!)",
  ui_story_1014_10140101_25_dialog_content = "네, 이해했습니다.",
  ui_story_1014_10140101_26_dialog_content = "절 믿어 주셔서 감사합니다. 안심하고 제게 맡겨 주세요.",
  ui_story_1014_10140101_27_dialog_content = "(또 너한테 뭘 맡기는 건데?)",
  ui_story_1014_10140101_28_dialog_content = "네! 성실히 임무를 수행하겠습니다!",
  ui_story_1014_10140101_29_dialog_content = "아무튼, PlayerName 네가 뭐라고 해도 난 너랑 같이 갈 거야!",
  ui_story_1014_10140101_30_dialog_content = "대원수님께서 직접 내리신 명령이니까.",
  ui_story_1014_10140101_31_dialog_content = "그러니까 나랑 대원수님 둘 다 곤란하게 만들지 마.",
  ui_story_1014_10140101_32_dialog_content = "그, 그런 게 어디 있어!",
  ui_story_1014_10140101_33_dialog_content = "무전기로 통화해 보니까, 대원수님이 일 때문에 잠시 자리를\n못 비우시는 상황이라 곤란하신가 봐.",
  ui_story_1014_10140101_34_dialog_content = "「바이스 중위, 일루미나를 대표해 아이테르와 변방 주둔 세력의 거래 업무를 지원하도록.」",
  ui_story_1014_10140101_35_dialog_content = "이렇게 말씀하셨어.",
  ui_story_1014_10140101_36_dialog_content = "아무리 그래도 그렇지...",
  ui_story_1014_10140101_37_dialog_content = "걱정 안 해도 돼, PlayerName.",
  ui_story_1014_10140101_38_dialog_content = "그러지 말고 차라리 나한테 「파견 임무」 계획에 대해 자세히 설명해 줘!",
  ui_story_1014_10140101_39_dialog_content = "...알겠어. 그럼 처음부터 설명해 줄게. 그러니까 아까 회의에서...",
  ui_story_1014_10140101_40_dialog_content = "<color=#e8d9bb>일루미나 연방 자난성, 일루미나 대형 회의실</color>",
  ui_story_1014_10140101_41_dialog_content = "당신이 이 거래에 응한다면, 그 연구 자료를 가지고 있는 과학자에게\n사람을 보내 논의하겠습니다.",
  ui_story_1014_10140101_42_dialog_content = "스카이워커호에게 필요한 연구 자료를 교환 조건으로 제공하지요.",
  ui_story_1014_10140101_43_dialog_content = "안 되겠어요. 더는 지체할 수 없어요. 제가 직접 오로라 유적에 가서 거래를 진행할게요!",
  ui_story_1014_10140101_44_dialog_content = "스카이워커가 있으면 병사들보다 훨씬 더 빨리 도착할 수 있을 거예요.",
  ui_story_1014_10140101_45_dialog_content = "그러니까 당신이 일루미나 본부를 대표해서,\n오로라 유적에 있는 거주 구역과 연락을 취하겠다는 겁니까?",
  ui_story_1014_10140101_46_dialog_content = "당신에게 그럴 권리는 없다고 봅니다만, 아이테르.",
  ui_story_1014_10140101_47_dialog_content = "나는 그렇게 해도 무방하다고 본다만.\n사소한 부분에 너무 연연하지 마라, 율리시스.",
  ui_story_1014_10140101_48_dialog_content = "이번 거래는 본래 더스크 타운과 PlayerName 사이의 거래다.\n일루미나는 방법을 제공했을 뿐이지.",
  ui_story_1014_10140101_49_dialog_content = "하~암, 난 오히려 꽤 기대되는데.",
  ui_story_1014_10140101_50_dialog_content = "확실히 「<color=#FFB400>천상의 취성</color>」을 호송해 줄 사람이 필요한 건 맞으니까.",
  ui_story_1014_10140101_51_dialog_content = "「천상의 취성」? 그게 자료와 교환하려는 물건이죠?",
  ui_story_1014_10140101_52_dialog_content = "맞아. 본부와 더스크 타운에 주둔 중인 일루미나 세력은 예전에 이미 협의를 했거든.",
  ui_story_1014_10140101_53_dialog_content = "변방 지대에 전쟁이 빈번히 일어나는 걸 감안해서,\n본부에서 그쪽에 고효율 전투 기계를 하나 보내 주기로 했어.",
  ui_story_1014_10140101_54_dialog_content = "그게 바로 율리시스가 만든 최신작이야.",
  ui_story_1014_10140101_55_dialog_content = "그걸로 그쪽에 있는 일루미나 세력과 거래하면,\n그쪽에선 콜로서스에 관한 연구 자료를 넘겨줄 거야.",
  ui_story_1014_10140101_56_dialog_content = "하지만 그 전투 기계는 아주 귀하고, 충격에 무척 취약해서\n반드시 조심해서 운송해야 해.",
  ui_story_1014_10140101_57_dialog_content = "비공정을 이용해서 옮기는 것보단, 이런 쪽의 전문가인 아이테르가\n수송을 전담해 주는 편이 훨씬 안심되지.",
  ui_story_1014_10140101_58_dialog_content = "그 유명한 「천상의 취성」이라니...",
  ui_story_1014_10140101_59_dialog_content = "맞아, 지금 내가 가지고 있어.",
  ui_story_1014_10140101_60_dialog_content = "진짜 궁금하네. 어떤 종류의 전투 기계일지 전혀 감이 안 와.",
  ui_story_1014_10140101_61_dialog_content = "<color=#e8d9bb><size=30>끼릭──</size></color>",
  ui_story_1014_10140101_62_dialog_content = "PlayerName! 이, 이거 봐! 뭔가 소리가 났어!",
  ui_story_1014_10140101_63_dialog_content = "소, 소리? 나, 난 아무것도 안 들렸는데?",
  ui_story_1014_10140101_64_dialog_content = "...아니면 내가 너무 예민했나 봐.",
  ui_story_1014_10140101_65_dialog_content = "근데 아깐 무슨 생각을 그렇게 했어?",
  ui_story_1014_10140101_66_dialog_content = "생각은 아니고... 그냥 조금 걱정돼서.",
  ui_story_1014_10140101_67_dialog_content = "스카이워커의 상태가 안 좋잖아. 기본적인 운송 작업만으로도 쉽지 않을 거야. 만에 하나...",
  ui_story_1014_10140101_68_dialog_content = "만에 하나 뭔가 문제가 생긴다면, 우리 둘이 같이 방법을 생각해 보면 돼.",
  ui_story_1014_10140101_69_dialog_content = "늑장 부려봐야 좋을 거 없으니까, 얼른 움직이자!",
  ui_story_1014_10140101_70_dialog_content = "응, 그래...!",
  ui_story_1014_10140101_71_dialog_content = "<color=#e8d9bb>스카이워커호, 함교</color>",
  ui_story_1014_10140101_72_dialog_content = "(제어 시스템 성능 검사... 확인.)",
  ui_story_1014_10140101_73_dialog_content = "(엔진 성능 검사... 확인.)",
  ui_story_1014_10140101_74_dialog_content = "이젠 이런 일들도... 내가 스스로 해야 하는구나.",
  ui_story_1014_10140101_75_dialog_content = "(휴식실에도 가서 검사해 보자.)",
  ui_story_1014_10140101_76_dialog_content = "...어라?!",
  ui_story_1014_10140101_77_dialog_content = "카렌, 베르타?! 그리고... 잉겔 씨?",
  ui_story_1014_10140101_78_dialog_content = "왜 다들 여기 있는 거야?!",
  ui_story_1014_10140101_79_dialog_content = "아직 카렌한테 연락도 안 했는데...",
  ui_story_1014_10140101_80_dialog_content = "바이스한테 들었거든.\nPlayerName 네가 또 영원한 밤의 땅에 갈 거라고 말이야.",
  ui_story_1014_10140101_81_dialog_content = "너희 둘만 거기서 싸우게 두려니까, 아무래도 마음이 안 놓여서.",
  ui_story_1014_10140101_82_dialog_content = "후후, 역시 카렌은 항상 믿음직하다니까.",
  ui_story_1014_10140101_83_dialog_content = "사실 카렌이 지각하면 어쩌나 걱정했어!",
  ui_story_1014_10140101_84_dialog_content = "마침 백야성도 더스크 타운에 주둔하고 있는 세력과 교류가 끊긴 지 오래된 참이거든.",
  ui_story_1014_10140101_85_dialog_content = "간 김에 시찰 업무를 맡아 줄 사람으로 베르타도 데려왔어.",
  ui_story_1014_10140101_86_dialog_content = "또 만났네, PlayerName.",
  ui_story_1014_10140101_87_dialog_content = "안색이 안 좋은데, 주사라도 한 대 놔 줄까?",
  ui_story_1014_10140101_88_dialog_content = "뭐, 뭐어어?!",
  ui_story_1014_10140101_89_dialog_content = "장난이야.",
  ui_story_1014_10140101_90_dialog_content = "근데 옆에 있는 일루미나 사람은 못 보던 얼굴이네.\n저번에 헤븐즈 밸리에는 없었던 것 같은데?",
  ui_story_1014_10140101_91_dialog_content = "이번엔 그 백발 녀석은 같이 안 온 모양이네?",
  ui_story_1014_10140101_92_dialog_content = "무례하게 굴지 마, 베르타.",
  ui_story_1014_10140101_93_dialog_content = "네, 카렌 전하!",
  ui_story_1014_10140101_94_dialog_content = "일루미나 연방, 정보기관 근위대 소속 잉겔 중령입니다.",
  ui_story_1014_10140101_95_dialog_content = "바이스 중위, 당신 이야기는 많이 들었어요.\n아이테르와 콜로서스에 관한 정보는 앞으로 잘 부탁할게요.",
  ui_story_1014_10140101_96_dialog_content = "아, 저... 편하게 대해 주세요. 중령님이 상관이시잖아요!",
  ui_story_1014_10140101_97_dialog_content = "(바이스가 완전히 허둥지둥하고 있네.)",
  ui_story_1014_10140101_98_dialog_content = "물어보고 싶은 게 하나 있어. 혹시 과학 수석 의회에서 보내서 온 거야?",
  ui_story_1014_10140101_99_dialog_content = "미안하군요. 이번에 여기 온 건 임무 때문이 맞습니다. 하지만...",
  ui_story_1014_10140101_100_dialog_content = "제가 변방의 전투 구역에 직접 가 보고 싶어서이기도 합니다.",
  ui_story_1014_10140101_101_dialog_content = "A-42 파일의 구체적인 내용에 따라, 전 당신에게 믿을 수 있는 정보를 제공할 겁니다.",
  ui_story_1014_10140101_102_dialog_content = "당신도 「천상의 취성」의 진실성을 증명해 줄 중개자가 필요할 테고 말이죠.",
  ui_story_1014_10140101_103_dialog_content = "그것도 그렇긴 한데...",
  ui_story_1014_10140101_104_dialog_content = "걱정은 안 해도 됩니다. 이건 본부에서 이끄는 거래니까,\n순조롭든 그렇지 않든 전 당신에게 많은 간섭을 하지 않을 겁니다.",
  ui_story_1014_10140101_105_dialog_content = "(확실히 반박할 근거도 딱히 없긴 하네...)",
  ui_story_1014_10140101_106_dialog_content = "...잠깐만. 이렇게 되면 남아서 과학 수석 의회랑 담판을 짓는 건\n라인하르트 씨 혼자라는 거잖아?",
  ui_story_1014_10140101_107_dialog_content = "지금 대원수님을 걱정하는 건 아니겠죠?",
  ui_story_1014_10140101_108_dialog_content = "그것도 그렇네. 라인하르트 씨는 물론 내가 걱정할 필요는 없겠지.",
  ui_story_1014_10140101_109_dialog_content = "<color=#e8d9bb>같은 시간, 일루미나 대형 회의실</color>",
  ui_story_1014_10140101_110_dialog_content = "노라와 헬리오스 그 둘은 전략 과제가 아닙니다, 라인하르트.\n당신이 직접 나설 필요는 없어 보입니다만.",
  ui_story_1014_10140101_111_dialog_content = "그 둘은 과학 수석 의회에서 더 적합한 인물에게 맡겼습니다.",
  ui_story_1014_10140101_112_dialog_content = "과거에 빠져 있는 건 좋지 않습니다. 더 중요한 일에 눈을 두어야지요.",
  ui_story_1014_10140101_113_dialog_content = "내 손으로 직접 율리시스에게 불리한 단서를 찾아낼까 걱정이 되는 모양이지?",
  ui_story_1014_10140101_114_dialog_content = "「제게 불리한 단서」라니, 그게 무슨 말씀이신지?",
  ui_story_1014_10140101_115_dialog_content = "그 점에 대해선 네가 나보다 더 잘 알고 있겠지.",
  ui_story_1014_10140101_116_dialog_content = "진상이 수면 위로 떠 오를 그날이 기대되는군, 율리시스.\n시치미를 뗄 수 있는 시간도 얼마 남지 않았어.",
  ui_story_1014_10140101_117_dialog_content = "한사코 고집을 부리신다면, 위원회에서 대원수님의 직무수행 자격을\n재고해야 할 수도 있습니다만.",
  ui_story_1014_10140101_118_dialog_content = "그런가. 그럼 네가 직접 말해 봐라.\n오로리안 그 자체보다 더 중요한 사안이 뭔지 말이다.",
  ui_story_1014_10140101_119_dialog_content = "그걸 제가 설명해 드려야 하는 겁니까?\n일루미나의 연합 훈련, 향후 연합군의 반격, 어느 하나 중요하지 않은 것이...",
  ui_story_1014_10140101_120_dialog_content = "가소롭기 이를 데 없군.",
  ui_story_1014_10140101_121_dialog_content = "내가 어떤 대원수가 되어야 하는지 누가 가르쳐 줄 필요는 없다.",
  ui_story_1014_10140101_122_dialog_content = "난 한번 결정한 일에 대해서는 그 누구에게도 쉽게 좌지우지되지 않아.",
  ui_story_1014_10140101_123_dialog_content = "그럼 먼저 실례하지, 여러분.",
  ui_story_1014_10140101_124_dialog_content = "여전히 독불장군이네요.",
  ui_story_1014_10140101_125_dialog_content = "하하, 대원수의 능력이라면 그 이클립스 여자를 찾아내는 건 일도 아닐 겁니다.",
  ui_story_1014_10140101_126_dialog_content = "다들 더는 왈가왈부할 것 없습니다.",
  ui_story_1014_10140101_127_dialog_content = "이럴 줄 알고 대응책을 마련해 두었으니 말이지요.",
  ui_story_1014_10140201_1_dialog_content = "제어 시스템 성능은, 음... 이상 없고.",
  ui_story_1014_10140201_2_dialog_content = "자동 조종 시스템 성능도 별 이상 없어.",
  ui_story_1014_10140201_3_dialog_content = "PlayerName, 스카이워커호가 안정적으로 비행한 지도 꽤 됐으니까,\n너도 이제 안심해도 될 것 같아.",
  ui_story_1014_10140201_4_dialog_content = "그, 그렇네. 수고했어, 바이스.",
  ui_story_1014_10140201_5_dialog_content = "수고는 뭘, 난 괜찮아. 근데 넌 계속 안절부절못하고 있는 것 같은걸.",
  ui_story_1014_10140201_6_dialog_content = "그것보다... 네가 계속 그 「천상의 취성」을 안고 있을 필요는 없지 않아?",
  ui_story_1014_10140201_7_dialog_content = "무슨 암탉도 아니고!",
  ui_story_1014_10140201_8_dialog_content = "어떤 의미에선 이 기계가 스카이워커를 복구할 수 있는 중요한 자료잖아.",
  ui_story_1014_10140201_9_dialog_content = "근데 이걸 어떻게 보호해야 좋을지 당장 떠오르는 방법이 없거든.",
  ui_story_1014_10140201_10_dialog_content = "게다가 생각보다 무게가 많이 나가지도 않고...",
  ui_story_1014_10140201_11_dialog_content = "어? 그래? 그건 신기하네. 뭐 경량형 무기 그런 건가?",
  ui_story_1014_10140201_12_dialog_content = "무게도 가볍고, 쉽게 부서지고...\n고성능 전투 기계라는 거, 엄청 신기하게 설계돼 있네.",
  ui_story_1014_10140201_13_dialog_content = "아, 아무튼 난 일단 이렇게 있을래!",
  ui_story_1014_10140201_14_dialog_content = "내가 못 살아...",
  ui_story_1014_10140201_15_dialog_content = "(기분 전환을 하고 싶으니까, 가서 카렌은 뭐 하고 있는지 봐야겠어.)",
  ui_story_1014_10140201_16_dialog_content = "<color=#e8d9bb>치지... 직... 치지직...</color>",
  ui_story_1014_10140201_17_dialog_content = "......",
  ui_story_1014_10140201_18_dialog_content = "베르타, 아직도 안 되니?",
  ui_story_1014_10140201_19_dialog_content = "죄송합니다, 카렌 전하. 저도 이런 무전기는 잘 사용할 줄 몰라서...",
  ui_story_1014_10140201_20_dialog_content = "음?",
  ui_story_1014_10140201_21_dialog_content = "바이스, 마침 잘 왔어.",
  ui_story_1014_10140201_22_dialog_content = "왜 그래? 무슨 일이야? 내가 뭐 도와줄 거 있어?",
  ui_story_1014_10140201_23_dialog_content = "백야성이 변방 쪽에 파견한 기사단에 연락해서 현지 상황을 좀 들어 볼까 하거든.",
  ui_story_1014_10140201_24_dialog_content = "적어도 일 년 이상은 그쪽에 주둔하고 있었을 테니까,\n우리의 이번 여행에 신뢰할 수 있는 지원을 해 줄 수 있을 거야.",
  ui_story_1014_10140201_25_dialog_content = "지금까지는 성주님께서 해 왔던 일이라, 내가 미리 연락해서 준비를 못 했어.",
  ui_story_1014_10140201_26_dialog_content = "카렌 넌 급하게 출발했잖아. 그럴 새가 어디 있었겠어!",
  ui_story_1014_10140201_27_dialog_content = "그래도 지금은 눈앞에 「선생님」이 와 줘서 이제는 걱정 안 해.",
  ui_story_1014_10140201_28_dialog_content = "부탁할게, 바이스. 이 무전기에 무슨 문제가 있는지 확인해 줘.",
  ui_story_1014_10140201_29_dialog_content = "신호가 끊겼다가 이어졌다를 반복하는 중이야.",
  ui_story_1014_10140201_30_dialog_content = "응, 나한테 맡겨!",
  ui_story_1014_10140201_31_dialog_content = "어디 보자... 우선 안테나 감도부터 조정해 볼게.",
  ui_story_1014_10140201_32_dialog_content = "다 됐어! 얼른 해 봐!",
  ui_story_1014_10140201_33_dialog_content = "<color=#e8d9bb>치지... 직... 치지직...</color>",
  ui_story_1014_10140201_34_dialog_content = "으으음, 그럼... 출력 확대 모듈을 복구해 볼게!",
  ui_story_1014_10140201_35_dialog_content = "좋아! 이제 괜찮을 거야!",
  ui_story_1014_10140201_36_dialog_content = "<color=#e8d9bb>치지... 직... 치지직...</color>",
  ui_story_1014_10140201_37_dialog_content = "아하하하... 이렇게 된 이상... 방법은...",
  ui_story_1014_10140201_38_dialog_content = "<color=#e8d9bb>퍼억! 퍽!</color>",
  ui_story_1014_10140201_39_dialog_content = "<color=#e8d9bb>삐빅, 삐비빅...</color>",
  ui_story_1014_10140201_40_dialog_content = "휴우~ 간단하지?",
  ui_story_1014_10140201_41_dialog_content = "그렇구나, 앞으로도 문제가 생기면 이렇게 고치면 될까?",
  ui_story_1014_10140201_42_dialog_content = "들리는가?",
  ui_story_1014_10140201_43_dialog_content = "이쪽은 <color=#FFB400>강철가시 기사단</color>이다. 반복한다. 이쪽은 강철가시 기사단이다.",
  ui_story_1014_10140201_44_dialog_content = "신호가 선명해졌네, 좋아. 만물은 백야 아래에,\n강철가시 기사단, 여기는 하이가든 호위대 호위대장 카렌이다.",
  ui_story_1014_10140201_45_dialog_content = "강철가시 기사단 단장 레오입니다. 카렌 전하께 인사...",
  ui_story_1014_10140201_46_dialog_content = "<color=#e8d9bb>치지직──</color>",
  ui_story_1014_10140201_47_dialog_content = "(신호 상태가 여전히 안 좋은 걸까...)",
  ui_story_1014_10140201_48_dialog_content = "레오 단장, 백야성에서 곧 더스크 타운에 관례대로 해 오던 시찰을 진행할 예정이야.",
  ui_story_1014_10140201_49_dialog_content = "이번엔 내가 백야성을 대표해서 나서게 됐으니, 앞으로 있을 만남을 기대할게.",
  ui_story_1014_10140201_50_dialog_content = "기사단은 변방 전투 구역의 업무로 수고가 많으니,\n직접 만나 감사의 뜻을 전할 기회가 있었으면 좋겠어.",
  ui_story_1014_10140201_51_dialog_content = "좀 갑작스럽긴 하지만, <color=#FFB400>백야 요새</color>를 순찰하실 수 있도록\n최대한 시간을 조절해 보겠습니다.",
  ui_story_1014_10140201_52_dialog_content = "감사는 하지 않으셔도 됩니다. 저는 제가 맡은 일을 할 뿐이니까요.",
  ui_story_1014_10140201_53_dialog_content = "그러면 그때 보도록 해.",
  ui_story_1014_10140201_54_dialog_content = "네, 도착하시면 제가 사람을 보내... 마중을... 나가...",
  ui_story_1014_10140201_55_dialog_content = "<color=#e8d9bb>치지직──</color>",
  ui_story_1014_10140201_56_dialog_content = "<color=#e8d9bb>삐빅, 삐비빅...</color>",
  ui_story_1014_10140201_57_dialog_content = "아무래도 신호가 완전히 끊겨 버린 모양이네...",
  ui_story_1014_10140201_58_dialog_content = "그래도 기본적인 정보는 전달해 뒀으니 괜찮겠지.",
  ui_story_1014_10140201_59_dialog_content = "카, 카렌 님... 괜찮을까요?",
  ui_story_1014_10140201_60_dialog_content = "헤븐즈 밸리의 전투 이후로 이제 막 대장으로 복직하신 거잖아요.",
  ui_story_1014_10140201_61_dialog_content = "비록 요즘은 전보다 마음에 흔들림이 없어지셨지만...",
  ui_story_1014_10140201_62_dialog_content = "성주 전하 말씀대로라면 복직도 아직 완전한 게 아니라, 아직은 감사 기간이에요.",
  ui_story_1014_10140201_63_dialog_content = "의외의 사고라도 생겼다간...",
  ui_story_1014_10140201_64_dialog_content = "괜찮아, 베르타. 네가 무슨 마음인지는 나도 알아.\n그래도 그렇게 걱정하진 않아도 돼.",
  ui_story_1014_10140201_65_dialog_content = "설령 무슨 일이 일어난다고 해도, 우린 대응에만 관여하면 되니까.",
  ui_story_1014_10140201_66_dialog_content = "음... 카렌 님 말씀이 맞네요!",
  ui_story_1014_10140201_67_dialog_content = "그나저나 「레오 단장」은 대체 어떤 사람인가요?",
  ui_story_1014_10140201_68_dialog_content = "카렌 님께서 감사 인사를 하겠다고 하셨는데, 그걸 저런 식으로 받다니 말이에요.",
  ui_story_1014_10140201_69_dialog_content = "베르타, 그렇게 말하면 안 돼.",
  ui_story_1014_10140201_70_dialog_content = "백야성에서 평온한 삶을 보내고 있는 우린 변방 지대에 있는 전사들에게\n감사하는 마음을 가져야 마땅해.",
  ui_story_1014_10140201_71_dialog_content = "<color=#e8d9bb>삐익── 삐익── 삐익──</color>",
  ui_story_1014_10140201_72_dialog_content = "무, 무슨 일이지?!",
  ui_story_1014_10140201_73_dialog_content = "스카이워커호에서 나는 경보음인 것 같은데?",
  ui_story_1014_10140201_74_dialog_content = "이런...!",
  ui_story_1014_10140201_75_dialog_content = "PlayerName한테 가 보자!",
  ui_story_1014_10140201_76_dialog_content = "허억, 허억...",
  ui_story_1014_10140201_77_option_content = "[긴급 모드 실행]",
  ui_story_1014_10140201_78_dialog_content = "<color=#e8d9bb>삐빅──!</color>",
  ui_story_1014_10140201_79_option_content = "[콜로서스를 안정시킨다]",
  ui_story_1014_10140201_80_dialog_content = "<color=#e8d9bb>위이잉──!</color>",
  ui_story_1014_10140201_81_dialog_content = "정말, 조심 좀 하세요.",
  ui_story_1014_10140201_82_dialog_content = "제가 껴안고 있지 않았으면 「천상의 취성」이 어딘가 부딪혀 흠이 생겼을 겁니다.",
  ui_story_1014_10140201_83_dialog_content = "PlayerName, 어떻게 된 거야?",
  ui_story_1014_10140201_84_dialog_content = "방금 내가 조작을 좀 잘못해서 경보기가 올린 거야. 다들 많이 놀랐지?",
  ui_story_1014_10140201_85_dialog_content = "아무 일도 없었던 것처럼 태연하게 말하면 안 되지, PlayerName!",
  ui_story_1014_10140201_86_dialog_content = "진짜 괜찮아? 콜로서스를 조종하는 게 생각보다 훨씬 더 어려운 일인 것 같은데...",
  ui_story_1014_10140201_87_dialog_content = "지, 진짜 아무 문제도 없어.",
  ui_story_1014_10140201_88_dialog_content = "(아무리 그래도 난 아이테르잖아!)",
  ui_story_1014_10140201_89_dialog_content = "혹시라도 힘들면 잠시 이 아래에 착륙해서 쉬었다 가자.",
  ui_story_1014_10140201_90_dialog_content = "영원한 밤의 땅에 가까워질수록, 주위의 다크매터도 점점 짙어지고 있어.",
  ui_story_1014_10140201_91_dialog_content = "지금 네 컨디션도 그리 좋지는 않을 거잖아. 그렇지, PlayerName?",
  ui_story_1014_10140201_92_dialog_content = "솔직하게 말해줘.",
  ui_story_1014_10140201_93_dialog_content = "정말 예리하다니까... 사실은 아까 전부터 머리가 지끈거리기 시작했거든.",
  ui_story_1014_10140201_94_dialog_content = "전 콜로서스의 조종법은 잘 모르지만, 「천상의 취성」의 안전을 고려한다면...",
  ui_story_1014_10140201_95_dialog_content = "저 역시 잠시 지면에 착륙해서 쉬었다 가는 쪽을 권하겠습니다.",
  ui_story_1014_10140201_96_dialog_content = "우리 모두 당신의 실수로 「천상의 취성」에 뜻밖의 문제가\n생기는 걸 원하진 않을 테니까요.",
  ui_story_1014_10140201_97_dialog_content = "그거야 당연하지.",
  ui_story_1014_10140201_98_dialog_content = "알겠어. 솔직히 내가 무리한 게 맞아.",
  ui_story_1014_10140201_99_dialog_content = "그럼 스카이워커를 착륙시킬 거니까 다들 준비해 줘.",
  ui_story_1014_10140201_100_dialog_content = "후우...",
  ui_story_1014_10140201_101_dialog_content = "밖에 나와서 좀 움직이는 것도 나쁘지 않네요.",
  ui_story_1014_10140201_102_dialog_content = "그나저나 지금 스카이워커호는 어떤 상황인 거야?",
  ui_story_1014_10140201_103_dialog_content = "임시 착륙 같은 조작도 PlayerName 네가 직접 해야 한다니 말이야.",
  ui_story_1014_10140201_104_dialog_content = "보아하니 저번보다 상황이 더 심각한 모양이네.",
  ui_story_1014_10140201_105_dialog_content = "의식에 여전히 문제가 있거든.\n가동에 문제는 없지만, 지금도 나와 감응은 할 수 없어.",
  ui_story_1014_10140201_106_dialog_content = "...난 가서 스카이워커의 장치들을 한 번 더 검사해 볼게.",
  ui_story_1014_10140201_107_dialog_content = "저도 같이 가죠.",
  ui_story_1014_10140201_108_dialog_content = "<color=#e8d9bb>휘이잉... 휘이잉...</color>",
  ui_story_1014_10140201_109_dialog_content = "(정말 황량한 곳이네.)",
  ui_story_1014_10140201_110_dialog_content = "여기 루미나 농도는 일루미나보다 훨씬 옅은데, 몸은 괜찮아?",
  ui_story_1014_10140201_111_dialog_content = "컨디션에 영향을 줄 정도로 옅진 않군요.",
  ui_story_1014_10140201_112_dialog_content = "게다가 「이번 여정 중 아이테르의 행적을 낱낱이 기록하는 것」도\n제 임무 중 하나입니다.",
  ui_story_1014_10140201_113_dialog_content = "어서 콜로서스에 무슨 고장이 난 건지 검사하러 가죠.",
  ui_story_1014_10140201_114_dialog_content = "아, 알겠어.",
  ui_story_1014_10140201_115_dialog_content = "(이거 원 감시당하는 느낌인데...)",
  ui_story_1014_10140201_116_dialog_content = "크에엑...",
  ui_story_1014_10140201_117_dialog_content = "음?! 이 소리...",
  ui_story_1014_10140201_118_dialog_content = "<anim type=Shake><size=45>그어어억!</size></anim>",
  ui_story_1014_10140201_119_dialog_content = "암귀?!",
  ui_story_1014_10140201_120_dialog_content = "이런 데서 암귀가 나타나는 건 이상한 일도 아니잖아!",
  ui_story_1014_10140201_121_dialog_content = "녀석들이 스카이워커한테 접근하게 둘 순 없어. 너 싸움은 잘해?",
  ui_story_1014_10140201_122_dialog_content = "전... 모의 전투라면 모를까...",
  ui_story_1014_10140201_123_dialog_content = "그, 그럼 얼른 가서 바이스랑 카렌 좀 불러와 줘!",
  ui_story_1014_10140201_124_dialog_content = "전투.",
  ui_story_1014_10140201_125_dialog_content = "악셀리아는 전투 명령을 받았습니다.",
  ui_story_1014_10140201_126_dialog_content = "?!",
  ui_story_1014_10140201_127_dialog_content = "(결국 나와버린 건가요...)",
  ui_story_1014_10140201_128_dialog_content = "누구야?! 누가 말하는 거야?!",
  ui_story_1014_10140201_129_dialog_content = "<color=#e8d9bb>끼릭... 끼리릭...</color>",
  ui_story_1014_10140201_130_dialog_content = "악셀리아는 당신에게 전투 명령을 받았습니다.",
  ui_story_1014_10140201_131_dialog_content = "잉겔을 난처하게 만들지 마세요.",
  ui_story_1014_10140201_132_dialog_content = "악셀리아는 전투 준비가 되었습니다.",
  ui_story_1014_10140201_133_dialog_content = "뭐, 뭐야...",
  ui_story_1014_10140201_134_dialog_content = "과학 수석 의회가 나한테 맡긴 <color=#FFB400>「천상의 취성」</color>이 너야?!",
  ui_story_1014_10140201_135_dialog_content = "크오오!",
  ui_story_1014_10140201_136_dialog_content = "한주먹 거리도 안 됩니다.",
  ui_story_1014_10140202_1_dialog_content = "받아라!",
  ui_story_1014_10140202_2_dialog_content = "얼어붙어라!",
  ui_story_1014_10140202_3_dialog_content = "수고했어요, 바이스 중위.",
  ui_story_1014_10140202_4_dialog_content = "악셀리아, 괜찮나요?",
  ui_story_1014_10140202_5_dialog_content = "그 말은 암귀에게 물어봐야 합니다.",
  ui_story_1014_10140202_6_dialog_content = "...이제 대답해 줄 암귀는 없지만요.",
  ui_story_1014_10140202_7_dialog_content = "휴, 여긴 당신이 임무를 수행해야 할 곳도 아니니까,\n마음대로 수면 캡슐에서 나와선 안 돼요.",
  ui_story_1014_10140202_8_dialog_content = "악셀리아는 자신이 다치지 않게 주의합니다.",
  ui_story_1014_10140202_9_dialog_content = "저는 잉겔을 곤란하게 만들지 않습니다.",
  ui_story_1014_10140202_10_dialog_content = "여기서 아무렇지도 않게 대화하지 말아 줄래?!",
  ui_story_1014_10140202_11_dialog_content = "일단 설명 좀 해 줄 수 있을까? 아무리 봐도 물건이 아니라 오로리안이잖아?",
  ui_story_1014_10140202_12_dialog_content = "엄밀히 말하면 오로리안은 맞습니다.",
  ui_story_1014_10140202_13_dialog_content = "하지만 오로리안이기에 앞서, 과학 수석 의회가 가장 자랑으로 여기는 전쟁 기계입니다.",
  ui_story_1014_10140202_14_dialog_content = "기계...라고?",
  ui_story_1014_10140202_15_dialog_content = "우린 「기계」라고 부르는 게 익숙해졌거든요.",
  ui_story_1014_10140202_16_dialog_content = "악셀리아는 모든 작전 명령을 끝까지 관철할 수 있는 완벽주의자입니다.",
  ui_story_1014_10140202_17_dialog_content = "특히 루미나를 다루고 있을 땐, 루미나의 현신이라고 해도 과언이 아니죠.",
  ui_story_1014_10140202_18_dialog_content = "루미나틱스를 사용하는 순간, 악셀리아는 루미나로 보고, 들을 수 있고,\n각종 기계를 조종해서 전투를 수행할 수 있습니다.",
  ui_story_1014_10140202_19_dialog_content = "대단하네! 그런 능력은 처음 들어 봐!",
  ui_story_1014_10140202_20_dialog_content = "네, 루미나틱스를 다루는 능력은 탁월한 수준이죠. 하지만...",
  ui_story_1014_10140202_21_dialog_content = "육체 쪽은 굉장히 약합니다.",
  ui_story_1014_10140202_22_dialog_content = "온몸에 감겨 있는 붕대만 봐도 알 수 있겠지만,\n신체 기능 쪽은 계속 쇠약해지고 있는 상태입니다.",
  ui_story_1014_10140202_23_dialog_content = "쇠약해지고 있는 상태라고? 왜? 일루미나의 의료 기술로도 손쓸 방법이 없어?",
  ui_story_1014_10140202_24_dialog_content = "유전자와 관계가 있는 모양입니다만, 누가 알겠습니까.",
  ui_story_1014_10140202_25_dialog_content = "아무튼 일종의 「유리 대포」라고 할 수 있습니다.",
  ui_story_1014_10140202_26_dialog_content = "악셀리아는 더스크 타운처럼 극한적인 지역에서만 능력을 발휘할 수 있습니다.\n일루미나에만 둔다면 인재를 썩히는 겁니다.",
  ui_story_1014_10140202_27_dialog_content = "안녕하세요. PlayerName. 늦었지만 이것은 인사입니다.",
  ui_story_1014_10140202_28_dialog_content = "번거롭겠지만 앞으로의 여정도 잘 부탁합니다.",
  ui_story_1014_10140202_29_dialog_content = "보고하겠습니다. 이제부터 악셀리아는...",
  ui_story_1014_10140202_30_dialog_content = "당신이 필요로 할 때 수면 캡슐에서 나와 전투를 시작하겠습니다.",
  ui_story_1014_10140202_31_dialog_content = "아, 안 그래도 돼!",
  ui_story_1014_10140202_32_dialog_content = "(고장이라도 나 버리면 끝장이니까!)",
  ui_story_1014_10140202_33_dialog_content = "평범한 암귀들은 우리들이 어떻게 할 수 있어.\n네가 나서면 모기를 잡겠다고 대포를 쏘는 거잖아!",
  ui_story_1014_10140202_34_dialog_content = "맞는 말이야. 진짜 어쩔 수 없는 상황이 오기 전까진 푹 쉬고 있어.",
  ui_story_1014_10140202_35_dialog_content = "그렇네요, 확실히 조금 졸립니다.",
  ui_story_1014_10140202_36_dialog_content = "(우와... 너무 귀여워!)",
  ui_story_1014_10140202_37_dialog_content = "우리 또래인 것 같은데, 엄청 잠꾸러기네.",
  ui_story_1014_10140202_38_dialog_content = "여전하군요...",
  ui_story_1014_10140202_39_dialog_content = "악셀리아에게 전투는 일종의 소모 같은 행동이니까, 쉬어 줄 때가 된 것입니다.",
  ui_story_1014_10140202_40_dialog_content = "모두, 안녕히 주무세요.",
  ui_story_1014_10140202_41_dialog_content = "이 사람은 우리가 다시 스카이워커호의 휴식실로 데려갈게.",
  ui_story_1014_10140202_42_dialog_content = "베르타, 그쪽은 어떻게 됐어?",
  ui_story_1014_10140202_43_dialog_content = "네! 다녀왔어요, 카렌 님!",
  ui_story_1014_10140202_44_dialog_content = "방금 콜로서스에 대략적인 검사를 해 봤어요.",
  ui_story_1014_10140202_45_dialog_content = "하지만 제가 라파엘 님의 조수이긴 해도,\n아직 이런 고대 기계에 발생한 병변에 대해서는 역시...",
  ui_story_1014_10140202_46_dialog_content = "수고 많았어, 베르타!",
  ui_story_1014_10140202_47_dialog_content = "아무튼 스카이워커도 지금 상태론 바로 날기 힘들 것 같아.",
  ui_story_1014_10140202_48_dialog_content = "그러니까 오늘은 여기 잠깐 머물면서 고장 난 부분들을 고치는 게 좋겠어.",
  ui_story_1014_10140202_49_dialog_content = "오늘... 이런 데서 쉰다고?",
  ui_story_1014_10140202_50_dialog_content = "해도 거의 안 보이는 이런 곳에서 어떻게 시간을 구분하려고 그래...?",
  ui_story_1014_10140202_51_dialog_content = "뭐, 됐어. 어쩌면 이것도 성지로 향하는 여정의 수행일지도 모르니까.",
  ui_story_1014_10140202_52_dialog_content = "성지? 그런 곳을 성지라고 부를 순 없을 텐데요.",
  ui_story_1014_10140202_53_dialog_content = "그곳은 고대의 오로리안들이 암귀과 전쟁을 치렀던 요새입니다.",
  ui_story_1014_10140202_54_dialog_content = "지금도 오로리안들은 그곳을 지키고 있을 뿐만 아니라,\n암귀들을 영원한 밤의 땅으로 몰아냈죠.",
  ui_story_1014_10140202_55_dialog_content = "수없이 많은 오로리안들의 시체가 묻혀 있는 구덩이에서\n찬송가를 부르는 게 백야성의 취미인 모양이군요.",
  ui_story_1014_10140202_56_dialog_content = "아니, 그런 게 아냐!",
  ui_story_1014_10140202_57_dialog_content = "전설에 따르면 오로라 유적은 이 세상 모든 오로라의 발원지야.",
  ui_story_1014_10140202_58_dialog_content = "그리고 거긴 오로리안들이 발을 들일 수 있는 가장 먼 곳이자,\n우리의 뿌리를 찾을 수 있는 곳이기도 해.",
  ui_story_1014_10140202_59_dialog_content = "그렇다고 해서 제가 방금 한 말이 없게 되는 건 아닐 텐데요.",
  ui_story_1014_10140202_60_dialog_content = "아무튼 거길 「시체 구덩이」 따위로 부르지 마!",
  ui_story_1014_10140202_61_dialog_content = "(머리 아파... 다크매터가 너무 짙어선지, 둘이 말다툼을 해서 그런 건지 모르겠네.)",
  ui_story_1014_10140202_62_dialog_content = "자, 자, 됐으니까 둘 다 그만 싸워...",
  ui_story_1014_10140202_63_dialog_content = "베르타, 내 옆으로 와.",
  ui_story_1014_10140202_64_dialog_content = "중령님, 진정하세요.",
  ui_story_1014_10140202_65_dialog_content = "날이 점점 어두워지고 있으니까, 일단 콜로서스로 돌아가자.",
  ui_story_1014_10140202_66_dialog_content = "......",
  ui_story_1014_10140202_67_dialog_content = "흥.",
  ui_story_1014_10140301_1_dialog_content = "<color=#e8d9bb>스카이워커호, 함교</color>",
  ui_story_1014_10140301_2_dialog_content = "<anim type=Shake>하~암...</anim>",
  ui_story_1014_10140301_3_dialog_content = "(졸리네... 잠을 제대로 못 잤어.)",
  ui_story_1014_10140301_4_dialog_content = "안녕, PlayerName.",
  ui_story_1014_10140301_5_dialog_content = "어?! PlayerName 너 왜... 그렇게 초췌해?!",
  ui_story_1014_10140301_6_dialog_content = "잠 못 잤어?",
  ui_story_1014_10140301_7_dialog_content = "비슷해. 저번에 왔을 때보다 다크매터가 더 짙어져서 그런가 봐.",
  ui_story_1014_10140301_8_dialog_content = "어젯밤엔 암귀가 스카이워커 근처를 지나가기만 해도 잠에서 깨게 되더라고.",
  ui_story_1014_10140301_9_dialog_content = "꼭 내가 사냥감이 된 것 같은 느낌이었어...",
  ui_story_1014_10140301_10_dialog_content = "많이 피곤하겠네... 그럼 지금이라도 자 둬.",
  ui_story_1014_10140301_11_dialog_content = "음, 그래야겠네.",
  ui_story_1014_10140301_12_dialog_content = "그럼 난 가서 좀 잘게...",
  ui_story_1014_10140301_13_dialog_content = "<color=#e8d9bb>쾅! 쾅!</color>",
  ui_story_1014_10140301_14_dialog_content = "<color=#e8d9bb>쿵──!</color>",
  ui_story_1014_10140301_15_dialog_content = "도저히 못 참겠네...",
  ui_story_1014_10140301_16_dialog_content = "밖에서 대체 뭐 하는 거야?!",
  ui_story_1014_10140301_17_dialog_content = "내가 베르타와 같이 가서 무슨 일인지 알아볼게.",
  ui_story_1014_10140301_18_dialog_content = "아니, 나도 직접 내려가서 확인해야겠어!",
  ui_story_1014_10140301_19_dialog_content = "(이 암귀들, 갈수록 너무하잖아!)",
  ui_story_1014_10140301_20_dialog_content = "소란을 피우는 것도 정도가 있지!",
  ui_story_1014_10140301_21_dialog_content = "...어? 숀?",
  ui_story_1014_10140301_22_dialog_content = "어? PlayerName?! 너구나!",
  ui_story_1014_10140301_23_dialog_content = "여기서 만나다니 이런 우연이 다 있네!",
  ui_story_1014_10140301_24_dialog_content = "이 흰색 덩치가 네 콜로서스였어?",
  ui_story_1014_10140301_25_dialog_content = "...그럼 나 말고 누구 거겠어!",
  ui_story_1014_10140301_26_dialog_content = "크흠... 아무튼 PlayerName 너랑 다들 번거롭게 만들어서 미안해.",
  ui_story_1014_10140301_27_dialog_content = "문은 이따 내가 검사해 볼게.\n내가 두들긴 것 때문에 스카이워커호에 피해가 없었으면 좋겠는데...",
  ui_story_1014_10140301_28_dialog_content = "(휴, 진짜...)",
  ui_story_1014_10140301_29_dialog_content = "방금까지 난 더스크 타운 주변 일대의 순찰이랑 청소 업무를 수행하는 중이었어.",
  ui_story_1014_10140301_30_dialog_content = "더스크 타운 같은 곳은 원래부터 루미나가 옅어서 길을 잃는 난민들이 자주 생기거든.",
  ui_story_1014_10140301_31_dialog_content = "내 주요 임무는 바로 혼자서 이런 돌발 재해에 빠진 사람들을 찾고,\n찾는 김에 암귀도 소탕하는 거야.",
  ui_story_1014_10140301_32_dialog_content = "그러다 아까 이 흰색 덩치를 발견하곤 마침 PlayerName 생각이 났지 뭐야!",
  ui_story_1014_10140301_33_dialog_content = "콜로서스가 있으면 먼 곳에 갈 때도 되게 편리하지?",
  ui_story_1014_10140301_34_dialog_content = "확실히 그렇지. 어딜 가든 콜로서스를 타면 금방 도착하거든.",
  ui_story_1014_10140301_35_dialog_content = "대단하네! 나도 콜로서스가 있었으면 좋겠어.",
  ui_story_1014_10140301_36_dialog_content = "난 내가 그때 빈 소원이 진짜로 이뤄진 줄 알았지 뭐야.",
  ui_story_1014_10140301_37_dialog_content = "근데 조금만 생각해 봐도 이런 변두리에서 버려진\n새 콜로서스를 줍는다는 건 말도 안 되는 일이잖아...",
  ui_story_1014_10140301_38_dialog_content = "풋, 으이구, 아무리 생각해도 말이 안 되잖아.",
  ui_story_1014_10140301_39_dialog_content = "그럼 소개해 줄게. 이쪽은 백야성 하이가든 호위대의 카렌이랑 베르타 씨야.",
  ui_story_1014_10140301_40_dialog_content = "안녕.",
  ui_story_1014_10140301_41_dialog_content = "다음엔 그렇게 경솔하게 굴지 마, 일루미나 소년.",
  ui_story_1014_10140301_42_dialog_content = "죄, 죄송합니다!",
  ui_story_1014_10140301_43_dialog_content = "여기 계신 분은 잉겔 중령님이셔.\n그리고 중령님이 안고 계시는 커다란 상자는 악셀리아인데, 정확히 말하면...",
  ui_story_1014_10140301_44_dialog_content = "...잉겔! 오랜만이야! 이런 데서 다시 만날 줄은 몰랐네!",
  ui_story_1014_10140301_45_dialog_content = "악셀리아는 잘 지내? 몸은 좀 어떻고?",
  ui_story_1014_10140301_46_dialog_content = "다들 서로 아는 사이였구나!",
  ui_story_1014_10140301_47_dialog_content = "설마 이런 데서 다시 만날 줄은 몰랐습니다. 당신은 여전히 기운차군요.",
  ui_story_1014_10140301_48_dialog_content = "하하, 당연하지! 더스크 타운의 생활은 전투의 연속이야.\n내 권법 실력도 꽤 강해졌어!",
  ui_story_1014_10140301_49_dialog_content = "정말 여전히 낙관적이군요...",
  ui_story_1014_10140301_50_dialog_content = "(어쩌다 보니까 잠이 다 달아나 버렸잖아...)",
  ui_story_1014_10140301_51_dialog_content = "난 가서 스카이워커의 상태를 다시 확인해 볼게.\n그러고 나면 출발할 수 있을 거야.",
  ui_story_1014_10140301_52_dialog_content = "출발? 설마 더스크 타운으로 가고 있던 거였어?",
  ui_story_1014_10140301_53_dialog_content = "설명하려면 긴데, 일루미나의 부탁으로 더스크 타운에\n「거래」를 하러 가는 중이었어.",
  ui_story_1014_10140301_54_dialog_content = "그럼 이 근처 지리는 내가 빠삭하게 알고 있으니까, 가이드가 되어 줄게!",
  ui_story_1014_10140301_55_dialog_content = "게다가 난 암귀 처리에도 꽤 자신이 있다구.\n그러니까 가는 길에 발생할지도 모를 돌발 상황은 전부 다 나한테 맡겨.",
  ui_story_1014_10140301_56_dialog_content = "그럼 나야 고맙지!",
  ui_story_1014_10140301_57_dialog_content = "으음...",
  ui_story_1014_10140301_58_dialog_content = "콜로서스의 상태는 좀 어때?",
  ui_story_1014_10140301_59_dialog_content = "전반적으로 큰 문제는 없으니까 이제 출발해도 될 것 같아.",
  ui_story_1014_10140301_60_dialog_content = "이, 입구 쪽은?",
  ui_story_1014_10140301_61_dialog_content = "거기도 멀쩡해! 긴장할 거 없어, 숀.",
  ui_story_1014_10140301_62_dialog_content = "휴... 그럼 됐어. 이제야 좀 안심이 되네.",
  ui_story_1014_10140301_63_dialog_content = "<color=#e8d9bb>스으윽...</color>",
  ui_story_1014_10140301_64_dialog_content = "뭔가 있어!",
  ui_story_1014_10140301_65_dialog_content = "또 시작인가...",
  ui_story_1014_10140301_66_dialog_content = "<anim type=Shake><size=45>그어어어!</size></anim>",
  ui_story_1014_10140301_67_dialog_content = "제 발로 직접 찾아왔구나!",
  ui_story_1014_10140301_68_dialog_content = "그럼 나도 계속해서 「청소 업무」를 수행해야지!",
  ui_story_1014_10140402_1_dialog_content = "이야아압──!",
  ui_story_1014_10140402_2_dialog_content = "대충 이 정도면 되겠지.",
  ui_story_1014_10140402_3_dialog_content = "아무래도 저번에 메디컬 센터에선 내가 널 너무 얕봤던 것 같아!",
  ui_story_1014_10140402_4_dialog_content = "헤헤, 그럼 이제 문제없이 출발할 수 있겠어.",
  ui_story_1014_10140402_5_dialog_content = "근데 있잖아, 본부에서 PlayerName 너한테 거래를 위임한 거라면...",
  ui_story_1014_10140402_6_dialog_content = "내가 우리 쪽 상부에 먼저 연락을 좀 해야 할 것 같아.",
  ui_story_1014_10140402_7_dialog_content = "아, PlayerName 널 의심한다는 건 아니야!",
  ui_story_1014_10140402_8_dialog_content = "그냥 더스크 타운은 외지인들을 많이 껄끄러워해서 그래.",
  ui_story_1014_10140402_9_dialog_content = "이렇게 연락해 두면 나중에 출입 과정이 좀 수월해질 거야.",
  ui_story_1014_10140402_10_dialog_content = "그렇구나. 그럼 부탁할게.",
  ui_story_1014_10140402_11_dialog_content = "<color=#e8d9bb>한편, 스카이워커호의 함교</color>",
  ui_story_1014_10140402_12_dialog_content = "(음... 예전보다 많이 강해졌군요.)",
  ui_story_1014_10140402_13_dialog_content = "잉겔, 숀을 관찰하고 있습니까?",
  ui_story_1014_10140402_14_dialog_content = "악셀리아? 가, 갑자기 뒤에서 튀어나오거나 하면 부담스럽단 말이죠...",
  ui_story_1014_10140402_15_dialog_content = "미안해요.",
  ui_story_1014_10140402_16_dialog_content = "휴식 시간이 되면 약간은 몸을 움직여 줘야 합니다.",
  ui_story_1014_10140402_17_dialog_content = "우리 셋이서 「<color=#FFB400>계명성 프로젝트</color>」의 훈련을 받던 날들이 조금은 그리워지는군요.",
  ui_story_1014_10140402_18_dialog_content = "「졸업」 후 5년밖에 안 됐지만, 악셀리아는 벌써 그때 일들을 거의 잊어버렸습니다.",
  ui_story_1014_10140402_19_dialog_content = "악셀리아의 머릿속엔 여러 가지 명령이 가득 차 있어서 그런 거예요.",
  ui_story_1014_10140402_20_dialog_content = "잉겔이야말로 머릿속에 명령이 가득합니다...",
  ui_story_1014_10140402_21_dialog_content = "그렇지만 이런 부분도 악셀리아의 장점이라고 할 수 있습니다.",
  ui_story_1014_10140402_22_dialog_content = "숀을 포함해 우리 셋은 각자의 자리에서 자신의 특기와 장점을\n발휘하고 있기 때문입니다.",
  ui_story_1014_10140402_23_dialog_content = "흥, 저런 버려진 녀석이...",
  ui_story_1014_10140402_24_dialog_content = "...그래도 즐거워 보이긴 하네요.",
  ui_story_1014_10140402_25_dialog_content = "다들 오래 기다렸지? 이제 출발해도 될 것 같아!",
  ui_story_1014_10140402_26_dialog_content = "더스크 타운의 일루미나 세력도 모두의 방문을 환영한대!",
  ui_story_1014_10140402_27_dialog_content = "?!",
  ui_story_1014_10140402_28_dialog_content = "악셀리아?! 일어났구나!",
  ui_story_1014_10140402_29_dialog_content = "서, 서, 설마 아까 내가 암귀랑 싸우던 거 다 봤어?",
  ui_story_1014_10140402_30_dialog_content = "그렇습니다.",
  ui_story_1014_10140402_31_dialog_content = "어땠어? 나 좀 대단해진 것 같지 않아?\n일루미나에 있었을 때보다 많이 강해진 것 같지?",
  ui_story_1014_10140402_32_dialog_content = "아니면 나랑 한 번 붙어 볼래? 이번엔 누가 이기는지 확인해 볼래?",
  ui_story_1014_10140402_33_dialog_content = "싫습니다.",
  ui_story_1014_10140402_34_dialog_content = "참, 그러고 보니까 너 옆에 내가 모르는 작은 로봇들이 4개나 생겼네!",
  ui_story_1014_10140402_35_dialog_content = "「큐빅」이라고 합니다.",
  ui_story_1014_10140402_36_dialog_content = "어? 「큐빅」이면 세제곱이란 뜻이잖아. 근데 왜 4개인데...?",
  ui_story_1014_10140402_37_dialog_content = "네 번째 로봇은 악셀리아의 소매를 들어 주는 일을 전담하고 있습니다.",
  ui_story_1014_10140402_38_dialog_content = "됐어요, 큐빅이 4개여도 이상할 건 없잖아요!",
  ui_story_1014_10140402_39_dialog_content = "유난 떨지 마세요, 숀.\n악셀리아는 이번에 더스크 타운을 지원할 「거래품」으로 파견된 거니까요.",
  ui_story_1014_10140402_40_dialog_content = "악셀리아의 신체 기능을 소모하게 만드는 짓은 그만두세요.",
  ui_story_1014_10140402_41_dialog_content = "그게 진짜야?!",
  ui_story_1014_10140402_42_dialog_content = "그럼 내가 악셀리아의 선배네!",
  ui_story_1014_10140402_43_dialog_content = "어때? 나한테 물어보고 싶은 거 있어?",
  ui_story_1014_10140402_44_dialog_content = "현재 더스크 타운의 군사 조직 구조는 어떤 상태입니까?",
  ui_story_1014_10140402_45_dialog_content = "그건... 난 말단 업무만 하고 있어서...",
  ui_story_1014_10140402_46_dialog_content = "그럼 더스크 타운에는 특수 유형의 암귀가 출몰합니까?",
  ui_story_1014_10140402_47_dialog_content = "그건 나도 잘...",
  ui_story_1014_10140402_48_dialog_content = "아니면 다른 걸 물어보지 않을래? 예를 들면 더스크 타운엔 뭐가 맛있는지,\n어떤 역사가 있고, 유명한 관광지는 뭐가 있는지 같은 거...",
  ui_story_1014_10140402_49_dialog_content = "시끄럽네요...",
  ui_story_1014_10140501_1_dialog_content = "<color=#e8d9bb>더스크 타운, 외곽 지역</color>",
  ui_story_1014_10140501_2_dialog_content = "카렌 님, 예전 시찰 기록을 보면 이 앞이 바로 더스크 타운인 것 같네요.",
  ui_story_1014_10140501_3_dialog_content = "마중을 나오기로 한 레오 단장도 거의 도착했을 거야. PlayerName, 이제 착륙하자.",
  ui_story_1014_10140501_4_dialog_content = "<color=#e8d9bb>콰앙──</color>",
  ui_story_1014_10140501_5_dialog_content = "무슨 소리지?!",
  ui_story_1014_10140501_6_dialog_content = "폭발이군요.",
  ui_story_1014_10140501_7_dialog_content = "악셀리아, 밖은 혼란스러운 상황이니 우선 수면 캡슐로 돌아가 있어요.",
  ui_story_1014_10140501_8_dialog_content = "하지만 이런 상황에서는 악셀리아가 매우 필요해 보입니다.",
  ui_story_1014_10140501_9_dialog_content = "숀, 바깥에 대체 무슨 일이 벌어진 겁니까?",
  ui_story_1014_10140501_10_dialog_content = "이상해할 거 없어, 아주 정상이야. 다들 조급해하지 말고 조금만 기다려 줘.",
  ui_story_1014_10140501_11_dialog_content = "그냥 평소처럼 암귀들이 잔뜩 몰려왔을 뿐이야.",
  ui_story_1014_10140501_12_dialog_content = "근데... 아래에 있는 사람들이 전부 멈춰 서고 있는데?",
  ui_story_1014_10140501_13_dialog_content = "다들 고개를 들고 뭘 보고 있어.",
  ui_story_1014_10140501_14_dialog_content = "PlayerName의 콜로서스가 눈에 확 띄어서 그런 거겠지!",
  ui_story_1014_10140501_15_dialog_content = "<color=#e8d9bb>위이잉...</color>",
  ui_story_1014_10140501_16_dialog_content = "뭔가 이상해.",
  ui_story_1014_10140501_17_dialog_content = "PlayerName, 어서 적당한 곳을 찾아서 착륙하자.",
  ui_story_1014_10140501_18_dialog_content = "아, 알겠어! 다들 꽉 잡아!",
  ui_story_1014_10140501_19_dialog_content = "오는 길이 순조롭진 않았지만, 그래도 더스크 타운에 온 걸 환영해!",
  ui_story_1014_10140501_20_dialog_content = "여긴 아스트라 대륙의 변방에 있는 도시야. 기후도 좋고 사람들은 순박하고...",
  ui_story_1014_10140501_21_dialog_content = "비켜요! 좀 지나갈게요! 다들 비켜요...!",
  ui_story_1014_10140501_22_dialog_content = "콜록콜록... 으, 먼지!",
  ui_story_1014_10140501_23_dialog_content = "하하하... 가끔 이럴 때도 있지만 말이야.",
  ui_story_1014_10140501_24_dialog_content = "실례합니다. 다들 어디로 가고 계신 거죠? 제가 도와드릴 게 있나요?",
  ui_story_1014_10140501_25_dialog_content = "여기서 더스크 타운까지 많이 먼가요?",
  ui_story_1014_10140501_26_dialog_content = "여기가 바로 더스크 타운의 외곽 지역이에요! 여기 분이 아니신가 봐요?",
  ui_story_1014_10140501_27_dialog_content = "알겠어요. 알려주셔서 고마워요.",
  ui_story_1014_10140501_28_dialog_content = "잠깐만요! 혹시 더스크 타운으로 가시려는 거면 저흴 따라오세요!",
  ui_story_1014_10140501_29_dialog_content = "미안하지만 지금은 1초도 낭비할 수가 없는 상황이야.",
  ui_story_1014_10140501_30_dialog_content = "당신들도 빨리 피난을 떠나는 게 좋을걸.",
  ui_story_1014_10140501_31_dialog_content = "피난이요?",
  ui_story_1014_10140501_32_dialog_content = "저 하늘 색이 이상한 건 <color=#FFB400>오로라 폭발</color>이 일어나기 전에 발생하는 징조야.",
  ui_story_1014_10140501_33_dialog_content = "얼른 안 피했다간 나중에 폭발이 발생했을 때 당신들을 구해줄 사람은 아무도 없어.",
  ui_story_1014_10140501_34_dialog_content = "오로라 폭발...?",
  ui_story_1014_10140501_35_dialog_content = "설명은 교과서에서 몇 번 봤었어.\n오로라가 자주 보이는 북방에서도 오로라 폭발은 무척 보기 드문 현상이야.",
  ui_story_1014_10140501_36_dialog_content = "변방에 거주했던 1세대 주민들이 아니라면,\n오로라 폭발을 경험해 본 사람은 아무도 없을 거야.",
  ui_story_1014_10140501_37_dialog_content = "<color=#e8d9bb>삑── 삐익──</color>",
  ui_story_1014_10140501_38_dialog_content = "더스크 타운 조기 경보기에서 나는 소리야!",
  ui_story_1014_10140501_39_dialog_content = "여러분, 지금 속도론 어떻게 해도 오늘 안에 더스크 타운엔 못 도착해요.",
  ui_story_1014_10140501_40_dialog_content = "전 더스크 타운 일루미나 주둔지의 말단 군인 숀이에요.\n여러분이 제 말을 믿어 주신다면...",
  ui_story_1014_10140501_41_dialog_content = "제가 여러분을 안전하게 임시 참호로 데리고 가 줄게요!",
  ui_story_1014_10140501_42_dialog_content = "당신들을 믿으라고? 고작 젊은 애들 몇 명을?",
  ui_story_1014_10140501_43_dialog_content = "하지만 우린 지금 당장 전투에 나설 수 있는 사람도 없잖아요.\n이 상태로 또 암귀한테 습격이라도 당했다간...",
  ui_story_1014_10140501_44_dialog_content = "암귀요? 설마 여러분의 마을도...",
  ui_story_1014_10140501_45_dialog_content = "...맞아요. 이러다간 우리처럼 도시 주변에 있는 마을들은 갈수록 줄어들 거예요.",
  ui_story_1014_10140501_46_dialog_content = "살기 위해선 더스크 타운 쪽으로 이주하는 방법밖에 없으니까요.",
  ui_story_1014_10140501_47_dialog_content = "애들한테 쓸데 없는 소리 그만해. 그냥 잠깐만 지내려는 것뿐이잖아.",
  ui_story_1014_10140501_48_dialog_content = "언젠간 다시 우리 마을로 돌아갈 거라고...",
  ui_story_1014_10140501_49_dialog_content = "<color=#e8d9bb>우르르르...</color>",
  ui_story_1014_10140501_50_dialog_content = "이번엔 땅에서 소리가 납니다.",
  ui_story_1014_10140501_51_dialog_content = "그어어...",
  ui_story_1014_10140501_52_dialog_content = "<anim type=Shake><size=45>크오오──!</size></anim>",
  ui_story_1014_10140501_53_dialog_content = "암귀야... 암귀가 뒤쫓아 왔어!",
  ui_story_1014_10140501_54_dialog_content = "에너지 흐름이 뒤얽혀 폭발하려는 때를 노려 공격하다니, 머리를 좀 썼구나.",
  ui_story_1014_10140501_55_dialog_content = "베르타.",
  ui_story_1014_10140501_56_dialog_content = "네!",
  ui_story_1014_10140501_57_dialog_content = "제가 여러분이 후퇴할 수 있도록 엄호할게요!",
  ui_story_1014_10140501_58_dialog_content = "계속 피하기만 하는 건 오래 버틸 수 있는 전술이 아닙니다.",
  ui_story_1014_10140501_59_dialog_content = "악셀리아가 전투에 나서게 해 주세요.\n그렇지 않으면 악셀리아도 강경한 수단을 사용하겠습니다.",
  ui_story_1014_10140501_60_dialog_content = "지금은 싸울 생각만 할 때가 아니야!",
  ui_story_1014_10140501_61_dialog_content = "암귀 녀석들한테 무작정 달려가면, 손에 무기조차 없는 이 사람들은 어떻게 해?",
  ui_story_1014_10140501_62_dialog_content = "악셀리아는 사람들을 보호할 자신이 있습니다.",
  ui_story_1014_10140501_63_dialog_content = "안심하세요. 금방 끝납니다.",
  ui_story_1014_10140501_64_dialog_content = "안 된다고 했잖아!",
  ui_story_1014_10140501_65_dialog_content = "베르타, 악셀리아, 너흰 따로 움직이자.",
  ui_story_1014_10140501_66_dialog_content = "베르타, 카렌, 숀은 사람들을 세 무리로 나눠서 인솔해.",
  ui_story_1014_10140501_67_dialog_content = "악셀리아, 잉겔 씨, 바이스, 우린 암귀를 상대하자!",
  ui_story_1014_10140501_68_dialog_content = "알겠어.\n알겠습니다.",
  ui_story_1014_10140501_69_dialog_content = "전투 인력을 낭비할 필요는 없습니다.",
  ui_story_1014_10140501_70_dialog_content = "이 암귀들은 저희 강철가시 기사단에 맡기세요.",
  ui_story_1014_10140501_71_dialog_content = "기사단이 멀리까지 마중을 나가지 못해 죄송합니다.\n그래도 다행히 아직은 사상자가 나오지 않은 상태군요.",
  ui_story_1014_10140501_72_dialog_content = "레오 단장, 제때 잘 왔어.\n더스크 타운까지 안내해 주기 전에, 우리와 함께 암귀를 물리치자.",
  ui_story_1014_10140501_73_dialog_content = "물론입니다. 전투가 일촉즉발의 위기 상태인 만큼,\n말에서 내리지 못하는 것을 양해해 주시지요, 카렌 전하.",
  ui_story_1014_10140501_74_dialog_content = "개의치 않아도 좋아. 예법보다는 기사로서 당신 명성에 걸맞은 모습을 보이면 돼.",
  ui_story_1014_10140501_75_dialog_content = "하하하하, 제가 기사가 된 건 명성을 위해서가 아니라, 더스크 타운을 위해서입니다.",
  ui_story_1014_10140501_76_dialog_content = "기사단이여! 손에 쥔 검을 들어라!",
  ui_story_1014_10140501_77_dialog_content = "이번 전투의 요구는 하나뿐...",
  ui_story_1014_10140501_78_dialog_content = "마지막 한숨밖에 남지 않을 때까지, 더 많은 암귀를 물리치는 것이다.",
  ui_story_1014_10140501_79_dialog_content = "돌격하라!",
  ui_story_1014_10140602_1_dialog_content = "대형을 유지해라. 흐트러져선 안 된다.",
  ui_story_1014_10140602_2_dialog_content = "우선 측면에 있는 적부터 처치한다.",
  ui_story_1014_10140602_3_dialog_content = "예!",
  ui_story_1014_10140602_4_dialog_content = "또 암귀 무리들이 몰려오고 있어! 수도 아까보다 더 많아!",
  ui_story_1014_10140602_5_dialog_content = "계속 이렇게 맞서는 건 힘들어. 일단 조금 후퇴하는 게 좋지 않을까?",
  ui_story_1014_10140602_6_dialog_content = "음, 나도 보여. 확실히 작은 규모는 아니야.",
  ui_story_1014_10140602_7_dialog_content = "그럼 일단...",
  ui_story_1014_10140602_8_dialog_content = "기사단 전원은 들어라! 중장비는 벗어 두고 돌격 준비를 시작하라!",
  ui_story_1014_10140602_9_dialog_content = "예!",
  ui_story_1014_10140602_10_dialog_content = "뭐? 돌격? 지금?",
  ui_story_1014_10140602_11_dialog_content = "지금 우리 전력으론 저 암귀 무리에 정면으로 맞서는 건 좋은 선택이 아닌 것 같은데...",
  ui_story_1014_10140602_12_dialog_content = "외지인, 너흰 우릴 따라오지 않아도 돼. 여기서 잘 보고 있어.",
  ui_story_1014_10140602_13_dialog_content = "기사단 전원! 화살 진형을 갖춘다!\n두 부대로 나누어 하나는 나를, 나머지는 부단장을 따른다.",
  ui_story_1014_10140602_14_dialog_content = "적진을 돌파한 후 각개 행동한다.",
  ui_story_1014_10140602_15_dialog_content = "지금부터 내가 쥐고 있는 깃발을 잘 봐라.",
  ui_story_1014_10140602_16_dialog_content = "강철가시 기사단, 돌격!",
  ui_story_1014_10140602_17_dialog_content = "<size=50>돌격!</size>",
  ui_story_1014_10140602_18_dialog_content = "다들 저 암귀 무리들 쪽으로 몰려가 버렸어! 너무... 무모한 거 아냐?",
  ui_story_1014_10140602_19_dialog_content = "그렇진 않아, 저길 봐.",
  ui_story_1014_10140602_20_dialog_content = "생각보다 순조롭게 적진을 돌파하고 있어.",
  ui_story_1014_10140602_21_dialog_content = "정말이네요! 저렇게 많은 암귀들이 기사단의 공세를 못 막고 있어요!",
  ui_story_1014_10140602_22_dialog_content = "칼로 베이듯 중앙부터 분열되고 있네요...",
  ui_story_1014_10140602_23_dialog_content = "저게 어떻게 가능한 거지?!",
  ui_story_1014_10140602_24_dialog_content = "난 조금 알 것 같아. 베르타가 아주 적절하게 표현했어.",
  ui_story_1014_10140602_25_dialog_content = "기사단은 칼인 거야.",
  ui_story_1014_10140602_26_dialog_content = "칼로 가축을 벨 때 칼이 무거운지, 가축이 무거운지 따지는 사람은 없어.",
  ui_story_1014_10140602_27_dialog_content = "무겁지 않아도 충분히 날카로우면 벨 수 있으니까.",
  ui_story_1014_10140602_28_dialog_content = "베는 건가...",
  ui_story_1014_10140602_29_dialog_content = "봐, 레오 단장이 기사단 절반을 데리고 돌아왔어.",
  ui_story_1014_10140602_30_dialog_content = "<color=#e8d9bb>다그닥, 다그닥, 다그닥...</color>",
  ui_story_1014_10140602_31_dialog_content = "외지인, 어때? 돌격이란 선택도 그렇게 나쁘지만은 않았지?",
  ui_story_1014_10140602_32_dialog_content = "전장은 단순한 물량 싸움이 아니야. 같은 힘을 가지고 있다고 하더라도,\n어떤 전술을 사용하느냐에 따라 다른 역량을 발휘해.",
  ui_story_1014_10140602_33_dialog_content = "여긴 머나먼 변방이야. 우린 암귀들을 힘으로 압도할 여력은 없어.",
  ui_story_1014_10140602_34_dialog_content = "하지만 암귀들은 전술을 모르고, 우린 알지. 그게 바로 우리가 지닌 이점이야.",
  ui_story_1014_10140602_35_dialog_content = "전술... 그렇다면 조금 전엔 돌격을 감행해도 된다고 어떻게 판단한 거야?",
  ui_story_1014_10140602_36_dialog_content = "난 저런 유형의 암귀들에 대해 잘 알거든.",
  ui_story_1014_10140602_37_dialog_content = "저 녀석들은 공격성이 높고, 무리로 행동하는 걸 좋아해.\n하지만 돌발 상황 대처에 서투르다는 명확한 약점을 가지고 있어.",
  ui_story_1014_10140602_38_dialog_content = "따라서 녀석들을 상대할 땐 설령 녀석들의 힘이 우리보다 강하더라도,\n반드시 우리가 먼저 녀석들을 공격해야 해.",
  ui_story_1014_10140602_39_dialog_content = "우리의 돌격은 힘을 한데 모을 수 있고, 적의 기세를 꺾어 그들의 전력을 약화시킬 수 있어.",
  ui_story_1014_10140602_40_dialog_content = "게다가 암귀들의 대형을 갈라놓는 것도 가능해.\n적의 힘이 분산될수록 우리에겐 유리해지고 말이야.",
  ui_story_1014_10140602_41_dialog_content = "봐, 내가 적진 중앙에 기사단의 절반을 남겨 두고 왔어.",
  ui_story_1014_10140602_42_dialog_content = "저들은 암귀들의 주변을 맴돌며 적진을 쪼개고, 소규모의 적 무리를 처치하면서\n전장을 한층 더 뒤흔들어 놓을 거야.",
  ui_story_1014_10140602_43_dialog_content = "대단하네! 암귀를 상대하는 작전에 이렇게 많은 생각을 할 수도 있는 거였구나.",
  ui_story_1014_10140602_44_dialog_content = "우리랑 암귀의 전력차는 눈에 띌 정도인데,\n전장의 형세는 의외로 서로 막상막하인 것처럼 보여...",
  ui_story_1014_10140602_45_dialog_content = "바로 그래서 전술이 더더욱 중요한 거야.",
  ui_story_1014_10140602_46_dialog_content = "하지만 나보다 먼저 암귀의 움직임을 파악하다니, 외지인 네 실력도 보통은 아니구나.",
  ui_story_1014_10140602_47_dialog_content = "이런 전장에서 적을 감지할 수 있는 능력은 보기 드문데 말이야.",
  ui_story_1014_10140602_48_dialog_content = "아, 사실 그렇게 띄워줄 만한 일은 아니야.",
  ui_story_1014_10140602_49_dialog_content = "난 당신이랑 다르게 오로리안이 아니라, 아이테르거든.",
  ui_story_1014_10140602_50_dialog_content = "아이테르? 전설의 그 종족 말이야?",
  ui_story_1014_10140602_51_dialog_content = "하하하하, 재미있네! 책 속에나 나오던 인물을 현실에서 보게 됐잖아.",
  ui_story_1014_10140602_52_dialog_content = "그럼 아이테르, 네 예민한 감응 능력으로 우리가 이제부터 뭘 해야 할지 알아내 볼래?",
  ui_story_1014_10140602_53_dialog_content = "으음... 적들이 진형을 다잡기 전에 다시 공격하는 거야?",
  ui_story_1014_10140602_54_dialog_content = "아니, 이젠 후퇴해야 해.",
  ui_story_1014_10140602_55_dialog_content = "뭐? 왜? 이제 막 우리가 유리해진 참이었잖아.",
  ui_story_1014_10140602_56_dialog_content = "이 전장에만 계속 시선을 빼앗길 순 없어.",
  ui_story_1014_10140602_57_dialog_content = "우리의 목표는 모든 암귀를 저지하는 거야. 하지만 지금 이 상태론 부족하지.",
  ui_story_1014_10140602_58_dialog_content = "우리 뒤편엔 지형이 험하고 좁은 길목이 자리 잡고 있어.\n이 전투는 반드시 그곳으로 이동하게 되겠지.",
  ui_story_1014_10140602_59_dialog_content = "그러니 미리 준비해 두는 게 좋아.",
  ui_story_1014_10140602_60_dialog_content = "외지인, 우릴 도와주겠어?",
  ui_story_1014_10140602_61_dialog_content = "물론이지! 당신 전술도 더 자세히 보고 싶어!",
  ui_story_1014_10140602_62_dialog_content = "그래, 어차피 우리도 암귀와 싸우려고 했던 거니까.",
  ui_story_1014_10140602_63_dialog_content = "저기, 기사단을 돕고 말고는 상관없지만, 문제가 하나 있습니다...",
  ui_story_1014_10140602_64_dialog_content = "혹시 숀 녀석이 어디 있는지 본 사람 없나요?",
  ui_story_1014_10140602_65_dialog_content = "<size=45>죽어!</size>",
  ui_story_1014_10140602_66_dialog_content = "어디 얼마나 더 튀어나오는지 보자고!",
  ui_story_1014_10140602_67_dialog_content = "일루미나 병사, 네가 이렇게 잘 싸울 줄은 몰랐다.",
  ui_story_1014_10140602_68_dialog_content = "어? 저기, 그... 칭찬 고마워!",
  ui_story_1014_10140602_69_dialog_content = "우리 강철가시 기사단의 전장에서 이렇게 눈에 띄는 활약을 펼치다니.",
  ui_story_1014_10140602_70_dialog_content = "너처럼 출중한 전사는 칭찬받아 마땅하지.",
  ui_story_1014_10140602_71_dialog_content = "그, 그래? 난 칭찬을 많이 안 받아 봤거든.",
  ui_story_1014_10140602_72_dialog_content = "그런데 왜 우릴 따라온 거지? 단장님께서 제자리에 있으라고 하지 않으셨나?",
  ui_story_1014_10140602_73_dialog_content = "그랬어?!",
  ui_story_1014_10140602_74_dialog_content = "봐, 네 동료들은 저쪽에 가만히 있잖아.",
  ui_story_1014_10140602_75_dialog_content = "아! 기억났다! 레오 단장이 외지인은 따라올 필요가 없다고 했었지.",
  ui_story_1014_10140602_76_dialog_content = "근데 난 외지인 아닌데? 나도 더스크 타운에 살아.",
  ui_story_1014_10140602_77_dialog_content = "......",
  ui_story_1014_10140602_78_dialog_content = "혹시 머리가 별로 안 좋단 얘기 들어본 적 있나?",
  ui_story_1014_10140602_79_dialog_content = "음, 있어.",
  ui_story_1014_10140602_80_dialog_content = "아무리 그래도 내가 비꼰 것 정도는 알아차려 줬으면 좋겠는데...",
  ui_story_1014_10140602_81_dialog_content = "됐어, 그만하자고. 네 덕에 전황이 많이 좋아지기도 했으니까.",
  ui_story_1014_10140602_82_dialog_content = "우리가 맡은 임무는 암귀들을 쫓아 이 주변을 도는 거였지만,\n지금 상태를 보면 적을 전부 처치하는 것도 무리는 아니겠어.",
  ui_story_1014_10140602_83_dialog_content = "당연히 다 처치해 버려야지! 암귀는 단 한 마리도 놓쳐선 안 돼!",
  ui_story_1014_10140602_84_dialog_content = "열정이 넘치는구나. 나쁘지 않아, 열정이 있다는 건 좋은 일이지.",
  ui_story_1014_10140602_85_dialog_content = "강철가시 기사단과 레오 단장의 명성은 예전부터 들었어.",
  ui_story_1014_10140602_86_dialog_content = "영웅 같은 부대랑 어깨를 나란히 하고 적과 싸울 수 있으니까,\n피가 막 부글부글 끌어오르는 것 같아!",
  ui_story_1014_10140602_87_dialog_content = "이 석궁들을 풀숲에 숨겨 놔. 준비 작업은 이 정도면 되겠어.",
  ui_story_1014_10140602_88_dialog_content = "마침 전장에 나가 있던 기사들이 돌아오고 있어.",
  ui_story_1014_10140602_89_dialog_content = "<color=#e8d9bb>다그닥, 다그닥, 다그닥...</color>",
  ui_story_1014_10140602_90_dialog_content = "단장님.",
  ui_story_1014_10140602_91_dialog_content = "잘해줬다. 내 예상보다 훌륭했어.",
  ui_story_1014_10140602_92_dialog_content = "이렇게 순조로울 수 있었던 건 모두 이 일루미나 전사의 협조가 있었기 때문입니다.",
  ui_story_1014_10140602_93_dialog_content = "에이, 딱히 그런 건...",
  ui_story_1014_10140602_94_dialog_content = "그래, 나도 봤다. 그렇게 열심히 싸웠는데, 눈이 가지 않는 게 이상한 일이겠지.",
  ui_story_1014_10140602_95_dialog_content = "넌 일루미나의 군인인가?",
  ui_story_1014_10140602_96_dialog_content = "네! 더스크 타운 주둔군 숀 소위입니다!",
  ui_story_1014_10140602_97_dialog_content = "더스크 타운 주둔군이라. 이웃에 이렇게 용맹한 전사가 있다는 건 오늘 처음 알았네.",
  ui_story_1014_10140602_98_dialog_content = "아니에요! 전 동기들에 비하면 돋보이는 점도 없고, 전투 경험도 부족해요.",
  ui_story_1014_10140602_99_dialog_content = "레오 단장님 같은 분이 절 모르는 것도 당연해요.",
  ui_story_1014_10140602_100_dialog_content = "넌 나를 아는 모양이네.",
  ui_story_1014_10140602_101_dialog_content = "네! 더스크 타운에서 강철가시 기사단의 명성을 모르는 사람은 아무도 없으니까요!",
  ui_story_1014_10140602_102_dialog_content = "그렇구나. 그럼 우리 기사단에 들어오지 않겠어?",
  ui_story_1014_10140602_103_dialog_content = "하아?",
  ui_story_1014_10140602_104_dialog_content = "뛰어난 전사는 병영에 누워 적당히 하루를 보낼 게 아니라,\n전장에서 자신의 가치를 선보여야 하는 법이지.",
  ui_story_1014_10140602_105_dialog_content = "강철가시 기사단에 들어온다면 한 달 안에 네 이름을\n더스크 타운 전역에 알릴 수 있도록 해 줄게.",
  ui_story_1014_10140602_106_dialog_content = "아... 근데...",
  ui_story_1014_10140602_107_dialog_content = "크흠, 레오 단장, 그런 스카우트는 규정 위반입니다만.",
  ui_story_1014_10140602_108_dialog_content = "정 우리 병사를 꼬드기고 싶다면 적어도 안 보이는 곳에서 하시죠.",
  ui_story_1014_10140602_109_dialog_content = "하하, 미안하게 됐습니다.\n하지만 인재 초빙을 왜 몰래 해야 하는지는 잘 모르겠군요.",
  ui_story_1014_10140602_110_dialog_content = "백야성과 일루미나는 그저 각자가 의탁하고 있는 장소에 지나지 않습니다.\n우리 모두의 적은 암귀입니다.",
  ui_story_1014_10140602_111_dialog_content = "전 그저 이 소년에게 돌아갈 곳으로 더 좋은 환경을 제공해 주고 싶었을 뿐입니다.",
  ui_story_1014_10140602_112_dialog_content = "물론 여장교님께서도 훌륭한 활약을 보여주셨죠.\n의향만 있다면, 강철가시 기사단은 언제든 당신을 환영합니다.",
  ui_story_1014_10140602_113_dialog_content = "당신... 강철가시 기사단장의 특기가 유세일 줄은 몰랐네요.",
  ui_story_1014_10140602_114_dialog_content = "저도 당신에게 더 좋은 환경을 제공해 주고 싶으니,\n자난성으로 와서 정치인이나 하시지 그래요.",
  ui_story_1014_10140602_115_dialog_content = "정치인이라. 나쁘지 않군요. 생각해 보겠습니다.",
  ui_story_1014_10140602_116_dialog_content = "졸려요.",
  ui_story_1014_10140602_117_dialog_content = "어?",
  ui_story_1014_10140602_118_dialog_content = "하암── 악셀리아는 졸립니다.",
  ui_story_1014_10140602_119_dialog_content = "하필 이럴 때...",
  ui_story_1014_10140602_120_dialog_content = "됐어요, 뭐 어떻게 할 수 있는 것도 아니니까요.\n수면 캡슐로 돌아가서 쉬어요, 악셀리아.",
  ui_story_1014_10140602_121_dialog_content = "네, 여러분 모두 힘을 내세요.",
  ui_story_1014_10140602_122_dialog_content = "악셀리아는 잠에서 깨어난 다음에 다시 여러분을 도울 겁니다.",
  ui_story_1014_10140602_123_dialog_content = "복잡하게 생각하지 말고 푹 쉬세요.",
  ui_story_1014_10140602_124_dialog_content = "PlayerName, 수면 캡슐을 잘 부탁합니다.",
  ui_story_1014_10140602_125_dialog_content = "응, 알겠어!",
  ui_story_1014_10140602_126_dialog_content = "소녀가 상자 안으로 들어가 버리다니!",
  ui_story_1014_10140602_127_dialog_content = "외지인들은 날 참 깜짝 놀라게 만든단 말이지.",
  ui_story_1014_10140602_128_dialog_content = "악셀리아는 몸 상태가 별로 안 좋아서,\n자주 저 「수면 캡슐」안에 들어가서 쉬어 줘야 한대.",
  ui_story_1014_10140602_129_dialog_content = "그런데 어째서 이렇게 위험한 곳까지 데려온 거지?",
  ui_story_1014_10140602_130_dialog_content = "저 아이를 안전히 더스크 타운에 데려다주는 게 우리 임무거든.",
  ui_story_1014_10140602_131_dialog_content = "아, 이해했어. 임무라면 더 캐묻지 않을게.",
  ui_story_1014_10140602_132_dialog_content = "이야기는 이쯤에서 마무리 짓도록 할까.\n근처 멀지 않은 곳에서 암귀 녀석들의 움직임이 느껴지고 있거든.",
  ui_story_1014_10140602_133_dialog_content = "그 녀석들이 시야에 들어오기 전에 여기 철책을 세워 둬야겠어.",
  ui_story_1014_10140602_134_dialog_content = "우리도 도울게. 우리가 해야 할 일이 있나?",
  ui_story_1014_10140602_135_dialog_content = "카렌 전하께선 기사단의 계획에 얽매이실 필요는 없습니다.\n친구분들과 함께 전투에만 신경 쓰시면 됩니다.",
  ui_story_1014_10140602_136_dialog_content = "사실 전하의 신분을 생각하면 지휘권을 넘겨 드려야 마땅할 것입니다.",
  ui_story_1014_10140602_137_dialog_content = "하지만 지금은 상황이 특수한 탓에, 기사단원들의 적응을 우려해 그러질 못했습니다.\n주제넘은 일이지만 부디 너그럽게 이해해 주셨으면 합니다.",
  ui_story_1014_10140602_138_dialog_content = "......",
  ui_story_1014_10140602_139_dialog_content = "지휘권은 모두에게 승리를 더 쉽게 가져다줄 수 있는 사람이 가지는 게 맞아.\n그러니 이 일로 그렇게 불필요한 겸양을 보일 필요는 없어.",
  ui_story_1014_10140602_140_dialog_content = "자유롭게 행동해도 된다면 우린 방어선 동쪽을 지원하러 가 볼게.",
  ui_story_1014_10140602_141_dialog_content = "내 판단이 틀리지 않았다면, 그곳의 방어가 상대적으로 취약할 거야.",
  ui_story_1014_10140602_142_dialog_content = "동쪽이라... 네, 맞습니다.\n기사단의 인원이 부족한 탓에 그쪽은 유일한 잠재 위협으로 남아 있습니다.",
  ui_story_1014_10140602_143_dialog_content = "카렌 전하께선 전략적인 안목이 무척 정확하시군요.",
  ui_story_1014_10140602_144_dialog_content = "내가 기사장이란 칭호를 받을 수 있었던 건 혈통 때문이 아니야.\n날 「백야성의 공주」로만 여기지는 않았으면 좋겠어.",
  ui_story_1014_10140602_145_dialog_content = "그럴 일은 없을 겁니다. 전 백야성의 기사라는 직위에 믿음을 가지고 있으니까요.",
  ui_story_1014_10140602_146_dialog_content = "기사라면 모두가 같은 명예를 짊어지고 전투에 임하는 것이 아니겠습니까.",
  ui_story_1014_10140602_147_dialog_content = "PlayerName, 여긴 비교적 안전한 후방이니까,\n악셀리아의 수면 캡슐은 여기 두도록 하자.",
  ui_story_1014_10140602_148_dialog_content = "응, 그러자.",
  ui_story_1014_10140602_149_dialog_content = "레오 단장의 기존 인력 배치를 고려해 보면, 동쪽의 방어선이 상대적으로 취약할 거야.",
  ui_story_1014_10140602_150_dialog_content = "우리가 그곳의 방어에 힘을 보태자.",
  ui_story_1014_10140602_151_dialog_content = "네, 카렌 님.",
  ui_story_1014_10140602_152_dialog_content = "카렌, 레오 단장의 지휘에 꽤 잘 맞춰 주는구나.",
  ui_story_1014_10140602_153_dialog_content = "그 사람은 지휘 경험이 풍부하니까. 너도 봤잖아.\n이 전장에선 레오 단장의 말을 따르면 비교적 쉽게 승리를 거둘 수 있어.",
  ui_story_1014_10140602_154_dialog_content = "그렇지만 그 사람 우리한텐 구체적으로 임무 지시는 안 했잖아.",
  ui_story_1014_10140602_155_dialog_content = "응, 하려고 안 할 거야.",
  ui_story_1014_10140602_156_dialog_content = "어? 왜 그런 건데?",
  ui_story_1014_10140602_157_dialog_content = "레오가 의식해서 거리를 두고 있다는 느낌을 받았어.",
  ui_story_1014_10140602_158_dialog_content = "나한테 굽실거리지도 않겠지만, 명령을 내리려고도 하지 않을 거야.",
  ui_story_1014_10140602_159_dialog_content = "난 백야성 성주의 딸이잖아.",
  ui_story_1014_10140602_160_dialog_content = "그렇구나. 잘은 모르겠지만, 그럼 그게 나쁜 일일까?",
  ui_story_1014_10140602_161_dialog_content = "나도 잘 모르겠어.",
  ui_story_1014_10140602_162_dialog_content = "사실 난 레오 단장이 허례허식에 얽매이지 않는 순수한 전사였으면 했어.",
  ui_story_1014_10140602_163_dialog_content = "머나먼 변방에서, 두 눈에 전장 말고는 아무것도 안 보이는 그런 사람 말이야.",
  ui_story_1014_10140602_164_dialog_content = "하지만 저 사람은 오히려 내 신분을 신경 쓰고 있었어.",
  ui_story_1014_10140602_165_dialog_content = "대신 나와의 거리감을 「신하의 도리」에서 「존중」으로 탈바꿈했지.",
  ui_story_1014_10140602_166_dialog_content = "그래서 나도 그 사람을 존중해 줄 수밖에 없었고,\n그 사람이 준비해 둔 전술에 맞춰 주기로 한 거야.",
  ui_story_1014_10140602_167_dialog_content = "엄청 복잡하네. 그런 걸 보고 전장 정치라고 하는 건가?",
  ui_story_1014_10140602_168_dialog_content = "적합한 표현이네.",
  ui_story_1014_10140602_169_dialog_content = "백야성의 비애가 바로 이런 걸지도 모르겠어.\n우린 언제나 정치에서 벗어나질 못하니까.",
  ui_story_1014_10140602_170_dialog_content = "<color=#e8d9bb>콰앙──</color>",
  ui_story_1014_10140602_171_dialog_content = "!!!",
  ui_story_1014_10140602_172_dialog_content = "무슨 소리야?",
  ui_story_1014_10140602_173_dialog_content = "<color=#e8d9bb>쿠우웅──!</color>",
  ui_story_1014_10140602_174_dialog_content = "뭔가 이쪽으로 오고 있어!",
  ui_story_1014_10140602_175_dialog_content = "다크매터가 엄청 짙어. 아마 대규모의 적일 거야.",
  ui_story_1014_10140602_176_dialog_content = "그리고... 덩치가 큰 녀석도 하나 있는 것 같아!",
  ui_story_1014_10140701_1_dialog_content = "강철가시 기사단, 응전을 준비하라!",
  ui_story_1014_10140701_2_dialog_content = "내 명령 없이는 그 누구도 대열을 이탈해선 안 된다!",
  ui_story_1014_10140701_3_dialog_content = "예!",
  ui_story_1014_10140701_4_dialog_content = "<color=#e8d9bb>쿵── 쿵──</color>",
  ui_story_1014_10140701_5_dialog_content = "아까보다 더 많은 암귀가 몰려오고 있습니다.",
  ui_story_1014_10140701_6_dialog_content = "이렇게 소란스러운 움직임이라면 그 녀석이겠군요.",
  ui_story_1014_10140701_7_dialog_content = "「<color=#FFB400>래비드후프</color>」.",
  ui_story_1014_10140701_8_dialog_content = "래비드후프... 녀석이 또...",
  ui_story_1014_10140701_9_dialog_content = "그게 뭐죠?",
  ui_story_1014_10140701_10_dialog_content = "말도 안 되게 힘이 센 특이한 암귀입니다.",
  ui_story_1014_10140701_11_dialog_content = "저희 강철가시 기사단도 맞붙어 싸워 본 적은 있지만,\n녀석과 저희 양쪽 다 상당한 대가를 치렀죠.",
  ui_story_1014_10140701_12_dialog_content = "그럼 이번엔 녀석을 막아 낼 자신이 있나요?",
  ui_story_1014_10140701_13_dialog_content = "자신이 있냐 없냐의 문제가 아니라, 반드시 막아야만 합니다.",
  ui_story_1014_10140701_14_dialog_content = "저희가 무너지면, 이 뒤엔 바로 더스크 타운이 있습니다.",
  ui_story_1014_10140701_15_dialog_content = "저 녀석을 막을 또 다른 강철가시 기사단이 나타나기만을 기대해선 안 됩니다.",
  ui_story_1014_10140701_16_dialog_content = "잠깐, 저기 좀 봐! 암귀 떼 맨 앞에!",
  ui_story_1014_10140701_17_dialog_content = "사람이야! 시민들이 녀석들한테서 도망치고 있어!",
  ui_story_1014_10140701_18_dialog_content = "제발... 누가 좀...",
  ui_story_1014_10140701_19_dialog_content = "이젠... 못 뛰겠어...",
  ui_story_1014_10140701_20_dialog_content = "조금만 더 버텨... 고, 곧 더스크 타운에 도착할 거야...",
  ui_story_1014_10140701_21_dialog_content = "거기 도착하면 분명히 누군가 우릴 지켜 줄 거야... 확실해!",
  ui_story_1014_10140701_22_dialog_content = "그때까지 버틸 수 있을까...",
  ui_story_1014_10140701_23_dialog_content = "뒤에서 나는 소리가 들려... 괴물들의 울부짖음이...",
  ui_story_1014_10140701_24_dialog_content = "그 소리들이 들려... 가까이... 아주 가까이에서...",
  ui_story_1014_10140701_25_dialog_content = "진짜 사람이 있잖아?! 곧 잡히겠어!",
  ui_story_1014_10140701_26_dialog_content = "빨리 구하러 가야 해! 안 그러면 잡히고 말 거야!",
  ui_story_1014_10140701_27_dialog_content = "맞아! 레오 단장, 저 사람들을 어떻게 구해야 하지?",
  ui_story_1014_10140701_28_dialog_content = "......",
  ui_story_1014_10140701_29_dialog_content = "레오 단장!",
  ui_story_1014_10140701_30_dialog_content = "강철가시 기사단은 대열을 이탈할 수 없어.",
  ui_story_1014_10140701_31_dialog_content = "<size=45>뭐라고?!</size>",
  ui_story_1014_10140701_32_dialog_content = "곧 암귀 무리가 돌격해 오는 상황에서 대열을 무너트리는 건 자살 행위야.",
  ui_story_1014_10140701_33_dialog_content = "그러니 우린 대열을 이탈할 순 없어.",
  ui_story_1014_10140701_34_dialog_content = "그럼 저 사람들은 어떡해! 저기서 도망치고 있는 시민들 말이야!",
  ui_story_1014_10140701_35_dialog_content = "곧 암귀들한테 따라잡힐 거야!",
  ui_story_1014_10140701_36_dialog_content = "미안해, 우린 기사지 신이 아니야. 우리가 모든 사람을 구할 순 없어.",
  ui_story_1014_10140701_37_dialog_content = "당신...",
  ui_story_1014_10140701_38_dialog_content = "난민들 때문에 암귀 떼에게 더스크 타운을 노출시킬 순 없어.\n게다가 평민들을 위해 내 기사들을 헛되이 희생시킬 수도 없어.",
  ui_story_1014_10140701_39_dialog_content = "여긴 변방이야. 목숨 하나하나가 모두 다 소중하지. 그래서 선택이 무척 중요해.",
  ui_story_1014_10140701_40_dialog_content = "그럼 저 사람들이 암귀들 손에 죽는 걸 보고만 있어야 해?",
  ui_story_1014_10140701_41_dialog_content = "가만히 두고 볼 수 없다면, 너희가 자율적으로 행동해도 좋아.",
  ui_story_1014_10140701_42_dialog_content = "너흰 강철가시 기사단의 단원이 아니니까.",
  ui_story_1014_10140701_43_dialog_content = "......",
  ui_story_1014_10140701_44_dialog_content = "알겠어. 그럼 방어선을 부탁할게.\n그리고 악셀리아의 수면 캡슐이 손상되지 않게 잘 지켜줘.",
  ui_story_1014_10140701_45_dialog_content = "우린 당신이 고르지 않은 선택을 할 테니까!",
  ui_story_1014_10140701_46_dialog_content = "<size=40>으아아악!</size>",
  ui_story_1014_10140701_47_dialog_content = "오빠! 왜 그래!",
  ui_story_1014_10140701_48_dialog_content = "괴물들이 바로 내 뒤에 있어! 놈이... 내 다리를 할퀴었어...",
  ui_story_1014_10140701_49_dialog_content = "넌 어서 도망쳐! 빨리!",
  ui_story_1014_10140701_50_dialog_content = "싫어! 난 오빠랑...",
  ui_story_1014_10140701_51_dialog_content = "<size=40>으아악!</size>",
  ui_story_1014_10140701_52_dialog_content = "<size=40>저리 비켜어어어어!</size>",
  ui_story_1014_10140701_53_dialog_content = "어? 이 사람들은...",
  ui_story_1014_10140701_54_dialog_content = "카렌, 여기도 있어!",
  ui_story_1014_10140701_55_dialog_content = "알겠어.",
  ui_story_1014_10140701_56_dialog_content = "먼 데 있는 녀석들은 나한테 맡겨!",
  ui_story_1014_10140701_57_dialog_content = "다들 절 따라오세요! 조금만 더 버티면 안전해질 거예요!",
  ui_story_1014_10140701_58_dialog_content = "살았다! 우리를 구하러 와 줬어!",
  ui_story_1014_10140701_59_dialog_content = "서둘러! 어서 저 사람들을 따라가!",
  ui_story_1014_10140701_60_dialog_content = "기사단의 방어선까지 후퇴하려면 시간이 모자랄 것 같군요.",
  ui_story_1014_10140701_61_dialog_content = "암귀 무리가 접근하고 있습니다. 녀석들과 맞설 준비를 해 두세요.",
  ui_story_1014_10140701_62_dialog_content = "이렇게 빨리? 근처에 있는 이 시민들은 어떻게 하지?!",
  ui_story_1014_10140701_63_dialog_content = "일단 모두를 한곳으로 모아!",
  ui_story_1014_10140701_64_dialog_content = "내가 힘닿는 데까지 보호할 테니까!",
  ui_story_1014_10140701_65_dialog_content = "보세요, 녀석들이 왔습니다.",
  ui_story_1014_10140701_66_dialog_content = "<color=#e8d9bb>쿵── 쿵── 쿵──</color>",
  ui_story_1014_10140701_67_dialog_content = "<anim type=Shake><size=45>캬아악! 크오오!</size></anim>",
  ui_story_1014_10140701_68_dialog_content = "바이스, 조금만 뒤로 물러나 줘. 암귀가 너무 접근하지 않게 주의해.",
  ui_story_1014_10140701_69_dialog_content = "상황이 이런데 물러날 데가 어디 있겠어! 오른쪽 조심해!",
  ui_story_1014_10140701_70_dialog_content = "으악! 뭐가 이렇게 많아! 동료들은 어디 갔지? 나 지금 어디 있는 거야?",
  ui_story_1014_10140701_71_dialog_content = "쳇, 악셀리아가 있었으면 좋았을 텐데 말이죠.",
  ui_story_1014_10140701_72_dialog_content = "야! 그렇게 말하면 나 상처받거든! 나도 여기 있다고!",
  ui_story_1014_10140701_73_dialog_content = "다들 내 뒤로 피해! 멋대로 돌아다니지 마!",
  ui_story_1014_10140701_74_dialog_content = "내가 지켜줄 테니까...",
  ui_story_1014_10140701_75_dialog_content = "으아아! 암귀들이 몰려오고 있어요!",
  ui_story_1014_10140701_76_dialog_content = "뭐? 어디서?",
  ui_story_1014_10140701_77_dialog_content = "여기요! 여기도 있어요!",
  ui_story_1014_10140701_78_dialog_content = "기다려! 금방 갈게!",
  ui_story_1014_10140701_79_dialog_content = "캬악!",
  ui_story_1014_10140701_80_dialog_content = "으... 왜 여기저기 다 있는 거야?!",
  ui_story_1014_10140701_81_dialog_content = "PlayerName, 적이 어디 있는지 감응해 줄 수 있을까?",
  ui_story_1014_10140701_82_dialog_content = "다들 어디서 오는 건지 모르겠어...",
  ui_story_1014_10140701_83_dialog_content = "<size=45>전부! 빨리 피해!</size>",
  ui_story_1014_10140701_84_dialog_content = "피하라고? 어디로?",
  ui_story_1014_10140701_85_dialog_content = "어떻게 설명해야 할지 모르겠어... 하지만 여기서 멀면 멀수록 좋아!",
  ui_story_1014_10140701_86_dialog_content = "<color=#e8d9bb>쿵── 쿵──</color>",
  ui_story_1014_10140701_87_dialog_content = "<color=#e8d9bb>쿠우웅──!</color>",
  ui_story_1014_10140701_88_dialog_content = "와, 저 녀석 진짜 말도 안 되게 생겼잖아.",
  ui_story_1014_10140701_89_dialog_content = "거기서 멍하니 있지 마세요!",
  ui_story_1014_10140701_90_dialog_content = "<anim type=Shake><size=50>크오오!</size></anim>",
  ui_story_1014_10140701_91_dialog_content = "콜록, 콜록. 대형이 단번에 무너졌잖아... 다들 괜찮아?",
  ui_story_1014_10140701_92_dialog_content = "PlayerName한테 미리 경고를 들었으니까, 다들 가만히 당하진 않았을 거야.",
  ui_story_1014_10140701_93_dialog_content = "걱정되는 건 평민들 쪽이야.",
  ui_story_1014_10140701_94_dialog_content = "대형이 무너져서 암귀들의 공격에 노출돼 버렸어.",
  ui_story_1014_10140701_95_dialog_content = "그렇네! 가서 도와야 해!",
  ui_story_1014_10140701_96_dialog_content = "빠져나갈 틈이 있겠어?",
  ui_story_1014_10140701_97_dialog_content = "살려주세요!",
  ui_story_1014_10140701_98_dialog_content = "암귀야! 여기저기 다 암귀라고!",
  ui_story_1014_10140701_99_dialog_content = "우릴 구하러 온 사람들은? 다들 어디 간 거야?!",
  ui_story_1014_10140701_100_dialog_content = "다들 당황하지 마세요! 제 쪽으로 가까이 붙으세요! 제가 지켜드릴게요!",
  ui_story_1014_10140701_101_dialog_content = "PlayerName, 적은...",
  ui_story_1014_10140701_102_dialog_content = "지금은 사방이 다 적이야. 전장이 아수라장이 돼 버렸어!",
  ui_story_1014_10140701_103_dialog_content = "암귀들 때문에 시민들이 다 뿔뿔이 흩어져서 한곳으로 모을 수가 없어!",
  ui_story_1014_10140701_104_dialog_content = "그, 그럼 어떡해?",
  ui_story_1014_10140701_105_dialog_content = "지금 생각하고 있어, 생각하고 있는데...",
  ui_story_1014_10140701_106_dialog_content = "시민들 생각만 할 게 아니라, 우리 생각도 좀 하죠.",
  ui_story_1014_10140701_107_dialog_content = "저 녀석이 또 돌격해 올 텐데, 계속 암귀 무리들 속에 있다간 우리도 오래는 못 버텨요.",
  ui_story_1014_10140701_108_dialog_content = "맞는 말이야... 녀석이 또 왔어...",
  ui_story_1014_10140701_109_dialog_content = "잉겔, 뭔가 방법이 없을까? 평소에 제일 똑똑한 건 너잖아.",
  ui_story_1014_10140701_110_dialog_content = "저 시민들은 포기하고, 기사단의 방어선으로 후퇴하면 됩니다.",
  ui_story_1014_10140701_111_dialog_content = "뭐? 하지만...",
  ui_story_1014_10140701_112_dialog_content = "레오 단장의 판단이 정확했습니다.\n여긴 변방이고, 우린 우리의 힘이 모자란단 사실을 인정해야 합니다.",
  ui_story_1014_10140701_113_dialog_content = "우리가 계속 암귀들과 맞서 싸운다고 해도,\n저 시민들은 이 난리 통에 하나씩 목숨을 잃게 될 겁니다.",
  ui_story_1014_10140701_114_dialog_content = "우리가 모든 사람을 구할 순 없습니다.",
  ui_story_1014_10140701_115_dialog_content = "......",
  ui_story_1014_10140701_116_dialog_content = "우린 최선을 다했습니다, PlayerName.\n당신도 지금 전장이 어떤 상황인지 확실히 알아야 합니다.",
  ui_story_1014_10140701_117_dialog_content = "<color=#e8d9bb>쿠르릉...</color>",
  ui_story_1014_10140701_118_dialog_content = "멀리서 울려 퍼지는 저 소리 들었죠? 아까 그 괴물이 곧 다시 나타날 거예요.",
  ui_story_1014_10140701_119_dialog_content = "우, 우린...",
  ui_story_1014_10140701_120_dialog_content = "당신이 결정을 못 내리겠다면, 제가 당신을 데려가겠습니다.",
  ui_story_1014_10140701_121_dialog_content = "!!!",
  ui_story_1014_10140701_122_dialog_content = "백야성의 아가씨, 엄호를 부탁합니다. 이제 후퇴하죠.",
  ui_story_1014_10140701_123_dialog_content = "하지만...",
  ui_story_1014_10140701_124_dialog_content = "저 사람들한테 내가 지켜주겠다고, 내가 지켜줄 거라고 약속했단 말이야...",
  ui_story_1014_10140701_125_dialog_content = "그렇다면 지키지 못한 약속을 양분으로 삼아 앞으로 성장해 나가면 됩니다.",
  ui_story_1014_10140701_126_dialog_content = "<color=#e8d9bb>쿠르릉...</color>",
  ui_story_1014_10140701_127_dialog_content = "미안, 그래도 한번 해 보고 싶어. 내가 한 약속을 그렇게 쉽게 저버릴 순 없어.",
  ui_story_1014_10140701_128_dialog_content = "왜냐하면 난 스스로를 기사라 부르기로 했으니까.",
  ui_story_1014_10140701_129_dialog_content = "당신...",
  ui_story_1014_10140701_130_dialog_content = "베르타!",
  ui_story_1014_10140701_131_dialog_content = "자칭 기사여. 당신을 그토록 거룩하고 순수하게 만들어 준 그 호칭에 감사를 표할게요.",
  ui_story_1014_10140701_132_dialog_content = "어라?",
  ui_story_1014_10140701_133_dialog_content = "크오오──!",
  ui_story_1014_10140701_134_dialog_content = "루미나틱스가 놈을 밀어냈어! 저건...",
  ui_story_1014_10140701_135_dialog_content = "당신 같은 기사는 처음 보는군요.",
  ui_story_1014_10140701_136_dialog_content = "그, 그래? 난 그냥 기사가 해야 할 일을 한 건데...",
  ui_story_1014_10140701_137_dialog_content = "그래도 다른 기사들은 당신과 달라요.",
  ui_story_1014_10140701_138_dialog_content = "당신 엄청 예쁘네. 혹시 천사야?",
  ui_story_1014_10140701_139_dialog_content = "저도 천사를 간절히 만나고 싶었지만, 한 번도 강림해 주질 않더군요.",
  ui_story_1014_10140701_140_dialog_content = "그래서 어떤 일들은 인간이 천사들을 대신해서 하는 수밖에 없는 거예요.",
  ui_story_1014_10140701_141_dialog_content = "여러분, 빛을 따라 제 곁으로 오세요.",
  ui_story_1014_10140701_142_dialog_content = "만물은 백야 아래에.\n광명이 사악하고 더러운 것들을 몰아내고, 모두를 귀로로 안내할 거예요.",
  ui_story_1014_10140701_143_dialog_content = "저기 좀 봐요! 암귀들이 저쪽에 있는 빛을 두려워하는 것 같아요!",
  ui_story_1014_10140701_144_dialog_content = "어, 얼른 저쪽으로 가자! 저쪽에 가면 살 수 있어!",
  ui_story_1014_10140701_145_dialog_content = "들어 본 적 있어! 분명 그 사람일 거야! 더스크 타운의 성녀 말이야!",
  ui_story_1014_10140701_146_dialog_content = "대단해! 시민들이 다시 모이고 있어!",
  ui_story_1014_10140701_147_dialog_content = "암귀들이 저 여자애한테서 나는 빛을 피하고 있으니까,\n따라가면 안전하게 후퇴할 수 있을 거야!",
  ui_story_1014_10140701_148_dialog_content = "음, 당신 말이 맞군요. 전략을 조정하죠.\n저 신비한 소녀를 둘러싸고, 전력을 다해 주변의 시민들을 지키며 후퇴합시다.",
  ui_story_1014_10140701_149_dialog_content = "네, 잉겔 중령님!",
  ui_story_1014_10140701_150_dialog_content = "당신은 그렇게 부르지 마세요.",
  ui_story_1014_10140701_151_dialog_content = "단장님! 저들이 시민들을 데리고 돌아왔습니다!",
  ui_story_1014_10140701_152_dialog_content = "나도 봤다. 대형의 측면을 열어 저들이 후방으로 후퇴할 수 있도록 해줘.",
  ui_story_1014_10140701_153_dialog_content = "예!",
  ui_story_1014_10140701_154_dialog_content = "강철가시 기사단이야! 살았어! 여기까지 왔으니까 이젠 안전할 거야!",
  ui_story_1014_10140701_155_dialog_content = "얼른 가자. 더스크 타운으로 들어가야지.\n허허벌판인 여기 있으면 어떻게 안심하겠어.",
  ui_story_1014_10140701_156_dialog_content = "수고 많았어요, 레오 단장님.",
  ui_story_1014_10140701_157_dialog_content = "<color=#FFB400>성녀님</color>, 절 놀리시는 겁니까?",
  ui_story_1014_10140701_158_dialog_content = "당연히 아니에요. 전 그렇게 유치한 사람이 아니랍니다.\n단장님의 처지에 대해서도 잘 알고 있어요.",
  ui_story_1014_10140701_159_dialog_content = "난민들이 계속 더스크 타운으로 피난을 오고 있고,\n도시는 지금 입구에 구멍이 났다고 해도 과언이 아닌 상태예요.",
  ui_story_1014_10140701_160_dialog_content = "기사단이 암귀를 놓치면 곧바로 더스크 타운 내부로 들어오게 되겠죠.\n그러니 기사단은 방어선에서 단 한 걸음도 이탈해선 안 돼요.",
  ui_story_1014_10140701_161_dialog_content = "책임을 덜어내 주셔서 감사합니다. 마음이 한결 편하군요.",
  ui_story_1014_10140701_162_dialog_content = "「편하다」곤 할 수 없는 표정이시네요.\n저번에 제게 말했던 「존엄성의 문제」 때문인가요?",
  ui_story_1014_10140701_163_dialog_content = "그렇지는 않습니다. 전 그저 부러울 뿐입니다.\n성녀님께서는 제가 할 수 없는 일을 편한 대로 하실 수 있으니까요.",
  ui_story_1014_10140701_164_dialog_content = "그럼 이젠 입장을 바꿔서 저는 할 수 없는 일을 단장님이 해 주셔야겠어요.",
  ui_story_1014_10140701_165_dialog_content = "물론입니다. 전장은 저희에게 맡기시고, 성녀님께선 시민들을 데리고 후퇴하시죠.",
  ui_story_1014_10140701_166_dialog_content = "암귀는 단 한 마리라도 강철가시 기사단의 방어선을 넘을 수 없을 겁니다.",
  ui_story_1014_10140701_167_dialog_content = "단장님을 믿어요.",
  ui_story_1014_10140701_168_dialog_content = "짧은 대화는 여기서 마무리 짓도록 하고, 어서 가시죠.",
  ui_story_1014_10140701_169_dialog_content = "왠지 성녀님과 전 항상 이렇게 전장에서 스쳐 지나갈 뿐인 것 같군요.",
  ui_story_1014_10140701_170_dialog_content = "네, 항상 그렇네요.",
  ui_story_1014_10140701_171_dialog_content = "서로 가고자 하는 방향이 달라서겠죠.",
  ui_story_1014_10140701_172_dialog_content = "아까 그 커다란 녀석이 점점 가까이 다가오고 있군. 녀석의 소리가 들려.",
  ui_story_1014_10140701_173_dialog_content = "강철가시 기사단 일동! 대형을 갖출 준비를 해라!\n저 커다란 녀석과 제대로 붙어 보고 싶은 사람 있나?",
  ui_story_1014_10140701_174_dialog_content = "<size=40>있습니다!</size>",
  ui_story_1014_10140701_175_dialog_content = "<size=40>우리도!</size>",
  ui_story_1014_10140701_176_dialog_content = "당신들도 나설 생각이야? 싸울 체력은 남아 있나?",
  ui_story_1014_10140701_177_dialog_content = "물론이지! 아까 저 녀석한테 진 빚을 제대로 갚아 줘야겠어!",
  ui_story_1014_10140701_178_dialog_content = "하하하하, 좋다! 좋은 기백이야!",
  ui_story_1014_10140701_179_dialog_content = "당신들이 힘을 보태 준다면, 이번 전투의 목표는 방어로 그치지 않겠어.",
  ui_story_1014_10140701_180_dialog_content = "오늘 밤, 녀석의 뿔을 뽑아 기사단의 깃발을 거는 거다!",
  ui_story_1014_10140702_1_dialog_content = "<anim type=Shake><size=45>크르르! 크에에엑!</size></anim>",
  ui_story_1014_10140702_2_dialog_content = "이제 쉬어라, 커다란 녀석.",
  ui_story_1014_10140702_3_dialog_content = "휴... 드디어 쓰러트렸네. 생명력이 참 질긴 녀석이었어.",
  ui_story_1014_10140702_4_dialog_content = "긴장을 풀어선 안 돼. 암귀의 공세는 아직 끝나지 않았어. 우린 마지막까지 버텨야 해.",
  ui_story_1014_10140702_5_dialog_content = "물론이지! 그래도 이젠 부담이 훨씬 줄어들었잖아.",
  ui_story_1014_10140702_6_dialog_content = "휴, 어떻게든 암귀 무리에서 탈출했네.",
  ui_story_1014_10140702_7_dialog_content = "래비드후프는? 그 녀석은 어디 갔어?",
  ui_story_1014_10140702_8_dialog_content = "......",
  ui_story_1014_10140702_9_dialog_content = "정말 감사합니다! 감사해요, 성녀님!",
  ui_story_1014_10140702_10_dialog_content = "성녀님께서 저희 모두의 목숨을 구해주셨어요!",
  ui_story_1014_10140702_11_dialog_content = "어머, 다들 절 그렇게 부르진 말아 주세요.",
  ui_story_1014_10140702_12_dialog_content = "제 이름은 <color=#FFB400>조셀린</color>이에요. 만약 앞으로 더스크 타운에서 지내실 거라면,\n여러분은 모두 제 이웃이에요.",
  ui_story_1014_10140702_13_dialog_content = "아, 그럼 이제 어떡하죠...",
  ui_story_1014_10140702_14_dialog_content = "일단은 더스크 타운에서 지내는 수밖에.\n여긴 백야성이랑 일루미나의 부대가 있으니까 어쨌든 안전하겠지.",
  ui_story_1014_10140702_15_dialog_content = "다른 곳으로 간다고 해도, 언제 또 암귀들의 습격을 받게 될지도 모르는 일이잖아.",
  ui_story_1014_10140702_16_dialog_content = "맞아. 이제 피난 다니는 건 지긋지긋해. 생각도 하기 삻어.",
  ui_story_1014_10140702_17_dialog_content = "여러 일들을 겪어서 녹초가 되셨을 것 같으니, 우선 모두 도시 안으로 들어가도록 해요.",
  ui_story_1014_10140702_18_dialog_content = "오늘 더스크 타운에는 다른 피난민들도 와 있어요.\n주민들은 지금 피난민들의 정착을 돕고 있답니다.",
  ui_story_1014_10140702_19_dialog_content = "밤엔 쉴 방을 준비해 드릴 테니 모두 푹 쉬도록 해요.",
  ui_story_1014_10140702_20_dialog_content = "앞으로의 일은 내일 아침에 다시 천천히, 신중하게 논의하기로 해요.",
  ui_story_1014_10140702_21_dialog_content = "네, 그럴게요. 이렇게 세세하게 신경 써 주셔서 정말 너무 감사해요.",
  ui_story_1014_10140702_22_dialog_content = "더스크 타운에선 자주 있는 일인걸요.",
  ui_story_1014_10140702_23_dialog_content = "더스크 타운 주민들은 대부분 근처에서 여기로 피신해 온 피난민들이에요.\n그러니 여러분이 어떤 상황을 겪고 있는지 제일 잘 이해하고 있어요.",
  ui_story_1014_10140702_24_dialog_content = "저희가 할 수 있는 일들은 그저 작은 도움에 불과해요.\n부디 여러분이 더스크 타운에서 새로운 터전을 가질 수 있었으면 좋겠네요.",
  ui_story_1014_10140702_25_dialog_content = "새로운 터전이라... 좋습니다!",
  ui_story_1014_10140702_26_dialog_content = "그럼 시간이 늦었으니 어서 도시 안으로 들어가죠.",
  ui_story_1014_10140702_27_dialog_content = "예! 그럼 자리를 잡고 나면 꼭 감사 인사를 드리러 가겠습니다, 성녀님!",
  ui_story_1014_10140702_28_dialog_content = "아이, 참. 그냥 조셀린이라고 부르시라니까요.",
  ui_story_1014_10140702_29_dialog_content = "만물은 백야 아래에! 시간이 나면 교회로 찾아뵈러 가겠습니다!",
  ui_story_1014_10140702_30_dialog_content = "거기로 가시면 절 못 만나실 거예요. 전 교회 소속이 아니거든요.",
  ui_story_1014_10140702_31_dialog_content = "네? 교회의 일원이 아니신 건가요?",
  ui_story_1014_10140702_32_dialog_content = "네, 저도 여러분처럼 그저 평범한 사람일 뿐이에요.",
  ui_story_1014_10140702_33_dialog_content = "그러니 절 만나고 싶으실 땐 시장으로 오세요. 자주 가서 물건을 사고팔거든요.",
  ui_story_1014_10140702_34_dialog_content = "좋습니다! 기억해 두겠습니다!",
  ui_story_1014_10140702_35_dialog_content = "성녀님! 그럼 다음에 또 뵙겠습니다!",
  ui_story_1014_10140702_36_dialog_content = "조셀린이라니까요...",
  ui_story_1014_10140702_37_dialog_content = "어머, 이 소리...",
  ui_story_1014_10140702_38_dialog_content = "기사단이 돌아온 모양이네요.",
  ui_story_1014_10140702_39_dialog_content = "<color=#e8d9bb>다그닥, 다그닥, 다그닥...</color>",
  ui_story_1014_10140702_40_dialog_content = "그러니까 카렌 전하께선 순시를 하러 오신 거였군요.",
  ui_story_1014_10140702_41_dialog_content = "그래. 백야성과 더스크 타운은 꽤 오랜 시간 정보 교류가 없었으니까.",
  ui_story_1014_10140702_42_dialog_content = "그런 사소한 일 때문에 카렌 전하를 파견했다는 건 너무 거창한 처사인 것 같군요.",
  ui_story_1014_10140702_43_dialog_content = "이곳의 대략적인 상황이 어떤지는 이미 보셔서 아시겠지요.\n전투는 무척 힘겹긴 하지만, 그래도 나름대로 안정을 유지하는 중입니다.",
  ui_story_1014_10140702_44_dialog_content = "백야성 세력은 「백야 요새」에 집중돼 있습니다.\n그곳은 더스크 타운의 에너지 코어를 장악하고 있기 때문에 방어 역량이 충분합니다.",
  ui_story_1014_10140702_45_dialog_content = "시간이 나신다면 한 번 가 보셔도 좋을 겁니다.",
  ui_story_1014_10140702_46_dialog_content = "알겠어, 그럴게.",
  ui_story_1014_10140702_47_dialog_content = "이 앞이 바로 더스크 타운입니다.",
  ui_story_1014_10140702_48_dialog_content = "보아하니 마중을 나온 사람이 있군요.",
  ui_story_1014_10140702_49_dialog_content = "어, 저 사람... 아까 전장에 있던 그 여자애잖아?!",
  ui_story_1014_10140702_50_dialog_content = "사람들이 「더스크 타운의 성녀」라고 부르던 것 같은데.",
  ui_story_1014_10140702_51_dialog_content = "부디 그 호칭은 잊어 주세요. 제 이름은 조셀린이에요.",
  ui_story_1014_10140702_52_dialog_content = "여러분 모두가 전장에서 보여준 용감하고 영웅적인 행동들은 정말 감명 깊었어요.",
  ui_story_1014_10140702_53_dialog_content = "승리를 거두고 돌아오는 전사들을 더스크 타운의 주민들 대신 제가 맞이하러 왔답니다.",
  ui_story_1014_10140702_54_dialog_content = "감명은 무슨, 오히려 네가 보여준 행동이 더 감명 깊었는걸.",
  ui_story_1014_10140702_55_dialog_content = "맞아. 쏟아지는 빛을 맞고 있던 모습은 정말 말이 안 나올 정도였어.",
  ui_story_1014_10140702_56_dialog_content = "도움을 받은 시민들은 나보다 훨씬 더 강렬한 느낌을 받았을 거야.",
  ui_story_1014_10140702_57_dialog_content = "마치 신의 사자가 직접 강림한 것 같았으니까...",
  ui_story_1014_10140702_58_dialog_content = "자꾸 그러시니까 정말 어쩔 줄을 모르겠네요.",
  ui_story_1014_10140702_59_dialog_content = "백야성에서 멀리 떨어진 이곳에서 그렇게 순수한 루미나를\n볼 수 있을 줄은 생각 못 했어.",
  ui_story_1014_10140702_60_dialog_content = "난 변방 지역의 교회들은 잘 알지 못해. 당신은 어느 교회 소속이지?",
  ui_story_1014_10140702_61_dialog_content = "옷차림이... 내가 아는 수녀들의 모습과는 조금 다르기도 하고.",
  ui_story_1014_10140702_62_dialog_content = "아, 다들 그렇다고 하더군요.",
  ui_story_1014_10140702_63_dialog_content = "미안해요. 전 교회 소속이 아니에요.",
  ui_story_1014_10140702_64_dialog_content = "으음? 그럼 설마 일루미나의 병사인가?",
  ui_story_1014_10140702_65_dialog_content = "일루미나의 병사는 저런 복장을 안 합니다.",
  ui_story_1014_10140702_66_dialog_content = "이곳은 변방입니다. 모든 이가 백야성 또는 일루미나에 속해야 할 필요는 없죠.\n병사들만이 싸울 수 있는 것 또한 아닙니다.",
  ui_story_1014_10140702_67_dialog_content = "이분의 정확한 신분을 말씀드리자면, 「토마토 판매상」이라고 할 수 있겠군요.",
  ui_story_1014_10140702_68_dialog_content = "?!",
  ui_story_1014_10140702_69_dialog_content = "뜨개질 일도 아직 하고 있다는 걸 잊지 말아 주셨으면 좋겠네요.",
  ui_story_1014_10140702_70_dialog_content = "단장님은 제가 파는 토마토를 한 번도 사 주시지 않았지만,\n전 기사단 깃발을 벌써 두 번이나 고쳐 드렸잖아요.",
  ui_story_1014_10140702_71_dialog_content = "미안합니다. 토마토 판매에 보탬이 되어 주고 싶지만,\n토마토는 기사들이 먹는 음식이 아니라서요.",
  ui_story_1014_10140702_72_dialog_content = "기사들이여, 모름지기 기사란 무엇을 먹어야 하지?",
  ui_story_1014_10140702_73_dialog_content = "고기입니다! 당연히 고기 아니겠습니까!",
  ui_story_1014_10140702_74_dialog_content = "양다리살에 소금을 뿌려 구워 먹으면 그것보다 끝내주는 게 어디 있겠습니까!",
  ui_story_1014_10140702_75_dialog_content = "휴, 여러분의 입맛 수준이 하루라도 빨리 여러분의 전투 솜씨를 따라잡았으면 좋겠네요.",
  ui_story_1014_10140702_76_dialog_content = "참, 기사단 분들 말고 다른 분들은 외지인이시죠? 오늘 처음 뵙네요.",
  ui_story_1014_10140702_77_dialog_content = "응, 우린 동쪽의 자난성에서 오늘 막 여기 왔어.",
  ui_story_1014_10140702_78_dialog_content = "자난성이라... 정말 먼 곳에서 오셨군요. 전 지도에서밖에 본 적 없는 곳인걸요.",
  ui_story_1014_10140702_79_dialog_content = "여러분은 당분간 더스크 타운에 머물 예정이신가요?",
  ui_story_1014_10140702_80_dialog_content = "응, 여기서 처리할 일이 있거든.",
  ui_story_1014_10140702_81_dialog_content = "그럼 절 따라오세요. 여러분이 머물 곳을 준비해 드릴게요.",
  ui_story_1014_10140702_82_dialog_content = "번거롭지 않으시다면 여러분께 더스크 타운의 특색 먹거리도 대접해 드리고 싶어요.",
  ui_story_1014_10140702_83_dialog_content = "영웅처럼 용감하게 암귀와 맞서 싸워 주신 여러분께 드리는\n작은 보답이라고 생각해 주세요.",
  ui_story_1014_10140702_84_dialog_content = "뭐? 그, 그렇게까지 신경 써 줄 필요는 없는데...",
  ui_story_1014_10140702_85_dialog_content = "더스크 타운에 손님이 찾아오는 일은 무척 드물어요.\n게다가 여러분은 조금 전에 이 도시를 위해 싸워 주셨는걸요.",
  ui_story_1014_10140702_86_dialog_content = "조셀린이 초대하지 않았다면, 제가 여러분께 저녁 식사를 대접하려던 참이었습니다.",
  ui_story_1014_10140702_87_dialog_content = "근데 성녀님께서 기꺼이 사비를 내시겠다니, 이 얼마나 기쁜 일입니까.\n그러니 여러분도 받아 주세요.",
  ui_story_1014_10140702_88_dialog_content = "그렇구나. 다들 어떻게 생각해?",
  ui_story_1014_10140702_89_dialog_content = "저런 말까지 듣고도 성의를 거절한다면, 우리가 너무 야속한 것 같잖아.",
  ui_story_1014_10140702_90_dialog_content = "맞아! 더스크 타운엔 어떤 맛있는 음식들이 있을까? 너무 기대돼!",
  ui_story_1014_10140702_91_dialog_content = "전 이 도시에 있는 크고 작은 가게들을 꽤 잘 알고 있거든요.\n여러분도 만족하실 수 있을 거예요.",
  ui_story_1014_10140702_92_dialog_content = "레오 단장님도 이번 전투 때문에 힘드셨을 텐데, 같이 식사하지 않으시겠어요?",
  ui_story_1014_10140702_93_dialog_content = "절 초대하시는 겁니까? 아니면 강철가시 기사단을 초대하시는 겁니까?",
  ui_story_1014_10140702_94_dialog_content = "제가 가려는 식당에 기사단 모두가 들어가려면 아마 자리가 모자랄 텐데요.",
  ui_story_1014_10140702_95_dialog_content = "사람 차별하시면 섭섭합니다, 성녀님!",
  ui_story_1014_10140702_96_dialog_content = "저희도 더스크 타운을 위해 피 튀기게 열심히 싸우지 않았습니까?",
  ui_story_1014_10140702_97_dialog_content = "자, 자, 다들 됐어. 기사단을 굶길 리가 없잖아.",
  ui_story_1014_10140702_98_dialog_content = "오늘 전투 뒤풀이는 내 돈으로 가서 마음껏 먹어.",
  ui_story_1014_10140702_99_dialog_content = "<size=45>오오오! 좋았어!</size>",
  ui_story_1014_10140702_100_dialog_content = "그럼 난 이쪽 일행과 갈게. 모처럼 조셀린 양이 초대해 주셨으니까.",
  ui_story_1014_10140702_101_dialog_content = "그리고 멀리서 온 새 친구들도 섭섭하게 대할 순 없잖아.",
  ui_story_1014_10140702_102_dialog_content = "겸사겸사 고급스러운 「입맛」이 뭔지도 좀 봐 두자고.",
  ui_story_1014_10140801_1_dialog_content = "밤에 자려면 베개랑 이불이랑 옷이 필요한데...",
  ui_story_1014_10140801_2_dialog_content = "휴, 아무것도 안 가지고 왔네요.",
  ui_story_1014_10140801_3_dialog_content = "도망쳐 오기도 바빴는데 짐 챙길 시간이 어디 있었겠어.",
  ui_story_1014_10140801_4_dialog_content = "난 돈도 못 챙겨 와서 이제부턴 끼니 걱정까지 해야 해.",
  ui_story_1014_10140801_5_dialog_content = "사람들이 그러는데 저쪽에 가면 일용품을 빌릴 수 있다는데?",
  ui_story_1014_10140801_6_dialog_content = "다들 같이 가 보자고!",
  ui_story_1014_10140801_7_dialog_content = "길거리에 난민들이 정말 많네.",
  ui_story_1014_10140801_8_dialog_content = "다들 오늘 피난 온 사람들이야?",
  ui_story_1014_10140801_9_dialog_content = "네, 더스크 타운에선 자주 있는 일이에요.",
  ui_story_1014_10140801_10_dialog_content = "자주?",
  ui_story_1014_10140801_11_dialog_content = "더스크 타운엔 백야성과 일루미나의 주둔군이 있지만,\n도시 바깥 쪽 지역은 그 어떤 세력의 관할도 아니거든요.",
  ui_story_1014_10140801_12_dialog_content = "도시 근처에 흩어져 있는 작은 마을들은 평소엔 자급자족하며\n자유롭고 편하게 지내고 있죠.",
  ui_story_1014_10140801_13_dialog_content = "하지만 오로라가 뒤죽박죽이 돼서 암귀들이 공격해 오면,\n습격을 받은 작은 마을들은 자신들을 지킬 수단이 거의 없어요.",
  ui_story_1014_10140801_14_dialog_content = "마을 사람들도 하는 수 없이 자신들의 터전을 뒤로한 채,\n보호를 바라면서 주둔군 근처로 찾아오는 거예요.",
  ui_story_1014_10140801_15_dialog_content = "마치 모래알들이 광풍에 휘날려 날아올랐다가, 같은 피난처에 내려앉은 느낌이랄까요.",
  ui_story_1014_10140801_16_dialog_content = "그리고 그런 모래알들이 모여서 흙더미가 되듯이,\n피난민들이 뿌리를 내려 더스크 타운을 세운 거예요.",
  ui_story_1014_10140801_17_dialog_content = "그랬구나...",
  ui_story_1014_10140801_18_dialog_content = "근데 왜 다들 더 안전한 곳으로 이주하지 않은 거야?",
  ui_story_1014_10140801_19_dialog_content = "동쪽 중앙에 위치한 백야성이나 자난성을 말하는 건가요?",
  ui_story_1014_10140801_20_dialog_content = "다들 물론 가고 싶어 하죠. 그렇지만 현실의 삶이란 무척 잔혹하답니다.\n원하는 일이 뭐든 그렇게 쉽게 이루어지진 않아요.",
  ui_story_1014_10140801_21_dialog_content = "먼 곳으로 이주하게 된다면 뭘 하면서 생계를 유지할 수 있죠?\n그리고 어디에 살아야 할까요?",
  ui_story_1014_10140801_22_dialog_content = "태어나면서 아무런 곳에도 소속되지 않은 주민들에게\n머물 땅과 집을 제공해 주려는 세력은 없어요.",
  ui_story_1014_10140801_23_dialog_content = "오로라 유적은 암귀라는 위험이 도사리고 있긴 하지만,\n땅이 비옥해서 최소한 먹고 입을 걱정은 없어요.",
  ui_story_1014_10140801_24_dialog_content = "다들 뿌리 없는 잡초처럼 떠돌아다녀야 하는 것보단\n비바람에 시달리는 게 차라리 낫다고 믿어요.",
  ui_story_1014_10140801_25_dialog_content = "아, 미안. 내가 너무 단순하게 생각한 것 같아.",
  ui_story_1014_10140801_26_dialog_content = "후훗, 괜찮아요. 보통은 아무도 이런 일에 신경 쓰지 않거든요.",
  ui_story_1014_10140801_27_dialog_content = "아마 지금까지 여러분이 봐 왔던 곳들과는 다를 테니,\n놀랍고 이상하다는 느낌을 받는 건 당연한 거예요.",
  ui_story_1014_10140801_28_dialog_content = "맞아, 너무 다른 것 같아. 시민들이 아무런 통제도 받지 않고,\n백야성이랑 일루미나가 한 도시에 공존하고 있잖아.",
  ui_story_1014_10140801_29_dialog_content = "공존이라고는 해도 서로 왕래하는 일은 거의 없어요.",
  ui_story_1014_10140801_30_dialog_content = "마침 당사자가 오셨네요. 직접 물어보면 되겠어요.",
  ui_story_1014_10140801_31_dialog_content = "백야성과 일루미나의 공존 말이지?\n내가 어릴 적 더스크 타운에 왔을 때부터 이런 상태였어.",
  ui_story_1014_10140801_32_dialog_content = "어른들은 역사적으로 남아 있는 문제들이 이것저것 있어서 그렇다고들 하더라고.",
  ui_story_1014_10140801_33_dialog_content = "윗분들께선 오로라 유적이란 지역 간의 경계 지역을 지키고 싶어해.\n하지만 그것뿐이고 다른 명령은 없어.",
  ui_story_1014_10140801_34_dialog_content = "오로라 유적은 백야성에게도, 일루미나에게도 자신이 갖기엔 별로지만,\n남 주기엔 아까운 변방 지역이야.",
  ui_story_1014_10140801_35_dialog_content = "상층부에서는 귀찮아서 별 간섭을 안 하니까, 양측의 병사들도 불필요하게\n주의를 기울일 필요가 많이 줄었어.",
  ui_story_1014_10140801_36_dialog_content = "오로라 유적 근처의 땅들은 아직 비옥한 편이지만, 에너지는 희박한 편이고,\n대체로 더스크 타운 주변에 집중돼 있어.",
  ui_story_1014_10140801_37_dialog_content = "그래서 양측은 서로의 에너지 소모량을 유지하기 위해,\n도시 내부에 함께 주둔하기로 협약을 맺었어.",
  ui_story_1014_10140801_38_dialog_content = "같은 곳에 주둔하면서 같은 에너지를 쓰면 서로 갈등이 발생하지 않아?",
  ui_story_1014_10140801_39_dialog_content = "암귀를 상대하는 것만으로도 힘이 다 빠져서, 내부의 갈등을 일으킬 기력조차 없거든.",
  ui_story_1014_10140801_40_dialog_content = "게다가 변방의 가장 큰 과제는 영원히 「생존」이야.",
  ui_story_1014_10140801_41_dialog_content = "중요한 게 뭔지, 급한 게 뭔지 제대로 파악하지 못하는 녀석들은 전장에서 교훈을 얻게 되지.",
  ui_story_1014_10140801_42_dialog_content = "그랬구나.",
  ui_story_1014_10140801_43_dialog_content = "역사책에서 봤던 오로리안 연합군이 생각났어.",
  ui_story_1014_10140801_44_dialog_content = "강력한 외부의 적을 앞에 두고, 세력 간의 갈등은 대수롭지 않은 게 됐었잖아.",
  ui_story_1014_10140801_45_dialog_content = "<color=#e8d9bb>치이익──</color>",
  ui_story_1014_10140801_46_dialog_content = "<anim type=Shake>흐──아암.</anim>",
  ui_story_1014_10140801_47_dialog_content = "악셀리아! 일어났구나!",
  ui_story_1014_10140801_48_dialog_content = "좋은 아침입니다, PlayerName.",
  ui_story_1014_10140801_49_dialog_content = "지금은 아침이 아닌걸...",
  ui_story_1014_10140801_50_dialog_content = "어머? 이렇게 귀여운 소녀를 숨겨 두고 있었던 건가요?",
  ui_story_1014_10140801_51_dialog_content = "제 외형은 그렇게 눈여겨볼 부분이 아닙니다. 외형은 가장 시시한 부분입니다.",
  ui_story_1014_10140801_52_dialog_content = "배가 고픕니다.",
  ui_story_1014_10140801_53_dialog_content = "마침 잘됐네요! 식당에 도착했거든요.",
  ui_story_1014_10140801_54_dialog_content = "당신은 뭘 좋아하죠?",
  ui_story_1014_10140801_55_dialog_content = "사탕이 좋습니다.",
  ui_story_1014_10140801_56_dialog_content = "자, 페이스트리, 에그타르트, 슈크림이랑 생크림 케이크야.",
  ui_story_1014_10140801_57_dialog_content = "음, 무척 뛰어난 솜씨입니다.",
  ui_story_1014_10140801_58_dialog_content = "조셀린, 디저트를 이렇게 많이 먹어도 괜찮은 건가?",
  ui_story_1014_10140801_59_dialog_content = "전혀 문제없어요. 가끔 한 번 이렇게 먹는 건 살도 안 쪄요.",
  ui_story_1014_10140801_60_dialog_content = "오늘 데려온 손님들은 못 보던 얼굴들이 많군.",
  ui_story_1014_10140801_61_dialog_content = "네, 이쪽에 있는 사람들은 자난성에서 먼 길을 와 준 손님들이에요.",
  ui_story_1014_10140801_62_dialog_content = "자난성이라, 옆집 아저씨가 가 본 적이 있다고 하던데.\n아주 꽉 막힌 곳이라고 하더라고. 아, 내가 말실수를 했네.",
  ui_story_1014_10140801_63_dialog_content = "꽈, 꽉 막혀요? 그 정도는 아닌데요...",
  ui_story_1014_10140801_64_dialog_content = "이 사람들 말고 우리 현지 주둔군의 전사들도 왔어요.",
  ui_story_1014_10140801_65_dialog_content = "일루미나의 젊은 장교 숀, 백야성 강철가시 기사단의 레오 단장님이에요.",
  ui_story_1014_10140801_66_dialog_content = "네! 더스크 타운 주둔군, 숀 소위입니다!",
  ui_story_1014_10140801_67_dialog_content = "이봐, 여긴 일루미나의 식당이 아니니까 나한테 경례하지 마.",
  ui_story_1014_10140801_68_dialog_content = "하하하, 우리 일루미나 친구 반응은 매번 참 재미있다니까.",
  ui_story_1014_10140801_69_dialog_content = "사장님, 이 가게 바비큐는 맛이 참 좋군요.",
  ui_story_1014_10140801_70_dialog_content = "다음엔 우리 기사단 형제들도 데려와서 맛을 보여 줘야겠습니다!",
  ui_story_1014_10140801_71_dialog_content = "휴, 정말 어딜 가나 매번 고기밖에 안 드시네요.",
  ui_story_1014_10140801_72_dialog_content = "가게라는 건 말이야. 요리 솜씨가 뒷받침되지 않으면 버티질 못해.",
  ui_story_1014_10140801_73_dialog_content = "다른 점원은 안 보이는데, 이렇게 큰 가게를 당신 혼자서 운영하는 겁니까?",
  ui_story_1014_10140801_74_dialog_content = "그래, 나 혼자야.",
  ui_story_1014_10140801_75_dialog_content = "혼자선 요리도 하랴 서빙도 하랴 힘들지 않나요?\n이 정도 솜씨라면 점원을 몇 명 고용해서 사업 규모를 늘려도 될 것 같은데요.",
  ui_story_1014_10140801_76_dialog_content = "관심 없어. 혼자서 하는 편이 조용해서 좋아.",
  ui_story_1014_10140801_77_dialog_content = "처음엔 친형제랑 같이 장사를 했었는데, 둘이 허구한 날 싸워서 짜증만 났었지.",
  ui_story_1014_10140801_78_dialog_content = "사장님한테 형제가 있단 얘긴 오늘 처음 듣는걸요.",
  ui_story_1014_10140801_79_dialog_content = "그럴 거야. 걘 3년 전에 죽었거든.",
  ui_story_1014_10140801_80_dialog_content = "둘이 같이 더스크 타운으로 피난 오는 길에, 암귀 손에 죽어 버렸어.",
  ui_story_1014_10140801_81_dialog_content = "아...",
  ui_story_1014_10140801_82_dialog_content = "걘 다리가 불편해서 피난민 무리의 맨 뒤쪽에 뒤처져 있었거든.",
  ui_story_1014_10140801_83_dialog_content = "암귀들이 뒤쫓아왔을 때, 백야성의 기사단은 제때 도착하긴 했지만, 걜 구해주진 않았지.",
  ui_story_1014_10140801_84_dialog_content = "......",
  ui_story_1014_10140801_85_dialog_content = "(기사단...)",
  ui_story_1014_10140801_86_dialog_content = "그 기사단을 증오하진 않아. 적어도 내 목숨은 구해줬으니까.",
  ui_story_1014_10140801_87_dialog_content = "여기선 목숨이 값지지 않아. 그래서 목숨을 가지고 흥정을 할 여지조차 없지.",
  ui_story_1014_10140801_88_dialog_content = "누굴 구했든, 누굴 구하지 않았든 다 당연한 거야.",
  ui_story_1014_10140801_89_dialog_content = "사장님, 그런 말 마세요. 목숨은 누구에게나 똑같이 소중한 거예요.",
  ui_story_1014_10140801_90_dialog_content = "너라면 그렇게 생각할 것 같았어, 조셀린. 왜냐하면 넌 다른 사람과는 다르거든.",
  ui_story_1014_10140801_91_dialog_content = "넌 모두를 구하러 나서고, 모두가 이 세상에 신이 존재한다고 믿게 만들어 줘.",
  ui_story_1014_10140801_92_dialog_content = "하지만 더스크 타운의 평화를 지키는 건 제가 아니라, 여기 주둔하고 있는 병사들이에요.",
  ui_story_1014_10140801_93_dialog_content = "병사들이 모두의 목숨을 소중히 여기지 않는다면,\n더스크 타운이 어떻게 사람들의 피난처가 될 수 있었겠어요?",
  ui_story_1014_10140801_94_dialog_content = "생명은 소중한 거예요. 생명이란 위대함 앞에선 구원과 포기 모두 일개 선택지에 불과해요.",
  ui_story_1014_10140801_95_dialog_content = "그 병사들은 단지 사람들보다 먼저 어쩔 수 없는 선택을\n해야 하는 상황에 놓였을 뿐이에요.",
  ui_story_1014_10140801_96_dialog_content = "......",
  ui_story_1014_10140801_97_dialog_content = "사실 그 사람들은...",
  ui_story_1014_10140801_98_dialog_content = "조셀린, 앞에 놓여 있는 소시지구이 좀 이쪽으로 밀어줘요. 손이 안 닿네요.",
  ui_story_1014_10140801_99_dialog_content = "아, 네.",
  ui_story_1014_10140801_100_dialog_content = "그러고 보니, PlayerName. 아직 자세히 물어보질 못했네.\n더스크 타운엔 무슨 볼일 때문에 온 거지?",
  ui_story_1014_10140801_101_dialog_content = "(어라, 레오 단장이 화제를 바꿨잖아.)",
  ui_story_1014_10140801_102_dialog_content = "일루미나의 중령이 동행할 정도라면, 겉치레 치곤 상당하잖아.",
  ui_story_1014_10140801_103_dialog_content = "뭐, 비밀을 엄수해야 하는 임무라면 내 질문은 못 들은 셈 쳐 줘.",
  ui_story_1014_10140801_104_dialog_content = "아, 우린 콜로서스를 수리하러 온 거야.",
  ui_story_1014_10140801_105_dialog_content = "뭐?! 콜로서스를 가지고 있다니...",
  ui_story_1014_10140801_106_dialog_content = "아니지, 넌 아이테르니까 콜로서스가 있는 것도 당연하겠네.",
  ui_story_1014_10140801_107_dialog_content = "근데 수리를 해야 한다는 말은 콜로서스에 뭔가 문제가 생긴 건가?",
  ui_story_1014_10140801_108_dialog_content = "어떻게 설명하는 게 좋을지 생각 좀 해 볼게.\n그러니까 기능은 정상인데, 잠시 의식을 잃은 상태거든.",
  ui_story_1014_10140801_109_dialog_content = "「콜로서스가 의식을 잃었다」는 사실이 이해가 어려울 수도 있겠지만...",
  ui_story_1014_10140801_110_dialog_content = "음, 알겠어. 이해하기 어렵지 않아.",
  ui_story_1014_10140801_111_dialog_content = "과연 더스크 타운에 찾아올 만하네.\n여기 있는 일루미나 연구원을 만나려는 거겠지?",
  ui_story_1014_10140801_112_dialog_content = "뭐? 어떻게 알았어?",
  ui_story_1014_10140801_113_dialog_content = "콜로서스 연구에 대해선 잘 모르지만, 콜로서스에 대한 이야기라면 조금 알고 있어.",
  ui_story_1014_10140801_114_dialog_content = "더스크 타운의 시민들은 거의 다 그 이야기를 알고 있다고 해도 과언이 아닐 거예요.",
  ui_story_1014_10140801_115_dialog_content = "이런 외진 곳에 전설이라고 할 만한 이야기는 그리 많지 않으니까요.",
  ui_story_1014_10140801_116_dialog_content = "전설? 어떤 이야기인데?",
  ui_story_1014_10140801_117_dialog_content = "어디서부터 이야기를 시작해야 되려나.",
  ui_story_1014_10140801_118_dialog_content = "됐어. 그냥 조셀린한테 들려달라고 해. 조셀린은 이야기를 잘하거든.",
  ui_story_1014_10140801_119_dialog_content = "단장님도 잘하시잖아요. 바에서 밤새 쉬지도 않고 얘기하시던 거 본 적 있어요.",
  ui_story_1014_10140801_120_dialog_content = "제 입은 고기 먹느라 바쁩니다.",
  ui_story_1014_10140801_121_dialog_content = "그렇군요, 알겠어요. 모처럼 식사를 대접하는 건데,\n손님을 출출하게 만들면 안 되겠죠.",
  ui_story_1014_10140801_122_dialog_content = "이 전설을 이야기하려면 일단 천 년 전으로 거슬러 올라가야 해요.",
  ui_story_1014_10140801_123_dialog_content = "오로리안들이 북방을 갓 벗어났을 무렵, 백야성이 세워지던 시작의 순간이었죠.",
  ui_story_1014_10140801_124_dialog_content = "그들은 생존할 수 있는 터전을 손에 넣기 위해,\n군대를 조직해서 암귀들과 쉼 없이 전투를 치렀어요.",
  ui_story_1014_10140801_125_dialog_content = "손에 넣은 영역은 전쟁이 진행되면서 점차 확대되어 지금과 비슷한 모습이 되었죠.",
  ui_story_1014_10140801_126_dialog_content = "그리고 그렇게 영역이 가장 멀리까지 확장된 곳이 바로\n여러분이 지금 머물고 있는 오로라 유적이에요.",
  ui_story_1014_10140801_127_dialog_content = "아하! 여긴 그렇게 오래전부터 변방이었구나!",
  ui_story_1014_10140801_128_dialog_content = "오로라 유적의 전략적 위치를 얕보면 곤란해.",
  ui_story_1014_10140801_129_dialog_content = "이 방어선만 공고히 한다면, 암귀들은 영원한 밤의 땅에 갇혀\n대륙에 더 깊이 들어오지 못해.",
  ui_story_1014_10140801_130_dialog_content = "반대로 오로라 유적이란 비좁은 좁은 길목을 포기해 버린다면,\n광대한 지역이 암귀의 직접적인 위협에 노출돼 버리지.",
  ui_story_1014_10140801_131_dialog_content = "즉, 당시의 전투는 오로리안이 아스트라 대륙을 지배할 권한이 있는지를\n판가름하는 중요한 전쟁이었다는 얘기야.",
  ui_story_1014_10140801_132_dialog_content = "단장님이 계속 설명하시겠어요? 아니면 제가 할까요?",
  ui_story_1014_10140801_133_dialog_content = "설명은 당신한테 맡기죠.\n전 그저 전략적인 지식을 보충 설명해 준 것뿐이에요.",
  ui_story_1014_10140801_134_dialog_content = "오로라 유적을 쟁탈하기 위해 벌어졌던 그 당시의 전쟁은 상당히 힘겨웠어요.",
  ui_story_1014_10140801_135_dialog_content = "여긴 영원한 밤의 땅과도 가깝고, 예측하기 어려운 오로라 현상도 있었죠.\n암귀들의 힘은 전대미문이라 할 정도로 강했어요.",
  ui_story_1014_10140801_136_dialog_content = "전쟁은 오랫동안 진행됐지만 방어선은 구축은 지지부진했고,\n오로리안들은 대대로 병사들을 희생시키며 방어선을 메울 수밖에 없었어요.",
  ui_story_1014_10140801_137_dialog_content = "끝날 기약도 없이 전쟁이 계속되던 중, 그 어떤 문자의 기록도 없는 어느 하루...",
  ui_story_1014_10140801_138_dialog_content = "오로리안은 마침내 운명의 총애를 받게 돼요.",
  ui_story_1014_10140801_139_dialog_content = "그날의 전장엔 전에 본 적 없는 먹구름이 햇빛을 가렸죠.",
  ui_story_1014_10140801_140_dialog_content = "그건 <color=#FFB400>콜로서스 함대</color>였어요.",
  ui_story_1014_10140801_141_dialog_content = "콜로서스 함대?!",
  ui_story_1014_10140801_142_dialog_content = "(본 적 있어! 지금 설명이랑 같은 장면을 본 적 있는 것 같아!)",
  ui_story_1014_10140801_143_dialog_content = "(설마 바로 그 함대인가?)",
  ui_story_1014_10140801_144_dialog_content = "콜로서스 함대는 먼 곳으로 비행해 떠나갔지만, 그중 한 대가 멈춰 섰어요.",
  ui_story_1014_10140801_145_dialog_content = "그 콜로서스는 오로리안 전사들과 소통했고,\n전장에 남아 오로리안들과 함께 전투를 치르기로 했어요.",
  ui_story_1014_10140801_146_dialog_content = "잠깐만, 콜로서스랑 오로리안이 소통을 했단 말이야?",
  ui_story_1014_10140801_147_dialog_content = "콜로서스에 타고 있던 아이테르가 아니고?",
  ui_story_1014_10140801_148_dialog_content = "네. 사실 그 콜로서스엔 아이테르가 단 한 명도 없었어요.",
  ui_story_1014_10140801_149_dialog_content = "이곳에 남기로 한 건 그 콜로서스가 <color=#FFB400>자신의 의지</color>로 결정한 거였으니까요.",
  ui_story_1014_10140801_150_dialog_content = "콜로서스가 스스로...",
  ui_story_1014_10140801_151_dialog_content = "어떤 책벌레 친구가 이런 이야기를 해 준 적이 있어.\n오로리안의 역사에선 「아이테르」란 단어보다 「콜로서스」가 먼저 탄생했다고 말이야.",
  ui_story_1014_10140801_152_dialog_content = "이 역시 그 전설이 사실임을 입증해 주는 증거라고 할 수 있겠지.",
  ui_story_1014_10140801_153_dialog_content = "그 뒤에는? 그 콜로서스는 계속 오로라 유적에 남은 거야?",
  ui_story_1014_10140801_154_dialog_content = "네. 콜로서스는 마치 특별한 병사처럼 그 지지부진했던 전쟁에 뛰어들었어요.",
  ui_story_1014_10140801_155_dialog_content = "그리고 수년 후, 전쟁에서 마침내 승리를 거둔 오로리안들은\n오로라 유적에 자신들의 요새를 건설했어요.",
  ui_story_1014_10140801_156_dialog_content = "콜로서스는 몇 년 동안 연이은 전쟁을 겪으며 점차 손상되기 시작했고,\n마지막엔 고요한 조각상으로 변했어요.",
  ui_story_1014_10140801_157_dialog_content = "더스크 타운의 오로리안들은 콜로서스를 무척 존경한답니다.\n심지언 콜로서스를 토템으로 삼아 숭배하기도 해요.",
  ui_story_1014_10140801_158_dialog_content = "콜로서스가 아이테르라는 단계를 건너뛰고 오로리안과\n유대 관계를 형성했다는 게 정말 신기하네.",
  ui_story_1014_10140801_159_dialog_content = "그래서 그 콜로서스는 아직 잘 보관돼 있어?",
  ui_story_1014_10140801_160_dialog_content = "제 이야기를 마저 들어 보세요.",
  ui_story_1014_10140801_161_dialog_content = "그 후 시간이 흘러 근대에 이르러 일루미나 연방이 탄생했고,\n오로라 유적에 주둔군을 파견했어요.",
  ui_story_1014_10140801_162_dialog_content = "그 연구원들은 고장 난 콜로서스를 복구하려 연구를 진행했죠.",
  ui_story_1014_10140801_163_dialog_content = "그들은... 절반 정도는 성공했다고 할 수 있었죠.",
  ui_story_1014_10140801_164_dialog_content = "그 콜로서스가 잠시 회복되긴 했었거든요. 하지만 그 뒤론 원인을 알 수 없는\n고장들 때문에 콜로서스의 행동이 혼란스러워졌어요.",
  ui_story_1014_10140801_165_dialog_content = "결국 콜로서스는 제어가 불가능한 상태가 되어버렸고,\n탐사할 수 없는 어둠의 밑바닥으로 떨어져 버리고 말았어요.",
  ui_story_1014_10140801_166_dialog_content = "어둠의 밑바닥에 떨어졌다고?! 너무 아깝잖아!",
  ui_story_1014_10140801_167_dialog_content = "네, 나이가 좀 있으신 분들은 그때 일 때문에 일루미나에\n여러 가지로 불만을 좀 가지고 계세요.",
  ui_story_1014_10140801_168_dialog_content = "그래서 일루미나의 병사들도 항상 눈총을 받는 거고요.",
  ui_story_1014_10140801_169_dialog_content = "그랬구나! 어쩐지 시장에 있는 할아버지들은 매번 뭘 물어봐도 시큰둥하더라.",
  ui_story_1014_10140801_170_dialog_content = "난 또 내가 뭘 잘못했나 했어.",
  ui_story_1014_10140801_171_dialog_content = "더스크 타운은 원래 그런 곳이에요.\n옳고 그름을 설명할 수 없는 일들이 너무 많아서, 모순을 해결할 수가 없죠.",
  ui_story_1014_10140801_172_dialog_content = "일루미나의 연구도 옳고 그름을 따지기 힘들어요.",
  ui_story_1014_10140801_173_dialog_content = "확실히 잘못이라고 할 수 있는 점이라면 그들이 더스크 타운에 있던\n고대 콜로서스를 잃어버렸다는 거겠죠.",
  ui_story_1014_10140801_174_dialog_content = "하지만 그들의 연구 성과가 PlayerName의 콜로서스 복구에 도움이 된다면,\n그건 또 좋은 일이잖아요?",
  ui_story_1014_10140801_175_dialog_content = "참, 일루미나 연구원이 벌써 나한테 연락했어.",
  ui_story_1014_10140801_176_dialog_content = "자기도 콜로서스 복구에 엄청 관심이 있다면서,\n한시라도 빨리 시작했으면 한다고 하더라.",
  ui_story_1014_10140801_177_dialog_content = "진짜? 근데 벌써 시간이 이렇게 됐는데, 자고 있지 않을까?",
  ui_story_1014_10140801_178_dialog_content = "그건 걱정 안 해도 돼. 아마 이제 막 일어났을걸.",
  ui_story_1014_10140801_179_dialog_content = "막 일어났다고?!",
  ui_story_1014_10140801_180_dialog_content = "너도 알잖아. 과학자들은 항상 좀 이상한 면이 있다는 거.",
  ui_story_1014_10140801_181_dialog_content = "하하, 그건 그렇네.",
  ui_story_1014_10140801_182_dialog_content = "그럼 이왕 이렇게 된 거, 밥 다 먹고 나면 연구소에 가 보자.",
  ui_story_1014_10140801_183_dialog_content = "스카이워커랑 관련된 일이라면 빠르면 빠를수록 좋으니까.",
  ui_story_1014_10140801_184_dialog_content = "<color=#e8d9bb>끼이익──</color>",
  ui_story_1014_10140801_185_dialog_content = "다들 돌아갔어요.",
  ui_story_1014_10140801_186_dialog_content = "저 외지인들 꽤 재미있는 사람들이네요.",
  ui_story_1014_10140801_187_dialog_content = "네, 무척 재미있는 사람들입니다.",
  ui_story_1014_10140801_188_dialog_content = "일루미나의 장교, 백야성의 공주가 함께 행동할 줄이야.",
  ui_story_1014_10140801_189_dialog_content = "소문의 아이테르도 솜씨가 보통이 아니군요.",
  ui_story_1014_10140801_190_dialog_content = "참, 저한테 고맙다고 하셔야죠?",
  ui_story_1014_10140801_191_dialog_content = "성녀님, 진심이십니까? 성녀님처럼 넓은 아량을 가지신 분이 평민들 앞에서\n제가 곤란하지 않게 해준 일 정도로 생색을 내실 생각은 아니겠죠?",
  ui_story_1014_10140801_192_dialog_content = "저한테 고맙단 인사를 하시면 오히려 마음이 좀 편해지시지 않을까 했어요.",
  ui_story_1014_10140801_193_dialog_content = "듣고 보니 오히려 성녀님께서 제게 고마워해야 할 것 같군요.",
  ui_story_1014_10140801_194_dialog_content = "네?",
  ui_story_1014_10140801_195_dialog_content = "그렇게 무작정 아무 생각 없이 사람을 구하려 뛰어드는 전투 방식은 옳지 않습니다.",
  ui_story_1014_10140801_196_dialog_content = "성녀님께 나쁜 일이 일어나지 않도록 돕는 이가 있기 때문에,\n성녀님께서 멋지게 영웅 행세를 하실 수 있는 거니까요.",
  ui_story_1014_10140801_197_dialog_content = "아, 그건 맞아요. 그 사람한테 고맙다고 해야겠네요.",
  ui_story_1014_10140801_198_dialog_content = "하지만 그렇게 따져도 저한테 고맙다고 하셔야 해요.",
  ui_story_1014_10140801_199_dialog_content = "어째서죠?",
  ui_story_1014_10140801_200_dialog_content = "제 덕분에 후회로 남을 일이 줄어들었잖아요.",
  ui_story_1014_10140801_201_dialog_content = "호오! 상태가 완벽한 콜로서스로군!",
  ui_story_1014_10140801_202_dialog_content = "정말 대단해! 당신들은 이게 얼마만큼의 연구 가치를 지니고 있는지 알고 있나?",
  ui_story_1014_10140801_203_dialog_content = "미안하지만, 우린 스카이워커를 연구해 달라고 부탁하러 온 게 아니에요.",
  ui_story_1014_10140801_204_dialog_content = "이번에 온 건...",
  ui_story_1014_10140801_205_dialog_content = "아, 알고 있네. 거래 때문이지.",
  ui_story_1014_10140801_206_dialog_content = "「전쟁 기계」는 가져왔나?",
  ui_story_1014_10140801_207_dialog_content = "네, 여기요.",
  ui_story_1014_10140801_208_dialog_content = "아, 이거군. 이쪽에 놓으면 된다.",
  ui_story_1014_10140801_209_dialog_content = "콜로서스의 의식을 복구하는 일은 내게 맡겨라.",
  ui_story_1014_10140801_210_dialog_content = "복구 과정을 진행하면서 데이터를 좀 기록해도 괜찮을지 모르겠군.\n그 정도는 당연히 괜찮겠지? 응?",
  ui_story_1014_10140801_211_dialog_content = "스카이워커가 의식을 회복하는 데 도움만 된다면 얼마든지 기록해도 좋아요.",
  ui_story_1014_10140801_212_dialog_content = "좋아, 그럼 지금 바로 시작해 볼까!",
  ui_story_1014_10140801_213_dialog_content = "여기서 보고 있어도 될까요?",
  ui_story_1014_10140801_214_dialog_content = "호, 혹시 갑자기 문제라도 생기는 건 아닐까 걱정이 돼서...",
  ui_story_1014_10140801_215_dialog_content = "물론이지. 따분해하지만 않는다면야.",
  ui_story_1014_10140801_216_dialog_content = "PlayerName, 시간이 벌써 이렇게 됐는데 계속 여기 있으려고?",
  ui_story_1014_10140801_217_dialog_content = "응. 스카이워커가 수리 중이라는 생각 때문에 잠이 잘 안 와서,\n차라리 여기서 지켜보고 있는 게 낫겠다 싶었거든.",
  ui_story_1014_10140801_218_dialog_content = "다들 먼저 가서 자.",
  ui_story_1014_10140801_219_dialog_content = "혼자서 괜찮겠어?",
  ui_story_1014_10140801_220_dialog_content = "괜찮아. 여긴 일루미나의 주둔지니까 별일 없을 거야.",
  ui_story_1014_10140801_221_dialog_content = "그래. 그렇지만... 너무 무리하진 마.",
  ui_story_1014_10140801_222_dialog_content = "응, 알았어.",
  ui_story_1014_10140801_223_dialog_content = "<color=#e8d9bb>팅팅, 탕탕...</color>",
  ui_story_1014_10140801_224_dialog_content = "이봐, 아이테르 청년, 눈 좀 떠봐.",
  ui_story_1014_10140801_225_dialog_content = "으음...",
  ui_story_1014_10140801_226_dialog_content = "그만 자고 좀 일어나 봐.",
  ui_story_1014_10140801_227_dialog_content = "으으으음...",
  ui_story_1014_10140801_228_dialog_content = "옆으로 굴러가 버리면 어떡해?",
  ui_story_1014_10140801_229_dialog_content = "얼른 일어나서 좀 보라고...",
  ui_story_1014_10140801_230_dialog_content = "오랜만입니다, PlayerName.",
  ui_story_1014_10140801_231_dialog_content = "<size=50>!!!</size>",
  ui_story_1014_10140801_232_dialog_content = "스카이워커! 저, 정신이 든 거야?",
  ui_story_1014_10140801_233_dialog_content = "일단은 수리도 끝났으니, 얼른 가서 확인해 봐라.",
  ui_story_1014_10140801_234_dialog_content = "다만 우리 쪽에 기록돼 있는 데이터가 부족해서,\n콜로서스의 의식을 안정적으로 유지시킬 순 없었어.",
  ui_story_1014_10140801_235_dialog_content = "그러니 서둘러.",
  ui_story_1014_10140801_236_dialog_content = "안정적으로 유지시킬 수 없다니요?",
  ui_story_1014_10140801_237_dialog_content = "계속 절 복구할 방법을 찾아 주셔서 감사합니다, PlayerName.",
  ui_story_1014_10140801_238_dialog_content = "드디어... 네 목소리가 들려... 스카이워커!",
  ui_story_1014_10140801_239_dialog_content = "그동안 너무 많은 일들이 있어서... 뭐부터 설명해야 좋을지...",
  ui_story_1014_10140801_240_dialog_content = "죄송합니다. 이번에도 곁에 오래 머물진 못할 것 같습니다.",
  ui_story_1014_10140801_241_dialog_content = "......",
  ui_story_1014_10140801_242_dialog_content = "사용한 방법은 옳았지만, 그 방법을 뒷받침할 데이터가 부족합니다.",
  ui_story_1014_10140801_243_dialog_content = "그래. 전에 진행했던 콜로서스의 연구가 아직 완벽하지 않아서 말이지... 휴.",
  ui_story_1014_10140801_244_dialog_content = "그, 그럼 어떡해...?",
  ui_story_1014_10140801_245_dialog_content = "제가 다른 콜로서스의 행방을 찾아냈습니다.",
  ui_story_1014_10140801_246_dialog_content = "뭐라고?!",
  ui_story_1014_10140801_247_dialog_content = "그 콜로서스만 찾으면 괜찮아질 수 있어? 어디 있는지 알려줘!",
  ui_story_1014_10140801_248_dialog_content = "<anim type=Shake>시간이... 다 됐습니다.</anim>",
  ui_story_1014_10140801_249_dialog_content = "<anim type=Shake>단말기에... 좌표 정보를... 남겨 두었습니다.</anim>",
  ui_story_1014_10140801_250_dialog_content = "좌표? 다른 콜로서스가 있다는 그 좌표인 거지?!",
  ui_story_1014_10140801_251_dialog_content = "<anim type=Shake>PlayerName... 저는... 당신을 믿습니다.</anim>",
  ui_story_1014_10140801_252_dialog_content = "<anim type=Shake>부디... 당신도... 자신을 믿어 주십시오.</anim>",
  ui_story_1014_10140901_1_dialog_content = "받으세요. 오로라 유적 구역의 가장 완벽한 군사 지도입니다.",
  ui_story_1014_10140901_2_dialog_content = "특별 권한을 사용해서 손에 넣은 거니까, 절대 외부로 유출하진 마세요.",
  ui_story_1014_10140901_3_dialog_content = "당신이 찾으려고 하는 좌표는 아마 이쯤에 있을 겁니다.",
  ui_story_1014_10140901_4_dialog_content = "여긴... 어둠의 밑바닥?",
  ui_story_1014_10140901_5_dialog_content = "맞아요. 게다가 지하성입니다.",
  ui_story_1014_10140901_6_dialog_content = "일루미나는 그 지하성의 표면적인 부분만 탐색을 진행했고,\n더 깊이 들어가진 않았습니다.",
  ui_story_1014_10140901_7_dialog_content = "그러니 그곳은 미지의 지역이나 다름없습니다.",
  ui_story_1014_10140901_8_dialog_content = "우리가 가도 되는 거야?",
  ui_story_1014_10140901_9_dialog_content = "그래요. 하지만 매우 위험할 테니 가기 전에 신중히 생각해 보세요.",
  ui_story_1014_10140901_10_dialog_content = "알겠어. 근데 사실 생각해 볼 필요도 없어.\n스카이워커를 위해서라면 반드시 가야만 하니까.",
  ui_story_1014_10140901_11_dialog_content = "가지 말라고 저지할 생각은 없습니다. 단지 신중히 생각해 보라는 겁니다.",
  ui_story_1014_10140901_12_dialog_content = "거기 가서 그 고대의 콜로서스를 찾았다고 칩시다.\n그 다음은요? 어떻게 여기까지 옮겨 올 거죠?",
  ui_story_1014_10140901_13_dialog_content = "어떻게 옮겨 올 거냐고? 어, 그건...",
  ui_story_1014_10140901_14_dialog_content = "문제없어! 내가 도와줄게! 내가 행보관님한테 운송 차량을 한 대 빌려달라고 할게!",
  ui_story_1014_10140901_15_dialog_content = "난 운전 연습도 해 본 적이 있어.\n나라면 분명히 콜로서스를 안전하게 가지고 돌아올 수 있을 거야!",
  ui_story_1014_10140901_16_dialog_content = "정말? 다행이다! 그러면 문제없겠네!",
  ui_story_1014_10140901_17_dialog_content = "당신들...",
  ui_story_1014_10140901_18_dialog_content = "둘이서 뭐라도 생각해 내준 것까진 참 고마운데요.",
  ui_story_1014_10140901_19_dialog_content = "콜로서스가 운송 차량에 실릴 만한 크기인지는 일단 넘어갑시다.",
  ui_story_1014_10140901_20_dialog_content = "지하성에 차량을 운전해 이동할 수 있는 노면이 있긴 한가요?\n그리고 암귀들이 포위해 오면 어떻게 거기서 빠져나올 거죠?",
  ui_story_1014_10140901_21_dialog_content = "그...그런 건...",
  ui_story_1014_10140901_22_dialog_content = "연구원, 스카이워커호를 복구하는 데 구체적으로 어떤 부품들이 필요하죠?",
  ui_story_1014_10140901_23_dialog_content = "흐음, 솔직히 말하면 콜로서스를 통째로 가져오는 게 제일 좋겠지요.",
  ui_story_1014_10140901_24_dialog_content = "우리도 콜로서스에 대해 모든 걸 다 알지는 못하니,\n뭔가 부족했다간 문제가 생길지도 모르는 일 아닙니까.",
  ui_story_1014_10140901_25_dialog_content = "하지만 굳이 꼽아야 한다면...",
  ui_story_1014_10140901_26_dialog_content = "그렇지, 「<color=#FFB400>제어 모듈</color>」이 필요하겠군요.",
  ui_story_1014_10140901_27_dialog_content = "그 부분이 연구 가치가 제일 높거든요.\n앞서 진행됐던 연구들에서도 중요한 연구 대상으로 다뤄지기도 했죠.",
  ui_story_1014_10140901_28_dialog_content = "좋아요. 그럼 다시 한번 확실히 해 두죠.\n목표는 콜로서스 그 자체가 아니라, 콜로서스의 「제어 모듈」인 겁니다.",
  ui_story_1014_10140901_29_dialog_content = "이번 행동은 당신이 자난성에서 이야기했던 거래 내용을 벗어났습니다.",
  ui_story_1014_10140901_30_dialog_content = "따라서 일루미나의 추가적인 지원을 받을 순 없습니다.",
  ui_story_1014_10140901_31_dialog_content = "응, 알겠어. 이건 내 개인적인 일이잖아.",
  ui_story_1014_10140901_32_dialog_content = "하지만 일부 개인의 도움을 받을 순 있을 겁니다.",
  ui_story_1014_10140901_33_dialog_content = "어?",
  ui_story_1014_10140901_34_dialog_content = "잉겔! 그럼 내가 도와줘도 된다는 거지?",
  ui_story_1014_10140901_35_dialog_content = "맞아요. 요즘엔 다른 작전 임무도 별로 없으니까, 시간은 당신이 알아서 배분하세요.",
  ui_story_1014_10140901_36_dialog_content = "하하하하, 알겠어!",
  ui_story_1014_10140901_37_dialog_content = "숀, 너...",
  ui_story_1014_10140901_38_dialog_content = "참고로 저와 악셀리아도 숀처럼 작전 임무가 없습니다.",
  ui_story_1014_10140901_39_dialog_content = "그럼... 두 사람도 날 도와주겠다는 거야?!",
  ui_story_1014_10140901_40_dialog_content = "어둠의 밑바닥에 있는 지하성은 매우 위험한 곳입니다.\n숀이 멋대로 유일한 아이테르를 거기 데려갔다가 죽게 만들고 싶진 않거든요.",
  ui_story_1014_10140901_41_dialog_content = "전 가서 악셀리아의 상태를 좀 볼게요. 준비가 끝나면 바로 출발하죠.",
  ui_story_1014_10140901_42_dialog_content = "진짜 잘 됐네, PlayerName! 나도 행보관님한테 가서 물자 차량을 빌려 올게!",
  ui_story_1014_10140901_43_dialog_content = "뭐, 뭐라고 해야 할지 모르겠지만...",
  ui_story_1014_10140901_44_dialog_content = "다들 고마워. 진짜, 진심으로 너무 고마워.",
  ui_story_1014_10140901_45_dialog_content = "<color=#e8d9bb>치이익──</color>",
  ui_story_1014_10140901_46_dialog_content = "악셀리아, 사탕 받아요.",
  ui_story_1014_10140901_47_dialog_content = "네.",
  ui_story_1014_10140901_48_dialog_content = "잉겔, 당신의 임무는 어떻게 됐습니까?",
  ui_story_1014_10140901_49_dialog_content = "마쳤습니다. 우리가 이렇게 무사히 도착했잖아요.",
  ui_story_1014_10140901_50_dialog_content = "악셀리아는 다른 임무를 이야기한 것입니다.",
  ui_story_1014_10140901_51_dialog_content = "다른 임무?",
  ui_story_1014_10140901_52_dialog_content = "임무가 모두 완료되었다면, 잉겔이 계속 PlayerName에게 도움을 줄 이유는 없습니다.",
  ui_story_1014_10140901_53_dialog_content = "따라서 당신에게는 다른 임무가 남아 있습니다.",
  ui_story_1014_10140901_54_dialog_content = "......",
  ui_story_1014_10140901_55_dialog_content = "가끔은 진짜 당신이 뭘 생각하고 있는 건지 모르겠군요.\n아무 생각이 없나 싶다가도 가끔은 뭐든지 알고 있으니 말이에요.",
  ui_story_1014_10140901_56_dialog_content = "이해합니다, 잉겔.",
  ui_story_1014_10140901_57_dialog_content = "만약 악셀리아가 알면 안 되는 임무라면 알려주지 않아도 됩니다.",
  ui_story_1014_10140901_58_dialog_content = "전 <color=#FFB400>노라</color>를 찾고 있습니다.",
  ui_story_1014_10140901_59_dialog_content = "그 배신한 과학자 말입니까?",
  ui_story_1014_10140901_60_dialog_content = "그래요.",
  ui_story_1014_10140901_61_dialog_content = "그 여자가 더스크 타운에 있습니까?",
  ui_story_1014_10140901_62_dialog_content = "그 여자가 어디에 있는진 아무도 몰라요.",
  ui_story_1014_10140901_63_dialog_content = "그래서 방법을 생각해 내서 그 여자가 스스로 모습을 보이게 만들어야 합니다.",
  ui_story_1014_10140901_64_dialog_content = "아이테르를 이용하는 겁니까?",
  ui_story_1014_10140901_65_dialog_content = "맞아요. 아이테르보다 더 좋은 미끼는 없으니까요.",
  ui_story_1014_10140901_66_dialog_content = "아이테르는 이 사실을 모르고 있을 것 같습니다.",
  ui_story_1014_10140901_67_dialog_content = "아이테르의 성격상 이 사실을 알게 된다면 화를 낼 겁니다.",
  ui_story_1014_10140901_68_dialog_content = "......",
  ui_story_1014_10140901_69_dialog_content = "악셀리아, 사탕 다 먹고 나면 조금 더 잘 수 있을까요?",
  ui_story_1014_10140901_70_dialog_content = "제가 깨울 때 일어나 줬으면 좋겠네요.",
  ui_story_1014_10140901_71_dialog_content = "네. 그렇게 하겠습니다.",
  ui_story_1014_10140901_72_dialog_content = "꼭 가야겠다고 했잖아!",
  ui_story_1014_10140901_73_dialog_content = "카렌 전하, 전하의 의중은 십분 이해합니다.",
  ui_story_1014_10140901_74_dialog_content = "그런데도 날 여기 붙잡고 뭘 하는 거지?",
  ui_story_1014_10140901_75_dialog_content = "이 모든 건 성주님의 뜻입니다. 부디 이해해 주십시오.",
  ui_story_1014_10140901_76_dialog_content = "성주님? 더스크 타운에서조차 성주님이라는 호칭을 듣게 될 줄은 몰랐는데.",
  ui_story_1014_10140901_77_dialog_content = "내 기억으론 지금껏 성주님께서 변방 쪽 일에 관여하신 적은 없었어.",
  ui_story_1014_10140901_78_dialog_content = "전하께서 이곳에 계시기 때문입니다.\n저희도 어쩔 수가 없는 상황이니 부디 이해해 주십시오.",
  ui_story_1014_10140901_79_dialog_content = "카렌 님과 난 이번에 시찰 임무를 받고 여기에 온 거야.\n백야 요새는 우리의 자유를 제한할 자격이 없어.",
  ui_story_1014_10140901_80_dialog_content = "만약 성주님의 명령이 있었다면, 증명할 수 있는 관련 문서를 제시하도록 해.",
  ui_story_1014_10140901_81_dialog_content = "그건...",
  ui_story_1014_10140901_82_dialog_content = "카렌, 베르타 씨? 두 사람 무슨 일 있어?",
  ui_story_1014_10140901_83_dialog_content = "왜 백야성 병사들이 카렌을 막고 있는 건데?",
  ui_story_1014_10140901_84_dialog_content = "PlayerName, 바이스, 두 사람 다 마침 잘 왔어.",
  ui_story_1014_10140901_85_dialog_content = "난 베르타와 출발 준비를 하려고 백야 요새에 물자를 좀 챙기러 왔어.",
  ui_story_1014_10140901_86_dialog_content = "그런데 병사들이 날 막고 있는 거야.",
  ui_story_1014_10140901_87_dialog_content = "전하를 막으려는 것은 아닙니다. 다만 위험한 곳에 가려 하시니\n반드시 전하의 안전을 확보할 사람을 파견해야 합니다.",
  ui_story_1014_10140901_88_dialog_content = "지금까지 내가 전장에 나설 때, 다른 이가 날 보호해 줄 필요는 단 한 번도 없었어.",
  ui_story_1014_10140901_89_dialog_content = "오, PlayerName. 한참 찾았네.",
  ui_story_1014_10140901_90_dialog_content = "다들 어둠의 밑바닥에 있는 지하성에 간다는 이야기를 들었는데,\n나도 데려가 줄 수 있을까?",
  ui_story_1014_10140901_91_dialog_content = "우리랑 같이 가려고?",
  ui_story_1014_10140901_92_dialog_content = "백야 요새에서 날 지원하라고 파견한 게 바로 단장인가?",
  ui_story_1014_10140901_93_dialog_content = "아니요, 그렇지 않습니다.\n그저 오래전부터 그 지하성에 가 보고 싶었을 뿐입니다.",
  ui_story_1014_10140901_94_dialog_content = "게다가 최근 더스크 타운 근처의 암귀들이 이상 행동을 보이고 있는데,\n어쩌면 그곳과 관련이 있을지도 모릅니다.",
  ui_story_1014_10140901_95_dialog_content = "가서 확실히 조사하고 싶습니다만, 기사단을 데리고 가면 문제의 소지가 있고,\n혼자 가자니 힘에 부쳐서 말이지요.",
  ui_story_1014_10140901_96_dialog_content = "그런데 마침 여러분이 그곳에 간다고 하니 이렇게 좋은 기회가 또 어디 있겠습니까.",
  ui_story_1014_10140901_97_dialog_content = "그랬구나.",
  ui_story_1014_10140901_98_dialog_content = "백야 요새에서 여러분께 파견한 지원은 제가 아니라 다른 사람입니다.",
  ui_story_1014_10140901_99_dialog_content = "아, 마침 왔군요.",
  ui_story_1014_10140901_100_dialog_content = "제가 여러분을 너무 오래 기다리게 만든 건 아니었으면 좋겠군요.",
  ui_story_1014_10140901_101_dialog_content = "시간이 촉박한 관계로 최소한의 준비만 해 두었습니다.",
  ui_story_1014_10140901_102_dialog_content = "<color=#FFB400>요제프 신부님</color>, 드디어 오셨군요.",
  ui_story_1014_10140901_103_dialog_content = "카렌 전하, 이쪽은 교구에서 지원 임무를 맡아 파견된 요제프 신부입니다.\n이번 여정은 요제프 신부가 전하의 일행과 동행할 것입니다.",
  ui_story_1014_10140901_104_dialog_content = "말씀 많이 들었습니다, 카렌 전하.",
  ui_story_1014_10140901_105_dialog_content = "요제프 신부가 도착했으니, 저도 더는 전하의 앞을 막아서지 않겠습니다.",
  ui_story_1014_10140901_106_dialog_content = "카렌 전하, 모든 일이 순조로우시길 기원하겠습니다.",
  ui_story_1014_10140901_107_dialog_content = "지원인데 딱 한 사람만 온 건가요?",
  ui_story_1014_10140901_108_dialog_content = "네. 하지만 교구가 여러분을 홀대하려는 것이 아니라,\n일손이 워낙 부족해 어쩔 수 없었습니다.",
  ui_story_1014_10140901_109_dialog_content = "저 말은 빈말이라 생각해도 돼.\n저 사람을 파견한 것만으로도 교구는 성의를 다한 거니까.",
  ui_story_1014_10140901_110_dialog_content = "우리가 가려는 곳은 아주 위험해.\n실력이 부족한 사람이라면 수가 많아 봤자 도움이 안 될 거야.",
  ui_story_1014_10140901_111_dialog_content = "레오 단장, 이번엔 원하는 바를 이룰 수 있겠군요.",
  ui_story_1014_10140901_112_dialog_content = "그러게. 이게 다 PlayerName 덕분이라고.\n이렇게 사람들을 모아 팀을 꾸리는 건 정말 흔한 일은 아니니까.",
  ui_story_1014_10140901_113_dialog_content = "그뿐만이 아닌 것 같군요. 그 평민 소녀가 단장님을 찾아왔습니다.",
  ui_story_1014_10140901_114_dialog_content = "평민 소녀라니...",
  ui_story_1014_10140901_115_dialog_content = "그 호칭 마음에 드네요. 「성녀님」보다 훨씬 좋아요.",
  ui_story_1014_10140901_116_dialog_content = "조셀린? 당신이 왜 여기 온 겁니까?",
  ui_story_1014_10140901_117_dialog_content = "PlayerName, 저도 같이 가도 될까요?",
  ui_story_1014_10140901_118_dialog_content = "뭐? 아, 그럼! 당연히 되지!",
  ui_story_1014_10140901_119_dialog_content = "근데... 왜 가려는 건데?",
  ui_story_1014_10140901_120_dialog_content = "멀리서 오신 손님들이 갚은 어둠속으로 들어가는 걸 가만히 보고만 있을 순 없거든요.",
  ui_story_1014_10140901_121_dialog_content = "적어도 곁에서 구석이라도 밝히는 등불이 되고 싶어요.",
  ui_story_1014_10140901_122_dialog_content = "<color=#e8d9bb>덜컹... 덜컹...</color>",
  ui_story_1014_10140901_123_dialog_content = "<color=#e8d9bb>덜... 컹... 덜...</color>",
  ui_story_1014_10140901_124_dialog_content = "엥? 왜 또 안 움직이지?",
  ui_story_1014_10140901_125_dialog_content = "또 어디가 걸렸나?",
  ui_story_1014_10140901_126_dialog_content = "숀, 됐습니다. 괜히 화물차 건드리지 마세요.",
  ui_story_1014_10140901_127_dialog_content = "제가 안 될 거라고 했었잖아요. 여기까지 몰고 온 것만으로 충분해요.",
  ui_story_1014_10140901_128_dialog_content = "다들 내리세요. 지하성 외곽 지역에 도착했습니다.",
  ui_story_1014_10140901_129_dialog_content = "악셀리아, 이제 일어나야 합니다.",
  ui_story_1014_10140901_130_dialog_content = "하암. 네, 잠은 충분히 잤습니다.",
  ui_story_1014_10140901_131_dialog_content = "바로 여기구나.",
  ui_story_1014_10140901_132_dialog_content = "역시 다크매터가 굉장히 짙어.",
  ui_story_1014_10140901_133_dialog_content = "앞으로 조금만 더 가면 어둠의 밑바닥이야.",
  ui_story_1014_10140901_134_dialog_content = "으, 그렇게 말하니까 엄청 긴장되네. 어둠의 밑바닥에 좋은 기억은 하나도 없단 말이야.",
  ui_story_1014_10140901_135_dialog_content = "저 지하성에 가 본 사람이 또 있나요?",
  ui_story_1014_10140901_136_dialog_content = "몇몇 노인은 가 본 적이 있는 모양이더군요.\n그리고 그 노인들이 저곳에 절대 가지 말라고 말을 하곤 했습니다.",
  ui_story_1014_10140901_137_dialog_content = "그렇지만 딱히 두려워할 필요는 없겠군요.\n갔다 왔다던 노인들도 딱히 불사신 괴물은 아니었으니까요.",
  ui_story_1014_10140901_138_dialog_content = "저들도 어둠의 밑바닥에서 살아 돌아왔는데, 우리라면 더 거뜬하겠죠.",
  ui_story_1014_10140901_139_dialog_content = "풋, 단장님이 드는 이유라면 뭔가 더 진지할 줄 알았는데요.",
  ui_story_1014_10140901_140_dialog_content = "어둠의 밑바닥에 직접 와 본 적이 없으니,\n진지하게 이야기하려고 해도 진지할 근거가 있어야 말이죠.",
  ui_story_1014_10140901_141_dialog_content = "레오 단장을 믿으면 됩니다. 언제나 정확한 판단을 내리는 사람이니까요.",
  ui_story_1014_10140901_142_dialog_content = "치켜세우지 마. 난 여기선 오히려 당신 판단이 더 듣고 싶거든.",
  ui_story_1014_10140901_143_dialog_content = "하하, 같이 온 사람들을 보니까 또 별로 안 무서워지는 것 같아.",
  ui_story_1014_10140901_144_dialog_content = "어쩌면 암귀보다 이 사람들이 더 무시무시한 힘을 가지고 있을지도 모르잖아.",
  ui_story_1014_10140901_145_dialog_content = "여러분, 준비 다 됐으면 이제 지하성으로 출발하죠.",
  ui_story_1014_10140901_146_dialog_content = "가서 그 콜로서스를 찾아내자구요.",
  ui_story_1014_10140901_147_dialog_content = "소란스럽군요. 너무나도 소란스러워요.",
  ui_story_1014_10140901_148_dialog_content = "이렇게 소란스러운 건 참으로 오랜만이네요.",
  ui_story_1014_10140901_149_dialog_content = "대체 무엇이길래 빗방울 소리보다 촘촘하고, 벌레의 지저귐보다 조급한 것일까요?",
  ui_story_1014_10140901_150_dialog_content = "아, 틀림없이 그렇겠죠. 사람의 소리네요.",
  ui_story_1014_10140901_151_dialog_content = "밉살스럽기 짝이 없는, 사람의 소리 말이에요.",
  ui_story_1014_10141101_1_dialog_content = "여기가 바로 그 콜로서스가 있다는 유적인가...",
  ui_story_1014_10141101_2_dialog_content = "지도엔 그렇게 적혀 있었습니다.",
  ui_story_1014_10141101_3_dialog_content = "다들 조심하세요. 꽤 많은 수의 암귀가 여기 모여 있습니다.",
  ui_story_1014_10141101_4_dialog_content = "......",
  ui_story_1014_10141101_5_dialog_content = "진짜 이상하네. 암귀가 왜 이렇게 많은 거지?",
  ui_story_1014_10141101_6_dialog_content = "암귀들의 평소 행동 방식으로 미뤄 보면, 이곳에 집결해 있다는 건 확실히 이상한 일이야.",
  ui_story_1014_10141101_7_dialog_content = "하지만 여기 환경은 다른 곳과는 차이가 있으니까,\n뭔가 우리가 알지 못하는 특성이 존재할지도 모르지.",
  ui_story_1014_10141101_8_dialog_content = "나도 이 암귀들이 이런 환경에 이끌려 모인 건지,\n아니면 누군가 녀석들을 지휘하고 있는 건지 확신할 수 없어.",
  ui_story_1014_10141101_9_dialog_content = "상황이 복잡하니 조심하는 게 좋겠군요.",
  ui_story_1014_10141101_10_dialog_content = "암귀는 두려워할 가치가 없습니다.\n암귀는 패배합니다. 그것이 바로 유일한 결과입니다.",
  ui_story_1014_10141101_11_dialog_content = "악셀리아가 그렇게 대단하단 말이야?",
  ui_story_1014_10141101_12_dialog_content = "악셀리아를 얕보면 안 돼! 아마 우리 중에서 제일 대단한 게 바로 악셀리아일걸!\n가끔은 나도 악셀리아한테 못 이기거든.",
  ui_story_1014_10141101_13_dialog_content = "제가 지금까지 쭉 봐 왔는데, 숀 당신이 악셀리아와 서로 대련을 하면\n보통은 열 번에 아홉 번은 지고, 한 번은 비겼죠.",
  ui_story_1014_10141101_14_dialog_content = "숀을 상대해 줄 때는, 그렇게 열심히 할 필요가 없습니다.",
  ui_story_1014_10141101_15_dialog_content = "그렇게 매정하게 말하지 말아 줄래?!",
  ui_story_1014_10141101_16_dialog_content = "하하하, 셋 다 사이가 좋군요.",
  ui_story_1014_10141101_17_dialog_content = "하지만 이곳은 안전하진 않으니 일단은 다투지 말고 진정하세요.",
  ui_story_1014_10141101_18_dialog_content = "어서 PlayerName에게 필요한 모듈을 찾고 속전속결로 끝냅시다.",
  ui_story_1014_10141101_19_dialog_content = "마침 앞에 암귀들이 있네. 그럼 이렇게 하자고!",
  ui_story_1014_10141101_20_dialog_content = "악셀리아, 나랑 누가 암귀를 더 많이 해치우는지 다시 대결하자!",
  ui_story_1014_10141101_21_dialog_content = "잉겔 넌 심판을 맡아.",
  ui_story_1014_10141101_22_dialog_content = "휴, 또 시작인가요.",
  ui_story_1014_10141101_23_dialog_content = "좋습니다. 이번엔 져도 울지는 마세요.",
  ui_story_1014_10141101_24_dialog_content = "<color=#e8d9bb>오로라 유적 밖, 어딘가</color>",
  ui_story_1014_10141101_25_dialog_content = "『<color=#FFB400>아스모데우스</color> 님. 오로리안과 아이테르가 이미 유적 내부로 들어왔습니다.』",
  ui_story_1014_10141101_26_dialog_content = "『놈들은 이미 유적 내의 동포들과 맞붙은 상태입니다.』",
  ui_story_1014_10141101_27_dialog_content = "『그들이 계속 깊이 들어오도록 만드세요.』",
  ui_story_1014_10141101_28_dialog_content = "『그들의 욕망이 우리가 줄곧 찾고 있던 그 물건으로 우릴 인도해 줄지도 모르니까요.』",
  ui_story_1014_10141102_1_dialog_content = "마지막 한 마리! 넌 내 거야!",
  ui_story_1014_10141102_2_dialog_content = "캬악──!",
  ui_story_1014_10141102_3_dialog_content = "잉겔, 어때? 누가 이겼어?",
  ui_story_1014_10141102_4_dialog_content = "그럼 결과를 발표하겠습니다.",
  ui_story_1014_10141102_5_dialog_content = "숀, 당신이 처치한 암귀는 20마리예요.",
  ui_story_1014_10141102_6_dialog_content = "응! 내 최고 기록보단 조금 적네.",
  ui_story_1014_10141102_7_dialog_content = "악셀리아가 처치한 암귀는...",
  ui_story_1014_10141102_8_dialog_content = "32마리예요!",
  ui_story_1014_10141102_9_dialog_content = "그렇게 많다고?!",
  ui_story_1014_10141102_10_dialog_content = "지, 진짜야?!",
  ui_story_1014_10141102_11_dialog_content = "숀, 당신은 이리저리 도망 다니는 소형 암귀들을 쫓느라 시간을 너무 많이 썼습니다.",
  ui_story_1014_10141102_12_dialog_content = "악셀리아는 그럴 시간에 대형 암귀 몇 마리가 이끄는 암귀 무리를 목표로 삼았죠.",
  ui_story_1014_10141102_13_dialog_content = "으... 하지만 어쩔 수 없었다고.",
  ui_story_1014_10141102_14_dialog_content = "내 능력으론 우선 작고 약한 암귀들부터 처치하면서 수를 줄이다가,\n마지막에 대형 암귀 처치에 집중하는 게 최선이란 말이야.",
  ui_story_1014_10141102_15_dialog_content = "맞아요. 당신이 아직 충분히 강하지 않기 때문에 결국은 악셀리아가 이긴 거죠.",
  ui_story_1014_10141102_16_dialog_content = "쳇! 또 악셀리아가 이겼네!",
  ui_story_1014_10141102_17_dialog_content = "숀이 또 졌습니다.",
  ui_story_1014_10141102_18_dialog_content = "그렇지만 숀은 낙담하지 않습니다.\n숀은 모든 도전에 열중하기 때문에, 지더라도 포기하지 않습니다.",
  ui_story_1014_10141102_19_dialog_content = "언젠가 승리를 거둘 때까지 노력할 뿐입니다.",
  ui_story_1014_10141102_20_dialog_content = "역시 악셀리아는 내 좋은 라이벌이라니까. 내 마음을 잘 알잖아.",
  ui_story_1014_10141102_21_dialog_content = "하지만 숀이 악셀리아를 이기는 것은 불가능합니다.",
  ui_story_1014_10141102_22_dialog_content = "그렇게 단호하게 말하지 마! 난 앞으로도 쭉 성장하고 강해질 거란 말이야!",
  ui_story_1014_10141102_23_dialog_content = "요제프 신부, 조금 전 저들의 활약에 대해 어떻게 생각하지?",
  ui_story_1014_10141102_24_dialog_content = "제 의견을 물으시는 겁니까?",
  ui_story_1014_10141102_25_dialog_content = "물론이지. 입을 꾹 닫은 채로 그렇게나 오래 관찰했으면\n분명히 여려 견해가 나왔을 텐데.",
  ui_story_1014_10141102_26_dialog_content = "(아까부터 아무 말이 없다 했더니, 우릴 관찰하고 있던 거야?)",
  ui_story_1014_10141102_27_dialog_content = "일루미나 분들 모두 아주 훌륭하십니다. 각자 저마다의 장점이 있군요.",
  ui_story_1014_10141102_28_dialog_content = "악셀리아 씨는 강력한 기계 조종 능력을 갖췄고, 잉겔 씨는 관찰과 협조 능력이,\n숀 씨는 경험을 살려 현재 상황에 반영하는 능력이 뛰어납니다.",
  ui_story_1014_10141102_29_dialog_content = "세 분이 한 팀이 된다면 아주 완벽할 겁니다.",
  ui_story_1014_10141102_30_dialog_content = "......!",
  ui_story_1014_10141102_31_dialog_content = "악셀리아는 요제프 신부의 견해를 긍정합니다.",
  ui_story_1014_10141102_32_dialog_content = "음, 인정해 주셔서 감사합니다.",
  ui_story_1014_10141102_33_dialog_content = "(정말 대단한 관찰력이네!)",
  ui_story_1014_10141102_34_dialog_content = "근데 악셀리아는 정말 대단하구나.",
  ui_story_1014_10141102_35_dialog_content = "연합 훈련에 참가하면 개인전 챔피언의 강력한 경쟁자가 될 것 같아!",
  ui_story_1014_10141102_36_dialog_content = "PlayerName도 연합 훈련을 알고 있나요?",
  ui_story_1014_10141102_37_dialog_content = "응, 라인하르트 씨가 전에 설명해 주신 적이 있거든.",
  ui_story_1014_10141102_38_dialog_content = "챔피언들의 대결이 무척 기대된다고도 하셨어.",
  ui_story_1014_10141102_39_dialog_content = "역시나 그 대원수답군. 그 사람 스타일이야.",
  ui_story_1014_10141102_40_dialog_content = "나도 연합 훈련에서 대원수나 악셀리아 같은 강자들과 맞붙게 되길 기대하고 있어.",
  ui_story_1014_10141102_41_dialog_content = "물론 기회가 된다면 저번 연합 훈련에서 챔피언을 차지하신\n카렌 전하와도 한 수 겨뤄보고 싶군요.",
  ui_story_1014_10141102_42_dialog_content = "무례하군요!",
  ui_story_1014_10141102_43_dialog_content = "괜찮아.",
  ui_story_1014_10141102_44_dialog_content = "난 이번에도 그 훈련에 참가할 거야.",
  ui_story_1014_10141102_45_dialog_content = "그럼 전장에서 맞붙게 될 그날을 기대할게, 레오 단장.",
  ui_story_1014_10141102_46_dialog_content = "물론입니다.",
  ui_story_1014_10141102_47_dialog_content = "레오 단장도 연합 훈련에 참가하는 거야?",
  ui_story_1014_10141102_48_dialog_content = "그래.",
  ui_story_1014_10141102_49_dialog_content = "오로리안이라면 누구나 참가할 수 있지.",
  ui_story_1014_10141102_50_dialog_content = "아스트라 대륙 각지의 강자들과 맞붙을 수 있다면,\n얼마나 먼 곳에서 열리든 난 꼭 참가할 생각이야.",
  ui_story_1014_10141102_X50_dialog_content = "<color=#e8d9bb>오로라 유적 내부</color>",
  ui_story_1014_10141102_51_dialog_content = "(여기까지 왔으니, 이번 여정도 곧 끝나겠군요.)",
  ui_story_1014_10141102_52_dialog_content = "(하지만 지금까지 노라는 도무지 나타나질 않고 있어요.\n설마 제 판단에 문제가 있는 걸까요...)",
  ui_story_1014_10141102_53_dialog_content = "(아니, 노라의 목표는 언제나 명확했어요.\n노라를 꾀어낼 최고의 미끼가 PlayerName인 건 확실해요.)",
  ui_story_1014_10141102_54_dialog_content = "(제 판단은 틀리지 않았을 겁니다.\n그러니까 노라가 모습을 보일 때까지 계속 기다리면 됩니다.)",
  ui_story_1014_10141102_55_dialog_content = "잉겔, 왜 가만히 서 있어? 혹시 아까 어디 다쳤어?",
  ui_story_1014_10141102_56_dialog_content = "네? 아니요, 안 다쳤습니다.\n그저 여기 암귀들이 이렇게 많은 이유가 뭘까 생각하고 있었습니다.",
  ui_story_1014_10141102_57_dialog_content = "여러분, 잠깐 실례할게요.",
  ui_story_1014_10141102_58_dialog_content = "이번 여행의 목적은 PlayerName 씨의 콜로서스 부품 수색을 돕는 거죠?",
  ui_story_1014_10141102_59_dialog_content = "제가 아는 대로라면 그 고대 콜로서스는 이제 여기서 그리 멀지 않은 곳에 있을 거예요.",
  ui_story_1014_10141102_60_dialog_content = "그러니 계속 이동하는 게 어떨까요?",
  ui_story_1014_10141102_61_dialog_content = "음, 조셀린 씨 말이 맞아요.",
  ui_story_1014_10141102_62_dialog_content = "처음 여기 도착했을 때부터 계속 누군가 우릴 지켜보는 것 같은\n느낌이 들어서 찝찝했거든요...",
  ui_story_1014_10141102_63_dialog_content = "그러니까 빨리 필요한 부품을 찾아서 더스크 타운으로 돌아가죠!",
  ui_story_1014_10141102_64_dialog_content = "<color=#e8d9bb>오로라 유적 밖, 어딘가</color>",
  ui_story_1014_10141102_65_dialog_content = "『욕망의 냄새가 그 콜로서스에 가까워지고 있군요.』",
  ui_story_1014_10141102_66_dialog_content = "『설마... 그 물건은 콜로서스 내부에 있는 걸까요?』",
  ui_story_1014_10141102_67_dialog_content = "『아스모데우스 님, 지금 행동을 시작합니까?』",
  ui_story_1014_10141102_68_dialog_content = "『욕망이 더 가까이, 조금 더 가까이 다가오게 하세요...』",
  ui_story_1014_10141102_69_dialog_content = "『그 아이테르의 배신자, 그자의 욕망이 길을 안내해 주는 표지가 되어 줄 테니까요.』",
  ui_story_1014_10141102_70_dialog_content = "『우린 그저 기다리기만 하면 돼요.』",
  ui_story_1014_10141201_1_dialog_content = "이 앞이 바로 콜로서스 유적입니다. 모두 경계를 늦추지 마세요.",
  ui_story_1014_10141201_2_dialog_content = "머나먼 옛날에 이곳에 남겨진 콜로서스, 이제 곧 그 모습을...",
  ui_story_1014_10141201_3_dialog_content = "<size=45>엄청 크잖아?!</size>",
  ui_story_1014_10141201_4_dialog_content = "이 크기는 내 예상을 완전히 빗나갔잖아...",
  ui_story_1014_10141201_5_dialog_content = "이 콜로서스의 크기는 지금까지 발견된 콜로서스 중에서도 최상위권에 속합니다.",
  ui_story_1014_10141201_6_dialog_content = "일루미나 연방은 과거 더스크 타운의 주둔군을 통해\n이 콜로서스를 연구해서 수많은 귀중한 데이터를 얻었어요.",
  ui_story_1014_10141201_7_dialog_content = "어떤 데이터였는데?",
  ui_story_1014_10141201_8_dialog_content = "일부 설비들의 상세한 제작법이었습니다. 의료 시스템의 일부 도면 같은 것들 말이죠.",
  ui_story_1014_10141201_9_dialog_content = "다른 건 못 찾았어? 콜로서스의 기억이나 과거 아이테르들의 정보 같은 거.",
  ui_story_1014_10141201_10_dialog_content = "그건 일루미나에서 기밀로 다루고 있는 부분이라 대답해 줄 수 없습니다.",
  ui_story_1014_10141201_11_dialog_content = "그렇지만, 당시 개발자가 잘못 조작하는 바람에 이 콜로서스는\n한 번 <color=#FFB400>폭주</color>했던 적이 있습니다.",
  ui_story_1014_10141201_12_dialog_content = "그때의 폭주로 이 콜로서스 내부의 많은 구역이 굳게 잠겼고, 들어갈 수 없게 돼 버렸죠.",
  ui_story_1014_10141201_13_dialog_content = "그 후 이 콜로서스는 오로라 유적과 함께 가치가 낮고 위험도가 높은 지역으로 분류됐습니다.",
  ui_story_1014_10141201_14_dialog_content = "이번에 율리시스 님께서 우리가 이곳을 조사하도록 허락해 주신 건,\n아마 당신이 있기 때문일 겁니다.",
  ui_story_1014_10141201_15_dialog_content = "내가 아이테르라서...?",
  ui_story_1014_10141201_16_dialog_content = "맞아요.",
  ui_story_1014_10141201_17_dialog_content = "아이테르는 콜로서스의 조종사니, 예상 밖의 발견을 할 수도 있으니까요.",
  ui_story_1014_10141201_18_dialog_content = "...이 얘긴 그만하고 싶어.",
  ui_story_1014_10141201_19_dialog_content = "자, 들어가자.",
  ui_story_1014_10141201_20_dialog_content = "조심해야 합니다.",
  ui_story_1014_10141201_21_dialog_content = "악셀리아는 암귀들이 활동한 흔적을 발견했습니다.",
  ui_story_1014_10141201_22_dialog_content = "이 콜로서스 내부에는 다수의 암귀가 존재합니다.",
  ui_story_1014_10141201_23_dialog_content = "암귀가 아무리 많아도 난 반드시 이 콜로서스의 데이터를 손에 넣어야 해.",
  ui_story_1014_10141201_24_dialog_content = "스카이워커를 위해서.",
  ui_story_1014_10141201_25_dialog_content = "콜로서스의 내부는 매우 넓습니다.",
  ui_story_1014_10141201_26_dialog_content = "암귀의 흔적 외에는 아무것도 없습니다.",
  ui_story_1014_10141201_27_dialog_content = "PlayerName, 네 콜로서스에도 여기처럼 넓은 방이 있어?",
  ui_story_1014_10141201_28_option_content = "있어.",
  ui_story_1014_10141201_29_dialog_content = "스카이워커의 창고는 굉장히 넓고 트여 있어서, 달리기를 해도 전혀 문제없어.",
  ui_story_1014_10141201_30_dialog_content = "우와, 엄청난데!",
  ui_story_1014_10141201_31_option_content = "없어.",
  ui_story_1014_10141201_32_dialog_content = "스카이워커에 있는 방이랑 복도가 넓기는 한데, 평소엔 사람들이 많이 있거든.",
  ui_story_1014_10141201_33_dialog_content = "그래서 동료들이 있는 곳은 그렇게 넓어 보이진 않아.",
  ui_story_1014_10141201_34_dialog_content = "그렇겠네!",
  ui_story_1014_10141201_35_dialog_content = "앞쪽에 문이 하나 보입니다.",
  ui_story_1014_10141201_36_dialog_content = "이 문은 스카이워커호에 있는 방문과 비슷하게 생겼습니다.",
  ui_story_1014_10141201_37_dialog_content = "이 문 뒤는 아마 이 콜로서스의 함교일 것 같습니다.",
  ui_story_1014_10141201_38_dialog_content = "아주 단단히 잠겨 있나 봐. 손잡이나 잠금장치도 안 달려 있는데...",
  ui_story_1014_10141201_39_dialog_content = "문을 열려면 어떻게 해야 하지?",
  ui_story_1014_10141201_40_dialog_content = "스카이워커의 방문은 전부 감응하면 열 수 있는 방식으로 되어 있긴 해.",
  ui_story_1014_10141201_41_dialog_content = "이 콜로서스도 같을지 한 번 감응해 볼게.",
  ui_story_1014_10141201_42_option_content = "(강제 감응!)",
  ui_story_1014_10141201_43_dialog_content = "<color=#e8d9bb>지지직──</color>",
  ui_story_1014_10141201_44_dialog_content = "<color=#e8d9bb>미등록 아이테르의 방문이 감지되었습니다.</color>",
  ui_story_1014_10141201_45_dialog_content = "(이 콜로서스의 시스템인가? 말투가 너무 딱딱한 것 같은데.)",
  ui_story_1014_10141201_46_dialog_content = "(마치 인격이 잠든 스카이워커 같잖아...)",
  ui_story_1014_10141201_47_dialog_content = "<color=#e8d9bb>신분을 인증해 주십시오.</color>",
  ui_story_1014_10141201_48_dialog_content = "내 이름은 PlayerName, 난 아이테르야.",
  ui_story_1014_10141201_49_dialog_content = "<color=#e8d9bb>「미등록 사용자」를 PlayerName 님으로 변경합니다.</color>",
  ui_story_1014_10141201_50_dialog_content = "<color=#e8d9bb>콜로서스 「패스파인더호」는 당신에게 모든 권한을 부여했습니다.</color>",
  ui_story_1014_10141201_51_dialog_content = "<color=#FFB400>패스파인더호</color>라면... 고대 데이터 속의 아이테르가 조종했던 콜로서스 중 하나잖아!",
  ui_story_1014_10141201_52_dialog_content = "모든 권한을 부여했다고?! 이렇게 쉽게?",
  ui_story_1014_10141201_53_dialog_content = "<color=#e8d9bb>패스파인더호의 권한 부여 방식은 콜로서스의 소유자가 설정한 규칙에 부합합니다.</color>",
  ui_story_1014_10141201_54_dialog_content = "<color=#e8d9bb>「대기 시간이 100년 미만인 경우, 관리자에게만 모든 권한을 부여한다.」</color>",
  ui_story_1014_10141201_55_dialog_content = "<color=#e8d9bb>「대기... 100년 초과, ...년 미만인 경우, 모든 아이테르에게... 부여한다.」</color>",
  ui_story_1014_10141201_56_dialog_content = "<color=#e8d9bb>「대기... 년 초과, ...미만... 모든 생명체... 모든 권한을 부여한다.」</color>",
  ui_story_1014_10141201_57_dialog_content = "<color=#e8d9bb>규칙에 따라 패스파인더호는 현재 모든 아이테르에게 권한을 부여합니다.</color>",
  ui_story_1014_10141201_58_dialog_content = "그렇게 오랫동안 기다린 거였구나... 고생했어.",
  ui_story_1014_10141201_59_dialog_content = "<color=#e8d9bb>패스파인더호의 인격은 사용 중지 상태입니다.\n따라서 「고생했다」의 의미를 분석할 수 없습니다.</color>",
  ui_story_1014_10141201_60_dialog_content = "<color=#e8d9bb>패스파인더호의 모든 것은 미래의 아이테르에게 남겨진 「선물」입니다.</color>",
  ui_story_1014_10141201_61_dialog_content = "인격이 사용 중지 상태라고? 이유가 뭐야?",
  ui_story_1014_10141201_62_dialog_content = "<color=#e8d9bb>인격 기능을 실행할 경우 에너지 소모가 증가합니다.</color>",
  ui_story_1014_10141201_63_dialog_content = "<color=#e8d9bb>패스파인더호의 모든 유용한 데이터와 설비가 미래에 찾아올\n아이테르에게 완벽하게 전달될 수 있도록...</color>",
  ui_story_1014_10141201_64_dialog_content = "<color=#e8d9bb>패스파인더호는 인격 기능을 사용 중지하고 저에너지 모드로 진입했습니다.</color>",
  ui_story_1014_10141201_65_dialog_content = "그럼 지금 네 여러 시스템이랑 인격 데이터는 아직 멀쩡한 거야?",
  ui_story_1014_10141201_66_dialog_content = "<color=#e8d9bb>점검 시스템 작동.</color>",
  ui_story_1014_10141201_67_dialog_content = "<color=#e8d9bb>제어 시스템 점검... 작동 중. 부품 손상률 72%, 유지 관리 필요.</color>",
  ui_story_1014_10141201_68_dialog_content = "<color=#e8d9bb>바이오 모듈 점검... 오프라인 상태.</color>",
  ui_story_1014_10141201_69_dialog_content = "<color=#e8d9bb>생명유지 시스템 점검... 오프라인 상태.</color>",
  ui_story_1014_10141201_70_dialog_content = "<color=#e8d9bb>인격 데이터 무결성 점검... 데이터 손실 32%, 정상 작동 불가.</color>",
  ui_story_1014_10141201_71_dialog_content = "이미 인격 데이터가 정상적으로 작동할 수 없을 만큼 손실된 거야?",
  ui_story_1014_10141201_72_dialog_content = "그럼 사실 패스파인더호 넌 이미...",
  ui_story_1014_10141201_73_dialog_content = "아무튼 이렇게 오랜 시간 동안 버텨 줘서 정말 고마워.",
  ui_story_1014_10141201_74_dialog_content = "함교랑 연결된 문을 열어 줘.",
  ui_story_1014_10141201_75_dialog_content = "<color=#e8d9bb>명령을 접수했습니다.</color>",
  ui_story_1014_10141201_76_dialog_content = "<color=#e8d9bb>쿠르르릉──!</color>",
  ui_story_1014_10141201_77_dialog_content = "문이 열렸습니다.",
  ui_story_1014_10141201_78_dialog_content = "파손된 함교와 콜로서스의 컨트롤러가 보입니다.",
  ui_story_1014_10141201_79_dialog_content = "<anim type=Shake><size=45>크오오──!</size></anim>",
  ui_story_1014_10141201_80_dialog_content = "다들 조심해. 안에서 어슬렁거리던 암귀들이 몰려왔어!",
  ui_story_1014_10141201_81_dialog_content = "전투 준비!",
  ui_story_1014_10141302_1_dialog_content = "이곳에 있던 암귀들은 모두 처리했습니다.",
  ui_story_1014_10141302_2_dialog_content = "PlayerName, 암귀들이 더 몰려올지도 모르니까 잠깐 콜로서스의 입구를 닫자.",
  ui_story_1014_10141302_3_dialog_content = "응, 지금 바로 패스파인더호한테 닫아 달라고 할게.",
  ui_story_1014_10141302_4_dialog_content = "......",
  ui_story_1014_10141302_5_dialog_content = "악셀리아, 괜찮나요?",
  ui_story_1014_10141302_6_dialog_content = "전투를 너무 오랫동안 지속했으니 휴식이 필요해요.",
  ui_story_1014_10141302_7_dialog_content = "악셀리아는 괜찮습니다.",
  ui_story_1014_10141302_8_dialog_content = "전투로 인한 부담은 아직 제어 가능한 범위 안입니다.",
  ui_story_1014_10141302_9_dialog_content = "네, 알겠어요. 만약 불편해지면 바로 제게 알려 주세요.",
  ui_story_1014_10141302_10_dialog_content = "악셀리아는 이해했습니다.",
  ui_story_1014_10141302_11_dialog_content = "(하마터면 잊어버릴 뻔했어.\n악셀리아의 강함은 일루미나의 인체 개조 기술에서 비롯된 거였지.)",
  ui_story_1014_10141302_12_dialog_content = "(평소엔 거의 무표정이었는데, 아까 잠깐 고통스러운 것 같은 표정을 지었던 것 같아.)",
  ui_story_1014_10141302_13_dialog_content = "(악셀리아가 지금 받고 있는 고통은...\n어쩌면 표정에 잠깐 드러난 것보다 훨씬 더 심할 수도 있겠어...)",
  ui_story_1014_10141302_14_dialog_content = "PlayerName, 안심하고 해야 할 일을 완수하러 가세요.",
  ui_story_1014_10141302_15_dialog_content = "응... 알겠어, 고마워.",
  ui_story_1014_10141302_16_dialog_content = "우린 주변을 살피면서 경계하자.",
  ui_story_1014_10141302_17_dialog_content = "그럼 난 PlayerName하고 같이 콜로서스의 상태를 점검할게.",
  ui_story_1014_10141302_18_dialog_content = "패스파인더호, 네 인격 데이터를 가지고 가야 해서... 네 제어 모듈이 필요해.",
  ui_story_1014_10141302_19_dialog_content = "<color=#e8d9bb>명령을 접수했습니다. 제어 모듈의 상태를 검사합니다.</color>",
  ui_story_1014_10141302_20_dialog_content = "<color=#e8d9bb>경고: 제어 모듈이 심각하게 파손되어 강제로 떼어낼 경우\n되돌릴 수 없는 손상을 야기할 수 있습니다.</color>",
  ui_story_1014_10141302_21_dialog_content = "떼어낼 수 없단 거야?!",
  ui_story_1014_10141302_22_dialog_content = "어, 어떻게 하지?",
  ui_story_1014_10141302_23_dialog_content = "PlayerName의 얼굴에서 곤란한 기색이 보입니다.\n악셀리아가 제안하고 싶은 것이 있습니다.",
  ui_story_1014_10141302_24_dialog_content = "악셀리아의 아머에는 데이터를 복사할 수 있는 장치가 있습니다.\n그 장치를 콜로서스에 연결해도 좋습니다, PlayerName.",
  ui_story_1014_10141302_25_dialog_content = "그 방법을 사용하면 제어 모듈을 통째로 가져갈 수는 없더라도,\n콜로서스의 의식 데이터는 손에 넣을 수 있습니다.",
  ui_story_1014_10141302_26_dialog_content = "알골에게는 데이터와 실제 모듈이 일으키는 작용이 일치합니다.",
  ui_story_1014_10141302_27_dialog_content = "그럼 지금은 그 방법을 사용하는 수밖에 없겠네.",
  ui_story_1014_10141302_28_dialog_content = "PlayerName, 데이터 복사기를 잘 들고 콜로서스의 메인 제어 모듈에 연결해야 합니다.",
  ui_story_1014_10141302_29_dialog_content = "그리고 이 버튼을 누르면 장치가 자동으로 데이터를 복사합니다.",
  ui_story_1014_10141302_30_dialog_content = "알겠어.",
  ui_story_1014_10141302_31_dialog_content = "<color=#e8d9bb>콜로서스의 의식 데이터를 복사 중입니다. 잠시만 기다려 주세요.</color>",
  ui_story_1014_10141302_32_dialog_content = "복사가 다 될 때까지 또 조금 기다려야겠네.",
  ui_story_1014_10141302_33_dialog_content = "여기 곳곳엔 고대의 과학 기술 제품들이 남겨져 있군요...",
  ui_story_1014_10141302_34_dialog_content = "만물은 백야 아래에. 부디 이 물건들이 사람들한테 위협이 되지 않았으면 좋겠네요.",
  ui_story_1014_10141302_35_dialog_content = "<color=#e8d9bb>삐비빅──</color>",
  ui_story_1014_10141302_36_dialog_content = "여기는 더스크 타운 강철가시 기사단 본부입니다.\n원정 기사 레오, 이 메시지가 들린다면 응답 바랍니다.",
  ui_story_1014_10141302_37_dialog_content = "원정 기사 레오다. 무슨 일인가?",
  ui_story_1014_10141302_38_dialog_content = "현재 위치와 임무 진척 상황을 보고 바랍니다.",
  ui_story_1014_10141302_39_dialog_content = "현 위치는 오로라 유적의 콜로서스 내부,\n아이테르 PlayerName 보호 임무를 수행 중이다.",
  ui_story_1014_10141302_40_dialog_content = "카렌 전하와 일루미나에서 온 오로리안 수 명도 동행 중이다.",
  ui_story_1014_10141302_41_dialog_content = "카렌 전하 말입니까... 알겠습니다.",
  ui_story_1014_10141302_42_dialog_content = "계속 임무를 수행하십시오.\n만약 뜻밖의 상황이 발생한다면 곧바로 강철가시 기사단에 증원 요청 바랍니다.",
  ui_story_1014_10141302_43_dialog_content = "알겠다.",
  ui_story_1014_10141302_44_dialog_content = "그럼 행운을 빌겠습니다. 통신 종료.",
  ui_story_1014_10141302_45_dialog_content = "강철가시 기사단에 증원 요청을 하라는 게 무슨 뜻이지?",
  ui_story_1014_10141302_46_dialog_content = "일 년 내내 밖에서 조사를 하러 다니는 원정 기사보다는\n더스크 타운 주둔 기사단이 더 많은 병력과 장비를 갖추고 있을 텐데.",
  ui_story_1014_10141302_47_dialog_content = "어째서 주둔 기사단이 아닌 강철가시 기사단에 증원을 요청하라는 거지?",
  ui_story_1014_10141302_48_dialog_content = "카렌 전하, 보시다시피 강철가시 기사단과 주둔 기사단 사이에는 약간의 틈이 있습니다.",
  ui_story_1014_10141302_49_dialog_content = "원정 기사들은 대부분 평민이나 유배된 귀족 가문 출신입니다.\n주둔 기사들과는 신분의 차이가 있죠.",
  ui_story_1014_10141302_50_dialog_content = "설령 지원을 요청한다 하더라도, 자신들보다 신분이 미천한 저희의 의견을\n진지하게 받아들여 주는 경우는 거의 없습니다.",
  ui_story_1014_10141302_51_dialog_content = "그렇기 때문에 저희는 원정 기사로서의 모든 일을 스스로의 힘으로\n해결하는 게 습관이 되어 버렸습니다.",
  ui_story_1014_10141302_52_dialog_content = "그런 일이...",
  ui_story_1014_10141302_53_dialog_content = "향후에 내가 이 일을 백야성 상부에 전달하겠어.",
  ui_story_1014_10141302_54_dialog_content = "신분이 다르다 하더라도 모두 백야성의 주민인 이상,\n이런 차별이 존재해서는 안 돼.",
  ui_story_1014_10141302_55_dialog_content = "열린 생각을 가지고 있어 주셔서 기쁩니다.\n하지만... 그다지 성과가 있을 것 같지는 않군요.",
  ui_story_1014_10141302_56_dialog_content = "귀족과 평민 사이에 존재하는 차이가 사라지지 않는 이상,\n이런 차별과 갈등은 사라지지 않을 테니까요.",
  ui_story_1014_10141302_57_dialog_content = "저처럼 유배된 귀족 가문 출신은 이 사실이 제일 가슴에 와닿을 겁니다.",
  ui_story_1014_10141302_58_dialog_content = "...난 예전에도 단장처럼 유배된 귀족 가문 출신인 사람들을 몇 명 만난 적이 있어.",
  ui_story_1014_10141302_59_dialog_content = "모두 자신의 현재 상황에 대해 많든 적든 불만을 가지고 있었지.",
  ui_story_1014_10141302_60_dialog_content = "레오 단장, 당신도 그런가?",
  ui_story_1014_10141302_61_dialog_content = "제 생각이 궁금하신 겁니까?",
  ui_story_1014_10141302_62_dialog_content = "음... 확실히 그렇습니다.",
  ui_story_1014_10141302_63_dialog_content = "저는 과거에 백야성 안에서 호의호식하던 귀족이었습니다.",
  ui_story_1014_10141302_64_dialog_content = "그 당시의 저는 기사라는 이름으로 적진에 깊숙이 돌격했고,\n백야성을 지키는 것을 가장 큰 명예로 여겼습니다.",
  ui_story_1014_10141302_65_dialog_content = "그러나 유배를 당한 후엔 더스크 타운의 이름 없는 평민이 되어 버렸죠.",
  ui_story_1014_10141302_66_dialog_content = "과거의 명예와, 백야성을 지키기 위해선 죽음도 불사하겠다는 신념으론\n말라비틀어진 빵 하나도 손에 넣을 수 없었습니다.",
  ui_story_1014_10141302_67_dialog_content = "그래서 그 격차에 좌절했나?",
  ui_story_1014_10141302_68_dialog_content = "부정하진 않겠습니다.",
  ui_story_1014_10141302_69_dialog_content = "하지만 더스크 타운으로 유배를 당한 덕분에, 전 진정으로 믿을 수 있는 건\n자기 자신의 힘뿐이라는 사실을 깨닫게 되었습니다.",
  ui_story_1014_10141302_70_dialog_content = "심사에 통과해 원정 기사가 되고, 더스크 타운에서 좀 지내다 보니\n제 마음가짐도 변하게 됐습니다.",
  ui_story_1014_10141302_71_dialog_content = "전 생각했던 것처럼 나쁘지만은 않다고 생각합니다.",
  ui_story_1014_10141302_72_dialog_content = "적어도 더스크 타운에서만큼은, 서로 다른 세력에 속한 오로리안이라도\n잠시 진영간의 대립은 잊은 채 사이좋게 지낼 수 있으니 말이지요.",
  ui_story_1014_10141302_73_dialog_content = "저는 사람들과 힘을 합쳐 암귀에 맞서는 이런 분위기를 좋아합니다.\n하지만... 여전히 전 불공평하다고 생각합니다.",
  ui_story_1014_10141302_74_dialog_content = "어떤 점 때문이지? 말해 줬으면 해.",
  ui_story_1014_10141302_75_dialog_content = "제 의견이 카렌 전하께 무슨 도움이 되는 거죠?",
  ui_story_1014_10141302_76_dialog_content = "난 더 많은 사람의 의견을 듣고, 백야성의 제도와 법률을 개선하고 싶어.",
  ui_story_1014_10141302_77_dialog_content = "백야성의 모든 이가 진정으로 공정한 판결을 받을 수 있도록 말이야.",
  ui_story_1014_10141302_78_dialog_content = "저는...",
  ui_story_1014_10141302_79_dialog_content = "<color=#e8d9bb>삐빅──</color>",
  ui_story_1014_10141302_80_dialog_content = "<color=#e8d9bb>알림: 콜로서스 인격 데이터 복사가 완료됐습니다. 이제 연결을 해제해도 됩니다.</color>",
  ui_story_1014_10141302_81_dialog_content = "PlayerName! 데이터 복사가 다 된 것 같아!",
  ui_story_1014_10141302_82_dialog_content = "얼른 챙겨서 돌아가자!",
  ui_story_1014_10141302_83_dialog_content = "응! 그래!",
  ui_story_1014_10141302_84_dialog_content = "(알골 씨 장치한테 고마워해야겠는걸...)",
  ui_story_1014_10141302_85_dialog_content = "(카렌이랑 레오 단장이 계속 대화하게 내버려 뒀다간 둘이 싸웠을지도 몰라!)",
  ui_story_1014_10141302_86_dialog_content = "<color=#e8d9bb>콰르릉!</color>",
  ui_story_1014_10141302_87_dialog_content = "풉... 콜록, 콜록! 뭐지?!",
  ui_story_1014_10141302_88_dialog_content = "<color=#e8d9bb>쿠구구구!</color>",
  ui_story_1014_10141302_89_dialog_content = "PlayerName! 이 콜로서스가 진동하고 있습니다!",
  ui_story_1014_10141302_90_dialog_content = "설마... 콜로서스가 또 폭주하려는 걸까요?!",
  ui_story_1014_10141302_91_dialog_content = "폭주요?!",
  ui_story_1014_10141302_92_dialog_content = "PlayerName, 얼른 장치를 챙겨서 나가자!",
  ui_story_1014_10141302_93_dialog_content = "진동이 너무 심해. 어쩌면 콜로서스가 해체되거나 붕괴할 수도 있어!",
  ui_story_1014_10141302_94_dialog_content = "얼른 여길 떠나야 해!",
  ui_story_1014_10141302_95_dialog_content = "<color=#e8d9bb>쿠구구구──!</color>",
  ui_story_1014_10141302_96_dialog_content = "이런!",
  ui_story_1014_10141302_97_dialog_content = "이 콜로서스는 더스크 타운과 그리 멀지 않은 곳에 있습니다.\n만약 정말로 폭주하고 있는 거라면, 더스크 타운에도 영향을 미칠 겁니다!",
  ui_story_1014_10141302_98_dialog_content = "더스크 타운에는 기사와 군인들 외에도 힘없는 평민들이 많이 있어요!",
  ui_story_1014_10141302_99_dialog_content = "어떻게든 이 콜로서스가 폭주하지 않도록 막아야 해요!",
  ui_story_1014_10141302_100_dialog_content = "하지만...",
  ui_story_1014_10141302_101_option_content = "내가 방법을 생각해 볼게!",
  ui_story_1014_10141302_102_dialog_content = "이 콜로서스는 아이테르의 유물이야.",
  ui_story_1014_10141302_103_dialog_content = "그러니까 이 콜로서스의 폭주를 막을 수 있는 건 아마 아이테르만 가능할 거야!",
  ui_story_1014_10141302_104_dialog_content = "바이스, 카렌, 부탁이야. 내가 이 콜로서스의 폭주를 막을 수 있게 도와줘!",
  ui_story_1014_10141302_105_dialog_content = "물론이지!",
  ui_story_1014_10141302_106_dialog_content = "알겠어.",
  ui_story_1014_10141302_107_dialog_content = "고마워, 그럼 시작할게.",
  ui_story_1014_10141302_108_dialog_content = "(강제 감응!)",
  ui_story_1014_10141401_1_dialog_content = "<color=#e8d9bb>지지직──</color>",
  ui_story_1014_10141401_2_dialog_content = "패스파인더호!",
  ui_story_1014_10141401_3_dialog_content = "<color=#e8d9bb>패스파인더호, 지시를 기다리고 있습니다.</color>",
  ui_story_1014_10141401_4_dialog_content = "지금 하고 있는 게 뭐든 빨리 멈춰!",
  ui_story_1014_10141401_5_dialog_content = "폭주하면 안 돼! 수많은 무고한 생명들이 말려들고 말 거야!",
  ui_story_1014_10141401_6_dialog_content = "<color=#e8d9bb>폭주와 관련된 자료를 찾고 있습니다.</color>",
  ui_story_1014_10141401_7_dialog_content = "<color=#e8d9bb>패스파인더호는 지금까지 폭주 행위를 일으킨 적이 없습니다.</color>",
  ui_story_1014_10141401_8_dialog_content = "지금까지 단 한 번도 폭주한 적이 없다고? 그렇다면 잉겔이 말했던 마지막 폭주란 건...",
  ui_story_1014_10141401_9_dialog_content = "<color=#e8d9bb>마지막 작동 정보를 검색 중입니다.</color>",
  ui_story_1014_10141401_10_dialog_content = "<color=#e8d9bb>당시 패스파인더호는 루미나 생명체의 잘못된 조작으로 방어 모드에 진입했습니다.</color>",
  ui_story_1014_10141401_11_dialog_content = "<color=#e8d9bb>패스파인더호는 데이터를 보호하기 위해, 필요에 의한 회피를 진행했습니다.</color>",
  ui_story_1014_10141401_12_dialog_content = "<color=#e8d9bb>해당 기간에 패스파인더호는 그 어떤 생명체도 해치지 않았습니다.</color>",
  ui_story_1014_10141401_13_dialog_content = "그럼 조금 전에 막 흔들리던 건 폭주 때문이 아니야?",
  ui_story_1014_10141401_14_dialog_content = "<color=#e8d9bb>패스파인더호의 동력 시스템이 심각하게 훼손돼 더는 기동할 수 없습니다.</color>",
  ui_story_1014_10141401_15_dialog_content = "<color=#e8d9bb>진동은 외부적 요인으로 발생한 것으로 추측됩니다.\n콜로서스 외부 영상에 접근 중입니다.</color>",
  ui_story_1014_10141401_16_dialog_content = "『이것은 욕망의 감옥이자, 욕망을 담는 용기랍니다.』",
  ui_story_1014_10141401_17_dialog_content = "『욕망은 세계를 구축하기도, 세계를 파괴하기도 하죠.』",
  ui_story_1014_10141401_18_dialog_content = "『그러니 욕망이 범람하기 전에, 저들을 깨끗하게 쓸어버리세요.』",
  ui_story_1014_10141401_19_dialog_content = "암귀가 뭐 저렇게 많아?!",
  ui_story_1014_10141401_20_dialog_content = "암귀 무리 중간에 있는 게 암귀들을 지휘하고 있는 녀석이겠지?",
  ui_story_1014_10141401_21_dialog_content = "『아스모데우스 님, 오로리안들이 밖으로 나오질 않습니다.』",
  ui_story_1014_10141401_22_dialog_content = "『저들의 욕망이 결국 저들을 우리에게로 인도해 줄 거예요.』",
  ui_story_1014_10141401_23_dialog_content = "『왜냐하면 저들은 벌써...』",
  ui_story_1014_10141401_24_dialog_content = "『우릴 보았거든요.』",
  ui_story_1014_10141401_25_dialog_content = "!!!",
  ui_story_1014_10141401_26_dialog_content = "PlayerName, 괜찮아?!",
  ui_story_1014_10141401_27_dialog_content = "얼굴이 왜 하얗게 질렸어?",
  ui_story_1014_10141401_28_dialog_content = "방금 그 진동은 콜로서스가 폭주한 게 아니라, 밖에 있는 암귀들 때문이었어!",
  ui_story_1014_10141401_29_dialog_content = "그리고 방금 영상으로 콜로서스의 외부 상황을 확인하다가 엄청 강한 암귀를 봤어...",
  ui_story_1014_10141401_30_dialog_content = "게다가 그 암귀도 영상 너머로 날 본 것만 같았어.",
  ui_story_1014_10141401_31_dialog_content = "그게 가능해? 설마 그 녀석도 노라처럼 강하다는 거야?",
  ui_story_1014_10141401_32_dialog_content = "<color=#e8d9bb>콰르릉!</color>",
  ui_story_1014_10141401_33_dialog_content = "<color=#e8d9bb>경고. 콜로서스 내부에 권한이 없는 생명체가 진입했습니다.</color>",
  ui_story_1014_10141401_34_dialog_content = "매우 강한 암귀가 왔습니다. 모두 조심하세요!",
  ui_story_1014_10141401_35_dialog_content = "정말 소란스럽군요. 게다가 소음뿐만 아니라 욕망의 냄새가 느껴지네요.",
  ui_story_1014_10141401_36_dialog_content = "권력을 향한 욕망.",
  ui_story_1014_10141401_37_dialog_content = "인정을 갈망하는 욕망.",
  ui_story_1014_10141401_38_dialog_content = "그리고... 어머, 이건...",
  ui_story_1014_10141401_39_dialog_content = "동료를 구하고자 하는 욕망이 있네요.",
  ui_story_1014_10141401_40_dialog_content = "넌 누구야?! 뭘 하려는 거지?",
  ui_story_1014_10141401_41_dialog_content = "저 말인가요? 오호, 당신도 제게 욕망을 품고 있나요?",
  ui_story_1014_10141401_42_dialog_content = "저는 아스모데우스랍니다.\n욕망을 위해 살고, 이 세상의 모든 욕망을 파멸시킬 운명을 지니고 있지요.",
  ui_story_1014_10141401_43_dialog_content = "그럼 제가 당신의 욕망을 파괴해 드리도록 하죠!",
  ui_story_1014_10141401_44_dialog_content = "목숨을 걸고 지키려는 욕망은 대체 무엇일까요? 정말 파괴해 보고 싶네요.",
  ui_story_1014_10141401_45_dialog_content = "꿈 깨시지!",
  ui_story_1014_10141401_46_dialog_content = "카렌!",
  ui_story_1014_10141401_47_dialog_content = "녀석은 강합니다. 모두 같이 공격하죠!",
  ui_story_1014_10141401_48_dialog_content = "암귀 녀석! 카렌 님한테서 떨어져!",
  ui_story_1014_10141401_49_dialog_content = "욕망... 하나같이 미약한 욕망들이로군요...",
  ui_story_1014_10141401_50_dialog_content = "고작 그것들만 가지고는 그 무엇도 이룰 수 없답니다.",
  ui_story_1014_10141401_51_dialog_content = "과도한 욕망은 때론 독이 되곤 하지요.\n암귀 양... 아니, 당신은 <color=#FFB400>팬텀</color>이겠군요.",
  ui_story_1014_10141401_52_dialog_content = "맞아요. 욕망이란 건 좋은 게 아니에요.\n제가 욕망을 파멸시키고자 한 이유도 바로 그래서랍니다.",
  ui_story_1014_10141401_53_dialog_content = "하지만 욕망만을 없애는 건 너무나도 힘겨운 일이에요\n 이 세상에 오로리안이 계속 존재하는 이상, 욕망은 소멸되지 않을 테니까요.",
  ui_story_1014_10141401_54_dialog_content = "그렇기에 욕망을 만들어내는 오로리안들부터 없앨 수밖에요.",
  ui_story_1014_10141401_55_dialog_content = "배신자인 아이테르도 함께 사라져야겠죠.",
  ui_story_1014_10141401_56_dialog_content = "PlayerName에게 피해를 입히는 것을 악셀리아는 허락하지 않습니다.",
  ui_story_1014_10141401_57_dialog_content = "음? 설마 그게 당신의 욕망인가요?",
  ui_story_1014_10141401_58_dialog_content = "악셀리아의 임무는 PlayerName의 보호입니다.",
  ui_story_1014_10141401_59_dialog_content = "이건 정말 드문 경우네요. 당신, 욕망이 없군요.",
  ui_story_1014_10141401_60_dialog_content = "아니, 틀려요.",
  ui_story_1014_10141401_61_dialog_content = "당신이라는 존재 자체가 곧 욕망의 결정체였군요. 그래서 그렇게 강할 수 있었던 거였네요.",
  ui_story_1014_10141401_62_dialog_content = "후훗... 굉장히 재미있군요.",
  ui_story_1014_10141401_63_dialog_content = "그런 욕망을 파괴하면 과연 어떤 광경을 보여줄까요?",
  ui_story_1014_10141401_64_dialog_content = "정말이지 너무나도 기대가 되네요!",
  ui_story_1014_10141401_65_dialog_content = "다들 조심해! 암귀들이 움직이기 시작했어!",
  ui_story_1014_10141402_1_dialog_content = "으윽!",
  ui_story_1014_10141402_2_dialog_content = "악셀리아!",
  ui_story_1014_10141402_3_dialog_content = "악셀리아는... 아직 싸울 수 있습니다.",
  ui_story_1014_10141402_4_dialog_content = "억지 부리지 마. 지금 너한테 가장 필요한 건 치료야!",
  ui_story_1014_10141402_5_dialog_content = "흥이 깨졌네요.",
  ui_story_1014_10141402_6_dialog_content = "일루미나의 모든 욕망이 응축된 결정체가 고작 연약한 계집애라니.",
  ui_story_1014_10141402_7_dialog_content = "너무나도 실망스러워요.\n지금의 오로리안들에겐 고작 이따위 무가치한 욕망만 남은 건가요?",
  ui_story_1014_10141402_8_dialog_content = "정말이지 이해가 되질 않네요.",
  ui_story_1014_10141402_9_dialog_content = "노라는 왜 이런 언급할 가치조차 없는 것들에 그토록 집착하는 걸까요?",
  ui_story_1014_10141402_10_dialog_content = "그딴 식으로 악셀리아를 흉보지 마!",
  ui_story_1014_10141402_11_dialog_content = "자신의 나약함을 아직도 인정할 수 없나요?",
  ui_story_1014_10141402_12_dialog_content = "그럼 이건 어떨까요?",
  ui_story_1014_10141402_13_dialog_content = "상황이 안 좋습니다. 암귀들이 더 많이 다가오고 있어요.",
  ui_story_1014_10141402_14_dialog_content = "조셀린, 요제프. 왼쪽에서 오는 소형 암귀들의 기습에 주의하세요!",
  ui_story_1014_10141402_15_dialog_content = "알겠어요!\n알겠습니다.",
  ui_story_1014_10141402_16_dialog_content = "잉겔, 숀. 두 사람은 우측에 있는 대형 암귀를 맡아 주세요!",
  ui_story_1014_10141402_17_dialog_content = "잠깐만요, 어째서 우리가 당신 말을 들어야 하죠?",
  ui_story_1014_10141402_18_dialog_content = "<anim type=Shake><size=45>그어어어!</size></anim>",
  ui_story_1014_10141402_19_dialog_content = "이쪽에 있는 녀석들은 저희한테 맡기세요!",
  ui_story_1014_10141402_20_dialog_content = "정말 어쩔 수 없군요.",
  ui_story_1014_10141402_21_dialog_content = "남은 사람들은 함께 이 녀석을 상대합시다!",
  ui_story_1014_10141402_22_dialog_content = "당신들의 욕망은 끝까지 이 정도에 불과하군요.",
  ui_story_1014_10141402_23_dialog_content = "욕망이 강할수록 힘도 강해지죠.",
  ui_story_1014_10141402_24_dialog_content = "당신들이 품고 있는 욕망이 평범하고 보잘것없기 때문에,\n당신들이 이렇게 변변치 못한 거예요.",
  ui_story_1014_10141402_25_dialog_content = "제 욕망은 무려 이 세상의 모든 욕망을 파괴하는 것인데 말이에요!",
  ui_story_1014_10141402_26_dialog_content = "PlayerName, 얼른 피해!",
  ui_story_1014_10141402_27_dialog_content = "뭐?!",
  ui_story_1014_10141402_28_dialog_content = "제 손아귀에서 빠져나갈 수 있는 욕망은 존재하지 않아요.",
  ui_story_1014_10141402_29_dialog_content = "쳇!",
  ui_story_1014_10141402_30_dialog_content = "PlayerName!",
  ui_story_1014_10141402_31_dialog_content = "으윽! 아파...",
  ui_story_1014_10141402_32_dialog_content = "이런... 장치가!",
  ui_story_1014_10141402_33_dialog_content = "평범하고 보잘것없는 욕망 따위가 제 앞을 가로막지 마세요.",
  ui_story_1014_10141402_34_dialog_content = "크윽!",
  ui_story_1014_10141402_35_dialog_content = "(얼른 장치를 챙겨야 해!)",
  ui_story_1014_10141402_36_dialog_content = "으윽?!",
  ui_story_1014_10141402_37_dialog_content = "이건 당신의 욕망이었군요, 아이테르의 배신자.",
  ui_story_1014_10141402_38_dialog_content = "......",
  ui_story_1014_10141402_39_dialog_content = "고작 이것뿐인가요?",
  ui_story_1014_10141402_40_dialog_content = "그거 내려 놔!",
  ui_story_1014_10141402_41_dialog_content = "따분하네요.",
  ui_story_1014_10141402_42_dialog_content = "대체 뭐라는 거야?!",
  ui_story_1014_10141402_43_dialog_content = "따분해요. 무료해요. 정말이지 아무런 재미도 없네요.",
  ui_story_1014_10141402_44_dialog_content = "배신자, 당신의 욕망은 고작 오류로 생겨난 이 쓰레기 더미들에 국한된 건가요?",
  ui_story_1014_10141402_45_option_content = "쓰레기가 아니야!",
  ui_story_1014_10141402_46_dialog_content = "그 데이터들은 기적이라고!",
  ui_story_1014_10141402_47_dialog_content = "콜로서스들이 오랜 시간 동안 끊임없이 시도하고...\n수많은 경험을 쌓아 완성된 인격이야...",
  ui_story_1014_10141402_48_dialog_content = "욕망 타령이나 하는 너처럼 평범하고 보잘것없는 녀석은\n그 데이터들이 얼마나 소중한 건지 이해조차 못하겠지!",
  ui_story_1014_10141402_49_dialog_content = "후훗... 평범하고 보잘것없다?",
  ui_story_1014_10141402_50_dialog_content = "배신자가 저와 같은 관점을 가지고 있을 줄은 몰랐네요.",
  ui_story_1014_10141402_51_dialog_content = "맞아요. 욕망은 모두 평범하고 보잘것없어요.\n너무 하찮은 나머지 이 세상에 존재하지 않아야 할 정도로요.",
  ui_story_1014_10141402_52_dialog_content = "암귀는 욕망이 없죠. 그래서 유혹당하지 않아요.\n그러니 암귀야말로 이 세상에 더 적합한 완전생물인 거예요.",
  ui_story_1014_10141402_53_dialog_content = "그리고 제가 팬텀이 되기로 한 것도, 바로 욕망을 버리기 위해서랍니다.",
  ui_story_1014_10141402_54_dialog_content = "PlayerName, 저런 헛소리는 들어줄 필요 없어.",
  ui_story_1014_10141402_55_dialog_content = "모두 같이 공격해서 장치를 되찾아 오자!",
  ui_story_1014_10141402_56_dialog_content = "그렇지만... 됐어요. 생각이 바뀌었어요.",
  ui_story_1014_10141402_57_dialog_content = "이 장치를 그렇게나 원하는 거면, 그냥 줄게요.",
  ui_story_1014_10141402_58_dialog_content = "앗! 장치가!",
  ui_story_1014_10141402_59_dialog_content = "휴, 아슬아슬했어...",
  ui_story_1014_10141402_60_dialog_content = "(일단 겉으론 부서진 부분 없이 멀쩡해 보여.)",
  ui_story_1014_10141402_61_dialog_content = "(이 녀석의 목적은 대체 뭐지? 그냥 우리를 비웃으려는 건가?)",
  ui_story_1014_10141402_62_dialog_content = "당신들의 욕망이 충분히 강할 줄 알았는데, 지금 보니 제가 틀렸네요.",
  ui_story_1014_10141402_63_dialog_content = "당신들이 바라던 것도 별 쓸모도 없는 폐품에 지나지 않았고요.",
  ui_story_1014_10141402_64_dialog_content = "그런 욕망은 파괴할 마음조차 안 들어요.",
  ui_story_1014_10141402_65_dialog_content = "어디서 입을 함부로 놀려!",
  ui_story_1014_10141402_66_dialog_content = "장치도 PlayerName한테 돌려준 이상, 이젠 참을 필요도 없겠네.",
  ui_story_1014_10141402_67_dialog_content = "받아라! 암귀!",
  ui_story_1014_10141402_68_dialog_content = "충성은 가장 쓸모없는 욕망이랍니다.",
  ui_story_1014_10141402_69_dialog_content = "...강해!",
  ui_story_1014_10141402_70_dialog_content = "지금까진 조금도 힘을 안 썼다는 거야?!",
  ui_story_1014_10141402_71_dialog_content = "<anim type=Shake><size=45>그어어어!</size></anim>",
  ui_story_1014_10141402_72_dialog_content = "베르타, 위험해!\n얼어붙어라!",
  ui_story_1014_10141402_73_dialog_content = "정말이지 너무나도 실망스럽네요...",
  ui_story_1014_10141402_74_dialog_content = "이곳엔 따분한 욕망뿐이라서, 파괴할 의욕조차 들지를 않네요.",
  ui_story_1014_10141402_75_dialog_content = "하지만 당신, 아이테르의 배신자, PlayerName.",
  ui_story_1014_10141402_76_dialog_content = "......",
  ui_story_1014_10141402_77_dialog_content = "어쩌면 당신에게 조금만 시간을 더 주면,\n당신의 욕망은 무척 재미있게, 무척... 맛있게 변할지도 모르겠네요.",
  ui_story_1014_10141402_78_dialog_content = "물론 당신도 마찬가지예요, <color=#FFB400>바이스</color>.",
  ui_story_1014_10141402_79_dialog_content = "...나?",
  ui_story_1014_10141402_80_dialog_content = "암귀들이여, 돌아가죠.",
  ui_story_1014_10141402_81_dialog_content = "이제 여긴 더 머무를 가치도 없어요.",
  ui_story_1014_10141402_82_dialog_content = "그냥 도망갈 생각은 꿈도 꾸지 마!",
  ui_story_1014_10141402_83_dialog_content = "성급하게 달려들면 안 됩니다, 베르타!",
  ui_story_1014_10141402_84_dialog_content = "저 여자는 평범한 암귀가 아닙니다.\n우리가 사력을 다해 싸운다 해도 기껏해야 지지 않는 게 전부겠죠.",
  ui_story_1014_10141402_85_dialog_content = "지금 우리에겐 저 암귀들을 쫓을 여력은 없습니다.\n지금 가장 시급한 건 후퇴하고 지원을 요청하는 겁니다.",
  ui_story_1014_10141402_86_dialog_content = "하지만...",
  ui_story_1014_10141402_87_dialog_content = "베르타, 레오 단장의 판단이 정확해. 이 상태로 계속 추격하는 건 좋지 않아.",
  ui_story_1014_10141402_88_dialog_content = "우선은 더스크 타운으로 돌아가자.",
  ui_story_1014_10141402_89_dialog_content = "...네.",
  ui_story_1014_10141402_90_dialog_content = "기사장님, 제 뜻을 이해해 주셔서 감사합니다.",
  ui_story_1014_10141402_91_dialog_content = "전장에 익숙한 사람이라면 모두 같은 결론을 내렸을 거야.",
  ui_story_1014_10141402_92_dialog_content = "(노라가 나타나지 않았는데, 다른 팬텀이 모습을 드러내다니...)",
  ui_story_1014_10141402_93_dialog_content = "(이건 우연일까요, 아니면 필연일까요.)",
  ui_story_1014_10141402_94_dialog_content = "(어쨌든 이번 임무는 실패로 끝내게 됐군요.\n노라는 예상처럼 모습을 드러내지 않았습니다.)",
  ui_story_1014_10141402_95_dialog_content = "(노라와 헬리오스의 행방을 쫓는 임무는\n다른 방법으로 완수하는 수밖에 없겠네요.)",
  ui_story_1014_10141402_95X1_dialog_content = "그냥 이렇게 가는 거야? 패스파인더호를 이렇게 여기 놔두고...",
  ui_story_1014_10141402_95X2_dialog_content = "같이 돌아갈 방법은 없을까? 바이스, 일루미나의 기술로 고칠 순 없는 거야?",
  ui_story_1014_10141402_95X3_dialog_content = "그건... 힘들지 않을까...",
  ui_story_1014_10141402_95X4_dialog_content = "......",
  ui_story_1014_10141402_95X5_dialog_content = "PlayerName, 당신의 마음은 이해해요.\n하지만 그건 지금의 우리로서는 해낼 수 없는 일이에요.",
  ui_story_1014_10141402_95X6_dialog_content = "잉겔, 이 콜로서스는 PlayerName한테 무척 중요할 거야.\n정말 어떤 방법도 없는 거야?",
  ui_story_1014_10141402_95X7_dialog_content = "이 콜로서스는 애초에 망가져 있었습니다.\n지난번 폭주로 인한 두 번째 피해는 말할 것도 없겠죠.",
  ui_story_1014_10141402_95X8_dialog_content = "지금도 가동하고 있는 것도 기적이나 마찬가지예요...",
  ui_story_1014_10141402_95X9_dialog_content = "어째서...",
  ui_story_1014_10141402_95X10_dialog_content = "<color=#e8d9bb>아이테르가 곧 떠날 것임을 감지했습니다.</color>",
  ui_story_1014_10141402_95X11_dialog_content = "패스파인더호?",
  ui_story_1014_10141402_95X12_dialog_content = "<color=#e8d9bb>패스파인더호가 아이테르 PlayerName에게 질문을 발송합니다.</color>",
  ui_story_1014_10141402_95X13_dialog_content = "<color=#e8d9bb>아이테르 PlayerName, 다음 방문 시간과 패스파인더호 수리 계획을 알려 주십시오.</color>",
  ui_story_1014_10141402_95X14_dialog_content = "......",
  ui_story_1014_10141402_95X15_dialog_content = "...모르겠어...",
  ui_story_1014_10141402_95X16_dialog_content = "미안해... 또 널 계속 기다리게 만들어야 할 것 같아...",
  ui_story_1014_10141402_95X17_dialog_content = "<color=#e8d9bb>명령을 접수했습니다.</color>",
  ui_story_1014_10141402_95X18_dialog_content = "<color=#e8d9bb>35의 설정에 따라 이곳에서 아이테르 PlayerName에게 축복을 보냅니다.</color>",
  ui_story_1014_10141402_95X19_dialog_content = "<color=#e8d9bb>패스파인더호를 고칠 수 없어 괴로워하지 마시고,\n앞으로 나아갈 방향에 당신의 시선을 두십시오.</color>",
  ui_story_1014_10141402_95X20_dialog_content = "뭐? 그게 35의 메시지야? 그 사람은 이런 일까지 생각했단 말이야?!",
  ui_story_1014_10141402_95X21_dialog_content = "<color=#e8d9bb>패스파인더호는 35와 함께 PlayerName의 순조로운 여정을 기원하겠습니다.</color>",
  ui_story_1014_10141402_95X22_dialog_content = "고마워...",
  ui_story_1014_10141402_95X23_dialog_content = "알겠어, 너와 그 사람 몫까지 내가 계속해서 나아갈게...",
  ui_story_1014_10141402_95X24_dialog_content = "PlayerName, 가자.",
  ui_story_1014_10141402_95X25_dialog_content = "응, 가자. 우린 아직 해야 할 일이 남아 있으니까.",
  ui_story_1014_10141402_96_dialog_content = "<color=#e8d9bb>스카이워커호, 함교</color>",
  ui_story_1014_10141402_97_dialog_content = "스카이워커, 기동!",
  ui_story_1014_10141402_98_dialog_content = "그 암귀들은요? 뒤쫓아오진 않았나요?",
  ui_story_1014_10141402_99_dialog_content = "감응해도 아무것도 안 느껴지니까, 아마 이 근처엔 없을 거야.",
  ui_story_1014_10141402_100_dialog_content = "녀석들이 대체 무슨 꿍꿍이인지는 모르겠지만,\n아무래도 얕잡아 보인 것 같다는 느낌이 드네.",
  ui_story_1014_10141402_101_dialog_content = "하지만 녀석들은 언젠가는 우리를 얕잡아 본 대가를 치르게 될 거야.",
  ui_story_1014_10141402_102_dialog_content = "악셀리아, 다친 덴 좀 어때? 아까 암귀한테 그렇게 심하게 공격을 받았잖아...",
  ui_story_1014_10141402_103_dialog_content = "악셀리아는 괜찮습니다.",
  ui_story_1014_10141402_104_dialog_content = "비록 악셀리아의 몸은 약하지만... 콜록, 쉽게 쓰러지진 않을 겁니다.",
  ui_story_1014_10141402_105_dialog_content = "(그런 점도 개조로 인한 결과인 건가?)",
  ui_story_1014_10141402_107_dialog_content = "(그래도 라인하르트 씨가 이 실험을 단호하게 반대한 건\n분명히 자신만의 이유가 있어서겠지.)",
  ui_story_1014_10141402_109_dialog_content = "(그러고 보면 라인하르트 씨도 일반인들을 훨씬 뛰어넘는\n전투력과 회복력을 가지고 있잖아...)",
  ui_story_1014_10141402_110_dialog_content = "PlayerName, 무슨 생각해?",
  ui_story_1014_10141402_111_dialog_content = "어? 아, 아무것도 아니야.",
  ui_story_1014_10141402_112_dialog_content = "왜 그래? 바이스.",
  ui_story_1014_10141402_113_dialog_content = "그냥... 이해가 안 되는 것들이 좀 있어서.",
  ui_story_1014_10141402_114_dialog_content = "그 아스모데우스라는 암귀 있잖아. 마지막에 왜 내 얘길 꺼낸 걸까?",
  ui_story_1014_10141402_115_dialog_content = "아무리 생각해도 난 그 암귀를 몰라. 내 이름은 더더욱 말해 준 적 없고.",
  ui_story_1014_10141402_116_option_content = "설마 화음 연결 때문인가?",
  ui_story_1014_10141402_117_dialog_content = "바이스 넌 화음 연결로 특별한 힘을 얻었잖아.",
  ui_story_1014_10141402_118_dialog_content = "그 녀석도 그 점을 눈치채고 너한테 관심을 보인 걸지도 몰라.",
  ui_story_1014_10141402_119_dialog_content = "모르겠어...",
  ui_story_1014_10141402_120_dialog_content = "그 녀석의 동기가 도저히 이해가 안 돼.",
  ui_story_1014_10141402_121_option_content = "설마 네 몸 상태 때문인가?",
  ui_story_1014_10141402_122_dialog_content = "화음 연결 장치를 사용하고 나서부터 네 몸 상태는 좀 특별한 상황이었잖아.",
  ui_story_1014_10141402_123_dialog_content = "몸에서 빛이 났던 것도 다 그 장치 때문이었고.",
  ui_story_1014_10141402_124_dialog_content = "그래도 겉으로 봤을 땐 무슨 변화가 있는지 별로 티가 안 나잖아.",
  ui_story_1014_10141402_125_dialog_content = "설마 그 녀석은 내부의 변화를 관찰할 수 있는 특별한 능력이 있는 걸까?",
  ui_story_1014_10141402_126_dialog_content = "알 수 없지...",
  ui_story_1014_10141402_127_dialog_content = "일단 그 얘긴 나중에 다시 하자. 아무튼 컨디션은 좀 어때, 바이스?",
  ui_story_1014_10141402_128_dialog_content = "너무 많은 전투를 겪었잖아. 혹시 어디 불편한 곳 있어?",
  ui_story_1014_10141402_129_dialog_content = "걱정하지 마. 그냥 조금 피곤한 정도라, 잠깐 쉬면 바로 회복될 거야.",
  ui_story_1014_10141402_130_dialog_content = "아무래도 힘든 전투를 치러도 내 몸이 나빠지거나 그러진 않는 것 같아.",
  ui_story_1014_10141402_131_dialog_content = "그래? 그럼 다행이네.",
  ui_story_1014_10141402_132_dialog_content = "이제 남은 건 자난성으로 돌아가서 우리가 얻은 부품과 데이터로\n스카이워커를 복구하는 거야!",
  ui_story_1014_10141402_133_dialog_content = "그 전에 악셀리아 일행도 더스크 타운에 데려다줘야 해.",
  ui_story_1014_10141402_134_dialog_content = "응!",
  ui_story_1014_10141402_135_dialog_content = "<color=#e8d9bb>지지직──</color>",
  ui_story_1014_10141402_136_dialog_content = "어? 스카이워커가 원거리 통신 신호를 수신했어.\n발신자는... 패스파인더호잖아?!",
  ui_story_1014_10141402_137_dialog_content = "<color=#e8d9bb>지지직──</color>",
  ui_story_1014_10141402_137X1_dialog_content = "<color=#e8d9bb>35의 명령에 따라 아이테르가 떠난 후 본 명령이 실행되었습니다.</color>",
  ui_story_1014_10141402_138_dialog_content = "<color=#e8d9bb>조건이 요구 사항을 충족하여 패스파인더호가 아이테르 PlayerName에게 요청을 발송합니다.</color>",
  ui_story_1014_10141402_139_dialog_content = "콜로서스가 나한테 요청할 게 있다고?",
  ui_story_1014_10141402_140_dialog_content = "<color=#e8d9bb>패스파인더호의 모든 데이터는 이미 아이테르 PlayerName의 소유가 되었습니다.</color>",
  ui_story_1014_10141402_141_dialog_content = "<color=#e8d9bb>패스파인더호의 에너지 코어는 이미 손상되어 복구가 불가능합니다.\n따라서 곧 기능을 정지합니다.</color>",
  ui_story_1014_10141402_142_dialog_content = "<color=#e8d9bb>35의 지시에 따라, 전술한 두 가지 상황에 부합할 경우\n패스파인더호는 근처에 위치한 아이테르에게 요청을 발송할 수 있습니다.</color>",
  ui_story_1014_10141402_143_dialog_content = "설마...",
  ui_story_1014_10141402_144_dialog_content = "<color=#e8d9bb>패스파인더호는 PlayerName 당신이 패스파인더호를 위해 <color=#FFB400>시</color>를 한 수 써 주길 요청합니다.</color>",
  ui_story_1014_10141402_145_dialog_content = "......",
  ui_story_1014_10141402_146_dialog_content = "알겠어.",
  ui_story_1014_10141402_147_dialog_content = "근데 난 시를 써 본 적은 없으니까, 잘 쓰진 못할 수도 있어.",
  ui_story_1014_10141402_148_dialog_content = "한때 우리와 함께 여정에 나선 그대",
  ui_story_1014_10141402_149_dialog_content = "끝없는 별의 바다는 그대의 날개를 지탱하고",
  ui_story_1014_10141402_150_dialog_content = "머나먼 거리와 아득한 세월을 뛰어넘었네",
  ui_story_1014_10141402_151_dialog_content = "기나긴 시간은 별빛마저 사그라트리고",
  ui_story_1014_10141402_152_dialog_content = "고독하고 기나긴 여정만이 남았구나",
  ui_story_1014_10141402_153_dialog_content = "집으로 돌아오란 부름은 울려 퍼졌으나",
  ui_story_1014_10141402_154_dialog_content = "이미 집으로 향하는 길을 잃어버리고 말았네",
  ui_story_1014_10141402_155_dialog_content = "그대는 별하늘에 너무도 오래 표류했고",
  ui_story_1014_10141402_156_dialog_content = "짙은 어둠 속에 너무도 오래 머물러 있었네",
  ui_story_1014_10141402_157_dialog_content = "시간과 재난은 집이 존재했던 흔적을 지웠으나",
  ui_story_1014_10141402_158_dialog_content = "귀로를 비추는 불빛이 다시금 빛을 발하니",
  ui_story_1014_10141402_159_dialog_content = "부디 그대의 의식이 바람과 민들레를 타고",
  ui_story_1014_10141402_160_dialog_content = "헤븐즈 밸리로 돌아올 수 있기를",
  ui_story_1014_10141402_161_dialog_content = "......",
  ui_story_1014_10141402_162_dialog_content = "(역시나 시를 써 본 적이 없어서 그런지 좀 이상한데...)",
  ui_story_1014_10141402_163_dialog_content = "<color=#e8d9bb>시를 받았습니다. 녹음을 재생합니다.</color>",
  ui_story_1014_10141402_164_dialog_content = "고마워요, 미래에서 온 선량한 사람.",
  ui_story_1014_10141402_165_dialog_content = "이건... 35의 목소리잖아?",
  ui_story_1014_10141402_166_dialog_content = "그 시와 함께라면 패스파인더도 분명히 기뻐하겠지요.",
  ui_story_1014_10141402_166X1_dialog_content = "비록 우린 한 번도 만난 적은 없지만, 지금 이 순간 서로의 마음을 이해할 수 있을 거라 믿어요.",
  ui_story_1014_10141402_166X2_dialog_content = "감응 능력을 사용하지 않아도 느낄 수 있답니다.",
  ui_story_1014_10141402_166X3_dialog_content = "그러게요. 감응 능력을 사용하지 않아도...\n하지만 눈물이 날 것 같은 이 충동은...",
  ui_story_1014_10141402_166X4_dialog_content = "이 「선물」을 발견한 당신이 누구든, 부디 당신의 여정에는 수많은 동료가 함께하며,\n영원히 쓸쓸하지 않기를 진심으로 빌겠습니다.",
  ui_story_1014_10141402_166X5_dialog_content = "부디 그가 당신과 함께 여행하게 해 주세요.\n그건 패스파인더와 제가 함께 품은 소망이니까요.",
  ui_story_1014_10141402_166X6_dialog_content = "고마워요... 정말 고마워요...",
  ui_story_1014_10141402_166X7_dialog_content = "이 선물... 소중하게 사용할게요.",
  ui_story_1014_10141402_168_dialog_content = "안녕, 패스파인더호.",
  ui_story_1014_10141402_169_dialog_content = "안녕하길, 35.",
  ui_story_1014_10141501_1_dialog_content = "<color=#e8d9bb>얼마 후, 더스크 타운</color>",
  ui_story_1014_10141501_2_dialog_content = "여기까지만 데려다주시면 됩니다.",
  ui_story_1014_10141501_3_dialog_content = "정말 고생이 많았습니다, PlayerName.",
  ui_story_1014_10141501_4_dialog_content = "별말씀을요. 도와달라고 부탁했던 건 저인데요.",
  ui_story_1014_10141501_5_dialog_content = "그럼 여러분, 다음에 또 만납시다.",
  ui_story_1014_10141501_6_dialog_content = "여러분과 함께 싸울 수 있어 영광이었습니다. 그럼 저도 이만 돌아가 보겠습니다.",
  ui_story_1014_10141501_7_dialog_content = "기회가 된다면 다시 만나자, PlayerName.",
  ui_story_1014_10141501_8_dialog_content = "잠깐.",
  ui_story_1014_10141501_9_dialog_content = "기사장님, 아직 지시하실 사항이 남으셨습니까?",
  ui_story_1014_10141501_10_dialog_content = "당신이 왜 불공평하다고 느끼는 건지 아직 그 대답을 못 들었어.",
  ui_story_1014_10141501_11_dialog_content = "하하하하, 아직도 그 문제를 마음에 두고 계셨던 겁니까?",
  ui_story_1014_10141501_12_dialog_content = "그렇다면 솔직히 말씀드리겠습니다.",
  ui_story_1014_10141501_13_dialog_content = "저는 현재의 백야성에는 변혁이 필요하다고 생각합니다.",
  ui_story_1014_10141501_14_dialog_content = "당신!",
  ui_story_1014_10141501_15_dialog_content = "아시다시피 백야성의 작위는 혈통을 따라 계승됩니다.",
  ui_story_1014_10141501_16_dialog_content = "자신의 능력에 기대지 않고 지위를 손에 넣었으니,\n손에 넣고 나서부턴 그 자리를 지키려고만 행동하게 되죠.",
  ui_story_1014_10141501_17_dialog_content = "바로 이런 이유 때문에 능력은 있지만 귀족이 아닌 이들이\n백야성에서 높은 자리에 올라갈 수 없는 겁니다.",
  ui_story_1014_10141501_18_dialog_content = "백야성은 철저한 변혁이 필요합니다.\n그리고 전 그 폭풍을 일으키는 자가 되고 싶습니다.",
  ui_story_1014_10141501_19_dialog_content = "방금 그 발언만으로도 내가 당신을 심판소에 반란 획책 혐의로\n고발할 수 있다는 사실은 알고 있겠지?",
  ui_story_1014_10141501_20_dialog_content = "하하하하, 그러지 않으실 거라 생각... 아니, 확신합니다.",
  ui_story_1014_10141501_21_dialog_content = "그토록 고귀한 신분을 가지고 계시면서도 권력에 눈이 멀지 않으신 분이니까요.",
  ui_story_1014_10141501_22_dialog_content = "기사장님께선 일반적인 백야성의 귀족들과는 달리,\n전장의 세례를 받은 진정한 기사이십니다.",
  ui_story_1014_10141501_23_dialog_content = "그 점에 대해선 같은 기사로서 저도 충분히 느낄 수 있었습니다.",
  ui_story_1014_10141501_24_dialog_content = "그래?",
  ui_story_1014_10141501_25_dialog_content = "그렇다면 최선을 다해 당신의 야심을 실현해 봐.",
  ui_story_1014_10141501_26_dialog_content = "서로 각자의 행동으로 누가 더 백야성에 도움이 되는지 증명하는 거야.",
  ui_story_1014_10141501_27_dialog_content = "네, 그러도록 하죠!",
  ui_story_1014_10141501_28_dialog_content = "카렌 님, 저렇게 가게 내버려 둬도 정말 괜찮을까요?",
  ui_story_1014_10141501_29_dialog_content = "괜찮아. 그냥 놔줘.",
  ui_story_1014_10141501_30_dialog_content = "그러고 보니까 조셀린이랑도 인사를... 어? 조셀린은 어디 갔어?",
  ui_story_1014_10141501_31_dialog_content = "조셀린은 조금 전에 지나가던 사람에게 부탁을 받고 그 사람을 도우러 갔습니다.",
  ui_story_1014_10141501_32_dialog_content = "PlayerName 당신이 카렌 씨와 레오 단장이 대화하는 것을\n보고 있을 때 일어난 일입니다.",
  ui_story_1014_10141501_33_dialog_content = "원래 그런 성격이셔. 누가 부탁만 하면 바로 달려가서 도와주시거든.",
  ui_story_1014_10141501_34_dialog_content = "작별 인사할 새도 없이 헤어져서 좀 아쉽네.",
  ui_story_1014_10141501_35_dialog_content = "다시 만날 기회는 또 있을 겁니다.",
  ui_story_1014_10141501_36_dialog_content = "잉겔, 숀, 악셀리아도 이제 돌아가야 합니다.",
  ui_story_1014_10141501_37_dialog_content = "임무는 순조롭게 완료됐습니다.",
  ui_story_1014_10141501_38_dialog_content = "그렇긴 하지만, 우선 상부에 아스모데우스에 대해 보고부터 해야 합니다.",
  ui_story_1014_10141501_39_dialog_content = "PlayerName, 바이스 중위, 카렌 님, 베르타 씨, 그럼 여기서 작별하도록 하죠.",
  ui_story_1014_10141501_40_dialog_content = "기회가 되면 나중에 또 만나자!",
  ui_story_1014_10141501_41_dialog_content = "악셀리아는 PlayerName의 임무 완수를 도울 수 있습니다.",
  ui_story_1014_10141501_42_dialog_content = "참! 다음번 연합 훈련엔 우리도 참가할 거야.",
  ui_story_1014_10141501_43_dialog_content = "그땐 모의 전장에서 만나!",
  ui_story_1014_10141501_44_dialog_content = "전장에서? 좋지! 우리도 다시 만날 날을 기대하고 있을게!",
  ui_story_1014_10141501_45_dialog_content = "그땐 제대로 겨뤄보자.",
  ui_story_1014_10141501_46_option_content = "다음에 또 만나!",
  ui_story_1014_10141501_47_dialog_content = "드디어 모두를 안전하게 더스크 타운으로 데려다줬네.",
  ui_story_1014_10141501_48_dialog_content = "우리도 얼른 자난성으로 돌아가자.",
  ui_story_1014_10141501_49_dialog_content = "아스모데우스란 암귀가 무척 신경 쓰이지만...\n그래도 지금 가장 급한 일은 스카이워커호를 수리하는 거니까.",
  ui_story_1014_10141501_50_dialog_content = "맞아, 더는 지체할 수 없어.",
  ui_story_1014_10141501_51_dialog_content = "그럼 가자!",
  ui_story_1014_10141501_52_dialog_content = "<color=#e8d9bb>얼마 후, 자난성</color>",
  ui_story_1014_10141501_53_dialog_content = "필요하다고 했던 데이터를 가져왔어요!",
  ui_story_1014_10141501_54_dialog_content = "아... 응? 뭐라고?",
  ui_story_1014_10141501_55_dialog_content = "벌써 돌아온 거야? 이렇게 빨리?",
  ui_story_1014_10141501_56_dialog_content = "네.",
  ui_story_1014_10141501_57_dialog_content = "상상도 못 한 적과 마주치긴 했지만, 그래도 무사히 데이터를 가지고 돌아왔어요.",
  ui_story_1014_10141501_58_dialog_content = "음, 그 얘긴 나도 들었어. 이상한 팬텀이 있었다며?\n<color=#FFB400>아스모데우스</color>라는 이름이었나?",
  ui_story_1014_10141501_59_dialog_content = "벌써 알고 있었어요?!",
  ui_story_1014_10141501_60_dialog_content = "하긴, 더스크 타운에도 일루미나의 주둔군이 있었죠.",
  ui_story_1014_10141501_61_dialog_content = "어떤 일이 일어나든 단말기로 통신만 하면 온 자난성이 다 알게 되겠죠.",
  ui_story_1014_10141501_62_dialog_content = "비슷해. 일루미나의 정보 시스템을 얕보면 안 돼.",
  ui_story_1014_10141501_63_dialog_content = "그렇지만 그 팬텀인지 뭔지에 어떻게 대응할지는 대원수한테 맡기는 게 좋겠어.",
  ui_story_1014_10141501_64_dialog_content = "지금 난 그저 당신들이 가져와 준 콜로서스의 데이터를\n확인해 보고 싶어서 몸이 근질거리거든.",
  ui_story_1014_10141501_65_dialog_content = "이 데이터들은 어떻게 손에 넣은 거야?\n일루미나에서 몇 번이나 탐험대를 보냈지만 다들 빈손으로 돌아오던데.",
  ui_story_1014_10141501_66_dialog_content = "그건...",
  ui_story_1014_10141501_67_option_content = "제가 아이테르이기 때문이에요.",
  ui_story_1014_10141501_68_dialog_content = "그 콜로서스의 의식은 한 아이테르의 끈기를 통해 탄생한 거였어요.",
  ui_story_1014_10141501_69_dialog_content = "저는 그저 마지막 아이테르로서 먼지가 쌓여있던 그 선물을 다시 돌려받은 것뿐이에요.",
  ui_story_1014_10141501_70_dialog_content = "흥미롭네, 아이테르 간의 계승이란 걸까?",
  ui_story_1014_10141501_71_option_content = "거기 「선물」이 있었거든요.",
  ui_story_1014_10141501_72_dialog_content = "그 콜로서스는 쭉 자신이 저장해 둔 귀중한 데이터를\n전달받을 사람이 찾아와 주길 기다리고 있었어요.",
  ui_story_1014_10141501_73_dialog_content = "귀환의 탑에서 프란츠 선생님이 그러셨던 것처럼요.",
  ui_story_1014_10141501_74_dialog_content = "그리고 그 콜로서스는... 마지막엔 제게 시를 하나 써 달라고도 했어요.",
  ui_story_1014_10141501_75_dialog_content = "콜로서스도 그런 부탁을 해? 신기하네.",
  ui_story_1014_10141501_76_dialog_content = "그럼 난 이 데이터들부터 좀 살펴볼게.",
  ui_story_1014_10141501_77_dialog_content = "......",
  ui_story_1014_10141501_78_dialog_content = "쳇, 예상했던 것보다 훨씬 복잡하잖아.",
  ui_story_1014_10141501_79_dialog_content = "그게 무슨 뜻이죠?",
  ui_story_1014_10141501_80_dialog_content = "복잡하다고요? 그럼 스카이워커호는 못 고치는 건가요?",
  ui_story_1014_10141501_81_dialog_content = "당황하지 마, 내가 차근차근 설명해 줄게.",
  ui_story_1014_10141501_82_dialog_content = "콜로서스의 의식은 어떤 아이테르의 꾸준한 시도에서 탄생했다고 했잖아?",
  ui_story_1014_10141501_83_dialog_content = "네.",
  ui_story_1014_10141501_84_dialog_content = "그렇게 시도하는 과정에서, 콜로서스는 기존 설정에서 고려하지 못한 상황에\n대처하기 위해 알 수 없는 변화를 일으켰어.",
  ui_story_1014_10141501_85_dialog_content = "보통은 그런 변화를 보고 「오류」라고 하는데,\n이 경우라면 난 그보다는 「<color=#FFB400>성장</color>」이라고 부르고 싶어.",
  ui_story_1014_10141501_86_dialog_content = "하지만 변화가 발생하게 된 근본적인 원인은 의외의 상황이야.",
  ui_story_1014_10141501_87_dialog_content = "그래서 의식 데이터 속에 그것을 구현하는 과정에서,\n그 변화들은 상당히 복잡하고 혼란스러운 데이터 변화 과정을 거치게 돼.",
  ui_story_1014_10141501_88_dialog_content = "이 데이터 변화 과정에서 어떤 건 별 쓸모가 없을 수도 있지만,\n어떤 건 콜로서스가 점차 의식을 갖도록 만드는 결정적인 요인이 될 수도 있어.",
  ui_story_1014_10141501_89_dialog_content = "그리고 콜로서스는 개체마다 데이터가 상호 독립 상태거든.\n그래서 저마다 일어나는 변화도 다 제각각이야.",
  ui_story_1014_10141501_90_dialog_content = "그러니까 네가 복사해 온 이 의식 데이터들의 형성 과정을\n스카이워커호에 그대로 사용할 순 없다는 거지.",
  ui_story_1014_10141501_91_dialog_content = "복잡한 지식 이야기는 이해가 잘 안 돼요.",
  ui_story_1014_10141501_92_dialog_content = "제가 궁금한 건 스카이워커를 수리할 수 있을지, 없을지 뿐이에요!",
  ui_story_1014_10141501_93_dialog_content = "구체적인 답을 해 주려면 이 데이터들을 분석해야 하는데, 그러려면 시간이 좀 필요해.",
  ui_story_1014_10141501_94_dialog_content = "스카이워커호가 가지고 있던 데이터만으로는 부족했지만,\n지금은 이 데이터들도 있으니까 교차 비교를 진행할 수 있겠지.",
  ui_story_1014_10141501_95_dialog_content = "스카이워커호의 회복 확률은 이미 큰 폭으로 상승했어.",
  ui_story_1014_10141501_96_dialog_content = "그러니까 날 믿고 조금만 시간을 줘.",
  ui_story_1014_10141501_97_dialog_content = "제겐 다른 선택지도 없는걸요.",
  ui_story_1014_10141501_98_dialog_content = "그렇게 풀 죽지 마. 난 인공지능 연구 쪽으론 꽤 자신 있거든.",
  ui_story_1014_10141501_99_dialog_content = "많은 일을 겪었으니까, 너도 이제 가서 좀 쉬어.",
  ui_story_1014_10141501_100_dialog_content = "지금부터는 내 싸움이니까.",
  ui_story_1014_10141501_101_dialog_content = "PlayerName, 스카이워커호의 상황은?",
  ui_story_1014_10141501_102_dialog_content = "그 데이터들이 도움이 될 것 같대?",
  ui_story_1014_10141501_103_dialog_content = "잘 모르겠어. 알골 씨 말로는 그 데이터들을 분석하는 데 시간이 좀 필요하대.",
  ui_story_1014_10141501_104_dialog_content = "그렇구나...",
  ui_story_1014_10141501_105_dialog_content = "결과가 좋길 바랄 수밖에 없겠네.",
  ui_story_1014_10141501_106_dialog_content = "그러게.",
  ui_story_1014_10141501_107_dialog_content = "<color=#e8d9bb>삐비빅──</color>",
  ui_story_1014_10141501_108_dialog_content = "바이스 중위, PlayerName 군, 둘 다 돌아왔습니까?",
  ui_story_1014_10141501_109_dialog_content = "율리시스 님?!",
  ui_story_1014_10141501_110_dialog_content = "화음 연결 장치의 연구에 새로운 진전이 조금 있었습니다.",
  ui_story_1014_10141501_111_dialog_content = "바이스 중위, 지금 즉시 PlayerName 군과 함께 올 수 있겠습니까?\n장소의 정확한 좌표는 잠시 뒤에 보내도록 하지요.",
  ui_story_1014_10141501_112_dialog_content = "좌표의 구체적인 내용은 기밀 사항이니, 관련자 외에는 동행할 수 없습니다.",
  ui_story_1014_10141501_113_dialog_content = "확인했다면 회신 바랍니다.",
  ui_story_1014_10141501_114_dialog_content = "네, 바이스 중위입니다. 확인했습니다.",
  ui_story_1014_10141501_115_dialog_content = "아주 좋습니다. 그렇다면 통신을 종료하겠습니다.",
  ui_story_1014_10141501_116_dialog_content = "또 기밀이야? 내가 도와줄 수 있는 부분은 없을 것 같네.",
  ui_story_1014_10141501_117_dialog_content = "그럼 난 우선 백야성으로 돌아가 볼게.",
  ui_story_1014_10141501_118_dialog_content = "마침 돌아가서 강철가시 기사단과 관련된 정보를 찾아보려던 참이었거든.",
  ui_story_1014_10141501_119_dialog_content = "그리고 성주님께 더스크 타운의 상황도 보고드려야 하고.",
  ui_story_1014_10141501_120_dialog_content = "아직도 거기 사람들이 신경 쓰이는 거야?",
  ui_story_1014_10141501_121_dialog_content = "신경이 안 쓰인다고 하면 거짓말이겠지.",
  ui_story_1014_10141501_122_dialog_content = "백야성과 관련된 일이니까 반드시 확인해 봐야 해.\n특히 원정 기사 레오라는 사람의 과거에 대해선 더더욱.",
  ui_story_1014_10141501_123_dialog_content = "그 사람의 의견을 부정하진 않아. 백야성을 더 좋은 방향으로 바꿔 줄지도 모르지.",
  ui_story_1014_10141501_124_dialog_content = "하지만 그가 백야성의 위협이 될 수도 있다는 사실을 간과할 순 없어.",
  ui_story_1014_10141501_125_dialog_content = "역시 카렌은 믿음직스럽다니까!",
  ui_story_1014_10141501_126_dialog_content = "그럼 우리도 얼른 안내받은 위치로 이동하자.",
  ui_story_1014_10141501_127_dialog_content = "응, 지금 바로 출발하자.",
  ui_story_1014_10141501_128_dialog_content = "<color=#e8d9bb>일루미나 연방, 어딘가</color>",
  ui_story_1014_10141501_129_dialog_content = "좌표를 따라왔는데... 여긴 지하성이잖아?!",
  ui_story_1014_10141501_130_dialog_content = "일루미나의 그 어느 지도에도 이런 지하성이 있다고 표시된 건 없었는데...",
  ui_story_1014_10141501_131_dialog_content = "좌표가 없었으면 절대로 못 찾았을 거야.",
  ui_story_1014_10141501_132_dialog_content = "......",
  ui_story_1014_10141501_133_dialog_content = "뭔가 경계가 엄청 삼엄하네...",
  ui_story_1014_10141501_134_dialog_content = "기밀 시설이니까 경비병이 많은 건 당연하지.",
  ui_story_1014_10141501_135_dialog_content = "왔군요.",
  ui_story_1014_10141501_136_dialog_content = "(왜 또 이 녀석이야...)",
  ui_story_1014_10141501_137_dialog_content = "(녀석이랑 얘기하면 매번 조사당하는 느낌이라 불편하단 말이지...)",
  ui_story_1014_10141501_138_dialog_content = "왜 그쪽이 여기 있는 거야? 우리보고 와 달라고 한 건 율리시스 씨 아니었어?",
  ui_story_1014_10141501_139_dialog_content = "율리시스 님께서는 긴급하고 중요한 일 때문에 직접 오실 수 없어,\n제게 두 사람을 맞이하라고 하셨습니다.",
  ui_story_1014_10141501_140_dialog_content = "급하게 우리보고 와 달라더니, 대체 무슨 일이야?",
  ui_story_1014_10141501_141_dialog_content = "이미 많은 일에 대해 알고 계시니, 이곳에서 진행되는 연구도 숨겨야 할 필요는 없겠죠.",
  ui_story_1014_10141501_142_dialog_content = "일단 설명부터 하겠습니다.",
  ui_story_1014_10141501_143_dialog_content = "계명성 프로젝트의 기원은 이곳에 있는 <color=#FFB400>또 하나의 화음 연결 장치</color>와 관련이 있습니다.",
  ui_story_1014_10141501_144_dialog_content = "네?! 화음 연결 장치는 한 대만 있는 게 아니었어요?!",
  ui_story_1014_10141501_145_dialog_content = "그렇습니다. 일루미나는 수년 전에 화음 연결 장치를 한 대 발견했습니다.",
  ui_story_1014_10141501_146_dialog_content = "그리고 그 장치를 연구해 오로리안을 개조하는 방법을 손에 넣었죠.",
  ui_story_1014_10141501_147_dialog_content = "다만 여러 가지 이유로 일루미나가 보유하고 있는 장치는\n헤븐즈 밸리에 있는 것만큼 온전하진 않습니다.",
  ui_story_1014_10141501_148_dialog_content = "일루미나에서 연구해 낸 개조 방법 역시 장치의 불완전으로 인해 완벽하지 않습니다.",
  ui_story_1014_10141501_149_dialog_content = "지금까지도 이러한 개조 방식은 능력 변화의 방향을 제어할 수 없을 뿐만 아니라,\n매우 높은 실패율을 가지고 있습니다.",
  ui_story_1014_10141501_150_dialog_content = "근데도 왜 계속 그런 연구를 하는 거야?",
  ui_story_1014_10141501_151_dialog_content = "매우 위험하다는 것도 알고, 사람을 고통스럽게 만든다는 것도 다 알고 있으면서...",
  ui_story_1014_10141501_152_dialog_content = "대체 왜 계속 그런 짓을 하는 건데?",
  ui_story_1014_10141501_153_dialog_content = "다시 한번 말씀드리지만, 이러한 연구를 계속하는 이유는\n대부분의 일루미나 사람들이 보통 사람이기 때문입니다.",
  ui_story_1014_10141501_154_dialog_content = "따라서 이렇게 해야만 일루미나가 계속해서 존재할 수 있는 것입니다.",
  ui_story_1014_10141501_155_option_content = "......",
  ui_story_1014_10141501_156_option_content = "난 동의할 수 없어.",
  ui_story_1014_10141501_157_dialog_content = "그 마음은 이해할 수 있습니다만, 우리의 관계는 거래와 비슷하다는\n사실을 잊지 않으셨으면 좋겠군요.",
  ui_story_1014_10141501_158_dialog_content = "불편함을 느끼신다면 우리에게 주었던 귀환의 탑 연구 권한을 취소하면 됩니다.\n당신에겐 그럴 권리가 있으니까요.",
  ui_story_1014_10141501_159_dialog_content = "다만 그렇게 되어 버린다면, 화음 연결과 그에 따른 부작용의 연구도 정체되겠죠.",
  ui_story_1014_10141501_160_dialog_content = "(지금 바이스랑 바튼 씨를 이용해서 날 위협하는 거야?)",
  ui_story_1014_10141501_161_dialog_content = "(여기서 이렇게 당할 줄이야...)",
  ui_story_1014_10141501_162_dialog_content = "표정을 보니 이해는 하신 것 같군요.",
  ui_story_1014_10141501_163_dialog_content = "그래서 너흰 이제부터 대체 뭘 할 생각인데?",
  ui_story_1014_10141501_164_dialog_content = "우리는 귀환의 탑에 있는 장치를 연구해서\n기존에 보유 중이던 불완전한 화음 연결 장치를 개선했습니다.",
  ui_story_1014_10141501_165_dialog_content = "그리고 이미 망가져 버린 두 장치를 통해 부작용이 없는,\n완벽한 화음 연결 장치를 제작하려 합니다.",
  ui_story_1014_10141501_166_dialog_content = "저 개인적으론 완벽한 화음 연결 장치만 제작할 수 있다면,\n많은 문제는 자연스레 해결될 거라고 봅니다.",
  ui_story_1014_10141501_167_dialog_content = "예를 들면 바이스 중위와 바튼 군단장이 가지고 있는\n알 수 없는 부작용 같은 것들 말입니다.",
  ui_story_1014_10141501_168_dialog_content = "...그럼 내가 뭘 해 주면 되는데?",
  ui_story_1014_10141501_169_dialog_content = "화음 연결 장치는 아이테르의 기술입니다.\n따라서 일부 데이터는 아이테르의 감응 능력으로만 해독이 가능하죠.",
  ui_story_1014_10141501_170_dialog_content = "현재는 해당 데이터들을 복원하는 중입니다.\n이 단계가 완료되고 나면 당신의 도움이 필요합니다.",
  ui_story_1014_10141501_171_dialog_content = "지금은 그 단계가 될 때까지 기다려 주시면 됩니다.",
  ui_story_1014_10141501_172_dialog_content = "(급하게 와 달라고 할 땐 언제고, 이젠 기다리라니...)",
  ui_story_1014_10141501_173_dialog_content = "좋아, 알겠어.",
  ui_story_1014_10141501_174_dialog_content = "협조해 주셔서 감사합니다.",
  ui_story_1014_10141501_175_dialog_content = "그럼 저는 아직 처리해야 할 일들이 많기 때문에 먼저 실례하겠습니다.",
  ui_story_1014_10141501_176_dialog_content = "이런 느낌 정말 싫어.",
  ui_story_1014_10141501_177_dialog_content = "꼭 내가 PlayerName 널 위협하는 데 쓸 도구가 된 것 같잖아.",
  ui_story_1014_10141501_178_dialog_content = "널 그런 식으로 말하지 마...",
  ui_story_1014_10141501_179_dialog_content = "저 사람들 도움 없이 나 혼자만의 능력으론 네 부작용을 해결할 수 없어.",
  ui_story_1014_10141501_180_dialog_content = "PlayerName...",
  ui_story_1014_10141501_181_dialog_content = "내 생각은 안 해도 돼.",
  ui_story_1014_10141501_182_dialog_content = "가끔 몸에서 빛이 나는 거 빼곤 몸 상태도 완전 멀쩡하다니까.",
  ui_story_1014_10141501_183_dialog_content = "그러니까 저 사람들한테 도움 같은 거 안 받아도,\n언젠간 후유증을 해결할 방법을 찾을 수 있을 거야.",
  ui_story_1014_10141501_184_dialog_content = "난 PlayerName 네가 네 본심을 저버리는 결정을 하는 건 원하지 않아.",
  ui_story_1014_10141501_185_option_content = "고마워, 바이스.",
  ui_story_1014_10141501_186_dialog_content = "그래도 난 화음 연결의 후유증 문제를 해결할 희망을 포기하고 싶진 않아.",
  ui_story_1014_10141501_187_option_content = "난 널 포기하지 않을 거야.",
  ui_story_1014_10141501_188_dialog_content = "어렸을 때부터 스카이워커가 항상 가르쳐 줬었어.\n동료는 하나하나가 모두 소중한 거라고.",
  ui_story_1014_10141501_189_dialog_content = "그러니까 난 동료들을 위험에 빠트리지 않을 거야.",
  ui_story_1014_10141501_190_dialog_content = "......",
  ui_story_1014_10141501_191_dialog_content = "(큰일 났네, 분위기가 너무 무거워졌어...)",
  ui_story_1014_10141501_192_dialog_content = "저기, 시간도 때울 겸 여기 구경 좀 해 볼까?",
  ui_story_1014_10141501_193_dialog_content = "계속 여기 서 있어 봐야 할 일도 없고, 언제 우리가 필요한 건지도 안 알려줬잖아.",
  ui_story_1014_10141501_194_dialog_content = "응, 근처만 살짝 돌아보는 건 아마 괜찮을 거야.",
  ui_story_1014_10141501_195_dialog_content = "(정말 엄청나게 큰 지하성이네...)",
  ui_story_1014_10141501_196_dialog_content = "(통로 양옆에 있는 방들은 다 실험실인 것 같아.)",
  ui_story_1014_10141501_197_dialog_content = "(이 실험실들 안에선 사람들에게 알려지지 않은 실험들이\n얼마나 많이 진행되고 있을까...)",
  ui_story_1014_10141501_198_dialog_content = "그런 요구에는 동의할 순 없습니다.",
  ui_story_1014_10141501_199_dialog_content = "그 장치는 아직 실험 단계입니다.\n더군다나 당신의 실험 대상은 아직 불안정한 상태일 텐데요.",
  ui_story_1014_10141501_200_dialog_content = "그런 실험 대상을 데리고 실험을 진행했다간,\n높은 확률로 귀중한 설비가 고장 나 버리고 말 겁니다.",
  ui_story_1014_10141501_201_dialog_content = "게다가 그 불완전한 장치가 당신 실험 대상을 치료할 수 있을지도 확실치 않습니다.",
  ui_story_1014_10141501_202_dialog_content = "이건 내 실험이야. 당신이 참견할 필요는 없어.",
  ui_story_1014_10141501_203_dialog_content = "당신은 그냥 나한테 실험 장치 사용 권한을 주고 입 닥치고 있기만 하면 돼.",
  ui_story_1014_10141501_204_dialog_content = "멀리서 누가 얘기하는 소리가 들려.",
  ui_story_1014_10141501_205_dialog_content = "어디서 들어 본 목소린데?",
  ui_story_1014_10141501_206_dialog_content = "그 의견엔 동의할 수 없습니다.",
  ui_story_1014_10141501_207_dialog_content = "귀중한 실험 장치들은 당신이 가지고 놀 장난감이 아닙니다. 게다가...",
  ui_story_1014_10141501_208_dialog_content = "지금의 당신은 이미 제게 그런 요구를 할 자격이 없습니다.",
  ui_story_1014_10141501_209_dialog_content = "자격이라... 후훗, 또 그런 걸 들먹이는 건가.",
  ui_story_1014_10141501_210_dialog_content = "나한테 자격을 줬던 것도, 그리고 그 자격을 빼앗아 간 것도 전부 당신들이야.",
  ui_story_1014_10141501_211_dialog_content = "처음엔 당신한테 협력해서 수많은 성과를 안겨 준 다음에야\n비로소 모든 장치를 사용할 자격을 얻을 수 있었지.",
  ui_story_1014_10141501_212_dialog_content = "그리고 지금은 그저 단 한마디 말로 내 모든 헌신을 박탈하려 하고 있고 말이야.",
  ui_story_1014_10141501_213_dialog_content = "그건 당신이 받아 마땅한 벌입니다.",
  ui_story_1014_10141501_214_dialog_content = "이 목소리... 설마 <color=#FFB400>노라</color>?!",
  ui_story_1014_10141501_215_dialog_content = "노라가 누굴 협박하고 있는 건가?",
  ui_story_1014_10141501_216_dialog_content = "얼른 가 보자!",
  ui_story_1014_10141501_217_dialog_content = "연구원들은 대부분 싸움은 못 하니까, 노라한테 잡혔다간 끝장이야!",
  ui_story_1014_10141501_218_dialog_content = "꼼짝 마! 그 사람을 풀어 줘!",
  ui_story_1014_10141501_219_dialog_content = "(진짜 노라였잖아! 왜 지금까지 노라의 기척을 못 느낀 거지?!)",
  ui_story_1014_10141501_220_dialog_content = "(잠깐만, 옆에 있던 연구원을 협박하고 있던 게 아니었나?)",
  ui_story_1014_10141501_221_dialog_content = "(저 사람, 왜 우리가 도착하자마자 도망가는 건데?!)",
  ui_story_1014_10141501_222_dialog_content = "정말 뜻밖이네, 내게 필요한 <color=#FFB400>실험 재료</color>들이 제 발로 찾아와 주다니.",
  ui_story_1014_10141501_223_dialog_content = "노라... 네가 왜 여기 있어? 그리고 연구원은 왜 협박한 거지?",
  ui_story_1014_10141501_224_dialog_content = "난 아무도 협박하지 않았어.",
  ui_story_1014_10141501_225_dialog_content = "그저 과거에 여기 두었던 내 권리들을 조금 돌려받으려고 했을 뿐이야.",
  ui_story_1014_10141501_226_dialog_content = "아무튼 모처럼 실험 재료가 제 발로 찾아와 줬으니까, 사양하지 않을게.",
  ui_story_1014_10141501_227_dialog_content = "잠깐, PlayerName! 얼른 피해! 뒤를 조심해!",
  ui_story_1014_10141501_228_dialog_content = "뭐?",
  ui_story_1014_10141501_229_dialog_content = "<anim type=Shake><size=50>크아아!</size></anim>",
  ui_story_1014_10141501_230_dialog_content = "으윽!",
  ui_story_1014_10141501_231_dialog_content = "으... 한참 기절해 있었던 것 같은데...",
  ui_story_1014_10141501_232_dialog_content = "기절하기 전에 노라랑 누군가가 대화하고 있는 걸 봤어. 그리고...",
  ui_story_1014_10141501_233_dialog_content = "바이스... 그래, 바이스! 괜찮아?!",
  ui_story_1014_10141501_234_dialog_content = "옆에 있는 건... 노라?!",
  ui_story_1014_10141501_235_dialog_content = "또 만났네, 아이테르.",
  ui_story_1014_10141501_236_dialog_content = "이 아이를 다치게 만들고 싶지 않다면, 내가 시키는 대로 해.",
  ui_story_1014_10141501_237_dialog_content = "......",
  ui_story_1014_10141501_238_dialog_content = "무슨 짓이야?! 바이스를 풀어 줘!",
  ui_story_1014_10141501_239_dialog_content = "바이스를 풀어 주면 널 따라갈 테니까.",
  ui_story_1014_10141501_240_dialog_content = "아직 상황 파악이 제대로 안 되는 모양이구나.",
  ui_story_1014_10141501_241_dialog_content = "넌 실험체야. 실험체는 뭔가를 요구할 자격이 없단다.",
  ui_story_1014_10141501_242_dialog_content = "게다가...",
  ui_story_1014_10141501_243_dialog_content = "실험을 위해선 너랑 이 아이 둘 다 필수품이거든.",
  ui_story_1015_10150101_1_dialog_content = "까악── 까악──",
  ui_story_1015_10150101_2_dialog_content = "날이 곧 어두워지겠군.",
  ui_story_1015_10150101_3_dialog_content = "그래, 얼른 가자.",
  ui_story_1015_10150101_4_dialog_content = "<color=#e8d9bb>터벅... 터벅...</color>",
  ui_story_1015_10150101_5_dialog_content = "잘 들어, 아이테르.",
  ui_story_1015_10150101_6_dialog_content = "지금부터 넌 반드시 내 명령에 따라 행동해야 해.",
  ui_story_1015_10150101_7_dialog_content = "도움을 청하지도, 반항하지도 말고, 어떤 불필요한 행동도 하지 마.",
  ui_story_1015_10150101_8_dialog_content = "난 이제부터 연구를 하나 해 볼 생각이고, 네 도움이 필요해.",
  ui_story_1015_10150101_9_dialog_content = "또 내 몸에 뭘 심으려는 거야?!",
  ui_story_1015_10150101_10_dialog_content = "아, 지난번 일 기억하고 있었구나.",
  ui_story_1015_10150101_11_dialog_content = "그걸 어떻게 잊냐고... 너 때문에 난 「그런」 게 돼버릴 뻔했어!",
  ui_story_1015_10150101_12_dialog_content = "맞아, 나도 참 아쉽게 생각해.",
  ui_story_1015_10150101_13_dialog_content = "겸사겸사하는 일일 뿐이지만,\n만약 네가 슈모르와 같은 「동포」가 되는 모습을 보게 된다면...",
  ui_story_1015_10150101_14_dialog_content = "그것도 아주 재미있을 것 같거든.",
  ui_story_1015_10150101_15_dialog_content = "「겸사겸사」? 이브, 도엔... 다른 사람들은?\n그 애들한테 그런 짓을 한 이유가 고작 「겸사겸사」라고?",
  ui_story_1015_10150101_16_dialog_content = "대체 뭘 한 거야? 아니, 넌 대체 뭘 하려고...",
  ui_story_1015_10150101_17_dialog_content = "시끄러워, 귀가 다 아프잖아.",
  ui_story_1015_10150101_18_dialog_content = "너희 아이테르들은... 다들 참 목소리가 크단 말이지. 이참에 성대를 잘라버릴까?",
  ui_story_1015_10150101_19_dialog_content = "어차피 넌 입으로 소통할 필요도 없잖아? 안 그래?",
  ui_story_1015_10150101_20_dialog_content = "......",
  ui_story_1015_10150101_21_dialog_content = "입을 다물어야 할 사람은 너야...",
  ui_story_1015_10150101_22_dialog_content = "아무튼 입 좀 다물고 있어, 아이테르.",
  ui_story_1015_10150101_23_dialog_content = "얌전히 따라오고, 시키는 대로 해. 난 지금 너랑 상의하고 있는 게 아니야.",
  ui_story_1015_10150101_24_dialog_content = "실험만 잘되면 너흰 구조될 기회를 얻을 수 있을 테니까.",
  ui_story_1015_10150101_25_dialog_content = "...실패한다면?",
  ui_story_1015_10150101_26_dialog_content = "난 너희 둘의 목숨으로 실패의 대가를 치를 거야.",
  ui_story_1015_10150101_27_dialog_content = "......",
  ui_story_1015_10150101_28_dialog_content = "흥, 목숨으로 우릴 협박하겠다고?",
  ui_story_1015_10150101_29_dialog_content = "난 아직 이클립스의 약속을 믿을 정도로 멍청해지진 않았어.",
  ui_story_1015_10150101_30_dialog_content = "넌 어차피 실험에 성공해도 우릴 죽일 거잖아.",
  ui_story_1015_10150101_31_dialog_content = "너흴 죽이는 건 나한테 아무런 이득도 없어.",
  ui_story_1015_10150101_32_dialog_content = "하나는 아이테르의 생존자고, 하나는 화음 연결 성공의 결과물이지.",
  ui_story_1015_10150101_33_dialog_content = "너흰 모두 귀중한 실험 소재야. 기회가 되면 난 너흴 내 연구실로 가지고 갈 생각이거든.",
  ui_story_1015_10150101_34_dialog_content = "뭐, 지금은 일루미나의 세력권 안이니까, 내 마음대로 할 방법은 없어.",
  ui_story_1015_10150101_35_dialog_content = "그러니까 너희한테 구조될 기회를 주겠다고 약속하는 거야.",
  ui_story_1015_10150101_36_dialog_content = "이건 자비를 베푸는 게 아니야. 미래의 연구에 가능성을 남겨두는 거지.",
  ui_story_1015_10150101_37_dialog_content = "......",
  ui_story_1015_10150101_38_dialog_content = "네 머릿속에 든 건 연구밖에 없는 모양이네.",
  ui_story_1015_10150101_39_dialog_content = "그렇다기보다는 다른 일에 어떤 생각할 만한 가치가 있는지 모르겠거든.",
  ui_story_1015_10150101_40_dialog_content = "그럼 실험에 대해 이야기해 보자. 너희도 조금 알아두는 게 편할 테니까.",
  ui_story_1015_10150101_41_dialog_content = "잠깐만, 아직 네 말을 듣겠다고 한 적 없잖아?",
  ui_story_1015_10150101_42_dialog_content = "너한테 다른 선택지는 없어.",
  ui_story_1015_10150101_43_dialog_content = "......",
  ui_story_1015_10150101_44_dialog_content = "난 어떻게 하면 개조를 통해 오로리안의 몸을 탈바꿈시킬 수 있는지 연구하고 있어.",
  ui_story_1015_10150101_45_dialog_content = "어느 측면의 능력도 잃지 않고 더 높은 종으로 철저한 진화를 이루는 거지.",
  ui_story_1015_10150101_46_dialog_content = "...말도 안 되는 소리네.",
  ui_story_1015_10150101_47_dialog_content = "너흰 아이테르가 남긴 화음 연결 장치를 써 봤잖아. 돌이켜 보면 이해할 수 있을 거야.",
  ui_story_1015_10150101_48_dialog_content = "그 장치는 내가 말한 잠재력을 가지고 있어.",
  ui_story_1015_10150101_49_dialog_content = "화음 연결 장치가 목적인 거야?",
  ui_story_1015_10150101_50_dialog_content = "맞아, 그게 내가 여기 온 이유야.",
  ui_story_1015_10150101_51_dialog_content = "너희도 알고 있겠지?\n일루미나에서 비밀리에 발굴한 화음 연결 장치가 이 지하성에 숨겨져 있다는 거 말이야.",
  ui_story_1015_10150101_52_dialog_content = "...그래.",
  ui_story_1015_10150101_53_dialog_content = "그게 바로 이번 연구에서 가장 중요한 설비야.",
  ui_story_1015_10150101_54_dialog_content = "난 그걸로 실험을 하고 데이터를 수집해서, 화음 연결 장치의 가장 적합한 사용법을 찾을 거야.",
  ui_story_1015_10150101_55_dialog_content = "그리고 가능하다면 오로리안 위에 군림할 생물을 창조해 내는 거지.",
  ui_story_1015_10150101_56_dialog_content = "서, 설마 바이스를 개조하려는 거야?!",
  ui_story_1015_10150101_57_dialog_content = "내가 벌써 그렇게 호의적으로 보여?\n바이스는 실험 데이터 측정의 샘플로만 쓰일 거야. 마지막 개조엔 참가하지 않아.",
  ui_story_1015_10150101_58_dialog_content = "그런 영광을 가장 먼저 누리게 될 실험체는 이쪽이거든.",
  ui_story_1015_10150101_59_dialog_content = "......",
  ui_story_1015_10150101_60_dialog_content = "아...",
  ui_story_1015_10150101_61_dialog_content = "(노라가 헬리오스를 구한 것도 방금 말한 연구를 위해서인 건가?)",
  ui_story_1015_10150101_62_dialog_content = "(아니면... 반대로 헬리오스를 구하는 게 연구의 진짜 목적이었던 걸까...?)",
  ui_story_1015_10150101_63_dialog_content = "하지만 연구가 잘되면 너희한테도 이득이 될 거야.",
  ui_story_1015_10150101_64_dialog_content = "일루미나 쪽 자료를 봤어.\n바이스 넌 화음 연결의 강화를 받은 뒤로 몸에 약간의 부작용이 있었지?",
  ui_story_1015_10150101_65_dialog_content = "그런 것도 알고 있다고?!",
  ui_story_1015_10150101_66_dialog_content = "너랑 상관없는 일이잖아!",
  ui_story_1015_10150101_67_dialog_content = "이 연구를 마치면 화음 연결을 통해 네 몸의 부작용을 제거할 수도 있어.",
  ui_story_1015_10150101_68_dialog_content = "이 일의 결과는 우리 모두에게 이익인 셈이지.",
  ui_story_1015_10150101_69_dialog_content = "...고작 그런 걸로 우릴 매수하시겠다?",
  ui_story_1015_10150101_70_dialog_content = "난 내가 그럴 필요는 없다고 생각하는데. 날 돕는 게 너희들의 유일한 살길이니까.",
  ui_story_1015_10150101_71_dialog_content = "방금 말한 이익은 그저 너희한테 사실을 전달했을 뿐이야.",
  ui_story_1015_10150101_72_dialog_content = "뭐, 알았어. 확실히 네 말대로 우린 선택지가 없어.",
  ui_story_1015_10150101_73_dialog_content = "근데 모르겠어. 우리가 너한테 무슨 도움이 되는데?",
  ui_story_1015_10150101_74_dialog_content = "연구 과정의 장애물을 없애줘.",
  ui_story_1015_10150101_75_dialog_content = "난 실험 장비, 실험 데이터가 필요해, 이것들은 전부 일루미나의 손에 있어.",
  ui_story_1015_10150101_76_dialog_content = "그리고 분명한 건 저들이 그걸 외부인이 사용할 수 있도록 준비해 두진 않았다는 거지.",
  ui_story_1015_10150101_77_dialog_content = "<color=#e8d9bb>변방, 더스크 타운</color>",
  ui_story_1015_10150101_78_dialog_content = "서둘러라, 부상당한 기사들부터 들어가라!",
  ui_story_1015_10150101_79_dialog_content = "예!",
  ui_story_1015_10150101_80_dialog_content = "일루미나 쪽 부상자들도 좀 도와줘, 저들도 인력이 부족해.",
  ui_story_1015_10150101_81_dialog_content = "레오 단장님, 고마워요...",
  ui_story_1015_10150101_82_dialog_content = "같은 전장에서 싸운 사인데, 누가 누구한테 고마워할 게 뭐 있겠어.",
  ui_story_1015_10150101_83_dialog_content = "오늘 이렇게 강한 적과 마주칠 줄은 몰랐어요. 부대가 심각한 손실을 입고 말았네요.",
  ui_story_1015_10150101_84_dialog_content = "다 제 탓이에요... 제가 지휘관 역할을 제대로 못 해서...",
  ui_story_1015_10150101_85_dialog_content = "네 탓이 아니야. 강적을 만난 이상 희생은 불가피한 일이야.",
  ui_story_1015_10150101_86_dialog_content = "그리고 난 오늘의 희생은 필연이라고 생각해.",
  ui_story_1015_10150101_87_dialog_content = "어째서죠?",
  ui_story_1015_10150101_88_dialog_content = "더스크 타운 주변의 「동향」이 이상했거든.",
  ui_story_1015_10150101_89_dialog_content = "최근 며칠 동안 마을을 노린 대규모 공격이 벌써 여러 번 연속해서 발생했어.",
  ui_story_1015_10150101_90_dialog_content = "적어도 내가 기억하는 한 적이 이렇게 활발한 공세를 펼친 적은 없었어.",
  ui_story_1015_10150101_91_dialog_content = "설마 놈들이 무슨 큰일을 꾸미고 있는 건 아니겠죠?",
  ui_story_1015_10150101_92_dialog_content = "글쎄, 하지만 우린 미리 대비해야만 해.",
  ui_story_1015_10150101_93_dialog_content = "참, 그러고 보니 너희 참모장이 돌아왔다면서?",
  ui_story_1015_10150101_94_dialog_content = "맞아요. 얼마 안 됐어요.",
  ui_story_1015_10150101_95_dialog_content = "그 사람 좀 불러줘. 늘 만나던 장소에서 기다리겠다고.",
  ui_story_1015_10150101_96_dialog_content = "어서 오세요, 몇 분이시죠?",
  ui_story_1015_10150101_97_dialog_content = "사람을 찾으러 왔습니다.",
  ui_story_1015_10150101_98_dialog_content = "더스크 타운의 유명인이 제게 식사 대접이라니, 드문 일이네요.",
  ui_story_1015_10150101_99_dialog_content = "앉아, 고기 먹자.",
  ui_story_1015_10150101_100_dialog_content = "괜찮아요, 밥 먹고 왔습니다.",
  ui_story_1015_10150101_101_dialog_content = "그거 잘됐네, 그 접시 이리 줘.",
  ui_story_1015_10150101_102_dialog_content = "그래도 역시 제 앞에 두는 게 좋을 것 같네요. 이건 제 환영회니까요.",
  ui_story_1015_10150101_103_dialog_content = "오늘 절 부른 건 식사보다는 더 중요한 일이겠죠?",
  ui_story_1015_10150101_104_dialog_content = "물론 밥만 먹는데 굳이 파트너를 찾을 필요는 없지.",
  ui_story_1015_10150101_105_dialog_content = "최근 며칠간 일루미나의 사상자 보고는 받았겠지?",
  ui_story_1015_10150101_106_dialog_content = "네, 데이터가 이상하더군요.",
  ui_story_1015_10150101_107_dialog_content = "더스크 타운의 일루미나 주둔군에 이렇게 밀집된 사상 기록은 없었습니다.",
  ui_story_1015_10150101_108_dialog_content = "최근 며칠간의 전투 강도는 이미 우리가 감당할 수 있는 임계점에 도달하려고 합니다.",
  ui_story_1015_10150101_109_dialog_content = "가장 무서운 건 사상자가 아니라,\n우리가 실질적으로는 적을 한 번도 쓰러트리지 못했다는 거야.",
  ui_story_1015_10150101_110_dialog_content = "매번 전투 결과는 양측이 대치 끝에 퇴각하는 것이었지.",
  ui_story_1015_10150101_111_dialog_content = "다시 말해 우린 상대방의 가용 전력을 전혀 파악하지 못하고 있다는 뜻이죠.",
  ui_story_1015_10150101_112_dialog_content = "가장 최악인 건 이번에 마주쳤던 것들이 전부 독자적인 암귀 무리였다는 겁니다.",
  ui_story_1015_10150101_113_dialog_content = "만약 놈들이 집결해서 더스크 타운을 포위한다면, 그 결과는 상상도 하고 싶지 않습니다.",
  ui_story_1015_10150101_114_dialog_content = "맞아. 역시 똑똑한 친구랑은 얘기가 쉽다니까.",
  ui_story_1015_10150101_115_dialog_content = "대응 전략은 생각해 두셨습니까?",
  ui_story_1015_10150101_116_dialog_content = "이미 병력을 나눠서 어둠의 밑바닥으로 정찰을 보냈어.\n어떻게든 적의 동향을 파악해 봐야지.",
  ui_story_1015_10150101_117_dialog_content = "하지만 내가 보기에 지금 병력으로는 더스크 타운을 지키기엔 부족해.",
  ui_story_1015_10150101_118_dialog_content = "그래서 지원을 요청하는 편지를 쓸 생각이야.",
  ui_story_1015_10150101_119_dialog_content = "음... 그렇죠, 그게 가장 타당한 방법이니까요.",
  ui_story_1015_10150101_120_dialog_content = "제게 그 말을 하시는 건, 일루미나의 지원을 받기 위해서겠죠?",
  ui_story_1015_10150101_121_dialog_content = "당연하지. 얼마나 더 많은 적을 상대해야 할지 우린 아직 모르잖아.",
  ui_story_1015_10150101_122_dialog_content = "여기서 백야성과 일루미나의 견해차를 이야기하는 건 너무 편협한 생각 아니겠어?",
  ui_story_1015_10150101_123_dialog_content = "알겠습니다, 편지는 돌아가면 보내도록 하죠.",
  ui_story_1015_10150101_124_dialog_content = "그래, 빠르면 빠를수록 좋다고. 지금 우리한테 가장 부족한 건 시간이니까.",
  ui_story_1015_10150101_125_dialog_content = "우리가 예상한 상황이 아무래도 곧 벌어질 것 같다는 예감이 들거든.",
  ui_story_1015_10150101_126_dialog_content = "<color=#e8d9bb>백야성 본성</color>",
  ui_story_1015_10150101_127_dialog_content = "휴...",
  ui_story_1015_10150101_128_dialog_content = "카렌, 보고서는 다 썼나요?",
  ui_story_1015_10150101_129_dialog_content = "응.",
  ui_story_1015_10150101_130_dialog_content = "조금 피곤해 보이네요.",
  ui_story_1015_10150101_131_dialog_content = "저분과 대화하는 건 사람을 지치게 만드는 일이니까.",
  ui_story_1015_10150101_132_dialog_content = "난 내가 시간을 낭비했다고 생각해.\n저분이 듣고 싶은 것과 내가 하고 싶은 말 사이엔 조금도 접점이 없거든.",
  ui_story_1015_10150101_133_dialog_content = "더스크 타운의 일 말인가요?",
  ui_story_1015_10150101_134_dialog_content = "응, 대체 왜 계속 자원 배분과 조직 구조 문제를 물어보시는 건지 이해가 안 돼.",
  ui_story_1015_10150101_135_dialog_content = "분명히 내가 보고한 것들이 더 중요할 텐데...",
  ui_story_1015_10150101_136_dialog_content = "됐어, 여기선 말하지 않는 게 좋겠어.",
  ui_story_1015_10150101_137_dialog_content = "그래요. 그만하고 차 마시러 가요.",
  ui_story_1015_10150101_138_dialog_content = "앞으로 며칠 동안은 무슨 계획이 있나요?",
  ui_story_1015_10150101_139_dialog_content = "별일 없어. 성주님이 백야성에 남아서 대기하라고 하셨거든.",
  ui_story_1015_10150101_140_dialog_content = "대기인가요? 아, 그렇네요. 이제 곧 「<color=#FFB400>연합 훈련</color>」이 있을 테니까요.",
  ui_story_1015_10150101_141_dialog_content = "응, 그렇겠지.",
  ui_story_1015_10150101_142_dialog_content = "잘 준비해야겠네요. 전하께선 연합 훈련의 스타잖아요.",
  ui_story_1015_10150101_143_dialog_content = "하지만... 지금은 마음이 차분해지질 않아.",
  ui_story_1015_10150101_144_dialog_content = "왜 그럴까요?",
  ui_story_1015_10150101_145_dialog_content = "PlayerName 쪽에서 계속 연락이 오질 않고 있어.",
  ui_story_1015_10150101_146_dialog_content = "조종사와 바이스... 두 사람이 어떻게 된 건지 모르겠어...",
  ui_story_1015_10150101_147_dialog_content = "오오, 카렌이잖아! 진짜 오랜만이네~",
  ui_story_1015_10150101_148_dialog_content = "오랜만이야, 그로누, 갑자기 연락해서 방해가 된 게 아니었으면 좋겠어.",
  ui_story_1015_10150101_149_dialog_content = "에이, 아니야. 마침 딱 좋은 타이밍이었거든.",
  ui_story_1015_10150101_150_dialog_content = "내 말 잘 들어. 지금 막 스카이워커호의 작업에 획기적인 진전이 있었어.",
  ui_story_1015_10150101_151_dialog_content = "들어 봐.",
  ui_story_1015_10150101_152_dialog_content = "스카이워커호, 기동!",
  ui_story_1015_10150101_153_dialog_content = "스카이워커호 기동 완료.",
  ui_story_1015_10150101_154_dialog_content = "들었어?!",
  ui_story_1015_10150101_155_dialog_content = "들었어, 그런데... 직전까지도 기동은 정상적으로 할 수 있었는걸.",
  ui_story_1015_10150101_156_dialog_content = "그래그래, 기동할 순 있지만 의식이 없었다는 거잖아?",
  ui_story_1015_10150101_157_dialog_content = "응.",
  ui_story_1015_10150101_158_dialog_content = "걱정 마. 스카이워커호의 의식 모듈은 이미 거의 다 복구됐거든.",
  ui_story_1015_10150101_159_dialog_content = "하지만 오로리안인 우린 스카이워커호와 직접 소통할 수 없어.",
  ui_story_1015_10150101_160_dialog_content = "이제 조종사가 돌아오면 스카이워커호랑 대화할 수 있을 거야!",
  ui_story_1015_10150101_161_dialog_content = "아, 그래! 사실 안 그래도 PlayerName... 그리고 바이스 일로 연락한 거였어.",
  ui_story_1015_10150101_162_dialog_content = "그 뒤로 어떻게 된 거야?",
  ui_story_1015_10150101_163_dialog_content = "내가 백야성으로 돌아온 뒤로, 두 사람한테서 연락이 전혀 없었어.",
  ui_story_1015_10150101_164_dialog_content = "아, 두 사람이 낸 보고서 봤어.",
  ui_story_1015_10150101_165_dialog_content = "어느 기밀 지하성으로 가서 치료를 받는다고 하더라고.\n아마 당분간 통신 연락이 차단될 거야.",
  ui_story_1015_10150101_166_dialog_content = "아마 치료가 끝나면 연락하지 않을까?",
  ui_story_1015_10150101_167_dialog_content = "기밀 지하성?",
  ui_story_1015_10150101_168_dialog_content = "응. 걱정 마. 거긴 보안 등급이 꽤 높거든.",
  ui_story_1015_10150101_169_dialog_content = "이름이 뭐였더라...",
  ui_story_1015_10150101_170_dialog_content = "아, 맞다. 「<color=#FFB400>X호 연구소</color>」라고 해.",
  ui_story_1015_10150101_171_dialog_content = "<color=#e8d9bb>자난성 기차역</color>",
  ui_story_1015_10150101_172_dialog_content = "앞에 좀 비켜 봐. 뒤에선 아무것도 안 보인다고.",
  ui_story_1015_10150101_173_dialog_content = "어라, 저거 좀 삐뚤게 걸린 거 아냐?",
  ui_story_1015_10150101_174_dialog_content = "그래! 우리 일루미나 깃발을 더 높이 걸어야지!",
  ui_story_1015_10150101_175_dialog_content = "왜 사람이 이렇게 많이 모여 있어? 다들 뭘 보고 있는 거야?",
  ui_story_1015_10150101_176_dialog_content = "몰랐어? 이제 곧 「연합 훈련」이잖아. 지금 다들 자기 세력의 깃발을 걸고 있는 거야.",
  ui_story_1015_10150101_177_dialog_content = "아! 벌써 시기가 그렇게 됐나?",
  ui_story_1015_10150101_178_dialog_content = "올해는 볼거리가 많을 거야.\n인터뷰를 딴 신문사가 매일 접수처 입구에서 줄을 서 있다니까.",
  ui_story_1015_10150101_179_dialog_content = "음? 올해 훈련에 뭐 특별한 점이라도 있는 건가?",
  ui_story_1015_10150101_180_dialog_content = "당연하지. 무려 10여 년 만에 아이테르가 다시 훈련 무대에 오르는 거잖아.",
  ui_story_1015_10150101_181_dialog_content = "<color=#e8d9bb>자난성 정보부</color>",
  ui_story_1015_10150101_182_dialog_content = "<color=#e8d9bb>똑똑똑.</color>",
  ui_story_1015_10150101_183_dialog_content = "들어와요.",
  ui_story_1015_10150101_184_dialog_content = "잉겔 중령님, 긴급 전보입니다.",
  ui_story_1015_10150101_185_dialog_content = "서둘러 확인해 주셔야 합니다.",
  ui_story_1015_10150101_186_dialog_content = "긴급 전보?",
  ui_story_1015_10150101_187_dialog_content = "네, 알겠어요. 책상 위에 두세요.",
  ui_story_1015_10150101_188_dialog_content = "예!",
  ui_story_1015_10150101_189_dialog_content = "(누가 긴급 전보를...)",
  ui_story_1015_10150101_190_dialog_content = "(음? 율리시스 님이...?)",
  ui_story_1015_10150201_1_dialog_content = "빨리 따라와, 꾸물거리지 말고.",
  ui_story_1015_10150201_2_dialog_content = "내 칼보다는 빨리 걷는 게 좋을걸.",
  ui_story_1015_10150201_3_dialog_content = "...알았다고.",
  ui_story_1015_10150201_4_dialog_content = "그래도 할 말은 해야겠어. 꼭 매일 이렇게 일찍 일어날 필요가 있어?",
  ui_story_1015_10150201_5_dialog_content = "벌써 며칠 동안 잠도 제대로 못 잤다고.",
  ui_story_1015_10150201_6_dialog_content = "십여 년간 한결같이 나태했던 생활이 네 버릇을 망친 모양이네.",
  ui_story_1015_10150201_7_dialog_content = "우리 스케줄은 전혀 가혹하지 않아.\n봐, 주변의 경비병들도 진작에 일어났잖아.",
  ui_story_1015_10150201_8_dialog_content = "휴... 도대체 얼마나 더 이렇게 지내라는 거야?",
  ui_story_1015_10150201_9_dialog_content = "그거라면 오히려 명확한 기한이 정해져 있어.",
  ui_story_1015_10150201_10_dialog_content = "너희도 들어봤겠지. 지금 일루미나는 「연합 훈련」이라는 행사를 준비하고 있어.\n그리고 너희 둘 다 초대받을 거야.",
  ui_story_1015_10150201_11_dialog_content = "그때까지 너희가 안 오면 일루미나에선 분명히 사람을 보내서 날 귀찮게 만들겠지.",
  ui_story_1015_10150201_12_dialog_content = "그러니까 그게 우리의 최종 기한이야.",
  ui_story_1015_10150201_13_dialog_content = "(맞아! 연합 훈련! 그럼 그걸 기회로 우리도 벗어날 수 있지 않을까?)",
  ui_story_1015_10150201_14_dialog_content = "너희한테 좋은 소식은 이 납치가 오래가진 않을 거라는 점이겠지.",
  ui_story_1015_10150201_15_dialog_content = "나쁜 소식은 실험을 기한 내에 제대로 끝내지 못하면,\n너희들의 남은 목숨은 생각보다 더 짧아질 수 있다는 거야.",
  ui_story_1015_10150201_16_dialog_content = "......",
  ui_story_1015_10150201_17_dialog_content = "그러니까 너희가 살아남을 수 있도록 더 효율을 높여 봐.",
  ui_story_1015_10150201_18_dialog_content = "아, 밀지 마! 길은 나도 안다고!",
  ui_story_1015_10150201_19_dialog_content = "아무튼 실험실에 가려는 거잖아. 거긴 자주 가 봤어.",
  ui_story_1015_10150201_20_dialog_content = "난 실험 외의 일에 너무 많은 시간을 낭비하고 싶지 않아.",
  ui_story_1015_10150201_21_dialog_content = "집중해. 우리 행적을 드러내지 마.",
  ui_story_1015_10150201_22_dialog_content = "저번처럼 도와달라고 소리를 지르거나 하면 꼭 너희 혀를 잘라준다고 약속할게.",
  ui_story_1015_10150201_23_dialog_content = "알았다니까. 이번엔 우리도 나름대로 협조하고 있잖아.",
  ui_story_1015_10150201_24_dialog_content = "경비병은 순찰 경로랑 출근 시간이 정해져 있어. 분명히 별일 없을...",
  ui_story_1015_10150201_25_dialog_content = "......",
  ui_story_1015_10150201_26_dialog_content = "<size=50>으아악!</size> 이, 이건...",
  ui_story_1015_10150201_27_dialog_content = "<size=50><anim type=Shake>크어어──</anim></size>",
  ui_story_1015_10150201_28_dialog_content = "노라, 네가 키우는 개가 또 따라왔어...",
  ui_story_1015_10150201_29_dialog_content = "다시 한번 말하는데, 제이드는 개가 아니야.",
  ui_story_1015_10150201_30_dialog_content = "좋아, 아무튼 네 애완동물이잖아.",
  ui_story_1015_10150201_31_dialog_content = "저렇게 큰 녀석이 따라와도 정말 괜찮겠어?",
  ui_story_1015_10150201_32_dialog_content = "오늘 연구엔 조수가 필요하거든. 그래서 내가 불렀어.",
  ui_story_1015_10150201_33_dialog_content = "연구...",
  ui_story_1015_10150201_34_dialog_content = "그럼 저게 저렇게 된 것도 네 연구 때문이겠지?",
  ui_story_1015_10150201_35_dialog_content = "......",
  ui_story_1015_10150201_36_dialog_content = "제이드는 원래 어떤 동물이었어?",
  ui_story_1015_10150201_37_dialog_content = "친칠라야.",
  ui_story_1015_10150201_38_dialog_content = "친칠라?!",
  ui_story_1015_10150201_39_dialog_content = "그런 작고 귀여운 동물이 저렇게 되다니...",
  ui_story_1015_10150201_40_dialog_content = "「작고 귀엽다」 같은 표현은 그저 네가 먹이사슬 꼭대기에서의\n시선으로 드러내는 오만함일 뿐이야.",
  ui_story_1015_10150201_41_dialog_content = "하?",
  ui_story_1015_10150201_42_dialog_content = "다른 생물의 사활은 네가 정의할 수 있는 게 아니야.\n그러니까 네 비위를 더 잘 맞추는 특성은 녀석의 이점이 되는 거지.",
  ui_story_1015_10150201_43_dialog_content = "자연계에서만 놓고 보자면 친칠라의 체형은 녀석이 더 높은 생태적 지위를\n차지하는 걸 의심의 여지 없이 제한하고 있어.",
  ui_story_1015_10150201_44_dialog_content = "하지만 지금의 제이드는 이미 그런 한계를 깨트렸지.",
  ui_story_1015_10150201_45_dialog_content = "한계를 깼다고?",
  ui_story_1015_10150201_46_dialog_content = "간단히 말해서 녀석은 더 풍부한 포식의 선택지를 가지게 됐어.",
  ui_story_1015_10150201_47_dialog_content = "그리고 마침 우린 문을 지키는 병사들과 교전할 차례야.",
  ui_story_1015_10150201_48_dialog_content = "야! 너 설마 병사들을 저 녀석한테 먹이려는 건 아니겠지?!",
  ui_story_1015_10150201_49_dialog_content = "약속했잖아! 널 도와서 싸우는 것까진 되지만, 절대로 병사들의 목숨을 해치진 않겠다고!",
  ui_story_1015_10150201_50_dialog_content = "넌 한 종족의 운명엔 신경도 안 쓰면서, 눈앞의 목숨 한두 개는 잘도 따지는구나.",
  ui_story_1015_10150201_51_dialog_content = "뭐, 됐어. 난 네 좁은 시야를 고쳐주는 일 같은 건 관심 없으니까.",
  ui_story_1015_10150201_52_dialog_content = "그럼 한두 명의 목숨은 안 중요하다는 거야? 저 사람들도...",
  ui_story_1015_10150201_53_dialog_content = "역시 그냥 하던 대로 아이테르가 나한테 전투 정보를 제공해.",
  ui_story_1015_10150201_54_dialog_content = "실험실이 방어를 강화한 탓에 이번 전투는 전보다 다소 어려울 거야.",
  ui_story_1015_10150201_55_dialog_content = "난 괜찮은 전력을 제공할 수 있어. 날 놓아주는 건 어때?",
  ui_story_1015_10150201_56_dialog_content = "넌 쓸데없는 짓하지 말고 그 자리에 가만히 있어.\n안 그러면 제이드의 첫 아침 식사가 될 거니까.",
  ui_story_1015_10150201_57_dialog_content = "흥.",
  ui_story_1015_10150201_58_dialog_content = "아이테르, 내 뒤를 바짝 따라와.",
  ui_story_1015_10150201_59_dialog_content = "가자.",
  ui_story_1015_10150302_1_dialog_content = "<color=#e8d9bb>쾅──</color>",
  ui_story_1015_10150302_2_dialog_content = "안 돼! 너무 세게 하지 마!",
  ui_story_1015_10150302_3_dialog_content = "저 사람 뼈라도 부러지면 어떡해!",
  ui_story_1015_10150302_4_dialog_content = "끝났어. 기절한 병사들을 옆으로 옮겨.",
  ui_story_1015_10150302_5_dialog_content = "적어도 실험 기간 동안엔 순찰병이 발견하게 해선 안 돼.",
  ui_story_1015_10150302_6_dialog_content = "<size=45><anim type=Shake>키아악──</anim></size>",
  ui_story_1015_10150302_7_dialog_content = "살살 당겨!",
  ui_story_1015_10150302_8_dialog_content = "휴, 그냥 내가 할게.",
  ui_story_1015_10150302_9_dialog_content = "서둘러. 시간 낭비하지 말고.",
  ui_story_1015_10150302_10_dialog_content = "알고 있다니까. 이젠 처음도 아니잖아.",
  ui_story_1015_10150302_11_dialog_content = "병사들, 이렇게 돼서 미안해.",
  ui_story_1015_10150302_12_dialog_content = "어라? 바닥에 물건도 잔뜩 떨어졌잖아.",
  ui_story_1015_10150302_13_dialog_content = "다시 주머니에 넣어줘야지.",
  ui_story_1015_10150302_14_dialog_content = "칼... 열쇠... 마그네틱 카드...",
  ui_story_1015_10150302_15_dialog_content = "이건 뭐지? 반짇고리인가?",
  ui_story_1015_10150302_16_dialog_content = "열리는 것 같은데...",
  ui_story_1015_10150302_17_dialog_content = "<size=45>!!!</size>",
  ui_story_1015_10150302_18_dialog_content = "아, <color=#FFB400>라이터</color>였구나...",
  ui_story_1015_10150302_19_dialog_content = "<size=50><anim type=Shake>크오오오!</anim></size>",
  ui_story_1015_10150302_20_dialog_content = "으악! 제이드 너 왜 그래?!",
  ui_story_1015_10150302_21_dialog_content = "<size=45><anim type=Shake>키아악──</anim></size>",
  ui_story_1015_10150302_22_dialog_content = "<color=#e8d9bb>콰앙──</color>",
  ui_story_1015_10150302_23_dialog_content = "라, 라이터를 밟아 부순 거야?",
  ui_story_1015_10150302_24_dialog_content = "그냥 라이터일 뿐인데 뭘 그렇게 놀라고 그래.",
  ui_story_1015_10150302_25_dialog_content = "......",
  ui_story_1015_10150302_26_dialog_content = "실험실의 환경은 매우 민감해. 작은 불씨조차 용납할 수 없어.",
  ui_story_1015_10150302_27_dialog_content = "방금 같은 일이 다시는 없게 해.",
  ui_story_1015_10150302_28_dialog_content = "아, 그래...",
  ui_story_1015_10150302_29_dialog_content = "(정말 그런 거면, 왜 실험실의 경비병이 라이터를 가지고 있었던 거지?)",
  ui_story_1015_10150302_30_dialog_content = "가자. 시간 낭비하지 말고.",
  ui_story_1015_10150302_31_dialog_content = "<color=#e8d9bb>위이잉──</color>",
  ui_story_1015_10150302_32_dialog_content = "문이 열렸어, 들어가.",
  ui_story_1015_10150302_33_dialog_content = "너흰 앞에 가서 기다려.",
  ui_story_1015_10150302_34_dialog_content = "뭘 하려고?",
  ui_story_1015_10150302_35_dialog_content = "...도어락 비밀번호를 바꾼 거야?",
  ui_story_1015_10150302_36_dialog_content = "...흥.",
  ui_story_1015_10150302_37_dialog_content = "(경비병이 쫓아오는 걸 막으려고 문을 잠가서 시간을 벌 생각이겠지.)",
  ui_story_1015_10150302_38_dialog_content = "휴... 우릴 막으려던 문이 반대로 경비병을 막게 생겼잖아.",
  ui_story_1015_10150302_39_dialog_content = "기계는 의식이 없어. 그저 사용할 줄 아는 사람을 도울 뿐이지.",
  ui_story_1015_10150302_40_dialog_content = "넌 여길 잘 아는 모양이네.",
  ui_story_1015_10150302_41_dialog_content = "음?",
  ui_story_1015_10150302_42_dialog_content = "연구소 외곽의 경계선도 돌파했고, 내부 지형도 잘 알고 있고,\n심지어 문이랑 기계 대부분을 조작할 수 있잖아.",
  ui_story_1015_10150302_43_dialog_content = "일루미나가 연구 장소를 보호하려고 준비한 것들이 네 앞에선 전부 무용지물이 됐다고.",
  ui_story_1015_10150302_44_dialog_content = "네가 말한 건 모두 내가 계획을 실행하는 데 필요한 조건들이야.",
  ui_story_1015_10150302_45_dialog_content = "그렇게 못 한다면, 난 여기 나타나지도 않았을 거야.",
  ui_story_1015_10150302_46_dialog_content = "어떻게 한 거야? 한때 일루미나의 연구원이었다는 것만으로 그게 가능해?",
  ui_story_1015_10150302_47_dialog_content = "이 연구소는 내가 직접 지었거든.",
  ui_story_1015_10150302_48_dialog_content = "뭐?!",
  ui_story_1015_10150302_49_dialog_content = "네가 지었다고...?",
  ui_story_1015_10150302_50_dialog_content = "그땐 「X호 지하성」이라고 불렸어.",
  ui_story_1015_10150302_51_dialog_content = "자, 키 재설정은 끝났어.",
  ui_story_1015_10150302_52_dialog_content = "이제 오늘 실험을 시작해야 해.",
  ui_story_1015_10150302_53_dialog_content = "앗, 진짜 화음 연결 장치잖아?!",
  ui_story_1015_10150302_54_dialog_content = "귀환의 탑에 있던 거랑 조금 다르긴 하지만, 확실히 같은 유형의 장치야.",
  ui_story_1015_10150302_55_dialog_content = "일루미나의 비밀 연구는 수년 동안 지속되어 왔어. 보안 등급도 아주 높지.",
  ui_story_1015_10150302_56_dialog_content = "접근 권한이 있는 건 위원회와 과학 수석 의회의 노인네들뿐이야.",
  ui_story_1015_10150302_57_dialog_content = "일루미나의 연구가 대체 어디까지 진행된 거지...",
  ui_story_1015_10150302_58_dialog_content = "근데 지금까진 우릴 여기 못 들어오게 해 놓고, 왜 오늘은 생각을 바꿨어?",
  ui_story_1015_10150302_59_dialog_content = "연구가 새로운 단계에 접어들었거든.",
  ui_story_1015_10150302_60_dialog_content = "일루미나는 이 기기의 사용법을 찾기 위해 수십 년을 투자했어.\n하지만 난 그렇게 많은 시간은 없어.",
  ui_story_1015_10150302_61_dialog_content = "그래서 난 실험을 통해 저들의 방법을 배울 거야.",
  ui_story_1015_10150302_62_dialog_content = "무슨 뜻이야?",
  ui_story_1015_10150302_63_dialog_content = "난 화음 연결 장치를 한 번 작동시켜서, 그 과정 속에서 장치의 원리를 이해할 거야.",
  ui_story_1015_10150302_64_dialog_content = "내가 왜 너희를 데리고 들어왔는지 알아?",
  ui_story_1015_10150302_65_dialog_content = "뭐? 그, 그걸 누구한테 쓰려고?!",
  ui_story_1015_10150302_66_dialog_content = "당연히 미리 준비해 둔 「실험체」지.",
  ui_story_1015_10150302_67_dialog_content = "너...!",
  ui_story_1015_10150302_68_dialog_content = "안 돼! 바이스를 건드리지 마!",
  ui_story_1015_10150302_69_dialog_content = "제이드.",
  ui_story_1015_10150302_70_dialog_content = "<size=50><anim type=Shake>크어어어──!</anim></size>",
  ui_story_1015_10150302_71_dialog_content = "크윽... 무거워...",
  ui_story_1015_10150302_72_dialog_content = "바, 바이스를 놔 줘! 사용법도 제대로 모르면서 함부로 굴지 말라고!",
  ui_story_1015_10150302_73_dialog_content = "내가 사용법을 알게 만드는 게 「실험체」의 역할인걸.",
  ui_story_1015_10150302_74_dialog_content = "과학 연구란 건 어둠 속으로 손을 내미는 것과 같아.\n손이 찔리고 긁혀야만 세상의 모양을 알아낼 수 있는 거야.",
  ui_story_1015_10150302_75_dialog_content = "시도가 없다면 연구의 과정은 영원히 진전을 이룰 수 없어.",
  ui_story_1015_10150302_76_dialog_content = "말은 잘하네! 그럼 왜 네가 직접 안 하는 건데?!",
  ui_story_1015_10150302_77_dialog_content = "날 가지고 시도하면 실패는 한 번밖에 허용되지 않아.\n대신 「실험체」를 쓰면 수많은 실패가 허용되지.",
  ui_story_1015_10150302_78_dialog_content = "연구는 도박이 아니야, 난 당연히 더 많은 기회가 필요해.",
  ui_story_1015_10150302_79_dialog_content = "<size=45>이... 자식...</size>",
  ui_story_1015_10150302_80_dialog_content = "바이스 양, 그럼 준비가 됐길 바랄게.",
  ui_story_1015_10150302_81_dialog_content = "네가 처음 화음 연결 장치를 썼을 때처럼 말이야.",
  ui_story_1015_10150302_82_dialog_content = "이거 놔!",
  ui_story_1015_10150302_83_dialog_content = "화음 연결 시험 가동, 실험 캡슐 및 실험체 준비 완료.",
  ui_story_1015_10150302_84_dialog_content = "실험을 시작한다.",
  ui_story_1015_10150302_85_dialog_content = "율리시스 님, 이대로는 곤란합니다.",
  ui_story_1015_10150302_86_dialog_content = "이미 경비병들을 보내 수색 및 포위 인력을 보강했지만, 여전히 침입자를 잡지 못했습니다.",
  ui_story_1015_10150302_87_dialog_content = "현재 분위기가 심상치 않습니다.\n다수의 연구원들이 실험실에 갈 엄두도 못 내고 있습니다.",
  ui_story_1015_10150302_88_dialog_content = "침입자의 신원은 파악했나?",
  ui_story_1015_10150302_89_dialog_content = "확인했습니다. 추측하신 대로 노라였습니다.",
  ui_story_1015_10150302_90_dialog_content = "노라가 대체 어떻게 침입한 건지 정말 모르겠습니다.\n수색도 피했을 뿐만 아니라 모든 방어 조치를 통과했습니다.",
  ui_story_1015_10150302_91_dialog_content = "참, 어떤 병사가 며칠째 연락이 끊긴 그 아이테르를 본 것 같다고 합니다.\n설마 그가 사실은 노라와 내통한 건 아니겠지요?",
  ui_story_1015_10150302_92_dialog_content = "노라라면 내통자가 전혀 필요하지 않을 걸세.",
  ui_story_1015_10150302_93_dialog_content = "예?",
  ui_story_1015_10150302_94_dialog_content = "노라는 누구보다 이곳을 잘 알고 있네. 「X호 연구소」를 세운 장본인이니 말이야.",
  ui_story_1015_10150302_95_dialog_content = "여길 노라가 만들었단 말입니까? 전 율리시스 님이 만드신 줄 알았습니다만...",
  ui_story_1015_10150302_96_dialog_content = "11년 전, 노라가 아직 일루미나에 있었을 때, 그녀는 가장 잠재력 있는 연구원이었지.",
  ui_story_1015_10150302_97_dialog_content = "노라는 내게 이름 없는 버려진 지하성을 비밀리에 인수하겠다는 신청서를 제출했네.",
  ui_story_1015_10150302_98_dialog_content = "그리고 그걸 「X호 지하성」이라고 명명했는데, 그것이 바로 현재 이 연구소의 전신일세.",
  ui_story_1015_10150302_99_dialog_content = "그랬군요.",
  ui_story_1015_10150302_100_dialog_content = "그 후 노라가 일루미나를 배반하면서 연구소도 지금의 모습으로 변한 겁니까?",
  ui_story_1015_10150302_101_dialog_content = "그렇다고 할 수 있겠지.",
  ui_story_1015_10150302_102_dialog_content = "노라는 천부적인 재능이 있었네. 하지만 천부적인 재능이란 무서운 것이지.",
  ui_story_1015_10150302_103_dialog_content = "그건 그녀가 보통 사람을 뛰어넘어, 끝없이 급진적이고 위험한 시도를 하게 만들었거든.",
  ui_story_1015_10150302_104_dialog_content = "그녀의 방식으로 「X호 지하성」은 일루미나 연방에서\n가장 앞선 생명공학 기술을 장악했네.",
  ui_story_1015_10150302_105_dialog_content = "그러나 그와 함께 끝없이 팽창하는 위험을 키워내고 있었지.",
  ui_story_1015_10150302_106_dialog_content = "일루미나뿐만 아니라, 그녀 자신도 감당할 수 없는 위험을 말이야.",
  ui_story_1015_10150302_107_dialog_content = "노라가 제명된 건 연구 중 심각한 사고가 발생했기 때문이라고 들었습니다만...",
  ui_story_1015_10150302_108_dialog_content = "맞네. 큰 화재로 「X호 지하성」이 소실되었지.",
  ui_story_1015_10150302_109_dialog_content = "하지만 사고는 그저 불씨였을 뿐,\n그 불씨는 상부가 노라의 비밀을 들여다보도록 이끌었네.",
  ui_story_1015_10150302_110_dialog_content = "일루미나가 진정으로 노라를 용납할 수 없었던 건\n그 연구의 비인간적이고 통제할 수 없는 본질이었지.",
  ui_story_1015_10150302_111_dialog_content = "근원을 막지 않으면 불은 점점 더 세차게 타오를 뿐이야.",
  ui_story_1015_10150302_112_dialog_content = "확실히 그렇겠죠. 만약 자난성에서 사고가 발생한다면,\n그 결과는 상상도 하고 싶지 않군요.",
  ui_story_1015_10150302_113_dialog_content = "하지만... 큰 사고가 있었던 「X호 지하성」은 어째서 폐기되지 않은 겁니까?",
  ui_story_1015_10150302_114_dialog_content = "연구 장소로 사용할 수 있는 지하성은 다른 곳에도 많이 있지 않습니까?",
  ui_story_1015_10150302_115_dialog_content = "휴, 그래서 내가 말하지 않았나. 천부적인 재능은 무서운 것이라고.",
  ui_story_1015_10150302_116_dialog_content = "그 실험들이 아무리 윤리에 어긋나고, 어떤 위해를 끼친다 해도,\n그녀의 뛰어난 연구 성과를 덮을 수는 없었네.",
  ui_story_1015_10150302_117_dialog_content = "결국 나도 그녀와 같은 부류였거든.",
  ui_story_1015_10150302_118_dialog_content = "난 노라가 남긴 물건이 아까웠네.",
  ui_story_1015_10150302_119_dialog_content = "그랬습니까...",
  ui_story_1015_10150302_120_dialog_content = "그 일이 끝나고, 난 손상된 지하성을 재건했고, 지금의 「X호 연구소」를 만들었네.",
  ui_story_1015_10150302_121_dialog_content = "노라가 남긴 장비와 성과에 힘입어 일루미나의 생물학 분야 연구는 더 발전할 수 있었지.",
  ui_story_1015_10150302_122_dialog_content = "그렇게 본다면 노라는 일루미나를 위해 좋은 일을 한 셈이군요.",
  ui_story_1015_10150302_123_dialog_content = "모든 일에는 대가가 있는 법일세. 그리고 이젠 우리가 빚을 갚을 때가 된 것이지.",
  ui_story_1015_10150302_124_dialog_content = "「X호 연구소」는 건물 전체를 새롭게 정비했지만,\n그 뼈대와 원리적인 부분은 뒤엎을 수 없었네.",
  ui_story_1015_10150302_125_dialog_content = "노라의 눈에 우리가 한 건 그저 오르골의 태엽을 갈아주고 새 천을 씌웠을 뿐이겠지.",
  ui_story_1015_10150302_126_dialog_content = "이제 손을 뻗기만 하면 자신의 곡을 연주할 수 있을 걸세.",
  ui_story_1015_10150401_1_dialog_content = "그렇게 본다면... X호 연구소의 상황은 매우 위험하군요.",
  ui_story_1015_10150401_2_dialog_content = "병력은 우리가 우세하지만, 전력은 팽팽한 대치를 이루고 있습니다.",
  ui_story_1015_10150401_3_dialog_content = "노라는 이곳의 지형을 잘 알고 있습니다.\n우리가 병력을 집중해 자신을 토벌할 기회는 절대 주지 않을 겁니다.",
  ui_story_1015_10150401_4_dialog_content = "지금 노라는 거의 원하는 대로 자유롭게 움직이고 있는 것 같습니다...",
  ui_story_1015_10150401_5_dialog_content = "자네 말이 맞아, 경비병으로는 노라를 어찌할 수 없어.",
  ui_story_1015_10150401_6_dialog_content = "단일 작전 능력으로 그녀와 필적할 수 있는 인원이 없는 한,\n경비병은 아무리 많아도 소용없네.",
  ui_story_1015_10150401_7_dialog_content = "그렇다면 이대로 있을 순 없습니다...",
  ui_story_1015_10150401_8_dialog_content = "율리시스 님, 자난성에 지원을 요청하는 게 좋겠습니다.",
  ui_story_1015_10150401_9_dialog_content = "지원이 조금만 더 있다면 분명히...",
  ui_story_1015_10150401_10_dialog_content = "안 돼.",
  ui_story_1015_10150401_11_dialog_content = "예? 어째서입니까?",
  ui_story_1015_10150401_12_dialog_content = "그리 간단한 일이 아니니까.",
  ui_story_1015_10150401_13_dialog_content = "지원을 요청해서 해결될 문제였다면, 내가 진작 자난성에 보고했겠지.\n그걸 자네가 일깨워 줄 필요가 있을까?",
  ui_story_1015_10150401_14_dialog_content = "전 잘 모르겠습니다...",
  ui_story_1015_10150401_15_dialog_content = "여긴 기밀 연구소라네. 모든 일은 보안을 유지해야 하지.",
  ui_story_1015_10150401_16_dialog_content = "군에 알리는 건 결코 좋은 일이 아니야. 노라가 어떻게 제명되었는지를 잊지 말게.",
  ui_story_1015_10150401_17_dialog_content = "...예.",
  ui_story_1015_10150401_18_dialog_content = "제 생각이 짧았습니다.\n전 그저 지금 눈앞의 문제가 더 중요하다고 생각했습니다.",
  ui_story_1015_10150401_19_dialog_content = "노라는 연구자야. 여기 잠입한 건 실험을 하기 위해서지.",
  ui_story_1015_10150401_20_dialog_content = "결국 이건 과학자 간의 충돌에 불과한 것일세.",
  ui_story_1015_10150401_21_dialog_content = "하지만 군이 개입하게 되면, 이야기는 달라지지.",
  ui_story_1015_10150401_22_dialog_content = "예, 이해했습니다.",
  ui_story_1015_10150401_23_dialog_content = "정말 이해했나?",
  ui_story_1015_10150401_24_dialog_content = "......",
  ui_story_1015_10150401_25_dialog_content = "허허, 자넨 군인이니 명령만 수행하면 그만이지. 내 생각을 이해할 필요는 없네.",
  ui_story_1015_10150401_26_dialog_content = "그저 이 모든 걸 하나의 실험이라고 생각하게.",
  ui_story_1015_10150401_27_dialog_content = "실험의 내용은 반드시 대외비여야 하며, 이는 규정에도 쓰여 있지. 알겠나?",
  ui_story_1015_10150401_28_dialog_content = "예!",
  ui_story_1015_10150401_29_dialog_content = "자, 이 일은 됐고, 다음은 자네가 알아들을 수 있는 걸 이야기해 볼까.",
  ui_story_1015_10150401_30_dialog_content = "자난성의 지원군이 없다고 해서 내가 가만히 앉아 죽길 기다리는 건 아니라네.",
  ui_story_1015_10150401_31_dialog_content = "노라를 어떻게 상대할지는 나도 나름대로 방법이 있으니 말이야.",
  ui_story_1015_10150401_32_dialog_content = "어떤 방법입니까...?",
  ui_story_1015_10150401_33_dialog_content = "<color=#e8d9bb>똑똑똑.</color>",
  ui_story_1015_10150401_34_dialog_content = "들어와라.",
  ui_story_1015_10150401_35_dialog_content = "일루미나 정보장교 잉겔 중령, 보고드립니다!",
  ui_story_1015_10150401_36_dialog_content = "<color=#e8d9bb>삐── 삐──</color>",
  ui_story_1015_10150401_37_dialog_content = "이렇게 작동하는 거였군...",
  ui_story_1015_10150401_38_dialog_content = "그래. 신체 구조만 바꿔서는 소용없지.",
  ui_story_1015_10150401_39_dialog_content = "루미나의 궤적은 여기 없어. 그건 더 깊은 곳에 숨겨져 있어...",
  ui_story_1015_10150401_40_dialog_content = "(바이스! 좀 어때?)",
  ui_story_1015_10150401_41_dialog_content = "(어디 불편한 데 없어?)",
  ui_story_1015_10150401_42_dialog_content = "(아직은 괜찮아. 근데 왠지 어떤 힘이 내 몸속의 루미나를 흐르게 해주고 있는 것 같아.)",
  ui_story_1015_10150401_43_dialog_content = "(그래? 그럼 당장은 괜찮겠네. 별일이 없었으면 좋겠는데...)",
  ui_story_1015_10150401_44_dialog_content = "(그렇게 걱정할 거 없어. 난 이미 한 번 화음 연결을 겪어봤잖아.)",
  ui_story_1015_10150401_45_dialog_content = "(하지만...)",
  ui_story_1015_10150401_46_dialog_content = "(그것보다 내 말 좀 들어 봐. 지금이 기회 같지 않아?)",
  ui_story_1015_10150401_47_dialog_content = "(기회?)",
  ui_story_1015_10150401_48_dialog_content = "(화음 연결 장치는 오로리안의 힘을 강화시켜 주잖아?)",
  ui_story_1015_10150401_49_dialog_content = "(어쩌면 이번 강화로 날 묶고 있는 밧줄을 풀 수 있을 것 같아.)",
  ui_story_1015_10150401_50_dialog_content = "(진짜? 가능할까?)",
  ui_story_1015_10150401_51_dialog_content = "(아마 할 수 있을 거야. 어쩌면 지금 당장도 가능할걸.)",
  ui_story_1015_10150401_52_dialog_content = "(근데 벗어난 뒤에 노라, 제이드와 어떻게 싸울지가 문제야.)",
  ui_story_1015_10150401_53_dialog_content = "(더 많은 힘이 필요해. 지금은 화음 연결의 강화에 기대해 보는 수밖에 없어.)",
  ui_story_1015_10150401_54_dialog_content = "(음... 노라는 지금 데이터에만 집중하고 있어. 확실히 좋은 반격 기회야.)",
  ui_story_1015_10150401_55_dialog_content = "(그렇지? 녀석한테 자기 실험 결과가 어떤지 제대로 보여주자구!)",
  ui_story_1015_10150401_56_dialog_content = "(이따가 우리 둘이 같이 움직여야 해. 기회는 딱 한 번뿐이야.)",
  ui_story_1015_10150401_57_dialog_content = "(노라가 반응하기 전에 제압하는 게 좋아. 장기전으로 끌고 가면 우리한테 불리하니까.)",
  ui_story_1015_10150401_58_dialog_content = "(알겠어. 한 방에 제압할 수 있는 기회를 찾아볼게.)",
  ui_story_1015_10150401_59_dialog_content = "(응! 그럼 부탁할게!)",
  ui_story_1015_10150401_60_dialog_content = "노라, 실험은 얼마나 남았어?",
  ui_story_1015_10150401_61_dialog_content = "제이드인지 뭔지 이 녀석 꼬리가 너무 무거워. 숨도 못 쉬겠다고.",
  ui_story_1015_10150401_62_dialog_content = "곧 끝나. 조용히 있어.",
  ui_story_1015_10150401_63_dialog_content = "곧이 언젠데? 정확한 시간을 말해줄 순 없어?",
  ui_story_1015_10150401_64_dialog_content = "이제 최종 단계야.",
  ui_story_1015_10150401_65_dialog_content = "<color=#e8d9bb>삑──</color>",
  ui_story_1015_10150401_66_dialog_content = "(PlayerName! 루미나의 흐름이 빨라지기 시작했어!)",
  ui_story_1015_10150401_67_dialog_content = "(그럼 준비하자. 강화가 끝나는 순간에 우리도 움직이는 거야!)",
  ui_story_1015_10150401_68_dialog_content = "(응!)",
  ui_story_1015_10150401_69_dialog_content = "(탈출하자마자 먼저 노라를 공격해. 제이드는 아마 본능적으로 노라를 돕겠지.\n그럼 그때 네가...)",
  ui_story_1015_10150401_70_dialog_content = "참, 아이테르.",
  ui_story_1015_10150401_71_dialog_content = "어? 왜?",
  ui_story_1015_10150401_72_dialog_content = "넌 남은 시간에만 관심 있고, 실험이 성공했는지에는 관심 없어?",
  ui_story_1015_10150401_73_dialog_content = "아...",
  ui_story_1015_10150401_74_dialog_content = "(이런, 우리 계획을 눈치챈 건가?)",
  ui_story_1015_10150401_75_dialog_content = "(바이스... 강화가 언제 끝날 것 같아?)",
  ui_story_1015_10150401_76_dialog_content = "걱정 마, 바이스의 몸에는 아무런 변화도 없으니까.",
  ui_story_1015_10150401_77_dialog_content = "부상도 없었고, 기대한 만큼의 향상도 없었어.",
  ui_story_1015_10150401_78_dialog_content = "실험은 끝났어.",
  ui_story_1015_10150401_79_dialog_content = "<color=#e8d9bb>위이잉...</color>",
  ui_story_1015_10150401_80_dialog_content = "(뭐야?! 강화가 중단됐어?!)",
  ui_story_1015_10150401_81_dialog_content = "너, 너 뭐 하는 거야?",
  ui_story_1015_10150401_82_dialog_content = "화음 연결 장치를 껐을 뿐이야.",
  ui_story_1015_10150401_83_dialog_content = "실험은 이 정도면 충분해. 난 실험체에 불필요한 변화가 발생하는 걸 바라진 않거든.",
  ui_story_1015_10150401_84_dialog_content = "설마 너희, 뭔가 기대하고 있었어?",
  ui_story_1015_10150401_85_dialog_content = "(어떡하지? 바이스, 우리 계획을 알아챈 것 같아...)",
  ui_story_1015_10150401_86_dialog_content = "(그런 거 따질 때가 아니야! 기회라고 할 만한 것도 이번뿐이니까!)",
  ui_story_1015_10150401_87_dialog_content = "(지금 바로 밧줄을 풀 테니까 준비해!)",
  ui_story_1015_10150401_88_dialog_content = "말 안 해? 아무래도 내가 너희한테 비현실적인 상상을 하게 만든 모양이네.",
  ui_story_1015_10150401_89_dialog_content = "흥, 비현실적인지 아닌지는 네가 얻어터지고 나서 알게 될걸!",
  ui_story_1015_10150401_90_dialog_content = "<color=#e8d9bb>후두둑──</color>",
  ui_story_1015_10150401_91_dialog_content = "역시 화음 연결의 힘을 빌려서 밧줄을 풀었구나.",
  ui_story_1015_10150401_92_dialog_content = "뭐, 괜찮아. 애초에 그것도 내가 예상했던 위험 범위 안이거든.",
  ui_story_1015_10150401_93_dialog_content = "한 번 잡은 녀석을 두 번은 못 잡을 것 같아?",
  ui_story_1015_10150401_94_dialog_content = "바이스! 노라가 숨어 있는 암귀들을 불러 모으고 있어!",
  ui_story_1015_10150401_95_dialog_content = "서둘러!",
  ui_story_1015_10150502_1_dialog_content = "하...하아...",
  ui_story_1015_10150502_2_dialog_content = "역시 안 되는 건가...",
  ui_story_1015_10150502_3_dialog_content = "화음 연결의 강화로 밧줄에서 벗어나겠다는 생각,\n고작 네가 떠올릴 수 있는 걸 내가 생각 못 했을까?",
  ui_story_1015_10150502_4_dialog_content = "이걸 기회라고 여기지 마. 난 진작에 준비가 돼 있었거든.",
  ui_story_1015_10150502_5_dialog_content = "싸우면서 잡담할 여유는 있는 모양이지?",
  ui_story_1015_10150502_6_dialog_content = "이건 싸움이 아니야. 싸움은 이미 끝났어.",
  ui_story_1015_10150502_7_dialog_content = "난 너랑 소란 피우고 있을 시간이 없어.",
  ui_story_1015_10150502_8_dialog_content = "그런다고 네 맘대로 될 줄 알고?!",
  ui_story_1015_10150502_9_dialog_content = "그럼 저쪽은 어떨까?",
  ui_story_1015_10150502_10_dialog_content = "<size=45>바이스! 뒤에!</size>",
  ui_story_1015_10150502_11_dialog_content = "뭐...?",
  ui_story_1015_10150502_12_dialog_content = "<size=45>으아악──!</size>",
  ui_story_1015_10150502_13_dialog_content = "<size=45>바이스!!!</size>",
  ui_story_1015_10150502_14_dialog_content = "헬리오스... 주변에 숨어 있었나...",
  ui_story_1015_10150502_15_dialog_content = "반항은 너희에게 있어서 가장 어리석은 선택이야.",
  ui_story_1015_10150502_16_dialog_content = "성공할 가능성도 없고, 실험 과정을 방해하는 요소가 될 뿐이거든.",
  ui_story_1015_10150502_17_dialog_content = "난 실험이 방해받는 걸 좋아하지 않아.",
  ui_story_1015_10150502_18_dialog_content = "뭐, 뭘 하려는 거야?",
  ui_story_1015_10150502_19_dialog_content = "오늘 실험은 끝났어. 데이터만 정리하고 여길 떠날 거야.",
  ui_story_1015_10150502_20_dialog_content = "아이테르는 날 따라와.\n헬리오스 넌 바이스를 데려가. <color=#FFB400>따로</color> 움직이자.",
  ui_story_1015_10150502_21_dialog_content = "따로?!",
  ui_story_1015_10150502_22_dialog_content = "방금 상황으로 봤을 때, 너흰 둘이서 불확정 요인을 형성했어.",
  ui_story_1015_10150502_23_dialog_content = "그렇다면 앞으로는 조금 떨어져 있는 게 좋겠어.",
  ui_story_1015_10150502_24_dialog_content = "잘 들어라, 잉겔. 현재 상황은 다음과 같다.",
  ui_story_1015_10150502_25_dialog_content = "노라는 이 연구소에 잠입했고, 우리의 연구 기구를 무단으로 사용했다.",
  ui_story_1015_10150502_26_dialog_content = "또한 앞서 연구소를 방문했던 바이스 중위와 그 아이테르는 며칠째 연락이 끊겼다.",
  ui_story_1015_10150502_27_dialog_content = "병사들의 목격 정보를 종합했을 때, 난 그들이 노라에게 납치당했을 거라 짐작하고 있다.",
  ui_story_1015_10150502_28_dialog_content = "PlayerName...",
  ui_story_1015_10150502_29_dialog_content = "율리시스 교수님, 제가 수행해야 할 임무는 무엇입니까?",
  ui_story_1015_10150502_30_dialog_content = "인질을 구출하고 노라를 체포해라.",
  ui_story_1015_10150502_31_dialog_content = "<size=45>!!!</size>",
  ui_story_1015_10150502_32_dialog_content = "(그렇게 어려운 임무를 일개 중령에게 맡긴다고?)",
  ui_story_1015_10150502_33_dialog_content = "...임무를 수행하겠습니다.",
  ui_story_1015_10150502_34_dialog_content = "하지만 교수님, 현재 상황으로는 임무를 완수할 가능성이 매우 낮습니다.",
  ui_story_1015_10150502_35_dialog_content = "상대는 지형에 익숙하고, 실력도 상당하며, 인질까지 잡고 있습니다.",
  ui_story_1015_10150502_36_dialog_content = "저 혼자라면 어떤 우세도 없습니다.",
  ui_story_1015_10150502_37_dialog_content = "만약 「<color=#FFB400>병기</color>」 사용을 신청할 수 있다면...",
  ui_story_1015_10150502_38_dialog_content = "악셀리아의 도움을 받길 원하는 것이겠지.",
  ui_story_1015_10150502_39_dialog_content = "...네.",
  ui_story_1015_10150502_40_dialog_content = "악셀리아의 힘에 너무 의존하지 마라.",
  ui_story_1015_10150502_41_dialog_content = "너흰 모두 「<color=#FFB400>계명성 프로젝트</color>」의 멤버다. 그저 중점을 둔 방향이 다를 뿐이지.",
  ui_story_1015_10150502_42_dialog_content = "이번엔 힘으로 부딪혀서 해결될 문제가 아니다. 지금 필요한 건 네가 잘하는 방식이다.",
  ui_story_1015_10150502_43_dialog_content = "알겠습니다, 교수님.",
  ui_story_1015_10150502_44_dialog_content = "게다가 악셀리아는 다른 중요한 계획을 준비해야 한다. 너도 곧 알게 될 거다.",
  ui_story_1015_10150502_45_dialog_content = "물론 저런 적과 싸우려면 너도 비장의 카드가 있어야겠지.",
  ui_story_1015_10150502_46_dialog_content = "넌 내게서 두 장의 카드를 얻을 수 있다.",
  ui_story_1015_10150502_47_dialog_content = "어떤 것입니까?",
  ui_story_1015_10150502_48_dialog_content = "첫 번째 카드는 증원이다.",
  ui_story_1015_10150502_49_dialog_content = "널 위해 믿을 만한 조력자를 차출했다. 지금 이쪽으로 오는 중이다.",
  ui_story_1015_10150502_50_dialog_content = "위원회가 신뢰하는 정보장교, 아나톨리 소령이지.",
  ui_story_1015_10150502_51_dialog_content = "아는 사람이네요! 확실히 효과적인 조력자입니다!",
  ui_story_1015_10150502_52_dialog_content = "또 다른 카드는...",
  ui_story_1015_10150502_53_dialog_content = "네가 그걸 마지막까지 남겨 두었으면 좋겠군.",
  ui_story_1015_10150601_1_dialog_content = "<color=#e8d9bb>더스크 타운, 백야 요새 안</color>",
  ui_story_1015_10150601_2_dialog_content = "......",
  ui_story_1015_10150601_3_dialog_content = "<color=#e8d9bb>똑똑──</color>",
  ui_story_1015_10150601_4_dialog_content = "들어와!",
  ui_story_1015_10150601_5_dialog_content = "...아, 조셀린, 당신이었군요.",
  ui_story_1015_10150601_6_dialog_content = "황혼이 다가오고 이제 기도가 시작될 텐데... 누굴 기다리고 있던 모양이네요.",
  ui_story_1015_10150601_7_dialog_content = "제가 때를 잘못 맞춰 왔군요.",
  ui_story_1015_10150601_8_dialog_content = "정보원의 보고를 기다리고 있었을 뿐입니다.\n기사단에게 지금 가장 중요한 일이거든요.",
  ui_story_1015_10150601_9_dialog_content = "전선 쪽 상황은 좋지 않아요. 점점 더 많은 주변 마을이 암귀의 공격을 받고 있어요.",
  ui_story_1015_10150601_10_dialog_content = "이 지하성의 규모라면 저 주민들을 받아들일 여력은 충분하지만...",
  ui_story_1015_10150601_11_dialog_content = "이대로 가다가는 지상의 통제권을 상실하게 될 거예요.",
  ui_story_1015_10150601_12_dialog_content = "맞습니다. 그리고 그런 상황이 벌어지는 건 절대 보고 싶지 않군요.",
  ui_story_1015_10150601_13_dialog_content = "암귀는 계속 모여들고 있지만, 아직까지 대규모 공세를 펼치진 않았습니다.\n백야성과 일루미나 연방도 마찬가지로 출군 지시를 내리고 있지 않습니다.",
  ui_story_1015_10150601_14_dialog_content = "병사들은 이미 기다리느라 지쳤습니다.\n이런 기다림은 저들에게 오히려 일종의 손실이 될 뿐입니다.",
  ui_story_1015_10150601_15_dialog_content = "그럼 부디 오늘의 일일 기도가 병사들의 근심을 조금이나마 달래줄 수 있길 바랄게요.",
  ui_story_1015_10150601_16_dialog_content = "고마워요, 조셀린.",
  ui_story_1015_10150601_17_dialog_content = "<color=#e8d9bb>똑똑──</color>",
  ui_story_1015_10150601_18_dialog_content = "휴...휴우...",
  ui_story_1015_10150601_19_dialog_content = "레오 단장님... 일루미나에서 소식이 왔습니다!",
  ui_story_1015_10150601_20_dialog_content = "일루미나에서 통신을 보내 주둔군 전원에게 준비 명령을 내렸습니다!",
  ui_story_1015_10150601_21_dialog_content = "뭘 준비하라는 거지?",
  ui_story_1015_10150601_22_dialog_content = "여, <color=#FFB400>연합 훈련</color> 준비입니다...",
  ui_story_1015_10150601_23_dialog_content = "?!",
  ui_story_1015_10150601_24_dialog_content = "<color=#e8d9bb>더스크 타운, 공동 통치 지하성.</color>",
  ui_story_1015_10150601_25_dialog_content = "이건 더스크 타운에 대한 연례적 초청인가요?",
  ui_story_1015_10150601_26_dialog_content = "네, 참모장님, 훈련 날짜는 전적으로 윗선 마음대로지만,\n그래도 어쨌든 오랜 전통이라고 할 수 있어요.",
  ui_story_1015_10150601_27_dialog_content = "그렇군요. 장병들에게는 그리 반가운 소식이 아닐 텐데요.",
  ui_story_1015_10150601_28_dialog_content = "에이 참, 왜 하필 꼭 이럴 때 하는 건지 모르겠어요!",
  ui_story_1015_10150601_29_dialog_content = "「한 번의 북소리는 사기를 높이고, 다시 치면 떨어진다」고 했습니다.\n아무리 큰 규모의 훈련도 호쾌한 전투 한 번보다는 못한 법인데 말이죠.",
  ui_story_1015_10150601_30_dialog_content = "초청장엔 뭐라고 쓰여 있었죠? 더스크 타운에서는 몇 명을 보내야 하는 겁니까?",
  ui_story_1015_10150601_31_dialog_content = "세 사람이요. 일루미나 군인, 백야성 기사, 성직자 한 명씩이요.\n그럼 참모장님 말고 나머지는...",
  ui_story_1015_10150601_32_dialog_content = "<color=#e8d9bb>더스크 타운, 백야 요새 안</color>",
  ui_story_1015_10150601_33_dialog_content = "알겠어. 비록 여긴 공동 통치 구역이긴 하지만,\n너흰 모두 일루미나의 명령이 그리 마음에 들지 않는 모양이네.",
  ui_story_1015_10150601_34_dialog_content = "그거야 당연한 거 아닙니까!\n자난성의 군인들은 항상 저런 융통성 없는 형식적인 일만 하니 말입니다.",
  ui_story_1015_10150601_35_dialog_content = "여기 전선은 일촉즉발인 상황인데, 고작 저들의 흥미나 만족시켜 줄 필요가 있겠습니까?!",
  ui_story_1015_10150601_36_dialog_content = "확실히 이 초청장을 보낸 건 생각지도 못한 깜짝 선물이긴 해.",
  ui_story_1015_10150601_37_dialog_content = "깜짝 선물? 레오 단장님, 벌써 결정한 건가요?",
  ui_story_1015_10150601_38_dialog_content = "네, 제가 가야겠습니다.",
  ui_story_1015_10150601_39_dialog_content = "단장님?!",
  ui_story_1015_10150601_40_dialog_content = "그 훈련에 여러 세력이 집결하고, 대륙 전체가 보게 될 무대라면...",
  ui_story_1015_10150601_41_dialog_content = "가서 위기에 처한 이 변방의 소식을 온 대륙에 알리는 겁니다.",
  ui_story_1015_10150601_42_dialog_content = "레오 단장님...",
  ui_story_1015_10150601_43_dialog_content = "가서 준비를 좀 하고, 요제프, 자오와 합류하겠습니다.",
  ui_story_1015_10150601_44_dialog_content = "그럼 저와 요제프가 떠나 있는 동안, 여긴 조셀린 당신에게 부탁할게요.",
  ui_story_1015_10150601_45_dialog_content = "네, 알고 있어요.",
  ui_story_1015_10150601_46_dialog_content = "강철가시 기사단과 함께 싸우며, 민중들에게 위로가 되는 힘을 주어야겠죠...",
  ui_story_1015_10150601_47_dialog_content = "돌아오면 제대로 한턱 내세요.",
  ui_story_1015_10150601_48_dialog_content = "하하, 물론 그래야죠.",
  ui_story_1015_10150601_49_dialog_content = "<color=#e8d9bb>일루미나 연방, 자난성 어딘가</color>",
  ui_story_1015_10150601_50_dialog_content = "난 결단코 반대다.",
  ui_story_1015_10150601_51_dialog_content = "내겐 확실히 반대할 권리가 있을 텐데, 아닌가?",
  ui_story_1015_10150601_52_dialog_content = "네, 대원수님, 과학 수석 의회의 규정에 따르면,\n대원수는 의회의 의견에 대한 표결권을 가지고 있습니다.",
  ui_story_1015_10150601_53_dialog_content = "그럼 수고스럽겠지만, 가서 저들에게 최대한 빨리 투표 회의를 열라고 통지해라.",
  ui_story_1015_10150601_54_dialog_content = "대원수님... 「연합 훈련」은 수석 의회에서 이해득실을 따진 끝에 결정한 사안입니다.",
  ui_story_1015_10150601_55_dialog_content = "반대표를 던지시더라도 수석 의회의 일원들이 쉽게 포기하진 않을 겁니다...",
  ui_story_1015_10150601_56_dialog_content = "너와 얘기하는 건 정말 힘들군. 율리시스보고 날 만나러 나오라고 해.",
  ui_story_1015_10150601_57_dialog_content = "죄송합니다. 율리시스 박사님은 대원수님께서 이 일로\n자신을 찾는다면 나오지 않을 거라고 하셨습니다.",
  ui_story_1015_10150601_58_dialog_content = "젠장.",
  ui_story_1015_10150601_59_dialog_content = "먼저 말해두지. 난 너희가 벌여온 수작에 끼어들 마음은 지금까지 단 한 번도 없었다.",
  ui_story_1015_10150601_60_dialog_content = "마찬가지로, 난 내 전략적 배치에 그 어떤 방해 요인이 발생하는 것도 원하지 않는다.",
  ui_story_1015_10150601_61_dialog_content = "오로라 유적에 일루미나의 지원군이 필요한 지금 같은 상황에\n군사 훈련을 빌미로 차출과 감원이라니!",
  ui_story_1015_10150601_62_dialog_content = "이게 대체 뭐 하는 짓이냔 말이다!",
  ui_story_1015_10150601_63_dialog_content = "죄송합니다, 대원수님, 전...",
  ui_story_1015_10150601_64_dialog_content = "고작 말단 병사를 난처하게 만들 필요는 없잖니?",
  ui_story_1015_10150601_65_dialog_content = "율리시스 그 노인네가 안 나온다면, 나한테 이야기해도 괜찮아.",
  ui_story_1015_10150601_66_dialog_content = "라인하르트, 지금 무척 충동적인 것 같구나. 조금 진정하는 게 좋겠어.\n카드게임 어때?",
  ui_story_1015_10150601_67_dialog_content = "「<color=#FFB400>철가면</color>」 님...",
  ui_story_1015_10150601_68_dialog_content = "재미없는 농담이군, <color=#FFB400>벨리사리아</color>. 난 카드게임 같은 건 관심 없다.",
  ui_story_1015_10150601_69_dialog_content = "그것보다 네가 모습을 드러낸 건 오히려 의외지만 말이야.",
  ui_story_1015_10150601_70_dialog_content = "농담이 아니란다. 내가 내줄 수 있는 시간과 인내심엔 한계가 있어.",
  ui_story_1015_10150601_71_dialog_content = "한 장 골라 보렴. 그리고 그 시간 안에 빨리 말하는 거야. 할 수 있겠지?",
  ui_story_1015_10150601_72_dialog_content = "......",
  ui_story_1015_10150601_73_dialog_content = "왼쪽.",
  ui_story_1015_10150601_74_dialog_content = "내 요구는 간단해. 난 싸움을 피하는 전략은 동의하지 않아.",
  ui_story_1015_10150601_75_dialog_content = "연합 훈련을 중단하고, 더스크 타운의 주둔군 지원을 최우선 전략으로 설정해라!",
  ui_story_1015_10150601_76_dialog_content = "오, 안타깝지만 넌 「조커」를 뽑았어. 네가 졌어.",
  ui_story_1015_10150601_77_dialog_content = "사전 관찰을 소홀히 한 채로 결정을 내리는 것도 역대 원수들이 지닌 공통의 폐단이었지.",
  ui_story_1015_10150601_78_dialog_content = "라인하르트, 전쟁은 네가 멋대로 할 수 있는 게임이 아니란다.\n그 본질은 어디까지나 비즈니스거든.",
  ui_story_1015_10150601_79_dialog_content = "이기고 지는 건 중요하지 않아.\n중요한 건 지면 무엇을 잃고, 이기면 무엇을 얻느냐지.",
  ui_story_1015_10150601_80_dialog_content = "넌 졌어. 그러니까 내가 주는 시간도 여기까지야.",
  ui_story_1015_10150601_81_dialog_content = "만약 네가 이 점을 배우지 못한다면,\n우리 위원회는 다른 사람을 찾아서 가르칠 수밖에 없어.",
  ui_story_1015_10150601_82_dialog_content = "......",
  ui_story_1015_10150601_83_dialog_content = "<color=#e8d9bb>빠드득──</color>",
  ui_story_1015_10150601_84_dialog_content = "<color=#e8d9bb>백야성 하이가든</color>",
  ui_story_1015_10150601_85_dialog_content = "역시 이번 일루미나 연합 훈련도 여명 아카데미에서 사람을 뽑고 있구나.",
  ui_story_1015_10150601_86_dialog_content = "후후~ 물론 우리 사천사들은 이의 없어. 자라나는 어린애들한테 기회를 많이 줘야지.",
  ui_story_1015_10150601_87_dialog_content = "...그러는 라파엘 님도 어린애잖아요!",
  ui_story_1015_10150601_88_dialog_content = "에이, 어차피 카렌 언니가 인솔할 거니까, 난 나설 필요도 없겠네.",
  ui_story_1015_10150601_89_dialog_content = "이번 기회를 잘 활용해 봐, 대장~ 한 번에 복직 심사를 통과할 수 있는 좋은 기회라구~",
  ui_story_1015_10150601_90_dialog_content = "초청장에 언니 말고 또 어떤 애들이 쓰여 있어?",
  ui_story_1015_10150601_91_dialog_content = "조금 이상해. 이번엔 여명 아카데미에서 무려 네 명이나 초대를 받았거든.",
  ui_story_1015_10150601_92_dialog_content = "나 말고도 크로이, 우라이아... 그리고 베르타까지.",
  ui_story_1015_10150601_93_dialog_content = "하지만 솔직히 난 이번 연합 훈련에는 딱히 관심 없어.",
  ui_story_1015_10150601_94_dialog_content = "이미 지난번 훈련에서 내가 이끄는 소대가 우승했었으니까.",
  ui_story_1015_10150601_95_dialog_content = "그리고 나도 그런 허무한 명예 따위로 내 정식 직위와 맞바꿀 뜻은 없어.",
  ui_story_1015_10150601_96_dialog_content = "헤에~ 역시 대장만 할 수 있는 말이네...",
  ui_story_1015_10150601_97_dialog_content = "그러니까 베르타, 괜찮지? 크로이, 우라이아와 서로 협력할 수 있겠어?",
  ui_story_1015_10150601_98_dialog_content = "에엣?!",
  ui_story_1015_10150601_99_dialog_content = "난 네가 이 3인 소대의 리더 자격을 이어받아서,\n네 「베르타 소대」를 이끌고 백야성을 위해 싸워줬으면 해.",
  ui_story_1015_10150601_100_dialog_content = "너도 백야성 외부로 파견되는 업무를 처음 수행하는 건 아니니까,\n난 네가 감당할 수 있을 거라 생각해.",
  ui_story_1015_10150601_101_dialog_content = "네네, 물론이죠. 이번 기회를 소중하게 여길게요!",
  ui_story_1015_10150601_102_dialog_content = "후후, 그럼 크로이랑 우라이아는 이제 우리 베르타한테 맡겨야겠네~",
  ui_story_1015_10150601_103_dialog_content = "잘 지켜주라구~",
  ui_story_1015_10150601_104_dialog_content = "네!",
  ui_story_1015_10150601_105_dialog_content = "근데... 지금 유일하게 자신 없는 게 하나 있어요.\n연합 훈련 장소까지 가는 거요...",
  ui_story_1015_10150601_106_dialog_content = "일루미나의 지하성들은 아주 복잡하게 지어져 있다는데,\n전 아직 한 번도 가본 적이 없어서요...",
  ui_story_1015_10150601_107_dialog_content = "아, 그건 걱정 안 해도 돼.",
  ui_story_1015_10150601_108_dialog_content = "난 리더는 아니지만, 너희와 함께 자난성에 다녀올 생각이거든.",
  ui_story_1015_10150601_109_dialog_content = "어라, 왜?",
  ui_story_1015_10150601_110_dialog_content = "어쩔 수 없어... 걱정 끼치는 녀석들이 둘이나 거기 있으니까...",
  ui_story_1015_10150701_1_dialog_content = "<color=#e8d9bb>일루미나 연방, X호 지하성</color>",
  ui_story_1015_10150701_2_dialog_content = "일루미나 연방 정보장교 아나톨리,\n위원회의 명령에 따라 당신을 보좌하러 왔습니다, 잉겔 중령님.",
  ui_story_1015_10150701_3_dialog_content = "정보장교...",
  ui_story_1015_10150701_4_dialog_content = "당신 알아요.\n전에 대원수님의 부관으로 헤븐즈 밸리에서 이클립스와 싸웠었죠.",
  ui_story_1015_10150701_5_dialog_content = "네, 잘 알고 계시는군요.\n줄곧 중령님과 함께 일할 수 있는 기회를 기대하고 있었습니다.",
  ui_story_1015_10150701_6_dialog_content = "듣기 좋은 말은 됐어요. 어서 준비부터 하는 게 좋겠네요.",
  ui_story_1015_10150701_7_dialog_content = "...뭘 적고 있는 거죠?",
  ui_story_1015_10150701_8_dialog_content = "아, 이건 제 노트입니다만, 방금 중령님의 이미지를 그려 보았습니다.\n제목은 「깔끔한 성격의 중령」입니다.",
  ui_story_1015_10150701_9_dialog_content = "당신... 뭐, 됐어요. 그게 당신의 업무 습관이라면 전 간섭하지 않겠어요.",
  ui_story_1015_10150701_10_dialog_content = "당신의 이번 임무는 저와 협력해서 인질을 구출하고 노라를 체포하는 거예요.",
  ui_story_1015_10150701_11_dialog_content = "중령님, 실례지만 먼저 좀 여쭙겠습니다.\n노라가... 이 지하성에 있는 겁니까? 게다가 인질이라니...",
  ui_story_1015_10150701_12_dialog_content = "휴, 현재 상황을 간략히 설명해 드리죠.",
  ui_story_1015_10150701_13_dialog_content = "한때 온 일루미나의 지명수배를 받았던 노라가\n바이스 중위와 아이테르 PlayerName 두 사람을 납치했어요.",
  ui_story_1015_10150701_14_dialog_content = "그리고 연구실에 잠입해 자신의 실험을 진행했죠.",
  ui_story_1015_10150701_15_dialog_content = "전 그녀의 행동이 분명히 헤븐즈 밸리의 그 전투에서\n발생한 일과 관련이 있다고 생각해요.",
  ui_story_1015_10150701_16_dialog_content = "노라는 아이테르의 기술이 바이스 중위에게 가져온 변화에 많은 관심을 가지고 있어요.",
  ui_story_1015_10150701_17_dialog_content = "그렇다면 그 두 사람이 지금 무척 위험한 상황 아닙니까?!",
  ui_story_1015_10150701_18_dialog_content = "하지만 일루미나의 정보망이 저들을 겹겹이 포위하고 있습니다.\n산 사람을 둘이나 끌고 다니면 분명 눈에 띌 텐데요.",
  ui_story_1015_10150701_19_dialog_content = "지금 가장 어려운 문제는 바이스 중위가 그 과정에서 따로 움직이게 되었다는 거예요.",
  ui_story_1015_10150701_20_dialog_content = "그러니 지금부터 우리 작전은 두 단계로 나누어 진행할게요.",
  ui_story_1015_10150701_21_dialog_content = "첫째는 바이스 중위의 행방을 찾는 거예요.\n빠르면 빠를수록 좋고, 반드시 노라보다 앞서야 해요.",
  ui_story_1015_10150701_22_dialog_content = "둘째는 노라의 계획을 망치는 거예요.\n아이테르가 인질로 잡혀 있지만, 노라도 그 사람을 함부로 대할 순 없을 테니까요.",
  ui_story_1015_10150701_23_dialog_content = "기회가 생기면 한 번에 노라를 잡는 게 가장 좋아요.",
  ui_story_1015_10150701_24_dialog_content = "네! 알겠습니다...",
  ui_story_1015_10150701_25_dialog_content = "당신 지금 또 낙서 중인가요?",
  ui_story_1015_10150701_26_dialog_content = "전 이 사람들의 성격과 행동에 대한 과거 기록을 바탕으로,\n저들의 다음 행동 경로 예상도를 그리고 있습니다.",
  ui_story_1015_10150701_27_dialog_content = "...휴, 마음대로 하세요.",
  ui_story_1015_10150701_28_dialog_content = "<color=#e8d9bb>삐빅, 삐빅!</color>",
  ui_story_1015_10150701_29_dialog_content = "음...?",
  ui_story_1015_10150701_30_dialog_content = "(이건... 새로운 손님인가요?)",
  ui_story_1015_10150701_31_dialog_content = "<color=#e8d9bb>같은 시간, X호 지하성의 어딘가</color>",
  ui_story_1015_10150701_32_dialog_content = "......",
  ui_story_1015_10150701_33_dialog_content = "멈추지 말고 빨리 따라와.",
  ui_story_1015_10150701_34_dialog_content = "왜 그래?",
  ui_story_1015_10150701_35_dialog_content = "넌 우리한테 협조해 달라고 하면서 우리 목숨에 위협이 있을 거란 말은 안 했어.",
  ui_story_1015_10150701_36_dialog_content = "바이스 말하는 거야? 걱정 마, 그 앤 못 죽어.\n내가 어떻게 그런 「아까운」 짓을 하겠어.",
  ui_story_1015_10150701_37_dialog_content = "그래서 반항하겠다는 거야? 아니면 번복하고 싶어?",
  ui_story_1015_10150701_38_dialog_content = "내가 널 어떻게 믿냐고!",
  ui_story_1015_10150701_39_dialog_content = "정말 귀찮네.",
  ui_story_1015_10150701_40_dialog_content = "이거나 받아.",
  ui_story_1015_10150701_41_dialog_content = "<color=#e8d9bb>지직... 지지직...</color>",
  ui_story_1015_10150701_42_dialog_content = "이거... 바이스랑 연결된 거야?",
  ui_story_1015_10150701_43_dialog_content = "그래. 일루미나인은 다들 하나씩 가지고 있는 <color=#FFB400>통신기</color>야.\n이건 그 애 주파수고, 난 계속 연결해 뒀어.",
  ui_story_1015_10150701_44_dialog_content = "그 애는 헬리오스가 데려갔고, 조금 뒤엔 서로 대화할 기회가 있을 거야.",
  ui_story_1015_10150701_45_dialog_content = "그럼 지금은?",
  ui_story_1015_10150701_46_dialog_content = "지금은 당연히 네가 이 병사들을 해결해 줘야지.",
  ui_story_1015_10150702_1_dialog_content = "여보세요? 바이스! 들려?",
  ui_story_1015_10150702_2_dialog_content = "PlayerName! 너야?!",
  ui_story_1015_10150702_3_dialog_content = "바이스, 괜찮아?!",
  ui_story_1015_10150702_4_dialog_content = "괜찮아... 근데 나 갇혀버렸어.",
  ui_story_1015_10150702_5_dialog_content = "여긴 텅 빈 창고인 것 같아.",
  ui_story_1015_10150702_6_dialog_content = "창고?",
  ui_story_1015_10150702_7_dialog_content = "경고하는데, 불필요한 의사소통은 하지 마.",
  ui_story_1015_10150702_8_dialog_content = "너희한테 무전기를 줘서 오히려 일만 귀찮게 만든다면...",
  ui_story_1015_10150702_9_dialog_content = "아, 알겠다고! 그럼 다른 얘기 좀 해도 돼?",
  ui_story_1015_10150702_10_dialog_content = "됐어, 그만 조잘대.",
  ui_story_1015_10150702_11_dialog_content = "저 앞이 목적지야. 일단 할 일부터 해.",
  ui_story_1015_10150702_12_dialog_content = "여긴 어디야? 들어가서 뭘 하는데?",
  ui_story_1015_10150702_13_dialog_content = "긴장할 거 없어. 그냥 대형 「<color=#FFB400>자료실</color>」이니까, 내가 원하는 걸 얻으면 바로 떠날 거야.",
  ui_story_1015_10150702_14_dialog_content = "내 시간은 아주 귀중하거든.",
  ui_story_1015_10150702_15_dialog_content = "그럼 우린 왜 아직도 여기 가만히 서 있는데?",
  ui_story_1015_10150702_16_dialog_content = "이리 와 봐.",
  ui_story_1015_10150702_17_dialog_content = "뭐?",
  ui_story_1015_10150702_18_dialog_content = "방문객 안면 정보 스캔 중...",
  ui_story_1015_10150702_19_dialog_content = "접근 데이터 분석 중...",
  ui_story_1015_10150702_20_dialog_content = "기록보관소 개방 완료.",
  ui_story_1015_10150702_21_dialog_content = "왜, 왜 나한테 열게 한 거야?",
  ui_story_1015_10150702_22_dialog_content = "내가 말했잖아, 이 연구소 전체가 내 거였다고. 하지만 그동안 율리시스가 손을 좀 썼겠지.",
  ui_story_1015_10150702_23_dialog_content = "넌 율리시스의 회의실에 들어간 적 있으니까, 분명히 이 문을 열어줄 수 있을 것 같았어.",
  ui_story_1015_10150702_24_dialog_content = "(모니터가 날 스캔했으니까, 내 뒤에 서 있던 노라도 분명히 찍혔을 거야...)",
  ui_story_1015_10150702_25_dialog_content = "(그럼 이제 얼마 안 있으면...)",
  ui_story_1015_10150702_26_dialog_content = "꾸물대지 말고 빨리 들어와.",
  ui_story_1015_10150702_27_dialog_content = "너랑 제이드는 입구에 서 있고 문 좀 닫아. 귀찮게 굴지 말고.",
  ui_story_1015_10150702_28_dialog_content = "누가 갑자기 오면 제이드가 나설 거야.",
  ui_story_1015_10150702_29_dialog_content = "...적어도 네가 무슨 파일을 찾는지는 말해줘야 할 거 아냐.",
  ui_story_1015_10150702_30_dialog_content = "율리시스가 절대 외부에 공개하지 않을 자료를 찾고 있어.",
  ui_story_1015_10150702_31_dialog_content = "난 「<color=#FFB400>계명성 프로젝트</color>」의 실험 정보를 봐야겠거든.",
  ui_story_1015_10150801_1_dialog_content = "<color=#e8d9bb>얼마 전</color>",
  ui_story_1015_10150801_2_dialog_content = "음... 개인정보 보호정책... 동의, 사용자 약관... 동의!",
  ui_story_1015_10150801_3_dialog_content = "필요한 파일 업데이트...",
  ui_story_1015_10150801_4_dialog_content = "<color=#e8d9bb>똑똑!</color>",
  ui_story_1015_10150801_5_dialog_content = "들어와...",
  ui_story_1015_10150801_6_dialog_content = "연구원장님, 자길 백야성의 「호위대장」이라고 하는 소녀가\n연구원장님을 만나고 싶다고 합니다.",
  ui_story_1015_10150801_7_dialog_content = "아, 백야성 여자애? 그럼 걔는 부팅 인터페이스 왼쪽에 서 있으라고 해...",
  ui_story_1015_10150801_8_dialog_content = "부, 부팅 인터페이스요?",
  ui_story_1015_10150801_9_dialog_content = "아~ 미안 미안, 게임 얘기였어!",
  ui_story_1015_10150801_10_dialog_content = "어? 카렌?",
  ui_story_1015_10150801_11_dialog_content = "에헤헤~ 과학자 씨도 참 무례했네.\n옆의 그분은 무려 지난번 연합 훈련의 우승자라구.",
  ui_story_1015_10150801_12_dialog_content = "잠깐 실례할게. 스카이워커호의 상황이 걱정돼서 확인 좀 하려고 왔어.",
  ui_story_1015_10150801_13_dialog_content = "그리고 바이스와 PlayerName 두 사람은?",
  ui_story_1015_10150801_14_dialog_content = "아! 스카이워커호 말이지? 지난번에 너희가 더스크 타운에 갔다 와 줘서 정말 다행이야.",
  ui_story_1015_10150801_15_dialog_content = "봐! 이제 깨어났잖아. 날개도 파닥거릴 수 있다니까.",
  ui_story_1015_10150801_16_dialog_content = "일루미나 과학 기술의 보정 덕분에 역전의 용사가 모습을 되찾았다구.\n이제 얼마든지 추락해도 걱정할 필요 없어!",
  ui_story_1015_10150801_17_dialog_content = "그거 정말 「좋은 말씀」이군요, 그로누 양.",
  ui_story_1015_10150801_18_dialog_content = "하아~ 아쉽네, PlayerName표 감응 번역이 없으니까\n스카이워커호가 나한테 고맙다고 하는 것도 못 듣고 말이야~",
  ui_story_1015_10150801_19_dialog_content = "스카이워커호가 다시 돌아왔다니 정말 다행이네.",
  ui_story_1015_10150801_20_dialog_content = "카렌 학생~ 이번에도 연합 훈련에서 우승할 생각이야?",
  ui_story_1015_10150801_21_dialog_content = "내가 공략 하나 미리 알려줄게. 이번 참가 멤버는 예전만큼 상대하기 쉽진 않을걸.",
  ui_story_1015_10150801_22_dialog_content = "아니, 난 사실상 기권했거든. 이번 백야성 3인 팀의 인솔자는 따로 있어.",
  ui_story_1015_10150801_23_dialog_content = "에? 아, 이해했어...",
  ui_story_1015_10150801_24_dialog_content = "역시 너희 셋은 빨리 만나는 게 좋겠어, 왜냐면...",
  ui_story_1015_10150801_25_dialog_content = "너흰 PlayerName 팀으로 초청된 거니까!",
  ui_story_1015_10150801_26_dialog_content = "그렇구나, 그럼 아이테르 일족도 오랜만에 다시 훈련에 모습을 드러내게 되겠네.",
  ui_story_1015_10150801_27_dialog_content = "맞아, 그러니까 정신 바짝 차리고 활약해 줘!",
  ui_story_1015_10150801_28_dialog_content = "고마워, 잘 알겠어.",
  ui_story_1015_10150801_29_dialog_content = "그럼 바이스와 PlayerName 두 사람은 대체...",
  ui_story_1015_10150801_30_dialog_content = "아, 잠깐만.",
  ui_story_1015_10150801_31_dialog_content = "<color=#e8d9bb>삑──삑!</color>",
  ui_story_1015_10150801_32_dialog_content = "너한테 준 그 초청장에 통행증이랑 지도 데이터를 넣어뒀어.",
  ui_story_1015_10150801_33_dialog_content = "지도상에 표시된 좌표가 바로 X호 지하성이야.\n거긴 일루미나에서 특수한 오로리안을 치료하고 연구하는 곳이야.",
  ui_story_1015_10150801_34_dialog_content = "(근데... 바이스랑 PlayerName 둘 다 너무 오래 소식이 없잖아...)",
  ui_story_1015_10150801_35_dialog_content = "아무튼 이 통행증이 있으면 네가 일루미나 대부분의 일반 통로를\n지나갈 수 있는 권한을 보장해 줄 거야.",
  ui_story_1015_10150801_36_dialog_content = "정말 고마워. 그럼 서두르는 게 좋겠어. 먼저 가볼게.",
  ui_story_1015_10150801_37_dialog_content = "응~ 여긴 백야성처럼 동행할 경비병이 없으니까 조심하구.",
  ui_story_1015_10150801_38_dialog_content = "<color=#e8d9bb>일루미나 연방, X호 지하성</color>",
  ui_story_1015_10150801_39_dialog_content = "(지도의 안내대로라면 여기가 바로 그로누가 말한 위치일 텐데...)",
  ui_story_1015_10150801_40_dialog_content = "(하지만 여긴 내가 생각했던 것보다 조금 크네.)",
  ui_story_1015_10150801_41_dialog_content = "(밀집된 대형 건물로 방대한 인구를 부양한다... 그게 바로 일루미나의 생존 전략이겠지.)",
  ui_story_1015_10150801_42_dialog_content = "?!",
  ui_story_1015_10150801_43_dialog_content = "<color=#e8d9bb>스으윽──!</color>",
  ui_story_1015_10150801_44_dialog_content = "누구냐!",
  ui_story_1015_10150801_45_dialog_content = "...잉겔?",
  ui_story_1015_10150801_46_dialog_content = "새로운 방문자 메시지가 발송되게 만든 게 당신이었군요.",
  ui_story_1015_10150801_47_dialog_content = "여기서 뭘 하는 거죠?\n...음, 알 것 같네요.",
  ui_story_1015_10150801_48_dialog_content = "우린 많든 적든 같은 목적을 가지고 있겠죠.",
  ui_story_1015_10150801_49_dialog_content = "그럼 먼저 지금 상황이 대체 어떻게 된 건지 설명해 줬으면 해.",
  ui_story_1015_10150801_50_dialog_content = "쉿──!",
  ui_story_1015_10150801_51_dialog_content = "<anim type=Shake>그억... 그어어...</anim>",
  ui_story_1015_10150801_52_dialog_content = "일단 이 암귀들부터 처리하죠.",
  ui_story_1015_10150801_53_dialog_content = "뭘 기다리고 있어? 서두르자.",
  ui_story_1015_10150802_1_dialog_content = "어떻게 그런 말도 안 되는 일이 벌어질 수 있는 거지?!",
  ui_story_1015_10150802_2_dialog_content = "노라는 대체 뭘 하려는 거야?",
  ui_story_1015_10150802_3_dialog_content = "왜 일루미나는 지금까지 병력을 파견해서 노라를 토벌하지 않은 거지?",
  ui_story_1015_10150802_4_dialog_content = "진정해요, 카렌. 여긴 백야성이 아니에요.\n모든 중요한 결정은 다방면의 결단이 필요해요.",
  ui_story_1015_10150802_5_dialog_content = "위원회는 이미 이 일에 대한 준비를 시작했어요.\n그리고 우린 그 조치를 가장 먼저 수행하는 선발대예요.",
  ui_story_1015_10150802_6_dialog_content = "그래서, 다음 계획은 뭐지?",
  ui_story_1015_10150802_7_dialog_content = "정보장교의 관점에서 보자면, 지금부터는 정보를 취합해서\n가장 효율적인 방식으로 노라를 상대해야 합니다.",
  ui_story_1015_10150802_8_dialog_content = "그 정보 수집의 첫발은 이곳의 철통같은 감시카메라부터 시작하는 게 좋겠습니다.",
  ui_story_1015_10150802_9_dialog_content = "상부에 감시카메라 기록 조회 허가를 요청하면 노라와 바이스의 위치를 한눈에 알 수 있을 겁니다.",
  ui_story_1015_10150802_10_dialog_content = "아마 안 될 거예요.",
  ui_story_1015_10150802_11_dialog_content = "무슨 목적인지는 모르겠지만, 이곳의 감시카메라는 신분 인증용으로만 사용되며,\n기록은 즉시 폐기됩니다.",
  ui_story_1015_10150802_12_dialog_content = "그런...",
  ui_story_1015_10150802_13_dialog_content = "숨겨야 할 게 참 많은 모양이네.",
  ui_story_1015_10150802_14_dialog_content = "그렇다고 지금 우리가 이 지하성을 무작정 돌아다니기만 할 순 없잖아.",
  ui_story_1015_10150802_15_dialog_content = "조급해할 거 없어요. 마침 방법이 하나 떠올랐거든요.",
  ui_story_1015_10150802_16_dialog_content = "일루미나에서 일어난 일은 당연히 일루미나의 도구로 해결해야죠.",
  ui_story_1015_10150901_1_dialog_content = "(A로 시작하는 파일을 번호 1번부터 50번까지 다 뒤졌지만 역시 못 찾았어.)",
  ui_story_1015_10150901_2_dialog_content = "(이렇게 찾는 것도 방법이 아니야. 이 캐비닛 안의 문서를 제목만 다 보는 데도 한 달이 걸릴 거야.)",
  ui_story_1015_10150901_3_dialog_content = "(율리시스 본인을 찾아가지 않는 이상, 빨리 이 캐비닛들의 분류 규칙을 알아내는 수밖에 없어...)",
  ui_story_1015_10150901_4_dialog_content = "바이스, 거기 음식이랑 물은 충분해?",
  ui_story_1015_10150901_5_dialog_content = "걱정...... 다 문제......",
  ui_story_1015_10150901_6_dialog_content = "뭐라고?",
  ui_story_1015_10150901_7_dialog_content = "응? 잘 안 들려?",
  ui_story_1015_10150901_8_dialog_content = "아, 이제 들려. 방금 소리가 끊겼다가 나왔다가 했거든. 이상하네.",
  ui_story_1015_10150901_9_dialog_content = "배터리가 부족한 거 아닐까? 무전기는 배터리 용량이 별로 안 크거든. 계속 쓰면 방전될 거야.",
  ui_story_1015_10150901_10_dialog_content = "어? 배터리는 아직...",
  ui_story_1015_10150901_11_dialog_content = "시끄러워 죽겠네, 이리 줘.",
  ui_story_1015_10150901_12_dialog_content = "야! 무전기는 왜 뺏는 건데?!",
  ui_story_1015_10150901_13_dialog_content = "이따가 다시 놀게 해줄게. 일단 와서 날 좀 도와줘.",
  ui_story_1015_10150901_14_dialog_content = "또 뭐 하려고?",
  ui_story_1015_10150901_15_dialog_content = "너희 아이테르는 특정 오로리안이 최근에 어떤 파일을 만졌는지를 감지할 수 있겠지?",
  ui_story_1015_10150901_16_dialog_content = "한번 봐줘.",
  ui_story_1015_10150901_17_dialog_content = "...불가능해. 내가 무슨 개인 줄 알아?!",
  ui_story_1015_10150901_18_dialog_content = "흥, 애초에 탑에서 널 그 기계에 집어넣었어야 했는데.",
  ui_story_1015_10150901_19_dialog_content = "못 하겠으면 이 기계의 암호를 어떻게 풀지 좀 봐봐.",
  ui_story_1015_10150901_20_dialog_content = "...안 그래도 이 기계, 확실히 좀 눈에 띄네.",
  ui_story_1015_10150901_21_dialog_content = "이 기계는 연구 지점마다 하나씩 있어.",
  ui_story_1015_10150901_22_dialog_content = "데이터를 찾고 기계 작동을 제어하는 데 쓰는 건데, 아무튼 연구자를 보조하는 도구야.",
  ui_story_1015_10150901_23_dialog_content = "그렇구나.",
  ui_story_1015_10150901_24_dialog_content = "근데 꼭 내가 조작해야 돼? 위험할지도 모르니까 난 안 할래.",
  ui_story_1015_10150901_25_dialog_content = "그리고 난 일루미나의 과학 기술에 대해 잘 모른다고.",
  ui_story_1015_10150901_26_dialog_content = "...참 말이 많네.",
  ui_story_1015_10150901_27_dialog_content = "<color=#e8d9bb>삑──</color>",
  ui_story_1015_10150901_28_dialog_content = "자, 잠깐만, 멋대로 암호부터 입력하면 어떡해...",
  ui_story_1015_10150901_29_dialog_content = "과학 기술은 애초부터 연구에 봉사하기 위한 물건이야.\n내가 사용할 수 없다면 존재할 가치도 없어.",
  ui_story_1015_10150901_30_dialog_content = "<color=#e8d9bb>삑, 삑── 삐익.</color>",
  ui_story_1015_10150901_31_dialog_content = "...그래.",
  ui_story_1015_10150901_32_dialog_content = "(그래도 왠지 정말 어떻게 푸는 건지 아는 것처럼 보이네.)",
  ui_story_1015_10150901_33_dialog_content = "<color=#e8d9bb>삑──</color>",
  ui_story_1015_10150901_34_dialog_content = "<color=#e8d9bb>경보── 경보──</color>",
  ui_story_1015_10150901_35_dialog_content = "<color=#e8d9bb>비밀번호 오류, 응급 경보 시설 가동──</color>",
  ui_story_1015_10150901_36_dialog_content = "뭐야?!",
  ui_story_1015_10150901_37_dialog_content = "<anim type=Shake><size=45>삑── 삐익──</size></anim>",
  ui_story_1015_10150901_38_dialog_content = "이게 무슨...",
  ui_story_1015_10150901_39_dialog_content = "너 자신 있는 거 아니었어?! 노라!",
  ui_story_1015_10150901_40_dialog_content = "실수는 불가피한 일이야. 전자 기술은 내 주력 분야가 아니니까.",
  ui_story_1015_10150901_41_dialog_content = "빨리 방법을 생각해 봐... 지금은 실수나 검토할 때가 아니라고!",
  ui_story_1015_10150901_42_dialog_content = "<color=#e8d9bb>쿵──</color>",
  ui_story_1015_10150901_43_dialog_content = "이 파일 저장소의 전원 스위치를 당기면 돼.",
  ui_story_1015_10150901_44_dialog_content = "그거면 된다고?",
  ui_story_1015_10150901_45_dialog_content = "......",
  ui_story_1015_10150901_46_dialog_content = "<anim type=Shake><size=45>삑── 삐익──</size></anim>",
  ui_story_1015_10150901_47_dialog_content = "전혀 소용없잖아!",
  ui_story_1015_10150901_48_dialog_content = "흥... 귀찮아.",
  ui_story_1015_10150901_49_dialog_content = "그럼 일단 저 로봇 개부터 상대해, 제이드.",
  ui_story_1015_10150901_50_dialog_content = "<anim type=Shake><size=50>그어어어!</size></anim>",
  ui_story_1015_10150901_51_dialog_content = "물어서 으깨버려.",
  ui_story_1015_10150902_1_dialog_content = "<anim type=Shake><size=45>그르르... 그르르...</size></anim>",
  ui_story_1015_10150902_2_dialog_content = "잘했어. 맛있게 먹어.",
  ui_story_1015_10150902_3_dialog_content = "그럼 계속 입구를 감시해. 알겠니?",
  ui_story_1015_10150902_4_dialog_content = "<anim type=Shake><size=45>크르르...</size></anim>",
  ui_story_1015_10150902_5_dialog_content = "이 기계가... 여길 지키는 녀석인가?",
  ui_story_1015_10150902_6_dialog_content = "몰라, 이건 내가 남겨둔 게 아니야.",
  ui_story_1015_10150902_7_dialog_content = "우린 이미 너무 많은 시간을 지체했어. 이제부터는 서둘러야 해.",
  ui_story_1015_10150902_8_dialog_content = "<color=#e8d9bb>삑, 삑── 삐익.</color>",
  ui_story_1015_10150902_9_dialog_content = "<color=#e8d9bb>스토리지 센터 가동 완료.</color>",
  ui_story_1015_10150902_10_dialog_content = "계속 검색해. 「계명성 프로젝트」.",
  ui_story_1015_10150902_11_dialog_content = "...아니지, 자료가 더 나오지 않는다면...",
  ui_story_1015_10150902_12_dialog_content = "...키워드를 변경해. 「<color=#FFB400>인공 태양 프로젝트</color>」를 검색해.",
  ui_story_1015_10150902_13_dialog_content = "(인공... 태양? 무슨 뜻이지? 말 그대로 거대한 태양을 만든다는 건가?)",
  ui_story_1015_10150902_14_dialog_content = "(계명성이라고 하다가... 이번엔 인공 태양... 노라가 찾는 게 대체 뭐지...?)",
  ui_story_1015_10150902_15_dialog_content = "찾았어.",
  ui_story_1015_10150902_16_dialog_content = "됐어, 빨리 철수해.",
  ui_story_1015_10150902_17_dialog_content = "노라, 대체 이 자료의 내용이 뭐야?\n너나 율리시스나 이렇게까지 여기 집착할 가치가 있는 거야?",
  ui_story_1015_10150902_18_dialog_content = "알고 싶어?",
  ui_story_1015_10150902_19_dialog_content = "근데 네가 알아도 쓸모는 없어. 헤븐즈 밸리의 그 장치는 이미 쓸 수 없게 됐으니까.",
  ui_story_1015_10150902_20_dialog_content = "게다가 내 연구는 이미 일루미나와 아이테르의 과학 기술 수준을 훨씬 뛰어넘었어.",
  ui_story_1015_10150902_21_dialog_content = "그러니까 충고하는데 쓸데없는 생각은 하지 마.",
  ui_story_1015_10150902_22_dialog_content = "그냥 궁금해서 물어본 거야. 방금 싸움에선 나도 힘을 보탰잖아.\n그럼 내가 왜 싸웠는지 정도는 알아야 할 거 아냐.",
  ui_story_1015_10150902_23_dialog_content = "그리고 지금 내 상황에선 너도 그렇게 경계할 필요는 없잖아, 안 그래?",
  ui_story_1015_10150902_24_dialog_content = "......",
  ui_story_1015_10150902_25_dialog_content = "좋아, 말해주는 것도 확실히 상관은 없겠어.",
  ui_story_1015_10150902_26_dialog_content = "이건 원래 네가 알고 있던 일이야.",
  ui_story_1015_10150902_27_dialog_content = "내가 안다고...?",
  ui_story_1015_10150902_28_dialog_content = "너희가 「어둠의 밑바닥」에서 오랫동안 잠들어 있던 헬리오스를 깨웠을 때 말이야.",
  ui_story_1015_10150902_29_dialog_content = "라인하르트는 분명히 우리 세 사람의 과거에 대해 너한테 말해줬겠지.",
  ui_story_1015_10150902_30_dialog_content = "그때 우리 셋은 함께 자랐고, 함께 군에 들어가서 싸웠어...",
  ui_story_1015_10150902_31_dialog_content = "하지만 그 오랜 시간의 조화가 흔히 말하는 우정이나 인연 같은 데서 비롯된 건 아냐.",
  ui_story_1015_10150902_32_dialog_content = "그건 우리가 「<color=#FFB400>인공 태양 프로젝트</color>」의 첫 실험체였기 때문이야.",
  ui_story_1015_10150902_33_dialog_content = "같은 성장 과정을 거쳐 같은 전장에서 싸우고, 같은 개조를 받은 자들만이 서로를 알 수 있어.",
  ui_story_1015_10150902_34_dialog_content = "다만 그 당시 그 늙은이들의 연구는 정말 형편없었어.",
  ui_story_1015_10150902_35_dialog_content = "그래서 라인하르트가 지금의 모습이 된 것도 정말 내 예상 밖이었어.",
  ui_story_1015_10150902_36_dialog_content = "그 뒤로 그 프로젝트는 조금 더 듣기 좋은 이름으로 바뀌었어.\n그게 바로 「<color=#FFB400>계명성 프로젝트</color>」야.",
  ui_story_1015_10150902_37_dialog_content = "그런... 이유가 있었다니...",
  ui_story_1015_10150902_38_dialog_content = "그 표정 정말 역겹네. 아이테르들은 전부 그렇게 동정심이 넘치는 종족이야?",
  ui_story_1015_10150902_39_dialog_content = "무전기 가져가. 이제 통신해도 돼.",
  ui_story_1015_10150902_40_dialog_content = "어?!",
  ui_story_1015_10150902_41_dialog_content = "<color=#e8d9bb>지직... 지지직...</color>",
  ui_story_1015_10150902_42_dialog_content = "PlayerName! 괜찮아?",
  ui_story_1015_10150902_43_dialog_content = "...바이스!",
  ui_story_1015_10150902_44_dialog_content = "<color=#e8d9bb>지직... 지지직...</color>",
  ui_story_1015_10150902_45_dialog_content = "아...",
  ui_story_1015_10150902_46_dialog_content = "바이스의 주파수가 불안정해요!",
  ui_story_1015_10150902_47_dialog_content = "주파수로 바이스의 위치를 확인할 순 없어?!",
  ui_story_1015_10150902_48_dialog_content = "일루미나의 현재 기술 수준으로는 아마 무리일 겁니다.",
  ui_story_1015_10150902_49_dialog_content = "하지만 적어도 바이스 중위가 자신의 무전기를 사용했다는 건 알 수 있습니다.",
  ui_story_1015_10150902_50_dialog_content = "그렇다는 건 어느 정도 행동의 자유가 허용되고 있다는 뜻이겠죠.",
  ui_story_1015_10150902_51_dialog_content = "제 추측이 맞다면, 바이스 중위의 통신 상대는 아마 노라일 겁니다.",
  ui_story_1015_10150902_52_dialog_content = "네, 아나톨리. 지금부터는 바이스 중위의 주파수 변화에 계속 주의해 주세요.",
  ui_story_1015_10150902_53_dialog_content = "예, 알겠습니다.",
  ui_story_1015_10150902_54_dialog_content = "그럼 구출 작전을 세워 보기로 하죠.",
  ui_story_1015_10150902_55_dialog_content = "방금 전 율리시스 교수님의 기록보관소 경보 시스템이 발동했다는 메시지를 받았어요.",
  ui_story_1015_10150902_56_dialog_content = "노라는 분명히 거기 있어요. PlayerName도 마찬가지겠죠.",
  ui_story_1015_10150902_57_dialog_content = "바이스 중위의 위치만 확인할 수 있다면 구출 계획을 실행할 수 있을 거예요.",
  ui_story_1015_10151001_1_dialog_content = "바이스, 난 괜찮아! 지금 노라랑 같이 X호 지하성 자료실에 있어!",
  ui_story_1015_10151001_2_dialog_content = "넌 괜찮아? 안 다쳤어? 지금 어디 있어?!",
  ui_story_1015_10151001_3_dialog_content = "<anim type=Shake>난...... 문이...... 빛이 비......</anim>",
  ui_story_1015_10151001_4_dialog_content = "바이스? 뭐라고?",
  ui_story_1015_10151001_5_dialog_content = "왜 이러지? 잘 안 들려... 또 배터리가 없나?",
  ui_story_1015_10151001_6_dialog_content = "<color=#e8d9bb>삑──</color>",
  ui_story_1015_10151001_7_dialog_content = "통신은 끝이야. 넌 물어보면 안 되는 걸 물었어.",
  ui_story_1015_10151001_8_dialog_content = "뭐가 안 되는지 미리 말도 안 했잖아! 그럼 나도 당연히 제일 물어보고 싶은 걸 묻지!",
  ui_story_1015_10151001_9_dialog_content = "그렇게 급하게 무전을 끊어버리고, 뭐가 그렇게 켕기는 거야?",
  ui_story_1015_10151001_10_dialog_content = "오해하지 마. 내가 끊은 게 아니야.",
  ui_story_1015_10151001_11_dialog_content = "그 구닥다리 기계 배터리가 나간 거지.",
  ui_story_1015_10151001_12_dialog_content = "(아, 진짜네...)",
  ui_story_1015_10151001_13_dialog_content = "(나 참! 하필 이런 중요한 순간에...)",
  ui_story_1015_10151001_14_dialog_content = "됐어. 더는 시간 낭비하지 마.",
  ui_story_1015_10151001_15_dialog_content = "갈 준비해. 새로운 실험이 기다리고 있으니까.",
  ui_story_1015_10151001_16_dialog_content = "여긴 율리시스 교수님 외에는 거의 아무도 발을 들여놓지 않았던 구역입니다.",
  ui_story_1015_10151001_17_dialog_content = "눈에 띄는 건물은 두 곳뿐이에요. 경보가 발생한 기록보관소, 그리고 실험실이죠.",
  ui_story_1015_10151001_18_dialog_content = "역시 중령님은 대단하시군요...\n저도 위원회에서 꽤 오래 일했지만, 이곳에 대해서는 전혀 몰랐습니다.",
  ui_story_1015_10151001_19_dialog_content = "기밀 사항이라고만 알아 두세요.\n교수님은 이 장소가 여러 사람에게 알려지는 걸 원치 않으시니까요.",
  ui_story_1015_10151001_20_dialog_content = "그러니 누구라도 허락 없이 이곳을 침입하는 자는 제가 반드시 쫓아낼 거예요.",
  ui_story_1015_10151001_21_dialog_content = "바이스 중위의 주파수에 변화는 없나요?",
  ui_story_1015_10151001_22_dialog_content = "아직 없습니다. 통신 전류음도 전혀 들리지 않았습니다.\n아마 그쪽은 지금 통신이 끊어졌을 겁니다.",
  ui_story_1015_10151001_23_dialog_content = "잠깐 좀 줘 보세요──",
  ui_story_1015_10151001_24_dialog_content = "바이스 중위, 응답하세요. 여기는 잉겔, 제 말 들리나요?",
  ui_story_1015_10151001_25_dialog_content = "무전이 가능하다면 지금 즉시 응답하세요!",
  ui_story_1015_10151001_26_dialog_content = "잠깐만! 그랬다간 바이스의 통신 상대에게도 목소리가 들릴 거잖아!",
  ui_story_1015_10151001_27_dialog_content = "보통은 그렇겠죠. 하지만 지금 노라 쪽 무전기는 이미 배터리가 떨어졌어요.",
  ui_story_1015_10151001_28_dialog_content = "뭐?!",
  ui_story_1015_10151001_29_dialog_content = "전 계속 두 사람의 대화를 도청하고 있었어요.\n하지만 PlayerName의 무전기 사용 빈도가 너무 높아서 배터리 소모도 빨라지고 있었죠.",
  ui_story_1015_10151001_30_dialog_content = "방금 전 소리로 봤을 때, 지금은 완전히 배터리가 나갔을 거예요.",
  ui_story_1015_10151001_31_dialog_content = "그리고 작전의 성패는 지금 이 순간에 달려 있어요.",
  ui_story_1015_10151001_32_dialog_content = "이...잉겔 중령님?",
  ui_story_1015_10151001_33_dialog_content = "(해냈어!)",
  ui_story_1015_10151001_34_dialog_content = "지금 즉시 위치를 보고하세요!",
  ui_story_1015_10151001_35_dialog_content = "주변에 위치를 특정할 수 있는 요소라도 좋습니다!",
  ui_story_1015_10151001_36_dialog_content = "네! 전 지금 X호 지하성의 한 창고에 갇혀 있어요!\n문은 회색이고, 창고에 창문이 있어서 자연광이 들어오는 곳이에요!",
  ui_story_1015_10151001_37_dialog_content = "알겠어요.",
  ui_story_1015_10151001_38_dialog_content = "통신을 연결한 채로 둘 테니까 배터리가 다 닳지 않게 주의하세요.\n노라가 통신을 걸더라도 우리가 들을 수 있을 수 있어요.",
  ui_story_1015_10151001_39_dialog_content = "거기 또 누가 있죠?",
  ui_story_1015_10151001_40_dialog_content = "헬리오스가 절 여기로 데려왔는데, 방금 어디론가 가버렸어요.",
  ui_story_1015_10151001_41_dialog_content = "알겠어요. 우리가 지금 그쪽으로 갈게요.",
  ui_story_1015_10151001_42_dialog_content = "중령님, 이미 위치를 짐작하신 겁니까?",
  ui_story_1015_10151001_43_dialog_content = "X호 지하성의 창고는 남쪽에 집중적으로 배치돼 있어요.\n거긴 지형이 낮아서 지키기 쉽고, 공격이 어렵거든요.",
  ui_story_1015_10151001_44_dialog_content = "회색 문이라면 아마 고체 약물 보관용 창고일 거예요.",
  ui_story_1015_10151001_45_dialog_content = "게다가 조금 전 바이스 중위의 목소리는 크게 울리고 있었죠.\n따라서 큰 규모의 창고가 분명해요.",
  ui_story_1015_10151001_46_dialog_content = "모든 지하 창고와 곳곳의 소형 저장실 등을 제외하면...",
  ui_story_1015_10151001_47_dialog_content = "바이스 중위가 갇혀 있을 장소의 범위는 X-106, X-107, X-108호 창고로 좁혀져요.",
  ui_story_1015_10151001_48_dialog_content = "그럼 지금 바로 출발하자.",
  ui_story_1015_10151001_49_dialog_content = "저와 아나톨리 둘이서 갈게요. 카렌 당신에겐 다른 일을 부탁하고 싶어요.",
  ui_story_1015_10151001_50_dialog_content = "기록보관소로 가서 아이테르를 구출하세요.",
  ui_story_1015_10151001_51_dialog_content = "두 사람의 안전을 확보하려면 반드시 동시에 구출해야 해요.",
  ui_story_1015_10151001_52_dialog_content = "그렇겠네, 이해했어.",
  ui_story_1015_10151001_53_dialog_content = "네, 저희가 바이스 중위를 구출하는 대로, 즉시 지원하러 갈게요.",
  ui_story_1015_10151001_54_dialog_content = "부디 조심하세요.",
  ui_story_1015_10151001_55_dialog_content = "<color=#e8d9bb>X호 지하성, 남쪽 창고</color>",
  ui_story_1015_10151001_56_dialog_content = "중령님의 추측대로군요.",
  ui_story_1015_10151001_57_dialog_content = "주변의 특징을 보니 맞게 찾아온 모양입니다.",
  ui_story_1015_10151001_58_dialog_content = "중령님, 이제 어떻게 하실 겁니까?",
  ui_story_1015_10151001_59_dialog_content = "하나하나 알아보는 수밖에 없겠죠.",
  ui_story_1015_10151001_60_dialog_content = "다행히 노라도 아직 다음 행동은 하지 않았어요...",
  ui_story_1015_10151001_61_dialog_content = "<color=#e8d9bb>쿵──!</color>",
  ui_story_1015_10151001_62_dialog_content = "<anim type=Shake><size=50>그어어어!</size></anim>",
  ui_story_1015_10151001_63_dialog_content = "무, 무슨...",
  ui_story_1015_10151001_64_dialog_content = "(이쪽의 행동을 이미 읽고 있었던 건가요...!)",
  ui_story_1015_10151001_65_dialog_content = "<anim type=Shake><size=50>크오오!</size></anim>",
  ui_story_1015_10151001_66_dialog_content = "조심하세요! 이쪽으로 옵니다!",
  ui_story_1015_10151101_1_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_1015_10151101_2_dialog_content = "완벽한 사격입니다.",
  ui_story_1015_10151101_3_dialog_content = "<anim type=Shake><size=50>크아아아!</size></anim>",
  ui_story_1015_10151101_4_dialog_content = "이 녀석, 대체 어떻게 된 거죠?!",
  ui_story_1015_10151101_5_dialog_content = "정보에 따르면 대원수님과의 교전으로 중상을 입었을 텐데...",
  ui_story_1015_10151101_6_dialog_content = "어째서 아직도 이 정도로 강한 전력을...",
  ui_story_1015_10151101_7_dialog_content = "<anim type=Shake><size=50>그어어!</size></anim>",
  ui_story_1015_10151101_8_dialog_content = "위험합니다!",
  ui_story_1015_10151101_9_dialog_content = "으윽...!",
  ui_story_1015_10151101_10_dialog_content = "고마워요...",
  ui_story_1015_10151101_11_dialog_content = "정보를 지나치게 믿으시면 안 됩니다, 중령님.\n정보도 정확하지 않을 수 있으니까요.",
  ui_story_1015_10151101_12_dialog_content = "만약 중령님의 정보가 사실이라면, 저자는...",
  ui_story_1015_10151101_13_dialog_content = "아니죠, 저 헬리오스 대위는 의식이 흐릿한 채로 어둠의 밑바닥에서 홀로 10여 년을 생존했습니다.",
  ui_story_1015_10151101_14_dialog_content = "그것만으로도 이미 쉽게 볼 수 있는 상대가 아닙니다.",
  ui_story_1015_10151101_15_dialog_content = "게다가 대원수님과 마찬가지로 강화 개조를 받은 개체입니다...",
  ui_story_1015_10151101_16_dialog_content = "저희 두 사람이 함께 상대해도 아마 대원수님의 절반에도 미치지 못할 겁니다.",
  ui_story_1015_10151101_17_dialog_content = "그런 말은 당신이 안 해도 알고 있어요, 아나톨리 소령.",
  ui_story_1015_10151101_18_dialog_content = "상대는 우리보다 기동력이 높고, 이 공간은 너무 트인 곳이에요.\n이대로 가면 우리 힘만 빠질 거예요!",
  ui_story_1015_10151101_19_dialog_content = "복도로 내려가서 상대의 움직임을 제한하죠.",
  ui_story_1015_10151101_20_dialog_content = "알겠습니다!",
  ui_story_1015_10151101_21_dialog_content = "<anim type=Shake>크르르...</anim>",
  ui_story_1015_10151101_22_dialog_content = "......",
  ui_story_1015_10151101_23_dialog_content = "멀리 떨어졌습니다.",
  ui_story_1015_10151101_24_dialog_content = "정면 대결은 곤란해요. 하지만 지형을 이용하면 약점을 찌른 기습을 가할 수 있을 거예요.",
  ui_story_1015_10151101_25_dialog_content = "대신 노라 쪽에서...",
  ui_story_1015_10151101_26_dialog_content = "아니, 잠깐만요...",
  ui_story_1015_10151101_27_dialog_content = "<size=45>아!</size>",
  ui_story_1015_10151101_28_dialog_content = "왜 그러십니까?",
  ui_story_1015_10151101_29_dialog_content = "강화 개조를 받은 오로리안들 사이에는 서로 특수한 감응 연결이 존재해요.",
  ui_story_1015_10151101_30_dialog_content = "노라는 이미 우리가 여기서 저자와 교전한 사실을 알고 있을 거예요!",
  ui_story_1015_10151101_31_dialog_content = "......!",
  ui_story_1015_10151101_32_dialog_content = "그렇게 중요한 정보를 왜 제게 미리 말씀 안 하신 겁니까?",
  ui_story_1015_10151101_33_dialog_content = "사실 그 실험 계획은 최고 기밀이에요.",
  ui_story_1015_10151101_34_dialog_content = "긴급 상황이 아니라면, 실험에 대한 일체의 정보는 저나 당신의 직권으로는 알 수 있는 게 아니에요.",
  ui_story_1015_10151101_35_dialog_content = "미안해요. 진작 공유했어야 했는데, 이건 제 실책이에요.",
  ui_story_1015_10151101_36_dialog_content = "아무래도 곤란한 상황이 될 것 같군요...",
  ui_story_1015_10151101_37_dialog_content = "(위원회는... 대체 얼마나 많은 비밀을 숨기고 있는 겁니까?)",
  ui_story_1015_10151101_38_dialog_content = "(인체 개조 건뿐만 아니라, 당시 제가 속한 팀이 목숨을 걸고 확보한 정보가 조작된 건도...)",
  ui_story_1015_10151101_39_dialog_content = "(저들을 정말 믿어도 되는 건가...)",
  ui_story_1015_10151101_40_dialog_content = "여기서 소모전을 계속할 순 없어요.",
  ui_story_1015_10151101_41_dialog_content = "노라가 이미 우리의 움직임을 알아챘다면, 대책을 세우지 않았을 리가 없어요.",
  ui_story_1015_10151101_42_dialog_content = "바이스 중위는 당분간 안전할 겁니다.\n하지만 카렌 양은 자기 움직임이 발각됐다는 사실을 아직 모르겠죠.",
  ui_story_1015_10151101_43_dialog_content = "저자를 따돌리고 서둘러 카렌 양을 지원해야 합니다.",
  ui_story_1015_10151101_44_dialog_content = "물론 그래야죠. 대신 우린 따로 움직이기로 해요.",
  ui_story_1015_10151101_45_dialog_content = "당신은 잠입이 특기니까, 기회를 봐서 저자를 피해 바이스 중위를 구출하고, 신속하게 카렌과 합류하세요.",
  ui_story_1015_10151101_46_dialog_content = "그럼 중령님은 어떻게 하실 겁니까?",
  ui_story_1015_10151101_47_dialog_content = "노라는 저 괴물보다도 더 벅찬 상대예요.\n우리 둘이 같이 싸운다 해도 승산은 희박해요.",
  ui_story_1015_10151101_48_dialog_content = "전 노라가 타협하게 만들 비장의 카드를 준비해야겠어요.",
  ui_story_1015_10151101_49_dialog_content = "<color=#e8d9bb>한편, 노라와 PlayerName 쪽에서는...</color>",
  ui_story_1015_10151101_50_dialog_content = "......",
  ui_story_1015_10151101_51_dialog_content = "<anim type=Shake>그르르, 그르렁──</anim>",
  ui_story_1015_10151101_52_dialog_content = "제이드, 조용히 해.",
  ui_story_1015_10151101_53_dialog_content = "<anim type=Shake>그르르...</anim>",
  ui_story_1015_10151101_54_dialog_content = "시끄러워.",
  ui_story_1015_10151101_55_dialog_content = "진짜 시끄럽네. 소리가 너무 커서 고막이 터질 것 같다고.",
  ui_story_1015_10151101_56_dialog_content = "입 다물어.",
  ui_story_1015_10151101_57_dialog_content = "여기 생쥐가 움직이고 있어.",
  ui_story_1015_10151101_58_dialog_content = "생쥐?",
  ui_story_1015_10151101_59_dialog_content = "(이 루미나의 기운은... 설마...!)",
  ui_story_1015_10151101_60_option_content = "[감응한다]",
  ui_story_1015_10151101_61_dialog_content = "(카렌?!)",
  ui_story_1015_10151101_62_dialog_content = "나와라.",
  ui_story_1015_10151101_63_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_1015_10151101_64_dialog_content = "어리석긴.",
  ui_story_1015_10151101_65_dialog_content = "<size=45>(카렌! 위험해!)</size>",
  ui_story_1015_10151101_66_dialog_content = "(무슨...)",
  ui_story_1015_10151101_67_dialog_content = "<color=#e8d9bb>콰아앙!</color>",
  ui_story_1015_10151101_68_dialog_content = "콜록... 콜록콜록!",
  ui_story_1015_10151101_69_dialog_content = "어떻게... 안 거지?",
  ui_story_1015_10151101_70_dialog_content = "너희 전술은 참 허술하다고밖에 못 말하겠네.",
  ui_story_1015_10151101_71_dialog_content = "......",
  ui_story_1015_10151101_72_dialog_content = "하지만 실험 결과에 영향을 미치는 요소인 건 확실해.\n시간을 할애해서 배제할 만한 가치는 있겠지.",
  ui_story_1015_10151101_73_dialog_content = "<anim type=Shake>그르르...</anim>",
  ui_story_1015_10151101_74_dialog_content = "(많다...)",
  ui_story_1015_10151101_75_dialog_content = "가.",
  ui_story_1015_10151101_76_dialog_content = "<anim type=Shake><size=50>그어어어!</size></anim>",
  ui_story_1015_10151102_1_dialog_content = "크윽...!",
  ui_story_1015_10151102_2_dialog_content = "<anim type=Shake><size=45>크오오오──!</size></anim>",
  ui_story_1015_10151102_3_dialog_content = "끝이 없잖아...",
  ui_story_1015_10151102_4_dialog_content = "카렌!",
  ui_story_1015_10151102_5_dialog_content = "너흰 양동작전으로 동시에 아이테르와 저 계집애를 구하려고 했겠지.",
  ui_story_1015_10151102_6_dialog_content = "하지만 그 계획이 성공하기 위한 전제는 자신들의 실력에 절대적인 자신감이 있어야 한다는 거야.",
  ui_story_1015_10151102_7_dialog_content = "대체 어떻게 알았지?",
  ui_story_1015_10151102_8_dialog_content = "그거라면 저 늙은이들의 계획 덕분이라고 해야겠지.",
  ui_story_1015_10151102_9_dialog_content = "설마 라인하르트 씨가 전에 얘기했던 특수한 감응...?",
  ui_story_1015_10151102_10_dialog_content = "큰일이야. 그런 능력이 있다면 잉겔 쪽도 지금...",
  ui_story_1015_10151102_11_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_1015_10151102_12_dialog_content = "콜록... 콜록콜록!",
  ui_story_1015_10151102_13_dialog_content = "여긴...",
  ui_story_1015_10151102_14_dialog_content = "<anim type=Shake>그르르...</anim>",
  ui_story_1015_10151102_15_dialog_content = "또 생쥐가 한 마리 늘었네.",
  ui_story_1015_10151102_16_dialog_content = "아나톨리 씨?! 왜 여기 있어?",
  ui_story_1015_10151102_17_dialog_content = "바이스는?",
  ui_story_1015_10151102_18_dialog_content = "죄송합니다... 저들이 제 움직임을 간파했습니다.\n결국 바이스 중위가 갇힌 장소를 못 찾은 탓에 구하지 못했습니다...",
  ui_story_1015_10151102_19_dialog_content = "아무래도 너희가 가진 건 자존심과 무능뿐인 모양이네.",
  ui_story_1015_10151102_20_dialog_content = "내가 하려는 일은 이제 곧 끝날 거야. 너흰 이제 필요 없어.",
  ui_story_1015_10151102_21_dialog_content = "......",
  ui_story_1015_10151102_22_dialog_content = "이런!",
  ui_story_1015_10151102_23_dialog_content = "여기서 포위되다니...",
  ui_story_1015_10151102_24_dialog_content = "조금만 더 버티세요, PlayerName, 카렌 양.",
  ui_story_1015_10151102_25_dialog_content = "아직 중령님이 남아 있다는 걸 잊지 마세요.",
  ui_story_1015_10151102_26_dialog_content = "가서 처리해──",
  ui_story_1015_10151102_27_dialog_content = "<color=#e8d9bb>치지직──</color>",
  ui_story_1015_10151102_28_dialog_content = "노라, 제 말 들리겠죠.",
  ui_story_1015_10151102_29_dialog_content = "마침 생각하던 참이야. 생쥐 한 마리가 어디로 샜는지.",
  ui_story_1015_10151102_30_dialog_content = "혼자 멀리 도망갔었구나.",
  ui_story_1015_10151102_31_dialog_content = "당신이 뭘 할 생각이든, 지금 당장 멈추세요.",
  ui_story_1015_10151102_32_dialog_content = "그렇지 않으면 반드시 후회할 거예요.",
  ui_story_1015_10151102_33_dialog_content = "......",
  ui_story_1015_10151102_34_dialog_content = "너, 뭘 한 거지?",
  ui_story_1015_10151102_35_dialog_content = "두 사람이 시간을 벌어주는 동안, 전 화음 연결 실험실 주변에 <color=#FFB400>폭약</color>을 설치했어요.",
  ui_story_1015_10151102_36_dialog_content = "그리고 지금 제 총구는 화약통을 향하고 있어요.\n방아쇠를 당기면 화음 연결 장치는 자료와 함께 불바다에 빠지겠죠.",
  ui_story_1015_10151102_37_dialog_content = "?!",
  ui_story_1015_10151102_38_dialog_content = "그 풍경, 당신에겐 무척 익숙하겠죠? 「노라」.",
  ui_story_1015_10151102_39_dialog_content = "지금 즉시 투항하고, PlayerName 일행을 풀어주세요.",
  ui_story_1015_10151102_40_dialog_content = "......",
  ui_story_1015_10151102_41_dialog_content = "<size=45>불... 불이...!</size>",
  ui_story_1015_10151102_42_dialog_content = "<size=45>안 돼! 내 실험... 내 실험이!</size>",
  ui_story_1015_10151102_43_dialog_content = "훗.",
  ui_story_1015_10151102_44_dialog_content = "그 늙은이들, 연구엔 재능도 없으면서 개 하나는 잘도 길들이네.",
  ui_story_1015_10151102_45_dialog_content = "...당신!",
  ui_story_1015_10151102_46_dialog_content = "넌 못 해.",
  ui_story_1015_10151102_47_dialog_content = "화음 연결 장치는 고대 아이테르 기술의 결정체야. 길에서 쉽게 주울 수 있는 게 아니라고.",
  ui_story_1015_10151102_48_dialog_content = "온 일루미나 연방에 단 한 대뿐인 물건이야.",
  ui_story_1015_10151102_49_dialog_content = "그 안에 저장되어 있는 데이터의 가치는 더 말할 것도 없겠지.\n계명성 프로젝트조차 그에 비하면 극히 일부일 뿐이야.",
  ui_story_1015_10151102_50_dialog_content = "저들의 개인 네가 그걸 모를 리가 없잖아?",
  ui_story_1015_10151102_51_dialog_content = "그 늙은이들이 화음 연결과 데이터를 저울에 올려둔다면, 너희 가치로는 저울추의 자격조차 없어.",
  ui_story_1015_10151102_52_dialog_content = "그런가요?",
  ui_story_1015_10151102_53_dialog_content = "그럼 한번 해보죠.",
  ui_story_1015_10151102_54_dialog_content = "<color=#e8d9bb>탕──!</color>",
  ui_story_1015_10151201_1_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_1015_10151201_2_dialog_content = "불...",
  ui_story_1015_10151201_3_dialog_content = "불이...",
  ui_story_1015_10151201_4_dialog_content = "헬리오스, 실험실로 따라와!",
  ui_story_1015_10151201_5_dialog_content = "<anim type=Shake><size=45>그어어──</size></anim>",
  ui_story_1015_10151201_6_dialog_content = "기회입니다!",
  ui_story_1015_10151201_7_dialog_content = "얼어붙어라!",
  ui_story_1015_10151201_8_dialog_content = "조심해! 암귀들이 또 오고 있어!",
  ui_story_1015_10151201_9_dialog_content = "<anim type=Shake><size=45>그어어어!</size></anim>",
  ui_story_1015_10151201_10_dialog_content = "<color=#e8d9bb>탕! 탕탕──!</color>",
  ui_story_1015_10151201_11_dialog_content = "<anim type=Shake>그어억...</anim>",
  ui_story_1015_10151201_12_dialog_content = "지금이에요! 아이테르를 구하세요!",
  ui_story_1015_10151201_13_dialog_content = "알겠습니다!",
  ui_story_1015_10151201_14_dialog_content = "PlayerName, 지금 바로 풀어주겠습니다!",
  ui_story_1015_10151201_15_dialog_content = "고마워...",
  ui_story_1015_10151201_16_dialog_content = "바이스는 괜찮아? 지금 어디 있어?",
  ui_story_1015_10151201_17_dialog_content = "죄송합니다. 제가 적에게 발각되어 바이스 중위를 찾지 못했습니다...",
  ui_story_1015_10151201_18_dialog_content = "다만 그쪽 구역에 다른 적은 없습니다. 따라서 바이스 중위의 안전은 보장할 수 있습니다.",
  ui_story_1015_10151201_19_dialog_content = "걱정 마세요. 바이스는 이미 다른 사람이 구하러 가고 있으니까요.",
  ui_story_1015_10151201_20_dialog_content = "지금 여러분이 해야 할 일은 노라의 실험을 막는 거예요.",
  ui_story_1015_10151201_21_dialog_content = "역시 화음 연결 장치를 없애지 않았구나.",
  ui_story_1015_10151201_22_dialog_content = "뭐? 안 없앴어?!",
  ui_story_1015_10151201_23_dialog_content = "그런 물건을 이렇게 쉽게 없앨 리가 없잖아요.",
  ui_story_1015_10151201_24_dialog_content = "정말 없앴으면 중령님은 군사 재판에 수백 번 회부되어도 부족할 겁니다.",
  ui_story_1015_10151201_25_dialog_content = "자, 그 이야기는 됐어요.",
  ui_story_1015_10151201_26_dialog_content = "일단 이 암귀들부터 없애고 노라를 막죠!",
  ui_story_1015_10151201_27_dialog_content = "당연히 그래야지!",
  ui_story_1015_10151202_1_dialog_content = "<color=#e8d9bb>몇 년 전, X호 지하성</color>",
  ui_story_1015_10151202_2_dialog_content = "안 돼! 내 실험... 내 실험이!",
  ui_story_1015_10151202_3_dialog_content = "데이터도 실험 재료도 전부 다 안에 있어! 어떻게든 꺼내야 해!",
  ui_story_1015_10151202_4_dialog_content = "<anim type=Shake><size=45>끽──! 끽끽──!</size></anim>",
  ui_story_1015_10151202_5_dialog_content = "제이드, 내 코트 안으로 들어와. 당장 돌아가야 해!",
  ui_story_1015_10151202_6_dialog_content = "<anim type=Shake><size=45>끽!</size></anim>",
  ui_story_1015_10151202_7_dialog_content = "실험 데이터를 꺼내야...",
  ui_story_1015_10151202_8_dialog_content = "<color=#e8d9bb>쾅──!</color>",
  ui_story_1015_10151202_9_dialog_content = "으악!",
  ui_story_1015_10151202_10_dialog_content = "제길... 이렇게 큰 불이 날 줄은...",
  ui_story_1015_10151202_11_dialog_content = "이 지하성에 있는 소방 설비만으로는 이 정도 불을 못 끌 거야.",
  ui_story_1015_10151202_12_dialog_content = "설마... 그 사람에게 지원을 부탁할 수밖에 없는 건가...",
  ui_story_1015_10151202_13_dialog_content = "<color=#e8d9bb>위잉── 위잉──</color>",
  ui_story_1015_10151202_14_dialog_content = "거의 모든 내 연구 성과가 그 화재로 사라졌어.",
  ui_story_1015_10151202_15_dialog_content = "절대 같은 일이 벌어지게 두진 않아!",
  ui_story_1015_10151202_16_dialog_content = "이건...",
  ui_story_1015_10151202_17_dialog_content = "(화음 연결 실험실에는 불꽃 하나조차 없잖아...)",
  ui_story_1015_10151202_18_dialog_content = "(이 스프링클러... 설마 내가 떠난 뒤로 그 늙은이들이 설치한 건가?)",
  ui_story_1015_10151202_19_dialog_content = "아무래도 그 화재는 나뿐만 아니라 그 늙은이들에게도 뭔가 깨닫게 만든 모양이네.",
  ui_story_1015_10151202_20_dialog_content = "하지만...",
  ui_story_1015_10151202_21_dialog_content = "<color=#e8d9bb>치지직──</color>",
  ui_story_1015_10151202_22_dialog_content = "저항은 그만 해요, 노라.",
  ui_story_1015_10151202_23_dialog_content = "인질은 모두 안전해졌어요. 당신의 마지막 카드도 이제 더는 없어요.",
  ui_story_1015_10151202_24_dialog_content = "그런 장난으로 날 떼어내는 게 네 계획이었어?",
  ui_story_1015_10151202_25_dialog_content = "맞아요. 하지만 이건 장난이 아니에요.",
  ui_story_1015_10151202_26_dialog_content = "실험실 주위에 배치한 화약통은 전부 진짜예요.\n가짜를 가지고 당신을 속일 순 없을 테니까요.",
  ui_story_1015_10151202_27_dialog_content = "다만, 당시의 화재 이후로 대원수님께서 이 지하성의 모든 소방 설비를\n보완하라고 명령하신 건 당신도 몰랐던 모양이네요.",
  ui_story_1015_10151202_28_dialog_content = "소화기와 스프링클러를 통상 시설의 두 배로 설치했을 뿐만 아니라\n벽까지도 방폭, 불연재료로 보강했죠.",
  ui_story_1015_10151202_29_dialog_content = "그 녀석 짓이었구나.",
  ui_story_1015_10151202_30_dialog_content = "이래저래 애쓴 모양인데, 아쉽지만 전부 쓸모없는 방해물일 뿐이야.",
  ui_story_1015_10151202_31_dialog_content = "......",
  ui_story_1015_10151202_32_dialog_content = "왜 갑자기 말이 없죠?",
  ui_story_1015_10151202_33_dialog_content = "아직도 당시 화재를 원망하고 있는 건가요?",
  ui_story_1015_10151202_34_dialog_content = "그때의 진상이 뭔지 알고 싶다고 생각해 본 적은 없나요?",
  ui_story_1015_10151202_35_dialog_content = "말해.",
  ui_story_1015_10151202_36_dialog_content = "당신이 지원 요청을 보냈을 때, 대원수님께선 즉시 X호 지하성에 지원을 보냈어요.",
  ui_story_1015_10151202_37_dialog_content = "하지만 불길이 너무 거셌고, 지원 부대가 도착했을 땐 지하성은 이미 짙은 연기로 뒤덮여 있었죠.",
  ui_story_1015_10151202_38_dialog_content = "그럼에도 대원수님께선 앞장서 불바다로 뛰어들으셨고,\n그 험난한 환경 속에서도 몇 시간 동안을 찾아다니셨어요.",
  ui_story_1015_10151202_39_dialog_content = "당시 지원 인력의 말에 따르면 대원수님의 몸엔 불에 탄 상처가 가득했고,\n옷도 전부 타서 해졌었다고 해요.",
  ui_story_1015_10151202_40_dialog_content = "하지만 그런 상황에서도 고통보다는 소중한 여동생을 찾지 못한 것만을 개탄하고 있었다고 했죠.",
  ui_story_1015_10151202_41_dialog_content = "......",
  ui_story_1015_10151202_42_dialog_content = "당신도 이제 알았겠죠.",
  ui_story_1015_10151202_43_dialog_content = "대원수님은 당신을 결코 저버린 적이 없었어요. 그리고 아무도 당신을 저버리지 않았어요.",
  ui_story_1015_10151202_44_dialog_content = "그저 당신 멋대로 자신이 버림받았다고 믿고, 저 극악무도한 암귀들 편에 섰을 뿐이죠.",
  ui_story_1015_10151202_45_dialog_content = "수년간 당신이 해 온 모든 건 한때 당신을 「버린」 사람에 대한 복수였잖아요?",
  ui_story_1015_10151202_46_dialog_content = "하지만 당신이 스스로 일루미나를 떠나지 않았다면, 아무도 당신을 버리지 않았어요.",
  ui_story_1015_10151202_47_dialog_content = "당신의 복수는 처음부터 거짓된 명제였어요!",
  ui_story_1015_10151202_48_dialog_content = "순순히 투항하세요.\n당신은 더는 일루미나와 적대할 이유도 없고, 도망갈 길도 없어요.",
  ui_story_1015_10151202_49_dialog_content = "훗.",
  ui_story_1015_10151202_50_dialog_content = "그 늙은이들 악취미는 몇 년이 지나도 변한 게 전혀 없다니까.",
  ui_story_1015_10151202_51_dialog_content = "딱 알맞게 멍청한 개를 좋아하는 건 정말 여전하네.",
  ui_story_1015_10151202_52_dialog_content = "......",
  ui_story_1015_10151202_53_dialog_content = "설마 내가 일루미나를 떠난 게 배신 같은 지루한 이유라고 생각했던 거야?",
  ui_story_1015_10151202_54_dialog_content = "넌 완전히 틀렸어.",
  ui_story_1015_10151202_55_dialog_content = "그럼 왜 일루미나를 배신한 거죠?",
  ui_story_1015_10151202_56_dialog_content = "이유는 간단해.",
  ui_story_1015_10151202_57_dialog_content = "일루미나 연방이 제공해 줄 수 있는 연구 환경은 이제 더는 내 연구의 심화를 도울 수 없거든.",
  ui_story_1015_10151202_58_dialog_content = "제공 가능한 연구 대상이든, 연구에 사용하는 소재든,\n전부 내 연구에 새로운 진전을 가져다줄 수 없는 것들뿐이었어.",
  ui_story_1015_10151202_59_dialog_content = "그래서 난 떠나기로 결정했어.\n마침 이클립스가 가진 기술엔 연구의 돌파구를 열 가능성이 있었거든.",
  ui_story_1015_10151202_60_dialog_content = "그게 다야.",
  ui_story_1015_10151202_61_dialog_content = "<color=#e8d9bb>같은 시간, 지하성의 어딘가</color>",
  ui_story_1015_10151202_62_dialog_content = "<color=#e8d9bb>콰앙!</color>",
  ui_story_1015_10151202_63_dialog_content = "딱 좋은 시간이군.",
  ui_story_1015_10151202_64_dialog_content = "녀석의 계획은 항상 정확했지.",
  ui_story_1015_10151202_65_dialog_content = "<color=#e8d9bb>치지직──</color>",
  ui_story_1015_10151202_66_dialog_content = "자, 그럼 이제 「<color=#FFB400>해결사</color>」가 나설 차례인가.",
  ui_story_1015_10151301_1_dialog_content = "<color=#e8d9bb>위잉── 위잉──</color>",
  ui_story_1015_10151301_2_dialog_content = "참 시끄럽네.",
  ui_story_1015_10151301_3_dialog_content = "뭐라고요?",
  ui_story_1015_10151301_4_dialog_content = "넌 다른 생쥐들보다 조금은 우수할 거라 생각했는데.",
  ui_story_1015_10151301_5_dialog_content = "아무래도 너도 딱 그 정도인 모양이구나.",
  ui_story_1015_10151301_6_dialog_content = "전력을 끊어.",
  ui_story_1015_10151301_7_dialog_content = "이런! 스위치를 지켜야 합니다!",
  ui_story_1015_10151301_8_dialog_content = "<anim type=Shake><size=45>캬아악!</size></anim>",
  ui_story_1015_10151301_9_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_1015_10151301_10_dialog_content = "이런... 이 지하성의 출입문 제어 시스템은 전력 시스템과 직결되어 있어요.",
  ui_story_1015_10151301_11_dialog_content = "전력이 끊기면 문도 닫혀버리죠...",
  ui_story_1015_10151301_12_dialog_content = "저 문 쪽이 출구입니까?",
  ui_story_1015_10151301_13_dialog_content = "아뇨, 저건... 출구보다 더 골치 아픈 물건이에요.",
  ui_story_1015_10151301_14_dialog_content = "무슨 뜻이죠?",
  ui_story_1015_10151301_15_dialog_content = "<color=#e8d9bb>치지직──</color>",
  ui_story_1015_10151301_16_dialog_content = "그 답은 내가 알려줄게.",
  ui_story_1015_10151301_17_dialog_content = "이 안에 있는 건 화음 연결 장치야.",
  ui_story_1015_10151301_19_dialog_content = "뭘 할 생각이든 당장 멈춰요!",
  ui_story_1015_10151301_20_dialog_content = "그 장치는 불완전해요! 함부로 사용하면 큰 위험이 따를 거라고요!",
  ui_story_1015_10151301_21_dialog_content = "네 정보력이 좋다는 건 인정할게.",
  ui_story_1015_10151301_22_dialog_content = "하지만 잊으면 안 되지, 생쥐야.",
  ui_story_1015_10151301_23_dialog_content = "넌 연구원이 아니야. 이 장치에 관한 지식도 전부 그 늙은이한테 들은 거잖아.",
  ui_story_1015_10151301_24_dialog_content = "네가 이 장치가 위험하다고 생각하는 것도 그저──",
  ui_story_1015_10151301_25_dialog_content = "너희가 사용법을 몰라서 그럴 뿐이야.",
  ui_story_1015_10151301_26_dialog_content = "<color=#e8d9bb>콰직──</color>",
  ui_story_1015_10151301_27_dialog_content = "실험에 방해가 되는 요소는 배제했어. 그럼 계속하자.",
  ui_story_1015_10151301_28_dialog_content = "실험체, 이리 와.",
  ui_story_1015_10151301_29_dialog_content = "......",
  ui_story_1015_10151301_30_dialog_content = "<color=#e8d9bb>같은 시간, 자난성</color>",
  ui_story_1015_10151301_31_dialog_content = "<color=#e8d9bb>지지직──</color>",
  ui_story_1015_10151301_32_dialog_content = "레이스 군단장님, 긴급 임무입니다! 수신 즉시 응답 바랍니다!",
  ui_story_1015_10151301_33_dialog_content = "긴급 임무? 이런 시간에 무슨 긴급 임무라는 거야?",
  ui_story_1015_10151301_34_dialog_content = "이상하네, 일단 들어나 봐.",
  ui_story_1015_10151301_35_dialog_content = "여기는 레이스, 수신 양호.",
  ui_story_1015_10151301_36_dialog_content = "X호 지하성에 노라가 침입한 것으로 추정되는 상황입니다.\n군단장님께서 즉시 지원해 노라와 헬리오스를 체포하라는 위원회의 명령입니다.",
  ui_story_1015_10151301_37_dialog_content = "<size=45>뭐라고?!</size>",
  ui_story_1015_10151301_38_dialog_content = "노라? 일루미나의 영역까지 발을 들일 줄이야...",
  ui_story_1015_10151301_39_dialog_content = "......",
  ui_story_1015_10151301_40_dialog_content = "그렇게 된 이상 나도 같이 가야겠지, 레이스.",
  ui_story_1015_10151301_41_dialog_content = "당연히 그럴 거라 생각했어.",
  ui_story_1015_10151301_42_dialog_content = "대신 약속해. 돌발 행동은 금지야.",
  ui_story_1015_10151301_43_dialog_content = "물론이지. 이건 네 임무니까, 나도 간섭하진 않겠어.",
  ui_story_1015_10151301_44_dialog_content = "좋아, 그럼 같이 가자.",
  ui_story_1015_10151302_1_dialog_content = "<color=#e8d9bb>똑똑똑.</color>",
  ui_story_1015_10151302_2_dialog_content = "들어와라.",
  ui_story_1015_10151302_3_dialog_content = "하아, 하아... 보고드립니다!",
  ui_story_1015_10151302_4_dialog_content = "율리시스 님, 계획대로 레이스 군단장이 이쪽으로 오고 있습니다.\n약 한 시간 뒤에 도착합니다.",
  ui_story_1015_10151302_5_dialog_content = "다만 상황이 조금 달라졌습니다. 대원수도 동행하고 있습니다.",
  ui_story_1015_10151302_6_dialog_content = "호오?",
  ui_story_1015_10151302_7_dialog_content = "상관없네. 그것도 예상 범위 안의 일이니.",
  ui_story_1015_10151302_8_dialog_content = "이것도 율리시스 님의 계획인 겁니까?",
  ui_story_1015_10151302_9_dialog_content = "허허, 내 계획일 리가 있나.",
  ui_story_1015_10151302_10_dialog_content = "하지만 화음 연결 실험실에서 연기가 피어오르고 있습니다...",
  ui_story_1015_10151302_11_dialog_content = "불은 신경 쓸 거 없네. 감시카메라로 확인했으니 말이야.\n거긴 불타지 않을 걸세.",
  ui_story_1015_10151302_12_dialog_content = "앉아서 물이라도 좀 마시게.\n앞으로의 일은 관중석에 앉아서 보고 있으면 되니 말이야.",
  ui_story_1015_10151302_13_dialog_content = "예.",
  ui_story_1015_10151302_14_dialog_content = "어쩐지 녀석과 카드게임을 하면 어떻게 해도 이길 수 없더라니.",
  ui_story_1015_10151302_15_dialog_content = "남의 마음을 다 읽고 있지 않은가.",
  ui_story_1015_10151302_16_dialog_content = "드니에르, 아니지, 노라. 정말 부러운 녀석이란 말이지.",
  ui_story_1015_10151302_17_dialog_content = "......?",
  ui_story_1015_10151302_18_dialog_content = "자네는 부럽지 않나?",
  ui_story_1015_10151302_19_dialog_content = "율리시스 님, 저는...",
  ui_story_1015_10151302_20_dialog_content = "하긴, 자네는 연구자가 아니니까, 부러워하지 않는 게 정상이지.",
  ui_story_1015_10151302_21_dialog_content = "......",
  ui_story_1015_10151302_22_dialog_content = "녀석의 어디가 부러워할 만한 건지 생각하고 있나?",
  ui_story_1015_10151302_23_dialog_content = "그렇습니다.",
  ui_story_1015_10151302_24_dialog_content = "노라는 연구자로서 가장 우수한 품성을 가지고 있네.",
  ui_story_1015_10151302_25_dialog_content = "집착 말씀이십니까?",
  ui_story_1015_10151302_26_dialog_content = "아니, 냉혹함일세.",
  ui_story_1015_10151302_27_dialog_content = "일루미나에서는 예로부터 전해지는 말이 있네.",
  ui_story_1015_10151302_28_dialog_content = "「과학 기술에는 선악의 구분이 없다. 있는 것은 그것을 이용하는 오로리안의 선악뿐이다.」",
  ui_story_1015_10151302_29_dialog_content = "허나 새로운 기술을 개발하기 위해서는 먼저 「악인」이 되어야 하는 경우가 많지.",
  ui_story_1015_10151302_30_dialog_content = "이 세상에는 언제나 모든 면에서 좋은 방법만 있는 건 아닐세.\n그리고 노라는 그 점을 아주 잘 알고 있네.",
  ui_story_1015_10151302_31_dialog_content = "훌륭한 연구 성과를 얻기 위해서라면 망설임 없이 과거의 전우들을 실험체로 삼을 수 있지.",
  ui_story_1015_10151302_32_dialog_content = "그것이 가장 확고한 증거일세.",
  ui_story_1015_10151302_33_dialog_content = "하지만 그건 궁지에 몰려 어쩔 수 없이 내린 선택 아닙니까?",
  ui_story_1015_10151302_34_dialog_content = "아니, 전혀. 우린 녀석을 결코 몰아세우지 않았네.",
  ui_story_1015_10151302_35_dialog_content = "우리가 한 일이라고는 그저 노라에게 약간의 제약과 함께,\n그 무엇보다도 좋은 기회를 주었을 뿐이지.",
  ui_story_1015_10151302_36_dialog_content = "그 기회를 잡은 건 온전히 노라 자신의 선택일세.",
  ui_story_1015_10151302_37_dialog_content = "「과학의 방식으로 생물이 지닌 가능성의 극한을 찾아낸다.」\n녀석의 연구는 단 한 순간도 그 실험의 본질에서 벗어난 적이 없었네.",
  ui_story_1015_10151302_38_dialog_content = "가장 처음의 「인공 태양 프로젝트」 때부터 말이야.",
  ui_story_1015_10151302_39_dialog_content = "자네도 알고 있겠지? 「계명성 프로젝트」의 전신이었던 것 말이야.",
  ui_story_1015_10151302_40_dialog_content = "그 성과는 일루미나가 독자적으로 개발해 낸 오로리안 강화 기술일세.\n하지만 기술이 아직 미숙했기 때문에 결과물은 안정적이지 못했지.",
  ui_story_1015_10151302_41_dialog_content = "막강한 힘이 오로리안의 체내에서 아무 제한 없이 날뛰고,\n오직 강력한 의지로 억누르는 수밖에 없었으니 말이야.",
  ui_story_1015_10151302_42_dialog_content = "그 결과 성공률이 극히 낮았을 뿐만 아니라, 실험체도 힘의 제어를 잃기 쉬웠지.",
  ui_story_1015_10151302_43_dialog_content = "그리고 힘의 제어를 잃은 결과는 목숨을 잃거나, 평생 장애가 남거나,\n아니면... 저런 「괴물」이 되는 것이네.",
  ui_story_1015_10151302_44_dialog_content = "하지만 과거의 드니에르, 그러니까 노라는 그 어느 상황에도 해당하지 않았습니다.",
  ui_story_1015_10151302_45_dialog_content = "그럼 노라는 실패한 겁니까?",
  ui_story_1015_10151302_46_dialog_content = "엄밀히 말하면 아닐세.",
  ui_story_1015_10151302_47_dialog_content = "노라는 성공한 개체일세. 다만 그 성공의 방향이 우리의 예상과는 달랐을 뿐이지.",
  ui_story_1015_10151302_48_dialog_content = "우리가 얻고자 했던 것은 힘이 강화된 개체였지만, 노라가 강화된 건 지능이었네.",
  ui_story_1015_10151302_49_dialog_content = "실험의 성공으로 노라는 가장 재능 있는 연구원이 되었고,\n동시에 일루미나의 최대 위험 요소가 되었지.",
  ui_story_1015_10151302_50_dialog_content = "그리고 그 결과는 자네도 본 대로일세.\n노라는 망설임 없이 반역자가 되었고, 일루미나와 대립했네.",
  ui_story_1015_10151302_51_dialog_content = "따라서 일루미나에 있어서는 라인하르트야말로 「인공 태양 프로젝트」의\n그 결과물 중에서 가장 성공한 개체인 것이네.",
  ui_story_1015_10151302_52_dialog_content = "하지만 아직도 이해가 안 되는 점이 하나 있습니다.",
  ui_story_1015_10151302_53_dialog_content = "대체 무슨 기준으로 「인공 태양 프로젝트」의 개조가 「성공」했는지 판단할 수 있는 겁니까?",
  ui_story_1015_10151302_54_dialog_content = "모든 실패의 특징이 개조 후 곧바로 드러나는 건 아니지 않습니까?",
  ui_story_1015_10151302_55_dialog_content = "80호 지하성에서 있었던 전투를 기억하나?",
  ui_story_1015_10151302_56_dialog_content = "예, 기억합니다.",
  ui_story_1015_10151302_57_dialog_content = "당시 「인공 태양 프로젝트」의 개조 개체 부대에 제공하는 자료를\n위원회의 요구에 따라 수정한 게 저였으니 말입니다.",
  ui_story_1015_10151302_58_dialog_content = "그 허위 정보로 저들이 암귀의 포위망에 빠지게 만들었었지요.",
  ui_story_1015_10151302_59_dialog_content = "당시 정확한 정보를 수집하기 위해 상당수의 정찰 부대 손실이 있었던 것도 기억합니다.",
  ui_story_1015_10151302_60_dialog_content = "제 부하가 속했던 부대도 그중 하나였습니다. 그 부대의 유일한 생환자 말입니다.",
  ui_story_1015_10151302_61_dialog_content = "아, 기억이 나는군. 그런 자가 있었지. 이름이 뭐였더라?",
  ui_story_1015_10151302_62_dialog_content = "<color=#FFB400>아나톨리</color>입니다.",
  ui_story_1015_10151302_63_dialog_content = "그런 이름이었던 것 같군.\n얼마 전 그자를 라인하르트의 부관으로 파견하지 않았었나?",
  ui_story_1015_10151302_64_dialog_content = "그자는 이 일을 알고 있는 건가?\n더 중요한 건 그자가 라인하르트의 감시를 맡아도 되는 건가?",
  ui_story_1015_10151302_65_dialog_content = "정보 수집 능력에 있어서는 충분히 신뢰할 만하다고 생각합니다.",
  ui_story_1015_10151302_66_dialog_content = "게다가 이 임무는 애초부터 그의 충성도를 시험하기 위한 것이었습니다.",
  ui_story_1015_10151302_67_dialog_content = "허허, 자네가 그렇게 생각한다면 그렇게 하게.",
  ui_story_1015_10151302_68_dialog_content = "이야기가 다른 길로 새버렸군. 80호 지하성 일로 돌아가지.",
  ui_story_1015_10151302_69_dialog_content = "그 전투는 우리가 개조 개체를 「선별」하는 작업이었네.",
  ui_story_1015_10151302_70_dialog_content = "의도적으로 그들을 절체절명의 상황에 빠뜨려 루미나를 극한까지 소모하게 만들면...",
  ui_story_1015_10151302_71_dialog_content = "약한 개체는 그대로 소멸하겠지.",
  ui_story_1015_10151302_72_dialog_content = "정신적 결함이 있는 불안정한 개체는 그러한 극단적 상황에서\n통제력을 잃고 결국 배제되는 것이네.",
  ui_story_1015_10151302_73_dialog_content = "그러나 성공한 개체는 그 어려움을 극복하고 살아남지.",
  ui_story_1015_10151302_74_dialog_content = "하지만... 그 프로젝트는 성공률이 너무 낮아서 결국 중단되지 않았습니까?",
  ui_story_1015_10151302_75_dialog_content = "일루미나가 그 불완전한 「화음 연결」 장치를 얻기 전까지 말입니다.",
  ui_story_1015_10151302_76_dialog_content = "그렇네. 「인공 태양 프로젝트」는 애초에 재개되지 말았어야 했네.",
  ui_story_1015_10151302_77_dialog_content = "하지만 「화음 연결」 장치가 새로운 전기를 가져왔지.",
  ui_story_1015_10151302_78_dialog_content = "「화음 연결」은 아이테르 과학 기술의 정점일세.\n또한 「인공 태양 프로젝트」와는 다른 완전히 새로운 힘이었지.",
  ui_story_1015_10151302_79_dialog_content = "그 두 기술을 융합한 끝에 「계명성 프로젝트」의 실험체들이 탄생했네.",
  ui_story_1015_10151302_80_dialog_content = "「계명성 프로젝트」의 개조를 받은 오로리안의 체내에는\n두 가지 다른 기술이 가져온 힘이 동시에 존재하지.",
  ui_story_1015_10151302_81_dialog_content = "그 두 힘은 서로 균형을 유지해서, 강화의 성공률을 일정 수준 향상시켰네.",
  ui_story_1015_10151302_82_dialog_content = "허나 그 균형도 충분히 안정적이진 않았네.\n따라서 「계명성 프로젝트」로 개조된 대부분의 오로리안은 몸이 취약했지.",
  ui_story_1015_10151302_83_dialog_content = "그 막강한 힘을 과도하게 사용하면, 미묘하게 유지되던 두 힘의 균형이 깨지고 마는 것이네.",
  ui_story_1015_10151302_84_dialog_content = "그리고 그들의 육체 역시 그로 인해 무너지고 말지.",
  ui_story_1015_10151302_85_dialog_content = "악셀리아가 바로 그 좋은 예시라네.",
  ui_story_1015_10151302_86_dialog_content = "하지만 이번엔 다르네. 노라가 새로운 힘을 가져왔으니,\n이제 노라의 연구가 실험을 더 높은 수준으로 이끌 것이네.",
  ui_story_1015_10151302_87_dialog_content = "...「<color=#FFB400>씨앗</color>」 말씀이십니까?",
  ui_story_1015_10151302_88_dialog_content = "그렇네.",
  ui_story_1015_10151302_89_dialog_content = "노라는 오랜 시간 동안 「씨앗」을 연구했네.\n그리고 「씨앗」은 이미 오래전부터 암귀 측 기술의 집대성이 되었지.",
  ui_story_1015_10151302_90_dialog_content = "「씨앗」의 존재는 퍼즐의 마지막 조각이 될 걸세.\n그리고 그 조각은 노라만이 끼울 수 있지.",
  ui_story_1015_10151302_91_dialog_content = "그렇게 세 가지 힘이 오로리안의 몸속에서 견제와 균형을 이루고, 안정적인 새 힘이 되겠지.",
  ui_story_1015_10151302_92_dialog_content = "......!",
  ui_story_1015_10151302_93_dialog_content = "우린 그 중대한 첫 실험의 결과를 기대하며 지켜보면 되는 것이네.",
  ui_story_1015_10151302_94_dialog_content = "<color=#e8d9bb>같은 시간, 일루미나 연방 화음 연결 실험실</color>",
  ui_story_1015_10151302_95_dialog_content = "<color=#e8d9bb>쿵── 쿵!</color>",
  ui_story_1015_10151302_96_dialog_content = "시끄러워.",
  ui_story_1015_10151302_97_dialog_content = "실험 환경은 마지못해 합격인가. 뭐, 이 정도면 충분해.",
  ui_story_1015_10151302_98_dialog_content = "마지막 파라미터 체크.",
  ui_story_1015_10151302_99_dialog_content = "파라미터 이상 없음.",
  ui_story_1015_10151302_100_dialog_content = "마지막 실험 재료를 넣을 차례네.",
  ui_story_1015_10151302_101_dialog_content = "실험을 시작한다.",
  ui_story_1015_10151302_102_dialog_content = "이제 「씨앗」이 생명의 진화를 이끌어 줄 거야.",
  ui_story_1015_10151302_103_dialog_content = "<color=#e8d9bb>화음 연결 실험실 밖</color>",
  ui_story_1015_10151302_104_dialog_content = "얼어붙어라!",
  ui_story_1015_10151302_105_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_1015_10151302_106_dialog_content = "수 차례의 공격과 폭발에도 이 문에는 구멍 하나 뚫리지 않았어.",
  ui_story_1015_10151302_107_dialog_content = "아무래도 강행 돌파는 무리일 것 같아.",
  ui_story_1015_10151302_108_dialog_content = "건설할 때 가장 견고한 방폭 소재를 사용했으니까요.",
  ui_story_1015_10151302_109_dialog_content = "방화용으로 준비한 시설이 지금은 우릴 막는 장애물이 돼버렸네요.",
  ui_story_1015_10151302_110_dialog_content = "안에 있는 화음 연결 장치는 아마 노라가 하려는 실험의 필수품이겠죠.",
  ui_story_1015_10151302_111_dialog_content = "이대로 마음대로 하게 뒀다가는 더 곤란해질 겁니다.",
  ui_story_1015_10151302_112_dialog_content = "맞아! 무조건 막아야지!",
  ui_story_1015_10151302_113_dialog_content = "그럼 다른 방법은 없을까?",
  ui_story_1015_10151302_114_dialog_content = "생각 좀 해 볼게요...",
  ui_story_1015_10151302_115_dialog_content = "어쩌면 방법이 하나 있을 것 같네요.",
  ui_story_1015_10151302_116_dialog_content = "뭔데?",
  ui_story_1015_10151302_117_dialog_content = "이 지하성은 한때 노라의 비밀 실험실이었어요.\n매일 실패한 실험체가 대량으로 버려지고 있었죠.",
  ui_story_1015_10151302_118_dialog_content = "노라는 전에 시간을 아끼려고 실험실에서 곧바로 지하의\n폐기물 처리실로 연결되는 통로를 만들었어요.",
  ui_story_1015_10151302_119_dialog_content = "지하성을 재건할 때 그 통로의 입구는 벽에 막혔지만,\n통로 자체는 남아 있어요.",
  ui_story_1015_10151302_120_dialog_content = "조금 돌아가는 길이긴 하지만, 통로를 막은 벽 쪽이 이 문보다는 파괴하기 쉬울 거예요.",
  ui_story_1015_10151302_121_dialog_content = "자기가 쓰레기를 버리려고 만든 「고속 통로」로 이번엔 깜짝 선물을 전해주죠.",
  ui_story_1015_10151401_1_dialog_content = "여기가 약한 부분이에요!",
  ui_story_1015_10151401_2_dialog_content = "<color=#e8d9bb>쾅! 쾅──!</color>",
  ui_story_1015_10151401_3_dialog_content = "<color=#e8d9bb>콰르릉──!</color>",
  ui_story_1015_10151401_4_dialog_content = "통로가 뚫렸어!",
  ui_story_1015_10151401_5_dialog_content = "노라, 당장 멈추세요!",
  ui_story_1015_10151401_6_dialog_content = "당신 수하의 암귀는 모두 처리했어요!",
  ui_story_1015_10151401_7_dialog_content = "너무 늦었네.",
  ui_story_1015_10151401_8_dialog_content = "실험은 이미 성공했거든.",
  ui_story_1015_10151401_9_dialog_content = "<color=#e8d9bb>위이잉──</color>",
  ui_story_1015_10151401_10_dialog_content = "PlayerName! 저 장치를 봐!",
  ui_story_1015_10151401_11_dialog_content = "안에서 뭔가 나오려고 해!",
  ui_story_1015_10151401_12_dialog_content = "저...저건?!",
  ui_story_1015_10151401_13_dialog_content = "저게 대체 무슨 괴물이야?!",
  ui_story_1015_10151401_14_dialog_content = "“실험체 헬리오스의 112번째 실험 기록──”",
  ui_story_1015_10151401_15_dialog_content = "“실험 절차, 먼저 「화음 연결」 장치를 사용하여 「인공 태양 프로젝트」의\n피험개체에 강화를 실시하였으며──”",
  ui_story_1015_10151401_16_dialog_content = "“추가로 「화음 연결」 장치에 「씨앗」을 투입했다.”",
  ui_story_1015_10151401_17_dialog_content = "“그 결과, 실험은 초보적인 성공을 거두었으며,\n피험개체가 활동을 정지할 위험성이 대폭 감소했다.”",
  ui_story_1015_10151401_18_dialog_content = "...저거 지금 실험 기록 남기고 있는 거야?",
  ui_story_1015_10151401_19_dialog_content = "자신의 옛 전우를 저런 모습으로 만들어 놓고 태연하게 실험 기록을 남기고 있다니...",
  ui_story_1015_10151401_20_dialog_content = "율리시스 교수님 말씀이 맞았네요. 당신은 정말 냉혈동물 그 자체군요.",
  ui_story_1015_10151401_21_dialog_content = "율리시스?",
  ui_story_1015_10151401_22_dialog_content = "그 늙은이라면 이번 실험 결과를 나보다 더 기대하고 있을걸.",
  ui_story_1015_10151401_23_dialog_content = "...뭐라고요?",
  ui_story_1015_10151401_24_dialog_content = "그럼 다음 실험을 할 차례네.",
  ui_story_1015_10151401_25_dialog_content = "실전을 통해 피험개체의 안정성을 체크해 보자.",
  ui_story_1015_10151401_26_dialog_content = "실험체, 가서 저들을 찢어버려.",
  ui_story_1015_10151401_27_dialog_content = "!!!",
  ui_story_1015_10151401_28_dialog_content = "PlayerName, 적당한 곳을 찾아서 숨으세요!",
  ui_story_1015_10151401_29_dialog_content = "아, 알았어!",
  ui_story_1015_10151401_30_dialog_content = "......",
  ui_story_1015_10151401_31_dialog_content = "(저 괴물... 아무 반응이 없는데, 설마 실험이 실패한 걸까요?)",
  ui_story_1015_10151401_32_dialog_content = "그렇구나, 아무래도 내 실험이 한 단계 더 성공했던 모양이네.",
  ui_story_1015_10151401_33_dialog_content = "(한 단계 더 성공? 그게 무슨...)",
  ui_story_1015_10151401_34_dialog_content = "그럼 이제 말하는 방식을 바꿔야겠구나.",
  ui_story_1015_10151401_35_dialog_content = "일루미나 연방의 병사, 헬리오스──",
  ui_story_1015_10151401_36_dialog_content = "......!",
  ui_story_1015_10151401_37_dialog_content = "반응을 보였어... 설마 말을 알아들은 건가?!",
  ui_story_1015_10151401_38_dialog_content = "지금 눈앞에 있는 건 일루미나 연방의 반역자와 적이다.",
  ui_story_1015_10151401_39_dialog_content = "네 임무는 저들을 처리하는 것이다.",
  ui_story_1015_10151401_40_dialog_content = "<anim type=Shake><size=50>크아아아!</size></anim>",
  ui_story_1015_10151401_41_dialog_content = "잠깐! 멈추세요!",
  ui_story_1015_10151401_42_dialog_content = "우리는 적이 아닙니다! 노라야말로 일루미나의 반역자이자 적입니다!",
  ui_story_1015_10151401_43_dialog_content = "<anim type=Shake><size=50>그어어어!</size></anim>",
  ui_story_1015_10151401_44_dialog_content = "으윽!",
  ui_story_1015_10151401_45_dialog_content = "소용없어요. 완전히 이성을 되찾은 건 아닌 것 같아요.",
  ui_story_1015_10151401_46_dialog_content = "일단 쓰러트리고 나서 생각해요.",
  ui_story_1015_10151402_1_dialog_content = "<anim type=Shake><size=50>크아아아!</size></anim>",
  ui_story_1015_10151402_2_dialog_content = "어떻게 이렇게 강해진 거지...?",
  ui_story_1015_10151402_3_dialog_content = "힘뿐만 아니라 행동까지도 예측이 어려워졌어요.",
  ui_story_1015_10151402_4_dialog_content = "모두 조심하세요!",
  ui_story_1015_10151402_5_dialog_content = "지금까지는 본능으로 반격했을 뿐이라면, 이제부터는 전술을 사용하기 시작했습니다.",
  ui_story_1015_10151402_6_dialog_content = "괴물이 전략을 배웠단 말인가요?",
  ui_story_1015_10151402_7_dialog_content = "일이 점점 귀찮아지는군요...",
  ui_story_1015_10151402_8_dialog_content = "“실험은 확실히 성공했다. 내 이론은 옳았던 것이다.”",
  ui_story_1015_10151402_9_dialog_content = "“세 가지 다른 힘이 실험체의 체내에서 상호작용을 통해 안정적인 상태를 이루었다.”",
  ui_story_1015_10151402_10_dialog_content = "“게다가 고강도의 전투를 수행해도 균형이 깨지지 않는다.”",
  ui_story_1015_10151402_11_dialog_content = "“그리고 가장 중요한 점은 이 실험을 재현할 수 있다는 것이다.”",
  ui_story_1015_10151402_12_dialog_content = "“나머지는 마지막 실험 결과만 검증하면 실험의 완전한 성공을 증명할 수 있다.”",
  ui_story_1015_10151402_13_dialog_content = "<anim type=Shake>그르르...</anim>",
  ui_story_1015_10151402_14_dialog_content = "조심해! 저 녀석 뭔가 이상해!",
  ui_story_1015_10151402_15_dialog_content = "저건 루미나야? 아니면 다크매터야? 두 힘이 섞여 있어서 구분이 안 돼!",
  ui_story_1015_10151402_16_dialog_content = "지금 그런 걸 따질 때가 아니에요. 방어 태세를 취하세요!",
  ui_story_1015_10151402_17_dialog_content = "<anim type=Shake><size=50>크오오오──!</size></anim>",
  ui_story_1015_10151402_18_dialog_content = "?!",
  ui_story_1015_10151402_19_dialog_content = "모습이 바뀌었잖아?!",
  ui_story_1015_10151402_20_dialog_content = "저 모습... 80호 지하성에서 기억의 조각을 감응했을 때 본 적 있어...",
  ui_story_1015_10151402_21_dialog_content = "헬리오스의 원래 모습이야!",
  ui_story_1015_10151402_22_dialog_content = "드디어 여기까지 왔네.",
  ui_story_1015_10151402_23_dialog_content = "이걸로 마지막 검증도 끝났어.",
  ui_story_1015_10151402_24_dialog_content = "상태가 안정되면서 더 큰 강점이 생겼어. 덕분에 힘을 제어할 수 있게 된 거야.",
  ui_story_1015_10151402_25_dialog_content = "이제 이성을 잃고 괴물이 된다는 「인공 태양 프로젝트」의 부작용을 억제할 수 있어.",
  ui_story_1015_10151402_26_dialog_content = "그리고 오로리안에게 스스로 형태를 바꿀 수 있는 능력을 줬지.",
  ui_story_1015_10151402_27_dialog_content = "이거야말로 내가 원하던 성과야.",
  ui_story_1015_10151402_28_dialog_content = "<anim type=Shake>으윽...</anim>",
  ui_story_1015_10151402_29_dialog_content = "<anim type=Shake>여기...는...</anim>",
  ui_story_1015_10151402_30_dialog_content = "마, 말을 하는데?!",
  ui_story_1015_10151402_31_dialog_content = "아... 아니... 어째서... 왜... 80호 지하성이 아닌 거냐?",
  ui_story_1015_10151402_32_dialog_content = "당신들은... 누구지?",
  ui_story_1015_10151402_33_dialog_content = "오로리안의 모습으로 돌아오다니... 설마 이성도 되찾은 겁니까?",
  ui_story_1015_10151402_34_dialog_content = "전 위원회 직속 정보장교 잉겔입니다.",
  ui_story_1015_10151402_35_dialog_content = "헬리오스 대위, 당신은 적과 내통하고 암귀와 결탁한 혐의가 있습니다.",
  ui_story_1015_10151402_36_dialog_content = "지금 당장 무기를 버려 저항을 멈추고, 위원회의 조사에 협조하세요!",
  ui_story_1015_10151402_37_dialog_content = "아니, 그런 적 없다...",
  ui_story_1015_10151402_38_dialog_content = "내가... 적과 내통이라니, 말도 안 돼...",
  ui_story_1015_10151402_39_dialog_content = "나...나는...",
  ui_story_1015_10151402_40_dialog_content = "헬리오스 대위, 진정하세요!",
  ui_story_1015_10151402_41_dialog_content = "주위를 잘 살펴보세요. 여긴 80호 지하성이 아닙니다.",
  ui_story_1015_10151402_42_dialog_content = "이젠 싸울 필요가 없습니다...",
  ui_story_1015_10151402_43_dialog_content = "대체... 무슨 일이 있었던 거지? 난... 왜 여기 있는 거냐...",
  ui_story_1015_10151402_44_dialog_content = "어째서... 아무것도 생각나지 않는 거냔 말이다...",
  ui_story_1015_10151402_45_dialog_content = "으윽...!",
  ui_story_1015_10151402_46_dialog_content = "“실험체의 인지 능력은 온전하다. 하지만 기억의 손실과 착란이 발생한 것 같다.\n제어를 잃은 후의 기억이 없는 것으로 보인다.”",
  ui_story_1015_10151402_47_dialog_content = "“일단 주의해야 할 부작용으로 기록해 두겠다.\n이 부작용을 완전히 없애려면 아직 연구가 필요하다.”",
  ui_story_1015_10151402_48_dialog_content = "“물론, 이러한 상태는 실험체 자체의 결함으로 인한 것일 가능성이 더 크다.”",
  ui_story_1015_10151402_49_dialog_content = "“그래도 총체적으로 이 실험은 성공했다.”",
  ui_story_1015_10151402_50_dialog_content = "“나는 마침내 「진화」의 방법을 손에 넣은 것이다.”",
  ui_story_1015_10151402_51_dialog_content = "“지금 남은 문제는 하나뿐이다...”",
  ui_story_1015_10151402_52_dialog_content = "(후속 검증을 진행하려면 이 실험체가 반드시 필요해.)",
  ui_story_1015_10151402_53_dialog_content = "(어떻게든 데리고 돌아가야 해.)",
  ui_story_1015_10151402_54_dialog_content = "(하지만 서서히 의식이나 인지를 회복하고 있는 건 계획에 불리한 변수야.)",
  ui_story_1015_10151402_55_dialog_content = "(그래도 저런 머리가 단순한 타입의 실험체에 대한 대처법이라면 얼마든지 있어.)",
  ui_story_1015_10151402_56_dialog_content = "너... 누군지 알겠어...",
  ui_story_1015_10151402_57_dialog_content = "...드니에르?",
  ui_story_1015_10151402_58_dialog_content = "어째서... 그런 모습인 거냐...",
  ui_story_1015_10151402_59_dialog_content = "라인하르트는... 어디 있어...?",
  ui_story_1015_10151402_60_dialog_content = "어째서... 너와... 함께 있지... 않은 거지...?",
  ui_story_1015_10151402_61_dialog_content = "......",
  ui_story_1015_10151402_62_dialog_content = "드니에르도, 너도, 오래전에 일루미나에게 버림받았어.",
  ui_story_1015_10151402_63_dialog_content = "그리고 난 드니에르가 아냐.",
  ui_story_1015_10151402_64_dialog_content = "버림...받아...?",
  ui_story_1015_10151402_65_dialog_content = "<anim type=Shake>크윽...!</anim>",
  ui_story_1015_10151402_66_dialog_content = "헬리오스의 몸에 다크매터가 모여들고 있어!",
  ui_story_1015_10151402_67_dialog_content = "설마 말로 정신을 자극해서 다시 괴물로 변하게 만들려는 건가?!",
  ui_story_1015_10151402_68_dialog_content = "다들 이제 남은 힘도 거의 없다고...",
  ui_story_1015_10151402_69_dialog_content = "들었어? 저들은 널 「괴물」이라고 불렀어.",
  ui_story_1015_10151402_70_dialog_content = "<anim type=Shake>아니야... 난... 괴물이 아니라고...</anim>",
  ui_story_1015_10151402_71_dialog_content = "<anim type=Shake>나는... 일루미나의... 군인이다...</anim>",
  ui_story_1015_10151402_72_dialog_content = "흥...",
  ui_story_1015_10151402_73_dialog_content = "일루미나 연방에 네가 있을 곳은 없어.",
  ui_story_1015_10151402_74_dialog_content = "네가 살 기회는 날 따라와야 얻을 수 있어.",
  ui_story_1015_10151402_75_dialog_content = "여기 남아 있으면 죽음뿐이야.",
  ui_story_1015_10151402_76_dialog_content = "믿지 마십시오! 일루미나 연방은 그 누구도 저버리지 않습니다!",
  ui_story_1015_10151402_77_dialog_content = "연방에 더는 공헌할 수 없는 자는 버림받게 돼 있어. 특히 실패작 말이야.",
  ui_story_1015_10151402_78_dialog_content = "대원수님께서도 당신을 결코 버리지 않으셨습니다.\n단 한 번도 당신들의 행방을 찾는 것을 포기하지 않으셨단 말입니다!",
  ui_story_1015_10151402_79_dialog_content = "라인하르트는 지원군을 데려오지 않았어.",
  ui_story_1015_10151402_80_dialog_content = "어쩔 수 없었어! 그땐 일루미나의 상부에서 마취제로 라인하르트 씨를\n못 움직이게 만들어서 그랬던 거라고!",
  ui_story_1015_10151402_81_dialog_content = "그건 내가 감응 능력으로 본 거야! 절대 거짓말이 아냐!",
  ui_story_1015_10151402_82_dialog_content = "잊지 마. 80호 지하성에서 라인하르트는 너와 내 편이 아니었어.",
  ui_story_1015_10151402_83_dialog_content = "눈 똑바로 뜨고 잘 보세요! 당신의 옛 전우는 이제 오로리안이 아니에요!",
  ui_story_1015_10151402_84_dialog_content = "이미 두 손이 피로 물든 건 저쪽이라고요!",
  ui_story_1015_10151402_85_dialog_content = "저 위선자들이 밉지 않아?",
  ui_story_1015_10151402_86_dialog_content = "<size=45>시끄러워요!</size>",
  ui_story_1015_10151402_87_dialog_content = "<color=#e8d9bb>탕──!</color>",
  ui_story_1015_10151402_88_dialog_content = "<anim type=Shake><size=50>으윽!</size></anim>",
  ui_story_1015_10151402_89_dialog_content = "?!",
  ui_story_1015_10151402_90_dialog_content = "...뭐 하는 거야?",
  ui_story_1015_10151402_91_dialog_content = "나는... 일루미나의 군인이다...",
  ui_story_1015_10151402_92_dialog_content = "조사에는... 협조하겠다...",
  ui_story_1015_10151402_93_dialog_content = "하지만... 전우도...지켜야 한다...",
  ui_story_1015_10151402_94_dialog_content = "......",
  ui_story_1015_10151402_95_dialog_content = "어리석네.",
  ui_story_1015_10151402_96_dialog_content = "“아무래도 이 실험체는 자신과 타인에 대한 인식이 정확하지 않은 것처럼 보인다.”",
  ui_story_1015_10151402_97_dialog_content = "“어쩌면 모종의 정신 착란일 수 있다. 착오가 발생한 인지는 철저히 제거할 필요가 있다.”",
  ui_story_1015_10151402_98_dialog_content = "......?",
  ui_story_1015_10151402_99_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_1015_10151402_100_dialog_content = "무, 무슨 일이야?!",
  ui_story_1015_10151402_101_dialog_content = "PlayerName, 뒤로 물러나세요! 문에 큰 구멍이 뚫렸습니다!",
  ui_story_1015_10151402_102_dialog_content = "뭔가 엄청난 괴물이 들어오려는 것 같습니다!",
  ui_story_1015_10151402_103_dialog_content = "뭐어?!",
  ui_story_1015_10151402_104_dialog_content = "<color=#e8d9bb>콰아앙!</color>",
  ui_story_1015_10151402_105_dialog_content = "엄청나다는 건 맞아. 하지만 괴물은 아니야, 나야.",
  ui_story_1015_10151402_106_dialog_content = "역시 여기 있었나, 노라.",
  ui_story_1015_10151402_107_dialog_content = "딱 맞춰서 왔구나.",
  ui_story_1015_10151402_108_dialog_content = "또 만났네, 라인하르트.\n너란 사람은 시간이 지나도 전혀 성장하질 않는구나.",
  ui_story_1015_10151402_109_dialog_content = "여전히 이용당하고만 있잖아.",
  ui_story_1015_10151402_110_dialog_content = "오랜만이야, 노라.",
  ui_story_1015_10151402_111_dialog_content = "암귀랑 굴러먹는 게 잘 안됐나 봐? 이 지경까지 온 걸 보면 말이야.",
  ui_story_1015_10151402_112_dialog_content = "응? 넌 이름이 뭐더라? 레...?",
  ui_story_1015_10151402_113_dialog_content = "뭐, 됐어. 학교 동기 같은 보잘것없는 배역까지 내가 기억할 가치는 없으니까.",
  ui_story_1015_10151402_114_dialog_content = "어머, 지금 나 무시한 거야? 하, 괜찮아.",
  ui_story_1015_10151402_115_dialog_content = "이따가 내 손에 짓눌려서 얻어터질 때 울면서 네 언니나 찾지 마.",
  ui_story_1015_10151402_116_dialog_content = "유치해.",
  ui_story_1015_10151402_117_dialog_content = "넌... 라인하르트...?",
  ui_story_1015_10151402_118_dialog_content = "헬리오스?! 너, 모습이...",
  ui_story_1015_10151402_119_dialog_content = "지원군을... 데려온 거야? 드디어...",
  ui_story_1015_10151402_120_dialog_content = "......",
  ui_story_1015_10151402_121_dialog_content = "응, 미안해. 많이 늦었네.",
  ui_story_1015_10151402_122_dialog_content = "지원군을 데리고 너흴 구하러 왔어.",
  ui_story_1015_10151402_123_dialog_content = "포위해라!",
  ui_story_1015_10151402_124_dialog_content = "예!",
  ui_story_1015_10151402_125_dialog_content = "역시 내 예상에서 조금도 벗어나질 않네.",
  ui_story_1015_10151402_126_dialog_content = "라인하르트, 우리 거래하자.",
  ui_story_1015_10151402_127_dialog_content = "뭐...?",
  ui_story_1015_10151402_128_dialog_content = "나랑 이 실험체가 일루미나를 떠나게 해줘. 너한테 나쁜 일은 아니잖아?",
  ui_story_1015_10151402_129_dialog_content = "어머? 극야에 오래 있었더니 다크매터로 머리가 망가졌니?",
  ui_story_1015_10151402_130_dialog_content = "지금 넌 우리랑 조건을 협상할 자격이 없어.",
  ui_story_1015_10151402_131_dialog_content = "협상 같은 게 아냐.",
  ui_story_1015_10151402_132_dialog_content = "늙은이들이 원하는 건 내가 아니라 이쪽이니까.",
  ui_story_1015_10151402_133_dialog_content = "(무슨 뜻이죠? 위원회가 원하는 게 헬리오스라고요?)",
  ui_story_1015_10151402_134_dialog_content = "(하지만 위원회가 내린 임무는 노라를 붙잡고 바이스 중위를 구출하는 거였는데...)",
  ui_story_1015_10151402_135_dialog_content = "그놈들 손에 떨어지면 어떻게 될진 너도 알 거야.",
  ui_story_1015_10151402_136_dialog_content = "네 요구는 받아들일 수 없다.",
  ui_story_1015_10151402_137_dialog_content = "만약 10여 년 전, 네가 아직 일루미나에 있었을 때라면 널 믿었을 거다.",
  ui_story_1015_10151402_138_dialog_content = "하지만 우린 그토록 오랫동안 싸워왔지. 지금 너를 가장 잘 아는 건 나다.",
  ui_story_1015_10151402_139_dialog_content = "네가 하려는 일은 「놈들」과 다를 바 없다.",
  ui_story_1015_10151402_140_dialog_content = "헬리오스를 내게 맡겨라.\n대원수의 이름으로 그를 지키고, 그 누구도 건드리게 두지 않겠다.",
  ui_story_1015_10151402_141_dialog_content = "넌 못 해.",
  ui_story_1015_10151402_142_dialog_content = "협상은 결렬이야. 나도 여기서 더 시간 낭비할 이유는 없어.",
  ui_story_1015_10151402_143_dialog_content = "제이드.",
  ui_story_1015_10151402_144_dialog_content = "<anim type=Shake><size=50>캬아아악!</size></anim>",
  ui_story_1015_10151402_145_dialog_content = "「또 만나」.",
  ui_story_1015_10151402_146_dialog_content = "<color=#e8d9bb>콰아앙!!!</color>",
  ui_story_1015_10151501_1_dialog_content = "보고드립니다. 잉겔 중령과 아나톨리 소령의 정보를 토대로,\n폐기된 실험실에서 바이스 중위를 발견했습니다.",
  ui_story_1015_10151501_2_dialog_content = "바이스 중위, 복귀했습니다!",
  ui_story_1015_10151501_3_dialog_content = "바이스! 괜찮아? 다친 데는 없어?",
  ui_story_1015_10151501_4_dialog_content = "응! 괜찮아!",
  ui_story_1015_10151501_5_dialog_content = "미안해. 내가 방심해서 다들 고생하게 만들었네...",
  ui_story_1015_10151501_6_dialog_content = "무사히 돌아왔으니까 그걸로 됐어.",
  ui_story_1015_10151501_7_dialog_content = "그래, 너무 자책할 거 없어.",
  ui_story_1015_10151501_8_dialog_content = "노라는 교활한 녀석이니까, 힘을 합쳐서 함께 맞서야 해.",
  ui_story_1015_10151501_9_dialog_content = "네...",
  ui_story_1015_10151501_10_dialog_content = "수색 상황은? 노라의 행적은 찾아냈나?",
  ui_story_1015_10151501_11_dialog_content = "온 지하성을 수색했지만 노라의 행적은 찾지 못했습니다.",
  ui_story_1015_10151501_12_dialog_content = "각 출입구와 옛 지하성 통로 쪽은?",
  ui_story_1015_10151501_13_dialog_content = "전부 경비병을 배치했지만, 출입한 사람은 없었습니다.",
  ui_story_1015_10151501_14_dialog_content = "알겠다. 절대 방심하지 말고 수색을 계속해라.",
  ui_story_1015_10151501_15_dialog_content = "예!",
  ui_story_1015_10151501_16_dialog_content = "노라 녀석, 잘도 눈앞에서 사라져 버렸잖아.",
  ui_story_1015_10151501_17_dialog_content = "큰소리치더니 도망 하나는 빠르네.",
  ui_story_1015_10151501_18_dialog_content = "대원수님, 레이스 군단장님, 노라의 도주 경로로 짐작 가는 곳이 있습니다.",
  ui_story_1015_10151501_19_dialog_content = "음? 어디지?",
  ui_story_1015_10151501_20_dialog_content = "이 지하성은 노라가 설계하고 건설을 주도했습니다.",
  ui_story_1015_10151501_21_dialog_content = "노라는 지하성이 완공됐을 때부터 일루미나 연방을 떠날 때까지\n여러 차례 비밀리에 이 지하성과 자난성 사이를 오갔습니다.",
  ui_story_1015_10151501_22_dialog_content = "제가 파악한 그자는 무의미한 일에 시간을 쓰는 것을 결코 원하지 않는 사람입니다.",
  ui_story_1015_10151501_23_dialog_content = "따라서 전 노라가 이 지하성과 자난성을 빠르게 왕래할 수 있는\n비밀 통로를 만들었을 거라 생각합니다.",
  ui_story_1015_10151501_24_dialog_content = "그러니까 지금 노라가 자난성으로 향했을 가능성이 있다는 건가?",
  ui_story_1015_10151501_25_dialog_content = "네.",
  ui_story_1015_10151501_26_dialog_content = "음, 일리가 있어. 즉시 인원을 조직해 자난성을 수색하고, 이 건에 대해 조사하겠다.",
  ui_story_1015_10151501_27_dialog_content = "라인하르트, 그 일은 나한테 맡겨줘.",
  ui_story_1015_10151501_28_dialog_content = "안 돼. 이건 노라와 헬리오스에 대한 일이야. 내가 직접 나서야만 해.",
  ui_story_1015_10151501_29_dialog_content = "그래서 더 나서면 안 된다는 거야.",
  ui_story_1015_10151501_30_dialog_content = "애초에 이 임무는 위원회가 내게 맡긴 거였어.\n난 제1책임자로서 임무를 수행할 필요가 있어.",
  ui_story_1015_10151501_31_dialog_content = "게다가 지금 우리가 상대하는 건 네 예전 가족이자 전우야.",
  ui_story_1015_10151501_32_dialog_content = "아무리 내가 네 의지와 정의감을 믿는다 해도, 다른 모든 사람이 널 믿는다는 보장은 없어.",
  ui_story_1015_10151501_33_dialog_content = "지금 눈치 빠른 녀석이라면 모두가 알고 있어.\n「저들」은 최근 계속해서 네 과실을 찾아내려 하고 있다고.",
  ui_story_1015_10151501_34_dialog_content = "게다가 곧 연합 훈련이 시작될 거야.\n아스트라 대륙의 모든 세력이 일루미나를 주목하고 있어.",
  ui_story_1015_10151501_35_dialog_content = "지금 네가 해야 할 일은 자난성으로 돌아가는 거야.",
  ui_story_1015_10151501_36_dialog_content = "네가 돌아가면 상황을 진정시키고, 네 위신도 유지할 수 있어.",
  ui_story_1015_10151501_37_dialog_content = "게다가 네가 자난성에 있는 한, 노라가 정말 거기 있더라도 쉽게 움직이진 못할 거야.",
  ui_story_1015_10151501_38_dialog_content = "......",
  ui_story_1015_10151501_39_dialog_content = "날 못 믿겠다면 감시를 붙여도 전혀 상관없어.",
  ui_story_1015_10151501_40_dialog_content = "항상 말했듯이 난 정정당당하게 널 이길 거니까.",
  ui_story_1015_10151501_41_dialog_content = "옛날에도, 지금도, 앞으로도 그럴 거야.",
  ui_story_1015_10151501_42_dialog_content = "난 널 믿어.",
  ui_story_1015_10151501_43_dialog_content = "노라를 잡고 헬리오스를 데려오는 일은 네게 맡길게.",
  ui_story_1015_10151501_44_dialog_content = "걱정 마. 꼭 찾아낼 테니까.",
  ui_story_1015_10151501_45_dialog_content = "이렇게 된 이상, PlayerName 너희도 나와 함께 자난성으로 돌아가지.",
  ui_story_1015_10151501_46_dialog_content = "하지만 임무가...",
  ui_story_1015_10151501_47_dialog_content = "위원회가 이미 레이스 군단장에게 이 건을 맡긴 이상, 너희가 더 신경 쓸 필요는 없다.",
  ui_story_1015_10151501_48_dialog_content = "앞으로의 업무에 집중해라.",
  ui_story_1015_10151501_49_dialog_content = "네.",
  ui_story_1015_10151501_50_dialog_content = "예, 알겠습니다.",
  ui_story_1015_10151501_51_dialog_content = "<size=30>확실히 남은 일이 산더미긴 하군요... 대원수님을 도와 훈련 기간의 일정을 조정하고, 또...</size>",
  ui_story_1015_10151501_52_dialog_content = "아나톨리.",
  ui_story_1015_10151501_53_dialog_content = "<size=45>예!</size>",
  ui_story_1015_10151501_54_dialog_content = "명령하실 다른 일이 있으십니까, 대원수님?",
  ui_story_1015_10151501_55_dialog_content = "넌 날 따라다닐 필요는 없다. 훈련에 참가해라.",
  ui_story_1015_10151501_56_dialog_content = "예... 예?! 잠시만요, 대원수님.\n전 팀에 들어가지 않아서 훈련에는 참가할 수 없습니다.",
  ui_story_1015_10151501_57_dialog_content = "그건 걱정하지 않아도 된다.\n마침 팀원 한 명이 사정상 참가할 수 없게 된 팀이 있으니까.",
  ui_story_1015_10151501_58_dialog_content = "그 빈자리를 네가 채워라.",
  ui_story_1015_10151501_59_dialog_content = "예. 그런데 어느 팀입니까?",
  ui_story_1015_10151501_60_dialog_content = "너도 잘 알 거다. 잉겔 팀이다.",
  ui_story_1015_10151501_61_dialog_content = "네? 저희 팀이요?",
  ui_story_1015_10151501_62_dialog_content = "악셀리아에게 무슨 일이 있는 겁니까?",
  ui_story_1015_10151501_63_dialog_content = "아니, 악셀리아가 아니라 숀 쪽이다.",
  ui_story_1015_10151501_64_dialog_content = "나도 이제 막 더스크 타운에서 전해온 소식을 들었다.",
  ui_story_1015_10151501_65_dialog_content = "숀이 갑자기 몸 상태가 나빠져서, 더스크 타운에 남아 상황을 지켜봐야 할 것 같다더군.",
  ui_story_1015_10151501_66_dialog_content = "많이 안 좋은가요? 괜찮은 거죠?",
  ui_story_1015_10151501_67_dialog_content = "그쪽 사람들 말로는 숀이 루미나틱스를 사용할 때\n지금까진 한 번도 없었던 이상 현상이 발생했다고 한다.",
  ui_story_1015_10151501_68_dialog_content = "아마 숀의 유전자 결함과 관계가 있는 거겠지.",
  ui_story_1015_10151501_69_dialog_content = "그런가요...",
  ui_story_1015_10151501_70_dialog_content = "이번 일이 끝나면 더스크 타운으로 병문안을 가야겠어요.",
  ui_story_1015_10151501_71_dialog_content = "그럼 저와 잉겔 중령, 악셀리아가 한 팀이 되는 겁니까?",
  ui_story_1015_10151501_72_dialog_content = "명령에 따르겠습니다.",
  ui_story_1015_10151501_73_dialog_content = "(원래 계획과는 조금 어긋나 버렸습니다만, 괜찮습니다.\n아직은 대처 가능한 범위 안이니까요.)",
  ui_story_1015_10151501_74_dialog_content = "저도 다른 의견은 없습니다.",
  ui_story_1015_10151501_75_dialog_content = "그럼 그렇게 정한 것으로 하지.",
  ui_story_1015_10151501_76_dialog_content = "이제 자난성으로 돌아가자.",
  ui_story_1015_10151501_77_dialog_content = "<color=#e8d9bb>며칠 뒤, 자난성</color>",
  ui_story_1015_10151501_78_dialog_content = "「열차가 곧 자난성에 도착합니다. 하차하실 승객께서는 미리 준비해 주시기 바랍니다.\n열차와 승강장 사이가 넓으니, 내리실 때 조심하십시오.」",
  ui_story_1015_10151501_79_dialog_content = "「부디 여명의 빛이 여러분의 여정을 밝게 비추길 바라겠습니다.」",
  ui_story_1015_10151501_80_dialog_content = "실례합니다. 저희 좀 내리게 비켜주세요.",
  ui_story_1015_10151501_81_dialog_content = "사람이 정말 많네... 역시 아스트라 대륙 최대 규모의 군사 훈련이구나!",
  ui_story_1015_10151501_82_dialog_content = "그나저나 이렇게 넓은데 잘못 온 건 아니겠지? 이 역에서 내리는 게 맞나?",
  ui_story_1015_10151501_83_dialog_content = "카렌 전하의 지시에 따르면 이 역에서 내리는 게 맞아요.",
  ui_story_1015_10151501_84_dialog_content = "길을 잃지 않았으면 좋겠는데요...",
  ui_story_1015_10151501_85_dialog_content = "베르타.",
  ui_story_1015_10151501_86_dialog_content = "카렌 님!",
  ui_story_1015_10151501_87_dialog_content = "약속대로 데리러 왔어.",
  ui_story_1015_10151501_88_dialog_content = "감사합니다! 전하께서 없으셨다면 분명히 길을 잃었을 거예요...",
  ui_story_1015_10151501_89_dialog_content = "천만에. 훈련에 몇 번 더 참가하고 나면 이곳도 익숙해질 거야.",
  ui_story_1015_10151501_90_dialog_content = "그럼 가자.",
  ui_story_1015_10151501_91_dialog_content = "네, 카렌 님!",
  ui_story_1015_10151501_92_dialog_content = "방금 지나간 사람, 그 공주님 아닙니까?",
  ui_story_1015_10151501_93_dialog_content = "아, 그런 것 같네.",
  ui_story_1015_10151501_94_dialog_content = "인사하러 안 가십니까?",
  ui_story_1015_10151501_95_dialog_content = "하하하, 일단은 됐어.",
  ui_story_1015_10151501_96_dialog_content = "사람도 많은데 방해하면 안 되지.",
  ui_story_1015_10151501_97_dialog_content = "연합 훈련이 정식으로 시작될 때까지 인사하고 회포 풀 시간 정도는 얼마든지 있잖아.",
  ui_story_1015_10151501_98_dialog_content = "그것도 그렇네요.",
  ui_story_1015_10151501_99_dialog_content = "게다가 우리 새로운 동료도 임무가 있는 상황이니...",
  ui_story_1015_10151501_100_dialog_content = "실례합니다, 지나가겠습니다.",
  ui_story_1015_10151501_101_dialog_content = "크로우, 차 문에 부딪히지 않게 이쪽으로 오세요.",
  ui_story_1015_10151501_102_dialog_content = "알겠어.",
  ui_story_1015_10151501_103_dialog_content = "정말 미안하게 됐어요...",
  ui_story_1015_10151501_104_dialog_content = "제가 받은 임무인데도 당신 도움을 받게 되어 버렸네요.",
  ui_story_1015_10151501_105_dialog_content = "난 네 경호원이야. 널 돕고 지키는 건 내 임무야.",
  ui_story_1015_10151501_106_dialog_content = "게다가 내가 안 도와줬으면 너 혼자서는 이걸 자난성까지 못 가져왔을 거야.",
  ui_story_1015_10151501_107_dialog_content = "어쩔 수 없네요. 전 체력이 필요한 일엔 능숙하지 못하니까요.",
  ui_story_1015_10151501_108_dialog_content = "도움이 필요한가? 일루미나 참모장.",
  ui_story_1015_10151501_109_dialog_content = "괜찮습니다. 곧 목적지에 도착하니까요.",
  ui_story_1015_10151501_110_dialog_content = "도움이 필요하면 제가 먼저 말씀드리죠.",
  ui_story_1015_10151501_111_dialog_content = "그럼 됐어. 지금까지 협력한 적 없었다고 어색하게 굴 필요는 없으니까.",
  ui_story_1015_10151501_112_dialog_content = "나중에 강철가시 기사단에 들어오고 싶다고 해도 난 반대 안 해.",
  ui_story_1015_10151501_113_dialog_content = "농담도 잘하시네요.",
  ui_story_1015_10151501_114_dialog_content = "괜찮으시다면 두 분은 먼저 가서 수속을 밟아 주세요.",
  ui_story_1015_10151501_115_dialog_content = "전 먼저 크로우와 「그녀」를 의뢰인에게 전달해야 갈 수 있거든요.",
  ui_story_1015_10151501_116_dialog_content = "좋아, 그럼 먼저 갈게.",
  ui_story_1015_10151501_117_dialog_content = "잠시 후에 뵙겠습니다, 자오 참모장님.",
  ui_story_1015_10151501_118_dialog_content = "......",
  ui_story_1015_10151501_119_dialog_content = "크로우, 왜 그러죠?",
  ui_story_1015_10151501_120_dialog_content = "..........",
  ui_story_1015_10151501_121_dialog_content = "혹시 제가 왜 당신이 아니라 저들과 한 팀이 된 건지 또 묻고 싶은 건가요?",
  ui_story_1015_10151501_122_dialog_content = "나라면 널 더 잘 지킬 수 있어. 하지만 저들은 못 해.",
  ui_story_1015_10151501_123_dialog_content = "그건 알고 있어요.",
  ui_story_1015_10151501_124_dialog_content = "하지만 이건 더스크 타운이 공동으로 내린 결정이에요.",
  ui_story_1015_10151501_125_dialog_content = "나도 더스크 타운의 일원이야.",
  ui_story_1015_10151501_126_dialog_content = "알고 있어요. 하지만 이번엔 달라요.",
  ui_story_1015_10151501_127_dialog_content = "강철가시 기사단, 그리고 빛의 신 교회와의 이번 협력은 외부 세계에\n더스크 타운의 힘과 단결을 보여주기 위해서예요.",
  ui_story_1015_10151501_128_dialog_content = "그래야 훈련에서 좋은 성적을 거두었을 때, 충분한 발언권과 수단으로\n각 세력에 압력을 넣을 수 있을 테니까요.",
  ui_story_1015_10151501_129_dialog_content = "다들 더스크 타운을 그렇게 싫어하는 거야?",
  ui_story_1015_10151501_130_dialog_content = "아니요, 싫어하는 게 아니에요.",
  ui_story_1015_10151501_131_dialog_content = "관심이 없을 뿐이죠.",
  ui_story_1015_10151501_132_dialog_content = "하지만 우린 달라요. 더스크 타운은 우리의 터전이에요.\n마을이 암귀의 파도에 휩쓸리는 걸 가만히 보고만 있을 순 없어요.",
  ui_story_1015_10151501_133_dialog_content = "그러니 우린 반드시 이겨야 해요.\n저들이 우릴 의식하고, 더스크 타운에 지원군을 보내도록 말이에요.",
  ui_story_1015_10151501_134_dialog_content = "......",
  ui_story_1015_10151501_135_dialog_content = "네 말대로 할게.",
  ui_story_1015_10151501_136_dialog_content = "이해해 줘서 고마워요.",
  ui_story_1015_10151501_137_dialog_content = "자, 그럼 어서 「그녀」를 건네주러 가죠.",
  ui_story_1015_10151501_138_dialog_content = "쟤들이 타깃이야?",
  ui_story_1015_10151501_139_dialog_content = "하나도 재미없을 것 같잖아. 내 꿈속의 곰돌이 인형이 훨씬 더 재미있겠어.",
  ui_story_1015_10151501_140_dialog_content = "그렇게 서둘러 결론을 내려서는 안 됩니다.",
  ui_story_1015_10151501_141_dialog_content = "「그분」께서 주신 임무는 저들을 관찰하는 것입니다.\n우린 충실히 본분을 다해야 합니다.",
  ui_story_1015_10151501_142_dialog_content = "「그분」의 직관이 빗나간 적은 없습니다. 저들은 분명히 무언가를 숨기고 있을 겁니다.",
  ui_story_1015_10151501_143_dialog_content = "동물 안 싫어했으면 좋겠는데...",
  ui_story_1015_10151501_144_dialog_content = "여기까지가 현재 상황입니다.",
  ui_story_1015_10151501_145_dialog_content = "대원수는 이미 자난성으로 돌아왔습니다.\n노라와 목표 실험체의 행방은 알 수 없으나, 자난성 어딘가에 있을 가능성이 높습니다.",
  ui_story_1015_10151501_146_dialog_content = "또한 각 세력도 이미 자난성에 집결했습니다. 연합 훈련이 이제 곧 시작될 겁니다.",
  ui_story_1015_10151501_147_dialog_content = "다만 더스크 타운이 일루미나와 백야성 연합 팀을 파견한 건 예상 밖이었습니다.",
  ui_story_1015_10151501_148_dialog_content = "저도 멤버를 찾아 팀을 편성하고 저들을 견제할 필요는 없겠습니까?",
  ui_story_1015_10151501_149_dialog_content = "확실히 주의할 필요는 있겠지. 하지만 그리 경계할 것까진 없네.",
  ui_story_1015_10151501_150_dialog_content = "잉겔과 악셀리아는 신뢰할 수 있는 병사들일세.",
  ui_story_1015_10151501_151_dialog_content = "그리고 자넨 다른 할 일이 있네.",
  ui_story_1015_10151501_152_dialog_content = "예.",
  ui_story_1015_10151501_153_dialog_content = "<color=#e8d9bb>같은 시간, 자난성 어딘가</color>",
  ui_story_1015_10151501_154_dialog_content = "<anim type=Shake><size=45>끼이익...</size></anim>",
  ui_story_1015_10151501_155_dialog_content = "여기다 놔.",
  ui_story_1015_10151501_156_dialog_content = "<anim type=Shake><size=45>끼긱!</size></anim>",
  ui_story_1015_10151501_157_dialog_content = "<anim type=Shake>그르렁──</anim>",
  ui_story_1015_10151501_158_dialog_content = "잘했어.",
  ui_story_1015_10151501_159_dialog_content = "원래 모습으로 돌아가. 그리고 이 통로를 타고 이 지하성을 떠나.",
  ui_story_1015_10151501_160_dialog_content = "<anim type=Shake><size=45>끽?!</size></anim>",
  ui_story_1015_10151501_161_dialog_content = "<anim type=Shake><size=45>끼긱── 끼긱──!</size></anim>",
  ui_story_1015_10151501_162_dialog_content = "여긴 이제 네가 할 수 있는 일이 없어.",
  ui_story_1015_10151501_163_dialog_content = "이대로 남아 있어도 발목만 잡힐 뿐이야.",
  ui_story_1015_10151501_164_dialog_content = "있던 곳으로 돌아가서 내가 돌아갈 때까지 기다려.",
  ui_story_1015_10151501_165_dialog_content = "<anim type=Shake>그르르...</anim>",
  ui_story_1015_10151501_166_dialog_content = "끽──!",
  ui_story_1015_10151501_167_dialog_content = "드니에르...?",
  ui_story_1015_10151501_168_dialog_content = "......",
  ui_story_1015_10151501_169_dialog_content = "일어났구나.",
  ui_story_1015_10151501_170_dialog_content = "그래...",
  ui_story_1015_10151501_171_dialog_content = "날... 어디로... 데려온 거지?",
  ui_story_1015_10151501_172_dialog_content = "인지능력이 조금씩 회복되고 있는 건가?",
  ui_story_1015_10151501_173_dialog_content = "실험이 성공했다는 뜻이지만, 타이밍이 안 좋네.",
  ui_story_1015_10151501_174_dialog_content = "무슨 소리야...? 무슨 뜻인지 모르겠어...",
  ui_story_1015_10151501_175_dialog_content = "아무것도 아니야.",
  ui_story_1015_10151501_176_dialog_content = "여긴... 어디지? 아직 대답 안 했잖아...",
  ui_story_1015_10151501_177_dialog_content = "......",
  ui_story_1015_10151501_178_dialog_content = "자난성이야.",
  ui_story_1015_10151501_179_dialog_content = "우리... 돌아온 건가?",
  ui_story_1015_10151501_180_dialog_content = "그래.",
  ui_story_1015_10151501_181_dialog_content = "다시 돌아온 거야.",
  ui_story_1016_10160101_1_dialog_content = "<color=#e8d9bb>치이익──</color>",
  ui_story_1016_10160101_2_dialog_content = "<color=#e8d9bb>덜컹덜컹──</color>",
  ui_story_1016_10160101_3_dialog_content = "「연합 훈련에 참가하는 후보생 여러분.」",
  ui_story_1016_10160101_4_dialog_content = "「열차가 역에 도착했습니다. 신속하게 하차해 주십시오.」",
  ui_story_1016_10160101_5_dialog_content = "「승강장에서 잠시 휴식을 취한 후, 후속 일정을 대기해 주시기 바랍니다.」",
  ui_story_1016_10160101_6_dialog_content = "우와! 기차 타보는 건 처음이었는데!",
  ui_story_1016_10160101_7_dialog_content = "속도가 너무 빨라요, 마차보다 훨씬...",
  ui_story_1016_10160101_8_dialog_content = "전 흔들림에 익숙하지 않아서요. 역시 차에서 내리고 나니 안심이 되네요.",
  ui_story_1016_10160101_9_dialog_content = "그럼 우리 훈련장에 도착한 거지? 그럼 이제 뭘 해야 하는데?",
  ui_story_1016_10160101_10_dialog_content = "여기서 조금만 기다리면 됩니다. 이제 곧 관계자가 와서 일정을 안내할 겁니다.",
  ui_story_1016_10160101_11_dialog_content = "아나톨리! 오랜만이네요!",
  ui_story_1016_10160101_12_dialog_content = "당신도 연합 훈련에 참가하는 건가요?",
  ui_story_1016_10160101_13_dialog_content = "물론이죠. 여기 서 있는 모두가 이번 연합 훈련에 참가할 후보생들입니다.",
  ui_story_1016_10160101_14_dialog_content = "그랬군요, 꽤 시끌벅적하네요.",
  ui_story_1016_10160101_15_dialog_content = "이번엔 우리가 당신들 구역에 왔으니까, 자기네 편 많다고 남 괴롭히지 마요.",
  ui_story_1016_10160101_16_dialog_content = "그건 당신들 백야성의 습관 아닙니까? 여기선 그런 걱정 안 해도 됩니다.",
  ui_story_1016_10160101_17_dialog_content = "흥.",
  ui_story_1016_10160101_18_dialog_content = "미안한데 다들 좀 비켜줘요. 「깨지기 쉬운 물건」을 운반하고 있거든요.",
  ui_story_1016_10160101_19_dialog_content = "조심... 부딪히지 않게 조심해요.",
  ui_story_1016_10160101_20_dialog_content = "자오, 이걸 어디 갖다줘야 하는데?",
  ui_story_1016_10160101_21_dialog_content = "원래라면 접선자가 여기서 우리와 만나기로 했습니다만...",
  ui_story_1016_10160101_22_dialog_content = "두 사람 모두 고생했습니다, 저한테 주세요.",
  ui_story_1016_10160101_23_dialog_content = "당신들 임무는 끝났습니다.",
  ui_story_1016_10160101_24_dialog_content = "잉겔 중령, 접선자가 당신이었군요.",
  ui_story_1016_10160101_25_dialog_content = "이상한가요?",
  ui_story_1016_10160101_26_dialog_content = "당신이 연합 훈련에 참가한다는 건 확실히 좀 이상하네요.",
  ui_story_1016_10160101_27_dialog_content = "전 당신이 모습을 잘 드러내지 않는 타입인 줄 알았거든요.",
  ui_story_1016_10160101_28_dialog_content = "절 높게 평가하셨네요.",
  ui_story_1016_10160101_29_dialog_content = "가져가세요. 어렵게 가져온 아이니까요.",
  ui_story_1016_10160101_30_dialog_content = "문제가 있는지 확인해 보세요.",
  ui_story_1016_10160101_31_dialog_content = "네.",
  ui_story_1016_10160101_32_dialog_content = "<color=#e8d9bb>똑똑.</color>",
  ui_story_1016_10160101_33_dialog_content = "악셀리아, 이제 일어나야 합니다.",
  ui_story_1016_10160101_34_dialog_content = "<color=#e8d9bb>치이익──</color>",
  ui_story_1016_10160101_35_dialog_content = "하──아암.",
  ui_story_1016_10160101_36_dialog_content = "잉겔, 좋은 아침입니다.",
  ui_story_1016_10160101_37_dialog_content = "잘 잤나요?",
  ui_story_1016_10160101_38_dialog_content = "네, 아주 활기차요.",
  ui_story_1016_10160101_39_dialog_content = "휴, 답답해 죽는 줄 알았네.",
  ui_story_1016_10160101_40_dialog_content = "난 저런 꽉 막히고 후덥지근한 공간은 정말 참을 수가 없다고.",
  ui_story_1016_10160101_41_dialog_content = "레오 단장, 땀을 많이 흘렸군요.",
  ui_story_1016_10160101_42_dialog_content = "그래, 전투에 나가는 것보다 더 힘든 것 같다니까.",
  ui_story_1016_10160101_43_dialog_content = "너무 과장된 거 아닙니까? 그냥 교통수단을 한번 이용했을 뿐입니다만.",
  ui_story_1016_10160101_44_dialog_content = "우린 어떤 위험도 겪지 않았습니다.",
  ui_story_1016_10160101_45_dialog_content = "그러니까 이건 애초에 위험이 있느냐 없느냐의 문제가 아니라고...",
  ui_story_1016_10160101_46_dialog_content = "티슈 필요해?",
  ui_story_1016_10160101_47_dialog_content = "고맙습니다... 어? 카렌 전하?!",
  ui_story_1016_10160101_48_dialog_content = "기계에 익숙해지지 못하는 백야성 사람은 많아, 난 이해할 수 있어.",
  ui_story_1016_10160101_49_dialog_content = "그렇습니다. 다른 사람들도 전하처럼 이해심이 많았으면 좋겠군요.",
  ui_story_1016_10160101_50_dialog_content = "그나저나 여기서 뵙게 되다니 이거 참 의외로군요.",
  ui_story_1016_10160101_51_dialog_content = "우리가 다시 만나게 될 곳은 백야성일 줄 알았습니다만.",
  ui_story_1016_10160101_52_dialog_content = "우리가 백야성에서 만났다면 신분 관계가 무척 복잡해질 거야.\n하지만 여기서는 우리 모두 후보생일 뿐이지.",
  ui_story_1016_10160101_53_dialog_content = "하하하하, 그것도 그렇군요.",
  ui_story_1016_10160101_54_dialog_content = "오랫동안 복잡한 생활을 하면 가끔은 단순한 걸 동경하게 되죠.",
  ui_story_1016_10160101_55_dialog_content = "레오 씨, 요제프 씨! 두 사람도 연합 훈련에 참가하러 온 거야?",
  ui_story_1016_10160101_56_dialog_content = "더스크 타운에서 여기까진 엄청 멀잖아!",
  ui_story_1016_10160101_57_dialog_content = "PlayerName! 네가 왜 여기 있어?",
  ui_story_1016_10160101_58_dialog_content = "연합 훈련에 초대받아서 카렌이랑 바이스랑 같이 왔어.",
  ui_story_1016_10160101_59_dialog_content = "그랬군. 이럴 줄 알았으면 애초에 네 콜로서스에 얻어탔을 텐데 말이야.",
  ui_story_1016_10160101_60_dialog_content = "아하하, 콜로서스 타고 싶으면 언제든지 환영이야!",
  ui_story_1016_10160101_61_dialog_content = "휴, 휴우...! 후보생 여러분! 조용히 이쪽으로 모여주세요.",
  ui_story_1016_10160101_62_dialog_content = "지금부터 연합 훈련의 제반 사항을 발표하겠습니다.",
  ui_story_1016_10160101_63_dialog_content = "이거 비비안 씨 목소리야?",
  ui_story_1016_10160101_64_dialog_content = "응! 얼른 가자!",
  ui_story_1016_10160101_65_dialog_content = "바이스, 조심해. 여긴 사람이 너무 많아.",
  ui_story_1016_10160101_66_dialog_content = "에이, 그렇게 걱정할 거 없어. 이번 일로 다친 것도 아닌데 뭐.",
  ui_story_1016_10160101_67_dialog_content = "병원 검사 결과도 나왔잖아, 나 아주 멀쩡해!",
  ui_story_1016_10160101_68_dialog_content = "그래도 좀...",
  ui_story_1016_10160101_69_dialog_content = "가자, 가자!",
  ui_story_1016_10160101_70_dialog_content = "연합 훈련에 참가하기 위해 자난성에 오신 후보생 여러분을 환영합니다.",
  ui_story_1016_10160101_71_dialog_content = "저는 일루미나 연방 참모장이자, 이번 훈련의 안내를 맡은 비비안이에요.",
  ui_story_1016_10160101_72_dialog_content = "일루미나는 효율을 중시하기 때문에 불필요한 허례허식은 없답니다.",
  ui_story_1016_10160101_73_dialog_content = "제가 규칙을 소개하고 나면, 이번 연합 훈련이 정식으로 시작될 거예요.",
  ui_story_1016_10160101_74_dialog_content = "와, 절차가 그렇게 깔끔하다고?",
  ui_story_1016_10160101_75_dialog_content = "그거 좋네. 지루한 정치 연설을 들을 필요도 없고 말이야.",
  ui_story_1016_10160101_76_dialog_content = "여러분도 잘 알고 있겠죠.\n연합 훈련의 취지는 청년 세대의 전쟁 대비 능력을 향상시키는 데 있어요.",
  ui_story_1016_10160101_77_dialog_content = "이곳에 초청된 후보생들은 모두 10대, 20대의 젊은 세대들이에요.",
  ui_story_1016_10160101_78_dialog_content = "여러분은 이제 막 재능을 드러낸 장교거나, 아직 상아탑에서 나오지 못한 학생이겠죠.",
  ui_story_1016_10160101_79_dialog_content = "나이와 경험의 차이가 얼마나 크든지, 여러분은 앞으로 같은 전장에서 함께 싸우게 될 거예요.",
  ui_story_1016_10160101_80_dialog_content = "이를 위해서는 배우고, 협력하고, 경쟁하며, 자신의 전투 능력을 최대한 연마해야 해요.",
  ui_story_1016_10160101_81_dialog_content = "연합 훈련은 후보생 여러분을 위해 준비된 무대예요.\n그리고 이 훈련은 교육과 심사 두 개의 단계로 진행될 거예요.",
  ui_story_1016_10160101_82_dialog_content = "교육 단계에서 여러분에게는 일루미나 연방 최고의 자원이 제공될 거예요.\n선배들의 힘을 빌려 자신을 더 높은 경지로 향상시키세요.",
  ui_story_1016_10160101_83_dialog_content = "그리고 심사 단계에서는 서로와의 경쟁을 통해 마지막 한 팀을 선출할 거예요.",
  ui_story_1016_10160101_84_dialog_content = "아마 많은 분들이 알고 계시겠죠.\n전통에 따라 훈련 심사의 우승자는 특별한 상을 받게 되는데요.",
  ui_story_1016_10160101_85_dialog_content = "바로 대원수와 대련할 수 있는 기회랍니다.",
  ui_story_1016_10160101_86_dialog_content = "세상에, 대원수와 대련이라니... 생각만 해도 무섭잖아.",
  ui_story_1016_10160101_87_dialog_content = "하지만 연합 훈련에서 우승할 수 있는 후보생들도 무서운 녀석들이잖아.",
  ui_story_1016_10160101_88_dialog_content = "맞아 맞아, 저번엔 무려 그 백야성의 공주였다고...",
  ui_story_1016_10160101_89_dialog_content = "자, 기본적인 소개는 여기까지예요.",
  ui_story_1016_10160101_90_dialog_content = "조수, 깃발 좀 올려주세요.",
  ui_story_1016_10160101_91_dialog_content = "<color=#e8d9bb>휘리릭──</color>",
  ui_story_1016_10160101_92_dialog_content = "우와! 엄청 긴 깃발이네!",
  ui_story_1016_10160101_93_dialog_content = "저건 「<color=#FFB400>우승기</color>」예요.",
  ui_story_1016_10160101_94_dialog_content = "연합 훈련에서 우승한 승자는 자기 진영의 깃발을 게양할 자격이 주어져요.",
  ui_story_1016_10160101_95_dialog_content = "훈련이 한 번 개최될 때마다 깃발이 조금씩 길어졌고, 점차 지금의 모습이 된 거예요.",
  ui_story_1016_10160101_96_dialog_content = "여러분은 여러 진영의 깃발을 볼 수 있을 거예요.",
  ui_story_1016_10160101_97_dialog_content = "뭇별들이 사방에서 떠올라 우리가 우러러보는 하늘 위에 모였어요.",
  ui_story_1016_10160101_98_dialog_content = "저 깃발은 연합 훈련의 상징이자, 대대로 전쟁을 이겨내겠다는 의지를 증명하고 있어요.",
  ui_story_1016_10160101_99_dialog_content = "(!!!)",
  ui_story_1016_10160101_100_dialog_content = "(내가 잘못 본 거 아니지? 저기 아이테르의 깃발이 있잖아...)",
  ui_story_1016_10160101_101_dialog_content = "자, 여러분, 그럼 이제 선포하겠습니다.",
  ui_story_1016_10160101_102_dialog_content = "지금부터 연합 훈련을 정식으로 개시합니다.",
  ui_story_1016_10160101_103_dialog_content = "<color=#e8d9bb>짝짝짝짝짝...</color>",
  ui_story_1016_10160101_104_dialog_content = "이어서 후보생 등록을 진행할게요.",
  ui_story_1016_10160101_105_dialog_content = "여러분의 초청장에는 각자 속한 팀이 기록되어 있을 거예요.",
  ui_story_1016_10160101_106_dialog_content = "한 팀은 3명의 후보생을 포함하고, 팀은 훈련 중 모든 단체 행동의 기본 단위예요.",
  ui_story_1016_10160101_107_dialog_content = "팀의 대장이 속한 진영은 그 팀을 대표하는 진영이에요.",
  ui_story_1016_10160101_108_dialog_content = "그럼 팀을 확인하고 자기 팀 멤버를 찾아보세요.",
  ui_story_1016_10160101_109_dialog_content = "나랑 같은 팀은 바이스랑 카렌 맞지?",
  ui_story_1016_10160101_110_dialog_content = "당연하지, 우리가 진작에 확인했잖아.",
  ui_story_1016_10160101_111_dialog_content = "초청장에 네 이름이 쓰여 있으니까, 넌 우리의 대장이 되어야 해.",
  ui_story_1016_10160101_112_dialog_content = "에이, 대장은 무슨...",
  ui_story_1016_10160101_113_dialog_content = "팀을 확인한 후보생은 저한테 와서 등록할 수 있어요.",
  ui_story_1016_10160101_114_dialog_content = "팀 편성이 끝나고 나면 절 따라 숙소로 이동할 거예요.\n짐을 풀고 나면 허용된 범위 내에서는 자유롭게 활동할 수 있어요.",
  ui_story_1016_10160101_115_dialog_content = "여러분의 첫 수업은 내일부터 시작될 거예요.",
  ui_story_1016_10160101_116_dialog_content = "너무 신나!",
  ui_story_1016_10160101_117_dialog_content = "어릴 때부터 연합 훈련은 들어봤지만 직접 참여하는 건 처음이거든.",
  ui_story_1016_10160101_118_dialog_content = "카렌, 지난번에 참가했을 땐 기분이 어땠어?",
  ui_story_1016_10160101_119_dialog_content = "지금 너와 비슷해.",
  ui_story_1016_10160101_120_dialog_content = "흥분되고, 의욕이 넘치지만, 마음속으로는 자신이 없었어.",
  ui_story_1016_10160101_121_dialog_content = "자신이 없는데 우승을 했어?",
  ui_story_1016_10160101_122_dialog_content = "역시 우등생의 능력은 참 부럽구나~",
  ui_story_1016_10160101_123_dialog_content = "아, 아니야! 자랑하려는 뜻은 아니었어!",
  ui_story_1016_10160101_124_dialog_content = "에헷, 나도 그냥 놀린 거야!",
  ui_story_1016_10160101_125_dialog_content = "PlayerName 넌 어떻게 생각해? 한참 동안 아무 말도 안 하더니.",
  ui_story_1016_10160101_126_dialog_content = "이런 팽팽한 분위기가 안 익숙해서 그래?",
  ui_story_1016_10160101_127_dialog_content = "...후보생들 중에 우리랑 친구인 사람들이 꽤 많구나 생각 중이었어.",
  ui_story_1016_10160101_128_dialog_content = "친구들과 서로 경쟁할 마음의 준비는 아직 안 됐는데 말이야.",
  ui_story_1016_10160101_129_dialog_content = "응, 네 성격이라면 경쟁을 싫어할 거라 생각해.",
  ui_story_1016_10160101_130_dialog_content = "괜찮아. 우린 공부에 중점을 두면 돼. 경쟁의식이 그렇게 심할 필요는 없어.",
  ui_story_1016_10160101_131_dialog_content = "하지만 난 이번엔 이기고 싶어...",
  ui_story_1016_10160101_132_dialog_content = "어?",
  ui_story_1016_10160101_133_dialog_content = "오늘 「우승기」에서 아이테르의 깃발을 봤거든.",
  ui_story_1016_10160101_134_dialog_content = "일족의 흔적을 볼 수 있어서 정말 기뻤지만...",
  ui_story_1016_10160101_135_dialog_content = "최근의 깃발과는 한참 떨어져 있는 걸 보니까 마음이 안 좋았어.",
  ui_story_1016_10160101_136_dialog_content = "아이테르는 이미 그렇게 오랜 시간 동안 경기장에 나타나지 않았던 거잖아...",
  ui_story_1016_10160101_137_dialog_content = "난 아이테르의 영광을 담은 깃발이 골동품으로 저곳에 남진 않았으면 좋겠어.",
  ui_story_1016_10160101_138_dialog_content = "새 깃발을 걸어주고 싶어.",
  ui_story_1016_10160101_139_dialog_content = "잘 들어, 우린 백야성에서 온 팀이야.",
  ui_story_1016_10160101_140_dialog_content = "그리고 우리의 성과는 곧 백야성의 교육 성과를 반영하게 될 거야.",
  ui_story_1016_10160101_141_dialog_content = "그러니까 여명 아카데미를 부끄럽게 만들면 안 돼.",
  ui_story_1016_10160101_142_dialog_content = "대장님, 시작부터 설교인 건가요?",
  ui_story_1016_10160101_143_dialog_content = "이, 이건 설교가 아냐!",
  ui_story_1016_10160101_144_dialog_content = "난 그저 다들 정신 차리고 열심히 해야겠다는 생각이 들어서...",
  ui_story_1016_10160101_145_dialog_content = "맞아요, 연합 훈련에 참여한 후보생들은 모두 실력이 뛰어난 사람들이에요.",
  ui_story_1016_10160101_146_dialog_content = "정신 바짝 차려야 뒤처지지 않을 거예요.",
  ui_story_1016_10160101_147_dialog_content = "참, 다른 팀 중에 인상 깊은 팀이 있었나요?",
  ui_story_1016_10160101_148_dialog_content = "전 PlayerName 님의 팀만 기억이 나네요.",
  ui_story_1016_10160101_149_dialog_content = "아이테르의 특수 능력에 카렌 전하와 바이스 양의 힘을 합친다면,\n상당한 경쟁력을 지니게 될 거예요.",
  ui_story_1016_10160101_150_dialog_content = "네, 카렌 전하는 지난번 우승자니까 이번엔 타이틀 방어전에 나설지도 몰라요.",
  ui_story_1016_10160101_151_dialog_content = "PlayerName 팀 외에도 두 팀 정도가 주목할 만했어.",
  ui_story_1016_10160101_152_dialog_content = "하나는 레오 단장의 팀인데, 세 멤버 모두 더스크 타운에서 왔어.",
  ui_story_1016_10160101_153_dialog_content = "전에 임무를 수행할 때 더스크 타운 사람들의 전투 방식을 본 적 있어.",
  ui_story_1016_10160101_154_dialog_content = "저 팀은 다른 어떤 팀과도 비교할 수 없을 정도로 많은 실전 경험을 갖고 있어.",
  ui_story_1016_10160101_155_dialog_content = "실전 경험은 확실히 중요하죠...",
  ui_story_1016_10160101_156_dialog_content = "비슷한 나이라도 엄청난 격차를 만드니까요.",
  ui_story_1016_10160101_157_dialog_content = "그리고 잉겔이 이끄는 팀이 있는데, 멤버는 악셀리아와 아나톨리야.",
  ui_story_1016_10160101_158_dialog_content = "저 세 사람은 모두 일루미나의 젊은 세대 중 가장 뛰어난 전사들이야.",
  ui_story_1016_10160101_159_dialog_content = "일루미나의 강력한 과학 기술이 저들을 뒷받침하고 있어서 실력을 헤아리기 힘들어.",
  ui_story_1016_10160101_160_dialog_content = "음... 과학과 관련이 있다면 왠지 우리가 싫어할 만한 것이겠네요.",
  ui_story_1016_10160101_161_dialog_content = "저도 그렇게 생각해요. 그들과는 싸우고 싶지 않아요.",
  ui_story_1016_10160101_162_dialog_content = "이번엔 손님으로 자난성에 온 이상, 일루미나의 방식을 받아들일 수밖에 없어.",
  ui_story_1016_10160101_163_dialog_content = "그냥 실전 훈련 한 번 한다고 생각하자.",
  ui_story_1016_10160101_164_dialog_content = "그렇다곤 해도 받아들이는 건 역시 쉽지 않네요.",
  ui_story_1016_10160101_165_dialog_content = "대장도 한참을 돌아다니고 있지만, 아직 자난성의 지형을 못 받아들이는 것처럼요.",
  ui_story_1016_10160101_166_dialog_content = "가, 갑자기 왜 내 얘기가 나와?!",
  ui_story_1016_10160101_167_dialog_content = "숙소로 돌아가고 싶거든요. 대장, 언제쯤 맞는 길로 갈 수 있을까요?",
  ui_story_1016_10160101_168_dialog_content = "거의 다 왔어! 이번엔 진짜야!",
  ui_story_1016_10160101_169_dialog_content = "여기서 오른쪽으로 돌면...",
  ui_story_1016_10160101_170_dialog_content = "<color=#e8d9bb>쿵!</color>",
  ui_story_1016_10160101_171_dialog_content = "<size=45>으앗!</size>",
  ui_story_1016_10160101_172_dialog_content = "으으...",
  ui_story_1016_10160101_173_dialog_content = "미, 미안해요! 앞을 못 봐서 부딪혔네요!",
  ui_story_1016_10160101_174_dialog_content = "괜찮아요?",
  ui_story_1016_10160101_175_dialog_content = "괜찮습니다. 전 남에게 자주 부딪치곤 합니다. 신경 쓰지 마십시오.",
  ui_story_1016_10160101_176_dialog_content = "지팡이 좀 집어주시겠습니까? 어디에 떨어트렸는지 모르겠습니다.",
  ui_story_1016_10160101_177_dialog_content = "여기 지팡이요.",
  ui_story_1016_10160101_178_dialog_content = "실례지만... 눈이 불편하신가요?",
  ui_story_1016_10160101_179_dialog_content = "부끄러운 모습을 보이고 말았군요.",
  ui_story_1016_10160101_180_dialog_content = "으앗, 미안해요! 부딪힌 제가 잘못한 거예요!",
  ui_story_1016_10160101_181_dialog_content = "어디로 가시죠? 저희가 안내해 드릴게요!",
  ui_story_1016_10160101_182_dialog_content = "괜찮습니다. 전 지금 사람을 찾고 있는 중입니다.\n인형 옷을 입은 키 작은 소녀인데, 혹시 보셨습니까?",
  ui_story_1016_10160101_183_dialog_content = "아니요...",
  ui_story_1016_10160101_184_dialog_content = "그렇군요. 그럼 제가 직접 찾도록 하겠습니다.",
  ui_story_1016_10160101_185_dialog_content = "참, 저도 여러분과 마찬가지로 훈련에 참가합니다.",
  ui_story_1016_10160101_186_dialog_content = "네?",
  ui_story_1016_10160101_187_dialog_content = "디시스라고 합니다. 그럼 수업 때 잘 부탁드리겠습니다.",
  ui_story_1016_10160101_188_dialog_content = "이번 계획에서 중요한 건 눈에 띄는 거야. 알고 있겠지?",
  ui_story_1016_10160101_189_dialog_content = "우리한테 전쟁 소꿉놀이 같은 건 의미 없어. 더 중요한 건 어떻게 목소리를 내느냐지.",
  ui_story_1016_10160101_190_dialog_content = "우린 반드시 더스크 타운에 곧 일어날 재난을 온 세계가 확실히 알게 만들어야 해.",
  ui_story_1016_10160101_191_dialog_content = "당신이 뭘 노리는지 알겠군요.",
  ui_story_1016_10160101_192_dialog_content = "똑똑한 머리 자랑 하나는 잘하네. 말해 봐.",
  ui_story_1016_10160101_193_dialog_content = "대원수와의 대결이 목표겠죠.",
  ui_story_1016_10160101_194_dialog_content = "하하하, 맞아! 라인하르트를 이기는 것보다 더 큰 뉴스가 어디 있겠어?",
  ui_story_1016_10160101_195_dialog_content = "욕심도 참 많네요.",
  ui_story_1016_10160101_196_dialog_content = "내가 날 너무 과대평가하는 것 같아?",
  ui_story_1016_10160101_197_dialog_content = "훈련에서 월등한 성적을 내고, 대원수와의 대결 기회를 얻는 건 어렵지 않겠죠.",
  ui_story_1016_10160101_198_dialog_content = "하지만 당신이 일대일 승부에서 대원수를 이길 수 있을 거라 생각하진 않습니다.",
  ui_story_1016_10160101_199_dialog_content = "쳇, 그렇게까지 말할 건 없잖아.",
  ui_story_1016_10160101_200_dialog_content = "애초에 일대일 싸움은 당신 강점이 아니잖아요.\n이런 걸로 제가 당신 자존심을 지켜줄 필요는 없겠죠?",
  ui_story_1016_10160101_201_dialog_content = "그래. 그건 나도 잘 알고 있으니까.",
  ui_story_1016_10160101_202_dialog_content = "하지만 우리 계획에서 라인하르트와 대결하는 건 내가 아냐.",
  ui_story_1016_10160101_203_dialog_content = "!!!",
  ui_story_1016_10160101_204_dialog_content = "...그게 요제프 신부를 데려온 이유였군요.",
  ui_story_1016_10160101_205_dialog_content = "요제프가 얼마나 승산이 있을진 모르겠어.",
  ui_story_1016_10160101_206_dialog_content = "하지만 그 싸움에서 충분히 큰 「소리」를 낼 수 있는 건 확실해.",
  ui_story_1016_10160101_207_dialog_content = "두 분 다 들어보시죠. 누군가 울고 있어요.",
  ui_story_1016_10160101_208_dialog_content = "음?",
  ui_story_1016_10160101_209_dialog_content = "마음을 가라앉히고 귀를 기울이세요.",
  ui_story_1016_10160101_210_dialog_content = "<size=30>훌쩍... 훌쩍...</size>",
  ui_story_1016_10160101_211_dialog_content = "진짜네!",
  ui_story_1016_10160101_212_dialog_content = "이상한 울음소리로군요. 슬픔에 잠긴 것 같지는 않습니다.",
  ui_story_1016_10160101_213_dialog_content = "목소리가 다가오고 있어요. 이쪽으로 오고 있는 것 같네요.",
  ui_story_1016_10160101_214_dialog_content = "훌쩍...",
  ui_story_1016_10160101_215_dialog_content = "오, 보기 드문 아인 혈통이잖아.",
  ui_story_1016_10160101_216_dialog_content = "괜찮으십니까? 우는 소리가 들리더군요.",
  ui_story_1016_10160101_217_dialog_content = "네? 저요?",
  ui_story_1016_10160101_218_dialog_content = "미안해요. 신경 쓰이게 만들었네요.",
  ui_story_1016_10160101_219_dialog_content = "그냥 머리가 아팠을 뿐이에요. 제 지병이에요.",
  ui_story_1016_10160101_220_dialog_content = "울 정도로 아프다고? 그럼 좀 심각한 것 같은데...",
  ui_story_1016_10160101_221_dialog_content = "역에서 봤어요. 당신도 훈련에 참가하는 후보생이겠죠.",
  ui_story_1016_10160101_222_dialog_content = "맞아요. 전 메리라고 해요.",
  ui_story_1016_10160101_223_dialog_content = "어디서 왔습니까?",
  ui_story_1016_10160101_224_dialog_content = "움브라톤이요.",
  ui_story_1016_10160101_225_dialog_content = "몇 명이서 왔죠?",
  ui_story_1016_10160101_226_dialog_content = "저까지 세 사람이요.",
  ui_story_1016_10160101_227_dialog_content = "참, 혹시 인형 옷 차림의 키 작은 여자애 못 보셨나요?",
  ui_story_1016_10160101_228_dialog_content = "제 팀원인데 이 근처에서 길을 잃은 것 같아요.",
  ui_story_1016_10160101_229_dialog_content = "못 봤어. 지금까지 우리가 마주친 후보생은 너뿐이야.",
  ui_story_1016_10160101_230_dialog_content = "그렇군요. 그럼 다른 볼일이 없으면 전 팀원을 찾으러 가 볼게요.",
  ui_story_1016_10160101_231_dialog_content = "신경 써 줘서 고마워요. 그럼 훈련에서 봐요.",
  ui_story_1016_10160101_232_dialog_content = "방금 왜 취조하듯 따진 거야?",
  ui_story_1016_10160101_233_dialog_content = "취조까진 아니죠. 그저 기본적인 정보를 조금 물었을 뿐입니다.",
  ui_story_1016_10160101_234_dialog_content = "수상해 보여서 그런 건가?",
  ui_story_1016_10160101_235_dialog_content = "지금은 확실하진 않습니다. 좀 더 상황을 지켜보기로 하죠.",
  ui_story_1016_10160101_236_dialog_content = "제가 받은 명령을 전달하겠습니다.",
  ui_story_1016_10160101_237_dialog_content = "우리 팀은 반드시 우승해야 합니다. 어떤 대가를 치르더라도 말이죠.",
  ui_story_1016_10160101_238_dialog_content = "질문 있습니까?",
  ui_story_1016_10160101_239_dialog_content = "없습니다.",
  ui_story_1016_10160101_240_dialog_content = "...그게 위원회의 명령입니까?",
  ui_story_1016_10160101_241_dialog_content = "네.",
  ui_story_1016_10160101_242_dialog_content = "알겠습니다. 그럼 저도 질문은 없습니다.",
  ui_story_1016_10160101_243_dialog_content = "심사 단계 전까지 특별한 계획은 없습니다. 정상적으로 수업에 참여해 주세요.",
  ui_story_1016_10160101_244_dialog_content = "유일하게 주의해야 할 점은 존재감을 줄이는 겁니다.\n적을 만들지 말고, 주의를 끄는 것도 삼가세요.",
  ui_story_1016_10160101_245_dialog_content = "우리에게 내려진 명령은 반드시 기밀을 유지해야 합니다.\n이 방을 나간 뒤에는 그 누구에게도 발설해서는 안 됩니다.",
  ui_story_1016_10160101_246_dialog_content = "알겠습니다.",
  ui_story_1016_10160101_247_dialog_content = "알겠습니다.",
  ui_story_1016_10160101_248_dialog_content = "좋습니다, 전달 사항은 여기까지입니다. 해산해 주세요.",
  ui_story_1016_10160101_249_dialog_content = "네, 악셀리아는 졸립니다.",
  ui_story_1016_10160101_250_dialog_content = "그럼 수면 캡슐로 가죠. 제가 데려다줄게요.",
  ui_story_1016_10160101_251_dialog_content = "아나톨리, 문 좀 열어주세요.",
  ui_story_1016_10160101_252_dialog_content = "네.",
  ui_story_1016_10160101_253_dialog_content = "<color=#e8d9bb>끼이익──</color>",
  ui_story_1016_10160101_254_dialog_content = "으앗!",
  ui_story_1016_10160101_255_dialog_content = "밖에 누가 있습니다!",
  ui_story_1016_10160101_256_dialog_content = "누구죠?",
  ui_story_1016_10160101_257_dialog_content = "아파 죽겠네! 문 좀 살살 열어!",
  ui_story_1016_10160101_258_dialog_content = "진짜 너무해. 머리에 혹이 생길 것 같잖아!",
  ui_story_1016_10160101_259_dialog_content = "......",
  ui_story_1016_10160101_260_dialog_content = "이 아이, 적입니까?",
  ui_story_1016_10160101_261_dialog_content = "왜 그런 눈으로 날 보는데?!",
  ui_story_1016_10160101_262_dialog_content = "따, 딱히 엿듣거나 하진 않았다구!",
  ui_story_1016_10160101_263_dialog_content = "당신이 엿듣고 있었다고 말하진 않았습니다만.",
  ui_story_1016_10160101_264_dialog_content = "큭...",
  ui_story_1016_10160101_265_dialog_content = "민치! 여기 있었구나!",
  ui_story_1016_10160101_266_dialog_content = "내가 자난성은 길이 복잡하다고 했잖아. 혼자 돌아다니면 안 돼.",
  ui_story_1016_10160101_267_dialog_content = "메리! 늦었잖아!",
  ui_story_1016_10160101_268_dialog_content = "동료입니까? 당신들은...",
  ui_story_1016_10160101_269_dialog_content = "죄송합니다. 제 친구가 폐를 끼쳤군요.",
  ui_story_1016_10160101_270_dialog_content = "저흰 자난성은 처음인데, 구조가 워낙 복잡해서 길을 잃고 말았습니다.",
  ui_story_1016_10160101_271_dialog_content = "방해가 되었습니까?",
  ui_story_1016_10160101_272_dialog_content = "디시스, 왜 사과해?! 쟤들이 문을 열어서 내가 부딪힌 거라구!",
  ui_story_1016_10160101_273_dialog_content = "됐어, 민치. 새로운 친구들을 예의 바르게 대해야지.",
  ui_story_1016_10160101_274_dialog_content = "......",
  ui_story_1016_10160101_275_dialog_content = "그럼 저희는 이만 실례하겠습니다.",
  ui_story_1016_10160101_276_dialog_content = "그래, 내가 돌아가는 길을 잊어버리기 전에 얼른 가자.",
  ui_story_1016_10160101_277_dialog_content = "흥, 바이바이! 메에롱~",
  ui_story_1016_10160101_278_dialog_content = "저 세 사람도 후보생입니다. 움브라톤에서 왔더군요.",
  ui_story_1016_10160101_279_dialog_content = "저대로 놔둬도 되는 겁니까? 우리 얘기를 엿들었을 수도 있습니다.",
  ui_story_1016_10160101_280_dialog_content = "만약 정말 엿들었다면, 제가 대응할 방법을 생각해 볼게요.",
  ui_story_1016_10160101_281_dialog_content = "자, 그럼 우리도 돌아가서 쉬도록 해요.",
  ui_story_1016_10160101_282_dialog_content = "내일 첫 수업에 대비해야죠.",
  ui_story_1016_10160101_283_dialog_content = "<color=#e8d9bb>뚜벅, 뚜벅, 뚜벅, 뚜벅...</color>",
  ui_story_1016_10160101_284_dialog_content = "녀석들... 갔나?",
  ui_story_1016_10160101_285_dialog_content = "응, 마지막 호위병들은 이미 떠났어.",
  ui_story_1016_10160101_286_dialog_content = "헬리오스, 몸 상태는 어때?",
  ui_story_1016_10160101_287_dialog_content = "신경 쓸 거 없어... 작은 상처니까.",
  ui_story_1016_10160101_288_dialog_content = "난... 언제든지 싸울 수 있어.",
  ui_story_1016_10160101_289_dialog_content = "여긴 자난성이야. 저들에게 들키면 온 일루미나의 병력이 우릴 포위할 거야.",
  ui_story_1016_10160101_290_dialog_content = "힘만으로는 돌파할 수 없어.",
  ui_story_1016_10160101_291_dialog_content = "하지만...",
  ui_story_1016_10160101_292_dialog_content = "조금만 참아. 이럴 때일수록 냉정해야지.",
  ui_story_1016_10160101_293_dialog_content = "좀 더 시간이 필요해.",
  ui_story_1016_10160101_294_dialog_content = "뭘 기다리는 거야?",
  ui_story_1016_10160101_295_dialog_content = "「<color=#FFB400>팬텀</color>」.",
  ui_story_1016_10160201_1_dialog_content = "<anim type=Shake>하암──</anim>, 잠도 제대로 못 잤네.",
  ui_story_1016_10160201_2_dialog_content = "이 도시는 어딜 가도 기계 냄새가 난단 말이지.",
  ui_story_1016_10160201_3_dialog_content = "실험실?! 우릴 이런 곳에 데려와서 뭘 하려는 거야?!",
  ui_story_1016_10160201_4_dialog_content = "우린 실험체가 되려고 일루미나에 온 게 아냐!",
  ui_story_1016_10160201_5_dialog_content = "아, 익숙한 곳이네.",
  ui_story_1016_10160201_6_dialog_content = "왠지 뭐 하려는 건지 알 것 같아.",
  ui_story_1016_10160201_7_dialog_content = "<color=#e8d9bb>딸랑──</color>",
  ui_story_1016_10160201_8_dialog_content = "시끄러워! 다들 조용히 해!",
  ui_story_1016_10160201_9_dialog_content = "난 너희들을 가르칠 교관 그로누야.\n과학 기술에 관한 수업은 전부 내가 맡을 거야.",
  ui_story_1016_10160201_10_dialog_content = "물론 너희 대부분은 진지하게 연구에 임할 생각 없는 거 잘 알고 있어.\n나도 분위기 싸하게 만들고 싶진 않아.",
  ui_story_1016_10160201_11_dialog_content = "그래서 첫 수업은 가장 재미있는... 최첨단 과학 연구 성과를 준비했어!",
  ui_story_1016_10160201_12_dialog_content = "자, 소개할게. 일루미나가 새롭게 연구 개발한 훈련 장치──",
  ui_story_1016_10160201_13_dialog_content = "「<color=#FFB400>전투 시뮬레이터</color>」야!",
  ui_story_1016_10160201_14_dialog_content = "역시나.",
  ui_story_1016_10160201_15_dialog_content = "헤드셋? 그걸로 무슨 훈련을 할 수 있지?",
  ui_story_1016_10160201_16_dialog_content = "이건 실제 무기를 쓰는 것보다 훨씬 더 효과적이라구.",
  ui_story_1016_10160201_17_dialog_content = "병사를 훈련시킬 때 가장 향상시키기 어려운 게 뭘까?",
  ui_story_1016_10160201_18_dialog_content = "신체 능력? 아니면 루미나틱스 수준?",
  ui_story_1016_10160201_19_dialog_content = "전투의 소질입니다.",
  ui_story_1016_10160201_20_dialog_content = "맞아, 전투 소질이야말로 가장 육성하기 어려운 거야.",
  ui_story_1016_10160201_21_dialog_content = "전장에서 일어날 일은 실제로 전장에 나가지 않으면 경험할 수 없거든.",
  ui_story_1016_10160201_22_dialog_content = "하지만 전장은 잔혹해. 모든 병사에게 경험을 가지고 돌아갈 권리가 주어지진 않아.",
  ui_story_1016_10160201_23_dialog_content = "저들이 겪는 게 「가상 전투」라면 모를까.",
  ui_story_1016_10160201_24_dialog_content = "가상 전투 같은 걸 어떻게 해야 하는 거지...?",
  ui_story_1016_10160201_25_dialog_content = "그게 바로 첫 수업에서 너희가 체험할 내용이야!",
  ui_story_1016_10160201_26_dialog_content = "이제 너희한테 지금 내가 가지고 있는 거랑 같은 장치를 나눠줄 거야.",
  ui_story_1016_10160201_27_dialog_content = "이 헤드셋을 끼면 다 같이 가상의 전장 속으로 들어갈 수 있어.",
  ui_story_1016_10160201_28_dialog_content = "거기선 루미나틱스도, 무기도 평소처럼 쓸 수 있어.\n그리고 맞서야 할 적은 물론 모두가 잘 아는 암귀야.",
  ui_story_1016_10160201_29_dialog_content = "「전사」할 때까지 실제 전쟁이라 생각하면서 싸워.",
  ui_story_1016_10160201_30_dialog_content = "하하하, 꽤 재미있을 것 같잖아.",
  ui_story_1016_10160201_31_dialog_content = "현실과 같은 수준의 전장을 보여줄 수 있을진 모르겠지만.",
  ui_story_1016_10160201_32_dialog_content = "좋아! 다들 의욕이 생긴 모양이네!",
  ui_story_1016_10160201_33_dialog_content = "지금 바로 헤드셋을 나눠줄게. 오늘의 모의 전투 훈련을 시작해 보자.",
  ui_story_1016_10160201_34_dialog_content = "전투를 벌이는 동안 모두의 성과가 득점으로 계산돼서 옆의 스크린에 표시될 거야.",
  ui_story_1016_10160201_35_dialog_content = "객관적인 숫자는 절대 인재를 썩게 놔두지 않는 법이야.\n다들 힘내서 자기 재능을 마음껏 순위에 반영해 봐!",
  ui_story_1016_10160201_36_dialog_content = "<color=#e8d9bb>모의 전장에 진입했습니다.</color>",
  ui_story_1016_10160201_37_dialog_content = "사용법은 전이랑 똑같네.",
  ui_story_1016_10160201_38_dialog_content = "바이스랑 카렌은 어디 있지? 아직 헤드셋 안 꼈나?",
  ui_story_1016_10160201_39_dialog_content = "음, 여긴...",
  ui_story_1016_10160201_40_dialog_content = "우와! 화면이 순식간에 튀어나왔네!",
  ui_story_1016_10160201_41_dialog_content = "아무래도 전장 시뮬레이터가 전보다 더 개선된 것 같아.\n이제 몸이 느끼는 감각도 현실이랑 거의 다를 게 없을 정도야.",
  ui_story_1016_10160201_42_dialog_content = "현실에 가까운 전장일수록 우리 위기의식도 더 강해지겠지.",
  ui_story_1016_10160201_43_dialog_content = "주변을 보니까 왠지 일루미나의 방어선 같은데?",
  ui_story_1016_10160201_44_dialog_content = "<color=#e8d9bb>모든 후보생이 지정 위치에 도착했습니다.</color>",
  ui_story_1016_10160201_45_dialog_content = "<color=#e8d9bb>이번 전장은 일루미나 연방이 실제로 수행했던 전투를 모의 재현한 것입니다.</color>",
  ui_story_1016_10160201_46_dialog_content = "<color=#e8d9bb>당시 갑자기 들이닥친 암귀 무리는 방어선을 돌파해 연방에 막대한 피해를 입혔습니다.</color>",
  ui_story_1016_10160201_47_dialog_content = "<color=#e8d9bb>본 시스템에서는 후보생 여러분의 전투 능력에 적합하도록,\n전투 규모를 3인 팀이 대응할 수 있는 수준으로 조정했습니다.</color>",
  ui_story_1016_10160201_48_dialog_content = "<color=#e8d9bb>각 팀 모두 랜덤으로 전장 주위에 배치되었습니다.\n후보생 여러분의 건투를 빌겠습니다.</color>",
  ui_story_1016_10160201_49_dialog_content = "<color=#e8d9bb>전투를 개시합니다.</color>",
  ui_story_1016_10160201_50_dialog_content = "다들 서로 다른 곳에 배정되는 거였구나.",
  ui_story_1016_10160201_51_dialog_content = "응, 아마 팀끼리 서로 영향을 주는 걸 피하기 위해서겠지.",
  ui_story_1016_10160201_52_dialog_content = "일루미나 연방이 실제로 겪은 전투를 재현한 거란 말이지?\n그럼 이걸로 그때 어떤 상황이었는지 알 수 있었으면 좋겠네.",
  ui_story_1016_10160201_53_dialog_content = "바이스는 이게 언제 어디서 있었던 전투인지 알아?",
  ui_story_1016_10160201_54_dialog_content = "잘 모르겠어. 일루미나 주변에서 벌어진 전쟁은 수없이 많았거든.\n방어선이 붕괴된 상황도 적지 않았어.",
  ui_story_1016_10160201_55_dialog_content = "역사적인 관점에서 본다면 그건 일루미나 방어선이 항상 보여왔던 상태라 할 수 있어.",
  ui_story_1016_10160201_56_dialog_content = "항상 벌어지는 전쟁이란 건가...",
  ui_story_1016_10160201_57_dialog_content = "암귀가 보여!",
  ui_story_1016_10160201_58_dialog_content = "이 규모... 정말 세 명이서 상대할 수 있는 수준인가?",
  ui_story_1016_10160201_59_dialog_content = "으... 실제 전투 때는 방어선이 암귀 군단한테 뚫렸다는 거잖아.",
  ui_story_1016_10160201_60_dialog_content = "그럼 전투 규모를 축소한다고 해도 우린 방어선 붕괴라는 결말을 바꿀 수 없는 거 아냐?",
  ui_story_1016_10160201_61_dialog_content = "암귀들을 눈앞에 두고 지금 우리가 느끼는 무력감은 분명히 그 당시 병사들과 같겠지...",
  ui_story_1016_10160201_62_dialog_content = "그러게, 시뮬레이션이라서 정말 다행이야.",
  ui_story_1016_10160201_63_dialog_content = "아무튼 최선을 다하자!",
  ui_story_1016_10160201_64_dialog_content = "그래, 가자!",
  ui_story_1016_10160202_1_dialog_content = "카렌! 빨리 뒤로 물러서!",
  ui_story_1016_10160202_2_dialog_content = "나도 그러고 싶어. 하지만...",
  ui_story_1016_10160202_3_dialog_content = "왠지 싸울수록 암귀가 늘어나는 느낌이야.",
  ui_story_1016_10160202_4_dialog_content = "그러게, 왠지 우리 쪽으로 몰려오는 것 같아.",
  ui_story_1016_10160202_5_dialog_content = "어떻게든 빠져나가지 않으면 암귀 무리에 파묻혀 버릴 거야...",
  ui_story_1016_10160202_6_dialog_content = "어? 카렌 전하!",
  ui_story_1016_10160202_7_dialog_content = "베르타?! 왜 여기 있어?",
  ui_story_1016_10160202_8_dialog_content = "저, 저희 팀이 암귀 무리에 휩쓸려서 흩어졌어요...",
  ui_story_1016_10160202_9_dialog_content = "혼자서는 계속 막는 데 급급해서, 싸우다 보니 계속 물러서게 됐죠...",
  ui_story_1016_10160202_10_dialog_content = "중간에 다른 후보생들도 만났어요...",
  ui_story_1016_10160202_11_dialog_content = "수다 떨 시간 있으면 적에게 더 집중하세요.",
  ui_story_1016_10160202_12_dialog_content = "당연히 집중하고 있지! 당신이 말 안 해도 알거든!",
  ui_story_1016_10160202_13_dialog_content = "아나톨리 씨도 있었네?! 아나톨리 씨는 잉겔 팀이었지?",
  ui_story_1016_10160202_14_dialog_content = "그쪽 팀도 싸우다 흩어진 거야?",
  ui_story_1016_10160202_15_dialog_content = "그렇습니다. 전투 중 다른 팀의 방해를 받아서 말이죠.",
  ui_story_1016_10160202_16_dialog_content = "야! 「다른 팀의 방해」라니! 분명히 협력하고 있었잖아!",
  ui_story_1016_10160202_17_dialog_content = "발목을 잡는 행위는 「방해」라고밖에 말할 수 없습니다.",
  ui_story_1016_10160202_18_dialog_content = "칫!",
  ui_story_1016_10160202_19_dialog_content = "어라? 처음 보는 후보생이네? 넌...",
  ui_story_1016_10160202_20_dialog_content = "이제 안 돼, PlayerName! 적이 너무 많아!",
  ui_story_1016_10160202_21_dialog_content = "이대로는 못 버텨!",
  ui_story_1016_10160202_22_dialog_content = "맞아, 암귀는 점점 늘어나고 있어...",
  ui_story_1016_10160202_23_dialog_content = "베르타, 아나톨리! 그리고 이름 모르는 후보생!",
  ui_story_1016_10160202_24_dialog_content = "<size=45>난 민치야!</size>",
  ui_story_1016_10160202_25_dialog_content = "모두 힘을 합치자! 전장 중심에서 탈출해 보는 거야!",
  ui_story_1016_10160202_26_dialog_content = "지금부터 힘을 합친다 해도... 난 이미 한계라고...",
  ui_story_1016_10160202_27_dialog_content = "윽... 으아악──!",
  ui_story_1016_10160202_28_dialog_content = "<size=45>베르타!!!</size>",
  ui_story_1016_10160202_29_dialog_content = "이런, 방금 전까지 베르타가 막아내던 적들이 한꺼번에 이쪽으로 몰려오고 있습니다!",
  ui_story_1016_10160202_30_dialog_content = "으아아악! 암귀가 덤벼든다! 어떡해!",
  ui_story_1016_10160202_31_dialog_content = "최대한 버티는 수밖에 없겠죠...",
  ui_story_1016_10160202_32_dialog_content = "다들 후방으로 돌파를 시도해! 그쪽 방향은 암귀도 적은 편이니까!",
  ui_story_1016_10160202_34_dialog_content = "PlayerName! 조심해!",
  ui_story_1016_10160202_35_dialog_content = "으악──",
  ui_story_1016_10160202_36_dialog_content = "뒤! 너희 뒤에──",
  ui_story_1016_10160202_37_dialog_content = "<color=#e8d9bb>삑──</color>",
  ui_story_1016_10160202_38_dialog_content = "<color=#e8d9bb>전투 시뮬레이터에서 퇴장했습니다.</color>",
  ui_story_1016_10160202_39_dialog_content = "휴... 돌아온 건가?",
  ui_story_1016_10160202_40_dialog_content = "전장 시뮬레이터에서 받은 죽음이 다가오는 느낌... 정말 괴로웠어...",
  ui_story_1016_10160202_41_dialog_content = "바이스? 카렌?",
  ui_story_1016_10160202_42_dialog_content = "휴... 결국 당했구나.",
  ui_story_1016_10160202_43_dialog_content = "그래, 그렇게 많은 암귀가 상대라면 뭘 해도 소용없을 거야.",
  ui_story_1016_10160202_44_dialog_content = "하하... 너희도 돌아왔구나. 이번 전투 시뮬레이터 소감은 어때?",
  ui_story_1016_10160202_45_dialog_content = "생각보다 훨씬 더 현실 같았어.\n그로누가 말한 대로 이거라면 확실히 전투 소질을 기를 수 있겠어.",
  ui_story_1016_10160202_46_dialog_content = "지금처럼 긴박한 전투는 현실에서라면 좀처럼 경험하기 힘드니까.",
  ui_story_1016_10160202_47_dialog_content = "실제 전투였으면 우린 아마 무사하지 못했을 거야.",
  ui_story_1016_10160202_48_dialog_content = "그러게, 실제로 겪어보니까 일루미나가 직면한 전쟁의 위협이\n얼마나 큰지 절실히 느낄 수 있었어.",
  ui_story_1016_10160202_49_dialog_content = "군인들은 항상 저렇게... 실패할지도 모르는 전쟁과 마주하고 있는 거구나.",
  ui_story_1016_10160202_50_dialog_content = "맞아...",
  ui_story_1016_10160202_51_dialog_content = "전투 시뮬레이터에서 나온 후보생들은 그만 떠들고 와서 여길 봐.",
  ui_story_1016_10160202_52_dialog_content = "다들 지금 전투에서 각자 느낀 점이 있겠지?\n그리고 시뮬레이션 시스템에 대해 생각하는 점도 있을 테고 말이야.",
  ui_story_1016_10160202_53_dialog_content = "이건 전투 시뮬레이터 체험 설문조사야.",
  ui_story_1016_10160202_54_dialog_content = "다들 지금 바로 작성해 줘!",
  ui_story_1016_10160202_55_dialog_content = "으엑... 설문조사까지 해야 하나...",
  ui_story_1016_10160202_56_dialog_content = "그로누 교관, 설마 우릴 가지고 실험하고 있는 건 아니겠지?",
  ui_story_1016_10160202_57_dialog_content = "에이, 어떻게 그렇게 말할 수가 있어!",
  ui_story_1016_10160202_58_dialog_content = "이 조사가 제공하는 데이터로 우린 시뮬레이터의 성능을 한 층 더 개선할 수 있다구.",
  ui_story_1016_10160202_59_dialog_content = "그럼 모두한테 좋은 일이잖아? 안 그래?",
  ui_story_1016_10160202_60_dialog_content = "그래그래...",
  ui_story_1016_10160202_61_dialog_content = "<color=#e8d9bb>20분 후</color>",
  ui_story_1016_10160202_62_dialog_content = "겨우 끝났네. 설문지가 뭐 이리 길어...",
  ui_story_1016_10160202_63_dialog_content = "그러게. 손이 다 저리잖아!",
  ui_story_1016_10160202_64_dialog_content = "설문지 끝에는 이번 모의 전투 점수를 적어야 해. 우리 점수는 몇이지?",
  ui_story_1016_10160202_65_dialog_content = "아, 그러게. 우리 성적이면 어느 정도인 건지 궁금하네.",
  ui_story_1016_10160202_66_dialog_content = "그로누 교관, 점수는 어디서 봐?",
  ui_story_1016_10160202_67_dialog_content = "아, 그건 조금만 더 기다려 봐.",
  ui_story_1016_10160202_68_dialog_content = "아직 전투 시뮬레이터에서 안 나온 후보생들이 있거든.",
  ui_story_1016_10160202_69_dialog_content = "아직도 안 나왔다고?! 벌써 한참 됐는데...",
  ui_story_1016_10160202_70_dialog_content = "<color=#e8d9bb>이번 모의 전투가 종료되었습니다.</color>",
  ui_story_1016_10160202_71_dialog_content = "<color=#e8d9bb>종료 시점의 상태에 따라 이번 전황을 판정합니다──</color>",
  ui_story_1016_10160202_72_dialog_content = "<color=#e8d9bb>전투 결과는 오로리안 측의 승리입니다.</color>",
  ui_story_1016_10160202_73_dialog_content = "하아? 우리가 이겼다고?",
  ui_story_1016_10160202_74_dialog_content = "<size=45>승리?!</size>",
  ui_story_1016_10160202_75_dialog_content = "말도 안 돼. 정말 이 스테이지를 클리어할 수 있는 사람이 있다고...?",
  ui_story_1016_10160202_76_dialog_content = "마지막으로 시뮬레이터에서 나온 사람은 누구지?",
  ui_story_1016_10160202_77_dialog_content = "휴, 헤드셋을 오래 썼더니 기분이 안 좋아졌어.",
  ui_story_1016_10160202_78_dialog_content = "제법이야. 가상의 전장이지만 꽤 실감 났어.",
  ui_story_1016_10160202_79_dialog_content = "항상 전쟁과 함께하는 자들답네. 전쟁에 대한 일루미나의 인식은 매우 정확했어.",
  ui_story_1016_10160202_80_dialog_content = "하지만 너무 현실적인 것도 문제입니다.",
  ui_story_1016_10160202_81_dialog_content = "모의 전장의 원형만 이해하고 있다면 전황의 변화를 읽는 건 어렵지 않거든요.",
  ui_story_1016_10160202_82_dialog_content = "따라서 난이도가 크게 떨어지게 되죠.",
  ui_story_1016_10160202_83_dialog_content = "이, 이게 난이도가 낮다고?",
  ui_story_1016_10160202_84_dialog_content = "전 내부의 환경이 마음에 들지 않았습니다.",
  ui_story_1016_10160202_85_dialog_content = "제가 아무리 경건하게 불러도, 대답해 주는 것은 그저 허구의 「빛」뿐이었습니다.",
  ui_story_1016_10160202_86_dialog_content = "너무 진지해지지 마, 요제프. 그냥 놀이였다고 생각하라고.",
  ui_story_1016_10160202_87_dialog_content = "스크린에 성적이 떴어!",
  ui_story_1016_10160202_88_dialog_content = "레오 씨네 팀 점수... 엄청 높네...",
  ui_story_1016_10160202_89_dialog_content = "의심의 여지가 없는 1등이잖아...",
  ui_story_1016_10160202_90_dialog_content = "우리 같은 전장에서 싸운 거 맞지?",
  ui_story_1016_10160202_91_dialog_content = "그 엄청난 수의 암귀를 상대로 어떻게 이긴 거지...?",
  ui_story_1016_10160202_92_dialog_content = "저들이 싸우는 방법을 봤어요.",
  ui_story_1016_10160202_93_dialog_content = "그 방어선을 파괴한 암귀 군단은... 저들이 「만들어」 낸 거예요...",
  ui_story_1016_10160202_94_dialog_content = "뭐라고?!",
  ui_story_1016_10160202_95_dialog_content = "암귀 군단을 만들어 낸다고? 말도 안 되잖아!",
  ui_story_1016_10160202_96_dialog_content = "사실인걸요. 저들은 싸우면서 암귀의 대열을 유도하는 방법을 알고 있었어요. \n그리고 암귀들을 서서히 한 곳으로 몰아갔죠.",
  ui_story_1016_10160202_97_dialog_content = "그 후 지형을 이용해서 암귀를 피하고 기회를 노리다가,\n병력의 우세를 발휘할 수 없는 좁은 지형에서 적을 섬멸했어요.",
  ui_story_1016_10160202_98_dialog_content = "암귀들은 마치 양치기에게 쫓기는 양 떼처럼 한 마리씩 계속해서 쓰러졌어요.",
  ui_story_1016_10160202_99_dialog_content = "암귀를 유도한다니... 그런 전투가 가능한 건가...",
  ui_story_1016_10160202_100_dialog_content = "딱히 대단한 전략도 아냐. 아군의 10배, 100배의 적을 앞에 두면\n누구라도 머리를 쥐어짤 수밖에 없거든.",
  ui_story_1016_10160202_101_dialog_content = "책의 내용 같은 건 생각할 필요 없어.\n이길 수 없는 전투를 이기는 방법을 가르쳐 주는 책은 없으니까.",
  ui_story_1016_10160202_102_dialog_content = "그저 머릿속에 있는 우스꽝스럽고 황당한 방법을 닥치는 대로\n끄집어내서 시도할 수밖에 없다고.",
  ui_story_1016_10160202_103_dialog_content = "여러 번 시도해서 운 좋게도 아직 전사하지 않았다면,\n그건 곧 네가 전장에서 필승법을 습득했다는 뜻이 되겠지.",
  ui_story_1016_10160202_104_dialog_content = "(맞아, 처음 만났을 때도 레오 씨는 이상한 방식으로 싸웠어.)",
  ui_story_1016_10160202_105_dialog_content = "(전투에 대한 더스크 타운 사람들의 상상력은 우리와는 비교할 수 없는 것 같네.)",
  ui_story_1016_10160202_106_dialog_content = "헤에, 정말 인상 깊었어. 다들 말이 없어져 버렸는데?",
  ui_story_1016_10160202_107_dialog_content = "잘 보고 배워. 다들 점수만 멍하니 쳐다보고 있는 게 꼭...",
  ui_story_1016_10160202_108_dialog_content = "무기를 처음 본 어린애들 같잖아.",
  ui_story_1016_10160301_1_dialog_content = "<color=#e8d9bb>일주일 후</color>",
  ui_story_1016_10160301_2_dialog_content = "어라? 이쪽은 사무실이잖아? 길을 잘못 들었나?",
  ui_story_1016_10160301_3_dialog_content = "아마 교실은...",
  ui_story_1016_10160301_4_dialog_content = "PlayerName, 여기서 뭐 하고 있습니까?",
  ui_story_1016_10160301_5_dialog_content = "수업이 곧 시작될 겁니다.",
  ui_story_1016_10160301_6_dialog_content = "아나톨리 씨! 휴, 다행이야!",
  ui_story_1016_10160301_7_dialog_content = "교실까지 어떻게 가는지 알아?\n복도를 계속 돌았더니 머리가 어지러울 정도거든, 하하하...",
  ui_story_1016_10160301_8_dialog_content = "그런 거였군요. 그럼 절 따라오시죠.",
  ui_story_1016_10160301_9_dialog_content = "절 만나서 다행입니다. 지각했으면 학점이 깎였을 겁니다.",
  ui_story_1016_10160301_10_dialog_content = "맞아, 안 그래도 오늘 다들 학점이 어쩌네 하면서 얘기하던데, 그건 뭐에 쓰는 거야?",
  ui_story_1016_10160301_11_dialog_content = "어제 나눠준 책자를 안 읽었습니까?",
  ui_story_1016_10160301_12_dialog_content = "아직 못 봤어. 어젠 그로누한테 끌려가서 스카이워커를 테스트하느라 바빴거든.",
  ui_story_1016_10160301_13_dialog_content = "그럼 제가 간단하게 설명해 드리죠.",
  ui_story_1016_10160301_14_dialog_content = "오늘부터 여러분의 수업 중 성적은 학점으로 기록됩니다.",
  ui_story_1016_10160301_15_dialog_content = "교육 단계가 종료될 때까지, 모든 후보생의 학점은 계속해서 누적될 겁니다.",
  ui_story_1016_10160301_16_dialog_content = "최종 학점으로 각 후보생의 능력을 평가하게 될 거라는 건 누가 봐도 알 수 있겠죠.\n하지만 학점에는 더 중요한 용도가 있습니다.",
  ui_story_1016_10160301_17_dialog_content = "심사 단계에서 학점은 후보생들에게 힘이 될 겁니다.",
  ui_story_1016_10160301_18_dialog_content = "힘이 된다고?",
  ui_story_1016_10160301_19_dialog_content = "심사 전에 학점을 가지고 물자로 교환할 수 있기 때문에,\n종합적인 능력 향상에 도움이 됩니다.",
  ui_story_1016_10160301_20_dialog_content = "학점이 많을수록 얻게 되는 우위도 그만큼 많습니다.",
  ui_story_1016_10160301_21_dialog_content = "따라서 모두가 수업에서 더 많은 학점을 얻으려고 할 겁니다.",
  ui_story_1016_10160301_22_dialog_content = "어쩐지 경쟁하는 분위기가 더 짙어진 것 같더라니.",
  ui_story_1016_10160301_23_dialog_content = "그렇습니다. 정상에 서기 위해선 정신을 바짝 차려야 합니다.",
  ui_story_1016_10160301_24_dialog_content = "교실에 도착했습니다. 시간도 딱 맞춰서 왔군요.",
  ui_story_1016_10160301_25_dialog_content = "이제 길은 익혔습니까?",
  ui_story_1016_10160301_26_dialog_content = "아하하, 안 잊어버리길 빌어야겠네.",
  ui_story_1016_10160301_27_dialog_content = "근데 이번 수업은 뭐야?",
  ui_story_1016_10160301_28_dialog_content = "실전 격투 수업입니다.",
  ui_story_1016_10160301_29_dialog_content = "<color=#e8d9bb>끼이익──</color>",
  ui_story_1016_10160301_30_dialog_content = "야! 거기 둘!",
  ui_story_1016_10160301_31_dialog_content = "20초만 더 늦었으면 지각이었어.",
  ui_story_1016_10160301_32_dialog_content = "뭐야, 엄청 아슬아슬했네...",
  ui_story_1016_10160301_33_dialog_content = "좋아. 가장 느린 후보생까지 다 왔으니까, 수업 시작할게.",
  ui_story_1016_10160301_34_dialog_content = "난 일루미나 연방 근위군의 군단장 레이스야. 그리고 오늘은 너희 교관이고.",
  ui_story_1016_10160301_35_dialog_content = "이 수업에서 배우는 건 간단해. 싸움이야.",
  ui_story_1016_10160301_36_dialog_content = "싸움?",
  ui_story_1016_10160301_37_dialog_content = "「싸움을 뭘 배운다는 거야」, 다들 그런 생각 하고 있겠지?",
  ui_story_1016_10160301_38_dialog_content = "게다가 여기 서 있는 사람들이라면 모두 많게든 적게든 자기 전투 능력에 자신이 있겠지.",
  ui_story_1016_10160301_39_dialog_content = "하지만 이 중의 많은 후보생들이 전투에 능숙하지 못한 것도 확실해.",
  ui_story_1016_10160301_40_dialog_content = "오늘 내가 가르치는 건 어떻게 해야 이길 수 있느냐가 아니라,\n어떻게 하면 완벽하게 이길 수 있느냐야.",
  ui_story_1016_10160301_41_dialog_content = "이길 수 있는 싸움의 속도를 높이고, 최대한 힘을 아껴야 해.\n그래야 더 좋은 상태로 다음 전투에 임할 수 있으니까.",
  ui_story_1016_10160301_42_dialog_content = "승리란 그렇게 쉬운 일이 아냐. 세세한 부분까지 완벽하게 해야만 해.",
  ui_story_1016_10160301_43_dialog_content = "음, 듣고 보니 확실히 그런 것 같네...",
  ui_story_1016_10160301_44_dialog_content = "지금까지 전투의 효율에 대해선 특별한 훈련을 받은 적이 없었어.",
  ui_story_1016_10160301_45_dialog_content = "논리는 맞지만, 「완벽」이란 건 쉬운 일이 아니잖아.",
  ui_story_1016_10160301_46_dialog_content = "교관은 완벽하게 할 수 있나?",
  ui_story_1016_10160301_47_dialog_content = "야, 지금 내 힘을 의심하는 거야?",
  ui_story_1016_10160301_48_dialog_content = "수업에서 배울 게 없을까 걱정이 돼서 말이지.",
  ui_story_1016_10160301_49_dialog_content = "흥, 난 오히려 네가 내 훈련을 못 따라올까 걱정인데?",
  ui_story_1016_10160301_50_dialog_content = "잡담은 여기까지 하고, 전원 팀별로 줄을 서도록 해.",
  ui_story_1016_10160301_51_dialog_content = "오늘 수업은 실전 위주야.\n훈련이 잘되어 있는 일루미나의 병사들이 너흴 상대해 줄 거야.",
  ui_story_1016_10160301_52_dialog_content = "1조, 앞으로!",
  ui_story_1016_10160301_53_dialog_content = "<size=45>예!</size>",
  ui_story_1016_10160301_54_dialog_content = "후보생들한테 일루미나식 인사를 해 줘.",
  ui_story_1016_10160301_55_dialog_content = "<size=45>예!</size>",
  ui_story_1016_10160301_56_dialog_content = "참, 그쪽 백야성의 기사 친구는 특별히 잘 「챙겨」줘.",
  ui_story_1016_10160301_57_dialog_content = "부족하면 수업 끝나고 나한테 대련 신청해도 좋아.",
  ui_story_1016_10160301_58_dialog_content = "사양할게, 차라리 수업에 더 힘쓰고 싶거든.",
  ui_story_1016_10160301_59_dialog_content = "그럼 적어도 학점은 받을 수 있으니까, 그렇지?",
  ui_story_1016_10160301_60_dialog_content = "맞아, 학점을 벌 수 있는 첫 번째 기회잖아. 전력으로 가야겠어.",
  ui_story_1016_10160301_61_dialog_content = "잉겔, 저는 어떻게 해야 하나요?",
  ui_story_1016_10160301_62_dialog_content = "평소보다 살살 하세요.",
  ui_story_1016_10160301_63_dialog_content = "<size=32>이 후보생들... 왠지 좀 무서워졌어...</size>",
  ui_story_1016_10160301_64_dialog_content = "<size=32>나...나도...</size>",
  ui_story_1016_10160401_1_dialog_content = "<color=#e8d9bb>한 달 후</color>",
  ui_story_1016_10160401_2_dialog_content = "자, 오늘 교육은 여기까지예요.",
  ui_story_1016_10160401_3_dialog_content = "수업을 끝내죠.",
  ui_story_1016_10160401_4_dialog_content = "잘했어, PlayerName. 오늘도 학점을 많이 땄잖아!",
  ui_story_1016_10160401_5_dialog_content = "휴, 다들 의욕이 넘치니까 학점 따는 것도 힘드네.",
  ui_story_1016_10160401_6_dialog_content = "팀 간 경쟁은 이미 과열된 상태야. 게다가 앞으로는 더 치열해질 거야.",
  ui_story_1016_10160401_7_dialog_content = "오늘 학점 순위 봤어?",
  ui_story_1016_10160401_8_dialog_content = "아직, 우리 지금 몇 등인데?",
  ui_story_1016_10160401_9_dialog_content = "3등.",
  ui_story_1016_10160401_10_dialog_content = "우와, 하나 더 올랐네!",
  ui_story_1016_10160401_11_dialog_content = "분위기가 좋은걸? 앞의 두 팀은 좀 어때?",
  ui_story_1016_10160401_12_dialog_content = "1등은 볼 것도 없어. 레오 팀이 격차를 한참 벌려놨어.",
  ui_story_1016_10160401_13_dialog_content = "그 정도 점수 차라면... 아마 다른 팀이 뛰어넘을 가망은 없을 거야.",
  ui_story_1016_10160401_14_dialog_content = "역시 그 팀답네...",
  ui_story_1016_10160401_15_dialog_content = "2등은 잉겔 팀이야. 이제서야 두각을 드러냈다고 봐야겠지.",
  ui_story_1016_10160401_16_dialog_content = "그 팀은 특별한 약점이 없어.\n어떤 수업에서든 괜찮은 성적을 내고 있어서 서서히 순위가 올라간 거야.",
  ui_story_1016_10160401_17_dialog_content = "우리랑은 얼마나 차이가 나는데?",
  ui_story_1016_10160401_18_dialog_content = "잉겔 팀과 레오 팀 점수 차의 절반 정도.",
  ui_story_1016_10160401_19_dialog_content = "그것도 격차가 꽤 크잖아...",
  ui_story_1016_10160401_20_dialog_content = "잉겔은 어떤 수업이든 높은 성취도를 내고 있어.\n저 팀을 넘는 건 확실히 조금 어려울 거야.",
  ui_story_1016_10160401_21_dialog_content = "다만 수업 외라면 얘기가 다르겠지.",
  ui_story_1016_10160401_22_dialog_content = "수업 외?",
  ui_story_1016_10160401_23_dialog_content = "어제 다른 팀이 수업 외 자율 훈련을 하는 걸 봤어.",
  ui_story_1016_10160401_24_dialog_content = "그리고 그 훈련 결과를 보고했더니 똑같이 학점을 받았어.",
  ui_story_1016_10160401_25_dialog_content = "뭐? 그런 방법도 있었어?!",
  ui_story_1016_10160401_26_dialog_content = "맞아, 아무래도 주최 측 의도는 후보생들의 자율 훈련을 촉진하는 데 있는 것 같아.",
  ui_story_1016_10160401_27_dialog_content = "그렇게 해서 받을 수 있는 학점은 상대적으로 적지만, 그래도 쌓이면 무시할 수 없어.",
  ui_story_1016_10160401_28_dialog_content = "그 방법이라면 우리도 잉겔 팀을 추월할 수 있을지도 몰라.",
  ui_story_1016_10160401_29_dialog_content = "오! 괜찮은 방법 같아!",
  ui_story_1016_10160401_30_dialog_content = "진짜 치열하네. 수업 밖에서까지 경쟁해야 한다니...",
  ui_story_1016_10160401_31_dialog_content = "자, 그럼 우리도 스케줄을 짜 보자.",
  ui_story_1016_10160401_32_dialog_content = "어떻게 하면 가장 효율적으로 훈련할 수 있을지 생각해 봐야지.",
  ui_story_1016_10160401_33_dialog_content = "<color=#e8d9bb>다음날, 훈련 교실</color>",
  ui_story_1016_10160401_34_dialog_content = "수업 후에도 교실에 남는 후보생들이 점점 늘고 있군요.",
  ui_story_1016_10160401_35_dialog_content = "대장님, 저희도 수업 외 훈련을 실시합니까?",
  ui_story_1016_10160401_36_dialog_content = "하고 싶은 훈련이 있다면 해도 괜찮습니다.",
  ui_story_1016_10160401_37_dialog_content = "단, 학점을 위해서라면 그럴 필요는 없습니다.",
  ui_story_1016_10160401_38_dialog_content = "학점이 많으면 최종 심사에서 유리할 것 같았습니다만,\n우리에겐 중요하지 않은 겁니까?",
  ui_story_1016_10160401_39_dialog_content = "그래요. 우린 이 훈련에 그렇게까지 진심으로 임할 필요는 없으니까요...",
  ui_story_1016_10160401_40_dialog_content = "잉겔, 와서 좀 봐 주세요.",
  ui_story_1016_10160401_41_dialog_content = "저쪽 바닥과 연습 파트너가 전부 알록달록하게 물들었습니다.",
  ui_story_1016_10160401_42_dialog_content = "「알록달록」?",
  ui_story_1016_10160401_43_dialog_content = "무슨 일이죠? 페인트인가요?",
  ui_story_1016_10160401_44_dialog_content = "방금 저 훈련용 더미가 갑자기 폭발했습니다.",
  ui_story_1016_10160401_45_dialog_content = "......",
  ui_story_1016_10160401_46_dialog_content = "악셀리아는 누가 안에 페인트를 미리 채워놓았을 거라고 추측했습니다.",
  ui_story_1016_10160401_47_dialog_content = "비비안 참모장이 준비한 걸까요?",
  ui_story_1016_10160401_48_dialog_content = "참모장님이라면 아마 그런 유치한 장난을 하진 않을 겁니다.",
  ui_story_1016_10160401_49_dialog_content = "<color=#e8d9bb>탕──!</color>",
  ui_story_1016_10160401_50_dialog_content = "<size=45>총소리?!</size>",
  ui_story_1016_10160401_51_dialog_content = "지금 뭐 하는 거야?!",
  ui_story_1016_10160401_52_dialog_content = "저, 전...",
  ui_story_1016_10160401_53_dialog_content = "크로이, 괜찮아?",
  ui_story_1016_10160401_54_dialog_content = "괜찮아요, 실탄이 아니었거든요. 그저 색종이가 잔뜩 나왔을 뿐이에요.",
  ui_story_1016_10160401_55_dialog_content = "소리가 너무 커서 귀가 아직도 울리고 있지만요...",
  ui_story_1016_10160401_56_dialog_content = "병사! 대체 어떻게 된 거야?! 어째서 이런 일이 벌어진 거지?",
  ui_story_1016_10160401_57_dialog_content = "베르타, 그 사람 잘못이 아니에요.",
  ui_story_1016_10160401_58_dialog_content = "그 사람 겁먹은 표정을 보세요.",
  ui_story_1016_10160401_59_dialog_content = "응?",
  ui_story_1016_10160401_60_dialog_content = "...그렇습니다. 아까 방아쇠를 당길 때 감촉이 뭔가 이상해서,\n급하게 방향을 틀었습니다.",
  ui_story_1016_10160401_61_dialog_content = "제가 느낀 감각이 맞았군요. 누군가 공포탄을... 색종이로 바꿔치기했습니다...",
  ui_story_1016_10160401_62_dialog_content = "총알을 바꿔치기했다고?! 어떻게 그럴 수가 있어?!",
  ui_story_1016_10160401_63_dialog_content = "저도 정말 당황스럽습니다.",
  ui_story_1016_10160401_64_dialog_content = "정말 죄송합니다. 즉시 상부에 보고하고 확실하게 조사하겠습니다.",
  ui_story_1016_10160401_65_dialog_content = "공포탄을 바뀌치기했다니...",
  ui_story_1016_10160401_66_dialog_content = "누가 그런 위험한 짓을...",
  ui_story_1016_10160401_67_dialog_content = "위험하기보단 시시하다고 해야겠죠.",
  ui_story_1016_10160401_68_dialog_content = "누군가 훈련을 방해해서 다른 후보생들의 득점을 막으려 하고 있어요.",
  ui_story_1016_10160401_69_dialog_content = "누가 저런 유치한 방식을 쓰는 겁니까?",
  ui_story_1016_10160401_70_dialog_content = "알 수 없죠. 훈련엔 많은 세력이 참가하고 있고, 이해관계도 복잡해요.",
  ui_story_1016_10160401_71_dialog_content = "깊이 생각할 거 없어요. 우리만 저 흙탕물에 빠지지 않으면 되니까요.",
  ui_story_1016_10160401_72_dialog_content = "앞으로 수업 외의 불필요한 일에는 참여하지 않도록 하세요.",
  ui_story_1016_10160401_73_dialog_content = "알겠습니다.",
  ui_story_1016_10160401_74_dialog_content = "가죠, 악셀리아.",
  ui_story_1016_10160401_75_dialog_content = "네.",
  ui_story_1016_10160401_76_dialog_content = "<color=#e8d9bb>같은 시간, 일루미나 연구소</color>",
  ui_story_1016_10160401_77_dialog_content = "됐어! 전투 시뮬레이터 사용 허가가 났어!",
  ui_story_1016_10160401_78_dialog_content = "시뮬레이션으로 훈련하면 체력도 많이 아낄 수 있을 거야.",
  ui_story_1016_10160401_79_dialog_content = "맞아, 다른 후보생들이 교실을 나가면, 우린 돌아가서 체력 소모가 심한 훈련을 하면 돼.",
  ui_story_1016_10160401_80_dialog_content = "이렇게 하면 가장 효율적으로 학점을 얻을 수 있을 거야.",
  ui_story_1016_10160401_81_dialog_content = "카렌은 이런 문제도 정말 꼼꼼하게 생각하는구나.",
  ui_story_1016_10160401_82_dialog_content = "난 저번 훈련에도 참가했으니까 어느 정도 경험이 있는 셈이잖아.",
  ui_story_1016_10160401_83_dialog_content = "자, 그럼 시작하자. 시간을 잘 활용해야지.",
  ui_story_1016_10160401_84_dialog_content = "응, 저번처럼 헤드셋부터 끼자.",
  ui_story_1016_10160401_85_dialog_content = "어라, 여긴 어디야?",
  ui_story_1016_10160401_86_dialog_content = "저번에 들어왔을 때와는 다른 곳 같은데.",
  ui_story_1016_10160401_87_dialog_content = "적은 어디 있지?",
  ui_story_1016_10160401_88_dialog_content = "어디 보자...",
  ui_story_1016_10160401_89_option_content = "(강제 감응!)",
  ui_story_1016_10160401_90_dialog_content = "<anim type=Shake>스윽...</anim>",
  ui_story_1016_10160401_91_dialog_content = "엄청 많아! 저번보다 더 많아졌어!",
  ui_story_1016_10160401_92_dialog_content = "게다가 적의 다크매터도 엄청 강한데?!",
  ui_story_1016_10160401_93_dialog_content = "설마 또 도망가야 되는 건 아니지?",
  ui_story_1016_10160401_94_dialog_content = "어쩌면 도망갈 곳도 없을 것 같아...",
  ui_story_1016_10160401_95_dialog_content = "왔어!",
  ui_story_1016_10160401_96_dialog_content = "<anim type=Shake><size=50>그어어어!</size></anim>",
  ui_story_1016_10160401_97_dialog_content = "얼어붙어라!",
  ui_story_1016_10160401_98_dialog_content = "어째서... 효과가 없는 거지...?",
  ui_story_1016_10160401_99_dialog_content = "이 암귀들 뭔가 이상해!",
  ui_story_1016_10160401_100_dialog_content = "됐어, 어차피 시뮬레이션이잖아! 붙어보자!",
  ui_story_1016_10160402_11_dialog_content = "다들 조심해!",
  ui_story_1016_10160402_12_dialog_content = "이런, 이쪽도...",
  ui_story_1016_10160402_13_dialog_content = "카렌! 바이스!",
  ui_story_1016_10160402_14_dialog_content = "<size=45>으아아악──!</size>",
  ui_story_1016_10160402_15_dialog_content = "<anim type=Shake>하아... 하아...</anim>",
  ui_story_1016_10160402_16_dialog_content = "뭐 이런 게 다 있어...",
  ui_story_1016_10160402_17_dialog_content = "그래, 아까 그 암귀들, 정상이 아니었어.",
  ui_story_1016_10160402_18_dialog_content = "그저 강하다는 말로는 부족할 정도로 터무니없었어.",
  ui_story_1016_10160402_19_dialog_content = "맞아, 게다가 공격 방식은 보통 암귀랑 별로 다를 게 없었는데,\n다크매터가 비정상적으로 짙었어...",
  ui_story_1016_10160402_20_dialog_content = "...저기, 혹시 누가 전투 시뮬레이터에 손을 댄 건 아닐까?",
  ui_story_1016_10160402_21_dialog_content = "계속 얘기해 봐.",
  ui_story_1016_10160402_22_dialog_content = "전에 가디언 1호가 그랬거든.\n시뮬레이션이 아무리 현실적이어도 결국 전부 데이터에 불과하다고.",
  ui_story_1016_10160402_23_dialog_content = "우리가 겪은 전투도 전부 데이터들 사이의 연산 같은 거랬어.",
  ui_story_1016_10160402_24_dialog_content = "그럼 만약 누군가 그 안의 숫자 몇 개를 엄청 큰 수로 바꾸면...\n전황의 밸런스가 깨지지 않을까?",
  ui_story_1016_10160402_25_dialog_content = "그럼 어쩌면 아까 같은 상황이 벌어질지도 몰라.",
  ui_story_1016_10160402_26_dialog_content = "확실히 그렇네! 시뮬레이터 속 암귀의 힘에 대한 데이터가 수정된 거야.\n그래서 아까처럼 그렇게 비정상적으로 강해진 거겠지.",
  ui_story_1016_10160402_27_dialog_content = "근데 대체 누가 그런 악질 같은 짓을 했을까?",
  ui_story_1016_10160402_28_dialog_content = "PlayerName, 주변에 누가 있는지 감응할 수 있어?",
  ui_story_1016_10160402_29_dialog_content = "해보고 있어. 근데 특별히 의심스러운 녀석은 못 찾았어...",
  ui_story_1016_10160402_30_dialog_content = "그렇구나...",
  ui_story_1016_10160402_31_dialog_content = "전투 시뮬레이터가 조작된 건 교관에게 보고하는 게 좋겠어.",
  ui_story_1016_10160402_32_dialog_content = "상황이 이상해. 오늘 훈련은 여기서 끝내자.",
  ui_story_1016_10160402_33_dialog_content = "응, 숙소로 돌아가자.",
  ui_story_1016_10160402_34_dialog_content = "정말로 누가 조작한 거였어?",
  ui_story_1016_10160402_35_dialog_content = "응, 그로누가 전투 시뮬레이터를 검사해 봤는데,\n인위적으로 수정된 데이터가 있었대.",
  ui_story_1016_10160402_36_dialog_content = "하지만 누가 그런 건지는 아직 확인되지 않았대.",
  ui_story_1016_10160402_37_dialog_content = "대체 목적이 뭘까...",
  ui_story_1016_10160402_38_dialog_content = "전투 시뮬레이터에서 일어난 일이 현실에 영향을 미치진 않아.",
  ui_story_1016_10160402_39_dialog_content = "그렇다면 그런 일을 하는 의미는... 우리가 학점을 따는 걸 방해하는 것밖에 없어.",
  ui_story_1016_10160402_40_dialog_content = "응, 그러면 확실히 말이 되지.",
  ui_story_1016_10160402_41_dialog_content = "학점 경쟁 때문에 이런 짓을 했다면, 범인도 후보생이겠지?",
  ui_story_1016_10160402_42_dialog_content = "그럴 가능성이 커. 경쟁이 나쁜 방향으로 빠지는 건 흔한 일이야.",
  ui_story_1016_10160402_43_dialog_content = "예전의 훈련에서도 백야성과 일루미나 후보생들 사이엔 갈등이 자주 있었어.",
  ui_story_1016_10160402_44_dialog_content = "그렇게 보면 연합 훈련은 사실 각 세력 간 경쟁의 축소판 같은 거잖아.",
  ui_story_1016_10160402_45_dialog_content = "근데 왜 우리가 공격의 대상이 됐을까?",
  ui_story_1016_10160402_46_dialog_content = "난 아이테르고, 카렌은 백야성, 바이스는 일루미나에 속해 있어.",
  ui_story_1016_10160402_47_dialog_content = "아무리 생각해도 각 세력 간 경쟁이랑 우리 팀은 상관이 없잖아?",
  ui_story_1016_10160402_48_dialog_content = "우릴 노린 게 아니었을 거야.",
  ui_story_1016_10160402_49_dialog_content = "우린 전투 시뮬레이터 사용 허가를 임시로 받았어.",
  ui_story_1016_10160402_50_dialog_content = "상대가 미리 조작을 했다면 우리가 쓸 줄은 몰랐을 가능성이 높아.",
  ui_story_1016_10160402_51_dialog_content = "그럼 실제로 노린 건...",
  ui_story_1016_10160402_52_dialog_content = "시간표를 보면 전투 시뮬레이터를 예약했던 건 레오 팀이었어.",
  ui_story_1016_10160402_53_dialog_content = "아! 그럼 앞뒤가 맞겠네!",
  ui_story_1016_10160402_54_dialog_content = "레오 팀은 1위니까 모두가 노리고 있을 거잖아!",
  ui_story_1016_10160402_55_dialog_content = "응, 나도 그 가능성이 가장 높다고 생각해.",
  ui_story_1016_10160402_56_dialog_content = "됐어, 일단은 우리 문제부터 생각해야지.",
  ui_story_1016_10160402_57_dialog_content = "남들이 뭘 하든 우리가 어떻게 할 수 있는 건 우리 자신뿐이야.",
  ui_story_1016_10160402_58_dialog_content = "내일 계획을 논의해 보자.",
  ui_story_1016_10160402_59_dialog_content = "응!",
  ui_story_1016_10160402_60_dialog_content = "아하하하! 재미있어! 완전 신나!",
  ui_story_1016_10160402_61_dialog_content = "디시스, 너 전투 시뮬레이터까지 만질 줄 알았구나!",
  ui_story_1016_10160402_62_dialog_content = "이제 막 배웠습니다.",
  ui_story_1016_10160402_63_dialog_content = "훈련 기간에는 평소에 보기 힘든 책도 읽을 수 있습니다.\n당신들도 읽어보면 좋을 겁니다.",
  ui_story_1016_10160402_64_dialog_content = "지식을 얻을 기회는 언제나 있는 것이 아닙니다.",
  ui_story_1016_10160402_65_dialog_content = "에이, 무슨 장님이 맨날 책 얘기만 해? 듣기 싫어!",
  ui_story_1016_10160402_66_dialog_content = "메리, 내일도 장난 치러 가자.",
  ui_story_1016_10160402_67_dialog_content = "봐, 쟤들 이제 서로를 의심하기 시작했어! 너무 재밌어~",
  ui_story_1016_10160402_68_dialog_content = "들키지 않게 조심해. 다들 슬슬 화를 낼 거야.",
  ui_story_1016_10160402_69_dialog_content = "괜찮아 괜찮아! 일루미나는 백야성을 의심하고, 백야성은 일루미나를 의심하니까.",
  ui_story_1016_10160402_70_dialog_content = "우리처럼 점수도 낮고 입장도 확실하지 않은 팀은 의심받을 리가 없다구.",
  ui_story_1016_10160402_71_dialog_content = "그 문제라면 저도 민치의 뜻에 동의합니다.",
  ui_story_1016_10160402_72_dialog_content = "이성이란 일종의 족쇄입니다.\n사람들이 모든 사물에 의미를 찾고 사고하도록 만들지요.",
  ui_story_1016_10160402_73_dialog_content = "아, 또 시작이네...",
  ui_story_1016_10160402_74_dialog_content = "그러나 저들은 그러한 사고가 편협하다는 것을 깨닫지 못합니다.",
  ui_story_1016_10160402_75_dialog_content = "작고 하찮은 우린 사실 무엇을 하든 무의미합니다.",
  ui_story_1016_10160402_76_dialog_content = "그것을 깨닫지 못하는 한, 아무 이유 없는 악의를 파악할 순 없습니다.",
  ui_story_1016_10160402_77_dialog_content = "그러니 안심하고 계속하십시오, 민치.",
  ui_story_1016_10160402_78_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_1016_10160402_79_dialog_content = "두 사람...",
  ui_story_1016_10160402_80_dialog_content = "휴, 또 저만 두고 가버렸군요.",
  ui_story_1016_10160402_81_dialog_content = "좋습니다. 저 혼자 숙소로 돌아가겠습니다. 숙소 쪽 방향은 그러니까...",
  ui_story_1016_10160402_82_dialog_content = "음?",
  ui_story_1016_10160501_1_dialog_content = "암귀의 흔적을 발견했다! 어서 지원 요청해!",
  ui_story_1016_10160501_2_dialog_content = "한 마리도 놓쳐선 안 돼!",
  ui_story_1016_10160501_3_dialog_content = "보초병이 이미 레이스 군단장님께 알렸어. 일단 우리끼리 쫓아가자!",
  ui_story_1016_10160501_4_dialog_content = "그래...",
  ui_story_1016_10160501_5_dialog_content = "거기 당신, 여기서 뭘 멍하니 서 있는 겁니까?\n앞에 암귀가 나타났다는 소리 못 들었습니까?",
  ui_story_1016_10160501_6_dialog_content = "죄송합니다. 저는 눈이...",
  ui_story_1016_10160501_7_dialog_content = "아! 눈이 안 보이시는 거군요!",
  ui_story_1016_10160501_8_dialog_content = "아, 그런 이유가... 미안합니다.",
  ui_story_1016_10160501_9_dialog_content = "지금은 긴급 상황이라서 당신을 바래다줄 순 없습니다.",
  ui_story_1016_10160501_10_dialog_content = "먼저 근처에 피해 있으세요. 여긴 일단은 안전할 겁니다.",
  ui_story_1016_10160501_11_dialog_content = "괜찮습니다. 절 신경 쓰실 필요는 없습니다.",
  ui_story_1016_10160501_12_dialog_content = "긴급 상황이라면 어서 가 보십시오.",
  ui_story_1016_10160501_13_dialog_content = "...그럼 먼저 가겠습니다. 조심하세요.",
  ui_story_1016_10160501_14_dialog_content = "가자, 어서 쫓아가!",
  ui_story_1016_10160501_15_dialog_content = "그래!",
  ui_story_1016_10160501_16_dialog_content = "자난성에 암귀라니...",
  ui_story_1016_10160501_17_dialog_content = "우리보다 더 장난을 잘 치는 녀석이 있는 모양이군요.",
  ui_story_1016_10160501_18_dialog_content = "<color=#e8d9bb>타탁... 타탁... 타탁...</color>",
  ui_story_1016_10160501_19_dialog_content = "바로 저 앞이다! 서둘러!",
  ui_story_1016_10160501_20_dialog_content = "이제 곧...",
  ui_story_1016_10160501_21_dialog_content = "조심해!",
  ui_story_1016_10160501_22_dialog_content = "<anim type=Shake><size=50>그어어어!</size></anim>",
  ui_story_1016_10160501_23_dialog_content = "뭐야?! 갑자기 전부 돌아보다니...",
  ui_story_1016_10160501_24_dialog_content = "이런, 이 수라면 우리가 감당하기 힘들겠어...",
  ui_story_1016_10160501_25_dialog_content = "어쩔 수 없지. 여기서 싸우는 수밖에.",
  ui_story_1016_10160501_26_dialog_content = "지원 병력이 도착할 때까진 버텨야 할 텐데...",
  ui_story_1016_10160501_27_dialog_content = "이봐, 그렇게 비장하게 굴 필요가 있나? 여긴 자난성이잖아.",
  ui_story_1016_10160501_28_dialog_content = "다, 당신 누구야?!",
  ui_story_1016_10160501_29_dialog_content = "지나가던 마음씨 좋은 사람이라고 해 두자고.",
  ui_story_1016_10160501_30_dialog_content = "엄청난 실력이다...",
  ui_story_1016_10160501_31_dialog_content = "가, 감사합니다!",
  ui_story_1016_10160501_32_dialog_content = "감사는 이쪽한테 해야지. 이쪽이 매일 산책하는 버릇이 있는 덕분인 줄 알아.",
  ui_story_1016_10160501_33_dialog_content = "지금 소규모의 적에게 포위 섬멸 전략을 쓰고 있었던 겁니까?",
  ui_story_1016_10160501_34_dialog_content = "전술적 소양이 너무 떨어지는군요.\n비효율적일 뿐만 아니라 병력 손실의 가능성도 높습니다.",
  ui_story_1016_10160501_35_dialog_content = "이 일이 알려지면 웃음거리가 될 겁니다.",
  ui_story_1016_10160501_36_dialog_content = "그 말씀은...",
  ui_story_1016_10160501_37_dialog_content = "(복장을 봐서는 우리 측 장교인 것 같은데...)",
  ui_story_1016_10160501_38_dialog_content = "(왜 백야성에서 온 것처럼 보이는 사람이랑 같이 있는 거지?)",
  ui_story_1016_10160501_39_dialog_content = "주변에 동원할 수 있는 부대가 얼마나 더 있습니까?",
  ui_story_1016_10160501_40_dialog_content = "지휘권을 제게 주세요. 제가 적을 소탕하도록 하죠.",
  ui_story_1016_10160501_41_dialog_content = "하, 하지만...",
  ui_story_1016_10160501_42_dialog_content = "절차에 맞고 안 맞고는 따지지 마세요. 계속 꾸물거리다간 일을 망칠 겁니다.",
  ui_story_1016_10160501_43_dialog_content = "예!",
  ui_story_1016_10160501_44_dialog_content = "주변 부대에 전달해서 다섯 블록 외곽 입구에 부채꼴의 진을 펼치세요.",
  ui_story_1016_10160501_45_dialog_content = "우린 추격 속도를 조금 줄이고 진형이 완성되길 기다리죠.",
  ui_story_1016_10160501_46_dialog_content = "기억하세요. 전투는 단순한 힘겨루기가 아닙니다.",
  ui_story_1016_10160501_47_dialog_content = "낚시를 할때 손을 뻗는다고 물고기를 잡을 순 없는 것처럼 말이죠.\n물고기가 그물로 들어오게 만들어야 하는 겁니다.",
  ui_story_1016_10160502_1_dialog_content = "암귀 무리? 대체 어디서 나타난 거지?",
  ui_story_1016_10160502_2_dialog_content = "아직 확인되지 않았습니다. 지금 출몰 경로를 조사하는 중입니다.",
  ui_story_1016_10160502_3_dialog_content = "다만 시기상으로 보면 자난성에 잠복 중인 노라와 관계가 있지 않겠습니까?",
  ui_story_1016_10160502_4_dialog_content = "노라랑 연관이 있다는 것 정도는 당연히 알지.\n문제는 노라가 어떻게 했냐는 거야.",
  ui_story_1016_10160502_5_dialog_content = "최근 순찰 범위도 넓혔고, 횟수도 계속 조정 중이었어.",
  ui_story_1016_10160502_6_dialog_content = "하지만 내가 받은 보고에선 노라의 머리카락 한 올도 발견되지 않았다고 했어.",
  ui_story_1016_10160502_7_dialog_content = "그건... 노라가 그만큼 몸을 잘 숨긴 건 아닐까요?",
  ui_story_1016_10160502_8_dialog_content = "물론 가능성은 있어. 하지만 그렇게 단순한 문제는 아닐 것 같아.",
  ui_story_1016_10160502_9_dialog_content = "요즘 자난성은 뭔가 이상하다는 느낌이 자꾸 든단 말이야...",
  ui_story_1016_10160502_10_dialog_content = "군단장님, 방금 들어온 보고입니다!",
  ui_story_1016_10160502_11_dialog_content = "현재 주변 부대가 합동으로 적을 포위 공격하고 있습니다.",
  ui_story_1016_10160502_12_dialog_content = "포위 공격? 규모는? 구체적인 장소는?",
  ui_story_1016_10160502_13_dialog_content = "내가 명령도 안 내렸는데, 대체 누가 멋대로 내 부대를 움직인 거야?!",
  ui_story_1016_10160502_14_dialog_content = "자세한 상황은 아직 모르겠습니다...",
  ui_story_1016_10160502_15_dialog_content = "가서 알아봐!",
  ui_story_1016_10160502_16_dialog_content = "내 소장 계급장이 멀쩡히 붙어 있는데, 누가 나 대신 지휘를 한다는 거야?!",
  ui_story_1016_10160502_17_dialog_content = "구, 군단장님! 새로운 보고가 들어왔습니다!",
  ui_story_1016_10160502_18_dialog_content = "자난성에 침입한 암귀 무리는 이미 전멸했습니다!",
  ui_story_1016_10160502_19_dialog_content = "<size=50>뭐라고?!</size>",
  ui_story_1016_10160502_20_dialog_content = "확실해?",
  ui_story_1016_10160502_21_dialog_content = "예, 주변엔 이미 암귀의 흔적이 없습니다.",
  ui_story_1016_10160502_22_dialog_content = "대처가 이렇게 빠르다고...?",
  ui_story_1016_10160502_23_dialog_content = "흥, 재미있네.",
  ui_story_1016_10160502_24_dialog_content = "오늘 누구 덕을 본 건지 한번 봐야겠어.",
  ui_story_1016_10160502_25_dialog_content = "좋아, 이걸로 해결이군.",
  ui_story_1016_10160502_26_dialog_content = "그럼 뒷처리는 맡길 테니 우린 먼저 실례하지.",
  ui_story_1016_10160502_27_dialog_content = "그리고 제가 임시로 지휘를 한 건 보고하지 않는 편이 좋을 겁니다.",
  ui_story_1016_10160502_28_dialog_content = "안 그러면 다들 여러 가지로 귀찮아질 테니까요...",
  ui_story_1016_10160502_29_dialog_content = "왜 보고를 안 해?\n암귀를 없애고 소란을 수습했으면 좋은 일 아냐?",
  ui_story_1016_10160502_30_dialog_content = "내가 「참 잘했어요」 훈장도 신청해 주려고 했는데.",
  ui_story_1016_10160502_31_dialog_content = "레이스 교관님...",
  ui_story_1016_10160502_32_dialog_content = "지금은 수업 중이 아니니까 「교관」이라고 안 불러도 돼.\n서로 군인 대 군인으로 대하자고.",
  ui_story_1016_10160502_33_dialog_content = "죄송합니다. 멋대로 부대를 움직이는 월권행위를 저지르고 말았습니다.",
  ui_story_1016_10160502_34_dialog_content = "처벌은 감수하겠습니다.",
  ui_story_1016_10160502_35_dialog_content = "음...난 처벌보단 「참 잘했어요 훈장」이 더 좋은데 말이지.",
  ui_story_1016_10160502_36_dialog_content = "됐어, 처벌 같은 소린 넣어둬.",
  ui_story_1016_10160502_37_dialog_content = "제때 와서 도움도 줬고, 전투도 효율적으로 치렀는데, 이만한 공적이 어디 있겠어.",
  ui_story_1016_10160502_38_dialog_content = "난 공을 세운 사람한테 벌을 줄 만큼 꽉 막힌 사람은 아냐.",
  ui_story_1016_10160502_39_dialog_content = "이해해 주셔서 감사합니다.",
  ui_story_1016_10160502_40_dialog_content = "너희 전술적 소양은 칭찬받아 마땅해. 결단력도 있었고.",
  ui_story_1016_10160502_41_dialog_content = "오늘 소란을 이만큼 완벽하게 해결할 수 있는 건 아마 너희들뿐이었을지도 몰라.",
  ui_story_1016_10160502_42_dialog_content = "분명 전란이 계속되는 변방의 환경이 그런 능력을 길러낸 거겠지.",
  ui_story_1016_10160502_43_dialog_content = "더 실용주의적인 사고방식까지 가지고 있고 말이야.",
  ui_story_1016_10160502_44_dialog_content = "난 너희 생각에 문제가 있다고 여기진 않아.\n전장에서 필요한 건 그런 결단력이니까.",
  ui_story_1016_10160502_45_dialog_content = "하지만 자난성에선 제도나 규칙이 더 높은 가치를 가지고 있어.",
  ui_story_1016_10160502_46_dialog_content = "나도 그 점을 배우는 데 시간이 많이 걸렸어. 너희도 잘 생각해 봤으면 좋겠어.",
  ui_story_1016_10160502_47_dialog_content = "제도와 규칙 말입니까...",
  ui_story_1016_10160502_48_dialog_content = "제도와 규칙을 통해 체제의 안정을 유지할 수 있기 때문입니까?",
  ui_story_1016_10160502_49_dialog_content = "맞아, 안정은 중요해.",
  ui_story_1016_10160502_50_dialog_content = "외력에 의해 쓰러지지 않을 뿐만 아니라,\n내부로부터의 붕괴도 막을 수 있어야 하니까.",
  ui_story_1016_10160502_51_dialog_content = "그런 안정을 지키기 위해 때로는 부분적인 승리를 희생해야 할 때도 있어.",
  ui_story_1016_10160502_52_dialog_content = "그렇군요. 이해했습니다.",
  ui_story_1016_10160502_53_dialog_content = "가르침에 감사드립니다.",
  ui_story_1016_10160502_54_dialog_content = "만약 너희도 변방을 떠나는 날이 온다면, 그 점을 확실히 알아두는 게 중요해.",
  ui_story_1016_10160502_55_dialog_content = "자, 그럼 먼저 돌아가.",
  ui_story_1016_10160502_56_dialog_content = "내일은 내 수업이니까, 지각하지 마.",
  ui_story_1016_10160502_57_dialog_content = "예!",
  ui_story_1016_10160502_58_dialog_content = "...만약 그 안정된 체제 자체가 왜곡된 것이었다면?",
  ui_story_1016_10160502_59_dialog_content = "뭐라고?",
  ui_story_1016_10160502_60_dialog_content = "만약 제도와 규칙을 기초로 세워진 건물이 언젠가는 쓰러질 사탑이라면...",
  ui_story_1016_10160502_61_dialog_content = "우리가 그걸 위해 치른 희생은 그저 우스운 꼴이 되겠지.",
  ui_story_1016_10160502_62_dialog_content = "그 말은 넌 지금의 「건물」에 불만이 있는 모양이네.",
  ui_story_1016_10160502_63_dialog_content = "우리가 왜 이 훈련에 참가했는지 알고 있나?",
  ui_story_1016_10160502_64_dialog_content = "지금 지도의 가장 끝에 있는 변방 지역, 어둠의 밑바닥엔 암귀들이 집결하고 있다.",
  ui_story_1016_10160502_65_dialog_content = "집결한 암귀들이 언제 방어선을 공격해 와도 이상하지 않은 상황이지.",
  ui_story_1016_10160502_66_dialog_content = "하지만 우리가 보낸 지원 요청에는 지금까지도 아무 답이 없었다.",
  ui_story_1016_10160502_67_dialog_content = "우리가 더스크 타운을 계속 지킨다면, 그건 「체제의 안정」을 유지하는 셈인가?",
  ui_story_1016_10160502_68_dialog_content = "아니면 그 변방이 사실은 희생되어야 할 「부분적」인 것인가?",
  ui_story_1016_10160502_69_dialog_content = "...변방에서 그런 큰일이 있었다고?",
  ui_story_1016_10160502_70_dialog_content = "역시 내 추측대로 모르고 있었군.",
  ui_story_1016_10160502_71_dialog_content = "지휘권을 가진 다른 군단장들도 아마 마찬가지겠지.",
  ui_story_1016_10160502_72_dialog_content = "미안하군. 얘기가 길어졌네.",
  ui_story_1016_10160502_73_dialog_content = "......",
  ui_story_1016_10160502_74_dialog_content = "이만 돌아가도 좋아.",
  ui_story_1016_10160502_75_dialog_content = "지금 그 이야기는 내가 확실하게 알아볼 테니까.",
  ui_story_1016_10160502_76_dialog_content = "그래.",
  ui_story_1016_10160502_77_dialog_content = "(그런 중대한 일을 내가 전혀 모르고 있었다니.)",
  ui_story_1016_10160502_78_dialog_content = "(라인하르트, 대체 뭘 하고 있는 거야?)",
  ui_story_1016_10160502_79_dialog_content = "(아니면, 너조차 손을 쓸 수 없는 건가...)",
  ui_story_1016_10160502_80_dialog_content = "드니에르.",
  ui_story_1016_10160502_81_dialog_content = "드니에르!",
  ui_story_1016_10160502_82_dialog_content = "...미안, 잠깐 다른 생각 중이었어.",
  ui_story_1016_10160502_83_dialog_content = "상황이... 많이 안 좋은가?",
  ui_story_1016_10160502_84_dialog_content = "안색이... 좋지 않네.",
  ui_story_1016_10160502_85_dialog_content = "자난성에 잠복시켜 놓은 암귀가 전부 쓰러졌어.",
  ui_story_1016_10160502_86_dialog_content = "이번 지휘관, 꽤 대단한 녀석이었어.\n내가 반응할 시간조차 주지 않을 정도였거든.",
  ui_story_1016_10160502_87_dialog_content = "그럼 우린 이제... 다른 방법이 없는 건가?",
  ui_story_1016_10160502_88_dialog_content = "팬텀이 오기 전까진 그렇겠지.",
  ui_story_1016_10160502_89_dialog_content = "우리 판돈을 전부 그들에게 거는 건 좋지 않아.",
  ui_story_1016_10160502_90_dialog_content = "이건 내기가 아니라 거래야.",
  ui_story_1016_10160502_91_dialog_content = "내가 가진 연구 성과로 우리 목숨과 맞바꾸는 거지.",
  ui_story_1016_10160601_1_dialog_content = "<color=#e8d9bb>며칠 뒤, 교육 단계가 끝나갈 무렵</color>",
  ui_story_1016_10160601_2_dialog_content = "어때! 우리 순위는?",
  ui_story_1016_10160601_3_dialog_content = "어디 보자──",
  ui_story_1016_10160601_4_dialog_content = "2등이야! 우리가 2등이 됐어!",
  ui_story_1016_10160601_5_dialog_content = "좋아! 드디어 해냈네!",
  ui_story_1016_10160601_6_dialog_content = "<color=#e8d9bb>띠리링──</color>",
  ui_story_1016_10160601_7_dialog_content = "자, 얼른 앉자. 오늘은 모범생답게!",
  ui_story_1016_10160601_8_dialog_content = "그래, 이번이 마지막 수업이니까.",
  ui_story_1016_10160601_9_dialog_content = "여러분, 안녕하세요!",
  ui_story_1016_10160601_10_dialog_content = "아시다시피 오늘이 연합 훈련 교육 단계의 마지막 수업이에요.",
  ui_story_1016_10160601_11_dialog_content = "이제 여러분은 실전 심사를 위한 준비를 해야 해요.\n심사에서는 마지막 승자의 자리를 두고 경쟁을 벌이게 되겠죠.",
  ui_story_1016_10160601_12_dialog_content = "그리고 교육 단계에서 쌓은 학점이 이번 단계에서 도움이 될 거예요.",
  ui_story_1016_10160601_13_dialog_content = "학점 획득 상황은 순위를 보면 확인할 수 있어요.",
  ui_story_1016_10160601_14_dialog_content = "레오 팀이 압도적인 차이로 1위네요.",
  ui_story_1016_10160601_15_dialog_content = "이거 영광이네.",
  ui_story_1016_10160601_16_dialog_content = "PlayerName 팀은 후반에 추격해서 2위를 차지했어요.",
  ui_story_1016_10160601_17_dialog_content = "힘들었어...",
  ui_story_1016_10160601_18_dialog_content = "잉겔 팀은 안정적인 성적으로 3위에 안착했네요.",
  ui_story_1016_10160601_19_dialog_content = "감사합니다.",
  ui_story_1016_10160601_20_dialog_content = "나머지 순위는 직접 확인해 주세요.",
  ui_story_1016_10160601_21_dialog_content = "그럼 수업 이야기를 마저 할까요? 오늘은 마지막 수업이니까,\n우린 여러분에게 심사 단계를 위한 워밍업 시간을 주려고 해요.",
  ui_story_1016_10160601_22_dialog_content = "따라서 이번 수업 내용은 실전이에요.",
  ui_story_1016_10160601_23_dialog_content = "실전? 저번 실전 격투 수업이랑 무슨 차이인데?",
  ui_story_1016_10160601_24_dialog_content = "여러분의 상대가 되는 적이 달라요.",
  ui_story_1016_10160601_25_dialog_content = "지금까지의 수업에선 안전을 고려해서, 여러분이 실제 위협과 마주하게 하진 않았어요.",
  ui_story_1016_10160601_26_dialog_content = "그래서 격투 수업이든 전장 시뮬레이터 내 환경이든 실제 피해를 입지는 않았죠.",
  ui_story_1016_10160601_27_dialog_content = "하지만 이어질 심사 단계에서는 누구도 여러분의 안전을 보장해 주지 않아요.",
  ui_story_1016_10160601_28_dialog_content = "이제부터는 여러분이 실제 암귀에 맞설 준비가 되어 있는지 확인해 볼 거예요.",
  ui_story_1016_10160601_29_dialog_content = "실제 암귀? 이 교실에서?",
  ui_story_1016_10160601_30_dialog_content = "일루미나 생화학 연구소에서 여러분에게 귀중한 「훈련용 샘플」을 제공했어요.",
  ui_story_1016_10160601_31_dialog_content = "그럼 후보생 여러분, 준비해 주세요.",
  ui_story_1016_10160601_32_dialog_content = "<color=#e8d9bb>쾅──</color>",
  ui_story_1016_10160601_33_dialog_content = "으앗! 암귀가 저렇게 많다고?",
  ui_story_1016_10160601_34_dialog_content = "일루미나의 생화학 연구소는 암귀를 연구하고 있는 건가...?\n너무 막 나가는 거 아냐?",
  ui_story_1016_10160601_35_dialog_content = "전장에서 가장 잘 알아야 하는 건 그 무엇도 아닌 적이에요.",
  ui_story_1016_10160601_36_dialog_content = "암귀를 연구함으로써 얻는 게 뭐라고 생각하죠?\n바로 우리 병사들의 목숨이에요.",
  ui_story_1016_10160601_37_dialog_content = "하지만...",
  ui_story_1016_10160601_38_dialog_content = "안심하세요. 이 암귀들은 통제 가능한 범위 내에 있으니까요.",
  ui_story_1016_10160601_39_dialog_content = "여러분, 이 수업에는 불필요한 규칙이 없어요.",
  ui_story_1016_10160601_40_dialog_content = "모든 수단을 동원해 암귀를 쓰러트리세요.",
  ui_story_1016_10160601_41_dialog_content = "<anim type=Shake><size=50>그어어어!</size></anim>",
  ui_story_1016_10160601_42_dialog_content = "벌써 시작이야?!",
  ui_story_1016_10160601_43_dialog_content = "아직 준비도 안 됐는데...",
  ui_story_1016_10160601_44_dialog_content = "PlayerName, 위험해!",
  ui_story_1016_10160601_45_dialog_content = "아, 미안! 잠깐 다른 생각 중이었어!",
  ui_story_1016_10160601_46_dialog_content = "싸우면서 다른 팀도 관찰해 보자.",
  ui_story_1016_10160601_47_dialog_content = "각 팀의 실력을 확인할 수 있는 좋은 기회니까.",
  ui_story_1016_10160601_48_dialog_content = "악셀리아, 당신은 최대한 나서지 마세요.",
  ui_story_1016_10160601_49_dialog_content = "저와 아나톨리에게 맡기세요.",
  ui_story_1016_10160601_50_dialog_content = "그래도 괜찮습니까?",
  ui_story_1016_10160601_51_dialog_content = "수업일 뿐이에요. 큰 위험은 없을 거예요.",
  ui_story_1016_10160601_52_dialog_content = "그리고 다른 팀도 있으니까요.",
  ui_story_1016_10160601_53_dialog_content = "그렇긴 한데...",
  ui_story_1016_10160601_54_dialog_content = "다른 사람들도 그다지 힘을 내지 않는 것 같습니다만.",
  ui_story_1016_10160601_55_dialog_content = "우라이아 씨, 내 왼쪽을 지원해 줘!",
  ui_story_1016_10160601_56_dialog_content = "알겠어요!",
  ui_story_1016_10160601_57_dialog_content = "안 돼... 다른 방향에서 또 밀려오고 있어...",
  ui_story_1016_10160601_58_dialog_content = "크로이!",
  ui_story_1016_10160601_59_dialog_content = "이쪽은 벗어날 수가 없어요!",
  ui_story_1016_10160601_60_dialog_content = "어떻게 된 거야? 왜 주변에 아군이 전혀 없는 건데?!",
  ui_story_1016_10160601_61_dialog_content = "우리 언제 선두가 된 거야?",
  ui_story_1016_10160601_62_dialog_content = "다른 사람들이 후퇴해서 그런 것 같아요...",
  ui_story_1016_10160601_63_dialog_content = "하아?!",
  ui_story_1016_10160601_64_dialog_content = "순위에서는 하나같이 대단하더니, 진짜로 싸우니까 다 어디 간 거야?!",
  ui_story_1016_10160601_65_dialog_content = "우리도 고전 중이야. 남 챙길 여력이 없다고.",
  ui_story_1016_10160601_66_dialog_content = "칼도 안 뽑았으면서 뭘 고전 중이라는 거야?!",
  ui_story_1016_10160601_67_dialog_content = "아무래도 다들 힘을 아끼고 있는 것 같네...",
  ui_story_1016_10160601_68_dialog_content = "그럴 만하지. 마지막 수업이잖아.\n다들 진짜 실력은 심사 때 발휘하려는 생각일 거야.",
  ui_story_1016_10160601_69_dialog_content = "하지만 이대로 가다간 암귀를 못 이길 것 같은데...",
  ui_story_1016_10160601_70_dialog_content = "전력을 다하고 싶지 않다면 다 같이 협력하면 돼!",
  ui_story_1016_10160601_71_dialog_content = "적이 그렇게 강한 것도 아니잖아.\n다 같이 협력만 잘하면 조금씩만 힘을 써도 이길 수 있을 거야!",
  ui_story_1016_10160601_72_dialog_content = "호오, 꽤 좋은 제안이네.",
  ui_story_1016_10160601_73_dialog_content = "다른 지역 사람들과 함께 싸우는 것도 한번 해보고는 싶었으니까.",
  ui_story_1016_10160601_74_dialog_content = "그렇습니다. 마지막 수업이니 경쟁할 것도 없지 않습니까.\n함께 사소한 문제를 해결한다고 생각하면 되는 겁니다.",
  ui_story_1016_10160601_75_dialog_content = "우리도 찬성이야! 그러니까 빨리 도와줘!",
  ui_story_1016_10160601_76_dialog_content = "재밌겠다~ 민치도 할래!",
  ui_story_1016_10160601_77_dialog_content = "좋아! 그럼 다 같이 싸우는 거야!",
  ui_story_1016_10160601_78_dialog_content = "전열을 전진시켜서 베르타 팀을 포위에서 구하자!",
  ui_story_1016_10160602_1_dialog_content = "훌륭해요! 암귀를 모두 쓰러트렸네요!",
  ui_story_1016_10160602_2_dialog_content = "축하해요. 여러분은 이번 연합 훈련의 마지막 수업을 무사히 마쳤어요.",
  ui_story_1016_10160602_3_dialog_content = "더 치열한 전투가 펼쳐질 줄 알았는데, 마지막엔 모두가 힘을 합칠 줄은 몰랐네요.",
  ui_story_1016_10160602_4_dialog_content = "각자 의도가 있는 협력이긴 했지만... 아하하...",
  ui_story_1016_10160602_5_dialog_content = "그럼 이것으로 본 교육 단계를 종료합니다!\n해산 전에 심사 단계의 내용을 설명해 줄게요.",
  ui_story_1016_10160602_6_dialog_content = "아마 다들 많이 궁금해하고 있을 테니까요.",
  ui_story_1016_10160602_7_dialog_content = "이번 심사 장소는 어느 폐기된 지하성이에요.",
  ui_story_1016_10160602_8_dialog_content = "그 지하성은 방어선 끝자락에 있고, 이미 암귀에게 점령당했어요.\n주변 일대는 오랫동안 오로리안의 활동 흔적이 없었죠.",
  ui_story_1016_10160602_9_dialog_content = "여러분이 해야 할 일은 그 지하성에 가서,\n우리가 사전에 두고 온 깃발을 찾고 쟁탈하는 거예요.",
  ui_story_1016_10160602_10_dialog_content = "규칙은 매우 간단해요. 그 깃발을 얻는 사람이 이번 훈련의 우승자가 되고,\n대원수와의 대결 기회를 얻을 수 있어요.",
  ui_story_1016_10160602_11_dialog_content = "목표를 달성하기 위한 수단에는 어떤 제한도 없어요.",
  ui_story_1016_10160602_12_dialog_content = "후보생들의 안전도 보장되나요?",
  ui_story_1016_10160602_13_dialog_content = "보장되지 않는다고 생각하는 게 좋을 거예요.",
  ui_story_1016_10160602_14_dialog_content = "심사를 통해 여러분의 전투 잠재력을 끌어낼 수 있도록,\n난이도와 위험도는 모두 높게 설정되어 있어요.",
  ui_story_1016_10160602_15_dialog_content = "수업에서 좋은 성적을 거뒀다고 해서 심사도 순조로울 거라 생각하면 안 돼요.\n실전과 훈련은 어디까지나 별개니까요.",
  ui_story_1016_10160602_16_dialog_content = "심사 중엔 교관들도 다양한 방법으로 여러분의 행동을 관찰할 거예요.",
  ui_story_1016_10160602_17_dialog_content = "만약 학생들 간에 악성 상해 사건이 발생한다면,\n우린 군사법정에 충분한 증거를 제출할 거예요.",
  ui_story_1016_10160602_18_dialog_content = "하지만 여러분 가까이에서 벌어지는 위험을 우리가 해결해 줄 순 없어요.",
  ui_story_1016_10160602_19_dialog_content = "주최 측이 뭔가를 보장해 줄 거라고는 생각하지 마세요.\n여러분이 의지할 수 있는 건 자기 자신뿐이에요.",
  ui_story_1016_10160602_20_dialog_content = "그렇군요. 이해했어요.",
  ui_story_1016_10160602_21_dialog_content = "그래야지. 누가 뒤에서 지켜주고 있다면 소꿉놀이하는 기분일 것 같거든.",
  ui_story_1016_10160602_22_dialog_content = "그리고 다음은 심사 전 준비 절차예요.",
  ui_story_1016_10160602_23_dialog_content = "심사의 공정성을 지키기 위해, 여러분은 자신의 전투 수행을 보장하는\n기본적인 장비만 사용할 수 있어요.",
  ui_story_1016_10160602_24_dialog_content = "그 외에 추가적인 도움이 필요하다면 훈련 단계에서 얻은 학점을 사용해야 해요.",
  ui_story_1016_10160602_25_dialog_content = "오! 열심히 모은 학점을 드디어 쓰는 거구나!",
  ui_story_1016_10160602_26_dialog_content = "맞아요. 내일 제가 여러분을 일루미나 연구소로 데려갈 거예요.\n여러분을 위한 다양한 물자가 거기 준비돼 있어요.",
  ui_story_1016_10160602_27_dialog_content = "전투 능력을 강화할 수 있는 것도 있고, 전투 정보를 제공해 주는 것도 있죠.",
  ui_story_1016_10160602_28_dialog_content = "여러분이 획득한 학점으로 그 물자들을 교환할 수 있어요.",
  ui_story_1016_10160602_29_dialog_content = "즉, 학점이 높은 팀일수록 물자를 더 많이 가지고 우세를 점할 수 있답니다.",
  ui_story_1016_10160602_30_dialog_content = "물자로 약점을 보완할지, 강점을 더 강화할지,\n전투 방법의 선택지를 늘릴지는 여러분 각자의 선택에 달렸어요.",
  ui_story_1016_10160602_31_dialog_content = "음, 우린 어떻게 하지...",
  ui_story_1016_10160602_32_dialog_content = "이제 숙소로 돌아가서 각자 잘 준비해 주세요.\n그리고 내일 아침 교실로 집합하세요.",
  ui_story_1016_10160602_33_dialog_content = "그럼 오늘은 여기까지 할게요. 해산하세요.",
  ui_story_1016_10160602_34_dialog_content = "<color=#e8d9bb>다음 날</color>",
  ui_story_1016_10160602_35_dialog_content = "와아! 장비가 엄청 많네!",
  ui_story_1016_10160602_36_dialog_content = "총검에 총기, 수류탄... 그리고 방호복도 다양하게 있어...",
  ui_story_1016_10160602_37_dialog_content = "으으... 다 갖고 싶어! 이걸 어떻게 골라!",
  ui_story_1016_10160602_38_dialog_content = "정신 차리고 보니까 물자들이 하나같이 비싸잖아?",
  ui_story_1016_10160602_39_dialog_content = "우린 지금 학점 2위인데도 교환할 수 있는 물자가 그렇게 많지가 않아.",
  ui_story_1016_10160602_40_dialog_content = "그렇네. 아마 물자는 일종의 동기부여 역할일 뿐이겠지.\n주최 측도 참가자들이 물자에 너무 의존하는 걸 원하진 않을 거야.",
  ui_story_1016_10160602_41_dialog_content = "우리한테 제일 필요한 걸 골라보자.",
  ui_story_1016_10160602_42_dialog_content = "어디 보자... 우리 팀은 PlayerName의 능력이 있으니까,\n정보 수집 측면에선 상당한 이점이 있어.",
  ui_story_1016_10160602_43_dialog_content = "그럼... 전력을 높일 수 있는 물자로 교환하는 게 좋지 않을까?",
  ui_story_1016_10160602_44_dialog_content = "그렇다면 방어구로 교환하는 게 좋겠어.",
  ui_story_1016_10160602_45_dialog_content = "PlayerName 넌 몸이 우리만큼 강하지 않으니까,\n방어구로 몸을 지킬 수 있다면 우리도 좀 더 안심이 될 거야.",
  ui_story_1016_10160602_46_dialog_content = "어? 학점을 굳이 나한테 쓸 필요는 없는데...",
  ui_story_1016_10160602_47_dialog_content = "나도 그게 제일 좋을 것 같아!",
  ui_story_1016_10160602_48_dialog_content = "PlayerName, 어떤 방호복이 몸에 맞는지 입어 봐.",
  ui_story_1016_10160602_49_dialog_content = "이미 그렇게 정한 거야?!",
  ui_story_1016_10160602_50_dialog_content = "알았어. 너희 발목을 안 잡는 것도 중요하니까...",
  ui_story_1016_10160602_51_dialog_content = "죄다 기계들이잖아...",
  ui_story_1016_10160602_52_dialog_content = "전혀 흥미가 안 생기네. 자오, 네가 골라.",
  ui_story_1016_10160602_53_dialog_content = "그러죠. 이미 생각해 두었습니다.",
  ui_story_1016_10160602_54_dialog_content = "지금 우리에게 가장 중요한 건 정보입니다.",
  ui_story_1016_10160602_55_dialog_content = "선수만 칠 수 있다면, 전투 자체는 우리에게 문제가 되지 않기 때문입니다.",
  ui_story_1016_10160602_56_dialog_content = "그래, 일리가 있네. 무작정 헤매는 건 나도 싫다고.",
  ui_story_1016_10160602_57_dialog_content = "지도로 교환하죠. 그리고 이 통신기도 필요할 겁니다.",
  ui_story_1016_10160602_58_dialog_content = "으윽, 이 통신기는 또 뭐 이리 비싸? 우리 학점의 절반이나 써야 하잖아.",
  ui_story_1016_10160602_59_dialog_content = "설명에 따르면 심사 중에 이 통신기로 장외의 교관과 실시간으로 연락할 수 있다고 합니다.",
  ui_story_1016_10160602_60_dialog_content = "이것보다 더 효율적으로 정보를 수집할 수단은 없을 겁니다.",
  ui_story_1016_10160602_61_dialog_content = "뭐, 좋아. 우리 참모님 뜻에 따라야지.",
  ui_story_1016_10160602_62_dialog_content = "문을 닫아라.",
  ui_story_1016_10160602_63_dialog_content = "네!",
  ui_story_1016_10160602_64_dialog_content = "<color=#e8d9bb>쾅──</color>",
  ui_story_1016_10160602_65_dialog_content = "임무는 잘 알고 있겠지?",
  ui_story_1016_10160602_66_dialog_content = "어떤 대가를 치르더라도 우승해야 한다.",
  ui_story_1016_10160602_67_dialog_content = "이미 두 사람에게 전달했습니다.",
  ui_story_1016_10160602_68_dialog_content = "난 너희 실력을 믿는다.\n하지만 임무 완수를 위해서 소위 말하는 공정성 같은 걸 지킬 필요는 없겠지.",
  ui_story_1016_10160602_69_dialog_content = "너희를 위한 물자는 따로 준비해 두었다.\n학점으로 교환할 수 있는 것보다 더 좋은 것들이다.",
  ui_story_1016_10160602_70_dialog_content = "모두 심사 전 검사를 통과할 수 있도록 되어 있다. 안심하고 가져가라.",
  ui_story_1016_10160602_71_dialog_content = "정보라면 여기 내용이 완전한 지도가 있다. 깃발이 있는 위치도 표기되어 있지.",
  ui_story_1016_10160602_72_dialog_content = "다른 팀처럼 탐색할 필요 없이 목표 지점을 곧바로 향하면 될 거다.",
  ui_story_1016_10160602_73_dialog_content = "그리고 거기 선반에는 전력을 강화할 장비들이 있다. 마음대로 가져가라.",
  ui_story_1016_10160602_74_dialog_content = "(마음대로라... 어떤 것이든 팀의 학점을 다 쓸 만큼의 가치가 있는 것들인데...)",
  ui_story_1016_10160602_75_dialog_content = "(이런 부정행위를 만약 들키기라도 한다면 상부도 체면이 말이 아닐 텐데요.)",
  ui_story_1016_10160602_76_dialog_content = "(위원회는 이렇게까지 연합 훈련 우승을 원하는 겁니까?)",
  ui_story_1016_10160602_77_dialog_content = "내 이야기는 여기까지다. 나머지는 너희에게 맡기마.",
  ui_story_1016_10160602_78_dialog_content = "오늘 날 만난 건 입 밖에 내지 않도록.",
  ui_story_1016_10160602_79_dialog_content = "<color=#e8d9bb>쾅──</color>",
  ui_story_1016_10160602_80_dialog_content = "악셀리아는 「큐빅」이 있습니다. 다른 장비는 필요하지 않습니다.",
  ui_story_1016_10160602_81_dialog_content = "저도 다른 장비는 필요 없어요.\n아나톨리, 골라 보세요.",
  ui_story_1016_10160602_82_dialog_content = "저요?",
  ui_story_1016_10160602_83_dialog_content = "장비는 한 사람에게 집중하는 게 효과적입니다.",
  ui_story_1016_10160602_84_dialog_content = "...알겠습니다. 명령대로 하겠습니다.",
  ui_story_1016_10160602_85_dialog_content = "네, 우린 모두 명령에 따르고 있죠.",
  ui_story_1016_10160602_86_dialog_content = "두 분은 위원회와 접촉이 많으실 테니, 이런 명령에도 익숙하시겠죠.",
  ui_story_1016_10160602_87_dialog_content = "뭔가 할 말이 있는 모양이군요.",
  ui_story_1016_10160602_88_dialog_content = "아닙니다. 그냥 물어본 겁니다.",
  ui_story_1016_10160602_89_dialog_content = "그냥 물어보는 건 정보장교로서 좋은 습관은 아닙니다만.",
  ui_story_1016_10160602_90_dialog_content = "당신이 말한 명령이라면 전 확실히 익숙해요.\n명령에 대한 복종은 절대적인 거예요. 그게 어떤 명령이든 말이죠.",
  ui_story_1016_10160602_91_dialog_content = "네, 알겠습니다...",
  ui_story_1016_10160602_92_dialog_content = "하지만 가끔은 명령과는 다른 생각이 떠오를 때가 있어요.",
  ui_story_1016_10160602_93_dialog_content = "그럴 때 전 생각을 행동 뒤에 숨기곤 해요.",
  ui_story_1016_10160701_1_dialog_content = "<color=#e8d9bb>치익, 치익──</color>",
  ui_story_1016_10160701_2_dialog_content = "자, 자, 다들 내려. 목적지에 도착했어!",
  ui_story_1016_10160701_3_dialog_content = "눈앞에 보이는 저 낡아빠진 지하성이 심사 현장이야.",
  ui_story_1016_10160701_4_dialog_content = "이제 곧 병사들이 각 팀을 각자 출발 지점까지 데려다줄 거야.",
  ui_story_1016_10160701_5_dialog_content = "음, 또 무슨 말을 해야 하더라...",
  ui_story_1016_10160701_6_dialog_content = "아, 맞다. 몸조심하고, 서로 싸우는 건 괜찮지만 죽을 만큼 싸우진 마.",
  ui_story_1016_10160701_7_dialog_content = "나도 몰래 지켜보고 있을 거니까.",
  ui_story_1016_10160701_8_dialog_content = "뭔가 소름 돋는데...",
  ui_story_1016_10160701_9_dialog_content = "자, 병사들. 각 팀을 출발 지점까지 데려다줘.",
  ui_story_1016_10160701_10_dialog_content = "좋은 소식 기다릴게.",
  ui_story_1016_10160701_11_dialog_content = "장비는 다 확인했어?",
  ui_story_1016_10160701_12_dialog_content = "응, 확인했어!",
  ui_story_1016_10160701_13_dialog_content = "화살도 충분해. 암귀들! 각오하라구!",
  ui_story_1016_10160701_14_dialog_content = "그럼 우리가 세운 계획대로 움직이자.",
  ui_story_1016_10160701_15_dialog_content = "다른 팀은 분명히 지도나 다른 정보 수단을 가지고 있을 거야.\n우린 PlayerName의 능력을 사용해서 맞는 팀을 따라가면 돼.",
  ui_story_1016_10160701_16_dialog_content = "응, 지금 찾아보고 있어.",
  ui_story_1016_10160701_17_dialog_content = "근데... 출발 지점이 다들 서로 꽤 떨어져 있어서 아직 못 찾겠어.",
  ui_story_1016_10160701_18_dialog_content = "괜찮아. 일단 안으로 들어가 보자.",
  ui_story_1016_10160701_19_dialog_content = "민치, 대체 뭘 산 거야...",
  ui_story_1016_10160701_20_dialog_content = "재미없어? 봐, 이건 섬광탄이야. 이렇게 던지면──",
  ui_story_1016_10160701_21_dialog_content = "<size=50>으앗!</size>",
  ui_story_1016_10160701_22_dialog_content = "왜 그럽니까? 무슨 일 있습니까?",
  ui_story_1016_10160701_23_dialog_content = "아무것도 아냐. 메리가 놀고 있는 거야.",
  ui_story_1016_10160701_24_dialog_content = "뭐야, 또 울어?",
  ui_story_1016_10160701_25_dialog_content = "너무 눈이 부셔서 눈물이 다 났잖아...",
  ui_story_1016_10160701_26_dialog_content = "민치, 이런 건 사서 어디다 쓰려고?",
  ui_story_1016_10160701_27_dialog_content = "재밌잖아!",
  ui_story_1016_10160701_28_dialog_content = "우린 학점도 얼마 없어서 쓸모 있는 도구는 살 수도 없어.",
  ui_story_1016_10160701_29_dialog_content = "그럼 차라리 재밌는 거나 많이 사는 게 좋잖아?",
  ui_story_1016_10160701_30_dialog_content = "아, 하긴...",
  ui_story_1016_10160701_31_dialog_content = "어차피 우린 우승하러 온 게 아니니까.",
  ui_story_1016_10160701_32_dialog_content = "우승하면 오히려 곤란해질 겁니다.\n우승자는 자기 진영의 깃발을 걸어야 하니까요.",
  ui_story_1016_10160701_33_dialog_content = "우리 어느 진영으로 등록했더라?",
  ui_story_1016_10160701_34_dialog_content = "움브라톤, 난 아직 안 가봤지만.",
  ui_story_1016_10160701_35_dialog_content = "아, 그럼 싫어. 움브라톤 깃발은 너무 못생겼어.",
  ui_story_1016_10160701_36_dialog_content = "그리고 우승하면 그 라인하르트인가 하는 사람이랑 싸워야 한댔잖아. 그런 거 싫거든?",
  ui_story_1016_10160701_37_dialog_content = "디시스라면 싸울 거죠? 우리 팀의 대장이잖아요.",
  ui_story_1016_10160701_38_dialog_content = "저도 관심 없습니다. 체제가 추켜세운 영웅일 뿐이니 말이지요.",
  ui_story_1016_10160701_39_dialog_content = "그것보다 우린 다른 참가자들을 더 주목해야 합니다.",
  ui_story_1016_10160701_40_dialog_content = "우리가 무엇 때문에 왔는지 잊어선 안 됩니다.",
  ui_story_1016_10160701_41_dialog_content = "에이 진짜, 디시스는 너무 진지해. 재미없어.",
  ui_story_1016_10160701_42_dialog_content = "자, 가자. 뭔가 재밌는 거 없나 찾아보자.",
  ui_story_1016_10160701_43_dialog_content = "다른 팀이랑 같이 놀고 싶어!",
  ui_story_1016_10160701_44_dialog_content = "찾았어!",
  ui_story_1016_10160701_45_dialog_content = "음? 어느 팀인데?",
  ui_story_1016_10160701_46_dialog_content = "항상 이상한 짓만 했던 움브라톤 팀이야.",
  ui_story_1016_10160701_47_dialog_content = "거기 대장은... 디시스라고 했었나?",
  ui_story_1016_10160701_48_dialog_content = "기억나. 디시스랑 민치, 그리고 메리.",
  ui_story_1016_10160701_49_dialog_content = "그 사람들 왠지 엄청 불성실한 것 같은 느낌이었는데.",
  ui_story_1016_10160701_50_dialog_content = "지금 엄청 빠르게 지하성 안쪽으로 가고 있어.",
  ui_story_1016_10160701_51_dialog_content = "그럼 단서를 찾았을 가능성이 높은 거 아닐까?",
  ui_story_1016_10160701_52_dialog_content = "응, 빠른 속도로 전진하는 건 명확한 목표가 있기 때문이겠지.",
  ui_story_1016_10160701_53_dialog_content = "어서 쫓아가 보자.",
  ui_story_1016_10160701_54_dialog_content = "쫓아갈 필요 없어. 곧 여길 지나갈 거거든.",
  ui_story_1016_10160701_55_dialog_content = "아, 무슨 소리가 나는데...",
  ui_story_1016_10160701_56_dialog_content = "흐흥~ 나 잡아봐라~",
  ui_story_1016_10160701_57_dialog_content = "민치, 좀 천천히 가세요...",
  ui_story_1016_10160701_58_dialog_content = "잠깐만! 뭔가 이상해!",
  ui_story_1016_10160701_59_dialog_content = "저 사람들 뒤로 암귀가 잔뜩 따라오고 있어!",
  ui_story_1016_10160701_60_dialog_content = "하아?",
  ui_story_1016_10160701_61_dialog_content = "너무 시끄러워서 암귀를 전부 유인해 버렸어!",
  ui_story_1016_10160701_62_dialog_content = "게다가... 저 사람들, 암귀를 쓰러트릴 생각은 없는 것 같아...",
  ui_story_1016_10160701_63_dialog_content = "그냥 암귀를 데리고 달리고 있을 뿐이야.",
  ui_story_1016_10160701_64_dialog_content = "뭐 하는 거야...? 전장을 놀이라고 생각하는 건가?",
  ui_story_1016_10160701_65_dialog_content = "아까 했던 말 정정해야겠어. 저들에게 뚜렷한 목표는 없어.\n어서 가자. 말려들기 전에.",
  ui_story_1016_10160701_66_dialog_content = "나도 같은 생각이야, 근데...",
  ui_story_1016_10160701_67_dialog_content = "곧장 이쪽으로 달려오고 있어!",
  ui_story_1016_10160701_68_dialog_content = "민치, 저 앞에 아이테르 팀이 있어.",
  ui_story_1016_10160701_69_dialog_content = "우와, 아이테르! 재밌는 애잖아, 가서 같이 놀자!",
  ui_story_1016_10160701_70_dialog_content = "<size=50>살려줘! 살려줘! 암귀한테 잡아먹히겠어! 빨리 도와줘!</size>",
  ui_story_1016_10160701_71_dialog_content = "망했다, 들켰어...",
  ui_story_1016_10160701_72_dialog_content = "......",
  ui_story_1016_10160701_73_dialog_content = "잘 들어! 디시스 팀!",
  ui_story_1016_10160701_74_dialog_content = "지금 즉시 돌아서서 전투를 개시해!",
  ui_story_1016_10160701_75_dialog_content = "응? 뭐래, 지금 나한테 명령하는 거야?!",
  ui_story_1016_10160701_76_dialog_content = "그쪽이 방향을 바꿔 싸운다면 우리도 협력하겠다.",
  ui_story_1016_10160701_77_dialog_content = "하지만 계속 달린다면 우린 너흴 공격하겠다.",
  ui_story_1016_10160701_78_dialog_content = "쟤들을 공격한다고?!",
  ui_story_1016_10160701_79_dialog_content = "우리가 주도권을 잡으려면 어쩔 수 없어.",
  ui_story_1016_10160701_80_dialog_content = "에이, 그렇게 적대할 거 없잖아. 민치는 그냥 같이 놀고 싶을 뿐인걸.",
  ui_story_1016_10160701_81_dialog_content = "그럼 그 말대로 할게. 우리 협력하자!",
  ui_story_1016_10160701_82_dialog_content = "메리, 되돌아서 암귀를 끝장내자!",
  ui_story_1016_10160701_83_dialog_content = "계속 그러고 싶었던 참이야!",
  ui_story_1016_10160701_84_dialog_content = "싸우기 시작했어, 우리도 가자!",
  ui_story_1016_10160701_85_dialog_content = "응! 속전속결이야!",
  ui_story_1016_10160802_1_dialog_content = "<anim type=Shake>크에엑...</anim>",
  ui_story_1016_10160802_2_dialog_content = "후후, 생각보다 쉽잖아~",
  ui_story_1016_10160802_3_dialog_content = "하지만 다른 팀은 전부 우리보다 앞서 있어.",
  ui_story_1016_10160802_4_dialog_content = "에휴, 계속 암귀한테 발목이 잡히고 있잖아.\n이러다간 다른 팀을 따라잡기 힘들겠어...",
  ui_story_1016_10160802_5_dialog_content = "<size=30>착각인지는 모르겠는데, 저 검은 옷 삼인조를 만난 뒤로...</size>",
  ui_story_1016_10160802_6_dialog_content = "<size=30>왠지 계속 재수가 없는 것 같아!</size>",
  ui_story_1016_10160802_7_dialog_content = "지금은 불평할 때가 아냐.",
  ui_story_1016_10160802_8_dialog_content = "이대로라면 정말로 우승과는 인연이 없게 될 거야.",
  ui_story_1016_10160802_9_dialog_content = "서두르자. 디시스 팀도 어서 따라붙도록 해.",
  ui_story_1016_10160802_10_dialog_content = "말씀 감사합니다. 하지만 저흰 지금은 안으로 들어갈 생각이 없습니다.",
  ui_story_1016_10160802_11_dialog_content = "해야 할 다른 중요한 일이 있어서 말이지요.",
  ui_story_1016_10160802_12_dialog_content = "(이 사람들, 생각할수록 이상하단 말이지...)",
  ui_story_1016_10160802_13_dialog_content = "그럼 PlayerName, 바이스. 우린 서두르자.",
  ui_story_1016_10160802_14_dialog_content = "응, 그래.",
  ui_story_1016_10160802_15_dialog_content = "<color=#e8d9bb>어둠의 밑바닥, 지하성 깊은 곳</color>",
  ui_story_1016_10160802_16_dialog_content = "다른 팀 봤어?",
  ui_story_1016_10160802_17_dialog_content = "아니요. 지금 상황으로 봐서는 우리가 제일 앞서고 있는 것 같네요.",
  ui_story_1016_10160802_18_dialog_content = "좋아, 이대로만 가자고. 심사는 내 예상보다 훨씬 쉬운 것 같네.",
  ui_story_1016_10160802_19_dialog_content = "생각해 보면, 기사와 참모, 그리고 막강한 루미나틱스의 신부까지...",
  ui_story_1016_10160802_20_dialog_content = "이 구성의 팀이 실패한다는 건 생각하기 어려운 일이겠지.",
  ui_story_1016_10160802_21_dialog_content = "하하, 당신은 정말 조금도 겸손을 모르는군요.",
  ui_story_1016_10160802_22_dialog_content = "우리가 이미 우세를 점한 이상, 이 기세로 더 밀고 나가는 게 좋을 겁니다.",
  ui_story_1016_10160802_23_dialog_content = "그로누 교관님──",
  ui_story_1016_10160802_24_dialog_content = "응, 듣고 있어.",
  ui_story_1016_10160802_25_dialog_content = "나머지 학점 전부를 쓰겠습니다.\n목적지의 상세한 좌표 정보를 부탁드립니다.",
  ui_story_1016_10160802_26_dialog_content = "음, 그거야 가능하지. 근데 너희 학점을 전혀 안 아끼네~",
  ui_story_1016_10160802_27_dialog_content = "이미 마지막 단계까지 온 이상, 쓸 수 있는 건 다 쓰는 게 좋겠죠.",
  ui_story_1016_10160802_28_dialog_content = "<color=#e8d9bb>삑──</color>",
  ui_story_1016_10160802_29_dialog_content = "자, 너희 지도를 확인해 봐. 거기 빛나는 지역이 목적지야.",
  ui_story_1016_10160802_30_dialog_content = "이것도 규칙이 허용하는 범위 안에 있는 거니까, 부정행위라고 할 순 없겠네.",
  ui_story_1016_10160802_31_dialog_content = "너흰 게임의 룰을 충분히 활용하고 있어. 보고 있으니까 나도 즐거운걸.",
  ui_story_1016_10160802_32_dialog_content = "그럼 스테이지를 클리어할 때까지 계속 잘해봐~",
  ui_story_1016_10160802_33_dialog_content = "이제 모든 준비는 끝났습니다.",
  ui_story_1016_10160802_34_dialog_content = "다른 팀이 따라오기 전에 서두르죠.",
  ui_story_1016_10160802_35_dialog_content = "<color=#e8d9bb>어둠의 밑바닥, 지하성 내 목적지 부근</color>",
  ui_story_1016_10160802_36_dialog_content = "<anim type=Shake>크에엑...</anim>",
  ui_story_1016_10160802_37_dialog_content = "자, 이제 마지막 한 마리도 쓰러트렸군요.",
  ui_story_1016_10160802_38_dialog_content = "비록 그대들의 마음은 어둠을 향하였으나,\n부디 빛의 신의 은혜가 그대들의 고통을 덜어주길 바랍니다.",
  ui_story_1016_10160802_39_dialog_content = "전 그런 말을 하는 당신이 오히려 더 무섭다고 생각하는데요...",
  ui_story_1016_10160802_40_dialog_content = "깃발의 위치에 이미 한없이 가까워지긴 했지만, 구체적인 장소라면...",
  ui_story_1016_10160802_41_dialog_content = "이렇게 큰 지하성에서 깃발을 둘 만한 곳은 과연...",
  ui_story_1016_10160802_42_dialog_content = "<color=#e8d9bb>탕── 탕!</color>",
  ui_story_1016_10160802_43_dialog_content = "<size=45>!!!</size>",
  ui_story_1016_10160802_44_dialog_content = "매복이다!",
  ui_story_1016_10160802_45_dialog_content = "목표의 위치라면 당연히 정보장교에게 맡겨야죠.",
  ui_story_1016_10160802_46_dialog_content = "한참 기다렸어요. 당신들 덕분에 주변이 비교적 안전한 결전 장소가 되었군요.",
  ui_story_1016_10160802_47_dialog_content = "<size=32>쳇...</size>",
  ui_story_1016_10160802_48_dialog_content = "<size=32>레오 단장, 아무래도 저쪽은 우리보다 먼저 와 있던 모양입니다.</size>",
  ui_story_1016_10160802_49_dialog_content = "<size=32>저들에게 지하성은 홈그라운드나 다름없어요. 예상했던 결과입니다.</size>",
  ui_story_1016_10160802_50_dialog_content = "우릴 향해 방아쇠를 당긴 걸로 저들의 의도도 확실해졌네.",
  ui_story_1016_10160802_51_dialog_content = "경쟁은 피할 수 없어. 승리가 동시에 두 팀에게 주어지는 일은 없으니까.",
  ui_story_1016_10160802_52_dialog_content = "좋아요, 그럼 서로 진지하게 해볼까요.",
  ui_story_1016_10160802_53_dialog_content = "악셀리아는 전투 준비가 되었습니다.",
  ui_story_1016_10160901_1_dialog_content = "<color=#e8d9bb>탕── 탕탕!</color>",
  ui_story_1016_10160901_2_dialog_content = "꽤 성가신 상대로군요.",
  ui_story_1016_10160901_3_dialog_content = "지금은 저도 도와드릴 수 없겠네요, 레오 단장.\n조심하세요, 녀석이 당신을 노리고 있습니다.",
  ui_story_1016_10160901_4_dialog_content = "아직 끝나지 않았습니다.",
  ui_story_1016_10160901_5_dialog_content = "<size=45>!!!</size>",
  ui_story_1016_10160901_6_dialog_content = "레오 단장!",
  ui_story_1016_10160901_7_dialog_content = "덕분에 살았어!",
  ui_story_1016_10160901_8_dialog_content = "저런 가녀린 아이가 저런 힘을 가지고 있다니.",
  ui_story_1016_10160901_9_dialog_content = "일루미나 연방은 정말 인재가 많잖아. 부러워서 질투심이 날 정도라고.",
  ui_story_1016_10160901_10_dialog_content = "큐빅.",
  ui_story_1016_10160901_11_dialog_content = "으윽!",
  ui_story_1016_10160901_12_dialog_content = "(내 움직임을 읽다니, 우릴 모이지 못하게 할 작정인가?)",
  ui_story_1016_10160901_13_dialog_content = "(지금이 기회군요.)",
  ui_story_1016_10160901_14_dialog_content = "(부정하게 얻은 장비로 싸우는 건 기분이 그리 좋지 않지만...)",
  ui_story_1016_10160901_15_dialog_content = "(그렇게까지 해서 우릴... 아니, 이 팀을 이기게 하려는 게 저들의 뜻인 건가...)",
  ui_story_1016_10160901_16_dialog_content = "(지금은 정보가 너무 적습니다. 상황을 지켜보며 판단하는 수밖에...)",
  ui_story_1016_10160901_17_dialog_content = "(...약점은 이곳이군요!)",
  ui_story_1016_10160901_18_dialog_content = "역시, 왔군요.",
  ui_story_1016_10160901_19_dialog_content = "<size=45>?!</size>",
  ui_story_1016_10160901_20_dialog_content = "당신들의 움직임은 이미 파악했습니다.",
  ui_story_1016_10160901_21_dialog_content = "더스크 타운 사람들을 만만하게 보면 안 되지요.",
  ui_story_1016_10160901_22_dialog_content = "크윽!",
  ui_story_1016_10160901_23_dialog_content = "(가...강하다!)",
  ui_story_1016_10160901_24_dialog_content = "(이 정도의 장비를 지니고도 방어가 무력화될 정도의 공격이라니...)",
  ui_story_1016_10160901_25_dialog_content = "(이 사람의 실력은 정보의 내용만큼 단순하지 않아!)",
  ui_story_1016_10160901_26_dialog_content = "양해해 주십시오. 전 반드시 당신을 쓰러트려야 합니다.",
  ui_story_1016_10160901_27_dialog_content = "<size=45>!!!</size>",
  ui_story_1016_10160901_28_dialog_content = "잉겔 중령님! 지원을 요청합니다!",
  ui_story_1016_10160901_29_dialog_content = "뭐라고요?!",
  ui_story_1016_10160901_30_dialog_content = "아나톨리!",
  ui_story_1016_10160901_31_dialog_content = "이럴 때 한눈을 팔다니, 중대한 전략적 실책입니다!",
  ui_story_1016_10160901_32_dialog_content = "──!",
  ui_story_1016_10160901_33_dialog_content = "(이런, 주도권을 빼앗기고 말았네요...)",
  ui_story_1016_10160901_34_dialog_content = "<color=#e8d9bb>같은 시간, 폐기된 지하성 어딘가</color>",
  ui_story_1016_10160901_35_dialog_content = "여긴 대체 어디야?",
  ui_story_1016_10160901_36_dialog_content = "방금까지 저 팀만 따라가고 있었는데, 이런 곳으로 오게 될 줄은...",
  ui_story_1016_10160901_37_dialog_content = "여긴 왠지 복도 같네.",
  ui_story_1016_10160901_38_dialog_content = "하지만 오랫동안 사용되지 않은 것 같아.",
  ui_story_1016_10160901_39_dialog_content = "그러게, 먼지도 쌓여 있고, 거미줄까지 쳐져 있어.",
  ui_story_1016_10160901_40_dialog_content = "언제라도 이상한 게 튀어나올 것 같은 분위기잖아...",
  ui_story_1016_10160901_41_dialog_content = "<anim type=Shake><size=45>키이익...</size></anim>",
  ui_story_1016_10160901_42_dialog_content = "이 느낌, 설마... 다들 조심해!",
  ui_story_1016_10160901_43_dialog_content = "뭔가 커다란 녀석이 이쪽으로 오고 있어!",
  ui_story_1016_10160901_44_dialog_content = "<anim type=Shake><size=50>키에에엑──!</size></anim>",
  ui_story_1016_10160901_45_dialog_content = "으아악──!",
  ui_story_1016_10160901_46_dialog_content = "저, 저건... 거미?!",
  ui_story_1016_10160901_47_dialog_content = "경계를 늦추면 안 돼. 저 녀석 꽤 강해 보여.",
  ui_story_1016_10160901_48_dialog_content = "빨리 해치우자! 우리 목표는 깃발이야!",
  ui_story_1016_10160902_1_dialog_content = "<anim type=Shake><size=50>키에에엑──!</size></anim>",
  ui_story_1016_10160902_2_dialog_content = "바이스, 합동 공격으로 가자!",
  ui_story_1016_10160902_3_dialog_content = "알았어!",
  ui_story_1016_10160902_4_dialog_content = "얼어붙어라──!",
  ui_story_1016_10160902_5_dialog_content = "<anim type=Shake><size=50>키에에엑!</size></anim>",
  ui_story_1016_10160902_6_dialog_content = "<size=45>지금이야!</size>",
  ui_story_1016_10160902_7_dialog_content = "일격필중!",
  ui_story_1016_10160902_8_dialog_content = "<anim type=Shake><size=40>그어어──</size></anim>",
  ui_story_1016_10160902_9_dialog_content = "드디어 쓰러트렸네...",
  ui_story_1016_10160902_10_dialog_content = "휴... 그러게.",
  ui_story_1016_10160902_11_dialog_content = "이 거미, 엄청 강했어!",
  ui_story_1016_10160902_12_dialog_content = "방금까지 마주친 암귀들이랑은 비교조차 안 될 정도야.",
  ui_story_1016_10160902_13_dialog_content = "그러게, 저 정도의 암귀가 심사에 나오는 건 말이 안 돼.",
  ui_story_1016_10160902_14_dialog_content = "그저 훈련일 뿐인데 저렇게 강한 데다가, 이런 외딴 구석에 숨어 있다니...",
  ui_story_1016_10160902_15_dialog_content = "설마 누가 일부러 여기 데려다 둔 걸까?",
  ui_story_1016_10160902_16_dialog_content = "그건 모르지. 그냥 우리 운이 나빴을 수도 있고.",
  ui_story_1016_10160902_17_dialog_content = "이 지하성은 꽤 오랫동안 폐허였던 것 같으니까, 암귀가 더 나와도 이상할 건 없어.",
  ui_story_1016_10160902_18_dialog_content = "이 문제는 다음에 이야기하자.",
  ui_story_1016_10160902_19_dialog_content = "이미 너무 많은 시간을 지체했어.",
  ui_story_1016_10160902_20_dialog_content = "이대로 가다간 실패로 끝날 거야.",
  ui_story_1016_10160902_21_dialog_content = "<color=#e8d9bb>쿠르릉──</color>",
  ui_story_1016_10160902_22_dialog_content = "무슨 소리지?!",
  ui_story_1016_10160902_23_dialog_content = "암귀인가?",
  ui_story_1016_10160902_24_dialog_content = "설마 또 암귀는 아니겠지?",
  ui_story_1016_10160902_25_dialog_content = "아니, 아마 아닐 거야...",
  ui_story_1016_10160902_26_dialog_content = "<color=#e8d9bb>쿠르릉... 우르르르... 탕...</color>",
  ui_story_1016_10160902_27_dialog_content = "들어 봐, 총소리와 루미나틱스의 소리가 섞여 있어.\n게다가 소리의 빈도도 높아. 아마 한 팀은 아닐 거야.",
  ui_story_1016_10160902_28_dialog_content = "정말이네, 왠지 두 팀이 서로 싸우는 소리 같아!",
  ui_story_1016_10160902_29_dialog_content = "이번 전투의 목표는 깃발 쟁탈이야. 다른 팀을 만났다고 싸우는 건 상책이 아냐.\n한 가지 경우만 빼고...",
  ui_story_1016_10160902_30_dialog_content = "아마 지금 두 팀이 동시에 깃발을 발견했을 거야!",
  ui_story_1016_10160902_31_dialog_content = "설마 깃발인가?",
  ui_story_1016_10160902_32_dialog_content = "누가 벌써 깃발을 찾은 건가?",
  ui_story_1016_10160902_33_dialog_content = "가능성은 있어. 소리를 잘 들어 봐.",
  ui_story_1016_10160902_34_dialog_content = "<color=#e8d9bb>쿠르릉... 우르르르... 탕...</color>",
  ui_story_1016_10160902_35_dialog_content = "총소리와 루미나틱스의 소리가 섞여 있어.\n게다가 소리의 빈도도 높아. 아마 한 팀은 아닐 거야.",
  ui_story_1016_10160902_36_dialog_content = "그럼 설마 두 팀이 동시에 깃발을 발견하고 서로 차지하려고 싸우기 시작한 건가?!",
  ui_story_1016_10160902_37_dialog_content = "그럴 가능성이 높겠네!",
  ui_story_1016_10160902_38_dialog_content = "우리도 서두르자! 이대로 승리를 다른 팀에게 양보할 순 없어!",
  ui_story_1016_10160902_39_dialog_content = "응!",
  ui_story_1016_10160902_40_dialog_content = "<color=#e8d9bb>같은 시간, 폐기된 지하성 깊은 곳</color>",
  ui_story_1016_10160902_41_dialog_content = "목표 포착.",
  ui_story_1016_10160902_42_dialog_content = "<color=#e8d9bb>탕──!</color>",
  ui_story_1016_10160902_43_dialog_content = "순순히 보내줄 것 같냐!",
  ui_story_1016_10160902_44_dialog_content = "(저들이 이렇게까지 강할 줄이야. 주도권을 잃고서도 우리와 호각으로 싸우고 있어.)",
  ui_story_1016_10160902_45_dialog_content = "(게다가 저 아나톨리인가 하는 정보장교... 저 장비는 어떻게 된 거지?)",
  ui_story_1016_10160902_46_dialog_content = "(저 팀의 학점은 계속 신경 쓰고 있었어.\n분명히 우리보다 낮았는데, 어떻게 우리보다 좋은 장비를 가지고 있지?)",
  ui_story_1016_10160902_47_dialog_content = "(이상해. 아무래도 일루미나 내부에서 녀석들에게 편의를 제공한 모양이군.)",
  ui_story_1016_10160902_48_dialog_content = "(어차피 더스크 타운의 상황은 일루미나의 야전 지휘관들에게 전해졌어.\n우리 목적은 이미 달성했다고 할 수 있겠지. 그렇다면...)",
  ui_story_1016_10160902_49_dialog_content = "요제프!",
  ui_story_1016_10160902_50_dialog_content = "네!",
  ui_story_1016_10160902_51_dialog_content = "......",
  ui_story_1016_10160902_52_dialog_content = "(그럴 생각입니까...)",
  ui_story_1016_10160902_53_dialog_content = "(알겠습니다.)",
  ui_story_1016_10160902_54_dialog_content = "(공격 속도가 느려지다니... 설마 눈속임인가?)",
  ui_story_1016_10160902_55_dialog_content = "(아니, 이건 절호의 기회입니다!)",
  ui_story_1016_10160902_56_dialog_content = "중령님!",
  ui_story_1016_10160902_57_dialog_content = "알겠어요!",
  ui_story_1016_10160902_58_dialog_content = "자오! 진형을 축소하고 방어 태세로!",
  ui_story_1016_10160902_59_dialog_content = "알겠습니다!",
  ui_story_1016_10160902_60_dialog_content = "마음대로 두진 않아요!",
  ui_story_1016_10160902_61_dialog_content = "<color=#e8d9bb>탕! 탕탕──!</color>",
  ui_story_1016_10160902_62_dialog_content = "이런. 퇴로가 막혔습니다!",
  ui_story_1016_10160902_63_dialog_content = "악셀리아, 지금이에요!",
  ui_story_1016_10160902_64_dialog_content = "오래 기다리셨습니다.",
  ui_story_1016_10160902_65_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_1016_10160902_66_dialog_content = "으윽──!",
  ui_story_1016_10160902_67_dialog_content = "자오가 당했다!",
  ui_story_1016_10160902_68_dialog_content = "최대한 제게 붙으세요! 루미나틱스로 엄호하겠습니다!",
  ui_story_1016_10160902_69_dialog_content = "소용없습니다.",
  ui_story_1016_10160902_70_dialog_content = "<color=#e8d9bb>콰아앙!</color>",
  ui_story_1016_10160902_71_dialog_content = "콜록... 콜록콜록!",
  ui_story_1016_10160902_72_dialog_content = "과연 일루미나 최강의 병기인가... 무서운 힘이다.",
  ui_story_1016_10160902_73_dialog_content = "이렇게 된 이상 저도 어쩔 수가 없군요.",
  ui_story_1016_10160902_74_dialog_content = "그래, 패배를 인정하겠어.",
  ui_story_1016_10160902_75_dialog_content = "현명한 선택입니다.",
  ui_story_1016_10160902_76_dialog_content = "악셀리아, 깃발을 가져오세요.",
  ui_story_1016_10160902_77_dialog_content = "알겠습니다.",
  ui_story_1016_10160902_78_dialog_content = "그렇다면 이번 우승자는──",
  ui_story_1016_10160902_79_dialog_content = "<size=45>따라잡았다아아──!</size>",
  ui_story_1016_10160902_80_dialog_content = "......",
  ui_story_1016_10160902_81_dialog_content = "............",
  ui_story_1016_10160902_82_dialog_content = "..................",
  ui_story_1016_10160902_83_dialog_content = "...늦었나?",
  ui_story_1016_10160902_84_dialog_content = "안타깝지만 늦었습니다.",
  ui_story_1016_10160902_85_dialog_content = "5초만 일찍 도착했다면 악셀리아와 제 동료들과 경쟁할 수 있었을 겁니다.",
  ui_story_1016_10160902_86_dialog_content = "그래? 역시 우리가 시간을 너무 많이 뺏긴 모양이네.",
  ui_story_1016_10160902_87_dialog_content = "어째서...",
  ui_story_1016_10160902_88_dialog_content = "거의 다 성공했었는데...",
  ui_story_1016_10160902_89_dialog_content = "자, 아쉬워하지 마.",
  ui_story_1016_10160902_90_dialog_content = "승패가 정해진 이상, 아쉬워해도 소용없어.",
  ui_story_1016_10160902_91_dialog_content = "더 노력해서 성장하는 수밖에 없어.",
  ui_story_1016_10160902_92_dialog_content = "응, 카렌 말이 맞아...",
  ui_story_1016_10160902_93_dialog_content = "그럼 이제 성적을 발표하겠습니다.",
  ui_story_1016_10160902_94_dialog_content = "이번 심사 우승팀은 <color=#FFB400>잉겔 팀</color>입니다!",
  ui_story_1016_10160902_95_dialog_content = "그리고 종합 득점 1위는 <color=#FFB400>악셀리아</color> 중위입니다!",
  ui_story_1016_10160902_96_dialog_content = "축하합니다.",
  ui_story_1016_10160902_97_dialog_content = "고마워요.",
  ui_story_1016_10160902_98_dialog_content = "(드디어 무사히 끝났군요.)",
  ui_story_1016_10160902_99_dialog_content = "악셀리아, 이겼습니다.",
  ui_story_1016_10160902_100_dialog_content = "예상했던 일입니다.",
  ui_story_1016_10160902_101_dialog_content = "(두 사람은 놀란 기색도, 기뻐하는 기색도 없군요.)",
  ui_story_1016_10160902_102_dialog_content = "(원래부터 감정을 잘 드러내지 않는 타입이라곤 하지만, 이래서는 너무 이상한데...)",
  ui_story_1016_10160902_103_dialog_content = "(설마, 이것도 계획의 일부인 겁니까...?)",
  ui_story_1016_10161001_1_dialog_content = "악셀리아 중위님, 축하드립니다!",
  ui_story_1016_10161001_2_dialog_content = "중위님이 우승해서 일루미나의 모두가 기뻐하고 있습니다!",
  ui_story_1016_10161001_3_dialog_content = "악셀리아는 해야 할 일을 했을 뿐입니다.",
  ui_story_1016_10161001_4_dialog_content = "다들 비켜 주세요.",
  ui_story_1016_10161001_5_dialog_content = "악셀리아는 지금 당장 휴식을 취해야 합니다.",
  ui_story_1016_10161001_6_dialog_content = "저 강한 아가씨가 일루미나 사람들에게 둘러싸여 버렸군요.",
  ui_story_1016_10161001_7_dialog_content = "그러게.",
  ui_story_1016_10161001_8_dialog_content = "레오 단장, 저는 당신이 왜 그런 결정을 내렸는지 알 권리가 있다고 생각합니다.",
  ui_story_1016_10161001_9_dialog_content = "스스로 승리를 포기한 이유가 무엇인지 말입니다.",
  ui_story_1016_10161001_10_dialog_content = "우린 이미 목표를 달성했으니까.",
  ui_story_1016_10161001_11_dialog_content = "더스크 타운의 상황은 이미 일루미나의 레이스 군단장에게 전해졌어.\n레이스 군단장은 전투 경험이 풍부하니까, 우리 상황을 이해할 수 있을 거야.",
  ui_story_1016_10161001_12_dialog_content = "이 정보는 곧 일루미나의 정보망을 통해 백야성 상부에도 전달되겠지.",
  ui_story_1016_10161001_13_dialog_content = "전 그렇다 해도 우리가 연합 훈련에서 승리해야 한다고 생각합니다만.",
  ui_story_1016_10161001_14_dialog_content = "그렇게 하면 우린 더 많은 관심을 끌 수 있고,\n더스크 타운은 더 많은 원조를 받을 수 있었을 겁니다.",
  ui_story_1016_10161001_15_dialog_content = "위기를 눈앞에 둔 지금, 우린 더 큰 승산이 필요합니다.",
  ui_story_1016_10161001_16_dialog_content = "하지만 너도 내 말대로 지는 걸 선택했잖아.",
  ui_story_1016_10161001_17_dialog_content = "그건 제가 당신의 판단을 믿기 때문입니다.\n다만 그 이유도 함께 알고 싶었을 뿐이지요.",
  ui_story_1016_10161001_18_dialog_content = "그렇게 해야만 우리도 더 잘 협력할 수 있을 테니까요.",
  ui_story_1016_10161001_19_dialog_content = "일루미나의 저 팀, 남들이 알아서는 안 될 수단을 쓰고 있었어.",
  ui_story_1016_10161001_20_dialog_content = "난 처음부터 저 팀을 주목했는데, 이상한 점이 아주 많았어.",
  ui_story_1016_10161001_21_dialog_content = "저들의 실력은 확실히 보통이 아냐. 하지만 저 승리는 결코 명예롭지 못해.",
  ui_story_1016_10161001_22_dialog_content = "그 말은... 저들이 부정행위를 했다는 겁니까?",
  ui_story_1016_10161001_23_dialog_content = "확실한 증거는 없어. 하지만 거의 확신할 수 있어.",
  ui_story_1016_10161001_24_dialog_content = "저들이 마지막 전투에서 쓴 장비는 저 팀의 학점으로 교환할 수 있는 장비의 수준이 아니었어.",
  ui_story_1016_10161001_25_dialog_content = "물론 그 차이는 크지 않아서, 다른 사람들이 알아채긴 쉽지 않았을 거야.\n하지만 저들의 실력을 한 단계 높이기엔 충분했지.",
  ui_story_1016_10161001_26_dialog_content = "저들의 뒤에 누군가 있어.",
  ui_story_1016_10161001_27_dialog_content = "일루미나의 윗선일까요?",
  ui_story_1016_10161001_28_dialog_content = "그럴지도 모르지. 아무튼 다시 말해 저들의 승리는 사전에 계획된 일이라는 거야.",
  ui_story_1016_10161001_29_dialog_content = "저들의 진짜 목적은 승리가 아니라 다른 무언가겠지.",
  ui_story_1016_10161001_30_dialog_content = "승리가 진짜 목적이 아니라 선결조건이라...",
  ui_story_1016_10161001_31_dialog_content = "설마...",
  ui_story_1016_10161001_32_dialog_content = "뭐, 누가 알겠어.",
  ui_story_1016_10161001_33_dialog_content = "어쩌면 여기도 이제 곧 소란스러워질지도 모르겠네.",
  ui_story_1016_10161001_34_dialog_content = "에이~",
  ui_story_1016_10161001_35_dialog_content = "더스크 타운 팀을 위해 준비한 「보너스」를\n왜 전부 PlayerName 팀이 처리해 버린 거냐구...",
  ui_story_1016_10161001_36_dialog_content = "쟤네 그냥 단순히 운이 나쁜 걸까? 아니면 일부러 우리 계획을 망친 걸까?",
  ui_story_1016_10161001_37_dialog_content = "상황을 봤을 땐 모두 우연이었을 겁니다. 게다가 결과적으로는 나쁘지 않습니다.",
  ui_story_1016_10161001_38_dialog_content = "더스크 타운 팀은 훈련 기간 동안 자신들의 실력을 충분히 증명했고,\n「보너스」도 우리에게 예상 밖의 수확을 가져다주었습니다.",
  ui_story_1016_10161001_39_dialog_content = "주목할 만한 강자가 이렇게나 많다는 걸 아시면\n「그분」께서도 분명히 기뻐하실 겁니다.",
  ui_story_1016_10161001_40_dialog_content = "게다가 아이테르 팀도 예상보다 빠르게 거미 여왕을 쓰러트렸습니다.\n저들의 실력도 크게 성장했다는 증거겠지요.",
  ui_story_1016_10161001_41_dialog_content = "하지만 우리 때문에 아이테르 팀이 우승을 놓친 것 같아요.",
  ui_story_1016_10161001_42_dialog_content = "우리한테 화나지 않았으면 좋겠는데요...",
  ui_story_1016_10161001_43_dialog_content = "<anim type=Shake>하암~</anim>, 피곤해.",
  ui_story_1016_10161001_44_dialog_content = "우리 언제 돌아갈 수 있어? 3일 연속으로 계속 자고 싶은데...",
  ui_story_1016_10161001_45_dialog_content = "보채면 안 돼, 민치.",
  ui_story_1016_10161001_46_dialog_content = "할 일이 남았으니까 아직은 못 가.",
  ui_story_1016_10161001_47_dialog_content = "그렇습니다. 아주 중요한 일이 하나 남아 있습니다.",
  ui_story_1016_10161001_48_dialog_content = "<color=#e8d9bb>자난성, 율리시스의 사무실</color>",
  ui_story_1016_10161001_49_dialog_content = "(또 자난성으로 돌아왔군.)",
  ui_story_1016_10161001_50_dialog_content = "(이제 앞으로 일어날 일은 일루미나 역사의 새로운 장을 열게 되겠지.)",
  ui_story_1016_10161001_51_dialog_content = "(음? 이건...)",
  ui_story_1016_10161001_52_dialog_content = "(이 여자 계획은 정말 치밀하단 말이지. 잠깐 쉴 틈도 없게 만드는군.)",
  ui_story_1016_10161001_53_dialog_content = "에센, 내 쪽으로 와라.",
  ui_story_1016_10161001_54_dialog_content = "예.",
  ui_story_1016_10161001_55_dialog_content = "<color=#e8d9bb>똑똑똑.</color>",
  ui_story_1016_10161001_56_dialog_content = "율리시스 님, 제가 뭘 하면 되겠습니까?",
  ui_story_1016_10161001_57_dialog_content = "이걸 「<color=#FFB400>철가면</color>」 님께 건네고, 내 말을 전해라.",
  ui_story_1016_10161001_58_dialog_content = "내가 준비한 이 도시 방어구조 조정 계획서에 협조해 달라고 말이야.",
  ui_story_1016_10161001_59_dialog_content = "예.",
  ui_story_1016_10161001_60_dialog_content = "<color=#e8d9bb>같은 시간, 자난성 어딘가</color>",
  ui_story_1016_10161001_61_dialog_content = "(아직 시간도 안 됐는데, 일루미나 놈들의 추적이 점점 더 심해지고 있어.)",
  ui_story_1016_10161001_62_dialog_content = "(그 늙은이, 이렇게까지 내 실험 성과를 원하는 건가.)",
  ui_story_1016_10161001_63_dialog_content = "(그럼 제이드한테...)",
  ui_story_1016_10161001_64_dialog_content = "......",
  ui_story_1016_10161001_65_dialog_content = "(...지금쯤 멀리 가버렸겠지.)",
  ui_story_1016_10161001_66_dialog_content = "드니에르!",
  ui_story_1016_10161001_67_dialog_content = "언니? 무슨 일이야?",
  ui_story_1016_10161001_68_dialog_content = "오늘이 무슨 날인지 기억해?",
  ui_story_1016_10161001_69_dialog_content = "오늘...?",
  ui_story_1016_10161001_70_dialog_content = "실험 보고서 제출일이었나? 아니면 심사 전 마지막 날?",
  ui_story_1016_10161001_71_dialog_content = "둘 다 틀렸어!",
  ui_story_1016_10161001_72_dialog_content = "설마 정말로 잊은 거야? 오늘은 네 생일이야!",
  ui_story_1016_10161001_73_dialog_content = "내 생일? 아... 그랬던 것 같네.",
  ui_story_1016_10161001_74_dialog_content = "어떻게 자기 생일도 잊을 수가 있어?",
  ui_story_1016_10161001_75_dialog_content = "별로 중요한 날도 아니잖아.\n「생일」이라고 정의된 걸 제외하면 다른 날과 딱히 차이도 없고.",
  ui_story_1016_10161001_76_dialog_content = "휴... 역시 너답네.",
  ui_story_1016_10161001_77_dialog_content = "그런 냉정하고 이성적인 답을 할 수 있는 사람도 아마 너뿐일 거야.",
  ui_story_1016_10161001_78_dialog_content = "하지만 네가 신경 쓰지 않아도 다른 사람은 신경 쓰고 있거든.",
  ui_story_1016_10161001_79_dialog_content = "음?",
  ui_story_1016_10161001_80_dialog_content = "내가 생일 선물을 준비했어.",
  ui_story_1016_10161001_81_dialog_content = "이거야!",
  ui_story_1016_10161001_82_dialog_content = "끽!",
  ui_story_1016_10161001_83_dialog_content = "?!",
  ui_story_1016_10161001_84_dialog_content = "하하하, 아무래도 네가 마음에 드는 모양이네!",
  ui_story_1016_10161001_85_dialog_content = "저번에 전장에서 주운 거야. 무슨 동물인지는 모르겠지만 꽤 얌전하더라고.",
  ui_story_1016_10161001_86_dialog_content = "데리고 가서 며칠 동안 톱밥 빵을 먹여 봤는데, 왠지 별로 안 좋아하는 것 같았어.",
  ui_story_1016_10161001_87_dialog_content = "내가 네 옆에 있어 주지 못할 땐 이 녀석이 대신 있어 주면 좋을 것 같아.",
  ui_story_1016_10161001_88_dialog_content = "언니도 참...",
  ui_story_1016_10161001_89_dialog_content = "이건 친칠라야. 빵 같은 건 보통 안 먹어.",
  ui_story_1016_10161001_90_dialog_content = "키울 거면 건초나 곡물 같은 걸 먹여야 돼. 당근도 괜찮아.",
  ui_story_1016_10161001_91_dialog_content = "역시 너한테 맡기길 잘한 것 같네.",
  ui_story_1016_10161001_92_dialog_content = "친칠라도 실험동물로 사용되거든. 실험동물을 사육하는 것도 연구의 일환이야.",
  ui_story_1016_10161001_93_dialog_content = "<anim type=Shake><size=45>끽!!!</size></anim>",
  ui_story_1016_10161001_94_dialog_content = "봐, 너 때문에 겁먹었잖아!",
  ui_story_1016_10161001_95_dialog_content = "......",
  ui_story_1016_10161001_96_dialog_content = "<anim type=Shake>끽...</anim>",
  ui_story_1016_10161001_97_dialog_content = "언니가 준 선물이라면 나도 어떻게 하진 않을 거야.",
  ui_story_1016_10161001_98_dialog_content = "선물 받아주는 거야?",
  ui_story_1016_10161001_99_dialog_content = "응.",
  ui_story_1016_10161001_100_dialog_content = "그럼 이름을 지어주는 건 어때?",
  ui_story_1016_10161001_101_dialog_content = "이름...",
  ui_story_1016_10161001_102_dialog_content = "「<color=#FFB400>제이드</color>」로 할래.",
  ui_story_1016_10161001_103_dialog_content = "<color=#e8d9bb>쾅──!</color>",
  ui_story_1016_10161001_104_dialog_content = "실험... 내 실험이...",
  ui_story_1016_10161001_105_dialog_content = "다 사라져 버렸어...",
  ui_story_1016_10161001_106_dialog_content = "언니, 어째서... 왜 또 안 와준 거야?",
  ui_story_1016_10161001_107_dialog_content = "<anim type=Shake><size=45>끽── 끽──</size></anim>",
  ui_story_1016_10161001_108_dialog_content = "제이드...",
  ui_story_1016_10161001_109_dialog_content = "「내가 네 옆에 있어주지 못할 땐 이 녀석이 대신 있어주면 좋을 것 같아.」",
  ui_story_1016_10161001_110_dialog_content = "나한테 또...!",
  ui_story_1016_10161001_111_dialog_content = "<anim type=Shake><size=45>끽! 끼익──!</size></anim>",
  ui_story_1016_10161001_112_dialog_content = "<anim type=Shake>끽...</anim>",
  ui_story_1016_10161001_113_dialog_content = "──!!!",
  ui_story_1016_10161001_114_dialog_content = "끽!",
  ui_story_1016_10161001_115_dialog_content = "<anim type=Shake>끽... 끽...</anim>",
  ui_story_1016_10161001_116_dialog_content = "어째서... 내가 조금만 더 힘을 줬으면 넌 목이 부러질 뻔했는데...",
  ui_story_1016_10161001_117_dialog_content = "왜 언니처럼 가버리지 않는 거야?",
  ui_story_1016_10161001_118_dialog_content = "<anim type=Shake><size=32>끽...</size></anim>",
  ui_story_1016_10161001_119_dialog_content = "......",
  ui_story_1016_10161001_120_dialog_content = "뭐, 됐어...",
  ui_story_1016_10161001_121_dialog_content = "곁에 있게 해 줄게.",
  ui_story_1016_10161001_122_dialog_content = "적어도 넌 실험동물로서의 가치는 있으니까.",
  ui_story_1016_10161001_123_dialog_content = "(「가치」라...)",
  ui_story_1016_10161001_124_dialog_content = "(확실히 이 세상엔 「가치」만이 사물을 평가하는 절대적인 기준이야.)",
  ui_story_1016_10161001_125_dialog_content = "<color=#e8d9bb>부스럭부스럭...</color>",
  ui_story_1016_10161001_126_dialog_content = "드니에르... 뭔가 온다... 조심해...",
  ui_story_1016_10161001_127_dialog_content = "키이익...",
  ui_story_1016_10161001_128_dialog_content = "암귀...다!",
  ui_story_1016_10161001_129_dialog_content = "......",
  ui_story_1016_10161001_130_dialog_content = "무기를 내려놔. 널 해치진 않으니까.",
  ui_story_1016_10161001_131_dialog_content = "『노라 님, <color=#FFB400>피제로</color> 님의 전언입니다.』",
  ui_story_1016_10161001_132_dialog_content = "『말해.』",
  ui_story_1016_10161001_133_dialog_content = "『내부에서 일루미나의 방어 체계를 무너트리고, 「<color=#FFB400>중요한 분</color>」을 영접하라고 하셨습니다.』",
  ui_story_1016_10161001_134_dialog_content = "『드디어 시간이 된 모양이네.』",
  ui_story_1016_10161001_135_dialog_content = "<color=#e8d9bb>시범 경기 당일, 경기 시작 15분 전</color>",
  ui_story_1016_10161001_136_dialog_content = "휴──",
  ui_story_1016_10161001_137_dialog_content = "카렌의 2연승을 못 돕다니...",
  ui_story_1016_10161001_138_dialog_content = "에휴...",
  ui_story_1016_10161001_139_dialog_content = "그렇게 속상해할 거 없어. 그렇게 아쉬울 일도 아니니까.",
  ui_story_1016_10161001_140_dialog_content = "애초에 이 훈련에 참가한 사람들은 각 세력의 정상급 인재야.\n나보다 강한 사람이 있는 것도 이상한 일이 아냐.",
  ui_story_1016_10161001_141_dialog_content = "이기고 지는 것도 처음부터 정해져 있는 건 아니야.\n이번 패배로 난 더 강한 사람들을 알게 됐고, 덕분에 새로운 목표를 얻었어.",
  ui_story_1016_10161001_142_dialog_content = "봐, 역시 카렌은 멋있는 말만 한다니까.",
  ui_story_1016_10161001_143_dialog_content = "그, 그래?",
  ui_story_1016_10161001_144_dialog_content = "다들 경기 보러 온 건가?",
  ui_story_1016_10161001_145_dialog_content = "레오 씨도 왔구나.",
  ui_story_1016_10161001_146_dialog_content = "자오 씨랑 요제프 씨는 같이 안 왔어?",
  ui_story_1016_10161001_147_dialog_content = "자오는 며칠간 훈련에 참가한 게 조금 과로였는지 몸이 안 좋아져서 못 왔어.",
  ui_story_1016_10161001_148_dialog_content = "지금 메디컬 센터에서 검사받고 있어. 요제프는 간호하고 있고.",
  ui_story_1016_10161001_149_dialog_content = "서로 챙겨주기까지 하는 걸 보면 다들 친해진 모양이네.",
  ui_story_1016_10161001_150_dialog_content = "하하하, 그럴 수도 있겠지.",
  ui_story_1016_10161001_151_dialog_content = "이번 협력을 통해 우린 서로를 조금 더 이해할 수 있었어.",
  ui_story_1016_10161001_152_dialog_content = "비록 서로 다른 진영에 속해 있지만,\n우린 서로 존경하는 친구도, 좋은 적도 될 수 있겠지.",
  ui_story_1016_10161001_153_dialog_content = "친구이자 적인가...",
  ui_story_1016_10161001_154_dialog_content = "덕분에 하나 배웠어.",
  ui_story_1016_10161001_155_dialog_content = "아, 저기 잉겔 중령님이 있는데? 그리고 아나톨리 소령님도?",
  ui_story_1016_10161001_156_dialog_content = "응? 어디? 인사하러 갈까?",
  ui_story_1016_10161001_157_dialog_content = "봐, 저기 심판석 옆자리.",
  ui_story_1016_10161001_158_dialog_content = "어째서...",
  ui_story_1016_10161001_159_dialog_content = "설마 암귀의 짓인가요?",
  ui_story_1016_10161001_160_dialog_content = "어쨌든 지금은 매우 긴급한 상황입니다.",
  ui_story_1016_10161001_161_dialog_content = "가서 확인해 봐야겠어요.",
  ui_story_1016_10161001_162_dialog_content = "무슨 일인데 두 분 다 저렇게 심각한 표정이지?",
  ui_story_1016_10161001_163_dialog_content = "너무 멀어서 무슨 말을 하는지 전혀 안 들려.",
  ui_story_1016_10161001_164_dialog_content = "음, 무슨 중요한 일이라도 생긴 건가?",
  ui_story_1016_10161001_165_dialog_content = "가서 직접 물어보자고.",
  ui_story_1016_10161001_166_dialog_content = "당신은 백야성 사람인데 왜 그렇게 일루미나의 일에 관심을 두는 거지?",
  ui_story_1016_10161001_167_dialog_content = "그 말씀은 제가 조금 정정해 드려야겠군요.\n전 일루미나에 관심이 없습니다. 하지만 더스크 타운의 일이라면 이야기가 다르죠.",
  ui_story_1016_10161001_168_dialog_content = "전하께서도 들으셨겠지요. 더스크 타운은 지금 암귀의 침공을 눈앞에 두고 있습니다.\n게다가 그 위기는 날이 갈수록 커지고 있습니다.",
  ui_story_1016_10161001_169_dialog_content = "더스크 타운의 안전을 보장하기 위해서는 더 많은 힘이 필요합니다.",
  ui_story_1016_10161001_170_dialog_content = "그러나 지금 일루미나는 뭔가 곤란한 일이 벌어져 도움이 필요한 것처럼 보입니다.",
  ui_story_1016_10161001_171_dialog_content = "적절한 기회에 일루미나의 차세대 요인들에게 호의를 베풀 수 있다면\n나쁘지 않은 선택일 겁니다.",
  ui_story_1016_10161001_172_dialog_content = "더스크 타운의 상황은 들었어. 당신들이 받는 부담도 물론 알고 있어.",
  ui_story_1016_10161001_173_dialog_content = "내가 백야성 상부에 보고해서 대책을 논의해 달라고 할게.",
  ui_story_1016_10161001_174_dialog_content = "더스크 타운에 관심을 가져 주셔서 감사합니다.",
  ui_story_1016_10161001_175_dialog_content = "다만 지금까지의 경험으로 봤을 때, 이 일은 아마 흐지부지될 겁니다.",
  ui_story_1016_10161001_176_dialog_content = "더스크 타운이 필요로 하는 건 구두 약속이 아니라 실질적인 원조입니다.",
  ui_story_1016_10161001_177_dialog_content = "......",
  ui_story_1016_10161001_178_dialog_content = "어떻게든 방법을 생각해 볼게.",
  ui_story_1016_10161001_179_dialog_content = "감사합니다. 저도 더 많은 원조를 받을 수 있도록 노력하겠습니다.",
  ui_story_1016_10161001_180_dialog_content = "한 사람이라도 더 우호를 증진한다면 더스크 타운에도 이로울 테니까요.",
  ui_story_1016_10161001_181_dialog_content = "여러분은 계속 여기서 관전하고 계시죠. 전 잠시 실례하겠습니다.",
  ui_story_1016_10161001_182_dialog_content = "저도 갈게요. 전 일루미나의 군인이잖아요.\n만약 문제가 생겼다면 저도 도와야 할 의무가 있어요!",
  ui_story_1016_10161001_183_dialog_content = "나도 갈래!",
  ui_story_1016_10161001_184_dialog_content = "그럼 나도 갈게.",
  ui_story_1016_10161001_185_dialog_content = "좋습니다. 그럼 다 같이 가시죠.",
  ui_story_1016_10161001_186_dialog_content = "원인과 용의자는 확인했나요?",
  ui_story_1016_10161001_187_dialog_content = "아직 조사 중입니다.",
  ui_story_1016_10161001_188_dialog_content = "자난성 전체의 방어 시스템 손실률은 어느 정도죠?",
  ui_story_1016_10161001_189_dialog_content = "현재 확인된 것만 16% 정도 파괴되어 완전히 기능을 잃었습니다.",
  ui_story_1016_10161001_190_dialog_content = "또한 절반 정도가 아직 상황을 알 수 없습니다.\n자난성은 규모도 크고 길도 복잡하다 보니...",
  ui_story_1016_10161001_191_dialog_content = "하지만 현재 파괴된 방어 시설만으로도 충분히 자난성의\n방어 체계에 구멍을 낼 수 있는 심각한 위기 상황입니다.",
  ui_story_1016_10161001_192_dialog_content = "이런 중요한 순간에 방어 시스템을 파괴하다니... 설마 노라의 소행일까요?",
  ui_story_1016_10161001_193_dialog_content = "그럴 가능성이 높습니다.",
  ui_story_1016_10161001_194_dialog_content = "따라오세요. 즉시 상부에...",
  ui_story_1016_10161001_195_dialog_content = "잉겔, 아나톨리 씨, 잠깐만!",
  ui_story_1016_10161001_196_dialog_content = "PlayerName? 바이스 중위와 백야성 분들까지...?",
  ui_story_1016_10161001_197_dialog_content = "곧 시범 경기가 시작될 거예요. 왜 경기장에 안 있고 이쪽으로 온 거죠?",
  ui_story_1016_10161001_198_dialog_content = "당신들이 급하게 경기장을 떠나는 모습을 봤거든.\n무슨 귀찮은 일이라도 생긴 건 아닌가 해서 말이야.",
  ui_story_1016_10161001_199_dialog_content = "필요하다면 나도 도와줄 수 있어.",
  ui_story_1016_10161001_200_dialog_content = "지금 도움을 주겠다고 먼저 나서는 건가요? 당신들답지 않은데요.\n게다가 당신은 일루미나인도 아닌데 왜 우리 일에 그렇게 관심을 갖는 거죠?",
  ui_story_1016_10161001_201_dialog_content = "그쪽에서 그렇게 말한다면 나도 솔직하게 말할 수밖에 없겠지.",
  ui_story_1016_10161001_202_dialog_content = "지금 내가 당신들을 돕는 건 훗날 당신들이 더스크 타운을 도와주길 바라기 때문이야.",
  ui_story_1016_10161001_203_dialog_content = "그럼 왜 우리가 도움이 필요하다고 확신하는 거죠?",
  ui_story_1016_10161001_204_dialog_content = "하물며 전 일개 정보장교일 뿐, 일루미나를 대표하는 입장은 아니에요.\n일루미나를 움직여 당신들을 지원할 방법 같은 건 없어요.",
  ui_story_1016_10161001_205_dialog_content = "물론 알고 있어. 그리고 내가 필요로 하는 건 일루미나의 도움이 아냐.\n당신과 당신 동료들의 도움이지.",
  ui_story_1016_10161001_206_dialog_content = "당신들은 모두 막강한 실력을 가지고 있어.\n더스크 타운은 바로 그런 강자의 도움이 필요해.",
  ui_story_1016_10161001_207_dialog_content = "게다가...",
  ui_story_1016_10161001_208_dialog_content = "이제 곧 연합 훈련의 대미를 장식할 시범 경기가 시작될 거잖아.\n다들 경기를 보고 있거나 주변의 경비를 맡고 있겠지.",
  ui_story_1016_10161001_209_dialog_content = "인력이 부족한 상황 아냐?",
  ui_story_1016_10161001_210_dialog_content = "......",
  ui_story_1016_10161001_211_dialog_content = "잉겔, 만약 정말로 무슨 일이 있는 거면 우리도 동료로서 못 본 척하진 않을 거야.",
  ui_story_1016_10161001_212_dialog_content = "게다가 만약 「노라」가 관련된 일이라면...",
  ui_story_1016_10161001_213_dialog_content = "노라?!",
  ui_story_1016_10161001_214_dialog_content = "당신...",
  ui_story_1016_10161001_215_dialog_content = "미안, 아까 오는 길에 들었어. 엿들을 생각은 없었어...",
  ui_story_1016_10161001_216_dialog_content = "아이테르의 능력은 참 편리하군요.",
  ui_story_1016_10161001_217_dialog_content = "정말 미안해...",
  ui_story_1016_10161001_218_dialog_content = "잉겔 중령님, 지금 상황을 말씀해 주실 수 있나요?\n만약 노라가 관련된 일이라면 저희도 가만히 있을 순 없어요!",
  ui_story_1016_10161001_219_dialog_content = "우린 여러 번 같이 싸웠잖아요! 믿어주세요!",
  ui_story_1016_10161001_220_dialog_content = "맞아!",
  ui_story_1016_10161001_221_dialog_content = "......",
  ui_story_1016_10161001_222_dialog_content = "당신 추측이 맞아요. 지금 우린 확실히 도움이 필요해요.",
  ui_story_1016_10161001_223_dialog_content = "자난성의 방어 시설에 문제가 발생했어요.\n지금 즉시 인원을 배치해 방어를 보강하고 파괴된 장치를 점검해야 해요.",
  ui_story_1016_10161001_224_dialog_content = "하지만 인력이 부족한 상황이에요.\n역시 여러분에게 도움을 부탁할 수밖에 없겠네요.",
  ui_story_1016_10161001_225_dialog_content = "다만 조건이 하나 있어요.\n노라나 다른 팬텀의 흔적을 발견한다면, 즉시 우리에게 알려주세요.",
  ui_story_1016_10161001_226_dialog_content = "노라와... 다른 팬텀이요?!",
  ui_story_1016_10161001_227_dialog_content = "만약 그들을 사로잡는다면, 일루미나에 인도해 주세요.",
  ui_story_1016_10161001_228_dialog_content = "여긴 당신들 땅이니 그래야지.",
  ui_story_1016_10161001_229_dialog_content = "방어 시설에 문제라니...",
  ui_story_1016_10161001_230_dialog_content = "상황이 심각한가?",
  ui_story_1016_10161001_231_dialog_content = "심각하다고 하면 심각하고, 심각하지 않다고 하면 그렇다고 할 수 있겠죠.",
  ui_story_1016_10161001_232_dialog_content = "문제 자체는 그리 크지 않아요. 하지만 지금 시기가 특수하다는 점,\n그리고 노라가 자난성에 잠복해 있을 가능성을 생각하면...",
  ui_story_1016_10161001_233_dialog_content = "반드시 만반의 대책을 세워야 할 필요가 있어요.\n그 어떤 빈틈도 있어선 안 돼요.",
  ui_story_1016_10161001_234_dialog_content = "지금 일루미나의 반역자가 자난성 안에 있다는 건가?",
  ui_story_1016_10161001_235_dialog_content = "(그게 사실이라면 전에 만난 그 암귀들도 아마 그자의 부하겠지.)",
  ui_story_1016_10161001_236_dialog_content = "지금은 아직 노라의 행적을 찾지 못했지만, 가능성이 높다고 할 수 있어요.",
  ui_story_1016_10161001_237_dialog_content = "여러분도 최대한 조심하는 게 좋아요.",
  ui_story_1016_10161001_238_dialog_content = "아나톨리 소령, 저들이 담당할 구역을 배정해 주세요.",
  ui_story_1016_10161001_239_dialog_content = "네.",
  ui_story_1016_10161001_240_dialog_content = "바이스 중위는 자난성에 대해 잘 아는 편이니까, 당신이 인솔을 맡아 주시죠.",
  ui_story_1016_10161001_241_dialog_content = "알겠습니다. 맡겨주세요.",
  ui_story_1016_10161001_242_dialog_content = "자난성역 부근 A구역에서 C구역 일대를 순찰하고, 시설 손상 정도를 점검해 주세요.",
  ui_story_1016_10161001_243_dialog_content = "임무 완료 후 저 또는 잉겔 중령님께 보고 바랍니다.",
  ui_story_1016_10161001_244_dialog_content = "네!",
  ui_story_1016_10161101_1_dialog_content = "조금 있으면 경기가 시작될 거야. 준비됐어?",
  ui_story_1016_10161101_2_dialog_content = "당연하지. 준비는 충분해.",
  ui_story_1016_10161101_3_dialog_content = "네 쪽은 어때? 뭔가 찾았어?",
  ui_story_1016_10161101_4_dialog_content = "아니.",
  ui_story_1016_10161101_5_dialog_content = "노라는 자난성의 미개발 지역 안에 잠복해 있을 가능성이 높아.\n거긴 사방으로 길이 통하니까 철저하게 알아보려면 시간이 더 필요해.",
  ui_story_1016_10161101_6_dialog_content = "고생이 많네.",
  ui_story_1016_10161101_7_dialog_content = "천만에.",
  ui_story_1016_10161101_8_dialog_content = "원래는 내가 직접 부대를 이끌고 조사하려고 했는데,\n그렇다고 연합 훈련 시범 경기 자리를 비울 순 없잖아.",
  ui_story_1016_10161101_9_dialog_content = "근위군단장이 결석했다는 걸 입방아 찧기 좋아하는 놈들이 알면\n또 순식간에 이상한 루머가 퍼질 테니 말이야.",
  ui_story_1016_10161101_10_dialog_content = "매번 발목을 잡는 건 그런 자식들이라니까.",
  ui_story_1016_10161101_11_dialog_content = "그래도 안심해. 경기장 주변엔 경비를 삼엄하게 서고 있어.",
  ui_story_1016_10161101_12_dialog_content = "내가 없더라도 노라가 경기를 방해할 순 없을 거야.",
  ui_story_1016_10161101_13_dialog_content = "그래, 네가 도와주면 연합 훈련도 분명히 무사히 끝나겠지.",
  ui_story_1016_10161101_14_dialog_content = "<color=#e8d9bb>같은 시간, 알골의 실험실</color>",
  ui_story_1016_10161101_15_dialog_content = "자, 됐어. 마지막 조정도 이걸로 끝났어.",
  ui_story_1016_10161101_16_dialog_content = "근데 제일 작은 애는 비행 속도가 좀 느린 것 같아.\n아마 부품이 노화돼서 그런 거겠지.",
  ui_story_1016_10161101_17_dialog_content = "어차피 걘 다른 용도가 있는 것도 아니니까, 여기 두고 가면 내가 정비해 줄게.",
  ui_story_1016_10161101_18_dialog_content = "괜찮습니다.",
  ui_story_1016_10161101_19_dialog_content = "악셀리아는 큐빅이 소매를 걷어줘야 합니다.",
  ui_story_1016_10161101_20_dialog_content = "큐빅이 없으면 악셀리아는 싸울 때 곤란해집니다.",
  ui_story_1016_10161101_21_dialog_content = "그래? 그럼 네 말대로 할게.",
  ui_story_1016_10161101_22_dialog_content = "라인하르트와의 경기가 끝나고 정비해도 늦지 않아.",
  ui_story_1016_10161101_23_dialog_content = "지금 큐빅은 가장 좋은 상태야. 마음껏 싸우고 와.",
  ui_story_1016_10161101_24_dialog_content = "알골은 큐빅의 제작자입니다. 큐빅 정비를 가장 잘하는 사람이기도 합니다.",
  ui_story_1016_10161101_25_dialog_content = "악셀리아는 알골을 신뢰하고 있습니다. 악셀리아가 큐빅을 신뢰하는 것과 같습니다.",
  ui_story_1016_10161101_26_dialog_content = "후훗, 고마워. 그렇게 말해 주니까 나도 기쁜걸.",
  ui_story_1016_10161101_27_dialog_content = "넌 어렸을 때부터 내가 살펴봤으니까, 돌봐주는 건 당연하지.",
  ui_story_1016_10161101_28_dialog_content = "지금 기분은 어때?",
  ui_story_1016_10161101_29_dialog_content = "악셀리아는 완벽한 상태입니다. 언제든지 싸울 수 있습니다.",
  ui_story_1016_10161101_30_dialog_content = "그래, 그럼 다행이네.",
  ui_story_1016_10161101_31_dialog_content = "근데 상태가 좋다고 라인하르트의 실력을 만만하게 보면 안 돼.",
  ui_story_1016_10161101_32_dialog_content = "구식 개조 기술로 강화된 오로리안이라곤 하지만,\n라인하르트는 여전히 일루미나에서 손꼽히는 강자야.",
  ui_story_1016_10161101_33_dialog_content = "그리고 네 몸은 너도 잘 알 거야. 절대로 능력을 과도하게 사용해선 안 돼.",
  ui_story_1016_10161101_34_dialog_content = "악셀리아는 마지막까지 싸워 승리합니다.",
  ui_story_1016_10161101_35_dialog_content = "의욕이 잔뜩이네. 말릴 수가 없다니까.",
  ui_story_1016_10161101_36_dialog_content = "그래도 절대 무리하진 마. 내가 말해도 안 듣겠지만.",
  ui_story_1016_10161101_37_dialog_content = "악셀리아는 율리시스 교수님의 명령에 복종합니다.",
  ui_story_1016_10161101_38_dialog_content = "때로는 다른 사람 의견도 들어야 하는 거야.",
  ui_story_1016_10161101_39_dialog_content = "이제 곧 경기 시간이구나. 그럼 이야기는 여기까지 해야겠네.",
  ui_story_1016_10161101_40_dialog_content = "경기장으로 가 봐.",
  ui_story_1016_10161101_41_dialog_content = "알겠습니다.",
  ui_story_1016_10161101_42_dialog_content = "승리를 기원할게.",
  ui_story_1016_10161101_43_dialog_content = "<color=#e8d9bb>경기장</color>",
  ui_story_1016_10161101_44_dialog_content = "지금부터 연합 훈련의 시범 경기를 진행하겠습니다!",
  ui_story_1016_10161101_45_dialog_content = "<size=45>와아아아아아!</size>",
  ui_story_1016_10161101_46_dialog_content = "먼저 일루미나 연방의 대원수, 여명의 빛,\n무패 전적의 라인하르트 님을 모시겠습니다!",
  ui_story_1016_10161101_47_dialog_content = "<size=45>대원수──! 대원수──!</size>",
  ui_story_1016_10161101_48_dialog_content = "모든 연합 훈련 참가자들, 고생 많았다!",
  ui_story_1016_10161101_49_dialog_content = "참가자 전원이 이 훈련에서 자신의 실력을 발휘하고 성장하는 모습을 잘 보았다.",
  ui_story_1016_10161101_50_dialog_content = "너희들의 성과를 진심으로 기쁘게 생각한다!",
  ui_story_1016_10161101_51_dialog_content = "<size=45>와아아아!</size>",
  ui_story_1016_10161101_52_dialog_content = "그리고 모든 시험을 통과하고 가장 우수한 성적을 거두어\n대원수님과의 대결 자격을 획득한 사람은 바로──",
  ui_story_1016_10161101_53_dialog_content = "일루미나 연방의 악셀리아입니다!",
  ui_story_1016_10161101_54_dialog_content = "악셀리아──!",
  ui_story_1016_10161101_55_dialog_content = "......",
  ui_story_1016_10161101_56_dialog_content = "악셀리아... 처음 듣는 이름인데 저렇게 강하다니!",
  ui_story_1016_10161101_57_dialog_content = "그러게 말이에요, 우리 일루미나 사람들도 다들 놀랐다니까요.",
  ui_story_1016_10161101_58_dialog_content = "우리조차 이름을 모르는 강자가 일루미나에 있을 줄 누가 알았겠어요.",
  ui_story_1016_10161101_59_dialog_content = "양 선수는 악수를 나눠 주시기 바랍니다.",
  ui_story_1016_10161101_60_dialog_content = "악셀리아...",
  ui_story_1016_10161101_61_dialog_content = "너에 대해서는 알고 있다. 막강한 실력을 가지고 있더군, 감탄했다.",
  ui_story_1016_10161101_62_dialog_content = "악셀리아는 대원수님의 인정에 감사드립니다.",
  ui_story_1016_10161101_63_dialog_content = "어때, 잘 쉬었나? 연합 훈련은 어제 막 끝났는데,\n오늘 또 시범 경기라니, 체력은 괜찮겠어?",
  ui_story_1016_10161101_64_dialog_content = "충분히 못 쉬었다고 봐주거나 하진 않을 거다.",
  ui_story_1016_10161101_65_dialog_content = "괜찮습니다, 악셀리아는...",
  ui_story_1016_10161101_66_dialog_content = "악셀리아는 이 순간을 위해 여기 서 있기 때문입니다.",
  ui_story_1016_10161101_67_dialog_content = "......!",
  ui_story_1016_10161101_68_dialog_content = "대원수님과 싸우는 것은 악셀리아의 사명입니다.",
  ui_story_1016_10161101_69_dialog_content = "악셀리아는 모든 가용 수단을 사용해 대원수님을 쓰러트리겠습니다.",
  ui_story_1016_10161101_70_dialog_content = "호오? 그렇다면 나도 네 활약을 기대하지.",
  ui_story_1016_10161101_71_dialog_content = "강한 후배와 겨뤄볼 수 있는 것도 무척 기쁜 일이니까.",
  ui_story_1016_10161101_72_dialog_content = "......",
  ui_story_1016_10161101_73_dialog_content = "(이 아이, 대체 어떻게 된 거지?)",
  ui_story_1016_10161101_74_dialog_content = "(이 표정... 어딘가 이상하군. 전혀 병사나 군인 같지 않아. 오히려...)",
  ui_story_1016_10161101_75_dialog_content = "(곧 죽으러 가는 사람의 얼굴 같잖아.)",
  ui_story_1016_10161101_76_dialog_content = "(저 아이의 눈에는 내가 그렇게나 무서운 건가?)",
  ui_story_1016_10161101_77_dialog_content = "(그게 아니라면...)",
  ui_story_1016_10161101_78_dialog_content = "그럼 두 선수, 각자 자리로 이동해 주십시오.\n이제 곧 경기를 시작하겠습니다!",
  ui_story_1016_10161101_79_dialog_content = "......",
  ui_story_1016_10161101_80_dialog_content = "경기를──",
  ui_story_1016_10161101_81_dialog_content = "<size=50><color=#FFB400>시작합니다!</color></size>",
  ui_story_1016_10161101_82_dialog_content = "──!",
  ui_story_1016_10161101_83_dialog_content = "큐빅!",
  ui_story_1016_10161101_84_dialog_content = "<size=45>!!!</size>",
  ui_story_1016_10161101_85_dialog_content = "(강하군!)",
  ui_story_1016_10161101_86_dialog_content = "(아무래도 나도 전력을 다할 수밖에 없겠어.)",
  ui_story_1016_10161101_87_dialog_content = "<color=#e8d9bb>콰아앙!</color>",
  ui_story_1016_10161101_88_dialog_content = "<size=45>대단해!</size>",
  ui_story_1016_10161101_89_dialog_content = "대원수── 대원수──!",
  ui_story_1016_10161101_90_dialog_content = "첫 공격, 명중했습니다. 공격의 효과는... 적에게 피해를 주지 못했습니다.",
  ui_story_1016_10161101_91_dialog_content = "적의 전력은 예상보다 다소 강하나, 대처 가능한 범위 내입니다.",
  ui_story_1016_10161101_92_dialog_content = "악셀리아, 출력을 높이겠습니다.",
  ui_story_1016_10161101_93_dialog_content = "3──",
  ui_story_1016_10161101_94_dialog_content = "(이건... 힘을 모으고 있는 건가?!)",
  ui_story_1016_10161101_95_dialog_content = "(막아야겠어!)",
  ui_story_1016_10161101_96_dialog_content = "2──",
  ui_story_1016_10161101_97_dialog_content = "<size=45>전부 꿰뚫어라!</size>",
  ui_story_1016_10161101_98_dialog_content = "──!",
  ui_story_1016_10161101_99_dialog_content = "방해된다!",
  ui_story_1016_10161101_100_dialog_content = "1!",
  ui_story_1016_10161101_101_dialog_content = "(늦은 건가?)",
  ui_story_1016_10161101_103_dialog_content = "가자, 나의 도끼창이여!",
  ui_story_1016_10161101_104_dialog_content = "오래 기다리셨습니다.",
  ui_story_1016_10161101_105_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_1016_10161101_106_dialog_content = "<size=45>엄청나!</size>",
  ui_story_1016_10161101_107_dialog_content = "콜록... 콜록, 콜록!",
  ui_story_1016_10161101_108_dialog_content = "으윽... 생각보다 꽤 아프잖아.",
  ui_story_1016_10161101_109_dialog_content = "너, 정말 대단한 녀석이네.",
  ui_story_1016_10161101_110_dialog_content = "두 번째 공격, 명중했습니다.",
  ui_story_1016_10161101_111_dialog_content = "루미나의 대부분이 적의 루미나틱스에 의해 상쇄되어 버렸습니다.\n공격의 효과가 부족합니다.",
  ui_story_1016_10161101_112_dialog_content = "악셀리아, 계속 출력을 높이겠습니다.",
  ui_story_1016_10161101_113_dialog_content = "(더 높일 수 있다고?!)",
  ui_story_1016_10161101_114_dialog_content = "(이 정도로 막강한 루미나라면 내 한계조차 뛰어넘는다.\n정면으로 부딪히면 곤란하겠지...)",
  ui_story_1016_10161101_115_dialog_content = "3──",
  ui_story_1016_10161101_116_dialog_content = "<color=#e8d9bb>콰직──</color>",
  ui_story_1016_10161101_117_dialog_content = "<size=45>!</size>",
  ui_story_1016_10161101_118_dialog_content = "(잠깐, 저 아이의 몸... <color=#FFB400>균열</color>인가?!)",
  ui_story_1016_10161101_119_dialog_content = "(신체가 붕괴하고 있잖아?! 저 엄청난 힘을 과도하게 사용한 게 원인인가...)",
  ui_story_1016_10161101_120_dialog_content = "(위원회 놈들, 저런 유리 대포를 만들어 내다니...)",
  ui_story_1016_10161101_121_dialog_content = "악셀리아, 멈춰라!",
  ui_story_1016_10161101_122_dialog_content = "이대로는 네 몸이 못 버틴다!",
  ui_story_1016_10161101_123_dialog_content = "으윽...",
  ui_story_1016_10161101_124_dialog_content = "2...",
  ui_story_1016_10161101_125_dialog_content = "말을 안 듣겠다는 거냐? 어쩔 수 없지...",
  ui_story_1016_10161101_126_dialog_content = "심판, 지금 당장 경기를 중단해라!",
  ui_story_1016_10161101_127_dialog_content = "이대로 경기를 계속하면 악셀리아의 목숨이 위험하다!",
  ui_story_1016_10161101_128_dialog_content = "당신네 대원수가 방금 뭐라고 한 거죠?",
  ui_story_1016_10161101_129_dialog_content = "모르겠어요. 아무것도 안 들리는데요...",
  ui_story_1016_10161101_130_dialog_content = "정숙하세요! 경기는 계속 진행됩니다.",
  ui_story_1016_10161101_131_dialog_content = "(심판도, 관객도 내 목소리가 안 들리는 건가? 이게 대체...)",
  ui_story_1016_10161101_132_dialog_content = "(경기장과 관중석 사이에... 희미한 <color=#FFB400>다크매터 장벽</color>이?! 언제 생긴 거지?!)",
  ui_story_1016_10161101_133_dialog_content = "(저게 내 목소리를 막은 건가? 그렇다면 우선 장벽을 깨는 수밖에!)",
  ui_story_1016_10161101_134_dialog_content = "<size=45>!!!</size>",
  ui_story_1016_10161101_135_dialog_content = "(움직임을 제한하겠다는 건가!)",
  ui_story_1016_10161101_136_dialog_content = "타깃... 록 온...",
  ui_story_1016_10161101_137_dialog_content = "1!",
  ui_story_1016_10161101_138_dialog_content = "<size=45>오래 기다리셨습니다!</size>",
  ui_story_1016_10161101_139_dialog_content = "......!",
  ui_story_1016_10161101_140_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_1016_10161101_141_dialog_content = "<color=#e8d9bb>같은 시간, 자난성</color>",
  ui_story_1016_10161101_142_dialog_content = "역 내부는 조사가 끝났다. 이상은 없었다.",
  ui_story_1016_10161101_143_dialog_content = "주변에도 문제는 없었어.",
  ui_story_1016_10161101_144_dialog_content = "이쪽도.",
  ui_story_1016_10161101_145_dialog_content = "PlayerName! 여기 문제가 생겼어!",
  ui_story_1016_10161101_146_dialog_content = "터널 보수 통로의 방어 시설이 전부 파괴되어 있어.\n그리고 암귀의 활동 흔적도 있는 것 같아!",
  ui_story_1016_10161101_147_dialog_content = "얼른 가서 확인해 보자!",
  ui_story_1016_10161101_148_dialog_content = "<anim type=Shake><size=50>크오오오──!</size></anim>",
  ui_story_1016_10161101_149_dialog_content = "역시 안에 암귀가 있었어!",
  ui_story_1016_10161101_150_dialog_content = "멋대로 굴게 놔둘 순 없지!",
  ui_story_1016_10161102_1_dialog_content = "녀석들은 지금쯤 자난성 안으로 들어갔겠지.",
  ui_story_1016_10161102_2_dialog_content = "하지만 아직 시간이 안 됐어. 여길 벗어날 수 없어.",
  ui_story_1016_10161102_3_dialog_content = "우린... 왜 숨어야 하는 거냐...",
  ui_story_1016_10161102_4_dialog_content = "어째서... 넌... 믿지 않는 거지?",
  ui_story_1016_10161102_5_dialog_content = "믿어?",
  ui_story_1016_10161102_6_dialog_content = "이 자난성 안에 이미 암귀의 스파이가 잔뜩 있다면?",
  ui_story_1016_10161102_7_dialog_content = "이 도시를 장악한 자들조차 암귀와 손을 잡고 있다면?",
  ui_story_1016_10161102_8_dialog_content = "그래도 넌 믿겠어?",
  ui_story_1016_10161102_9_dialog_content = "......",
  ui_story_1016_10161102_10_dialog_content = "네가 지금 믿을 수 있는 건 나뿐이야.",
  ui_story_1016_10161102_11_dialog_content = "널 구하고 여기서 벗어날 수 있는 건 나뿐이라고.",
  ui_story_1016_10161102_12_dialog_content = "......",
  ui_story_1016_10161102_13_dialog_content = "『노라 님.』",
  ui_story_1016_10161102_14_dialog_content = "『말해.』",
  ui_story_1016_10161102_15_dialog_content = "『피제로 님으로부터의 새로운 소식입니다.』",
  ui_story_1016_10161102_16_dialog_content = "『모든 준비가 끝났으니, 이제 퇴각하셔도 됩니다.』",
  ui_story_1016_10161102_17_dialog_content = "『이제서야 끝난 건가, 너흰 너무 느려.』",
  ui_story_1016_10161102_18_dialog_content = "『정말 죄송합니다.』",
  ui_story_1016_10161102_19_dialog_content = "『퇴각을 위한 비밀통로를 찾아 두었습니다.』",
  ui_story_1016_10161102_20_dialog_content = "『그 통로를 따라 자난성을 떠나시면 됩니다.』",
  ui_story_1016_10161102_21_dialog_content = "『위치는?』",
  ui_story_1016_10161102_22_dialog_content = "『정보는 여기 적혀 있습니다.』",
  ui_story_1016_10161102_23_dialog_content = "...무척 외진 곳이네.",
  ui_story_1016_10161102_24_dialog_content = "실험체, 가자.",
  ui_story_1016_10161201_1_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_1016_10161201_2_dialog_content = "<size=45>콜록콜록!</size>",
  ui_story_1016_10161201_3_dialog_content = "으윽...",
  ui_story_1016_10161201_4_dialog_content = "세 번째 공격... 콜록... 명중했습니다.",
  ui_story_1016_10161201_5_dialog_content = "공격은... 뚜렷한 효과를 보였습니다.",
  ui_story_1016_10161201_6_dialog_content = "공격을... 계속합니다.",
  ui_story_1016_10161201_7_dialog_content = "(하지만 악셀리아의 루미나가 부족합니다...)",
  ui_story_1016_10161201_8_dialog_content = "(조금 시간을 들여서 힘을 모아야만... 공격을 계속할 수 있습니다.)",
  ui_story_1016_10161201_9_dialog_content = "(이대로라면 저 아이는 죽는다.)",
  ui_story_1016_10161201_10_dialog_content = "(대체 무엇이 저 아이가 목숨까지 걸고 날 쓰러트리게 만드는 거지?)",
  ui_story_1016_10161201_11_dialog_content = "(설마... 율리시스... 위원회가 내린 명령인가?)",
  ui_story_1016_10161201_12_dialog_content = "큐빅!",
  ui_story_1016_10161201_13_dialog_content = "──!",
  ui_story_1016_10161201_14_dialog_content = "(공격 방식이 바뀌었군. 루미나도 아까보다 약해졌다.)",
  ui_story_1016_10161201_15_dialog_content = "(힘을 모아서 다음 공격을 준비하고 있는 거겠지.)",
  ui_story_1016_10161201_16_dialog_content = "(어쩌면 지금이 기회일지도 모른다.)",
  ui_story_1016_10161201_17_dialog_content = "악셀리아, 왜 그렇게까지 날 이기는 데 집착하는 거지?",
  ui_story_1016_10161201_18_dialog_content = "악셀리아는 해낼 수 있습니다. 따라서 악셀리아는 반드시 이겨야 합니다.",
  ui_story_1016_10161201_19_dialog_content = "그건 내 질문에 대한 답이 전혀 아니잖아.",
  ui_story_1016_10161201_20_dialog_content = "율리시스가 내린 명령이냐?",
  ui_story_1016_10161201_21_dialog_content = "......",
  ui_story_1016_10161201_22_dialog_content = "(부정하지 않는 걸 보면 위원회의 명령이 틀림없다.)",
  ui_story_1016_10161201_23_dialog_content = "(이렇게까지 날 쓰러트리고 더 많은 발언권을 얻는 데 급급하단 말인가.)",
  ui_story_1016_10161201_24_dialog_content = "(정말 놈들의 명령이라면 이 아이의 성격상 목숨을 걸고라도 해내려고 하겠지.)",
  ui_story_1016_10161201_25_dialog_content = "(하지만 지금은 위원회에게 더는 힘이 실리게 만들어선 안 된다.)",
  ui_story_1016_10161201_26_dialog_content = "(저 아이를 구하려면 먼저 제압해서 패배를 인정하게 할 수밖에 없다.)",
  ui_story_1016_10161201_27_dialog_content = "아직 끝나지 않았습니다...",
  ui_story_1016_10161201_28_dialog_content = "<size=45>허점이 보인다!</size>",
  ui_story_1016_10161201_29_dialog_content = "<color=#e8d9bb>채앵──!</color>",
  ui_story_1016_10161201_30_dialog_content = "네가 졌다.",
  ui_story_1016_10161201_31_dialog_content = "<size=50>우와아──!</size>",
  ui_story_1016_10161201_32_dialog_content = "대원수님이 상대를 제압했다!",
  ui_story_1016_10161201_33_dialog_content = "역시 이번에도 대원수의 승리인가요?",
  ui_story_1016_10161201_34_dialog_content = "......",
  ui_story_1016_10161201_35_dialog_content = "패배를 인정해라.",
  ui_story_1016_10161201_36_dialog_content = "네 의지는 이해한다. 하지만 우린 모두 질 수 없는 이유가 있다.",
  ui_story_1016_10161201_37_dialog_content = "난 널 해치고 싶지 않다. 그리고 네가 이렇게 자신을 해치는 걸 보고 싶지도 않다.",
  ui_story_1016_10161201_38_dialog_content = "넌 나보다 젊고 우수하다. 넌 일루미나 연방의 미래를 짊어질 희망이다.",
  ui_story_1016_10161201_39_dialog_content = "이런 곳에서 장래를 포기하지 마라.",
  ui_story_1016_10161201_40_dialog_content = "<anim type=Shake>악셀리아는...</anim>",
  ui_story_1016_10161201_41_dialog_content = "<anim type=Shake><size=45>악셀리아는... 아직 지지 않았습니다!</size></anim>",
  ui_story_1016_10161201_42_dialog_content = "?!",
  ui_story_1016_10161201_43_dialog_content = "큐빅!",
  ui_story_1016_10161201_44_dialog_content = "<color=#e8d9bb>쾅──!</color>",
  ui_story_1016_10161201_45_dialog_content = "으윽... 큭!",
  ui_story_1016_10161201_46_dialog_content = "(보기에 아무런 공격력도 없어 보이던 로봇이 폭발하다니!)",
  ui_story_1016_10161201_47_dialog_content = "(날 떼어내려고 그런 위험한 수를 쓰다니...\n저 아이가 나보다 더 중상을 입었을지도 모른다...)",
  ui_story_1016_10161201_48_dialog_content = "<anim type=Shake>아픕니다...</anim>",
  ui_story_1016_10161201_49_dialog_content = "<anim type=Shake>하지만 아직... 싸울 수... 있습니다...</anim>",
  ui_story_1016_10161201_50_dialog_content = "<anim type=Shake>악셀리아는... 패배를 인정하지 않습니다...</anim>",
  ui_story_1016_10161201_51_dialog_content = "(이미 각오했단 말이냐, 그렇다면 이 경기에는 이제 두 가지 결말밖에 남지 않았다...)",
  ui_story_1016_10161201_52_dialog_content = "(내가 승리하고, 저 아이가 목숨을 잃거나...)",
  ui_story_1016_10161201_53_dialog_content = "(저 아이가 힘을 다 쓰기 전에 내가 패배를 인정하거나...겠지.\n그렇게 하면 위원회의 뜻대로 되겠지만, 적어도 저 아이의 목숨은 구할 수 있다...)",
  ui_story_1016_10161201_54_dialog_content = "<anim type=Shake>악셀리아는... 임무를... 완수합니다... 대원수님을...</anim>",
  ui_story_1016_10161201_55_dialog_content = "<color=#e8d9bb>콰직──</color>",
  ui_story_1016_10161201_56_dialog_content = "<anim type=Shake>악셀리아는... 아직... 싸울 수...</anim>",
  ui_story_1016_10161201_57_dialog_content = "......",
  ui_story_1016_10161201_58_dialog_content = "뭐죠? 왜 반격하지 않는 거죠?",
  ui_story_1016_10161201_59_dialog_content = "대원수님! 반격하세요!",
  ui_story_1016_10161201_60_dialog_content = "그러게, 대체 무슨 일이지?",
  ui_story_1016_10161201_61_dialog_content = "보아하니 때가 된 모양이군.",
  ui_story_1016_10161201_62_dialog_content = "<color=#e8d9bb>치지직──</color>",
  ui_story_1016_10161201_63_dialog_content = "다음 행동을 시작하세요.",
  ui_story_1016_10161201_64_dialog_content = "확신이 있는 건가?",
  ui_story_1016_10161201_65_dialog_content = "그렇습니다.",
  ui_story_1016_10161201_66_dialog_content = "그녀는 이제 승리할 수 없습니다.",
  ui_story_1016_10161201_67_dialog_content = "<color=#e8d9bb>같은 시간, 자난성 깊은 곳</color>",
  ui_story_1016_10161201_68_dialog_content = "휴...휴우...",
  ui_story_1016_10161201_69_dialog_content = "암귀는... 어디 갔지?!",
  ui_story_1016_10161201_70_dialog_content = "암귀들이 우릴 보고 도망칠 줄이야, 게다가 도망치는 속도도 빠르잖아.",
  ui_story_1016_10161201_71_dialog_content = "여긴 어디지?",
  ui_story_1016_10161201_72_dialog_content = "바이스, 넌 알아?",
  ui_story_1016_10161201_73_dialog_content = "나도 모르겠어...",
  ui_story_1016_10161201_74_dialog_content = "자난성의 저층부에 가깝다는 것만 겨우 알아볼 수 있을 정도야.",
  ui_story_1016_10161201_75_dialog_content = "바이스 중위? PlayerName? 왜 여기 있는 거죠?",
  ui_story_1016_10161201_76_dialog_content = "음?",
  ui_story_1016_10161201_77_dialog_content = "당신들은 역 쪽을 조사하러 갔던 거 아니었습니까?",
  ui_story_1016_10161201_78_dialog_content = "잉겔 중령님?!",
  ui_story_1016_10161201_79_dialog_content = "여기서 모일 줄은 몰랐네.",
  ui_story_1016_10161201_80_dialog_content = "우린 역을 조사하다가 터널 보수 통로 안에서 암귀를 발견했어.",
  ui_story_1016_10161201_81_dialog_content = "맞아, 그 암귀들 우릴 보자마자 도망치길래 쫓아왔더니 여기까지 온 거야.",
  ui_story_1016_10161201_82_dialog_content = "너흰 왜 여기 있어? 성 내부 순찰하고 있던 거 아니었어?",
  ui_story_1016_10161201_83_dialog_content = "어쩌다 여기까지 온 거야?",
  ui_story_1016_10161201_84_dialog_content = "우리도 여러분과 비슷한 상황을 겪었습니다.",
  ui_story_1016_10161201_85_dialog_content = "무척 이상한 암귀였어요. 싸우려는 기색은 전혀 없더군요...",
  ui_story_1016_10161201_86_dialog_content = "어쩌면 저들의 음모일 수도 있어요. 최대한 경계하는 게 좋겠어요.",
  ui_story_1016_10161201_87_dialog_content = "나도 여기 뭔가 꿍꿍이가 있을 거라 생각해.",
  ui_story_1016_10161201_88_dialog_content = "그럼 어떻게 하지? 추격을 멈추고 내버려 둘까?",
  ui_story_1016_10161201_89_dialog_content = "그건 안 돼요!",
  ui_story_1016_10161201_90_dialog_content = "암귀가 자난성 안을 멋대로 다니게 만들면 더 위험해질 거예요.",
  ui_story_1016_10161201_91_dialog_content = "여긴 자난성의 심층부예요. 귀중한 과학 기술 설비가 대량으로 있는 곳이에요.\n그중 한 대라도 파괴된다면 일루미나에 중대한 손실을 끼치게 돼요.",
  ui_story_1016_10161201_92_dialog_content = "그러니까 쫓아야 해요. 놈들의 계략을 계획 단계에서 격파해야죠!",
  ui_story_1016_10161201_93_dialog_content = "PlayerName, 감응 능력으로 암귀가 어느 쪽으로 도망쳤는지 확인할 수 있겠어요?",
  ui_story_1016_10161201_94_dialog_content = "해볼게. 근데 여긴 지형이 복잡해서 감응 능력을 써도 대략적인 방향밖에 모를 거야...",
  ui_story_1016_10161201_95_dialog_content = "길을 어떻게 가야 할지는 나도 알 수가 없어.",
  ui_story_1016_10161201_96_dialog_content = "괜찮아요. 추적 경로는 제가 생각할 테니 방향만 알려주세요.",
  ui_story_1016_10161201_97_dialog_content = "알겠어, 그럼 해볼게.",
  ui_story_1016_10161201_98_option_content = "(강제 감응!)",
  ui_story_1016_10161201_99_dialog_content = "다크매터가 모여 있는 방향은... 이 아래야...",
  ui_story_1016_10161201_100_dialog_content = "...이건?",
  ui_story_1016_10161201_101_dialog_content = "<size=45>!!!</size>",
  ui_story_1016_10161201_102_dialog_content = "<color=#FFB400>피제로</color>가 여기 있어!",
  ui_story_1016_10161201_103_dialog_content = "그 <color=#FFB400>팬텀</color> 말하는 거야?! 지금 어디 있어?",
  ui_story_1016_10161201_104_dialog_content = "바로 밑이야! 아주 가까워!",
  ui_story_1016_10161201_105_dialog_content = "바로 밑...?",
  ui_story_1016_10161201_106_dialog_content = "(여긴 이미 자난성의 심층부와 가까운 곳이에요.\n여기서 더 아래로 내려가면 <color=#FFB400>가디언 1호</color>의 본체가 있는 곳인데...)",
  ui_story_1016_10161201_107_dialog_content = "(설마 이클립스가 가디언 1호를...?!)",
  ui_story_1016_10161201_108_dialog_content = "당장 쫓아야 해요! 따라와요!",
  ui_story_1016_10161201_109_dialog_content = "(처음 이 지하성을 건설했던 자는 분명히 머리에 문제가 있었던 모양이군.)",
  ui_story_1016_10161201_110_dialog_content = "(그렇지 않으면 복도를 이따위로 복잡하게 만들었을 리가 있나!)",
  ui_story_1016_10161201_111_dialog_content = "팬텀! 당장 멈추세요!",
  ui_story_1016_10161201_112_dialog_content = "더는 도망칠 수 없다. 지금 항복하는 게 좋을 거다.",
  ui_story_1016_10161201_113_dialog_content = "(뭐냐?! 어째서 추격자가...)",
  ui_story_1016_10161201_114_dialog_content = "(분명히 방해되는 오로리안은 전부 그 녀석이...)",
  ui_story_1016_10161201_114X1_dialog_content = "(흐음? <color=#FFB400>그 여자</color>는 어디 간 거지? 설마 벌써 <color=#FFB400>그곳</color>까지 간 거냐...?)",
  ui_story_1016_10161201_115_dialog_content = "제기랄! 어느 하나 날 방해하지 않는 녀석이 없군!",
  ui_story_1016_10161201_116_dialog_content = "너희들, 가서 놈들을 막아라!",
  ui_story_1016_10161201_117_dialog_content = "<anim type=Shake><size=45>크오오!</size></anim>",
  ui_story_1016_10161201_118_dialog_content = "멈춰!",
  ui_story_1016_10161301_1_dialog_content = "나는 줄곧 생각해 왔다.",
  ui_story_1016_10161301_2_dialog_content = "일루미나 연방에 있어서 무엇이 가장 중요한 것인가.",
  ui_story_1016_10161301_3_dialog_content = "강력한 선진 군비인가.",
  ui_story_1016_10161301_4_dialog_content = "훈련이 잘된 병사인가.",
  ui_story_1016_10161301_5_dialog_content = "아니면 첨단 기술인가.",
  ui_story_1016_10161301_6_dialog_content = "오랫동안 생각했지만 답은 얻지 못했다.",
  ui_story_1016_10161301_7_dialog_content = "그러다가 전장에 나선 뒤에야...",
  ui_story_1016_10161301_8_dialog_content = "나는 그곳에서 볼 수 있었다.",
  ui_story_1016_10161301_9_dialog_content = "인내.",
  ui_story_1016_10161301_10_dialog_content = "책임.",
  ui_story_1016_10161301_11_dialog_content = "그리고 희생을.",
  ui_story_1016_10161301_12_dialog_content = "그제야 비로소 나는 깨달았다.\n일루미나 연방에 있어서 가장 중요한 것은──",
  ui_story_1016_10161301_13_dialog_content = "<color=#FFB400>사람</color>이다.",
  ui_story_1016_10161301_14_dialog_content = "지상의 일루미나는 암귀를 막는 천연의 장벽도, 고대의 과학기술도 없다.",
  ui_story_1016_10161301_15_dialog_content = "그저 일루미나인들이 대를 이어 자신의 뜨거운 열정과 심혈로\n하나하나 지하성을 쌓아왔을 뿐이다.",
  ui_story_1016_10161301_16_dialog_content = "한 세대가 세상을 떠나면, 젊은 세대가 그 자리를 지탱한다.\n그렇게 대를 거듭하며 지금까지 이어져 온 것이다.",
  ui_story_1016_10161301_17_dialog_content = "분명히 모두의 생명은 귀한 것이다.\n그럼에도 자신의 동포들, 다음 세대가 더 나은 삶을 살 수 있도록──",
  ui_story_1016_10161301_18_dialog_content = "그들은 조금도 주저하지 않고 나섰다.",
  ui_story_1016_10161301_19_dialog_content = "그 어떤 생명도 내부 투쟁이라는 무의미한 일 따위에 희생돼서는 안 된다.",
  ui_story_1016_10161301_20_dialog_content = "그런 일은 무슨 수를 써서라도 서둘러 막아야 한다.\n그렇지 않으면 계속해서 되풀이될 뿐이다.",
  ui_story_1016_10161301_21_dialog_content = "지금 여기서 이 아이를 쓰러트린다 해도,\n저들은 이 아이와 같은 자들을 더 많이 보낼 것이다...",
  ui_story_1016_10161301_22_dialog_content = "지금 저들이 온갖 수단으로 날 패배시키려는 것은,\n그저 내가 대원수의 자리를 내놓게 만들고 싶어서일 뿐일지도 모른다.",
  ui_story_1016_10161301_23_dialog_content = "대원수의 자리는 물론 중요하다. 하지만 꼭 필요한 것은 아니다.\n고작 그 자리를 지키기 위해 동포의 목숨을 희생할 가치는 없다.",
  ui_story_1016_10161301_24_dialog_content = "적어도 지금은 이 아이의 목숨을 구해야 한다.",
  ui_story_1016_10161301_25_dialog_content = "그러니까...",
  ui_story_1016_10161301_26_dialog_content = "<size=45>멈춰라──!</size>",
  ui_story_1016_10161301_27_dialog_content = "<anim type=Shake>악셀리아는... 멈추지 않습니다...</anim>",
  ui_story_1016_10161301_28_dialog_content = "<color=#e8d9bb>덜커덩──</color>",
  ui_story_1016_10161301_29_dialog_content = "이제 그만둬라, <color=#FFB400>내가 패배를 인정하지</color>.",
  ui_story_1016_10161301_30_dialog_content = "네 뒤에 있는 그자들이 그토록 이 승리를 원한다면, 저들에게 가지라고 해라.",
  ui_story_1016_10161301_31_dialog_content = "하지만 난 네가 잘 살아갔으면 좋겠다.",
  ui_story_1016_10161301_32_dialog_content = "유리 대포나 쓸모 있는 도구로서가 아니라, 너라는 하나의 <color=#FFB400>인간</color>으로 살아가길 바란다.",
  ui_story_1016_10161301_33_dialog_content = "......!",
  ui_story_1016_10161301_34_dialog_content = "방금 뭐라고 하신 거죠?",
  ui_story_1016_10161301_35_dialog_content = "모르겠어요... 전혀 안 들려요.",
  ui_story_1016_10161301_36_dialog_content = "왜 무기를 버리신 거지? 뭔가 특별한 능력이라도 쓰시려는 건가?",
  ui_story_1016_10161301_37_dialog_content = "심판, 내 말이 들리겠지.",
  ui_story_1016_10161301_38_dialog_content = "대원수님... 지, 지금 뭐라고 하셨습니까?",
  ui_story_1016_10161301_39_dialog_content = "이제야 들리는 거냐. 하하하, 참 공교롭군.",
  ui_story_1016_10161301_40_dialog_content = "이 경기는 내가 졌다고 말했다.",
  ui_story_1016_10161301_41_dialog_content = "......",
  ui_story_1016_10161301_42_dialog_content = "하, 하지만...",
  ui_story_1016_10161301_43_dialog_content = "뭘 망설이고 있나? 결과를 선언해라.",
  ui_story_1016_10161301_44_dialog_content = "이 아이를 오래 기다리게 하지 마라.",
  ui_story_1016_10161301_45_dialog_content = "알겠습니다...그럼 선언하겠습니다... 경기가 종료되었습니다!",
  ui_story_1016_10161301_46_dialog_content = "대원수님께서 스스로 경기를 포기하셨으므로, 본 경기의 승자는──\n<color=#FFB400>악셀리아</color>입니다!",
  ui_story_1016_10161301_47_dialog_content = "<color=#e8d9bb>같은 시간, 자난성 깊은 곳</color>",
  ui_story_1016_10161301_48_dialog_content = "(드디어 여기까지 왔군. 허나 저 귀찮은 놈들도 따라와 버렸잖아.)",
  ui_story_1016_10161301_48X1_dialog_content = "(그 여자는 먼저 들어간 건가? 그럼 계획대로...)",
  ui_story_1016_10161301_49_dialog_content = "도망치게 두지 않습니다!",
  ui_story_1016_10161301_50_dialog_content = "<color=#e8d9bb>탕! 탕탕!</color>",
  ui_story_1016_10161301_51_dialog_content = "빌어먹을 계집이 잘도 끈질기게 쫓아오는구나!",
  ui_story_1016_10161301_52_dialog_content = "이런 곳까지 오게 되다니...",
  ui_story_1016_10161301_53_dialog_content = "허억, 헉... 드디어 따라잡았어!",
  ui_story_1016_10161301_53X1_dialog_content = "아이테르, 또 만났군.",
  ui_story_1016_10161301_53X2_dialog_content = "저번에 탑에서는 정말 크게 한 방 먹었었지...\n그 덕에 이 몸은 그간 기분이 몹시 좋지 않았다.",
  ui_story_1016_10161301_53X3_dialog_content = "또 무슨 짓을 하려는 거야?!",
  ui_story_1016_10161301_53X4_dialog_content = "이번에는 절대 놓치지 않겠어!",
  ui_story_1016_10161301_53X5_dialog_content = "여긴 이미 막다른 길이야! 넌 이제 도망칠 곳도 없어!",
  ui_story_1016_10161301_53X6_dialog_content = "크크크크, 그렇게 흥분하지 마라.",
  ui_story_1016_10161301_54_dialog_content = "내 추측이 맞다면 여기가 바로 자난성의 최하부겠지?",
  ui_story_1016_10161301_55_dialog_content = "저 문은 정말 튼튼해 보이네. 안에 분명히 아주 중요한 게 들어 있을 것 같은데.",
  ui_story_1016_10161301_56_dialog_content = "저 안에는 가디언 1호의 본체가 있어요. 절대 이클립스 놈들이 손대게 둬선 안 돼요!",
  ui_story_1016_10161301_57_dialog_content = "가디언 1호?! 그거 분명히 나보다 작았잖아?",
  ui_story_1016_10161301_58_dialog_content = "그 캐터필러 로봇은 가디언 1호의 단말기에 불과해요.",
  ui_story_1016_10161301_59_dialog_content = "진짜 본체는 바로 저 안에 있어요.",
  ui_story_1016_10161301_60_dialog_content = "자난성만이 아니라 일루미나 전체의 방어 시설이\n가디언 1호에 의해 자동 제어되고 있다고 들었습니다.",
  ui_story_1016_10161301_61_dialog_content = "가디언 1호에 문제가 생긴다면 연방이 위험해질 겁니다!",
  ui_story_1016_10161301_62_dialog_content = "<size=45>크크크크크!</size>",
  ui_story_1016_10161301_63_dialog_content = "애송이, 네 말이 맞다.",
  ui_story_1016_10161301_64_dialog_content = "하지만 늦었다. 우리 쪽 사람이 이미 들어갔으니 말이야.",
  ui_story_1016_10161301_65_dialog_content = "뭐라고요?!",
  ui_story_1016_10161301_66_dialog_content = "대체 어떻게... 분명히 키가 없으면 들어갈 수 없을 텐데...",
  ui_story_1016_10161301_67_dialog_content = "그 답은 알아서 찾아라.",
  ui_story_1016_10161301_68_dialog_content = "<size=30>이제 조금만 더, 조금만 더 있으면 이클립스도 더는 날...</size>",
  ui_story_1016_10161301_69_dialog_content = "가라, 놈들을 막아라!",
  ui_story_1016_10161301_70_dialog_content = "크오오!",
  ui_story_1016_10161301_71_dialog_content = "다 같이 공격하자! 멋대로 하게 둘 순 없어!",
  ui_story_1016_10161302_1_dialog_content = "<color=#e8d9bb>자난성 주거 구역 어딘가</color>",
  ui_story_1016_10161302_2_dialog_content = "<color=#e8d9bb>콰앙!</color>",
  ui_story_1016_10161302_3_dialog_content = "딱히 비밀 실험실도 아니었네. 그냥 평범한 주택이었잖아.",
  ui_story_1016_10161302_4_dialog_content = "이런 외딴곳에 밖으로 통하는 통로가 있는 건가?",
  ui_story_1016_10161302_5_dialog_content = "넌... 여길 떠날 생각이냐...",
  ui_story_1016_10161302_6_dialog_content = "어째서...",
  ui_story_1016_10161302_7_dialog_content = "여긴 이제 물러설 곳이 없어.",
  ui_story_1016_10161302_8_dialog_content = "일루미나는 이미 널 버렸고, 나도 버렸어. 이대로 남아봤자 의미가 없어.",
  ui_story_1016_10161302_9_dialog_content = "그래... 위원회는... 우릴 버렸지...",
  ui_story_1016_10161302_10_dialog_content = "...생각이 났어...",
  ui_story_1016_10161302_11_dialog_content = "뭐가 생각났는데?",
  ui_story_1016_10161302_12_dialog_content = "......",
  ui_story_1016_10161302_13_dialog_content = "전부.",
  ui_story_1016_10161302_14_dialog_content = "과거의 기억도, 그때의 싸움도... 끝없이 기다리는 날들도.",
  ui_story_1016_10161302_15_dialog_content = "그리고 절망도.",
  ui_story_1016_10161302_16_dialog_content = "그럼 너도 지금 네 상황을 이해할 수 있겠네.",
  ui_story_1016_10161302_17_dialog_content = "한때 네가 가졌던 모든 건 이제 어디에도 없어.",
  ui_story_1016_10161302_18_dialog_content = "넌 더는 일루미나의 군인이 아니라 그냥 도주범, 괴물일 뿐이야.",
  ui_story_1016_10161302_19_dialog_content = "살아남고 싶다면 통로 찾는 거나 도와줘.",
  ui_story_1016_10161302_20_dialog_content = "그럴 필요 없습니다.",
  ui_story_1016_10161302_21_dialog_content = "여긴 출구 같은 건 없으니까요.",
  ui_story_1016_10161302_22_dialog_content = "......",
  ui_story_1016_10161302_23_dialog_content = "흥, 그게 너희 계획이었구나.",
  ui_story_1016_10161302_24_dialog_content = "뭐, 의외는 전혀 아니야.",
  ui_story_1016_10161302_25_dialog_content = "투항하고 실험 성과를 넘기세요.",
  ui_story_1016_10161302_26_dialog_content = "협조한다면 덜 비참하게 죽도록 해드릴 순 있을 겁니다.",
  ui_story_1016_10161302_27_dialog_content = "비켜.",
  ui_story_1016_10161302_28_dialog_content = "아무래도 협조할 의향이 없는 모양이군요.",
  ui_story_1016_10161302_29_dialog_content = "그럼 절 원망하지 마십시오.",
  ui_story_1016_10161302_30_dialog_content = "너희들... 뭘 하려는 거냐!",
  ui_story_1016_10161302_31_dialog_content = "붙잡으세요.",
  ui_story_1016_10161302_32_dialog_content = "예!",
  ui_story_1016_10161302_33_dialog_content = "분수도 모르는구나.",
  ui_story_1016_10161302_34_dialog_content = "<size=45>방어하라!</size>",
  ui_story_1016_10161302_35_dialog_content = "<color=#e8d9bb>콰앙!</color>",
  ui_story_1016_10161302_36_dialog_content = "......",
  ui_story_1016_10161302_37_dialog_content = "쓸데없는 저항은 그만하시죠.",
  ui_story_1016_10161302_38_dialog_content = "이 병사들은 모두 당신을 상대하기 위해 과학 수석 의회가\n개발한 방어 장비를 갖추고 있습니다.",
  ui_story_1016_10161302_39_dialog_content = "우린 방어가 무너지기 전에 당신을 붙잡을 겁니다.",
  ui_story_1016_10161302_40_dialog_content = "너희도 조금은 배운 모양이네.",
  ui_story_1016_10161302_41_dialog_content = "하지만 여전히 어리석은 녀석들이야.",
  ui_story_1016_10161302_42_dialog_content = "<color=#e8d9bb>같은 시간, 결승전 현장</color>",
  ui_story_1016_10161302_43_dialog_content = "악셀리아가... 이긴 겁니까?",
  ui_story_1016_10161302_44_dialog_content = "그래, 네가 이겼다.",
  ui_story_1016_10161302_45_dialog_content = "그러니 멈추고, 더는 자신을 해치지 마라.",
  ui_story_1016_10161302_46_dialog_content = "......",
  ui_story_1016_10161302_47_dialog_content = "뭐라고요? 제가 잘못 들은 거 아니죠?",
  ui_story_1016_10161302_48_dialog_content = "그 전설의 라인하르트가 졌다고요?",
  ui_story_1016_10161302_49_dialog_content = "어떻게 이런 일이...",
  ui_story_1016_10161302_50_dialog_content = "어째서...",
  ui_story_1016_10161302_51_dialog_content = "<size=45>대체 뭐 하는 짓거리야?!</size>",
  ui_story_1016_10161302_52_dialog_content = "라인하르트가 패배를 인정했다고? 애초에 진지하게 싸우지도 않았잖아!",
  ui_story_1016_10161302_53_dialog_content = "너희 빌어먹을 늙다리들, 또 무슨 개 같은 수작을 부린 거야?!",
  ui_story_1016_10161302_54_dialog_content = "바튼 군단장님, 지나친 언사는 삼가 주십시오! 이건 정식 경기입니다!",
  ui_story_1016_10161302_55_dialog_content = "진정하세요, 바튼 장군.",
  ui_story_1016_10161302_56_dialog_content = "지금은 분노에 이성을 잃을 때가 아니에요.",
  ui_story_1016_10161302_57_dialog_content = "라인하르트가 내린 결정이라면 분명히 무슨 이유가 있을 거야.",
  ui_story_1016_10161302_58_dialog_content = "난 라인하르트의 선택을 믿어. 나중에 무슨 일인지 물어보면 돼.",
  ui_story_1016_10161302_59_dialog_content = "<size=45>뭔가 잘못된 거 아냐?!</size>",
  ui_story_1016_10161302_60_dialog_content = "<size=45>이렇게 끝이라고? 대체 뭐가 어떻게 된 거야?!</size>",
  ui_story_1016_10161302_61_dialog_content = "모두 정숙하십시오!",
  ui_story_1016_10161302_62_dialog_content = "경기 결과를 존중해야 합니다!",
  ui_story_1016_10161302_63_dialog_content = "참 떠들썩하군.",
  ui_story_1016_10161302_64_dialog_content = "시간도 이쯤이면 됐겠지.",
  ui_story_1016_10161302_65_dialog_content = "율리시스 님! 보고드립니다!",
  ui_story_1016_10161302_66_dialog_content = "말하게.",
  ui_story_1016_10161302_67_dialog_content = "다름이 아니라...",
  ui_story_1016_10161302_68_dialog_content = "음, 흐음... 잘 알겠네.",
  ui_story_1016_10161302_69_dialog_content = "이제 가도 좋네.",
  ui_story_1016_10161302_70_dialog_content = "예.",
  ui_story_1016_10161302_71_dialog_content = "심판, 잠깐 마이크를 좀 빌려줄 수 있겠나?",
  ui_story_1016_10161302_72_dialog_content = "예? 하, 하지만...",
  ui_story_1016_10161302_73_dialog_content = "긴급 상황을 선포해야 하네.",
  ui_story_1016_10161302_74_dialog_content = "위원회의 이름으로 말이야.",
  ui_story_1016_10161302_75_dialog_content = "아, 알겠습니다...",
  ui_story_1016_10161302_76_dialog_content = "크흠... 여러분, 정숙해 주시지요. 지금부터 긴급명령을 발포하겠습니다.",
  ui_story_1016_10161302_77_dialog_content = "뭐? 긴급명령?",
  ui_story_1016_10161302_78_dialog_content = "긴급명령이라고?",
  ui_story_1016_10161302_79_dialog_content = "저 하나같이 빌어 처먹을 늙다리 자식들...",
  ui_story_1016_10161302_80_dialog_content = "또 무슨 개수작을 부리려는 거겠지.",
  ui_story_1016_10161302_81_dialog_content = "뭔가 안 좋은 예감이 드는군요...",
  ui_story_1016_10161302_82_dialog_content = "방금 우리 위원회는 경악할 만한 정보를 입수했습니다.",
  ui_story_1016_10161302_83_dialog_content = "위원회의 정보장교가 자난성에서 수배범 노라와 헬리오스의 행적을\n포착하고 그 은신처를 알아냈습니다.",
  ui_story_1016_10161302_84_dialog_content = "말도 안 돼! 자난성 수색은 줄곧 내가 담당하고 있었어.\n지도를 토대로 성 전역을 철저하게 수색하고 있었다고.",
  ui_story_1016_10161302_85_dialog_content = "하지만 나와 내 순찰대는 노라의 그림자조차 못 봤어!",
  ui_story_1016_10161302_86_dialog_content = "그건 당신들의 능력 부족을 증명할 뿐이지 않습니까.",
  ui_story_1016_10161302_87_dialog_content = "정보장교들은 노라를 추적하는 동시에, 노라가 몸을 숨기고 있던 비밀 통로를 발견했습니다.\n그 통로는 지도에 표기되지 않은 것이었지요.",
  ui_story_1016_10161302_88_dialog_content = "그리고 그 통로 끝은...\n유감스럽게도 라인하르트 대원수의 자택 근처로 이어지고 있었습니다.",
  ui_story_1016_10161302_89_dialog_content = "그 후 정보장교는 상대의 경계가 풀릴 때까지 잠시 동안 노라를 미행했고,\n노라가 당당하게 라인하르트의 자택으로 들어가는 것을 발견했습니다.",
  ui_story_1016_10161302_90_dialog_content = "<size=45>뭐라고?! 그게 무슨 말이냐!</size>",
  ui_story_1016_10161302_91_dialog_content = "......",
  ui_story_1016_10161302_92_dialog_content = "그랬군. 그게 네놈들 계획이었나...",
  ui_story_1016_10161302_93_dialog_content = "무슨 헛소리야?!",
  ui_story_1016_10161302_94_dialog_content = "이 늙다리 놈들이...",
  ui_story_1016_10161302_95_dialog_content = "전장에 나서는 꼴은 보이지도 않는 것들이 모욕 하나는 끝내주게 하는군!",
  ui_story_1016_10161302_96_dialog_content = "이 건에 대해서는 제대로 된 증거를 제시하는 게 좋을 겁니다.",
  ui_story_1016_10161302_97_dialog_content = "그래. 아니면 이 칼이 동지의 명예를 더럽힌 자를 용서하지 않을 거다.",
  ui_story_1016_10161302_98_dialog_content = "조용히, 일단 조용히 해 주세요.",
  ui_story_1016_10161302_99_dialog_content = "여러분이 초조해하는 것도 잘 압니다.\n위원회도 처음에는 이러한 사실을 믿고 싶지 않았습니다.",
  ui_story_1016_10161302_100_dialog_content = "하지만 확고한 증거가 있습니다. 순찰대원들이 모두 증인입니다.",
  ui_story_1016_10161302_101_dialog_content = "현재 두 수배범은 자난성 내에서 도주 중입니다.",
  ui_story_1016_10161302_102_dialog_content = "정말 황당하기 짝이 없네요! 이만 돌아가야겠어요!",
  ui_story_1016_10161302_103_dialog_content = "그 수배범이 사고라도 치면 어떡하려고 그러죠?\n설마 이대로 잠자코 당하길 기다리라는 건가요?!",
  ui_story_1016_10161302_104_dialog_content = "걱정할 필요 없습니다. 경기장 주변에는 삼엄한 경비를 펼치고 있습니다.\n일루미나의 위원회는 여러분의 안전을 보장할 것입니다.",
  ui_story_1016_10161302_105_dialog_content = "단, 그 전에 위원회는 결정을 내리고자 합니다.",
  ui_story_1016_10161302_106_dialog_content = "라인하르트는 적과 내통하고 도주범을 숨긴 혐의가 있습니다.",
  ui_story_1016_10161302_107_dialog_content = "따라서 위원회는 라인하르트를 대원수 직위에서 해임하는 바입니다.",
  ui_story_1016_10161302_108_dialog_content = "또한, 위원회의 조사에 협조해 주시기 바랍니다.",
  ui_story_1016_10161401_1_dialog_content = "<color=#e8d9bb>위이잉──</color>",
  ui_story_1016_10161401_2_dialog_content = "불법 침입 감지, 불법 침입 감지!",
  ui_story_1016_10161401_2X1_dialog_content = "역시 안에 누군가 있군요!\n비켜라, 팬텀!",
  ui_story_1016_10161401_3_dialog_content = "크크, 내게 조금이라도 존중의 태도를 보이는 게 좋을 거다.\n그러면 내가 널 죽일 때 고통은 덜어줄 수 있으니 말이야.",
  ui_story_1016_10161401_4_dialog_content = "다른 놈들은...",
  ui_story_1016_10161401_5_dialog_content = "너희가 처리해라.",
  ui_story_1016_10161401_6_dialog_content = "<anim type=Shake><size=45>크오오오──!</size></anim>",
  ui_story_1016_10161401_7_dialog_content = "얼어붙어라!",
  ui_story_1016_10161401_8_dialog_content = "<anim type=Shake>크에엑...</anim>",
  ui_story_1016_10161401_9_dialog_content = "『피제로 님, 이제 병력이 얼마 없습니다...』",
  ui_story_1016_10161401_10_dialog_content = "죽는 게 너희 사명이다! 군소리 말고 죽어라!",
  ui_story_1016_10161401_11_dialog_content = "저 여자에게 시간만 벌어주고 나면 이 오로리안들은 끝이다!",
  ui_story_1016_10161401_12_dialog_content = "<color=#e8d9bb>위이잉──</color>",
  ui_story_1016_10161401_24_dialog_content = "흐흐... <size=50>흐하하하!</size>",
  ui_story_1016_10161401_26_dialog_content = "지금 바로 증명해 주지! 난 아직 남을 자격이 있다고!",
  ui_story_1016_10161401_27_dialog_content = "(남을 자격? 설마 이클립스에서 제명이라도 당하는 건가?)",
  ui_story_1016_10161401_28_dialog_content = "주변을 보시죠.",
  ui_story_1016_10161401_29_dialog_content = "당신 부하들은 우리가 모두 쓰러트렸습니다.",
  ui_story_1016_10161401_30_dialog_content = "지금의 당신은 부하 없는 사령관일 뿐입니다.",
  ui_story_1016_10161401_31_dialog_content = "부하 없는 사령관?",
  ui_story_1016_10161401_32_dialog_content = "그래서 뭐가 어쨌다는 것이냐.\n나 혼자라도 네놈들 같은 벌레 정도는 짓밟아 줄 수 있다.",
  ui_story_1016_10161401_33_dialog_content = "<anim type=Shake><size=45>크아아아──!</size></anim>",
  ui_story_1016_10161401_34_dialog_content = "뭘 하려는 거지?",
  ui_story_1016_10161401_35_dialog_content = "PlayerName! 조심해!",
  ui_story_1016_10161401_36_dialog_content = "<anim type=Shake><size=45>크크크크크!</size></anim>",
  ui_story_1016_10161401_37_dialog_content = "진정한 힘을 해방시키는 건 참으로 오랜만이로구나!",
  ui_story_1016_10161401_38_dialog_content = "이 힘은 북방의 그 계집을 상대할 때 쓸 생각이었거늘...",
  ui_story_1016_10161401_39_dialog_content = "우선 네놈들 몸에 구멍을 내서 예전 감각을 되찾도록 하지!",
  ui_story_1016_10161401_40_dialog_content = "두려워해라! 전율해라!",
  ui_story_1016_10161401_41_dialog_content = "마지막 유언이나 생각해라!",
  ui_story_1016_10161402_0X1_dialog_content = "빌어먹을, 벌레 놈들이... 날 이 정도로 몰아붙이다니...",
  ui_story_1016_10161402_0X2_dialog_content = "죽어라! 모두 죽으란 말이다!",
  ui_story_1016_10161402_0X3_dialog_content = "위험해! 아직 힘이 남아 있어!",
  ui_story_1016_10161402_0X4_dialog_content = "그리고 아이테르 네놈! 너흰 진작에 죽어 없어졌단 말이다!",
  ui_story_1016_10161402_0X5_dialog_content = "물러서! PlayerName!",
  ui_story_1016_10161402_0X6_dialog_content = "날 막지 마라!",
  ui_story_1016_10161402_0X7_dialog_content = "으악!",
  ui_story_1016_10161402_0X8_dialog_content = "<color=#e8d9bb>위이잉──</color>",
  ui_story_1016_10161402_0X9_dialog_content = "(?!)",
  ui_story_1016_10161402_0X10_dialog_content = "(그 아이 건드리지 마.)",
  ui_story_1016_10161402_0X11_dialog_content = "(물건은 찾았나? 그럼 뭘 기다리고 있는 거냐. 빨리 나와서 여길...)",
  ui_story_1016_10161402_0X12_dialog_content = "(그 아이 몸에서 손 떼.)",
  ui_story_1016_10161402_0X13_dialog_content = "(난 분명히 경고했어.)",
  ui_story_1016_10161402_1_dialog_content = "<anim type=Shake><size=45>제기랄!</size></anim>",
  ui_story_1016_10161402_2_dialog_content = "<anim type=Shake>이... 빌어먹을... 오로리안 놈들...!</anim>",
  ui_story_1016_10161402_3_dialog_content = "<anim type=Shake>빌어먹을 오로리안! ...노라! ...이클립스!</anim>",
  ui_story_1016_10161402_4_dialog_content = "<anim type=Shake>전부 죽여주마!</anim>",
  ui_story_1016_10161402_4X1_dialog_content = "크윽...",
  ui_story_1016_10161402_5_dialog_content = "바이스!!",
  ui_story_1016_10161402_6_dialog_content = "<anim type=Shake>죽더라도 벌레 놈들 따위에게 당하진 않을 거다!</anim>",
  ui_story_1016_10161402_7_dialog_content = "<color=#e8d9bb>탕──!</color>",
  ui_story_1016_10161402_7X1_dialog_content = "<color=#e8d9bb>위이잉──!</color>",
  ui_story_1016_10161402_8_dialog_content = "──!!!",
  ui_story_1016_10161402_9_dialog_content = "말이 정말 많네요.",
  ui_story_1016_10161402_10_dialog_content = "콜록, 콜록콜록...",
  ui_story_1016_10161402_10X1_dialog_content = "바이스! 괜찮아?!",
  ui_story_1016_10161402_11_dialog_content = "어서 이쪽으로 피해! 기절한 척하다가 기습할지도 몰라!",
  ui_story_1016_10161402_12_dialog_content = "제가 확인해보죠.",
  ui_story_1016_10161402_13_dialog_content = "......",
  ui_story_1016_10161402_14_dialog_content = "문제는 없어 보입니다. 확실히 의식을 잃었습니다.",
  ui_story_1016_10161402_15_dialog_content = "아직 살아있습니다. 그저 기절했을 뿐입니다.",
  ui_story_1016_10161402_15X1_dialog_content = "(방금 제 공격... 어떻게 그런 위력을 냈던 거죠?)",
  ui_story_1016_10161402_15X2_dialog_content = "(대체 무슨...)",
  ui_story_1016_10161402_16_dialog_content = "그렇다면 이 검으로 끝을 내서 스러진 영령들을 달래주겠어.",
  ui_story_1016_10161402_17_dialog_content = "멈추세요! 죽이면 안 돼요!",
  ui_story_1016_10161402_18_dialog_content = "음?",
  ui_story_1016_10161402_19_dialog_content = "당부했을 텐데요. 노라나 다른 팬텀을 잡으면 일루미나에게 인도해 달라고 말이에요.",
  ui_story_1016_10161402_20_dialog_content = "...그랬었지. 뭐, 그렇게 하자고.",
  ui_story_1016_10161402_21_dialog_content = "하지만 이 녀석은 거의 죽은 거나 다름없어.\n심문을 하더라도 알아낼 수 있는 건 없을걸.",
  ui_story_1016_10161402_22_dialog_content = "그건 우리 문제예요. 당신이 걱정할 필요는 없어요.",
  ui_story_1016_10161402_23_dialog_content = "왜 살려주는 건데? 저놈 때문에 수많은 사람들이 죽었어!",
  ui_story_1016_10161402_24_dialog_content = "PlayerName, 진정하세요. 당신 마음은 이해해요.",
  ui_story_1016_10161402_25_dialog_content = "하지만 잘 생각해 보세요.\n지금까지 아스트라에는 팬텀에 관한 연구 기록이 전혀 없었어요.",
  ui_story_1016_10161402_26_dialog_content = "게다가 이자는 <color=#FFB400>이클립스</color>에 관한 중요한 정보를 가지고 있을지도 몰라요.",
  ui_story_1016_10161402_27_dialog_content = "더욱 중요한 건, 이런 곳까지 아무 어려움 없이 들어올 수 있었던 건...",
  ui_story_1016_10161402_28_dialog_content = "분명히 배후에 신뢰할 만한 정보원이 있는 거겠죠.",
  ui_story_1016_10161402_29_dialog_content = "그 배후에서 계획을 세운 사람은 일루미나 내부의 반역자일 가능성이 높아요.",
  ui_story_1016_10161402_30_dialog_content = "당신 말에 일리는 있어. 그래도 미안하지만 난 찬성할 수 없어.",
  ui_story_1016_10161402_31_dialog_content = "팬텀에 관한 연구가 없다는 건, 일루미나 연방에서도 저자를\n완전히 통제할 수 있다는 보장은 못 한다는 뜻이 되겠지.",
  ui_story_1016_10161402_32_dialog_content = "깨어난 뒤에 통제를 벗어나 도망치면 그땐 어쩔 생각이지?",
  ui_story_1016_10161402_33_dialog_content = "일루미나는 그런 일이 일어나지 않도록 모든 수단을 다해 노력할 거예요.",
  ui_story_1016_10161402_34_dialog_content = "당신들은 절대적인 안전을 보장할 수 없어.",
  ui_story_1016_10161402_35_dialog_content = "그렇다고 위험이 있다는 이유로 나아갈 가능성을 버리고 제자리에 머무를 순 없어요.",
  ui_story_1016_10161402_36_dialog_content = "......",
  ui_story_1016_10161402_37_dialog_content = "좋아, 당신 뜻대로 해.",
  ui_story_1016_10161402_38_dialog_content = "바이스, 아나톨리, 그리고 PlayerName, 여러분은 다른 의견이 있나요?",
  ui_story_1016_10161402_39_dialog_content = "저, 전 없습니다.",
  ui_story_1016_10161402_40_dialog_content = "중령님께서 그렇게 결정하셨다면, 저도 다른 의견은 없습니다.",
  ui_story_1016_10161402_41_option_content = "나도 없어.",
  ui_story_1016_10161402_42_option_content = "난 동의 못 해.",
  ui_story_1016_10161402_43_dialog_content = "카렌 말이 맞아. 나도 이놈이 도망칠까 그게 걱정이야.",
  ui_story_1016_10161402_44_dialog_content = "이렇게 벅찬 상대를 겨우 쓰러트렸는데,\n지금 놓치면 앞으론 더 상대하기 힘들 거잖아!",
  ui_story_1016_10161402_45_dialog_content = "게다가 이놈은 수많은 사람들을 해쳤어... 그러니까...",
  ui_story_1016_10161402_46_dialog_content = "당신 생각은 알겠어요. 하지만 제 생각도 변하지 않아요.",
  ui_story_1016_10161402_47_dialog_content = "부디 제게, 그리고 일루미나 연방의 동료들에게 한 번만 기회를 주세요.",
  ui_story_1016_10161402_48_dialog_content = "너무나도 많은 동포들이 적의 정보를 얻기 위해 목숨을 바쳐 왔어요.\n이런 절호의 기회를 이대로 놓칠 순 없어요!",
  ui_story_1016_10161402_49_dialog_content = "......",
  ui_story_1016_10161402_50_dialog_content = "......",
  ui_story_1016_10161402_51_dialog_content = "알겠어.",
  ui_story_1016_10161402_52_dialog_content = "협조해 주셔서 감사합니다.",
  ui_story_1016_10161402_53_dialog_content = "즉시 정보부에 연락해서 팬텀을 수용하고 심문을 개시하도록 할게요.",
  ui_story_1016_10161402_54_dialog_content = "하지만 우리 임무는 아직 끝나지 않았습니다.\n저 문 너머에는 아마 저자의 동료가 있을 겁니다.",
  ui_story_1016_10161402_55_dialog_content = "맞아요. 게다가 가장 중요한 가디언 1호도 저 안에 있죠...",
  ui_story_1016_10161402_56_dialog_content = "뭐, 어떤 적이든 얼마든지 오라고.",
  ui_story_1016_10161402_57_dialog_content = "그저 이 모든 게 빨리 끝났으면 좋겠군요.",
  ui_story_1016_10161402_58_dialog_content = "(악셀리아 쪽은 어떻게 되었을까요, 악셀리아는... 살아 있을까요?)",
  ui_story_1016_10161402_59_dialog_content = "(분명히 목숨을 걸 각오를 했는데, 어째서 그 아이가 가는 모습을 보면...)",
  ui_story_1016_10161402_60_dialog_content = "여러분! 대비하세요!",
  ui_story_1016_10161402_61_dialog_content = "문이 움직이려는 것 같아요!",
  ui_story_1016_10161402_62_dialog_content = "(이 기운...!)",
  ui_story_1016_10161402_63_dialog_content = "<color=#e8d9bb>쿠르릉──</color>",
  ui_story_1016_10161402_64_dialog_content = "<color=#e8d9bb>위잉── 위잉──</color>",
  ui_story_1016_10161402_65_dialog_content = "다시 전투 준비를 하자. PlayerName!",
  ui_story_1016_10161402_66_dialog_content = "대형을 유지하고 허점을 숨기세요!",
  ui_story_1016_10161402_67_dialog_content = "<color=#e8d9bb>콰아앙──</color>",
  ui_story_1016_10161402_68_dialog_content = "안에서 누가 나오는데?!",
  ui_story_1016_10161402_69_dialog_content = "......!",
  ui_story_1016_10161402_70_dialog_content = "(낯선 모습의 존재가 거대한 문 안에서 모습을 드러냈다.)",
  ui_story_1016_10161402_71_dialog_content = "(그 순간, 나는 그 사람에게서 피제로보다 훨씬 강력한 다크매터를 느낄 수 있었다.)",
  ui_story_1016_10161402_72_dialog_content = "(우린 방금 피제로를 쓰러트리느라 너무 많은 힘을 써버린 뒤였다.)",
  ui_story_1016_10161402_73_dialog_content = "(지금 저 사람이 마음만 먹는다면, 언제든지 우릴 해칠 수 있을지도 모른다...)",
  ui_story_1016_10161402_74_dialog_content = "바이스! 위험해! 네 쪽으로 간다!",
  ui_story_1016_10161402_75_dialog_content = "어?!",
  ui_story_1016_10161402_76_dialog_content = "머나먼 시간과 거리를 뛰어넘어...",
  ui_story_1016_10161402_77_dialog_content = "다시 만났구나.",
  ui_story_1016_10161402_78_dialog_content = "당신... 누구야?",
  ui_story_1016_10161402_79_dialog_content = "(겉보기엔 <color=#FFB400>팬텀</color> 같은데...)",
  ui_story_1016_10161402_80_dialog_content = "(왜... 난 저 사람의 이름조차 모르는데... 어째서...)",
  ui_story_1016_10161402_81_dialog_content = "(<color=#FFB400>익숙한 느낌</color>이 드는 거지?!)",
  ui_story_1016_10161402_82_dialog_content = "잠깐만! 가지 마!",
  ui_story_1016_10161402_83_dialog_content = "곧 알게 될 거야.",
  ui_story_1016_10161402_84_dialog_content = "다가올 미래에.",
  ui_story_1016_10161402_85_dialog_content = "막으세요!",
  ui_story_1016_10161402_86_dialog_content = "그자가 손에 들고 있는 건 <color=#FFB400>가디언 1호의 코어</color>예요!",
  ui_story_1016_10161402_87_dialog_content = "빛이여!",
  ui_story_1016_10161402_88_dialog_content = "소용없어.",
  ui_story_1016_10161402_89_dialog_content = "전혀 효과가 없다니...!",
  ui_story_1016_10161402_90_dialog_content = "어서 쫓아가요! 절대로 코어를 가져가게 둬선 안 돼요!",
  ui_story_1016_10161402_91_dialog_content = "<color=#e8d9bb>같은 시간, 자난성</color>",
  ui_story_1016_10161402_92_dialog_content = "서둘러 수색하세요. 그리 멀리는 못 갔을 겁니다.\n어느 한 곳도 빠트려선 안 됩니다.",
  ui_story_1016_10161402_93_dialog_content = "예!",
  ui_story_1016_10161402_94_dialog_content = "......",
  ui_story_1016_10161402_95_dialog_content = "집요하네.",
  ui_story_1016_10161402_96_dialog_content = "이대로면 여기도 곧 들키겠어.",
  ui_story_1016_10161402_97_dialog_content = "이제 가야 해.",
  ui_story_1016_10161402_98_dialog_content = "이 상황... 마치 80호 지하성으로 돌아간 것 같아.",
  ui_story_1016_10161402_99_dialog_content = "쓸데없는 소리 하지 마.",
  ui_story_1016_10161402_100_dialog_content = "쓸데없나? 그럴지도 모르지...",
  ui_story_1016_10161402_101_dialog_content = "그때도... 우린... 지금처럼 지하성에 갇혀 있었지...\n주변은 온통 적이었고 말이야...",
  ui_story_1016_10161402_102_dialog_content = "하지만 그때... 우리가 맞섰던 건... 암귀야.\n그런데 지금은 동포와 맞서고 있지...",
  ui_story_1016_10161402_103_dialog_content = "뭐가 다른데?",
  ui_story_1016_10161402_104_dialog_content = "내 앞을 가로막는 건 모두 적이야.",
  ui_story_1016_10161402_105_dialog_content = "오로리안이든 암귀든 적이라면 그 본질은 다를 게 없어.",
  ui_story_1016_10161402_106_dialog_content = "아니... 달라...",
  ui_story_1016_10161402_107_dialog_content = "암귀는 태생부터 우리의 적이야. 하지만 동포들은...\n그저 우리가 뭘 겪었는지... 모르고 있을 뿐이야.",
  ui_story_1016_10161402_108_dialog_content = "저들은 오해를 한 거야.",
  ui_story_1016_10161402_109_dialog_content = "오해가 아냐.",
  ui_story_1016_10161402_110_dialog_content = "어리석은 자들의 맹종이지.",
  ui_story_1016_10161402_111_dialog_content = "......",
  ui_story_1016_10161402_112_dialog_content = "드니에르... 대체 무슨 일을 겪었길래... 그렇게 변한 거야...?",
  ui_story_1016_10161402_113_dialog_content = "네 사고가 뚜렷해진 건 언제부터야?",
  ui_story_1016_10161402_114_dialog_content = "최근 며칠간... 조금씩 변했어...",
  ui_story_1016_10161402_115_dialog_content = "처음엔 머릿속이... 안개로... 가득한 것 같았지...",
  ui_story_1016_10161402_116_dialog_content = "하지만... 지금은 좀 나아졌어...",
  ui_story_1016_10161402_117_dialog_content = "그래?",
  ui_story_1016_10161402_118_dialog_content = "실험 성과가 예상을 뛰어넘은 모양이네.",
  ui_story_1016_10161402_119_dialog_content = "넌 아직... 내 질문에 답을 주지 않았어...",
  ui_story_1016_10161402_120_dialog_content = "말해봐... 왜 떠나야 하는지....",
  ui_story_1016_10161402_121_dialog_content = "네가 일루미나로 돌아갈 수 있게... 내가, 도와줄게...",
  ui_story_1016_10161402_122_dialog_content = "유치하긴.",
  ui_story_1016_10161402_123_dialog_content = "대체 뭘 가지고 네가 살아서 돌아갈 수 있을 거라 생각한 거야?",
  ui_story_1016_10161402_124_dialog_content = "일루미나는... 내 집이니까.",
  ui_story_1016_10161402_125_dialog_content = "우리 동료, 라인하르트가... 아직 우릴 기다리고 있으니까.",
  ui_story_1016_10161402_126_dialog_content = "동료는 진작부터 아니었어.\n그 여자는 날 포기했고, 너도 포기했어.",
  ui_story_1016_10161402_127_dialog_content = "일루미나 연방은 이미 썩어 문드러졌어. 위에서부터 아래까지 전부.",
  ui_story_1016_10161402_128_dialog_content = "넌... 증오하고 있어...",
  ui_story_1016_10161402_129_dialog_content = "...자신을 불태우고 있다고...",
  ui_story_1016_10161402_130_dialog_content = "그래? 그럼 내가 모든 진실을 말해줄게.",
  ui_story_1016_10161402_131_dialog_content = "진실을 알고도 미련하게 저들을 믿으려 한다면,\n그건 네가 구제 불능이라는 뜻이겠지.",
  ui_story_1016_10161402_132_dialog_content = "진실?",
  ui_story_1016_10161402_133_dialog_content = "나, 그리고 너와 라인하르트는 모두 일루미나를 위해 만들어진 무기야.",
  ui_story_1016_10161402_134_dialog_content = "위원회는 우리 몸에 「인공 태양 프로젝트」라는 개조 실험을 실시해서 우릴 강화시켰어.",
  ui_story_1016_10161402_135_dialog_content = "80호 지하성에서의 전투는 우리 같은 개조 실험체에 대한 테스트였어.",
  ui_story_1016_10161402_136_dialog_content = "그리고 그 임무라는 것들은 애초에 아무런 의미도 없었어.",
  ui_story_1016_10161402_137_dialog_content = "그럴 리가...",
  ui_story_1016_10161402_138_dialog_content = "그 전투에서... 그렇게 많은 사람이 죽었는데!",
  ui_story_1016_10161402_139_dialog_content = "다른 사람을 사지로 내모는 게 놈들의 목적이야.",
  ui_story_1016_10161402_140_dialog_content = "위원회는 그 싸움을 이용해서 실험체를 궁지에 빠트리고,\n그 과정에서 잠재력을 끌어내려 했어.",
  ui_story_1016_10161402_141_dialog_content = "그중 대부분은 개조에 실패한 폐기품이었어.\n어떤 건 그대로 살해됐고, 어떤 건 너처럼 그런 꼴이 됐지.",
  ui_story_1016_10161402_142_dialog_content = "왜... 그런 짓을... 한 거지?",
  ui_story_1016_10161402_143_dialog_content = "말했잖아, 테스트라고. 「인공 태양」 개조는 성공률이 매우 낮았어.",
  ui_story_1016_10161402_144_dialog_content = "실험 성공 여부를 검증하는 유일한 방법은 잔혹한 전투에서 살아남아서,\n암귀의 포위를 뚫고 돌아오는 거였어.",
  ui_story_1016_10161402_145_dialog_content = "그리고 라인하르트는 우리 중 유일한 성공 사례야.",
  ui_story_1016_10161402_146_dialog_content = "나머지 사람들은 애초부터 버려질 운명이었어.",
  ui_story_1016_10161402_147_dialog_content = "아직도 모르겠어? 일루미나에게 넌 처음부터 사람이 아니었던 거야.\n그저 도구이자 무기일 뿐이지.",
  ui_story_1016_10161402_148_dialog_content = "더는 국가의 대의나 정의 따위에 속지 마.\n살아남기 위해선 일단 스스로 생각하는 법부터 배워.",
  ui_story_1016_10161402_149_dialog_content = "이곳엔 부러진 무기가 있을 곳 따위는 없어.",
  ui_story_1016_10161402_150_dialog_content = "너도 봤잖아? 여기 놈들은 전부 너한테 칼을 겨누고 있어.",
  ui_story_1016_10161402_151_dialog_content = "......",
  ui_story_1016_10161402_152_dialog_content = "너도 아까... 말했었지. 저들은... 어리석고, 맹종하고 있다고...",
  ui_story_1016_10161402_153_dialog_content = "그러니까... 제대로 설명해서... 오해를 풀어야 해...",
  ui_story_1016_10161402_154_dialog_content = "그리고... 모두를 현혹시키는 놈을... 내쫓으면 돼.",
  ui_story_1016_10161402_155_dialog_content = "일루미나를... 원래의 바른길로 되돌리는 거야.",
  ui_story_1016_10161402_156_dialog_content = "우리가 해야 할 일은... 문제를 해결하는 거지...\n무작정... 남을 증오하는 게 아니야.",
  ui_story_1016_10161402_157_dialog_content = "아직도 그놈들의 헛소리를 믿는 거야?",
  ui_story_1016_10161402_158_dialog_content = "아니... 진작부터 안 믿었다.",
  ui_story_1016_10161402_159_dialog_content = "이건... 내가 스스로 내린 결론이야. 네가 말한 것처럼 말이야.",
  ui_story_1016_10161402_160_dialog_content = "네가 여길 떠난다면... 난 막지 않겠어.",
  ui_story_1016_10161402_161_dialog_content = "하지만 난 남을 거다... 모든 진상을 밝히고...\n더는 놈들이 다른 사람들을 죽게 만들지 못하게 하겠어.",
  ui_story_1016_10161402_162_dialog_content = "허락 못 해.",
  ui_story_1016_10161402_163_dialog_content = "넌 내 실험체야. 연구 가치가 없어질 때까지는 날 따라와야 해.",
  ui_story_1016_10161402_164_dialog_content = "다른 선택지는 없어.",
  ui_story_1016_10161402_165_dialog_content = "이쪽입니다! 목표 대상을 발견했습니다!",
  ui_story_1016_10161402_166_dialog_content = "흥.",
  ui_story_1016_10161402_167_dialog_content = "귀찮은 벌레들.",
  ui_story_1016_10161402_168_dialog_content = "!!!",
  ui_story_1016_10161402_169_dialog_content = "물러서지 마세요. 잔재주로는 당신들을 해치지 못합니다!",
  ui_story_1016_10161402_170_dialog_content = "아직도 힘이 남은 건가...",
  ui_story_1016_10161402_171_dialog_content = "일루미나 연방의 최우선 지명수배범에 맞서기 위해 우린 만반의 준비를 했습니다.",
  ui_story_1016_10161402_172_dialog_content = "저리 비켜!",
  ui_story_1016_10161402_173_dialog_content = "이번엔 절대 놓쳐선 안 됩니다!",
  ui_story_1016_10161402_174_dialog_content = "A팀, 방어 진형으로 서서히 전진!",
  ui_story_1016_10161402_175_dialog_content = "B팀, 후방으로 우회해 퇴로를 막도록!",
  ui_story_1016_10161402_176_dialog_content = "예!",
  ui_story_1016_10161402_177_dialog_content = "성가셔.",
  ui_story_1016_10161402_178_dialog_content = "뭘 꾸물대고 있어? 가자, 실험체.",
  ui_story_1016_10161402_179_dialog_content = "아니...",
  ui_story_1016_10161402_180_dialog_content = "앞은 내가... 막을 테니까, 나머지 절반은... 네가 제압하고... 도망쳐.",
  ui_story_1016_10161402_181_dialog_content = "뭘 어쩌려는 거야?!",
  ui_story_1016_10161402_182_dialog_content = "<size=45>어서 가!</size>",
  ui_story_1016_10161402_183_dialog_content = "빨리 잡으세요!",
  ui_story_1016_10161402_184_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_1016_10161402_185_dialog_content = "콜록콜록──!",
  ui_story_1016_10161402_186_dialog_content = "천장을 허물고 길을 뚫다니...!",
  ui_story_1016_10161402_187_dialog_content = "드니에르, 도망쳐.",
  ui_story_1016_10161402_188_dialog_content = "이게 내가 줄 수 있는... 마지막 도움이야.",
  ui_story_1016_10161402_189_dialog_content = "멍청하긴!",
  ui_story_1016_10161402_190_dialog_content = "정말 멍청하기 짝이 없어!",
  ui_story_1016_10161402_191_dialog_content = "빨리 가...",
  ui_story_1016_10161402_192_dialog_content = "놓치고 만 건가...",
  ui_story_1016_10161402_193_dialog_content = "뭐, 좋습니다. 어차피...",
  ui_story_1016_10161402_194_dialog_content = "우리의 최우선 목표는 당신이니까요.",
  ui_story_1016_10161402_195_dialog_content = "잡으세요.",
  ui_story_1016_10161402_196_dialog_content = "예!",
  ui_story_1016_10161402_197_dialog_content = "다가오지 마라...",
  ui_story_1016_10161402_198_dialog_content = "일루미나의 동포를... 해치고 싶진 않단 말이다...",
  ui_story_1016_10161402_199_dialog_content = "당장 무기를 버려!",
  ui_story_1016_10161402_200_dialog_content = "<size=45>오지 마라!</size>",
  ui_story_1016_10161402_201_dialog_content = "크윽!",
  ui_story_1016_10161402_202_dialog_content = "쓸모없는 저항입니다.",
  ui_story_1016_10161402_203_dialog_content = "......!",
  ui_story_1016_10161402_204_dialog_content = "꼼짝 마!",
  ui_story_1016_10161402_205_dialog_content = "드디어 최우선 목표를 사로잡았군요.",
  ui_story_1016_10161402_206_dialog_content = "두 번째 목표는 놓쳤지만 상관없습니다.",
  ui_story_1016_10161402_207_dialog_content = "이번 임무는 이걸로 종료입니다.",
  ui_story_1016_10161402_208_dialog_content = "나머지는 율리시스 님의 지시를 기다리면 됩니다.",
  ui_story_1016_10161402_209_dialog_content = "<color=#e8d9bb>경기장</color>",
  ui_story_1016_10161402_210_dialog_content = "악셀리아 중위, 위원회에 협조해 용의자 라인하르트를 체포하세요.",
  ui_story_1016_10161402_211_dialog_content = "......",
  ui_story_1016_10161402_212_dialog_content = "네...",
  ui_story_1016_10161402_213_dialog_content = "멈춰! 네 몸은 이미...",
  ui_story_1016_10161402_214_dialog_content = "......!",
  ui_story_1016_10161402_215_dialog_content = "악셀리아!",
  ui_story_1016_10161402_216_dialog_content = "음... 힘을 너무 많이 쓴 건가?",
  ui_story_1016_10161402_217_dialog_content = "조금은 더 버틸 수 있을 줄 알았는데 말이야.",
  ui_story_1016_10161402_218_dialog_content = "상관없다. 병사들, 가서 체포해라.",
  ui_story_1016_10161402_219_dialog_content = "예!",
  ui_story_1016_10161402_220_dialog_content = "전부 꼼짝 마!",
  ui_story_1016_10161402_221_dialog_content = "율리시스, 확실하게 알아 둬. 위원회의 이번 행동은 선을 넘었어.",
  ui_story_1016_10161402_222_dialog_content = "너희 망할 늙다리들은 매번 우릴 억누르려고 헛수작을 부려 왔지.",
  ui_story_1016_10161402_223_dialog_content = "지금까진 라인하르트가 막아서 네놈들한테 따지러 가질 못했는데...",
  ui_story_1016_10161402_224_dialog_content = "이번엔 우리 머리 꼭대기에 앉으려고 들어?!",
  ui_story_1016_10161402_225_dialog_content = "대원수님, 설명해 주세요. 대체 어떻게 된 일입니까?",
  ui_story_1016_10161402_226_dialog_content = "만약 이게 저들의 음모라면 우린 반드시 당신을 위해 싸울 겁니다.",
  ui_story_1016_10161402_227_dialog_content = "군단장 여러분, 위원회는 항상 규칙에 따라 일을 처리하고 있습니다.",
  ui_story_1016_10161402_228_dialog_content = "오히려 군단장 여러분의 지금 행동이야말로 법보다 사적인 감정을\n앞세우고 있는 규정 위반 행위입니다.",
  ui_story_1016_10161402_229_dialog_content = "위원회의 결정에 이의가 있다면 폭력을 남용할 게 아니라 서면으로 이의를 제기해 주세요.",
  ui_story_1016_10161402_230_dialog_content = "이 자식이...!",
  ui_story_1016_10161402_231_dialog_content = "모두 태도를 바로잡아 주시지요.\n그렇지 않으면 위원회는 여러분을 라인하르트의 공범으로 간주할 수밖에 없습니다.",
  ui_story_1016_10161402_232_dialog_content = "됐다.",
  ui_story_1016_10161402_233_dialog_content = "이 일은 저들과는 무관하다.",
  ui_story_1016_10161402_234_dialog_content = "라인하르트?!",
  ui_story_1016_10161402_235_dialog_content = "레이스, 내가 한번 해 볼게.",
  ui_story_1016_10161402_236_dialog_content = "과연 이 일루미나에서 나 혼자서 합법적인 방식으로\n내 결백을 증명할 수 있는지 한번 확인해 보자.",
  ui_story_1016_10161402_237_dialog_content = "......",
  ui_story_1016_10161402_238_dialog_content = "알겠어.",
  ui_story_1016_10161402_239_dialog_content = "그래, 고맙다...",
  ui_story_1016_10161402_240_dialog_content = "그럼 나머지는 부탁할게.",
  ui_story_1016_10161402_241_dialog_content = "그리고 저 아이도.\n상태가 좋지 않아. 서둘러 치료를 받게 해 줘.",
  ui_story_1016_10161402_242_dialog_content = "......",
  ui_story_1016_10161402_243_dialog_content = "대원수...?!",
  ui_story_1016_10161402_244_dialog_content = "대원수님...",
  ui_story_1016_10161402_245_dialog_content = "......",
  ui_story_1016_10161402_246_dialog_content = "율리시스, 더는 애쓸 거 없다.",
  ui_story_1016_10161402_247_dialog_content = "조사에 협력하지.",
  ui_story_1016_10161402_248_dialog_content = "협조해 주어 고맙군요, 라인하르트.",
  ui_story_1016_10161402_249_dialog_content = "데려가도록.",
  ui_story_1016_10161402_250_dialog_content = "예!",
  ui_story_1016_10161501_1_dialog_content = "이상입니다.",
  ui_story_1016_10161501_2_dialog_content = "정체불명의 팬텀이 <color=#FFB400>가디언 1호</color>의 코어를 탈취했고,\n지금까지도 행방을 찾지 못했다니...",
  ui_story_1016_10161501_3_dialog_content = "잉겔 중령, 이건 중대한 직무상 과실입니다.",
  ui_story_1016_10161501_4_dialog_content = "죄송합니다. 어떤 처벌도 감수하겠습니다.",
  ui_story_1016_10161501_5_dialog_content = "현장의 사람들 외에 이 일을 알고 있는 자가 있습니까?",
  ui_story_1016_10161501_6_dialog_content = "아직까지는 없습니다.",
  ui_story_1016_10161501_7_dialog_content = "목격자는 제가 모두 이곳에 모아 두었고, 정보를 누설할 기회는 아직 없었습니다.",
  ui_story_1016_10161501_8_dialog_content = "음... 알겠습니다.",
  ui_story_1016_10161501_9_dialog_content = "잉겔 중령, 정체불명의 팬텀 수색 임무는 제가 인계받겠습니다.",
  ui_story_1016_10161501_10_dialog_content = "당신은 휴식을 취한 후 위원회의 다음 지시를 기다리세요.",
  ui_story_1016_10161501_11_dialog_content = "여러분도 이 건은 외부에 누설하지 말아 주시기 바랍니다.",
  ui_story_1016_10161501_12_dialog_content = "예.",
  ui_story_1016_10161501_13_dialog_content = "알겠습니다.",
  ui_story_1016_10161501_14_dialog_content = "그래.",
  ui_story_1016_10161501_15_dialog_content = "그러지. 무턱대고 이야기를 꺼내 봤자 나한테도 좋을 게 없으니까.",
  ui_story_1016_10161501_16_dialog_content = "비밀은 지킬게.",
  ui_story_1016_10161501_17_dialog_content = "협조해 주셔서 감사합니다.",
  ui_story_1016_10161501_18_dialog_content = "그럼 해산하겠습니다.",
  ui_story_1016_10161501_19_dialog_content = "잠시만요. 악셀리아는 어떤가요?",
  ui_story_1016_10161501_20_dialog_content = "악셀리아 중위는 경기에서 힘을 과도하게 사용한 탓에 현재 혼수상태입니다.",
  ui_story_1016_10161501_21_dialog_content = "지금은 레이스 군단장님이 이송해 메디컬 센터에서 치료를 받고 있습니다.",
  ui_story_1016_10161501_22_dialog_content = "그런가요, 그럼...",
  ui_story_1016_10161501_23_dialog_content = "악셀리아에게 가 봐야겠어요.",
  ui_story_1016_10161501_24_dialog_content = "그럼 저도 대원수님께 돌아가도록 하겠습니다.",
  ui_story_1016_10161501_25_dialog_content = "PlayerName, 바이스 중위, 카렌 양, 그리고 레오, 여기서 작별합시다.",
  ui_story_1016_10161501_26_dialog_content = "돌아가지 않아도 됩니다.",
  ui_story_1016_10161501_27_dialog_content = "예?",
  ui_story_1016_10161501_28_dialog_content = "라인하르트는 해임되어 이제 더는 일루미나 연방의 대원수가 아닙니다.",
  ui_story_1016_10161501_29_dialog_content = "<size=45>뭐라고요?!</size>",
  ui_story_1016_10161501_30_option_content = "농담이지?!",
  ui_story_1016_10161501_31_dialog_content = "무슨 일이 있었던 거지? 그런 중대한 일을 왜 우리는 모르고 있었지?",
  ui_story_1016_10161501_32_option_content = "대체 어떻게 된 거야?!",
  ui_story_1016_10161501_33_dialog_content = "왜 라인하르트 씨가 갑자기 해임된 건데?",
  ui_story_1016_10161501_34_dialog_content = "여러분, 일단 진정하세요.",
  ui_story_1016_10161501_35_dialog_content = "갑작스러운 사태였고, 그때 여러분은 자난성 내 암귀를 추적 중이었으니\n모르시는 게 당연합니다.",
  ui_story_1016_10161501_36_dialog_content = "자난성 순찰대가 지명수배범 노라와 공범 헬리오스의 흔적을 발견했습니다.",
  ui_story_1016_10161501_37_dialog_content = "두 사람은 최근 며칠간 자난성에 계속 잠복하면서\n연합 훈련을 방해할 기회를 엿보고 있었습니다.",
  ui_story_1016_10161501_38_dialog_content = "그리고 그 두 사람의 은신처가 바로 라인하르트의 집이었던 것입니다.",
  ui_story_1016_10161501_39_dialog_content = "두 사람은 현장에서 체포되었으며, 위원회는 적과 내통한 혐의로\n라인하르트에게 해임 처분을 내리기로 결정했습니다.",
  ui_story_1016_10161501_40_dialog_content = "말도 안 되잖아?",
  ui_story_1016_10161501_41_dialog_content = "대원수님은 절대 내통 같은 걸 하실 분이 아니에요!",
  ui_story_1016_10161501_42_dialog_content = "다시 말씀드리죠. 라인하르트는 더는 일루미나 연방의 대원수가 아닙니다.",
  ui_story_1016_10161501_43_dialog_content = "이것은 조사에 필요한 절차입니다.\n결백이 증명된다면 위원회에서 복직시킬 것입니다.",
  ui_story_1016_10161501_44_dialog_content = "당신들이 지금 해야 할 일은 이해와 협조입니다.",
  ui_story_1016_10161501_45_dialog_content = "하지만...",
  ui_story_1016_10161501_46_dialog_content = "역시 못 믿겠어...",
  ui_story_1016_10161501_47_dialog_content = "당신이 믿든 안 믿든 조사 결과를 기다리는 수밖에 없습니다.",
  ui_story_1016_10161501_48_dialog_content = "게다가 평소 라인하르트와 가까운 사이였던 점을 감안해서...",
  ui_story_1016_10161501_49_dialog_content = "PlayerName 씨, 바이스 중위, 아나톨리 소령은 조사를 받야아 합니다.",
  ui_story_1016_10161501_50_dialog_content = "그게 무슨 소리야!",
  ui_story_1016_10161501_51_dialog_content = "조사 말입니까...",
  ui_story_1016_10161501_52_dialog_content = "그런...",
  ui_story_1016_10161501_53_option_content = "좋아.",
  ui_story_1016_10161501_54_dialog_content = "하지만 당신들이 묻는다 해도 난 할 말 없어.",
  ui_story_1016_10161501_55_dialog_content = "난 라인하르트 씨를 믿어.\n그리고 지금까지 라인하르트 씨가 해서는 안 될 일을 한 걸 본 적도 없어.",
  ui_story_1016_10161501_56_dialog_content = "잘 말했어.",
  ui_story_1016_10161501_57_option_content = "만약 내가 거절하면?",
  ui_story_1016_10161501_58_dialog_content = "방금 그 말은 의문문이 아니라 서술문입니다.",
  ui_story_1016_10161501_59_dialog_content = "협력하는 것 외에 당신에겐 선택의 권리가 없습니다.",
  ui_story_1016_10161501_60_dialog_content = "그게 일루미나의 중요한 손님을 대하는 태도야?",
  ui_story_1016_10161501_61_dialog_content = "레이스 군단장님?!",
  ui_story_1016_10161501_62_dialog_content = "어이, 바이스, PlayerName, 그리고 라인하르트의 그 부관.",
  ui_story_1016_10161501_63_dialog_content = "레이스 군단장님, 위원회의 공무를 방해하지 마십시오.",
  ui_story_1016_10161501_64_dialog_content = "방해 안 했어. 그저 주의를 주려는 것뿐이야.\n태도가 너무 강경하면 일을 힘들게 만들 뿐이라고.",
  ui_story_1016_10161501_65_dialog_content = "......",
  ui_story_1016_10161501_66_dialog_content = "죄송합니다. 방금 제 발언이 적절하지 않았습니다.",
  ui_story_1016_10161501_67_dialog_content = "여러분, 부디 조사에 협조해 주시기 바랍니다.",
  ui_story_1016_10161501_68_dialog_content = "앞으로 한동안 세 사람은 일루미나에 머무르게 될 것입니다.\n조사 결과가 나온 후에는 자유롭게 행동해도 좋습니다.",
  ui_story_1016_10161501_69_dialog_content = "......",
  ui_story_1016_10161501_70_dialog_content = "뭐 다른 선택지도 없겠지.",
  ui_story_1016_10161501_71_dialog_content = "이해를 부탁드립니다.",
  ui_story_1016_10161501_72_dialog_content = "됐어, 일단 그렇게 하자고.",
  ui_story_1016_10161501_73_dialog_content = "PlayerName, 너희도 일단 기분 풀어.\n이 일을 불필요한 갈등으로 키울 필요는 없어.",
  ui_story_1016_10161501_74_dialog_content = "알겠어요...",
  ui_story_1016_10161501_75_dialog_content = "볼일이 끝났으면 해산하자고.",
  ui_story_1016_10161501_76_dialog_content = "그럼 전 다른 업무가 있어서 먼저 실례하겠습니다.",
  ui_story_1016_10161501_77_dialog_content = "저 자식, 도망 하나는 빠르네...",
  ui_story_1016_10161501_78_dialog_content = "군단장님, 대체 그동안 무슨 일이 있었던 거죠? 어째서 대원수님이...",
  ui_story_1016_10161501_79_dialog_content = "잘 모르겠어.",
  ui_story_1016_10161501_80_dialog_content = "나도 지금 상황이 어떻게 된 건지 확실히는 몰라.",
  ui_story_1016_10161501_81_dialog_content = "다만 지금은 절대로 위원회 놈들과 정면으로 부딪칠 타이밍이 아냐.",
  ui_story_1016_10161501_82_dialog_content = "오히려 저쪽은 지금 우리가 맞받아치길 바라고 있어.\n양측의 충돌이 클수록 라인하르트는 운신의 폭이 좁아질 테니까.",
  ui_story_1016_10161501_83_dialog_content = "괜찮겠죠...?",
  ui_story_1016_10161501_84_dialog_content = "......",
  ui_story_1016_10161501_85_dialog_content = "믿어 보자고.",
  ui_story_1016_10161501_86_dialog_content = "카렌 전하──!",
  ui_story_1016_10161501_87_dialog_content = "드디어 찾았네요!",
  ui_story_1016_10161501_88_dialog_content = "무슨 일이야?",
  ui_story_1016_10161501_89_dialog_content = "방금 성주님의 긴급 전보가 들어왔어요.\n전하를 포함해서 훈련에 참가한 백야성 인원은 모두 즉시 돌아오라는 명령이에요!",
  ui_story_1016_10161501_90_dialog_content = "성주님의 명령인가...",
  ui_story_1016_10161501_91_dialog_content = "알겠어. 짐 정리하고 바로 돌아가자.",
  ui_story_1016_10161501_92_dialog_content = "네, 그럼 기다리고 있을게요!",
  ui_story_1016_10161501_93_dialog_content = "아무래도 곧 큰일이 벌어질... 아니지, 이미 벌어진 모양이네.",
  ui_story_1016_10161501_94_dialog_content = "나도 요제프와 자오를 찾으러 가야겠어.\n빨리 더스크 타운으로 돌아가는 게 좋을 것 같아.",
  ui_story_1016_10161501_95_dialog_content = "그럼 먼저 가볼게. 행운을 빌어.",
  ui_story_1016_10161501_96_dialog_content = "응...",
  ui_story_1016_10161501_97_dialog_content = "<color=#e8d9bb>같은 시간, 연구소</color>",
  ui_story_1016_10161501_98_dialog_content = "음? 벌써 일어났나?",
  ui_story_1016_10161501_99_dialog_content = "대단한 생명력이로군. 역시 노라의 연구 성과라 이건가.",
  ui_story_1016_10161501_100_dialog_content = "당신... 누군지 기억해...",
  ui_story_1016_10161501_101_dialog_content = "율리시스... 한때 우리의 상관이었지...",
  ui_story_1016_10161501_102_dialog_content = "조금도 변하지 않았군.",
  ui_story_1016_10161501_103_dialog_content = "호오? 기억까지 서서히 회복되고 있단 말인가?",
  ui_story_1016_10161501_104_dialog_content = "정말 놀랍군.",
  ui_story_1016_10161501_105_dialog_content = "하지만 아쉽게도 그리 똑똑하진 않은 모양이야.",
  ui_story_1016_10161501_106_dialog_content = "......",
  ui_story_1016_10161501_107_dialog_content = "자네에게 궁금한 점이 하나 있네.\n자넨 우리와 싸우고 싶지 않다면서, 왜 노라가 시키는 대로 한 건가?",
  ui_story_1016_10161501_108_dialog_content = "심지어 자신이 잡히면서까지 노라의 도주를 도왔지. 이유가 뭔가?",
  ui_story_1016_10161501_109_dialog_content = "시키는 대로 한 게 아니다.",
  ui_story_1016_10161501_110_dialog_content = "나는... 일루미나 연방의 군인이다...",
  ui_story_1016_10161501_111_dialog_content = "일루미나인과 전우를 지키는 것이... 내 사명이다.",
  ui_story_1016_10161501_112_dialog_content = "!",
  ui_story_1016_10161501_113_dialog_content = "허허허, 정말 생각지도 못한 답이로군.",
  ui_story_1016_10161501_114_dialog_content = "노라가 뭐라고 말했지? 설마 자기가 그렇게 된 게 위원회 때문이라고 하던가?",
  ui_story_1016_10161501_115_dialog_content = "아니, 천만에. 일루미나를 떠나 모두를 배신한 건 노라 자신의 선택이다.",
  ui_story_1016_10161501_116_dialog_content = "......",
  ui_story_1016_10161501_117_dialog_content = "하지만 자네는 참으로 불쌍하군.\n평생을 거듭된 거짓말 속에서 살면서 그걸 믿어 의심치 않고 있다니.",
  ui_story_1016_10161501_118_dialog_content = "게다가 반쪽짜리 암귀는 믿으면서 자신과 같은 오로리안은 믿으려 하지 않는군.",
  ui_story_1016_10161501_119_dialog_content = "뭐, 이상할 것도 없지. 자넨 애초부터 불량품이었으니 말이야.",
  ui_story_1016_10161501_120_dialog_content = "하지만 그런 자네도 이제는 가치가 조금 생겼어.",
  ui_story_1016_10161501_121_dialog_content = "<color=#e8d9bb>똑똑.</color>",
  ui_story_1016_10161501_122_dialog_content = "들어와라.",
  ui_story_1016_10161501_123_dialog_content = "율리시스 님.",
  ui_story_1016_10161501_124_dialog_content = "내가 분명히 말하지 않았나?\n지금부터 중요한 연구를 진행해야 하니 누구도 방해하지 말라 했을 텐데.",
  ui_story_1016_10161501_125_dialog_content = "정말 죄송합니다! 하지만 「그분」께서 지금 찾으십니다.",
  ui_story_1016_10161501_126_dialog_content = "「<color=#FFB400>철가면</color>」인가... 허허, 확실히 찾아올 때가 되긴 했지.",
  ui_story_1016_10161501_127_dialog_content = "<color=#e8d9bb>잠시 후, 자난성 어딘가</color>",
  ui_story_1016_10161501_128_dialog_content = "책임 추궁이라도 하러 오신 겁니까?",
  ui_story_1016_10161501_129_dialog_content = "지금 죄를 묻는다면 조금 성급하겠지.",
  ui_story_1016_10161501_130_dialog_content = "오늘은 그저 내 추측이 맞는지 확인해 줬으면 해서 온 거야.",
  ui_story_1016_10161501_131_dialog_content = "당신의 추측은 언제나 맞지 않았습니까?",
  ui_story_1016_10161501_132_dialog_content = "무의미한 아첨은 사양할게. 그런다고 당신에겐 아무 이득도 없으니까.",
  ui_story_1016_10161501_133_dialog_content = "그렇겠지요.",
  ui_story_1016_10161501_134_dialog_content = "그럼 원래 계획부터 얘기해 볼까?",
  ui_story_1016_10161501_135_dialog_content = "처음 계획은 이클립스의 버린 패를 이용해 연극을 하고\n네 부하들을 동원해 라인하르트를 끌어내리는 것이었지.",
  ui_story_1016_10161501_136_dialog_content = "그런데 지금은 계획 밖의 상황이 벌어졌어.\n이클립스는 노라와 그 연구 성과만 원했던 게 아니라, 가디언 1호의 코어까지 노리고 있었어.",
  ui_story_1016_10161501_137_dialog_content = "그뿐만이 아니야. 이번 계획을 귀찮은 자들에게 발각되고 말았지.",
  ui_story_1016_10161501_138_dialog_content = "그게 누구입니까?",
  ui_story_1016_10161501_139_dialog_content = "<color=#FFB400>더스크 타운</color>.",
  ui_story_1016_10161501_140_dialog_content = "더스크 타운에서 온 그 팀은 당신 계획을 간파했어.\n그래서 마지막 단계에서 당신 부하들한테 승리를 양보한 거야.",
  ui_story_1016_10161501_141_dialog_content = "설마... 누가 정보를 흘린 겁니까?",
  ui_story_1016_10161501_142_dialog_content = "다른 가능성도 생각할 수 있겠지. 예를 들면...",
  ui_story_1016_10161501_143_dialog_content = "당신 부하들은 한 번도 전력을 다하지 않았어.",
  ui_story_1016_10161501_144_dialog_content = "그리고 비정상적으로 좋은 장비를 사용했지.",
  ui_story_1016_10161501_145_dialog_content = "게다가 시험 내용을 진작부터 대비했고 말이야.",
  ui_story_1016_10161501_146_dialog_content = "......",
  ui_story_1016_10161501_147_dialog_content = "당신 움직임은 너무 눈에 띄었어.",
  ui_story_1016_10161501_148_dialog_content = "더스크 타운은 작은 곳이지만, 일루미나와 백야성 모두 쉽게 건드리지 않는 상대야.",
  ui_story_1016_10161501_149_dialog_content = "이제 저쪽이 주도권을 쥐고 있으니, 앞으로의 계획에서 저들은 변수가 되겠지.",
  ui_story_1016_10161501_150_dialog_content = "그러니 이제 당신이 해야 할 일은 책임지고 그 변수를\n통제 가능한 범위로 만드는 거야.",
  ui_story_1016_10161501_151_dialog_content = "그리고 하나 더, 최대한 빨리 가디언 1호의 코어를 되찾아.",
  ui_story_1016_10161501_152_dialog_content = "난 허점 하나 때문에 이것저것 따져야 하는 것보다는 자유로운 게임이 더 좋거든.",
  ui_story_1016_10161501_153_dialog_content = "음... 그렇게 하죠.",
  ui_story_1016_10161501_154_dialog_content = "당신, 이번 실험에 꽤 자신이 있는 모양이네.",
  ui_story_1016_10161501_155_dialog_content = "물론입니다.",
  ui_story_1016_10161501_156_dialog_content = "노라의 기술 해석에 성공하고 나면, 다년간 추진해 온 일루미나 연방의\n기술 연구 중에서도 가장 큰 혁신이 될 것입니다.",
  ui_story_1016_10161501_157_dialog_content = "이 기술의 원리를 밝히고 나면 X호 지하성의 화음 연결 장치를 사용해\n강화 병사를 양산할 수 있습니다.",
  ui_story_1016_10161501_158_dialog_content = "「계명성 프로젝트」나 「인공 태양 프로젝트」의 결과물은\n일루미나에 아직 많이 있으니 말이지요.",
  ui_story_1016_10161501_159_dialog_content = "그때가 되면 일루미나 연방의 힘은 비약적인 질적 향상을 이룰 것입니다.",
  ui_story_1016_10161501_160_dialog_content = "그럼 서두르는 게 좋을 거야. 우리의 시간은 빛보다 훨씬 귀하니까.",
  ui_story_1016_10161501_161_dialog_content = "하지만 결국 노라의 실험 성과를 표절하기로 한 거네.",
  ui_story_1016_10161501_162_dialog_content = "연구자로서의 자존심이 정말 그걸 허락했어?",
  ui_story_1016_10161501_163_dialog_content = "그건 문제가 안 됩니다.",
  ui_story_1016_10161501_164_dialog_content = "이 세계의 문명을 지속하기 위해서라면, 우린 모든 수단을 쓸 수밖에 없습니다.",
  ui_story_1016_10161501_165_dialog_content = "<color=#e8d9bb>며칠 뒤, 일루미나 메디컬 센터</color>",
  ui_story_1016_10161501_166_dialog_content = "(그 경기로부터 벌써 며칠이나 지났는데, 악셀리아는 아직도 깨어나지 않았네요.)",
  ui_story_1016_10161501_167_dialog_content = "(이번에도 거의 완전 붕괴에 가까운 과정을 또 겪고 말았군요.)",
  ui_story_1016_10161501_168_dialog_content = "(다행히 지난번 붕괴를 복구한 경험이 있어서,\n의사와 연구원들도 빠르게 몸을 수리했지만...)",
  ui_story_1016_10161501_169_dialog_content = "(부상이 심각해 언제 눈을 뜰 수 있을지는 미지수네요.)",
  ui_story_1016_10161501_170_dialog_content = "으음...",
  ui_story_1016_10161501_171_dialog_content = "악셀리아?!",
  ui_story_1016_10161501_172_dialog_content = "악셀리아는... 뭔가 긴 꿈을 꾼 것 같습니다.",
  ui_story_1016_10161501_173_dialog_content = "드디어... 깨어났군요...",
  ui_story_1016_10161501_174_dialog_content = "잉겔, 안녕하세요.",
  ui_story_1016_10161501_175_dialog_content = "잉겔은 많이 지친 것 같습니다.",
  ui_story_1016_10161501_176_dialog_content = "그런가요? 아마 그렇겠죠...",
  ui_story_1016_10161501_177_dialog_content = "기분은 어떤가요? 어디 아픈 곳은 없나요?",
  ui_story_1016_10161501_178_dialog_content = "악셀리아는 정상입니다.",
  ui_story_1016_10161501_179_dialog_content = "다만 싸울 수 있는 상태까지 회복하려면 아직 시간이 필요합니다.",
  ui_story_1016_10161501_180_dialog_content = "싸움을 서두를 필요는 없어요. 살아남은 것만으로도 행운이었으니까요.",
  ui_story_1016_10161501_181_dialog_content = "......",
  ui_story_1016_10161501_182_dialog_content = "라인하르트 님도 악셀리아에게 비슷한 말을 했습니다.",
  ui_story_1016_10161501_183_dialog_content = "들었어요... 스스로 패배를 인정했다고 말이에요.",
  ui_story_1016_10161501_184_dialog_content = "그래서 당신이 살아남을 수 있었던 거예요.",
  ui_story_1016_10161501_185_dialog_content = "참, 이건 당신의 우승 메달이에요.",
  ui_story_1016_10161501_186_dialog_content = "그땐 상황이 엉망이 된 데다가 당신도 쓰러져서 시상식을 못 했었죠...",
  ui_story_1016_10161501_187_dialog_content = "지금 줄게요.",
  ui_story_1016_10161501_188_dialog_content = "메달, 무겁습니다.",
  ui_story_1016_10161501_189_dialog_content = "......",
  ui_story_1016_10161501_190_dialog_content = "악셀리아, 잉겔에게 물어보고 싶은 게 있습니다.",
  ui_story_1016_10161501_191_dialog_content = "뭐죠?",
  ui_story_1016_10161501_192_dialog_content = "결승전에서 라인하르트 님은 악셀리아에게 말했습니다.",
  ui_story_1016_10161501_193_dialog_content = "악셀리아가 저라는 인간으로 살아갔으면 좋겠다고 말입니다.",
  ui_story_1016_10161501_194_dialog_content = "악셀리아에게 「<color=#FFB400>인간으로 살아간다</color>」는 것이 무엇인지 알려주세요.",
  ui_story_1017_10170101_1_dialog_content = "대원수님, 들리시나요?",
  ui_story_1017_10170101_2_dialog_content = "들린다.",
  ui_story_1017_10170101_3_dialog_content = "그럼 시작하겠습니다.",
  ui_story_1017_10170101_4_dialog_content = "저는 본건의 재판장을 맡은 일루미나 연방 감찰관 네메시스입니다.",
  ui_story_1017_10170101_5_dialog_content = "지금부터 일루미나 연방 조사법에 따라, 당신이 적과 내통하고 수배범을 은닉했다는\n혐의에 대한 제3차 내부공개재판을 진행하겠습니다.",
  ui_story_1017_10170101_6_dialog_content = "연방 조사법 규정이 부여하는 권리에 따라 당신은...",
  ui_story_1017_10170101_7_dialog_content = "형식적인 절차는 생략하자고.",
  ui_story_1017_10170101_8_dialog_content = "그럼 심문을 시작하겠습니다. 율리시스 씨가 당신을 고발한 내용에 대해 추가할 진술이 있습니까?",
  ui_story_1017_10170101_9_dialog_content = "다시 한번 말하도록 하지. 연합 훈련 기간에 노라가 자난성에 은신해 있었던 것은 모르는 일이었다.",
  ui_story_1017_10170101_10_dialog_content = "나와 노라 사이에는 어떠한 형태의 내통 행위도 존재하지 않는다.",
  ui_story_1017_10170101_11_dialog_content = "지난 두 번의 심문 때와 같은 주장을 하시는군요.\n그래서는 당신에게 불리한 판결만 나올 뿐입니다.",
  ui_story_1017_10170101_12_dialog_content = "그게 바로 너희가 원하는 결과 아니었나?",
  ui_story_1017_10170101_13_dialog_content = "차라리 확실하게 말해라. 너희 목적이 뭐지?",
  ui_story_1017_10170101_14_dialog_content = "재판장님, 증언 보충을 신청합니다.",
  ui_story_1017_10170101_15_dialog_content = "발언을 허락합니다.",
  ui_story_1017_10170101_16_dialog_content = "첩보에 따르면. 연합 훈련이 시작되기 전 노라는 「X호 연구소」에서\n라인하르트와 직접 만나 거래를 했습니다.",
  ui_story_1017_10170101_17_dialog_content = "그때 라인하르트는 헬리오스만 두고 가면 노라를 놓아주겠다고 약속했습니다.",
  ui_story_1017_10170101_18_dialog_content = "잉겔 중령, 아나톨리 소령이 이 사실을 증언할 수 있습니다.",
  ui_story_1017_10170101_19_dialog_content = "재판장──!",
  ui_story_1017_10170101_20_dialog_content = "<size=30>레이스, 끼어들지 마세요.</size>",
  ui_story_1017_10170101_21_dialog_content = "잉겔 중령, 발언하세요.",
  ui_story_1017_10170101_22_dialog_content = "재판장이 묻는 말에만 대답하면 된다. 노라가 라인하르트에게 거래를 제안했나?",
  ui_story_1017_10170101_23_dialog_content = "...예.",
  ui_story_1017_10170101_24_dialog_content = "너 이 새끼...!",
  ui_story_1017_10170101_25_dialog_content = "<size=30>입 다물어. 나서봤자 대원수님께 불리해질 뿐이니까.</size>",
  ui_story_1017_10170101_26_dialog_content = "거래가 성사된 후, 라인하르트는 옛 동창에 대한 사사로운 정에 얽매여 소극적으로 대응했습니다.",
  ui_story_1017_10170101_27_dialog_content = "라인하르트는 지원군을 이끌고 수배범의 도주를 원조했고,\n이로 인해 「가디언 1호」의 코어 도난이라는 결과를 초래했습니다.",
  ui_story_1017_10170101_28_dialog_content = "라인하르트, 이를 인정하십니까?",
  ui_story_1017_10170101_29_dialog_content = "「가디언 1호」의 코어를 빼앗긴 것은 나에게 책임이 있다.\n그 외의 고발에 대해서는 증거를 제시해라.",
  ui_story_1017_10170101_30_dialog_content = "아나톨리.",
  ui_story_1017_10170101_31_dialog_content = "네?",
  ui_story_1017_10170101_32_dialog_content = "라인하르트가 노라와 헬리오스에게 「지원군을 데리고 너흴 구하러 왔다」고 말한 게 맞습니까?",
  ui_story_1017_10170101_33_dialog_content = "......",
  ui_story_1017_10170101_34_dialog_content = "맞습니까, 아닙니까?",
  ui_story_1017_10170101_35_dialog_content = "맞습니다...",
  ui_story_1017_10170101_36_dialog_content = "라인하르트, 지금 증언에 대해 변론해 주세요.",
  ui_story_1017_10170101_37_dialog_content = "......",
  ui_story_1017_10170101_38_dialog_content = "재판장님, 제 진술은 여기까지입니다.",
  ui_story_1017_10170101_39_dialog_content = "(그때의 상황은 그런 게 아니었어...)",
  ui_story_1017_10170101_40_dialog_content = "(잠깐만! 나와 잉겔 중령님이 증인이라면...)",
  ui_story_1017_10170101_41_dialog_content = "라인하르트, 이상의 고발에 대해 죄를 인정하십니까? 보충할 변론이 있습니까?",
  ui_story_1017_10170101_42_dialog_content = "훗, 일루미나가 지금의 꼴이 되어버린 건 내 책임이지. 인정한다!",
  ui_story_1017_10170101_43_dialog_content = "굳이 내가 해야 할 말이 있다면...",
  ui_story_1017_10170101_44_dialog_content = "하하하하하!",
  ui_story_1017_10170101_45_dialog_content = "이상이다. 재판장, 판결을 내리도록.",
  ui_story_1017_10170101_46_dialog_content = "......",
  ui_story_1017_10170101_47_dialog_content = "라인하르트의 사건에 대해 세 차례 심문을 실시한 결과, 감찰부에서는 다음과 같이 판결합니다.",
  ui_story_1017_10170101_48_dialog_content = "일루미나 연방 전임 대원수 라인하르트는──",
  ui_story_1017_10170101_49_dialog_content = "자신의 직위를 이용, 연합 훈련 기간에 일루미나로 잠입한 수배자 노라와\n비밀 거래를 획책하였습니다.",
  ui_story_1017_10170101_50_dialog_content = "그 결과 「가디언 1호」의 코어를 빼앗기고, 78명의 일루미나 병사와 그 가족이 피해를 입는 등\n일루미나 연방의 안전에 중대한 영향을 미쳤습니다.",
  ui_story_1017_10170101_51_dialog_content = "이에 대해 라인하르트 또한 직무상 과실을 인정했습니다.",
  ui_story_1017_10170101_52_dialog_content = "그러나 적 은닉죄 고발에 대해서는 증거가 불충분하므로, 당사자 심문이 가능해지거나,\n쌍방이 충분한 증거를 제시할 경우 다시 심문하겠습니다.",
  ui_story_1017_10170101_53_dialog_content = "오늘 판결에 대해서는 일루미나 연방 조사법에 의거하여, 다음의 처벌을 내리는 바입니다.",
  ui_story_1017_10170101_54_dialog_content = "「라인하르트를 대원수 직위에서 해임한다.」",
  ui_story_1017_10170101_55_dialog_content = "「라인하르트에게 주어진 일루미나 군인으로서의 권한을 박탈한다.」",
  ui_story_1017_10170101_56_dialog_content = "「라인하르트를 현 시간부로 일루미나 감옥에 수감한다.」",
  ui_story_1017_10170101_57_dialog_content = "이상입니다.",
  ui_story_1017_10170101_58_dialog_content = "나왔어, 나왔어!",
  ui_story_1017_10170101_59_dialog_content = "으앗, 죄, 죄송합니다!",
  ui_story_1017_10170101_60_dialog_content = "음...",
  ui_story_1017_10170101_61_dialog_content = "<size=30>누구야?</size>",
  ui_story_1017_10170101_62_dialog_content = "벨리사리아 님이야. 위원회에서 꽤 큰 발언력이 있는 분이라던 것 같아.",
  ui_story_1017_10170101_63_dialog_content = "방금 긴장해서 경례도 잊어버렸지 뭐야...",
  ui_story_1017_10170101_64_option_content = "나까지 긴장했잖아.",
  ui_story_1017_10170101_65_option_content = "끝장이네.",
  ui_story_1017_10170101_66_dialog_content = "너 진짜... 달래주진 못할망정.",
  ui_story_1017_10170101_67_dialog_content = "뭐... 지금 가서 인사해도 늦지 않았을까...",
  ui_story_1017_10170101_68_dialog_content = "......",
  ui_story_1017_10170101_69_dialog_content = "벨리사리아 님까지 오셨다니, 대원수님 일... 어떻게 되려나...",
  ui_story_1017_10170101_70_dialog_content = "방금 전엔 미처 신경 못 썼어.",
  ui_story_1017_10170101_71_dialog_content = "네가 그 아이테르지?",
  ui_story_1017_10170101_72_dialog_content = "네... 맞아요.",
  ui_story_1017_10170101_73_dialog_content = "벨리사리아 님!",
  ui_story_1017_10170101_74_dialog_content = "너, 아이테르랑 백야성 친구하고 같이 연합 훈련에 참가했다면서?",
  ui_story_1017_10170101_75_dialog_content = "네, 그렇습니다.",
  ui_story_1017_10170101_76_dialog_content = "후훗, 대단하네...",
  ui_story_1017_10170101_77_dialog_content = "너흴 보고 있으면 뭔가 말하기 어려운 기분이 든단 말이야.",
  ui_story_1017_10170101_78_dialog_content = "이제 곧 너흰 내 추측이 맞는지 검증하러 가게 될 거야.",
  ui_story_1017_10170101_79_dialog_content = "그럼 먼저 실례할게, 아이테르. 다음 만남은 아마 공식적인 자리가 되겠지.",
  ui_story_1017_10170101_80_dialog_content = "......",
  ui_story_1017_10170101_81_dialog_content = "까, 깜짝 놀랐잖아...",
  ui_story_1017_10170101_82_dialog_content = "이번엔 그래도 경례했잖아?",
  ui_story_1017_10170101_83_dialog_content = "벨리사리아 님이 우릴 보는 눈빛... 왠지 되게 이상했어.",
  ui_story_1017_10170101_84_dialog_content = "그냥 내가 괜히 예민한 건가...",
  ui_story_1017_10170101_85_dialog_content = "앗! 군단장님들도 나오셨어── 히이로 님!",
  ui_story_1017_10170101_86_dialog_content = "......",
  ui_story_1017_10170101_87_dialog_content = "여기서 이야기하긴 좀 곤란한 모양인데...",
  ui_story_1017_10170101_88_dialog_content = "다들 표정이 심각해...",
  ui_story_1017_10170101_89_dialog_content = "PlayerName 씨, 바이스 중위.",
  ui_story_1017_10170101_90_dialog_content = "아나톨리 소령님! 어떻게 됐어요?",
  ui_story_1017_10170101_91_dialog_content = "......",
  ui_story_1017_10170101_92_dialog_content = "어디 조용한 곳에 가서 이야기하도록 하죠.",
  ui_story_1017_10170101_93_dialog_content = "현재 변방에서는 암귀의 활동이 잦아지고 있으며, 상황은 이미 며칠째 지속되고 있습니다.",
  ui_story_1017_10170101_94_dialog_content = "<color=#FFB400>「어둠의 밑바닥 정찰대」</color>에는 이미 탐사 데이터를 토대로\n정찰 전략을 즉시 조정하도록 지시해 두었습니다.",
  ui_story_1017_10170101_95_dialog_content = "과거 데이터를 순차 비교한 결과, <color=#FFB400>오로라 교란</color> 빈도는 근 20년 이래 가장 높은 수준입니다.",
  ui_story_1017_10170101_96_dialog_content = "이는 즉 이클립스가 또 한 차례 「어둠의 위기」를 일으킬 가능성이 높음을 의미합니다.",
  ui_story_1017_10170101_97_dialog_content = "다들 들었겠지?",
  ui_story_1017_10170101_98_dialog_content = "지난번 어둠의 위기가 찾아왔을 때 이 자리에 앉아있던 것도 우리들이었어.",
  ui_story_1017_10170101_99_dialog_content = "시간이 많이 지나서 그런지 다들 더 과묵해졌네.",
  ui_story_1017_10170101_100_dialog_content = "어둠의 위기와 「가디언 1호」의 코어가 빼앗긴 일도 관계가 있는 겁니까?",
  ui_story_1017_10170101_101_dialog_content = "최근 이클립스가 취한 일련의 움직임은 두 사건의 관계를 충분히 증명하고 있어.",
  ui_story_1017_10170101_102_dialog_content = "다만 이번엔 놈들이 「가디언 1호」의 코어를 손에 넣었어. 상황은 조금 달라지겠지.",
  ui_story_1017_10170101_103_dialog_content = "추적 상황은 어떻게 돼가고 있습니까?",
  ui_story_1017_10170101_104_dialog_content = "방금 들은 보고 내용대로야. 이미 「최정예 정찰대」가 어둠의 밑바닥으로 출발했어.",
  ui_story_1017_10170101_105_dialog_content = "「최정예 정찰대」요?",
  ui_story_1017_10170101_106_dialog_content = "확실히 「최정예」라고 부를 만하다 생각하는데 말이지.",
  ui_story_1017_10170101_107_dialog_content = "팬텀 추적과 「가디언 1호」 탈환 임무는 에센에게 맡기는 게 아니었습니까?",
  ui_story_1017_10170101_108_dialog_content = "그 친구가 맡을 수 있었으면 내가 「페피타」를 부를 일도 없었겠지.",
  ui_story_1017_10170101_109_dialog_content = "페피타? 일루미나를 배반하고 진리의 결사에 들어간 그 죄수 말입니까?",
  ui_story_1017_10170101_110_dialog_content = "죄수라고요?",
  ui_story_1017_10170101_111_dialog_content = "다들 너무 과민반응 하는 거 아냐?",
  ui_story_1017_10170101_112_dialog_content = "그 여자는 감옥에 있어야 마땅합니다.",
  ui_story_1017_10170101_113_dialog_content = "오랜 시간 병사를 기르는 건 한순간의 전투를 위해서야.",
  ui_story_1017_10170101_114_dialog_content = "페피타는 어둠의 밑바닥 깊은 곳까지 진입한 경험이 있어.\n어떻게 보면 이 임무를 해낼 수 있는 유일한 인선이라 할 수 있겠지.",
  ui_story_1017_10170101_115_dialog_content = "벨리사리아, 위원회가 당신에게 사병을 조직하고 훈련할 권한을 준 적은 없을 텐데요.",
  ui_story_1017_10170101_116_dialog_content = "하지만 죄수를 개조하고 이용하는 것도 내 직무 범위잖아.",
  ui_story_1017_10170101_117_dialog_content = "다른 부대는 언제 출발하지?",
  ui_story_1017_10170101_118_dialog_content = "대원 정보는 이미 정리해 두었습니다. 명령만 내리시면 됩니다. 빠르면 내일 출발할 수 있을 겁니다.",
  ui_story_1017_10170101_119_dialog_content = "다른 부대가 또 있단 말입니까?",
  ui_story_1017_10170101_120_dialog_content = "조사 결과, 바이스 중위와 이번에 자난성에 잠입한 이클립스의 일원 사이에는\n모종의 특수한 관계가 있었습니다.",
  ui_story_1017_10170101_121_dialog_content = "그리고 연합 훈련 연습에 참가한 움브라톤 출신의 세 후보생 또한\n이클립스의 행적에 어느 정도 단서가 되었습니다.",
  ui_story_1017_10170101_122_dialog_content = "이상의 두 정보를 고려했을 때, 저희는 그들이 「가디언 1호」의 코어 추적에\n큰 도움이 될 것이라고 생각합니다.",
  ui_story_1017_10170101_123_dialog_content = "따라서 그들을 임시 부대로 조직하여, 「정찰대」의 보충 병력으로 삼고자 합니다.",
  ui_story_1017_10170101_124_dialog_content = "훗, 그 졸개들이 정말 움브라톤에서 왔다고 생각하시는 건 아니겠지요.",
  ui_story_1017_10170101_125_dialog_content = "역으로 코가 꿰이진 않으시길 바라겠습니다, 「철가면」 님.",
  ui_story_1017_10170101_126_dialog_content = "내가 편의를 봐주는 건 물론 저들에게 그만한 가치가 있기 때문이야.",
  ui_story_1017_10170101_127_dialog_content = "그것보다 당신 연구 상황이나 좀 들어볼까?\n율리시스, 무기는 좀 어때? 충분히 갈아뒀어?",
  ui_story_1017_10170101_128_dialog_content = "노라의 「실험체」에 대한 분석은 이미 마쳤습니다.\n이제 「계명성 프로젝트」를 새롭게 정의할 때가 온 것 같군요.",
  ui_story_1017_10170101_129_dialog_content = "「계명성 프로젝트」 2.0이 가동되면, 오로리안의 전투력은 큰 폭의 향상을 이룰 겁니다.",
  ui_story_1017_10170101_130_dialog_content = "그리고 지금은 바로 차기 대원수를 선출해야 할 때입니다.",
  ui_story_1017_10170101_131_dialog_content = "적임자가 있나요?",
  ui_story_1017_10170101_132_dialog_content = "대원수 인선은 현재 계획의 가장 취약한 부분입니다.",
  ui_story_1017_10170101_133_dialog_content = "제가 걱정하는 건 어둠의 위기가 다시 찾아왔을 때, 우리가 속수무책일 거라는 사실입니다.",
  ui_story_1017_10170101_134_dialog_content = "「대원수 인선이 현재 계획의 가장 취약한 부분이다」?",
  ui_story_1017_10170101_135_dialog_content = "그 의견엔 동의할 수 없습니다만.",
  ui_story_1017_10170101_136_dialog_content = "라인하르트가 최근 몇 년간 쌓은 영향력은 우리 예상을 진작에 넘어섰습니다.",
  ui_story_1017_10170101_137_dialog_content = "지금의 상황까지 오게 된 것도 모두 「계명성 프로젝트」가 초래한 것입니다만,\n그런데도 계속하겠다는 겁니까?",
  ui_story_1017_10170101_138_dialog_content = "라인하르트의 심문 결과도 아직 결정적인 증거가 뒷받침되지 못한 상황이에요.\n해임 처분도 결국 임시 조치에 불과할 텐데요.",
  ui_story_1017_10170101_139_dialog_content = "율리시스 박사야말로 너무 서두르시는 건 아닌가요?",
  ui_story_1017_10170101_140_dialog_content = "이미 결과가 나온 일을 논의하는 건 의미가 없습니다.",
  ui_story_1017_10170101_141_dialog_content = "이견이 있다면 절차에 따라 소송을 제기하시지요.",
  ui_story_1017_10170101_142_dialog_content = "율리시스 박사, 연구만 할 게 아니라 나가서 바깥 공기도 좀 쐬고 그러세요.",
  ui_story_1017_10170101_143_dialog_content = "고기를 먹겠다면서 가축이 스스로 도살장에 오게 만들 생각인가요?",
  ui_story_1017_10170101_144_dialog_content = "당신 「최강의 무기」를 자랑하는 건 저도 딱히 반대할 생각 없어요.",
  ui_story_1017_10170101_145_dialog_content = "하지만 누굴 대원수로 추천할지에 대해서는 지금 당신이 한 말처럼 절차를 따라 주었으면 좋겠네요.",
  ui_story_1017_10170101_146_dialog_content = "자, 거기까지 하자고. 우리 일루미나는 항상 공적인 문제를 우선시해 왔잖아.",
  ui_story_1017_10170101_147_dialog_content = "마침 사람도 모였겠다, 대원수 인선도 논의할 필요가 있겠어.",
  ui_story_1017_10170101_148_dialog_content = "자료는 보냈어?",
  ui_story_1017_10170101_149_dialog_content = "네, 여러분께서 지금 보고 계신 자료에는 영관급 이상 장교들의 이력이 상세히 기록되어 있습니다.",
  ui_story_1017_10170101_150_dialog_content = "내용에는 개인적인 인맥이나 동료 평가도 포함되어 있죠.",
  ui_story_1017_10170101_151_dialog_content = "일루미나 건립 당시, 대원수는 반드시 최강의 병사가 맡는 것이 모두의 결정이었습니다.",
  ui_story_1017_10170101_152_dialog_content = "나중에 그 규칙은 「대원수가 되려는 자는 반드시 신체 기능의 강화를 받아야 한다」는\n불문율로 발전했습니다.",
  ui_story_1017_10170101_153_dialog_content = "「계명성 프로젝트」 2.0의 시동에는 이견이 없습니다.\n능력만으로 본다면 대원수에 걸맞은 자는 저 장군들 네 명뿐이겠지요.",
  ui_story_1017_10170101_154_dialog_content = "하지만 저들 중에서 또 다른 라인하르트를 키워낸다면, 대원수를 교체하는 의미가 있나요?",
  ui_story_1017_10170101_155_dialog_content = "저들 중에서 대원수를 뽑는 건 우리 스스로 자기 목을 조르는 꼴 아닌가요?",
  ui_story_1017_10170101_156_dialog_content = "율리시스, 당신 생각은 어때?",
  ui_story_1017_10170101_157_dialog_content = "......",
  ui_story_1017_10170101_158_dialog_content = "네 사람 중에서 골라야 한다면, 확실히 적합한 사람이 한 명 있습니다만...",
  ui_story_1017_10170201_1_dialog_content = "누굽니까? 들어오세요.",
  ui_story_1017_10170201_2_dialog_content = "충성! 히이로 님... 군단장 여러분, 실례합니다...",
  ui_story_1017_10170201_3_dialog_content = "안녕하세요.",
  ui_story_1017_10170201_4_dialog_content = "방해해서 죄송합니다. 히이로 님을 뵈러 왔는데 다들 계실 줄은 몰랐어요...",
  ui_story_1017_10170201_5_dialog_content = "대원수님 일은 들었어요. 그럼...",
  ui_story_1017_10170201_X5_dialog_content = "<color=#e8d9bb>삑──삑!</color>",
  ui_story_1017_10170201_6_dialog_content = "......",
  ui_story_1017_10170201_7_dialog_content = "전장으로 돌아가라는 명령이다.",
  ui_story_1017_10170201_8_dialog_content = "벌써?",
  ui_story_1017_10170201_9_dialog_content = "나도 받았다. 이렇게 짧은 임무 설명은 또 처음이군.",
  ui_story_1017_10170201_10_dialog_content = "저도 받았습니다.",
  ui_story_1017_10170201_11_dialog_content = "흥, 반란이라도 일으킬까 걱정하는 건가?",
  ui_story_1017_10170201_12_dialog_content = "이 바튼, 오직 싸움만으로 일루미나 연방의 장군 자리까지 왔다.\n들이받는 건 내가 전문이라고!",
  ui_story_1017_10170201_13_dialog_content = "우선은 신중하게 각자의 임무에 힘쓰도록 하죠. 어쨌든 상황을 보면서 대응합시다.",
  ui_story_1017_10170201_14_dialog_content = "그래.",
  ui_story_1017_10170201_15_dialog_content = "레이스, 당신은요?",
  ui_story_1017_10170201_X15_dialog_content = "...응? 뭐가?",
  ui_story_1017_10170201_X16_dialog_content = "당신도 명령을 받았습니까?",
  ui_story_1017_10170201_X17_dialog_content = "...내 근위군단은 줄곧 장식이었잖아. 싸운다 해도 너희 먼저 나섰지.",
  ui_story_1017_10170201_X18_dialog_content = "무슨 일 있으면 언제든지 연락해, 몸조심하고.",
  ui_story_1017_10170201_X19_dialog_content = "네, 몸조심하세요.",
  ui_story_1017_10170201_16_dialog_content = "나? 어차피 <color=#FFB400>내 근위군단 같은 건 장식이잖아</color>. 싸운다 해도 일단 너희 먼저 나서야겠지. 난 당장 자난성을 떠나진 않을 거야.",
  ui_story_1017_10170201_17_dialog_content = "알겠어요, 그럼 몸조심하세요.",
  ui_story_1017_10170201_18_dialog_content = "......",
  ui_story_1017_10170201_19_dialog_content = "다 가버렸네.",
  ui_story_1017_10170201_20_dialog_content = "대체 무슨 일이지? 히이로 님까지 저렇게...",
  ui_story_1017_10170201_21_dialog_content = "넌 다들 무슨 얘기 하고 계셨을 것 같아?",
  ui_story_1017_10170201_22_option_content = "반란이겠지.",
  ui_story_1017_10170201_23_dialog_content = "지금 군단장들과 일루미나 상부의 관계는 일촉즉발의 상태야.",
  ui_story_1017_10170201_24_dialog_content = "라인하르트 씨가 저런 일을 당한 이상, 군단장들도 뭔가 행동을 취할지도 몰라...",
  ui_story_1017_10170201_25_dialog_content = "쉿! 그런 말은 꺼내면 안 되는 거야!",
  ui_story_1017_10170201_26_option_content = "라인하르트 씨를 구하는 일이겠지.",
  ui_story_1017_10170201_27_dialog_content = "라인하르트 씨가 모함을 당한 이상, 군단장들은 분명히 라인하르트 씨를 구하려고 할 거야.",
  ui_story_1017_10170201_28_dialog_content = "정말 그런 거라면... 우린 뭘 할 수 있을까...?",
  ui_story_1017_10170201_29_option_content = "모르겠어...",
  ui_story_1017_10170201_30_dialog_content = "군단장들이 바쁘게 가는 걸 보니까 상황이 좋지는 않은 것 같아.",
  ui_story_1017_10170201_31_dialog_content = "휴, 아무래도 우리 헛걸음한 것 같아...",
  ui_story_1017_10170201_32_dialog_content = "하아... 드디어 찾았네요, 바이스!",
  ui_story_1017_10170201_33_dialog_content = "당신이 맡을 긴급 임무가 있어요!",
  ui_story_1017_10170201_34_dialog_content = "너랑 같이 갈 멤버들은 앞에서 기다리고 있는 거야?",
  ui_story_1017_10170201_35_dialog_content = "아까 비비안 씨도 엄청 급해 보였어. 용건만 말하고 휙 가버리고 말이야.",
  ui_story_1017_10170201_36_dialog_content = "맞아, 안색도 별로 안 좋으셨어. 아무래도... 일루미나에 엄청난 격변이 일어날 것 같아.",
  ui_story_1017_10170201_37_dialog_content = "지금은 정보가 너무 많아서 머릿속이 혼란스러워...",
  ui_story_1017_10170201_38_dialog_content = "이상한 기차 기적소리까지 들리는 것 같아...",
  ui_story_1017_10170201_39_dialog_content = "그건 나한테도 들리는데...",
  ui_story_1017_10170201_40_dialog_content = "「삼도천 열차」의 승객들이여. 기다리고 있었다.",
  ui_story_1017_10170201_41_dialog_content = "카론 님! 그럼 이번 임무에 함께 동행하시는 건가요?",
  ui_story_1017_10170201_42_dialog_content = "반갑다, 바이스, 그리고 아이테르.",
  ui_story_1017_10170201_43_dialog_content = "반갑다, 바이스, 그리고 아이테르~",
  ui_story_1017_10170201_44_dialog_content = "반갑다, 바이스, 그리고 아이테르~",
  ui_story_1017_10170201_45_dialog_content = "마침내 다 모였군요. 크흠, 안녕하십니까.",
  ui_story_1017_10170201_46_dialog_content = "왜 너희가 여기 있어?",
  ui_story_1017_10170201_47_dialog_content = "후후! 깜짝 놀랐지? 우린 이래 봬도 <color=#FFB400>「추적 소대」</color>의 정식 멤버라구.",
  ui_story_1017_10170201_48_dialog_content = "맞아요. 그럼 이번 여행도 잘 부탁드릴게요.",
  ui_story_1017_10170201_49_dialog_content = "카론 님... 이게 대체 무슨...?",
  ui_story_1017_10170201_50_dialog_content = "이 멀리서 온 손님 세 사람도 너와 마찬가지로 「삼도천 열차」에 초청받은 동료다.",
  ui_story_1017_10170201_51_dialog_content = "동료요?",
  ui_story_1017_10170201_52_dialog_content = "그렇다. 하지만 네 이름은 명단에 없군, 아이테르여.",
  ui_story_1017_10170201_53_dialog_content = "그러니 돌아가라. 「삼도천 열차」는 이제 곧 출발할 테니.",
  ui_story_1017_10170201_54_dialog_content = "잠깐만요! 저도 태워 줘요!",
  ui_story_1017_10170201_55_dialog_content = "PlayerName, 넌 왜...?",
  ui_story_1017_10170201_56_dialog_content = "아이테르여, 가르쳐 주겠나. 왜 내가 널 열차에 태워야 하지?",
  ui_story_1017_10170201_57_option_content = "바이스가 걱정되니까요.",
  ui_story_1017_10170201_58_dialog_content = "비비안 씨한테 들었어요. 이번 임무는 어둠의 밑바닥 깊은 곳으로 들어갈 수도 있다고 말이에요...",
  ui_story_1017_10170201_59_dialog_content = "연합 훈련 때 마주친 그 정체불명의 적이 또 바이스한테 무슨 짓을 할까 걱정돼요.",
  ui_story_1017_10170201_60_dialog_content = "그러니까 저도 같이 데려가 주세요.",
  ui_story_1017_10170201_61_option_content = "카론 씨가 걱정되니까요.",
  ui_story_1017_10170201_62_dialog_content = "일루미나가 「추적 소대」를 꾸렸다고 비비안 씨한테 들었는데, 설마 저 세 사람이 있을 줄은 몰랐어요.",
  ui_story_1017_10170201_63_dialog_content = "카론 씨를 곤란하게 만들지도 몰라요. 그러니까 저도 같이 가요.",
  ui_story_1017_10170201_64_dialog_content = "내 동료라면 물론 널 태우는 걸 반대하지 않을 거다. 다만 이 길에는 많은 위험이 기다리고 있다.",
  ui_story_1017_10170201_65_dialog_content = "어쩌면 여정의 종점이 곧 생명의 종점이 될 수도 있지.",
  ui_story_1017_10170201_66_dialog_content = "절 믿어주세요! 위험한 일은 저도 경험이 충분히 많으니까요!",
  ui_story_1017_10170201_67_dialog_content = "PlayerName...",
  ui_story_1017_10170201_68_dialog_content = "오! 들었나? 「피안호」여, 아이테르가 우리와 함께 지옥으로 가겠다는구나!",
  ui_story_1017_10170201_69_dialog_content = "그렇게까지 말한 건 아니었는데요...",
  ui_story_1017_10170201_70_dialog_content = "유감이지만 초청받지 않은 손님들은 비켜주었으면 좋겠군. 우린 이제 출발해야 하니 말이야.",
  ui_story_1017_10170201_71_dialog_content = "어둠의 밑바닥에 가려면 더 많은 준비가 필요하다.",
  ui_story_1017_10170201_72_dialog_content = "그럼 다녀올게, PlayerName.",
  ui_story_1017_10170201_73_option_content = "응, 바이스.",
  ui_story_1017_10170201_74_dialog_content = "뭐 할 말 없어?",
  ui_story_1017_10170201_75_dialog_content = "있어...",
  ui_story_1017_10170201_76_option_content = "잠깐만 기다려, 바이스.",
  ui_story_1017_10170201_77_dialog_content = "왜 그래?",
  ui_story_1017_10170201_78_dialog_content = "어둠의 밑바닥은 위험하니까, 꼭 조심해.",
  ui_story_1017_10170201_79_dialog_content = "그래, 알아. 그치만 지금까지 어떤 위험이든 극복해 왔잖아?",
  ui_story_1017_10170201_80_dialog_content = "그건 그때마다...",
  ui_story_1017_10170201_81_dialog_content = "그때마다 뭐?",
  ui_story_1017_10170201_82_dialog_content = "...아무튼 안 좋은 예감이 들어...",
  ui_story_1017_10170201_83_dialog_content = "알고 있다구. 넌 아이테르고, 감응 능력이 뛰어나고, 여러 가지로 대단하잖아.",
  ui_story_1017_10170201_84_dialog_content = "그치만 카론 님도 계시니까 분명히 괜찮을 거야!",
  ui_story_1017_10170201_85_dialog_content = "응, 혹시라도 정말 위험한 일이 생기면... 내 이름을 불러줘!",
  ui_story_1017_10170201_86_dialog_content = "네 이름을 부르라고? 그렇게 멀리 있는데 그게 들려?",
  ui_story_1017_10170201_87_dialog_content = "몰라. 아무튼 한번 해보면 되지.",
  ui_story_1017_10170201_88_dialog_content = "너 좀 이상해... 아무튼 안녕!",
  ui_story_1017_10170201_89_dialog_content = "응, 바이스, 다녀와.",
  ui_story_1017_10170201_90_dialog_content = "<color=#e8d9bb>두근... 두근...</color>",
  ui_story_1017_10170201_X90_dialog_content = "「Vice」...",
  ui_story_1017_10170201_91_dialog_content = "물어보고 싶은 게 있다면 뭐든 물어보세요.",
  ui_story_1017_10170201_92_dialog_content = "이해가 안 돼. 피제로는 당신을 위해서 죽도록 일했는데, 왜 그런 꼴을 맞게 된 거지?",
  ui_story_1017_10170201_93_dialog_content = "사서 고생하는 녀석에게 좋은 결과는 없기 마련이에요. 기회를 안 준 것도 아니고 말이죠.",
  ui_story_1017_10170201_94_dialog_content = "어쨌든, 결과가 그리 좋진 않았으니까, 당신들은 전부 죽어야 해요.",
  ui_story_1017_10170201_95_dialog_content = "하지만 아쉽게도 물건을 손에 넣었고, 임무를 완수해 버렸네요.",
  ui_story_1017_10170201_96_dialog_content = "벌써 자축하는 건가요? 아네모네.",
  ui_story_1017_10170201_97_dialog_content = "물건은 이미 손에 넣었어요.",
  ui_story_1017_10170201_98_dialog_content = "어디 보자... 음, 이게 뭔지 알고 있나요? 일루미나의 계집애.",
  ui_story_1017_10170201_99_dialog_content = "날 그렇게 부르지 말라고 했을 텐데.",
  ui_story_1017_10170201_100_dialog_content = "후훗, 유치하군요... 어디 말해 보세요.",
  ui_story_1017_10170201_101_dialog_content = "그냥 오래된 기계잖아. 고작 그거 때문에 지금까지 그 난리를 친 거였어?",
  ui_story_1017_10170201_102_dialog_content = "맞아요, 오래된 기계예요. 하지만 이건 <color=#FFB400>「엔지니어」</color>의 것이에요.\n그저 실수로... 자난성에 두고 갔을 뿐이죠.",
  ui_story_1017_10170201_103_dialog_content = "「엔지니어」?",
  ui_story_1017_10170201_104_dialog_content = "아무래도 정말 모르는 모양이군요, 일루미나의 계집애.",
  ui_story_1017_10170201_105_dialog_content = "「엔지니어」는 일루미나의 역사보다 오래된 존재예요.\n「엔지니어」가 없으면 일루미나는 아무것도 아니죠.",
  ui_story_1017_10170201_106_dialog_content = "당신들, 뭘 하려는 거지?",
  ui_story_1017_10170201_107_dialog_content = "물건을 얻었으면 물론 주인에게 돌려줘야죠, 세상은 지금 보이는 게 다가 아니에요.\n「엔지니어」가 깨어나면 당신도 더 많은 걸 보게 되겠죠.",
  ui_story_1017_10170201_108_dialog_content = "아, 마침 「엔지니어」의 행차를 위한 「카펫」을 깔아주는 일에 관심이 있을지 모르겠네요...",
  ui_story_1017_10170201_109_dialog_content = "이클립스의 전당에서 아스트라의 중심으로 이어지는──",
  ui_story_1017_10170201_110_dialog_content = "칠흑 같은 다크매터와 오로리안의 시체 조각들로 이루어진 거대한 「카펫」 말이에요.\n분명히 장관일 것 같네요.",
  ui_story_1017_10170201_111_dialog_content = "그게 나한테 무슨 이점이 있지?",
  ui_story_1017_10170201_112_dialog_content = "이점? 이클립스를 위해 일할 수 있는 것만으로도 당신에겐 이미 은혜인걸요.",
  ui_story_1017_10170201_113_dialog_content = "언제까지 떠들고 있을 생각이죠? 아스모데우스, 돌아가서 보고 안 할 건가요?",
  ui_story_1017_10170201_114_dialog_content = "당신은 참 재미없다니까요...",
  ui_story_1017_10170201_115_dialog_content = "그럼 이건 어떨까요? 당신이 「카펫」을 깔아준다면 제가 약속하죠.\n일이 잘되고 난 뒤엔 이클립스에 당신 자리도 하나 생길 거예요.",
  ui_story_1017_10170201_116_dialog_content = "흥, 그 「카펫」 까는 게 말처럼 쉽진 않을 텐데. 당신도 알잖아.",
  ui_story_1017_10170201_117_dialog_content = "걱정 마세요. 당신이 발명한 그 쓰레기들 중에도 그나마 도움이 될 만한 게 있으니까,\n제가 가지고 와 줄게요.",
  ui_story_1017_10170201_118_dialog_content = "당신이 한 일을 「엔지니어」가 알면, 일루미나의 동포로서 당신을 만나고 싶어 하지 않겠어요?",
  ui_story_1017_10170201_119_dialog_content = "일은 내가 알아서 잘 처리할 거야. 대신 도중에 개인적인 원한도 좀 해결해야겠어.",
  ui_story_1017_10170201_120_dialog_content = "마음대로 하세요. 대신 서두르는 게 좋을 거예요.\n당신네 일루미나의 동료들이 더는 기다려 주지 않을 거라서요.",
  ui_story_1017_10170201_121_dialog_content = "말 안 해도 이미 알고 있다고.",
  ui_story_1017_10170201_122_dialog_content = "당신은 당신 일에 집중하세요. 시끄러운 벌레들은 녀석들한테 먹이로 주면 되니까요.",
  ui_story_1017_10170202_1_dialog_content = "대장님, 암귀를 모두 처리했습니다. 위험 상황은 종료됐습니다!",
  ui_story_1017_10170202_2_dialog_content = "내가 대장이라고 부르지 말라고 했지?",
  ui_story_1017_10170202_3_dialog_content = "앞서던 녀석들은 이미 자리도 옮겨 버렸어. 너희가 처치한 이것들은──",
  ui_story_1017_10170202_4_dialog_content = "하나도! 재미없다고!",
  ui_story_1017_10170202_5_dialog_content = "하지만 페피타 대장님, 우리가 쫓고 있는 적은 정말로 아주 강합니다!",
  ui_story_1017_10170202_6_dialog_content = "방금 계기판에 나온 다크매터 수치는 이미 최고치에 근접했습니다.",
  ui_story_1017_10170202_7_dialog_content = "그러니까 내가 말했잖아. 아까 그 세 마리가 나타났을 때 곧바로 갖다 박았어야지.",
  ui_story_1017_10170202_8_dialog_content = "굳이 굳이 이게 어쩌고 저게 어쩌고 보고나 하고 앉았고... 흥도 다 깨진 건 그렇다 쳐.\n이러다 쟤들 아예 놓쳐버리면 네 책임이야!",
  ui_story_1017_10170202_9_dialog_content = "대장님, 전 그저 정찰 수칙에 따라 발견 사항을 보고했을 뿐입니다.",
  ui_story_1017_10170202_10_dialog_content = "감지된 이상 기후... 다크매터가 대륙 중심부로 퍼져나가는 속도...\n그리고 1킬로미터마다 현 위치 좌표 보고까지...",
  ui_story_1017_10170202_11_dialog_content = "알았으니까 그만 말해. 그치만 나한테는 그런 거 안 시키겠다고 벨리사리아가 약속했단 말이야.",
  ui_story_1017_10170202_12_dialog_content = "너흰 사람도 그렇게 많으면서 고작 그런 상황 보고 좀 하는 것도 힘들어?",
  ui_story_1017_10170202_13_dialog_content = "그, 그게...",
  ui_story_1017_10170202_14_dialog_content = "그럼 발상을 전환해 보자. 우리 목표는 「가디언 1호」의 코어 추적이야.\n뭐가 어떻게 되든 물건을 되찾는 게 제일 중요해.",
  ui_story_1017_10170202_15_dialog_content = "예, 대장님! 그럼 아까 그 방향으로 계속 전진합니까?",
  ui_story_1017_10170202_16_dialog_content = "이제 곧 어둠의 밑바닥이니까 내가 앞장설게. 이 길이라면 눈 감고도 갈 수 있으니까.",
  ui_story_1017_10170202_17_dialog_content = "벌써 다 온 겁니까?! 이번 임무가 순조롭게 진행되고 있는 모양이군요!",
  ui_story_1017_10170202_18_dialog_content = "쫓아가는 건 쉽지만, 되찾는 건 너희한테 달렸어.",
  ui_story_1017_10170202_19_dialog_content = "미리 말해두는데, 이따가 또 길 막는 암귀가 나오면 내가 조종할 테니까, 너흰 내려가서 치워.",
  ui_story_1017_10170202_20_dialog_content = "이건 긴급 임무야. 이제 더는 지체되면 안 돼.",
  ui_story_1017_10170202_21_dialog_content = "예! 대장님!",
  ui_story_1017_10170202_22_dialog_content = "다시 말하지만 난 너희 대장이 아니라구!",
  ui_story_1017_10170301_1_dialog_content = "군단장님도 자세히 말씀은 안 하셨지만, 일부 병사들은 이미 각 전선에 파견됐어.",
  ui_story_1017_10170301_2_dialog_content = "하지만 대원수님 일이 터진 지도 얼마 안 됐는데, 어째서 이런 시기에...",
  ui_story_1017_10170301_3_dialog_content = "그러게 말이야. 대원수님도 안 계시는데, 앞으로 누가 전군을 지휘하는 거지...",
  ui_story_1017_10170301_4_dialog_content = "「일루미나 동포 여러분, 지금부터 중대 발표가 있겠습니다──」",
  ui_story_1017_10170301_5_dialog_content = "......",
  ui_story_1017_10170301_6_dialog_content = "「일루미나 연방은 건립 이래로 역대 대원수들의 통솔 아래 암귀의 침입에 맞서 왔습니다.」",
  ui_story_1017_10170301_7_dialog_content = "「우리는 공동의 이상을 토대로 오로리안 동맹을 결성했고,\n대원수의 영광은 항상 일루미나를 비춰 왔습니다.」",
  ui_story_1017_10170301_8_dialog_content = "「어쩌면 지금 우리는 유사 이래 가장 큰 존망의 위기에 처해 있을지도 모릅니다...」",
  ui_story_1017_10170301_9_dialog_content = "「하지만 앞길이 아무리 칠흑같이 어둡더라도,\n우리는 변함없이 손을 잡고 함께 나아가야 합니다.」",
  ui_story_1017_10170301_10_dialog_content = "「지금 이 순간, 일루미나 연방 군사 및 정무위원회의 이름으로\n일루미나의 모든 동포에게 알립니다──」",
  ui_story_1017_10170301_11_dialog_content = "「일루미나의 신임 대원수가 모든 준비를 마치고, 이제 계속해서 일루미나를 이끌어\n암귀와 맞서 싸우는 사명을 완수할 것입니다.」",
  ui_story_1017_10170301_12_dialog_content = "「새로운 일루미나의 대원수──」",
  ui_story_1017_10170301_13_dialog_content = "「레이스 대원수님이 이끄는 일루미나 연방의 미래로 함께 나아갑시다!」",
  ui_story_1017_10170301_14_dialog_content = "...레이스 군단장님?!",
  ui_story_1017_10170301_15_dialog_content = "레이스 군단장님이... 신임 대원수?!",
  ui_story_1017_10170301_16_dialog_content = "역시 레이스 장군이 대원수가 됐구나~",
  ui_story_1017_10170301_17_dialog_content = "뭐, 뭐야... 갑자기 왜 다들 온 거야?",
  ui_story_1017_10170301_18_dialog_content = "PlayerName, 내 부하들한테 연락을 받았거든. 더스크 타운에 암귀가 침입했어!",
  ui_story_1017_10170301_19_dialog_content = "하필 이럴 때?!",
  ui_story_1017_10170301_20_dialog_content = "그래, 일루미나 상부의 이번 반응은 정말 빠르네. 대원수 교체까지 끝내버리다니 말이야.",
  ui_story_1017_10170301_21_dialog_content = "연합 훈련에서 벌어진 상황들, 전임 대원수의 투옥, 변방 지역 암귀의 움직임...\n이 모든 건 절대 우연이 아냐.",
  ui_story_1017_10170301_22_dialog_content = "(바이스도 지금 임무 때문에 어둠의 밑바닥에 가 있잖아...)",
  ui_story_1017_10170301_23_dialog_content = "더 분석하고 있을 시간이 없어, PlayerName.",
  ui_story_1017_10170301_24_dialog_content = "콜로서스 수리가 끝났다고 들었어.\n콜로서스로 우릴 더스크 타운까지 데려다 달라고 부탁하고 싶어.",
  ui_story_1017_10170301_25_dialog_content = "그게 지금 내가 생각할 수 있는 것 중에서 가장 빠른 방법이거든.",
  ui_story_1017_10170301_26_dialog_content = "그거야 괜찮긴 한데... 스카이워커는 지금 계속 그로누가 테스트 중이거든.",
  ui_story_1017_10170301_27_dialog_content = "그래서 나도 온 거야.",
  ui_story_1017_10170301_28_dialog_content = "스카이워커호에 대한 연구라면 아직 한참 부족하지만, 비행은 언제든지 가능해.",
  ui_story_1017_10170301_29_dialog_content = "진짜?",
  ui_story_1017_10170301_30_dialog_content = "당연하지.",
  ui_story_1017_10170301_31_dialog_content = "부탁할게, PlayerName!\n이번 여정은 쉽지 않겠지만, 더스크 타운이 위험에 처한 이상, 난 반드시 돌아가야 해.",
  ui_story_1017_10170301_32_dialog_content = "알겠어, 그럼 바로 출발하자!",
  ui_story_1017_10170301_33_dialog_content = "잠시만요, 레오. 당신들 먼저 돌아가세요. 전 백야성 쪽과 한번 이야기해 볼까 해요.",
  ui_story_1017_10170301_34_dialog_content = "백야성? 카렌 전하조차 방법이 없었는데, 네가 가서 뭐 하려고?",
  ui_story_1017_10170301_35_dialog_content = "그쪽 상황은 적어도 여기보다는 나을 거예요.",
  ui_story_1017_10170301_36_dialog_content = "여러분은 PlayerName 씨와 먼저 돌아가세요.\n우리가 함께 지키는 도시를 위해, 얼마나 어렵든 저도 뭔가 해 볼 테니까요.",
  ui_story_1017_10170301_37_dialog_content = "......",
  ui_story_1017_10170301_38_dialog_content = "진심이야?",
  ui_story_1017_10170301_39_dialog_content = "네, 지금 더스크 타운이 위기에 빠진 상황에서, 「강철가시 기사단」에는 당신이 필요해요.",
  ui_story_1017_10170301_40_dialog_content = "절 믿으세요. 훈련에 참가한 건 더스크 타운의 상황을 알리기 위해서였던 것처럼,\n백야성에 지원을 요청하는 것도 제 계획의 일부예요.",
  ui_story_1017_10170301_41_dialog_content = "참모 없는 전장에 어떤 결과가 있을지는 너도 잘 알 텐데.",
  ui_story_1017_10170301_42_dialog_content = "PlayerName 씨가 있다면 결과는 같을 거예요. 심지어 더 좋을 수도 있겠죠.",
  ui_story_1017_10170301_43_dialog_content = "어떤가요? 당신은 병사들을 이끌고 암귀를 없애고, 전 그 뒤에 좋은 소식을 가지고 돌아가죠.",
  ui_story_1017_10170301_44_dialog_content = "요제프 신부, 어떻게 생각해?",
  ui_story_1017_10170301_45_dialog_content = "참모님이라면 반드시 해내리라 믿습니다. 그리고 당신과 PlayerName도 믿습니다.",
  ui_story_1017_10170301_46_dialog_content = "네, 최선을 다할게요!",
  ui_story_1017_10170301_47_dialog_content = "그럼 네 말대로 하자고. 약속이야.",
  ui_story_1017_10170301_48_dialog_content = "몸조심하세요.",
  ui_story_1017_10170301_49_dialog_content = "몸조심해.",
  ui_story_1017_10170301_50_dialog_content = "<color=#e8d9bb>같은 시간, 율리시스의 실험실...</color>",
  ui_story_1017_10170301_51_dialog_content = "교수님, 1기 「씨앗」들의 방향성 선택 시뮬레이션 데이터가 유의성 검정을 통과했습니다.",
  ui_story_1017_10170301_52_dialog_content = "진행이 예상보다 빠릅니다. 이제 임상실험을 시작할 수 있지 않을까요?",
  ui_story_1017_10170301_53_dialog_content = "음, 방금 방송 들었겠죠? 새 대원수도 취임했으니, 그 어떤 실수도 있어서는 안 됩니다.",
  ui_story_1017_10170301_54_dialog_content = "네, 교수님. 그리고 지금까지 교수님 실험에 실수 같은 건 단 한 번도 없었잖아요.",
  ui_story_1017_10170301_55_dialog_content = "허허, 지나간 일은 생각할 필요가 없는 겁니다.",
  ui_story_1017_10170301_56_dialog_content = "역시 참 겸손하다니까. 모든 게 계획대로 되고 있는 모양이네.",
  ui_story_1017_10170301_57_dialog_content = "...먼저 나가 있으세요.",
  ui_story_1017_10170301_58_dialog_content = "네, 교수님.",
  ui_story_1017_10170301_59_dialog_content = "소기의 결과를 내고 싶다면, 실험 중에도 목표에 맞춰 조정이 필요한 법이죠.",
  ui_story_1017_10170301_60_dialog_content = "그래서 당신 목표가 레이스였어?",
  ui_story_1017_10170301_61_dialog_content = "제 생각은 잘 아실 텐데요.",
  ui_story_1017_10170301_62_dialog_content = "내 목적은 하나뿐이야. 일루미나의 안정을 위협하지 않는 한,\n 난 어떤 변화라도 수용할 수 있어.",
  ui_story_1017_10170301_63_dialog_content = "「계명성 프로젝트」 2.0도 그 수용 범위 내에 있는 겁니까?",
  ui_story_1017_10170301_64_dialog_content = "암귀가 벌써 더스크 타운을 친 모양이야.\n이클립스의 최근 동향은 마치 당신 실험에 맞춰 준비된 게 아닌가 싶을 정도네.",
  ui_story_1017_10170301_65_dialog_content = "암귀와의 싸움에 투기성 결정이란 결코 있을 수 없는 일입니다.",
  ui_story_1017_10170301_66_dialog_content = "전 어둠의 위기가 끝났을 무렵부터 이미 오로리안 육체 개조 연구에 몰두해 왔습니다.",
  ui_story_1017_10170301_67_dialog_content = "그리고 최근 몇 년간 서서히 확신했습니다.\n노라의 「씨앗」은 매우 중요한 관건이 될 것이라고 말이지요.",
  ui_story_1017_10170301_68_dialog_content = "당신이 원하는 게 나와 같길 바랄게. 대신 충고는 해야겠어.\n과학자에게 있어 질투는 독약이야.",
  ui_story_1017_10170301_69_dialog_content = "그저 심리 상담만을 위해 절 찾아오신 건 아니겠죠.",
  ui_story_1017_10170301_70_dialog_content = "잡담은 다음에 하자고.\n내가 알고 싶은 건 당신이 「계명성 프로젝트」 2.0을 가동하는 목적이 나와 같은지야.",
  ui_story_1017_10170301_71_dialog_content = "대원수의 취임 세리머니로 가장 좋은 건 역시 전쟁에서 이기는 거잖아?",
  ui_story_1017_10170301_72_dialog_content = "난 레이스만이 아니라, 레이스가 이끄는 군단도 쇄신된 모습으로 전장에 나섰으면 좋겠어.",
  ui_story_1017_10170301_73_dialog_content = "허허, 「철가면」 님. 전 그 별명이 당신과 어울리지 않는다는 생각이 드는군요.",
  ui_story_1017_10170301_74_dialog_content = "명예, 품위, 만인의 존경... 당신이 대원수가 되신다면 더 멋진 국면이 펼쳐질 텐데 말이지요.",
  ui_story_1017_10170301_75_dialog_content = "40년간 일해온 경험으로 확신하는데, 가장 어려운 도전은 공격이 아니라 방어야.",
  ui_story_1017_10170301_76_dialog_content = "게다가 젊은이에겐 젊은이의 운명이 있어. 우린 저들의 성장을 위한 무대를 제공해야만 해.",
  ui_story_1017_10170301_77_dialog_content = "그렇다면 더스크 타운을 「계명성 프로젝트」 2.0의 무대로 삼도록 하죠.",
  ui_story_1017_10170301_78_dialog_content = "레이스도, 수천수만의 일루미나 병사들도 얼마든지 좋습니다. 모두 제 계획에 참여해서...",
  ui_story_1017_10170301_79_dialog_content = "일루미나 연방의 「별」이 되어, 더스크 타운에 여명을 가져다줄 것입니다.",
  ui_story_1017_10170301_80_dialog_content = "들어오세요.",
  ui_story_1017_10170301_81_dialog_content = "교수님, 오늘의 암귀 기능 실험이 곧 시작됩니다. 참관하실 겁니까?",
  ui_story_1017_10170301_82_dialog_content = "어떠십니까? 「철가면」 님. 비록 늘 하던 대로 암귀의 기능 데이터를 기록할 뿐이지만 말입니다.",
  ui_story_1017_10170301_83_dialog_content = "같이 가 볼까. 쇳덩어리 의자에 앉아 있는 것도 지겹던 참이거든.",
  ui_story_1017_10170302_1_dialog_content = "들어와라.",
  ui_story_1017_10170302_2_dialog_content = "율리시스 님, 대원수가 곧 출병할 겁니다. 실험 쪽은 더 필요한 게 있습니까?",
  ui_story_1017_10170302_3_dialog_content = "먼저 이 보고서를 살펴보게.",
  ui_story_1017_10170302_4_dialog_content = "이 데이터... 훌륭하군요! 율리시스 님, 실험에 성공하셨군요!",
  ui_story_1017_10170302_5_dialog_content = "이토록 위대한 계획에 절 참여시켜 주셔서 감사합니다.",
  ui_story_1017_10170302_6_dialog_content = "아니, 아직 멀었네.",
  ui_story_1017_10170302_7_dialog_content = "그게... 무슨 말씀이신지...?",
  ui_story_1017_10170302_8_dialog_content = "이번엔 1기 「씨앗」들일 뿐일세. 이어서 2기, 3기가 생산될 걸세.",
  ui_story_1017_10170302_9_dialog_content = "그렇다면... 이번 더스크 타운행은 그저 1기 실험체에 대한 검증 과정일 뿐인 겁니까?",
  ui_story_1017_10170302_10_dialog_content = "그렇네. 이번 임상 데이터는 나쁘지 않았지.\n하지만 과학 연구란 기적과 파멸이 반씩 들어 있는 상자 같은 것일세.",
  ui_story_1017_10170302_11_dialog_content = "상자 속 내용물을 확실하게 보기 위해서는 끝없이 실험을 개선해야 하네.\n다행히 이 며칠간의 데이터는 괜찮아 보이는군.",
  ui_story_1017_10170302_12_dialog_content = "예, 물론 이해합니다...",
  ui_story_1017_10170302_13_dialog_content = "무슨 걱정거리라도 있는 건가?",
  ui_story_1017_10170302_14_dialog_content = "그... 말씀드려도 될지 모르겠습니다만...",
  ui_story_1017_10170302_15_dialog_content = "상관없으니 말해보게.",
  ui_story_1017_10170302_16_dialog_content = "최근 일부 병사들이 특별한 약물 주사를 맞고 무서운 능력을 얻었다는 소문이\n자난성에 돌고 있습니다.",
  ui_story_1017_10170302_17_dialog_content = "그건 사실이잖나.",
  ui_story_1017_10170302_18_dialog_content = "일부만 사실이죠. 전 지금 상황이 향후 계획에 차질을 줄까 우려가 됩니다.",
  ui_story_1017_10170302_19_dialog_content = "그것뿐인가?",
  ui_story_1017_10170302_20_dialog_content = "그리고... 라인하르트의 공개재판 때 저희 움직임이 잠재적인 문제를\n만들진 않았을까 걱정이 됩니다.",
  ui_story_1017_10170302_21_dialog_content = "허허, 자네가 무슨 말을 하고 싶은지는 알겠네, 에센.",
  ui_story_1017_10170302_22_dialog_content = "위원회의 젊은 일원으로서 자네가 알 수 있는 것에는 한계가 있겠지.",
  ui_story_1017_10170302_23_dialog_content = "무슨 말씀이신지 잘 모르겠습니다...",
  ui_story_1017_10170302_24_dialog_content = "나도 자네 나이였을 때 자네와 같은 고민을 가지고 있었네.",
  ui_story_1017_10170302_25_dialog_content = "정확하고 오류 없는 실험 절차를 토대로, 발생 가능한 모든 결과에 대응책을 마련해 두었지...",
  ui_story_1017_10170302_26_dialog_content = "그땐 모든 게 자신의 수중에 있는 그 감각에 흠뻑 취해 있었다네.",
  ui_story_1017_10170302_27_dialog_content = "하지만 소위 말하는 그 「완벽주의」 때문에 난 많은 것을 잃었네.",
  ui_story_1017_10170302_28_dialog_content = "뭘 잃으셨습니까?",
  ui_story_1017_10170302_29_dialog_content = "돌파, 의외... 기적이라고 불리는 모든 것들을 잃었지.",
  ui_story_1017_10170302_30_dialog_content = "하지만 「규칙, 계획, 실행, 복기」는 우리 모든 일루미나인들이 어릴 때부터\n익숙하게 배워 온 방법론 아닙니까?",
  ui_story_1017_10170302_31_dialog_content = "그래서 자네가 아직 젊다고 말한 걸세. 자네도 자신만의 생존 방법을 찾을 필요가 있네.",
  ui_story_1017_10170302_32_dialog_content = "질서란 허황된 이상일 뿐, 오직 혼돈이야말로 세계의 본질이니 말이야.",
  ui_story_1017_10170302_33_dialog_content = "......",
  ui_story_1017_10170302_34_dialog_content = "율리시스 님의 이상은 일루미나에서 가장 뛰어난 과학자가 되는 것입니까?",
  ui_story_1017_10170302_35_dialog_content = "지금은 아니란 말인가?",
  ui_story_1017_10170302_36_dialog_content = "그럴 리가요! 물론 이미 최고의 과학자이십니다!",
  ui_story_1017_10170302_37_dialog_content = "함께 1기 「씨앗」이나 보러 가세.",
  ui_story_1017_10170302_38_dialog_content = "예.",
  ui_story_1017_10170401_1_dialog_content = "「오늘 대원수님께서는 더스크 타운의 암귀 진압을 위해 근위군단을 이끌고 출정하실 것입니다.」",
  ui_story_1017_10170401_2_dialog_content = "「이번 출병은 신임 대원수 취임 후의 첫 공개 행보이기도 합니다.」",
  ui_story_1017_10170401_3_dialog_content = "「일루미나 근위군단의 정예 전사가 되기 위해서는 매우 엄격한 훈련과 선발을\n거쳐야 한다고 알려져 있습니다.」",
  ui_story_1017_10170401_4_dialog_content = "「게다가 이번에는 많은 병사들이 일루미나의 신형 무기 『엔진 7호』를 사용해\n전투를 수행할 것이라고 합니다.」",
  ui_story_1017_10170401_5_dialog_content = "「히이로 장군님의 제3군단도 이미 집결을 마쳤습니다.」",
  ui_story_1017_10170401_6_dialog_content = "「지금 많은 일루미나 군인들과 주민들이 자발적으로 이 자리에 모여\n대원수님의 등장을 기다리고 있습니다.」",
  ui_story_1017_10170401_7_dialog_content = "저기 좀 봐! 오셨어!",
  ui_story_1017_10170401_8_dialog_content = "엄청난 위압감이다...",
  ui_story_1017_10170401_9_dialog_content = "「대원수님께서 근위군단을 이끌고 이 자리에 나오셨습니다!\n일루미나의 동포 여러분, 뜨거운 박수로 맞이해 주시기 바랍니다!」",
  ui_story_1017_10170401_10_dialog_content = "「대원수님과 병사들의 얼굴에는 승리의 확신이 서 있습니다.\n아직 출병 전이지만, 마치 개선 행진을 보는 것만 같습니다.」",
  ui_story_1017_10170401_11_dialog_content = "「그리고 대원수님 다음으로 이번 출정에서 주목받는 『엔진 7호』는\n일루미나 그로누 연구원장과 개발진이 제작한 것이라고 합니다.」",
  ui_story_1017_10170401_12_dialog_content = "「『엔진 7호』의 탄생까지는 정말 수많은 곡절이 있었다고 하는데요.\n오늘 제가 현장에서 여러분께 더 자세한 정보를 전달해 드리겠습니다.」",
  ui_story_1017_10170401_13_dialog_content = "──으앗! 아파라...",
  ui_story_1017_10170401_14_dialog_content = "미안해요...",
  ui_story_1017_10170401_15_dialog_content = "어라? 당신, 시범 경기에서 승리한 악셀리아죠?!",
  ui_story_1017_10170401_16_dialog_content = "라인하르트 전임 대원수보다 강한 전사! 당신도 근위군단 소속이었군요!",
  ui_story_1017_10170401_17_dialog_content = "「전쟁 기계」 악셀리아는 일루미나를 위해 탄생했습니다.",
  ui_story_1017_10170401_18_dialog_content = "근위군단은 전부... 저런 「괴물」들로 이루어진 건가?",
  ui_story_1017_10170401_19_dialog_content = "체격부터가 우리랑 전혀 다르잖아...",
  ui_story_1017_10170401_20_dialog_content = "저런 병사들을 이끌고 싸운다니, 대원수님은 정말 엄청나네...",
  ui_story_1017_10170401_21_dialog_content = "응, 딱 봐도 알겠어. 전임 대원수님보다도 강해!",
  ui_story_1017_10170401_22_dialog_content = "근데... 히이로 군단장님 표정 봤어? 엄청 굳어 있는데...",
  ui_story_1017_10170401_23_dialog_content = "히이로 군단장님이라면 언제든 그러시잖아.",
  ui_story_1017_10170401_24_dialog_content = "그렇게 작게 말해서야 대원수님이 못 들으실 거예요.",
  ui_story_1017_10170401_25_dialog_content = "차, 참모장님! 저흰...",
  ui_story_1017_10170401_26_dialog_content = "변명은 여러분 군단장한테 가서 하세요. 일단 저도 기록해 둘 테니까요.",
  ui_story_1017_10170401_27_dialog_content = "참모장님...",
  ui_story_1017_10170401_28_dialog_content = "잉겔 중령? 당신이 왜 여기 있죠? 신임 대원수가 나온다니 구경이라도 하러 온 건가요?",
  ui_story_1017_10170401_29_dialog_content = "전 악셀리아가 걱정돼서 온 거예요.",
  ui_story_1017_10170401_30_dialog_content = "저 앤 율리시스 박사의 회심작이잖아요. 걱정할 게 뭐가 있겠어요.",
  ui_story_1017_10170401_31_dialog_content = "저번 전투에서 악셀리아는 이미 한계에 내몰렸어요.\n하지만 교수님은 왠지 그렇게 생각하지 않으시는 것 같아요...",
  ui_story_1017_10170401_32_dialog_content = "그 사람 생각까지 읽을 수 있다니, 그거 정말 대단하네요.",
  ui_story_1017_10170401_33_dialog_content = "이렇게 말하면 어쩌면 「계명성 프로젝트」에 참여한 병사들에겐 불공평할 수 있겠죠.\n하지만 율리시스 교수님도 지금까지 정말 많은 것들을 희생해 오셨어요.",
  ui_story_1017_10170401_34_dialog_content = "오로리안을 무기로 전장에 내보내는 건 희생이 아니란 말인가요?\n율리시스 교수의 실험은 일루미나의 근본을 흔들고 있어요!",
  ui_story_1017_10170401_35_dialog_content = "오로리안들의 피와 살로 세워진 연방이 지금 위기에 처해 있는데,\n당신들은 아직도 율리시스를 감싸고 도는 건가요?!",
  ui_story_1017_10170401_36_dialog_content = "피와 살... 설마 피와 살이 암귀를 막을 수 있다고 생각하시는 건 아니겠죠?",
  ui_story_1017_10170401_37_dialog_content = "물론 피와 살만으로는 암귀를 막을 수 없어요.",
  ui_story_1017_10170401_38_dialog_content = "하지만 그동안 수없이 많은 암귀와의 싸움 속에서, 지금처럼 오로리안의 존엄성을 버려가면서까지\n우리의 힘을 증명하려 한 적은 결코 없었어요.",
  ui_story_1017_10170401_39_dialog_content = "악셀리아, 병사들, 그리고 당신이 치른 희생도 일루미나에 안녕을 가져다주진 않아요...\n그저 사람들이 암귀를 더 두려워하게 만들 뿐이죠.",
  ui_story_1017_10170401_40_dialog_content = "그런 건 놈들에게 굴복하는 거나 마찬가지라고요!",
  ui_story_1017_10170401_41_dialog_content = "전 전쟁이 싫어요. 하지만 굴복하지도 않아요.\n일루미나가 절 필요로 한다면, 전 일루미나를 위해 싸울 거예요.",
  ui_story_1017_10170401_42_dialog_content = "지금 한 말을 기억해 두세요, 잉겔 중령.\n그리고 전장으로 나아가는 저 병사들을 똑똑히 보세요.",
  ui_story_1017_10170401_43_dialog_content = "저들은 아마 자신이 치르게 될 희생이 무엇인지도 모르겠죠. 악셀리아도 마찬가지고요.\n하지만 당신은 알고 있어요.",
  ui_story_1017_10170401_44_dialog_content = "......",
  ui_story_1017_10170401_45_dialog_content = "「지금 대원수님께서 근위군단 앞에 서 계십니다!」",
  ui_story_1017_10170401_46_dialog_content = "일루미나의 병사들이여, 잘 들어라!",
  ui_story_1017_10170401_47_dialog_content = "나 일루미나 연방 대원수 레이스가 이 자리에서 선포한다.",
  ui_story_1017_10170401_48_dialog_content = "지금 암귀가 더스크 타운을 침공했고, 우리의 오로리안 동포들을 무참히 해치고 있다.\n이에 오늘 우리는 더스크 타운으로 출정해 모든 암귀를 물리칠 것이다!",
  ui_story_1017_10170401_49_dialog_content = "이 자리에 집결한 근위군단 전군은 일루미나 최강의 전력이다.\n제군들은 선봉으로서 나와 함께 영광스럽게 출전할 것이다.",
  ui_story_1017_10170401_50_dialog_content = "우리는 무슨 일이 있어도 반드시 이 싸움에서 승리한다!\n그 모든 것은 오직, 여명의 빛을 위하여!",
  ui_story_1017_10170401_51_dialog_content = "여명의 빛을 위하여──!",
  ui_story_1017_10170401_52_dialog_content = "제3군단장 히이로, 명령을 하달하겠다!",
  ui_story_1017_10170401_53_dialog_content = "예!",
  ui_story_1017_10170401_54_dialog_content = "대열 정비 및 업무 분장 후 출전 명령을 대기하도록.",
  ui_story_1017_10170401_55_dialog_content = "예!",
  ui_story_1017_10170401_56_dialog_content = "근위군단, 출격하라!",
  ui_story_1017_10170401_57_dialog_content = "예!",
  ui_story_1017_10170401_58_dialog_content = "우리가... 대기 병력이라고?",
  ui_story_1017_10170401_59_dialog_content = "엄청난 기세다...!",
  ui_story_1017_10170401_60_dialog_content = "레이스, 방금 휘장을 만졌죠?",
  ui_story_1017_10170401_61_dialog_content = "네, 봤습니다.",
  ui_story_1017_10170401_62_dialog_content = "아무튼 드디어 해냈네요.",
  ui_story_1017_10170401_63_dialog_content = "그러게요. 다만... 레이스가 지금 무슨 생각을 하고 있을지 모르겠네요...",
  ui_story_1017_10170401_64_dialog_content = "......",
  ui_story_1017_10170401_65_dialog_content = "(대원수의 「전군 호령」이란 이런 느낌이었구나.)",
  ui_story_1017_10170401_66_dialog_content = "(라인하르트, 그동안 넌 이 모든 게 이미 익숙해졌겠지만...)",
  ui_story_1017_10170401_67_dialog_content = "(네가 처음 대원수 자리에 섰을 땐 무슨 생각을 했을까.)",
  ui_story_1017_10170401_68_dialog_content = "(자신이 대원수가 되는 게 당연하다고 생각했을까. 아니면 보통 사람들을 뛰어넘는\n네 노력과 희생이 드디어 보답을 받았다고 여겼을까...)",
  ui_story_1017_10170401_69_dialog_content = "넌 강하구나. 우리 친구 하자.",
  ui_story_1017_10170401_70_dialog_content = "친구? 필요 없어. 지금 나한테 필요한 건 단련뿐이야.",
  ui_story_1017_10170401_71_dialog_content = "(난 항상 자신에게 말해왔어. 우정이란 날 약하게 만들 뿐이고,\n너와는 친구가 될 수 없다고 말이야.)",
  ui_story_1017_10170401_72_dialog_content = "(그래서 나는 대원수가 되는 것을 목표로 끝없이 자신을 단련해 왔어.)",
  ui_story_1017_10170401_73_dialog_content = "(하지만 내가 이미 충분히 강해졌다고 생각했을 때...)",
  ui_story_1017_10170401_74_dialog_content = "이것들은 과학기술부에서 개발한 최신형 에너지 유도장치다.\n라인하르트가 나와서 제군들에게 시범을 보여주도록.",
  ui_story_1017_10170401_75_dialog_content = "왜 라인하르트죠?",
  ui_story_1017_10170401_76_dialog_content = "너희 중에서 이 장치를 완벽하게 제어할 수 있는 건 라인하르트뿐이다.",
  ui_story_1017_10170401_77_dialog_content = "......",
  ui_story_1017_10170401_78_dialog_content = "(겨우 에너지 유도장치일 뿐이잖아? 상관없어, 열 배의 시간을 들여서 나도 완벽하게 제어해 주겠어.)",
  ui_story_1017_10170401_79_dialog_content = "(정식 작전 땐 우리 사이에 더는 차이가 없게 될 거야.)",
  ui_story_1017_10170401_80_dialog_content = "라인하르트와 레이스 조는 라인하르트가 작전 명령을 하달하도록.",
  ui_story_1017_10170401_81_dialog_content = "교관님! 왜 전 안 되는 거죠?!",
  ui_story_1017_10170401_82_dialog_content = "작전 명령의 하달은 대원들의 생명이 달린 문제다.",
  ui_story_1017_10170401_83_dialog_content = "너도 실전 속에서 부대를 이끄는 법을 많이 익혀 두는 게 좋을 거다.",
  ui_story_1017_10170401_84_dialog_content = "......",
  ui_story_1017_10170401_85_dialog_content = "(부대를 이끌고 대원들의 안전을 지키면서... 난 끝없이 자신을 발전시켰고,\n점차 나를 따르는 부하들이 생겼어.)",
  ui_story_1017_10170401_86_dialog_content = "제1군단 레이스, 대위 승진을 축하한다. 앞으로의 임무에서도 많은 활약을 기대하겠다.",
  ui_story_1017_10170401_87_dialog_content = "(모든 건 순조로웠어. 그렇게 난 자신의 힘을 증명할 기회를 기다려 왔어.)",
  ui_story_1017_10170401_88_dialog_content = "(하지만 암귀가 19호 지하성을 침공했을 때...)",
  ui_story_1017_10170401_89_dialog_content = "(처음 지원 요청 통신을 받은 건 나였는데, 넌 그 임무를 빼앗아서 전공을 세웠지...)",
  ui_story_1017_10170401_90_dialog_content = "일루미나를 위한 공헌을 기리는 이 훈장을... 라인하르트에게 수여한다!",
  ui_story_1017_10170401_91_dialog_content = "(넌 언제나 앞서갔어. 게다가 네가 우수한 탓에 간부 심사에 불필요한 지표도 많이 추가됐지.)",
  ui_story_1017_10170401_92_dialog_content = "(내 꿈은 전장 밖에서 활약하는 게 아냐. 전사라면 전사다운 방법으로 승부를 가려야지!)",
  ui_story_1017_10170401_93_dialog_content = "(그렇게 난 더는 기다릴 이유가 없었고, 네게 도전하기로 결정했어!)",
  ui_story_1017_10170401_94_dialog_content = "지금은 감정적으로 움직일 때가 아냐. 주변엔 아직도 암귀들이 많이 있어!",
  ui_story_1017_10170401_95_dialog_content = "쓸데없는 소리 하지 말고 무기를 들어. 날 죽이든지, 아니면 내가 너보다 더 강하다는 걸 인정해.",
  ui_story_1017_10170401_96_dialog_content = "유치해.",
  ui_story_1017_10170401_97_dialog_content = "비켜──!",
  ui_story_1017_10170401_98_dialog_content = "대신 암귀랑 싸워달라고 한 적 없어! 그 창으로 날 겨누란 말이야!",
  ui_story_1017_10170401_99_dialog_content = "다시 한번 말하지만 지금은 그럴 때가 아냐. 전투에 집중해!",
  ui_story_1017_10170401_100_dialog_content = "방해하지 마──!",
  ui_story_1017_10170401_101_dialog_content = "암귀를 다 없애고 나면, 내 도전을 받아들일 거야?",
  ui_story_1017_10170401_102_dialog_content = "그때까지 네가 살아있다면, 좋을 대로 해.",
  ui_story_1017_10170401_103_dialog_content = "좋아!",
  ui_story_1017_10170401_104_dialog_content = "암귀 따위, 날 방해하지 마!",
  ui_story_1017_10170502_1_dialog_content = "(이 익숙한 느낌... 매번 네게 도전하면 항상 이런 식으로 끝났었지.)",
  ui_story_1017_10170502_2_dialog_content = "(훈련에서도, 실전에서도, 넌 한 번도 진 적이 없었어. 대체 어떻게 그럴 수 있는 거야?)",
  ui_story_1017_10170502_3_dialog_content = "(그런 의문을 품은 채 나는 대원수 최종 선발에서 너와 대결하게 됐었지...)",
  ui_story_1017_10170502_4_dialog_content = "승자는── 라인하르트!",
  ui_story_1017_10170502_5_dialog_content = "이것으로 일루미나 연방의 대원수가 정해졌다! 모두 함께 축하하자!",
  ui_story_1017_10170502_6_dialog_content = "라인하르트 대원수님!",
  ui_story_1017_10170502_7_dialog_content = "비록 패했지만, 레이스도 상당한 실력을 지닌 일루미나의 군인이다.",
  ui_story_1017_10170502_8_dialog_content = "(인정 못 해. 난 아직 지지 않았다고!)",
  ui_story_1017_10170502_9_dialog_content = "(네게 다시 도전하겠어!)",
  ui_story_1017_10170502_10_dialog_content = "(10번 해서 안 되면 100번, 100번이라도 안 되면 1000번 도전할 테니까!)",
  ui_story_1017_10170502_11_dialog_content = "돌아가자. 방송에서 오늘 날씨가 안 좋다고 했어. 아마 지상에는 지금 비가 내리고 있겠지.",
  ui_story_1017_10170502_12_dialog_content = "패자에게 연민을 느낄 필요는 없어.",
  ui_story_1017_10170502_13_dialog_content = "나에게 있어 넌 패자가 아냐. 넌 내 친구야.",
  ui_story_1017_10170502_14_dialog_content = "...친구?",
  ui_story_1017_10170502_15_dialog_content = "그래. 서로 상대의 앞길을 막고, 서로 그걸 넘어서는 친구지.",
  ui_story_1017_10170502_16_dialog_content = "누가 네 친구래? 우린 한 번도 친구였던 적 없어.",
  ui_story_1017_10170502_17_dialog_content = "(내게 친구란 없어. 그저 너라는 유일한 목표만 있을 뿐이야.)",
  ui_story_1017_10170502_18_dialog_content = "우리의 이 결투는 오직 일루미나의 미래를 위한 것일 뿐,\n쥐어진 주먹은 공통의 적을 향해야만 해.",
  ui_story_1017_10170502_19_dialog_content = "네 미래는 네 손안에서 솟아날 거야. 그렇게 주먹만 쥐고 있으면 아무것도 남지 않아.",
  ui_story_1017_10170502_20_dialog_content = "넌 네 대원수 완장이나 쥐고 가서 축하나 받아. 난 앞으로도 계속해서 네게 도전할 테니까.",
  ui_story_1017_10170502_21_dialog_content = "대원수가 됐다고 해서 봐주진 않을 테니까.",
  ui_story_1017_10170502_22_dialog_content = "날 이기기만 하면 대원수 자리는 네 거야.",
  ui_story_1017_10170502_23_dialog_content = "앞으로 남은 인생에서도 날 계속 이길 거라고 자신할 수 있어?",
  ui_story_1017_10170502_24_dialog_content = "......",
  ui_story_1017_10170502_25_dialog_content = "자신할 수 있냐고.",
  ui_story_1017_10170502_26_dialog_content = "물론이지.",
  ui_story_1017_10170502_27_dialog_content = "그럼 방심하지 마. 앞으로도 난 끝없이 네게 도전할 거야.",
  ui_story_1017_10170502_28_dialog_content = "대원수 자리도, 그 외의 것들도 뭐든 좋아. 네가 가진 건 모두 빼앗을 테니까!",
  ui_story_1017_10170502_29_dialog_content = "(하지만 이렇게 내가 가장 원하지 않았던 방식으로 네 자리를 대체하게 될 줄은 몰랐어.)",
  ui_story_1017_10170502_30_dialog_content = "(훗... 환호와 비방의 소리, 모두 잘 들었어. 하지만 난 너처럼 조종당하지 않을 거야.)",
  ui_story_1017_10170502_31_dialog_content = "(날 가지고 실험이니 뭐니 하려는 녀석들이 앞으로 보게 될 건...)",
  ui_story_1017_10170502_32_dialog_content = "(길들여지지 않는 「대원수」일 테니까.)",
  ui_story_1017_10170601_1_dialog_content = "<color=#e8d9bb>더스크 타운, 많은 주민들이 의료원을 향해 이동하고 있다...</color>",
  ui_story_1017_10170601_2_dialog_content = "조금만 더 버텨... 이제 곧 <color=#FFB400>의료원</color>에 도착할 거야.",
  ui_story_1017_10170601_3_dialog_content = "도저히 못 걷겠어...",
  ui_story_1017_10170601_4_dialog_content = "내가 업어줄게. 지금 주변 전장은 온통 암귀 천지야. 언제 여기까지 올지 몰라...",
  ui_story_1017_10170601_5_dialog_content = "악! 아, 아파...",
  ui_story_1017_10170601_6_dialog_content = "들것에 눕히세요.",
  ui_story_1017_10170601_7_dialog_content = "음? 당신들은...",
  ui_story_1017_10170601_8_dialog_content = "다리 쪽 안 스치게 조심하세요.",
  ui_story_1017_10170601_9_dialog_content = "알겠어, 조셀린 언니.",
  ui_story_1017_10170601_10_dialog_content = "당신들이 의료원 사람들인가요?",
  ui_story_1017_10170601_11_dialog_content = "네, 안녕하세요. 전 조셀린이라고 해요. 이쪽은 의료원의 간호사예요.",
  ui_story_1017_10170601_12_dialog_content = "안녕, 난 치치라고 해!",
  ui_story_1017_10170601_13_dialog_content = "치치는 어린데 대단하구나.",
  ui_story_1017_10170601_14_dialog_content = "헤헷!",
  ui_story_1017_10170601_15_dialog_content = "조셀린...?",
  ui_story_1017_10170601_16_dialog_content = "앗! 그럼 설마 당신이... 백야 교구의 「성녀」님이신가요?!",
  ui_story_1017_10170601_17_dialog_content = "「성녀」님?!",
  ui_story_1017_10170601_18_dialog_content = "아, 아니에요... 전 「성녀」가 아니라 평범한 백성일 뿐이에요.",
  ui_story_1017_10170601_19_dialog_content = "언니, 「성녀」가 뭐야?",
  ui_story_1017_10170601_20_dialog_content = "「성녀」는 빛의 신의 백성들을 지키려고 세상에 내려오신 여신님이야!",
  ui_story_1017_10170601_21_dialog_content = "「성녀」님이 계신다면 암귀도 우리 터전에 감히 발을 들이지 못해.",
  ui_story_1017_10170601_22_dialog_content = "우와! 진짜야? 「성녀」 언니?",
  ui_story_1017_10170601_23_dialog_content = "전 진짜로 「성녀」가 아니에요. 조셀린이라고 불러 주시면 돼요.",
  ui_story_1017_10170601_24_dialog_content = "전 그저 「빛의 신」께서 어둠을 가르시고, 빛의 백성은 영원히 빛을 이어갈 거라고 믿을 뿐이에요.",
  ui_story_1017_10170601_25_dialog_content = "그날이 올 때까지, 전 제가 할 수 있는 모든 노력을 다할 거예요.",
  ui_story_1017_10170601_26_dialog_content = "언니, 난 「빛의 신」이나 그런 건... 어려워서 잘 모르겠어.",
  ui_story_1017_10170601_27_dialog_content = "빛은 반드시 어둠을 이기고, 우린 모두 「빛의 신」의 품으로 돌아갈 수 있다는 뜻이에요.",
  ui_story_1017_10170601_28_dialog_content = "조셀린──!",
  ui_story_1017_10170601_29_dialog_content = "의료원 쪽은 괜찮나?",
  ui_story_1017_10170601_30_dialog_content = "이렇게 많은 사람이 모인 적은 없었지만... 아직 여유는 있을 거예요.",
  ui_story_1017_10170601_31_dialog_content = "전선의 상황은 어떤가요?",
  ui_story_1017_10170601_32_dialog_content = "하아... 암귀의 공격도 갑작스러웠고, 공세가 무척 거센 탓에 병사들의 피해가 심해!",
  ui_story_1017_10170601_33_dialog_content = "지금 더스크 타운 주변의 방어선은 모두 붕괴한 상황이고, 상당수 주민들도 습격을 당했어...",
  ui_story_1017_10170601_34_dialog_content = "말도 안 돼!",
  ui_story_1017_10170601_35_dialog_content = "끝이야... 모든 게 끝장이라고...",
  ui_story_1017_10170601_36_dialog_content = "레오 단장님 쪽은 아직 소식이 없나요?",
  ui_story_1017_10170601_37_dialog_content = "이미 한참 전에 서신을 보냈는데, 아직도 안 오셨어!",
  ui_story_1017_10170601_38_dialog_content = "그래서 지금 단장님의 말과 장비를 가지고 더스크 타운 <color=#FFB400>관문</color>까지 마중 나가는 중이었어.",
  ui_story_1017_10170601_39_dialog_content = "단장님이 안 계신 동안 이 녀석은 자기가 대신 지휘라도 할 생각이었는지,\n전장으로 뛰쳐나가서 하마터면 암귀한테 당할 뻔했지 뭐야.",
  ui_story_1017_10170601_40_dialog_content = "「강철가시 기사단」은 지금도 싸우는 중이야... 먼저 가 봐야겠어.\n그럼 이쪽 일은 당신한테 부탁할게.",
  ui_story_1017_10170601_41_dialog_content = "만물은 백야 아래에──",
  ui_story_1017_10170601_42_dialog_content = "치치, 이분과 함께 다친 아가씨를 의료원까지 데려다주세요.",
  ui_story_1017_10170601_43_dialog_content = "그리고 의료원에 도착하면 수간호사에게 더스크 타운 주변에\n의료진을 증원해 달라고 말해 주세요.",
  ui_story_1017_10170601_44_dialog_content = "언니는 어디 가는데?",
  ui_story_1017_10170601_45_dialog_content = "전장으로 갈 거예요.",
  ui_story_1017_10170601_46_dialog_content = "전장이라고요?! 전장은... 전사들이 가야 하는 곳이잖아요.",
  ui_story_1017_10170601_47_dialog_content = "제가 바로 그 전사예요. 이럴 때일수록 전 반드시 전장에 있어야만 해요.",
  ui_story_1017_10170601_48_dialog_content = "치치, 그럼 부탁할게요. 이따 봐요.",
  ui_story_1017_10170601_49_dialog_content = "......",
  ui_story_1017_10170601_50_dialog_content = "너... 괜찮겠어?",
  ui_story_1017_10170601_51_dialog_content = "어리다고 무시하지 마! 난 힘이 세거든!",
  ui_story_1017_10170601_52_dialog_content = "<color=#e8d9bb>조셀린은 더스크 타운 외곽의 전장으로 향했다...</color>",
  ui_story_1017_10170601_53_dialog_content = "발밑을 조심해!",
  ui_story_1017_10170601_54_dialog_content = "「힘껏 베겠어요!」",
  ui_story_1017_10170601_55_dialog_content = "이 암귀는 조금 전 공격으로 숨이 끊어졌을 텐데요.",
  ui_story_1017_10170601_56_dialog_content = "이미 쓰러진 적도 주의해. 가끔은 그런 놈들의 공격이 더 치명적이니까.",
  ui_story_1017_10170601_57_dialog_content = "알겠어요. 고마워요!",
  ui_story_1017_10170601_58_dialog_content = "전부 단장님한테 배운 거야. 문제는 단장님이 안 계시니까 역시 뭔가 부족한 것 같단 말이지.",
  ui_story_1017_10170601_59_dialog_content = "다들 말은 안 꺼내고 있지만 속으로는 불안해하고 있어...",
  ui_story_1017_10170601_60_dialog_content = "느껴져요... 이 정도 수의 암귀는 저도 처음 봐요.",
  ui_story_1017_10170601_61_dialog_content = "놈들이 노리는 게 뭐죠?",
  ui_story_1017_10170601_62_dialog_content = "아직 모르겠어. 움직임도 무척 혼란스럽고. 방어선은 계속해서 밀리고 있어...",
  ui_story_1017_10170601_63_dialog_content = "이대로 계속 물러선다면, 더스크 타운을 지킬 수가 없다고...",
  ui_story_1017_10170601_64_dialog_content = "뒤쪽 조심해요!",
  ui_story_1017_10170601_65_dialog_content = "제길!",
  ui_story_1017_10170601_66_dialog_content = "「강철가시 기사단」의 전사가 그런 약한 말을 하면 어떡해요?",
  ui_story_1017_10170601_67_dialog_content = "레오 단장님이 없어도 우린 전력을 다해 암귀를 없애야죠!",
  ui_story_1017_10170601_68_dialog_content = "우린 오랫동안 변방을 지켜 오면서 깨달았어. 더스크 타운은 신에게 버려진 땅이야.\n구원 같은 건 받을 수 없고, 암귀한테 잡아먹힐 뿐이지.",
  ui_story_1017_10170601_69_dialog_content = "우리가 여길 지키는 건 그저 우리가 여기서 태어났고, 다른 갈 곳이 없어서일 뿐이야.",
  ui_story_1017_10170601_70_dialog_content = "만약 그곳으로... 돌아갈 수 있다면, 누가 이런 데서 내일조차 알 수 없는 삶을 살고 싶겠어?",
  ui_story_1017_10170601_71_dialog_content = "......",
  ui_story_1017_10170601_72_dialog_content = "뭐, 그렇다고... 겁먹고 있다는 뜻은 아니야...\n이름 없는 전사라도, 자기가 무엇을 위해 싸우는지 정도는 알아야지...",
  ui_story_1017_10170601_73_dialog_content = "이런 말 했다고 실망한 건 아니지?",
  ui_story_1017_10170601_74_dialog_content = "이곳을 지키기 위해서라면 그걸로 충분하지 않나요?",
  ui_story_1017_10170601_75_dialog_content = "더스크 타운 밖을 본 적이 없는 아이들은 더스크 타운이 곧 세계라고 생각해요.",
  ui_story_1017_10170601_76_dialog_content = "이 세상의 진실한 모습을 보기 전까진 우리도 그렇게 생각했었고 말이죠.",
  ui_story_1017_10170601_77_dialog_content = "자신을 희생했던 지난날의 전사들도 바로 이 작은 세계를 지키기 위해 싸웠던 거잖아요?",
  ui_story_1017_10170601_78_dialog_content = "......",
  ui_story_1017_10170601_79_dialog_content = "전사가 꼭 위대한 전쟁에서 자신을 증명할 필요는 없어요.",
  ui_story_1017_10170601_80_dialog_content = "작은 땅을 지켜내는 것만으로도 그 공적은 위대한 거예요.",
  ui_story_1017_10170601_81_dialog_content = "그럴지도 모르지... 그 말도 물론 일리는 있어. 하지만 그동안 우린 깨달았어.\n우린 모두 단장님을 위해서 싸워왔던 거야...",
  ui_story_1017_10170601_82_dialog_content = "레오 단장님도 줄곧 당신들을 위해 싸워왔잖아요?",
  ui_story_1017_10170601_83_dialog_content = "맞아, 그리고 우리 때문에 단장은 많은 걸 잃었지.",
  ui_story_1017_10170601_84_dialog_content = "그럼 더 많은 걸 잃지 않도록, 함께 싸워온 이 땅을 우리 같이 지켜요!",
  ui_story_1017_10170601_85_dialog_content = "이 땅에서 태어났든, 무슨 이유로 이곳에 왔든, 모두 서로를 위해 싸우는 거에요!",
  ui_story_1017_10170601_86_dialog_content = "그래, 당신 말이 맞아! 지금 바로 모두에게 전할게!",
  ui_story_1017_10170601_87_dialog_content = "「강철가시 기사단」 형제들이여, 잘 들어라! 암귀 놈들이 한 발짝이라도 더 전진하게 둔다면,\n이는 떠나간 동료들을 치욕스럽게 만드는 일이다!",
  ui_story_1017_10170601_88_dialog_content = "「강철가시 기사단」에는 날카로운 가시만 있는 것이 아니다!\n결코 부러지지 않는 강철의 뼈도 있다!",
  ui_story_1017_10170601_89_dialog_content = "설령 우리의 주검으로 벽을 쌓는 한이 있더라도! 암귀가 쳐들어오게 둬서는 안 된다!",
  ui_story_1017_10170601_90_dialog_content = "자, 가자!",
  ui_story_1017_10170601_91_dialog_content = "저도 같이 가요!",
  ui_story_1017_10170601_92_dialog_content = "목숨을 걸고 더스크 타운을 지키자!",
  ui_story_1017_10170601_93_dialog_content = "목숨을 걸고 더스크 타운을 지키자!",
  ui_story_1017_10170602_1_dialog_content = "스카이워커, 더스크 타운까지 얼마나 남았어?",
  ui_story_1017_10170602_2_dialog_content = "PlayerName, 당신은 지난 1분 동안 같은 질문을 10번 했습니다.",
  ui_story_1017_10170602_3_dialog_content = "아... 그냥 좀 걱정돼서 그래...",
  ui_story_1017_10170602_4_dialog_content = "그랬군요. 전 의식 연결에 지연이 발생한 것이 아닌지 확인하고 있었습니다.",
  ui_story_1017_10170602_5_dialog_content = "연결에 지연은 없는데... 너 비행 속도가 너무 느린 것 같아서 말이지...",
  ui_story_1017_10170602_6_dialog_content = "비행 속도 확인 결과, 출발부터 지금까지 <color=#FFB400>최고 속도</color>를 유지하고 있습니다.",
  ui_story_1017_10170602_7_dialog_content = "......",
  ui_story_1017_10170602_8_dialog_content = "낙담하고 있는 듯하군요. 이유를 말씀해 주시겠습니까?",
  ui_story_1017_10170602_9_dialog_content = "네가 의식을 잃었던 것도 벌써 엄청 오래전 일이 돼버렸어.",
  ui_story_1017_10170602_10_dialog_content = "근데도 난 네가 어떤지 물어볼 겨를도 없이 우릴 더스크 타운으로 태워달라고 하고 있잖아...",
  ui_story_1017_10170602_11_dialog_content = "당신에게는 긴 시간이었을지도 모르지만, 제 설정 속에서 우리는 한 번도 떨어진 적이 없었습니다.",
  ui_story_1017_10170602_12_dialog_content = "음... 생각해 보니 그것도 그렇네.",
  ui_story_1017_10170602_13_dialog_content = "당신이 동료들과 함께 많은 여정에 오르면서, 저도 그토록 많은 풍경들을 볼 수 있었습니다.",
  ui_story_1017_10170602_14_dialog_content = "마침 <color=#FFB400>새로운 풍경</color>이 보이는군요. 이 앞이 바로 우리의 목적지입니다.",
  ui_story_1017_10170602_15_dialog_content = "도착한 거야?",
  ui_story_1017_10170602_16_dialog_content = "이미 매우 근접했습니다. 착륙 지점을 확인해 주십시오.",
  ui_story_1017_10170602_17_dialog_content = "응, 더스크 타운의 일이 끝나고 나면 지금까지 있었던 일들을 전부 말해줄게.",
  ui_story_1017_10170602_18_dialog_content = "우선 감속해서 저공비행하고, <color=#FFB400>해치를 열어 줘</color>.",
  ui_story_1017_10170602_19_dialog_content = "감속하고 있습니다. <color=#FFB400>3호 해치</color>를 개방합니다...",
  ui_story_1017_10170602_20_dialog_content = "레오 씨──",
  ui_story_1017_10170602_21_dialog_content = "고마워, PlayerName. 이번 일을 마치고 나면 제대로 보답할게.",
  ui_story_1017_10170602_22_dialog_content = "에이, 그럴 거 없어... 그것보다 스카이워커가 하강하기 시작했는데, 어디 착륙하면 돼?",
  ui_story_1017_10170602_23_dialog_content = "관문 쪽에 있는 저 병사 보여?",
  ui_story_1017_10170602_24_dialog_content = "사람이 있는 것 같긴 하네... 말 세 마리처럼 보이기도 하고...",
  ui_story_1017_10170602_25_dialog_content = "내 부하야. 내 말을 데리고 와서 날 기다리고 있는 거야.",
  ui_story_1017_10170602_26_option_content = "눈이 그렇게 좋다고?!",
  ui_story_1017_10170602_27_dialog_content = "이렇게 멀리서 저게 사람이랑 말인 게 보인단 말이야?",
  ui_story_1017_10170602_28_dialog_content = "당연하지. 더스크 타운은 훈련에 가장 좋은 곳이니까.",
  ui_story_1017_10170602_29_option_content = "정말 레오 씨답네.",
  ui_story_1017_10170602_30_dialog_content = "역시 단장하고 부하들하고 마음이 통하는구나.",
  ui_story_1017_10170602_31_dialog_content = "오랜 세월 동안 만든 팀워크니까.",
  ui_story_1017_10170602_32_dialog_content = "기회가 된다면 너한테도 행군하고 싸우는 법을 가르쳐 줄게.",
  ui_story_1017_10170602_33_dialog_content = "착륙 고도에 도달했습니다. PlayerName, 착륙 지점을 확정해 주십시오.",
  ui_story_1017_10170602_34_dialog_content = "레오 씨, 그럼 관문 앞에 착륙하면 될까?",
  ui_story_1017_10170602_35_dialog_content = "음... 이 정도면 됐어. 좋아, 이쯤이야. 그럼──",
  ui_story_1017_10170602_36_dialog_content = "PlayerName, 요제프 좀 부탁할게.",
  ui_story_1017_10170602_37_dialog_content = "신부, 밑에서 보자고.",
  ui_story_1017_10170602_38_dialog_content = "네, 이따 봅시다. 기사단장님.",
  ui_story_1017_10170602_39_dialog_content = "?!",
  ui_story_1017_10170602_40_dialog_content = "어, 뛰어내렸어?!",
  ui_story_1017_10170602_41_dialog_content = "레오 씨! <size=45>그럼──</size> 난── <size=30>어떡해──!</size>",
  ui_story_1017_10170602_42_dialog_content = "<size=45>돌──</size>아──<size=30>가──</size>",
  ui_story_1017_10170602_43_dialog_content = "......",
  ui_story_1017_10170602_44_dialog_content = "단장님! 누가 저 큰 물체에서 뛰어내리나 했더니... 정말 단장님이었군요!",
  ui_story_1017_10170602_45_dialog_content = "저게 바로 그 전설의... 콜로서스입니까?!",
  ui_story_1017_10170602_46_dialog_content = "맞아, 오래 기다렸지?",
  ui_story_1017_10170602_47_dialog_content = "이대로 전장으로 향하겠다. 얘기하면서 가자고. 더스크 타운의 상황은?",
  ui_story_1017_10170602_48_dialog_content = "<color=#FFB400>영원한 밤의 땅</color> 방향에서 암귀가 침입헀고, 주변의 보루는 이미 격파당했습니다.\n형제들은 아직도 저항하고 있습니다.",
  ui_story_1017_10170602_49_dialog_content = "암귀는 누가 조종하고 있지?",
  ui_story_1017_10170602_50_dialog_content = "우두머리급 암귀는 없습니다. 다만 수가 매우 많고, 움직임도 무질서합니다!",
  ui_story_1017_10170602_51_dialog_content = "사상자 현황은?",
  ui_story_1017_10170602_52_dialog_content = "다수의 주변 지역 주민이 습격을 받았고, 현재 이미 안전지대로 이주 준비를 마쳤습니다.\n병사는 수백 명이 부상을 입었고...",
  ui_story_1017_10170602_53_dialog_content = "<color=#FFB400>75명</color>의 형제들이 목숨을 잃었습니다...",
  ui_story_1017_10170602_54_dialog_content = "<color=#FFB400>75명</color>?! 그럼 넌 여기서 뭘 하고 있는 거지?",
  ui_story_1017_10170602_55_dialog_content = "단장님이 안 계시는 동안... 단장님 말까지 고삐를 뿌리치고 전장에 나가서\n암귀를 들이받았습니다...",
  ui_story_1017_10170602_56_dialog_content = "제가 어떻게든 이 녀석을 붙잡아 오긴 했지만... 저흰 정말 어떻게 해야 할지 막막했습니다!",
  ui_story_1017_10170602_57_dialog_content = "흥! 더스크 타운을 집어삼키겠다? 그렇겐 안 되지.",
  ui_story_1017_10170602_58_dialog_content = "근처 마을에는 연락했나?",
  ui_story_1017_10170602_59_dialog_content = "싸울 수 있는 사람들은 모두 지원을 왔습니다만...\n자기들 한 몸 지키는 것조차 어려운 마을도 있습니다.",
  ui_story_1017_10170602_60_dialog_content = "전투뿐만이 아닙니다... 의료자원 소모도 굉장히 심합니다...",
  ui_story_1017_10170602_61_dialog_content = "백야 요새에서는 의료원에 도움을 주지 않는 건가?",
  ui_story_1017_10170602_62_dialog_content = "그렇습니다. 의료원에는 마을의 의사와 간호사들뿐이고,\n심지어 이제 막 철든 어린애까지 와서 일을 돕고 있습니다.",
  ui_story_1017_10170602_63_dialog_content = "그 어떤 일이든 더스크 타운에서는 하나같이 어려운 게 돼버린단 말이지.",
  ui_story_1017_10170602_64_dialog_content = "좋은 소식이라면 내가 돌아왔다는 거다. 더는 형제들이 헛되이 희생되게 만들지 않을 거다.",
  ui_story_1017_10170602_65_dialog_content = "나쁜 소식은 우리가 의지할 수 있는 게 여전히 우리 자신뿐이라는 거겠지.",
  ui_story_1017_10170602_66_dialog_content = "그렇습니다... 그런데 단장님. 자오 님은 왜 같이 안 오신 겁니까?",
  ui_story_1017_10170602_67_dialog_content = "그 녀석은 아직 할 일이 있거든.\n시간이 좀 걸리겠지만, 분명히 우리에게 역전의 기회를 가져다줄 거다.",
  ui_story_1017_10170602_68_dialog_content = "이 더스크 타운의 위기에 정말 역전의 기회가 올 수 있을까요?",
  ui_story_1017_10170602_69_dialog_content = "...위를 봐라!",
  ui_story_1017_10170602_70_dialog_content = "받아줘!",
  ui_story_1017_10170602_71_dialog_content = "<color=#e8d9bb>병사는 하늘에서 떨어진 조종사를 받아냈고, 두 사람은 하마터면 말에서 떨어질 뻔했다...</color>",
  ui_story_1017_10170602_72_dialog_content = "다, 당신... 그 아이테르군요. 깔려 죽을 뻔했잖습니까!",
  ui_story_1017_10170602_73_dialog_content = "콜로서스까지 떨어지는 줄 알고 얼마나 놀랐는지 압니까?!",
  ui_story_1017_10170602_74_dialog_content = "미안해요...",
  ui_story_1017_10170602_75_dialog_content = "괜찮습니까?",
  ui_story_1017_10170602_76_option_content = "괜찮아요.",
  ui_story_1017_10170602_77_dialog_content = "스카이워커가 딱 좋은 고도로 날았거든요.",
  ui_story_1017_10170602_78_option_content = "여긴 어디고... 전 누구죠?",
  ui_story_1017_10170602_79_dialog_content = "낙하할 때 심장이 멈추는 줄 알았다니까요...",
  ui_story_1017_10170602_80_dialog_content = "그래도 스카이워커가 딱 좋은 고도로 날아서 다행이었어요...",
  ui_story_1017_10170602_81_dialog_content = "뭐 하러 왔어?",
  ui_story_1017_10170602_82_dialog_content = "같이 더스크 타운에 가자고 해 놓고, 중간에 돌아가라는 법이 어딨어?",
  ui_story_1017_10170602_83_dialog_content = "고마워, 하지만 네 도움은 이걸로 충분해.",
  ui_story_1017_10170602_84_dialog_content = "저 친구 좀 돌려보내 줘.",
  ui_story_1017_10170602_85_dialog_content = "단장님...",
  ui_story_1017_10170602_86_dialog_content = "더는 부하를 희생시킬 순 없어!",
  ui_story_1017_10170602_87_dialog_content = "잠깐만! 난 레오 씨 부하가 될 생각이 없는데?!",
  ui_story_1017_10170602_88_dialog_content = "나랑 스카이워커가 있으면 더스크 타운의 전황에도 유리할 거야.",
  ui_story_1017_10170602_89_dialog_content = "지금 스카이워커가 있는 고도라면 전선의 상태도 더 잘 파악할 수 있을 거고.",
  ui_story_1017_10170602_90_dialog_content = "스카이워커가 공중에서 시야를 제공하면, 내가 전장 지시를 도와줄게.",
  ui_story_1017_10170602_91_dialog_content = "공중의 시야라... 설득력이 있네.",
  ui_story_1017_10170602_92_dialog_content = "자오 님이 없는 지금, PlayerName 씨의 전장 지휘 능력은 큰 힘이 될지도 모릅니다.",
  ui_story_1017_10170602_93_dialog_content = "그건 맞아.",
  ui_story_1017_10170602_94_dialog_content = "하지만 더스크 타운에서의 싸움은 훈련 따위가 아냐. 쓰러지면 정말 목숨을 잃는다고.",
  ui_story_1017_10170602_95_dialog_content = "그래도 할 거야?",
  ui_story_1017_10170602_96_dialog_content = "당연하지!",
  ui_story_1017_10170602_97_dialog_content = "좋아, 그럼 전장을 향해 전속력으로 간다!",
  ui_story_1017_10170602_98_dialog_content = "예, 단장님!",
  ui_story_1017_10170602_99_dialog_content = "적이... 끝도 없는 것 같아...",
  ui_story_1017_10170602_100_dialog_content = "게다가 아직도 우두머리 암귀는 보이지 않아요.",
  ui_story_1017_10170602_101_dialog_content = "모두 지쳤어, 조셀린. 이대로는 결국 버틸 수 없게 될 거야.",
  ui_story_1017_10170602_102_dialog_content = "새로운 보루도 아직 완성되지 않았어요.\n여기서 포기해 버리면, 지금까지의 저항도 헛수고가 되어 버려요!",
  ui_story_1017_10170602_103_dialog_content = "하지만 사기가 너무 낮아. 단장이 돌아오더라도 만회할 수 없을지도 몰라...",
  ui_story_1017_10170602_104_dialog_content = "누구냐, 내가 돌아와도 만회할 방법이 없다는 녀석이.",
  ui_story_1017_10170602_105_dialog_content = "단장님! 돌아오셨군요!",
  ui_story_1017_10170602_106_dialog_content = "단장님이 돌아오셨다!",
  ui_story_1017_10170602_107_dialog_content = "아, 하늘에...",
  ui_story_1017_10170602_108_dialog_content = "「강철가시 기사단」의 형제들이여! 오래 기다렸다!",
  ui_story_1017_10170602_109_dialog_content = "자, 지금부터 다시 한번 기사다운 기백을 보여봐라!",
  ui_story_1017_10170602_110_dialog_content = "아이테르 PlayerName, 그리고 그의 콜로서스 스카이워커호가\n우리의 앞길을 인도할 테니 말이다!",
  ui_story_1017_10170602_111_dialog_content = "저게 그 전설의 콜로서스인가? 생각보다 더 크잖아!",
  ui_story_1017_10170602_112_dialog_content = "콜로서스가 우릴 돕는대!",
  ui_story_1017_10170602_113_dialog_content = "그래. 스카이워커호도 우리와 함께 싸울 것이다. 모두 귀를 잘 기울이고 지휘에 주의하도록!",
  ui_story_1017_10170602_114_dialog_content = "지금부터 스카이워커호가 가는 방향으로 전속력으로 전진하며, 암귀를 격퇴한다!",
  ui_story_1017_10170602_115_dialog_content = "우오오──!",
  ui_story_1017_10170602_116_dialog_content = "PlayerName, 부탁할게!",
  ui_story_1017_10170602_117_dialog_content = "응, 최선을 다할게!",
  ui_story_1017_10170701_1_dialog_content = "(백야성으로 통하는 길은 아마 이 근처일 텐데...)",
  ui_story_1017_10170701_2_dialog_content = "으앗──",
  ui_story_1017_10170701_X2_dialog_content = "물어! 물어뜯어!",
  ui_story_1017_10170701_3_dialog_content = "재미없어, 진짜 재미없어. 괴롭힐 녀석 어디 없나?!",
  ui_story_1017_10170701_4_dialog_content = "다, 당신들은... 누굽니까?",
  ui_story_1017_10170701_5_dialog_content = "맞혀 봐!",
  ui_story_1017_10170701_6_dialog_content = "놀리지 마세요. 전 급한 일이 있어서 먼저 실례하겠습니다.",
  ui_story_1017_10170701_7_dialog_content = "급한 일이 있으면 우리한테 시키면 되잖아. 제대로 할 수 있을지 보장은 못 하지만~",
  ui_story_1017_10170701_8_dialog_content = "......",
  ui_story_1017_10170701_9_dialog_content = "백야성은 어떻게 가야 하죠?",
  ui_story_1017_10170701_10_dialog_content = "저 하얗고 둥실둥실하고 차가운 곳은 아무도 안 가.",
  ui_story_1017_10170701_11_dialog_content = "백야성으로 가는 교통수단이 있던 걸로 기억하는데요...",
  ui_story_1017_10170701_12_dialog_content = "착한 강아지가 알려줄게. 백야성으로 가는 교통수단은 이미 운항이 중단됐어.",
  ui_story_1017_10170701_13_dialog_content = "...최근에 중단된 겁니까? 자세한 이유도 알고 있습니까?",
  ui_story_1017_10170701_14_dialog_content = "질문이 많네. 나쁜 짓을 할 생각인 거면 똑바로 말해. 아니면...",
  ui_story_1017_10170701_15_dialog_content = "나도 데려가 줘!",
  ui_story_1017_10170701_16_dialog_content = "(일루미나 쪽 사정은 이미 전해졌겠죠. 하지만 백야성의 대응은 제 예상보다 더 빠르군요.)",
  ui_story_1017_10170701_17_dialog_content = "(쿠리어 길드의 운송 수단을 빌릴 수 있을지 모르겠습니다만...)",
  ui_story_1017_10170701_18_dialog_content = "(무슨 구실로 빌리느냐가 문제로군요...)",
  ui_story_1017_10170701_19_dialog_content = "으앗!",
  ui_story_1017_10170701_20_dialog_content = "다, 당신들... 뭘 하려는 겁니까?!",
  ui_story_1017_10170701_21_dialog_content = "온몸에서 음모의 냄새가 나! 강아지 코는 속일 수 없어!",
  ui_story_1017_10170701_22_dialog_content = "딱 봐도 수상해! 보스한테 넘기고 밥해 먹자!",
  ui_story_1017_10170701_23_dialog_content = "그렇게 코가 좋으면서 더스크 타운의 화약 냄새는 못 느꼈습니까?\n전 지금 정말 급하단 말입니다. 빨리 풀어주세요!",
  ui_story_1017_10170701_24_dialog_content = "이 안은... 으윽... 두통이...",
  ui_story_1017_10170701_25_dialog_content = "여긴 움브라톤이야! 더스크 타운이 아니라구!",
  ui_story_1017_10170701_26_dialog_content = "쓰레기통 안에 있는 건 다 좋은 거야! 잘 익혀서 먹어야 돼!",
  ui_story_1017_10170701_27_dialog_content = "보스! 새로운 발견이야! 상으로 고기 줘!",
  ui_story_1017_10170701_28_dialog_content = "내가 쓰레기를 주워 오지 말라고 분명히 말했을 텐데.",
  ui_story_1017_10170701_29_dialog_content = "쓰레기 아니야! 나쁜 놈이야! 보스, 봐──",
  ui_story_1017_10170701_30_dialog_content = "수상하고, 허둥지둥했어.",
  ui_story_1017_10170701_31_dialog_content = "그리고 우릴 보고 도망쳤어!",
  ui_story_1017_10170701_32_dialog_content = "......",
  ui_story_1017_10170701_33_dialog_content = "이런! 맛이 갔잖아!",
  ui_story_1017_10170701_34_dialog_content = "그 말쑥한 복장, 일루미나 사람이로군... 그 사람이 여기서 뭘 하고 있었지?",
  ui_story_1017_10170701_35_dialog_content = "뭐라더라... 백야성을 점령하고, 쿠리어 길드를 없애버리겠다고 했나...",
  ui_story_1017_10170701_36_dialog_content = "맞아! 그리고 움브라톤을 더스크로 만들어 버리겠대!",
  ui_story_1017_10170701_37_dialog_content = "더스크 타운이랬거든!",
  ui_story_1017_10170701_38_dialog_content = "더스크 타운?",
  ui_story_1017_10170701_39_dialog_content = "맞아, 더스크 타운! 이 녀석 몸에서 화약 냄새가 진동해!",
  ui_story_1017_10170701_40_dialog_content = "가서 <color=#FFB400>클레이튼</color>을 찾아오고, 너희는 가서 밥을 먹어라.",
  ui_story_1017_10170701_41_dialog_content = "알았어~ 보스! 작업 끝! 밥 먹자!",
  ui_story_1017_10170701_42_dialog_content = "성주님, 대체 언제까지 생각하고 계실 겁니까?",
  ui_story_1017_10170701_43_dialog_content = "제가 가져온 건 모두 백야 요새에서 보낸 서한들입니다.",
  ui_story_1017_10170701_44_dialog_content = "계속 출병을 주저했다가는 올해 <color=#FFB400>리치라이트</color> 채굴량이 40%는 감산될 것입니다.",
  ui_story_1017_10170701_45_dialog_content = "채굴량 감소로 야기되는 원료 수요의 급등, 나아가 공급 부족은 백야성의 대외 무역액에\n영향을 미칠 수 있습니다...",
  ui_story_1017_10170701_46_dialog_content = "게다가 그로 인해 발생하는 손실은 말로 다 할 수가 없을 거란 말입니다!",
  ui_story_1017_10170701_47_dialog_content = "더스크 타운의 안부가 언제부터 백야성의 경제 상황에 영향을 주게 된 거지?",
  ui_story_1017_10170701_48_dialog_content = "자네가 걱정하는 건 지난 몇 년간 더스크 타운에서 쌓은 재물 아닌가?",
  ui_story_1017_10170701_49_dialog_content = "터무니없는 말씀입니다! 저희 <color=#FFB400>디트리히</color> 가문은 비록 역사가 깊은 귀족은 아니나,\n줄곧 자원을 채굴해 백야성에 공급해 왔습니다...",
  ui_story_1017_10170701_50_dialog_content = "어려운 환경 속에서도 유배된 수많은 기사들에게 거처를 제공했고 말입니다...",
  ui_story_1017_10170701_51_dialog_content = "그 공적으로 말하자면, <color=#FFB400>디트리히</color> 가문도 오래전에 업타운에 장원을 가지고 있었어야 마땅합니다.",
  ui_story_1017_10170701_52_dialog_content = "하지만 <color=#FFB400>트로이</color> 가문을 보십시오. 성주님 곁에서 호사만 누리고,\n암귀에 대항하는 능력은 진작에 퇴화해 버리지 않았습니까?",
  ui_story_1017_10170701_53_dialog_content = "일루미나는 줄곧 전쟁을 좋아했지. 암귀의 진압 같은 일은 저들에게 맡기면 그만 아닌가.",
  ui_story_1017_10170701_54_dialog_content = "게다가 「강철가시 기사단」은 더스크 타운에서 상당한 영향력을 갖고 있다.",
  ui_story_1017_10170701_55_dialog_content = "말로는 기사를 후원하고 있다지만, 자네의 그 검이 장차 어디로 향할지\n이미 계획이 선 것은 아닌지 모르겠군.",
  ui_story_1017_10170701_56_dialog_content = "당신은 모르시겠죠. 「강철가시 기사단」은 더스크 타운의 모든 이를 지키고 있습니다.",
  ui_story_1017_10170701_57_dialog_content = "저들은 일루미나의 군인과도 친밀하고, 레오 단장은 이번에 저들과 함께\n일루미나 연방의 연합 훈련에까지 참가했습니다.",
  ui_story_1017_10170701_58_dialog_content = "내가 알기로 그자의 일족은 이미 몰락했을 텐데.\n아니면 자네는 그자가 더스크 타운에서 쌓은 명성에 위협이라도 느낀 건가?",
  ui_story_1017_10170701_59_dialog_content = "흐음... 더스크 타운 외에는 보고할 내용이 없는가.",
  ui_story_1017_10170701_60_dialog_content = "성주님, 연합 훈련 과정에서 확인한 정황을 보고드리고 싶습니다.",
  ui_story_1017_10170701_61_dialog_content = "고하라.",
  ui_story_1017_10170701_62_dialog_content = "연합 훈련에서 전 더스크 타운의 한 병사와 알게 되었습니다. 그 사람은...",
  ui_story_1017_10170701_63_dialog_content = "되었다. 또 더스크 타운이로군. 보고할 필요 없다.",
  ui_story_1017_10170701_64_dialog_content = "하지만...",
  ui_story_1017_10170701_65_dialog_content = "책상 위의 이 서한들을 보아라.",
  ui_story_1017_10170701_66_dialog_content = "더스크 타운, 백야 요새, 심지어 움브라톤에서도 보낸 것이다. 이미 충분히 보았다.",
  ui_story_1017_10170701_67_dialog_content = "그럼 왜 결정을 내리지 않으시는 겁니까?",
  ui_story_1017_10170701_68_dialog_content = "그대는 더스크 타운에 오래 있어서인지, 저들의 조급한 습성에 물들었군.",
  ui_story_1017_10170701_69_dialog_content = "......",
  ui_story_1017_10170701_70_dialog_content = "(말씀은 여유로운 듯이 하고 계시지만, 손가락은 계속 책상을 두드리고 계셔...)",
  ui_story_1017_10170701_71_dialog_content = "(더스크 타운의 일은 듣고 싶지 않으시다면... 그럼 대체 뭘 기다리고 계신 거지?)",
  ui_story_1017_10170701_72_dialog_content = "성주님! 일루미나 연방의 새로운 동향에 대한 보고가 올라왔습니다.",
  ui_story_1017_10170701_73_dialog_content = "고하라.",
  ui_story_1017_10170701_74_dialog_content = "새롭게 편성된 일루미나의 부대가 이미 방어선을 넘어 곧 더스크 타운에 도착한다고 합니다.",
  ui_story_1017_10170701_75_dialog_content = "방어선을 넘었다고?",
  ui_story_1017_10170701_76_dialog_content = "예!",
  ui_story_1017_10170701_77_dialog_content = "새롭게 편성된 부대는 무슨 말이지?",
  ui_story_1017_10170701_78_dialog_content = "레이스 장군이 대원수에 취임한 후 창설한 근위군단입니다.",
  ui_story_1017_10170701_79_dialog_content = "최신 무기와 병사로 구성되었고, 그중 한 전사는 연합 훈련에서 라인하르트를 이긴 자라고 합니다.",
  ui_story_1017_10170701_80_dialog_content = "(악셀리아? 지금은 휴양하고 있어야 할 텐데 어째서...)",
  ui_story_1017_10170701_81_dialog_content = "다른 군단장들과 아이테르에 대한 소식은 있나?",
  ui_story_1017_10170701_82_dialog_content = "히이로 장군 외의 군단장은 각각 다른 임무를 맡고 있으며,\n더스크 타운으로는 향하지 않은 듯합니다.",
  ui_story_1017_10170701_83_dialog_content = "아이테르의 경우 직전에 입수한 정보에 따르면, 개전 직후 그의 콜로서스가\n더스크 타운으로 향했다고 합니다.",
  ui_story_1017_10170701_84_dialog_content = "PlayerName 그 애가 더스크 타운으로 갔다고?!",
  ui_story_1017_10170701_85_dialog_content = "그래서 그게 어쨌다는 것이냐.",
  ui_story_1017_10170701_86_dialog_content = "뻔한 일이 아닙니까. 연합 훈련 후 더스크 타운의 상황은 이미 각 세력에 전해졌습니다.",
  ui_story_1017_10170701_87_dialog_content = "일루미나 연방은 더스크 타운의 방어에 확고한 승산이 있을 것입니다.\n그렇기 때문에 그런 강력한 부대를 파견한 것이겠지요.",
  ui_story_1017_10170701_88_dialog_content = "이제 앞으로 더스크 타운에서 백야성의 입지가 남아 있을지 장담할 수 없을 겁니다.",
  ui_story_1017_10170701_89_dialog_content = "이런 중요한 시기에 대원수를 교체하고, 새로 조직한 군을 보내서 암귀를 진압한다...?",
  ui_story_1017_10170701_90_dialog_content = "내가 보기엔 참으로 황당한 행위로군.",
  ui_story_1017_10170701_91_dialog_content = "저들이 정말 지원을 위해서 가는 건지, 아니면 다른 뭔가를 하려는 건지...\n잘 생각해야 할 걸세, 솔라드 성주.",
  ui_story_1017_10170701_92_dialog_content = "명령을 전해라. 지원군을 편성해 즉시 더스크 타운으로 향하도록.",
  ui_story_1017_10170701_93_dialog_content = "감사합니다, 성주님. 외람되오나 어떤 생각이신지 여쭤봐도 되겠습니까?",
  ui_story_1017_10170701_94_dialog_content = "일루미나군이 방어선을 넘었다면, 백야성도 물론 방관하고 있을 순 없지.",
  ui_story_1017_10170701_95_dialog_content = "목적이 협력이든, 쟁탈이든, 출병하지 않는다면 이쪽만 열세에 빠질 뿐이다.",
  ui_story_1017_10170701_96_dialog_content = "명심해라. 가장 중요한 것은 백야 요새의 안전 확보다. 일루미나군의 행동에 개입하지 마라.",
  ui_story_1017_10170701_97_dialog_content = "내 허가가 없는 한, 지원군의 그 어떤 행동도 금한다.",
  ui_story_1017_10170701_98_dialog_content = "예!",
  ui_story_1017_10170701_99_dialog_content = "(아버님께선 일루미나군의 움직임을 경계하고 있어...)",
  ui_story_1017_10170701_100_dialog_content = "성주님, 지원군을 통솔할 지휘관은 결정하셨습니까? 전...",
  ui_story_1017_10170701_101_dialog_content = "우선 물러가라. 더스크 타운의 지원 임무는 네 직무 소관이 아니다.",
  ui_story_1017_10170701_102_dialog_content = "하지만...!",
  ui_story_1017_10170701_103_dialog_content = "오늘은 여기까지 하도록 하지.",
  ui_story_1017_10170801_1_dialog_content = "저기... 가족이 아직 돌아오질 않았습니다...\n성문을 조금만 더 기다렸다가 닫아주시면 안 되겠습니까?",
  ui_story_1017_10170801_2_dialog_content = "성문을 닫고 백야성 사람 외에는 누구도 들여보내지 말라는 성주님의 명령이다.",
  ui_story_1017_10170801_3_dialog_content = "하지만... 제 아이도 백야성의 백성입니다...\n그 아이는 우릴 지키려고 전선에 나서 싸우고 있단 말입니다!",
  ui_story_1017_10170801_4_dialog_content = "명령이 뭔지 모르는 거냐? 성문을 닫아야 하니 물러나라!",
  ui_story_1017_10170801_5_dialog_content = "위대한 「빛의 신」이시여, 부디 저희를 버리지 마옵소서!",
  ui_story_1017_10170801_6_dialog_content = "황혼 뒤에는 검은 밤이 오고, 검은 밤이 지나면 또 황혼이 오니...",
  ui_story_1017_10170801_7_dialog_content = "전선에서 싸우는 아이들을 위해 경건한 마음으로 기도하겠나이다...",
  ui_story_1017_10170801_8_dialog_content = "PlayerName, 물러서!",
  ui_story_1017_10170801_9_dialog_content = "전장에서 물러서는 지휘관이 어디 있어?!",
  ui_story_1017_10170801_10_dialog_content = "이 정도 규모의 암귀 침공은 나도 처음이야.",
  ui_story_1017_10170801_11_dialog_content = "두 번의 협공도 전부 암귀 무리에 휩쓸려 버렸어. 지금은 억지 부릴 때가 아냐!",
  ui_story_1017_10170801_12_dialog_content = "확실히 다크매터가 점점 강해지는 게 느껴져...",
  ui_story_1017_10170801_13_dialog_content = "우두머리도 없고, 목적도 불분명하지만, 수가 너무 많아.\n상황을 정확히 파악하기 전까진 무작정 공격해선 안 돼.",
  ui_story_1017_10170801_14_dialog_content = "단장님! 방어선을 지키고 있던 2개 부대가 암귀의 습격을 받아 흩어졌습니다.\n피해 상황이 심각합니다!",
  ui_story_1017_10170801_15_dialog_content = "각 부대는 방어 태세를 유지하면서 즉시 100보 후퇴하라!",
  ui_story_1017_10170801_16_dialog_content = "예!",
  ui_story_1017_10170801_17_dialog_content = "후방 부대에 전해라. 마구간의 늙은 말을 활용해 짐수레를 준비하고,\n부상자를 마을 주점으로 옮겨라!",
  ui_story_1017_10170801_18_dialog_content = "부상자의 치료는 우리 스스로 해결한다!",
  ui_story_1017_10170801_19_dialog_content = "예, 단장님!",
  ui_story_1017_10170801_20_dialog_content = "단장님, 후퇴하면서 상황을 분석해 보죠. 암귀가 뭘 하려는 것 같나요?",
  ui_story_1017_10170801_21_dialog_content = "놈들은 그저 규모로 압도하며 이쪽 병력을 소모하고 있어요.\n상식으로는 이해할 수 없는 일입니다.",
  ui_story_1017_10170801_22_dialog_content = "PlayerName, 암귀의 행동 패턴에 뭔가 단서가 없을까?",
  ui_story_1017_10170801_23_dialog_content = "한번 감응해 볼게.",
  ui_story_1017_10170801_24_dialog_content = "(더스크 타운 외곽이 전부 암귀잖아... 다크매터가 밀집해 있어...)",
  ui_story_1017_10170801_25_dialog_content = "(암귀들은 천천히 행동하면서 서로의 거리를 짧게 유지하고 있어. 마치...)",
  ui_story_1017_10170801_26_dialog_content = "(거대한 「다크매터의 그물」을 엮으면서 더스크 타운으로 밀려오는 것 같아...)",
  ui_story_1017_10170801_27_dialog_content = "(「그물」에는... 교차점이 잔뜩 있고...)",
  ui_story_1017_10170801_28_dialog_content = "(잠깐만... 교차점의 다크매터 강도가 달라. 밀집한 교차점이 향하는 건...)",
  ui_story_1017_10170801_29_dialog_content = "레오 씨, 다크매터는 넓은 범위로 퍼져 있지만,\n암귀의 행동은 어떤 「중심」의 지휘를 받는 것 같아.",
  ui_story_1017_10170801_30_dialog_content = "「중심」이 뭔지 알겠어?",
  ui_story_1017_10170801_31_dialog_content = "미안... 내 감응 범위 밖이야.",
  ui_story_1017_10170801_32_dialog_content = "하지만 적어도 암귀의 행동에 규칙성이 전혀 없지는 않다는 건 알 수 있겠네요.",
  ui_story_1017_10170801_33_dialog_content = "그래. 그럼 지금은 그 「중심」을 찾는 게 중요해.",
  ui_story_1017_10170801_34_dialog_content = "스카이워커, 「중심」을 찾아봐 줄 수 있겠어?",
  ui_story_1017_10170801_35_dialog_content = "수색 중입니다...",
  ui_story_1017_10170801_36_dialog_content = "시야를 확대합니다...",
  ui_story_1017_10170801_37_dialog_content = "「중심」을 발견하지 못했습니다. 계속 수색 중입니다...",
  ui_story_1017_10170801_38_dialog_content = "지금은 안 되는 것 같아...",
  ui_story_1017_10170801_39_dialog_content = "단순히 거리의 문제라면 「중심」은 어둠의 밑바닥 근처 아니면 그 안에 있겠지.",
  ui_story_1017_10170801_40_dialog_content = "내가 보기엔 「중심」의 적을 쓰러트려야 암귀의 행동을 억제할 수 있을 것 같아.",
  ui_story_1017_10170801_41_dialog_content = "어둠의 밑바닥으로 들어가실 건가요?",
  ui_story_1017_10170801_42_dialog_content = "그래요. 이대로 싸움을 계속한다면 더스크 타운에 남은 건 죽음뿐이니까요.",
  ui_story_1017_10170801_43_dialog_content = "단장님, 저도 가겠습니다.",
  ui_story_1017_10170801_44_dialog_content = "아니, 넌 나 대신 주력 부대의 지휘를 맡고, 계속 방어선을 지켜줘.",
  ui_story_1017_10170801_45_dialog_content = "정찰대, 명령을...",
  ui_story_1017_10170801_46_dialog_content = "PlayerName, 반대 방향에서 당신들 쪽으로 접근하는 병력이 있습니다.",
  ui_story_1017_10170801_47_dialog_content = "어디 군대인지 보여?",
  ui_story_1017_10170801_48_dialog_content = "선두의 수송 차량에 깃발이 걸려 있습니다. 깃발의 문장은...",
  ui_story_1017_10170801_49_dialog_content = "일루미나야!",
  ui_story_1017_10170801_50_dialog_content = "레오 씨, 후방에서 일루미나의 군대가 오고 있어!",
  ui_story_1017_10170801_51_dialog_content = "근위군단, 명령을 하달하겠다──",
  ui_story_1017_10170801_52_dialog_content = "각 부대는 연합 방어 진형을 갖추어 진격하라!",
  ui_story_1017_10170801_53_dialog_content = "「엔진 7호」는 보루의 틈을 먼저 막도록! 암귀가 한 걸음도 앞으로 나아가지 못하게 해라!",
  ui_story_1017_10170801_54_dialog_content = "예!",
  ui_story_1017_10170801_55_dialog_content = "흥, 더스크 타운을 침공한 암귀가 고작 이 정도였어? 몸풀기용으로도 부족하잖아!",
  ui_story_1017_10170801_56_dialog_content = "어...엄청난 박력이다... 저 사람이 일루미나의 신임 대원수인 겁니까?",
  ui_story_1017_10170801_57_dialog_content = "연합 훈련 땐 우리 교관이었지. 대원수가 된 지금은 전혀 몰라보게 변했잖아.",
  ui_story_1017_10170801_58_dialog_content = "그러게, 군복도 전혀 다르고, 힘도 훨씬 더 강해진 것 같아!",
  ui_story_1017_10170801_59_dialog_content = "병사들의 전력도 무서울 정도입니다. 저기 저 병사 좀 보십시오.",
  ui_story_1017_10170801_60_dialog_content = "오면서 이미 암귀 열 마리를 없앴는데, 기세가 전혀 흔들림이 없습니다.",
  ui_story_1017_10170801_61_dialog_content = "난 그것보다 저 병기가 더 흥미롭단 말이지. 병사가 안에서 조종하고 있어.",
  ui_story_1017_10170801_62_option_content = "(나도 조종해 보고 싶네.)",
  ui_story_1017_10170801_63_dialog_content = "안전을 생각하십시오. 권장하지 않겠습니다.",
  ui_story_1017_10170801_64_option_content = "(스카이워커도 저렇게 개조하고 싶네.)",
  ui_story_1017_10170801_65_dialog_content = "스타일이 전혀 다릅니다. 권장하지 않겠습니다.",
  ui_story_1017_10170801_66_dialog_content = "그냥 해본 소리야...",
  ui_story_1017_10170801_67_dialog_content = "음? 저 병사도 와 있군.",
  ui_story_1017_10170801_68_dialog_content = "연합 훈련에서 라인하르트를 이기자마자 레이스의 부하로서 출전이라니, 보통이 아니잖아.",
  ui_story_1017_10170801_69_dialog_content = "악셀리아... 중상을 입었을 텐데, 왜 여길...",
  ui_story_1017_10170801_70_dialog_content = "어머, PlayerName도 있었잖아. 고작 이 정도로 놀라는 거야?",
  ui_story_1017_10170801_71_dialog_content = "......",
  ui_story_1017_10170801_72_dialog_content = "또 만났네, 우리 기사단장님.",
  ui_story_1017_10170801_73_dialog_content = "오랜만이군, 레이스 교관... 아, 미안. 일루미나 대원수라고 불러야겠지.",
  ui_story_1017_10170801_74_dialog_content = "자기 전장으로 돌아왔는데도 그리 가뿐해 보이진 않네.",
  ui_story_1017_10170801_75_dialog_content = "당신, 그리고 일루미나군은 무슨 목적으로 여기 온 거지?",
  ui_story_1017_10170801_76_dialog_content = "난 일루미나 연방의 대원수로서, 더스크 타운의 암귀 진압을 위해 정예 부대를 이끌고 왔어.",
  ui_story_1017_10170801_77_dialog_content = "이해가 안 될 게 있나?",
  ui_story_1017_10170801_78_dialog_content = "줄곧 철면피였던 일루미나가 더스크 타운에 파병이라니 조금 놀랐을 뿐이야.",
  ui_story_1017_10170801_79_dialog_content = "후후, 더스크 타운이 함락되면 피해를 보는 건 일루미나야. 가만히 있을 이유가 없잖아?",
  ui_story_1017_10170801_80_dialog_content = "대원수에겐 그 정도의 식견은 있는 모양이군.\n또 연합 훈련 때처럼 잔꾀를 부리지만 않았으면 좋겠는데 말이지.",
  ui_story_1017_10170801_81_dialog_content = "그때 개입에 대해서도 물론 조사하고 있어.\n지금은 더스크 타운의 맹우로서 협력이 순조롭길 바랄 뿐이야.",
  ui_story_1017_10170801_82_dialog_content = "그러자고.",
  ui_story_1017_10170801_83_dialog_content = "근위군단, 잘 들어라. 「강철가시 기사단」은 이미 오랫동안 힘든 전투를 치렀다!",
  ui_story_1017_10170801_84_dialog_content = "이제 우리의 힘을 보여줄 차례다. 암귀들을 모조리 쓸어버려라!",
  ui_story_1017_10170801_85_dialog_content = "예!",
  ui_story_1017_10170801_86_dialog_content = "「강철가시 기사단」은 들어라!",
  ui_story_1017_10170801_87_dialog_content = "학익진 대형으로 돌격한다! 웃음거리가 되고 싶지 않다면 나와 함께 선두에 서도록!",
  ui_story_1017_10170801_88_dialog_content = "예!",
  ui_story_1017_10170901_1_dialog_content = "율리시스도 정말 불쌍하네. 내가 버린 쓰레기를 개조해서 부랴부랴 전장에 보냈잖아.",
  ui_story_1017_10170901_2_dialog_content = "심지어 전면에 내세울 생각인가?",
  ui_story_1017_10170901_3_dialog_content = "『저 쓰레기들은 강합니다.』",
  ui_story_1017_10170901_4_dialog_content = "당연하지. 저들 몸속에는 내가 만든 「씨앗」이 박혀 있거든. 이미 느꼈겠지?",
  ui_story_1017_10170901_5_dialog_content = "『......』",
  ui_story_1017_10170901_6_dialog_content = "네가 무슨 생각하는지 알아. 그 사람도 곧 오겠지.",
  ui_story_1017_10170901_7_dialog_content = "그렇게나 절 기다렸나요? 이까짓 공격에도 애를 먹고 있는 건가요?",
  ui_story_1017_10170901_8_dialog_content = "예상밖의 상황이 됐거든. 저쪽 참전자가 늘었어.",
  ui_story_1017_10170901_9_dialog_content = "그거 딱 좋은 복수의 기회잖아요? 그럼 기뻐해야죠.",
  ui_story_1017_10170901_10_dialog_content = "내 복수는 당신이 신경 쓸 거 없어. 물건은 가져왔어?",
  ui_story_1017_10170901_11_dialog_content = "그래요.",
  ui_story_1017_10170901_12_dialog_content = "머드번들?",
  ui_story_1017_10170901_13_dialog_content = "생긴 건 좀 역겹지만, 당신 진행 속도엔 도움이 될 거예요. 어떤가요?",
  ui_story_1017_10170901_14_dialog_content = "공간을 삼켜 늪을 만드는 녀석이었던 걸로 기억하는데 말이죠.\n오로리안에게 고통을 주는 방식도 꽤... 독특했고 말이에요. 그래요. 아주 독특했죠.",
  ui_story_1017_10170901_15_dialog_content = "한번 해 보자고.",
  ui_story_1017_10170901_16_dialog_content = "『예.』",
  ui_story_1017_10170901_17_dialog_content = "『다크매터가... 모이고 있다... 배고프다!』",
  ui_story_1017_10170901_18_dialog_content = "암귀가 머드번들의 늪 속에 있으면, 체내의 「씨앗」이 녀석의 코어와 공명을 일으킬 거야.",
  ui_story_1017_10170901_19_dialog_content = "『힘이 넘쳐난다!』",
  ui_story_1017_10170901_20_dialog_content = "그리고 이제 너흰 오로리안을 먹고 성장하기만 하면 돼.\n나머지는 때가 되면 머드번들이 처리해 줄 테니까.",
  ui_story_1017_10170901_21_dialog_content = "재미없는 설명 같은 건 됐고, 여긴 당신한테 맡길게요.\n그럼 「카펫」을 검사하러 올 때 다시 만나요~",
  ui_story_1017_10170901_22_dialog_content = "『음식이다!』",
  ui_story_1017_10170901_23_dialog_content = "자, 시작해. 늪이 더스크 타운까지 닿을 때까지, 여기 있는 음식은 전부 네 거야.",
  ui_story_1017_10170901_24_dialog_content = "『구오오오!』",
  ui_story_1017_10170901_25_dialog_content = "이런! 전방에서 강력한 다크매터가 전해지고 있어!",
  ui_story_1017_10170901_26_dialog_content = "벌써?! 「중심」에 있던 적인가?",
  ui_story_1017_10170901_27_dialog_content = "모르겠어... 하지만 「다크매터의 그물」이 점점 가까워지는 건 확실해!",
  ui_story_1017_10170901_28_dialog_content = "으... 어억...",
  ui_story_1017_10170901_29_dialog_content = "무슨 상황이지?",
  ui_story_1017_10170901_30_dialog_content = "보고드립니다! 일부 병사들이 다크매터의 영향을 받은 것으로 보입니다...",
  ui_story_1017_10170901_31_dialog_content = "서둘러 치료하고, 부상자의 수를 파악해라.",
  ui_story_1017_10170901_32_dialog_content = "예!",
  ui_story_1017_10170901_33_dialog_content = "(...뭐지? 갑자기... 힘이 끓어오르는 느낌이야...)",
  ui_story_1017_10170901_34_dialog_content = "대원수님, 괜찮으신가요?",
  ui_story_1017_10170901_35_dialog_content = "이 다크매터... 확실히 느낌이 좋지 않아...",
  ui_story_1017_10170901_36_dialog_content = "부하들을 데리고 퇴각해.\n「강철가시 기사단」, 1분대와 2분대는 적을 추격하고, 3분대, 4분대는 엄호를 맡는다!",
  ui_story_1017_10170901_37_dialog_content = "기다려! 이 정도 암귀는 아무것도 아니라고.",
  ui_story_1017_10170901_38_dialog_content = "PlayerName, 계속 전투를 지원해!",
  ui_story_1017_10170901_39_dialog_content = "전방에서 특수한 형태의 암귀가 접근하고 있습니다.",
  ui_story_1017_10170901_40_dialog_content = "「중심」의 적이야?",
  ui_story_1017_10170901_41_dialog_content = "모르겠습니다. 다만 다른 암귀보다 강한 다크매터를 감지했습니다.",
  ui_story_1017_10170901_42_dialog_content = "알겠어. 다른 정보는 없어?",
  ui_story_1017_10170901_43_dialog_content = "계속 탐지 후 결과가 나오는 대로 말씀드리겠습니다.",
  ui_story_1017_10170901_44_dialog_content = "응, 부탁할게!",
  ui_story_1017_10170901_45_dialog_content = "강한 암귀가 이쪽으로 오고 있어요! 다들 준비하세요!",
  ui_story_1017_10170901_46_dialog_content = "흥, 드디어 상대가 될 만한 녀석이 오는 건가.",
  ui_story_1017_10170901_47_dialog_content = "잘 보라고, 기사 나리들. 근위군단은 결코 이런 데서 쓰러지지 않아. 적은 우리에게 맡기라고!",
  ui_story_1017_10170901_48_dialog_content = "뭐, 그러지. 「강철가시 기사단」, 엄호하라!",
  ui_story_1017_10170901_49_dialog_content = "예!",
  ui_story_1017_10171001_1_dialog_content = "어떻게든... 쓰러트렸네!",
  ui_story_1017_10171001_2_dialog_content = "쓰러지기 전에 저렇게 많은 암귀를 소환할 줄은 몰랐어요. 정말 벅찬 상대였네요.",
  ui_story_1017_10171001_3_dialog_content = "음, 공격에 전략이 보이기 시작했어. 그래도 전장은 이걸로 당분간 안전할 거야.",
  ui_story_1017_10171001_4_dialog_content = "보고드립니다! 다크매터의 영향을 받는 병사가 여전히 증가하고 있습니다!",
  ui_story_1017_10171001_5_dialog_content = "원인은 알아냈나?",
  ui_story_1017_10171001_6_dialog_content = "아직입니다. 다수의 병사들이 몸을 제어할 수 없게 되었고, <color=#FFB400>광적인 공격성</color>을 보이기 시작했습니다.\n치료도 전혀 효과가 없습니다.",
  ui_story_1017_10171001_7_dialog_content = "......",
  ui_story_1017_10171001_8_dialog_content = "(신체의 제어가 안 되고, 공격성이 생긴다...? 방금 그 전투에서 모두 같은 느낌을 느낀 건가...?)",
  ui_story_1017_10171001_9_dialog_content = "단장님! 동부 전장에서 소수의 암귀가 또 참호를 휩쓸기 시작했습니다!",
  ui_story_1017_10171001_10_dialog_content = "아무래도 지금 쓰러트린 건 「중심」의 적이 아니었던 모양이군.",
  ui_story_1017_10171001_11_dialog_content = "누구 단서를 찾은 사람 없나?",
  ui_story_1017_10171001_12_dialog_content = "치료 과정에서 알게 된 건데요. 이번에 병사들이 받은 다크매터의 영향은\n평소 우리가 접하는 것과 달랐어요.",
  ui_story_1017_10171001_13_dialog_content = "효과를 보려면 의료원에 가서 더 높은 수준의 치료를 해야 할 것 같아요.",
  ui_story_1017_10171001_14_dialog_content = "레이스 대원수님, 문제가 생긴 휘하의 병사들은 제가 의료원으로 데려다줄게요.",
  ui_story_1017_10171001_15_dialog_content = "마침 같은 부탁을 하려던 참이었어. 고마워!\n이번 전투가 끝나면 일루미나에서 상응하는 보상을 지급할 거야.",
  ui_story_1017_10171001_16_dialog_content = "이건 제가 마땅히 해야 할 일인걸요.",
  ui_story_1017_10171001_17_dialog_content = "대원수님, 일선 병사들의 보고에 따르면 일부 병사들이 대열을 이탈하여\n같은 방향으로 일제히 향하고 있다고 합니다...",
  ui_story_1017_10171001_18_dialog_content = "마치 무슨 힘에 조종당하고 있는 것 같다고 합니다...",
  ui_story_1017_10171001_19_dialog_content = "「중심」 쪽 적의 영향일 가능성은?",
  ui_story_1017_10171001_20_dialog_content = "가능성이 없다고 할 순 없겠죠. 전부터 다크매터의 움직임은 「중심」의 조종을\n받는 게 아닐지 추측했거든요.",
  ui_story_1017_10171001_21_dialog_content = "더스크 타운의 병사들도 같은 상황을 겪었나?",
  ui_story_1017_10171001_22_dialog_content = "<size=30>단장님, 보고드립니다...</size>",
  ui_story_1017_10171001_23_dialog_content = "<size=30>...확실한가?</size>",
  ui_story_1017_10171001_24_dialog_content = "<size=30>네, 단장님.</size>",
  ui_story_1017_10171001_25_dialog_content = "대원수, 지금 이상 행동을 보이는 병사들은 모두 당신의 부하들이다.",
  ui_story_1017_10171001_26_dialog_content = "무슨 말이 하고 싶은 거지?",
  ui_story_1017_10171001_27_dialog_content = "단도직입적으로 말하지. 방금 몇 번의 진격 중 당신 부하들의 모습은 줄곧 이상했어.",
  ui_story_1017_10171001_28_dialog_content = "적이 너무 강해서인 건지...",
  ui_story_1017_10171001_29_dialog_content = "아니면 대원수의 군에 내통자가 있는 건지 모르겠군.",
  ui_story_1017_10171001_30_dialog_content = "지금 일루미나가 더스크 타운에 온 의도를 의심하고 있는 건가?",
  ui_story_1017_10171001_31_dialog_content = "물론 그건 아니지. 다만 이번 적이 뭔가 다르다는 걸 느낀 이상,\n내겐 단장으로서 부하들을 지킬 책임이 있다.",
  ui_story_1017_10171001_32_dialog_content = "지금 상황으로 봤을 때 당신 부하들은 이미 오로리안과 암귀를 구분할 수 없게 됐거든.",
  ui_story_1017_10171001_33_dialog_content = "말조심해! 나 레이스, 지금까지 단 한 번도 더러운 수작 따윈 써본 적 없어!",
  ui_story_1017_10171001_34_dialog_content = "레오 단장님, 레이스 대원수님, 전 여기 있는 모든 사람들이\n더스크 타운을 위해 싸우고 있다고 믿어요.",
  ui_story_1017_10171001_35_dialog_content = "병사들이 명령을 따르지 않는 이유는 아직 알 수 없지만...",
  ui_story_1017_10171001_36_dialog_content = "혹시나 이게 우리의 전황 분석을 막는 적의 수법은 아닐지 걱정돼요.",
  ui_story_1017_10171001_37_dialog_content = "방금 전투에서 내 병사들이 명령을 전적으로 따르지 않은 건 맞아.",
  ui_story_1017_10171001_38_dialog_content = "하지만 대원수로서 일루미나군이 전장에서 벌이는 일체의 행동은 모두 내 책임이야.",
  ui_story_1017_10171001_39_dialog_content = "병사들의 비정상적인 행동에 대해선 내가 조사해서 확실하게 설명할게.",
  ui_story_1017_10171001_40_dialog_content = "다만, 계속해서 일루미나의 의도를 의심한다면, 우리에 대한 적대행위로 간주하겠어.",
  ui_story_1017_10171001_41_dialog_content = "호오? 적대라니, 그렇게 말할 것까지야. 난 그저 가볍게 충고했을 뿐이라고.",
  ui_story_1017_10171001_42_dialog_content = "당신도 일루미나의 대원수가 된 지 얼마 안 됐잖아?\n부하들의 전투 습관을 좀 더 이해해 두었으면 좋겠는데 말이지.",
  ui_story_1017_10171001_43_dialog_content = "만약 다음에 또 이유 없이 적에게 투신하거나, 다른 병사를 해치는 일이 발생한다면,\n그땐 나도 그냥 넘어가진 않을 테니까.",
  ui_story_1017_10171001_44_dialog_content = "흥, 큰소리는 잘도 치는군.",
  ui_story_1017_10171001_45_dialog_content = "일루미나와 겨루고 싶다면 어디 해 봐. 나 혼자서도 널 철저히 밟아줄 테니까!",
  ui_story_1017_10171001_46_dialog_content = "대원수님! 긴급 보고입니다!",
  ui_story_1017_10171001_47_dialog_content = "악셀리아 중위의 작전 소대 전원이 행방불명인 상황입니다!",
  ui_story_1017_10171001_48_dialog_content = "?!",
  ui_story_1017_10171001_49_dialog_content = "담당 전장은?",
  ui_story_1017_10171001_50_dialog_content = "서부입니다. 현재 서부 쪽은 암귀가 여전히 더스크 타운을 향해 전진하고 있습니다.",
  ui_story_1017_10171001_51_dialog_content = "근위군단 전군, 서쪽으로 이동해 암귀를 섬멸하라!",
  ui_story_1017_10171001_52_dialog_content = "부상자도 마찬가지야. 다리나 머리가 잘린 게 아니라면 바짝 따라와!",
  ui_story_1017_10171001_53_dialog_content = "그리고 이상 행동을 보이는 병사를 발견하면 즉시 보고하도록!",
  ui_story_1017_10171001_54_dialog_content = "예!",
  ui_story_1017_10171001_55_dialog_content = "PlayerName, 따라와.",
  ui_story_1017_10171001_56_dialog_content = "네? 저요?",
  ui_story_1017_10171001_57_dialog_content = "얼른!",
  ui_story_1017_10171001_58_dialog_content = "......",
  ui_story_1017_10171001_59_dialog_content = "단장님, 저희는 저희끼리 움직입니까?",
  ui_story_1017_10171001_60_dialog_content = "사람이 새 자리에 앉으면 처음엔 늘 의욕이 넘치기 마련이지.\n문제를 확실히 말해두지 않으면 나중에 더 골치 아파질 뿐이야.",
  ui_story_1017_10171001_61_dialog_content = "우린 동부로 간다. 동부는 거주구에 가까우니까, 암귀는 한 마리도 넘어오게 둬선 안 돼.",
  ui_story_1017_10171001_62_dialog_content = "예, 단장님.",
  ui_story_1017_10171001_63_dialog_content = "단장님, 의료원의 동료가 도착했어요. 전 먼저 중상을 입은 병사부터 의료원으로 보낼게요.",
  ui_story_1017_10171001_64_dialog_content = "의료원은 주민들을 위해 남겨 둡시다. 다친 병사는 제가 <color=#FFB400>주점</color>의 친구에게 부탁하죠.",
  ui_story_1017_10171001_65_dialog_content = "단장님, 주점은 이미...",
  ui_story_1017_10171001_66_dialog_content = "그렇다면 캠프에 있는 후방 지원 병력들을 데리고 임시 의료 부대를 조직하고,\n남은 <color=#FFB400>리치라이트</color>를 가지고 백야 요새로 가서 의료 물자로 바꾸어 와라.",
  ui_story_1017_10171001_67_dialog_content = "하지만 단장님, 백야 요새는 이미 성문을 닫아버렸습니다!",
  ui_story_1017_10171001_68_dialog_content = "그러니까 리치라이트를 가져가라는 거야!",
  ui_story_1017_10171001_69_dialog_content = "아, 알겠습니다. 단장님.",
  ui_story_1017_10171001_70_dialog_content = "정말 무슨 일이든 백야 요새만 얽혔다 하면 첩첩산중이란 말이지.",
  ui_story_1017_10171001_71_dialog_content = "전 더스크 타운 출신이지만, 백야성 사람이기도 해요. 저도 뭔가 방법을 생각해 볼게요.",
  ui_story_1017_10171001_72_dialog_content = "백야성 사람인 것을 명예롭게 여기다니, 참 흔치 않은 마음가짐 아닙니까.",
  ui_story_1017_10171001_73_dialog_content = "어느 진영에 속하는지는 중요하지 않아요.\n전 그저 더스크 타운에 사는 사람들이 편안하게 살아갈 수 있길 바랄 뿐이니까요.",
  ui_story_1017_10171001_74_dialog_content = "당신이 꿈꾸는 그 풍경은 너무나도 아득하군요.",
  ui_story_1017_10171001_75_dialog_content = "일루미나와 백야성의 도움이 없다면 더스크 타운은 당장 내일도 장담할 수 없어요.\n하물며 편안한 삶이라니요.",
  ui_story_1017_10171001_76_dialog_content = "군에 있어 가장 중요한 게 뭔지 알고 있습니까?",
  ui_story_1017_10171001_77_dialog_content = "마음입니다. 한마음 한뜻이 되어야만 승리할 수 있기 때문이죠.\n하지만 지금 일루미나군은 오합지졸 그 자체입니다.",
  ui_story_1017_10171001_78_dialog_content = "콜로서스는 군 전체의 이동 현황을 볼 수 있나?",
  ui_story_1017_10171001_79_dialog_content = "아주 잘 보입니다, PlayerName.",
  ui_story_1017_10171001_80_dialog_content = "네, 레이스... 대원수님.",
  ui_story_1017_10171001_81_dialog_content = "그렇게 부르면 어색하지 않아?",
  ui_story_1017_10171001_82_dialog_content = "......",
  ui_story_1017_10171001_83_dialog_content = "그건 무슨 표정이야?",
  ui_story_1017_10171001_84_dialog_content = "아, 아무것도 아니에요... 그냥 대원수랑 같이 움직이는 게 익숙하지가 않아서...",
  ui_story_1017_10171001_85_dialog_content = "흥, 너 라인하르트랑은 친하지 않아?",
  ui_story_1017_10171001_86_dialog_content = "그러면서 나랑 있으면 그렇게 긴장이 되나? 라인하르트랑 내가 뭐가 다른데?",
  ui_story_1017_10171001_87_dialog_content = "(그냥 다르기만 할까...)",
  ui_story_1017_10171001_88_dialog_content = "그냥 편하게 불러도 돼. 나도 널 편하게 부를 거니까.",
  ui_story_1017_10171001_89_dialog_content = "알겠어요, 레이스 씨...",
  ui_story_1017_10171001_90_dialog_content = "내 부하들의 상황에 대해 부탁하고 싶은 게 있어.",
  ui_story_1017_10171001_91_dialog_content = "뭐죠?",
  ui_story_1017_10171001_92_dialog_content = "앞으로의 전투에서 부하들의 상태가 더 악화될지도 몰라.",
  ui_story_1017_10171001_93_dialog_content = "그래서 지금부터 부하들의 위치를 특정해 줬으면 좋겠어.\n적들의 대거 공격이 있기 전에 상황을 파악하고 싶어.",
  ui_story_1017_10171001_94_dialog_content = "알겠어요, 스카이워커도 도와줄 거예요.",
  ui_story_1017_10171001_95_dialog_content = "이상 행동을 보이는 병사를 수색하고 있습니다. 예상 소요 시간은 60초입니다.",
  ui_story_1017_10171001_96_dialog_content = "물어보고 싶은 게 있어요.",
  ui_story_1017_10171001_97_dialog_content = "뭐지?",
  ui_story_1017_10171001_98_dialog_content = "악셀리아가 왜 레이스 씨 부대에 있는 거죠?",
  ui_story_1017_10171001_99_dialog_content = "분명히... 연합 훈련에서 중상을 입어서 요양 중이어야 맞을 텐데요.",
  ui_story_1017_10171001_100_dialog_content = "그게 바로 일루미나 군인의 인내력이야. 알겠어?",
  ui_story_1017_10171001_101_dialog_content = "매번 생명의 위험을 무릅쓰고 전장에 나가는 게 말인가요...",
  ui_story_1017_10171001_102_dialog_content = "그 애가 할 수 있다고 못 믿겠어?",
  ui_story_1017_10171001_103_dialog_content = "아뇨, 악셀리아면 가능할 거예요. 그냥 왠지...",
  ui_story_1017_10171001_104_dialog_content = "악셀리아는 제가 아는 다른 동료들처럼 싸움을 무서워하지도, 갈망하지도 않는 것 같아서요.",
  ui_story_1017_10171001_105_dialog_content = "지금까지 지내보면서 전 악셀리아한테서 감정이란 걸 거의 못 느꼈어요...",
  ui_story_1017_10171001_106_dialog_content = "감정은 싸움을 승리로 이끄는 무기가 될 수 없어, 아이테르.",
  ui_story_1017_10171001_107_dialog_content = "아니, 제가 하고 싶은 말은...",
  ui_story_1017_10171001_108_dialog_content = "나도 알아.",
  ui_story_1017_10171001_109_dialog_content = "대원수가 되기 전까진 나도 같은 걱정을 하고 있었으니까.",
  ui_story_1017_10171001_110_dialog_content = "하지만 지금은 알 수 있어.",
  ui_story_1017_10171001_111_dialog_content = "무엇을 해도 이길 수 없는 상대를 이기기 위해선, 반드시 기존의 자신을 버리고,\n상대의 관점에서 문제를 생각해야만 해.",
  ui_story_1017_10171001_112_dialog_content = "기존의 자신을... 하지만 제 눈에 보이는 레이스 씨는 예전이랑 마찬가지로\n선두를 달리며 싸우고 있는데요.",
  ui_story_1017_10171001_113_dialog_content = "후훗, 강력한 감각 능력을 가진 아이테르면서, 머릿속은 오히려 단순하네.",
  ui_story_1017_10171001_114_dialog_content = "참 부럽단 말이지...",
  ui_story_1017_10171001_115_dialog_content = "그거 왠지 칭찬은 아닌 것 같네요...",
  ui_story_1017_10171001_116_dialog_content = "틀렸어. 됐으니까 앞이나 잘 봐. 구덩이에 빠지거나 하지 말고.",
  ui_story_1017_10171001_117_dialog_content = "20미터 앞 장애물 아래에 이상 행동을 보이는 병사가 한 명 있습니다.",
  ui_story_1017_10171001_118_dialog_content = "레이스 씨, 앞에 이상해진 병사가 있어요!",
  ui_story_1017_10171001_119_dialog_content = "서두르자.",
  ui_story_1017_10171001_120_dialog_content = "......",
  ui_story_1017_10171001_121_dialog_content = "지금 느낌이 어때?",
  ui_story_1017_10171001_122_dialog_content = "......",
  ui_story_1017_10171001_123_dialog_content = "아직 의식이 있어요. 하지만 레이스 씨 말은 안 들리나 봐요.",
  ui_story_1017_10171001_124_dialog_content = "감응해 볼게요... 뭔가 단서를 찾을 수 있을지도 몰라요.",
  ui_story_1017_10171001_125_dialog_content = "응.",
  ui_story_1017_10171001_126_option_content = "[감응을 시도한다]",
  ui_story_1017_10171001_127_dialog_content = "(여긴... 늪인가?)",
  ui_story_1017_10171001_128_dialog_content = "(마치 거대한 카펫처럼 온 땅을 뒤덮고 있어...)",
  ui_story_1017_10171001_129_dialog_content = "(주변의 파괴된 건물... 뭔가 익숙한 느낌이야...)",
  ui_story_1017_10171001_130_dialog_content = "(아마... 더스크 타운이겠지...)",
  ui_story_1017_10171001_131_dialog_content = "(근데 이 늪은 대체 어디서 온 거지...? 내 발밑으로 점점 모여들고 있잖아...)",
  ui_story_1017_10171001_132_dialog_content = "(왠지 정해진 방향으로 흐르고 있진 않은 것 같아...)",
  ui_story_1017_10171001_133_dialog_content = "으윽...",
  ui_story_1017_10171001_134_dialog_content = "어때? 느낌이 안 좋아?",
  ui_story_1017_10171001_135_dialog_content = "다크매터 때문에 머리가 아파요... 뭐, 그래도 아직까진 괜찮아요...",
  ui_story_1017_10171001_136_dialog_content = "이 병사의 의식 속은 늪으로 뒤덮인 더스크 타운이었어요.\n게다가 그 늪은 끝이 보이지 않을 정도였고요...",
  ui_story_1017_10171001_137_dialog_content = "흙탕물이 계속 발밑으로 몰려와서 제대로 서 있기도 힘들었어요.",
  ui_story_1017_10171001_138_dialog_content = "늪... 다크매터... 그렇다면 병사의 의식 속 늪은 현실세계의 다크매터와 대응하는 거겠지...",
  ui_story_1017_10171001_139_dialog_content = "그게 병사들이 이상해진 이유인가...",
  ui_story_1017_10171001_140_dialog_content = "늪이 확산되는 방향을 알 수 있다면... 「중심」의 적이 있는 곳도 찾아낼 수 있을지도 몰라...",
  ui_story_1017_10171001_141_dialog_content = "방해하지 마!",
  ui_story_1017_10171001_142_dialog_content = "잠깐만...! 어째서...",
  ui_story_1017_10171001_143_dialog_content = "이 사람... 레이스 씨 부하인가요?",
  ui_story_1017_10171001_144_dialog_content = "그거야 당연하지. 그리고 지금 내 손으로 죽여버릴 뻔했다고!",
  ui_story_1017_10171001_145_dialog_content = "다크매터의 영향이 심각한 것 같아요. 완전히 이성을 잃었잖아요...",
  ui_story_1017_10171001_146_dialog_content = "이 사람도 감응해 볼게요.",
  ui_story_1017_10171001_147_dialog_content = "너무 무리하지 마. 위험을 느끼면 바로 감응을 중단해.",
  ui_story_1017_10171001_148_option_content = "[감응을 시도한다]",
  ui_story_1017_10171001_149_dialog_content = "(아까랑 같은 풍경이야... 근데 늪의 흐름이 아까보다 훨씬 더 빨라...)",
  ui_story_1017_10171001_150_dialog_content = "(이번엔... 늪이 같은 방향에서 흘러오는 것 같아...)",
  ui_story_1017_10171001_151_dialog_content = "(저쪽은... 영원한 밤의 땅인가?)",
  ui_story_1017_10171001_152_dialog_content = "(어두운 하늘이 꼭 늪이랑 하나로 이어진 것 같아.)",
  ui_story_1017_10171001_153_dialog_content = "(확실해... 분명히 저쪽이 바로 「중심」이 있는 방향이야...)",
  ui_story_1017_10171001_154_dialog_content = "(이런──)",
  ui_story_1017_10171001_155_dialog_content = "...암귀!",
  ui_story_1017_10171001_156_dialog_content = "물러서!",
  ui_story_1017_10171001_157_dialog_content = "...레이스 씨? 이 사람...",
  ui_story_1017_10171001_158_dialog_content = "걱정할 거 없어. 기절했을 뿐이니까.",
  ui_story_1017_10171001_159_dialog_content = "다만 감응은 그만하는 게 좋겠어. 나한테도 이 녀석 몸속의 다크매터가 느껴질 정도니까.",
  ui_story_1017_10171001_160_dialog_content = "저기 하늘 좀 봐. 점점 어두워지고 있어...",
  ui_story_1017_10171001_161_dialog_content = "...저기예요! 병사의 의식 속에 있던 늪은 영원한 밤의 땅 쪽에서 흘러오고 있었어요.\n게다가 속도도 점점 빨라졌어요.",
  ui_story_1017_10171001_162_dialog_content = "저기가 분명히 「중심」이 있는 방향이에요!",
  ui_story_1017_10171001_163_dialog_content = "그럼 적의 위치를 찾은 셈인가?",
  ui_story_1017_10171001_164_dialog_content = "아마 맞을 거예요. 게다가 다크매터와 오래 접촉해서 그런지... 주변이 전부 흐릿한 느낌이에요...",
  ui_story_1017_10171001_165_dialog_content = "네가 느낀 게 맞아. 영원한 밤의 땅 방향의 하늘이 점점 어두워지고 있어.",
  ui_story_1017_10171001_166_dialog_content = "아무래도 다크매터는 병사들만 영향을 주는 게 아니라 환경조차 바꿔버릴 수 있는 것 같아. 주변에 부패하는 냄새가 풍기기 시작했어.",
  ui_story_1017_10171001_167_dialog_content = "<color=#e8d9bb>콸콸... 콸콸...</color>",
  ui_story_1017_10171001_168_dialog_content = "지금 무슨 소리 안 났어...?",
  ui_story_1017_10171001_169_dialog_content = "이건... 물 흐르는 소리 같은데요...",
  ui_story_1017_10171001_170_dialog_content = "물 흐르는 소리...? 설마 정말로 늪이 더스크 타운으로 흘러오는 건 아니겠지?!",
  ui_story_1017_10171001_171_dialog_content = "게다가... 영원한 밤의 땅 방향에서 오고 있어요!",
  ui_story_1017_10171001_172_dialog_content = "...아무래도 「중심」의 적이 다가오고 있는 모양이네.",
  ui_story_1017_10171001_173_dialog_content = "<color=#e8d9bb>콸콸... 콸콸...</color>",
  ui_story_1017_10171001_174_dialog_content = "PlayerName, 서쪽에 암귀 무리가 나타났습니다. 약 5초 후 당신의 감응 범위에 진입합니다.",
  ui_story_1017_10171001_175_dialog_content = "그렇게 빨리?! 확인해 볼게...",
  ui_story_1017_10171001_176_option_content = "[감응을 시도한다]",
  ui_story_1017_10171001_177_dialog_content = "(주변 일대가 온통 새까맣잖아... 이, 이건... 진짜 늪이야!)",
  ui_story_1017_10171001_178_dialog_content = "레이스 씨! 병사들의 의식에서 봤던 거랑 똑같아요!\n암귀가 늪을 따라 우리가 있는 방향으로 오고 있어요!",
  ui_story_1017_10171001_179_dialog_content = "뭐라고?!",
  ui_story_1017_10171001_180_dialog_content = "현 상황을 기사단에 전하고, 주민들을 즉시 대피시키라고 해!",
  ui_story_1017_10171001_181_dialog_content = "예!",
  ui_story_1017_10171001_182_dialog_content = "정찰부대는 나와 함께 상황을 파악하러 간다. 「엔진 7호」는 후미에서 엄호하도록!",
  ui_story_1017_10171001_183_dialog_content = "누구도 내 명령 없이 함부로 행동하지 마라. 몸에 이상을 느끼면 즉시 전장을 벗어나라!",
  ui_story_1017_10171001_184_dialog_content = "대원수님! 동쪽 부대의 병사들이 하나둘씩 난폭해지고 있습니다!",
  ui_story_1017_10171001_185_dialog_content = "동쪽? 내가 감응한 건 서쪽인데...",
  ui_story_1017_10171001_186_dialog_content = "비켜!",
  ui_story_1017_10171001_187_dialog_content = "벌써 이쪽까지... 어째서...",
  ui_story_1017_10171001_188_dialog_content = "흥! 이미 포위돼 버렸잖아.",
  ui_story_1017_10171001_189_dialog_content = "PlayerName, 잘 따라 와!",
  ui_story_1017_10171101_1_dialog_content = "<color=#e8d9bb>얼마 전, 일루미나의 한 실험동...</color>",
  ui_story_1017_10171101_2_dialog_content = "뭘 하고 있는 거죠?",
  ui_story_1017_10171101_3_dialog_content = "앗, 수...순찰 중입니다... 오, 오늘은 제가 이 구역의 순찰을 맡고 있습니다...",
  ui_story_1017_10171101_4_dialog_content = "여긴 율리시스 교수님의 실험실입니다. 이 구역은 평소에 순찰을 배정하지 않는데요.",
  ui_story_1017_10171101_5_dialog_content = "아, 그, 그게...",
  ui_story_1017_10171101_6_dialog_content = "누가 보낸 거죠?",
  ui_story_1017_10171101_7_dialog_content = "아니, 전...",
  ui_story_1017_10171101_8_dialog_content = "죄, 죄송해요, 중령님! 제가 거짓말을 했어요... 전 그저...",
  ui_story_1017_10171101_9_dialog_content = "오빠가 일루미나 역사상 가장 위대한 <color=#FFB400>실험</color>에 참가하게 된 게 부러워서, 그래서...",
  ui_story_1017_10171101_10_dialog_content = "실험은 성공 전까지 엄격하게 기밀을 유지해야 합니다. 병사의 가족에게도 알 권리는 없습니다.",
  ui_story_1017_10171101_11_dialog_content = "저랑 오빠는 정말 사이가 좋아서, 전 오빠에 대해선 다 알아요. 믿어주세요, 정말이에요...",
  ui_story_1017_10171101_12_dialog_content = "......",
  ui_story_1017_10171101_13_dialog_content = "오빠가 실험에 참여해서 엄마도 저도 정말 기뻤어요!",
  ui_story_1017_10171101_14_dialog_content = "하지만 전 경험이 부족해서 뽑히지 못했어요...",
  ui_story_1017_10171101_15_dialog_content = "그게 아쉬운 건가요?",
  ui_story_1017_10171101_16_dialog_content = "네...",
  ui_story_1017_10171101_17_dialog_content = "앞으로도 기회는 있을 겁니다...",
  ui_story_1017_10171101_18_dialog_content = "정말요? 이번에 뽑히지 않았어도 앞으로 일루미나를 밝힐 「별」이 될 기회가 있는 건가요?",
  ui_story_1017_10171101_19_dialog_content = "그래요...",
  ui_story_1017_10171101_20_dialog_content = "감사합니다, 중령님! 그, 그럼 지금 바로 가 보겠습니다!",
  ui_story_1017_10171101_21_dialog_content = "그러세요... 저들은 지금쯤 암귀와 싸우고 있을 겁니다...",
  ui_story_1017_10171101_22_dialog_content = "네! 저희 오빠는 아주 강해요... 암귀 따윈 오빠 상대가 못 돼요!",
  ui_story_1017_10171101_23_dialog_content = "......",
  ui_story_1017_10171101_24_dialog_content = "앗... 죄송합니다! 제가 말이 너무 많았네요... 실례했습니다!",
  ui_story_1017_10171101_25_dialog_content = "<size=30>...이런 게... 일루미나를 밝힐 「별」인 건가요?</size>",
  ui_story_1017_10171101_26_dialog_content = "......",
  ui_story_1017_10171101_27_dialog_content = "<size=30>교수님...</size>",
  ui_story_1017_10171101_28_dialog_content = "......",
  ui_story_1017_10171101_29_dialog_content = "율리시스 교수님?",
  ui_story_1017_10171101_30_dialog_content = "음, 왔나. 조사의 진척은?",
  ui_story_1017_10171101_31_dialog_content = "임무 문제로 온 게 아닙니다... 다른 일 때문입니다.",
  ui_story_1017_10171101_32_dialog_content = "뭐지?",
  ui_story_1017_10171101_33_dialog_content = "교수님, 악셀리아는 지난번 연합 훈련에서 심각한 부상을 입었습니다.",
  ui_story_1017_10171101_34_dialog_content = "상대는 라인하르트였으니 말이야. 지금까지 악셀리아가 접해 본 가장 강한 상대였지.",
  ui_story_1017_10171101_35_dialog_content = "......",
  ui_story_1017_10171101_36_dialog_content = "할 말이 있는 모양이군.",
  ui_story_1017_10171101_37_dialog_content = "교수님, 악셀리아는 지금까지 몇 번이나 중상을 입어 왔습니다.\n그래도 악셀리아는 여전히 일루미나를 위해 싸우고 있습니다.",
  ui_story_1017_10171101_38_dialog_content = "전 그저... 「계명성 프로젝트」 2.0을 거친 후 악셀리아가...",
  ui_story_1017_10171101_39_dialog_content = "허허, 그 일이라면 전혀 걱정할 필요 없다.",
  ui_story_1017_10171101_40_dialog_content = "이건 두 실험 데이터의 대비 결과다. 한번 살펴봐라.",
  ui_story_1017_10171101_41_dialog_content = "「계명성 프로젝트」 2.0을 거친 병사들의 신체 기능은 기존의 10배로 높아졌다.",
  ui_story_1017_10171101_42_dialog_content = "그리고 앞으로는 20배, 50배로 성장할 것이다.",
  ui_story_1017_10171101_43_dialog_content = "악셀리아의 실험 결과는 양호하다. 손상될 확률도 크게 낮아졌지.",
  ui_story_1017_10171101_44_dialog_content = "지금의 악셀리아는 절정기에 있다고 해도 좋을 것이다.",
  ui_story_1017_10171101_45_dialog_content = "더스크 타운으로 떠난 다른 병사들도 마찬가지고 말이야.",
  ui_story_1017_10171101_46_dialog_content = "교수님... 그래도 전 이제 막 회복한 악셀리아를 전장에 내보내는 건...\n너무 잔혹하다고 생각합니다...",
  ui_story_1017_10171101_47_dialog_content = "...자신이 일루미나의 미래를 밝히는 「별」이라고 생각하는 저 병사들도 마찬가지고 말입니다.",
  ui_story_1017_10171101_48_dialog_content = "그래, 현실이란 원래 잔혹한 것이다. 하지만 그것이 일루미나의 군인으로서의 의무다.",
  ui_story_1017_10171101_49_dialog_content = "정말... 그런가요?",
  ui_story_1017_10171101_50_dialog_content = "저들은 자신들의 힘이 이런 수단으로 얻어진 것임을 모릅니다...",
  ui_story_1017_10171101_51_dialog_content = "한계에 도달했을 때 급격하게 힘을 잃는 건 저들에게 파멸에 가까운 타격을 줄 겁니다.",
  ui_story_1017_10171101_52_dialog_content = "잉겔, 네 질문은 정보장교의 직무에 맞지 않는군.",
  ui_story_1017_10171101_53_dialog_content = "다른 용무가 없다면 난 실험을 계속하도록 하지.",
  ui_story_1017_10171101_54_dialog_content = "하지만 교수님...!",
  ui_story_1017_10171101_55_dialog_content = "자신의 생각을 말하기 전에, 먼저 목적을 명확히 해라.",
  ui_story_1017_10171101_56_dialog_content = "잘 모르겠다면 너도 지금 하는 일을 그만두고 내 실험을 자주 보러 오는 게 좋겠군.",
  ui_story_1017_10171101_57_dialog_content = "엄격한 선별 끝에 선택된 실험체가 여기에 오는 목적은 단 하나──",
  ui_story_1017_10171101_58_dialog_content = "신체의 한계를 넘어 암귀를 이기고, 일루미나와 오로리안을 지키는 것, 오직 그것뿐이다.",
  ui_story_1017_10171101_59_dialog_content = "이 실험실에선 매일같이 오로리안이 죽고 있다.\n하지만 암귀가 나타났을 때 모두가 목숨을 잃는 것보다는 훨씬 낫지.",
  ui_story_1017_10171101_60_dialog_content = "내 목적은 한계를 깨나가는 실험을 통해 무기를 연마하는 것이다.\n좋은 데이터가 없다면, 오로리안의 미래도 없다.",
  ui_story_1017_10171101_61_dialog_content = "실험도, 무기도, 데이터도... 교수님이 하시는 모든 것에 저는 경의를 표하고 있습니다...",
  ui_story_1017_10171101_62_dialog_content = "하지만 병사를 희생하는 것에는 찬성할 수 없습니다.\n하물며 실험에 참가한 결과가 무엇인지도 모른 채로는 말입니다...",
  ui_story_1017_10171101_63_dialog_content = "허허, 모두가 모르는 채로 참가한 것은 아니다만.",
  ui_story_1017_10171101_64_dialog_content = "그 여자는 목적을 위해 이 실험의 모든 것을 감당했다. 넌 어떻지?",
  ui_story_1017_10171101_65_dialog_content = "...이건 아니에요... 일루미나의 지금이 있는 건... 이런 실험 덕분이 아니란 말입니다...",
  ui_story_1017_10171101_66_dialog_content = "으윽...!",
  ui_story_1017_10171101_67_dialog_content = "이... 소리...",
  ui_story_1017_10171101_68_dialog_content = "실험이 시작됐군. 그렇다면 너도 두 실험의 격차를 똑똑히 봐 두도록 해라.",
  ui_story_1017_10171101_69_dialog_content = "(안 돼요... 이 소리는...)",
  ui_story_1017_10171101_70_dialog_content = "동일한 신체 기능의 강화라도 결과는 판이하지.",
  ui_story_1017_10171101_71_dialog_content = "왼쪽 실험체는 새로운 「씨앗」을 이식한 후 순간적인 힘이 더 강해졌고,\n더 오래 지속할 수 있게 되었다.",
  ui_story_1017_10171101_72_dialog_content = "반면 오른쪽 실험체는 암귀에게 거의 삼켜져 버렸지.",
  ui_story_1017_10171101_73_dialog_content = "이제 너도 알았겠지. 왜 어떤 대가를 치러서라도 라인하르트를 제거하려 했는지 말이야.",
  ui_story_1017_10171101_74_dialog_content = "왼쪽 실험체는 설마...",
  ui_story_1017_10171101_75_dialog_content = "네가 역사나 진상을 어떻게 생각하든, 세상이란 결국 그런 것이다.",
  ui_story_1017_10171101_76_dialog_content = "우린 그저 이렇게 해서 앞으로 나아갈 수밖에 없다.",
  ui_story_1017_10171101_77_dialog_content = "어둠의 위기 속에서 우린 이렇게 해서라도 걸음을 재촉할 수밖에 없단 말이다.",
  ui_story_1017_10171101_X78_dialog_content = "(머리가... 아파...)",
  ui_story_1017_10171101_78_dialog_content = "교수님, 왼쪽 실험체가 오른쪽 방의 다크매터에 강한 반응을 보이고 있습니다!",
  ui_story_1017_10171101_79_dialog_content = "박사님, 왼쪽 실험체가 오른쪽 방의 다크매터에 강한 반응을 보이고 있습니다!",
  ui_story_1017_10171101_80_dialog_content = "그렇습니다. 그래야 마땅하죠. 「씨앗」과 「씨앗」은 서로 반응하니까요.",
  ui_story_1017_10171101_81_dialog_content = "자, 그럼 그 다음엔 과연 무엇을 할까요...",
  ui_story_1017_10171101_X82_dialog_content = "......",
  ui_story_1017_10171101_82_dialog_content = "교수님, 실험체가 유리를 깨고 오른쪽 방으로 가려고 합니다!",
  ui_story_1017_10171101_83_dialog_content = "박사님, 실험체가 유리를 깨고 오른쪽 방으로 가려고 합니다!",
  ui_story_1017_10171101_84_dialog_content = "음... 문을 열려는 게 아니라 유리를 부수려고 하는군요.",
  ui_story_1017_10171101_85_dialog_content = "좋습니다. 이번에 강화된 건 뇌가 아닌 모양입니다. 이로써 1기 「씨앗」의 결점을 보완했군요.",
  ui_story_1017_10171101_86_dialog_content = "이게... 암귀를 만드는 것과 무슨 차이가 있죠...?",
  ui_story_1017_10171101_87_dialog_content = "암귀를 이기고 싶다면 보통 방법만으로는 불가능해.",
  ui_story_1017_10171101_88_dialog_content = "하지만 전장 밖에선 그도 너와 같은 오로리안 동포다.",
  ui_story_1017_10171101_89_dialog_content = "아뇨, 일루미나는 암귀와 동포가 될 수 없습니다... 즉시 실험을 중지하세요.",
  ui_story_1017_10171101_90_dialog_content = "......",
  ui_story_1017_10171101_91_dialog_content = "교수님, 성공했어요! 실험체가 암귀를 삼키기 시작했어요!",
  ui_story_1017_10171101_92_dialog_content = "율리시스 교수님, 제발... 실험을 멈춰주세요!",
  ui_story_1017_10171101_93_dialog_content = "실험은 이제 막 시작됐을 뿐이다.",
  ui_story_1017_10171101_94_dialog_content = "일루미나의 병사가 암귀를 먹고 있다고요!\n이건 실험 프로세스에 대한 중대한 위반 사항이에요... 당장 그만두세요!",
  ui_story_1017_10171101_95_dialog_content = "내 기억이 맞다면, 그 실험 프로세스는 내가 만들었을 텐데.",
  ui_story_1017_10171101_96_dialog_content = "모든 실험의 목적은 검증과 혁신이다.",
  ui_story_1017_10171101_97_dialog_content = "교수님! 실험체가 이쪽 유리를 두들기고 있어요!",
  ui_story_1017_10171101_98_dialog_content = "(그 살의는... 절 향하고 있는 건가요...?)",
  ui_story_1017_10171101_99_dialog_content = "제발... 실험을 멈춰주세요...",
  ui_story_1017_10171101_100_dialog_content = "교수님, 잉겔 중령의 상태가 이상해요!",
  ui_story_1017_10171101_101_dialog_content = "잉겔, 뭔가 느껴지나?",
  ui_story_1017_10171101_102_dialog_content = "머리가... 너무... 아파요...",
  ui_story_1017_10171101_103_dialog_content = "먼저 돌아가서 쉬도록 해라.",
  ui_story_1017_10171101_104_dialog_content = "기록하세요. 「씨앗」들 사이의 반응 메커니즘과 거리에도 추가적인 확인이 필요합니다.",
  ui_story_1017_10171101_105_dialog_content = "교수님! 유리가...!",
  ui_story_1017_10171101_106_dialog_content = "경비대를 부르세요!",
  ui_story_1017_10171101_107_dialog_content = "으앗! 교수님, 빨리 피하세요──!",
  ui_story_1017_10171101_108_dialog_content = "......",
  ui_story_1017_10171201_1_dialog_content = "더는 전진할 수 없어! 늪이 퍼지는 속도가 너무 빨라!",
  ui_story_1017_10171201_2_dialog_content = "전원 흩어져서 신속하게 후퇴하라!",
  ui_story_1017_10171201_3_dialog_content = "근데 레이스 씨는... 계속 갈 생각인가요?",
  ui_story_1017_10171201_4_dialog_content = "내 부하들이 안에 있어. 무슨 일이 있어도 절대 저들을 저버릴 순 없어.",
  ui_story_1017_10171201_5_dialog_content = "하지만 지금 더스크 타운의 절반 정도가 이미 늪에 덮였어요...",
  ui_story_1017_10171201_6_dialog_content = "그러니까 마을 전체가 덮여버리기 전에 「중심」의 적을 쓰러트려야지.",
  ui_story_1017_10171201_7_dialog_content = "...방금 공격으로 봤을 때, 「중심」 쪽 적의 이동 방향은 갈피를 잡을 수가 없어요.",
  ui_story_1017_10171201_8_dialog_content = "흥, 확실히 복잡한 상황이야. 암귀 무리는 우릴 포위하고 있고,\n자기들은 늪에 숨어서 사방에서 우릴 덮치고 있잖아!",
  ui_story_1017_10171201_9_dialog_content = "놈을 찾으려면 전진하는 수밖에 없어.",
  ui_story_1017_10171201_10_dialog_content = "하지만 이대로라면 더 많은 병사가 희생될 거예요...",
  ui_story_1017_10171201_11_dialog_content = "그 누구의 희생도 헛된 건 없어, PlayerName.\n전사들은 네 애도나 받으려고 희생된 게 아냐!",
  ui_story_1017_10171201_12_dialog_content = "전 그냥...",
  ui_story_1017_10171201_13_dialog_content = "됐어. 여기까지 오면서 모두 이미 그만한 각오는 했으니까.",
  ui_story_1017_10171201_14_dialog_content = "사실 계속 물어보고 싶은 게 있었어요. 레이스 씨 휘하의 일부 병사들은...\n전장에 따로 보내진 이유가 있는 것 같았거든요.",
  ui_story_1017_10171201_15_dialog_content = "...뭘 알아냈는데?",
  ui_story_1017_10171201_16_dialog_content = "그냥 추측이지만...",
  ui_story_1017_10171201_17_dialog_content = "다크매터에 저렇게 강한 반응을 보인다는 건...\n병사들의 몸속에 암귀와 같은 게 들어 있는 거겠죠.",
  ui_story_1017_10171201_18_dialog_content = "아까 그 병사들과 감응했을 때 그 감각...",
  ui_story_1017_10171201_19_dialog_content = "사실 제 몸에 「씨앗」이 심어졌을 때 느낀 적 있었어요...",
  ui_story_1017_10171201_20_dialog_content = "그거라면 병사들이 암귀 쪽으로 향하고, 「중심」의 지휘를 따르는 이유도 설명이 되겠죠...",
  ui_story_1017_10171201_21_dialog_content = "그리고 더스크 타운 쪽 병사들한테는 그런 현상이 없잖아요...",
  ui_story_1017_10171201_22_dialog_content = "그럼 난 어떨 것 같은데?",
  ui_story_1017_10171201_23_dialog_content = "......",
  ui_story_1017_10171201_24_dialog_content = "훗, 사실 병사들이 이변을 일으켰을 때부터 이미 난 우리가 더스크 타운에 온\n진짜 목적이 뭔지 알 수 있었어.",
  ui_story_1017_10171201_25_dialog_content = "더스크 타운을 지원하기 위해서 아니었어요?",
  ui_story_1017_10171201_26_dialog_content = "지금이야말로 지원이 필요한 상황이야. 하지만 봐, 아무도 안 오잖아?",
  ui_story_1017_10171201_27_dialog_content = "......",
  ui_story_1017_10171201_28_dialog_content = "지원 요청에 반응도 없고, 통신도 응답하지 않아... 모든 전투에서 이런 상황이 계속 이어지고 있어.",
  ui_story_1017_10171201_29_dialog_content = "다크매터의 영향으로 신호가 교란된 건 아닐까요?",
  ui_story_1017_10171201_30_dialog_content = "넌 일루미나를 몰라. 일루미나는 준비되지 않은 싸움은 절대 하지 않아.\n다른 의도가 있지 않고선 말이야.",
  ui_story_1017_10171201_31_dialog_content = "우리가 지금 의지할 수 있는 건 우리 자신뿐이야.",
  ui_story_1017_10171201_32_dialog_content = "다만... 내 대원수 지위도 결국 라인하르트와 같은 결말일 거라 생각하면...",
  ui_story_1017_10171201_33_dialog_content = "절대 인정할 수 없어...!",
  ui_story_1017_10171201_34_dialog_content = "레이스 씨, 저도 같이 싸울 거예요...",
  ui_story_1017_10171201_35_dialog_content = "됐어, 지금은 슬픔에 젖을 때가 아냐. 스카이워커호가 뭐 발견한 거 없어?",
  ui_story_1017_10171201_36_dialog_content = "전방 300미터 지점에서 거대한 다크매터 덩어리가 늪 속을 이동하고 있습니다.",
  ui_story_1017_10171201_37_dialog_content = "「중심」의 적이야? 아니면...",
  ui_story_1017_10171201_38_dialog_content = "밀집된 다크매터가 주변으로 산개하고 있습니다. 현 상황에서는 고위 암귀로 추정됩니다.",
  ui_story_1017_10171201_39_dialog_content = "이쪽으로 오고 있는 거야?",
  ui_story_1017_10171201_40_dialog_content = "출몰 지점을 특정하지 못해 이동 방향과 도달 시간을 판단할 수 없습니다.",
  ui_story_1017_10171201_41_dialog_content = "지휘를 하는 녀석은 보여?",
  ui_story_1017_10171201_42_dialog_content = "수색을 계속하겠습니다...",
  ui_story_1017_10171201_43_dialog_content = "고마워, 스카이워커.",
  ui_story_1017_10171201_44_dialog_content = "어라? 레이스 씨는?!",
  ui_story_1017_10171201_45_dialog_content = "그리고 왜 갑자기 암귀가 잔뜩 늘어난 거야?!",
  ui_story_1017_10171201_46_dialog_content = "뭐 좀 나온 거 있어? PlayerName!",
  ui_story_1017_10171201_47_dialog_content = "(잠깐만... 이 감각...)",
  ui_story_1017_10171201_48_dialog_content = "전방에 고위 암귀가 늪 속에서 이동하고 있어요!",
  ui_story_1017_10171201_49_dialog_content = "흥, 봤지? 우리가 공격을 안 해도 어차피 놈들은 우리가 움직이게 만들 생각인 거야!",
  ui_story_1017_10171201_50_dialog_content = "그럼 차라리 정정당당하게 한판 붙는 게 나아!",
  ui_story_1017_10171201_51_dialog_content = "늪 속엔 아마 대규모의 암귀 병력이 잠복 중일 거야. 공격 준비!",
  ui_story_1017_10171201_52_dialog_content = "레이스 씨, 잠깐만요! 늪 속은 위험해요! 들어가면 안 돼요!",
  ui_story_1017_10171201_53_dialog_content = "아니! 꼭 들어가야만 해! 늪에 잡아먹히는 한이 있더라도 반드시 놈을 쓰러트리겠어!",
  ui_story_1017_10171201_54_dialog_content = "각 부대는 즉시 일반 암귀들을 양쪽으로 유도하라!",
  ui_story_1017_10171201_55_dialog_content = "「엔진 7호」는 전방의 암귀를 쓰러트리고, 내가 진격할 길을 열도록!",
  ui_story_1017_10171201_56_dialog_content = "예!",
  ui_story_1017_10171201_57_dialog_content = "흥! 얼마나 대단한 녀석이라고, 어차피 뒤에 숨어나 있는 주제에...",
  ui_story_1017_10171201_58_dialog_content = "대원수님! 서쪽에 암귀가 출현했습니다!",
  ui_story_1017_10171201_59_dialog_content = "대원수님! 동쪽도 있습니다!",
  ui_story_1017_10171201_60_dialog_content = "좌우에서 도발이라... 그럼 이번엔...",
  ui_story_1017_10171201_61_dialog_content = "레이스 씨, 발밑 조심해요!",
  ui_story_1017_10171201_62_dialog_content = "역시나, 네놈 행동 패턴은──",
  ui_story_1017_10171201_63_dialog_content = "단순하기 짝이 없어!",
  ui_story_1017_10171201_64_dialog_content = "대원수님! 괘, 괜찮으십니까?",
  ui_story_1017_10171201_65_dialog_content = "이 정도는... 아무것도 아냐... 안 괜찮을 리가 없잖아..",
  ui_story_1017_10171201_66_dialog_content = "안색이 안 좋아요! 얼른 제 쪽으로 오세요!",
  ui_story_1017_10171201_67_dialog_content = "아니, 내가 녀석을 쳤어...",
  ui_story_1017_10171201_68_dialog_content = "속도가 엄청 빨라요. 늪에서 나오자마자 바로 들어가는 것밖에 못 봤어요.",
  ui_story_1017_10171201_69_dialog_content = "레이스 씨 공격이 먹혔나요?",
  ui_story_1017_10171201_70_dialog_content = "그렇게 단순하지가 않았어. 그 녀석... 왠지...",
  ui_story_1017_10171201_71_dialog_content = "레이스 씨... 몸이 떨리고 있어요!",
  ui_story_1017_10171201_72_dialog_content = "그래, 그 녀석이었어... 마치 날...",
  ui_story_1017_10171201_73_dialog_content = "대원수님! 「엔진 7호」가 왔습니다! 함께 늪을 탈출하십시오!",
  ui_story_1017_10171201_74_dialog_content = "아무도 가까이 오지 마!",
  ui_story_1017_10171201_75_dialog_content = "이 늪은... 녀석의 영역이야.",
  ui_story_1017_10171201_76_dialog_content = "안으로 들어오면... 녀석이...",
  ui_story_1017_10171201_77_dialog_content = "지금 레이스 씨는 이미 안에 있잖아요!",
  ui_story_1017_10171201_78_dialog_content = "(정신을 유지하는 거야! 정신 차려!)",
  ui_story_1017_10171201_79_dialog_content = "얼른 거기서 나와요! 레이스 씨!",
  ui_story_1017_10171201_80_dialog_content = "녀석이 오고 있어... 난... 물러설 수 없어.",
  ui_story_1017_10171201_81_dialog_content = "레이스 씨가 당하면 더스크 타운은 끝장이라구요!",
  ui_story_1017_10171201_82_dialog_content = "난 쓰러지지 않아... 지금 난...",
  ui_story_1017_10171201_83_dialog_content = "힘이... 끝없이 솟구치는 것 같거든...",
  ui_story_1017_10171201_84_dialog_content = "반드시... 녀석을 쓰러트리겠어!",
  ui_story_1017_10171201_85_dialog_content = "그럼 제가 지휘할게요!",
  ui_story_1017_10171201_86_dialog_content = "물러서!",
  ui_story_1017_10171201_87_dialog_content = "10시 쪽은 다크매터가 상대적으로 약해요.\n그쪽을 통해서 암귀의 후방으로 돌아갈 수 있어요!",
  ui_story_1017_10171201_88_dialog_content = "암귀가 네 쪽으로 가고 있어! 물러서라고!",
  ui_story_1017_10171201_89_dialog_content = "뒤쪽으로 다섯 보 지점의 다크매터가 약해요. 계속...",
  ui_story_1017_10171201_90_dialog_content = "(으윽... 몸이 갑자기... 안 움직여...)",
  ui_story_1017_10171201_91_dialog_content = "PlayerName!",
  ui_story_1017_10171201_92_dialog_content = "(발아... 얼른 움직여...! 암귀가 잔뜩 오고 있다고...)",
  ui_story_1017_10171201_93_dialog_content = "PlayerName?!",
  ui_story_1017_10171201_94_dialog_content = "(으윽... 전혀 움직일 수가 없어...)",
  ui_story_1017_10171201_95_dialog_content = "(직접 레이스 씨와 감응해서 지휘하는 수밖에...)",
  ui_story_1017_10171301_1_dialog_content = "또 왔어! 「꿰뚫어라, 우레의 창이여!」",
  ui_story_1017_10171301_2_dialog_content = "(전투가 길어질수록 몸이 점점 더 말을 안 듣는 게 느껴져...)",
  ui_story_1017_10171301_3_dialog_content = "(처음엔 혼란스럽던 감정이 지금은 살육의 쾌감으로 바뀌고 있어...)",
  ui_story_1017_10171301_4_dialog_content = "(이러다간... 설마 정말 저 병사들처럼...)",
  ui_story_1017_10171301_5_dialog_content = "(안 돼!)",
  ui_story_1017_10171301_6_dialog_content = "(쓰러질 순 없어! 이제 막 시작인데 그럴 순 없다고!)",
  ui_story_1017_10171301_7_dialog_content = "야! 조심해!",
  ui_story_1017_10171301_8_dialog_content = "으아아──!",
  ui_story_1017_10171301_9_dialog_content = "정신이 들어?",
  ui_story_1017_10171301_10_dialog_content = "사람이 던져지면 당연히 정신이 들죠!",
  ui_story_1017_10171301_11_dialog_content = "뭐라고?",
  ui_story_1017_10171301_12_dialog_content = "(잠깐만, 지금 말하는 건 PlayerName인데...)",
  ui_story_1017_10171301_13_dialog_content = "(어째서... 이 애가 암귀라는 기분이 드는 거지...?)",
  ui_story_1017_10171301_14_dialog_content = "괜찮아요?",
  ui_story_1017_10171301_15_dialog_content = "응, 괜찮아...",
  ui_story_1017_10171301_16_dialog_content = "(PlayerName... 눈앞에 있는 건 PlayerName 녀석이라고!)",
  ui_story_1017_10171301_17_dialog_content = "레이스 씨!",
  ui_story_1017_10171301_18_dialog_content = "아... 괜찮다니까.",
  ui_story_1017_10171301_19_dialog_content = "그것보다 내가 늪에서 벗어나라고 했잖아!",
  ui_story_1017_10171301_20_dialog_content = "하지만 방금 레이스 씨는 뒤도 안 돌아보고 늪으로 들어갔잖아요. 저 병사들처럼요...",
  ui_story_1017_10171301_21_dialog_content = "......",
  ui_story_1017_10171301_22_dialog_content = "레이스 씨?",
  ui_story_1017_10171301_23_dialog_content = "(레이스 씨 상태가 이상해...)",
  ui_story_1017_10171301_24_dialog_content = "앞쪽에 암귀가 있어. 놈들을 없애겠어!",
  ui_story_1017_10171301_25_dialog_content = "잠깐만요, 암귀가 어디 있다는 거예요?",
  ui_story_1017_10171301_26_dialog_content = "「꿰뚫어라, 우레의 창이여!」",
  ui_story_1017_10171301_27_dialog_content = "레이스 씨... 암귀 같은 건 없어요. 그건 늪이잖아요...",
  ui_story_1017_10171301_28_dialog_content = "「꿰뚫어라, 우레의 창이여!」",
  ui_story_1017_10171301_29_dialog_content = "이...이게 무슨...",
  ui_story_1017_10171301_30_dialog_content = "아무래도 지금은 네가 정신이 덜 깬 모양이네.",
  ui_story_1017_10171301_31_dialog_content = "암귀가 늪에 숨어서 습격할 기회를 노리고 있는 건가요...?",
  ui_story_1017_10171301_32_dialog_content = "(...레이스 씨, 암귀의 행동을 읽자마자 공격하고 있어. 움직임이 제어되지 않는 느낌인데...)",
  ui_story_1017_10171301_33_dialog_content = "아직 내 힘이 남은 동안 제대로 지휘해!",
  ui_story_1017_10171301_34_dialog_content = "알았어요! 1시 방향이요!",
  ui_story_1017_10171301_35_dialog_content = "좋아!",
  ui_story_1017_10171301_36_dialog_content = "레이스 씨, 1시 방향이라니까요?",
  ui_story_1017_10171301_37_dialog_content = "......",
  ui_story_1017_10171301_38_dialog_content = "그쪽이 아니잖아요!",
  ui_story_1017_10171301_39_dialog_content = "PlayerName, 레이스가 암귀 무리 속으로 돌진했습니다.",
  ui_story_1017_10171301_40_dialog_content = "이러다간 암귀들한테 집어삼켜질 거야!",
  ui_story_1017_10171301_41_dialog_content = "(강제 감응!)",
  ui_story_1017_10171301_42_dialog_content = "(늪이야...)",
  ui_story_1017_10171301_43_dialog_content = "(물살이 엄청 빨라... 게다가 방향도 혼란스러워.)",
  ui_story_1017_10171301_44_dialog_content = "(음? 왠지 뭔가가 여길 휘젓는 느낌인데...)",
  ui_story_1017_10171301_45_dialog_content = "(빛이다!)",
  ui_story_1017_10171301_46_dialog_content = "(늪이 위로 흘러서... 그림을 만들기 시작했어...)",
  ui_story_1017_10171301_47_dialog_content = "(이건... 율리시스, 벨리사리아... 그리고 모니터엔...)",
  ui_story_1017_10171301_48_dialog_content = "(제대로 못 봤는데 사라져 버렸잖아... 레이스 씨는 여기 없어.)",
  ui_story_1017_10171301_49_dialog_content = "(앞에 또 빛이 보여!)",
  ui_story_1017_10171301_50_dialog_content = "(...라인하르트 씨야!)",
  ui_story_1017_10171301_51_dialog_content = "(젊은 시절의 라인하르트 씨네... 관중도 있고... 현수막에 적혀 있는 건...)",
  ui_story_1017_10171301_52_dialog_content = "(「일루미나 대원수 최종 심사」... 라인하르트 씨한테 진 거구나...)",
  ui_story_1017_10171301_53_dialog_content = "(어라? 비...?)",
  ui_story_1017_10171301_54_dialog_content = "(여긴 지하성 같은데, 비가 내리다니...)",
  ui_story_1017_10171301_55_dialog_content = "(레이스 씨한테 이 날은 분명히 잊을 수 없는 하루였겠지...)",
  ui_story_1017_10171301_56_dialog_content = "(여긴... 일루미나의 실험실인가...)",
  ui_story_1017_10171301_57_dialog_content = "(율리시스와 사람들이 실험대 주변에 서 있어...)",
  ui_story_1017_10171301_58_dialog_content = "(실험대에 누워 있는 건...)",
  ui_story_1017_10171301_59_dialog_content = "(라인하르트 씨?)",
  ui_story_1017_10171301_60_dialog_content = "(왜 라인하르트 씨인 거지?)",
  ui_story_1017_10171301_61_dialog_content = "(레이스 씨가 아니라?!)",
  ui_story_1017_10171301_62_dialog_content = "(잠깐만... 실험대 옆에 서 있는 건... 율리시스가 아니라 레이스 씨잖아!)",
  ui_story_1017_10171301_63_dialog_content = "(레이스 씨! 제 목소리 들려요?)",
  ui_story_1017_10171301_64_dialog_content = "(......)",
  ui_story_1017_10171301_65_dialog_content = "(레이스 씨는 지금 더스크 타운에서 암귀와 싸우고 있어요! 정신 차려요!)",
  ui_story_1017_10171301_66_dialog_content = "(암귀... 실험대에 올려진 자는 모두 암귀가 돼...)",
  ui_story_1017_10171301_67_dialog_content = "(적이 더스크 타운을 짓밟으려고 해요! 그리고 레이스 씨는 지금 온몸이 상처투성이라구요. 빨리 눈을 떠요!)",
  ui_story_1017_10171301_68_dialog_content = "(왜 라인하르트는 다치지 않는 거지?)",
  ui_story_1017_10171301_69_dialog_content = "(...그래, 왜냐하면 라인하르트는 암귀니까...)",
  ui_story_1017_10171301_70_dialog_content = "(다치지 않는 사람은 없어요! 하지만 지금 레이스 씨는 대원수잖아요!\n병사들한테는 레이스 씨가 필요해요!)",
  ui_story_1017_10171301_71_dialog_content = "(대원수...)",
  ui_story_1017_10171301_72_dialog_content = "(효과가 있었나? 그럼...)",
  ui_story_1017_10171301_73_dialog_content = "(대원수 최종 심사!)",
  ui_story_1017_10171301_74_dialog_content = "(레이스 씨랑 라인하르트 씨의 승부는 아직 안 끝났어요! 얼른 경기장으로 돌아가요!)",
  ui_story_1017_10171301_75_dialog_content = "(라인하르트... 빌어먹을 라인하르트!)",
  ui_story_1017_10171301_76_dialog_content = "(그래요! 라인하르트 씨는 아직 경기장에 있어요! 가서 결판을 내야죠!)",
  ui_story_1017_10171301_77_dialog_content = "(레이스 씨──!)",
  ui_story_1017_10171301_78_dialog_content = "PlayerName, 드디어 정신을 차렸군요.",
  ui_story_1017_10171301_79_dialog_content = "난 괜찮아. 레이스 씨는? 지금 어떤데?",
  ui_story_1017_10171301_80_dialog_content = "의식은 회복한 것으로 보입니다. 다시 암귀를 제압하기 시작했습니다.",
  ui_story_1017_10171301_81_dialog_content = "다행이야!",
  ui_story_1017_10171301_82_dialog_content = "방금처럼 상대의 상황도 모른 채 강제 감응을 하는 건 매우 위험합니다.",
  ui_story_1017_10171301_83_dialog_content = "알아... 근데 급해서 생각할 겨를도 없었고...",
  ui_story_1017_10171301_84_dialog_content = "어쩌면 네가 있으니까 위험하지 않다고 생각한 것 같아.",
  ui_story_1017_10171301_85_dialog_content = "오른쪽 방향을 보십시오. 「강철가시 기사단」이 당신들을 지켜 주었습니다.",
  ui_story_1017_10171301_86_dialog_content = "레오 씨가 와줬구나!",
  ui_story_1017_10171301_87_dialog_content = "당신이 레이스와 감응하고 있을 때 이미 와 있었습니다.",
  ui_story_1017_10171301_88_dialog_content = "고마워, 스카이워커!",
  ui_story_1017_10171301_89_dialog_content = "스카이워커호는 계속해서 안내를 진행하겠습니다.",
  ui_story_1017_10171301_90_dialog_content = "「꿰뚫어라, 우레의 창이여!」",
  ui_story_1017_10171301_91_dialog_content = "너 아까 나한테 무슨 헛소리를 한 거야?",
  ui_story_1017_10171301_92_option_content = "도와주려고 그런 거예요.",
  ui_story_1017_10171301_93_dialog_content = "무사해서 다행이에요!",
  ui_story_1017_10171301_94_dialog_content = "괜한 참견이야.",
  ui_story_1017_10171301_95_option_content = "일부러 그런 말을 한 건 아니에요.",
  ui_story_1017_10171301_96_dialog_content = "의식을 되찾게 도와주려고 그런 것뿐이에요...",
  ui_story_1017_10171301_97_dialog_content = "보면 안 되는 걸 멋대로 보지 마. 알겠어?",
  ui_story_1017_10171301_98_dialog_content = "그래도 평소 말투로 돌아왔네요. 다행이에요!",
  ui_story_1017_10171301_99_dialog_content = "더스크 타운을 지키는 임무는 아직 끝나지 않았어.",
  ui_story_1017_10171301_100_dialog_content = "설령 암귀가 되는 한이 있더라도, 더스크 타운을 지켜낸 암귀가 될 테니까!",
  ui_story_1017_10171301_101_dialog_content = "근위군단, 잘 들어라!",
  ui_story_1017_10171301_102_dialog_content = "이번 전투에서 우린 저마다 불편한 증세를 많게든 적게든 느꼈을 것이다.\n하지만 날 믿어라. 모두 일시적인 문제일 뿐이다.",
  ui_story_1017_10171301_103_dialog_content = "정신을 집중하면 다크매터의 영향을 최소화할 수 있다.",
  ui_story_1017_10171301_104_dialog_content = "약속하겠다. 대열을 이탈한 병사들도 내가 반드시 모두 찾아올 것이다.\n그전까지는 너희들의 힘이 필요하다!",
  ui_story_1017_10171301_105_dialog_content = "이제 부상자, 의식이 불분명한 자는 지금 즉시 일루미나로 돌아가라!",
  ui_story_1017_10171301_106_dialog_content = "그리고 아직 버틸 수 있고, <color=#FFB400>다크매터를 두려워하지 않는</color> 자는 나를 따라 「중심」으로 진격한다!",
  ui_story_1017_10171301_107_dialog_content = "예!",
  ui_story_1017_10171401_1_dialog_content = "충분히 먹었어?",
  ui_story_1017_10171401_2_dialog_content = "아직 멀었다──",
  ui_story_1017_10171401_3_dialog_content = "맛있는 건 당연히 마지막까지 남겨두는 거야. 그나저나 이 「카펫」, 꽤 잘 깔았네.",
  ui_story_1017_10171401_4_dialog_content = "전부 삼킨다──",
  ui_story_1017_10171401_5_dialog_content = "움직이지 마. 마지막 조정 중이니까.",
  ui_story_1017_10171401_6_dialog_content = "이 거지 같은 곳은 실험실보다 열악한 점이 너무 많아서 진행이 느려.",
  ui_story_1017_10171401_7_dialog_content = "『한 오로리안이 계속해서 버티고 있습니다.』",
  ui_story_1017_10171401_8_dialog_content = "걱정할 거 없어. 그 신임 대원수는 머드번들의 마지막 디저트거든.",
  ui_story_1017_10171401_9_dialog_content = "전부 내게 줘라──",
  ui_story_1017_10171401_10_dialog_content = "『그자가 아니라 다른 오로리안입니다. 녀석은 다크매터의 영향을 거의 받지 않았습니다.』",
  ui_story_1017_10171401_11_dialog_content = "새로운 녀석이라고? 얼른 보러 가 보자.",
  ui_story_1017_10171401_12_dialog_content = "......",
  ui_story_1017_10171401_13_dialog_content = "누군가 했네. 싸울 줄도 모르는 멍청한 녀석이잖아.",
  ui_story_1017_10171401_14_dialog_content = "악셀리아는 전쟁 기계입니다. 악셀리아는 계속 싸워 왔습니다.",
  ui_story_1017_10171401_15_dialog_content = "말도 할 줄 알았네? 벙어리가 아니었구나. 그럼 이건 어때?",
  ui_story_1017_10171401_16_dialog_content = "......",
  ui_story_1017_10171401_17_dialog_content = "암귀를 안 죽인다니, 특이하네. 뭘 하자는 건데?",
  ui_story_1017_10171401_18_dialog_content = "「악셀리아는 그 어떤 대가를 치러서라도 라인하르트 대원수를 쓰러트려야 합니다.」",
  ui_story_1017_10171401_19_dialog_content = "아하하하! 율리시스, 고작 이 정도였어? 얜 당신 사활엔 전혀 관심이 없어 보이는데?",
  ui_story_1017_10171401_20_dialog_content = "「악셀리아는 인간으로 살아가야 합니다.」",
  ui_story_1017_10171401_21_dialog_content = "너랑 잡담하고 있을 시간 없어. 머드번들, 식사 시간이야.",
  ui_story_1017_10171401_22_dialog_content = "병사들을 전부 여기 몰아놨네. 잘했어, 나머지는 하고 싶은 대로 해.",
  ui_story_1017_10171401_23_dialog_content = "『예.』",
  ui_story_1017_10171401_24_dialog_content = "......",
  ui_story_1017_10171401_25_dialog_content = "감히 내 부하를 습격해? 죽어!",
  ui_story_1017_10171401_26_dialog_content = "드디어 찾았네. 늪에 빠져버린 줄 알았잖아!",
  ui_story_1017_10171401_27_dialog_content = "대원수님, 악셀리아 중위 소대의 나머지 병사들도 찾았습니다.",
  ui_story_1017_10171401_28_dialog_content = "알겠다. 부상자 현황을 확인하고, 「중심」의 적이 또 습격해 올 수도 있으니 주의하도록.",
  ui_story_1017_10171401_29_dialog_content = "스카이워커, 근처에 혹시 다른 병사가 더 있어?",
  ui_story_1017_10171401_30_dialog_content = "수색 중입니다...",
  ui_story_1017_10171401_31_dialog_content = "......",
  ui_story_1017_10171401_32_dialog_content = "왜 공격만 막을 뿐, 적을 쓰러트리지 않은 거지? 악셀리아.",
  ui_story_1017_10171401_33_dialog_content = "「악셀리아는 그 어떤 대가를 치러서라도 라인하르트 대원수를 쓰러트려야 합니다.」",
  ui_story_1017_10171401_34_dialog_content = "율리시스가 그렇게 말한 건가?",
  ui_story_1017_10171401_35_dialog_content = "「악셀리아는 그 어떤 대가를 치러서라도 라인하르트 대원수를 쓰러트려야 합니다.」",
  ui_story_1017_10171401_36_dialog_content = "...그 임무라면 넌 이미 완수했어. 연합 훈련에서 이미 라인하르트를 쓰러트렸잖아.",
  ui_story_1017_10171401_37_dialog_content = "......",
  ui_story_1017_10171401_38_dialog_content = "다크매터에 크게 영향을 받지는 않은 것 같아요. 근데 상태는 조금 안 좋아 보이네요.",
  ui_story_1017_10171401_39_dialog_content = "악셀리아, 라인하르트가 패배를 인정하기 전에 뭐라고 말했지?",
  ui_story_1017_10171401_40_dialog_content = "라인하르트 대원수는 악셀리아에게 「인간으로 살아가라」고 하셨습니다.",
  ui_story_1017_10171401_41_dialog_content = "흥, 그 녀석...",
  ui_story_1017_10171401_42_dialog_content = "자긴 꼼짝 없이 당해놓고, 그럴싸한 말은 잘도 했네. 또 뭐라고 했어?",
  ui_story_1017_10171401_43_dialog_content = "악셀리아는 두 가지 임무를 완수해야 합니다.",
  ui_story_1017_10171401_44_dialog_content = "「악셀리아는 그 어떤 대가를 치러서라도 라인하르트 대원수를 쓰러트려야 합니다.」",
  ui_story_1017_10171401_45_dialog_content = "「악셀리아는 인간으로 살아가야 합니다.」",
  ui_story_1017_10171401_46_dialog_content = "......",
  ui_story_1017_10171401_47_dialog_content = "악셀리아, 첫 번째 임무는 이미 완수했어. 지금은 두 번째 임무가 네 유일한 임무야.",
  ui_story_1017_10171401_48_dialog_content = "유일한 임무는 「악셀리아는 인간으로 살아가야 합니다」입니다.",
  ui_story_1017_10171401_49_dialog_content = "그래. 암귀를 이겨야 우리가 살 수 있어. 넌 일루미나의 전사고, 살아남을 권리가 있어.",
  ui_story_1017_10171401_50_dialog_content = "악셀리아는 암귀를 이기고 살아남아야 합니다.",
  ui_story_1017_10171401_51_dialog_content = "악셀리아가... 움직이는데요?",
  ui_story_1017_10171401_52_dialog_content = "일단 위험한 상태는 벗어난 것 같아. 완전히 회복되려면 아직 시간이 걸리겠지만.",
  ui_story_1017_10171401_53_dialog_content = "대원수님, 악셀리아 중위의 부대는 다크매터의 영향을 심하게 받아\n전투를 수행할 수 없을 것으로 보입니다.",
  ui_story_1017_10171401_54_dialog_content = "아무래도 「중심」의 적이 있는 거점은 여기서 그리 멀지 않은 모양이야...",
  ui_story_1017_10171401_55_dialog_content = "PlayerName, 너랑 스카이워커호 덕분이야.",
  ui_story_1017_10171401_56_dialog_content = "마지막으로 한 가지 더 부탁할 게 있어. 전투 불능이 된 병사들을 돌려보내 줘.",
  ui_story_1017_10171401_57_dialog_content = "지금요?",
  ui_story_1017_10171401_58_dialog_content = "하지만 늪에 숨은 암귀가 언제 또 나올지 모르잖아요!",
  ui_story_1017_10171401_59_dialog_content = "그리고 「중심」이 우리 쪽으로 점점 다가오는 게 느껴져요!",
  ui_story_1017_10171401_60_dialog_content = "그 이유가 뭔지 알아?",
  ui_story_1017_10171401_61_dialog_content = "뭔데요?",
  ui_story_1017_10171401_62_dialog_content = "「중심」은 날 쫓아오고 있거든.",
  ui_story_1017_10171401_63_dialog_content = "네?",
  ui_story_1017_10171401_64_dialog_content = "지금까지 어떻게 해도 악셀리아 부대를 찾을 수 없었던 건,\n놈들이 이 근처에 거점을 두고 늪으로 우릴 차단했기 때문이야.",
  ui_story_1017_10171401_65_dialog_content = "사방에서 습격을 가해 부대를 교란시킨 건 최후의 공격에 대비해\n시간을 벌고 있었을 뿐이었어.",
  ui_story_1017_10171401_66_dialog_content = "그리고 마지막이 돼서야 날 여기로 유인했어... 훗, 내 공격이 무서웠던 모양이지?",
  ui_story_1017_10171401_67_dialog_content = "근데 「중심」의 적은 왜 그런 짓을 한 거죠?",
  ui_story_1017_10171401_68_dialog_content = "흥, 내 부하를 노리고, 그 뒤에 날 노리고...\n늪 뒤에 숨은 그 녀석은 분명히 일루미나를 무척 증오하고 있겠지.",
  ui_story_1017_10171401_69_dialog_content = "상대가 누군지 알아요?",
  ui_story_1017_10171401_70_dialog_content = "물론이지. 늪의 「중심」을 무너트리면 녀석이 숨을 곳은 이제 없어.",
  ui_story_1017_10171401_71_dialog_content = "전방 500미터에서 거대한 다크매터 덩어리가 이쪽으로 이동 중입니다.",
  ui_story_1017_10171401_72_dialog_content = "레이스 씨, 스카이워커가...",
  ui_story_1017_10171401_73_dialog_content = "발밑을 조심해!",
  ui_story_1017_10171401_74_dialog_content = "레오 씨! 왜 이쪽으로 온 거야?",
  ui_story_1017_10171401_75_dialog_content = "그 암귀, 늪 곳곳에서 모습을 드러냈지만, 움직임은 줄곧 한 방향을 향하고 있었어.",
  ui_story_1017_10171401_76_dialog_content = "그래서 나한테 따지러 온 건가?",
  ui_story_1017_10171401_77_dialog_content = "아니, 더스크 타운은 자신들을 위해 싸우는 모든 동료를 지킨다.",
  ui_story_1017_10171401_78_dialog_content = "당신은 줄곧 병사들의 상황을 걱정해 왔어. 당신이 신뢰할 수 있는 대원수라는 걸 인정할게.",
  ui_story_1017_10171401_79_dialog_content = "이 싸움은 너무 길었어. 이제 함께 끝낼 때가 됐어.",
  ui_story_1017_10171401_80_dialog_content = "바라던 바야. 다 끝나고 나면 우리 승부도 잊지 말라고.",
  ui_story_1017_10171401_81_dialog_content = "물론이지.",
  ui_story_1017_10171401_82_dialog_content = "(힘은 아직 남아 있어... 의식도 뚜렷해...)",
  ui_story_1017_10171401_83_dialog_content = "(부디 이게 마지막으로 내리는 공격 명령이길 바랄게.)",
  ui_story_1017_10171401_84_dialog_content = "PlayerName, 적이 100미터까지 접근했습니다.",
  ui_story_1017_10171401_85_dialog_content = "약 5초 후 당신의 감응 범위에 진입합니다.",
  ui_story_1017_10171401_86_dialog_content = "이렇게 가까이 있는데 모습이 안 보이다니... 감응 능력을 사용하는 수밖에...",
  ui_story_1017_10171401_87_dialog_content = "크어어어──",
  ui_story_1017_10171401_88_dialog_content = "이, 이건 대체...",
  ui_story_1017_10171401_89_dialog_content = "레이스 씨! 입에서 피를 뿜는 적이에요...",
  ui_story_1017_10171401_90_dialog_content = "저 입... 우릴 통째로 삼킬 수 있을 만큼 큰데요...?",
  ui_story_1017_10171401_91_dialog_content = "「엔진 7호」, 엄호하라!",
  ui_story_1017_10171401_92_dialog_content = "이 강풍은... 적의 소행인가...?",
  ui_story_1017_10171401_93_dialog_content = "저, 저기 좀 봐! 늪이 솟아오른 곳에...",
  ui_story_1017_10171401_94_dialog_content = "크어어어!",
  ui_story_1017_10171401_95_dialog_content = "이 다크매터는 아까 공격보다도 더... 괴로운 느낌이에요! 다들 조심해요!",
  ui_story_1017_10171401_96_dialog_content = "대원수님! 이제 어떻게...",
  ui_story_1017_10171401_97_dialog_content = "전방의 병사들이 이미 늪에 휘말렸습니다!",
  ui_story_1017_10171401_98_dialog_content = "......",
  ui_story_1017_10171401_99_dialog_content = "(안 돼... 난 아직...)",
  ui_story_1017_10171401_100_dialog_content = "레이스 씨! 늪이 퍼지고 있어요! 빨리 벗어나요!",
  ui_story_1017_10171401_101_dialog_content = "근위군단──",
  ui_story_1017_10171401_102_dialog_content = "......",
  ui_story_1017_10171401_103_dialog_content = "(명령을 내리는 소리조차... 벌써...)",
  ui_story_1017_10171401_104_dialog_content = "다른 사람들은... 모두 늪 밖으로...",
  ui_story_1017_10171401_105_dialog_content = "나한테서... 떨어져...",
  ui_story_1017_10171401_106_dialog_content = "형제들이여! 날 따라 늪으로 돌격한다! 일루미나의 철수를 엄호하라!",
  ui_story_1017_10171401_107_dialog_content = "대원수! 정신 차려!",
  ui_story_1017_10171401_108_dialog_content = "나한테서 떨어지라고!",
  ui_story_1017_10171401_109_dialog_content = "......",
  ui_story_1017_10171401_110_dialog_content = "레이스 씨! 하지만 지금 그 몸으로는 더는 무리하면 안 돼요!",
  ui_story_1017_10171401_111_dialog_content = "기사... 내 부하들을... 부탁한다...",
  ui_story_1017_10171401_112_dialog_content = "암귀든... 다른 무엇이든... 난 절대로... 지지 않아...",
  ui_story_1017_10171401_113_dialog_content = "그렇다면...",
  ui_story_1017_10171401_114_dialog_content = "PlayerName! 말에 타라!",
  ui_story_1017_10171401_115_dialog_content = "(또 늪에 들어간다면... 레이스 씨는...)",
  ui_story_1017_10171401_116_dialog_content = "레이스 씨──! 잊지 마요! 레이스 씨랑 라인하르트 씨의 싸움은 아직 안 끝났잖아요!",
  ui_story_1017_10171401_117_dialog_content = "!!!",
  ui_story_1017_10171401_118_dialog_content = "(정신을 집중하자...)",
  ui_story_1017_10171401_119_dialog_content = "(이건...)",
  ui_story_1017_10171401_120_dialog_content = "(나... 대원수 레이스의... 전쟁이야...)",
  ui_story_1017_10171402_1_dialog_content = "<color=#e8d9bb>한편, 이미 늪으로 뒤덮인 더스크 타운...</color>",
  ui_story_1017_10171402_2_dialog_content = "단장님! 방어선은 이미 무너졌고, 늪이 더스크 타운으로 흘러들어 주민들이 혼란에 빠졌습니다!",
  ui_story_1017_10171402_3_dialog_content = "...일루미나의 대원수도 늪에 휘말렸다...",
  ui_story_1017_10171402_4_dialog_content = "우선 주민들을 의료원으로 데려가라. 우린 수색을 계속한다.",
  ui_story_1017_10171402_X1_dialog_content = "도망쳐! 진흙탕이 마을로 쏟아져 들어오고 있어!",
  ui_story_1017_10171402_X2_dialog_content = "어떻게 이런... 우리 아이... 아이는 어디 있죠?!",
  ui_story_1017_10171402_X3_dialog_content = "조셀린 언니는 아직 전장에 있는데...",
  ui_story_1017_10171402_X4_dialog_content = "방어선은 이미 무너졌고, 늪이 더스크 타운으로 흘러들어 주민들이 혼란에 빠졌습니다!",
  ui_story_1017_10171402_X5_dialog_content = "단장님은 아직 더스크 타운 밖에 계셔... 어서 단장님께 알려야 해!",
  ui_story_1017_10171402_5_dialog_content = "대원수님──!",
  ui_story_1017_10171402_6_dialog_content = "레이스 씨! 레...",
  ui_story_1017_10171402_7_dialog_content = "PlayerName, 버틸 수 있겠어?",
  ui_story_1017_10171402_8_dialog_content = "괜찮아... 대신 전투가 너무 길어져서, 당장은 감응 능력을 쓸 수 없을 것 같아.",
  ui_story_1017_10171402_9_dialog_content = "이미 이 근처는 전부 수색했다...",
  ui_story_1017_10171402_10_dialog_content = "아까 암귀가 쓰러질 때까지 레이스 씨의 위치를 전혀 감응할 수 없었어....",
  ui_story_1017_10171402_11_dialog_content = "스카이워커가 마지막으로 봤을 때 레이스 씨는 적의 입 근처에 있었고, 온몸이 진흙투성이였어...",
  ui_story_1017_10171402_12_dialog_content = "내 잘못이야... 내가 제대로 못 따라가서...",
  ui_story_1017_10171402_13_dialog_content = "초점 없는 눈으로 적한테 달려드는 걸 보고만 있었어... 게다가 지칠 대로 지쳤으면서...",
  ui_story_1017_10171402_14_dialog_content = "일부러 암귀를 우리 반대 방향으로 유인했어...",
  ui_story_1017_10171402_15_dialog_content = "네 잘못이 아냐. 서로 협력해야만 적을 이길 수 있는 거니까.",
  ui_story_1017_10171402_16_dialog_content = "다만 모두를 지키려고 「엔진 7호」에게 우리가 오는 걸 막게 할 줄이야...",
  ui_story_1017_10171402_17_dialog_content = "그런 위험한 짓을 하다니... 대원수나, 그 부하들이나, 너무 극단적이잖아.",
  ui_story_1017_10171402_18_dialog_content = "......",
  ui_story_1017_10171402_19_dialog_content = "악셀리아는 살아남았습니다. 하지만 레이스 대원수님을 찾을 수 없었습니다.",
  ui_story_1017_10171402_20_dialog_content = "악셀리아, 무사해서 다행이야...",
  ui_story_1017_10171402_21_dialog_content = "레이스 대원수님은 일루미나의 전사입니다. 「일루미나의 전사는 살아남을 권리가 있습니다」.",
  ui_story_1017_10171402_22_dialog_content = "......",
  ui_story_1017_10171402_23_dialog_content = "속도를 높여서 외곽 구역을 더 살펴보자.",
  ui_story_1017_10171402_24_dialog_content = "새로운 적이 공격해 온다면 대원수를 찾기가 더 힘들어져!",
  ui_story_1017_10171402_25_dialog_content = "응!",
  ui_story_1017_10171402_26_dialog_content = "PlayerName, 더스크 타운에서 레이스의 흔적은 찾을 수 없었습니다.",
  ui_story_1017_10171402_27_dialog_content = "수색 시간으로 추산했을 때, 레이스가 이미 사망했을 확률은 99%입니다.",
  ui_story_1017_10171402_28_dialog_content = "말도 안 돼...",
  ui_story_1017_10171402_29_dialog_content = "그럴 리가 없어!",
  ui_story_1017_10171402_30_dialog_content = "<size=50>레이스 씨!!!</size>",
  ui_story_1017_10171501_1_dialog_content = "(여긴... 해가 진 더스크 타운인가?)",
  ui_story_1017_10171501_2_dialog_content = "(하지만 나 혼자밖에 없어...)",
  ui_story_1017_10171501_3_dialog_content = "(흥, 또 낙오되다니. 라인하르트 그 녀석은 여전히 강하잖아...)",
  ui_story_1017_10171501_4_dialog_content = "(몸이... 무거워. 전혀 힘이 들어가질 않아...)",
  ui_story_1017_10171501_5_dialog_content = "(이 지하성... 너무 조용해서... 기분이 나쁠 정도야...)",
  ui_story_1017_10171501_6_dialog_content = "(등에 있는 건... 제길...)",
  ui_story_1017_10171501_7_dialog_content = "(라인하르트한테 지고 나서, 녀석들은 내 몸에 쇠사슬을 묶었어...)",
  ui_story_1017_10171501_8_dialog_content = "(이게 최종 대결에서 진 대가인가...)",
  ui_story_1017_10171501_9_dialog_content = "(싸움은... 아직 끝나지 않았는데...)",
  ui_story_1017_10171501_10_dialog_content = "(난 저런 물건 따위에... 당하지 않아!)",
  ui_story_1017_10171501_11_dialog_content = "(당하지 않는다고!)",
  ui_story_1017_10171501_12_dialog_content = "(재결투를 신청하겠어...)",
  ui_story_1017_10171501_13_dialog_content = "(관중석에서는 모두 내 이름을 외치고 있어...)",
  ui_story_1017_10171501_14_dialog_content = "(내 뇌창을... 군복을... 돌려줘...)",
  ui_story_1017_10171501_15_dialog_content = "(난... 일루미나의 대원수가 될 거라고...)",
  ui_story_1017_10171501_16_dialog_content = "(그 누구도... 날 막을 수 없어...)",
  ui_story_1017_10171501_17_dialog_content = "며칠 전, 일루미나 상부의 비밀 좌담회...",
  ui_story_1017_10171501_18_dialog_content = "데려왔습니다.",
  ui_story_1017_10171501_19_dialog_content = "앉아.",
  ui_story_1017_10171501_20_dialog_content = "용건만 말해. 아직 임무 수행 중이니까.",
  ui_story_1017_10171501_21_dialog_content = "앉으라고.",
  ui_story_1017_10171501_22_dialog_content = "......",
  ui_story_1017_10171501_23_dialog_content = "너한테 일루미나의 대원수가 되라고 한다면, 어쩔 생각이니?",
  ui_story_1017_10171501_24_dialog_content = "내가? 어째서?",
  ui_story_1017_10171501_25_dialog_content = "넌 그걸 원하고, 일루미나 연방도 네가 필요하거든.",
  ui_story_1017_10171501_26_dialog_content = "이해할 수 없어. 라인하르트가 뭘 잘못했는데?",
  ui_story_1017_10171501_27_dialog_content = "재판 때 전부 똑똑히 들었을 텐데. 너도 자리에 있었잖아.",
  ui_story_1017_10171501_28_dialog_content = "그건 진실이 아니잖아. 대체 당신들 목적이 뭐야?",
  ui_story_1017_10171501_29_dialog_content = "눈에 보이는 게 꼭 진실은 아니란다. 좀 더 현실적으로 생각하는 건 어떠니?",
  ui_story_1017_10171501_30_dialog_content = "잘 생각해 봐. 네가 대원수가 될지, 아니면 다른 사람에게 맡길지.",
  ui_story_1017_10171501_31_dialog_content = "다른 세 사람은 알아?",
  ui_story_1017_10171501_32_dialog_content = "결정은 네가 하면 돼. 신중하게 생각하길 바랄게.",
  ui_story_1017_10171501_33_dialog_content = "......",
  ui_story_1017_10171501_34_dialog_content = "율리시스, 할 말 있는 거 아니었어?",
  ui_story_1017_10171501_35_dialog_content = "당신은 각 방면으로 뛰어난 조건을 가지고 있습니다. 다만 신체적 소질이 유일한 결점이지요.",
  ui_story_1017_10171501_36_dialog_content = "대원수가 된다면 제가 그 결점을 보완해 드리겠습니다.",
  ui_story_1017_10171501_37_dialog_content = "......",
  ui_story_1017_10171501_38_dialog_content = "뭘 하려고?",
  ui_story_1017_10171501_39_dialog_content = "걱정할 필요 없습니다. 라인하르트와 마찬가지로 약간의 실험에 참가하면 될 뿐입니다.",
  ui_story_1017_10171501_40_dialog_content = "신체 기능을 개조해서 일루미나 최강의 전사가 되는 것이지요.",
  ui_story_1017_10171501_41_dialog_content = "라인하르트가 개조를 받았다고?!",
  ui_story_1017_10171501_42_dialog_content = "의외인가?",
  ui_story_1017_10171501_43_dialog_content = "(라인하르트가?!)",
  ui_story_1017_10171501_44_dialog_content = "(강대... 불패... 넘을 수 없는 높은 벽...!)",
  ui_story_1017_10171501_45_dialog_content = "(...전부 가짜였어!)",
  ui_story_1017_10171501_46_dialog_content = "라인하르트가 「인공 태양 프로젝트」에 참여했을 땐 아직 어렸어.",
  ui_story_1017_10171501_47_dialog_content = "하지만 진상을 알게 된 후에도 네게 말하지 않는 것도 당연해.\n누구나 자신의 힘이 타고난 것이길 바라거든.",
  ui_story_1017_10171501_48_dialog_content = "......",
  ui_story_1017_10171501_49_dialog_content = "자신이 타고난 대원수인지 알고 싶다면, 그걸 증명할 기회가 필요해.",
  ui_story_1017_10171501_50_dialog_content = "그리고 지금 그 기회는 네 눈앞에 있어.",
  ui_story_1017_10171501_51_dialog_content = "무슨 기회?",
  ui_story_1017_10171501_52_dialog_content = "조만간 더스크 타운 주변에서 대규모의 전쟁이 벌어질 거야.\n난 너라면 그 전쟁을 승리로 이끌 거라고 믿어.",
  ui_story_1017_10171501_53_dialog_content = "물론 이길 수 있지. 하지만 난 내 방식으로 이길 거야.",
  ui_story_1017_10171501_54_dialog_content = "지금 당장 대답할 필요는 없어.",
  ui_story_1017_10171501_55_dialog_content = "한 마디 덧붙이죠. 오래전 자신이 했던 말을 기억하고 있습니까?",
  ui_story_1017_10171501_56_dialog_content = "최종 대결에서 진 그날, 당신은 대회장 구석에 서 있었지요.",
  ui_story_1017_10171501_57_dialog_content = "전 당신에게 지지 말았어야 했다고 말했고, 당신은 이렇게 대답했습니다.",
  ui_story_1017_10171501_58_dialog_content = "신체의 한계를 뛰어넘을 수 있다면... 어떤 대가라도 치르겠어!",
  ui_story_1017_10171501_59_dialog_content = "그리고 이게 제 답입니다.",
  ui_story_1017_10171501_60_dialog_content = "......",
  ui_story_1017_10171501_61_dialog_content = "<color=#e8d9bb>레이스는 바튼, 히이로, 시로나에게 비밀 좌담회에서의 일을 말했다.</color>",
  ui_story_1017_10171501_62_dialog_content = "......",
  ui_story_1017_10171501_63_dialog_content = "위원회 그 개자식들이 무슨 짓이라고 안 하겠어?",
  ui_story_1017_10171501_64_dialog_content = "율리시스 쪽 사람이 대원수가 되지만 않는다면, 아직 기회는 있을 겁니다.",
  ui_story_1017_10171501_65_dialog_content = "바튼, 어떻게 생각해?",
  ui_story_1017_10171501_66_dialog_content = "할 말 없다. 라인하르트 일을 이대로 그냥 넘어갈 생각은 없으니까.",
  ui_story_1017_10171501_67_dialog_content = "그 자리를 누가 대신할지는 상관 안 해.",
  ui_story_1017_10171501_68_dialog_content = "어차피 라인하르트 외에 난 그 누구의 명령도 들을 생각 없다고.",
  ui_story_1017_10171501_69_dialog_content = "아까 불려 간 게 너였으면?",
  ui_story_1017_10171501_70_dialog_content = "흥! 율리시스가 내 몸에 수술을 하게 둘 것 같아? 내가 놈을 죽여버렸을 거다.",
  ui_story_1017_10171501_71_dialog_content = "만약 대원수님의 일이 정말 사실이라면, 네가 뭘 어쩔 수 있는 문제가 아냐.",
  ui_story_1017_10171501_72_dialog_content = "지금 어둠의 밑바닥 쪽 움직임은 점점 더 활발해지고 있습니다.\n곧 상부에서도 움직이기 시작할 겁니다.",
  ui_story_1017_10171501_73_dialog_content = "지휘를 맡을 대원수가 공석인 상황에서 암귀가 침입한다면, 대응은 쉽지 않을 겁니다.",
  ui_story_1017_10171501_74_dialog_content = "레이스, 당신이 할 수 있겠어요?",
  ui_story_1017_10171501_75_dialog_content = "라인하르트도 대원수가 되었을 때 아무것도 두려워하지 않았어. 난 더 무서울 게 없다고.",
  ui_story_1017_10171501_76_dialog_content = "네가 괴물이 되면 어쩌려고?",
  ui_story_1017_10171501_77_dialog_content = "그렇게 된다면 부탁 하나 할게. 라인하르트를 데리고 와서 직접 날 죽이라고 해.",
  ui_story_1017_10171501_78_dialog_content = "정말... 영문 모를 소리만 하는군.",
  ui_story_1017_10171501_79_dialog_content = "그런 소리 하지 마. 살아서 돌아오면 당연히 대원수님을 만날 수 있을 테니까.",
  ui_story_1017_10171501_80_dialog_content = "맞아요. 당신이 직접 가서 만나세요.",
  ui_story_1017_10171501_81_dialog_content = "잠깐만... 지금 내가 라인하르트 얘기한 건 농담이 아냐.",
  ui_story_1017_10171501_82_dialog_content = "그리고 우리 중에서 그걸 할 수 있는 건 너뿐이야.",
  ui_story_1017_10171501_83_dialog_content = "그 말은...",
  ui_story_1017_10171501_84_dialog_content = "맞아. 이클립스가 움직이면 시로나와 바튼은 즉시 전장으로 돌아가 대기해야만 해.",
  ui_story_1017_10171501_85_dialog_content = "방어선이 위험해지기 전까지 난 네 지원군을 마지막까지 남겨둘 거야.",
  ui_story_1017_10171501_86_dialog_content = "다시 말해서 싸움이 치열해질수록 우리 기회는 커질 거야.",
  ui_story_1017_10171501_87_dialog_content = "그래서야 돌아오는 건 감옥행 아니면 죽음뿐인데, 레이스, 너 진심이냐?",
  ui_story_1017_10171501_88_dialog_content = "그래. 다른 방법은 없다고 생각해.",
  ui_story_1017_10171501_89_dialog_content = "그럼 「계명성 프로젝트」는 어쩌려고?",
  ui_story_1017_10171501_90_dialog_content = "...솔직히 아직 잘 모르겠어.",
  ui_story_1017_10171501_91_dialog_content = "그래도 믿어줘. 위험할수록 난 더 정확한 판단을 할 수 있거든.",
  ui_story_1017_10171501_92_dialog_content = "진짜냐?",
  ui_story_1017_10171501_93_dialog_content = "아무튼 나와 함께 싸워서 일루미나가 망신당할 일은 없을 거야.",
  ui_story_1017_10171501_94_dialog_content = "<color=#e8d9bb>다음 날...</color>",
  ui_story_1017_10171501_95_dialog_content = "상태는 어떻습니까?",
  ui_story_1017_10171501_96_dialog_content = "아무 느낌 없어.",
  ui_story_1017_10171501_97_dialog_content = "이제 곧 의식이 흐려질 겁니다.",
  ui_story_1017_10171501_98_dialog_content = "다시 눈을 떴을 때 이 세상은 당신에게 훨씬 더 공평하게 바뀌어 있겠지요.",
  ui_story_1017_10171501_99_dialog_content = "공평...",
  ui_story_1017_10171501_100_dialog_content = "강자는 약자를 발판 삼아 위로 올라가고, 약자는 세상이 불공평하다고 외칠 수밖에 없죠.",
  ui_story_1017_10171501_101_dialog_content = "사람들은 암귀가 잔인무도하다고 비난하지만, 사실 그저 자신이 강하지 않을 뿐입니다.",
  ui_story_1017_10171501_102_dialog_content = "당신이 라인하르트를 이기고 싶어 하는 것도 마찬가지지요.",
  ui_story_1017_10171501_103_dialog_content = "수술이 끝나고 나면, 당신들의 대결은 훨씬 더 공평해질 겁니다.",
  ui_story_1017_10171501_104_dialog_content = "(훨씬 더 공평한... 대결...)",
  ui_story_1017_10171501_105_dialog_content = "(한때 난 목표를 위해서라면 그 어떤 대가도 치를 수 있다고 생각했어.)",
  ui_story_1017_10171501_106_dialog_content = "(하지만 날카로운 기계가 내 몸을 찌를 때, 난 마치 내 손으로 직접 이 몸을\n해체하는 기분이 들었어.)",
  ui_story_1017_10171501_107_dialog_content = "(내 야심과 오기까지 함께 산산조각나는 듯했지.)",
  ui_story_1017_10171501_108_dialog_content = "(그동안 내가 해왔던 모든 선택들은 마치 물에 빠진 자의 몸부림 같았어...)",
  ui_story_1017_10171501_109_dialog_content = "(하지만 어둠은 힘차게 밀려왔고, 난 점점 깊이 빠져들었지...)",
  ui_story_1017_10171501_110_dialog_content = "(계속 발버둥 쳐야 하는 걸까. 이게 내가 정말 원했던 결과일까.)",
  ui_story_1017_10171501_111_dialog_content = "(훨씬 더 공평한... 대결... 확실히 그럴지도 모르지.)",
  ui_story_1017_10171501_112_dialog_content = "(하지만 그 공평은...)",
  ui_story_1017_10171501_113_dialog_content = "(너무 늦게 찾아왔어...)",
  ui_story_1018_10180101_1_dialog_content = "<color=#e8d9bb>어둠의 밑바닥, 눈에 띄지 않는 한 장소...</color>",
  ui_story_1018_10180101_2_dialog_content = "대장님... 아까 제가 그 <color=#FFB400>초록빛을 내는 암귀</color>한테 당하지 않아서 정말 다행입니다!",
  ui_story_1018_10180101_3_dialog_content = "오는 길에 커다란 얼음기둥과 기괴한 모양의 고드름이 있던데요.\n설마 영원한 어둠의 땅이 이런 환경일 줄은 상상도 못 했습니다...",
  ui_story_1018_10180101_4_dialog_content = "하지만 우리 임무는 「가디언 1호」의 코어를 추적하는 건데,\n왜 여기 숨어서 암귀를 관찰해야 하는 거죠?",
  ui_story_1018_10180101_5_dialog_content = "쉿! 조용히 해!",
  ui_story_1018_10180101_6_dialog_content = "아... 전 아까 대장님이 엄청 흥분하시길래, <color=#FFB400>암귀의 본거지</color>라도 찾으신 줄 알았죠...",
  ui_story_1018_10180101_7_dialog_content = "하지만 여긴 <color=#FFB400>평원</color>이고, 일정 거리마다 암귀들이 모여있을 뿐인데요...",
  ui_story_1018_10180101_8_dialog_content = "대체 녀석들을 관찰하는 게 무슨 의미가 있는지 도저히 모르겠네요.",
  ui_story_1018_10180101_9_dialog_content = "흐음~ 그건 네 사고방식이 암귀처럼 단순하다는 뜻이야.",
  ui_story_1018_10180101_10_dialog_content = "돌아가면 어디 가서 내 대원이었다고 말하지 마!",
  ui_story_1018_10180101_11_dialog_content = "하아? 그건 또 무슨...",
  ui_story_1018_10180101_12_dialog_content = "추적의 요령은 주도권을 가져오는 거야. 다시 말해서 적의 생각을 읽는 거지.",
  ui_story_1018_10180101_13_dialog_content = "코어를 가져간 그 암귀는 어떻게든 우릴 이상한 곳에 발이 묶이게 만들 생각이었겠지.\n다시 말해서 여길 못 오게 만들겠다는 뜻이잖아?",
  ui_story_1018_10180101_14_dialog_content = "물건을 훔친 도둑놈이 제일 싫어하는 건 자기 아지트를 남한테 들키는 거야.",
  ui_story_1018_10180101_15_dialog_content = "그리고 여긴 겉보기엔 그냥 평원이지만, 이렇게 많은 암귀들이 지키고 있잖아?\n그러니까 이클립스한테 아주 중요한 장소인 게 분명해.",
  ui_story_1018_10180101_16_dialog_content = "그럼... 저 암귀 무리들은 대체 뭘 지키고 있는 걸까요?",
  ui_story_1018_10180101_17_dialog_content = "내 추측이 맞다면 아마 「가디언 1호」의 코어만큼이나 중요한 물건일 거야.",
  ui_story_1018_10180101_18_dialog_content = "자, 이걸 봐...",
  ui_story_1018_10180101_19_dialog_content = "대장님! 암귀가 갑자기 막 움직이기 시작했습니다!",
  ui_story_1018_10180101_20_dialog_content = "어때? 「가디언 1호」의 코어랑 똑같이 반응이 있지?",
  ui_story_1018_10180101_21_dialog_content = "역시 뭔가 큰일을 꾸미고 있는 거야.",
  ui_story_1018_10180101_22_dialog_content = "그럼 우리가 「가디언 1호」의 코어 외에도 의외의 수확을 얻을 수 있다는 겁니까?",
  ui_story_1018_10180101_23_dialog_content = "후후, 벨리사리아한테 깜짝 선물을 주는 것도 재미있지 않겠어?",
  ui_story_1018_10180101_24_dialog_content = "역시 대장님은 정찰의 달인이시군요!",
  ui_story_1018_10180101_25_dialog_content = "근데... 전 그 전에 우리가 먼저 암귀한테 당할까 걱정인데요...",
  ui_story_1018_10180101_26_dialog_content = "자신감을 좀 가져. 우리가 타고 있는 건 어둠의 밑바닥 환경과 거의 동화돼 있다구.",
  ui_story_1018_10180101_27_dialog_content = "이 열차 외부 도장은 특수 가공이 돼 있어서 주변 환경에 완전히 녹아들 수 있어.",
  ui_story_1018_10180101_28_dialog_content = "너흴 대원으로 뽑은 것도 루미나의 기척이 약해서 암귀한테 쉽게 발견되지 않아서고 말이야.",
  ui_story_1018_10180101_29_dialog_content = "아, 설마 너희들 그거 때문에 루미나틱스 단련을 못 하는 건 아니지...?",
  ui_story_1018_10180101_30_dialog_content = "휴... 전에 제 상관이 그러더군요. 전 평생 운전병밖에 못 할 거라고 말이죠.",
  ui_story_1018_10180101_31_dialog_content = "에이, 그냥 해본 소리였어~ 돌아가면 그 상관에게 말해.\n넌 나랑 어둠의 밑바닥 깊은 곳까지 들어가 본 운전병이라구~",
  ui_story_1018_10180101_32_dialog_content = "아무튼 내 경험으로 보면 어둠의 밑바닥에 가까워질수록 오히려 안전해졌어.",
  ui_story_1018_10180101_33_dialog_content = "대장님... 진짜로 전에 이클립스 쪽 사람이었다가 배신하고 일루미나에 오신 건 아니시죠?",
  ui_story_1018_10180101_34_dialog_content = "질문이 틀렸잖아.\n전에 일루미나 사람이었다가 지금 배신하고 이클립스에 들어간 거 아니냐고 물어봐야지.",
  ui_story_1018_10180101_35_dialog_content = "......",
  ui_story_1018_10180101_36_dialog_content = "너흰 천천히 접근하면서 날 엄호해. 최대한 가볍게 움직이고.",
  ui_story_1018_10180101_37_dialog_content = "난 「가디언 1호」의 코어랑 비슷한 물건이 대체 뭔지 좀 보고 올 테니까.",
  ui_story_1018_10180101_38_dialog_content = "예, 대장님. 그리고 지금 좌표는 후방의 추적 소대에 보내야 할까요?",
  ui_story_1018_10180101_39_dialog_content = "그건 그쪽이 위험에서 벗어난 다음에 생각하자... 지금은 일이 잘 안 풀리고 있는 것 같으니까.",
  ui_story_1018_10180101_40_dialog_content = "<color=#e8d9bb>백야성 본성</color>",
  ui_story_1018_10180101_41_dialog_content = "성주님, 지원군이 그저 백야 요새만 지킨다면, 더스크 타운에 가는 의도는 무엇인지...",
  ui_story_1018_10180101_42_dialog_content = "일루미나의 새로운 부대가 어떻게 조직되었는지 알고 있나?",
  ui_story_1018_10180101_43_dialog_content = "그건 왜 물어보시는 거죠?",
  ui_story_1018_10180101_44_dialog_content = "봐라.",
  ui_story_1018_10180101_45_dialog_content = "이건... 더스크 타운 백야 교구의 긴급 서한...? 하지만 발신인이 안 적혀 있네요.",
  ui_story_1018_10180101_46_dialog_content = "「늪은 더스크 타운의 보루를 무너트렸고, 암귀는 학살을 벌이고 있습니다.\n일루미나군과 기사단이 협력하여 맞서고 있으나, 그 효과는 미미한 상황입니다.」",
  ui_story_1018_10180101_47_dialog_content = "「일루미나의 병사들은 고전을 면치 못했고, 심각한 피해를 입었습니다.\n대원수는 지금도 행방이 묘연하고... 전장을 지키고 있는 건 기사단뿐입니다.」",
  ui_story_1018_10180101_48_dialog_content = "「의료원에는 부상자가 넘치고, 물자는 부족합니다. 백성들의 목숨이 경각에 달려 있습니다...」",
  ui_story_1018_10180101_49_dialog_content = "...대원수가 행방불명이라니... 어떻게 그런 일이 가능한 거죠?!",
  ui_story_1018_10180101_50_dialog_content = "일루미나 연방이 전쟁에서 패해본 적이 없는 것은 아니다.\n허나 더스크 타운의 국면은 나로서도 처음 보는 일이다.",
  ui_story_1018_10180101_51_dialog_content = "그럼에도 일루미나 연방의 다른 군단은 여전히 자난성을 지키고 있고,\n방어선을 넘으려 하지 않는다.",
  ui_story_1018_10180101_52_dialog_content = "저들은 애초에 더스크 타운을 도울 생각이 전혀 없는 것이다.\n그저 새 대원수 취임을 빌미로 최신 군사 기술의 힘을 검증하려는 것뿐이지.",
  ui_story_1018_10180101_53_dialog_content = "이대로 가면 새 부대는 이번 검증의 희생양이 될 것이다.",
  ui_story_1018_10180101_54_dialog_content = "성주님! 그걸 진작부터 알고 계셨던 건가요?!",
  ui_story_1018_10180101_55_dialog_content = "이 또한 그저 역사의 반복일 뿐이다.\n일루미나 연방이 행하는 일은 단 한 번도 그 초심을 저버린 적이 없었다.",
  ui_story_1018_10180101_56_dialog_content = "그럼 지금 전선에서 싸우고 있는 병사들은 어떻게 되는 거죠?",
  ui_story_1018_10180101_57_dialog_content = "일루미나는 제쳐 두더라도, 우리 백야성의 지원군은 더스크 타운 백성들의\n안전을 지켜야 한다고 생각합니다.",
  ui_story_1018_10180101_58_dialog_content = "생각 중이다.",
  ui_story_1018_10180101_59_dialog_content = "...결단이 늦어질수록 더스크 타운뿐만 아니라, 백야성 지상의 마을도 영향을 받습니다!",
  ui_story_1018_10180101_60_dialog_content = "<size=45>생각 중이라고 하였다.</size>",
  ui_story_1018_10180101_61_dialog_content = "......",
  ui_story_1018_10180101_62_dialog_content = "성주님, 섀도우마스터 이스타반의 사자가 알현을 청하고 있습니다.",
  ui_story_1018_10180101_63_dialog_content = "들라 하라.",
  ui_story_1018_10180101_64_dialog_content = "역시 이 부유섬은 예나 지금이나 「적막」하군요~ 성주님, 카렌 전하, 인사드립니다.",
  ui_story_1018_10180101_65_dialog_content = "「소란스러운 도시」에서 온 사자여, 무슨 일인가.",
  ui_story_1018_10180101_66_dialog_content = "오, 저한테 사자 신분도 있었던 겁니까~?",
  ui_story_1018_10180101_67_dialog_content = "전 그저 이스타반 님의 부탁을 받아 말을 전해드리러 왔을 뿐입니다.",
  ui_story_1018_10180101_68_dialog_content = "성주님께서도 지금 더스크 타운의 전투에 관심을 가지고 계시겠지요.",
  ui_story_1018_10180101_69_dialog_content = "하지만 지원군을 파견하셨으면서 주변 마을의 안위에는 관심이 없으신데, 이유가 뭘까요?",
  ui_story_1018_10180101_70_dialog_content = "이스타반이 그리 말하던가.",
  ui_story_1018_10180101_71_dialog_content = "음... 제가 살짝 다듬긴 했는데요.",
  ui_story_1018_10180101_72_dialog_content = "성주님께선 모르시겠지만, 사실 더스크 타운에서 온 손님 한 분이 성주님을 찾아오는 길에\n마침 이스타반 님과 우연히 만났는데 서로 말이 잘 통해서...",
  ui_story_1018_10180101_73_dialog_content = "상황 설명을 마쳤을 때쯤엔 더스크 타운이 이미 더 엉망이 됐다더군요.",
  ui_story_1018_10180101_74_dialog_content = "그 손님이란 사람, 자오인가?",
  ui_story_1018_10180101_75_dialog_content = "아, 맞아요. 바로 그 이름이었습니다!",
  ui_story_1018_10180101_76_dialog_content = "성주님, 더스크 타운의 자오라고 하는 자가 알현을 청하고 있습니다.",
  ui_story_1018_10180101_77_dialog_content = "이야, 벌써 왔네요.",
  ui_story_1018_10180101_78_dialog_content = "백야성과 외부를 잇는 교통로는 모두 운항을 중단했을 터인데.",
  ui_story_1018_10180101_79_dialog_content = "이스타반 님께서 원하는 일이라면 불가능한 건 없답니다.",
  ui_story_1018_10180101_80_dialog_content = "이 자오라는 사람은 혼자 힘으로 각 세력을 찾아다녔습니다.\n일루미나, 그리고 움브라톤, 그 다음은 이곳 백야성이었죠.",
  ui_story_1018_10180101_81_dialog_content = "성주님께서 만나주지 않으신다면 아마 다음엔 북방, 레디젤 사막으로 갈 겁니다...",
  ui_story_1018_10180101_82_dialog_content = "「허약한 몸을 가지고도 목적을 이루기 전까지는 결코 포기하지 않는 의지를 가진 자,\n그것이 지금 알현을 청하는 자오라는 사내다.」",
  ui_story_1018_10180101_83_dialog_content = "지금 이건 이스타반 님 말씀 그대로예요.",
  ui_story_1018_10180101_84_dialog_content = "더스크 타운이라는 뜨거운 감자를 꽤 흔쾌히 떠맡은 모양이다만, 왜 이스타반은 직접 오지 않았나.",
  ui_story_1018_10180101_85_dialog_content = "전 그냥 말만 전하는 사람이라서요.\n나머지는 지금 문 밖에 있는 손님한테 물어보면 아시게 될 겁니다.",
  ui_story_1018_10180101_86_dialog_content = "여긴 너무 밝아서 전 제 심해로 돌아가야겠네요.\n성주님, 카렌 전하, 배웅은 안 나오셔도 됩니다~",
  ui_story_1018_10180101_87_dialog_content = "......",
  ui_story_1018_10180101_88_dialog_content = "자오를 만나지 않으실 건가요?",
  ui_story_1018_10180101_89_dialog_content = "더스크 타운 문제를 결정할 수 있는 것은 백야성과 일루미나 연방뿐,\n그 밖의 사람에게 담판에 참가할 권한은 없다.",
  ui_story_1018_10180101_90_dialog_content = "일루미나 연방이 이미 저들의 의도를 밝했으니, 더스크 타운은 백야성이 지키는 수밖에.",
  ui_story_1018_10180101_91_dialog_content = "따라와라.",
  ui_story_1018_10180101_92_dialog_content = "친히 더스크 타운으로 가실 건가요?",
  ui_story_1018_10180101_93_dialog_content = "죄를 드러낼 검은 내가 아니다.\n오로리안을 모독한 일루미나의 행위는 신전이 대신 심판할 것이다.",
  ui_story_1018_10180201_1_dialog_content = "<color=#e8d9bb>더스크 타운</color>",
  ui_story_1018_10180201_2_dialog_content = "(벌써 한참을 찾았는데...)",
  ui_story_1018_10180201_3_dialog_content = "(레이스 씨... 대체 어디에 있는 거냐구요...)",
  ui_story_1018_10180201_4_dialog_content = "단장님, 「중심」의 적을 격파한 뒤로, 늪을 따라 튀어나온 암귀를 모두 처리했습니다.",
  ui_story_1018_10180201_5_dialog_content = "늪은 아직 남아 있지만, 더스크 타운은 일단 위험에서 벗어났습니다.",
  ui_story_1018_10180201_6_dialog_content = "현재 상황은 이걸로 일단락이 되었다고 보시는지요.",
  ui_story_1018_10180201_7_dialog_content = "전장이 밖으로 밀려난 추세긴 하지만, 완전히 끝나려면 시간이 조금 더 걸릴 거다.",
  ui_story_1018_10180201_8_dialog_content = "PlayerName, 더스크 타운 쪽의 다크매터는 이제 꽤 줄었겠지?",
  ui_story_1018_10180201_9_dialog_content = "응, 스카이워커도 다크매터 밀도가 높은 적은 안 보인다고 해.",
  ui_story_1018_10180201_10_dialog_content = "그치만 늪이 아직 더스크 타운을 덮고 있으니까, 위험이 없어진 건 아니잖아.",
  ui_story_1018_10180201_11_dialog_content = "맞아요... 의료원도 늪에 영향을 받은 병사들 상태를 일시적으로 안정시켰을 뿐이고,\n확실한 치료법은 아직 못 찾았어요.",
  ui_story_1018_10180201_12_dialog_content = "이대로는 골치가 아프겠어...",
  ui_story_1018_10180201_13_dialog_content = "단장님, 더스크 타운의 백성들은 모두 임시 의료원에 모였습니다.",
  ui_story_1018_10180201_14_dialog_content = "중심지에 가까운 주민들은 피난민을 위해 자신들의 집을 내주고 있습니다.",
  ui_story_1018_10180201_15_dialog_content = "대부분의 백성들은 피해를 입지 않았어. 모두가 목숨을 걸고 싸워준 덕분이야.",
  ui_story_1018_10180201_16_dialog_content = "하지만 더스크 타운에 계속 머무르는 것도 좋은 방법은 아냐.\n주민들을 일루미나 방어선 근처 마을로 이동시키는 것도 생각해 볼 필요가 있어.",
  ui_story_1018_10180201_17_dialog_content = "하지만 단장님, 지금은 아직 주변 전장도 수습하지 못한 상태입니다.\n주민들을 이동시키는 건 위험하지 않겠습니까?",
  ui_story_1018_10180201_18_dialog_content = "적진으로 향한 레이스 대원수와 그 부하들도 아직 행방을 찾지 못했고 말입니다.",
  ui_story_1018_10180201_19_dialog_content = "먼저 준비는 해 두자고. 전황이 명확해지면 다음 행보를 생각하자.",
  ui_story_1018_10180201_20_dialog_content = "일루미나 병사, 실종된 당신들 병력은 대략 얼마나 되지?",
  ui_story_1018_10180201_21_dialog_content = "2개 부대가 대원수님과 함께 돌격했고, 인원은 100명이 넘습니다...",
  ui_story_1018_10180201_22_dialog_content = "게다가 대부분... 신병들입니다.",
  ui_story_1018_10180201_23_dialog_content = "「강철가시 기사단」의 절반 가량 병력이잖아.",
  ui_story_1018_10180201_24_dialog_content = "단장님, 서쪽 성벽 근처에서 병사 몇 명을 발견했습니다.\n상황이 확실하지 않아 단원들도 일단 접근하진 않았습니다.",
  ui_story_1018_10180201_25_dialog_content = "바로 가서 확인해 보자고!",
  ui_story_1018_10180201_26_dialog_content = "맞습니다... 대원수님과 함께 돌격한 병사들입니다.",
  ui_story_1018_10180201_27_dialog_content = "거의 또 수십 명이 희생됐군요...",
  ui_story_1018_10180201_28_dialog_content = "...늪 속에 잠복한 적을 주의하면서 병사들을 정중히 막사로 옮기도록.",
  ui_story_1018_10180201_29_dialog_content = "예!",
  ui_story_1018_10180201_30_dialog_content = "......",
  ui_story_1018_10180201_31_dialog_content = "아직 인사도 못 해봤는데... 이렇게 눈을 감다니...",
  ui_story_1018_10180201_32_dialog_content = "군인이란 그런 거야, PlayerName.",
  ui_story_1018_10180201_33_dialog_content = "항상 전쟁을 치르고, 전우의 죽음을 애도할 시간도 없이 다음 전장으로 가야 하지.",
  ui_story_1018_10180201_34_dialog_content = "......",
  ui_story_1018_10180201_35_dialog_content = "단장님! 아직 숨을 쉬는 전사가 있어요!",
  ui_story_1018_10180201_36_dialog_content = "상태는 어떻습니까?",
  ui_story_1018_10180201_37_dialog_content = "치료하면 잠깐 정도는 안정시킬 수 있을 거예요...",
  ui_story_1018_10180201_38_dialog_content = "......",
  ui_story_1018_10180201_39_dialog_content = "무서워하는 건가요...? 아니면 뭔가 얘기하고 싶으신가요?",
  ui_story_1018_10180201_40_dialog_content = "뭔가... 먹고 있는 것 같은데?",
  ui_story_1018_10180201_41_dialog_content = "크아아아악!",
  ui_story_1018_10180201_42_dialog_content = "「번개처럼 휘두른다!」",
  ui_story_1018_10180201_43_dialog_content = "갑자기 암귀로 변했잖아?!",
  ui_story_1018_10180201_44_dialog_content = "역시나, 가장 우려했던 상황이 결국 벌어졌군...",
  ui_story_1018_10180201_45_dialog_content = "크아아아악!",
  ui_story_1018_10180201_46_dialog_content = "저쪽도...?",
  ui_story_1018_10180201_47_dialog_content = "단장님! 희생된 병사들이... 아니, 암귀가 갑자기 저흴 공격했습니다!",
  ui_story_1018_10180201_48_dialog_content = "...좋지 않군, 상황이 내 예상보다 더 복잡해졌어. 이대로 수색과 치료를 진행할 순 없어!",
  ui_story_1018_10180201_49_dialog_content = "모두 전투 준비!",
  ui_story_1018_10180201_50_dialog_content = "잠깐만! 레오 씨...",
  ui_story_1018_10180202_1_dialog_content = "저 병사들은... 다 죽은 걸까...?",
  ui_story_1018_10180202_2_dialog_content = "......",
  ui_story_1018_10180202_3_dialog_content = "암귀에게 슬픔을 느낄 필요는 없어.",
  ui_story_1018_10180202_4_dialog_content = "한때는 우리와 같은 전사였다 해도, 계속 전장에 남겨두면 더 많은 사상자만 생길 뿐이야.",
  ui_story_1018_10180202_5_dialog_content = "일루미나의 병사들이여, 이곳은 우리에게 맡기고 너희는 더스크 타운에서 신속히 철수하라!",
  ui_story_1018_10180202_6_dialog_content = "단장님, 저희 병사들은... 아직 더스크 타운을 떠날 수 없습니다.",
  ui_story_1018_10180202_7_dialog_content = "다시 한번 말하지. 모든 일루미나군은 더스크 타운에서 철수하라.",
  ui_story_1018_10180202_8_dialog_content = "......",
  ui_story_1018_10180202_9_dialog_content = "...그럼 드리고 싶은 말씀이 있습니다.",
  ui_story_1018_10180202_10_dialog_content = "다 듣고 나서 저흴 보낼지 다시 한번 생각해 주셨으면 좋겠습니다.",
  ui_story_1018_10180202_11_dialog_content = "말해 봐.",
  ui_story_1018_10180202_12_dialog_content = "더스크 타운에 오기 전, 근위군단은 일루미나의 최정예 병사들로 이루어진\n정예 예비부대였습니다.",
  ui_story_1018_10180202_13_dialog_content = "제 뒤에 있는 동료들도 모두 정예 예비부대 사람들이고, 줄곧 레이스 대원수님을 따라 왔습니다.",
  ui_story_1018_10180202_14_dialog_content = "비록 저흰 이런 전쟁에 참여해 본 적 없었지만, 지금까지 버텨온 것만으로도\n충분히 저희의 실력을 증명했다고 생각합니다.",
  ui_story_1018_10180202_15_dialog_content = "무슨 말을 하고 싶은진 알겠어.\n갑자기 암귀가 된 저 신병들은 일루미나에서 특수한 훈련을 받았겠지.",
  ui_story_1018_10180202_16_dialog_content = "그리고 더스크 타운에 도착하자 늪의 영향을 받기 시작했어. 너희 대원수도 포함해서 말이야.",
  ui_story_1018_10180202_17_dialog_content = "맞습니다... 하지만 맹세할 수 있습니다.\n전장에 오기 전까지 저흰 누구도 이런 일이 일어날 줄은 몰랐습니다!",
  ui_story_1018_10180202_18_dialog_content = "이렇게 많은 전우들을 잃고, 대원수님마저 실종된 상황에 저희 모두 괴로워하고 있습니다.",
  ui_story_1018_10180202_19_dialog_content = "그러니 제가 정예 예비부대를 대표해서 부탁드리겠습니다!\n이대로 전장에 남아서 더스크 타운을 지킬 수 있게 해 주십시오!",
  ui_story_1018_10180202_20_dialog_content = "대원수님을 찾기 전까지, 이건 저희가 일루미나의 군인으로서 수행할 명령입니다.",
  ui_story_1018_10180202_21_dialog_content = "저희도 더스크 타운을 함께 지키고 싶습니다. 제가 대원수님 대신 지휘를 맡겠습니다.",
  ui_story_1018_10180202_22_dialog_content = "정말 그 대장에 그 부하 아니랄까 봐.",
  ui_story_1018_10180202_23_dialog_content = "적이 너희의 동포였는데도 말이야?",
  ui_story_1018_10180202_24_dialog_content = "저들이 더스크 타운을 파멸로 이끄는 암귀로 변했다면... 연민을 갖지 않겠습니다...",
  ui_story_1018_10180202_25_dialog_content = "크아아아악!",
  ui_story_1018_10180202_26_dialog_content = "단장님! 이쪽에도 있습니다!",
  ui_story_1018_10180202_27_dialog_content = "......!",
  ui_story_1018_10180202_28_dialog_content = "흥... 「번개처럼 휘두른다!」",
  ui_story_1018_10180202_29_dialog_content = "지금 그 행동으로는 방금 전 맹세가 증명이 되질 않잖아, 병사.\n일단 물러서 있어. 저들은 이제 가망이 없다고.",
  ui_story_1018_10180202_30_dialog_content = "단장님, 아직은 그렇게 단정짓지 마세요.\n우릴 먼저 공격하지 않는 자들은 아직 가망이 없다고 말할 순 없어요.",
  ui_story_1018_10180202_31_dialog_content = "맞아... 왠지 망설이는 것 같았다고...",
  ui_story_1018_10180202_32_dialog_content = "다들 방금 상황을 봤잖아? 한순간의 방심은 저들에게 공격의 기회를 주고 만다고.",
  ui_story_1018_10180202_33_dialog_content = "하지만 저들도 오로리안이에요!",
  ui_story_1018_10180202_34_dialog_content = "크아아아악!",
  ui_story_1018_10180202_35_dialog_content = "모두 똑바로 봐! 저들은 암귀와 전혀 차이가 없어! 더스크 타운을 해치려는 자는 모두 적이야!",
  ui_story_1018_10180202_36_dialog_content = "일루미나의 군사들이여. 더스크 타운을 지키고 싶다면 용기를 보여!\n적에게 용서 따위는 필요 없어!",
  ui_story_1018_10180202_37_dialog_content = "못 하겠다면 이곳을 떠나라. 너희 임무는 끝이야.",
  ui_story_1018_10180202_38_dialog_content = "전...",
  ui_story_1018_10180202_39_dialog_content = "내 부하한테... 지시를 내리려면... 아직 멀었어...",
  ui_story_1018_10180202_40_dialog_content = "다크매터의 영향을 받고 있다고 해서... 저들이... 죽어야 하는 건 아니라고...",
  ui_story_1018_10180202_41_dialog_content = "내가... 반드시...",
  ui_story_1018_10180202_42_dialog_content = "레오 씨! 레이스 씨야!",
  ui_story_1018_10180202_43_dialog_content = "......",
  ui_story_1018_10180202_44_dialog_content = "왜냐면 내가... 겪었으니까...",
  ui_story_1018_10180202_45_dialog_content = "대원수님!",
  ui_story_1018_10180301_1_dialog_content = "레이스 씨! 한참 찾았다구요!",
  ui_story_1018_10180301_2_dialog_content = "레이스 씨가 나타나니까... 발작했던 병사들이 잠잠해졌어요...",
  ui_story_1018_10180301_3_dialog_content = "늪의 영향 때문에... 몸 안의 힘을 제어할 수 없었을 뿐이야...",
  ui_story_1018_10180301_4_dialog_content = "저들은 너흴 해칠 생각은... 없었어...",
  ui_story_1018_10180301_5_dialog_content = "......",
  ui_story_1018_10180301_6_dialog_content = "만물은 백야 아래에... 대원수님, 무사하셨군요!",
  ui_story_1018_10180301_7_option_content = "많이 힘들어 보여요...",
  ui_story_1018_10180301_8_dialog_content = "지금 어디 불편한 곳 있어요?",
  ui_story_1018_10180301_9_dialog_content = "늪에 부딪혔을 때 통증이 있었던 것 외에는...",
  ui_story_1018_10180301_10_dialog_content = "전부 기억이 안 나...",
  ui_story_1018_10180301_11_option_content = "대체 무슨 일이 있었던 거예요?",
  ui_story_1018_10180301_12_dialog_content = "아무리 찾아도 찾을 수가 없었다구요!",
  ui_story_1018_10180301_13_dialog_content = "나도 잘 모르겠어...",
  ui_story_1018_10180301_14_dialog_content = "기억나는 건 늪에 둘러싸인 순간 눈앞이 캄캄해진 것밖에...",
  ui_story_1018_10180301_15_dialog_content = "아무튼 걱정 마... 그냥 흙투성이가 됐을 뿐이니까...",
  ui_story_1018_10180301_16_dialog_content = "같은 상황인 병사들이 얼마나 더 있지...?",
  ui_story_1018_10180301_17_dialog_content = "사실 레오 씨가 계속 레이스 씨 부하들을 찾아주고 있었어요...",
  ui_story_1018_10180301_18_dialog_content = "아무튼 돌아와서 다행이에요!",
  ui_story_1018_10180301_19_dialog_content = "그래...",
  ui_story_1018_10180301_20_dialog_content = "내가 말했지... 암귀가 되더라도 그 전에 더스크 타운을 지켜내겠다고...",
  ui_story_1018_10180301_21_dialog_content = "이제... 거기 내 부하들도 더해야겠어...",
  ui_story_1018_10180301_22_dialog_content = "내 부하들을 암귀로 대하고 멋대로 쓰러트리는 건... 절대 허락 못 해.",
  ui_story_1018_10180301_23_dialog_content = "...대원수, 무사해서 다행이군.",
  ui_story_1018_10180301_24_dialog_content = "일루미나의 병사들을 해칠 뜻은 없었어. 그저 더스크 타운을 생각해서 결정했을 뿐이야.",
  ui_story_1018_10180301_25_dialog_content = "순탄할 땐 적을 쓰러트리고, 역경에는 병사를 버린다...\n미안하지만 난 그런 용병술은 받아들일 수 없어...",
  ui_story_1018_10180301_26_dialog_content = "대원수, 난...",
  ui_story_1018_10180301_27_dialog_content = "내가 돌아온 이상, 내 부하들의 지휘는 내가 맡는다...",
  ui_story_1018_10180301_28_dialog_content = "지금은 너와 더 논쟁할 기운은 없으니까... 더는 선을 넘지 않았으면 좋겠어...",
  ui_story_1018_10180301_29_dialog_content = "...그러지.",
  ui_story_1018_10180301_30_dialog_content = "대원수님, 많이 힘드신 것 같아요.",
  ui_story_1018_10180301_31_dialog_content = "저랑 같이 의료원으로 가요. 의료진들이 치료해 드릴 거예요!",
  ui_story_1018_10180301_32_dialog_content = "여긴 전장이야... 부하들이 아직 싸우고 있는데 내가 빠질 순 없어.",
  ui_story_1018_10180301_33_dialog_content = "그럼 적어도... 제가 상처를 볼 수 있게 해 주세요. 일단 제 말을 타고 잠깐 쉬세요!",
  ui_story_1018_10180301_34_dialog_content = "정말 부하들에게 책임을 느낀다면, 먼저 당신 몸 상태부터 확인하는 게 좋겠어.",
  ui_story_1018_10180301_35_dialog_content = "늪 속에 한참 동안 있었잖아요. 무리하지 마세요.",
  ui_story_1018_10180301_36_dialog_content = "...그럼 부탁할게, 조셀린 양.",
  ui_story_1018_10180301_37_dialog_content = "...만물은 백야 아래에... 이러고도 아직 루미나틱스를 쓰실 수 있다니...",
  ui_story_1018_10180301_38_dialog_content = "온몸이 상처투성이에요. 치명상은 아니긴 해도, 이미 힘이 심하게 약해져 있어요.",
  ui_story_1018_10180301_39_dialog_content = "힘이 약해져...? 그런 느낌은 없어...",
  ui_story_1018_10180301_40_dialog_content = "오히려 급속도로 회복되는 것 같아...",
  ui_story_1018_10180301_41_dialog_content = "그러고 보니 정신을 잃었을 때, 어떤 힘이 내 몸속에서 흐르고 있었어...",
  ui_story_1018_10180301_42_dialog_content = "마치 누군가가 곁에서 치료해 주는 듯한... 뭐라고 표현하기 힘든 느낌이었어...",
  ui_story_1018_10180301_43_dialog_content = "치료? 전장에 또 누가 있었나요?",
  ui_story_1018_10180301_44_dialog_content = "이상한 얘기지... 그래도 내가 지금 여기 서 있는 걸 보면 가능성이 없는 건 아냐...",
  ui_story_1018_10180301_45_dialog_content = "하지만 여전히 내 부하들은 지키지 못했어...",
  ui_story_1018_10180301_46_dialog_content = "...대원수님과 함께 늪에 돌입한 두 부대는 아직 발견되지 않았습니다.",
  ui_story_1018_10180301_47_dialog_content = "악셀리아 대장이 부대를 이끌고 수색을 계속하고 있습니다만...",
  ui_story_1018_10180301_48_dialog_content = "어쩌면 저들도 전부... 아까 그 병사들처럼...",
  ui_story_1018_10180301_49_dialog_content = "...나 때문이야... 내 손으로 저들을 위험에 빠트렸어...",
  ui_story_1018_10180301_50_dialog_content = "아닙니다! 저희가 명령을 어긴 겁니다...",
  ui_story_1018_10180301_51_dialog_content = "대원수님과 함께 가겠다고... 저희가 선택했습니다! 그리고 이 신병들도...",
  ui_story_1018_10180301_52_dialog_content = "이런 적을 앞에 두고도 당신은 망설임 없이 전진하며 전세를 뒤집었어요.",
  ui_story_1018_10180301_53_dialog_content = "저들을 빨리 발견할 수 있다면 아직 기회가 있을지도 몰라요!",
  ui_story_1018_10180301_54_dialog_content = "......",
  ui_story_1018_10180301_55_dialog_content = "...어쨌든 더는 모두가 나와 함께 위험을 무릅쓰게 할 순 없어...",
  ui_story_1018_10180301_56_dialog_content = "<color=#e8d9bb>일행은 서쪽 전장으로 향했다...</color>",
  ui_story_1018_10180301_57_dialog_content = "늪이 여기까지 퍼져 있다니... 게다가 아직도 계속 흐르고 있는 것 같잖아...",
  ui_story_1018_10180301_58_dialog_content = "음... 적이 또 공격해 올 수도 있겠어. 게다가 실종된 병사들도 늪에 휩쓸렸을 가능성이 높아.",
  ui_story_1018_10180301_59_dialog_content = "그렇다면 늪이 있는 한 이 전쟁은 끝나지 않아요.",
  ui_story_1018_10180301_60_dialog_content = "내가 가장 걱정하는 건... 내 부하가 적에게 이용당하는 거야...",
  ui_story_1018_10180301_61_dialog_content = "이번 부대 편성의 과실은 전황에 엄청난 영향을 끼치고 말았어. 내 책임이야.",
  ui_story_1018_10180301_62_dialog_content = "대원수님, 당신도 사정을 몰랐잖아요. 아무튼 늪을 따라 계속 수색해 보자구요.",
  ui_story_1018_10180301_63_dialog_content = "그래...",
  ui_story_1018_10180301_64_dialog_content = "대원수님! 방어선 서쪽입니다!",
  ui_story_1018_10180301_65_dialog_content = "「엔진 7호」 3대가 저쪽에 있습니다! 게다가... 병사들도 있는 것 같습니다!",
  ui_story_1018_10180301_66_dialog_content = "저건 내가 진격할 때 날 엄호했던 기체야... 어째서 이런 곳에...",
  ui_story_1018_10180301_67_dialog_content = "주변 일대가 폐허다... 저들 뒤의 보루도 이미 무너졌어. 다행히 저들이 지켜준 덕분에...",
  ui_story_1018_10180301_68_dialog_content = "그럼 이걸로 못 찾은 「엔진 7호」는 1대뿐이야. 아마 이 근처에 있을 거야. 서두르자...",
  ui_story_1018_10180301_69_dialog_content = "<color=#e8d9bb>콰직── 콰직──</color>",
  ui_story_1018_10180301_70_dialog_content = "다...단장님, 저건...",
  ui_story_1018_10180301_71_dialog_content = "......",
  ui_story_1018_10180301_72_dialog_content = "이미 완전히 파괴됐습니다...",
  ui_story_1018_10180301_73_dialog_content = "기체를 둘러싼 병사들이... 기체의 외피를 먹고 있습니다...",
  ui_story_1018_10180301_74_dialog_content = "그어어...",
  ui_story_1018_10180301_75_dialog_content = "암귀처럼 먹는 걸로 에너지를 보급하고 있는 건가...?",
  ui_story_1018_10180301_76_dialog_content = "그런...",
  ui_story_1018_10180301_77_dialog_content = "그어어!",
  ui_story_1018_10180301_78_dialog_content = "......",
  ui_story_1018_10180301_79_dialog_content = "대원수님, 일단 내리지 마세요. 저들은 아직 우릴 눈치 채지 못한 것 같아요.\n여긴 우리한테 맡기세요.",
  ui_story_1018_10180301_80_dialog_content = "맞아. 암귀의 수는 많지 않아. 나 혼자면 충분해.",
  ui_story_1018_10180301_81_dialog_content = "저들은 암귀가 아냐... 내 부하라고...",
  ui_story_1018_10180301_82_dialog_content = "...어떻게든 제어해야만 해...",
  ui_story_1018_10180301_83_dialog_content = "......",
  ui_story_1018_10180301_84_dialog_content = "대원수로서 늘 앞장서는 당신이 부하들 앞에서는 그토록 판단이 무뎌지는 건가?",
  ui_story_1018_10180301_85_dialog_content = "우선 제어해 보는 거야... 어쩌면 아직 구할 수 있을지도 몰라...",
  ui_story_1018_10180301_86_dialog_content = "레이스 씨 말이 맞아. 내가 해볼게!",
  ui_story_1018_10180302_1_dialog_content = "휴... 이제 진정이 된 것 같아.",
  ui_story_1018_10180302_2_dialog_content = "나머지는 의료진에게 맡겨주세요.\nPlayerName 당신은 지휘뿐만 아니라 치료에도 능숙했군요.",
  ui_story_1018_10180302_3_dialog_content = "전에 레이스 씨도 비슷한 상황에서 이렇게 하니까 정신을 되찾았거든.",
  ui_story_1018_10180302_4_dialog_content = "다들 그저 의식 속으로 너무 깊게 빠져서 자길 제어하지 못하고 있을 뿐이야.",
  ui_story_1018_10180302_5_dialog_content = "하지만... 철판을 잔뜩 먹은 그 병사는... 너무 안타까워.",
  ui_story_1018_10180302_6_dialog_content = "만물은 백야 아래에... 레오 단장님도 어떻게든 붙잡으려 했는걸요...\n두 사람 모두 최선을 다했어요.",
  ui_story_1018_10180302_7_dialog_content = "그 병사는 이미 몸이 엉망이었어. 오로지 다크매터로 버티고 있었던 거지...",
  ui_story_1018_10180302_8_dialog_content = "대원수, 역시 대국을 우선시하는 게 좋겠어.\n저런... 병사를 두고 스스로 고통받을 필요는 없어.",
  ui_story_1018_10180302_9_dialog_content = "말하지 않아도 알고 있다고...",
  ui_story_1018_10180302_10_dialog_content = "그나저나 대원수, 앞으로 찾은 병사들을 모두 의료원에서 치료할 생각인가?",
  ui_story_1018_10180302_11_dialog_content = "수백 명의 병사는 결코 적은 수가 아냐.",
  ui_story_1018_10180302_12_dialog_content = "확실히 그렇죠... 앞으로 구조하는 부상자들까진 의료원에서 감당할 수 없을 거예요...",
  ui_story_1018_10180302_13_dialog_content = "하지만 일루미나 병사들은 특수한 상태라서, 한시라도 빨리 치료해야 해요.",
  ui_story_1018_10180302_14_dialog_content = "이미 부하들에게 준비하라고 해 뒀습니다.\n부하가 돌아오는 대로 주민들을 중심부의 마을로 이동시킬 겁니다.",
  ui_story_1018_10180302_15_dialog_content = "뭘로 이동시키려고? 마차 몇 대로...?",
  ui_story_1018_10180302_16_dialog_content = "그래, 그마저도 몇 대 안 남았지. 어쩌면 도보로 이동해야 할 수도 있어...",
  ui_story_1018_10180302_17_dialog_content = "도보로 이동하는 건 암귀에게 식량을 공급하는 거나 다름없잖아...",
  ui_story_1018_10180302_18_dialog_content = "...그래서 말인데, 제안할 게 하나 있어. 대신 PlayerName 네가 결정할 문제야.",
  ui_story_1018_10180302_19_dialog_content = "사실 저도 마침 생각한 방법이 있는데요...",
  ui_story_1018_10180302_20_dialog_content = "스카이워커호.",
  ui_story_1018_10180302_21_dialog_content = "더스크 타운 주민들을 한시라도 빨리 대피시키는 건 좋아요...\n게다가 헤븐즈 밸리라면 지금으로선 가장 안전한 곳이고 말이에요.",
  ui_story_1018_10180302_22_dialog_content = "하지만 앞으로 구조하는 부상자들은 어쩔 생각이죠?",
  ui_story_1018_10180302_23_dialog_content = "늪이 사라질 때까지... 우리가 방법을 찾아볼게.\n지금은 싸울 수조차 없는 일반 주민들을 먼저 구해야 해.",
  ui_story_1018_10180302_24_dialog_content = "단장님, 제가 백야 요새로 한번 가 볼게요.",
  ui_story_1018_10180302_25_dialog_content = "지금까지 많은 교회 분들이 먼저 나서서 의료원에 남아 치료를 도와줬어요.",
  ui_story_1018_10180302_26_dialog_content = "응급 치료가 필요한 부상자를 수용해 달라고 부탁해 볼게요.\n그러면 대원수님의 향후 구조도 차질 없이 진행할 수 있을 거예요.",
  ui_story_1018_10180302_27_dialog_content = "백야 요새라... 저라면 큰 기대는 안 할 겁니다.",
  ui_story_1018_10180302_28_dialog_content = "하지만 지금은 피난민을 지키는 게 가장 중요하고, 무엇이 최선인지는 아무도 모릅니다.\n그러니 말리진 않겠습니다.",
  ui_story_1018_10180302_29_dialog_content = "진영의 차이가 아무리 크다 해도, 전 백야 교회가 오로리안을 거부하진 않을 거라고 믿어요.",
  ui_story_1018_10180302_30_dialog_content = "다만... 레이스 대원수님. 당신이나 일루미나 여러분은 백야 교회로 가는 것도 괜찮은가요?",
  ui_story_1018_10180302_31_dialog_content = "난 신경 안 써. 일루미나는 종교와 대립하지 않거든.",
  ui_story_1018_10180302_32_dialog_content = "지금은 부하들의 안부가 가장 중요해. 그럼 부하들을... 부탁할게.",
  ui_story_1018_10180302_33_dialog_content = "레이스 씨, 정말 치료 안 해도 되겠어요?",
  ui_story_1018_10180302_34_dialog_content = "난 그냥 피곤할 뿐이야... 너희랑 얘기하고 나니까 많이 좋아졌어.",
  ui_story_1018_10180302_35_dialog_content = "조셀린 양, 말을 좀 빌려줄 수 있을까?",
  ui_story_1018_10180302_36_dialog_content = "물론이죠! 걱정 마세요. 제가 당신 부하들이 최대한 빨리 치료를 받을 수 있게 노력할게요.",
  ui_story_1018_10180302_37_dialog_content = "다음에 만날 땐 이 전투가 끝나 있길 바랄게요. 그럼 먼저 준비하러 갈게요.",
  ui_story_1018_10180302_38_dialog_content = "몸조심해요.",
  ui_story_1018_10180302_39_dialog_content = "PlayerName, 이따가 내 부하와 같이 서쪽 출구에서 모이는 걸로 하자고.",
  ui_story_1018_10180302_40_dialog_content = "더스크 타운의 위험이 해결되는 대로 나도 피난민들을 보러 갈 테니까.",
  ui_story_1018_10180302_41_dialog_content = "이번엔... 크흠, 고마웠어. 다음에 또 만나자.",
  ui_story_1018_10180302_42_dialog_content = "저기... 저도 떠난다곤 말 안 했는데요.",
  ui_story_1018_10180302_43_dialog_content = "스카이워커의 자동 비행 시스템이 마을 사람들을 알아서 안전한 곳으로 데려다줄 거예요.",
  ui_story_1018_10180302_44_dialog_content = "저도 같이 더스크 타운을 지키겠다고 했잖아요.\n이 싸움이 끝나기 전까지 저도 여길 떠나지 않을 거예요.",
  ui_story_1018_10180302_45_dialog_content = "...PlayerName, 네 의지는 내 생각을 훨씬 뛰어넘는구나.",
  ui_story_1018_10180302_46_dialog_content = "오히려 난 네가 그럴지도 모른다고 생각했어. 우린 오랫동안 같이 싸웠으니까.",
  ui_story_1018_10180302_47_dialog_content = "PlayerName, 더스크 타운 서쪽에 착륙했습니다.\n현재 거리라면 교신을 유지할 수 있습니다.",
  ui_story_1018_10180302_48_dialog_content = "스카이워커, 이따가 더스크 타운 사람들을 우리들 집까지 안전하게 데려다줬으면 좋겠어.",
  ui_story_1018_10180302_49_dialog_content = "목적지를 설정합니다. 목적지는 헤븐즈 밸리입니다.",
  ui_story_1018_10180302_50_dialog_content = "PlayerName, 부디 몸조심하십시오.",
  ui_story_1018_10180302_51_dialog_content = "응, 그럼 사람들을 부탁할게!",
  ui_story_1018_10180401_1_dialog_content = "<color=#e8d9bb>어둠의 밑바닥을 향해 달리는 열차 안...</color>",
  ui_story_1018_10180401_2_dialog_content = "하나, 둘, 셋... 여기 벌써 네 바퀴는 돌고 있어요. 내려온 지시는 없나요?",
  ui_story_1018_10180401_3_dialog_content = "메리, 진정하세요. 우릴 여기까지 이끈 수수께끼도 반드시 풀릴 때가 올 겁니다.",
  ui_story_1018_10180401_4_dialog_content = "카론 열차장은 정말로 민치의 안내를 믿고 있는 걸까요?",
  ui_story_1018_10180401_5_dialog_content = "이미 오랫동안 동행하지 않았습니까. 당신은 어떻게 생각하죠? 그나저나... 민치, 괜찮습니까?",
  ui_story_1018_10180401_6_dialog_content = "아까부터 계속 머리가 아파. 바람이 많이 불어서 그런가 봐...",
  ui_story_1018_10180401_7_dialog_content = "열차 안에 바람은 안 부는데...",
  ui_story_1018_10180401_8_dialog_content = "창밖 말하는 거야. 강풍이 부는 빈도가 엄청 이상하다구...",
  ui_story_1018_10180401_9_dialog_content = "지나간 뒤쪽 마을에 예상치 못한 사태가 발생한 것이 희미한 빛을 통해 느껴지는군요.\n그분께서 아직 오시지 않은 것도 그 때문일 수도 있겠지요.",
  ui_story_1018_10180401_10_dialog_content = "저 검은 게 마을이었군요. 꼭 어둠의 밑바닥에서 뻗어나온 검은 발톱처럼 보여요...",
  ui_story_1018_10180401_11_dialog_content = "휴, 모처럼 승차감도 좋고 보기도 좋은 열차를 탔는데, 창밖은 온통 저런 풍경이라니...",
  ui_story_1018_10180401_12_dialog_content = "카론 님, 저 세 사람 말을 정말 믿어도 되는 건가요?\n출발했을 때부터 카론 님이 저희보고 쉬라고 하셨잖아요.",
  ui_story_1018_10180401_13_dialog_content = "근데 벌써 자다가 세 번이나 깼는데, 왜 아직도 어둠의 밑바닥에 도착하지 못한 거죠?",
  ui_story_1018_10180401_14_dialog_content = "우리는 지금 임무를 수행하는 중이다, 바이스.\n걱정할 필요 없다. 피안호가 우리의 안전을 지켜줄 테니 말이야.",
  ui_story_1018_10180401_15_dialog_content = "하지만 카론 님, 제 기억으론 일루미나에서 어둠의 밑바닥까진 이렇게 안 멀었는데요...",
  ui_story_1018_10180401_16_dialog_content = "이번 임무에서 난 두 가지 확실한 단서를 받았다.\n그리고 이건 그 수수께끼를 풀기 위해 반드시 지나야 할 길이다.",
  ui_story_1018_10180401_17_dialog_content = "확실한 단서? 그게 뭐죠?",
  ui_story_1018_10180401_18_dialog_content = "하나는 일루미나 방어선 바깥의 각 좌표들이다.\n우리가 통과한 장소는 모두 지도상에서 찾아볼 수 있지.",
  ui_story_1018_10180401_19_dialog_content = "그러니 이건 절대 이상한 곳을 달리고 있는 건 아니다.",
  ui_story_1018_10180401_20_dialog_content = "근데 이 표식을 보면... 계속 같은 곳만 돌고 있지 않나요?!",
  ui_story_1018_10180401_21_dialog_content = "쉿... 먼 곳에서 온 손님을 놀라게 만들면 일이 귀찮아질 거다.",
  ui_story_1018_10180401_22_dialog_content = "저 세 사람요? 역시 카론 님도 수상하다고 생각하신 거죠?",
  ui_story_1018_10180401_23_dialog_content = "비밀 임무라고 할 수 있겠지. 같은 곳을 돌고 있는 것도 임무의 일환이다.",
  ui_story_1018_10180401_24_dialog_content = "어둠 속 목소리가 내게 알려주고 있다. 수수께끼는 곧 밝혀질 거라고 말이야.",
  ui_story_1018_10180401_25_dialog_content = "또 수수께끼니 뭐니인가요...",
  ui_story_1018_10180401_26_dialog_content = "그럼 두 번째 단서는 뭐죠?",
  ui_story_1018_10180401_27_dialog_content = "두 번째는 특수한 표식이 있는 지점을 주행한 뒤, 「어둠의 밑바닥 정찰대」와의 통신 주파수다.",
  ui_story_1018_10180401_28_dialog_content = "어라? 근데 그쪽에선 위치 신호를 안 보낸 지 오래됐는데요?",
  ui_story_1018_10180401_29_dialog_content = "그쪽 책임자가 통신기를 끄고 있는 걸까요? 아니면 근처에 전파 차단기가 있거나요.",
  ui_story_1018_10180401_30_dialog_content = "...카론 님... 아무래도 지금까지의 정보를 좀 정리할 필요가 있을 것 같은데요.\n이래서야 우리 임무를 전혀 수행할 수 없잖아요!",
  ui_story_1018_10180401_31_dialog_content = "전 일루미나의 지금 상황이 너무 걱정돼요.",
  ui_story_1018_10180401_32_dialog_content = "그 의심과 우려를 다른 것으로 승화시켜 보면 어떨까? 내가 멀리서 대답해 줄 수 있을지도 몰라.",
  ui_story_1018_10180401_33_dialog_content = "카론 님... 혹시 지금... 여자 목소리 들으셨어요?",
  ui_story_1018_10180401_34_dialog_content = "지금 내 귓가에도 스쳐 지나갔다.",
  ui_story_1018_10180401_35_dialog_content = "빅토리아 님!",
  ui_story_1018_10180401_36_dialog_content = "빅토리아 님! 드디어 오셨습니까?",
  ui_story_1018_10180401_37_dialog_content = "아직 날 기억하고 있을까? 일루미나의 열차장.\n다른 사람 앞에서는 동족이나... 먼 친척이라고 부르지 않는 편이 좋겠지?",
  ui_story_1018_10180401_38_dialog_content = "이상한 말은 하지 않았으면 좋겠군, 빅토리아 여사.\n당신과 당신 부하들은 대체 무슨 일을 꾸미고 있는 거지?",
  ui_story_1018_10180401_39_dialog_content = "빅토리아 씨...? 그럼 이 세 사람도 진리의 결사 멤버였던 건가요?!",
  ui_story_1018_10180401_40_dialog_content = "바이스 양, 세 사람이 여행을 방해하진 않았겠지?",
  ui_story_1018_10180401_41_dialog_content = "그건... 카론 님께 여쭤봐야 할 것 같은데요.\n그치만 계속 같은 곳을 달리고 있던 게 설마 당신 때문인가요?",
  ui_story_1018_10180401_42_dialog_content = "전부 그렇진 않아. 하지만 내가 나섬으로써 진리를 아는 이들을 태운 이 열차는\n비로소 정상 궤도에 오를 수 있게 됐단다.",
  ui_story_1018_10180401_43_dialog_content = "바이스 양이 이번 임무를 맡은 건 일루미나를 방문한 그 수수께끼의 손님에게\n관심이 있기 때문이겠지...",
  ui_story_1018_10180401_44_dialog_content = "그리고 더스크 타운에서 대체 무슨 일이 일어나고 있는지 궁금해서겠지?",
  ui_story_1018_10180401_45_dialog_content = "일루미나에 잠입한 자에 대해 어떻게 알고 있는 거죠?\n그리고... 더스크 타운에 무슨 일이 생겼나요...?",
  ui_story_1018_10180401_46_dialog_content = "그러니까 이 열차는 내 인도가 필요하지 않겠어?",
  ui_story_1018_10180401_47_dialog_content = "더스크 타운에서 일어나는 일이라면...\n아이테르와 일루미나의 신임 대원수가 아직 살길을 찾지 못했다고 말할 수 있으려나.",
  ui_story_1018_10180401_48_dialog_content = "PlayerName 그 애도 더스크 타운으로 갔다구요?!",
  ui_story_1018_10180401_49_dialog_content = "대원수님이 출정하신 건 알고 있었지만... 그럼 다들 더스크 타운에서 위험에 처한 건가요...?",
  ui_story_1018_10180401_50_dialog_content = "당신이 더스크 타운이 어떻길 바라느냐에 따라 당신의 차원 속 저들의 상태도 결정될 거야.\n계시가 강림하기 전까진 애를 써 봐도 알게 되는 건 없어.",
  ui_story_1018_10180401_51_dialog_content = "...카론 님, 저 말이 사실인가요? 대원수님이랑 PlayerName... 다들 무사한 거죠?",
  ui_story_1018_10180401_52_dialog_content = "......",
  ui_story_1018_10180401_53_dialog_content = "어떠니? 늪을 보러 가 보겠니?",
  ui_story_1018_10180401_54_dialog_content = "비록 칠흑의 서의 계시에 따르면 아가씨의 운명의 궤적은...\n영원한 어둠의 땅을 향하고 있지만 말이야.",
  ui_story_1018_10180401_55_dialog_content = "「깊은 사랑을 잊고 영원한 밤의 땅에 빠져 어둠의 창으로 자라나지만,\n이를 도와 속죄의 의식을 마친다.」",
  ui_story_1018_10180401_56_dialog_content = "바이스 양, 축하해. 이 여행으로 당신은 진상을 알게 될 거야.",
  ui_story_1018_10180401_57_dialog_content = "대체... 그게 다 무슨 소리냐구요...",
  ui_story_1018_10180401_58_dialog_content = "허튼소리! 이 여행은 운명이 아니라 일루미나의 군인이 수행하는 임무일 뿐이다.",
  ui_story_1018_10180401_59_dialog_content = "빅토리아 여사, 우릴 방해하지 않았으면 좋겠군. 그렇지 않으면 나도 좌시하진 않겠다.",
  ui_story_1018_10180401_60_dialog_content = "우리 결사 멤버들과 한참을 같이 다녔으면서, 「공간 루프」의 존재도 느끼지 못한 걸까?",
  ui_story_1018_10180401_61_dialog_content = "「공간 루프」...? 같은 곳을 돌고 있었던 게 당신 소행이 아니었단 말인가?",
  ui_story_1018_10180401_62_dialog_content = "선조들의 낙인도 네 몸에서는 흐려진 모양이네. 그럼 이제 계시를 받을 때가 된 것 같아.",
  ui_story_1018_10180401_63_dialog_content = "지금 이클립스는 모종의 이유로 당신들이 가까이 오지 못하게 하고 있어.",
  ui_story_1018_10180401_64_dialog_content = "당신들이 일정한 거리를 갈 때마다, 「최초의 위치」로 되돌아가는 것,\n그게 바로 「공간 루프」의 힘이야.",
  ui_story_1018_10180401_65_dialog_content = "그리고 그 「최초의 위치」라는 건 정해진 원형 공간 내의 중심을 말해.\n당신들은 그 반경 범위에서만 움직일 수 있는 거야.",
  ui_story_1018_10180401_66_dialog_content = "...그런 일이 어떻게 가능하죠?",
  ui_story_1018_10180401_67_dialog_content = "깊게 생각할 거 없어, 바이스 양. 그래봤자 광기에 빠질 뿐이니까.",
  ui_story_1018_10180401_68_dialog_content = "하지만 내 인도가 있다면 그런 상황은 존재하지 않게 될 거야.\n이렇게 말해도 열차장은 여전히 내 동승을 거부할까?",
  ui_story_1018_10180401_69_dialog_content = "......",
  ui_story_1018_10180401_70_dialog_content = "그 침묵은 허락의 뜻으로 이해할게. 이제 가속해서 전진하도록 해, 열차장.",
  ui_story_1018_10180401_71_dialog_content = "카론 님... 이해가 잘 안 돼요. 우리 지금 계속 영원한 밤의 땅 방향으로 가고 있는 건가요?",
  ui_story_1018_10180401_72_dialog_content = "바이스 양, 열차가 멈추는 곳은 당신의 마음이 바라는 곳으로 정해.",
  ui_story_1018_10180401_73_dialog_content = "마음이 바라는 곳...?",
  ui_story_1018_10180401_74_dialog_content = "<color=#e8d9bb>빠아앙──!</color>",
  ui_story_1018_10180401_75_dialog_content = "조심해──",
  ui_story_1018_10180401_76_dialog_content = "갑자기 왜 강풍이 부는 거지...? 설마 적이 공격해 올 조짐은 아니겠지...?",
  ui_story_1018_10180401_77_dialog_content = "악셀리아는 부하를 보호합니다...",
  ui_story_1018_10180401_78_dialog_content = "이렇게 강한 바람이 부는데 늪은 조금도 움직이지 않아... 역시 이상해...",
  ui_story_1018_10180401_79_dialog_content = "악셀리아, 그쪽 수색할 때 뭔가 이상이 있었나?",
  ui_story_1018_10180401_80_dialog_content = "설마 「중심」의 적이 쓰러진 게 아니라, 잠복해서 기회를 노리고 있는 건 아니겠지...",
  ui_story_1018_10180401_81_dialog_content = "<color=#e8d9bb>부글부글──</color>",
  ui_story_1018_10180401_82_dialog_content = "단장님, 담당 구역 수색을 마쳤습니다. 이제 부상자를 의료원으로 호송할 준비를 하는 중입니다.",
  ui_story_1018_10180401_83_dialog_content = "알겠어. 암귀의 방해가 없으니까 예상보다 꽤 순조롭게 진행되고 있네.",
  ui_story_1018_10180401_84_dialog_content = "<color=#e8d9bb>부글부글──</color>",
  ui_story_1018_10180401_85_dialog_content = "악셀리아는 기묘한 소리를 들었습니다...",
  ui_story_1018_10180401_86_dialog_content = "나한테도 들렸어. 물에서 뭔가 나올 때 같은 소리였어...",
  ui_story_1018_10180401_87_dialog_content = "그어어...",
  ui_story_1018_10180401_88_dialog_content = "이 소리는...?",
  ui_story_1018_10180401_89_dialog_content = "대원수님! 큰일입니다... 들것에 실은 병사가...",
  ui_story_1018_10180401_90_dialog_content = "어째서...?",
  ui_story_1018_10180401_91_dialog_content = "몸의 진흙이 흐르고 있어... 마치 생물처럼...",
  ui_story_1018_10180401_92_dialog_content = "그럼 아까 그 소리는...",
  ui_story_1018_10180401_93_dialog_content = "으아악──! 사...살려줘...",
  ui_story_1018_10180401_94_dialog_content = "전원 들것에서 떨어져 내 주변으로 집결하라!",
  ui_story_1018_10180401_95_dialog_content = "구조했을 땐 분명히 아무 문제 없었는데...",
  ui_story_1018_10180401_96_dialog_content = "<color=#e8d9bb>휘이잉──</color>",
  ui_story_1018_10180401_97_dialog_content = "그어어...",
  ui_story_1018_10180401_98_dialog_content = "잠깐만... 이 바람이야! 설마 습격인가?!",
  ui_story_1018_10180401_99_dialog_content = "어서 몸을 숨겨──!",
  ui_story_1018_10180401_100_dialog_content = "모, 못 서 있겠어...!",
  ui_story_1018_10180401_101_dialog_content = "PlayerName, 날 잡아!",
  ui_story_1018_10180401_102_dialog_content = "눈이... 전혀 안 떠져... 새, 새로운 적이야?",
  ui_story_1018_10180401_103_dialog_content = "<color=#e8d9bb>후두둑!</color>",
  ui_story_1018_10180401_104_dialog_content = "조심해! 늪이 튀어 올라온다!",
  ui_story_1018_10180401_105_dialog_content = "대원수! 뒤쪽이다!",
  ui_story_1018_10180401_106_dialog_content = "봤어... 늪만이 아니야... 안에 뭔가 있어!",
  ui_story_1018_10180401_107_dialog_content = "크오오!",
  ui_story_1018_10180401_108_dialog_content = "늪 속에 암귀 무리가 있어요!",
  ui_story_1018_10180401_109_dialog_content = "역시 그랬어. 암귀가 늪을 타고 공격해 오니까, 다크매터의 영향을 받은 병사들도 반응하기 시작한 거야...",
  ui_story_1018_10180401_110_dialog_content = "크오오!",
  ui_story_1018_10180401_111_dialog_content = "으아악──! 사...살려줘...",
  ui_story_1018_10180401_112_dialog_content = "대원수, 놈들은 이제 제정신이 아니야! 암귀로 간주하고 처치하는 수밖에 없어!",
  ui_story_1018_10180401_113_dialog_content = "아니... 아니야...",
  ui_story_1018_10180401_114_dialog_content = "지금 우리 뒤엔 암귀가 있어! 더 우물쭈물하다간 전군이 늪에 파묻힐 거라고!",
  ui_story_1018_10180401_115_dialog_content = "레오 씨...",
  ui_story_1018_10180401_116_dialog_content = "<color=#e8d9bb>휘이잉── 빠아앙──!</color>",
  ui_story_1018_10180401_117_dialog_content = "이런! 또 온다!",
  ui_story_1018_10180401_118_dialog_content = "그리고 기차 기적소리도 들렸어요...",
  ui_story_1018_10180401_119_dialog_content = "카론 님! 지도로 보면 여긴 더스크 타운인데요?",
  ui_story_1018_10180401_120_dialog_content = "빅토리아 여사, 이것도 「공간 루프」의 소행인가? 우리가 왜 여기 있는 거지?",
  ui_story_1018_10180401_121_dialog_content = "「공간 루프」에서는 이미 벗어났어. 난 바이스 씨의 소망에 따라 열차를 여기로 옮겼을 뿐이야.",
  ui_story_1018_10180401_122_dialog_content = "원형 공간의 반경 안에 마침 더스크 타운이 있었거든.",
  ui_story_1018_10180401_123_dialog_content = "이런 일이 정말 가능하다니...",
  ui_story_1018_10180401_124_dialog_content = "카론 님, 앞쪽에 사람들이 잔뜩 모여 있어요! PlayerName 일행 아닐까요?",
  ui_story_1018_10180401_125_dialog_content = "열차 밑은 온통 늪이란다. 안에 숨어 있는 암귀를 조심해.",
  ui_story_1018_10180401_126_dialog_content = "이 얼마나 불결한 늪과 불결한 암귀인가! 피안호, 모조리 분쇄해라!",
  ui_story_1018_10180401_127_dialog_content = "승객들이여, 손잡이를 꽉 잡도록. 늪을 뚫고 전방에 정차하겠다!",
  ui_story_1018_10180401_128_dialog_content = "<color=#e8d9bb>빠아앙──!</color>",
  ui_story_1018_10180401_129_dialog_content = "오! 레이스 대원수 아니십니까!",
  ui_story_1018_10180401_130_dialog_content = "대원수 취임을 축하드립니다. 도착이 늦어진 점 부디 용서해 주십시오.",
  ui_story_1018_10180401_131_dialog_content = "대원수님! PlayerName!",
  ui_story_1018_10180401_132_dialog_content = "바이스!",
  ui_story_1018_10180401_133_dialog_content = "카론, 바이스... 너희가 왜 여기 온 거지?!",
  ui_story_1018_10180401_134_dialog_content = "너흰 임무를 수행하고 있지 않았나? 왜 더스크 타운으로 온 거야?",
  ui_story_1018_10180401_135_dialog_content = "열차장, 시간을 엄수해 줘. 여긴 잠깐 정차하는 곳일 뿐이야.",
  ui_story_1018_10180401_136_dialog_content = "대원수님, 더스크 타운의 전황을 듣고 전 몹시나 걱정이 되었습니다. 허나 지금은 임무 수행 중인 탓에 오래 머무를 수 없습니다.",
  ui_story_1018_10180401_137_dialog_content = "너희가 암귀 무리를 깔아뭉개준 덕분에 큰 도움이 됐어.",
  ui_story_1018_10180401_138_dialog_content = "그럼 아까 그 강풍은 적이 아니라 너희가 일으킨 건가...?",
  ui_story_1018_10180401_139_dialog_content = "저희가 여기 온 건 결코 우연이 아닙니다. 하지만 지금은 설명할 시간이 없습니다. 늪은 길게 늘어져 있고, 아래에는 수많은 암귀가 있을지도 모릅니다.",
  ui_story_1018_10180401_140_dialog_content = "빅토리아 님, 강풍이 분 건... 혹시 「공간 루프」가 다시 나타난 것은 아닌지요...",
  ui_story_1018_10180401_141_dialog_content = "끝까지 쫓아올 생각인 건가... 잠깐 앉아 있도록 해. 내가 너흴 데리고 도망칠 테니까.",
  ui_story_1018_10180401_142_dialog_content = "이 거리라면 20초인가.",
  ui_story_1018_10180401_143_dialog_content = "빅토리아 님, 저희가 세겠습니다...",
  ui_story_1018_10180401_144_dialog_content = "바이스, 오는 동안 별일 없었어?",
  ui_story_1018_10180401_145_dialog_content = "더스크 타운에 있던 모두에 비하면... 우리가 겪은 건 아무것도 아냐.",
  ui_story_1018_10180401_146_dialog_content = "근데 오는 도중에 빅토리아 씨가 계속 수수께끼 같은 말을 해서 이해가 잘 안 됐어...",
  ui_story_1018_10180401_147_dialog_content = "아무튼 조심해. 진리의 결사가 나타났다는 건 불길한 징조니까.",
  ui_story_1018_10180401_148_dialog_content = "너까지 왜 그래? 영문 모를 소리나 하고...",
  ui_story_1018_10180401_149_dialog_content = "그리고 사실 빅토리아 씨는 확실히 우릴 도와주고 있다구.",
  ui_story_1018_10180401_150_dialog_content = "만약 그것도 카론 씨 생각이라면...",
  ui_story_1018_10180401_151_dialog_content = "15, 14, 13...",
  ui_story_1018_10180401_152_dialog_content = "10, 9...",
  ui_story_1018_10180401_153_dialog_content = "...그러니까 대원수님, 반드시 버티셔야 해요. 모두 대원수님의 무사 귀환을 기다리고 있어요!",
  ui_story_1018_10180401_154_dialog_content = "물론 그래야지. 너도 조심하고, 임무를 완수해서 무사히 일루미나로 돌아와.",
  ui_story_1018_10180401_155_dialog_content = "5, 4, 3...",
  ui_story_1018_10180401_156_dialog_content = "내가 한 말 기억하지?",
  ui_story_1018_10180401_157_dialog_content = "...응. 위험한 일이 생기면 네 이름을 부르라고.",
  ui_story_1018_10180401_158_dialog_content = "2, 1, 0.",
  ui_story_1018_10180401_159_dialog_content = "그럼 여러분, 다음에 또 만나자.",
  ui_story_1018_10180401_160_dialog_content = "<color=#e8d9bb>쿠르릉──</color>",
  ui_story_1018_10180401_161_dialog_content = "다들... 사라져버렸잖아?!",
  ui_story_1018_10180401_162_dialog_content = "...믿을 수 없어. 루미나틱스에 대한 내 이해에서 완전히 벗어난 장면이잖아.",
  ui_story_1018_10180401_163_dialog_content = "크오오!",
  ui_story_1018_10180401_164_dialog_content = "대원수님! 기사단 쪽은 이미 한계입니다! 더는 저 병사들을 저지할 수 없습니다...!",
  ui_story_1018_10180401_165_dialog_content = "더는 방법이 없는 건가...",
  ui_story_1018_10180401_166_dialog_content = "단장님, 형제들은 모두 의문을 품고 있습니다. 우리의 적은 대체 누굽니까...?",
  ui_story_1018_10180401_167_dialog_content = "대원수의 부하이자... 눈앞의 이 잔인한 암귀들이지...",
  ui_story_1018_10180401_168_dialog_content = "설령 저자가 날 막는다 해도, 이제 더는 양보할 수 없다.",
  ui_story_1018_10180401_169_dialog_content = "내 부하를 해치는 자는 내 손으로 직접 처단하겠다!",
  ui_story_1018_10180401_170_dialog_content = "기사단이여! 나를 따르라! 저들을 해치워라!",
  ui_story_1018_10180401_171_dialog_content = "...예!",
  ui_story_1018_10180401_X171_dialog_content = "갑자기 강풍이라니... 설마 적이 공격해 올 조짐인 걸까요...?",
  ui_story_1018_10180401_X172_dialog_content = "확실히 암귀들이 많아지고 있긴 하지만, 아직 구조는 진행할 수 있어.\n발견한 특이사항은 없나?",
  ui_story_1018_10180401_X173_dialog_content = "보고드립니다. 제 담당 구역 내에서는 구조 작업에 영향은 없는 상황입니다.",
  ui_story_1018_10180401_X174_dialog_content = "보고드립니다. 악셀리아의 담당 구역에는 다수의 암귀가 나타났습니다.\n하지만 이미 모두 처리했습니다.",
  ui_story_1018_10180401_X175_dialog_content = "대원수님, 레오 단장이 맡고 있는 늪 구역의 상황이 좋지 않습니다.",
  ui_story_1018_10180401_X176_dialog_content = "알겠어... 다들 조심해. 내가 가서 살펴볼 테니까.",
  ui_story_1018_10180401_X177_dialog_content = "단장님, 부상자들은 모두 들것에 태웠습니다. 먼저 의료원으로 호송하겠습니다.",
  ui_story_1018_10180401_X178_dialog_content = "그래, 병사들의 상황에도 주의하도록. 늪이 다시 움직이면서 암귀도 점점 많아지고 있어.\n놈들이 대규모 공격을 가하기 전에 피해야만 해.",
  ui_story_1018_10180401_X179_dialog_content = "예, 단장님.",
  ui_story_1018_10180401_X180_dialog_content = "악셀리아는 기묘한 소리를 들었습니다... 병사의 몸에서 나고 있습니다.",
  ui_story_1018_10180401_X181_dialog_content = "너무 다가가지 마. 모두 늪에서 건져낸 병사들이야.",
  ui_story_1018_10180401_X182_dialog_content = "진흙이 몸 위를 흐르고 있어... 마치 생물처럼...",
  ui_story_1018_10180401_X183_dialog_content = "지금 당장은 저 진흙을 처리할 방법이 없어...",
  ui_story_1018_10180401_X184_dialog_content = "그어억...",
  ui_story_1018_10180401_X185_dialog_content = "그어어어...",
  ui_story_1018_10180401_X186_dialog_content = "대원수님! 부상자의 상태가 매우 불안정합니다!",
  ui_story_1018_10180401_X187_dialog_content = "몸의 진흙이 더 빠르게 흐르는 것 같지 않아?",
  ui_story_1018_10180401_X188_dialog_content = "더 빨라졌다고? 그럼 설마...",
  ui_story_1018_10180401_X189_dialog_content = "조심해! 늪이 튀어 올라온다!",
  ui_story_1018_10180401_X190_dialog_content = "늪만이 아니야... 안에 뭔가 있어!",
  ui_story_1018_10180401_X191_dialog_content = "크오오!",
  ui_story_1018_10180401_X192_dialog_content = "역시, 암귀가 늪을 타고 공격해 오니까 다크매터의 영향을 받은 병사들도\n문제가 생기기 시작했어...",
  ui_story_1018_10180401_X193_dialog_content = "...기사단 1부대는 의료진을 엄호하고, 나머지는 전투를 준비하라!",
  ui_story_1018_10180401_X194_dialog_content = "예!",
  ui_story_1018_10180401_X195_dialog_content = "<color=#e8d9bb>휘이잉──</color>",
  ui_story_1018_10180401_X196_dialog_content = "또 시작이야... 설마 뒤에도 적이 있는 건가?!",
  ui_story_1018_10180401_X197_dialog_content = "모, 못 서 있겠어...!",
  ui_story_1018_10180401_X198_dialog_content = "어서 몸을 숨겨──!",
  ui_story_1018_10180401_X199_dialog_content = "눈이... 전혀 안 떠져... 새, 새로운 적이야?",
  ui_story_1018_10180401_X200_dialog_content = "PlayerName, 날 잡아!",
  ui_story_1018_10180401_X201_dialog_content = "<color=#e8d9bb>휘이잉── 빠아앙──!</color>",
  ui_story_1018_10180401_X202_dialog_content = "PlayerName, 괜찮아?",
  ui_story_1018_10180401_X203_dialog_content = "왠지... 기차 기적소리가 또 들린 것 같아요...",
  ui_story_1018_10180401_X204_dialog_content = "제가 잘못 본 거 아니죠?! 저기 먼지투성이인 사람... PlayerName 아닌가요?!",
  ui_story_1018_10180401_X205_dialog_content = "카론 님... 그럼 지금 우린 더스크 타운에 온 거잖아요? 이게 어떻게 가능한 거죠...?",
  ui_story_1018_10180401_X206_dialog_content = "「공간 루프」는 확실히 재미있네.\n하지만 더 재미있는 건 내가 바이스 양의 소망에 따라 열차를 여기로 옮겼다는 거야.",
  ui_story_1018_10180401_X207_dialog_content = "이런 일이 정말 가능하다니...",
  ui_story_1018_10180401_X208_dialog_content = "무슨 말인지 이해가 잘 안 되지만, 일단 앞쪽에 열차를 세워주실 수 있나요?\nPlayerName하고 저 사람들 왠지 위험한 상황 같아요...",
  ui_story_1018_10180401_X209_dialog_content = "저 컴컴한 늪이랑 암귀 무리가 사람들을 포위하려고 해요...",
  ui_story_1018_10180401_X210_dialog_content = "바이스 양, 안타깝지만 여긴 우리 목적지가 아냐. 「공간 루프」를 돌파하기 전까진 멈출 수 없어.",
  ui_story_1018_10180401_X211_dialog_content = "사람들이랑 점점 더 멀어지고 있어요... 카론 님, 우리가 뭔가 할 수 있는 게 없을까요?",
  ui_story_1018_10180401_X212_dialog_content = "정차할 수 없다면...",
  ui_story_1018_10180401_X213_dialog_content = "피안호는 이 더러운 늪을 뚫고 암귀들을 모조리 분쇄할 뿐이다!\n승객들이여! 자리에 잘 앉도록 해라!",
  ui_story_1018_10180401_X214_dialog_content = "<color=#e8d9bb>덜컹덜컹, 덜컹덜컹──</color>",
  ui_story_1018_10180401_X215_dialog_content = "키아악──",
  ui_story_1018_10180401_X216_dialog_content = "단장님! 방금 저거... 기차 아닙니까? 늪 속의 암귀들을 거의 다 없애버렸습니다!",
  ui_story_1018_10180401_X217_dialog_content = "...일루미나의 기술로 보이는데 말이지. 이참에 어서 의료진들 상황부터 확인하자고.",
  ui_story_1018_10180401_X218_dialog_content = "예!",
  ui_story_1018_10180401_X219_dialog_content = "맞아... 저건 카론 씨 기차야. 그리고 왠지 바이스가 보였던 것 같아...",
  ui_story_1018_10180401_X220_dialog_content = "저들이 왜 여기 있는 거지? 게다가 순식간에 사라지다니...",
  ui_story_1018_10180401_X221_dialog_content = "저도 모르겠어요... 우리가 더스크 타운에 오기 전에 바이스랑 카론 씨는\n이미 어둠의 밑바닥 쪽으로 임무를 수행하러 갔었잖아요.",
  ui_story_1018_10180401_X222_dialog_content = "갑자기 여기 나타나서 우릴 도와준 건 확실히 말이 안 되는 상황이야.",
  ui_story_1018_10180401_X223_dialog_content = "대원수님! 실종됐던 다른 부대를 찾았습니다!",
  ui_story_1018_10180401_X224_dialog_content = "알겠어, 금방 갈게.",
  ui_story_1018_10180401_X225_dialog_content = "PlayerName, 어쩌면 저들은 우리가 이해할 수 없는 일을 겪었을지도 몰라.\n하지만 그건 저들 스스로 해결해야 할 문제고, 난 저들을 믿어.",
  ui_story_1018_10180401_X226_dialog_content = "우린 지금 눈앞의 위기부터 먼저 해결하자.",
  ui_story_1018_10180401_X227_dialog_content = "네. 무사하길 바랄 수밖에요...",
  ui_story_1018_10180401_X228_dialog_content = "(바이스, 꼭 무사해야 해.)",
  ui_story_1018_10180501_1_dialog_content = "<color=#e8d9bb>열차는 한 미지의 공간에 정차했다...</color>",
  ui_story_1018_10180501_2_dialog_content = "민치! 얼른 소매 좀 치워요... 숨막혀 죽을 뻔했잖아요!",
  ui_story_1018_10180501_3_dialog_content = "어라? 이거 좀 봐! 방울이 반짝이고 있어... 우리가 성공했다는 거야?!",
  ui_story_1018_10180501_4_dialog_content = "그런 것 같군요... 끈적끈적한 물질이 제 눈꺼풀에 닿았습니다. 이 감각은 틀림없습니다.",
  ui_story_1018_10180501_5_dialog_content = "빅토리아 님, 여긴 대체...",
  ui_story_1018_10180501_6_dialog_content = "빛도 어둠도 없이, 오직 진리만이 존재하는 곳... 여긴 나의 비경이란다.",
  ui_story_1018_10180501_7_dialog_content = "오오! 무릎 꿇고 주의 소리에 귀를 기울이겠나이다!",
  ui_story_1018_10180501_8_dialog_content = "이게 진리의 목소리를 듣는 아픔이었군요... 기억나요... 차분한 마음으로 들을게요!",
  ui_story_1018_10180501_9_dialog_content = "저기... 좀 우리도 알아들을 수 있는 말로 해 주지 않을래요? 여기가 대체 어디죠?",
  ui_story_1018_10180501_10_dialog_content = "걱정할 거 없어, 바이스 양. 「공간 루프」는 이미 벗어났으니까.",
  ui_story_1018_10180501_11_dialog_content = "그럼 빅토리아 씨가 우릴 구해준 건가요?",
  ui_story_1018_10180501_12_dialog_content = "모든 것은 인도를 따르는 일...",
  ui_story_1018_10180501_13_dialog_content = "빅토리아 님! 선혈이 「보였」습니다!",
  ui_story_1018_10180501_14_dialog_content = "저, 전 생생한 말이 「들렸」어요! 귀를 찌르는 듯한 아픔이 느껴져요!",
  ui_story_1018_10180501_15_dialog_content = "...칠흑의 서가 이 순간에 계시를 내리다니...",
  ui_story_1018_10180501_16_dialog_content = "글자가 빠르게 변하고... 앞날이 희미하게 모습을 드러내고 있어...",
  ui_story_1018_10180501_17_dialog_content = "「행동 후에는 패배가 오리라.」",
  ui_story_1018_10180501_18_dialog_content = "「일식이 그 꼬리를 펴고, 극광이 비칠 때, 그가 귀로에 오른다」... 그 예언을 가리키는 건가?",
  ui_story_1018_10180501_19_dialog_content = "아니야... 글자가 아직도 변하고 있어...",
  ui_story_1018_10180501_20_dialog_content = "「좌절 후에는 웅대한 쾌거가 오리라.」",
  ui_story_1018_10180501_21_dialog_content = "「오로리안에게 재난의 때가 찾아와 그와 만나나, 오로라가 그것을 막으리라」... 이 내용이야.",
  ui_story_1018_10180501_22_dialog_content = "계시가... 불분명해...",
  ui_story_1018_10180501_23_dialog_content = "빅토리아 님! 진한 증오가 주의 눈 속을 흐르고 있습니다...",
  ui_story_1018_10180501_24_dialog_content = "디시스, 눈을 감아! 그건 주의 눈빛이 아냐. 주께선 증오를 품지 않으셔!",
  ui_story_1018_10180501_25_dialog_content = "...여러분, 다들 숨을 죽여.",
  ui_story_1018_10180501_26_dialog_content = "......",
  ui_story_1018_10180501_27_dialog_content = "카론 님! 계기판에 희미한 신호 반응이 있어요...",
  ui_story_1018_10180501_28_dialog_content = "「어둠의 밑바닥」 탐색대가 보낸 좌표로군. 이 위치는... 지도상에는 없다.",
  ui_story_1018_10180501_29_dialog_content = "거긴 <color=#FFB400>진실의 땅</color>이 아니라 계시에서 말한 「버려진 고향, 귀로의 기점」이거든.",
  ui_story_1018_10180501_30_dialog_content = "무슨 뜻이죠? 그럼 우리가 탐색대를 찾아낼 순 있는 건가요?",
  ui_story_1018_10180501_31_dialog_content = "아무래도 빛과 어둠의 싸움을 끝낼 때가 온 것 같아. 진리의 주인께선 반드시 강림하실 거야.",
  ui_story_1018_10180501_32_dialog_content = "그 순간을 목도하기 위해 난 당신들을 목적지까지 바래다 줄 거야.",
  ui_story_1018_10180501_33_dialog_content = "대신, 열차장 당신의 도움이 필요해.",
  ui_story_1018_10180501_34_dialog_content = "......",
  ui_story_1018_10180501_35_dialog_content = "카론 님, 너무 불안해요...",
  ui_story_1018_10180501_36_dialog_content = "빅토리아 씨의 비경이 뭔가에 짓눌려있는 것 같아서... 숨쉬기가 힘들 정도예요...",
  ui_story_1018_10180501_37_dialog_content = "나도... 같은 느낌이 드는군...",
  ui_story_1018_10180501_38_dialog_content = "역시나, 결국 찾아왔구나...",
  ui_story_1018_10180501_39_dialog_content = "아네모네는 대체 뭘 하려던 걸까요? 당신들을 아직까지 살려 두다니 말이에요.",
  ui_story_1018_10180501_40_dialog_content = "...누, 누가 얘기하는 거죠?",
  ui_story_1018_10180501_41_dialog_content = "당신 몸에선 제가 싫어하는 냄새가 나는군요. 하지만 그게 뭐였는지 기억이 나질 않는단 말이죠...",
  ui_story_1018_10180501_42_dialog_content = "불결한 놈! 내 부하 곁에서 떨어져라!",
  ui_story_1018_10180501_43_dialog_content = "당신에겐 관심 없어요. 다만 이쪽 금발의 숙녀분... 재미있는 걸 가지고 계시는군요.",
  ui_story_1018_10180501_44_dialog_content = "진정한 지식 앞에서 죄악의 하수인은 전율할 수밖에 없겠지.",
  ui_story_1018_10180501_45_dialog_content = "제가 보기엔 당신들이야말로 벌벌 떨고 있는 것 같은데요. 눈을 감고 뭘 하고 있는 걸까요?",
  ui_story_1018_10180501_46_dialog_content = "...선혈을 바치나이다. 진리의 주인이시여, 부디 가호를 내려 주소서.",
  ui_story_1018_10180501_47_dialog_content = "호오? 무슨 의식이라도 거행하는 건가요?",
  ui_story_1018_10180501_48_dialog_content = "네 상대는 나다. 정체를 밝히지 않는 악인이여, 업화의 맛을 느껴봐라!",
  ui_story_1018_10180501_49_dialog_content = "<size=30>신자 디시스, 제사를 마쳤나이다.</size>",
  ui_story_1018_10180501_50_dialog_content = "<size=30>아픔을 제물로 바치나니, 주께서 진리로 인도하시리라.</size>",
  ui_story_1018_10180501_51_dialog_content = "<size=30>신자 메리, 제사를 마쳤나이다.</size>",
  ui_story_1018_10180501_52_dialog_content = "제가 도와줄까요? 그럼 효율도 더 높아질 텐데 말이죠.",
  ui_story_1018_10180501_53_dialog_content = "「기적을 그 눈에 새겨라!」",
  ui_story_1018_10180501_54_dialog_content = "의식은 곧 끝날 거야. 열차장──",
  ui_story_1018_10180501_55_dialog_content = "카론 님... 괘, 괜찮으신 거 맞죠?",
  ui_story_1018_10180501_56_dialog_content = "꽉 잡아라. 삼도천 열차가 출발한다! 머리를 틀어 아래로 전진한다!",
  ui_story_1018_10180501_57_dialog_content = "...다리가... 공중에 떠 버렸는데요?!",
  ui_story_1018_10180501_58_dialog_content = "<size=30>총애가 깃든 제물을 바치나니, 주께서 숨은 의문을 밝히시리라.</size>",
  ui_story_1018_10180501_59_dialog_content = "<size=30>신자 민치, 제사를 마쳤나이다.</size>",
  ui_story_1018_10180501_60_dialog_content = "도망치려고요?",
  ui_story_1018_10180501_61_dialog_content = "부디 주께서 제물을 받으사 제 선혈의 힘을 취하시고, 진홍색의 진리를 세상에 드러내소서!",
  ui_story_1018_10180501_62_dialog_content = "신의 기적이 현현하였나니── 팬텀의 영역은 이미 벗어났도다!",
  ui_story_1018_10180501_63_dialog_content = "승객들이여, 꽉 잡아라!",
  ui_story_1018_10180501_64_dialog_content = "아, 안 되겠어요... 몸이... 엄청난 속도로 떨어져요──!",
  ui_story_1018_10180501_65_dialog_content = "어둠의 밑바닥으로 가려면 우린 <color=#FFB400>명류의 강</color>을 지나야 해. <color=#FFB400>망각의 황야</color>라고 불리는 그곳 말이야.",
  ui_story_1018_10180501_66_dialog_content = "빛이 보일 때까지는 눈을 감고 있으렴. 위험이 당신을 느끼지 못하도록.",
  ui_story_1018_10180501_67_dialog_content = "근데 눈을 감으면 암귀 무리가 다가오는 게 보여요...",
  ui_story_1018_10180501_68_dialog_content = "그건 당신 의식 속의 전장이지, 진짜 적이 아니야.",
  ui_story_1018_10180501_69_dialog_content = "하지만... 저들은... 일루미나의 병사예요...",
  ui_story_1018_10180501_70_dialog_content = "저들이 로봇을 먹고 있는 게 보여요...",
  ui_story_1018_10180501_71_dialog_content = "병사들끼리 서로 죽이고...",
  ui_story_1018_10180501_72_dialog_content = "게다가... 검은 늪이 어둠의 밑바닥에서 계속해서 일루미나의 방어선 쪽으로 뻗어나가고 있어요...",
  ui_story_1018_10180501_73_dialog_content = "(여기서 떠나. 다가가면 안 돼.)",
  ui_story_1018_10180501_74_dialog_content = "(또 당신이야...? 당신... 대체 누구야?)",
  ui_story_1018_10180501_75_dialog_content = "(여기서 떠나. 다가가면 안 돼.)",
  ui_story_1018_10180501_76_dialog_content = "(...뭔가 이상한 힘이 날 몰아세우고 있어...)",
  ui_story_1018_10180501_77_dialog_content = "바이스?",
  ui_story_1018_10180501_78_dialog_content = "목소리가 들려요... 우리보고 떠나라고 하고 있어요...",
  ui_story_1018_10180501_79_dialog_content = "듣지도, 응시하지도 마. 안 그러면 다시는 깨어날 수 없게 될 테니까.",
  ui_story_1018_10180501_80_dialog_content = "누군지 잘 안 보여요... 하지만... 목소리도... 심장 소리도... 정말 진짜 같단 말이에요...",
  ui_story_1018_10180501_81_dialog_content = "마치... 제가 그 사람인 것처럼요...",
  ui_story_1018_10180501_82_dialog_content = "그건 위험이 다가오고 있다는 신호야.",
  ui_story_1018_10180501_83_dialog_content = "(...PlayerName 말대로 해 보자. 위험한 일이 생기면 이름을 부르라고 했잖아.)",
  ui_story_1018_10180501_84_dialog_content = "(어쩌면 정말로 들을지도 몰라...)",
  ui_story_1018_10180501_85_dialog_content = "(여기서 떠나. 여긴 위험해.)",
  ui_story_1018_10180501_86_dialog_content = "(하지만... 난 어떻게든 당신 정체를 확인하고 싶어...)",
  ui_story_1018_10180501_87_dialog_content = "(지금까지 한 번도 누군가가 나와 이렇게 가까이 있다고 느낀 적은 없었으니까...)",
  ui_story_1018_10180501_88_dialog_content = "(......)",
  ui_story_1018_10180501_89_dialog_content = "(...이 소리는?)",
  ui_story_1018_10180501_90_dialog_content = "(바이스의 심장 소리야...)",
  ui_story_1018_10180501_91_dialog_content = "(바이스가 위험한 게 분명해...)",
  ui_story_1018_10180501_92_dialog_content = "PlayerName! 뒤를 조심해!",
  ui_story_1018_10180601_1_dialog_content = "그어어...",
  ui_story_1018_10180601_2_dialog_content = "대원수님, 이미 머리를 조준하고 있습니다... 부디 명령을 내려 주십시오...!",
  ui_story_1018_10180601_X2_dialog_content = "총을 내려놔.",
  ui_story_1018_10180601_X3_dialog_content = "하지만... 그자는 제9부대 지휘관이었으면서 저렇게나 많은 전우들을 죽였고,\n이젠 대원수님까지 해치려고 합니다! 그자는 더는 일루미나의 군인이 아닙니다!",
  ui_story_1018_10180601_X4_dialog_content = "그건 이자가 의도한 게 아냐! 눈빛이 말해주고 있어. 아직 의식이 있어!",
  ui_story_1018_10180601_X5_dialog_content = "대원수님! 기사단 쪽은 이미 한계입니다! 더는 저 병사들을 저지할 수 없습니다...!\n이대로 가다간... 모두 위험해집니다!",
  ui_story_1018_10180601_3_dialog_content = "그자는 제9부대 지휘관이었습니다... 하지만 이미 저렇게나 많은 전우들을 죽였습니다! 그자는 더는 일루미나의 군인이 아닙니다!",
  ui_story_1018_10180601_4_dialog_content = "눈빛이 말해주고 있어. 아직 의식이 있어!",
  ui_story_1018_10180601_5_dialog_content = "똑똑히 봐라... 나는 너의 대원수다! 당장 손 풀어!",
  ui_story_1018_10180601_6_dialog_content = "...대원수...님...",
  ui_story_1018_10180601_7_dialog_content = "...저, 정말로 말을 듣다니...",
  ui_story_1018_10180601_8_dialog_content = "일루미나로 데리고 돌아가 주마. 넌 이런 곳에서 죽어선 안 된다.",
  ui_story_1018_10180601_9_dialog_content = "......",
  ui_story_1018_10180601_10_dialog_content = "그자의 몸은 이미 다크매터에 완전히 지배되고 있어!\n당신... 이대로 가다간 부하 손에 목이 부러질 거라고!",
  ui_story_1018_10180601_11_dialog_content = "그어어...",
  ui_story_1018_10180601_12_dialog_content = "(몸속의 에너지가... 깨어난 것 같아...)",
  ui_story_1018_10180601_13_dialog_content = "(내가... 이 녀석을 죽이고 싶은 충동을 느끼다니...)",
  ui_story_1018_10180601_14_dialog_content = "그 사람도 전에 레이스 씨가 그랬던 것처럼 의식 속에 잠겨 있어요! 일단 진정하세요...",
  ui_story_1018_10180601_15_dialog_content = "제가 감응 능력을 써 볼게요!",
  ui_story_1018_10180601_16_dialog_content = "아직 이자의 의식이 어떤 상황인지 몰라. 네가 위험해질 수도 있어.",
  ui_story_1018_10180601_17_dialog_content = "하지만 지금은 이게 유일한 방법이에요...",
  ui_story_1018_10180601_18_dialog_content = "위험하다고 생각되면 바로 감응을 끊을게요. 절 믿어줘요.",
  ui_story_1018_10180601_19_dialog_content = "...좋아, 만약 이자가 널 해치려 한다면... 나도 더는 주저하지 않겠어.",
  ui_story_1018_10180601_20_dialog_content = "네...",
  ui_story_1018_10180601_21_option_content = "[감응을 시도한다]",
  ui_story_1018_10180601_22_dialog_content = "(들어왔어... 여긴... 일루미나의 지하성이야...)",
  ui_story_1018_10180601_23_dialog_content = "(주거 구역이겠지... 세제 냄새가 나는 것 같아...)",
  ui_story_1018_10180601_24_dialog_content = "하지만 엄마... 이건 다시 없을 기회라고요!",
  ui_story_1018_10180601_25_dialog_content = "(자기 어머니랑 말싸움하고 있는 건가...)",
  ui_story_1018_10180601_26_dialog_content = "레이스 군단장님은 목표를 향해 수없이 도전한 끝에 지금의 자리에 오르셨어요!",
  ui_story_1018_10180601_27_dialog_content = "이번 육성 계획을 놓치면 대원수가 되겠다는 내 꿈도 영영 이룰 수 없을 거라고요!",
  ui_story_1018_10180601_28_dialog_content = "군단장님은 내 능력을 인정해 주셨어요. 내가 더 높은 자리에 오를 수 있다고 하셨다고요!",
  ui_story_1018_10180601_29_dialog_content = "그래, 고위 장교가 되어... 많은 전쟁에서 이기겠지... 네 아버지가 그랬고, 너도...",
  ui_story_1018_10180601_30_dialog_content = "넌 네 아빠를 닮아서 담력과 지혜가 있어. 엄마 눈에는 항상 네가 최고야...",
  ui_story_1018_10180601_31_dialog_content = "하지만 얘... 그 육성 계획은 아주 힘들다고 들었어...",
  ui_story_1018_10180601_32_dialog_content = "훈련을 견디지 못하면 다시는 전장에 나갈 수 없을 거야...",
  ui_story_1018_10180601_33_dialog_content = "그러니까 엄마 옆에 있어 주면 안 될까? 엄마한테는 이제 너희들밖에 없어...",
  ui_story_1018_10180601_34_dialog_content = "엄마... 난 오빠를 믿어...",
  ui_story_1018_10180601_35_dialog_content = "응! 그러니까 엄마도 날 좀 믿어줘요. 꼭 해낼 테니까요!",
  ui_story_1018_10180601_36_dialog_content = "계속 자난성에만 있어서는 미래가 없어요. 군인은 전장에 나가야 군인이에요.\n죽음 따윈 두렵지 않아요!",
  ui_story_1018_10180601_37_dialog_content = "얘... 그런 말은 하면 안 돼...",
  ui_story_1018_10180601_38_dialog_content = "아무튼 난 이미 결정했어요!",
  ui_story_1018_10180601_39_dialog_content = "(......)",
  ui_story_1018_10180601_40_dialog_content = "(이 어머니가 지금 상황을 알면 어떻게 생각할까...)",
  ui_story_1018_10180601_41_dialog_content = "(으앗! 이야기에 빠져서 듣고만 있었잖아?!)",
  ui_story_1018_10180601_42_dialog_content = "(어라? 다른 곳으로 바뀌었네... 이건 조명인가? 눈부셔...)",
  ui_story_1018_10180601_43_dialog_content = "박사님, 이게 「계명성 프로젝트」의 최종 시험입니까?",
  ui_story_1018_10180601_44_dialog_content = "그렇습니다. 이게 바로 마지막 단계입니다.",
  ui_story_1018_10180601_45_dialog_content = "당신의 유일한 목표는 앞으로의 적을 쓰러트리고 살아남는 것입니다.\n수단과 방법에는 그 어떤 제한도 없습니다.",
  ui_story_1018_10180601_46_dialog_content = "(잠깐만! 빨리 여길 떠나!)",
  ui_story_1018_10180601_47_dialog_content = "(엄마? 여긴 왜 온 거예요...? 이미 말했잖아요. 난 결정했어요. 그러니 이제 그만하세요...)",
  ui_story_1018_10180601_48_dialog_content = "(날 자기 어머니로 착각하고 있어... 그럼...)",
  ui_story_1018_10180601_49_dialog_content = "(그 사람 말 듣지 마! 계획에 참가하면 넌 암귀가 돼! 엄마는 그런 걸 원하지 않아!)",
  ui_story_1018_10180601_50_dialog_content = "(괜찮아요, 엄마... 박사님은 내가 재능이 있다고 했어요. 난 꼭 심사에 통과할 거예요.)",
  ui_story_1018_10180601_51_dialog_content = "준비가 되면 언제든지 시작해도 좋습니다.",
  ui_story_1018_10180601_52_dialog_content = "(널 속이는 거야! 넌 지금 더스크 타운의 전장에 있어!)",
  ui_story_1018_10180601_53_dialog_content = "(지금 네 눈 앞에 있는 건 적이 아니라 네 상관 레이스 씨야! 빨리 이 방에서 나가!)",
  ui_story_1018_10180601_54_dialog_content = "(레이스 대원수님도 보고 계신다고요?)",
  ui_story_1018_10180601_55_dialog_content = "(잠깐만... 더스크 타운...? 왠지 거기 가본 적이 있는 것 같은데...)",
  ui_story_1018_10180601_56_dialog_content = "망설이고 있는 겁니까?",
  ui_story_1018_10180601_57_dialog_content = "아닙니다... 박사님, 시작해도 좋습니다.",
  ui_story_1018_10180601_58_dialog_content = "(제발! 눈을 떠!)",
  ui_story_1018_10180601_59_dialog_content = "(엄마, 지켜봐 줘요. 난 반드시 용감한 전사가 될 거예요.)",
  ui_story_1018_10180601_60_dialog_content = "그어어!",
  ui_story_1018_10180601_61_dialog_content = "(야! 정신 차려! 싸우면 안 돼!)",
  ui_story_1018_10180601_62_dialog_content = "박사님, 저 암귀를 본 순간... 온몸에 힘이 넘쳐나는 느낌이 듭니다.",
  ui_story_1018_10180601_63_dialog_content = "맞아요, 바로 그겁니다. 그 힘을 느끼고, 힘을 제어하세요.",
  ui_story_1018_10180601_64_dialog_content = "그어어!",
  ui_story_1018_10180601_65_dialog_content = "암귀... 죽어라!",
  ui_story_1018_10180601_66_dialog_content = "(어떡하지... 계속 감응을 안 끊었다간...)",
  ui_story_1018_10180601_67_dialog_content = "죽어라!",
  ui_story_1018_10180601_68_dialog_content = "그어어!",
  ui_story_1018_10180601_69_dialog_content = "<color=#e8d9bb>그어어!</color>",
  ui_story_1018_10180601_70_dialog_content = "이런! 저 외침 소리에 다른 병사들도 반응하는 것 같습니다!",
  ui_story_1018_10180602_1_dialog_content = "<color=#e8d9bb>타앙──!</color>",
  ui_story_1018_10180602_2_dialog_content = "......",
  ui_story_1018_10180602_3_dialog_content = "대원수님... 죄송합니다. 이 방법밖에 없었습니다.",
  ui_story_1018_10180602_4_dialog_content = "괜찮아, PlayerName?",
  ui_story_1018_10180602_5_dialog_content = "미안... 결국 구하지 못했어...",
  ui_story_1018_10180602_6_dialog_content = "우수한 병사였는데...",
  ui_story_1018_10180602_7_dialog_content = "악셀리아는 괴롭습니다...",
  ui_story_1018_10180602_8_dialog_content = "...저쪽에 있는 병사들은 어떻게 할 생각이지?",
  ui_story_1018_10180602_9_dialog_content = "......",
  ui_story_1018_10180602_10_dialog_content = "부하를 자기 손으로 죽인 내겐 일루미나 대원수의 자격이 없어...",
  ui_story_1018_10180602_11_dialog_content = "(대체 어떻게 해야 하는 거냐고...)",
  ui_story_1018_10180602_12_dialog_content = "(라인하르트... 너라면 어떻게 했을까.)",
  ui_story_1018_10180602_13_dialog_content = "내가 하지.",
  ui_story_1018_10180602_14_dialog_content = "레오 씨...",
  ui_story_1018_10180602_15_dialog_content = "너흰 그저 폭주한 병사들을 내가 독단적으로 죽이는 걸 막지 못한 거라고 하자고.",
  ui_story_1018_10180602_16_dialog_content = "난 더스크 타운을 지키는 기사일 뿐이다. 당신처럼 한 진영에 대한 책임을 질 필요는 없어.",
  ui_story_1018_10180602_17_dialog_content = "마음 약하게 굴수록 우리 손실만 커질 뿐이야. 당신도 현실을 마주하는 법을 배울 필요가 있어.",
  ui_story_1018_10180602_18_dialog_content = "아니... 애초에 난 저토록 많은 목숨을 짊어질 수 없는 거였어...",
  ui_story_1018_10180602_19_dialog_content = "부하들과 함께 더스크 타운 전투에서 이기겠다고 다짐했는데...",
  ui_story_1018_10180602_20_dialog_content = "저들은... 나 때문에 목숨을 잃었어...",
  ui_story_1018_10180602_21_dialog_content = "(난 나 자신에게 힘이 있다면... 내가 충분히 강하면 어떤 일이든 이룰 수 있다고 생각했어.)",
  ui_story_1018_10180602_22_dialog_content = "(충분히 강하다면... 하하...)",
  ui_story_1018_10180602_23_dialog_content = "레이스 씨, 전 레이스 씨가 맡은 일이 강해지는 것보다 훨씬 더 어렵다고 생각해요...",
  ui_story_1018_10180602_24_dialog_content = "......",
  ui_story_1018_10180602_25_dialog_content = "전사란 애초에 그 몸을 던져 위험을 막는 존재다.",
  ui_story_1018_10180602_26_dialog_content = "그 전사들 스스로가 위험이 되어, 자신의 생사를 선택할 수 없게 되었을 때──",
  ui_story_1018_10180602_27_dialog_content = "지금 같은 일은 우리가 지휘관으로서 유일하게 저들을 위해 해 줄 수 있는 일이다.",
  ui_story_1018_10180602_28_dialog_content = "지휘관으로서...",
  ui_story_1018_10180602_29_dialog_content = "(주먹을 펴라던 게 이런 거였어? 라인하르트...)",
  ui_story_1018_10180602_30_dialog_content = "당신의 부하들은 결코 헛되이 죽는 것이 아니다. 날 믿어. 저들의 고통은 금방 끝날 테니.",
  ui_story_1018_10180602_31_dialog_content = "기다려, 레오.",
  ui_story_1018_10180602_32_dialog_content = "당신 말이 맞을지도 몰라. 저들은... 결코 헛되이 죽는 게 아냐...",
  ui_story_1018_10180602_33_dialog_content = "그리고 나도 현실을 마주해야만 해...",
  ui_story_1018_10180602_34_dialog_content = "이대로 부하들을 고통스럽게 하느니, 내가 그 고통을 끊어주겠어.",
  ui_story_1018_10180602_35_dialog_content = "대원수님...",
  ui_story_1018_10180602_36_dialog_content = "전사들이여... 너희들의 옛 전우에게 마지막 이야기를 전하고 싶다.",
  ui_story_1018_10180602_37_dialog_content = "저흰 무슨 일이 있어도 영원히 대원수님을 따를 것입니다!",
  ui_story_1018_10180602_38_dialog_content = "......",
  ui_story_1018_10180602_39_dialog_content = "설령 내 말을 알아듣지 못하더라도, 지금 이 자리에서 너희들에게 약속하겠다.",
  ui_story_1018_10180602_40_dialog_content = "너희는 일루미나의 군인이다. 태어날 때부터 일루미나의 영광을 몸에 두르고,\n암귀를 쓰러트리는 사명을 어깨에 짊어졌다.",
  ui_story_1018_10180602_41_dialog_content = "전장은 항상 죽음과 가장 가까운 길임을 알면서도, 너희는 항상 두려움 없이 나아갔다...",
  ui_story_1018_10180602_42_dialog_content = "너희들은 용감한 일루미나의 병사로서 스러진 것이지...",
  ui_story_1018_10180602_43_dialog_content = "결코 버림받은 것이 아니다...",
  ui_story_1018_10180602_44_dialog_content = "너희들이 완수하지 못한 사명은 우리가 이어받아, 앞으로도 계속해서 싸워 나갈 것이다!",
  ui_story_1018_10180602_45_dialog_content = "그어어...",
  ui_story_1018_10180602_46_dialog_content = "(그래, 레이스... 곧 끝날 거야...)",
  ui_story_1018_10180602_47_dialog_content = "이제 너희는 짊어진 책임을 내려놓아도 좋다. 승리가 찾아왔을 때처럼...",
  ui_story_1018_10180602_48_dialog_content = "영원히 전쟁이 없는... 고향으로 돌아가라.",
  ui_story_1018_10180602_49_dialog_content = "그어어!",
  ui_story_1018_10180602_50_dialog_content = "저격수, 조준──!",
  ui_story_1018_10180602_51_dialog_content = "사격 개시!",
  ui_story_1018_10180602_52_dialog_content = "<color=#e8d9bb>탕탕탕──</color>",
  ui_story_1018_10180602_53_dialog_content = "......",
  ui_story_1018_10180602_54_dialog_content = "전쟁은 끝났다. 편히 잠들어라...",
  ui_story_1018_10180602_55_dialog_content = "......",
  ui_story_1018_10180602_56_dialog_content = "......",
  ui_story_1018_10180701_1_dialog_content = "<color=#e8d9bb>백야 요새로 향하는 길...</color>",
  ui_story_1018_10180701_2_dialog_content = "치치, 이제 곧 백야 요새예요. 버틸 수 있겠어요?",
  ui_story_1018_10180701_3_dialog_content = "응... 아직 괜찮아...",
  ui_story_1018_10180701_4_dialog_content = "상태가 안 좋아 보이네요... 아까 밧줄을 풀어버린 병사 때문에 놀란 건가요?",
  ui_story_1018_10180701_5_dialog_content = "아니야, 조셀린 언니...",
  ui_story_1018_10180701_6_dialog_content = "언니가 모두를 지키려고 열심히 하는 걸 보고 있으면 난 하나도 안 무서워.",
  ui_story_1018_10180701_7_dialog_content = "그치만 이번엔... 다친 사람이 너무 많아... 게다가 밧줄로 안 묶으면 진정시킬 수가 없어서...",
  ui_story_1018_10180701_8_dialog_content = "아, 그렇다고 저 사람들이 싫다는 건 아냐! 군인 오빠들도 우릴 지키려고 와 준 거니까...",
  ui_story_1018_10180701_9_dialog_content = "그냥... 언니는 계속 이런 모습을 보고 있으니까, 분명히 힘들 거 같아서...",
  ui_story_1018_10180701_10_dialog_content = "......",
  ui_story_1018_10180701_11_dialog_content = "치치, 그거 알고 있나요? 제가 어렸을 때 더스크 타운은 지금보다 더 힘든 곳이었어요...",
  ui_story_1018_10180701_12_dialog_content = "언니가... 어렸을 때?",
  ui_story_1018_10180701_13_dialog_content = "제가 12살 때, 더스크 타운은 암귀의 습격을 받았고, 부모님은 절 지키기 위해 목숨을 잃었죠.",
  ui_story_1018_10180701_14_dialog_content = "당시 살던 마을엔 우릴 도와줄 사람도 없었고, 우린 자기 힘만으로 살아갈 수밖에 없었어요.",
  ui_story_1018_10180701_15_dialog_content = "그래서 저와 별로 나이 차이가 안 나는 아이까지 무기를 들고 전장에 나서야 했고, 그중 많은 아이들과 그 이후로 다시는 만나지 못했죠...",
  ui_story_1018_10180701_16_dialog_content = "그다음엔... 어떻게 됐어?",
  ui_story_1018_10180701_17_dialog_content = "그 후 암귀가 마을을 덮쳤고, 전 마을에 남아 있던 아이들을 데리고 이곳저곳 도망을 다녔어요.\n그런 불안한 날들이 몇 년이나 계속되었죠.",
  ui_story_1018_10180701_18_dialog_content = "다행히 우린 원정 기사단의 구조를 받았고, 우릴 백야 교회 고아원에 데려다줬어요.\n그래서 전 수녀가 됐던 거예요.",
  ui_story_1018_10180701_19_dialog_content = "정말 힘들었겠네... 근데 조셀린 언니는 왜 그 뒤에도 원정 기사단을 따라 다니는 거야?",
  ui_story_1018_10180701_20_dialog_content = "전 우리가 적극적으로 암귀에 맞서지 않는다면, 더스크 타운의 백성들에게\n살아갈 희망은 없다고 믿어요.",
  ui_story_1018_10180701_21_dialog_content = "전 기사단 덕분에 살 수 있었어요.\n그러니 저도 저들처럼 더스크 타운의 백성들에게 안전한 삶을 만들어 주고 싶어요.",
  ui_story_1018_10180701_22_dialog_content = "언니는 정말 대단한 사람이구나!",
  ui_story_1018_10180701_23_dialog_content = "치치, 당신은 많은 사람을 도왔어요. 그건 어렸을 때의 저보다도 훨씬 훌륭한 거예요!",
  ui_story_1018_10180701_24_dialog_content = "자, 다 왔어요. 조금만 더 힘내요. 부상자를 들여보내 주면 이제 안전할 거예요.",
  ui_story_1018_10180701_25_dialog_content = "응!",
  ui_story_1018_10180701_26_dialog_content = "<color=#e8d9bb>똑똑── 똑똑똑──</color>",
  ui_story_1018_10180701_27_dialog_content = "전 더스크 타운의 전사 조셀린이라고 해요.\n부상자가 있으니 백야 요새에서 치료와 보호를 제공해 주셨으면 해요!",
  ui_story_1018_10180701_28_dialog_content = "성주님의 명령이다. 백야성 사람 외에는 누구도 들여보낼 수 없다. 다른 피난처를 찾아봐라.",
  ui_story_1018_10180701_29_dialog_content = "제 얘기 좀 들어 보세요. 데려온 부상자 중에는 백야 요새의 기사도 있어요.\n모두 저희 동포잖아요. 그럼 적어도 저들만이라도 들여보내 주세요.",
  ui_story_1018_10180701_30_dialog_content = "그동안 「강철가시 기사단」도 이미 여러 차례 요청했다.\n하지만 백야 요새의 자원도 한계가 있고, 더는 부상자를 받아들일 여유가 없다.",
  ui_story_1018_10180701_31_dialog_content = "병사님...",
  ui_story_1018_10180701_32_dialog_content = "<color=#e8d9bb>콰당탕──</color>",
  ui_story_1018_10180701_33_dialog_content = "조셀린 언니! 저 일루미나 부상병 두 사람이 계속 몸부림치고 있어!",
  ui_story_1018_10180701_34_dialog_content = "또 밧줄을 풀고 다른 부상자들을 공격한다면...",
  ui_story_1018_10180701_35_dialog_content = "지금 당신들이 데리고 있는 부상자는 백야 요새의 백성들을 해칠 위험이 있는 것으로 보인다!\n그렇다면 더더욱 들여보내줄 수 없다!",
  ui_story_1018_10180701_36_dialog_content = "그렇다면...",
  ui_story_1018_10180701_37_dialog_content = "부디 백야 교구의 요제프 신부에게 전해 주세요──!",
  ui_story_1018_10180701_38_dialog_content = "저 조셀린은 더스크 타운의 「성녀」로서, 백야 교회가 오로리안들을 지켜주길 바란다고 말이에요.",
  ui_story_1018_10180701_39_dialog_content = "요제프 신부는 중요한 용무가 있어 지금 성 안에 계시지 않는다.\n게다가 그 「성녀」라는 것도 그저 더스크 타운 백성들이 당신을 부르는 호칭일 뿐이잖나.",
  ui_story_1018_10180701_40_dialog_content = "설령 당신이 진짜 「성녀」라 해도 성주님의 명령을 어길 수는 없다!",
  ui_story_1018_10180701_41_dialog_content = "빛의 신의 백성들은 지금 극심한 고난을 겪고 있어요!\n설마 백야 교회는 오로리안이 어떻게 되든 상관하지 않는 건가요?!",
  ui_story_1018_10180701_42_dialog_content = "그어어!",
  ui_story_1018_10180701_43_dialog_content = "으악! 벼, 병사가 암귀로 변했어!",
  ui_story_1018_10180701_44_dialog_content = "조셀린 언니!",
  ui_story_1018_10180701_45_dialog_content = "여러분! 진정하세요! 즉시 마차에서 멀리 떨어지고, 여긴 제게 맡기세요!",
  ui_story_1018_10180701_46_dialog_content = "<size=30>성문을 열어주세요.</size>",
  ui_story_1018_10180701_47_dialog_content = "저런 자들을 들여보내는 건 자멸하겠다는 거나 마찬가지라고...!",
  ui_story_1018_10180701_48_dialog_content = "성문을 열어주세요.",
  ui_story_1018_10180701_49_dialog_content = "감히 「성녀」의 뜻을 거스르다니, 백야의 교리를 잊어버린 것이냐!",
  ui_story_1018_10180701_50_dialog_content = "나 하이가든 호위대장 카렌이 백야 요새 성주 대행의 이름으로 명한다!\n성문을 열고 난민을 들여보내라!",
  ui_story_1018_10180701_51_dialog_content = "암귀는 내게 맡기고 성문을 열어라!",
  ui_story_1018_10180701_52_dialog_content = "카, 카렌 전하...! 알겠습니다!",
  ui_story_1018_10180701_53_dialog_content = "<color=#e8d9bb>덜컹──</color>",
  ui_story_1018_10180702_1_dialog_content = "<color=#e8d9bb>이 세상의 것이 아닌 듯한 빛 앞에서 사람들은 무심코 무릎을 꿇고 싶은 마음이 들었다...</color>",
  ui_story_1018_10180702_2_dialog_content = "저분은... 진짜 「성녀님」이세요!",
  ui_story_1018_10180702_3_dialog_content = "틀림없어요... 저 거룩한 빛은 오직 「성녀님」의 것이에요!",
  ui_story_1018_10180702_4_dialog_content = "빛의 신께서는 수녀가 고한 모든 것이 거짓 없는 진실임을 아십니다.",
  ui_story_1018_10180702_5_dialog_content = "부디 거룩한 빛으로 방황하는 오로리안을 감싸 주소서.",
  ui_story_1018_10180702_6_dialog_content = "조셀린 언니! 병사들 몸이 금빛으로 빛나고 있어!",
  ui_story_1018_10180702_7_dialog_content = "정말 기묘한 느낌이야... 몸의 통증이 사라지고 있어...",
  ui_story_1018_10180702_8_dialog_content = "앗... 조셀린 언니... 우는 거야...?",
  ui_story_1018_10180702_9_dialog_content = "미안해요... 「성녀님」을 직접 뵙게 돼서... 부끄러운 모습을 보였네요..",
  ui_story_1018_10180702_10_dialog_content = "치치, 저분이야말로 신의 대리인으로서 세상에 오신 사자, 백야 교회의 「성녀님」이에요!",
  ui_story_1018_10180702_11_dialog_content = "「성녀님」...",
  ui_story_1018_10180702_12_dialog_content = "조셀린──!",
  ui_story_1018_10180702_13_dialog_content = "요제프 신부님! 만물은 백야 아래에──",
  ui_story_1018_10180702_14_dialog_content = "만물은 백야 아래에── 죄송합니다. 더스크 타운의 병사들에게 큰 고통을 주고 말았습니다!\n레오 단장님은 괜찮습니까?",
  ui_story_1018_10180702_15_dialog_content = "일루미나 병사들과 아이테르 덕분에 암귀의 수는 이미 크게 줄었어요.",
  ui_story_1018_10180702_16_dialog_content = "다만 아직 사라지지 않은 늪은 여전히 위험 요인이에요. 일루미나 병사들의 상황도 좋지 않고요...",
  ui_story_1018_10180702_17_dialog_content = "정말 죄송합니다. 요새의 병사들은 백야성 귀족의 명령만 듣고 있고,\n성주님이 파견하신 지원군들조차 요새의 방어에만 치중하고 있었습니다.",
  ui_story_1018_10180702_18_dialog_content = "전 계속 성주님께 지원을 요청하는 것 외에는 아무것도 할 수가 없었습니다...",
  ui_story_1018_10180702_19_dialog_content = "그저 교회 사람들을 더스크 타운으로 보내 돕도록 하고,\n계속해서 백야 신전에 도움을 청하는 편지를 쓰는 수밖에 없었지요.",
  ui_story_1018_10180702_20_dialog_content = "그러셨군요! 이제 성녀님께서 오셨으니, 백야 교구는 신의 은총을 받았네요!",
  ui_story_1018_10180702_21_dialog_content = "저도 이렇게 될 줄은 정말 몰랐습니다.\n사실 전 편지를 보내고 나서 백야성으로 직접 가려던 참이었습니다.",
  ui_story_1018_10180702_22_dialog_content = "하지만 출발 전에 성녀님께서 직접 오신다는 전갈을 받고 이곳에서 기다리게 되었지요.",
  ui_story_1018_10180702_23_dialog_content = "자세한 건 나중에 얘기하시죠. 우선 교회에 가서 준비하고 있겠습니다.",
  ui_story_1018_10180702_24_dialog_content = "더스크 타운의 부상자들은 제가 교회의 인원들에게 데리고 가라고 하겠습니다.",
  ui_story_1018_10180702_25_dialog_content = "정말 고마워요, 요제프 신부님!",
  ui_story_1018_10180702_26_dialog_content = "다만...일부 부상자의 상황은 조금 복잡합니다. 부디 조심해 주세요.",
  ui_story_1018_10180702_27_dialog_content = "안심하시지요. 성녀님과 함께 오신 성직자분들도 마찬가지로 의료에 정통하시니,\n부상자들을 잘 돌보실 수 있을 겁니다.",
  ui_story_1018_10180702_28_dialog_content = "만물은 백야 아래에──",
  ui_story_1018_10180702_29_dialog_content = "만물은 백야 아래에──",
  ui_story_1018_10180702_30_dialog_content = "<size=30>휴... 이 정도면 됐겠죠.</size> 빛의 신이여 영원하라.",
  ui_story_1018_10180702_31_dialog_content = "저, 정말 성녀님이십니까...? 신에게 버림받은 이 땅에 신의 사자께서 강림하시다니!",
  ui_story_1018_10180702_32_dialog_content = "성녀님이 계신다면 저 늪도 더는 퍼지지 않을 거야!",
  ui_story_1018_10180702_33_dialog_content = "봐! 마을 위를 뒤덮던 먹구름도 성녀님이 전부 몰아내셨어! 암귀 놈들은 이제 더는 갈 곳도 없다고!",
  ui_story_1018_10180702_34_dialog_content = "성녀님! 감사합니다!",
  ui_story_1018_10180702_35_dialog_content = "고마워할 거 없어요... 그리고 성녀님이라고 부를 필요 없어요...",
  ui_story_1018_10180702_36_dialog_content = "성녀님, 부탁이 있습니다... 제 아이는 아직 더스크 타운에서 싸우고 있습니다...",
  ui_story_1018_10180702_37_dialog_content = "성녀님! 제발 제 얘기 좀 들어주세요...",
  ui_story_1018_10180702_38_dialog_content = "성녀님...",
  ui_story_1018_10180702_39_dialog_content = "여, 여러분... 힐다라고 불러주세요...",
  ui_story_1018_10180702_40_dialog_content = "여러분의 기도는 힐다가 모두 귀기울여 들을게요...",
  ui_story_1018_10180702_41_dialog_content = "성녀님! 저흴 두고 가지 마세요...",
  ui_story_1018_10180702_42_dialog_content = "......",
  ui_story_1018_10180702_43_dialog_content = "일일이 답하실 필요는 없습니다.",
  ui_story_1018_10180702_44_dialog_content = "하지만... 이건 힐다가 처음으로 신전 밖의 오로리안과 이야기를 나누는 건데요...",
  ui_story_1018_10180702_45_dialog_content = "답하실 필요 없습니다.",
  ui_story_1018_10180702_46_dialog_content = "...알겠어요.",
  ui_story_1018_10180702_47_dialog_content = "당신들의 마음은 성녀님께서 이미 헤아려 주셨어.",
  ui_story_1018_10180702_48_dialog_content = "고마워요, 카렌~ 힐다도 사실 정말 기쁘거든요. 헤헷~",
  ui_story_1018_10180702_49_dialog_content = "응? 당신은 누구죠? 왜... 힐다를 계속 보는 건가요...?",
  ui_story_1018_10180702_50_dialog_content = "너 머리 위에 그 뿔은 뭐야?",
  ui_story_1018_10180702_51_dialog_content = "무례하군요!",
  ui_story_1018_10180702_52_dialog_content = "괜찮아요~",
  ui_story_1018_10180702_53_dialog_content = "이거요? 사실 이건 <color=#FFB400>라이콘</color> 이야기랑 관계가 있는 건데요...",
  ui_story_1018_10180702_54_dialog_content = "라이콘 수호신 이야기 말이야? 어렸을 때부터 들어봤어! 그 이야기는...",
  ui_story_1018_10180702_55_dialog_content = "<color=#e8d9bb>조셀린이 부상자를 무사히 교회로 보낸 후...</color>",
  ui_story_1018_10180702_56_dialog_content = "인사가 늦었습니다. 수녀 조셀린, 성녀님을 뵙습니다.",
  ui_story_1018_10180702_57_dialog_content = "안녕하세요, 조셀린. 요제프 신부에게 이야기는 들었어요.\n잘 부탁해요. 힐다가 도움이 됐으면 좋겠어요.",
  ui_story_1018_10180702_58_dialog_content = "정말 송구스럽게도 전 암귀에게 해를 입은 오로리안들을 구할 수 없었습니다.\n저들을 치유한 것은 오로지 성녀님의 빛이었습니다.",
  ui_story_1018_10180702_59_dialog_content = "그렇지 않아요. 당신은 전력을 다해 오로리안을 구했어요. 당신은 정말 선량한 사람이에요.",
  ui_story_1018_10180702_60_dialog_content = "괜찮다면... 힐다라고 불러주세요. 힐다는 제 이름이에요.\n힐다는 아직 당신에게 배우고 싶은 게 아주 많아요!",
  ui_story_1018_10180702_61_dialog_content = "그게 무슨... 성녀님께 제가 어떻게 감히 그럴 수가 있겠어요!",
  ui_story_1018_10180702_62_dialog_content = "언니, 난 왠지 성녀님이 더스크 타운의 언니들처럼 다정한 느낌이야.",
  ui_story_1018_10180702_63_dialog_content = "그럼요! 치치, 그러고 보니까 아직 이야기도 안 끝났잖아요. 사실 그 이야기의 결말은...",
  ui_story_1018_10180702_64_dialog_content = "......",
  ui_story_1018_10180702_65_dialog_content = "무슨 생각을 하고 있지? 조셀린.",
  ui_story_1018_10180702_66_dialog_content = "카렌 전하... 그저 조금 의외라서요...",
  ui_story_1018_10180702_67_dialog_content = "성녀님은 성녀이시면서도... 어린아이의 천진난만함을 지니고 계시네요.",
  ui_story_1018_10180702_68_dialog_content = "사실 나도 처음 성녀님을 뵀을 때 저 세상 물정 모르는 모습에 꽤 놀랐어.",
  ui_story_1018_10180702_69_dialog_content = "하지만 당신도 보다시피, 성녀님은 치치 같은 나이의 여자애를 허물없이 대하고,\n더스크 타운에 전해지는 이야기에도 무척 호기심을 가지고 계셔.",
  ui_story_1018_10180702_70_dialog_content = "어쩌면 성녀님은 성녀로서의 역할 외의 일에 대해서는 잘 모르시는 걸지도 모르지.",
  ui_story_1018_10180702_71_dialog_content = "그렇네요. 제가 식견이 좁았네요.",
  ui_story_1018_10180702_72_dialog_content = "부상자들은 교회로 보내고 나면, 당신도 남아서 치료를 도울 건가?",
  ui_story_1018_10180702_73_dialog_content = "더스크 타운의 전투는 아직 끝나지 않았어요.\n전 다시 전장으로 돌아가서 전사들과 함께 싸울 거예요.",
  ui_story_1018_10180702_74_dialog_content = "여긴 요제프 신부님이 계시니까 안심할 수 있어요.",
  ui_story_1018_10180702_75_dialog_content = "알겠어. 나도 백야성의 지원군을 이끌고 함께 가겠어.",
  ui_story_1018_10180702_76_dialog_content = "힐다도 갈게요! 우리... 아직 시간 있죠...?",
  ui_story_1018_10180702_77_dialog_content = "네, 성녀님.",
  ui_story_1018_10180702_78_dialog_content = "성녀님이 함께하신다면 더스크 타운은 반드시 위기를 벗어날 수 있을 거예요. 지금 바로 가시죠!",
  ui_story_1018_10180801_1_dialog_content = "<color=#e8d9bb>더스크 타운 밖</color>",
  ui_story_1018_10180801_2_dialog_content = "『노라 님, 어째서 그 여자를 도우신 건지 이해가 되지 않습니다.』",
  ui_story_1018_10180801_3_dialog_content = "『그 여자도 자기 병사들처럼 우리와 하나가 되었어야 합니다.』",
  ui_story_1018_10180801_4_dialog_content = "궁지에 몰아넣었는데도 살아남다니, 실험 결과는 확실히 예상 밖이었어.",
  ui_story_1018_10180801_5_dialog_content = "그 몸속에 있는 「씨앗」이 왜 그렇게 특별했는지 확인할 수 있다면, 이번 일도 헛수고는 아닐 거야.",
  ui_story_1018_10180801_6_dialog_content = "『노라 님, 전 벌써 한참 동안 이빨을 갈지 못했습니다.』",
  ui_story_1018_10180801_7_dialog_content = "머드번들도 이제 슬슬 회복됐겠네. 카펫을 좀 더 펼쳐 봐.",
  ui_story_1018_10180801_8_dialog_content = "『계속 전진하는 겁니까?』",
  ui_story_1018_10180801_9_dialog_content = "맞아, 대신 이번엔 더스크 타운을 피해서 가.",
  ui_story_1018_10180801_10_dialog_content = "늪이 일루미나까지 닿으면 율리시스가 가진 병사들은 전부 암귀가 되겠지...",
  ui_story_1018_10180801_11_dialog_content = "『그럼 이 병사들은 어떻게 하실 겁니까?』",
  ui_story_1018_10180801_12_dialog_content = "머드번들한테 방어선까지 옮기라고 해. 물론 그 「예술품」도.",
  ui_story_1018_10180801_13_dialog_content = "여길 떠나기 전에 내가 준비한 선물을 그 여자가 마음에 들어 하는지 보고 싶거든.",
  ui_story_1018_10180801_14_dialog_content = "대원수님! 악셀리아 대장님! 제9부대를 찾았습니다...",
  ui_story_1018_10180801_15_dialog_content = "전부... 보루 부근의 늪 속에 쓰러져 있었습니다.",
  ui_story_1018_10180801_16_dialog_content = "늪이 물러나서 찾을 수 있었습니다만... 이미...",
  ui_story_1018_10180801_17_dialog_content = "......",
  ui_story_1018_10180801_18_dialog_content = "안내해.",
  ui_story_1018_10180801_19_dialog_content = "현 부대로 배치된 전차 승무원을 제외한 제9부대 병사 전원이 여기서 발견되었습니다.",
  ui_story_1018_10180801_20_dialog_content = "나머지 병사들은... 「엔진 7호」 파일럿까지 모두 희생됐습니다.",
  ui_story_1018_10180801_21_dialog_content = "저 병사는 왜... 저렇게 죽은 것입니까...?",
  ui_story_1018_10180801_22_dialog_content = "아래턱에 총상의 흔적이 있고, 손가락은 총의 방아쇠에 걸려 있다.\n폭주하기 전에 스스로 목숨을 끊은 게 분명하군...",
  ui_story_1018_10180801_23_dialog_content = "......",
  ui_story_1018_10180801_24_dialog_content = "여기 있는 자들은 그저 일반 병사겠지?",
  ui_story_1018_10180801_25_dialog_content = "그렇습니다...",
  ui_story_1018_10180801_26_dialog_content = "저 둘은 서로를 부축하고 있습니다. 늪을 막으려고 했던 것 같습니다...",
  ui_story_1018_10180801_27_dialog_content = "이 얼마나 잔혹한... 거의 뼈밖에 남지 않았잖습니까...",
  ui_story_1018_10180801_28_dialog_content = "...이런 최후를 맞이하다니, 저들은... 정말 용감한 병사들이었어.",
  ui_story_1018_10180801_29_dialog_content = "...일전의 내 성급한 판단을 당신들에게 사과하고 싶다.",
  ui_story_1018_10180801_30_dialog_content = "......",
  ui_story_1018_10180801_31_dialog_content = "레이스 씨...",
  ui_story_1018_10180801_32_dialog_content = "오랜 세월 변방을 지켜왔지만, 나도 이런 광경은 처음이었어.",
  ui_story_1018_10180801_33_dialog_content = "우리가 뭔가 할 수 있는 게 없을까...?",
  ui_story_1018_10180801_34_dialog_content = "계속 주변 상황을 살피고, 부상자를 찾아내자.",
  ui_story_1018_10180801_35_dialog_content = "<color=#e8d9bb>부글부글──</color>",
  ui_story_1018_10180801_36_dialog_content = "단장님! 병사들 뒤쪽 늪의 움직임이 이상합니다!",
  ui_story_1018_10180801_37_dialog_content = "더스크 타운이 사람들을 끌어들이는 이유가 이런 걸까?",
  ui_story_1018_10180801_38_dialog_content = "역시 다른 그 무엇 때문도 아니었어.\n오직 이 진정한 「예술품」만을 위해서인 거지.",
  ui_story_1018_10180801_39_dialog_content = "노라?!",
  ui_story_1018_10180801_40_dialog_content = "계속 숨어 있던 적이 너냐?",
  ui_story_1018_10180801_41_dialog_content = "난 대원수한테 인사하러 온 거야. 후련하게 싸웠어?",
  ui_story_1018_10180801_42_dialog_content = "노...라...!",
  ui_story_1018_10180801_43_dialog_content = "긴장 풀어. 네 그 몸으로 뭘 하려고? 진심이야?",
  ui_story_1018_10180801_44_dialog_content = "레이스 대원수를 해치는 일은 허락하지 않습니다!",
  ui_story_1018_10180801_45_dialog_content = "또 너야? 멍청한 녀석, 아무래도 봐주면 안 될 것 같네.",
  ui_story_1018_10180801_46_dialog_content = "내 부하들에게 한 짓은 내가 몇 배로 갚아주마!",
  ui_story_1018_10180801_47_dialog_content = "갚아? 네 부하를 전부 죽여봤자 내가 입은 손실은 못 갚아.",
  ui_story_1018_10180801_48_dialog_content = "아마 왜 네가 지금까지 버틸 수 있는지도 모르고 있겠지?\n일루미나가 네게 한 짓은 이미 널 100번 죽이고도 남았어.",
  ui_story_1018_10180801_49_dialog_content = "네가 여기서 애쓰는 동안, 일루미나가 왜 전혀 움직이지 않는지 알고 싶지 않아?",
  ui_story_1018_10180801_50_dialog_content = "헛소리 집어 치워! 파렴치한 자식!",
  ui_story_1018_10180801_51_dialog_content = "조금은 아는 모양이네.\n그럼 저들은 신임 대원수가 자기 손으로 부하를 죽이는 인간이라는 걸 알까?",
  ui_story_1018_10180801_52_dialog_content = "...노라, 죽여버리겠어!",
  ui_story_1018_10180801_53_dialog_content = "레이스 씨, 진정해요! 지금 일부러 자극하는 거예요!",
  ui_story_1018_10180801_54_dialog_content = "......",
  ui_story_1018_10180801_55_dialog_content = "더스크 타운에서 일어나는 모든 게 네 짓이라는 건 진작에 알고 있었어. 오늘은 절대 놓치지 않아!",
  ui_story_1018_10180801_56_dialog_content = "부정하진 않을게. 근데 나도 좋아서 하는 거야. 도둑놈에 대한 벌이라고나 할까?",
  ui_story_1018_10180801_57_dialog_content = "예술품은 이미 감상한 것 같고, 진짜 전시는 지금부터야. 눈 똑바로 뜨고 보라고!",
  ui_story_1018_10180801_58_dialog_content = "뭘 하려는 거지?",
  ui_story_1018_10180801_59_dialog_content = "호오? 그 앞에 선다는 건, 나랑 일대일로 붙어보려고?",
  ui_story_1018_10180801_60_dialog_content = "악셀리아도 있습니다...",
  ui_story_1018_10180801_61_dialog_content = "맞아, 나도 있다고!",
  ui_story_1018_10180801_62_dialog_content = "마음대로 해. 난 이미 질렸으니까. 지금 너희 상대는 내가 아냐──",
  ui_story_1018_10180801_63_dialog_content = "그어어...",
  ui_story_1018_10180801_64_dialog_content = "「엔진 7호」 파일럿 목소리야... 이미 죽은 거 아니었어...?",
  ui_story_1018_10180801_65_dialog_content = "그어어...",
  ui_story_1018_10180801_66_dialog_content = "...너희들은 이미 한 번 자신을 희생했어...",
  ui_story_1018_10180801_67_dialog_content = "더는 이렇게...",
  ui_story_1018_10180801_68_dialog_content = "대원수님... 악셀리아는 대원수님의 분노를 느꼈습니다...",
  ui_story_1018_10180801_69_dialog_content = "너...",
  ui_story_1018_10180801_70_dialog_content = "악셀리아는 대원수님을 지키고 싶습니다...\n비록 악셀리아는 대원수님의 체온을 느낄 수 없지만...",
  ui_story_1018_10180801_71_dialog_content = "그렇지만 잉겔이 말했습니다... 여기가 바로 악셀리아의 원래 심장이 있던 곳이라고요...",
  ui_story_1018_10180801_72_dialog_content = "전 그것이 제 몸속의 힘보다 더 따뜻했을 거라고 생각합니다...",
  ui_story_1018_10180801_73_dialog_content = "악셀리아...",
  ui_story_1018_10180801_74_dialog_content = "...걱정 마. 이 힘이 날 조종하게 만들진 않을 테니까.",
  ui_story_1018_10180801_75_dialog_content = "단장님... 부대 전체가 이쪽으로 오고 있습니다! 이제 어떡합니까?",
  ui_story_1018_10180801_76_dialog_content = "늪이... 아니, 다크매터가 몸에서 흘러나오는 게 눈으로도 보일 정도입니다!\n병사들의 눈에서 기괴한 빛이 나고 있습니다!",
  ui_story_1018_10180801_77_dialog_content = "<color=#e8d9bb>휘이잉──</color>",
  ui_story_1018_10180801_78_dialog_content = "「꿰뚫어라, 우레의 창이여!」",
  ui_story_1018_10180801_79_dialog_content = "저들의 영혼은 이미 명예롭게 고향으로 돌아갔어. 계속 싸우는 건 저들에 대한 모욕이야.",
  ui_story_1018_10180801_80_dialog_content = "모두 잘 들어라. 더는 우리의 병사들을 고통스럽게 만들지 마라.\n저들은 이미 우릴 지켜주었고, 저들의 희생은 결코 헛되지 않았다!",
  ui_story_1018_10180801_81_dialog_content = "알겠어, 대원수.",
  ui_story_1018_10180801_82_dialog_content = "멋지네, 아주 악독해. 그럼 나머지는 내가 데려가도 상관 없는 거겠지?",
  ui_story_1018_10180801_83_dialog_content = "거기 서!",
  ui_story_1018_10180801_84_dialog_content = "노라와 함께 늪 속으로 사라진 건...",
  ui_story_1018_10180801_85_dialog_content = "악셀리아의 부하들입니다.",
  ui_story_1018_10180801_86_dialog_content = "제8부대를 악셀리아에게 돌려주세요!",
  ui_story_1018_10180801_87_dialog_content = "악셀리아...! 저대로 괜찮을까요...?",
  ui_story_1018_10180801_88_dialog_content = "함께 간 부하들은 처음부터 쭉 악셀리아를 따르던 자들이야. 아마 괜찮을 거야.",
  ui_story_1018_10180801_89_dialog_content = "여길 처리하고 나면 우리도 바로 쫓아간다!",
  ui_story_1018_10180801_90_dialog_content = "네!",
  ui_story_1018_10180802_1_dialog_content = "그런 몸으로 아직도 쫓아오는 거야?",
  ui_story_1018_10180802_2_dialog_content = "악셀리아는... 모두를 지켜야 합니다... 그들을 돌려주세요.",
  ui_story_1018_10180802_3_dialog_content = "그럼 어디 한번 날 죽여볼래?",
  ui_story_1018_10180802_4_dialog_content = "악셀리아는... 제8부대를 데리고 돌아갑니다!",
  ui_story_1018_10180802_5_dialog_content = "사람은 이렇게 죽이는 거야!",
  ui_story_1018_10180802_6_dialog_content = "안 돼요...",
  ui_story_1018_10180802_7_dialog_content = "악셀리아 대장님... 괜찮으십니까...?",
  ui_story_1018_10180802_8_dialog_content = "......",
  ui_story_1018_10180802_9_dialog_content = "그건 무슨 표정이야? 율리시스가 만든 깡통 인간 주제에... 고통을 느끼는 거야?",
  ui_story_1018_10180802_10_dialog_content = "악셀리아는... 깡통 인간이 아닙니다...",
  ui_story_1018_10180802_11_dialog_content = "고집도 세네.",
  ui_story_1018_10180802_12_dialog_content = "그들을 해치지 마세요... 괴로워하고 있잖아요...",
  ui_story_1018_10180802_13_dialog_content = "얘들한테 네 말이 들릴 것 같아?",
  ui_story_1018_10180802_14_dialog_content = "악셀리아는 당신을 용서하지 않습니다...",
  ui_story_1018_10180802_15_dialog_content = "내가 얘들을 죽이는 걸 보는 거 말고 네가 뭘 할 수 있는데?",
  ui_story_1018_10180802_16_dialog_content = "『노라 님, 머드번들이 준비되었습니다.』",
  ui_story_1018_10180802_17_dialog_content = "좋아, 그렇게까지 간청한다면 몇 개는 같이 놀게 남겨줄게. 나머지는... 후훗.",
  ui_story_1018_10180802_18_dialog_content = "악셀리아 대장님... 전부... 늪 속으로 사라져 버렸습니다...",
  ui_story_1018_10180802_19_dialog_content = "모두를... 돌려주세요...",
  ui_story_1018_10180802_20_dialog_content = "그어어!",
  ui_story_1018_10180802_21_dialog_content = "악셀리아 대장님! 위험합니다!",
  ui_story_1018_10180802_22_dialog_content = "그어어!",
  ui_story_1018_10180802_23_dialog_content = "멈추세요...",
  ui_story_1018_10180802_24_dialog_content = "살려주세요! 대장님!",
  ui_story_1018_10180802_25_dialog_content = "그어어!",
  ui_story_1018_10180802_26_dialog_content = "으아악...",
  ui_story_1018_10180802_27_dialog_content = "...당신들은 전쟁 기계가 아닙니다... 모두를 죽이지 말아주세요...",
  ui_story_1018_10180802_28_dialog_content = "그어어!",
  ui_story_1018_10180802_29_dialog_content = "으아악──",
  ui_story_1018_10180802_30_dialog_content = "......",
  ui_story_1018_10180802_31_dialog_content = "(비명 소리도... 바람소리도, 무기 소리도... 더는 들리지 않습니다...)",
  ui_story_1018_10180802_32_dialog_content = "(병사는... 이미 죽은 건가요...?)",
  ui_story_1018_10180802_33_dialog_content = "(어쩌면... 악셀리아가 죽은 건지도 모릅니다...)",
  ui_story_1018_10180802_34_dialog_content = "(......)",
  ui_story_1018_10180802_35_dialog_content = "대장님! 살려주세요!",
  ui_story_1018_10180802_36_dialog_content = "(몸이 무거워서... 움직일수가 없습니다...)",
  ui_story_1018_10180802_37_dialog_content = "(빨리... 구해야 합니다!)",
  ui_story_1018_10180802_38_dialog_content = "<color=#e8d9bb>콰당──</color>",
  ui_story_1018_10180802_39_dialog_content = "(...부하의 몸이 땅에 내동댕이쳐졌습니다...)",
  ui_story_1018_10180802_40_dialog_content = "(마치... 악셀리아의 몸이 땅에 쓰러진 것처럼 느껴집니다...)",
  ui_story_1018_10180802_41_dialog_content = "<color=#e8d9bb>그어어!</color>",
  ui_story_1018_10180802_42_dialog_content = "(부하의 가슴을 찢고... 그 몸을 먹고 있습니다...)",
  ui_story_1018_10180802_43_dialog_content = "(부하가 피바다 속에 쓰러졌습니다...)",
  ui_story_1018_10180802_44_dialog_content = "(하지만 악셀리아는... 쓰러진 것이 자신처럼 느껴집니다...)",
  ui_story_1018_10180802_45_dialog_content = "<color=#e8d9bb>쿵── 콰당──</color>",
  ui_story_1018_10180802_46_dialog_content = "(5번, 6번...)",
  ui_story_1018_10180802_47_dialog_content = "(악셀리아는 이미 6번 쓰러졌습니다...)",
  ui_story_1018_10180802_48_dialog_content = "(10번...)",
  ui_story_1018_10180802_49_dialog_content = "(23번, 24번...)",
  ui_story_1018_10180802_50_dialog_content = "(102번...)",
  ui_story_1018_10180802_51_dialog_content = "(2000번...)",
  ui_story_1018_10180802_52_dialog_content = "(......)",
  ui_story_1018_10180802_53_dialog_content = "(11111번...)",
  ui_story_1018_10180802_54_dialog_content = "(악셀리아는 아직도 쓰러지고 있습니다...)",
  ui_story_1018_10180802_55_dialog_content = "(악셀리아는 우수한 전투 병기라고 아버지는 말씀하셨습니다.\n전투 병기는 결코 흔들리지 않습니다.)",
  ui_story_1018_10180802_56_dialog_content = "(하지만 악셀리아는 몇 번이나 쓰러졌습니다...)",
  ui_story_1018_10180802_57_dialog_content = "(어떻게 하면 이 모든 것을 막을 수 있는지, 악셀리아는 모르겠습니다...)",
  ui_story_1018_10180802_58_dialog_content = "악셀리아!",
  ui_story_1018_10180802_59_dialog_content = "(아버지...? 악셀리아를 용서해 주세요...)",
  ui_story_1018_10180802_60_dialog_content = "악셀리아! 잊지 마! 넌 인간으로 살아가야 해!",
  ui_story_1018_10180802_61_dialog_content = "(살아간다... 악셀리아는 어떻게 하면 좋을까요...)",
  ui_story_1018_10180802_62_dialog_content = "(어쩌면... 악셀리아도...)",
  ui_story_1018_10180802_63_dialog_content = "그어어...",
  ui_story_1018_10180802_64_dialog_content = "그어어!",
  ui_story_1018_10180802_65_dialog_content = "「천둥의 힘!」",
  ui_story_1018_10180802_66_dialog_content = "정신 차려, 악셀리아! 내 말 들어!",
  ui_story_1018_10180802_67_dialog_content = "레이스! 더 가면 안 돼!",
  ui_story_1018_10180802_68_dialog_content = "그어어...",
  ui_story_1018_10180802_69_dialog_content = "어떻게... 악셀리아까지...",
  ui_story_1018_10180802_70_dialog_content = "<color=#e8d9bb>이랴──!</color>",
  ui_story_1018_10180802_71_dialog_content = "이 목소리...",
  ui_story_1018_10180802_72_dialog_content = "뭐야?! 이 엄청난 빛은...?",
  ui_story_1018_10180802_73_dialog_content = "대원수님! 레오 단장님! 늦어서 미안해요──",
  ui_story_1018_10180802_74_dialog_content = "수녀 조셀린, 성녀의 빛으로 세례를 받아, 오로리안들을 수호하여 신의 품으로 인도하겠습니다!",
  ui_story_1018_10180802_75_dialog_content = "사악한 암귀가 더는 여러분을 해치지 못할 것입니다!",
  ui_story_1018_10180802_76_dialog_content = "단장님! 조셀린입니다! 그리고... 카렌 전하와 백야성 공중기병입니다!",
  ui_story_1018_10180802_77_dialog_content = "...저 빛 속에 서 있는 소녀... 설마...",
  ui_story_1018_10180802_78_dialog_content = "성녀가 귀를 기울여 들으매, 뭇 백성들이 돌아갈 때가 아직 이르지 않았노라.",
  ui_story_1018_10180802_79_dialog_content = "만물에는 영혼이 있나니, 너는 신의 강보 속에서 타락의 힘을 씻어내리라.",
  ui_story_1018_10180802_80_dialog_content = "성스러운 빛으로 몸을 씻고, 거룩한 기도를 귀담아 들어, 축복의 빛을 얻으라.",
  ui_story_1018_10180802_81_dialog_content = "봉인의 힘이 이 땅에 솟아날지니, 원컨대 다치고 병든 자를 고치고, 악한 뜻을 없애어지이다.",
  ui_story_1018_10180802_82_dialog_content = "빛의 신이시여, 영원하소서.\n오로리안이여, 불멸할지어다.",
  ui_story_1018_10180802_83_dialog_content = "단장님! 병사들의 몸이 금빛으로 빛나고 있습니다!",
  ui_story_1018_10180802_84_dialog_content = "틀림없어... 조셀린이 성녀님을 모셔오다니...",
  ui_story_1018_10180802_85_dialog_content = "저 사람이 병사들을 되돌려 준 거야?",
  ui_story_1018_10180802_86_dialog_content = "그래... 성녀님은 다크매터의 영향을 제거할 수 있을 뿐만 아니라,\n평범한 이들은 저 성스러운 빛을 보기만 해도 병과 상처가 낫는다고 들었어...",
  ui_story_1018_10180802_87_dialog_content = "확실히 그래...",
  ui_story_1018_10180802_88_dialog_content = "내 몸속의 그 힘이 조금씩 사라지고 있어... 무척이나 편해진 느낌이야...",
  ui_story_1018_10180802_89_dialog_content = "암귀가 되었던 병사들도 더는 공격해 오지 않고 있습니다...",
  ui_story_1018_10180802_90_dialog_content = "네 고통을 나는 잘 알고 있다. 지금 이 순간 필요한 것은 오직 수양과 기다림뿐이다.",
  ui_story_1018_10180802_91_dialog_content = "만물은 백야 아래에──",
  ui_story_1018_10180802_92_dialog_content = "다들 늦어서 미안해요!",
  ui_story_1018_10180802_93_dialog_content = "안녕하세요...",
  ui_story_1018_10180802_94_dialog_content = "소개해 드릴게요. 이쪽은 백야성 신전의 성녀님이세요.",
  ui_story_1018_10180802_95_dialog_content = "백야성 신전이라니... 대체...",
  ui_story_1018_10180802_96_dialog_content = "레이스 대원수님, 성녀님은 병사들의 치료를 도우려고 와 주신 거예요.",
  ui_story_1018_10180802_97_dialog_content = "백야 요새로 데려갔던 부상자들도 모두 성녀님의 치료 덕분에 위기를 넘길 수 있었어요.",
  ui_story_1018_10180802_98_dialog_content = "이 성녀...님이 다루는 건... 신의 힘인가?",
  ui_story_1018_10180802_99_dialog_content = "아니에요. 힐다는 오로리안이에요. 대원수와 다르지 않아요.",
  ui_story_1018_10180802_100_dialog_content = "하지만 아무리 봐도...",
  ui_story_1018_10180802_101_dialog_content = "대원수와 부하들이 무슨 일을 겪었는지는 이미 들었어요.\n힐다는 너무나도 상심해서 멋대로 저들을 돕고 말았어요. 부디 이해해 주셨으면 해요.",
  ui_story_1018_10180802_102_dialog_content = "아니, 오히려 내가 성녀님한테 감사해야지...요.",
  ui_story_1018_10180802_103_dialog_content = "그런데... 왜 이곳에...?",
  ui_story_1018_10180802_104_dialog_content = "오로리안들이 악몽 속에서 속삭이는 소리를 들었어요.\n그 고통의 목소리, 힐다는 잘 알고 있거든요.",
  ui_story_1018_10180802_105_dialog_content = "대원수도 한때 악몽에 괴로워했었죠. 힐다는 그 목소리도 들었어요.",
  ui_story_1018_10180802_106_dialog_content = "......",
  ui_story_1018_10180802_107_dialog_content = "아, 죄송해요... 지금은 제 이야기를 할 때가 아닌 것 같네요.",
  ui_story_1018_10180802_108_dialog_content = "가서 부하들의 상태를 살펴 보세요. 이미 위험은 벗어났을 거예요.",
  ui_story_1018_10180802_109_dialog_content = "네, 다시 한번 진심으로 감사드립니다...",
  ui_story_1018_10180802_110_dialog_content = "<size=30>역시... 성녀님은 다르구나...</size>",
  ui_story_1018_10180802_111_dialog_content = "당신 목소리도 들었거든요!",
  ui_story_1018_10180802_112_dialog_content = "어라? 아주 작게 말했는데...",
  ui_story_1018_10180802_113_dialog_content = "당신은 왠지 다른 사람들과는 다른 거 같아요.",
  ui_story_1018_10180802_114_dialog_content = "성녀님, 이쪽이 바로 그 아이테르입니다.",
  ui_story_1018_10180802_115_dialog_content = "성녀님, 처음 뵙겠습니다. 전 PlayerName입니다.",
  ui_story_1018_10180802_116_dialog_content = "안녕하세요, PlayerName 씨, 힐다라고 불러 주세요.",
  ui_story_1018_10180802_117_dialog_content = "힐다...",
  ui_story_1018_10180802_118_dialog_content = "전에 읽었던 소설책의 주인공도 힐다라는 이름이었어요...",
  ui_story_1018_10180802_119_dialog_content = "네? 진짜요?! 그럼 그 힐다는 어떤 사람이었나요?",
  ui_story_1018_10180802_120_dialog_content = "힐다는 사실... 동물인데요...",
  ui_story_1018_10180802_121_dialog_content = "PlayerName 너... 서, 성녀님께 동물이라니...",
  ui_story_1018_10180802_122_dialog_content = "근데 책에 진짜 그렇게 쓰여 있었다고! 힐다는 화초 심는 걸 좋아했고...",
  ui_story_1018_10180802_123_dialog_content = "푸하하하... 화초 심는 걸 좋아하는 동물이라구요? 두더지인가요? 아니면 여우?",
  ui_story_1018_10180802_124_dialog_content = "혹시 뿔이나 날개는 없나요? 여행도 많이 가 봤겠죠...?",
  ui_story_1018_10180802_125_dialog_content = "<size=30>단장님, 바로 저분이 그 백야 교회의 성녀님입니까...?</size>",
  ui_story_1018_10180802_126_dialog_content = "그래...",
  ui_story_1018_10180901_1_dialog_content = "<color=#e8d9bb>자난성</color>",
  ui_story_1018_10180901_2_dialog_content = "음... 아니면 이런 기사는 어때요?",
  ui_story_1018_10180901_3_dialog_content = "「더스크 타운의 전세가 좋지 않다는 소식이 전해지면서,\n곧 전장으로 향할 병사들의 가족들은 많은 염려를 하고 있다...」",
  ui_story_1018_10180901_4_dialog_content = "휴, 좀 더 긍정적인 톤으로 쓸 순 없어? 꼭 우리가 전쟁에서 진 것처럼 들리잖아...",
  ui_story_1018_10180901_5_dialog_content = "하지만 사실이잖아요? 지금까지 전해진 좋은 소식은 하나도 없었어요.\n이러다간 쓸 기사도 없게 생겼다구요...",
  ui_story_1018_10180901_6_dialog_content = "군단장님, 왜 이번 우리 임무는 더스크 타운의 지원이 아니라 방어선 파견입니까?",
  ui_story_1018_10180901_7_dialog_content = "그것이 명령입니다.",
  ui_story_1018_10180901_8_dialog_content = "하지만 더스크 타운은 지금 어려운 상황이지 않습니까...?",
  ui_story_1018_10180901_9_dialog_content = "우려는 마음 속으로 삼키고, 앞으로 닥칠 위기에 맞설 힘으로 삼으세요.",
  ui_story_1018_10180901_10_dialog_content = "예...",
  ui_story_1018_10180901_11_dialog_content = "군단장님, 부대가 준비를 마쳤습니다.",
  ui_story_1018_10180901_12_dialog_content = "참모장이 배정한 자주포는 어떻게 됐습니까?",
  ui_story_1018_10180901_13_dialog_content = "이미 도착했습니다!",
  ui_story_1018_10180901_14_dialog_content = "출발합시다.",
  ui_story_1018_10180901_15_dialog_content = "예!",
  ui_story_1018_10180901_16_dialog_content = "「제3군단이 출발했습니다! 이것으로 더스크 타운의 전세도 역전의 기회가 올 것입니다──」",
  ui_story_1018_10180901_17_dialog_content = "어라? 무전기에 이상한 신호가 들어온 것 같은데요?",
  ui_story_1018_10180901_18_dialog_content = "어? 나도!",
  ui_story_1018_10180901_19_dialog_content = "누가 장난이라도 치고 있는 건가...? 주파수를 조정하면 제대로 들리려나...",
  ui_story_1018_10180901_20_dialog_content = "「계명성 프로젝트」는 율리시스와 이클립스의 노라가 공모한 음모이며...",
  ui_story_1018_10180901_21_dialog_content = "이건...!",
  ui_story_1018_10180901_22_dialog_content = "당신이 신호를 보낸 사람이죠?",
  ui_story_1018_10180901_23_dialog_content = "왜 그렇게 생각하십니까?",
  ui_story_1018_10180901_24_dialog_content = "제가 한번 정리해 볼게요.",
  ui_story_1018_10180901_25_dialog_content = "당신은 처음엔 에센의 스파이 역할로 대원수님을 따라다니면서\n그분의 일거수일투족을 관찰했어요.",
  ui_story_1018_10180901_26_dialog_content = "그 후 연합 훈련에선 대원수님께 누명을 씌우려는 율리시스의 연극에 부득이하게 협조했죠.",
  ui_story_1018_10180901_27_dialog_content = "그러다 라인하르트 님의 공개재판에서 마침내 자신이 정쟁의 체스말이었음을 깨달았고...",
  ui_story_1018_10180901_28_dialog_content = "그래서 양심을 되찾고 우리 행동을 묵인해 주었을 뿐만 아니라, 몰래 도움까지 준 거겠죠.",
  ui_story_1018_10180901_29_dialog_content = "하지만 정보장교가 통신에도 꽤 조예가 있을 줄은 몰랐네요.\n당신 상관은 아무 말도 안 하던가요?",
  ui_story_1018_10180901_30_dialog_content = "정보장교는 정보를 수집하지만, 적절히 정보를 전파하는 법도 물론 알고 있습니다.\n이번 일은 제 개인의 신념을 따랐을 뿐이고, 다른 누구와도 관계가 없습니다.",
  ui_story_1018_10180901_31_dialog_content = "훗, 아무래도 진심인 모양이네요.",
  ui_story_1018_10180901_32_dialog_content = "신념에 따라 행동하는 건 제가 타인을 판단할 때의 기준 중 하나예요.\n당신의 정보 작전은 정확했고, 태도는 확고했어요.",
  ui_story_1018_10180901_33_dialog_content = "다시 말해서, 당신이 감옥에서 제게 했던 말들, 지금은 전부 믿을 수 있겠어요...",
  ui_story_1018_10180901_34_dialog_content = "<color=#e8d9bb>얼마 전, 비비안이 일루미나 감옥에 세 번째 면회를 갔을 때...</color>",
  ui_story_1018_10180901_35_dialog_content = "최고 경비등급 감옥에 들어올 수 있다니, 아나톨리가 제공해 준 정보가 틀리진 않았던 모양이네요.",
  ui_story_1018_10180901_36_dialog_content = "참모장님, 이렇게 중요한 계획을 어째서 위증했던 녀석이 제공한 정보를 믿고 진행하신 거죠?",
  ui_story_1018_10180901_37_dialog_content = "직감이에요.",
  ui_story_1018_10180901_38_dialog_content = "전에 레이스는 아나톨리의 위증에 뭔가 사정이 있을 것 같다고 했어요.\n게다가 계속해서 이번 우리 행동의 목적을 찾으려는 건 그가 흔들리고 있다는 증거예요.",
  ui_story_1018_10180901_39_dialog_content = "그리고 이번 일은 그가 우릴 돕겠다는 결심을 한 거겠죠.",
  ui_story_1018_10180901_40_dialog_content = "그럼... 갑자기 나타난 저 순찰병도 우릴 돕는 결심의 일환일까요...",
  ui_story_1018_10180901_41_dialog_content = "......",
  ui_story_1018_10180901_42_dialog_content = "비비안 참모장님, 최고 경비등급 감옥에 들어가려면 증명서를 제시해 주셔야 합니다.",
  ui_story_1018_10180901_43_dialog_content = "당신들 상관에게 물어봐 주시겠어요? 절 여기 보낸 상관은 증명서 같은 건 안 주셨는데요.",
  ui_story_1018_10180901_44_dialog_content = "당신의 직속 상관 라인하르트는 지금 이곳에 수용되어 있습니다.\n신중하게 생각한 다음에 행동하셨으면 좋겠습니다.",
  ui_story_1018_10180901_45_dialog_content = "<size=30>참모장님, 아무래도 그 정보장교에 대한 직감은 틀리신 것 같은데요.</size>",
  ui_story_1018_10180901_46_dialog_content = "<size=30>저도 사람을 잘못 볼 수 있어요. 그리고 잘못 본 건 그 사람이 처음이라구요.</size>",
  ui_story_1018_10180901_47_dialog_content = "<size=30>하지만 계획은 계획이에요. 어떻게든 히이로의 출병 전까지 대원수님을 구해내야 해요.</size>",
  ui_story_1018_10180901_48_dialog_content = "<size=30>이번이 마지막 기회예요. 전투를 준비하세요!</size>",
  ui_story_1018_10180901_49_dialog_content = "<size=30>네, 대원수님을 위해!</size>",
  ui_story_1018_10180901_50_dialog_content = "참모장님, 실력 행사를 하실 생각입니까? 그렇다면 저희도...",
  ui_story_1018_10180901_51_dialog_content = "으아아앗! 아프잖아요!",
  ui_story_1018_10180901_52_dialog_content = "...아직 아무것도 안 했습니다만.",
  ui_story_1018_10180901_53_dialog_content = "제가 하죠.",
  ui_story_1018_10180901_54_dialog_content = "예, 소령님.",
  ui_story_1018_10180901_55_dialog_content = "...아나톨리, 이게 어떻게 된 거죠? 우릴 가지고 논 건가요?!",
  ui_story_1018_10180901_56_dialog_content = "죄송합니다. 제 의문을 풀기 위해 이런 방식을 쓸 수밖에 없었습니다.",
  ui_story_1018_10180901_57_dialog_content = "무슨 의문이죠?",
  ui_story_1018_10180901_58_dialog_content = "일루미나의 미래를 위해 당신들이 어떤 길을 택했고,\n목적을 달성하기 위해 어디까지 할 각오가 되어 있는지 말입니다.",
  ui_story_1018_10180901_59_dialog_content = "그럼 결론은 얻었나요?",
  ui_story_1018_10180901_60_dialog_content = "대원수님은 위대한 지도자입니다. 그게 제가 오랜 관찰을 통해 얻은 결론입니다.",
  ui_story_1018_10180901_61_dialog_content = "정보장교로서 늘 의심하는 태도는 가장 기본적인 준칙입니다.\n따라서 전 맹목적인 믿음을 싫어합니다.",
  ui_story_1018_10180901_62_dialog_content = "하지만 저는 한때 다른 이들의 무조건적인 신뢰를 받았던 적이 있었고,\n그리고 그러한 신뢰를 지금 당신들에게서 다시 볼 수 있었습니다.",
  ui_story_1018_10180901_63_dialog_content = "그것이야말로 제가 갈망하는 미래입니다. 그러니 저는 당신들 편에 서는 것을 선택하겠습니다.",
  ui_story_1018_10180901_64_dialog_content = "후훗, 전 대원수님의 등에 칼을 꽂았던 자를 믿을 순 없어요.\n아무리... 제가 당신 연설이 마음에 들었다 해도 말이죠.",
  ui_story_1018_10180901_65_dialog_content = "절 알게 되실 기회는 앞으로도 얼마든지 있습니다.\n순찰병은 제 부하입니다. 두 분께선 서두르십시오.",
  ui_story_1018_10180901_66_dialog_content = "그럼... 한편이 된 걸 환영해요. 목숨 아까운 줄 모르는 정보장교님~",
  ui_story_1018_10180901_67_dialog_content = "눈길을 끄는 행동은 됐습니다. 전 어둠 속에서 움직이는 게 더 익숙하니까요.",
  ui_story_1018_10180901_68_dialog_content = "당신들 계획이 성공한다면, 제 수중의 다른 패들이 아마 도움이 될 겁니다.",
  ui_story_1018_10180901_69_dialog_content = "후훗, 약속이에요.",
  ui_story_1018_10180901_70_dialog_content = "<color=#e8d9bb>지직... 지지직...</color>",
  ui_story_1018_10180901_71_dialog_content = "통신 장치가 왜... 전부 이상한 소리가 나는 거죠?",
  ui_story_1018_10180901_72_dialog_content = "<color=#e8d9bb>삑──</color>",
  ui_story_1018_10180901_73_dialog_content = "이상하네요... 무전기가 고장났나? 신호가 안 잡히는데요?",
  ui_story_1018_10180901_74_dialog_content = "내 것도 그래...",
  ui_story_1018_10180901_75_dialog_content = "대체... 무슨 일이지?",
  ui_story_1018_10180901_76_dialog_content = "아무래도 위원회가 움직이기 시작한 모양이군요...",
  ui_story_1018_10180901_77_dialog_content = "참모장님, 통신 장애의 발생과 동시에 방어선 부대와의 연락이 끊어졌습니다.",
  ui_story_1018_10180901_78_dialog_content = "이런 방법을 쓰다니...",
  ui_story_1018_10180901_79_dialog_content = "지금까지 일루미나가 전파를 교란한 적은 있었어도,\n방어선 부대와의 통신까지 방해한 적은 없었어요.",
  ui_story_1018_10180901_80_dialog_content = "...시간이 없어요. 아나톨리, 몸조심하세요.",
  ui_story_1018_10180901_81_dialog_content = "......",
  ui_story_1018_10180901_82_dialog_content = "<color=#e8d9bb>지직... 지지직...</color>",
  ui_story_1018_10180901_83_dialog_content = "교수님, 전파 간섭 문제는 해결된 것 같습니다. 이제 회의를 재개할 수 있습니다.",
  ui_story_1018_10180901_84_dialog_content = "......",
  ui_story_1018_10180901_85_dialog_content = "리스크 회피를 위해 어쩔 수 없었습니다.",
  ui_story_1018_10180901_86_dialog_content = "이제 신호의 출처도 조사해야 합니다. 완전히 복구하기까진 시간이 좀 더 걸릴 겁니다.",
  ui_story_1018_10180901_87_dialog_content = "아무래도 일루미나의 모두가 박사님의 음모를 감상할 순간이 한 발짝 더 가까워진 모양이네요.",
  ui_story_1018_10180901_88_dialog_content = "이 건은 즉시 에센에게 조사하라고 하겠습니다.",
  ui_story_1018_10180901_89_dialog_content = "주의력을 돌리는 게 정면으로 맞서는 것보다 부담이 덜한 법이야.\n율리시스 당신은 실험의 결함을 보완하는 쪽에나 더 집중하도록 해.",
  ui_story_1018_10180901_90_dialog_content = "음? 더스크 타운의 전황에 대한 해결책이라도 있는 겁니까?",
  ui_story_1018_10180901_91_dialog_content = "해결책이야 늘 있었지. 문제는 어떤 걸 고르느냐일 뿐이야.\n그것도 사태의 전개를 보고 결정해야겠지.",
  ui_story_1018_10180901_92_dialog_content = "4기 「씨앗」으로 최대한 빠르게 수습하도록 하죠.",
  ui_story_1018_10180901_93_dialog_content = "한 가지 일에 계속 인내심을 소모하고 싶진 않은데요. 이건 제 경험이에요.",
  ui_story_1018_10180901_94_dialog_content = "「어둠의 밑바닥 정찰대」 쪽은 소식이 있었나요?",
  ui_story_1018_10180901_95_dialog_content = "그쪽에선 이미 「가디언 1호」의 코어를 <color=#FFB400>복제한 설비</color>로 추정되는 사진을 여러 장 보냈습니다.",
  ui_story_1018_10180901_96_dialog_content = "현 단계에서 추측하자면, 이클립스가 「가디언 1호」의 핵심을 훔친 것은\n「엔지니어」와 관련된 사항의 준비를 위해서인 것으로 보입니다.",
  ui_story_1018_10180901_97_dialog_content = "......",
  ui_story_1018_10180901_98_dialog_content = "어둠의 위기로부터 벌써 10년이 지났어. 우린 그동안 대체 뭘 이뤄냈지?",
  ui_story_1018_10180901_99_dialog_content = "불필요한 걱정입니다, 철가면 님.",
  ui_story_1018_10180901_100_dialog_content = "「가디언 1호」는 제가 잘 알고 있습니다. 그 코어를 활용하려면 시간이 좀 더 걸릴 겁니다.",
  ui_story_1018_10180901_101_dialog_content = "이참에 미리 말해두죠. 전 「씨앗」의 연구 개발 속도를 높이기 위해\n향후의 회의에는 참석하지 않겠습니다. 그럼 먼저 실례하죠.",
  ui_story_1018_10180901_102_dialog_content = "교수님, 실험 결과가 나왔습니다. 확인해 보세요.",
  ui_story_1018_10180901_103_dialog_content = "...새로운 씨앗의 전투 데이터가 왜 이렇게 나쁜 거죠?",
  ui_story_1018_10180901_104_dialog_content = "교수님, 벨리사리아 님으로부터의 통신 요청입니다...",
  ui_story_1018_10180901_105_dialog_content = "...받으세요.",
  ui_story_1018_10180901_106_dialog_content = "역시 충고 하나 해야겠어, 박사.",
  ui_story_1018_10180901_107_dialog_content = "지금까지 단 한 번도 모습을 드러낸 적 없었던 소녀까지 나왔다는 건,\n우리가 얼마나 뒤처졌는지 당신도 이해할 수 있을 거야.",
  ui_story_1018_10180901_108_dialog_content = "이클립스는 대대적인 침공을 시작할 거야. 그건 어둠의 밑바닥 쪽 움직임이 지연된다는 뜻이겠지.\n이것도 당신에게 이로운 소식일지는 모르겠지만 말이야.",
  ui_story_1018_10180901_109_dialog_content = "무슨 말씀을 하고 싶으신 겁니까.",
  ui_story_1018_10180901_110_dialog_content = "당신 실험은 계속해도 좋아. 다만 당신 계획은 이제 내 우선 순위에서 배제됐어.",
  ui_story_1018_10180901_111_dialog_content = "몸조심해, 율리시스 박사.",
  ui_story_1018_10180901_112_dialog_content = "......",
  ui_story_1018_10180901_113_dialog_content = "교수님... 실험은... 계속 진행되나요?",
  ui_story_1018_10180901_114_dialog_content = "계속하세요! 이 정도 장애물이 뭐가 문제입니까!",
  ui_story_1018_10180901_115_dialog_content = "절차, 환경, 계산... 개선할 수 있는 변인이 더 있습니까?",
  ui_story_1018_10180901_116_dialog_content = "교수님... 전 그것들 전부 문제가 아니라고 생각하는데요.",
  ui_story_1018_10180901_117_dialog_content = "아무래도 연구의 방향을 재검토하는 쪽이...",
  ui_story_1018_10180901_118_dialog_content = "이 연구는 그 여자의 방향과 완벽히 일치합니다!",
  ui_story_1018_10180901_119_dialog_content = "일루미나의 과학기술, 화음 연결, 「씨앗」... 이 세 가지 중에 뭘 더 조정할 수 있단 말입니까?",
  ui_story_1018_10180901_120_dialog_content = "교수님... 현재 「씨앗」의 개량 속도에 문제는 없습니다.\n하지만 버전마다 얻을 수 있는 개선 효과는 극히 미미합니다...",
  ui_story_1018_10180901_121_dialog_content = "아무래도 제가 투여량의 조절에 너무 보수적이었던 것 같군요...",
  ui_story_1018_10180901_122_dialog_content = "...이제 시간이 없습니다. 다음 「씨앗」에서는 추출물 투여량을 늘리세요!",
  ui_story_1018_10180901_123_dialog_content = "그리고 에센에게 다시 병사를 모집하라고 전하세요.\n지금까지 탈락한 병사들도 특별히 실험 참가를 허용하겠습니다.",
  ui_story_1018_10180901_124_dialog_content = "...네.",
  ui_story_1018_10180901_125_dialog_content = "어머~ 율리시스 교수네 실험실은 이렇게 시끌벅적했었구나?",
  ui_story_1018_10180901_126_dialog_content = "교수님...",
  ui_story_1018_10180901_127_dialog_content = "여긴 뭐 하러 온 겁니까?",
  ui_story_1018_10180901_128_dialog_content = "그렇게 긴장할 거 없어.\n난 그냥 명령을 받고 우리 실험실 동료들을 며칠간 빌려주러 왔을 뿐이야.",
  ui_story_1018_10180901_129_dialog_content = "위원회의 명령입니까?",
  ui_story_1018_10180901_130_dialog_content = "어라? 교수는 명령 못 받았어? 으음... 아니면 잉겔 중령이 말하는 걸 까먹었나 보네.",
  ui_story_1018_10180901_131_dialog_content = "맞습니다, 교수님... 저도 명령을 받았습니다.\n어쩌면 함께 임하면 실험의 진척도 빨라질지도 모릅니다...",
  ui_story_1018_10180901_132_dialog_content = "<size=30>흥, 날 감시하려고 벨리사리아가 보낸 것뿐이겠지...</size>",
  ui_story_1018_10180901_133_dialog_content = "뭐, 좋습니다. 전 포기하지 않을 겁니다.",
  ui_story_1018_10180901_134_dialog_content = "잉겔, 병사 징집은 네게 맡기겠다. 옆에 있는 조수와 인수인계하도록.",
  ui_story_1018_10180901_135_dialog_content = "알겠습니다, 교수님...",
  ui_story_1018_10180901_136_dialog_content = "그로누 연구원장, 당신의 실험 동료들은 「계명성 프로젝트」에 대해 얼마나 알고 있습니까?",
  ui_story_1018_10180901_137_dialog_content = "아, 그거라면 직접 물어보면 돼. 다들 배우는 걸 좋아하는 착한 애들이거든~",
  ui_story_1018_10180901_138_dialog_content = "잘 부탁드리겠습니다. 율리시스 교수님.",
  ui_story_1018_10180901_139_dialog_content = "여기 있었구나? 잉겔 중령~ 아깐 잘했어. 율리시스 교수도 눈치 못 챈 모양이야~",
  ui_story_1018_10180901_140_dialog_content = "감사합니다, 그로누 선배님... 직무를 생각하면 이래서는 안 되는 거였지만...",
  ui_story_1018_10180901_141_dialog_content = "교수님의 실험을 직접 보고 나니, 아무 일도 없었던 척할 순 없었어요.",
  ui_story_1018_10180901_142_dialog_content = "눈을 감을 때마다 보여요... 악셀리아가 전장에서 병사들과 서로...",
  ui_story_1018_10180901_143_dialog_content = "헤헷, 착한 아기새는 걱정할 거 없어~ 이미 충분히 잘했으니까.\n전장 일은 우리한테 맡겨.",
  ui_story_1018_10180901_144_dialog_content = "그게... 무슨 말씀이시죠?",
  ui_story_1018_10180901_145_dialog_content = "사실 일루미나 사람들도 다들 너랑 같은 걱정을 하고 있어.\n그러니까 엄밀히 말하면 네가 우릴 도와주고 있는 거야.",
  ui_story_1018_10180901_146_dialog_content = "그럼 이제 출발할게. 전장의 부상병들을 데리고 돌아올 테니까!",
  ui_story_1018_10180901_147_dialog_content = "정말인가요? 그럼 그로누 선배님의 이번 행동도... 위원회의 명령이었나요?",
  ui_story_1018_10180901_148_dialog_content = "잉겔 중령, 이제 너도 스스로 판단할 줄 알아야 한다구~",
  ui_story_1018_10180901_149_dialog_content = "......",
  ui_story_1018_10180901_150_dialog_content = "그로누 선배님, 부탁드리고 싶은 게 하나 더 있는데요...",
  ui_story_1018_10180901_151_dialog_content = "응? 말해 봐.",
  ui_story_1018_10180901_152_dialog_content = "저도... 함께 전장에 가도 될까요?",
  ui_story_1018_10180901_153_dialog_content = "음... 같이 가는 거야 상관없지만...",
  ui_story_1018_10180901_154_dialog_content = "근데 저번에 여기서 봤을 때 너 상태가 별로 안 좋았잖아?\n무기 소리 같은 거 들으면 힘들지 않을까?",
  ui_story_1018_10180901_155_dialog_content = "맞아요... 군인이라면 무기를 들어야 하는 건 당연하지만...",
  ui_story_1018_10180901_156_dialog_content = "혼자가 되면 그 차가운 금속 소리가 귓가에 울리면서... 식은땀이 나더군요...",
  ui_story_1018_10180901_157_dialog_content = "하지만 지금 일루미나는 절 필요로 하고 있고, 저도 반드시 뭔가 해야만 해요.\n제가 비비안 참모장님께 드렸던 말씀처럼요...",
  ui_story_1018_10180901_158_dialog_content = "아, 비비안은... 으앗, 말실수할 뻔했네!",
  ui_story_1018_10180901_159_dialog_content = "아무튼! 착한 아기새도 자기 세상을 향해 날아오를 날이 올 거야.\n준비되면 정비소로 날 찾으러 와~",
  ui_story_1018_10180901_160_dialog_content = "네, 감사합니다, 그로누 선배님.",
  ui_story_1018_10181002_1_dialog_content = "호위대장님, 보고드리겠습니다. 늪은 거의 사라졌습니다.\n더스크 타운 주변에 이제 암귀의 활동 흔적은 없습니다.",
  ui_story_1018_10181002_2_dialog_content = "일루미나의 수색 구조에 대한 지원 임무도 완수하였으며,\n현재 레이스 대원수가 부하에게 상황을 듣고 있는 중입니다.",
  ui_story_1018_10181002_3_dialog_content = "알겠어. 부대를 정비하고 명령을 기다려.",
  ui_story_1018_10181002_4_dialog_content = "늪이 물러간 더스크 타운은 이런 모습이었군요... 정말 떠들썩하네요.",
  ui_story_1018_10181002_5_dialog_content = "네, 성녀님. 이 부근은 원래 시장이었어요.\n지금은 간신히 노점이 늘어선 모습이 되었네요.",
  ui_story_1018_10181002_6_dialog_content = "앞에 보이는 저 갈라진 돌벽은 원래 화단을 둘러싸고 있던 거예요.",
  ui_story_1018_10181002_7_dialog_content = "생각해보니 참 신기한 화단이었어요.\n아주 다양한 꽃들이 피어 있었고, 게다가 일년 내내 만개해 있었거든요.",
  ui_story_1018_10181002_8_dialog_content = "아이들은 근처에서 노는 걸 좋아했어요. 저도 어렸을 때는 그랬고요.",
  ui_story_1018_10181002_9_dialog_content = "하지만 지금은... 아이들의 놀이터도 암귀의 손에 파괴되어 버렸네요...",
  ui_story_1018_10181002_10_dialog_content = "힐다는 시들어 버린 꽃들도 다시 필 때가 올 거라고 믿어요.",
  ui_story_1018_10181002_11_dialog_content = "아이들은 조셀린 씨의 보호 덕분에 여기서 행복하게 살 수 있을 거예요.",
  ui_story_1018_10181002_12_dialog_content = "헤헷, 힐다는 아이들의 즐거운 웃음소리가 들리거든요~",
  ui_story_1018_10181002_13_dialog_content = "성녀님... 정말 감사합니다! 하지만 아직 걱정이 돼요...",
  ui_story_1018_10181002_14_dialog_content = "암귀가 파괴한 건 우리의 터전만이 아니에요.\n전사들에 대한 더스크 타운 사람들의 믿음도 무너지고 말았어요...",
  ui_story_1018_10181002_15_dialog_content = "어쩌면 사람들은 이제 더는 이 땅이 가호와 안녕을 줄 거라고 믿지 않을지도 몰라요.",
  ui_story_1018_10181002_16_dialog_content = "전 믿습니다.",
  ui_story_1018_10181002_17_dialog_content = "단장님...?",
  ui_story_1018_10181002_18_dialog_content = "늪에 쓰러져 있던 이들은 모두 이번 전쟁에서 희생된 전사들입니다.",
  ui_story_1018_10181002_19_dialog_content = "더스크 타운은 애초부터 병사의 시신 위에 세워진 마을입니다.\n이번 일로 사람들은 전쟁이 영원히 끝나지 않을 것임을 깨달았을 겁니다.",
  ui_story_1018_10181002_20_dialog_content = "이 땅에 살고자 하는 사람이 있는 한, 더스크 타운을 지키겠다는 신념은 흔들리지 않습니다.",
  ui_story_1018_10181002_21_dialog_content = "그동안 더스크 타운은 제겐 심리적인 안전지대였습니다.",
  ui_story_1018_10181002_22_dialog_content = "이번 싸움이 없었다면, 전 여전히 예전처럼 더스크 타운을 걱정하면서도,\n한편으로는 주저하며 나아가지 못했을 겁니다.",
  ui_story_1018_10181002_23_dialog_content = "그리고 지금의 결과는 더스크 타운이나 저 모두 자신을 새롭게 돌아볼 기회였습니다.",
  ui_story_1018_10181002_24_dialog_content = "레오 단장, 지금 그 말은 백야성에 대한 당신의 견해가 바뀌었다는 의미로 이해해도 될까?",
  ui_story_1018_10181002_25_dialog_content = "그렇지 않습니다, 카렌 전하. 아무래도 실망시켜 드릴 것 같군요.",
  ui_story_1018_10181002_26_dialog_content = "하지만 레이스 대원수의 행동을 보고 전 느꼈습니다.\n그저 당국에 대한 불만을 드러내는 것에서 그쳐서는 안 됩니다.",
  ui_story_1018_10181002_27_dialog_content = "전 반드시 저부터 개혁할 겁니다. 제 능력이 제 야심에 걸맞도록 말이죠.",
  ui_story_1018_10181002_28_dialog_content = "그리고 여러분께 약속하죠. 더스크 타운의 미래는 곧 저의 미래입니다.",
  ui_story_1018_10181002_29_dialog_content = "이걸로 조금은 안심할 수 있겠습니까? 조셀린.",
  ui_story_1018_10181002_30_dialog_content = "단장님... 그렇게 말씀해 주셔서 정말 감동했어요.",
  ui_story_1018_10181002_31_dialog_content = "이제 전 더스크 타운이 반드시 순조롭게 재건될 거라고 믿어요!",
  ui_story_1018_10181002_32_dialog_content = "그리고 사실 그동안 계속 생각하던 게 하나 있어요.\n성녀님, 부디 가르침을 주실 수 있을까요?",
  ui_story_1018_10181002_33_dialog_content = "성녀님, 저희는 아직 중요한 일이 남아 있습니다.",
  ui_story_1018_10181002_34_dialog_content = "그랬죠... 그치만 마지막으로 조셀린 씨랑 조금 더 얘기해도 될까요?",
  ui_story_1018_10181002_35_dialog_content = "조셀린 씨, 되도록 짧게 부탁드립니다.",
  ui_story_1018_10181002_36_dialog_content = "성녀님, 저는 더스크 타운에... 모든 사람을 지켜주는 교회를 세우고 싶어요.\n빛의 신을 믿는 사람들만을 위해서가 아니라...",
  ui_story_1018_10181002_37_dialog_content = "오로리안, 아인족, 아이테르... 심지어 어둠에 몸을 던질 수밖에 없었던 사람들도요...",
  ui_story_1018_10181002_38_dialog_content = "그들은 어쩌면 다른 진영에서는 받아들여지지 않을지도 몰라요.\n하지만 오직 사랑과 배려를 품고 있다면, 그 누구든지 이곳을 터전으로 삼을 수 있었으면 해요.",
  ui_story_1018_10181002_39_dialog_content = "더스크 타운에 있어야 할 것은 황혼만이 아니에요. 이곳 역시 빛이 닿는 곳이여야만 해요.",
  ui_story_1018_10181002_40_dialog_content = "저들도 아스트라 대륙 다른 곳의 사람들처럼 해와 달, 별이 있는 하늘을 볼 수 있어야 해요.",
  ui_story_1018_10181002_41_dialog_content = "어려운 일이라는 건... 알아요. 하지만 먼저 성녀님의 가호를 받을 수 있었으면 좋겠어요.",
  ui_story_1018_10181002_42_dialog_content = "조셀린 씨, 당신은 정말 경건하고 의로운 사람이군요.",
  ui_story_1018_10181002_43_dialog_content = "오로리안의 시조가 북쪽에서 처음으로 내려와 교리를 세울 때 겪었던 고난처럼,\n이곳에 당신이 원하는 교회를 세우는 건 마찬가지로 힘겨운 길이 될 거예요.",
  ui_story_1018_10181002_44_dialog_content = "하지만 거룩한 빛은 모든 경건한 땅을 비출 거예요. 당신이 이끈다면 더욱 그렇겠죠.",
  ui_story_1018_10181002_45_dialog_content = "당신이 원한다면, 그대로 행하세요. 저는 당신의 뜻을 지지할 테니까요.",
  ui_story_1018_10181002_46_dialog_content = "성녀님의 가르침에 감사드립니다... 수녀 조셀린, 반드시 마음속 깊이 새기겠습니다!",
  ui_story_1018_10181002_47_dialog_content = "<size=30>휴... 어땠어요?</size>",
  ui_story_1018_10181002_48_dialog_content = "절도 있는 말씀이었습니다, 성녀님. 하지만 이젠 출발하셔야 합니다.",
  ui_story_1018_10181002_49_dialog_content = "네! 그럼 앞으로의 일은 여러분께 맡길게요.",
  ui_story_1018_10181002_50_dialog_content = "참, 카렌. 더스크 타운의 일이 끝나면 서둘러 방어선으로 가서 성주의 군대와 합류하세요.",
  ui_story_1018_10181002_51_dialog_content = "네?! 성주님의 군대가 방어선에 계신단 말인가요?!",
  ui_story_1018_10181002_52_dialog_content = "그럼 어째서 회의 때는 무관심한 모습을 보이셨던 걸까요?",
  ui_story_1018_10181002_53_dialog_content = "음...성주는 「정세에 따라 이로운 길로 이끈다」고 말했지만, 힐다는 잘 모르겠어요.",
  ui_story_1018_10181002_54_dialog_content = "성주의 군대뿐만이 아니에요. 대원수의 동료들도 있어요.",
  ui_story_1018_10181002_55_dialog_content = "이 전쟁은... 끝난 게 아니었나요?",
  ui_story_1018_10181002_56_dialog_content = "더스크 타운의 전쟁은 끝났어요. 안심해도 돼요.",
  ui_story_1018_10181002_57_dialog_content = "하지만 오로리안의 전쟁은 이제 막 시작된 것 같아요. 제가 신전을 떠난 의미도 거기에 있구요.",
  ui_story_1018_10181002_58_dialog_content = "여정 중에 여러분을 만나서 힐다는 정말 기뻐요. 제 가호가 여러분에게 있을 거예요.",
  ui_story_1018_10181002_59_dialog_content = "부디 빛의 신께서 여러분과 함께하기를. 힐다는 여러분과 다시 만날 날을 기대하고 있을게요.",
  ui_story_1018_10181002_60_dialog_content = "빛의 신이시여, 영원하소서──",
  ui_story_1018_10181002_61_dialog_content = "만물은 백야 아래에──",
  ui_story_1018_10181002_62_dialog_content = "...암귀는 철수한 게 아니라, 일루미나의 방어선으로 향한 거였어.\n이번 위기는 쉽게 가라앉지 않을 모양이야...",
  ui_story_1018_10181002_63_dialog_content = "다들 알게 된 모양이네.",
  ui_story_1018_10181002_64_dialog_content = "레이스 대원수님... 성녀님이 말씀하셨어요... 적어도 더스크 타운은 이제 안전하다고요.",
  ui_story_1018_10181002_65_dialog_content = "일루미나군과 기사단이 함께 싸운 덕분에 더스크 타운이 재난을 넘길 수 있었어요!",
  ui_story_1018_10181002_66_dialog_content = "그렇게 말해 줘서 기뻐, 조셀린 양. 하지만 위로해 주지 않아도 돼.",
  ui_story_1018_10181002_67_dialog_content = "사태의 전개가 점차 명확해지면서, 난 오히려 다행이라고 생각했어.",
  ui_story_1018_10181002_68_dialog_content = "결과만 보면 우린 성공했지만, 나한테 있어서 이번 일은 매우 큰 실패야...",
  ui_story_1018_10181002_69_dialog_content = "레이스 대원수, 지금의 이 상황은 이미 일루미나 단독으로 대응할 수 있는 범위를 넘어섰어.",
  ui_story_1018_10181002_70_dialog_content = "더스크 타운의 전황이 불리할 때, 백야성은 방관해서는 안 됐어.",
  ui_story_1018_10181002_71_dialog_content = "이젠 성주님의 군대도 방어선에 집결해 있어.\n일루미나가 어떻게 생각하든, 백야성도 더는 방관하진 않을 거야.",
  ui_story_1018_10181002_72_dialog_content = "오해하지 마, 카렌 공주. 오히려 실패했기 때문에 이 모든 게 의미가 있는 거야.",
  ui_story_1018_10181002_73_dialog_content = "더스크 타운 전투, 부하들의 희생, 그리고 상부의 계획...\n이 모든 건 반드시 나 개인의 실패로만 끝나야 해.",
  ui_story_1018_10181002_74_dialog_content = "그래야만 일루미나도 미래를 얻을 수 있어.",
  ui_story_1018_10181002_75_dialog_content = "대원수... 동료들과 무슨 계획이라도 있는 건가?",
  ui_story_1018_10181002_76_dialog_content = "방어선에서 기다리고 있는 위험이 무엇이든, 난 내가 믿는 걸 반드시 가서 검증할 거야.",
  ui_story_1018_10181002_77_dialog_content = "난 더스크 타운의 상황이 일루미나에서 다시 벌어질까 걱정이다만...",
  ui_story_1018_10181002_78_dialog_content = "부하들이 노라에게 끌려갔다고 그 악셀리아라는 전사가 말했잖아.",
  ui_story_1018_10181002_79_dialog_content = "피와 살로 이루어진 저들이 일루미나를 지키고 있는 한, 그런 일이 다시 벌어지진 않을 거야.",
  ui_story_1018_10181002_80_dialog_content = "희생된 부하들에게 약속했어. 무슨 일이 있어도 반드시 일루미나로 데려가 주겠다고.",
  ui_story_1018_10181002_81_dialog_content = "더스크 타운의 일은 추후에 당신과 논의할게. 우선 전군을 이끌고 방어선으로 귀환하겠어.",
  ui_story_1018_10181002_82_dialog_content = "방어선으로 갈 거라면 더스크 타운의 기사단도 함께다.",
  ui_story_1018_10181002_83_dialog_content = "적은 아직 쓰러지지 않았으니까. 잊지 마라, 우린 함께 싸운 맹우다.",
  ui_story_1018_10181002_84_dialog_content = "아하하, 좋아! 더스크 타운의 맹우여, 이 레이스, 절대 잊지 않겠어.",
  ui_story_1018_10181002_85_dialog_content = "그럼 레오 단장, 레이스 대원수, 백야성 비공정에 함께 탈 의향이 있을까?",
  ui_story_1018_10181002_86_dialog_content = "전 사양하겠습니다. 기사단은 줄곧 말을 타고 싸워 왔습니다.\n저흰 하늘을 나는 탈것은 익숙하지 않아서 말이죠.",
  ui_story_1018_10181002_87_dialog_content = "호의는 고마워, 카렌 공주. 하지만 그건 일루미나의 규칙에 어긋나는 일이야.",
  ui_story_1018_10181002_88_dialog_content = "병사들은 모두 피폐해져 있어. 비공정에서 조금이라도 쉬는 게 좋을 텐데.",
  ui_story_1018_10181002_89_dialog_content = "카렌 말이 맞아. 이 뒤에도 힘든 싸움이 기다리고 있는 거라면, 지금은 반드시 휴식이 필요해.",
  ui_story_1018_10181002_90_dialog_content = "길을 따라 계속 이동하는 건 부상병들한테도 좋지 않아...",
  ui_story_1018_10181002_91_dialog_content = "...너까지 지휘관의 규범을 배운 거야?",
  ui_story_1018_10181002_92_dialog_content = "좋아, 아무래도 더스크 타운은 정말로 사람을 단련시키는 곳인 모양이네.",
  ui_story_1018_10181002_93_dialog_content = "대원수님, 그럼 사양하지 않고 호의를 받겠습니다.",
  ui_story_1018_10181002_94_dialog_content = "단장님, 저희도 탈까요...?",
  ui_story_1018_10181002_95_dialog_content = "......",
  ui_story_1018_10181002_96_dialog_content = "같이 가자, 레오 씨.",
  ui_story_1018_10181002_97_dialog_content = "같이 싸운 맹우끼리 괜히 튕기지 말라고, 우리 기사님.",
  ui_story_1018_10181002_98_dialog_content = "...그래!",
  ui_story_1018_10181101_1_dialog_content = "<color=#e8d9bb>일루미나 방어선</color>",
  ui_story_1018_10181101_2_dialog_content = "군단장님, 동서 방어선에 출현한 기병은 백야성의 군사로 확인되었습니다.",
  ui_story_1018_10181101_3_dialog_content = "현재 방어선에는 암귀의 종적이 보이지 않으며, 백야성 기병과 아군 수비부대가 감시 태세를 유지하고 있습니다.",
  ui_story_1018_10181101_4_dialog_content = "알겠다.",
  ui_story_1018_10181101_5_dialog_content = "암귀의 진격 경로에 변화는 없나?",
  ui_story_1018_10181101_6_dialog_content = "없습니다. 줄곧 중부에서 내륙을 향해 수직으로 진격 중입니다.\n공격부대가 적들과 교전 중이며, 여건에 따라 적 부대를 돌파할 수 있을 것입니다.",
  ui_story_1018_10181101_7_dialog_content = "지금은 목표가 명확하지 않은 상황이다. 공격부대는 암귀를 참호 바깥까지 막기만 하면 된다.",
  ui_story_1018_10181101_8_dialog_content = "하지만 군단장님... 한 무리를 격파해도 연이어 새로운 무리가 공격해 오고 있습니다.\n정말 이대로 방어에만 전념해도 괜찮겠습니까...?",
  ui_story_1018_10181101_9_dialog_content = "놈들은 그저 우릴 도발하고 있을 뿐이다. 제대로 된 진격 태세가 아냐.",
  ui_story_1018_10181101_10_dialog_content = "적의 정황을 확실히 알기 전까진 경거망동하지 말도록.",
  ui_story_1018_10181101_11_dialog_content = "방어시설 쪽은 어떻게 돼 가고 있지?",
  ui_story_1018_10181101_12_dialog_content = "지하성 간의 방어 임무는 바튼 장군님이 담당하고 계십니다.\n히이로 장군님의 부대는 곧 방어선에 도착할 것입니다.",
  ui_story_1018_10181101_13_dialog_content = "직전에 발생한 통신 장애가 아직 회복되지 않은 탓에, 군단장님 지시에 따라 통지를 내렸고,\n지상 전장에는 전방 부대를 배치했습니다.",
  ui_story_1018_10181101_14_dialog_content = "각 지하성은 각자 방어에 매진하고 있어 방어선의 전황에는 영향이 없습니다.",
  ui_story_1018_10181101_15_dialog_content = "좋아, 더스크 타운 쪽은 아직 소식이 없나?",
  ui_story_1018_10181101_16_dialog_content = "대원수님의 소식은 아직입니다. 다만 백야성군의 경계 태세로 봤을 때,\n더스크 타운 전투는 이미 끝나가고 있는 것으로 추정됩니다.",
  ui_story_1018_10181101_17_dialog_content = "...예상대로였으면 좋겠는데 말이야.",
  ui_story_1018_10181101_18_dialog_content = "군단장님! 방어선 밖 참호에서 갑자기 늪이 솟아났고, 일부 병사들이 안으로 빠졌습니다!",
  ui_story_1018_10181101_19_dialog_content = "암귀의 이번 공세는 그 어느 때보다 거센 상황입니다!",
  ui_story_1018_10181101_20_dialog_content = "참호에? 지금까지 늪이 확산되는 움직임은 없었잖아?",
  ui_story_1018_10181101_21_dialog_content = "서서히 확산된 것이 아니라 갑자기 지하에서 솟아나왔다고 합니다!",
  ui_story_1018_10181101_22_dialog_content = "보고에 따르면 처음에는 진흙이 조금 생겼고, 그 진흙이 갑자기 흔들리더니\n계속해서 쌓이기 시작했다고 합니다.",
  ui_story_1018_10181101_23_dialog_content = "이미 주변 보루까지 확산되고 있습니다!",
  ui_story_1018_10181101_24_dialog_content = "......",
  ui_story_1018_10181101_25_dialog_content = "방어선의 백야성 기병들에게 상황을 공유하고, 수비부대는 신속히 중부로 집결하도록!",
  ui_story_1018_10181101_26_dialog_content = "돌격부대 전원은 즉시 나를 따라 중부로 전진한다!",
  ui_story_1018_10181101_27_dialog_content = "예!",
  ui_story_1018_10181101_28_dialog_content = "이런 게 보루라고? 10년 전이나 지금이나 바뀐 게 없구나.",
  ui_story_1018_10181101_29_dialog_content = "음식──",
  ui_story_1018_10181101_30_dialog_content = "넌 여기 식사하러 온 게 아냐. 쓸 수 있는 놈들을 옮겨주기만 하면 돼.",
  ui_story_1018_10181101_31_dialog_content = "이제 곧 어둠의 밑바닥에서 중심부로 이어지는 길이 열릴 거야.",
  ui_story_1018_10181101_32_dialog_content = "푸른 불꽃이 타오르고 있다──",
  ui_story_1018_10181101_33_dialog_content = "훗, 움직임이 꽤 빠르네.",
  ui_story_1018_10181101_34_dialog_content = "너였구나, 동포를 배신한 자.",
  ui_story_1018_10181101_35_dialog_content = "하, 너도 다를 거 없잖아? 네가 죽였던 병사들을 잊었어?",
  ui_story_1018_10181101_36_dialog_content = "이 무지한 소인배가! 더스크 타운에서 희생된 병사들은 네 짓이냐?",
  ui_story_1018_10181101_37_dialog_content = "전부는 아냐. 자기 편한테 죽은 사람도 꽤 많거든.\n뭐, 이용하고 나면 버리는 일루미나의 전통에도 마침 딱 맞지 않아?",
  ui_story_1018_10181101_38_dialog_content = "헛소리는 거기까지다. 죽을 준비나 해라!",
  ui_story_1018_10181101_39_dialog_content = "곧 죽을 건 너겠지. 너희 신임 대원수도 저들 앞에서 꽤나 고통스러워했거든.",
  ui_story_1018_10181101_40_dialog_content = "...?!",
  ui_story_1018_10181101_41_dialog_content = "낯이 익지? 자기가 똑똑한 줄 아는 녀석이라면 진작 이런 날이 올 줄 알았어야지.",
  ui_story_1018_10181101_42_dialog_content = "...레이스는 어디 있지?",
  ui_story_1018_10181101_43_dialog_content = "걔가 죽는 건 시간문제야. 그러고 나면 대원수 자리는 네 거가 되겠지.",
  ui_story_1018_10181101_44_dialog_content = "대원수는 너 따위가 모욕할 수 있는 게 아냐!",
  ui_story_1018_10181101_45_dialog_content = "그어어!",
  ui_story_1018_10181101_46_dialog_content = "......",
  ui_story_1018_10181101_47_dialog_content = "왜 그래? 못 죽이겠어? 마음의 준비가 필요한 거라면 서두르는 게 좋을 거야.",
  ui_story_1018_10181101_48_dialog_content = "늪속에 몸을 숨길 수 있다니...",
  ui_story_1018_10181101_49_dialog_content = "설마 더스크 타운이 이미 늪에 잠겼고... 그 늪이 지하에서 퍼져나온 건 아니겠지...",
  ui_story_1018_10181101_50_dialog_content = "일루미나의 방어선도... 늪에 잠겨버리는 건가?",
  ui_story_1018_10181101_51_dialog_content = "...우선은 암귀를 처리해라. 난 참호 아래 상황을 확인하겠다.",
  ui_story_1018_10181101_52_dialog_content = "저들이 지하에서 튀어나올 수 있다면, 차라리 지하성을 직접 공격하는 게 더 빠르겠지.",
  ui_story_1018_10181101_53_dialog_content = "동요할 것 없다. 전선을 지켜라!",
  ui_story_1018_10181101_54_dialog_content = "예!",
  ui_story_1018_10181101_55_dialog_content = "공격부대는 석벽 근처까지 물러나 암귀를 소탕하라.",
  ui_story_1018_10181101_56_dialog_content = "그어어!",
  ui_story_1018_10181101_57_dialog_content = "군단장님! 저들은... 우리 일루미나의 병사입니까?!",
  ui_story_1018_10181101_58_dialog_content = "다크매터가 모여 암귀를 잡아먹고 동포들을 해치고 있다...",
  ui_story_1018_10181101_59_dialog_content = "놈들은 암귀다! 용서하지 마라!",
  ui_story_1018_10181101_60_dialog_content = "아, 알겠습니다!",
  ui_story_1018_10181102_1_dialog_content = "<color=#e8d9bb>콰아아앙──!</color>",
  ui_story_1018_10181102_2_dialog_content = "포격입니다! 늪의 확산이 멈춘 것 같습니다!",
  ui_story_1018_10181102_3_dialog_content = "암귀의 공세도 멈췄습니다!",
  ui_story_1018_10181102_4_dialog_content = "군단장님께서 적시에 내리신 명령 덕분입니다!",
  ui_story_1018_10181102_5_dialog_content = "내가 내린 명령이 아냐...",
  ui_story_1018_10181102_6_dialog_content = "...포격은 각각 세 곳의 보루에서 가해진 것 같습니다!",
  ui_story_1018_10181102_7_dialog_content = "설마...",
  ui_story_1018_10181102_8_dialog_content = "하하하하, 아주 자극적이야! 이렇게 흥분되는 포성도 참 오랜만이잖아!",
  ui_story_1018_10181102_9_dialog_content = "목표에서 약간 벗어났지만, 소기의 효과는 달성했습니다.",
  ui_story_1018_10181102_10_dialog_content = "군단장님! 바튼 장군님과 히이로 장군님입니다!",
  ui_story_1018_10181102_11_dialog_content = "역시 다른 군단장님들의 지원이었군요!",
  ui_story_1018_10181102_12_dialog_content = "지하성 방어는 이미 순조롭게 되고 있으니까. 방어선의 싸움을 이 바튼 님이 놓칠 순 없잖아!",
  ui_story_1018_10181102_13_dialog_content = "적이 여기까지 쳐들어 온 이상, 조용히 후방에 머무를 이유는 없습니다.",
  ui_story_1018_10181102_14_dialog_content = "두 사람의 지원에 진심으로 감사할게.\n지금까지 암귀의 움직임은 아직 우리가 제어할 수 있는 범위 내야.",
  ui_story_1018_10181102_15_dialog_content = "다만 참호에 늪이 생긴 걸 보면 놈들이 지하성까지 침투했을지가 걱정이야.",
  ui_story_1018_10181102_16_dialog_content = "오는 동안 그런 상황은 발생하지 않았습니다. 아마 적은 방어선에 이제 막 도착했을 겁니다.",
  ui_story_1018_10181102_17_dialog_content = "맞아. 방어선 주변은 내가 잘 보고 있다고.",
  ui_story_1018_10181102_18_dialog_content = "늪은 여기 오기 전 더스크 타운을 파괴했어. 게다가 또 노라 그 녀석이야...",
  ui_story_1018_10181102_19_dialog_content = "어떤 상황이든 우리가 함께 맞서면 됩니다.",
  ui_story_1018_10181102_20_dialog_content = "이제 레이스만 기다리면 돼. 우리에게 말한 계획대로 되길 빌어야겠지...",
  ui_story_1018_10181102_21_dialog_content = "나는 믿는다.",
  ui_story_1018_10181102_22_dialog_content = "...대원수님!",
  ui_story_1018_10181102_23_dialog_content = "저도 레이스를 믿어요!",
  ui_story_1018_10181102_24_dialog_content = "참모장까지...? 어떻게...",
  ui_story_1018_10181102_25_dialog_content = "레이스의 계획으로는 암귀가 방어선에 쳐들어올 경우 제가 마지막으로\n출병하기로 되어 있었습니다.",
  ui_story_1018_10181102_26_dialog_content = "명령을 받은 후, 대원수님은 저와 함께 움직이셨습니다.",
  ui_story_1018_10181102_27_dialog_content = "그럼...아까 포탄 세 발 중에 한 발은 대원수님이 쏘신 겁니까?",
  ui_story_1018_10181102_28_dialog_content = "<color=#FFB400>자주포를 다루는</color> 건 오랜만이지만, 서툴진 않았던 모양이야.",
  ui_story_1018_10181102_29_dialog_content = "하지만 대원수님, 감옥은 어떻게...",
  ui_story_1018_10181102_30_dialog_content = "아, 잊을 뻔했네요!",
  ui_story_1018_10181102_31_dialog_content = "보고드립니다! 참모장 비비안, 탈옥 조력 임무를 무사히 완수했습니다!",
  ui_story_1018_10181102_32_dialog_content = "하, 참...",
  ui_story_1018_10181102_33_dialog_content = "보고드립니다! 제1군단장 시로나, 명령에 따라 방어선을 지키고,\n한 마리 암귀도 침입을 허용하지 않았습니다.",
  ui_story_1018_10181102_34_dialog_content = "나 제2군단장 바튼이 있는 한, 암귀가 지하성에 들어오는 건 꿈도 못 꿀 거다!",
  ui_story_1018_10181102_35_dialog_content = "제3군단장 히이로, 최후 지원부대로서 임무를 완수했습니다.",
  ui_story_1018_10181102_36_dialog_content = "다들 잘했어. 일루미나의 동포들, 모두 고생했다!",
  ui_story_1018_10181102_37_dialog_content = "대원수님과 군단장님들이 전부 오시다니... 믿기지가 않아...",
  ui_story_1018_10181102_38_dialog_content = "대원수님!",
  ui_story_1018_10181102_39_dialog_content = "우오오오──!",
  ui_story_1018_10181201_1_dialog_content = "군단장님, 참호 안에 노라의 흔적은 없었습니다.",
  ui_story_1018_10181201_2_dialog_content = "현재 백야성 기병들은 여전히 방어선을 지키고 있습니다.\n또한, 더스크 타운으로 향했던 지원군도 돌아오고 있다고 합니다.",
  ui_story_1018_10181201_3_dialog_content = "알겠다. 지원군이 보이는 대로 즉시 보고하도록.",
  ui_story_1018_10181201_4_dialog_content = "아무래도 백야성은 전쟁에 개입할 생각이 없는 모양이군요.",
  ui_story_1018_10181201_5_dialog_content = "아직 더스크 타운의 상황을 모르는 이상, 앞으로도 의논의 여지는 있다.\n지금은 그저 레이스가 걱정될 뿐이다...",
  ui_story_1018_10181201_6_dialog_content = "그렇습니다. 이미 한참 동안 더스크 타운에서 소식이 오지 않았습니다.",
  ui_story_1018_10181201_7_dialog_content = "모두 제 책임입니다. 레이스가 더스크 타운으로 향한 뒤로 전 이곳을 지키기만 했습니다...",
  ui_story_1018_10181201_8_dialog_content = "진격할 경우 방어선이 붕괴할 위험이 있었고,\n방어선 안으로 물러나면 더스크 타운의 소식을 알 수 없는 상황이었습니다.",
  ui_story_1018_10181201_9_dialog_content = "심지어 늪의 확산 정황도 모른 채 노라를 놓치고 말았습니다.",
  ui_story_1018_10181201_10_dialog_content = "네 책임이 아니다. 더스크 타운 쪽 상황은 오는 길에 들었다.\n적은 전대미문의 방식으로 공격을 가했다. 그러니 모두 조심해야 한다.",
  ui_story_1018_10181201_11_dialog_content = "대원수님, 전방의 늪에 움직임이 있습니다. 적이 빠르게 이쪽으로 접근하는 중입니다.",
  ui_story_1018_10181201_12_dialog_content = "또 죽으러 오는 거냐? 내가 상대해 주지!",
  ui_story_1018_10181201_13_dialog_content = "늪을 조심해. 노라가 잠복하고 있을 가능성이 높아.",
  ui_story_1018_10181201_14_dialog_content = "쥐새끼처럼 뛰어다니는 게 너희가 방어선을 공략하는 방법이냐?",
  ui_story_1018_10181201_15_dialog_content = "표범의 일격을 받아라!",
  ui_story_1018_10181201_16_dialog_content = "모두 삼켜주마──",
  ui_story_1018_10181201_17_dialog_content = "벌레 자식, 드디어 나왔군!",
  ui_story_1018_10181201_18_dialog_content = "그어어──",
  ui_story_1018_10181201_19_dialog_content = "군단장님! 늪에서 암귀가 출현했고, 정체를 알 수 없는 다수의 병사들이\n방어선을 향해 이동 중입니다!",
  ui_story_1018_10181201_20_dialog_content = "대원수님, 지시를 내려 주십시오!",
  ui_story_1018_10181201_21_dialog_content = "......",
  ui_story_1018_10181201_22_dialog_content = "명령은 내리지 않는다. 지금 이곳은 내가 지휘할 전장이 아니거든.",
  ui_story_1018_10181201_23_dialog_content = "대원수님...",
  ui_story_1018_10181201_24_dialog_content = "더 논의할 여지는 없다. 나는 나 개인의 이름으로 부대에 들어가겠다.",
  ui_story_1018_10181201_25_dialog_content = "너희는 각자 계획에 따라 마음껏 해 봐라.",
  ui_story_1018_10181201_26_dialog_content = "......",
  ui_story_1018_10181201_27_dialog_content = "그럼 기껏 가져온 포탄을 안 쓸 순 없지! 동부 포병대, 조준!",
  ui_story_1018_10181201_28_dialog_content = "서부 포병대, 조준!",
  ui_story_1018_10181201_29_dialog_content = "군단장님, 동서 수비부대가 집결했습니다.",
  ui_story_1018_10181201_30_dialog_content = "동서 수비부대는 늪을 뚫고 노라를 찾고, 공격부대는 암귀를 요격한다!",
  ui_story_1018_10181201_31_dialog_content = "잠깐만요, 시로나... 늪에 덮인 저 암귀들... 일루미나의 병사잖아요...?",
  ui_story_1018_10181201_32_dialog_content = "......",
  ui_story_1018_10181201_33_dialog_content = "일부는... 아직 의식이 있어. 하지만 이미 완전히 암귀가 된 자들도 많아.",
  ui_story_1018_10181201_34_dialog_content = "그럼 어떻게 해야...",
  ui_story_1018_10181201_35_dialog_content = "내게 맡겨라.",
  ui_story_1018_10181201_36_dialog_content = "대원수님...",
  ui_story_1018_10181201_37_dialog_content = "걱정하지 마. 희망이 있는 한 내가 저들을 구해낼 테니까.",
  ui_story_1018_10181201_38_dialog_content = "하지만 대원수님, 저들은 병사를 잡아먹고 있습니다! 그리고 아까 전 이미 저들을...",
  ui_story_1018_10181201_39_dialog_content = "내가 너였어도 같은 일을 했을 거다. 다만 내 몸이라면 놈들이 물어뜯어도 견딜 수 있겠지.",
  ui_story_1018_10181201_40_dialog_content = "계속 부하들의 지휘에 힘써라. 부상자를 데려올 부대도 곧 도착할 것이다.",
  ui_story_1018_10181201_41_dialog_content = "네, 대원수님.",
  ui_story_1018_10181201_42_dialog_content = "<color=#e8d9bb>콰아앙──</color>",
  ui_story_1018_10181201_43_dialog_content = "방금 저건... 히이로 군단장님 쪽 포격입니까? 늪에 명중했습니다!",
  ui_story_1018_10181201_44_dialog_content = "...서부 포병대는 아직 공격하지 않았습니다.",
  ui_story_1018_10181201_45_dialog_content = "뭘 봐? 나도 아니라고.",
  ui_story_1018_10181201_46_dialog_content = "그렇다면...",
  ui_story_1018_10181201_47_dialog_content = "후훗, 네가 온다고 해서 머드번들을 막을 수 있을 것 같아?",
  ui_story_1018_10181201_48_dialog_content = "녀석은 더스크 타운도 부수고 온 몸이야.",
  ui_story_1018_10181201_49_dialog_content = "늪은 방어선을 넘는다──",
  ui_story_1018_10181201_50_dialog_content = "노라, 더스크 타운을 무너트려 놓고, 지금은 왜 또 방어선을 공격하는 거냐.",
  ui_story_1018_10181201_51_dialog_content = "뭐야, 널 감옥까지 처넣은 일루미나를 아직도 생각해 주고 있는 건 아니지?",
  ui_story_1018_10181201_52_dialog_content = "나랑 치고받느니 차라리 성문이나 열고, 내가 널 모함한 놈들을 태워 죽이게 두는 게 어때?",
  ui_story_1018_10181201_53_dialog_content = "훗, 일루미나에는 일루미나의 규칙이 있다. 너흰 여기까지다.",
  ui_story_1018_10181201_54_dialog_content = "여전히 성자라도 된 양 말하는구나. 그러니 그 꼴이 됐지.",
  ui_story_1018_10181201_55_dialog_content = "대원수님께 그런 언사는 용납 못 해요!",
  ui_story_1018_10181201_56_dialog_content = "충견은 눈이나 똑바로 떠. 애초에 여긴 대원수 같은 건 없어.",
  ui_story_1018_10181201_57_dialog_content = "대원수가 없다고? 지금 저렇게 왔는데 무슨 소리냐.",
  ui_story_1018_10181201_58_dialog_content = "<color=#e8d9bb>진동하는 대지 위로 귀를 울리는 바퀴 소리와 말발굽 소리가 들려왔다...</color>",
  ui_story_1018_10181201_59_dialog_content = "미리 지상으로 내려오길 잘했다니까. 역시 땅에서 달리는 게 마음이 편해!",
  ui_story_1018_10181201_60_dialog_content = "전방의 참호를 넘고 나면 적은 도망갈 곳을 잃는다! 자주포는 계속해서 늪을 공격하라!",
  ui_story_1018_10181201_61_dialog_content = "으음, 일루미나의 방어선은 정말 소란스럽군. 적의 공격 전략이 이렇게 직접적일 줄이야.",
  ui_story_1018_10181201_62_dialog_content = "흥, 원하던 바야. 포위망의 마지막 철벽은 우리가 만들게 될 테니까.",
  ui_story_1018_10181201_63_dialog_content = "악셀리아는 부하들을 되찾아 올 겁니다...",
  ui_story_1018_10181201_64_dialog_content = "벌써 회복된 건가? 당신 몸은 꼭 일루미나의 전투 기계 같군...",
  ui_story_1018_10181201_65_dialog_content = "정말 심한 부상이었는데, 다치기 전의 상태까지 회복할 수 있다니...",
  ui_story_1018_10181201_66_dialog_content = "PlayerName, 충분히 쉬었으면 전투를 시작하자. 도착하기 전까지 보이는 암귀를 전부 쓰러트려야 해.",
  ui_story_1018_10181201_67_dialog_content = "네, 준비됐어요.",
  ui_story_1018_10181201_68_dialog_content = "그럼 꽉 잡아. 여기서 낙오하면 포병대가 암귀인 줄 알고 쏴버릴 테니까.",
  ui_story_1018_10181201_69_dialog_content = "...알았어요.",
  ui_story_1018_10181201_70_dialog_content = "<color=#e8d9bb>콰앙──</color>",
  ui_story_1018_10181201_71_dialog_content = "커브 돌 거니까 조심해!",
  ui_story_1018_10181201_72_dialog_content = "「엔진 7호」? 갑자기... 참호 속에서 나타났습니다!",
  ui_story_1018_10181201_73_dialog_content = "저건... 더스크 타운에서 부서졌던 그 기체야.",
  ui_story_1018_10181201_74_dialog_content = "「엔진 7호」까지 가져오다니... 병사들이 사라진 이유가 있었어...",
  ui_story_1018_10181201_75_dialog_content = "...그어어...",
  ui_story_1018_10181201_76_dialog_content = "...이 목소리... 파일럿이 아직 의식이 있는 걸까요?",
  ui_story_1018_10181201_77_dialog_content = "가까이 가지 마! 녀석 아래에서 병사가 기어올라온다!",
  ui_story_1018_10181201_78_dialog_content = "늪에... 대체 얼마나 많은 병사가...",
  ui_story_1018_10181201_79_dialog_content = "<color=#e8d9bb>콰직── 끼익── 끼익──</color>",
  ui_story_1018_10181201_80_dialog_content = "저 움직임... 머뭇거리고 있는 거야...",
  ui_story_1018_10181201_81_dialog_content = "대원수님, 안의 병사는 어쩌면 아직 살아있을지도 모릅니다.\n악셀리아는 병사를 구하고 싶습니다.",
  ui_story_1018_10181201_82_dialog_content = "넌 이미... 한 번 부서졌잖아!",
  ui_story_1018_10181201_83_dialog_content = "지금까지 악셀리아는 몇 번이나 부서져 왔습니다...",
  ui_story_1018_10181201_84_dialog_content = "하지만 그때마다 악셀리아는 회복했습니다.",
  ui_story_1018_10181201_85_dialog_content = "안에 있는 파일럿은 악셀리아 부대의 대원입니다.\n대원을 지키는 것은 악셀리아의 의무입니다.",
  ui_story_1018_10181201_86_dialog_content = "......",
  ui_story_1018_10181201_87_dialog_content = "...그어어...",
  ui_story_1018_10181201_88_dialog_content = "몸이 이미 기계와 하나가 됐어... 저 파일럿, 분명히 무척 괴로울 거야.",
  ui_story_1018_10181201_89_dialog_content = "악셀리아도 신체의 일부는 기계입니다. 그래서 악셀리아는 알 수 있어요.\n지금 그는 무척 괴로울 거예요.",
  ui_story_1018_10181201_90_dialog_content = "...미안... 악셀리아...",
  ui_story_1018_10181201_91_dialog_content = "레이스 씨, 제가 악셀리아랑 같이 갈게요! 같이 악셀리아의 부하들을 구할 수 있을 거예요!",
  ui_story_1018_10181201_92_dialog_content = "...대원수의 직무대로라면 난 너희들을 막아야 해. 하지만 이렇게 된 이상...",
  ui_story_1018_10181201_93_dialog_content = "레오, 「엔진 7호」의 주의를 끌어줘!",
  ui_story_1018_10181201_94_dialog_content = "얼마든지.",
  ui_story_1018_10181201_95_dialog_content = "레이스 씨...?",
  ui_story_1018_10181201_96_dialog_content = "내가 어떻게 너희 둘만 보낼 수 있겠어?",
  ui_story_1018_10181201_97_dialog_content = "「엔진 7호」는 더스크 타운에서 줄곧 우리 군의 보루 역할을 맡아줬어.\n하지만 지금은 우리 앞을 가로막고 있어.",
  ui_story_1018_10181201_98_dialog_content = "녀석이 너희들을 해치려 한다면, 반드시 나라는 보루부터 무너트려야 할 거야.",
  ui_story_1018_10181201_99_dialog_content = "그어어!",
  ui_story_1018_10181201_100_dialog_content = "이런... 참호 속에서 병사들이 기어나오고 있어요...",
  ui_story_1018_10181201_101_dialog_content = "모두... 악셀리아의 부하들입니다...",
  ui_story_1018_10181201_102_dialog_content = "내 부하를 이용해서 날 막겠다...? 더는 뜻대로 안 될걸!",
  ui_story_1018_10181201_103_dialog_content = "안심하고 가, 악셀리아! 가서 네 부하를 구하는 거야! 병사들은 나한테 맡겨!",
  ui_story_1018_10181201_104_dialog_content = "알겠습니다.",
  ui_story_1018_10181202_1_dialog_content = "이쪽 병사들은 전부 제압했다. 아직 의식이 있어.",
  ui_story_1018_10181202_2_dialog_content = "이쪽도 끝났어. 「엔진 7호」의 공격을 조심해.",
  ui_story_1018_10181202_3_dialog_content = "...그어어...",
  ui_story_1018_10181202_4_dialog_content = "악셀리아는 알 수 있습니다. 당신이 겪은 일은 무척 괴로울 거예요.",
  ui_story_1018_10181202_5_dialog_content = "당신도 모두에게 상처를 주고 싶지는 않을 겁니다... 악셀리아는 모두 알고 있습니다.",
  ui_story_1018_10181202_6_dialog_content = "그어어...",
  ui_story_1018_10181202_7_dialog_content = "천천히 방어선 쪽으로 이동하고 있어요... 저쪽엔 적은 없어요.",
  ui_story_1018_10181202_8_dialog_content = "조심해서 따라가! 참호를 넘고 나면 뒤에서부터 제압해!",
  ui_story_1018_10181202_9_dialog_content = "그어어!",
  ui_story_1018_10181202_10_dialog_content = "지금이야!",
  ui_story_1018_10181202_11_dialog_content = "악셀리아, 떨어져!",
  ui_story_1018_10181202_12_dialog_content = "「꿰뚫어라, 우레의 창이여!」",
  ui_story_1018_10181202_13_dialog_content = "그어어...",
  ui_story_1018_10181202_14_dialog_content = "멈췄어요! 하지만 악셀리아가 녀석한테 맞고 날아갔어요──!",
  ui_story_1018_10181202_15_dialog_content = "레오, 악셀리아가 그쪽으로!",
  ui_story_1018_10181202_16_dialog_content = "이랴──!",
  ui_story_1018_10181202_17_dialog_content = "이 거리라면 문제없어!",
  ui_story_1018_10181202_18_dialog_content = "이랴──!",
  ui_story_1018_10181202_19_dialog_content = "<color=#e8d9bb>히히힝──</color>",
  ui_story_1018_10181202_20_dialog_content = "워어, 워──",
  ui_story_1018_10181202_21_dialog_content = "또다시 네 용맹함을 증명했군, 더스크 타운의 레오.",
  ui_story_1018_10181202_22_dialog_content = "당신이... 어떻게 여기에...?",
  ui_story_1018_10181202_23_dialog_content = "고생했다, 악셀리아.",
  ui_story_1018_10181202_24_dialog_content = "...대원수님이 악셀리아를 받아주었습니다.",
  ui_story_1018_10181202_25_dialog_content = "넌 이미 시범 경기 때의 자신을 뛰어넘었다. 너는 우수한 전사다.",
  ui_story_1018_10181202_26_dialog_content = "악셀리아는... 대원수님이 하신 말씀을 계속 생각하고 있었습니다...",
  ui_story_1018_10181202_27_dialog_content = "악셀리아는 대원수님께 묻고 싶습니다. 암귀를 이기고 일루미나를 지킨 전사는...",
  ui_story_1018_10181202_28_dialog_content = "「인간으로 살아」간다고 할 수 있나요?",
  ui_story_1018_10181202_29_dialog_content = "넌 이미 해냈다, 악셀리아.",
  ui_story_1018_10181202_30_dialog_content = "감사합니다, 대원수님. 악셀리아는 계속해서 싸울 거예요.",
  ui_story_1018_10181202_31_dialog_content = "기회는 앞으로도 얼마든지 있다, 악셀리아. 지금은 널 걱정하는 동료가 널 데리러 왔다.",
  ui_story_1018_10181202_32_dialog_content = "악셀리아! 다행이에요... 늦지 않았네요...",
  ui_story_1018_10181202_33_dialog_content = "잉겔...",
  ui_story_1018_10181202_34_dialog_content = "미안해요! 분명히 알고 있었으면서... 이런 일을 겪게 만들어서... 정말 미안해요!",
  ui_story_1018_10181202_35_dialog_content = "악셀리아는 알고 있습니다. 잉겔은 악셀리아를 지키고 싶어 해요.",
  ui_story_1018_10181202_36_dialog_content = "악셀리아가 무사해서 정말 다행이야.\n그러게 내가 말했잖아~ 착한 아기새는 반드시 보답을 받는다구!",
  ui_story_1018_10181202_37_dialog_content = "대원수님! 연구원장 그로누, 잉겔 중령과 함께 일루미나의 병사들을 데리러 왔어요!",
  ui_story_1018_10181202_38_dialog_content = "그래, 이 전사들은 너희에게 부탁하지.",
  ui_story_1018_10181202_39_dialog_content = "대원수님, 공개재판 때 일은... 정말 죄송합니다.",
  ui_story_1018_10181202_40_dialog_content = "그리고 율리시스 교수의 실험도...",
  ui_story_1018_10181202_41_dialog_content = "하지만 믿어주세요. 더는 이 일로 교수님을 두둔할 생각은 없습니다.\n전 무고한 동포들이 상처받는 걸 더는 보고 싶지 않습니다.",
  ui_story_1018_10181202_42_dialog_content = "허락해 주신다면 병사들을 데리고 일루미나로 돌아가 치료를 받게 하겠습니다.\n그리고 실험 일은 제가 어떻게든...",
  ui_story_1018_10181202_43_dialog_content = "너희는 모두 피해자다. 미안함을 느낄 필요는 없다.",
  ui_story_1018_10181202_44_dialog_content = "하지만... 저 때문에 대원수 자리에서...",
  ui_story_1018_10181202_45_dialog_content = "대원수 자리는 네 말 한 마디로 뺏을 수 있는 게 아냐.",
  ui_story_1018_10181202_46_dialog_content = "그래도 고맙다고 해야겠어. 네 덕분에 난 한 번이라도 대원수가 될 수 있었으니까.",
  ui_story_1018_10181202_47_dialog_content = "돌아왔구나, 레이스.",
  ui_story_1018_10181202_48_dialog_content = "우와~ 대원수가 둘이네!",
  ui_story_1018_10181202_49_dialog_content = "역시 레이스라면 문제없을 줄 알았어요!",
  ui_story_1018_10181202_50_dialog_content = "너 이 자식 꽤 대원수다워졌잖아?",
  ui_story_1018_10181202_51_dialog_content = "더스크 타운의 격전을 결국엔 이겨냈구나.",
  ui_story_1018_10181202_52_dialog_content = "우린 계속 방어선에서 기다리고 있었습니다.",
  ui_story_1018_10181202_53_dialog_content = "대원수 자리를 잠깐 대신 맡고, 살아서 돌아오겠다고 했잖아.\n이 레이스가 약속을 어길 리가 있겠어?",
  ui_story_1018_10181202_54_dialog_content = "대원수님... 군단장님들... 설마...",
  ui_story_1018_10181202_55_dialog_content = "......",
  ui_story_1018_10181202_56_dialog_content = "지금까지 난 하나의 결과만 연연하며 애써왔어.\n하지만 마침내 한 가지 사실을 검증했어... 그건 바로 내가...",
  ui_story_1018_10181202_57_dialog_content = "레이스, 넌 자격이 있어.",
  ui_story_1018_10181202_58_dialog_content = "아직 말 안 했는데...",
  ui_story_1018_10181202_59_dialog_content = "넌 충분히 자격이 있어.",
  ui_story_1018_10181202_60_dialog_content = "......",
  ui_story_1018_10181202_61_dialog_content = "크흠... 네가 그런다고 내가 넙죽 받아들일 줄 알았어?",
  ui_story_1018_10181202_62_dialog_content = "널 이기지 못하면 난 마음 편하게 대원수가 될 수 없다고.",
  ui_story_1018_10181202_63_dialog_content = "전쟁은 아직 안 끝났어. 똑바로 잘 지휘해.",
  ui_story_1018_10181202_64_dialog_content = "......",
  ui_story_1018_10181202_65_dialog_content = "...근위군단장 레이스, 명령에 따라 더스크 타운의 암귀를 격퇴하고, 임무를 완수했습니다.",
  ui_story_1018_10181202_66_dialog_content = "일루미나 제4군단은 이미 방어선에 집결을 마쳤으며,\n일루미나 대원수의 명령을 기다리고 있습니다!",
  ui_story_1018_10181401_1_dialog_content = "시간도 충분히 줬으니까, 지금쯤 여기 큰 구멍이 났을 줄 알았는데 말이죠.",
  ui_story_1018_10181401_2_dialog_content = "왜 그러죠? 언니한테 미련이라도 남았나요?",
  ui_story_1018_10181401_3_dialog_content = "웃기지 마. 지금쯤이면 당신 일이 끝났을 거라 생각하던 참이었어.\n나야말로 계속 시간 낭비할 생각은 없어.",
  ui_story_1018_10181401_4_dialog_content = "그럼 가죠, 당신이 기다리던 순간이 이제 곧 오겠네요.",
  ui_story_1018_10181401_5_dialog_content = "좋아. 대신 가기 전에 좀 정리할 것들이 있어.",
  ui_story_1018_10181401_6_dialog_content = "...노라에 대해서라면 내가 잘 알고 있다.\n녀석은 자기 실험에 도움이 되지 않는다면, 위험을 무릅쓰고 이 정도 일을 하진 않는다.",
  ui_story_1018_10181401_7_dialog_content = "게다가 헬리오스는 아직 자난성에 있다. 지금 상황은 아마 녀석에게 예상 밖의 결과겠지.",
  ui_story_1018_10181401_8_dialog_content = "그럼 노라가 지하성에 잠입한 건, 원하는 걸 주겠다고 율리시스가 약속했기 때문인 거겠네...",
  ui_story_1018_10181401_9_dialog_content = "하지만 율리시스는 약속을 깼고, 「씨앗」을 얻자 곧바로 「계명성 프로젝트」에 사용했어.",
  ui_story_1018_10181401_10_dialog_content = "그럴 가능성은 있어.",
  ui_story_1018_10181401_11_dialog_content = "「가디언 1호」의 코어도 저들의 거래에 포함되나?",
  ui_story_1018_10181401_12_dialog_content = "이클립스가 꾸미는 계획의 일부겠지. 하지만 두 사람의 거래에 포함됐는지는 아직 확실하지 않다.",
  ui_story_1018_10181401_13_dialog_content = "난 「가디언 1호」 코어를 도난당한 건은 율리시스의 계획 밖이었다고 생각한다.",
  ui_story_1018_10181401_14_dialog_content = "위원회가 「계명성 프로젝트」를 위해 「가디언 1호」의 코어를 이클립스 손에 넘길 이유는 없다.",
  ui_story_1018_10181401_15_dialog_content = "그랬다간 대가가 너무 크고, 「씨앗」을 심은 병사들은 이번엔 버티더라도,\n앞으로는 전장에 나설 수 없을 테니 말이야.",
  ui_story_1018_10181401_16_dialog_content = "...뭐? ...너 지금 뭐라고 했어?",
  ui_story_1018_10181401_17_dialog_content = "......",
  ui_story_1018_10181401_18_dialog_content = "......",
  ui_story_1018_10181401_19_dialog_content = "...너, 「씨앗」을 심은 거야...?",
  ui_story_1018_10181401_20_dialog_content = "...그게 뭐 어쨌다고... 지금 이렇게 잘 살아있잖아.",
  ui_story_1018_10181401_21_dialog_content = "......",
  ui_story_1018_10181401_22_dialog_content = "네가 대원수가 되는 걸 지지한 게 「씨앗」을 심는 결과를 초래할 줄이야...",
  ui_story_1018_10181401_23_dialog_content = "이건 너랑은 상관없어. 내가 결정한 거야.",
  ui_story_1018_10181401_24_dialog_content = "아니, 이건 내...",
  ui_story_1018_10181401_25_dialog_content = "내 「씨앗」이 없었으면 자기 힘으로 지금까지 버틸 수 있었을 것 같아?",
  ui_story_1018_10181401_26_dialog_content = "...드디어 왔군, 노라.",
  ui_story_1018_10181401_27_dialog_content = "이 추악한 녀석!",
  ui_story_1018_10181401_28_dialog_content = "노라! 내 부하들에게 고통을 준 빚을... 이제 갚아줄 때가 됐어.",
  ui_story_1018_10181401_29_dialog_content = "레이스 씨, 잠깐만요! 뒤의 늪 속에 병사들이 있어요!",
  ui_story_1018_10181401_30_dialog_content = "그어어...",
  ui_story_1018_10181401_31_dialog_content = "이런 음험한 방법을 쓰다니...",
  ui_story_1018_10181401_32_dialog_content = "병사들을 제압하고 방어선을 지켜줘! 여긴 일단 나한테 맡겨!",
  ui_story_1018_10181401_33_dialog_content = "알겠습니다!\n알겠다!",
  ui_story_1018_10181401_34_dialog_content = "기운이 넘치네. 왜 네 몸속의 「씨앗」은 널 괴롭히지 않았는지 궁금하지 않아?",
  ui_story_1018_10181401_35_dialog_content = "아니면 서슴없이 부하를 죽일 때 사실 즐거웠던 거야?",
  ui_story_1018_10181401_36_dialog_content = "닥쳐라, 노라. 일루미나의 병사를 해친 건 너다.",
  ui_story_1018_10181401_37_dialog_content = "......",
  ui_story_1018_10181401_38_dialog_content = "늪 속에서 날 치료한 건 역시 너였어...",
  ui_story_1018_10181401_39_dialog_content = "부하들을 괴롭히고... 날 궁지에 빠트리고...\n「씨앗」이 내 몸속에서 어떤 반응을 일으키는지 보려던 거겠지...",
  ui_story_1018_10181401_40_dialog_content = "내가 생각한 만큼 멍청하진 않나 보네. 그냥 겸사겸사 율리시스를 도와줬을 뿐이야.\n그 녀석은 처참하게 실패했거든.",
  ui_story_1018_10181401_41_dialog_content = "노라, 대체 이클립스가 네게 뭘 약속했지?",
  ui_story_1018_10181401_42_dialog_content = "그런 걸 네가 어떻게 이해할 수 있겠어? 네가 모든 걸 지킬 힘이 있다고 생각해?",
  ui_story_1018_10181401_43_dialog_content = "아무리 개조를 받아 봤자, 오로리안은 여전히 나약하고 미개한 폐기물일 뿐이야.",
  ui_story_1018_10181401_44_dialog_content = "일루미나의 윗대가리들한테 다 쓰이고 버려질 바에야...\n차라리 너도 얼른 자기 살길을 찾는 게 좋을걸.",
  ui_story_1018_10181401_45_dialog_content = "흥, 이클립스에 빌붙어서 심부름이나 하는 암귀 주제에, 뭘 잘난척을 하고 있어?",
  ui_story_1018_10181401_46_dialog_content = "넌 네가 똑똑하다고 생각하나 본데, 그것도 결국 「인공 태양 프로젝트」에\n참가한 결과물일 뿐이잖아?",
  ui_story_1018_10181401_47_dialog_content = "더스크 타운에서 희생된 병사들, 그리고 여기 있는 이들은 모두 자기 의지로\n지금까지 걸어온 사람들이야.",
  ui_story_1018_10181401_48_dialog_content = "저들에 비하면 너야말로 힘에 굴복한 노예일 뿐이야.",
  ui_story_1018_10181401_49_dialog_content = "정말로 나약한 건 너라고!",
  ui_story_1018_10181401_50_dialog_content = "닥쳐! 정신 나간 머저리 주제에! 지금 네 목숨이 붙어 있는 건 내 「씨앗」 덕분이야!",
  ui_story_1018_10181401_51_dialog_content = "이 세계는 애들 보는 동화책이 아냐.\n살아남으려면 그 어떤 대가를 치러서라도 기어 올라가야 한다고.",
  ui_story_1018_10181401_52_dialog_content = "바퀴벌레처럼 도망만 다니는 무지한 오로리안은 죽을 때까지 이 세계의 진상을 알지 못해.",
  ui_story_1018_10181401_53_dialog_content = "네겐 포부가 있다는 건 안다, 노라.\n하지만 남의 희생을 대가로 그 포부를 실현하는 건 내가 허락하지 않는다.",
  ui_story_1018_10181401_54_dialog_content = "이런 말을 하는 것도 이번이 마지막이다.",
  ui_story_1018_10181401_55_dialog_content = "넌 일루미나의 동포를 해쳤고, 일루미나는 너를 결코 용서하지 않는다.\n하지만 난 지금 대원수가 아냐. 부디 네가 여기서 멈췄으면 좋겠다.",
  ui_story_1018_10181401_56_dialog_content = "이클립스의 명령에 따르지 마라. 그건 네 진정한 의지가 아냐.",
  ui_story_1018_10181401_57_dialog_content = "명령을 따르는 건 너잖아, 라인하르트! 네가 모두를 지킬 순 없어.",
  ui_story_1018_10181401_58_dialog_content = "그리고 날 동정할 필요도 없어. 난 이미 진작에 너와 다른 편이 되었으니까.",
  ui_story_1018_10181401_59_dialog_content = "날 죽이고 싶다면 얼마든지 해 봐. 대신 나도 멈추진 않을 거야.",
  ui_story_1018_10181401_60_dialog_content = "<color=#e8d9bb>콰지직──</color>",
  ui_story_1018_10181401_61_dialog_content = "크흠, 그 작별인사가 언니에게 줄 선물이었나 보죠?",
  ui_story_1018_10181401_62_dialog_content = "팬텀! 이거나 받아라!",
  ui_story_1018_10181401_63_dialog_content = "병사들을 전부 제압했더니 팬텀까지 나타날 줄은 몰랐군요.",
  ui_story_1018_10181401_64_dialog_content = "제가 당신들과 놀아줄 생각이었다면, 당신들은 진작에 죽었어요.",
  ui_story_1018_10181401_65_dialog_content = "노라, 계속 떠들거면 제 생각이 바뀔지도 몰라요.",
  ui_story_1018_10181401_66_dialog_content = "이클립스를 따르지 마라, 노라. 목숨을 잃게 될 거다.",
  ui_story_1018_10181401_67_dialog_content = "상관하지 마, 이건 내 일이야. 라인하르트 너야말로 내 손에 안 죽게 조심해.",
  ui_story_1018_10181401_68_dialog_content = "<color=#e8d9bb>콰지직──</color>",
  ui_story_1018_10181401_69_dialog_content = "몸속의 「씨앗」이 희미하게 떨고 있어... 조심해! 근처에 적이 있어!",
  ui_story_1018_10181401_70_dialog_content = "구웨에엑──",
  ui_story_1018_10181401_71_dialog_content = "그어어!",
  ui_story_1018_10181401_72_dialog_content = "놈이 토해낸 건... 노라가 더스크 타운에서 데려갔던 병사들이야...",
  ui_story_1018_10181401_73_dialog_content = "그어어!",
  ui_story_1018_10181401_74_dialog_content = "뭐, 뭐냐, 이미 쓰러트린 게 아니었나?! 또 일어섰잖아!",
  ui_story_1018_10181401_75_dialog_content = "역시 다른 수를 남기고 있었군.",
  ui_story_1018_10181401_76_dialog_content = "저 참호는 아까부터 늪이 쌓여 있었고, 이 기체는 쓰러진 뒤로 줄곧 참호 속에 있었다.",
  ui_story_1018_10181401_77_dialog_content = "그렇다면 지금 늪에서 다시 나타난 암귀는... 아마 쉽게 쓰러지지 않을 것이다.",
  ui_story_1018_10181401_78_dialog_content = "이제 어떡하지? 대원수.",
  ui_story_1018_10181401_79_dialog_content = "......",
  ui_story_1018_10181401_80_dialog_content = "......",
  ui_story_1018_10181401_81_dialog_content = "부하들에게 안식을 주지 못한 건 내 잘못이야...",
  ui_story_1018_10181401_82_dialog_content = "그러니 부하들의 몸은 어떻게든 내가 되찾겠어!",
  ui_story_1018_10181401_83_dialog_content = "레이스 씨... 노라한테 당한 지도 얼마 안 됐잖아요...",
  ui_story_1018_10181401_84_dialog_content = "내 몸은 내가 잘 알아... 제어할 수 있어... 그 힘은 쓰지 않을 거야.",
  ui_story_1018_10181401_85_dialog_content = "곧바로 늪의 「중심」을 쳐서 다시 한번 부숴주겠어!",
  ui_story_1018_10181401_86_dialog_content = "나도 같이 할게, 레이스. 난폭해진 병사들은 내게 맡겨.",
  ui_story_1018_10181401_87_dialog_content = "방어선은 우리한테 맡기라고!",
  ui_story_1018_10181401_88_dialog_content = "네!\n그래!",
  ui_story_1018_10181401_89_dialog_content = "대원수──!",
  ui_story_1018_10181401_90_dialog_content = "당신들까지...",
  ui_story_1018_10181401_91_dialog_content = "백야성 공중기병이 엄호할 거야. 암귀는 너흴 해치지 못해.",
  ui_story_1018_10181401_92_dialog_content = "대원수의 전투 방식은 이미 익숙하다. 이번엔 더스크 타운의 기사들이 늪까지 함께하도록 하지.",
  ui_story_1018_10181401_93_dialog_content = "레이스 씨! 저도 있어요! 제가 작전을 보조할게요!",
  ui_story_1018_10181401_94_dialog_content = "만물은 백야 아래에── 각 세력이 모여 이루어진 연합군이네요!",
  ui_story_1018_10181401_95_dialog_content = "그럼 각자의 뜻을 펼쳐라! 적을 쓰러트리고 다시 모이는 것이다!",
  ui_story_1018_10181401_96_dialog_content = "라인하르트, 이걸로 됐을까?",
  ui_story_1018_10181401_97_dialog_content = "그래, 무슨 일이 있어도 단 한 사람의 일루미나의 동포도 저버릴 순 없다!",
  ui_story_1018_10181501_1_dialog_content = "<color=#e8d9bb>주륵주륵...</color>",
  ui_story_1018_10181501_2_dialog_content = "어? 비가 오잖아...?",
  ui_story_1018_10181501_3_dialog_content = "확실히 흔치 않은 일이군.",
  ui_story_1018_10181501_4_dialog_content = "대원수님, 이제 주변에 암귀의 흔적은 없습니다.",
  ui_story_1018_10181501_5_dialog_content = "백야성 부대는 전장을 소탕하러 동서 방어선으로 향했습니다.",
  ui_story_1018_10181501_6_dialog_content = "내 쪽도 순조롭다. 늪이 걷히고 있고, 방어선은 멀쩡하다!",
  ui_story_1018_10181501_7_dialog_content = "레이스 이 자식, 역시 꽤 하잖아!",
  ui_story_1018_10181501_8_dialog_content = "늪이 걷힌 건 이 비와 관계가 있는 걸까요?",
  ui_story_1018_10181501_9_dialog_content = "그건 생각 안 해 봤는데, 그럼... 정말 끝난 건가...?",
  ui_story_1018_10181501_10_dialog_content = "정신이 들었나, 괜찮아?",
  ui_story_1018_10181501_11_dialog_content = "계속 깨어 있었거든? 그냥 생각 중이었어... 그때 네가 나한테 했던 말...",
  ui_story_1018_10181501_12_dialog_content = "<color=#e8d9bb>레이스가 율리시스를 찾아가기 전...</color>",
  ui_story_1018_10181501_13_dialog_content = "대체 언제까지 여기 있을 거야?",
  ui_story_1018_10181501_14_dialog_content = "여기서 그 얘기는 하지 마. 판결은 너도 들었잖아.",
  ui_story_1018_10181501_15_dialog_content = "라인하르트!",
  ui_story_1018_10181501_16_dialog_content = "설마 지금 네가 적과 내통했다는 헛소리를 나보고 믿으라는 거야?",
  ui_story_1018_10181501_17_dialog_content = "......",
  ui_story_1018_10181501_18_dialog_content = "계속 그렇게 입 다물고 있을 거야? 「인공 태양 프로젝트」에 참가했을 했을 때처럼?",
  ui_story_1018_10181501_19_dialog_content = "다 알았구나.",
  ui_story_1018_10181501_20_dialog_content = "네가 결투에서 날 이긴 것도, 신체 개조를 받았기 때문인 거야?",
  ui_story_1018_10181501_21_dialog_content = "......",
  ui_story_1018_10181501_22_dialog_content = "대답해!",
  ui_story_1018_10181501_23_dialog_content = "너한테 보이는 것처럼 그리 단순한 문제가 아냐. 일루미나를 생각한다면 그 이상은 묻지 마.",
  ui_story_1018_10181501_24_dialog_content = "일루미나의 대원수라는 사람이──",
  ui_story_1018_10181501_25_dialog_content = "바로 그래서야! 난 반드시 이 결과를 받아들여야만 해.",
  ui_story_1018_10181501_26_dialog_content = "......",
  ui_story_1018_10181501_27_dialog_content = "알았으면 이 손 놔. 지금은 나와 다투고 있을 때가 아냐.",
  ui_story_1018_10181501_28_dialog_content = "......",
  ui_story_1018_10181501_29_dialog_content = "네 미래는 네 손안에서 솟아날 거야.",
  ui_story_1018_10181501_30_dialog_content = "그렇게 주먹만 쥐고 있으면 아무것도 남지 않아.",
  ui_story_1018_10181501_31_dialog_content = "「주먹만 쥐고 있으면 아무것도 남지 않아」...",
  ui_story_1018_10181501_32_dialog_content = "왜 지금 이 말이 생각난 걸까...",
  ui_story_1018_10181501_33_dialog_content = "때가 되었으니까. 이제 우린 주먹을 쥐고 공통의 적과 맞서야 해.",
  ui_story_1018_10181501_34_dialog_content = "쥐어진 주먹은 공통의 적을 향해야만 해.",
  ui_story_1018_10181501_35_dialog_content = "......",
  ui_story_1018_10181501_36_dialog_content = "날 믿어. 내 손안의 힘은 네가 가장 잘 알테니까.",
  ui_story_1018_10181501_37_dialog_content = "이게 전부 네 계획이었어...?",
  ui_story_1018_10181501_38_dialog_content = "......",
  ui_story_1018_10181501_39_dialog_content = "이미 각오한 거구나. 나보고 마음껏 해 보라고...",
  ui_story_1018_10181501_40_dialog_content = "......",
  ui_story_1018_10181501_41_dialog_content = "알겠어.",
  ui_story_1018_10181501_42_dialog_content = "대원수 자리는 내가 잠깐 대신 맡아줄게.",
  ui_story_1018_10181501_43_dialog_content = "하지만 언젠간 반드시 철벽을 부수고, 네가 그 무엇에도 얽매일 필요 없이\n전력으로 날 상대하게 만들 거야.",
  ui_story_1018_10181501_44_dialog_content = "그때까진 함께 주먹을 쥐고 공통의 적과 맞서자.",
  ui_story_1018_10181501_45_dialog_content = "레이스.",
  ui_story_1018_10181501_46_dialog_content = "응?",
  ui_story_1018_10181501_47_dialog_content = "마음껏 해. 다만, 꼭 살아서 돌아와.",
  ui_story_1018_10181501_48_dialog_content = "......",
  ui_story_1018_10181501_49_dialog_content = "<color=#e8d9bb>주륵주륵...</color>",
  ui_story_1018_10181501_50_dialog_content = "결국 난 살아서 돌아왔어. 하지만 저 병사들은... 이제 구할 수 없어, 그렇지?",
  ui_story_1018_10181501_51_dialog_content = "여기까지 버틴 것만으로도 저들은 이미 충분히 훌륭해.",
  ui_story_1018_10181501_52_dialog_content = "저들은 진정한 용사야. 일루미나는 최고의 경의를 담아 저들의 장례를 치를 거야.",
  ui_story_1018_10181501_53_dialog_content = "난 더스크 타운에서도 저들을 지키지 못했고... 방어선에서도 또 저들을 적으로 삼아 쓰러트렸어...",
  ui_story_1018_10181501_54_dialog_content = "실패하고... 또 실패했어...",
  ui_story_1018_10181501_55_dialog_content = "대원수가 되고도... 난 결국 실패자야.",
  ui_story_1018_10181501_56_dialog_content = "레이스, 넌 실패한 적 없어. 모두를 이끌어 더스크 타운을 지키고, 방어선을 지킨 건 너야.",
  ui_story_1018_10181501_57_dialog_content = "비가 세지기 시작했어, 돌아가자.",
  ui_story_1018_10181501_58_dialog_content = "......",
  ui_story_1018_10181501_59_dialog_content = "돌아가자. 방송에서 오늘 날씨가 안 좋다고 했어. 아마 지상에는 지금 비가 내리고 있겠지.",
  ui_story_1018_10181501_60_dialog_content = "<color=#e8d9bb>후두두둑──</color>",
  ui_story_1018_10181501_61_dialog_content = "하하... 라인하르트...",
  ui_story_1018_10181501_62_dialog_content = "왜 웃어?",
  ui_story_1018_10181501_63_dialog_content = "대원수라는 건 언제나 이런 무력감에 사로잡혀야 하는 거야...?",
  ui_story_1018_10181501_64_dialog_content = "눈을 감으면, 마치 더스크 타운에서 희생된 병사들의 모습이 떠오르는 것 같아...",
  ui_story_1018_10181501_65_dialog_content = "저들은 자신이 암귀가 되어 동포들을 해치지 않도록, 자기 머리에 총탄을 쏘는 걸 선택했어...",
  ui_story_1018_10181501_66_dialog_content = "악셀리아의 몸은 이미 수없이 부서졌지만, 부하들을 구하기 위해 몇 번이고 일어섰지...",
  ui_story_1018_10181501_67_dialog_content = "그리고 마지막 일말의 의식만 남았지만 일루미나로 돌아오려던 아까 그 병사도...",
  ui_story_1018_10181501_68_dialog_content = "전쟁에서 이기기 위해 이렇게 큰 대가를 치러야만 하다니...",
  ui_story_1018_10181501_69_dialog_content = "넌 분명히 이런 경험을 몇 번이고 반복해 왔겠지...",
  ui_story_1018_10181501_70_dialog_content = "그런데도 오랜 시간 동안 대원수를 맡아 오면서, 넌 조금도 후회하는 기색을 보인 적이 없었어...",
  ui_story_1018_10181501_71_dialog_content = "심지어 악셀리아를 지키려고 전장에서 패배를 선언했고...",
  ui_story_1018_10181501_72_dialog_content = "일루미나의 미래를 위해, 감옥에 갇혀 자유를 빼앗기는 것도 받아들였어...",
  ui_story_1018_10181501_73_dialog_content = "...이런 건... 전부 라인하르트 너밖에 할 수 없는 일이야.",
  ui_story_1018_10181501_74_dialog_content = "......",
  ui_story_1018_10181501_75_dialog_content = "대원수란 만인을 향한 약속이고, 만인을 대변하는 입장이며, 만인을 가려주는 우산이야...\n죽어서도 안 되고, 오히려 끝없이 남을 애도해야 하는 사람이지.",
  ui_story_1018_10181501_76_dialog_content = "대원수는 바로 자신의 피와 살로 동포의 목숨을 지키는 자야.",
  ui_story_1018_10181501_77_dialog_content = "너는 나밖에 할 수 없다고 했지만... 하하, 그런 너도 일루미나의 안위를 위해 지금까지 버텼잖아.",
  ui_story_1018_10181501_78_dialog_content = "그런가...",
  ui_story_1018_10181501_79_dialog_content = "<color=#e8d9bb>비는 지상의 진흙을 씻어냈고, 먼 하늘에 떠 있는 구름 사이로는 희미한 빛이 비쳐왔다.</color>",
  ui_story_1018_10181501_80_dialog_content = "<color=#e8d9bb>레이스의 어깨는 가냘프면서도 굳셌고, 빛 속에 선 그 윤곽은 점점 더 뚜렷하고 당당하게 보였다.</color>",
  ui_story_1018_10181501_81_dialog_content = "그래도 역시 난... 이젠 대원수 같은 건 더는 하고 싶지 않아졌어...",
  ui_story_1018_10181501_82_dialog_content = "이 위기의 시간 동안 넌 나 대신 대원수의 중임을 짊어졌어.\n이제부터는 내가 이어서 책임을 다할 차례야.",
  ui_story_1018_10181501_83_dialog_content = "앞으로 닥칠 문제도 마찬가지로 쉽지 않을 거야.\n하지만 날 믿어 줘. 내가 모두를 위해, 내부의 적을 제거할 테니까.",
  ui_story_1018_10181501_84_dialog_content = "위원회를 어떻게 상대하려고?",
  ui_story_1018_10181501_85_dialog_content = "어이, 대원수, 군은 우리 손 안에 있잖냐. 네 말 한 마디면 내가 놈들의 소굴을 뒤집어 엎어 주마!",
  ui_story_1018_10181501_86_dialog_content = "내가 여기서 너희와 함께 싸울 수 있다는 건, 이미 위원회가 우리의 행동을 묵인하고 있다는 뜻이다.",
  ui_story_1018_10181501_87_dialog_content = "저들이 「계명성 프로젝트」 추진을 서두른 건 결코 더스크 타운만을 위해서가 아냐.",
  ui_story_1018_10181501_88_dialog_content = "어둠의 위기가 닥쳐오는 지금, 「가디언 1호」의 코어마저 빼앗긴 이상,\n이클립스의 행동이야말로 가장 까다로운 문제가 될 거다.",
  ui_story_1018_10181501_89_dialog_content = "자난성으로 돌아가면 또 순순히 감옥에 들어갈 건 아니지?",
  ui_story_1018_10181501_90_dialog_content = "병사들이 이런 일을 당한 이상, 율리시스는 심판을 면할 수 없어.",
  ui_story_1018_10181501_91_dialog_content = "어쨌든 벨리사리아는 체면을 지키는 사람이니까, 내 문제는 저들이 합당한 답을 줄 거야.",
  ui_story_1018_10181501_92_dialog_content = "대원수님, 이클립스 이야기가 나와서 말인데요. 이미 2개 부대가 어둠의 밑바닥으로 향했어요.",
  ui_story_1018_10181501_93_dialog_content = "위원회 쪽은 어쩔 생각일지 모르겠지만, 카론과 바이스 쪽 부대는 우리 지원이 필요할 거예요.",
  ui_story_1018_10181501_94_dialog_content = "맞아... 잠깐 만났을 때 얘기를 들었어. 지금 저들 상황은 확실히 낙관할 수 없을 거야...",
  ui_story_1018_10181501_95_dialog_content = "PlayerName, 넌 어떻게 할 계획이지?",
  ui_story_1018_10181501_96_dialog_content = "더스크 타운의 피난민들이 아직 헤븐즈 밸리에 있어요.\n전 우선 레오 씨랑 같이 가서 피난민들이 지낼 준비를 도와야겠어요.",
  ui_story_1018_10181501_97_dialog_content = "하지만 솔직히... 계속 바이스 쪽이 걱정됐어요...",
  ui_story_1018_10181501_98_dialog_content = "그들이 위험에 빠지게 두진 않을 거다, PlayerName. 내가 약속하지.",
  ui_story_1018_10181501_99_dialog_content = "위원회가 후속 문제를 어떻게 처리하든, 내가 그들의 행방을 최우선으로 찾아내겠다.",
  ui_story_1018_10181501_100_dialog_content = "그럼 더스크 타운 쪽은 나한테 맡겨 줘. 레오와는 오래 함께 싸웠고,\n일루미나도 더스크 타운에 제대로 된 답을 줘야 한다고 생각해.",
  ui_story_1018_10181501_101_dialog_content = "네... 대신 레이스 씨, 꼭 빨리 치료를 받으세요...",
  ui_story_1018_10181501_102_dialog_content = "알겠어, 정 곤란해지면 연락할 테니까.",
  ui_story_1018_10181501_103_dialog_content = "네... 제가 도울 수 있는 일은 얼마든지 도울게요.",
  ui_story_1018_10181501_104_dialog_content = "<color=#e8d9bb>치지지직──</color>",
  ui_story_1018_10181501_105_dialog_content = "어처구니없는 촌극... 아니지, 희극이로군요.\n그리고 우리 극작가 율리시스는 볼 낯이 없는지 오늘 회의에 안 나오셨네요.",
  ui_story_1018_10181501_106_dialog_content = "어떻게 수습할 생각입니까?",
  ui_story_1018_10181501_107_dialog_content = "아직 수습할 때가 아니야.",
  ui_story_1018_10181501_108_dialog_content = "농담이죠? 두 일루미나 대원수가 군대를 이끌고 방어선에서 승전을 거뒀다고요.",
  ui_story_1018_10181501_109_dialog_content = "저들이 저자세로 당신과 평화 협상이라도 하길 바라고 있는 건가요?",
  ui_story_1018_10181501_110_dialog_content = "라인하르트가 일루미나의 감옥을 나간 걸 내가 몰랐을 것 같아?",
  ui_story_1018_10181501_111_dialog_content = "지금은 아직 핵심 증거를 내밀 때가 아냐.\n앞으로의 상황이 어떻게 전개될지는 저들의 태도에 달려 있어.",
  ui_story_1018_10181501_112_dialog_content = "역시 당신답네요. 무슨 일이든 퇴로를 준비해 두고 말이에요.",
  ui_story_1018_10181501_113_dialog_content = "하지만 온 아스트라 대륙이 방어선에서의 싸움을 지켜봤어요.",
  ui_story_1018_10181501_114_dialog_content = "그래, 모두가 봤지. 기왕이면 아주 자세히 봐 뒀길 바라는 중이야.",
  ui_story_1018_10181501_115_dialog_content = "어둠의 위기가 정말로 찾아온다면, 각 진영은 과연 어디까지 싸울 수 있을까?",
  ui_story_1018_10181501_116_dialog_content = "...율리시스의 계획을 지지한 건 백야성을 끌어내기 위해서였습니까?",
  ui_story_1018_10181501_117_dialog_content = "이유 중 하나일 뿐이야.",
  ui_story_1018_10181501_118_dialog_content = "더스크 타운이든 방어선이든 너희도 봤겠지. 우린 암귀에 대해 여전히 억지력을 가지고 있어.",
  ui_story_1018_10181501_119_dialog_content = "게다가 저들도 비장의 카드 하나를 꺼냈고 말이야.",
  ui_story_1018_10181501_120_dialog_content = "그 여자애 말인가요?",
  ui_story_1018_10181501_121_dialog_content = "맞아, 하지만 분명히 그게 전부는 아니겠지.",
  ui_story_1018_10181501_122_dialog_content = "설마 이게 바로 당신이 보고 싶었던 진짜 「연합 훈련」입니까?",
  ui_story_1018_10181501_123_dialog_content = "다른 건 몰라도 대가가 너무 컸어요. 후폭풍은 생각해 봤나요?",
  ui_story_1018_10181501_124_dialog_content = "누구든 더 좋은 방법이 있으면 얼마든지 말해 봐.",
  ui_story_1018_10181501_125_dialog_content = "이번에 이클립스가 사용한 무기는 여전히 노라의 「씨앗」이야.\n적어도 현 단계에서는 우리도 가지고 있고.",
  ui_story_1018_10181501_126_dialog_content = "그게 바로 내가 율리시스를 지지했던 이유야.",
  ui_story_1018_10181501_127_dialog_content = "앞으로도 우릴 파멸시킬 가능성이 있는 그 어떤 무기든지, 반드시 우리 손에 쥐어야만 해.",
  ui_story_1018_10181501_128_dialog_content = "백야성의 것이든, 북방의 것이든, 심지어 이단 교단의 것이든 말이야.",
  ui_story_1018_10181501_129_dialog_content = "「가디언 1호」의 핵심을 빼앗긴 마당에, 지금 각 세력 간의 균형을 가장 걱정하시는 겁니까?",
  ui_story_1018_10181501_130_dialog_content = "우선순위는 없어. 앞뒤로 적의 공격을 받고 있는 게 일루미나의 지금 처지니까.",
  ui_story_1018_10181501_131_dialog_content = "당시 일루미나에서 쫓겨난 「엔지니어」를 지탄한 건 백야성뿐만이 아니었어.",
  ui_story_1018_10181501_132_dialog_content = "이렇게 된 이상, 차라리 생각을 바꿔 보는 것도 좋을 것 같아.\n모두에게 「엔지니어」가 어떤 존재인지 보여 주는 거지.",
  ui_story_1018_10181501_133_dialog_content = "자신 있습니까?",
  ui_story_1018_10181501_134_dialog_content = "이미 「어둠의 밑바닥 정찰대」에서 소식이 들어왔어. 예상했던 대로야.",
  ui_story_1018_10181501_135_dialog_content = "「가디언 1호」의 코어는 「엔지니어」 소생 계획의 마지막 퍼즐이었어.",
  ui_story_1018_10181501_136_dialog_content = "방어선에서의 싸움이 끝난 이상, 「엔지니어」도 곧 깨어날 거야.",
  ui_story_1018_10181501_137_dialog_content = "......",
  ui_story_1018_10181501_138_dialog_content = "「엔지니어」라... 자난성 건설 이래로 진정한 의미에서의 첫 「성주」 아닙니까.",
  ui_story_1018_10181501_139_dialog_content = "그런 오래된 존재가 만약 정말로 깨어난다면, 그건 오히려 조금 기대가 되네요.",
  ui_story_1018_10181501_140_dialog_content = "훗, 나도 마찬가지야.",
  ui_story_1018_10181501_141_dialog_content = "치지직──",
  ui_story_1018_10181501_142_dialog_content = "신호가... 또...",
  ui_story_1018_10181501_143_dialog_content = "제가... 아닌...",
  ui_story_1018_10181501_144_dialog_content = "아무래도... 「엔지...",
  ui_story_1018_10181501_145_dialog_content = "...이미 깨어난 모양이네...",
  ui_story_1019_10190101_1_dialog_content = "<color=#e8d9bb>위이잉──</color>",
  ui_story_1019_10190101_2_dialog_content = "역시, 씨앗은 능력을 강화하는 게 아니라 바꿔 버리는군...",
  ui_story_1019_10190101_3_dialog_content = "씨앗의 핵심 메커니즘을 복제했는데도 늪에서 여전히 다크매터에 침식당한 것도 그래서였나...",
  ui_story_1019_10190101_4_dialog_content = "하하... 대체 어떻게 이런 생각을 한 거냐...",
  ui_story_1019_10190101_5_dialog_content = "쿨럭, 쿨럭쿨럭... 쿨럭, 쿨럭쿨럭...",
  ui_story_1019_10190101_6_dialog_content = "이 근처에 놓아뒀을 텐데...",
  ui_story_1019_10190101_7_dialog_content = "...뭐, 이 결론을 도출할 수 있었으니, 더스크 타운에서 죽은 실험체들도 가치는 있었군.",
  ui_story_1019_10190101_8_dialog_content = "<color=#e8d9bb>달그락──</color>",
  ui_story_1019_10190101_9_dialog_content = "마지막 세 알인가...",
  ui_story_1019_10190101_10_dialog_content = "연구에 힘쓴 지 40년, <color=#FFB400>특수 유전자형 라이브러리</color> 준비에 약 20년...\n내가 할 수 있는 건 다 했군.",
  ui_story_1019_10190101_11_dialog_content = "하지만 왜 아직도 마음이 편치 않단 말인가...",
  ui_story_1019_10190101_12_dialog_content = "정말 이게 최선이란 말이냐, <color=#FFB400>라빌</color>...",
  ui_story_1019_10190101_13_dialog_content = "<color=#e8d9bb>휘이잉── 휘이잉──</color>",
  ui_story_1019_10190101_14_dialog_content = "바, 바람이 엄청 세네...",
  ui_story_1019_10190101_15_dialog_content = "잠깐만... 나 왜 구름 위에 있지?",
  ui_story_1019_10190101_16_dialog_content = "이 익숙한 무중력 상태... 나 또 추락 중인 건 아니지...?!",
  ui_story_1019_10190101_17_dialog_content = "침착하자! 침착해! 스카이워커호가 날 받아 줄 거야...!",
  ui_story_1019_10190101_18_dialog_content = "조종사, 저를 불렀습니까?",
  ui_story_1019_10190101_19_dialog_content = "오늘 비행 스타일, 꼭 저번에 나 속이 다 뒤집힌 그때랑 비슷한 것 같네.\n그래서 우리 지금 어디 가는 거야?",
  ui_story_1019_10190101_20_dialog_content = "우리는 공중 투하 임무를 수행하기 위해 <color=#FFB400>탑의 전장</color>으로 이동 중입니다.",
  ui_story_1019_10190101_21_dialog_content = "...임무라니? 갑자기 무슨 임무?",
  ui_story_1019_10190101_22_dialog_content = "조종사를 위해 작전 명령을 재생하겠습니다.",
  ui_story_1019_10190101_23_dialog_content = "「모든 조종사는 탑의 전장으로 항해 무기를 투하하라.」",
  ui_story_1019_10190101_24_dialog_content = "고도가 완충 구역에 도달했습니다. 무기를 안전히 투하하기 위해 명령을 내려 주십시오.",
  ui_story_1019_10190101_25_dialog_content = "자, 잠깐만! 지금 무슨 소리 하는 거야?!",
  ui_story_1019_10190101_26_dialog_content = "스카이워커? 스카이워커──!",
  ui_story_1019_10190101_27_dialog_content = "으아아아──!",
  ui_story_1019_10190101_28_dialog_content = "크오오오오오!",
  ui_story_1019_10190101_29_dialog_content = "이 암귀들은 또 뭐야?! 내가 왜... 암귀들이랑 같이 추락하고 있냐고!",
  ui_story_1019_10190101_30_dialog_content = "스카이워커! 이게 대체 어떻게 된 거야?!",
  ui_story_1019_10190101_31_dialog_content = "조종사, 무기가 확실히 투하될 수 있는지 확인 바랍니다.\n이 임무는 아이테르 일족인 당신의 사명입니다.",
  ui_story_1019_10190101_32_dialog_content = "크오오오오오!",
  ui_story_1019_10190101_33_dialog_content = "아니야... 이, 이건 꿈인 게 분명해!",
  ui_story_1019_10190101_34_dialog_content = "꿈이 아닙니다, 조종사.",
  ui_story_1019_10190101_35_dialog_content = "현재 좌표는 탑의 전장임이 확인되었습니다. 무기의 안전한 투하 가능 여부를 확인하십시오.",
  ui_story_1019_10190101_36_dialog_content = "탑...? 여긴 헤븐즈 밸리잖아! 저기 커다란 게 귀환의 탑인 것도 보면 알겠는데?!",
  ui_story_1019_10190101_37_dialog_content = "땅 위에서 사방으로 도망치고 있는 건... 아이테르인가? 아니면...",
  ui_story_1019_10190101_38_dialog_content = "...꿈이야! 이건 꿈이라고! 땅에 추락해 버리면 잠에서 깰 수 있을지도 몰라...",
  ui_story_1019_10190101_39_dialog_content = "...에라 모르겠다!",
  ui_story_1019_10190101_40_dialog_content = "......",
  ui_story_1019_10190101_41_dialog_content = "...아직도 공중에 떠 있네...?",
  ui_story_1019_10190101_42_dialog_content = "(마음속으로 추락을 담담히 받아들인 순간,\n땅으로 떨어지는 과정은 더없이 길게 느껴졌다...)",
  ui_story_1019_10190101_43_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_1019_10190101_44_dialog_content = "으아아악──!",
  ui_story_1019_10190101_45_dialog_content = "......",
  ui_story_1019_10190101_46_dialog_content = "일어났어?",
  ui_story_1019_10190101_47_dialog_content = "만물은 백야 아래에, 우리 모두 무사히 도착했어요.",
  ui_story_1019_10190101_48_dialog_content = "레오 씨... 조셀린? 여, 여긴...",
  ui_story_1019_10190101_49_dialog_content = "이미 헤븐즈 밸리에 돌아왔어요.",
  ui_story_1019_10190101_50_dialog_content = "전사들이 제대로 서 있지도 못할 정도로 비공정이 흔들리는데,\n넌 누가 업어가도 모르게 자더라고...",
  ui_story_1019_10190101_51_dialog_content = "헤븐즈 밸리...",
  ui_story_1019_10190101_52_dialog_content = "맞네... 그래... 헤븐즈 밸리야...",
  ui_story_1019_10190101_53_dialog_content = "더스크 타운이랑 일루미나 방어선에서 전투가 있었고,\n우린 백야성의 비공정을 타고 헤븐즈 밸리로 돌아왔었지...",
  ui_story_1019_10190101_54_dialog_content = "그래, 다 꿈이었던 거야. 다행이다... 정말 다행이야!",
  ui_story_1019_10190101_55_dialog_content = "뭘 그리 뛰어다니고 있어? 정말 괜찮은 거 맞아?",
  ui_story_1019_10190101_56_dialog_content = "괜찮아... 정말 다행이야, 레오 씨!",
  ui_story_1019_10190101_57_dialog_content = "무중력 상태가 너무 진짜 같아서... 예전에 진짜 있었던 일이란 착각이 들 정도였어...",
  ui_story_1019_10190101_58_dialog_content = "다행히 꿈이었어... 꿈이었다고!",
  ui_story_1019_10190101_59_dialog_content = "...그렇다고 날 이렇게 세게 끌어안을 필요는 없지 않나 싶은데.",
  ui_story_1019_10190101_60_dialog_content = "<color=#e8d9bb>와락──</color>",
  ui_story_1019_10190101_61_dialog_content = "PlayerName, 내 신발이 깨끗하진 않지만,\n그렇다고 밟고 올라오진 말아 줬으면 좋겠어.",
  ui_story_1019_10190101_62_dialog_content = "아, 미안... 근데 나 안 밟았는데...",
  ui_story_1019_10190101_63_dialog_content = "츄츄... 츄츄...",
  ui_story_1019_10190101_64_dialog_content = "이 네모난 건 뭐지...? 왜 내 부츠를 끌어안고 있는 거야?",
  ui_story_1019_10190101_65_dialog_content = "얘는 헤븐즈 밸리에 사는 내 동료 츄브라고 해. 근데 왜 취한 것처럼 보이지...?",
  ui_story_1019_10190101_66_dialog_content = "츄츄... 딸꾹──",
  ui_story_1019_10190101_67_dialog_content = "어머! 레오 단장님! 성녀님! 아이테르 군!",
  ui_story_1019_10190101_68_dialog_content = "드디어 돌아오셨군요!",
  ui_story_1019_10190101_69_dialog_content = "남자들은 여러분이 더스크 타운에서 암귀를 몰아냈단 얘기를 듣더니,\n곧바로 돌아갈 준비를 하더라고요!",
  ui_story_1019_10190101_70_dialog_content = "그래서 저랑 양조장 아줌마들끼리 얘기해서, 병사들 대접할 음식이랑 과일주를 준비했어요!",
  ui_story_1019_10190101_71_dialog_content = "발효 기간이 짧긴 해도, 헤븐즈 밸리의 과일로 담근 술은 특별한 맛이 나던걸요.",
  ui_story_1019_10190101_72_dialog_content = "츄브가 과일주를 마셨던 거군요...",
  ui_story_1019_10190101_73_dialog_content = "아이테르 군, 레이스 대원수님은 괜찮으신가요? 대원수님은 같이 안 오셨어요?",
  ui_story_1019_10190101_74_dialog_content = "건강에 큰 문제는 없으신데, 그래도 일루미나로 돌아가 치료를 받으셔야 해서요.",
  ui_story_1019_10190101_75_dialog_content = "그렇군요... 그래도 큰 문제는 없다니 다행이네요!\n더스크 타운을 지켜 주신 전사분들을 언젠가 꼭 직접 만나 감사 인사를 드리고 싶어요.",
  ui_story_1019_10190101_76_dialog_content = "참, 아이테르 군, 우릴 받아 줘서 고마워요!",
  ui_story_1019_10190101_77_dialog_content = "여기선 할 일이 별로 없으니까, 다들 물고기 먹이나 주고, 술이나 담그고,\n나무에 있는 벌레나 잡고 있어요...",
  ui_story_1019_10190101_78_dialog_content = "전 매일매일 방 청소를 했어요.\n나무 끝에 걸어 논 건 아이테르 형이랑 기사 형들의 승리를 축하하는 깃발이에요...",
  ui_story_1019_10190101_79_dialog_content = "이렇게 많은 일들을 해 주실 줄이야...",
  ui_story_1019_10190101_80_dialog_content = "헤븐즈 밸리에 우릴 받아 준 게 고마워서 한 일들이니까 마음 편히 생각해 줘요!",
  ui_story_1019_10190101_81_dialog_content = "오히려 제가 더 감사하죠! 헤븐즈 밸리가 이렇게 활기찬 적은 처음이었거든요...",
  ui_story_1019_10190101_82_dialog_content = "여러분만 괜찮으시다면, 계속 헤븐즈 밸리에서 지내셔도 돼요...",
  ui_story_1019_10190101_83_dialog_content = "그렇다면 이제부터 더스크 타운에서 맛 좋은 술이 많이 사라지겠군.",
  ui_story_1019_10190101_84_dialog_content = "만물은 백야 아래에,\nPlayerName 씨, 당신이 더스크 타운을 해 준 모든 것들에 감사드려요.",
  ui_story_1019_10190101_85_dialog_content = "츄츄! 츄... 딸꾹── 딸꾹──",
  ui_story_1019_10190101_86_dialog_content = "<color=#e8d9bb>건배!</color>",
  ui_story_1019_10190101_87_dialog_content = "하하하, 백야성으로 향하는 여정에 그렇게 우여곡절이 많았을 줄이야.\n고군분투하느라 고생 많았어, 참모장.",
  ui_story_1019_10190101_88_dialog_content = "더스크 타운에 비하면 별거 아니었습니다.\n결과만 좋다면, 제가 한 모든 일은 그만한 가치가 있었던 거겠죠.",
  ui_story_1019_10190101_89_dialog_content = "역시 내가 높이 사는 사람답다니까. 자, 마시자고!",
  ui_story_1019_10190101_90_dialog_content = "......",
  ui_story_1019_10190101_91_dialog_content = "왜 그러지? 큰 전투를 치른 후인데, 술은 입에 대지 않는 건가?",
  ui_story_1019_10190101_92_dialog_content = "몸 상태 때문에 제겐 그림의 떡이네요. 대신 여러분이 실컷 마셔 주세요.\n뭐, 그래도 이런 광경을 보는 건 정말 몇 년 만이군요.",
  ui_story_1019_10190101_93_dialog_content = "그러게, 나도 마찬가지야.",
  ui_story_1019_10190101_94_dialog_content = "모두의 심정은 충분히 이해돼. 다들 하하 웃으며 기뻐하고 있지만,\n속으론 여전히 더스크 타운을 걱정하고 있겠지.",
  ui_story_1019_10190101_95_dialog_content = "고민이 없어 보이는 저 네모난 녀석들 외에는 다들 마음이 무거워 보이는군요.",
  ui_story_1019_10190101_96_dialog_content = "그래서 난 내일 바로 돌아가기로 결정했어.",
  ui_story_1019_10190101_97_dialog_content = "전사는 화약 냄새를 맡지 않으면 잠을 제대로 못 자거든.\n그러니 이 술들을 다 마시고 나면, 다음 전투를 준비할 차례야.",
  ui_story_1019_10190101_98_dialog_content = "<color=#e8d9bb>즐거운 노랫소리와 웃음소리는 깊은 밤까지 계속되었다...</color>",
  ui_story_1019_10190101_99_dialog_content = "<color=#e8d9bb>삑──</color>",
  ui_story_1019_10190101_100_dialog_content = "음? 너였군. 헤븐즈 밸리 쪽은 잘 돼가나?",
  ui_story_1019_10190101_101_dialog_content = "네, 꽤 괜찮아요...",
  ui_story_1019_10190101_102_dialog_content = "이렇게 늦은 시간에 연락해 온 건, 바이스가 어떤 상황인지 묻기 위해선가?",
  ui_story_1019_10190101_103_dialog_content = "네... 바이스랑 카론 씨 쪽 소식은 새로 들어온 게 있나요?",
  ui_story_1019_10190101_104_dialog_content = "있다. 하지만 상황에 대해 확답을 줄 정도는 아니군.",
  ui_story_1019_10190101_105_dialog_content = "네? 정말 소식이 있었어요?!",
  ui_story_1019_10190101_106_dialog_content = "카론이 이끄는 추적 소대는 전진 중이라는 신호를 지속해서 보내오고 있다.\n일루미나의 정찰 임무를 수행할 때 이는 순조롭게 진행되고 있음을 의미하지.",
  ui_story_1019_10190101_107_dialog_content = "...하지만 특수한 상황에 처한 거라면요? 예를 들면 더스크 타운처럼...",
  ui_story_1019_10190101_108_dialog_content = "알고 있다. 그래서 더 자세히 사실 확인을 진행 중이다.\n소식이 들어오면 네게 연락할 테니, 안심해라.",
  ui_story_1019_10190101_109_dialog_content = "그럼 지금 제가 뭘 할 수 있을까요?\n더스크 타운의 전투에도 참여했었으니까, 뭔가 도움이 될지도 모르잖아요.",
  ui_story_1019_10190101_110_dialog_content = "아무것도 하지 않아도 된다, PlayerName.",
  ui_story_1019_10190101_111_dialog_content = "그렇지만...",
  ui_story_1019_10190101_112_dialog_content = "호의는 고맙게 받도록 하지. 하지만 지금은 일루미나에 올 때가 아니다.",
  ui_story_1019_10190101_113_dialog_content = "「가디언 1호」의 코어를 도난당한 후, 자난성의 방어에 몇 가지 문제가 생겼다.\n지금 모두 최선을 다해 대응 중이지.",
  ui_story_1019_10190101_114_dialog_content = "네가 더스크 타운에서 보여 준 용기와 친절은 우리 일루미나에 이미 큰 힘이 되었다.",
  ui_story_1019_10190101_115_dialog_content = "나머지 일은 내게 맡겨라. 시간도 늦었으니 일찍 쉬도록.",
  ui_story_1019_10190101_116_dialog_content = "네...",
  ui_story_1019_10190101_117_dialog_content = "......",
  ui_story_1019_10190101_118_dialog_content = "PlayerName, 바이스의 안전이 걱정돼 잠이 안 오는 모양이군요.",
  ui_story_1019_10190101_119_dialog_content = "응...",
  ui_story_1019_10190101_120_dialog_content = "<color=#e8d9bb>나는 침착하게 20초를 세고, 심장이 몇 번이나 뛰었는지 헤아려 보았다.</color>",
  ui_story_1019_10190101_121_dialog_content = "스카이워커...",
  ui_story_1019_10190101_122_dialog_content = "스카이워커호는 늘 당신 곁에 있습니다.",
  ui_story_1019_10190101_123_dialog_content = "20초 명상법이 정말 효과가 있나 봐. 즐거운 기억들이 생각났어.",
  ui_story_1019_10190101_124_dialog_content = "......",
  ui_story_1019_10190101_125_dialog_content = "PlayerName, 당신이 즐거워할 때의 이미지 데이터를 가져왔습니다.\n당신은 어렸을 때, 기쁘면 물구나무서기를 했습니다.",
  ui_story_1019_10190101_126_dialog_content = "물구나무서기를 했다고?!",
  ui_story_1019_10190101_127_dialog_content = "게다가 PlayerName 당신은 제게도 어떻게 해서든지 물구나무서기를\n보여 달라는 요청을 했었습니다.",
  ui_story_1019_10190101_128_dialog_content = "음... 지금은 너나 나나 물구나무를 서긴 힘들 거야.",
  ui_story_1019_10190101_129_dialog_content = "계산에 따르면 스카이워커호의 물구나무서기 성공률은 59%입니다.\n실행을 원할 경우, 우선 안전한 장소로 이동해 주십시오.",
  ui_story_1019_10190101_130_dialog_content = "아? 하하, 고마워, 스카이워커. 근데... 지금 이대로도 괜찮을 거 같아.",
  ui_story_1019_10190101_131_dialog_content = "지금처럼 걱정이나 고민도, 딱히 하는 일도 없이 컨트롤러만 보는 시간도\n참 오랜만이니까...",
  ui_story_1019_10190101_132_dialog_content = "제 의식 모듈이 손상된 후 당신은 많은 일을 했더군요.",
  ui_story_1019_10190101_133_dialog_content = "응. 넌 아직 무슨 일이 있었는지 잘 모를 수도 있겠네. 그럼 차근차근 되돌아보자...",
  ui_story_1019_10190101_134_dialog_content = "일단 네 의식 모듈이 손상되고 나서, 우린 네가 남겨 둔 좌표 정보에 따라\n지하성에서 열쇠를 하나 발견했어...",
  ui_story_1019_10190101_135_dialog_content = "그리고 좌표의 인도에 따라 우린 헤븐즈 밸리에 도착했어.",
  ui_story_1019_10190101_136_dialog_content = "난 처음으로 밟아 보는 고향 땅이었는데... 아이테르들은 고향에서 사라진 지 오래였지.",
  ui_story_1019_10190101_137_dialog_content = "아, 그리고 그때 하마터면 우리의 가장 소중한 친구를 잃을 뻔했었어...",
  ui_story_1019_10190101_138_dialog_content = "그다음엔 과거의 아이테르와 콜로서스들이 함께 이 대륙을 떠났다가\n아주 긴 시간 뒤에 다시 돌아오는 걸 봤고.",
  ui_story_1019_10190101_139_dialog_content = "그 모습은 지금 생각해 봐도 마치 긴 꿈을 꾼 듯한 느낌이었어.\n과거의 아이테르들과 콜로서스들은 어떻게 됐을까...?",
  ui_story_1019_10190101_140_dialog_content = "그리고 넌 날 구하려고 고대 전장에 갇혀 버리고 말았어...",
  ui_story_1019_10190101_141_dialog_content = "다행히 우리가 「패스파인더호」의 의식 데이터를 찾아내서 널 깨울 수 있게 된 거야.",
  ui_story_1019_10190101_142_dialog_content = "......",
  ui_story_1019_10190101_143_dialog_content = "수리 일지를 여러 번 확인해 보았습니다만,\n역시 PlayerName에게 직접 듣는 게 낫군요.",
  ui_story_1019_10190101_144_dialog_content = "다 알고 있었구나... 그럼 괜히 얘기했네...",
  ui_story_1019_10190101_145_dialog_content = "그로누 연구원장이 일련의 상황을 스카이워커호의 수리 일지에 자세히 기록해 두었습니다.",
  ui_story_1019_10190101_146_dialog_content = "혹시 연합 훈련에 아이테르 일족을 대표해 참가했던 경험에 대해\n이야기해 주실 수 있겠습니까?",
  ui_story_1019_10190101_147_dialog_content = "아, 그래. 그때 무슨 일이 있었냐면...",
  ui_story_1019_10190201_1_dialog_content = "<color=#e8d9bb>며칠 뒤 새벽, 일루미나 메디컬 센터</color>",
  ui_story_1019_10190201_2_dialog_content = "이것들을... 전부 다 내가 쓰러트린 건가...",
  ui_story_1019_10190201_3_dialog_content = "미, 미안하군... 찬드라 선생, 여전히 자신을 통제할 수가 없었다...",
  ui_story_1019_10190201_4_dialog_content = "미안해할 필요 없어요, 헬리오스 대위!",
  ui_story_1019_10190201_5_dialog_content = "적당한 전투 훈련은 그 자체로도 심리 치료의 일부인 데다가,\n감정 발산에도 도움이 되거든요.",
  ui_story_1019_10190201_6_dialog_content = "내가 지금 이 상태로 일루미나에 무슨 공헌을 할 수 있을지 정말 모르겠군...",
  ui_story_1019_10190201_7_dialog_content = "그런 생각 말아요, 헬리오스 대위.",
  ui_story_1019_10190201_8_dialog_content = "당신의 기억에 등장했던 여러 곳 중, 어둠의 밑바닥에 관한 기억들은\n일루미나에서 특히 중요하게 여기는 정보들이니까요.",
  ui_story_1019_10190201_9_dialog_content = "그리고 지금까지 겪은 일들과 사람들에 대한 기억 같은 경우는...",
  ui_story_1019_10190201_10_dialog_content = "사람의 대뇌는 타인과 교류할 때 감각 기관과 감정 처리 영역을 사용해요.",
  ui_story_1019_10190201_11_dialog_content = "그러니까 당신이 감정을 더 잘 통제할 수 있게 되면,\n그 부분의 기능들도 서서히 회복될 거예요.",
  ui_story_1019_10190201_12_dialog_content = "그런 건가... 그렇다면 나도 더 많이 노력해야겠군.",
  ui_story_1019_10190201_13_dialog_content = "음, 망가진 모형들은 내가 고쳐 두겠다... 앞으론 나도 모형 제작을 돕도록 하지.",
  ui_story_1019_10190201_14_dialog_content = "아, 그리고! 늦은 시간에 잠을 깨워 정말 미안하군...",
  ui_story_1019_10190201_15_dialog_content = "괜찮아요, 헬리오스 대위. 이게 제 일인 걸요... 하암~",
  ui_story_1019_10190201_16_dialog_content = "헤헷, 그럼 오늘은 여기까지 해요.",
  ui_story_1019_10190201_17_dialog_content = "앞으로도 뭔가 기억나는 게 있다거나, 꿈에서 뭔가 보게 되면 수시로 기록해 주세요.",
  ui_story_1019_10190201_18_dialog_content = "대원수님께서 그 기록들로 뭘 하시려는 건진 모르겠지만,\n굉장히 중요하게 생각하시는 거 같았거든요.",
  ui_story_1019_10190201_19_dialog_content = "갑자기 올라오는 감정들과 불현듯 떠오르는 광경들을 얕보면 안 돼요.",
  ui_story_1019_10190201_20_dialog_content = "그 자그마한 불씨들 아래엔 아주 오래전부터 타오르던 장작 더미가 있기 마련이거든요.",
  ui_story_1019_10190201_21_dialog_content = "그래. 그 어둡고 추운 세계 속 모든 사소한 기억들조차 난 영원히 잊지 못할 거다.",
  ui_story_1019_10190201_22_dialog_content = "다시 한번 감사하네, 찬드라 선생.",
  ui_story_1019_10190201_23_dialog_content = "<color=#e8d9bb>삑──</color>",
  ui_story_1019_10190201_24_dialog_content = "어라? 이 새벽에 누가 메시지를 보냈지...?",
  ui_story_1019_10190201_25_dialog_content = "<color=#e8d9bb>휘이잉── 휘이──</color>",
  ui_story_1019_10190201_26_dialog_content = "『1011X.』",
  ui_story_1019_10190201_27_dialog_content = "『네. 마지막 <color=#FFB400>구동 링</color>은 이미 손에 넣었습니다.』",
  ui_story_1019_10190201_28_dialog_content = "『01X11.』",
  ui_story_1019_10190201_29_dialog_content = "『고귀하신 당신의 이름을 읊나니, 부디 지켜봐 주시옵소서──』",
  ui_story_1019_10190201_30_dialog_content = "『저희는 당신의 강림을 기다리나이다──』",
  ui_story_1019_10190201_31_dialog_content = "<color=#e8d9bb>삑──</color>",
  ui_story_1019_10190201_32_dialog_content = "여긴...?",
  ui_story_1019_10190201_33_dialog_content = "이 검은 그림자들은 누구지...?",
  ui_story_1019_10190201_34_dialog_content = "보면 안 돼! PlayerName!",
  ui_story_1019_10190201_35_dialog_content = "잠깐만... 바이스 너야?",
  ui_story_1019_10190201_36_dialog_content = "너구나! 바이스, 진짜 너였어!",
  ui_story_1019_10190201_37_dialog_content = "집으로 돌아와.",
  ui_story_1019_10190201_38_dialog_content = "길을 잃은 거야? 바이스! 거기 지금 엄청 위험한 상황인 거지?",
  ui_story_1019_10190201_39_dialog_content = "얼른 네가 어디 있는지 알려 줘. 내가 데리러 갈게.",
  ui_story_1019_10190201_40_dialog_content = "집으로 돌아와.",
  ui_story_1019_10190201_41_dialog_content = "......",
  ui_story_1019_10190201_42_dialog_content = "돌아가라니? 바이스?",
  ui_story_1019_10190201_43_dialog_content = "(돌아와라.)",
  ui_story_1019_10190201_44_dialog_content = "집? 여긴 어디지...?",
  ui_story_1019_10190201_45_dialog_content = "(집으로 돌아와라.)",
  ui_story_1019_10190201_46_dialog_content = "넌 누구야? 바이스는?",
  ui_story_1019_10190201_47_dialog_content = "<color=#e8d9bb>삑──</color>",
  ui_story_1019_10190201_48_dialog_content = "PlayerName, 여긴 위험해!",
  ui_story_1019_10190201_49_dialog_content = "바이스! 너 대체 어디 있는 거야?!",
  ui_story_1019_10190201_50_dialog_content = "<color=#e8d9bb>삐익── 삐익── 삐익──</color>",
  ui_story_1019_10190201_51_dialog_content = "바이스... 바이스!",
  ui_story_1019_10190201_52_dialog_content = "PlayerName, 또 악몽을 꿨습니까?",
  ui_story_1019_10190201_53_dialog_content = "꿈...",
  ui_story_1019_10190201_54_dialog_content = "또 꿈인가...",
  ui_story_1019_10190201_55_dialog_content = "스카이워커, 아무래도 뭔가 이상해...\n헤븐즈 밸리에서 돌아오고 나서부터 자꾸 이상한 꿈을 꿔...",
  ui_story_1019_10190201_56_dialog_content = "느낌은 꿈이 아니라 뭔가에 감응한 거랑 더 비슷한데...\n나도 어떻게 표현해야 할지 모르겠어.",
  ui_story_1019_10190201_57_dialog_content = "PlayerName의 지나친 관심으로 인한 현상일지도 모릅니다.\n며칠 밤마다 이곳에서 소식을 기다리지 않았습니까. 이제 방으로 돌아가 쉬어야 합니다.",
  ui_story_1019_10190201_58_dialog_content = "지금 몇 시야?",
  ui_story_1019_10190201_59_dialog_content = "세 시간 후면 일출을 볼 수 있을 겁니다.",
  ui_story_1019_10190201_60_dialog_content = "또 하루가 지났네...",
  ui_story_1019_10190201_61_dialog_content = "아무것도 못 하고 그냥 기다릴 수밖에 없는 건 정말 끔찍한 기분이야...",
  ui_story_1019_10190201_62_dialog_content = "<color=#e8d9bb>삑──</color>",
  ui_story_1019_10190201_63_dialog_content = "이 소리 기억나... 또 「패스파인더호」의 데이터에서 오래전의 좌표 신호가 탐지된 거지?",
  ui_story_1019_10190201_64_dialog_content = "네가... 「과거에서 온 메아리」라고 표현했던 거 말이야.",
  ui_story_1019_10190201_65_dialog_content = "맞습니다.",
  ui_story_1019_10190201_66_dialog_content = "「패스파인더호」는 침묵에 빠지기 전까지 여러 번 이 좌표 신호들을 송출했습니다만,\n현재 이 대륙에서 이에 대응하는 위치는 발견되지 않았습니다.",
  ui_story_1019_10190201_67_dialog_content = "환경이 달라져서 그런가?",
  ui_story_1019_10190201_68_dialog_content = "시간의 변화 때문이기도 합니다.",
  ui_story_1019_10190201_69_dialog_content = "근데도 넌 탐지를 계속하고 있었구나...",
  ui_story_1019_10190201_70_dialog_content = "모든 데이터를 열람할 수 있다면, 제 의식을 예전과 동일하게 회복할 수 있을 것입니다.",
  ui_story_1019_10190201_71_dialog_content = "있잖아, 사실 넌 지금도 내가 알던 그 스카이워커야.",
  ui_story_1019_10190201_72_dialog_content = "PlayerName 당신과 제 의식 일치율은 복구 전 대비 90%에 불과합니다.",
  ui_story_1019_10190201_73_dialog_content = "그랬구나... 근데 난 별 차이를 못 느끼겠던데.",
  ui_story_1019_10190201_74_dialog_content = "계속 학습해 나가겠습니다.",
  ui_story_1019_10190201_75_dialog_content = "참, 물어보고 싶은 게 하나 있어...",
  ui_story_1019_10190201_76_dialog_content = "라인하르트 씨가 일루미나 쪽 일에 관여하지 말라고 하긴 했는데,\n아무래도 너무 걱정돼서...",
  ui_story_1019_10190201_77_dialog_content = "헤븐즈 밸리가 조용할수록 마음도 조급해지고,\n그때 느꼈던 바이스의 심장 소리 생각이 나...",
  ui_story_1019_10190201_78_dialog_content = "바이스는 나한테 뭔가 알려 주려고 했던 게 분명해. 근데 내가 그걸 놓치고 있는 거고...",
  ui_story_1019_10190201_79_dialog_content = "그래서 제게 묻고 싶은 것은 무엇입니까? PlayerName.",
  ui_story_1019_10190201_80_dialog_content = "아니야, 결정했어! 라인하르트 씨는 일루미나에 오지 말라고 했지만, 난...",
  ui_story_1019_10190201_81_dialog_content = "<color=#e8d9bb>삑──</color>",
  ui_story_1019_10190201_82_dialog_content = "...어? 이 사람이 왜...",
  ui_story_1019_10190201_83_dialog_content = "당신이 기대하던 소식입니까?",
  ui_story_1019_10190201_84_dialog_content = "응! 이거 봐!",
  ui_story_1019_10190201_85_dialog_content = "......",
  ui_story_1019_10190201_86_dialog_content = "「일루미나로 와」",
  ui_story_1019_10190201_87_dialog_content = "「빨리빨리」",
  ui_story_1019_10190301_1_dialog_content = "<color=#e8d9bb>일루미나 정비공장</color>",
  ui_story_1019_10190301_2_dialog_content = "큰일 났네... 어디서 만날 건지 물어본다는 걸 깜빡했잖아.",
  ui_story_1019_10190301_3_dialog_content = "저기, 안녕하세요. 실례지만...",
  ui_story_1019_10190301_4_dialog_content = "일반 주민은 정비공장에 출입할 수 없습니다. 당장 여기서 떠나세요.",
  ui_story_1019_10190301_5_dialog_content = "앗, 저는 여기 주민이 아니라 아이테...",
  ui_story_1019_10190301_6_dialog_content = "전원 집합!",
  ui_story_1019_10190301_7_dialog_content = "집합──!",
  ui_story_1019_10190301_8_dialog_content = "다시 말씀드리겠습니다.\n방어 시스템에 허점이 발견돼 이곳은 안전하지 않습니다! 당장 떠나세요.",
  ui_story_1019_10190301_9_dialog_content = "방어 시스템에 허점이 발견됐다니...",
  ui_story_1019_10190301_10_dialog_content = "순찰병이 이렇게 많은 걸 보면 아직도 문제가 해결이 안 된 모양이네.",
  ui_story_1019_10190301_11_dialog_content = "이얍! PlayerName, 받아라!",
  ui_story_1019_10190301_12_dialog_content = "자, 잠깐만... 넌...",
  ui_story_1019_10190301_13_dialog_content = "뭐? 아니지? PlayerName, 진짜 날 잊어버린 거야?!",
  ui_story_1019_10190301_14_dialog_content = "아! 기억났어. 넌...",
  ui_story_1019_10190301_15_option_content = "초록 털...?",
  ui_story_1019_10190301_16_dialog_content = "아니, 내 말은 그러니까... 숀이었지!",
  ui_story_1019_10190301_17_dialog_content = "(하마터면 첫인상을 말해 버릴 뻔했네...)",
  ui_story_1019_10190301_18_dialog_content = "헤헤, 사실 날 그렇게 부르는 사람들이 좀 있긴 해~",
  ui_story_1019_10190301_19_option_content = "크로우...?",
  ui_story_1019_10190301_20_dialog_content = "아니, 잠깐만... 크로우가 아니라 숀이지, 참!",
  ui_story_1019_10190301_21_dialog_content = "음... 크로우에 비하면 난 부대에서 눈에 띄는 편이 아니긴 해.",
  ui_story_1019_10190301_22_option_content = "숀...?",
  ui_story_1019_10190301_23_dialog_content = "그래, 숀이었어, 숀...",
  ui_story_1019_10190301_24_dialog_content = "미안해! 그냥 좀... 내가 기억하는 네 모습이랑 달라서 그랬어.",
  ui_story_1019_10190301_25_dialog_content = "당연하지. 왜냐면 나 요즘 매일 복싱 연습 중이라 하루가 다르게 강해지고 있거든!",
  ui_story_1019_10190301_26_dialog_content = "뭐, 됐어, 그냥 넘어가 줄게~",
  ui_story_1019_10190301_27_dialog_content = "그래서 여긴 어쩐 일이야?",
  ui_story_1019_10190301_28_dialog_content = "난 원래 정기적으로 자난성에 돌아와서 신체검사를 받거든.\n이번엔 평소보다 좀 일찍 왔는데, 널 만나게 될 줄은 몰랐어.",
  ui_story_1019_10190301_29_dialog_content = "일찍 돌아왔으면 순찰대에 합류해서 암귀 수색을 도와야 하는 거 아닌가요?",
  ui_story_1019_10190301_30_dialog_content = "충성! 비비안 참모장님, 그게...",
  ui_story_1019_10190301_31_dialog_content = "농담이었어요. 당신 일부터 마저 보세요. 몸조심하고요.",
  ui_story_1019_10190301_32_dialog_content = "넵, 참모장님!\n그럼 또 봐, PlayerName.",
  ui_story_1019_10190301_33_dialog_content = "응, 나중에 봐, 숀.",
  ui_story_1019_10190301_34_dialog_content = "역시 대원수님 말씀이 맞았네요. 당신이 기다리다 못 참고 일루미나에 올 거라고 하셨거든요.",
  ui_story_1019_10190301_35_dialog_content = "내가 올 걸 아셨구나. 그래서 비비안 씨를...",
  ui_story_1019_10190301_36_dialog_content = "물론이죠. 저희는 이 아스트라에서 당신과 콜로서스가 하는 행동들을 훤히 알고 있어요.",
  ui_story_1019_10190301_37_dialog_content = "하지만 지금 일루미나는 상황이 복잡해요. 윗분들이 알력 다툼에 여념이 없으시거든요.",
  ui_story_1019_10190301_38_dialog_content = "당신도 봤겠지만, 방어 문제도 아직 심각하고요.",
  ui_story_1019_10190301_39_dialog_content = "참, 그럼 지금 일루미나의 대원수는...",
  ui_story_1019_10190301_40_option_content = "라인하르트 씨인 거야?",
  ui_story_1019_10190301_41_dialog_content = "당연하죠. 그분은 우리 일루미나 군인 모두의 정신적인 지도자이자,\n그 누구도 넘어설 수 없는 대원수세요.",
  ui_story_1019_10190301_42_option_content = "레이스 씨인 거야?",
  ui_story_1019_10190301_43_dialog_content = "명목상으로는 레이스가 아직 대원수예요.\n하지만 대원수 직위를 라인하르트 님께 돌려주겠다고 위원회에 밝힌 상태예요.",
  ui_story_1019_10190301_44_dialog_content = "그리고 위원회로선 누가 대원수를 맡든 탐탁지 않겠죠.\n그래도 군대엔 통일된 지휘 체계가 필요하기 때문에...",
  ui_story_1019_10190301_45_dialog_content = "일단 지금은 대원수님의 내통 혐의에 대한 조사를 미루고,\n위원회와 군이 공동으로 일루미나의 정무를 담당하기로 했어요.",
  ui_story_1019_10190301_46_dialog_content = "그럼 업무가 엄청 복잡해질 것 같은데?",
  ui_story_1019_10190301_47_dialog_content = "맞아요. 지금 일루미나는 행정 체계가 무척 혼란스러운 상태라,\n저조차도 대원수님과 연락이 닿지 않을 때가 많아요.",
  ui_story_1019_10190301_48_dialog_content = "그래서 계속 연락이 없으셨던 거구나... 미안! 나 때문에 다들 번거롭게 만들었네...",
  ui_story_1019_10190301_49_dialog_content = "근데... 레이스 씨는 아직도 라인하르트 씨랑 승부를 가리고 싶어 하는 거야?",
  ui_story_1019_10190301_50_dialog_content = "맞아요. 대원수 자리를 두고 싸울 생각은 없으면서,\n어떻게든 대원수님과 붙어 보겠다고 하네요.",
  ui_story_1019_10190301_51_dialog_content = "역시 레이스 씨답다니까... 그럼 레이스 씨는 좀 어때? 수술은 잘 된 거야?",
  ui_story_1019_10190301_52_dialog_content = "저도 무척 궁금하지만... 행정 절차가 복잡해져 버린 탓에,\n「계명성 프로젝트」와 관련된 업무는 접근이 매우 어려워졌어요.",
  ui_story_1019_10190301_53_dialog_content = "혹시 이번에 레이스를 만나러 온 거라면, 그건 아마 힘들 거예요.",
  ui_story_1019_10190301_54_dialog_content = "아, 사실 내가 온 이유는...",
  ui_story_1019_10190301_55_dialog_content = "그어어어!",
  ui_story_1019_10190301_56_dialog_content = "참모장님! 정비원의 보고에 따르면 정비공장 서쪽 환기구가 제어 불능 상태이며,\n암귀는 그쪽을 통해 침입한 것으로 보입니다!",
  ui_story_1019_10190301_57_dialog_content = "드디어 허점을 찾았군요! 밤새 고생한 보람이 있었네요.",
  ui_story_1019_10190301_58_dialog_content = "대열을 갖춰 용접공을 엄호하고, 저와 함께 암귀를 소탕하세요!",
  ui_story_1019_10190301_59_dialog_content = "예!",
  ui_story_1019_10190301_60_dialog_content = "으앗! 거기 앞에! 비켜! 비켜!",
  ui_story_1019_10190301_61_dialog_content = "참모장님! 뒤쪽에서... 암귀가 사람의 목을 조르고 있습니다!",
  ui_story_1019_10190301_62_dialog_content = "저거 설마...",
  ui_story_1019_10190301_63_dialog_content = "부부부부!",
  ui_story_1019_10190301_64_dialog_content = "보는 사람도 이렇게 많은데...",
  ui_story_1019_10190301_65_dialog_content = "부부부부!",
  ui_story_1019_10190301_66_dialog_content = "알겠어, 알겠다니까, 아직 운동할 시간이 아니긴 하지만...",
  ui_story_1019_10190301_67_dialog_content = "「프로그램 실행 준비!」",
  ui_story_1019_10190301_68_dialog_content = "부우!",
  ui_story_1019_10190301_69_dialog_content = "...저 사람 대체 누구죠?",
  ui_story_1019_10190402_1_dialog_content = "업로드... 업로드... 휴, 역시 실외 운동 데이터는 아직 부족하다니까.",
  ui_story_1019_10190402_2_dialog_content = "원래 과학자들은 저런 식으로 싸우는 건가...",
  ui_story_1019_10190402_3_dialog_content = "야, 잠깐만. 네가 과학자에 대한 편견을 토대로 편향된 어휘들을 끄집어내기 전에,\n내가 먼저 주의를 좀 줘야겠어...",
  ui_story_1019_10190402_4_dialog_content = "과학자라고 전부 다 음침하고, 지루하고, 팔다리 뻣뻣한 대머리 책벌레인 건 아니라고.",
  ui_story_1019_10190402_5_dialog_content = "아, 아니, 그런 뜻으로 한 말은 아닌데요...",
  ui_story_1019_10190402_6_dialog_content = "PlayerName, 이 사람은...?",
  ui_story_1019_10190402_7_dialog_content = "이쪽은 일루미나 과학 수석 의회의 과학자, 알골 씨야.",
  ui_story_1019_10190402_8_dialog_content = "오늘 내가 온 건 이 사람한테 부탁을 받아서였거든...\n근데 이 사람 왠지 저번에 봤을 때랑은 뭔가 다르네.",
  ui_story_1019_10190402_9_dialog_content = "과학 수석 의회라... 그쪽 사람들을 진짜로 보는 건 처음이네요.",
  ui_story_1019_10190402_10_dialog_content = "해결── 끝──!",
  ui_story_1019_10190402_11_dialog_content = "안녕! 아이테르, 그리고... 내가 그쪽도 불렀던가?",
  ui_story_1019_10190402_12_dialog_content = "알골 교수, 전 일루미나 참모장, 비비안이에요.",
  ui_story_1019_10190402_13_dialog_content = "음... 그래. 기왕 온 거 그럼 같이 가자고.",
  ui_story_1019_10190402_14_dialog_content = "알골 교수, 우선 설명해 두고 싶네요.\n전 대원수님의 명령에 따라 PlayerName의 일루미나 내 활동을 지원하고 있어요.",
  ui_story_1019_10190402_15_dialog_content = "그래서 저는 두 사람의 계획을 사전에 파악하고, 대원수님께 보고해야만 해요.",
  ui_story_1019_10190402_16_dialog_content = "우린 그냥 즉흥적으로 만난 거야. 계획은커녕 당신한테 줄 일정표도 없어.\n굳이 기억해 둬야겠다면, 여기 있어.",
  ui_story_1019_10190402_17_dialog_content = "...어디 있다는 거죠?",
  ui_story_1019_10190402_18_dialog_content = "내 머리.",
  ui_story_1019_10190402_19_dialog_content = "부우!",
  ui_story_1019_10190402_20_dialog_content = "......",
  ui_story_1019_10190402_21_dialog_content = "하지만 안전 문제를 고려해 확인해 둘 부분이 있어요.\n조금 전 전투에서 당신과 함께 싸운 건... 평범한 무기가 아닌 거죠?",
  ui_story_1019_10190402_22_dialog_content = "물론 아니지. 얘는 부르라고 하고, 내 애완...",
  ui_story_1019_10190402_23_dialog_content = "부부!",
  ui_story_1019_10190402_24_dialog_content = "아야! 아프다고! 동료, 동료야... 아, 좀!",
  ui_story_1019_10190402_25_dialog_content = "어휴, 진짜... 으음~ 시원해~ 조금 더 위에...",
  ui_story_1019_10190402_26_dialog_content = "걔 마사지도 할 줄 알아요...?",
  ui_story_1019_10190402_27_dialog_content = "부르 말론 네가 지난번에 봤을 때보다 살이 좀 찐 거 같다는데?",
  ui_story_1019_10190402_28_dialog_content = "뭐라고요...?! 걔 말도 해요?",
  ui_story_1019_10190402_29_dialog_content = "아이테르라면 정보 교류가 꼭 입으로만 하는 게 아니란 건 알고 있을 거잖아?",
  ui_story_1019_10190402_30_dialog_content = "나랑 부르 사이에도 특별한 교류 방식이 있어.",
  ui_story_1019_10190402_31_dialog_content = "예를 들면, 부르는 지금... 내가 자기 전투 시스템을 업그레이드해 줘서\n무척 만족스러워하고 있어!",
  ui_story_1019_10190402_32_dialog_content = "부우!",
  ui_story_1019_10190402_33_dialog_content = "아하하, 천만에!",
  ui_story_1019_10190402_34_dialog_content = "(그래도 왠지 아까 같은 등장 방식은 좀 많이 아니지 싶은데...)",
  ui_story_1019_10190402_35_dialog_content = "응? 아이테르가 뭐라고 하고 있다고?",
  ui_story_1019_10190402_36_dialog_content = "부우!",
  ui_story_1019_10190402_37_dialog_content = "그러네... 사람을 얕보는 표정을 짓고 있는 건 나도 확실히 알겠어.",
  ui_story_1019_10190402_38_dialog_content = "둘은 제 속마음까지 들리는 건가요...",
  ui_story_1019_10190402_39_dialog_content = "아하하, 긴장할 거 없어. 아무튼 일단 가자.",
  ui_story_1019_10190402_40_dialog_content = "참... 이렇게 급하게 절 일루미나로 부른 걸 보면, 뭔가 중요한 일이라도 있는 건가요?",
  ui_story_1019_10190402_41_dialog_content = "지금 뭘 하려는 건지도 모르고 무작정 온 거란 말이에요?",
  ui_story_1019_10190402_42_dialog_content = "그건 오히려 내가 가지고 있던 아이테르에 대한 고정관념과 일치하는데?",
  ui_story_1019_10190402_43_dialog_content = "네가 스카이워커호를 고치려고 「패스파인더호」의 인격 데이터를 복사했었던 건 기억하지?",
  ui_story_1019_10190402_44_dialog_content = "원래라면 지금은 그 데이터들 속 좌표들과 대응하는 위치를 찾을 수 없는 게 맞아.",
  ui_story_1019_10190402_45_dialog_content = "그런데 얼마 전 일루미나에서 영원한 밤의 땅의 지도 일부를 업데이트했거든.\n어쩌면 그 안에서 「가디언 1호」의 코어에 대한 단서를 찾을 수 있을 것 같아.",
  ui_story_1019_10190402_46_dialog_content = "게다가 추적 소대가 발견한 미지의 좌표도 그 데이터들 속에 답이 있을지도 모르고.",
  ui_story_1019_10190402_47_dialog_content = "정말요?! 다행이네요! 그럼 제가 뭘 하면 될까요?",
  ui_story_1019_10190402_48_dialog_content = "이번에 필요한 건 네 감응 능력이 아니라 스카이워커호의 학습 능력이야.",
  ui_story_1019_10190402_49_dialog_content = "학습 능력이요?",
  ui_story_1019_10190402_50_dialog_content = "그래. 스카이워커호의 의식이 그렇게 짧은 시간 만에 회복될 수 있었다는 건,\n상당한 학습 능력을 지녔다는 방증이거든.",
  ui_story_1019_10190402_51_dialog_content = "난 스카이워커호의 학습 능력을 참고해서 어둠의 밑바닥 지도 제작 효율을 높이고,\n내 연구의 새로운 방향도 모색하고 싶어.",
  ui_story_1019_10190402_52_dialog_content = "왠지 뭔가 대단한 일 같은데... 도움이 될 수 있다면 좋겠네요.",
  ui_story_1019_10190402_53_dialog_content = "그럼 스카이워커호를 내 <color=#FFB400>단말기</color>에 연결해 줘. 시간이 좀 걸릴 거야.",
  ui_story_1019_10190402_54_dialog_content = "어느 정도 걸릴 거냐면... 어디 보자...",
  ui_story_1019_10190402_55_dialog_content = "알골 씨 <color=#FFB400>단말기</color>는 손목에 찬 그거인가요?",
  ui_story_1019_10190402_56_dialog_content = "이건 하이테크 밴드야. 물론, 난 스포츠 밴드라고 부르는 걸 더 선호하지만.",
  ui_story_1019_10190402_57_dialog_content = "아, 운동할 시간이 됐네. 두 사람도 나랑 같이 운동 좀 할래?",
  ui_story_1019_10190402_58_dialog_content = "지금은 새벽인걸요... 알골 교수, 평소에도 새벽 시간에 운동을 하나요?",
  ui_story_1019_10190402_59_dialog_content = "내 생체 시계는 원래 이렇거든...",
  ui_story_1019_10190402_60_dialog_content = "그럼 이렇게 하자. 아까 암귀하고 싸운 걸 운동으로 치고, 이따가 바로 일 시작하자!",
  ui_story_1019_10190402_61_dialog_content = "......",
  ui_story_1019_10190402_62_dialog_content = "집사, 집사... 문 열어. 정신을 맑게 해 줄 커피 세 잔도 좀 준비해 주고.",
  ui_story_1019_10190402_63_dialog_content = "1호는 거절합니다. 1호는 집사가 아닙니다.",
  ui_story_1019_10190402_64_dialog_content = "......",
  ui_story_1019_10190402_65_dialog_content = "아하하... 바, 방금 막 일어나서 그런 모양이야...",
  ui_story_1019_10190501_1_dialog_content = "<color=#e8d9bb>알골의 사무실</color>",
  ui_story_1019_10190501_2_dialog_content = "내 실험실에 온 걸 환영해. 안이 좀 정신없긴 한데, 자리 찾아서 앉아.",
  ui_story_1019_10190501_3_dialog_content = "일루미나의 실험실 중에 이런 곳도 있었다니...",
  ui_story_1019_10190501_4_dialog_content = "분재, 운동 기구, 게다가 굉장해 보이는 이런 것들까지...",
  ui_story_1019_10190501_5_dialog_content = "이건 침대인가요, 아니면 소파인가요?",
  ui_story_1019_10190501_6_dialog_content = "직접 누워 보면 알 텐데 뭘 묻고 그래? 마사지 기능 버튼은 그 옆에 있어.",
  ui_story_1019_10190501_7_dialog_content = "으음... 시원하네요. 금방 잠들어 버릴 것만 같아요.",
  ui_story_1019_10190501_8_dialog_content = "이건 일루미나 스타일이랑 거리가 너무 먼 거 같은데...",
  ui_story_1019_10190501_9_dialog_content = "맞아요. 이 실험실의 인테리어는 《일루미나 거주 환경 관리 조례》를\n전혀 따르지 않았거든요...",
  ui_story_1019_10190501_10_dialog_content = "아? 여기 있는 물건 대부분은 내가 폐기된 재료를 가져다가 직접 만든 거야.",
  ui_story_1019_10190501_11_dialog_content = "이렇게 해서 난 내 일과 생활을 이 방에 하나로 모아 놨어.\n이러면 자원 절약도 많이 되잖아?!",
  ui_story_1019_10190501_12_dialog_content = "그리고 업무 시간 중에 마사지를 받는 것도 《일루미나 군인 조례》 위반이야, 참모장.",
  ui_story_1019_10190501_13_dialog_content = "제, 제가 언제 마사지 같은 걸 받았다고...",
  ui_story_1019_10190501_14_dialog_content = "방금 금방 잠들 거 같다고 그랬잖아...",
  ui_story_1019_10190501_15_dialog_content = "아이테르, 너도 거기 그렇게 서 있지 말고, 저쪽에 쳇바퀴처럼 생긴 거 보이지?",
  ui_story_1019_10190501_16_dialog_content = "그 위에 10분만 서 있으면, 콜로서스 안을 10바퀴 뛰는 것보다\n다이어트에 훨씬 도움이 될 거야.",
  ui_story_1019_10190501_17_dialog_content = "다이어트 얘긴 나중에 하면 안 될까요...",
  ui_story_1019_10190501_18_dialog_content = "띠릭──",
  ui_story_1019_10190501_19_dialog_content = "오랜만입니다, 아이테르!",
  ui_story_1019_10190501_20_dialog_content = "아, 1호! 집사 로봇이 누군가 했더니 너였구나!",
  ui_story_1019_10190501_21_dialog_content = "1호는 알골의 집사 채용 제안에 단 한 번도 동의한 적 없습니다.",
  ui_story_1019_10190501_22_dialog_content = "...그럼 네가 가져온 건 뭔데?",
  ui_story_1019_10190501_23_dialog_content = "1호가 두 손님을 위해 준비한 모닝커피입니다. 알골의 커피는 알아서 준비하세요.",
  ui_story_1019_10190501_24_dialog_content = "야, 어떻게 나한테 그럴 수가 있어...?",
  ui_story_1019_10190501_25_dialog_content = "음... 안에 버터를 넣었나요? 움브라톤에서만 맛볼 수 있던 커피 맛이 나네요.",
  ui_story_1019_10190501_26_dialog_content = "특정 비율에 따라 블렌딩한 오일을 넣은 커피입니다. 참모장님의 입에 맞을 겁니다.",
  ui_story_1019_10190501_27_dialog_content = "아주 마음에 들어요.",
  ui_story_1019_10190501_28_dialog_content = "그럼 나도 어디...",
  ui_story_1019_10190501_29_dialog_content = "으음... 싱그러운 풀 향기가 느껴져. 의외로 엄청 맛있는데!",
  ui_story_1019_10190501_30_dialog_content = "그건 헤븐즈 밸리 특별 블렌딩입니다.",
  ui_story_1019_10190501_31_dialog_content = "알골은 최근 재미있는 프로그램을 다수 개발했습니다.\n1호는 당신이 일루미나에서 보인 식습관을 바탕으로, 특제 커피를 제조할 수 있습니다.",
  ui_story_1019_10190501_32_dialog_content = "그렇게 얘기하니까 진짜 집사 같잖아.",
  ui_story_1019_10190501_33_dialog_content = "......",
  ui_story_1019_10190501_34_dialog_content = "부부!",
  ui_story_1019_10190501_35_dialog_content = "읏차, 환경은 갖춰졌으니까, 이제 데이터를 이동시켜 보자!",
  ui_story_1019_10190501_36_dialog_content = "입력기, 입력기가... 쓰읍, 어디 간 거야?",
  ui_story_1019_10190501_37_dialog_content = "이런... 좀 주워 줘, 1호.",
  ui_story_1019_10190501_38_dialog_content = "......",
  ui_story_1019_10190501_39_dialog_content = "...그냥 제가 할게요.",
  ui_story_1019_10190501_40_dialog_content = "어라...? 뒤에 이 핑크색 하트는 다 뭐죠?",
  ui_story_1019_10190501_41_dialog_content = "...「사랑하는 알골에게. 내게 수학을 가르쳐 주지 않을래?」",
  ui_story_1019_10190501_42_dialog_content = "여기도 있네요. 「네 지혜는 지하성의 탐조등처럼 날 환히 비춰」라고...",
  ui_story_1019_10190501_43_dialog_content = "게다가 보낸 사람 사인은... 「누구게?」...?",
  ui_story_1019_10190501_44_dialog_content = "아, 그거? 내가 예전에 받은 러브레터들이야.",
  ui_story_1019_10190501_45_option_content = "손발이 오그라들 거 같네요...",
  ui_story_1019_10190501_46_option_content = "안 본 눈 사요...",
  ui_story_1019_10190501_47_dialog_content = "알골, 설마 다른 사람에게 받은 러브레터를 메모지로 사용할 줄은 몰랐습니다.",
  ui_story_1019_10190501_48_dialog_content = "손 닿는 곳에 멀쩡한 메모지가 있는데 안 쓸 이유가 없잖아...\n그리고 바꿔 말하면 내가 한 통도 안 버리고 있었단 뜻이잖아?",
  ui_story_1019_10190501_49_dialog_content = "상황판을 써도 되는 거잖아요...",
  ui_story_1019_10190501_50_dialog_content = "저 커다란 상황판에서 있는 거라곤... 지도... 계산식... 계산식...\n죄다 계산식인데요...",
  ui_story_1019_10190501_51_dialog_content = "이 메모지들은 알골 교수의 심경을 반영이라도 한 것처럼 수정된 흔적이 가득하네요.",
  ui_story_1019_10190501_52_dialog_content = "참모장도 거기 새겨진 내 고통이 보이는 모양이네?",
  ui_story_1019_10190501_53_dialog_content = "그건 다 내가 「가디언」의 수수께끼를 못 풀어서 느낀 고통의 흔적들이거든.",
  ui_story_1019_10190501_54_dialog_content = "「가디언」이면, 1호 얘기인가요?",
  ui_story_1019_10190501_55_dialog_content = "아닙니다.",
  ui_story_1019_10190501_56_dialog_content = "「가디언 1호」는 일루미나 과학 기술 시스템 전체의 일상적인 가동과 계산을\n담당하는 고대의 인공지능이야.",
  ui_story_1019_10190501_57_dialog_content = "게다가 그건 거대한 컴퓨터 클러스터 형태를 이루고 있거든.\n팬텀이 거기서 코어를 훔쳐간 게 자난성에 어떤 영향을 줬는지는 다들 이미 잘 봤을 거야.",
  ui_story_1019_10190501_X57_dialog_content = "그 클러스터는 고대 기술 「가디언」을 기반으로 점진적으로 발전해 왔어.",
  ui_story_1019_10190501_58_dialog_content = "즉, 「가디언」은 「가디언 1호」의 프로토타입이라고 할 수 있지.",
  ui_story_1019_10190501_59_dialog_content = "여기 있는 1호는 바로 그 컴퓨터 클러스터의 일부인 거야.\n얜 데이터 처리를 위한 독립적인 코어도 있고, 많은 양의 고대 정보를 저장하고 있어.",
  ui_story_1019_10190501_X59_dialog_content = "따라서 이론적으로는 동일한 이름을 가지는 게 맞아.\n뭐, 구별하기 쉽게 1호... 우체통이라고 불러도 돼.",
  ui_story_1019_10190501_60_dialog_content = "1호는 우체통이 아닙니다.",
  ui_story_1019_10190501_61_dialog_content = "띠릭, 띠릭, 띠리릭.",
  ui_story_1019_10190501_62_dialog_content = "1호는 알골의 말이 이해되지 않습니다.",
  ui_story_1019_10190501_63_dialog_content = "역시 넌 오로리안 간의 복잡한 대화 정보를 어떻게 처리할지 좀 더 공부할 필요가 있어.",
  ui_story_1019_10190501_64_dialog_content = "1호는 이해했습니다.",
  ui_story_1019_10190501_65_dialog_content = "(그냥 대충 넘어가려는 건 아니고...?)",
  ui_story_1019_10190501_66_dialog_content = "아무튼, 「가디언」에 대한 연구 및 학습을 계속 진행하고,\n다른 기능을 개발하는 게 내 업무야.",
  ui_story_1019_10190501_67_dialog_content = "그럼 이 기계가 바로 프로토타입인가요?",
  ui_story_1019_10190501_68_dialog_content = "이건 <color=#FFB400>가상 머신</color>이라고 해. 프로토타입은 안전 문제 때문에 오래전에 봉인된 상태거든.",
  ui_story_1019_10190501_69_dialog_content = "그렇겠죠... 고대의 기술로 만들어진 기계라면, 지금은 다 낡아빠진 상태일 테니까요.",
  ui_story_1019_10190501_70_dialog_content = "꼭 그렇지만은 않아. 전에 프로토타입을 직접 본 적이 있는데,\n그 외형... 뭐랄까, 아주 고풍스러운 느낌이었어.",
  ui_story_1019_10190501_71_dialog_content = "최근 몇 년간 주변 장치 쪽의 기술은 발전을 이뤘지만, 「가디언」의 연구만 줄곧 지지부진했거든....",
  ui_story_1019_10190501_72_dialog_content = "그게 봉인되기 전에 내가 조금 더 깊이 파고들었더라면...",
  ui_story_1019_10190501_73_dialog_content = "그런 생각이 들 때마다 나 자신에게 이가 갈릴 정도로 화가 난다니까!",
  ui_story_1019_10190501_74_dialog_content = "부우~",
  ui_story_1019_10190501_75_dialog_content = "부르! 어떻게 너까지 날 비웃을 수가 있어...?",
  ui_story_1019_10190501_76_dialog_content = "부르의 반응은... 왠지 비웃는 게 아니라, 알골 씨 말을 부정하는 거 같은데요?",
  ui_story_1019_10190501_77_dialog_content = "부우!",
  ui_story_1019_10190501_78_dialog_content = "이제 됐어! 심지어 아이테르가 나보다 머리도 좋네!",
  ui_story_1019_10190501_79_dialog_content = "......",
  ui_story_1019_10190501_80_dialog_content = "아, 오해 얘기가 나와서 생각난 건데...",
  ui_story_1019_10190501_81_dialog_content = "아이테르 넌 1호의 의식에 감응할 수 있으니까,\n그럼 부르의 의식 속도 볼 수 있지 않을까?",
  ui_story_1019_10190501_82_dialog_content = "부부!",
  ui_story_1019_10190501_83_dialog_content = "...알골 씨는 진짜 의식의 흐름대로 사는 사람이었군요...\n근데 부르가 알골 씨 뒤에 숨은 걸 보니까, 별로 원하지 않는 것 같은데요.",
  ui_story_1019_10190501_84_dialog_content = "부우...",
  ui_story_1019_10190501_85_dialog_content = "그래 보여? 얘 지금 일부러 조신한 척하는 거야.",
  ui_story_1019_10190501_86_dialog_content = "그럼... 한번 해 볼게요.",
  ui_story_1019_10190501_87_dialog_content = "부우...",
  ui_story_1019_10190501_88_option_content = "(감응 연결!)",
  ui_story_1019_10190501_89_dialog_content = "(어? 부르는 알골 씨 뒤에 숨은 거 아니었나? 왜 알골 씨밖에 안 느껴지지...?)",
  ui_story_1019_10190501_90_dialog_content = "(설마 내가 감응을 잘못했나?)",
  ui_story_1019_10190501_91_dialog_content = "(왜 아무것도 안 보이지...?)",
  ui_story_1019_10190501_92_dialog_content = "(설마 알골 씨... 오로리안이 아니라 로봇...? 인공지능?!)",
  ui_story_1019_10190501_93_dialog_content = "(그럴 리가... 조금 전에 알골 씨가 싸울 때 루미나를 다뤘잖아.\n나도 참, 무슨 생각을 하는 거야...)",
  ui_story_1019_10190501_94_dialog_content = "(감응이 너무 얕아서 이러는 걸 수도 있으니까,\n의식에 조금 더 깊게 들어가 봐야겠어...)",
  ui_story_1019_10190501_95_dialog_content = "(깊은 의식 속으로...)",
  ui_story_1019_10190501_96_dialog_content = "(더 깊게...)",
  ui_story_1019_10190501_97_dialog_content = "(어? 방금 그거... 부르인가?)",
  ui_story_1019_10190501_98_dialog_content = "(내가 두 감응 대상을 전환할 수 있었나? 진짜 신기하네.\n왠지 눈 한 쌍이 더 생긴 느낌이야...)",
  ui_story_1019_10190501_99_dialog_content = "<color=#e8d9bb>부우! 퍼억──</color>",
  ui_story_1019_10190501_100_dialog_content = "──으앗!",
  ui_story_1019_10190601_1_dialog_content = "부르가 너한테 이렇게 다정할 줄은 몰랐지 뭐야~",
  ui_story_1019_10190601_2_dialog_content = "심박수, 혈압... 음, 데이터는 다 정상이야.\n그리고 산소 수용력과 신체 협응력은 조금 향상됐어.",
  ui_story_1019_10190601_3_dialog_content = "지금 「구타」당한 걸 운동한 걸로 취급하는 거예요?!",
  ui_story_1019_10190601_4_dialog_content = "그게 무슨 구타야? 몸에 멍도 안 들었으면서...\n그리고 이건 아주 고차원적인 소통 방식이야.",
  ui_story_1019_10190601_5_dialog_content = "부우~",
  ui_story_1019_10190601_6_dialog_content = "부르 너 그거 무슨 말투인지 나 기억해! 근데 지금 위로해 줘 봤자 너무 늦잖아...",
  ui_story_1019_10190601_7_dialog_content = "알골 박사, 당신과 부르의 소통은 대체 어떤 방식으로 이루어지고 있는 거죠?",
  ui_story_1019_10190601_8_dialog_content = "부르가 날 툭툭 치는 강도를 조절하는 방식으로 소통하고 있어.\n근데 이 방식은 아이테르하곤 안 맞는 모양이네.",
  ui_story_1019_10190601_9_dialog_content = "안 맞으면 그냥 안 맞는 대로 지낼게요...",
  ui_story_1019_10190601_10_dialog_content = "하지만 지금까지 부르는 널 굉장히 친근하게 대했는걸. 그럼 왜 그랬던 걸까...",
  ui_story_1019_10190601_11_dialog_content = "음... 아까 부르의 의식 속에서 제가 뭔가 보긴 했어요...",
  ui_story_1019_10190601_12_dialog_content = "근데 1호의 의식 속이랑 다르게, 어떤 구체적인 장면이 보인 건 아니었어요.",
  ui_story_1019_10190601_13_dialog_content = "그럴 거야. 부르는 컴퓨터에 가까운 사고방식을 가지고 있거든.",
  ui_story_1019_10190601_14_dialog_content = "아무튼 부르가 심통 부린 건 너그럽게 봐줘. 싸우면서 정든다는 말도 있잖아?",
  ui_story_1019_10190601_15_dialog_content = "......",
  ui_story_1019_10190601_16_dialog_content = "<color=#e8d9bb>삑── 삐빅──</color>",
  ui_story_1019_10190601_17_dialog_content = "아, 역시 새 지도에 추가할 만한 좌표 정보가 스카이워커호의 데이터 안에 있었네.",
  ui_story_1019_10190601_18_dialog_content = "저쪽은 지금까지 우리 발길이 닿은 적 없는 곳이잖아요?",
  ui_story_1019_10190601_19_dialog_content = "음? 이 깜빡이는 점들은 좌표가 여러 개 존재한다는 의미인가요?",
  ui_story_1019_10190601_20_dialog_content = "어쩌면 신호의 근원지는 하나고, 신호에 편차가 조금 있는 것뿐일지도 몰라.",
  ui_story_1019_10190601_21_dialog_content = "자난성 북서쪽이고, 거리는 대략 4천여 킬로미터 정도인가...",
  ui_story_1019_10190601_22_dialog_content = "음... 이 정도면 괜찮네. 생각만큼 멀진 않잖아.",
  ui_story_1019_10190601_23_dialog_content = "근데 이 신호들은 귀환의 탑에서 송출했던 신호들보다 훨씬 오래된 거야.",
  ui_story_1019_10190601_24_dialog_content = "그럼... 콜로서스가 탄생한 곳이 헤븐즈 밸리가 아니란 뜻인가요...?",
  ui_story_1019_10190601_25_dialog_content = "그래. 헤븐즈 밸리의 현재 위치는 암귀가 아스트라 대륙을 침략했을 무렵에\n세워진 전초기지가 있던 곳으로 보이거든.",
  ui_story_1019_10190601_26_dialog_content = "콜로서스가 처음 만들어진 곳은 어둠의 밑바닥에 있을 가능성이 커.",
  ui_story_1019_10190601_27_dialog_content = "헤븐즈 밸리가 스카이워커호의 고향이 아니었던 거군요...",
  ui_story_1019_10190601_28_dialog_content = "심지어 아이테르의 고향도 아니고 말이죠...",
  ui_story_1019_10190601_29_dialog_content = "고향이 어디에 있느냐는 중요한 게 아냐, 아이테르.",
  ui_story_1019_10190601_30_dialog_content = "중요한 건 스카이워커호가 「집」이라는 의식을 가진 순간부터,\n쭉 아이테르와 함께 헤븐즈 밸리에서 생활해 왔다는 거야.",
  ui_story_1019_10190601_31_dialog_content = "기계생물학적 관점으로 보면 지금의 스카이워커호는 네 피조물이라고 간주하는 게 맞아.",
  ui_story_1019_10190601_32_dialog_content = "......",
  ui_story_1019_10190601_33_dialog_content = "너무 속상해하진 마. 지금은 어디까지나 추측 단계일 뿐이니까.",
  ui_story_1019_10190601_34_dialog_content = "위치를 확정하고 나면, 함께 가서 답을 찾아보도록 해요.",
  ui_story_1019_10190601_35_dialog_content = "알골 박사, 어둠의 밑바닥에서 탐색을 진행하려면 어떤 준비를 해야 하죠?",
  ui_story_1019_10190601_36_dialog_content = "헬리오스와 어둠의 밑바닥에 보낸 탐색대가 제공해 준 정보 덕분에\n우린 어둠의 밑바닥에 대해 어느 정도는 파악할 수 있었어.",
  ui_story_1019_10190601_37_dialog_content = "전문가가 그 정보를 토대로 지도를 제작 중인데,\n스카이워커호의 데이터도 그 사람 작업에 도움이 되고 있거든.",
  ui_story_1019_10190601_38_dialog_content = "같이 가서 그 사람한테 조언을 구해 보자. 이러면 조금 흥미가 생겼으려나?",
  ui_story_1019_10190601_39_dialog_content = "좋아요.",
  ui_story_1019_10190601_40_dialog_content = "<color=#e8d9bb>띠링──</color>",
  ui_story_1019_10190601_41_dialog_content = "으응? 연구동 쪽에 암귀가 나타났다고? ...순찰대 담당자는 누구야?",
  ui_story_1019_10190601_42_dialog_content = "이 시간대라면 바튼 군단장일 거예요. 그런데 연구동에 암귀가 나타났단 걸 어떻게 안 거죠?",
  ui_story_1019_10190601_43_dialog_content = "내 하이테크 밴드는 주변의 위험 요소를 감지할 수 있거든.\n아무튼 바튼이 순찰을 맡고 있다면... 별문제없겠네.",
  ui_story_1019_10190601_44_dialog_content = "연구동은 자난성의 중요 기지예요. 그런데 암귀가 침입하다니...\n자난성의 안전이 이 지경이 될 줄은 몰랐네요...",
  ui_story_1019_10190601_45_dialog_content = "암귀가 출몰한 곳이 어디인가요? 지금 바로 상황을 조사한 다음 사람을 보내야겠어요.",
  ui_story_1019_10190601_46_dialog_content = "이미 바튼한테 연락했어.",
  ui_story_1019_10190601_47_dialog_content = "위험 요소 보고, 암귀 분석, 병사 배치, 암귀 처치, 취약점 해결...\n이런 건 다 하이테크 밴드로 처리할 수 있어.",
  ui_story_1019_10190601_48_dialog_content = "하지만...",
  ui_story_1019_10190601_49_dialog_content = "괜찮을 테니까 날 믿어. 모든 일을 당신이 다 직접 처리하진 못해...\n그랬다간 힘들어서 쓰러질걸.",
  ui_story_1019_10190601_50_dialog_content = "제가 당연히 해야 할 일들이에요. 전혀 힘들지 않아요.",
  ui_story_1019_10190601_51_dialog_content = "표정은 나쁘지 않네. 그렇지만 부르 말로는 다크 서클이 진해서 설득력이 없대.",
  ui_story_1019_10190601_52_dialog_content = "부우!",
  ui_story_1019_10190601_53_dialog_content = "가자. 어차피 가는 길에 위험 요소가 있는 곳도 지나니까,\n정 걱정되면 잠깐 들렀다 가도 돼.",
  ui_story_1019_10190601_54_dialog_content = "부우!",
  ui_story_1019_10190702_1_dialog_content = "연구동에 암귀가 침입할 거라고는 정말 생각도 못 했는걸요...",
  ui_story_1019_10190702_2_dialog_content = "근데 저거 진짜 암귀 맞아...? 암귀가 아니라... 일루미나 병사 같이 생겼는데?",
  ui_story_1019_10190702_3_dialog_content = "바튼이 암귀는 다 처리했을 거야. 가서 물어보자.",
  ui_story_1019_10190702_4_dialog_content = "오, 애송이, 네가 여긴 어쩐 일이냐?\n대원수가 헤븐즈 밸리에서 얌전히 기다리라고 한 거 아니었어?",
  ui_story_1019_10190702_5_dialog_content = "그게요... 말하자면 길어요...",
  ui_story_1019_10190702_6_dialog_content = "내가 불렀어.",
  ui_story_1019_10190702_7_dialog_content = "당신이 나한테 메시지를 보낸 과학자인 모양이군. 알골이라 했었나?",
  ui_story_1019_10190702_8_dialog_content = "맞아. 녀석들은 외부에서 침입한 게 아니지?",
  ui_story_1019_10190702_9_dialog_content = "암귀에 대한 건... 너희 과학자들이 신경 쓸 거 없다.",
  ui_story_1019_10190702_10_dialog_content = "더스크 타운에서 있었던 일은 너도 알고 있겠지.\n율리시스의 음모는 실패했다지만, 그 덕에 우리 군인들은 쓴맛을 제대로 봤다고.",
  ui_story_1019_10190702_11_dialog_content = "날 다른 과학자들이랑 똑같이 취급하지 마. 난 오로리안 쪽엔 관심 없으니까.",
  ui_story_1019_10190702_12_dialog_content = "바튼 장군, 알골 교수는 좋은 마음으로 물어본 거예요.\n그러니 우선 암귀들의 상황에 대해 대답부터 해 주세요.",
  ui_story_1019_10190702_13_dialog_content = "......",
  ui_story_1019_10190702_14_dialog_content = "쳇! 이상하게 들리겠지만, 내가 위험 지역에 도착하니 암귀는 안 보이고,\n웬 병사 두 명이 실험동을 지나고 있었다...",
  ui_story_1019_10190702_15_dialog_content = "근데 내가 가까이 가니까 그 자식들 갑자기 머리가 돌았는지 나한테 달려들었단 말이다!",
  ui_story_1019_10190702_16_dialog_content = "저희도 똑같은 상황을 겪었어요.",
  ui_story_1019_10190702_17_dialog_content = "가만 보니 「계명성 프로젝트」에 참여했던 병사들과도 비슷했어.\n애송이, 넌 어떻게 생각하지?",
  ui_story_1019_10190702_18_dialog_content = "방금 전투를 지휘할 때, 저 둘한테서 심상치 않은 다크매터가 느껴졌어요...",
  ui_story_1019_10190702_19_dialog_content = "만약 암귀라면 방어 시스템에 문제가 생겨서 실험용 암귀가 창고에서 도망쳐 나온 거겠지.",
  ui_story_1019_10190702_20_dialog_content = "그럴 가능성도 있다. 일루미나 연구동엔 메디컬 센터, 블랙 엄브렐라 연구소뿐만 아니라...",
  ui_story_1019_10190702_21_dialog_content = "오로리안의 몸에 칼을 대는 미친 과학자도 있으니 말이야!",
  ui_story_1019_10190702_22_dialog_content = "부우...",
  ui_story_1019_10190702_23_dialog_content = "그럼 율리시스한테 직접 가서 묻지 그래?",
  ui_story_1019_10190702_24_dialog_content = "나라고 안 그러고 싶을 것 같나?",
  ui_story_1019_10190702_25_dialog_content = "위원회 놈들, 「계명성 프로젝트」 조사는 이렇게나 오래 끌어놓고,\n율리시스의 병사 개조 건에 대해선 여전히 모호한 태도를 보이고 있다고!",
  ui_story_1019_10190702_26_dialog_content = "내가 보기에 이대로 가다간 자난성은 더 위험해질 뿐이야!",
  ui_story_1019_10190702_27_dialog_content = "율리시스 때문에 목숨을 잃은 병사들이 그렇게 많은데,\n일루미나는 왜 율리시스를 처벌하지 않는 거죠?",
  ui_story_1019_10190702_28_dialog_content = "제가 설명할게요.",
  ui_story_1019_10190702_29_dialog_content = "그건 오히려 병사들을 위해서예요.\n율리시스는 후속 치료에 협조해야 할 의무가 있으니까요.",
  ui_story_1019_10190702_30_dialog_content = "그리고 해당 건과 관련된 자료들은 모두 율리시스의 실험동에 있고,\n심사단은 계속 자료를 이송해서 조사하는 중이에요.",
  ui_story_1019_10190702_31_dialog_content = "감시인이 계속 붙어 있긴 하지만, 현재까지 율리시스는 상대적으로 자유로운 편이죠.",
  ui_story_1019_10190702_32_dialog_content = "그래서 특별한 상황이 없는 한, 우린 율리시스의 실험실에 들어갈 수 없어요.",
  ui_story_1019_10190702_33_dialog_content = "이 암귀들을 증거로 삼고, 방어 시스템의 허점을 조사한다는 구실로\n가서 물어보면 되지 않겠어?",
  ui_story_1019_10190702_34_dialog_content = "부우!",
  ui_story_1019_10190702_35_dialog_content = "그 방법은 이미 써 봤지만, 소용없었다.",
  ui_story_1019_10190702_36_dialog_content = "그럼 날 따라와. 난 율리시스의 실험실에 들어갈 권한이 있으니까.\n너흰 내 조수로 온 거라고 해.",
  ui_story_1019_10190702_37_dialog_content = "적어도 내 추측으론 암귀가 외부에서 자난성 최하층으로 침입해 들어올 방법은 없어.",
  ui_story_1019_10190702_38_dialog_content = "그리고 「가디언 1호」의 코어를 도난당한 것도 모자라서,\n연구동이 암귀 소굴이 되는 것도 난 바라지 않거든.",
  ui_story_1019_10190702_39_dialog_content = "그것도 방법이라면 방법이네요. 바튼 장군은 어떻게 생각하죠?",
  ui_story_1019_10190702_40_dialog_content = "뭐, 한번 해보자고...",
  ui_story_1019_10190702_41_dialog_content = "가자. 대신 조심해. 암귀가 창고 안에서 도망쳐 나온 게 맞다면,\n분명히 이 몇 마리로 끝나진 않을 거야.",
  ui_story_1019_10190802_1_dialog_content = "부부!",
  ui_story_1019_10190802_2_dialog_content = "조급해할 거 없어. 지금 데이터를 전송해 주고 있으니까...",
  ui_story_1019_10190802_3_dialog_content = "순찰병의 보고에 따르면 다른 실험동 내엔 암귀가 나타나지 않았어요.\n아무래도 우리가 맞게 찾아온 모양이네요.",
  ui_story_1019_10190802_4_dialog_content = "설마 율리시스 교수가 일부러 암귀를 풀어놓은 걸까요?",
  ui_story_1019_10190802_5_dialog_content = "그럴 배짱은 없을 거다.\n온 일루미나를 저승길 동무로 삼을 만큼 멍청하지도 않을 테고 말이야.",
  ui_story_1019_10190802_6_dialog_content = "콜록콜록... 그거 칭찬입니까?",
  ui_story_1019_10190802_7_dialog_content = "어이, 율리시스. 네 실험실에 암귀가 있는 거 알고 있나?",
  ui_story_1019_10190802_8_dialog_content = "여긴 실험동입니다. 오로리안과 암귀의 연구를 위한 실험용 암귀가 항상 많이 준비돼 있지요.",
  ui_story_1019_10190802_9_dialog_content = "그건 비밀도 아니고, 당신들이 걱정할 일도 아닙니다.",
  ui_story_1019_10190802_10_dialog_content = "하지만 코어가 도난당한 뒤로 실험동 창고 문에도 문제가 발생하고 있어요.\n암귀들은 아마 창고에서 도망쳐 나온 거겠죠.",
  ui_story_1019_10190802_11_dialog_content = "<color=#e8d9bb>콰당──</color>",
  ui_story_1019_10190802_12_dialog_content = "그리고 이건 실험용 암귀가 아니잖아요.\n오로리안 개조 실험을 금지하라는 명령은 이미 받았을 텐데요.",
  ui_story_1019_10190802_13_dialog_content = "게다가 개조한 병사든, 실험용 암귀든...",
  ui_story_1019_10190802_14_dialog_content = "당신의 실험동에서 도망쳐서 우리 동포들의 목숨을 위태롭게 했다면,\n우린 당신을 추궁할 권한이 있어요.",
  ui_story_1019_10190802_15_dialog_content = "금지 명령? 하하...",
  ui_story_1019_10190802_16_dialog_content = "그럼 누가 당신들에게 제 실험동에 들어와 실험용 암귀를 쓰러트리라는 권한을 줬습니까?",
  ui_story_1019_10190802_17_dialog_content = "위원회가 뭐라고 지껄이든 상관없어! 우리 임무는 모든 암귀를 없애는 거니까!",
  ui_story_1019_10190802_18_dialog_content = "목소리가 크다고 이치가 서는 게 아닙니다.\n다만 절 대신해 이 실험체들을 찾아준 능력은 조금 인정해 드리지요.",
  ui_story_1019_10190802_19_dialog_content = "이 빌어먹을 영감이 진짜!",
  ui_story_1019_10190802_20_dialog_content = "잠깐 부르의 시스템을 체크하고 있었는데, 왜 또 싸우기 시작한 거야...?",
  ui_story_1019_10190802_21_dialog_content = "율리시스, 이 사람들은 내가 불렀어. 내 일에 도움이 좀 필요하거든.\n당신이랑은 상관없어.",
  ui_story_1019_10190802_22_dialog_content = "잠깐...",
  ui_story_1019_10190802_23_dialog_content = "율리시스 님, 위원회에서 연락이 왔습니다...",
  ui_story_1019_10190802_24_dialog_content = "최종 심의회에 늦지 않게 참석하시라는 전갈입니다.",
  ui_story_1019_10190802_25_dialog_content = "...알겠네.",
  ui_story_1019_10190802_26_dialog_content = "(율리시스 교수, 지금 날 보고 있는 건가...?)",
  ui_story_1019_10190802_27_dialog_content = "오랜만이로군요, 아이테르 군.",
  ui_story_1019_10190802_28_dialog_content = "전에 회의실에서 만났을 때는 라인하르트와 함께였지요. 알골도 그 자리에 있었습니다.",
  ui_story_1019_10190802_29_dialog_content = "...그 재미없고 따분한 회의, 지금 생각해도 시간 낭비라고밖에 말할 수 없겠어.",
  ui_story_1019_10190802_30_dialog_content = "시간이 흘렀고, 세계에는 또 변화들이 있었습니다.\n아이테르 군이라면 모두 놓치지 않고 그 눈에 담아 두었겠지요.",
  ui_story_1019_10190802_31_dialog_content = "무슨 뜻이죠...?",
  ui_story_1019_10190802_32_dialog_content = "오래전부터... 전 어떤 특이한 장면을 보게 되곤 했습니다.\n그리고 최근 몇 년 사이에 그 빈도는 더 높아졌지요.",
  ui_story_1019_10190802_33_dialog_content = "그 장면은 너무나도 현실적이어서, 마치 제 몸을 뒤흔들고, 심장을 뛰게 만드는 듯했습니다.",
  ui_story_1019_10190802_34_dialog_content = "부부! 부부! 부부!",
  ui_story_1019_10190802_35_dialog_content = "어? 왜 그래...?",
  ui_story_1019_10190802_36_dialog_content = "심장...?",
  ui_story_1019_10190802_37_dialog_content = "하하, 우리는 모두 진실을 엿볼 수 있는 사람들입니다...\n하지만 누군가는 애써 절 그 진실로부터 떼어놓으려 하지요...",
  ui_story_1019_10190802_38_dialog_content = "그리고 당신이 생명의 비밀을 찾을 기회도 빼앗으려 합니다...\n그것은 당신에게 있어 정말 아쉬운 일일 겁니다.",
  ui_story_1019_10190802_39_dialog_content = "콜록... 심의회가 끝나면 과연 또 누가 암귀에 맞설 수 있을까요?",
  ui_story_1019_10190802_40_dialog_content = "뭔 헛소리를 하고 있어? 이 바튼, 아직까지 내가 이길 수 없는 적은 만난 적 없었다고.",
  ui_story_1019_10190802_41_dialog_content = "제 생각엔 당신은 그저 자기 잘못에 PlayerName도 끌어들여\n책임을 피하고 싶은 것처럼 보이는데요.",
  ui_story_1019_10190802_42_dialog_content = "그렇지 않습니다. 전 그저 아스트라의 아이테르에게 묻고 싶을 뿐입니다.\n당신, 설마 그런 호기심이 없는 겁니까?",
  ui_story_1019_10190802_43_dialog_content = "조금만 서두른다면, 여기서 그 진상을 볼 수 있을지도 모릅니다만...",
  ui_story_1019_10190802_44_dialog_content = "부부! 부부! 부부!",
  ui_story_1019_10190802_45_dialog_content = "으앗... 잠깐만, 지금 잘 모르겠어...",
  ui_story_1019_10190802_46_dialog_content = "부르가 왜 그래요?",
  ui_story_1019_10190802_47_dialog_content = "상태가 이상해. 지금까진 이런 반응을 보여준 적이 없었는데...",
  ui_story_1019_10190802_48_dialog_content = "하하, 그 이상이 일종의 행운일지 누가 알겠습니까?",
  ui_story_1019_10190802_49_dialog_content = "행운?",
  ui_story_1019_10190802_50_dialog_content = "악몽이 문을 두드릴 때, 누군가 대신 밤을 지켜주는 것은 곧 행운입니다.",
  ui_story_1019_10190802_51_dialog_content = "다만 지금은 아직 모든 게 불확실한 상태로군요...",
  ui_story_1019_10190802_52_dialog_content = "수수께끼 낼 시간이 있으면 병원에 가서 진찰이나 좀 받아보는 게 어때?",
  ui_story_1019_10190802_53_dialog_content = "하하, 젊음이란 참 좋군요.",
  ui_story_1019_10190802_54_dialog_content = "어떻습니까? PlayerName, 알고 싶은 진상이 있습니까?",
  ui_story_1019_10190802_55_dialog_content = "(설마...)",
  ui_story_1019_10190802_56_option_content = "(그 꿈의 진상을 알고 있는 건가...?)",
  ui_story_1019_10190802_57_option_content = "(바이스의 심장 소리에 대해 알고 있는 건가...?)",
  ui_story_1019_10190802_58_dialog_content = "(근데 이 사람이 만약 정말로 그걸 안다면... 대체 어떻게 안 거지?)",
  ui_story_1019_10190802_59_dialog_content = "(아니면 비비안 씨 말처럼 날 이용해서 처벌을 피하려는 걸까?)",
  ui_story_1019_10190802_60_dialog_content = "망설이는 모습을 보면 역시 의문이 있는 모양이군요.",
  ui_story_1019_10190802_61_dialog_content = "제 실험실에 와서 작은 「실험」을 하나 돕는다면, 그 답을 찾을 수 있을 겁니다.",
  ui_story_1019_10190802_62_dialog_content = "그뿐만 아니라... 당신의 한계도 알게 되겠지요.",
  ui_story_1019_10190802_63_dialog_content = "율리시스 박사, 대원수님께서 이미 확실하게 말씀하셨을 텐데요.\n그 어떤 실험이든 금지입니다!",
  ui_story_1019_10190802_64_dialog_content = "실험은커녕 PlayerName 털끝 하나라도 건드려 봐라.\n그 즉시 널 잡아다 처넣어주마.",
  ui_story_1019_10190802_65_dialog_content = "두 사람 모두 오해했군요.\n저야말로 PlayerName 군의 실험대에 오를 「실험」 대상입니다만.",
  ui_story_1019_10190802_66_dialog_content = "호기심에 근거한 그 어떤 가설이든, 검증을 위해선 실험을 통해야 하지 않습니까?",
  ui_story_1019_10190802_67_dialog_content = "무슨 실험을 하려는 거죠?",
  ui_story_1019_10190802_68_dialog_content = "아이테르의 감응 능력으로 제 꿈속 기묘한 장면을 보고...\n그 안에 당신이 원하는 답이 있는지 확인해 보는 겁니다.",
  ui_story_1019_10190802_69_dialog_content = "기묘한 꿈...?!",
  ui_story_1019_10190802_70_dialog_content = "부부! 부부! 부부!",
  ui_story_1019_10190802_71_dialog_content = "뭐가 어떻게 된 거야...? 아이테르, 얼른 가자.",
  ui_story_1019_10190802_72_dialog_content = "...안 갈래요.",
  ui_story_1019_10190802_73_dialog_content = "PlayerName?!",
  ui_story_1019_10190802_74_dialog_content = "그 실험, 해 보고 싶어요.",
  ui_story_1019_10190802_75_dialog_content = "부부! 부부! 부부!",
  ui_story_1019_10190802_76_dialog_content = "아니, 잠깐만... 그, 그만 좀 당겨...",
  ui_story_1019_10190802_77_dialog_content = "미안, 난 일단 부르부터 좀 진정시키고 있을게.",
  ui_story_1019_10190802_78_dialog_content = "걱정 마라. 내 임무 범위는 아니지만, 놈은 내가 잘 보고 있을 테니 말이야.",
  ui_story_1019_10190802_79_dialog_content = "PlayerName의 안전을 지키는 건 제 의무예요.",
  ui_story_1019_10190802_80_dialog_content = "제 실험실은 안전합니다. 들어오시지요.",
  ui_story_1019_10190901_1_dialog_content = "아이테르 군, 준비는 됐습니까? 시작하기 전에 질문을 하나 하고 싶습니다만.",
  ui_story_1019_10190901_2_dialog_content = "당신은 세상의 끝이 어디에 있다고 생각합니까?",
  ui_story_1019_10190901_3_dialog_content = "어둠의 위기가 다시 찾아온다면, 오로리안은 어떻게 해야 어둠의 침식에 맞설 수 있겠습니까?",
  ui_story_1019_10190901_4_dialog_content = "그런 건... 아직 생각해 본 적 없는데요.",
  ui_story_1019_10190901_5_dialog_content = "아이테르 일족은 한때 날아올라 아스트라 대륙을 떠나는 쾌거를 이루었습니다.\n설마 하늘 위 미지의 공간에 대해 알고 싶지 않은 겁니까?",
  ui_story_1019_10190901_6_dialog_content = "그건 고대의 아이테르와 콜로서스가 이룬 기적이고,\n지금의 저랑은 한참 동떨어진 얘기잖아요.",
  ui_story_1019_10190901_7_dialog_content = "전 그냥 평범한 아이테르고, 가장 멀리 가 본 것도 아스트라 대륙에서\n가까운 동쪽 대륙 정도예요.",
  ui_story_1019_10190901_8_dialog_content = "하하, 사람들은 늘 두려움으로 자신의 상상력을 제한하곤 하지요.",
  ui_story_1019_10190901_9_dialog_content = "왜 그런 말을 하는 거죠?",
  ui_story_1019_10190901_10_dialog_content = "곧 알게 될 겁니다. 그럼 이제 시작합시다.",
  ui_story_1019_10190901_11_dialog_content = "......",
  ui_story_1019_10190901_12_option_content = "(감응 연결!)",
  ui_story_1019_10190901_13_dialog_content = "(여긴... 북방?)",
  ui_story_1019_10190901_14_dialog_content = "(얼음 돌기둥이 잔뜩 있네... 마치 칼날처럼 하늘을 향하고 있어...)",
  ui_story_1019_10190901_15_dialog_content = "(아니, 이 어두운 느낌은... 오히려 어둠의 밑바닥 같아...)",
  ui_story_1019_10190901_16_dialog_content = "(전에 탐색한 오로라 유적에서도 검은 암석이 서늘한 기운을 내뿜고 있었어.)",
  ui_story_1019_10190901_17_dialog_content = "(근데 오로라 유적의 암석은 묵직하게 지면 위에 서 있었는데,\n여기 얼음 돌기둥은 공중에 떠 있어.)",
  ui_story_1019_10190901_18_dialog_content = "(그리고 어떤 것들은 빛을 내면서 위로 계속 자라고 있어...)",
  ui_story_1019_10190901_19_dialog_content = "(이게... 율리시스 교수의 기억인가? 왜 이런 데 왔던 거지?)",
  ui_story_1019_10190901_20_dialog_content = "(율리시스 교수의 의식 속에... 어떻게 이런 기억이 있는 거지?)",
  ui_story_1019_10190901_21_dialog_content = "(여긴 꼭 잊혀진 세계 같아. 생명의 기운이 전혀 없어...)",
  ui_story_1019_10190901_22_dialog_content = "<color=#e8d9bb>쿠구구구──</color>",
  ui_story_1019_10190901_23_dialog_content = "(뭐지...?!)",
  ui_story_1019_10190901_24_dialog_content = "(얼음 돌기둥이 움직이고 있어! 마치 어떤 힘에 이끌려 하늘로 모이는 것 같아...)",
  ui_story_1019_10190901_25_dialog_content = "(설마... 어떤 형태를 이루려고 하는 건가?)",
  ui_story_1019_10190901_26_dialog_content = "(여긴... 대체 어디지?)",
  ui_story_1019_10190901_27_dialog_content = "<color=#e8d9bb>쿠르릉──</color>",
  ui_story_1019_10190901_28_dialog_content = "후우...",
  ui_story_1019_10190901_29_dialog_content = "어떻습니까, 아이테르 군. 소감은?",
  ui_story_1019_10190901_30_dialog_content = "어이, 놈이 대체 너한테 뭘 보여준 거냐?",
  ui_story_1019_10190901_31_option_content = "방금 그건 어디죠?",
  ui_story_1019_10190901_32_dialog_content = "어디라...",
  ui_story_1019_10190901_33_option_content = "저한테 그걸 보여준 이유가 뭐죠?",
  ui_story_1019_10190901_34_dialog_content = "이유라...",
  ui_story_1019_10190901_35_dialog_content = "그곳은 세상의 끝입니다.",
  ui_story_1019_10190901_36_dialog_content = "그리고 바로 그곳에, 암귀가 숨어서 악마를 깨우려 하고 있습니다.",
  ui_story_1019_10190901_37_dialog_content = "악마...?",
  ui_story_1019_10190901_38_dialog_content = "(설마 전에 고대 전장에서 들었던 그걸 말하는 건가...?)",
  ui_story_1019_10190901_39_dialog_content = "근데 암귀 같은 건 없었어요. 그저 얼음 돌기둥만 잔뜩 있었고요...",
  ui_story_1019_10190901_40_dialog_content = "하하, 그건 이미 시작되었기 때문입니다.",
  ui_story_1019_10190901_41_dialog_content = "시작됐다뇨...?",
  ui_story_1019_10190901_42_dialog_content = "악마 소환 말입니다.",
  ui_story_1019_10190901_43_dialog_content = "......",
  ui_story_1019_10190901_44_dialog_content = "율리시스, 이 미친 자식, PlayerName한테서 떨어져!",
  ui_story_1019_10190901_45_dialog_content = "참모장님, 바튼 군단장님, PlayerName도 있었군요...",
  ui_story_1019_10190901_46_dialog_content = "아나톨리 소령, 마침 잘 왔어요.",
  ui_story_1019_10190901_47_dialog_content = "위원회에서 보냈겠군...",
  ui_story_1019_10190901_48_dialog_content = "네, 율리시스 박사님. 「계명성 프로젝트」의 조사를 위한 심의회 건으로 왔습니다.\n이미 연락을 드렸을 겁니다.",
  ui_story_1019_10190901_49_dialog_content = "참석할 걸세, 다만...",
  ui_story_1019_10190901_50_dialog_content = "위원회가 아이테르를 「오로리안을 구할 영웅」이라고 생각한다면,\n난 아이테르도 참석하게 해 주었으면 좋겠군.",
  ui_story_1019_10190901_51_dialog_content = "율리시스 박사님, 그건 아무래도 규정에 맞지 않을 것 같습니다.",
  ui_story_1019_10190901_52_dialog_content = "그럼 아이테르가 자유롭게 자난성을 드나드는 건 규정에 맞는 일이란 말인가?",
  ui_story_1019_10190901_53_dialog_content = "아이테르 군, 제 제안을 잘 생각해 보세요.\n당신은 분명히 무언가를 알고 싶어 하고 있습니다.",
  ui_story_1019_10190901_54_dialog_content = "그리고 온 일루미나에서 진상을 말해줄 수 있는 건 저뿐일지도 모릅니다.",
  ui_story_1019_10190901_55_dialog_content = "......",
  ui_story_1019_10190901_56_dialog_content = "지금 당신에게 가장 중요한 일이 뭔지 알고 있습니까?\n악마가 찾아오기 전에 살아남기 위한 준비를 하는 것입니다!",
  ui_story_1019_10190901_57_dialog_content = "......",
  ui_story_1019_10190901_58_dialog_content = "아나톨리, 율리시스 박사를 데려가세요.",
  ui_story_1019_10190901_59_dialog_content = "아이테르 군?",
  ui_story_1019_10190901_60_dialog_content = "......",
  ui_story_1019_10190901_61_dialog_content = "하하하하... 역시, 당신이 오로리안을 구한다니, 그럴 리가 있겠습니까!\n콜록, 콜록콜록콜록...",
  ui_story_1019_10190901_62_dialog_content = "망설이고... 나약하고... 포부라고는 조금도 없지 않습니까! 당신은... 콜록, 콜록콜록...",
  ui_story_1019_10190901_63_dialog_content = "늦어서 죄송합니다, 율리시스 님. 제가 부축해 드리겠습니다.",
  ui_story_1019_10190901_64_dialog_content = "필요 없어!",
  ui_story_1019_10190901_65_dialog_content = "으어...",
  ui_story_1019_10190901_66_dialog_content = "(...다크매터? 아니, 잠깐만... 뭔가 달라...)",
  ui_story_1019_10190901_67_dialog_content = "전... 절대 포기하지 않습니다... 모두 후회하게 될 겁니다! 콜록, 콜록...",
  ui_story_1019_10190901_68_dialog_content = "율리시스 님... 몸이 떨리시는데, 정말 괜찮으십니까?",
  ui_story_1019_10190901_69_dialog_content = "괜찮다고 말했지 않나!",
  ui_story_1019_10190901_70_dialog_content = "으아아아아!",
  ui_story_1019_10190901_71_dialog_content = "「희미한 빛은 어두운 그림자에 숨어 있는 것입니다.」",
  ui_story_1019_10190901_72_dialog_content = "아까랑 똑같아... 암귀 같은 적...",
  ui_story_1019_10190901_73_dialog_content = "저들은 적이 아닙니다...",
  ui_story_1019_10190901_74_dialog_content = "그럼 뭐죠?!",
  ui_story_1019_10190901_75_dialog_content = "...뭐, 해명은 심의회에 가서 하세요. PlayerName, 지휘를 부탁해요!",
  ui_story_1019_10190901_76_dialog_content = "알겠어!",
  ui_story_1019_10190902_1_dialog_content = "바튼 장군, 무기를 내려놓으세요!",
  ui_story_1019_10190902_2_dialog_content = "이미 대원수님께 보고드렸어요. 곧 사람들이 도착할 거예요.\n그리고 우리가 먼저 실험실을 조사하고 있으라는 명령을 내리셨어요.",
  ui_story_1019_10190902_3_dialog_content = "아직도 저 미치광이를 살려둘 생각이냐? 저놈들은 율리시스는 놔두고 우리만 노려서 공격했다!",
  ui_story_1019_10190902_4_dialog_content = "놈이 실험동의 암귀를 풀어놓기라도 하면 일루미나는 끝장이라고!",
  ui_story_1019_10190902_5_dialog_content = "바튼 장군, 지금 율리시스 박사 건은 아나톨리 소령이 책임자예요.\n대원수님께서도 진상을 반드시 규명하겠다고 말씀하셨고요.",
  ui_story_1019_10190902_6_dialog_content = "앗~ 사람이 많네? 나 뭐 재밌는 거 놓쳤어?",
  ui_story_1019_10190902_7_dialog_content = "젊은 친구도 있었잖아? 아무래도 전장의 세례를 받고 다들 꽤 성숙해진 모양이네.\n심지어... 냄새까지 달라졌잖아~",
  ui_story_1019_10190902_8_dialog_content = "......",
  ui_story_1019_10190902_9_dialog_content = "두 분이 절 막으시더라도 전 율리시스 박사를 데려가야 합니다.",
  ui_story_1019_10190902_10_dialog_content = "안 막을 거야. 우린 그냥 실험실 인수인계하러 온 거거든. 그러니까 다들 해산해도 좋아~",
  ui_story_1019_10190902_11_dialog_content = "제 실험실을 인계받겠다고요? 웃기는군요...",
  ui_story_1019_10190902_12_dialog_content = "과학 수석 의회의 의장은 접니다! 당신들은 평생을 바쳐도 제 업적을 넘어설 수 없습니다!",
  ui_story_1019_10190902_13_dialog_content = "업적은 높을수록 좋지! 그치만 일루미나는 지식의 독점을 허용하지 않는다구.\n여기 자료들 중에 이 그로누 님이 이해 못 할 게 있을 것 같아?",
  ui_story_1019_10190902_14_dialog_content = "아무튼, 가기 전에 컴퓨터 권한 좀 넘겨줘~",
  ui_story_1019_10190902_15_dialog_content = "실험용 암귀와 생물 재료는 우리 블랙 엄브렐라 연구소가 인수할게.",
  ui_story_1019_10190902_16_dialog_content = "걱정 마. 내가 있는 한, 연구동 지역엔 암귀 한 마리라도\n멋대로 다니는 일은 없을 테니까.",
  ui_story_1019_10190902_17_dialog_content = "아이테르 군, 정말 알고 싶지 않습니까?!",
  ui_story_1019_10190902_18_option_content = "(알고 싶지 않아...)",
  ui_story_1019_10190902_19_dialog_content = "(율리시스 교수와 아까 그 장면은... 대체 무슨 관계일까...\n아무리 생각해도 이상해...)",
  ui_story_1019_10190902_20_dialog_content = "(비비안 씨한테도 아까 본 걸 말해주는 게 좋을 것 같아..)",
  ui_story_1019_10190902_21_option_content = "(알고 싶어...)",
  ui_story_1019_10190902_22_dialog_content = "(율리시스 교수는 왜 아까 그 장면을 나한테 보여준 거지...?\n설마, 정말로 나한테 뭔가 알려주고 싶은 게 있는 건가?)",
  ui_story_1019_10190902_23_dialog_content = "(하지만 저 사람 상태, 뭔가 이상해. 어쩌면 믿어선 안 될지도 몰라...)",
  ui_story_1019_10190902_24_dialog_content = "심의회가 끝나면 모든 게 밝혀지겠죠.",
  ui_story_1019_10190902_25_dialog_content = "하하... 하하하하...",
  ui_story_1019_10190902_26_dialog_content = "이것이 오로리안의 말로란 말입니까...\n제 평생 심혈을 기울인 결과가 당신들 같은 어리석은 자들에게 짓밟히고 말았군요.",
  ui_story_1019_10190902_27_dialog_content = "뭐, 됐습니다...",
  ui_story_1019_10190902_28_dialog_content = "그렇다면 제가 직접 모든 것을 밝히도록 하겠습니다.",
  ui_story_1019_10190902_29_dialog_content = "당신들도 역사의 증인이 될 수 있다면, 그것도 영광이라 할 수 있겠지요...",
  ui_story_1019_10190902_30_dialog_content = "벨리사리아에게 전해라. 난 내 증인들을 부를 거다.",
  ui_story_1019_10190902_31_dialog_content = "증인이요? 누굴 말씀하시는 겁니까?",
  ui_story_1019_10190902_32_dialog_content = "잉겔, 악셀리아, 숀, 넌 가서 데려오기만 하면 된다.",
  ui_story_1019_10190902_33_dialog_content = "네, 율리시스 님.",
  ui_story_1019_10190902_34_dialog_content = "......",
  ui_story_1019_10190902_35_dialog_content = "PlayerName, 당신이 걱정하는 건 이미 대원수님께도 전해드렸어요.\n하지만 지금은 율리시스 박사를 심의회로 보내는 수밖에 없어요.",
  ui_story_1019_10190902_36_dialog_content = "저들이 진상이 밝히기 전까지, 우린 해야 할 더 중요한 일이 있어요.\n잊지 마세요. 우린 지금 좌표 탐색이 더 중요해요.",
  ui_story_1019_10190902_37_dialog_content = "응... 근데 난 저 사람이 한 말이 계속 신경 쓰여...",
  ui_story_1019_10190902_38_dialog_content = "당신은 세상의 끝이 어디에 있다고 생각합니까?",
  ui_story_1019_10190902_39_dialog_content = "어둠의 위기가 다시 찾아온다면, 오로리안은 어떻게 해야 어둠의 침식에 맞설 수 있겠습니까?",
  ui_story_1019_10190902_40_dialog_content = "하아── 후우──",
  ui_story_1019_10190902_41_dialog_content = "아마 요즘 잠을 잘 못 자서 그런 걸지도 몰라. 왠지 항상 멍하고,\n뭔가 소중한 걸 잃어버린 것 같은 느낌이 들거든.",
  ui_story_1019_10190902_42_dialog_content = "설령 정말로 무언가를 잃어버렸더라도, 나아갈 길이 아득하고 어둡더라도,\n전 당신이 용감하게 찾으러 갈 거라고 믿어요.",
  ui_story_1019_10190902_43_dialog_content = "하지만 일루미나는 달라요. 일루미나는 우리의 터전이자 희망이에요.",
  ui_story_1019_10190902_44_dialog_content = "만약 여기서 지하성의 하늘을 볼 수 있다면...",
  ui_story_1019_10190902_45_dialog_content = "지상엔 이미 해가 떠 있겠죠.",
  ui_story_1019_10190902_46_dialog_content = "그리고 일루미나인에게 있어서는 지하성을 떠나 햇빛 아래 서는 게\n우리가 갈 수 있는 가장 먼 곳이에요.",
  ui_story_1019_10190902_47_dialog_content = "자난성은 십 년이 하루 같고, 태양도 보이지 않는다.\n하지만 오히려 어둠에 침식될 걱정을 할 필요도 없지.",
  ui_story_1019_10190902_48_dialog_content = "그저 시간이 흐르면서 우린 점점 더 지하 깊은 곳으로 들어갈 뿐이다.",
  ui_story_1019_10190902_49_dialog_content = "처음 세워졌을 때의 자난성은 어떤 모습이었을지 정말 궁금하네요...",
  ui_story_1019_10190902_50_dialog_content = "한 가지만은 확실하겠지. 어디에나 암귀가 있었을 거다.",
  ui_story_1019_10190902_51_dialog_content = "암귀의 위협이 우릴 이곳에서 살게 했고, 암귀를 없애는 걸 우리의 목표로 만들었으니까.",
  ui_story_1019_10190902_52_dialog_content = "과연 심문이 끝난 뒤 일루미나의 미래는 어떻게 될지 모르겠군.",
  ui_story_1019_10190902_53_dialog_content = "......",
  ui_story_1019_10190902_54_dialog_content = "어이, 애송이. 생각이 많이 들 거다. 그래도 정신 바짝 차려!",
  ui_story_1019_10190902_55_dialog_content = "네, 두 사람이랑 얘기하다 보니까 조금 기운이 난 것 같아요.",
  ui_story_1019_10190902_56_dialog_content = "아마 알골 박사가 말했던 「생체 시계」가 움직이고 있는 거겠죠.\n지금이 딱 하루를 시작할 시간인 거예요.",
  ui_story_1019_10190902_57_dialog_content = "그런가...",
  ui_story_1019_10190902_58_dialog_content = "그럼... 두 사람 모두 좋은 아침이에요.",
  ui_story_1019_10190902_59_dialog_content = "네, 좋은 아침입니다, PlayerName.",
  ui_story_1019_10190902_60_dialog_content = "좋은 아침이다, 일루미나! 그럼 얼른 너희 일을 하러 가라. 모든 게 빨리 끝나길 빌겠다.",
  ui_story_1019_10191001_1_dialog_content = "<color=#e8d9bb>침묵에 잠긴 일루미나 고위층 회의실</color>",
  ui_story_1019_10191001_2_dialog_content = "절 단죄할 때가 되니 오히려 아무도 말을 못 하는군요.",
  ui_story_1019_10191001_3_dialog_content = "크흠...",
  ui_story_1019_10191001_4_dialog_content = "으음...",
  ui_story_1019_10191001_5_dialog_content = "벌써 다섯 번째 심의회야. 아니면 방식을 좀 바꿔서 편하게 대화나 좀 나눠보는 건 어때?\n당신 증인도 데려온 거 아냐?",
  ui_story_1019_10191001_6_dialog_content = "......",
  ui_story_1019_10191001_7_dialog_content = "대화? 대체 언제까지 질질 끌 생각이냐.\n우리 군의 결의와 실력은 더스크 타운과 일루미나 방어선 전투에서 이미 증명했다!",
  ui_story_1019_10191001_8_dialog_content = "연합 훈련 사건의 증인 헬리오스는 아직 의식을 완전히 회복하진 못했어.\n「계명성 프로젝트」에 참가한 병사들의 신체 상태도 아직 검사 중이야.",
  ui_story_1019_10191001_9_dialog_content = "전부 변명일 뿐이다. 확실한 증거를 제시하란 말이다!",
  ui_story_1019_10191001_10_dialog_content = "맞아. 연합 훈련이든, 「계명성 프로젝트」든, 직접 겪은 나라면 증인으로 충분하잖아!",
  ui_story_1019_10191001_11_dialog_content = "수술 후 회복은 순조로운 모양이네, 레이스 대원수.",
  ui_story_1019_10191001_12_dialog_content = "너희들 말은 이해해. 하지만 우린 율리시스 박사의 입장과 공헌을 무시할 수도 없어.",
  ui_story_1019_10191001_13_dialog_content = "심의회를 여기까지 끌어놓고, 아직도 부족해?",
  ui_story_1019_10191001_14_dialog_content = "우리는 율리시스에게 기회를 주겠다. 단, 이번이 마지막이다.",
  ui_story_1019_10191001_15_dialog_content = "라인하르트?",
  ui_story_1019_10191001_16_dialog_content = "단, 조건이 있다. 우리 군도 더는 양보하지 않겠다.\n최종 심판 전에 나도 내 증인을 부르겠다.",
  ui_story_1019_10191001_17_dialog_content = "그땐 너희도 율리시스를 단죄할 수밖에 없을 거다.",
  ui_story_1019_10191001_18_dialog_content = "물론이지. 그럼 남은 시간을 알차게 써 보자, 율리시스.\n마지막 진술에서 난 좀 다른 이야기를 듣고 싶거든.",
  ui_story_1019_10191001_19_dialog_content = "하하... 전... 콜록콜록...",
  ui_story_1019_10191001_20_dialog_content = "율리시스 님, 약 여기 있습니다...",
  ui_story_1019_10191001_21_dialog_content = "......",
  ui_story_1019_10191001_22_dialog_content = "...별일 아닙니다. 요즘 몸이 안 좋아서 말이지요. 조금 피곤하군요.",
  ui_story_1019_10191001_23_dialog_content = "이미 말씀드렸듯이, 저는 그 어떤 일도 숨기지 않았습니다.",
  ui_story_1019_10191001_24_dialog_content = "묻지 않으면 말하지도 않으니 당연히 숨기지 않은 셈이겠지.",
  ui_story_1019_10191001_25_dialog_content = "다만 지금까지 당신의 연구 성과, 그리고 당신이 실험실을 떠난 후에도\n당신 팀이 연구를 계속할 수 있을지 솔직히 말해 줬으면 해.",
  ui_story_1019_10191001_26_dialog_content = "어쨌든 당신 임무는 역사가 남긴 거니까, 다음 세대에 물려줘야지.",
  ui_story_1019_10191001_27_dialog_content = "제가 너무 오래 살았다고 탓하는 겁니까? 하하...",
  ui_story_1019_10191001_28_dialog_content = "저 율리시스는 서광력 1945년에 태어나, 이미 반세기 이상을 살아왔습니다...",
  ui_story_1019_10191001_29_dialog_content = "일루미나 오로리안의 평균 수명으로 보자면,\n전 같은 나이대 사람들처럼 진작에 죽어야 했지요.",
  ui_story_1019_10191001_30_dialog_content = "당신들은 일루미나가 세워진 이래로 「엔지니어」의 속박을 받아 온 난제를,\n정말 전쟁과 총포밖에 모르는 저 군인들에게 맡길 생각입니까?",
  ui_story_1019_10191001_31_dialog_content = "......",
  ui_story_1019_10191001_32_dialog_content = "「엔지니어」? 무슨 소리야?",
  ui_story_1019_10191001_33_dialog_content = "라인하르트, 넌 뭐 아는 거 있어?",
  ui_story_1019_10191001_34_dialog_content = "......",
  ui_story_1019_10191001_35_dialog_content = "율리시스, 말 돌리지 마. 대체 「계명성 프로젝트」를 진행한 목적이 뭐야?",
  ui_story_1019_10191001_36_dialog_content = "오로리안의 생존 능력 제고를 위해, 일루미나는 오랫동안 오로리안 개조 실험을 해 왔습니다.\n그건 이제 여러분도 모두 알게 되었지요.",
  ui_story_1019_10191001_37_dialog_content = "초기의 기체 강화 실험부터, 현재의 「계명성 프로젝트」에 이르기까지 탄생한 우수한 개체들이\n모두 이 자리에 모여 있습니다. 헬리오스와 드니에르를 제외하고 말이지요.",
  ui_story_1019_10191001_38_dialog_content = "......",
  ui_story_1019_10191001_39_dialog_content = "......",
  ui_story_1019_10191001_40_dialog_content = "기체 강화 실험...? 우수한 개체?",
  ui_story_1019_10191001_41_dialog_content = "일루미나 연방의 군인 중에는 전투력을 높여 다른 이들의 목숨을\n지키고 있는 자들이 적지 않습니다.",
  ui_story_1019_10191001_42_dialog_content = "또한 신체 기능의 결함을 가진 오로리안이 개조 기술로\n생명을 연장하고 있는 경우도 많지요...",
  ui_story_1019_10191001_43_dialog_content = "박사님... 왜... 절 보시는 거죠?",
  ui_story_1019_10191001_44_dialog_content = "제가 그... 개조 기술로 생명을 연장하고 있는 오로리안인가요...?",
  ui_story_1019_10191001_45_dialog_content = "......",
  ui_story_1019_10191001_46_dialog_content = "...농담이죠...? 전 그냥 정기적으로 검사만 받으러 온 건데요...\n개조 기술로 제 생명을 연장하고 있다고요...?",
  ui_story_1019_10191001_47_dialog_content = "당신은 평범한 오로리안이 아닙니다, 숀.\n당신은 「계명성 프로젝트」의 우수한 개체 중 하나입니다.",
  ui_story_1019_10191001_48_dialog_content = "......",
  ui_story_1019_10191001_49_dialog_content = "믿기 어렵습니까? 하지만 당신들은 모를 겁니다. 자신들이 얼마나 운이 좋은지 말입니다.",
  ui_story_1019_10191001_50_dialog_content = "전쟁의 한가운데에서 살아온 제 시대의 사람들 사이에서는,\n싸울 수 있는 자가 곧 무력한 자의 생살여탈권을 지닌 존재였습니다.",
  ui_story_1019_10191001_51_dialog_content = "여러분이 제 입장이었다면 어떤 선택을 했을 것 같습니까...?",
  ui_story_1019_10191001_52_dialog_content = "율리, 오늘은 또 어떤 새로운 문제가 떠올랐지?",
  ui_story_1019_10191001_53_dialog_content = "평소랑 똑같아.",
  ui_story_1019_10191001_54_dialog_content = "하하, 유전공학이로군. 선배들은 이런 명칭을 대체 어떻게 생각해 낸 걸까?",
  ui_story_1019_10191001_55_dialog_content = "어떻게 생각해 냈는지가 중요한가?",
  ui_story_1019_10191001_56_dialog_content = "중요한 건 내가 지금 그걸 연구하고 있다는 거지.",
  ui_story_1019_10191001_57_dialog_content = "「선배들이 어떻게 생각해 냈는가」, 나는 한 번도 그런 문제를 생각해 본 적 없었다.\n그렇게 근원을 찾아서 거슬러 올라가 보면 결과는 늘 우스울 뿐이었기 때문이다...",
  ui_story_1019_10191001_58_dialog_content = "자난성은 백야성의 한 선발대에 의해 발견되었다.",
  ui_story_1019_10191001_59_dialog_content = "두려움을 모르는 이 전사들은 암귀에 맞서 싸우는 과정에서 괴멸적인 타격을 받았다.\n그러나 이어진 결과는 백야성으로부터 버림받는 것이었다...",
  ui_story_1019_10191001_60_dialog_content = "그 선발대는 결국 지금처럼 지하성에 틀어박혀 살아가는 군사 연방으로 변모했다.",
  ui_story_1019_10191001_61_dialog_content = "하지만 왜인지... 라빌의 말은 줄곧 내 머릿속에서 떠나질 않았다.",
  ui_story_1019_10191001_62_dialog_content = "율리, 오늘은 또 어떤 새로운 문제가 떠올랐지?",
  ui_story_1019_10191001_63_dialog_content = "......",
  ui_story_1019_10191001_64_dialog_content = "뭘 그렇게 정신없이 읽고 있어?",
  ui_story_1019_10191001_65_dialog_content = "「일루미나 연방 역사 연감」? 그런 걸 읽을 시간도 있나?\n오늘은 갑자기 역사에 흥미라도 생긴 건가?",
  ui_story_1019_10191001_66_dialog_content = "라빌, 일루미나 연방이 세워진 지 얼마나 됐는지 아나?",
  ui_story_1019_10191001_67_dialog_content = "<color=#FFB400>649년.</color>",
  ui_story_1019_10191001_68_dialog_content = "...잘도 기억하고 있군.",
  ui_story_1019_10191001_69_dialog_content = "당연하지. 아버지 반대만 아니었으면 난 어머니의 격려를 받으면서\n역사학자가 됐을 테니까.",
  ui_story_1019_10191001_70_dialog_content = "그래서? 고작 날 시험하려고 그걸 물어본 건 아니겠지?",
  ui_story_1019_10191001_71_dialog_content = "유전공학의 발전 과정을 돌아보고 있었거든.\n그런데 「일루미나 연방 역사 연감」을 읽다 보니까 문제를 하나 찾았어.",
  ui_story_1019_10191001_72_dialog_content = "지금 일루미나엔 유전공학의 시작에 대한 기록이 없어.\n마치 유전자 개조 기술이 그 탄생 순간부터 이미 높은 수준에 있었던 것처럼 말이야.",
  ui_story_1019_10191001_73_dialog_content = "설마 유전공학이 백야성의 기술이었던 건가?\n일루미나가 세워지기 전부터 존재했다든지 말이야.",
  ui_story_1019_10191001_74_dialog_content = "아니면... 일루미나의 역사가 649년이 아니거나.",
  ui_story_1019_10191001_75_dialog_content = "그럴 수도 있겠지. 난 계속 연구해 볼 생각이야.",
  ui_story_1019_10191001_76_dialog_content = "그리고 나는 마치 무언가에 홀린 듯 이 문제에 대해 조사하기 시작했다.",
  ui_story_1019_10191001_77_dialog_content = "자료관 밖이 평화로운지, 전란이 벌어지는지 나는 알지 못했다.",
  ui_story_1019_10191001_78_dialog_content = "내가 아는 것이라고는 그저 전쟁의 여파가 미치지 않는 이 작은 자료실에서,\n내가 진상을 쫓는 일에 영향을 미치는 것은 오직 시간뿐이라는 사실이었다.",
  ui_story_1019_10191001_79_dialog_content = "하루... 그리고 한 달...",
  ui_story_1019_10191001_80_dialog_content = "머릿속에서 한 목소리가 내게 말해주었다.\n실험의 실패 따위는 이제 두려워할 게 없고, 역사가 답을 알려줄 것이라고.",
  ui_story_1019_10191001_81_dialog_content = "일 년... 그리고 이 년...",
  ui_story_1019_10191001_82_dialog_content = "그러다 어느 날...",
  ui_story_1019_10191001_83_dialog_content = "라빌! 라빌! 빨리 와서 이것 좀 봐... 오른쪽 밑에 쓰인 글자!",
  ui_story_1019_10191001_84_dialog_content = "...「엔지니어」?",
  ui_story_1019_10191001_85_dialog_content = "이게 뭐지?",
  ui_story_1019_10191001_86_dialog_content = "지금까지 읽어온 자료엔 유전공학의 기원에 대한 기록이 없거나,\n간단한 설명밖에 돼 있지 않았지.",
  ui_story_1019_10191001_87_dialog_content = "하지만 이 책의 이 부분이 나한테 답을 줬어.",
  ui_story_1019_10191001_88_dialog_content = "「...의 도움으로 루미나 과부하 문제를 해결했고....」",
  ui_story_1019_10191001_89_dialog_content = "누구의 도움으로?",
  ui_story_1019_10191001_90_dialog_content = "그래! 그게 누구겠어?",
  ui_story_1019_10191001_91_dialog_content = "...「엔지니어」? 넌 책에서 삭제된 정보가 「엔지니어」라고 생각하는 건가?",
  ui_story_1019_10191001_92_dialog_content = "내 직감이 그렇게 말하고 있어.",
  ui_story_1019_10191001_93_dialog_content = "재미있네... 본문에서는 삭제했는데, 답을 구석에 남겨두다니...",
  ui_story_1019_10191001_94_dialog_content = "하지만 율리, 확신할 수 있나? 비슷한 상황이 또 있었어?",
  ui_story_1019_10191001_95_dialog_content = "아니, 없어... 하지만 난해한 자료도 이 「엔지니어」의 가설을 더해서 읽어나가면...",
  ui_story_1019_10191001_96_dialog_content = "그래, 모든 게 말이 됐지...",
  ui_story_1019_10191001_97_dialog_content = "「엔지니어의 인솔하에 일부 오로리안은 빠르게 연구진을 조직해\n고대 과학기술 연구를 시작했다.」",
  ui_story_1019_10191001_98_dialog_content = "「엔지니어는 연구진을 인솔해 자난성의 전체 구조를 참관했고,\n연구진에게 일부 과학기술의 사용법을 가르쳤다.」",
  ui_story_1019_10191001_99_dialog_content = "율리, 네가 그렇게 신난 건 처음 보는군.",
  ui_story_1019_10191001_100_dialog_content = "계속 찾아봐야겠어!",
  ui_story_1019_10191001_101_dialog_content = "자료실 밖으로 끊임없이 울리는 포화 소리도...",
  ui_story_1019_10191001_102_dialog_content = "내게 조금만 더 시간을 준다면, 그것은 오로리안이 암귀를 물리친 축포 소리가 될 것이라고...\n나는 그렇게 믿었다.",
  ui_story_1019_10191101_1_dialog_content = "어둠의 밑바닥 지도 제작은 좀 어때?",
  ui_story_1019_10191101_2_dialog_content = "오, 알골 박사 아닙니까. 당신이 실험실에서 나와서 바깥바람을 쐬다니, 정말 별일이네요!",
  ui_story_1019_10191101_3_dialog_content = "안녕하세요, 조이스 박사.",
  ui_story_1019_10191101_4_dialog_content = "네, 안녕하세요. 어? 이쪽은... 아이테르 아닙니까?",
  ui_story_1019_10191101_5_dialog_content = "안녕하세요.",
  ui_story_1019_10191101_6_dialog_content = "알골 박사한테 들었습니다. 당신 콜로서스의 기능은 제 어둠의 밑바닥 지도의\n모델 구축에 큰 도움이 되었습니다. 정말 감사합니다!",
  ui_story_1019_10191101_7_dialog_content = "천만에요, 일루미나를 돕겠다고 약속도 했고, 이건 저를 돕는 일이기도 하니까요.",
  ui_story_1019_10191101_8_dialog_content = "조이스, 잡담은 그만하고, 당신 의견을 들려줘.\n어둠의 밑바닥 좌표를 하나 찾았는데, 탐색할 가능성이 있을까?",
  ui_story_1019_10191101_9_dialog_content = "어둠의 밑바닥에 관한 새로운 데이터란 말입니까...?\n이러다 곧 <color=#FFB400>지형 모델 시뮬레이션</color>의 진도를 따라잡겠군요.",
  ui_story_1019_10191101_10_dialog_content = "당신도 알다시피, 제 환경 모델은 현재 알려진 영역의 연속성을 바탕으로\n계산을 수행하고 구축한 겁니다.",
  ui_story_1019_10191101_11_dialog_content = "즉, 좌표와 자난성의 거리가 멀고, 그 사이에 지층을 달리하는 대륙이 있다면,\n매우 복잡한 계산이 필요하게 되죠.",
  ui_story_1019_10191101_12_dialog_content = "현 단계에서는 확률의 가중치를 바탕으로 연속과 불연속 패턴에 각각 계산을 수행한 후,\n기존 환경 데이터를 참조하면서 추산할 수밖에 없겠군요.",
  ui_story_1019_10191101_13_dialog_content = "그래서? 추산 결과는?",
  ui_story_1019_10191101_14_dialog_content = "그렇게나 인내심이 없는 겁니까...?",
  ui_story_1019_10191101_15_dialog_content = "그냥 결과부터 말해.",
  ui_story_1019_10191101_16_dialog_content = "휴, 좋습니다...\n제 지형 모델은 헬리오스가 제공한 단서를 바탕으로 아직 수정하고 있는 중입니다만...",
  ui_story_1019_10191101_17_dialog_content = "아스트라의 거주 가능 지역 바깥에는 두께가 불균일한 얼음 습지가 있습니다.\n그 위에는 눈이 얇게 덮여 있지요.",
  ui_story_1019_10191101_18_dialog_content = "습지를 지나면 높이가 고르지 않은 빙탑의 숲이 있는데,\n그 빙탑의 형상은 저마다 다양합니다...",
  ui_story_1019_10191101_19_dialog_content = "어떤 건 날카로운 삼각뿔형이고, 어떤 건 역원추형이고,\n어떤 건 뒤틀린 나선형도 있는데...",
  ui_story_1019_10191101_20_dialog_content = "쓸데없는 건 됐으니까 중점만!",
  ui_story_1019_10191101_21_dialog_content = "부! 부! 부!",
  ui_story_1019_10191101_22_dialog_content = "어? 부르 넌 관심 있다고?",
  ui_story_1019_10191101_23_dialog_content = "부! 부! 부!",
  ui_story_1019_10191101_24_dialog_content = "......",
  ui_story_1019_10191101_25_dialog_content = "<color=#e8d9bb>조이스가 15분간 설명한 후...</color>",
  ui_story_1019_10191101_26_dialog_content = "...그래서 이 빙탑 안의 일부 공기가 온도 차로 인해 액화되어,\n기괴한 돌기둥과 얼음기둥이 형성된 것입니다.",
  ui_story_1019_10191101_27_dialog_content = "그 원리는 저도 잘 모르겠습니다만, 어쩌면 백야성의 부유 기술과 관계가 있을지도 모릅니다.",
  ui_story_1019_10191101_28_dialog_content = "하지만 기류가 응고할 경우 어떤 건 상승하고, 어떤 건 하강하게 되죠...",
  ui_story_1019_10191101_29_dialog_content = "잠깐만요! 방금 뭐라고 했죠?",
  ui_story_1019_10191101_30_dialog_content = "...그래서 돌의 형상에 큰 차이가 발생하게 되는 겁니다. 그게 제 결론입니다.",
  ui_story_1019_10191101_31_dialog_content = "어떤 걸 물어본 겁니까?",
  ui_story_1019_10191101_32_dialog_content = "상승하는 돌기둥이요...",
  ui_story_1019_10191101_33_dialog_content = "율리시스 교수의 의식 속에서 비슷한 걸 봤어요...",
  ui_story_1019_10191101_34_dialog_content = "잘못 본 게 아니에요... 이게 우연일까요?",
  ui_story_1019_10191101_35_dialog_content = "......",
  ui_story_1019_10191101_36_dialog_content = "조이스, 돌기둥 얘기 좀 다시 해 봐.",
  ui_story_1019_10191101_37_dialog_content = "기류가 응고할 경우 어떤 건 상승하고, 어떤 건 하강해서\n돌의 형상에 큰 차이가 발생하게 되는 거라고요.",
  ui_story_1019_10191101_38_dialog_content = "상승과 하강이라고 하니 우리가 전에 했던 실험이 하나 기억이 나는군요. 그때...",
  ui_story_1019_10191101_39_dialog_content = "틀림없어요...",
  ui_story_1019_10191101_40_dialog_content = "생각해 보니까 그 떠오르는 얼음 돌기둥 중엔 빛나는 고리 같은 게 끼워진 것도 있었어요.",
  ui_story_1019_10191101_41_dialog_content = "...「가디언 1호」의 코어가 보인 거야? 얼음 돌기둥 안에 코어가 있었다고?!",
  ui_story_1019_10191101_42_dialog_content = "...이런 거?",
  ui_story_1019_10191101_43_dialog_content = "네! 맞아요! 이거였어요!",
  ui_story_1019_10191101_44_dialog_content = "재미있네... 아주 재미있어!",
  ui_story_1019_10191101_45_dialog_content = "네가 율리시스 의식 속에서 본 건, 어둠의 밑바닥 정찰대가 보낸\n「가디언 1호」의 코어로 보이는 이미지와 똑같아...",
  ui_story_1019_10191101_46_dialog_content = "게다가 스카이워커호의 데이터 속에 있던 좌표 주위엔 상승하는 얼음 돌기둥이 있어...",
  ui_story_1019_10191101_47_dialog_content = "이제 알겠어... 신호가 깜빡이는 건 좌표가 여러 개라서가 아니라\n얼음 돌기둥이 이동하고 있어서였어!",
  ui_story_1019_10191101_48_dialog_content = "잠깐 정리 좀 해 볼게요. 그럼 율리시스 박사가 코어의 위치도 알고 있을 뿐만 아니라,\n코어는 콜로서스가 탄생한 장소에 있을 가능성이 높다는 건가요?",
  ui_story_1019_10191101_49_dialog_content = "...게다가 그 사람, 왠지 바이스한테 무슨 일이 생긴 건지 아는 듯했어요!",
  ui_story_1019_10191101_50_dialog_content = "......",
  ui_story_1019_10191101_51_dialog_content = "아무래도 제가 큰 도움이 된 것도 모자라서, 거대한 비밀까지 파헤쳐 버린 모양이군요.",
  ui_story_1019_10191101_52_dialog_content = "쓰읍... 율리시스가 이클립스와 모종의 관계가 있다면...\n어떻게 생각해도 좋은 소식은 아니긴 하지...",
  ui_story_1019_10191101_53_dialog_content = "하지만 율리시스는 한 번도 지하성을 떠난 적이 없었어.\n근데 어떻게 이클립스의 계획과 그렇게 깊게 관련될 수 있었던 거지...?",
  ui_story_1019_10191101_54_dialog_content = "전 얼마 전 팬텀이 자난성에 잠입해 가디언 1호의 코어를 훔친 것도\n율리시스 교수와 관계가 있을지도 모른다고 생각해요.",
  ui_story_1019_10191101_55_dialog_content = "좀 더 대담한 추측도 해 볼 수 있겠지...",
  ui_story_1019_10191101_56_dialog_content = "「가디언 1호」는 내 시스템 감시의 눈을 피할 수 없어. 그걸 피했다는 건...",
  ui_story_1019_10191101_57_dialog_content = "「안전상의 이유로 봉인된」 프로토타입을 사용했을 가능성밖에 없어.",
  ui_story_1019_10191101_58_dialog_content = "......",
  ui_story_1019_10191101_59_dialog_content = "율리시스 박사가 몰래 프로토타입을 조종했다면, 반드시 회의에서 제대로 추궁해야만 해요.",
  ui_story_1019_10191101_60_dialog_content = "아니, 그냥 곧바로 연구실로 가자.",
  ui_story_1019_10191101_61_dialog_content = "우리 추측이 맞다면 율리시스의 연구실이야말로 지금 일루미나에서 가장 위험한 곳이야!",
  ui_story_1019_10191101_62_dialog_content = "......",
  ui_story_1019_10191201_1_dialog_content = "질문해도 될까? 너흰 대체 뭘 하고 있는 거야? 기록을 삭제하고, 역사를 은폐하다니...",
  ui_story_1019_10191201_2_dialog_content = "「엔지니어」에 대해선 대체 뭘 숨긴 건데?\n아니면 백야성에 무슨 말 못 할 비밀이라도 있는 거야?",
  ui_story_1019_10191201_3_dialog_content = "지금 장담할 수 있는 건 「엔지니어」에 관한 정보는 일루미나의 기록에만 존재하고,\n위원회도 그걸 아직 충분히 파악하진 못했다는 것뿐이야.",
  ui_story_1019_10191201_4_dialog_content = "장난해? 내가 바보로 보여?!",
  ui_story_1019_10191201_5_dialog_content = "그 정보는 확실히 위원회가 삭제한 게 아닙니다.",
  ui_story_1019_10191201_6_dialog_content = "적어도 지금의 위원회는 아니지요.",
  ui_story_1019_10191201_7_dialog_content = "어둠의 위기 때 일루미나 상부가 「가디언 프로토타입」의 연구 제한을 해제하지 않았다면,\n저도 「엔지니어」의 자료를 찾아낼 수 없었을 것입니다.",
  ui_story_1019_10191201_8_dialog_content = "「가디언 프로토타입」...?",
  ui_story_1019_10191201_9_dialog_content = "백야성 선발대가 자난성에서 발견했던 신비한 고대의 기계를 말하는 것입니다.",
  ui_story_1019_10191201_10_dialog_content = "훗날 자난성 사람들에 의해 「가디언」이라는 이름이 붙여졌지요.",
  ui_story_1019_10191201_11_dialog_content = "그 「가디언」을 지금도 연구하고 있어?",
  ui_story_1019_10191201_12_dialog_content = "알골이 가지고 있는 건 <color=#FFB400>샌드박스로 격리한</color> 복제일 뿐이야.\n프로토타입은 안전상의 이유로 봉인돼 있어.",
  ui_story_1019_10191201_13_dialog_content = "그게 원래 계획이었지요...",
  ui_story_1019_10191201_14_dialog_content = "...율리시스... 당신 설마?!",
  ui_story_1019_10191201_15_dialog_content = "하하... 전 늘 생각해 왔습니다.\n프로토타입의 봉인과 「엔지니어」의 정보 은폐 사이에는 분명히 모종의 관계가 있다고 말입니다.",
  ui_story_1019_10191201_16_dialog_content = "그리고 제가 프로토타입 안에서 「엔지니어」가 남긴 대량의 작업 메모를 발견했을 때...",
  ui_story_1019_10191201_17_dialog_content = "<color=#e8d9bb>휘리릭──</color>",
  ui_story_1019_10191201_18_dialog_content = "율리, 여기 있었군! 한참 찾았잖아. 전장에 나간 건 아닌가 다들 걱정했다고.",
  ui_story_1019_10191201_19_dialog_content = "다들 네가 다시 일어서지 못할 거라고 했지만, 난 아냐.\n네가 그런 좌절에 포기하지 않을 거란 걸 아니까.",
  ui_story_1019_10191201_20_dialog_content = "...그렇지...?",
  ui_story_1019_10191201_21_dialog_content = "......",
  ui_story_1019_10191201_22_dialog_content = "율리? 왜 말이 없어?",
  ui_story_1019_10191201_23_dialog_content = "내가 「엔지니어」의 자료를 조사하고 있던 거, 기억하나?",
  ui_story_1019_10191201_24_dialog_content = "당연하지. 하지만 전쟁 때문에 연구 환경도 엉망이고,\n넌... 가족을 잃은 지 얼마 안 돼서, 포기했을 줄 알았어...",
  ui_story_1019_10191201_25_dialog_content = "라빌, 믿기지 않겠지만, 위원회가 최근 개방한 고대 인공지능이야말로\n「엔지니어」의 조사를 위한 열쇠였어.",
  ui_story_1019_10191201_26_dialog_content = "그 고대 기계 말하는 건가? 「가디언」이라고 했었나. 그건 알골이 연구하는 거 아니었어?",
  ui_story_1019_10191201_27_dialog_content = "그건 그냥 가상 머신이야. 프로토타입은 지금 네 눈앞에 있어.",
  ui_story_1019_10191201_28_dialog_content = "율리! 너 설마 봉인된 프로토타입을... 그러다 감옥에 갈 수도 있는 거 몰라?",
  ui_story_1019_10191201_29_dialog_content = "하지만 「엔지니어」의 연구 자료를 찾는다면 이야기는 다르겠지...",
  ui_story_1019_10191201_30_dialog_content = "......",
  ui_story_1019_10191201_31_dialog_content = "「엔지니어」는 유전공학의 제창자일 뿐만 아니라...",
  ui_story_1019_10191201_32_dialog_content = "「엔지니어」가 가진 오로리안 실험과 마도공학에 관한 구상,\n그리고 육체와 정신의 본질에 관한 사고는...",
  ui_story_1019_10191201_33_dialog_content = "마치 강렬한 전류처럼 내 뇌를 자극하고 있어! 이런 격동적인 느낌은 처음이라고!",
  ui_story_1019_10191201_34_dialog_content = "율리...",
  ui_story_1019_10191201_35_dialog_content = "일단 내 말을 끝까지 들어 봐.",
  ui_story_1019_10191201_36_dialog_content = "「엔지니어」가 남긴 한 노트에는 오로리안의 유전자 발현의 편집을 시도하고 있는데...",
  ui_story_1019_10191201_37_dialog_content = "그건 지금 우리 오로리안의 신체 소질보다 수백 배 강해질 수 있는 방법이었어!\n그게 뭘 뜻하는지 알아?",
  ui_story_1019_10191201_38_dialog_content = "그 「엔지니어」가 있던 시대는... 지금보다 더 앞선 과학기술을 가지고 있었단 말인가?",
  ui_story_1019_10191201_39_dialog_content = "또?",
  ui_story_1019_10191201_40_dialog_content = "아... 「엔지니어」야말로 「가디언」의 주인이었군!",
  ui_story_1019_10191201_41_dialog_content = "아니야, 라빌. 가장 중요한 건 그런 게 아냐.",
  ui_story_1019_10191201_42_dialog_content = "중요한 건 그 기술을 복원할 수 있다면, 우린 더는 햇빛이 보이지 않는 지하에서\n암귀를 피해 살 필요가 없다는 거야!",
  ui_story_1019_10191201_43_dialog_content = "......",
  ui_story_1019_10191201_44_dialog_content = "율리, 만약에 그게 다 사실이라면... 그건 너무...",
  ui_story_1019_10191201_45_dialog_content = "기쁜 일이겠지, 안 그런가? 이건 획기적인 진보이자, 일루미나의 미래야!\n암귀를 이겨내고 지상으로 돌아가겠다는 이상을 실현해 줄 수단이라고!",
  ui_story_1019_10191201_46_dialog_content = "아이올리아를 일주하겠다는 네 꿈도 말이야!",
  ui_story_1019_10191201_47_dialog_content = "아이올리아 일주라...",
  ui_story_1019_10191201_48_dialog_content = "율리, 난 네 마음속 깊은 곳엔 그 누구보다 강한 용기와 힘이 있다는 걸 알아.",
  ui_story_1019_10191201_49_dialog_content = "지금까진 그래도 걱정했는데... 하하, 다시 일어섰구나. 다행이야, 율리.",
  ui_story_1019_10191201_50_dialog_content = "아무튼... 네가 괜찮으면 그걸로 됐어...",
  ui_story_1019_10191201_51_dialog_content = "라빌이 처음 그렇게 말했을 때, 전 미처 깨닫지 못했습니다..",
  ui_story_1019_10191201_52_dialog_content = "그러나 그의 얼굴에서 미소가 점차 사라지고, 나날이 전쟁의 고통에 짓눌린 후에야,\n저는 비로소 그의 말에 담긴 뜻을 이해할 수 있었지요.",
  ui_story_1019_10191201_53_dialog_content = "전 서둘러야겠다고 생각했습니다. 오로리안이 암귀의 손에 철저히 소멸되기 전에,\n「엔지니어」의 연구 성과를 재현하고자 했습니다.",
  ui_story_1019_10191201_54_dialog_content = "비록 남과 자신을 잊게 되더라도 말이지요.",
  ui_story_1019_10191201_55_dialog_content = "「엔지니어」의 노트에서 오로리안의 전투 능력을 높일 방법을 발견했을 때,\n오직 그 순간에만 전 비로소 흥분과...",
  ui_story_1019_10191201_56_dialog_content = "콜록... 콜록콜록... 희열을 느낄 수 있었기 때문입니다.",
  ui_story_1019_10191201_57_dialog_content = "율리시스 님, 괜찮으십니까...? 아니면 좀...",
  ui_story_1019_10191201_58_dialog_content = "...괜찮다... 콜록콜록!",
  ui_story_1019_10191201_59_dialog_content = "전 「엔지니어」가 남긴 단서를 찾아 그 성과를 재현하는 데\n십 년 가까운 시간을 보냈습니다.",
  ui_story_1019_10191201_60_dialog_content = "자그마치 십 년이란 말입니다. 저들이 제 실험실을 인계받은들 뭘 할 수 있단 말입니까?",
  ui_story_1019_10191201_61_dialog_content = "<color=#e8d9bb>딸깍딸깍──</color>",
  ui_story_1019_10191201_62_dialog_content = "꽤 깔끔하게 정리돼 있네. 노인네 강박증 덕분에 우리 수고도 덜었잖아.\n음, 이건 뭘까...?",
  ui_story_1019_10191201_63_dialog_content = "......",
  ui_story_1019_10191201_64_dialog_content = "잠깐만, 아까 마지막 한 턴이라면서? 벌써 30분 지났어. 또 땡땡이칠 생각이야?",
  ui_story_1019_10191201_65_dialog_content = "으음... 수고를 덜 수 있다면 나머지는 우리 미자드한테 맡길게~ 아하하!",
  ui_story_1019_10191201_66_dialog_content = "이렇게 단순한 게임은 진짜 오랜만이거든. 유일한 단점이라면... 실행 속도가 너무 느려!",
  ui_story_1019_10191201_67_dialog_content = "어... 근데 일루미나의 컴퓨터는 차세대 모델이 나올 때 일괄 교체했을 텐데?\n누락됐나? 아니면 이 기계, 영감 개인 물건인가?",
  ui_story_1019_10191201_68_dialog_content = "뭐가 누락됐다는 거죠?",
  ui_story_1019_10191201_69_dialog_content = "히익... 나 근무시간에 게임한 거 아냐! 이건... 그러니까...",
  ui_story_1019_10191201_70_dialog_content = "컴퓨터 좀 쓰게 해 줘.",
  ui_story_1019_10191201_71_dialog_content = "알골 박사, 이 기계인가요?",
  ui_story_1019_10191201_72_dialog_content = "...아니야. 설마 뭔가 빠진 단서가 있는 건가...",
  ui_story_1019_10191201_73_dialog_content = "잠깐만... 움직이지 마...",
  ui_story_1019_10191201_74_dialog_content = "그, 그렇게 가까이 와서... 뭐 하는 건데?",
  ui_story_1019_10191201_75_dialog_content = "가까이 와야 뭐가 이상한지 알 수 있잖아?",
  ui_story_1019_10191201_76_dialog_content = "오는 길에 무슨 일 있었어? 뭔가 나쁜 생각을 하고 있는 느낌이란 말이지...",
  ui_story_1019_10191201_77_dialog_content = "나 말하는 거야? 아니면 부르?",
  ui_story_1019_10191201_78_dialog_content = "부부! 부부! 부부!",
  ui_story_1019_10191201_79_dialog_content = "위험? 아니... 매우 위험하다고?\n아까 율리시스를 만났을 때도 그 말을 하고 싶었다고...?",
  ui_story_1019_10191201_80_dialog_content = "너희가 들어왔을 때부터 뭔가 느낌이 이상했거든.\n그리고 지금은 이 실험실 안에서 뭔가 우릴 주시하는 느낌이 들어...",
  ui_story_1019_10191201_81_dialog_content = "젊은 친구, 뭔가 느껴져?",
  ui_story_1019_10191201_82_dialog_content = "조금...?",
  ui_story_1019_10191201_83_dialog_content = "부부! 부부! 부부!",
  ui_story_1019_10191201_84_dialog_content = "으앗... 부르, 목 잡아당기지 말라고 내가 몇 번 말했어?!",
  ui_story_1019_10191201_85_dialog_content = "밖에? 문밖에 뭐가 있는데...?",
  ui_story_1019_10191201_86_dialog_content = "이런! 엄청 강한 다크매터가 느껴져요...",
  ui_story_1019_10191201_87_dialog_content = "순찰 중에 놓친 암귀인가...? 성큰 스파인의 주시를 피하다니...",
  ui_story_1019_10191201_88_dialog_content = "모두 조심하세요!",
  ui_story_1019_10191201_89_dialog_content = "<color=#e8d9bb>콰아앙!</color>",
  ui_story_1019_10191202_1_dialog_content = "으어억──!",
  ui_story_1019_10191202_2_dialog_content = "드디어... 잠잠해졌나?",
  ui_story_1019_10191202_3_dialog_content = "엄청 크네... 꼭 게임에 나오는 보스 같잖아!",
  ui_story_1019_10191202_4_dialog_content = "근데 이 암귀엔 아무 표식도 없어. 얘가 어디서 온 건지 어떻게 찾지?",
  ui_story_1019_10191202_5_dialog_content = "이 녀석, 창고 안의 실험용 암귀와는 다르게 실험 코드도 없어.",
  ui_story_1019_10191202_6_dialog_content = "게다가 이게 실험용 암귀인지, 아니면 다른 무언가인지조차 알 수 없겠어.",
  ui_story_1019_10191202_7_dialog_content = "율리시스의 실험체일까? 레이스의 근위군단처럼...\n설마 이 괴물들로 위원회에 맞서려는 건...",
  ui_story_1019_10191202_8_dialog_content = "어쨌든 아군을 공격하는 무기를 만드는 건 이클립스의 이익과 일치하잖아?",
  ui_story_1019_10191202_9_dialog_content = "위원회 쪽은 결론이 나왔어?",
  ui_story_1019_10191202_10_dialog_content = "아직 대원수님과 연락이 안 닿아요. 심의회가 아직 안 끝난 모양이에요.",
  ui_story_1019_10191202_11_dialog_content = "위원회 쪽 결론을 기다리고 있을 시간이 없어. 우리가 먼저 움직여야 해.\n율리시스의 심판보다는 프로토타입과 허점을 찾는 게 더 중요하니까.",
  ui_story_1019_10191202_12_dialog_content = "네, 그럼 10분 뒤에 현재 상황 정보를 같이 취합해 보도록 하죠.",
  ui_story_1019_10191202_13_dialog_content = "전 일단 실험동을 조사하면서 연구원들을 대피시킬게요.\n그 사람들도 뭔가 유용한 정보를 가지고 있을지도 몰라요.",
  ui_story_1019_10191202_14_dialog_content = "알골 박사, 위험원의 정보를 주변 순찰병에게 보내고, 증원을 요청해 주세요.",
  ui_story_1019_10191202_15_dialog_content = "얼마나 더 많은 암귀가 여기 잠복해 있을지 몰라요. 경계를 늦춰서는 안 돼요.",
  ui_story_1019_10191202_16_dialog_content = "알았어. 그럼 나도 계속 프로토타입을 찾고 있을게.",
  ui_story_1019_10191301_1_dialog_content = "에센, 내가 어디까지 얘기했지?",
  ui_story_1019_10191301_2_dialog_content = "「엔지니어」의 작업 기록을 읽고... 흥분과 희열을 느꼈다고 하는 부분까지 말씀하셨습니다.",
  ui_story_1019_10191301_3_dialog_content = "맞아, 희열...",
  ui_story_1019_10191301_4_dialog_content = "그 희열은 제가 「엔지니어」의 위대한 창조를 보았기 때문입니다.\n그는 「오로리안 유전자의 발현 개조」 기술로 수많은 강화 병사를 만들어냈던 것입니다!",
  ui_story_1019_10191301_5_dialog_content = "「강화 병사 대량 생산」이... 이름을 바꿔 「인공 태양 프로젝트」,\n「계명성 프로젝트」가 된 건가?",
  ui_story_1019_10191301_6_dialog_content = "단지 그 실험 과정들을 재현하기만 하는 것은 대단한 일도 아닙니다.\n생각지도 못한 것은 그의 마지막 작업 노트에 있었습니다.",
  ui_story_1019_10191301_7_dialog_content = "그 대량 생산된 강화 병사의 수는 <color=#FFB400>600년</color> 전 어느 시점에 갑자기 최고치에 도달했습니다.",
  ui_story_1019_10191301_8_dialog_content = "그러나 그 순간부터 「가디언」은 알 수 없는 이유로 인해 영구적으로 종료되었고...",
  ui_story_1019_10191301_9_dialog_content = "「엔지니어」의 이름도 일루미나의 역사에서 영원히 사라져 버렸습니다.",
  ui_story_1019_10191301_10_dialog_content = "왜 그렇게 된 것일까요?",
  ui_story_1019_10191301_11_dialog_content = "......",
  ui_story_1019_10191301_12_dialog_content = "잉겔, 넌 어떻게 생각하지?",
  ui_story_1019_10191301_13_dialog_content = "...「엔지니어」의 실험이 실패해서인가요?",
  ui_story_1019_10191301_14_dialog_content = "아니, 실험은 엄청난 성공을 거두었다.",
  ui_story_1019_10191301_15_dialog_content = "그 이유는... 일루미나가 그제서야 깨달았기 때문이었다...",
  ui_story_1019_10191301_16_dialog_content = "저들의 「엔지니어」가 대량 생산한 「강화 병사」가 바로\n전장에서 저들을 죽이는 <color=#FFB400>암귀</color>였던 것이다.",
  ui_story_1019_10191301_17_dialog_content = "라빌, 아무래도 내가 잘못 생각했는지도 모르겠어...",
  ui_story_1019_10191301_18_dialog_content = "전장에서 수거해 온 암귀의 구성 성분은 복잡하지만,\n그래도 유전자 샘플을 분리해 낼 수 있는 개체도 있었어.",
  ui_story_1019_10191301_19_dialog_content = "...분석 결과, 오로리안과 일부 암귀의 유전체 유사도는 90% 이상이었어.",
  ui_story_1019_10191301_20_dialog_content = "90% 이상이라고?",
  ui_story_1019_10191301_21_dialog_content = "무기물로 이루어진 대부분의 암귀는 진정한 적이 전장에 던진 포탄 같은 존재야.",
  ui_story_1019_10191301_22_dialog_content = "하지만 오로리안과 매우 흡사한 개체가 있어. 저들이야말로 포탄을 던지는 적일지도 몰라.",
  ui_story_1019_10191301_23_dialog_content = "비슷한 무기를 만들어내지 않으면, 우린 영원히 저들을 이길 수 없어.\n포탄을 던진 적이 누구인지 알아낼 수 없는 건 말할 것도 없겠지.",
  ui_story_1019_10191301_24_dialog_content = "율리... 넌... 암귀를 만들 작정이야...?",
  ui_story_1019_10191301_25_dialog_content = "아니, 우리의 무기는 적보다 더 강해야 해.",
  ui_story_1019_10191301_26_dialog_content = "우리의 무기는 암귀 포탄이면서 막강한 루미나틱스를 가진 오로리안이 될 거야.",
  ui_story_1019_10191301_27_dialog_content = "암귀와 오로리안의... 유전자를 융합하겠다는 거냐...?",
  ui_story_1019_10191301_28_dialog_content = "율리... 넌 미쳐버렸어...",
  ui_story_1019_10191301_29_dialog_content = "아니, 이제야 확실히 안 거야.",
  ui_story_1019_10191301_30_dialog_content = "이렇게 해야만 우리 오로리안들은 암귀를 상대로 승산이 있어.",
  ui_story_1019_10191301_31_dialog_content = "그저 가지고 있는 육체만으로 암귀와 맞서 봤자, 결말은 하나뿐이야.",
  ui_story_1019_10191301_32_dialog_content = "그럼 자기가 암귀로 변모해도 상관없다는 거냐고!",
  ui_story_1019_10191301_33_dialog_content = "아니, 변모가 아니라 초월이야! 이건 「엔지니어」의 천재적인 쾌거라고!\n그가 오로리안에게 더 강대한 힘을 준 거야!",
  ui_story_1019_10191301_34_dialog_content = "율리, 지금 네가 무슨 말을 하는 건지 모르겠나?\n넌 오로리안이 적과 싸우는 의미를 부정하고 있어. 우리의 신념을 저버리고 있다고!",
  ui_story_1019_10191301_35_dialog_content = "「엔지니어」의 단서를 발견하고 나서부터, 네 연구는 일루미나가\n용납할 수 있는 선을 넘어섰어.",
  ui_story_1019_10191301_36_dialog_content = "그런 생각은 안 해 봤어? 어쩌면 이게 바로 「엔지니어」의 목적일 수도 있어.\n우리가 암귀를 만들고, 심지어 암귀가 되도록 유도하는 거라고!",
  ui_story_1019_10191301_37_dialog_content = "우릴 암귀로 만들겠다는 게 아냐. 우릴 더 강한 오로리안으로 만들겠다는 거지!",
  ui_story_1019_10191301_38_dialog_content = "방법은 이미 찾았어. 내 연구는 곧 다음 단계로 접어들 거야.",
  ui_story_1019_10191301_39_dialog_content = "넌 항상 날 믿어줬잖아? 난 우리 꿈을 현실로 만들 수 있어.\n오로리안의 운명을 바꿀 수 있다고!",
  ui_story_1019_10191301_40_dialog_content = "이건 아니야, 율리... 이건 아니라고...",
  ui_story_1019_10191301_41_dialog_content = "우린 아직도 모르는 게 하나 있어...",
  ui_story_1019_10191301_42_dialog_content = "네 말대로 「엔지니어」가 이 모든 걸 만들었다면... 그는 대체 누구지?\n그리고 왜 일루미나의 역사에서 지워진 거지?",
  ui_story_1019_10191301_43_dialog_content = "어째서 일루미나를 등지고... 왜 모든 오로리안을 적으로 돌렸지?",
  ui_story_1019_10191301_44_dialog_content = "......",
  ui_story_1019_10191301_45_dialog_content = "「엔지니어」는 대체 누구지?",
  ui_story_1019_10191301_46_dialog_content = "암귀? 오로리안? 악마? 아니면...",
  ui_story_1019_10191301_47_dialog_content = "그 무엇도 아닐지도 모르지요. 콜록... 콜록콜록... 콜록!",
  ui_story_1019_10191301_48_dialog_content = "대체 언제까지 기침이나 하고 있을 거야?!\n오늘 당신을 내버려두면 죽을 때까지 입을 다물 작정이야?",
  ui_story_1019_10191301_49_dialog_content = "하하... 40년간의 괴로운 탐색이었습니다.\n말하고 싶어도 늘 느껴지는 역사의 무게 때문에 어디부터 떠올려야 할지 모르겠군요...",
  ui_story_1019_10191301_50_dialog_content = "여러분께는 감사드리죠. 기개가 넘치던 그 세월과... 라빌을 떠올리게 해 주셔서 말입니다.",
  ui_story_1019_10191301_51_dialog_content = "다만 「엔지니어」가 누구인가 하는 문제는 더는 제게 중요하지 않습니다.",
  ui_story_1019_10191301_52_dialog_content = "......",
  ui_story_1019_10191301_53_dialog_content = "율리시스, 그가 누구인지 당신에겐 중요하지 않겠지.",
  ui_story_1019_10191301_54_dialog_content = "하지만 일루미나가 어디로 나아가야 하는지는 내게 아주 중요해.",
  ui_story_1019_10191301_55_dialog_content = "당신 이상을 설파할 시간은 이미 충분히 줬어.",
  ui_story_1019_10191301_56_dialog_content = "그럼 이제 말해 봐.\n「계명성 프로젝트」가 일루미나에 가져올 이익을 내가 어떻게 평가해야 할까?",
  ui_story_1019_10191301_57_dialog_content = "지금 당신 눈앞에는 일루미나에 지난 10년간의 안녕을 가져다준 자,\n그리고 향후 10년의 미래에 있어 가장 잠재력 있는 자가 있습니다.",
  ui_story_1019_10191301_58_dialog_content = "오로리안이 암귀를 이겨내는 길은 단 하나뿐입니다.\n설령 오로리안의 백골을 밟고 나아가야 하더라도, 저는 그렇게 할 겁니다.",
  ui_story_1019_10191301_59_dialog_content = "이익을 알고 싶습니까? 그게 제 대답입니다.",
  ui_story_1019_10191401_1_dialog_content = "여러분... 무슨 소리가 난 것 같은데요...",
  ui_story_1019_10191401_2_dialog_content = "이미 모든 연구원들에게 연구센터를 떠나라고 전달했을 텐데요. 왜 아직도 여기 있죠?",
  ui_story_1019_10191401_3_dialog_content = "잠깐만, 나 당신 알아. 율리시스 박사 조수지?",
  ui_story_1019_10191401_4_dialog_content = "이 실험체들, 어느 창고에서 나온 거야?",
  ui_story_1019_10191401_5_dialog_content = "실험체요...? 박사님 실험체엔 전부 라벨이 달려 있고, 로트별로 보관하고 있어요.",
  ui_story_1019_10191401_6_dialog_content = "이것들은... 죄송하지만 저도 본 적이 없네요.\n아마 박사님 컴퓨터 안에 기록이 있을 거예요.",
  ui_story_1019_10191401_7_dialog_content = "컴퓨터는 내가 조사해 봤어. 실험 데이터나 보고서 같은 거밖에 없던데?",
  ui_story_1019_10191401_8_dialog_content = "그럼 대체 어디서 나타난 거지?",
  ui_story_1019_10191401_9_dialog_content = "어디 보자...",
  ui_story_1019_10191401_10_dialog_content = "액세스 실패? 아직도 뭔가 숨기는 게 있나 본데.",
  ui_story_1019_10191401_11_dialog_content = "부르? 어떻게 생각해?",
  ui_story_1019_10191401_12_dialog_content = "부부!",
  ui_story_1019_10191401_13_dialog_content = "오, 좋아. 아주 훌륭해!",
  ui_story_1019_10191401_14_dialog_content = "조수 씨, 액세스 키 좀 입력해 줘.",
  ui_story_1019_10191401_15_dialog_content = "네...",
  ui_story_1019_10191401_16_dialog_content = "<color=#e8d9bb>타탁타닥──</color>",
  ui_story_1019_10191401_17_dialog_content = "<color=#e8d9bb>삑──</color>",
  ui_story_1019_10191401_18_dialog_content = "역시 뭔가 있네!",
  ui_story_1019_10191401_19_dialog_content = "강화 병사 파일... 벌써 여러 번 버전이 바뀌었어...",
  ui_story_1019_10191401_20_dialog_content = "이것들... 전 실험실에서 본 적 없는 것들인데요...",
  ui_story_1019_10191401_21_dialog_content = "당연하지. 이건 율리시스의 개인적인 실험이니까!",
  ui_story_1019_10191401_22_dialog_content = "그 강화 병사라는 게 우릴 계속 습격한 적을 말하는 거겠죠? 대체 어디 보관돼 있죠?",
  ui_story_1019_10191401_23_dialog_content = "장소... 보관 장소는...",
  ui_story_1019_10191401_24_dialog_content = "부부!",
  ui_story_1019_10191401_25_dialog_content = "아, 찾았어!",
  ui_story_1019_10191401_26_dialog_content = "...<color=#FFB400>0호 창고</color>? 거긴...",
  ui_story_1019_10191401_27_dialog_content = "자난성에... 0호 창고가 있었나요?",
  ui_story_1019_10191401_28_dialog_content = "들어본 적 없는데...",
  ui_story_1019_10191401_29_dialog_content = "오래전에 폐쇄된 그 0호 창고를 말하는 거라면...",
  ui_story_1019_10191401_30_dialog_content = "따라 와!",
  ui_story_1019_10191401_31_dialog_content = "......",
  ui_story_1019_10191401_32_dialog_content = "다들... 너무 빠르잖아...!",
  ui_story_1019_10191401_33_dialog_content = "저건 이미 오로리안을 개조한 수준이 아냐! 암귀를 양산하고 있는 거라고!",
  ui_story_1019_10191401_34_dialog_content = "방어 시설의 허점에서 도망친 놈들만으로도 이미 충분히 위험해.\n얼른 근원지부터 막아야 해. 안 그러면 다 같이 죽을 뿐이야!",
  ui_story_1019_10191401_35_dialog_content = "<color=#e8d9bb>철컹──</color>",
  ui_story_1019_10191401_36_dialog_content = "...여기가 0호 창고인가요?",
  ui_story_1019_10191401_37_dialog_content = "어, 엄청 크네!",
  ui_story_1019_10191401_38_dialog_content = "창고 문이 다 열려 있어... 엔진 7호를 몇 대는 더 둘 수 있을 넓이잖아.",
  ui_story_1019_10191401_39_dialog_content = "약 냄새가 나... 여기서 실험을 하고 있었던 건가? 다들 조심해.",
  ui_story_1019_10191401_40_dialog_content = "<color=#e8d9bb>삐빅──</color>",
  ui_story_1019_10191401_41_dialog_content = "부부! 부부! 부부!",
  ui_story_1019_10191401_42_dialog_content = "진짜 있었잖아...",
  ui_story_1019_10191401_43_dialog_content = "<color=#e8d9bb>콰앙──</color>",
  ui_story_1019_10191401_44_dialog_content = "이 소리... 이 저 앞의 기계 위예요! 강화 병사가 있어요!",
  ui_story_1019_10191401_45_dialog_content = "실험이 막 끝난 모양이네... 전에 우릴 습격했던 괴물과 확실히 비슷해.",
  ui_story_1019_10191401_46_dialog_content = "근원지를 찾아서 다행이에요! 여러분, 안전에 주의하면서 주변을 확인해 보세요.",
  ui_story_1019_10191401_47_dialog_content = "<color=#e8d9bb>지빅──</color>",
  ui_story_1019_10191401_48_dialog_content = "하하...하하하하!",
  ui_story_1019_10191401_49_dialog_content = "부! 부! 부!",
  ui_story_1019_10191401_50_dialog_content = "알골 박사, 여기 있는 기계들은 안 건드리는 게 좋을 거예요.\n무슨 함정이라도 가동하면 큰일이라구요!",
  ui_story_1019_10191401_51_dialog_content = "온도 제어 모니터, 중단 버튼, 입력 장치...",
  ui_story_1019_10191401_52_dialog_content = "틀림없어...",
  ui_story_1019_10191401_53_dialog_content = "<color=#e8d9bb>콰앙──</color>",
  ui_story_1019_10191401_54_dialog_content = "저 강화 병사, 움직임이 심상치 않아! 기계에서 벗어나려는 것 같아!",
  ui_story_1019_10191401_55_dialog_content = "부부! 부부! 부부!",
  ui_story_1019_10191401_56_dialog_content = "모니터와 본체는 케이스를 바꿨지만, 운영체제, 인터페이스, 명령 프롬프트는...",
  ui_story_1019_10191401_57_dialog_content = "안전상의 이유로 봉인했다는 건 역시 거짓말이었구나.",
  ui_story_1019_10191401_58_dialog_content = "그리고 여기...",
  ui_story_1019_10191401_59_dialog_content = "아직도 가동하고 있어...",
  ui_story_1019_10191401_60_dialog_content = "대체 여기서 뭘 하고 있었던 거야...?",
  ui_story_1019_10191401_61_dialog_content = "부부부부──!",
  ui_story_1019_10191401_62_dialog_content = "부르! 너무 빨라!",
  ui_story_1019_10191401_63_dialog_content = "<color=#e8d9bb>철커덩, 철커덩──!</color>",
  ui_story_1019_10191401_64_dialog_content = "으어어어──",
  ui_story_1019_10191401_65_dialog_content = "이런! 강화 병사가 풀려났어!",
  ui_story_1019_10191401_66_dialog_content = "알골 박사, 여긴 위험해요! 얼른 가요!",
  ui_story_1019_10191401_67_dialog_content = "......",
  ui_story_1019_10191401_68_dialog_content = "알골 박사!",
  ui_story_1019_10191401_69_dialog_content = "......",
  ui_story_1019_10191401_70_dialog_content = "<color=#e8d9bb>철컹──!</color>",
  ui_story_1019_10191401_71_dialog_content = "「아머 스킬!」",
  ui_story_1019_10191401_72_dialog_content = "대체 얼마나 넓은 거야?! 이게 벽이 아니라 문이었어──?!",
  ui_story_1019_10191401_73_dialog_content = "다들 빨리 도망가! 뒤에 커다란 괴물이 있다구!",
  ui_story_1019_10191401_74_dialog_content = "일단 입구까지 퇴각하죠... 들어왔을 땐 분명히 아무것도 없었는데...!",
  ui_story_1019_10191401_75_dialog_content = "...일어선 모습이 꽤 무시무시하네.",
  ui_story_1019_10191401_76_dialog_content = "알골 씨가 들어온 뒤로 전혀 움직일 생각을 안 해요!",
  ui_story_1019_10191401_77_dialog_content = "알골 박사!",
  ui_story_1019_10191401_78_dialog_content = "부부! 부부! 부부!",
  ui_story_1019_10191401_79_dialog_content = "암귀 처치는 당신들 전문이잖아.",
  ui_story_1019_10191401_80_dialog_content = "암귀가 알골 씨 바로 뒤에 있어요! 그게 아무리 중요해도 목숨은 챙겨야죠!",
  ui_story_1019_10191401_81_dialog_content = "괴로움을 맛보고 나면 너도 알게 될 거야.",
  ui_story_1019_10191401_82_dialog_content = "내 손에 쥐어뜯긴 머리카락들...",
  ui_story_1019_10191401_83_dialog_content = "피가 날 때까지 깨문 열 손가락...",
  ui_story_1019_10191401_84_dialog_content = "끝없이 날 괴롭히면서도 내가 계속 뜨겁게 타오르게 해주는 코드들...",
  ui_story_1019_10191401_85_dialog_content = "난 평생 이 프로토타입을 떠날 수 없어!",
  ui_story_1019_10191401_86_dialog_content = "......",
  ui_story_1019_10191401_87_dialog_content = "여러분, 알골 박사를 지키죠. 전투 준비!",
  ui_story_1019_10191502_1_dialog_content = "다들 다친 곳은 없나요?",
  ui_story_1019_10191502_2_dialog_content = "찰과상 정도야. 아무렇지도 않아.",
  ui_story_1019_10191502_3_dialog_content = "피가 나잖아... 너 설마 게임처럼 괴물 독에 감염돼서 괴물이 되는 건 아니지?",
  ui_story_1019_10191502_4_dialog_content = "...날 뭐라고 생각하는 거야? 이 정도 상처, 블랙 엄브렐라 연구소에선 보통이라고...",
  ui_story_1019_10191502_5_dialog_content = "다만 성큰 스파인의 반응이 심상치 않았어.\n구조나 에너지 출력, 모두 엄청난 변화가 있었거든.",
  ui_story_1019_10191502_6_dialog_content = "맞아! 그치만 이 괴물들도 결국 내 왕좌의 상대는 못 돼!",
  ui_story_1019_10191502_7_dialog_content = "율리시스는 강화 병사를 만들어서 대체 뭘 하려던 거지?\n게다가 프로토타입은 아직도 뭔가를 계산하고 있어...",
  ui_story_1019_10191502_8_dialog_content = "그가 「계명성 프로젝트」를 계속 진행한 걸 보면 쉽게 알 수 있죠...\n강화 병사로 오로리안을 대체해서 오로리안의 생존율을 높이려고 했을 거예요.",
  ui_story_1019_10191502_9_dialog_content = "다만... 강화 병사는 이게 전부일까요?\n레이스 근위군단의 개조 오로리안만해도 100명이 넘었는걸요...",
  ui_story_1019_10191502_10_dialog_content = "알골 박사한테 뭔가 알아낸 게 있는지 물어보자.\n알골 박사라면 강화 병사의 근원지와 수를 찾아낼 수 있을지도 몰라.",
  ui_story_1019_10191502_11_dialog_content = "<color=#e8d9bb>타탁타닥──</color>",
  ui_story_1019_10191502_12_dialog_content = "부르가 키보드도 칠 수 있다니... 게다가 빨라!",
  ui_story_1019_10191502_13_dialog_content = "맞아...",
  ui_story_1019_10191502_14_dialog_content = "부르가 왜 항상 내 머리카락을 꼬아대는지 이제 알겠어.",
  ui_story_1019_10191502_15_dialog_content = "부우!",
  ui_story_1019_10191502_16_dialog_content = "알골 박사, 부르는 어떻게 이 프로토타입을 조작하는 거야?",
  ui_story_1019_10191502_17_dialog_content = "혹시 촉수 한쪽은 박사 머리에 연결돼 있고, 다른 쪽으로 당신 명령을 실행하고 있는 거야?",
  ui_story_1019_10191502_18_dialog_content = "음... 좋은 발상이네. 아쉽지만 틀렸어.\n부르는 아마 자기 촉각과 기억을 바탕으로, 내 동작을 따라 명령어를 입력하고 있을 거야.",
  ui_story_1019_10191502_19_dialog_content = "알골 박사, 뭔가 발견한 게 있나요?",
  ui_story_1019_10191502_20_dialog_content = "여기 실험 중인 강화 병사들은 확실히 전에 우릴 습격한 병사들이 맞아요.",
  ui_story_1019_10191502_21_dialog_content = "강화 병사는 이게 전부인가요?",
  ui_story_1019_10191502_22_dialog_content = "난 지금 봉인되지 않은 프로토타입을 발견한 것만으로도\n이미 내가 상상할 수 있는 한계를 넘어섰어...",
  ui_story_1019_10191502_23_dialog_content = "강화 병사에 대한 건 시스템에 로그인해야 알 수 있을 거야.",
  ui_story_1019_10191502_24_dialog_content = "부르가 계산하는 동안 창고를 한번 살펴보고, 다른 실험체나 창고가 있는지 확인했으면 해.",
  ui_story_1019_10191502_25_dialog_content = "「가디언 1호」의 코어가 도난당한 것도, 자난성의 방어에 구멍이 난 것도\n모두 율리시스와 관계가 있어.",
  ui_story_1019_10191502_26_dialog_content = "내가 지금 해야 할 일은 여전히 가동 중인 이 프로토타입에 다른 리스크가 없는지,\n그리고 율리시스가 이걸 가지고 뭘 하려고 했는지 알아내는 거야.",
  ui_story_1019_10191502_27_dialog_content = "지금 당장 율리시스를 탐문하고 싶어졌어...",
  ui_story_1019_10191502_28_dialog_content = "안전상의 이유로 봉인했다고...? 아하하하...",
  ui_story_1019_10191502_29_dialog_content = "왜 웃어요...?",
  ui_story_1019_10191502_30_dialog_content = "「가디언」의 연구 권한이 개방됐을 때, 난 율리시스의 학생 자격으로\n이 기계를 참관한 적이 있어.",
  ui_story_1019_10191502_31_dialog_content = "그때 율리시스는 인공지능엔 관심이 없어 보였고, 그냥 겉핥기로만 다루고 말았어.\n그 뒤에 프로토타입은 안전상의 이유로 처분됐다고 들었고, 난 율리시스가 포기한 줄 알았어.",
  ui_story_1019_10191502_32_dialog_content = "대체 혼자서 이걸로 뭘 하려고 했을까?",
  ui_story_1019_10191502_33_dialog_content = "연구란 건 말이야. 진척이 없을 땐 설비나 역사의 한계성이 문제인 게 아냐...",
  ui_story_1019_10191502_34_dialog_content = "문제는 항상 사람에게 있었어.",
  ui_story_1019_10191502_35_dialog_content = "부부부부──!",
  ui_story_1019_10191502_36_dialog_content = "<color=#e8d9bb>위이잉──</color>",
  ui_story_1019_10191502_37_dialog_content = "잘했어...",
  ui_story_1019_10191502_38_dialog_content = "드디어 「가디언」의 전모를 볼 수 있겠네...",
  ui_story_1019_10191502_39_dialog_content = "원... 4개의 커서... 이게 뭐죠?",
  ui_story_1019_10191502_40_dialog_content = "로그인 비밀번호가 필요한 모양이네.\n프로토타입의 보호 수단인지, 아니면 율리시스가 경계한 건지는 모르겠지만...",
  ui_story_1019_10191502_41_dialog_content = "로그인하면... 안에 뭐가 있을까요?",
  ui_story_1019_10191502_42_dialog_content = "해 보면 알겠지.",
  ui_story_1019_10191502_43_dialog_content = "「부르, 명령, 점프!」",
  ui_story_1019_10191502_44_dialog_content = "부우!",
  ui_story_1020_10200101_1_dialog_content = "<size=45>부부부부──!</size>",
  ui_story_1020_10200101_2_dialog_content = "암호를 푸는 건 부르한테 맡기면 되겠죠?",
  ui_story_1020_10200101_3_dialog_content = "속도가 굉장히 빠르네요... 가까이에서 보고 있는데도 믿기지가 않아요.",
  ui_story_1020_10200101_4_dialog_content = "이건 오히려 내 추측을 뒷받침하는 증거야...",
  ui_story_1020_10200101_5_dialog_content = "부르는 전에 율리시스의 사무실에 왔을 때도 이런 격렬한 반응을 보였어.\n율리시스 본인을 봤을 때도 마찬가지였고.",
  ui_story_1020_10200101_6_dialog_content = "어쩌면 율리시스와 프로토타입 사이에 모종의 관계가 있다고 알려 주고 있는 걸지도 몰라.",
  ui_story_1020_10200101_7_dialog_content = "부르가 그걸 어떻게 알죠?",
  ui_story_1020_10200101_8_dialog_content = "저도 궁금한 게 있어요.\n부르는 아무리 봐도 이번에 처음 프로토타입을 조종해 보는 건 아닌 것 같은데요.",
  ui_story_1020_10200101_9_dialog_content = "그건 나하고 부르가 어떻게 만나게 됐느냐부터 설명해야 할 것 같네.",
  ui_story_1020_10200101_10_dialog_content = "프로토타입이 봉인되기 전에, 난 「가디언」 시스템의 격리된 복사 데이터를 제작하려고\n다른 연구원들이랑 이 낡은 창고에 왔었어.",
  ui_story_1020_10200101_11_dialog_content = "다른 연구원들이 뭔가 빠뜨리진 않을까 걱정돼서, 난 매일 밤늦은 시간까지 여기 머물곤 했어.\n솔직히 프로토타입이랑 더 많이 접촉하고 싶단 사심도 좀 있었고.",
  ui_story_1020_10200101_12_dialog_content = "여기 있는 장치들은 언제나 「위이이잉」하는 소리가 나서, 잠도 엄청 잘 왔거든.\n그런데 가끔 들리는 「부부부」 소리에 시끄러워 깰 때도 있었어...",
  ui_story_1020_10200101_13_dialog_content = "복사 데이터가 완성된 후, 난 가상 머신을 가지고 방으로 돌아갔어.\n그런데 내 목에 촉수인지, 전선인지 모를 뭔가가 감겨 있더라고...",
  ui_story_1020_10200101_14_dialog_content = "그날 이후로 프로토타입의 일부가 네 몸에 기생하기 시작했던 거지.",
  ui_story_1020_10200101_15_dialog_content = "그렇게 보면 왕좌나 성큰 스파인과도 좀 비슷한 구석이 있네.",
  ui_story_1020_10200101_16_dialog_content = "그럴지도. 하지만 부르를 알게 된 지 얼마 안 됐을 때,\n내가 얼마나 고통에 시달렸었는진 다들 상상도 못 할걸.",
  ui_story_1020_10200101_17_dialog_content = "부르는 잠도 안 자고 쉴 틈 없이 내 방의 있는 가구들을 산산조각 냈어.",
  ui_story_1020_10200101_18_dialog_content = "소통을 시도해 보긴 했지만, 늘 부르한테 얻어터지는 결말을 피할 순 없었어...",
  ui_story_1020_10200101_19_dialog_content = "쇄골, 늑골, 견갑골... 부르가 휘감을 수 있는 곳이라면 다 한 번쯤은 부러졌었다니까...",
  ui_story_1020_10200101_20_dialog_content = "그 정도면 이미 얻어터진 게 아니라 온몸을 끊어 놓은 수준이잖아요!",
  ui_story_1020_10200101_21_dialog_content = "그게 아니면 내가 왜 이렇게까지 몸을 단련했겠어?",
  ui_story_1020_10200101_22_dialog_content = "그럼... 알골 씨 실험실에 있던 그 많은 운동 기구들도 전부 체력 단련용이었던 거군요?",
  ui_story_1020_10200101_23_dialog_content = "거기다 매일 건강 검진도 받고, 정해진 시간마다 신체검사도 하고 있어...\n나도 일루미나 메디컬 센터의 단골인 셈이지.",
  ui_story_1020_10200101_24_dialog_content = "부르를 연구하려고 알골 박사가 그 정도까지 할 수 있을 줄은 몰랐는걸...",
  ui_story_1020_10200101_25_dialog_content = "역시 과학 연구에 몸을 바친 여자는 날 흥분하게 만든다니까...",
  ui_story_1020_10200101_26_dialog_content = "부르한테 악의가 없단 건 잘 알고 있었으니까.\n그리고 친구가 되려면 적응 기간이 필요한 법이잖아?",
  ui_story_1020_10200101_27_dialog_content = "그러다가 업무에 본격적으로 집중하기 시작했을 때쯤에서야\n난 부르가 단순한 기생 생물이 아니란 걸 발견했어.",
  ui_story_1020_10200101_28_dialog_content = "부르는 내 연구에 관심이 많았어. 심지어는 조작할 때 피드백도 주던걸.",
  ui_story_1020_10200101_29_dialog_content = "프로토타입의 일부에서 지금의 모습이 될 때까지 어떤 일들을 겪었을지 상상도 하기 어렵네요...",
  ui_story_1020_10200101_30_dialog_content = "아무튼, 부르의 존재에 익숙해지고 나니까 그제서야 내가 반년이나\n방 밖으로 안 나갔단 걸 깨달았어.",
  ui_story_1020_10200101_31_dialog_content = "그 반년이라는 시간은 내 인생에서 가장 보람차고 홀가분한 날들이었지.",
  ui_story_1020_10200101_32_dialog_content = "나한테 「로봇」, 「아웃사이더」, 「외톨이」 같은 꼬리표가\n붙기 시작한 것도 그때부터지만, 난 신경 안 써.",
  ui_story_1020_10200101_33_dialog_content = "날 이해하지 못하는 오로리안들한테 일일이 해명하는 것보단,\n기계랑 같이 있는 게 오히려 편하니까.",
  ui_story_1020_10200101_34_dialog_content = "아하하, 물론 1호도 빼놓을 수 없겠지. 그 녀석도... 날 꽤나 애먹였거든.",
  ui_story_1020_10200101_35_dialog_content = "처음엔 1호, 그다음엔 부르까지, 알골 씨는 정말...",
  ui_story_1020_10200101_36_dialog_content = "괴짜라고?",
  ui_story_1020_10200101_37_dialog_content = "조금 괴짜 같긴 하지만, 그래도 재미있는 사람이네요!",
  ui_story_1020_10200101_38_dialog_content = "나도 알아. 그리고 난 내가 괴짜인 게 좋아.",
  ui_story_1020_10200101_39_dialog_content = "그거 뭔가 마음에 와닿는 말이네. 나도 똑같은 걸 달고 다녔었거든.",
  ui_story_1020_10200101_40_dialog_content = "꼬리표가 꼭 그렇게 나쁜 것도 아냐~ 내 것도 들어볼래?\n「게임의 왕」, 「던전 학살자」, 「2회차 블랙홀」...",
  ui_story_1020_10200101_41_dialog_content = "난 나한테 이런 꼬리표가 더 많이 붙었으면 좋겠어!",
  ui_story_1020_10200101_42_dialog_content = "그거야 다 개성적인 꼬리표들이니까 그렇겠지.\n젊은 친구, 네 건 뭐야?",
  ui_story_1020_10200101_43_dialog_content = "전 왠지... 없는 것 같아요.",
  ui_story_1020_10200101_44_dialog_content = "나 알아! 「패배자」!",
  ui_story_1020_10200101_45_dialog_content = "네네...",
  ui_story_1020_10200101_46_dialog_content = "전에는 조금 싫어하더니, 지금은 의외로 흔쾌히 인정하는군요.",
  ui_story_1020_10200101_47_dialog_content = "지금은 당장 생각나는 게 없었을 뿐이야...",
  ui_story_1020_10200101_48_dialog_content = "이야기가 길어졌는데, 알골 박사, 우린 이제 뭘 해야 하죠?",
  ui_story_1020_10200101_49_dialog_content = "음, 아무것도 안 할 거야.",
  ui_story_1020_10200101_50_dialog_content = "이 기계가 움직이는 소리 좀 들어 봐. 부르의 본능인지는 모르겠지만,\n프로토타입에 접촉한 순간부터 업데이트된 데이터들을 찾고 있어.",
  ui_story_1020_10200101_51_dialog_content = "그리고 자기 실행 로직을 조정하고 암호를 해독하고 있어. 시간이 꽤 걸릴 거야.",
  ui_story_1020_10200101_52_dialog_content = "대신 로그인에 성공하기만 하면, 율리시스가 뭘 했는지도 알 수 있고...",
  ui_story_1020_10200101_53_dialog_content = "「가디언」의 방어 코드를 활용해 새로운 코어를 만들고,\n일루미나의 방어 허점도 보완할 수 있을 거야.",
  ui_story_1020_10200101_54_dialog_content = "그거 정말 다행이네요!",
  ui_story_1020_10200101_55_dialog_content = "이렇게 오랜 시간이 지났는데도 프로토타입이 아직 가동하고 있을 줄은 몰랐어.\n게다가 아이테르가 오고 나서야 이 사실을 발견했고 말이야.",
  ui_story_1020_10200101_56_dialog_content = "아무래도 역시 실험실에 틀어박혀 연구만 하면 안 될 것 같아.",
  ui_story_1020_10200101_57_dialog_content = "아하하... 정말 뜻밖이라니까... 아하하하하!",
  ui_story_1020_10200101_58_dialog_content = "궁금한 게 하나 있는데요...\n만약에 율리시스 그 사람이 진짜 여기서 몰래 강화 병사를 만들었던 거라면...",
  ui_story_1020_10200101_59_dialog_content = "메디컬 센터에서 병사들을 치료하면서 전혀 불안하지도 않았던 걸까요?",
  ui_story_1020_10200101_60_dialog_content = "만약 진짜로 프로토타입에서 율리시스와 암귀의 연결 고리가 발견된다 쳐도,\n율리시스는 네 걱정처럼 불안해하진 않을 거야.",
  ui_story_1020_10200101_61_dialog_content = "사람은 나쁜 짓을 할 때 딱히 구실을 찾진 않거든.\n그저 나쁜 짓이 재미있으니까 할 뿐이지.",
  ui_story_1020_10200201_1_dialog_content = "지금 당신 눈앞에는 일루미나에 지난 10년간의 안녕을 가져다준 자,\n그리고 향후 10년의 미래에 있어 가장 잠재력 있는 자가 있습니다.",
  ui_story_1020_10200201_2_dialog_content = "제 실험의 이익을 알고 싶습니까? 그게 제 대답입니다.",
  ui_story_1020_10200201_3_dialog_content = "지난 10년의 안녕... 라인하르트를 말하는 거야?",
  ui_story_1020_10200201_4_dialog_content = "일루미나에는 여러 대원수가 있었습니다.\n스스로 강한 힘을 가진 자도 있었지만, 후천적으로 강해진 경우가 더 많았지요.",
  ui_story_1020_10200201_5_dialog_content = "라인하르트 이전의 많은 대원수들은 자신의 힘을 제어할 수 없었던 까닭에...",
  ui_story_1020_10200201_6_dialog_content = "생의 후반에 자의 또는 타의로 자신의 삶을 끝냈습니다.",
  ui_story_1020_10200201_7_dialog_content = "이와 비슷한 실험은 제가 태어나기도 전부터 아주 오랜 시간 지속되어 왔습니다.",
  ui_story_1020_10200201_8_dialog_content = "이것은 일루미나가 영원히 묻어 두고 싶어 하는 과거이자, 연구자로서의 수치일 것입니다.",
  ui_story_1020_10200201_9_dialog_content = "제가 고안한 영유아 단계부터 병사를 개조하는 방법과,\n<color=#FFB400>80호 지하성</color>의 선별 방식이 아니었더라면...",
  ui_story_1020_10200201_10_dialog_content = "지금의 일루미나에는 라인하르트와 같이 용기와 지혜를 겸비한 대원수가\n존재하지 않았을 것입니다.",
  ui_story_1020_10200201_11_dialog_content = "......",
  ui_story_1020_10200201_12_dialog_content = "그리고 일루미나의 연구는 「인공 태양 프로젝트」가 시작되면서 비로소 궤도에 오른 것입니다.\n심지어 상당한 성과를 이룩했고 말입니다.",
  ui_story_1020_10200201_13_dialog_content = "그 과정에서 희생자가 다소 발생했습니다만, 우리의 안녕과 발전을 위해 필요한 희생이었습니다.",
  ui_story_1020_10200201_14_dialog_content = "그럼 <color=#FFB400>80호 지하성</color>의 참사는 「잘못된 정보」에서 비롯된 것이 아니라고 인정하시는 거군요...",
  ui_story_1020_10200201_15_dialog_content = "물론 아니었지요. 하지만 제 실험의 모든 절차를 대중에게 설명할 필요는 없는 것입니다.",
  ui_story_1020_10200201_16_dialog_content = "안정적인 정치 체제를 위해서는 강력한 통치가 필요합니다.\n동요하는 일루미나의 대중에게 있어 윤리와 도덕의 충돌은 더 치명적인 영향을 줄 뿐입니다.",
  ui_story_1020_10200201_17_dialog_content = "윤리와 도덕의 충돌...",
  ui_story_1020_10200201_18_dialog_content = "제 동료들이 목숨과 맞바꿔 가져온 그 정보들은... 당신의 한낱 실험 절차에 불과했군요.",
  ui_story_1020_10200201_19_dialog_content = "<color=#e8d9bb>쿠르릉──!</color>",
  ui_story_1020_10200201_20_dialog_content = "이번 80호 지하성 정찰 임무의 목표를 모두 기억하고 있겠지?!",
  ui_story_1020_10200201_21_dialog_content = "반드시 성공한다! 실패는 없다!",
  ui_story_1020_10200201_22_dialog_content = "그어어어──!",
  ui_story_1020_10200201_23_dialog_content = "반장님! 이건 <color=#FFB400>로크</color>가... 제게 맡긴 정보입니다... 로크는 정찰반의 명예를 지켰습니다!",
  ui_story_1020_10200201_24_dialog_content = "로크... 알겠다! ...잘했다!",
  ui_story_1020_10200201_25_dialog_content = "이 앞이 바로 출구다. 아나톨리, 단숨에 뛰어나가라!",
  ui_story_1020_10200201_26_dialog_content = "예!",
  ui_story_1020_10200201_27_dialog_content = "<color=#e8d9bb>쿠르릉──!</color>",
  ui_story_1020_10200201_28_dialog_content = "반장님!",
  ui_story_1020_10200201_29_dialog_content = "정보는 아나톨리에게 맡겨라! 너, 그리고 너희들! 나와 함께 후방을 차단한다!",
  ui_story_1020_10200201_30_dialog_content = "예!",
  ui_story_1020_10200201_31_dialog_content = "반장님! 저도...",
  ui_story_1020_10200201_32_dialog_content = "내가 정찰 임무는 어떻게 하라고 가르쳤지?!",
  ui_story_1020_10200201_33_dialog_content = "......",
  ui_story_1020_10200201_34_dialog_content = "동료가 정보를 맡기면, 상황을 막론하고 그 즉시 정보를 가지고\n도망쳐 살아남으라고 했을 텐데!",
  ui_story_1020_10200201_35_dialog_content = "알고 있습니다, 반장님! 하지만... 전 모두와 함께 나가겠습니다!",
  ui_story_1020_10200201_36_dialog_content = "그어어어──!",
  ui_story_1020_10200201_37_dialog_content = "크어억...!",
  ui_story_1020_10200201_38_dialog_content = "내 말을 귓등으로 들었나?! 임무에 사적인 감정은 금물이다!\n정찰 임무에 존재하는 건 정보와 암귀, 그리고 시체뿐이다!",
  ui_story_1020_10200201_39_dialog_content = "어서 가라!",
  ui_story_1020_10200201_40_dialog_content = "크아아──!",
  ui_story_1020_10200201_41_dialog_content = "반장님!!!",
  ui_story_1020_10200201_42_dialog_content = "...가!",
  ui_story_1020_10200201_43_dialog_content = "...정보를 가지고 돌아가라... 아나톨리...",
  ui_story_1020_10200201_44_dialog_content = "...내가 뒤에 있다면... 더 빨리... 갈 수 있을 거야...",
  ui_story_1020_10200201_45_dialog_content = "<color=#e8d9bb>쿠르릉──!</color>",
  ui_story_1020_10200201_46_dialog_content = "당신은 저들의 목숨과... 삶의 의미를... 무참히 짓밟았습니다!",
  ui_story_1020_10200201_47_dialog_content = "80호 지하성의 데이터 회수 작전이 있었기에 여명의 빛, 라인하르트가 탄생한 걸세.\n그들의 희생과 맞바꾼 것은 일루미나의 10년간의 안녕이었네.",
  ui_story_1020_10200201_48_dialog_content = "덕분에 자네와 나 같은 사람이 지금까지 살아 있는 걸세. 충분히 가치 있는 희생이 아닌가?",
  ui_story_1020_10200201_49_dialog_content = "...저는 대원수님께서 일루미나를 위해 하신 모든 일을 존중합니다.",
  ui_story_1020_10200201_50_dialog_content = "하지만 전 오직 동료들의 죽음에 관한 진실을 밝히겠다는 일념으로 지금까지 살아 왔습니다.",
  ui_story_1020_10200201_51_dialog_content = "수년간 당신들 곁을 따르면서. 전 진작에 깨달았어야 했습니다...",
  ui_story_1020_10200201_52_dialog_content = "대원수님, 제가 정보장교가 된 목적은 제 정보를 통해 더 많은 이가\n전장에서 살아남게 하는 것이었습니다.",
  ui_story_1020_10200201_53_dialog_content = "하지만 제가 가져온 정보 때문에 대원수님께서는 암귀들에게 포위당했고,\n소중한 동료를 잃으셨습니다.",
  ui_story_1020_10200201_54_dialog_content = "정보장교가 정보에 불민해 엄중한 결과를 초래한 처벌은 달게 받겠습니다.\n하지만 그 전에...",
  ui_story_1020_10200201_55_dialog_content = "부디 율리시스 박사를 사형에 처해 주셨으면 합니다!",
  ui_story_1020_10200201_56_dialog_content = "아나톨리...",
  ui_story_1020_10200201_57_dialog_content = "얼마든지 기다리겠습니다! 어떻게 해서라도... 전 기필코...\n반드시 동료들의 희생에 대한 책임을 물을 겁니다!",
  ui_story_1020_10200201_58_dialog_content = "이건 제가 목숨을 걸고 맹세한 일입니다!",
  ui_story_1020_10200201_59_dialog_content = "<color=#e8d9bb>쾅──!</color>",
  ui_story_1020_10200201_60_dialog_content = "라인하르트...",
  ui_story_1020_10200201_61_dialog_content = "벨리사리아!",
  ui_story_1020_10200201_62_dialog_content = "율리시스의 입장이 어떻든, 난 결코 우리의 동포들이 이런 냉혹한 집단 속에서\n살아가게 두진 않겠다!",
  ui_story_1020_10200201_63_dialog_content = "지금 당장 판결을 내려라! 그렇지 않겠다면... 내가 직접 심판하겠다!",
  ui_story_1020_10200201_64_dialog_content = "「칼을 뽑았습니다.」",
  ui_story_1020_10200201_65_dialog_content = "「천둥의 힘...!」",
  ui_story_1020_10200201_66_dialog_content = "기다려──",
  ui_story_1020_10200201_67_dialog_content = "모두, 무기를 내려놔!",
  ui_story_1020_10200201_68_dialog_content = "......",
  ui_story_1020_10200201_69_dialog_content = "난 그 누구도 단죄하지 않아.\n내가 보기엔 너희 모두 일루미나의 생존을 위해 저마다 할 수 있는 선택을 했거든.",
  ui_story_1020_10200201_70_dialog_content = "그래서 난 율리시스의 실험도 지지했고, 마찬가지로 군부가 위원회의 명령을 무시하고\n멋대로 병력을 운용한 것도 지지했어.",
  ui_story_1020_10200201_71_dialog_content = "하지만 대국이 끝났으면 체스판의 기물들은 각자 자리로 돌아가는 게 순리야.",
  ui_story_1020_10200201_72_dialog_content = "대국? 기물? 넌 대체 자신을 뭐라고 생각하는 거냐?!",
  ui_story_1020_10200201_73_dialog_content = "지금 일루미나 내부에는 동포를 해치는 종양이 자라나 있고,\n외부에는 시시각각 자난성으로 다가오는 암귀가 있다...",
  ui_story_1020_10200201_74_dialog_content = "그런데도 여기 가만히 앉아, 아무 일도 없었다는 듯 넘어갈 수 있으리라 생각하나?",
  ui_story_1020_10200201_75_dialog_content = "난 다시는 일루미나가 암귀 토벌과 위험 지역 탐색의 선발대가 되게 하진 않아.",
  ui_story_1020_10200201_76_dialog_content = "이제 저들이 움직이지 않는다면, 일루미나도 움직이지 않아.",
  ui_story_1020_10200201_77_dialog_content = "지금 무슨 소릴 하는 거냐?",
  ui_story_1020_10200201_78_dialog_content = "위기가 다가오기 전까진, 일루미나는 먼저 나서지도, 스스로 팔을 자르지도 않을 거야.\n설령 그게 종양이 가득 자란 팔이라 해도 말이야.",
  ui_story_1020_10200201_79_dialog_content = "무슨 말인지 알겠어?!",
  ui_story_1020_10200201_80_dialog_content = "하하하하... 철가면님, 오로리안 간의 권력 게임을 평생 해 오셨으면서, 아직도 부족하십니까?",
  ui_story_1020_10200201_81_dialog_content = "이대로 가다가 모두가 맞이하게 될 결말이 무엇인지 제가 알려드려야겠습니까?",
  ui_story_1020_10200201_82_dialog_content = "차라리 죽을지언정, 일루미나가 백야성의 선발대로 전락하게 두진 않아!",
  ui_story_1020_10200201_83_dialog_content = "으... 귀가 먹겠어요...",
  ui_story_1020_10200201_84_dialog_content = "율리시스, 계속 말해 봐. 그럼 일루미나의 향후 10년의 잠재력이란 건 뭐지?",
  ui_story_1020_10200201_X84_dialog_content = "당신이 어떻게 해서든 전장에 내보내고 싶었던 대원수 후보자야?",
  ui_story_1020_10200201_85_dialog_content = "하하...",
  ui_story_1020_10200201_86_dialog_content = "「계명성 프로젝트」의 성과는 하나만 있는 게 아닙니다.\n향후 10년의 잠재력을 대표할 수 있는 자는... 바로 숀입니다.",
  ui_story_1020_10200201_87_dialog_content = "......",
  ui_story_1020_10200201_88_dialog_content = "......저요?",
  ui_story_1020_10200301_1_dialog_content = "<color=#e8d9bb>위이잉──</color>",
  ui_story_1020_10200301_2_dialog_content = "저기, 부르가 암호를 풀기 시작한 지도 이제 한참 되지 않았나요...?",
  ui_story_1020_10200301_3_dialog_content = "......",
  ui_story_1020_10200301_4_dialog_content = "제 말 안 듣고 있죠...?",
  ui_story_1020_10200301_5_dialog_content = "띠릭── 알골이 대기 모드에 진입했을 가능성이 있습니다. 1호가 알골을 깨우겠습니다.",
  ui_story_1020_10200301_6_dialog_content = "1호? 뭘 이렇게... 잔뜩 가져왔어?",
  ui_story_1020_10200301_7_dialog_content = "이것들은 알골이 자주 사용하는 컴퓨터 장치들입니다.\n1호는 이것들이 알골의 코어 구축 속도 향상에 도움을 줄 것이라고 생각합니다.",
  ui_story_1020_10200301_8_dialog_content = "<color=#e8d9bb>후두둑──</color>",
  ui_story_1020_10200301_9_dialog_content = "오오! 소리만 들어도 내 귀염둥이들인 거 딱 알겠어! 1호, 얼른 같이 조립하자!",
  ui_story_1020_10200301_10_dialog_content = "(진짜 「일어나」 버렸잖아?!)",
  ui_story_1020_10200301_11_dialog_content = "오늘 알골의 실행 속도는 아주 느리군요.",
  ui_story_1020_10200301_12_dialog_content = "그건 이 기계가 우리랑 세대 차이가 어마어마하게 많이 나서 그런 거야...",
  ui_story_1020_10200301_13_dialog_content = "그러고 보니까 이건 네 조상님이잖아?",
  ui_story_1020_10200301_14_dialog_content = "전혀 닮지 않은 조상님입니다.",
  ui_story_1020_10200301_15_dialog_content = "음... 암호 해독 시간도 내 예상을 훌쩍 뛰어넘었어.",
  ui_story_1020_10200301_16_dialog_content = "설마 부르가 매번 업그레이드를 해오면서 저 기호들 너머의 「언어」 규칙이\n낯설어진 건 아니겠지...?",
  ui_story_1020_10200301_17_dialog_content = "그래도 자기 프로토타입인데, 지금까지 멈추지도 않고 계속 처리 중이잖아.\n데이터는 얼마나 처리한 걸까...?",
  ui_story_1020_10200301_18_dialog_content = "알골이 초조해져서 발을 동동 구르고 있습니다.",
  ui_story_1020_10200301_19_dialog_content = "당연히 초조하지! 속이 타들어 가고 있다고!",
  ui_story_1020_10200301_20_dialog_content = "휴, 부르도 너처럼 아이테르랑 의식으로 소통할 수 있으면 좋았을 텐데!\n진짜 아주 일부분의 데이터라도 좋으니까...",
  ui_story_1020_10200301_21_dialog_content = "지금 여기 동시에 가동할 컴퓨터가 이렇게 많은데, 정작 내가 할 수 있는 건 아무것도 없잖아!",
  ui_story_1020_10200301_22_dialog_content = "...언어로 소통할 순 없지만, 전에 부르의 「정보」를 조금 감응할 순 있었어요.",
  ui_story_1020_10200301_23_dialog_content = "아니면 단서가 될 만한 게 있는지 다시 감응해 볼까요?",
  ui_story_1020_10200301_24_dialog_content = "마음 써 줘서 고맙지만, 부르가 널 공격하지 않는 것만 해도 다행일걸.",
  ui_story_1020_10200301_25_dialog_content = "...근데 저번에 부르는 학습 능력이 좋다고 그랬잖아요?\n아까 겪은 일도 있으니까, 이젠 부르가 절 믿어 주지 않을까요?",
  ui_story_1020_10200301_26_dialog_content = "똑똑하군요, PlayerName.",
  ui_story_1020_10200301_27_dialog_content = "일리가 있네... 어차피 다른 방법도 없으니까, 그럼 그냥 한 대 맞는다 생각하고 시도해 봐.",
  ui_story_1020_10200301_28_dialog_content = "맞는다고요?!",
  ui_story_1020_10200301_29_dialog_content = "으... 그럼... 부탁할게, 부르!",
  ui_story_1020_10200301_30_option_content = "(감응 연결──)",
  ui_story_1020_10200301_31_dialog_content = "......",
  ui_story_1020_10200301_32_dialog_content = "벌써 끝이야...? 혹시 부르가 거부했어?",
  ui_story_1020_10200301_33_dialog_content = "아니요... 「정보」가 바뀌는 속도가 너무 빨랐어요!",
  ui_story_1020_10200301_34_dialog_content = "...본 것 중에 도움이 될 만한 정보는 있었어?",
  ui_story_1020_10200301_35_dialog_content = "도움이 될 만한 정보라면...",
  ui_story_1020_10200301_36_option_content = "왠지 단서를 본 것 같아요.",
  ui_story_1020_10200301_37_dialog_content = "엄청나게 많은 단서들이... 하늘에서 떨어져 내렸어요.",
  ui_story_1020_10200301_38_dialog_content = "근데 단서가 아닐 수도 있어요...",
  ui_story_1020_10200301_39_dialog_content = "하나 마나 한 대답이잖아!",
  ui_story_1020_10200301_40_dialog_content = "아오! 왜 프로토타입하고 연결된 게 내가 아닌 거냐고──!",
  ui_story_1020_10200301_41_option_content = "숫자가 엄청 많았어요.",
  ui_story_1020_10200301_42_dialog_content = "그리고 굉장히 빠른 속도로 움직였어요!",
  ui_story_1020_10200301_43_dialog_content = "숫자? 0이랑 1들이었어? 몇 자리였는데? 고정된 패턴이 있었어?",
  ui_story_1020_10200301_44_dialog_content = "전부 해당하는 것 같긴 한데...",
  ui_story_1020_10200301_45_dialog_content = "몇 자리였는지랑 패턴은 제대로 못 봤어요...",
  ui_story_1020_10200301_46_option_content = "제대로 본 게 하나도 없어요.",
  ui_story_1020_10200301_47_dialog_content = "너무 빨리 지나가서 뭔지 보기도 전에 끝나 버렸어요.",
  ui_story_1020_10200301_48_dialog_content = "한 번 더 해볼게요!",
  ui_story_1020_10200301_49_dialog_content = "방금 한 번 해 봤으니까, 이번엔 제대로 볼 수 있을 거예요.",
  ui_story_1020_10200301_50_dialog_content = "무리 안 해도 돼. 부르는 나조차도 아직 이해하려고 노력 중인 존재니까.",
  ui_story_1020_10200301_51_dialog_content = "혹시라도 몸이 불편해지면, 바로 멈추고.",
  ui_story_1020_10200301_52_dialog_content = "네, 알겠어요.",
  ui_story_1020_10200301_53_dialog_content = "사실 귀환의 탑이 솟아오른 뒤부터 제 감응 능력도 왠지 많이 좋아진 것 같거든요.",
  ui_story_1020_10200301_54_dialog_content = "탑 위에서 빠르게 아스트라 대륙 곳곳을 파악했었는데,\n제 눈이 아니라 주변 환경의 눈을 빌리는 것 같은 느낌이었어요...",
  ui_story_1020_10200301_55_dialog_content = "뭔가 추상적인 느낌이네.\n그럼 그 방법으로 부르의 「정보」를 제대로 볼 수 있을 것 같단 얘기지?",
  ui_story_1020_10200301_56_dialog_content = "네, 주변 환경의 눈을 빌린다면...",
  ui_story_1020_10200301_57_dialog_content = "아무튼 일단 해볼게요!",
  ui_story_1020_10200301_58_option_content = "(감응 연결──)",
  ui_story_1020_10200301_59_dialog_content = "(빠, 빨라!)",
  ui_story_1020_10200301_60_dialog_content = "(어떻게든... 따라잡아야 해...)",
  ui_story_1020_10200301_61_dialog_content = "(으아... 눈이 빠질 것 같아...)",
  ui_story_1020_10200301_62_dialog_content = "(잠깐만! 내 눈이 아니라 주변 환경의 눈으로 봐야 해...)",
  ui_story_1020_10200301_63_dialog_content = "(우선 숫자열을 하나 고르고, 그다음은...)",
  ui_story_1020_10200301_64_option_content = "(감응 확장──)",
  ui_story_1020_10200301_65_dialog_content = "(......)",
  ui_story_1020_10200301_66_dialog_content = "(맞아, 이 숫자들...)",
  ui_story_1020_10200301_67_dialog_content = "(01105745630112... 2311111... 0010112231...)",
  ui_story_1020_10200301_68_dialog_content = "(알골 씨한테 이 숫자들을 가르쳐 주면... 암호를 빨리 풀 수 있겠지?)",
  ui_story_1020_10200301_69_dialog_content = "(근데... 내가 이걸 어떻게 기억하냐고...)",
  ui_story_1020_10200301_70_dialog_content = "보였어요! 숫자열들이 비처럼 내리고 있었어요!",
  ui_story_1020_10200301_71_dialog_content = "오오! 클리어 암호가 적혀 있었어?",
  ui_story_1020_10200301_72_dialog_content = "그렇게 간단하진 않지... 근데 클리어 암호는 아마 그 숫자들 중에 있을 거야.",
  ui_story_1020_10200301_73_dialog_content = "아이테르, 감응하면서 그 숫자들을 말해 줄 수 있겠어?",
  ui_story_1020_10200301_74_dialog_content = "충분한 데이터를 얻을 수 있다면, 다른 컴퓨터로 같이 암호 해독을 시도해 볼 수 있을 것 같아.",
  ui_story_1020_10200301_75_dialog_content = "지금 이게 줄이 아니라 숫자란 걸 구분하는 것만으로도 한계예요.\n소리 내 읽는 건 무리일 것 같아요...",
  ui_story_1020_10200301_76_dialog_content = "게다가...",
  ui_story_1020_10200301_77_dialog_content = "게다가?",
  ui_story_1020_10200301_78_dialog_content = "저 많은 숫자를 알골 씨가 기억하긴 힘들 것 같은데요...",
  ui_story_1020_10200301_79_dialog_content = "너, 나 믿어?",
  ui_story_1020_10200301_80_dialog_content = "당연히 믿죠... 근데 그건 왜요?",
  ui_story_1020_10200301_81_dialog_content = "짐작 가는 게 하나 있어...",
  ui_story_1020_10200301_82_dialog_content = "콜로서스에 인격이 탄생한 그 순간부터, 콜로서스라는 복잡한 「자동화 공장」도\n창조성과 적응성이란 능력을 얻게 됐어.",
  ui_story_1020_10200301_83_dialog_content = "창조성과 적응성은 우리의 뇌가 지닌 특별한 능력이고 말이야.",
  ui_story_1020_10200301_84_dialog_content = "덕분에 우린 여러 복잡한 상황이나 문제를 융통성 있게 해결할 수 있지만,\n가끔은 이 두 가지 능력이...",
  ui_story_1020_10200301_85_dialog_content = "기계화 연산 과정에서 「간섭」을 초래하는 바람에 작업 효율을 크게 떨어트리곤 하거든.",
  ui_story_1020_10200301_86_dialog_content = "그러니까 날 믿는다면, 네 창조성과 적응성을 잠깐 포기해 줘.",
  ui_story_1020_10200301_87_dialog_content = "창조성과 적응성을 포기하라고요? ...어떻게 포기하는데요?",
  ui_story_1020_10200301_88_dialog_content = "간단히 말해서, 생각하는 걸 잠깐 포기하고 기계처럼 행동하라는 거야.",
  ui_story_1020_10200301_89_dialog_content = "그런 건 한 번도 안 해봤는데요...",
  ui_story_1020_10200301_90_dialog_content = "내가 고강도 작업을 할 때 쓰는 방법이야. 나도 너랑 같이 그 숫자들을 최대한 기록할게.",
  ui_story_1020_10200301_91_dialog_content = "정보가 주는 충격을 걱정하지 말고 과정에만 집중해.\n충분한 정보가 의식 표면을 지나고 나면, 그 정보들은 분명히 흔적을 남길 테니까.",
  ui_story_1020_10200301_92_dialog_content = "날 믿어. 일단 그 상태에 들어서기만 하면, 시간이 끝없이 늘어나는 느낌이 들 거야.",
  ui_story_1020_10200301_93_dialog_content = "과정에 집중...",
  ui_story_1020_10200301_94_dialog_content = "땅에 추락해 버리면 잠에서 깰 수 있을지도 몰라...",
  ui_story_1020_10200301_95_dialog_content = "...아직도 공중에 떠 있네...?",
  ui_story_1020_10200301_96_dialog_content = "(마음속으로 추락을 담담히 받아들인 순간,\n땅으로 떨어지는 과정은 더없이 길게 느껴졌다...)",
  ui_story_1020_10200301_97_dialog_content = "왠지 무슨 말인지 알 것 같아요.",
  ui_story_1020_10200301_98_dialog_content = "뭔가 생각난 거야?",
  ui_story_1020_10200301_99_dialog_content = "엄밀히 말하면 추락은 아니지만... 어쨌든, 대충 어떻게 해야 할지 알겠어요.",
  ui_story_1020_10200301_100_option_content = "(감응 심화──)",
  ui_story_1020_10200301_101_dialog_content = "어라... PlayerName의 눈동자가 엄청 빨리 움직이고 있어...",
  ui_story_1020_10200301_102_dialog_content = "이렇게 신기한 PlayerName 머릿속엔 대체 뭐가 들어있을지\n참 확인해 보고 싶다니까.",
  ui_story_1020_10200301_103_dialog_content = "선포할게. 지금부터 아이테르는 내 연구 조수야.\n이번 일이 끝나면 아이테르한테 새 옷을 만들어 줘야겠어!",
  ui_story_1020_10200301_104_dialog_content = "알골은 아이테르와 친구가 되고 싶어 합니다.",
  ui_story_1020_10200301_105_dialog_content = "몸에 입는 저런 옷 말고, 너 같은 기계 케이스 말하는 거야.",
  ui_story_1020_10200301_106_dialog_content = "띠릭──",
  ui_story_1020_10200301_107_dialog_content = "11101100...",
  ui_story_1020_10200301_108_dialog_content = "오! 뭔가 말한다!",
  ui_story_1020_10200301_109_dialog_content = "2진법인가?!",
  ui_story_1020_10200301_110_dialog_content = "010221111, 022211110101...",
  ui_story_1020_10200301_111_dialog_content = "...아니잖아?",
  ui_story_1020_10200301_112_dialog_content = "1호, 얼른 녹음해. 하나라도 놓치면 안 되니까.",
  ui_story_1020_10200301_113_dialog_content = "띠릭, 1호는 이해했습니다.",
  ui_story_1020_10200301_114_dialog_content = "그로누, 미자드도 옆에 있는 컴퓨터로 같이 해 줘!\n루미나로 보조해 줄 테니까, 정신을 집중해.",
  ui_story_1020_10200301_115_dialog_content = "응!",
  ui_story_1020_10200301_116_dialog_content = "0101157567565500101... 100150115332234560101...",
  ui_story_1020_10200301_117_dialog_content = "(5열... 6열... 7, 8, 9...)",
  ui_story_1020_10200301_118_dialog_content = "(대체 몇 개나 있는 거야...)",
  ui_story_1020_10200301_119_dialog_content = "(잠깐만... 내 눈이 이상해졌나? 왠지 뭔가... 번쩍이는 것 같은데?)",
  ui_story_1020_10200301_120_dialog_content = "(이, 이런... 또 생각하기 시작했어...)",
  ui_story_1020_10200301_121_dialog_content = "(으윽... 너무 빨라... 따라잡기가... 너, 너무 힘들어!)",
  ui_story_1020_10200401_1_dialog_content = "율리시스 박사님, 대체... 그게 무슨 말씀이세요?",
  ui_story_1020_10200401_2_dialog_content = "너, 잉겔, 악셀리아. 너희 셋은 모두 「계명성 프로젝트」의 산물이다.",
  ui_story_1020_10200401_3_dialog_content = "......",
  ui_story_1020_10200401_4_dialog_content = "......",
  ui_story_1020_10200401_5_dialog_content = "「계명성 프로젝트」의 산물은 잉겔처럼 똑똑하고,\n악셀리아처럼 암귀를 날려버리는 강한 오로리안이겠죠...",
  ui_story_1020_10200401_6_dialog_content = "전...",
  ui_story_1020_10200401_7_dialog_content = "너는 네 생각보다 강하다, 숀.",
  ui_story_1020_10200401_8_dialog_content = "「강하다」... 저한테 그런 말이 쓰이는 건 처음인 것 같은데요...",
  ui_story_1020_10200401_9_dialog_content = "악셀리아, 내 주먹을 받아! 이야아압──!",
  ui_story_1020_10200401_10_dialog_content = "아얏──!",
  ui_story_1020_10200401_11_dialog_content = "......",
  ui_story_1020_10200401_12_dialog_content = "전 악셀리아랑 주먹을 맞부딪치는 것만으로도 아픈데... 「강하다」니...",
  ui_story_1020_10200401_13_dialog_content = "얘가 신병이라고? 이런 꼬마가? 더스크 타운은 너 같은 애가 올 곳이 아냐!",
  ui_story_1020_10200401_14_dialog_content = "......",
  ui_story_1020_10200401_15_dialog_content = "너 자난성에서 뭔 잘못을 했길래 여기로 보내진 거냐?\n이 정도 암귀도 못 이기는 녀석이 말이야!",
  ui_story_1020_10200401_16_dialog_content = "......",
  ui_story_1020_10200401_17_dialog_content = "제게 이런 말을 할 자격이 없단 건 알고 있습니다.\n하지만 우린 힘든 환경에서도 최선을 다해 자신을 갈고닦아야 합니다, 숀.",
  ui_story_1020_10200401_18_dialog_content = "그럴게요, 참모장님...",
  ui_story_1020_10200401_19_dialog_content = "큰 힘엔 큰 책임이 따르는 거다. 내가 숀 너보다 「강한」 사람이잖냐, 하하하! 안 그래?",
  ui_story_1020_10200401_20_dialog_content = "하지만... 여긴 제 담당 구역이잖아요.",
  ui_story_1020_10200401_21_dialog_content = "괜찮아, 그때 가서 내가 반장님한테 이 구역의 암귀가 너무 강했다고 말씀드리면 되니까.",
  ui_story_1020_10200401_22_dialog_content = "......",
  ui_story_1020_10200401_23_dialog_content = "빨리 뛰어라! 숀! 더 빨리!",
  ui_story_1020_10200401_24_dialog_content = "...네, 네엡!",
  ui_story_1020_10200401_25_dialog_content = "그러니까, 저도 잉겔이랑 악셀리아처럼 강한 개체라는 건가요...?",
  ui_story_1020_10200401_26_dialog_content = "그런데 왜... 제 두 손만...",
  ui_story_1020_10200401_27_dialog_content = "이렇게 굳은살로 가득한 건가요...?",
  ui_story_1020_10200401_28_dialog_content = "훈련이 남긴 이 흔적들... 아무리 봐도 저처럼 쓸모없는 녀석의 몸에만 남는 거잖아요.",
  ui_story_1020_10200401_29_dialog_content = "두 손뿐만이 아니라... 제 온몸 곳곳엔 훈련 중에 생긴 흉터들로 가득해요...",
  ui_story_1020_10200401_30_dialog_content = "제 노력이 부족했기 때문인가요?",
  ui_story_1020_10200401_31_dialog_content = "숀...",
  ui_story_1020_10200401_32_dialog_content = "널 더스크 타운으로 보냈던 이유는 실험 초기에 네가 「실패작」으로 판명됐기 때문이다.",
  ui_story_1020_10200401_33_dialog_content = "하지만 실험의 시작 단계에서는 늘 각종 오판이 발생하기 마련이다.",
  ui_story_1020_10200401_34_dialog_content = "「실패작」...",
  ui_story_1020_10200401_35_dialog_content = "역시 제가 더스크 타운으로 보내진 건 실패작이라서 그랬던 거네요... 하하...",
  ui_story_1020_10200401_36_dialog_content = "숀, 저런 헛소리를 귀담아들을 필요는 없다. 그건 네 잘못이 아니다.",
  ui_story_1020_10200401_37_dialog_content = "저 계획에선 우리 모두가 「실패작」이거든.",
  ui_story_1020_10200401_38_dialog_content = "위로해 주셔서 감사해요. 하지만 전 다 알아요... 결국 전 모두와 다르다는 걸요...",
  ui_story_1020_10200401_39_dialog_content = "더스크 타운으로 보낸 「실패작」이 어떻게 일루미나의 미래를 위한 잠재력이 됐다는 겁니까?",
  ui_story_1020_10200401_40_dialog_content = "요점을 말해, 율리시스.",
  ui_story_1020_10200401_41_dialog_content = "「철가면」 님답군요...",
  ui_story_1020_10200401_42_dialog_content = "우리가 숀에 대한 연구를 중도에 포기한 건 맞습니다.\n하지만 숀은 어둠의 밑바닥과 가까운 더스크 타운에 간 뒤로부터 신체에 변화가 발생했습니다.",
  ui_story_1020_10200401_43_dialog_content = "지속적인 검증을 통해 저는 숀의 루미나틱스가 유전자 결함으로 인한 제약을 받은 게 아니라,\n오히려 그가 다크매터를 흡수할 수 있게 만들었다는 사실을 발견했습니다.",
  ui_story_1020_10200401_44_dialog_content = "그 다크매터들은 루미나로 전환해 활용할 수는 없지만,\n암귀와 맞서는 과정에서 숀의 몸에 강력한 배리어를 형성했습니다.",
  ui_story_1020_10200401_45_dialog_content = "페피타가 어둠의 밑바닥 탐색에 대동했던 병사들도 이와 유사한 특징을 보인 바 있습니다.",
  ui_story_1020_10200401_46_dialog_content = "학술적인 내용은 이 정도로 끝내지요.\n요컨대 저들은 암귀에게서 승리를 거둘, 오로리안의 희망인 것입니다!",
  ui_story_1020_10200401_47_dialog_content = "기체 강화 실험 방안도 이미 작성해 두었습니다.\n머지않아 이번 실험의 산물은 어둠의 밑바닥에 들어갈 수 있을 겁니다.",
  ui_story_1020_10200401_48_dialog_content = "웃기지 마라, 율리시스! 일루미나가 네 헛수작을 계속 용납할 것 같으냐!",
  ui_story_1020_10200401_49_dialog_content = "숀! 내 말 잘 들어라!",
  ui_story_1020_10200401_50_dialog_content = "넌 일루미나의 군인이 널 암귀 손에서 구해 고아원으로 보낸 걸로 알고 있겠지.\n네 신상 기록에도 그렇게 적혀 있었을 테니 말이야.",
  ui_story_1020_10200401_51_dialog_content = "하지만 널 암귀들이 있는 곳에 데리고 가서 네가 죽길 바랐던 건 바로 네 부모였다!",
  ui_story_1020_10200401_52_dialog_content = "그들은 신체적 결함으로 갖은 고통을 받았고, 그래서 네가 아무것도 모를 때\n빨리 그 고통에서 벗어나길 바랐던 것이다.",
  ui_story_1020_10200401_53_dialog_content = "하지만 바로 「계명성 프로젝트」 덕분에 넌 더는 고통을 받지 않게 되었다.",
  ui_story_1020_10200401_54_dialog_content = "내가 진행한 신체 개조가 네게 두 번째 삶을 부여한 거란 말이다.\n만약 네가 타인에게 인정받는 「강한」 사람이 되고 싶다면, 반드시...",
  ui_story_1020_10200401_55_dialog_content = "율리시스 교수님... 대체 뭘 하시려는 거죠?",
  ui_story_1020_10200401_56_dialog_content = "어둠의 밑바닥으로 가서 암귀들의 희망을 꺾어라... 약속해라!",
  ui_story_1020_10200401_57_dialog_content = "더스크 타운의 보잘것없는 병사가 아니라, 네 유전자의 우세를 발휘해\n이클립스 내부로 침투하는 오로리안 영웅이 되는 것이다!",
  ui_story_1020_10200401_58_dialog_content = "그때가 되면... 암귀를 모조리 없애고...\n어둠 속에 숨은 그 악마를 두 눈으로 똑똑히 보아라...",
  ui_story_1020_10200401_59_dialog_content = "율리시스, 멈춰라!",
  ui_story_1020_10200401_60_dialog_content = "숀에게 다가오지 마세요, 교수님!",
  ui_story_1020_10200401_61_dialog_content = "타인의 목숨은 아랑곳하지 않고 실험을 해오셨던 당신이...\n이제 와서 숀을 자신이 구했다고 말씀하신다니...",
  ui_story_1020_10200401_62_dialog_content = "교수님의 그런 냉혹하고 이기적인 모습... 이젠 진절머리가 나요!",
  ui_story_1020_10200401_63_dialog_content = "이제 그 누구도 숀의 목숨을 포기하고, 빼앗고, 멋대로 휘두를 수 없어요!",
  ui_story_1020_10200401_64_dialog_content = "그 누구도 숀의 목숨을 포기하고, 빼앗고, 멋대로 휘두를 수 없습니다.",
  ui_story_1020_10200401_65_dialog_content = "...잉겔, 악셀리아... 날 이렇게 꽁꽁 싸맬 것까진 없잖아... 헤헷...",
  ui_story_1020_10200401_66_dialog_content = "근데 율리시스 교수님 말이 맞아...\n날 데리고 암귀한테 뛰어든 건 내 부모님이었어.",
  ui_story_1020_10200401_67_dialog_content = "전에 난 그게 꿈이라고 늘 생각했어...",
  ui_story_1020_10200401_68_dialog_content = "그렇게 생생한 느낌이... 꿈일 리가 없겠지만 말이야... 아하하...",
  ui_story_1020_10200401_69_dialog_content = "그치만 난 그날을 「부모님이 용감하게 날 구하다가 돌아가신 날」로 기억하기로 했어.",
  ui_story_1020_10200401_70_dialog_content = "엄청 바보 같겠지만... 그런 멍청한 생각에 기대야만 낙천적으로 살아갈 수 있었거든...",
  ui_story_1020_10200401_71_dialog_content = "그날 어떤 일이 있었는지 이제 더는 중요하지 않아요, 숀.",
  ui_story_1020_10200401_72_dialog_content = "당신은 더스크 타운, 아니... 일루미나의 우수한 전사니까요!",
  ui_story_1020_10200401_73_dialog_content = "지금의 숀은 악셀리아와 같습니다. 우리는 수많은 암귀를 쓰러트린 일루미나의 군인입니다.",
  ui_story_1020_10200401_74_dialog_content = "이렇게 말한다면 제가 이기적이라고 생각할 수도 있겠지만,\n악셀리아는 숀이 영웅도, 전사도 될 필요가 없다고 생각합니다.",
  ui_story_1020_10200401_75_dialog_content = "숀은 숀이면 되는 겁니다.",
  ui_story_1020_10200401_76_dialog_content = "하하하하! 너흰 고대 전쟁의 실패를 또다시 반복할 작정이냐?",
  ui_story_1020_10200401_77_dialog_content = "이 세상은 그리 간단한 게 아니다... 나는 이클립스의 힘을 직접 보았다.\n그리고 오로리안이 살아남을 수 있는 방법은 오직 이것뿐이다.",
  ui_story_1020_10200401_78_dialog_content = "온갖 실험으로 동포들의 목숨을 희생시킨 건 너다! 우리 일루미나를,\n그리고 모든 오로리안을 파멸로 몰아넣고 있는 건 바로 너란 말이다!",
  ui_story_1020_10200401_79_dialog_content = "전쟁 병기가 제게 희생과 파멸을 운운할 수 있다고 생각합니까...?",
  ui_story_1020_10200401_80_dialog_content = "전 노라가 정말 부럽습니다. 젊은 나이에 루미나와 다크매터 속 숨겨진 힘의 가설을 세우고,\n자신의 이상을 관철해 나가고 있지 않습니까.",
  ui_story_1020_10200401_81_dialog_content = "하지만 당신들은 중요하지도 않은 죽음들을 강조하며 그저 감정에 호소할 뿐이지요...",
  ui_story_1020_10200401_82_dialog_content = "바로 그런 사사로운 감정이 오로리안들의 손발을 묶어 진보를 막은 것이고...",
  ui_story_1020_10200401_83_dialog_content = "당신들의 아둔함이 더 많은 이들을 희생시킨 것입니다...",
  ui_story_1020_10200401_84_dialog_content = "오로리안이 죽음을 두려워하게 만들면... 그저 죽음만 기다리게 될 뿐입니다...",
  ui_story_1020_10200401_85_dialog_content = "하지만 저는 감정의 노예가 되지 않을 겁니다...",
  ui_story_1020_10200401_86_dialog_content = "절대로!",
  ui_story_1020_10200401_87_dialog_content = "전 익숙해질 것입니다...",
  ui_story_1020_10200401_88_dialog_content = "1분 1초마다 오로리안이 죽고 있습니다!\n수십, 수백, 수천, 수만 명이 죽고 있다는 그 사실에 무뎌져야 한단 말입니다!",
  ui_story_1020_10200401_89_dialog_content = "눈앞의 그 누구라도 언젠가는 썩어 문드러질 백골로 보고, 그 모든 것을 뛰어넘어...\n강인한 육체와 정신을 지닌 오로리안을 만들어낼 것입니다!",
  ui_story_1020_10200401_90_dialog_content = "여러분은... 진화에 대해 들어 본 적 있습니까? 오로리안은 반드시 진화해야만 합니다...",
  ui_story_1020_10200401_91_dialog_content = "1분, 1초, 매 순간 진화해 나가야만 합니다...",
  ui_story_1020_10200401_92_dialog_content = "우리가 종말에서 살아남을 길은 오직 그것뿐입니다.\n그래야만 두 눈을 부릅뜨고, 강한 육체와 함께...",
  ui_story_1020_10200401_93_dialog_content = "하늘로... 날아오를 것입니다...",
  ui_story_1020_10200401_94_dialog_content = "율리시스 님... 괜찮으십니까...?",
  ui_story_1020_10200401_95_dialog_content = "진화... 이 얼마나 아름다운 단어인가...",
  ui_story_1020_10200401_96_dialog_content = "1분, 1초, 매 순간 진화해 나가야만 해...",
  ui_story_1020_10200401_97_dialog_content = "율리시스 님──!",
  ui_story_1020_10200401_98_dialog_content = "미쳐버린 건가요?",
  ui_story_1020_10200401_99_dialog_content = "직접 보지 않았다면... 나 역시 믿지 못했을 거다...",
  ui_story_1020_10200401_100_dialog_content = "왜 저러는 거지?",
  ui_story_1020_10200401_101_dialog_content = "저게 바로 내가 찬드라를 증인으로 불러 달라고 고집한 이유다.",
  ui_story_1020_10200401_102_dialog_content = "저 여기 있어요, 대원수님.",
  ui_story_1020_10200401_103_dialog_content = "모두에게 율리시스의 상태에 대해 설명해 주도록.",
  ui_story_1020_10200401_104_dialog_content = "네, 대원수님. 율리시스 박사는 심리 치료 기간에 종종 저렇게\n초점 없는 눈으로 어딘가를 바라볼 때가 있었어요...",
  ui_story_1020_10200401_105_dialog_content = "하지만 시간이 조금 지나면 언제 그랬냐는 듯 다시 정상으로 되돌아왔죠.",
  ui_story_1020_10200401_106_dialog_content = "......",
  ui_story_1020_10200401_107_dialog_content = "찬드라 증인, 계속해...",
  ui_story_1020_10200401_108_dialog_content = "율리시스 교수는 10년 전부터 심리 치료를 받기 시작했어요. 이건 그 치료 기록이에요.",
  ui_story_1020_10200401_109_dialog_content = "제가 그 당시의 치료에 참여한 건 아니지만, 과거의 치료 기록을 확인해 보니,\n그땐 암귀 군단이 각 세력과 총력전을 벌였던 시기더군요.",
  ui_story_1020_10200401_110_dialog_content = "게다가 이번 연합 훈련이 시작되기 몇 달 전, 율리시스 교수가 메디컬 센터에서\n심리 치료를 받는 횟수가 다시 증가했어요.",
  ui_story_1020_10200401_111_dialog_content = "그리고 얼마 뒤 수배자 노라가 X호 연구소에 잠입했고,\n팬텀이 자난성에서 「가디언 1호」의 코어를 탈취했죠.",
  ui_story_1020_10200401_112_dialog_content = "이 두 핵심 사건의 공통점은 모두 율리시스 박사가 참여했다는 거예요.\n그래서 저흰 율리시스 박사와 이클립스 간에 특수한 연락 방식이 있다고 의심하고 있어요.",
  ui_story_1020_10200401_113_dialog_content = "......",
  ui_story_1020_10200401_114_dialog_content = "내가 주목했던 건 율리시스 박사가 치료 과정 중에 묘사했던 기괴한 장면들이었다...",
  ui_story_1020_10200401_115_dialog_content = "그 얼음기둥은 아래로 떨어지는 물이 얼어붙은 게 아니라,\n거대한 암석이 위로 상승한 것이었습니다...",
  ui_story_1020_10200401_116_dialog_content = "구동 성분이 소진되면 연결은 끊어집니다.\n하지만 유일한 눈은 아직 하늘에서 우리를 주시하고 있지요...",
  ui_story_1020_10200401_117_dialog_content = "상승하는 얼음기둥, 구동 성분... 주시하는 눈...",
  ui_story_1020_10200401_118_dialog_content = "아스트라 대륙에 존재할 수 없는 이런 장면을, 자난성에서 단 한 발짝도\n나간 적 없는 율리시스가 어떻게 알 수 있지?",
  ui_story_1020_10200401_119_dialog_content = "너도 당연히 의구심이 들 텐데, 벨리사리아. 이건 절대로 우연이 아니다!",
  ui_story_1020_10200401_120_dialog_content = "어떻게 저렇게 확신하는 거죠?",
  ui_story_1020_10200401_121_dialog_content = "증거는?",
  ui_story_1020_10200401_122_dialog_content = "한때 암귀가 되어... 어둠의 밑바닥 깊은 곳까지 가 봤던 헬리오스의 회고록에도\n같은 내용이 있었기 때문이다!",
  ui_story_1020_10200401_123_dialog_content = "위원회는 헬리오스의 의식이 온전히 회복되지 않았다는 점을 빌미로 내 혐의의 철회를 미뤄 왔다.",
  ui_story_1020_10200401_124_dialog_content = "만약 이 사실이 내가 율리시스를 고발한 내용과 맞아떨어진다면,\n너희는 또 어떤 변명을 할 생각이지?",
  ui_story_1020_10200401_125_dialog_content = "전 그게 생각나는군요. 여러분은 어떻습니까.",
  ui_story_1020_10200401_126_dialog_content = "그 팬텀 말입니까?",
  ui_story_1020_10200401_127_dialog_content = "녀석이 말한 게 이거였나...",
  ui_story_1020_10200401_128_dialog_content = "......",
  ui_story_1020_10200401_129_dialog_content = "내 곁에서 시간을 낭비할 필요는 없다.",
  ui_story_1020_10200401_130_dialog_content = "그분이 강림하시고 나면, 고리가 없는 것들은 그저 바닥을 기어다니며 두려움에 떨고,\n그 하찮은 목숨을 잃게 될 수밖에 없을 테니 말이다.",
  ui_story_1020_10200401_131_dialog_content = "고리가 뭐냐?!",
  ui_story_1020_10200401_132_dialog_content = "감히 그분의 고리를 얻겠다는 헛된 망상을 하는 것이냐?\n이 비천한 짐승들, 도적놈들, 기생충 놈들이!",
  ui_story_1020_10200401_133_dialog_content = "600년 전... 저 부유섬은 본디 내 격을 높여줄 발판이 되었을 터였다!",
  ui_story_1020_10200401_134_dialog_content = "부유섬이라면... 백야성을 말하는 건가?",
  ui_story_1020_10200401_135_dialog_content = "그분께서 강림하시고 나면 내게 다시금 그 영광의 기회를 내려 주실 것이다.\n그리하면 나는 다시 전당으로 향하여 그분의 품으로 돌아갈 수 있겠지.",
  ui_story_1020_10200401_136_dialog_content = "너흰 왜 오로리안을 적대하는 거지?",
  ui_story_1020_10200401_137_dialog_content = "너희 오로리안들이 끝없는 탐욕으로 너희 것이 아닌 그분의 피조물을 탐하기 때문이 아니더냐!",
  ui_story_1020_10200401_138_dialog_content = "그분께서는 당신께서 세우신 모든 것을 되찾으실 것이다!",
  ui_story_1020_10200401_139_dialog_content = "크크크크크!",
  ui_story_1020_10200401_140_dialog_content = "......",
  ui_story_1020_10200401_141_dialog_content = "일루미나가 세워지기 전부터 존재하던 그 고대의 기계가... 이 모든 일의 근원이었나...",
  ui_story_1020_10200401_142_dialog_content = "이게 바로 일루미나의 숙명이란 말인가, 하하...",
  ui_story_1020_10200401_143_dialog_content = "그 기계는 지금 어디 있죠?",
  ui_story_1020_10200401_144_dialog_content = "어느 창고 안에 있습니다. 당신이 점찍은 천재가 지켜보는 중입니다만.",
  ui_story_1020_10200401_145_dialog_content = "진화, 이 얼마나 아름다운 단어인가...",
  ui_story_1020_10200401_146_dialog_content = "1분, 1초, 매 순간 진화해 나가야만 해...",
  ui_story_1020_10200401_147_dialog_content = "......",
  ui_story_1020_10200501_1_dialog_content = "...이게 다야?",
  ui_story_1020_10200501_2_dialog_content = "대조해 봤는데 틀리거나 빠트린 건 없었어. 알골 박사가 보기엔 뭐가 모자란데?",
  ui_story_1020_10200501_3_dialog_content = "이건 내 예상보다 훨씬 적어. 이 수열은 순환 구조를 이루고 있어...\n아마 어떤 한정된 문자의 조합일지도 몰라.",
  ui_story_1020_10200501_4_dialog_content = "게다가 최초의 프로그램 언어는 「가디언」 시스템에서 비롯됐어.\n그러니까 어떻게 변화해 왔든, 언어의 규칙은 서로 통하겠지.",
  ui_story_1020_10200501_5_dialog_content = "내 프로그램은 이 데이터들을 기반으로 분석해서 그 조합 논리를 알아낼 수 있어.",
  ui_story_1020_10200501_6_dialog_content = "그럼 금방 이 컴퓨터들이랑 부르를 통해서 완전한 「가디언」 시스템에\n로그인할 수 있게 될 거야!",
  ui_story_1020_10200501_7_dialog_content = "정말 한정된 문자의 조합이라면, PlayerName의 감응이 왜 아직도 안 끝난 거죠?\n혹시 무슨 일이 생긴 건 아니겠죠?",
  ui_story_1020_10200501_8_dialog_content = "맞아! 머리카락이 다 솟아 올랐다구... 저거 왠지 뭐랑 닮았는데, 뭐였지...?",
  ui_story_1020_10200501_9_dialog_content = "금방 끝날 거야... 금방...",
  ui_story_1020_10200501_10_dialog_content = "부부!",
  ui_story_1020_10200501_11_dialog_content = "좋았어!",
  ui_story_1020_10200501_12_dialog_content = "이제 순서대로 입력만 하면...",
  ui_story_1020_10200501_13_dialog_content = "<color=#e8d9bb>삐비빅──</color>",
  ui_story_1020_10200501_14_dialog_content = "...틀렸다고?",
  ui_story_1020_10200501_15_dialog_content = "아, 그래! 패배자의 지금 헤어스타일, 부르의 촉수랑 똑같이 생겼잖아!",
  ui_story_1020_10200501_16_dialog_content = "설마 PlayerName 머리도 부르처럼 엄청난 연산력을 지닌 기계는 아니겠지?",
  ui_story_1020_10200501_17_dialog_content = "알골 박사, 전 PlayerName의 안전이 우려돼요!",
  ui_story_1020_10200501_18_dialog_content = "...감응 능력이 아무리 대단해도 컴퓨터가 될 순 없어...",
  ui_story_1020_10200501_19_dialog_content = "그럼 일단 깨우는 게...",
  ui_story_1020_10200501_20_dialog_content = "85...... X...... 32875...... X......",
  ui_story_1020_10200501_21_dialog_content = "뭐야?!",
  ui_story_1020_10200501_22_dialog_content = "얘 방금 뭐라고 했어?",
  ui_story_1020_10200501_23_dialog_content = "...「X」?",
  ui_story_1020_10200501_24_dialog_content = "...숫자만으로 이루어진 배열이 아니었던 거야...?",
  ui_story_1020_10200501_25_dialog_content = "3292...... X...... 4782...... X...... 2212323293845......",
  ui_story_1020_10200501_26_dialog_content = "얼굴이 새빨개졌어! 꼭 감전된 것 같아!",
  ui_story_1020_10200501_27_dialog_content = "......12983289...... X......",
  ui_story_1020_10200501_28_dialog_content = "50227833...... X......",
  ui_story_1020_10200501_29_dialog_content = "이 녀석... 설마 부르의 연산 속도를 따라잡은 거야...? 이대로는 위험해...",
  ui_story_1020_10200501_30_dialog_content = "...근데 지금 끝내면 이 정보들을 다시 얻긴 어려울 거야...",
  ui_story_1020_10200501_31_dialog_content = "이렇게 하자! 얘한테 내 밴드를 채워 주고 2분만 지켜보자.",
  ui_story_1020_10200501_32_dialog_content = "...그게 무슨 효과가 있죠?",
  ui_story_1020_10200501_33_dialog_content = "뇌세포를 최고 속도로 활용할 수 있는 한계가 2분이야.\n그리고 이 밴드는 착용자의 몸 상태를 모니터링할 수 있어.",
  ui_story_1020_10200501_34_dialog_content = "정보량이 착용자의 신체 한계를 넘어서면, 밴드에서 경고음이 울릴 거야.",
  ui_story_1020_10200501_35_dialog_content = "그전까지 그로누랑 1호는 한 번 더 나랑 같이 내용을 기록해 줘.\n2분 안에 쓸만한 정보를 최대한 많이 모아야 해.",
  ui_story_1020_10200501_36_dialog_content = "일부라도 좋아. 이건 지금 우리가 유일하게 얻을 수 있는 프로토타입의 심층 정보일지도 몰라!",
  ui_story_1020_10200501_37_dialog_content = "알겠어!",
  ui_story_1020_10200501_38_dialog_content = "1호는 이해했습니다.",
  ui_story_1020_10200501_39_dialog_content = "비비안 참모장은 시간을 보고 있다가 2분이 되면 바로 우리를 멈춰 줘.",
  ui_story_1020_10200501_40_dialog_content = "알겠어요.",
  ui_story_1020_10200501_41_dialog_content = "미자드, 2분 안에 밴드에서 경고음이 울리면,\n당신이 곧바로 PlayerName 얠 끄집어내.",
  ui_story_1020_10200501_42_dialog_content = "응, 나한테 맡겨!",
  ui_story_1020_10200501_43_dialog_content = "862033934...... X......",
  ui_story_1020_10200501_44_dialog_content = "385782493666...... X......",
  ui_story_1020_10200501_45_dialog_content = "띠릭, 띠릭, 띠리릭...",
  ui_story_1020_10200501_46_dialog_content = "236758423423...... X......",
  ui_story_1020_10200501_47_dialog_content = "(「X」?)",
  ui_story_1020_10200501_48_dialog_content = "(저 번쩍이는 글자, 「X」인가? 내가 잘못 본 건 아니겠지?)",
  ui_story_1020_10200501_49_dialog_content = "(으... 시간이 한참 지났을 것 같은데...)",
  ui_story_1020_10200501_50_dialog_content = "(근데 아까처럼 머리가 아프진 않아!)",
  ui_story_1020_10200501_51_dialog_content = "(그치만 이 「X」는 대체 뭐냐고...)",
  ui_story_1020_10200501_52_dialog_content = "(으아아... 또 속도가 빨라졌어...)",
  ui_story_1020_10200502_1_dialog_content = "부부! 부부! 부부!",
  ui_story_1020_10200502_2_dialog_content = "2분이에요!",
  ui_story_1020_10200502_3_dialog_content = "좋아!",
  ui_story_1020_10200502_4_dialog_content = "부부부! 부부, 부부──",
  ui_story_1020_10200502_5_dialog_content = "자, 옳지... 처, 천천히...",
  ui_story_1020_10200502_6_dialog_content = "그럼 이제부터 이 기계들도 같이 사용해서 데이터를 분석해 봐야겠어.\n이번엔 분명히 문제없을 거야.",
  ui_story_1020_10200502_7_dialog_content = "부우!",
  ui_story_1020_10200502_8_dialog_content = "으윽──!",
  ui_story_1020_10200502_9_dialog_content = "PlayerName, 괜찮아요?!",
  ui_story_1020_10200502_10_dialog_content = "...우와! 혈압이 엄청 높아! 혈중 산소 포화도는... 야, 우리 잘 보여?",
  ui_story_1020_10200502_11_dialog_content = "보, 보여...",
  ui_story_1020_10200502_12_dialog_content = "일단 앉아서 가만히 있어. 이제 눈동자만 내 손가락을 따라 움직여 봐.",
  ui_story_1020_10200502_13_dialog_content = "(왼쪽... 오른쪽...)",
  ui_story_1020_10200502_14_dialog_content = "지금 느낌이 어때?",
  ui_story_1020_10200502_15_dialog_content = "...머리가... 하아, 조금 어지럽고... 팔다리에 힘이 잘 안 들어가...",
  ui_story_1020_10200502_16_dialog_content = "속이 울렁거리거나 눈이 흐릿하진 않아?",
  ui_story_1020_10200502_17_dialog_content = "그렇진 않은 것 같아요...",
  ui_story_1020_10200502_18_dialog_content = "이거 마셔.",
  ui_story_1020_10200502_19_dialog_content = "이게 뭔데요?",
  ui_story_1020_10200502_20_dialog_content = "두뇌를 최대로 활용하고 나면 산소결핍증이 동반되는 경우가 많아.\n이런 건 나도 나름 전문가거든.",
  ui_story_1020_10200502_21_dialog_content = "근데 네 감응 능력으로 이 정도까지 할 수 있을 줄은 몰랐어. 정말 큰 도움이 됐다니까!",
  ui_story_1020_10200502_22_dialog_content = "저도 진짜 생각도 못 했어요... 처음엔 숫자가 바뀌는 게 너무 빨라서,\n정보를 제대로 보려고 수열을 하나 응시하는 것만으로도 힘들었거든요.",
  ui_story_1020_10200502_23_dialog_content = "그러다 하나씩 제대로 보겠다는 생각 대신 알골 씨 말대로 생각하는 걸 포기했더니...\n오히려 숫자들이 자연스럽게 「흘러들어」 왔어요...",
  ui_story_1020_10200502_24_dialog_content = "중간에 잠깐 다시 생각을 하기 시작했는데...",
  ui_story_1020_10200502_25_dialog_content = "그걸 눈치채기라도 한 것처럼 속도가 또 빨라졌구요...",
  ui_story_1020_10200502_26_dialog_content = "빨라졌다... 느려졌다... 생각을 하니까... 속도가 또 빨라지고...\n학습 반사궁 그 자체잖아...",
  ui_story_1020_10200502_27_dialog_content = "잠깐만, 생각하는 걸 포기했다면서? 그럼 수열을 어떻게 읽어냈는데?\n너 대체 무슨 괴물인 거야...?!",
  ui_story_1020_10200502_28_dialog_content = "너... 진짜 AI인 거 아냐?",
  ui_story_1020_10200502_29_dialog_content = "그, 그건 또 무슨 의심이냐구요...",
  ui_story_1020_10200502_30_dialog_content = "아, 그래서 숫자 사이에 있던 「X」는 뭐였는데요?",
  ui_story_1020_10200502_31_dialog_content = "...제가 똑바로 읽은 건 맞죠?",
  ui_story_1020_10200502_32_dialog_content = "맞아...",
  ui_story_1020_10200502_33_dialog_content = "그런데... 그런 중요한 정보는 지금으로선 부르한테 맡길 수밖에 없어.\n부르도 마찬가지로 고대 기계의 일부니까...",
  ui_story_1020_10200502_34_dialog_content = "알골도 어쩔 수 없는 일입니다.",
  ui_story_1020_10200502_35_dialog_content = "...진짜로 고대 기술에 한참이나 뒤처져 있다니...",
  ui_story_1020_10200502_36_dialog_content = "이걸 발명한 녀석은 대체 인간이 맞긴 한 거야? 아니면 신인가...? 하하... 아하하하!",
  ui_story_1020_10200502_37_dialog_content = "......",
  ui_story_1020_10200502_38_dialog_content = "일루미나만 해도 봐. 여전히 2진법을 기반으로 한 컴퓨터에 머물러 있잖아...\n이미 600년이 넘게 지났는데도 말이야!",
  ui_story_1020_10200502_39_dialog_content = "물리적 재료의 정상 상태 수효는 물론이고, 수학적 측면에서의 논리 연산도...\n우린 줄곧 2진법이 컴퓨터에 최적화된 방식이라고 생각해 왔어.",
  ui_story_1020_10200502_40_dialog_content = "하지만 이 기계는... 최하층에 사용된 언어조차 0과 1 외의 다른 숫자를 쓰고 있어!\n3진법, 4진법도 모자라서...",
  ui_story_1020_10200502_41_dialog_content = "심지어 「X」까지 있잖아... 이건 내가 전혀 이해할 수 없는 기술이야...\n「X」라니! 「X」?",
  ui_story_1020_10200502_42_dialog_content = "꼭 날 비웃는 것 같지 않아?! 아하하하!",
  ui_story_1020_10200502_43_dialog_content = "대체 어떻게 실현한 걸까? 저 안에서는 또 얼마나 복잡한 연산을 수행하고 있을까?",
  ui_story_1020_10200502_44_dialog_content = "고대엔 대체 무슨 일이 있었던 거냐고!",
  ui_story_1020_10200502_45_dialog_content = "왜 모든 게 다 사라지고, 아이테르, 암귀, 그리고 오로리안만 살아남은 거지?",
  ui_story_1020_10200502_46_dialog_content = "아...! 잊어버릴 뻔했네... 빛의 신도 있었지?! 그리고 진리의 주인도!\n설마 그 성전에 답이 있을까?!",
  ui_story_1020_10200502_47_dialog_content = "흐흐... 아하하하...",
  ui_story_1020_10200502_48_dialog_content = "왜 저래? 갑자기 사람 무섭게...",
  ui_story_1020_10200502_49_dialog_content = "알골은 자신이 너무나도 쓸모없다는 사실을 깨달았습니다.",
  ui_story_1020_10200502_50_dialog_content = "어떻게 이럴 수가 있지? 이게 무슨 농담이냐고! 내가 말해 놓고도 우스울 지경이잖아...",
  ui_story_1020_10200502_51_dialog_content = "아하하하...!",
  ui_story_1020_10200502_52_dialog_content = "1호! 난 이걸 만든 사람이 무슨 악한 신이든 악령이든 상관없어!",
  ui_story_1020_10200502_53_dialog_content = "어차피 가는 데 순서 없는 게 이 세상이야. 내 의문을 이미 죽어버린 것들한테 던지진 않겠어!",
  ui_story_1020_10200502_54_dialog_content = "비록 아직 이 안에 담긴 비밀을 다 밝혀내진 못했지만,\n난 앞으로도 계속 「가디언」 시스템을 연구하고 개발할 거야.",
  ui_story_1020_10200502_55_dialog_content = "내 말 들었어?!",
  ui_story_1020_10200502_56_dialog_content = "1호는 잘 들었습니다. 여러 의미로 말입니다.",
  ui_story_1020_10200502_57_dialog_content = "부부!",
  ui_story_1020_10200502_58_dialog_content = "좋아! 부르! 그럼 부탁할게!",
  ui_story_1020_10200502_59_dialog_content = "...부부...",
  ui_story_1020_10200502_60_dialog_content = "드디어 이 순간이 찾아왔네요...",
  ui_story_1020_10200502_61_dialog_content = "그럼 다 같이 보스 방으로 입장하자구!",
  ui_story_1020_10200502_62_dialog_content = "......",
  ui_story_1020_10200502_63_dialog_content = "...이게 뭐야?",
  ui_story_1020_10200502_64_dialog_content = "(아이테르.)",
  ui_story_1020_10200502_65_dialog_content = "......",
  ui_story_1020_10200502_66_dialog_content = "아까 머릿속을 스쳐 지나간 게... 꿈이 아니었단 말이야?",
  ui_story_1020_10200502_67_dialog_content = "저 커다란 검은 태양... 프로토타입이랑 무슨 관계인 거지?",
  ui_story_1020_10200601_1_dialog_content = "그러니까, 당신 꿈에 저 고리가 나왔고...",
  ui_story_1020_10200601_2_dialog_content = "팬텀과 바이스도 나왔다는 건가요?",
  ui_story_1020_10200601_3_dialog_content = "맞아...",
  ui_story_1020_10200601_4_dialog_content = "그럼 율리시스가 사용한 프로토타입을 만든 게... 설마 이클립스일까요?\n알골 박사, 당신 생각엔 관계가 있어 보이나요?",
  ui_story_1020_10200601_5_dialog_content = "물론 있겠지... 아하하하하하!",
  ui_story_1020_10200601_6_dialog_content = "......",
  ui_story_1020_10200601_7_dialog_content = "...다들 표정이 왜 그래?",
  ui_story_1020_10200601_8_dialog_content = "이건 일루미나가 세워졌을 때부터 우리의 생존을 위해 의지해 온 고대의 기술이에요...",
  ui_story_1020_10200601_9_dialog_content = "그런데 이게 이클립스의 물건이라면... 그것보다 중대한 위험이 또 있겠어요?",
  ui_story_1020_10200601_10_dialog_content = "(아이테르.)",
  ui_story_1020_10200601_11_dialog_content = "(또 나타났어...)",
  ui_story_1020_10200601_12_dialog_content = "적어도 내가 살펴봤을 땐 내 가상 머신하고 별 차이는 없었어.",
  ui_story_1020_10200601_13_dialog_content = "다른 강화 병사를 보관해 둔 장소가 있더라도, 프로토타입에 기록돼 있진 않을 것 같아.",
  ui_story_1020_10200601_14_dialog_content = "하지만 프로토타입의 기호와 PlayerName의 꿈속 풍경은 뭔가 관계가 있는 것 같아요. 수수께끼가 점차 늘어가는 느낌이네요...",
  ui_story_1020_10200601_15_dialog_content = "난 오히려 반대로 점점 더 상황이 확실하게 이해되고 있어.",
  ui_story_1020_10200601_16_dialog_content = "처음엔 율리시스를 구제불능의 에고마니아라고 생각했어.\n그런데 이걸 보고 나서 난 율리시스에 대한 시각이 조금 달라졌어.",
  ui_story_1020_10200601_17_dialog_content = "지금까지 그 오랜 시간 동안, 자난성은 멸망하지 않았어...\n율리시스가 그런 실험을 계속해 온 건 정말 그 사람이 미쳤기 때문일까?",
  ui_story_1020_10200601_18_dialog_content = "참모장, 난 지금 율리시스를 이 자리에 데려와야겠어.",
  ui_story_1020_10200601_19_dialog_content = "그건... 위원회에서 동의하지 않겠지만, 대원수님께 연락은 해 볼게요...",
  ui_story_1020_10200601_20_dialog_content = "......",
  ui_story_1020_10200601_21_dialog_content = "지금 이 기계에 대해 가장 잘 알고 있는 건 율리시스야.",
  ui_story_1020_10200601_22_dialog_content = "부르는 코어 구축에 필요한 모듈 데이터 역컴파일에 도움을 줄 수 있지만,\n우리가 방금 기록한 정보들은 연산 작업을 보조한 정도밖에 안 돼.",
  ui_story_1020_10200601_23_dialog_content = "프로토타입은 계속 봉인된 상태였고, 앞으로의 연구에 또 제한이 생길지는 잘 모르겠어.",
  ui_story_1020_10200601_24_dialog_content = "(아이테르.)",
  ui_story_1020_10200601_25_dialog_content = "......",
  ui_story_1020_10200601_26_dialog_content = "괜찮아? PlayerName.",
  ui_story_1020_10200601_27_dialog_content = "바...방금 뭔가 스쳐 지나가는 걸 본 것 같아요...",
  ui_story_1020_10200601_28_dialog_content = "뭐였는데?",
  ui_story_1020_10200601_29_dialog_content = "부부! 부부! 부부!",
  ui_story_1020_10200601_30_dialog_content = "<color=#e8d9bb>삑── 삑── 삑──</color>",
  ui_story_1020_10200601_31_dialog_content = "...잠겼잖아?!",
  ui_story_1020_10200601_32_dialog_content = "<color=#e8d9bb>쿠구구구──</color>",
  ui_story_1020_10200601_33_dialog_content = "으앗! 무슨 일이야?",
  ui_story_1020_10200601_34_dialog_content = "창고가 흔들리고 있어요...!",
  ui_story_1020_10200601_35_dialog_content = "......",
  ui_story_1020_10200601_36_dialog_content = "잠깐만... 모듈 데이터를 역컴파일할 수 있다면, 잠길 리가 없는데...",
  ui_story_1020_10200601_37_dialog_content = "부부! 부부! 부부!",
  ui_story_1020_10200601_38_dialog_content = "<color=#e8d9bb>쿠구구구──</color>",
  ui_story_1020_10200601_39_dialog_content = "부르가 이미 프로토타입의 방어 코드를 역컴파일해서 새 코어를 구축했던 거 아니었어?",
  ui_story_1020_10200601_40_dialog_content = "아니면 방어 시스템의 허점을 메꾸면서 생긴 반응이야?",
  ui_story_1020_10200601_41_dialog_content = "원래라면 그게 맞겠지만, 이 정도로 흔들리는 건 너무 심하잖아!",
  ui_story_1020_10200601_42_dialog_content = "<color=#e8d9bb>쿠구구구──</color>",
  ui_story_1020_10200601_43_dialog_content = "부부! 부부! 부부!",
  ui_story_1020_10200601_44_dialog_content = "맞아! 「가디언」의 모듈 데이터를 역컴파일한 뒤부터 뭔가가 내 컴퓨터를 공격하기 시작했는데, 그게 이젠 일루미나의 방어 시스템까지 공격하고 있는 것 같아.",
  ui_story_1020_10200601_45_dialog_content = "데이터 침입? 게임이 현실이 된 거야?",
  ui_story_1020_10200601_46_dialog_content = "잠깐... 잠깐만... 음... 방어 모듈... 방어 모듈...",
  ui_story_1020_10200601_47_dialog_content = "일단 주변 상황을 좀 파악해 줘. 난 방어 모듈을 다시 역컴파일해 볼게.",
  ui_story_1020_10200601_48_dialog_content = "만약 「가디언」이 방어 시스템의 허점을 메우는 게 아니라, 한층 더 허물고 있는 거라면...",
  ui_story_1020_10200601_49_dialog_content = "그럼 지하성이 위험해지겠네요...",
  ui_story_1020_10200601_50_dialog_content = "...아니, 이건 프로토타입 내부, 아니면 반대편에서 뭔가가 우리랑 맞서고 있는 거야.",
  ui_story_1020_10200601_51_dialog_content = "......",
  ui_story_1020_10200601_52_dialog_content = "프로토타입 내부나 반대편에 누가 있는데요?",
  ui_story_1020_10200601_53_dialog_content = "그건 아마 율리시스만 알겠지...",
  ui_story_1020_10200601_54_dialog_content = "<color=#e8d9bb>삑── 삑── 삑──</color>",
  ui_story_1020_10200601_55_dialog_content = "젠장! 내 경로를 막아버렸어!",
  ui_story_1020_10200601_56_dialog_content = "<color=#e8d9bb>쿠르르릉──!</color>",
  ui_story_1020_10200601_57_dialog_content = "<color=#e8d9bb>삑──</color>",
  ui_story_1020_10200601_58_dialog_content = "<color=#e8d9bb>삑──</color>",
  ui_story_1020_10200601_59_dialog_content = "<color=#e8d9bb>삐비빅──</color>",
  ui_story_1020_10200601_60_dialog_content = "...한 번에 단말기 메시지가 이렇게 잔뜩 오다니...",
  ui_story_1020_10200601_61_dialog_content = "터널... 10호 성문... 알골 박사, 상황이 생각보다 훨씬 안 좋아요!",
  ui_story_1020_10200601_62_dialog_content = "지하성의 여러 방어 시스템이 전부 공격받고 있어요!",
  ui_story_1020_10200601_63_dialog_content = "...사용이 중단된 제어 스위치도 꽤 많을 거야.\n참모장, 바깥 상황은 당신들한테 맡길 테니까, 일단 좀 버텨 줘!",
  ui_story_1020_10200601_64_dialog_content = "부르, 모듈을 재부팅해!",
  ui_story_1020_10200601_65_dialog_content = "부우!",
  ui_story_1020_10200601_66_dialog_content = "그로누, 미자드, 실험동에 가서 컨트롤러를 확인해 주세요.\n특히 창고와 대형 실험 시설이 있는 곳들에 주의해서요.",
  ui_story_1020_10200601_67_dialog_content = "방어 시스템에 의존하는 일부 스위치는 일단 수동으로 제어하는 수밖에 없어요!",
  ui_story_1020_10200601_68_dialog_content = "전 우선 메시지를 보내온 사람들을 통해 상황을 파악하고, 대원수님께 연락을 드릴게요!",
  ui_story_1020_10200601_69_dialog_content = "PlayerName, 당신은 감각이 예민하니까, 위험을 느끼면 즉시 모두에게 알려 주세요!",
  ui_story_1020_10200601_70_dialog_content = "그럴게!",
  ui_story_1020_10200601_71_dialog_content = "(이 상황, 설마 아까 스쳐 지나간 장면이랑 뭔가 관련돼 있는 걸까...)",
  ui_story_1020_10200601_72_dialog_content = "<color=#e8d9bb>일루미나, 모 터널 시공팀</color>",
  ui_story_1020_10200601_73_dialog_content = "<color=#e8d9bb>쿠르르릉──!</color>",
  ui_story_1020_10200601_74_dialog_content = "시엘! 시엘──!",
  ui_story_1020_10200601_75_dialog_content = "빨리 밖으로 나와!",
  ui_story_1020_10200601_76_dialog_content = "어라...?",
  ui_story_1020_10200601_77_dialog_content = "이렇게 세게 흔들리는데 아무것도 못 느꼈어? 앞쪽 터널이 무너져 버렸다고!",
  ui_story_1020_10200601_78_dialog_content = "음... 지금 멋대로 뛰어다니면 더 위험할지도 몰라...",
  ui_story_1020_10200601_79_dialog_content = "아무튼... 일단 강화복을 가동할게.",
  ui_story_1020_10200601_80_dialog_content = "<color=#e8d9bb>일루미나 메디컬 센터</color>",
  ui_story_1020_10200601_81_dialog_content = "<color=#e8d9bb>쿠르르릉──!</color>",
  ui_story_1020_10200601_82_dialog_content = "(이 진동...)",
  ui_story_1020_10200601_83_dialog_content = "(설마 또 나 때문에... 다들 잠에서 깨버린 건가?)",
  ui_story_1020_10200601_84_dialog_content = "......",
  ui_story_1020_10200601_85_dialog_content = "(아니... 이번엔 아니군...)",
  ui_story_1020_10200601_86_dialog_content = "(난 아직 침대에 있다...)",
  ui_story_1020_10200601_87_dialog_content = "(라인하르트... 난 진심으로 내가 일루미나를 위해 뭔가 할 수 있었으면 한다...)",
  ui_story_1020_10200601_88_dialog_content = "<color=#e8d9bb>삑──</color>",
  ui_story_1020_10200601_89_dialog_content = "대원수님! 드디어 연결됐네요!",
  ui_story_1020_10200601_90_dialog_content = "오래 기다리게 만들어 미안하군.",
  ui_story_1020_10200601_91_dialog_content = "연구동 창고 안에 위험한 기계가 있다고 하더군. 다들 지금 어디 있지?",
  ui_story_1020_10200601_92_dialog_content = "0호 창고요! 율리시스가 사적으로 사용하고 있던 곳이에요!",
  ui_story_1020_10200601_93_dialog_content = "0호 창고라고?!",
  ui_story_1020_10200601_94_dialog_content = "여긴 강화 병사들이 보관돼 있었어요!\n그리고 이클립스와 관련이 있다고 추정되는 고대 기계도 한 대 있어요.\n지금 진동은 그 기계 때문에 발생한 거예요!",
  ui_story_1020_10200601_95_dialog_content = "우선 그곳에서 벗어나라!",
  ui_story_1020_10200601_96_dialog_content = "전원, 그곳을 즉시 떠나라!",
  ui_story_1020_10200601_97_dialog_content = "알골 박사...",
  ui_story_1020_10200601_98_dialog_content = "일단 스위치부터 안정시켜야 해!\n방어 시스템의 허점을 완벽히 해결하려면 새 코어를 구축해야 돼. 시간이 좀 걸릴 거야!",
  ui_story_1020_10200601_99_dialog_content = "부부! 부부! 부부!",
  ui_story_1020_10200601_100_dialog_content = "아, 그렇지. 참모장! 대원수한테 율리시스를 여기로 데려오라고 전해 줘!",
  ui_story_1020_10200601_101_dialog_content = "<color=#e8d9bb>일루미나 고위층 회의실</color>",
  ui_story_1020_10200601_102_dialog_content = "자동 제어 시스템은 통제 불능, 외곽 구역의 성문 제어도 고장, 터널은 붕괴했습니다...",
  ui_story_1020_10200601_103_dialog_content = "이게 당신이 기대하던 결과인가요?",
  ui_story_1020_10200601_104_dialog_content = "백야성은?",
  ui_story_1020_10200601_105_dialog_content = "아무 움직임도 없습니다.",
  ui_story_1020_10200601_106_dialog_content = "......",
  ui_story_1020_10200601_107_dialog_content = "<color=#FFB400>긴급조치</color>를 발동할까 고민 중이신가요?",
  ui_story_1020_10200601_108_dialog_content = "아직은 때가 아니야.",
  ui_story_1020_10200601_109_dialog_content = "악셀리아는... 지면에서 흔들림이 느껴지는 것 같습니다.",
  ui_story_1020_10200601_110_dialog_content = "저도 느꼈어요...",
  ui_story_1020_10200601_111_dialog_content = "이게 바로 제 실험실을 인계받겠다는 자들이 벌인 일인가 보군요.",
  ui_story_1020_10200601_112_dialog_content = "하하... 당신들이 뭐라도 할 수 있을 줄 알았습니까?",
  ui_story_1020_10200601_113_dialog_content = "넌 그 프로토타입에 문제가 있다는 걸 알고 있었군. 그리고 뭔가를 기다리고 있겠지. 아닌가?",
  ui_story_1020_10200601_114_dialog_content = "...프로토타입에 문제가 있다고?",
  ui_story_1020_10200601_115_dialog_content = "역사의 장은... 당신들 스스로 열어야 합니다...",
  ui_story_1020_10200601_116_dialog_content = "레이스, 히이로. 너희는 율리시스를 감시하도록.\n무슨 일이 있어도 너희 시야를 벗어나지 못하게 해라.",
  ui_story_1020_10200601_117_dialog_content = "나는 먼저 가서 상황을 확인하겠다. 확인이 끝나면 연락할 테니, 그때 율리시스를 데려오도록.",
  ui_story_1020_10200601_118_dialog_content = "알겠습니다.",
  ui_story_1020_10200601_119_dialog_content = "조심해.",
  ui_story_1020_10200601_120_dialog_content = "<color=#e8d9bb>자난성 외곽</color>",
  ui_story_1020_10200601_121_dialog_content = "<color=#e8d9bb>쿠르르릉──!</color>",
  ui_story_1020_10200601_122_dialog_content = "네, 군단장님! 누군가 성문 스위치를 돌려 버리기라도 한 것처럼,\n벽이 무시무시한 기세로 흔들렸습니다!",
  ui_story_1020_10200601_123_dialog_content = "모든 성문이 그랬다는 거냐?!",
  ui_story_1020_10200601_124_dialog_content = "아닙니다! 오른쪽 두 성문의 파손이 가장 심각하며, 암귀가 접근 중입니다!",
  ui_story_1020_10200601_125_dialog_content = "비비안 쪽에 골치 아픈 일이 생긴 모양이군.",
  ui_story_1020_10200601_126_dialog_content = "어떻게든 반드시 성문을 지켜라.",
  ui_story_1020_10200601_127_dialog_content = "성문에 구멍이 생긴다면, 그 구멍에 대포를 박아 넣고 한 마리씩 날려 버려라!\n열 마리가 와도 한꺼번에 날려 버리면 그만이다!",
  ui_story_1020_10200601_128_dialog_content = "암귀들을 쳐부수고 싶어 몸이 근질거렸다면, 어디 오늘 한번 신나게 날뛰어 봐라!",
  ui_story_1020_10200601_129_dialog_content = "예!",
  ui_story_1020_10200601_130_dialog_content = "<color=#e8d9bb>쾅── 쾅── 콰앙──!</color>",
  ui_story_1020_10200601_131_dialog_content = "아하하하하!",
  ui_story_1020_10200601_132_dialog_content = "모조리 터트려 버려!",
  ui_story_1020_10200601_133_dialog_content = "바튼 군단 최강자 등장!",
  ui_story_1020_10200602_1_dialog_content = "부부부부──!",
  ui_story_1020_10200602_2_dialog_content = "......",
  ui_story_1020_10200602_3_dialog_content = "다들 괜찮나?",
  ui_story_1020_10200602_4_dialog_content = "대원수님! 후방의 적을 대신 막아주셨군요. 감사해요...",
  ui_story_1020_10200602_5_dialog_content = "이미 쓰러진 강화 병사들이 또 공격해 올 줄은 정말 몰랐어요!",
  ui_story_1020_10200602_6_dialog_content = "으아아! 나 왔어! 가 봤더니 몇몇 실험실 해치에서 경고음이 울리고 있었어!",
  ui_story_1020_10200602_7_dialog_content = "지금은 다시 잠가 둔 상태고, 병사들이 실험실 입구를 지키고 있어요.",
  ui_story_1020_10200602_8_dialog_content = "모두 수고 많았다.",
  ui_story_1020_10200602_9_dialog_content = "PlayerName, 일루미나가 위험에 처한 상황에서도\n넌 기어코 여길 와야 직성이 풀리는 모양이군.",
  ui_story_1020_10200602_10_dialog_content = "죄송해요...",
  ui_story_1020_10200602_11_dialog_content = "무사하면 됐어.\n율리시스가 여길 강화 병사를 만드는 곳으로 삼았을 줄이야...",
  ui_story_1020_10200602_12_dialog_content = "비비안, 현재 상황을 설명하도록.",
  ui_story_1020_10200602_13_dialog_content = "처음엔 자난성 방어에 허점이 발생한 탓에,\n강화 병사들이 연구동에서 나타나 사람들을 공격했어요...",
  ui_story_1020_10200602_14_dialog_content = "다행히 알골 박사가 여길 찾아냈고, 봉인됐던 프로토타입을 발견했어요.\n지금은 방어 코어 구축을 시도하는 중이에요.",
  ui_story_1020_10200602_15_dialog_content = "현재 상황으로 보면, 아까 진동을 야기했던 문제는 이미 해결된 건가?",
  ui_story_1020_10200602_16_dialog_content = "스위치들을 안정시키기 위해 임시로 새로운 경로를 구축했어.\n하지만 방어 시스템의 어디에 허점이 발생한 건지는 아직 몰라.",
  ui_story_1020_10200602_17_dialog_content = "율리시스는?",
  ui_story_1020_10200602_18_dialog_content = "그자가 이 기계에 대해서도 자백하긴 했지만, 그자를 여기 데려올지는\n이곳의 상황을 파악한 뒤에 다시 결정하려고 했다.",
  ui_story_1020_10200602_19_dialog_content = "율리시스의 지금 상태는... 다소 특수해서 말이지.",
  ui_story_1020_10200602_20_dialog_content = "이클립스 쪽에선 누가 율리시스한테 연락한 거야? 그것도 자백했어?",
  ui_story_1020_10200602_21_dialog_content = "너도 그렇게 말하는 걸 보면 틀림없겠군...",
  ui_story_1020_10200602_22_dialog_content = "율리시스는 자신이 프로토타입을 통해 「엔지니어」에 대한 단서를 발견했다고 말했다.",
  ui_story_1020_10200602_23_dialog_content = "그자의 설명에 따르면, 「엔지니어」는 일루미나를 세운 초대 성주였다.\n하지만 이미 600년 전에 행적이 묘연해졌다더군.",
  ui_story_1020_10200602_24_dialog_content = "600년 동안 사라졌던 「엔지니어」가... 지금 컴퓨터 한 대로 율리시스와 연락을 취했다...?",
  ui_story_1020_10200602_25_dialog_content = "PlayerName처럼 감응 능력을 쓴 건 아닐까?",
  ui_story_1020_10200602_26_dialog_content = "감응 능력...?",
  ui_story_1020_10200602_27_dialog_content = "(그럼 머릿속을 스쳐 지나간 장면들도 설마 감응이었던 건가...?)",
  ui_story_1020_10200602_28_dialog_content = "감응 능력은 아이테르만 쓸 수 있을 거잖아...",
  ui_story_1020_10200602_29_dialog_content = "「엔지니어」가 실존한다고 가정했을 때, 이론적으론 회선의 성능만 뒷받침되면\n프로토타입을 통해 율리시스와 실시간으로 소통할 수 있어.",
  ui_story_1020_10200602_30_dialog_content = "하지만 프로토타입엔 육안으로 확인할 수 있는 회선도,\n신호를 전송하거나 수신할 수 있는 장치도 없어. 그래서...",
  ui_story_1020_10200602_31_dialog_content = "띠릭──",
  ui_story_1020_10200602_32_dialog_content = "알골이 1호에게 가져와 달라고 한 <color=#FFB400>단자</color>입니다.",
  ui_story_1020_10200602_33_dialog_content = "고마워, 이리 줘.",
  ui_story_1020_10200602_34_dialog_content = "예를 들면...",
  ui_story_1020_10200602_35_dialog_content = "이런 케이블만 연결하면, 1호는 언제든 내 컴퓨터에 나타나서\n나랑 얼굴을 보며 실시간으로 소통할 수 있어.",
  ui_story_1020_10200602_36_dialog_content = "오, 여러분, 안녕하세요! 제 얼굴이 너무 큰 건 아닌지 모르겠군요...",
  ui_story_1020_10200602_37_dialog_content = "저희 조사에서는 이런 <color=#FFB400>케이블</color>이 발견되지 않았어요.\n주변은 아주 깔끔했고, 벽과 바닥 모두 확실히 용접돼 있었죠...",
  ui_story_1020_10200602_38_dialog_content = "그건 이상하군. 이 창고가 사용 등록되지 않았던 이유는 당시 낡은 케이블이\n창고 환경과 심각하게 일체화돼 있어 처리가 불가능했기 때문이었다.",
  ui_story_1020_10200602_39_dialog_content = "그런 일이 있었다고? 여긴 내가 여기 처음 와 봤을 때부터 지금 상태랑 비슷했는데?",
  ui_story_1020_10200602_40_dialog_content = "아마 네가 오기 전에 처리를 끝내 둔 것이겠지.",
  ui_story_1020_10200602_41_dialog_content = "이런 커다란 창고의 낡은 물건들을 처리하는 것도 쉽지 않았겠는데 말이죠...",
  ui_story_1020_10200602_42_dialog_content = "부부! 부부! 부부!",
  ui_story_1020_10200602_43_dialog_content = "<color=#e8d9bb>타닥타닥── 화르륵──</color>",
  ui_story_1020_10200602_44_dialog_content = "어...? 알골 박사, 왜 당신 케이블에서 불꽃이 튀는 거야?!",
  ui_story_1020_10200602_45_dialog_content = "하아? 출력 과부하인가...?! 그럴 리가 없는데?!",
  ui_story_1020_10200602_46_dialog_content = "뭐...? 모든 부품이 강제로 풀로드 가동 중이라고?!",
  ui_story_1020_10200602_47_dialog_content = "<color=#e8d9bb>화르륵── 펑!</color>",
  ui_story_1020_10200602_48_dialog_content = "으앗! 내 케이블이 망가져 버렸잖아!",
  ui_story_1020_10200602_49_dialog_content = "알골은 분노하고 있습니다.",
  ui_story_1020_10200602_50_dialog_content = "부부부부──!",
  ui_story_1020_10200602_51_dialog_content = "<color=#e8d9bb>삑── 삑── 삑──</color>",
  ui_story_1020_10200602_52_dialog_content = "젠장! 방금 구축한 방어 모듈이 마비됐잖아!",
  ui_story_1020_10200602_53_dialog_content = "부부! 부부! 부부!",
  ui_story_1020_10200602_54_dialog_content = "<color=#e8d9bb>위이잉──</color>",
  ui_story_1020_10200602_55_dialog_content = "멈췄는데요...?",
  ui_story_1020_10200602_56_dialog_content = "<color=#e8d9bb>지직... 지지직...</color>",
  ui_story_1020_10200602_57_dialog_content = "머리다!",
  ui_story_1020_10200602_58_dialog_content = "......",
  ui_story_1020_10200602_59_dialog_content = "저게 설마 그 「엔지니어」인가?",
  ui_story_1020_10200602_60_dialog_content = "방금 스쳐 지나간 건... 실시간 소통 같은 건가?",
  ui_story_1020_10200602_61_dialog_content = "어...? 왜 없어졌지...?",
  ui_story_1020_10200602_62_dialog_content = "부부부부──!",
  ui_story_1020_10200602_63_dialog_content = "뭐? 대화? 너 저 말을 해석할 수 있어?",
  ui_story_1020_10200602_64_dialog_content = "...부부...",
  ui_story_1020_10200602_65_dialog_content = "뭐라고 하는데?",
  ui_story_1020_10200602_66_dialog_content = "...부부...",
  ui_story_1020_10200602_67_dialog_content = "「오랜만이군」",
  ui_story_1020_10200602_68_dialog_content = "...부부...",
  ui_story_1020_10200602_69_dialog_content = "「율리시스」",
  ui_story_1020_10200602_70_dialog_content = "...부부...",
  ui_story_1020_10200602_71_dialog_content = "「박사」",
  ui_story_1020_10200602_72_dialog_content = "......",
  ui_story_1020_10200602_73_dialog_content = "부르! 경로를 바꾸고 모듈을 다시 역컴파일해!",
  ui_story_1020_10200602_74_dialog_content = "부우!",
  ui_story_1020_10200602_75_dialog_content = "<color=#e8d9bb>위이잉──</color>",
  ui_story_1020_10200602_76_dialog_content = "......",
  ui_story_1020_10200602_77_dialog_content = "오랜만...입니다...",
  ui_story_1020_10200602_78_dialog_content = "훗... 하하... 하하하하...",
  ui_story_1020_10200602_79_dialog_content = "오셨군요...",
  ui_story_1020_10200602_80_dialog_content = "누가 왔다는 겁니까?",
  ui_story_1020_10200602_81_dialog_content = "「엔지니어」 말입니다...",
  ui_story_1020_10200602_82_dialog_content = "「엔지니어」? 어디 있죠?",
  ui_story_1020_10200602_83_dialog_content = "에센, 마지막 약을... 주게.",
  ui_story_1020_10200602_84_dialog_content = "율리시스 님...",
  ui_story_1020_10200602_85_dialog_content = "어서!",
  ui_story_1020_10200602_86_dialog_content = "<color=#e8d9bb>일루미나 구금실</color>",
  ui_story_1020_10200602_87_dialog_content = "『다, 당신이셨군요... 지고의 지배자시여!』",
  ui_story_1020_10200602_88_dialog_content = "『당신의 충직한 종 피제로, 이곳에서 무릎을 꿇고 당신의 강림을 기다렸습니다.』",
  ui_story_1020_10200602_89_dialog_content = "......",
  ui_story_1020_10200602_90_dialog_content = "<color=#e8d9bb>철컹──</color>",
  ui_story_1020_10200602_91_dialog_content = "『......』",
  ui_story_1020_10200602_92_dialog_content = "『...겨, 결코 당신의 뜻을 거스르지 않을 것입니다!』",
  ui_story_1020_10200602_93_dialog_content = "『당신께 보답하기 위해...』",
  ui_story_1020_10200602_94_dialog_content = "『그때 실패한 임무를 이제 제 목숨으로 완수하겠습니다.』",
  ui_story_1020_10200701_1_dialog_content = "<color=#e8d9bb>쿠구구구──</color>",
  ui_story_1020_10200701_2_dialog_content = "율리시스, 그자는 이미 「가디언 1호」의 코어를 가지고 갔어. 대체 뭘 하려는 거지?",
  ui_story_1020_10200701_3_dialog_content = "이 지하성이 무너져 내릴 듯 흔들리고 있는데도, 당신은 두렵지 않습니까? 철가면님.",
  ui_story_1020_10200701_4_dialog_content = "이 모든 걸 꾸민 이유가 뭐지...? 일루미나의 목숨줄을 이클립스 손에 넘기고,\n더 많은 연구 자원을 얻어 당신 이상을 실현하기 위해서야?",
  ui_story_1020_10200701_5_dialog_content = "저 역시 한때는 엔지니어가 없었다면, 일루미나의 오늘도 없었을 것이라 굳게 믿었습니다.",
  ui_story_1020_10200701_6_dialog_content = "하지만 그 후 전 깨달았지요.\n「가디언 1호」의 코어는 단 한 번도 일루미나의 목숨줄이었던 적이 없었습니다.",
  ui_story_1020_10200701_7_dialog_content = "저야말로 일루미나의 목숨줄이었습니다!",
  ui_story_1020_10200701_8_dialog_content = "고작 「가디언 1호」의 코어가 사라졌을 뿐인데,\n자난성의 방어 시스템이 이렇게까지 망가진단 말입니까?",
  ui_story_1020_10200701_9_dialog_content = "제가 엔지니어의 계획을 알려 드리지요...",
  ui_story_1020_10200701_10_dialog_content = "그는 모든 것을 통합하고, 불태우고, 그의 강대한 시선으로\n오로리안을 내려다볼 것입니다...",
  ui_story_1020_10200701_11_dialog_content = "하지만 전 당신들처럼 이 깜깜한 지하성에 앉아서 죽기만을 기다리진 않을 겁니다!\n전 그에게 도전할 테니 말입니다!",
  ui_story_1020_10200701_12_dialog_content = "미쳤어... 헛소리 집어치워!",
  ui_story_1020_10200701_13_dialog_content = "당신들은 그가 어떻게 한 건지 알고 있습니까...?",
  ui_story_1020_10200701_14_dialog_content = "그는 이 모든 것을 만든 후 침묵에 빠졌고, 코어 회수와 암귀 제작이라는 임무를\n그 어리석은 팬텀들에게 맡겼습니다.",
  ui_story_1020_10200701_15_dialog_content = "그리고 수백 년을 칩거하던 그는 마침내 소생했습니다.",
  ui_story_1020_10200701_16_dialog_content = "하지만 이 세상은 이미 변했고, 그는 이미 제가 자료를 통해 알던 엔지니어가 아니었습니다.",
  ui_story_1020_10200701_17_dialog_content = "그가 할 수 있었던 일은 이제 저도 할 수 있게 되었지요.",
  ui_story_1020_10200701_18_dialog_content = "그 입 좀 닥치라니까!",
  ui_story_1020_10200701_19_dialog_content = "여기 있는 사람 중 그 누구라도 널 죽여버릴 수 있어. 그러니까 얌전히...",
  ui_story_1020_10200701_20_dialog_content = "그래서 이제 당신은 뭘 할 수 있지?",
  ui_story_1020_10200701_21_dialog_content = "......",
  ui_story_1020_10200701_22_dialog_content = "하하하... 제가 하려는 건 이미 제 창고에 모두 준비해 두었습니다.",
  ui_story_1020_10200701_23_dialog_content = "멈추세요!",
  ui_story_1020_10200701_24_dialog_content = "...절 막겠다는 겁니까?",
  ui_story_1020_10200701_25_dialog_content = "얌전히 여기 있으세요.",
  ui_story_1020_10200701_26_dialog_content = "...당신들이 절 믿지 않는다 해도... 이젠... 오직 저만이...",
  ui_story_1020_10200701_27_dialog_content = "한 걸음만 더 움직여 보시죠.",
  ui_story_1020_10200701_28_dialog_content = "칼을 거둬.",
  ui_story_1020_10200701_29_dialog_content = "......",
  ui_story_1020_10200701_30_dialog_content = "당신도, 저도 이제 시간이 없습니다. 철가면님.\n하지만 일루미나, 그리고 오로리안이 가야 할 길은 아직 멉니다.",
  ui_story_1020_10200701_31_dialog_content = "전 언젠가 이런 날이 오리란 것을 알고 있었습니다.\n하지만 설령 모든 이가 절 부정한다 하더라도, 전 포기하지 않습니다!",
  ui_story_1020_10200701_32_dialog_content = "전 제 방식대로 맞서 싸울 것입니다.",
  ui_story_1020_10200701_33_dialog_content = "당신들이 못 한다면, 제가 직접 나서지요...",
  ui_story_1020_10200701_34_dialog_content = "...지켜볼 배짱은 있습니까?",
  ui_story_1020_10200701_35_dialog_content = "......",
  ui_story_1020_10200701_36_dialog_content = "<color=#e8d9bb>삑──</color>",
  ui_story_1020_10200701_37_dialog_content = "대원수님인가요...?",
  ui_story_1020_10200701_38_dialog_content = "율리시스를 데리고 오래...",
  ui_story_1020_10200701_39_dialog_content = "......",
  ui_story_1020_10200701_40_dialog_content = "벨리사리아, 체스말이 없으면 대국도 없어. 그때 가서 어떻게 체스를 둘 생각인데?",
  ui_story_1020_10200701_41_dialog_content = "난 믿어. 라인하르트는 무슨 일이 있어도 이 자난성을 지탱해 낼 거야.\n하지만 당신은 그럴 수 있겠어?",
  ui_story_1020_10200701_42_dialog_content = "......",
  ui_story_1020_10200701_43_dialog_content = "대퍼딜, 바렛에게 연락해.",
  ui_story_1020_10200701_44_dialog_content = "바렛 박사님은 이미 한참 전부터 기다리고 계셨습니다.",
  ui_story_1020_10200701_45_dialog_content = "결정했나요?",
  ui_story_1020_10200701_46_dialog_content = "<color=#FFB400>긴급조치</color>를 시행하겠어.",
  ui_story_1020_10200701_47_dialog_content = "기존 장비를 해체하고 경로 기본값을 변경해. 수직구도 개방하고.\n주민들을 태워서 예비용 지하성 몇 곳으로 이동시켜.",
  ui_story_1020_10200701_48_dialog_content = "운송 수단과 수직구는 정상 운용이 가능해요. 주민들도 이송할 수 있고요.",
  ui_story_1020_10200701_49_dialog_content = "대신 수직구 작전의 안전을 위해 위원회에서 충분한 병력을 파견해 줬으면 해요.",
  ui_story_1020_10200701_50_dialog_content = "넌 실행만 생각해. 길은 위원회가 열어줄 테니까.",
  ui_story_1020_10200701_51_dialog_content = "좋아요, 깔끔하네요.",
  ui_story_1020_10200701_52_dialog_content = "당신들은 율리시스를 창고까지 안전하게 데려가 줘요.",
  ui_story_1020_10200701_53_dialog_content = "잠깐만, 방금 말한 운송 수단이랑 수직구는... 또 뭐야?",
  ui_story_1020_10200701_54_dialog_content = "일루미나가 연구개발한 비행체, 그리고 그 비행체를 위해 만들어진 지하 궤도야.",
  ui_story_1020_10200701_55_dialog_content = "비행체...?",
  ui_story_1020_10200701_56_dialog_content = "기차, 수송 차량, 궤도 전용열차... 너흰 일루미나에 그런 지상용만 있는 줄 알았어?",
  ui_story_1020_10200701_57_dialog_content = "기존 장비와 경로 기본값은... 또 뭡니까?",
  ui_story_1020_10200701_58_dialog_content = "물론 말해줄게. 비행체들은 저 부유섬을 위해 준비한 거야.\n그러니까 경로 기본값은 당연히 백야성으로 설정돼 있지.",
  ui_story_1020_10200701_59_dialog_content = "...그럼 거기 탄약을 싣고 백야성을 공격하려던 거였어?!",
  ui_story_1020_10200701_60_dialog_content = "적에 따라 다른 무기를 사용해야지.\n지상으로 올라가겠다고 결정한다면, 수단과 방법을 가리지 않는 수밖에 없어.",
  ui_story_1020_10200701_61_dialog_content = "......",
  ui_story_1020_10200701_62_dialog_content = "이런 시기에, 이런 방식으로 긴급조치를 시행하게 될 줄은 몰랐지만 말이야.",
  ui_story_1020_10200701_63_dialog_content = "당신이 말하지 않아도 알아. 최소한 이번엔 나와 모두의 이익이 일치하니까.",
  ui_story_1020_10200701_64_dialog_content = "율리시스를 그 창고로 데려가. 그 사람은 이제 너희 인질이야.",
  ui_story_1020_10200701_65_dialog_content = "......",
  ui_story_1020_10200701_66_dialog_content = "하하... 철가면님, 한때 세상의 모든 걸 업신여기던 당신도\n이젠 그 자리에서 내려오신 모양이군요.",
  ui_story_1020_10200701_67_dialog_content = "우린 다시 만나게 되겠지요...",
  ui_story_1020_10200701_68_dialog_content = "사람이 놀 땐 노는 게 맞아.",
  ui_story_1020_10200701_69_dialog_content = "하지만 놀 만큼 놀았으면 뭔가 해야 하지 않을까?",
  ui_story_1020_10200701_70_dialog_content = "만약 당신도 그렇게 해 준다면, 우리가 다시 만나야 할 필요는 없을 거야.",
  ui_story_1020_10200701_71_dialog_content = "수직구를 개방했지만, 백야성은 여전히 아무 움직임도 보이지 않습니다.",
  ui_story_1020_10200701_72_dialog_content = "이렇게 오랜 시간을 기다렸는데, 이참에 저 부유섬에 몇 방 날려볼 수 없는 건 아쉽네요.",
  ui_story_1020_10200701_73_dialog_content = "다들 각자 위치로 돌아가. 앞으로 할 일도 아직 많으니까.",
  ui_story_1020_10200701_74_dialog_content = "<color=#e8d9bb>쿠구구구──</color>",
  ui_story_1020_10200701_75_dialog_content = "악셀리아, 잉겔... 우리 이제 어떡해?",
  ui_story_1020_10200701_76_dialog_content = "그동안 해온 대로 하면 되는 겁니다.\n대원수님과 다른 분들은 모두 그 창고로 가셨으니, 우린 그분들을 지켜야죠.",
  ui_story_1020_10200701_77_dialog_content = "전쟁 병기라도... 너흰 항상 자기가 뭘 해야 하는지 아는 거야?",
  ui_story_1020_10200701_78_dialog_content = "전 기억이라는 걸 할 수 있을 때부터 알았어요.",
  ui_story_1020_10200701_79_dialog_content = "악셀리아는 얼마 전에 알게 됐습니다. 숀도 알게 될 겁니다.",
  ui_story_1020_10200701_80_dialog_content = "말이야 쉽지... 그치만 너흰...",
  ui_story_1020_10200701_81_dialog_content = "아얏──!",
  ui_story_1020_10200701_82_dialog_content = "잉겔... 왜 꼬집어? 피, 피까지 나잖아...",
  ui_story_1020_10200701_83_dialog_content = "전쟁 병기라도 심장이 뛰고 피가 흐르는 오로리안 아닌가요?",
  ui_story_1020_10200701_84_dialog_content = "회의에서 있었던 일은 마음에 담아 두지 마세요.\n무슨 일이 벌어지든 대원수님께선 당신의 존재 의미를 부정하지 않으실 테니까요.",
  ui_story_1020_10200701_85_dialog_content = "그리고 대원수님과 레이스 님 모두 이번 음모의 피해자시면서도...\n여전히 자신의 의무를 다하고 계세요.",
  ui_story_1020_10200701_86_dialog_content = "이렇게 말하면 이상하겠지만... 그런 대원수님이 계시기 때문에, 전 조금도 두렵지 않아요.",
  ui_story_1020_10200701_87_dialog_content = "......",
  ui_story_1020_10200701_88_dialog_content = "악셀리아도 같은 의견입니다...",
  ui_story_1020_10200701_89_dialog_content = "너희들...",
  ui_story_1020_10200701_90_dialog_content = "자, 가죠! 서둘러요, 숀!",
  ui_story_1020_10200701_91_dialog_content = "...응!",
  ui_story_1020_10200701_92_dialog_content = "<color=#e8d9bb>쿠구구구──</color>",
  ui_story_1020_10200801_1_dialog_content = "흔들림이... 멈췄어요.",
  ui_story_1020_10200801_2_dialog_content = "코어 구축에 성공한 건가요?!",
  ui_story_1020_10200801_3_dialog_content = "아니... 우리 쪽 실행 속도가 너무 느려서, 이제 일부만 완성된 상태야.",
  ui_story_1020_10200801_4_dialog_content = "조금만 더 시간을 줘. 반드시 해낼 테니까!",
  ui_story_1020_10200801_5_dialog_content = "부우!",
  ui_story_1020_10200801_6_dialog_content = "시간 낭비할 필요 없습니다...",
  ui_story_1020_10200801_7_dialog_content = "똑바로 서세요, 율리시스!",
  ui_story_1020_10200801_8_dialog_content = "다들 왔군.",
  ui_story_1020_10200801_9_dialog_content = "이건 벨리사리아의 뜻이기도 해. 벨리사리아는 이미 자난성 주민 이송 명령을 내렸어.",
  ui_story_1020_10200801_10_dialog_content = "그건 의외군...\n알골 박사, 이제 율리시스를 어떻게 처리할 생각이지?",
  ui_story_1020_10200801_11_dialog_content = "율리시스, 당신이 이 창고에서 이 많은 암귀를 만든 건, 「엔지니어」와의 거래 때문이야?",
  ui_story_1020_10200801_12_dialog_content = "순진하군요. 그래도 시스템에 로그인해 자난성의 스위치들을 안정시킨 걸 보면,\n당신도 몇 년간 확실히 성과는 있었던 모양이지만 말입니다.",
  ui_story_1020_10200801_13_dialog_content = "하지만 「가디언」의 방어 데이터를 역컴파일하면서, 그의 공격도 막으려던\n당신 잔머리가 이 상황을 만든 겁니다.",
  ui_story_1020_10200801_14_dialog_content = "무슨 뜻이야?",
  ui_story_1020_10200801_15_dialog_content = "일루미나의 허점은 이렇게 조금씩 메울 수 있는 것이 아닙니다.\n방어를 와해하는 것도 간단한 일이지요.",
  ui_story_1020_10200801_16_dialog_content = "하지만 전 그에게 멈추라고 말하기만 하면 됩니다...",
  ui_story_1020_10200801_17_dialog_content = "그럼 어디 해 봐.",
  ui_story_1020_10200801_18_dialog_content = "전 못 합니다. 아이테르라면 할 수 있다고 제가 말했지만, 당신들은 믿지 않았지요.",
  ui_story_1020_10200801_19_dialog_content = "...내가?",
  ui_story_1020_10200801_20_dialog_content = "다른 사람은 끌어들이지 마라. 그래서 네가 어떻게 「엔지니어」를 막을 수 있다는 거냐?",
  ui_story_1020_10200801_21_dialog_content = "막는다고요? 전 그를 막을 생각이 없습니다만...\n그저 당신들이 제 물건을 부수진 않았는지 보러 왔을 뿐입니다.",
  ui_story_1020_10200801_22_dialog_content = "율리시스! 이제 와서 말을 바꾸겠다는 거야?!",
  ui_story_1020_10200801_23_dialog_content = "이건 애초부터 당신들과는 관계없는 일이었습니다...",
  ui_story_1020_10200801_24_dialog_content = "<color=#e8d9bb>지직── 지지직──</color>",
  ui_story_1020_10200801_25_dialog_content = "또야...",
  ui_story_1020_10200801_26_dialog_content = "...부부...",
  ui_story_1020_10200801_27_dialog_content = "「선물」?",
  ui_story_1020_10200801_28_dialog_content = "...무슨 의미지?",
  ui_story_1020_10200801_29_dialog_content = "아직 끝내지 못한 실험은 당신들이 망쳐 버렸으니, 더는 따지지 않겠습니다.",
  ui_story_1020_10200801_30_dialog_content = "하지만 전 그를 위해 준비한 게 더 있습니다.",
  ui_story_1020_10200801_31_dialog_content = "어디 보자, 여기인가...",
  ui_story_1020_10200801_32_dialog_content = "<color=#e8d9bb>쿠르르릉──!</color>",
  ui_story_1020_10200801_33_dialog_content = "으앗──!",
  ui_story_1020_10200801_34_dialog_content = "내 손 잡아!",
  ui_story_1020_10200801_35_dialog_content = "율리시스, 당신 뭘 건드린 거야?!",
  ui_story_1020_10200801_36_dialog_content = "이, 이 흔들림... 아까보다 훨씬 더 강해요!",
  ui_story_1020_10200801_37_dialog_content = "흔들리는 게 아니야! 이, 이동하고 있어...!",
  ui_story_1020_10200801_38_dialog_content = "모두 조심해라!",
  ui_story_1020_10200801_39_dialog_content = "하하하하하하... 보십시오!",
  ui_story_1020_10200801_40_dialog_content = "<color=#e8d9bb>쿠르르릉──!</color>",
  ui_story_1020_10200801_41_dialog_content = "오로리안과 암귀를 융합한 일당백의 <color=#FFB400>강화 병사</color>들을...",
  ui_story_1020_10200801_42_dialog_content = "전 이미 오래전에 당신의 연구 성과를 뛰어넘었습니다!",
  ui_story_1020_10200801_43_dialog_content = "지하가 전부...",
  ui_story_1020_10200801_44_dialog_content = "대체 얼마나 있는 거죠...?",
  ui_story_1020_10200801_45_dialog_content = "...우리가 서 있는 이 지면이 창고였던 거네! 이러니까 아무리 찾아도 안 나오지!",
  ui_story_1020_10200801_46_dialog_content = "어림잡아도 수백... 아니, 그 이상이야.",
  ui_story_1020_10200801_47_dialog_content = "저 녀석들 몸에 케이블이 잔뜩 꽂혀 있어. 에너지 공급을 받고 있는 것 같아...",
  ui_story_1020_10200801_48_dialog_content = "율리시스!",
  ui_story_1020_10200801_49_dialog_content = "<color=#e8d9bb>파지직──</color>",
  ui_story_1020_10200801_50_dialog_content = "이런... 강화 병사들이 움직이기 시작했어!",
  ui_story_1020_10200801_51_dialog_content = "<color=#e8d9bb>파직── 파직──</color>",
  ui_story_1020_10200801_52_dialog_content = "창고 안에 있는 케이블들 좀 봐... 불꽃이 튀고 있는 것 같아!",
  ui_story_1020_10200801_53_dialog_content = "환경과 일체화된 케이블은 줄곧 이 창고 지하에 있었던 거다!",
  ui_story_1020_10200801_54_dialog_content = "부부! 부부! 부부!",
  ui_story_1020_10200801_55_dialog_content = "이 케이블들로 강화 병사들을 제어하고, 컴퓨터로 명령을 내렸던 거야...",
  ui_story_1020_10200801_56_dialog_content = "...알겠어! 부르!",
  ui_story_1020_10200801_57_dialog_content = "부우!",
  ui_story_1020_10200801_58_dialog_content = "어떻습니까? 마음에 드십니까?!",
  ui_story_1020_10200801_59_dialog_content = "10년 전... 20년 전... 아스트라 대륙을 공격한 암귀들도 이보다 못했을 텐데 말이지요.",
  ui_story_1020_10200801_60_dialog_content = "음?",
  ui_story_1020_10200801_61_dialog_content = "하하하하...",
  ui_story_1020_10200801_62_dialog_content = "<color=#e8d9bb>지직── 지지직──</color>",
  ui_story_1020_10200801_63_dialog_content = "(엔지니어는 어떻게 율리시스가 하는 말을 들을 수 있는 거지?)",
  ui_story_1020_10200801_64_dialog_content = "(프로토타입을 통해서인가? 아니면 다른 소통 방식?)",
  ui_story_1020_10200801_65_dialog_content = "...부부...",
  ui_story_1020_10200801_66_dialog_content = "「말할」",
  ui_story_1020_10200801_67_dialog_content = "...부부...",
  ui_story_1020_10200801_68_dialog_content = "「가치도 없군」",
  ui_story_1020_10200801_X68_dialog_content = "(엔지니어는 어떻게 율리시스가 하는 말을 들을 수 있는 거지?)",
  ui_story_1020_10200801_X69_dialog_content = "(프로토타입을 통해서인가? 아니면 다른 소통 방식?)",
  ui_story_1020_10200801_69_dialog_content = "<color=#e8d9bb>쿠르르릉──!</color>",
  ui_story_1020_10200801_70_dialog_content = "강화 병사들이 전부 일어섰어요!",
  ui_story_1020_10200801_X70_dialog_content = "자... 어떻습니까... 하하하하...",
  ui_story_1020_10200801_71_dialog_content = "히이로는 율리시스를 제압하고, 나머지는 퇴각하라!",
  ui_story_1020_10200801_72_dialog_content = "예!",
  ui_story_1020_10200801_73_dialog_content = "......",
  ui_story_1020_10200801_74_dialog_content = "알골 박사!",
  ui_story_1020_10200801_75_dialog_content = "...이 기계를 내버려둔다면 일루미나는 끝이야!",
  ui_story_1020_10200801_76_dialog_content = "자... 어떻습니까... 하하하하...",
  ui_story_1020_10200801_77_dialog_content = "<color=#e8d9bb>삐비빅──</color>",
  ui_story_1020_10200801_78_dialog_content = "율리시스, 창고의 문은 어떻게 하면 닫을 수 있지?",
  ui_story_1020_10200801_79_dialog_content = "대답해!",
  ui_story_1020_10200801_80_dialog_content = "그게 당신들과 무슨 관계가 있습니까? ...이것들은 당신들의 적이 아닙니다!\n당신들은 그냥 떠나기만 하면 됩니다...",
  ui_story_1020_10200801_81_dialog_content = "헛소리!",
  ui_story_1020_10200801_82_dialog_content = "부르, 루트는 찾았어?! 서둘러야 돼! 더 빨리!",
  ui_story_1020_10200801_83_dialog_content = "부부부부──!",
  ui_story_1020_10200801_X83_dialog_content = "더... 더 빠르게!",
  ui_story_1020_10200801_84_dialog_content = "<color=#e8d9bb>파지직──</color>",
  ui_story_1020_10200801_85_dialog_content = "크오오오──!",
  ui_story_1020_10200801_86_dialog_content = "알골 박사!",
  ui_story_1020_10200801_87_dialog_content = "......",
  ui_story_1020_10200801_88_dialog_content = "알골 박사가 여전히 갈 생각을 안 해요...",
  ui_story_1020_10200801_89_dialog_content = "알골 씨, 제가 감응 능력으로 도와줄게요!",
  ui_story_1020_10200801_90_dialog_content = "아니야! 다들 나가!",
  ui_story_1020_10200801_91_dialog_content = "강화 병사들을 제어하는 루트는 이미 찾았어...",
  ui_story_1020_10200801_92_dialog_content = "부부부부──!",
  ui_story_1020_10200801_93_dialog_content = "데이터베이스 동기화도 끝났고, 좋아! 이제 접근해 보면...",
  ui_story_1020_10200801_94_dialog_content = "빨리... 더 빨리!",
  ui_story_1020_10200801_95_dialog_content = "부부! 부부! 부부!",
  ui_story_1020_10200801_96_dialog_content = "알골 씨! 빨리 피해요!",
  ui_story_1020_10200801_97_dialog_content = "<color=#e8d9bb>콰앙!</color>",
  ui_story_1020_10200801_98_dialog_content = "부부?",
  ui_story_1020_10200801_99_dialog_content = "크오오오──!",
  ui_story_1020_10200801_100_dialog_content = "어떻게 된 거죠? 강화 병사가 알골 씨를 공격하지 않았어요!",
  ui_story_1020_10200801_101_dialog_content = "......",
  ui_story_1020_10200801_102_dialog_content = "<color=#e8d9bb>콰앙! 콰앙! 콰앙!</color>",
  ui_story_1020_10200801_103_dialog_content = "강화 병사들이... 프로토타입을 공격하고 있어요.",
  ui_story_1020_10200801_104_dialog_content = "설마, 율리시스가 강화 병사를 만든 건...",
  ui_story_1020_10200801_105_dialog_content = "하하하하하... 마음에 드십니까? ...음?",
  ui_story_1020_10200801_106_dialog_content = "...당신의 암귀들은... 어디 있습니까?",
  ui_story_1020_10200801_107_dialog_content = "<color=#e8d9bb>지직── 지지직──</color>",
  ui_story_1020_10200801_108_dialog_content = "...부부...",
  ui_story_1020_10200801_109_dialog_content = "「고맙군」",
  ui_story_1020_10200801_110_dialog_content = "...고맙다고?",
  ui_story_1020_10200801_111_dialog_content = "......",
  ui_story_1020_10200801_112_dialog_content = "크어어...",
  ui_story_1020_10200801_113_dialog_content = "강화 병사들의 움직임이... 멈췄어.",
  ui_story_1020_10200801_114_dialog_content = "뭘 찾고 있는 걸까요?",
  ui_story_1020_10200801_115_dialog_content = "<color=#e8d9bb>타닥타닥── 화르륵──</color>",
  ui_story_1020_10200801_116_dialog_content = "알골 박사, 저 케이블들에서 또 불꽃이 튀기 시작했어!",
  ui_story_1020_10200801_117_dialog_content = "괜찮아... 내가 명령을 끊을 거니까...",
  ui_story_1020_10200801_118_dialog_content = "<color=#e8d9bb>삑── 삑── 삑──</color>",
  ui_story_1020_10200801_119_dialog_content = "...으아아아아! 괴물! 이건 괴물이야!",
  ui_story_1020_10200801_120_dialog_content = "지금 뭘 하려는 겁니까...?",
  ui_story_1020_10200801_121_dialog_content = "<color=#e8d9bb>타닥타닥── 화르륵──</color>",
  ui_story_1020_10200801_122_dialog_content = "저 강화 병사들의 뒤를 봐!",
  ui_story_1020_10200801_123_dialog_content = "크어어어──!",
  ui_story_1020_10200801_124_dialog_content = "녀석이 또 공격하기 시작했어!",
  ui_story_1020_10200801_125_dialog_content = "제 물건에 무슨 짓을 하려는 겁니까?!",
  ui_story_1020_10200801_126_dialog_content = "크어어어──!",
  ui_story_1020_10200801_127_dialog_content = "알골 씨! 위험해요!",
  ui_story_1020_10200901_1_dialog_content = "<color=#e8d9bb>콰르르르르──!</color>",
  ui_story_1020_10200901_2_dialog_content = "바튼 님! 저희는 이미 최선을 다했습니다!",
  ui_story_1020_10200901_3_dialog_content = "하지만 <color=#FFB400>10호 성문</color> 쪽 전우들이 아직 고전 중입니다! 지원이 필요합니다!",
  ui_story_1020_10200901_4_dialog_content = "그럼 너희 정예 소대는 이렇게 좋은 실전 기회를 남에게 넘겨줄 생각이냐?!",
  ui_story_1020_10200901_5_dialog_content = "아닙니다! 성문의 진동이 너무 강력해 저희 몸이 더는 버틸 수가 없습니다...",
  ui_story_1020_10200901_6_dialog_content = "10호 성문이면... 정비공장이 있는 방향이잖아?",
  ui_story_1020_10200901_7_dialog_content = "설마 그 애송이의 스카이워커호도 성문을 지탱하려고 나선 건가?",
  ui_story_1020_10200901_8_dialog_content = "콜로서스가 성문을 지탱할 수 있습니까...?",
  ui_story_1020_10200901_9_dialog_content = "안 될 건 뭐냐? 콜로서스는 아이테르도 키워 낸 녀석이다!",
  ui_story_1020_10200901_10_dialog_content = "자, 날 따라와라! 내 몸이 고철 덩어리보다 못할 순 없지!",
  ui_story_1020_10200901_11_dialog_content = "바튼 님! <color=#FFB400>9호 성문</color> 쪽도 땅이 강하게 흔들리고 있습니다!\n마치 지하에서 위로 뚫고 올라오려는 듯 엄청난 기류가 발생했습니다!",
  ui_story_1020_10200901_12_dialog_content = "지하?! 당장 모든 환기구를 조사해라! 구석구석까지 절대 놓치지 마라!",
  ui_story_1020_10200901_13_dialog_content = "이미 조사했습니다! 아직 암귀의 흔적은 보이지 않았습니다!",
  ui_story_1020_10200901_14_dialog_content = "대체 뭐가 어떻게 된 거냐...",
  ui_story_1020_10200901_15_dialog_content = "<color=#e8d9bb>9호 성문 근처</color>",
  ui_story_1020_10200901_16_dialog_content = "박사님, 현재 이 지역은 흔들림이 거셉니다. 부디 안전한 곳으로 피해 주십시오!",
  ui_story_1020_10200901_17_dialog_content = "전 신경 쓸 거 없어요. 지금 밑에 수직구가 가동 중이에요.\n전 위쪽 진동은 어떤지 조사하러 온 거니까요.",
  ui_story_1020_10200901_18_dialog_content = "수직구... 말씀이십니까?",
  ui_story_1020_10200901_19_dialog_content = "<color=#e8d9bb>쿠구구구──</color>",
  ui_story_1020_10200901_20_dialog_content = "괜찮네요. 이 정도면 성문에 주는 영향이 크진 않겠어요.",
  ui_story_1020_10200901_21_dialog_content = "......",
  ui_story_1020_10200901_22_dialog_content = "<color=#e8d9bb>백야성, 여명 아카데미</color>",
  ui_story_1020_10200901_23_dialog_content = "만물은 백야 아래에. 그 얘기 들었어요? 아카데미 안 <color=#FFB400>백야석</color>에 갑자기 이변이 생겨서,\n루미나가 뒤엉키는 현상이 몇 날 며칠 동안 계속되고 있대요.",
  ui_story_1020_10200901_24_dialog_content = "신부님과 수녀님들이 가서 루미나틱스를 최대한 시전하는 중인데도,\n전혀 가라앉지 않는다고 해요!",
  ui_story_1020_10200901_25_dialog_content = "저번에 발생한 백야성의 진동과 관계가 있는 걸까요?",
  ui_story_1020_10200901_26_dialog_content = "음, 어쩌면 고대 유적이 또 신비한 힘과 공명했을지도 모르겠네요.",
  ui_story_1020_10200901_27_dialog_content = "전에 더스크 타운에서 오로라 교란이 일어났을 때도 그랬었는데,\n이번엔 그때보다 훨씬 심각해요.",
  ui_story_1020_10200901_28_dialog_content = "<color=#e8d9bb>백야성 본성</color>",
  ui_story_1020_10200901_29_dialog_content = "봐라, 지면에서 탐욕스럽게 주둥이를 벌리고 있는 저 구덩이들을.\n일루미나, 저 늑대 놈들의 뱃가죽이 등에 붙은 모양이군!",
  ui_story_1020_10200901_30_dialog_content = "그 굶주린 늑대의 송곳니가 아직 백야성에 닿진 않았다.",
  ui_story_1020_10200901_31_dialog_content = "호위대장, 유적은 이미 안정된 상태다. 방어 태세를 해제하도록.",
  ui_story_1020_10200901_32_dialog_content = "예.",
  ui_story_1020_10200901_33_dialog_content = "성주님, 여명 아카데미의 루미나 저장석이 조금 전 진동에 격렬한 반응을 보였습니다.\n백야성에 알 수 없는 힘이 존재한다고 생각하십니까?",
  ui_story_1020_10200901_34_dialog_content = "만물은 백야 아래에. 카렌 전하, 심려 마십시오.",
  ui_story_1020_10200901_35_dialog_content = "비록 성녀님께서 신전에 들어가신 이후로는 발생한 적 없던 상황입니다만,\n그래도 빛의 신께서 저희를 인도해 주실 겁니다.",
  ui_story_1020_10200901_36_dialog_content = "신부, 그대는 백야석에 이변이 발생한 연유가 무엇이라 생각하나?",
  ui_story_1020_10200901_37_dialog_content = "교전에 관련 기록이 존재합니다. 새로운 <color=#FFB400>영혼의 계승자</color>가 나타날 무렵,\n루미나가 뒤엉킬 것이라는 내용이지요.",
  ui_story_1020_10200901_38_dialog_content = "......",
  ui_story_1020_10200901_39_dialog_content = "지하 유적에 숨겨진 사악한 힘이 과거에 부유섬 전체를 뒤흔들었을 때,\n그 사악한 힘을 몰아낸 것은 영혼의 계승자인 성녀님이셨다.",
  ui_story_1020_10200901_40_dialog_content = "헤아려 보건대, 성녀님께서는 이미 오랫동안 이 부유섬을 지켜 오신 것이겠지.",
  ui_story_1020_10200901_41_dialog_content = "사악함은 줄어들 뿐, 몰아낼 수는 없습니다. 백야성은 티끌 하나 없는 섬이 아닙니다.",
  ui_story_1020_10200901_42_dialog_content = "신부님, 백야성이 위험에 빠질까요?",
  ui_story_1020_10200901_43_dialog_content = "그럴 일은 없습니다.",
  ui_story_1020_10200901_44_dialog_content = "그렇다면 일루미나 연방은 어떤가요?",
  ui_story_1020_10200901_45_dialog_content = "그들은 먼저 자신의 믿음부터 찾아내야 할 것입니다.",
  ui_story_1020_10200901_46_dialog_content = "호위대장, 일루미나에서 보내오는 서신에 유의하도록.",
  ui_story_1020_10200901_47_dialog_content = "네, 성주님.",
  ui_story_1020_10200901_48_dialog_content = "<color=#e8d9bb>쿠구구구──</color>",
  ui_story_1020_10200901_49_dialog_content = "알골 박사, 현재 상황은 어떻지?",
  ui_story_1020_10200901_50_dialog_content = "컨트롤러에서 출력되는 표시를 보면, 코어 구축도 이제 곧 완료될 거야.",
  ui_story_1020_10200901_51_dialog_content = "엔지니어가 왠지 모르게 잠잠하니까... 조금만 더 힘내, 부르!",
  ui_story_1020_10200901_52_dialog_content = "부부! 부부! 부부!",
  ui_story_1020_10200901_53_dialog_content = "뭐라고...?",
  ui_story_1020_10200901_54_dialog_content = "<color=#e8d9bb>지직── 지지직──</color>",
  ui_story_1020_10200901_55_dialog_content = "...부부...",
  ui_story_1020_10200901_56_dialog_content = "「집으로 돌아와라, 아이테르」",
  ui_story_1020_10200901_57_dialog_content = "아이테르는 어디에도 가지 않습니다!",
  ui_story_1020_10200901_58_dialog_content = "......",
  ui_story_1020_10200901_59_dialog_content = "「엔지니어」는 율리시스와 대화 중인 거 아니었나요?\n어떻게 PlayerName에 대해 알고 있는 거죠?",
  ui_story_1020_10200901_60_dialog_content = "(집으로 돌아와라, 아이테르.)",
  ui_story_1020_10200901_61_dialog_content = "「엔지니어」의 목소리... 어디서 들어 본 적 있는 것 같아요...",
  ui_story_1020_10200901_62_dialog_content = "어디서 들었는데?",
  ui_story_1020_10200901_63_dialog_content = "머릿속에서요...",
  ui_story_1020_10200901_64_dialog_content = "머릿속을 스쳐 지나간 장면들이... 진짜로 감응이었어요...",
  ui_story_1020_10200901_65_dialog_content = "(집으로 돌아와라, 아이테르.)",
  ui_story_1020_10200901_66_dialog_content = "(...당신 누구야?)",
  ui_story_1020_10200901_67_dialog_content = "(너희는 나를 엔지니어라고 부른다.)",
  ui_story_1020_10200901_68_dialog_content = "(당신은 이클립스의 암귀고... 프로토타입으로 일루미나의 강화 병사들을 통제하고 있지?)",
  ui_story_1020_10200901_69_dialog_content = "(아니다.)",
  ui_story_1020_10200901_70_dialog_content = "(...당신이 일루미나의 「가디언 1호」 코어를 훔치고,\n암귀들이 자난성에 침입하게 만들었잖아.)",
  ui_story_1020_10200901_71_dialog_content = "(그것은 원래부터 나의 것이었다.)",
  ui_story_1020_10200901_72_dialog_content = "(너 또한 그러하다.)",
  ui_story_1020_10200901_73_dialog_content = "(...난 아스트라 대륙의 헤븐즈 밸리에서 태어났어. 난 아이테르야.)",
  ui_story_1020_10200901_74_dialog_content = "(아이테르는 어떻게 탄생했지?)",
  ui_story_1020_10200901_75_dialog_content = "(당신, 나한테... 아이테르한테 뭘 한 거야?)",
  ui_story_1020_10200901_76_dialog_content = "(집으로 돌아와라, 아이테르.)",
  ui_story_1020_10200901_77_dialog_content = "(나와 함께, 그 숭고한 대업을 계속해 나가는 것이다.)",
  ui_story_1020_10200901_78_dialog_content = "「숭고한 대업」...? 아이테르는 어디에도 가지 않습니다!",
  ui_story_1020_10200901_79_dialog_content = "율리시스, 대체 무슨 소리를 하는 겁니까?!",
  ui_story_1020_10200901_80_dialog_content = "......",
  ui_story_1020_10200901_81_dialog_content = "(율리시스도 당신이랑 감응할 수 있는 거야?)",
  ui_story_1020_10200901_82_dialog_content = "(저자는 너와 다르다.)",
  ui_story_1020_10200901_83_dialog_content = "(네가 알고자 하는 모든 진실을 알려 주겠다.)",
  ui_story_1020_10200901_84_dialog_content = "(고대 어둠의 밑바닥 전장, 콜로서스 정박장, 아이테르의 터전...)",
  ui_story_1020_10200901_85_dialog_content = "(그리고 네가 줄곧 갈망해 왔던 동족들에 대한 진실을.)",
  ui_story_1020_10200901_86_dialog_content = "(......?!)",
  ui_story_1020_10200901_87_dialog_content = "<color=#e8d9bb>삑── 삐빅── 삐비빅──</color>",
  ui_story_1020_10200901_88_dialog_content = "알골의 하이테크 밴드에서 위험 요소 감지 알림이 울리고 있습니다.",
  ui_story_1020_10200901_89_dialog_content = "일루미나 정비공장...?",
  ui_story_1020_10200901_90_dialog_content = "PlayerName! 콜로서스가 내 단말기랑 연결을 끊고 있어!",
  ui_story_1020_10200901_91_dialog_content = "스카이워커...!",
  ui_story_1020_10200901_92_dialog_content = "(당신이 한 짓이야?!)",
  ui_story_1020_10200901_93_dialog_content = "(난 네가 가동했다고 생각했다만.)",
  ui_story_1020_10200901_94_dialog_content = "아...안 돼!",
  ui_story_1020_10200901_95_dialog_content = "<color=#e8d9bb>콰앙──</color>",
  ui_story_1020_10200901_96_dialog_content = "PlayerName!",
  ui_story_1020_10200901_97_dialog_content = "오우, 벌써 달려 나갔습니다.",
  ui_story_1020_10200901_98_dialog_content = "비비안, 지금 밖은 위험하다. 쫓아가 봐라.",
  ui_story_1020_10200901_99_dialog_content = "네!",
  ui_story_1020_10200901_100_dialog_content = "아이테르는 어디에도 가지 않습니다! 당신 목표는 바로 저란 말입니다...",
  ui_story_1020_10200901_101_dialog_content = "율리시스, 더는 멋대로 굴지 마세요!",
  ui_story_1020_10200901_102_dialog_content = "이거 놓으세요! 제가 상대할 겁니다!",
  ui_story_1020_10200901_103_dialog_content = "<color=#e8d9bb>타탁타닥──</color>",
  ui_story_1020_10200901_104_dialog_content = "부부! 부부! 부부!",
  ui_story_1020_10200901_105_dialog_content = "멈춰! 율리시스!",
  ui_story_1020_10200901_106_dialog_content = "그어어!",
  ui_story_1020_10200901_107_dialog_content = "이렇게 오랜 시간을 들여... 결국 저도 해냈습니다...",
  ui_story_1020_10200901_108_dialog_content = "이 정도면 충분합니까...?!",
  ui_story_1020_10200901_109_dialog_content = "부족하다면 더 있습니다!\n암귀 따위보다 수백, 수천 배는 더 강한 강화 병사들이 얼마든지 더 있단 말입니다!",
  ui_story_1020_10200901_110_dialog_content = "<color=#e8d9bb>지직── 지지직──</color>",
  ui_story_1020_10200901_111_dialog_content = "...부부...",
  ui_story_1020_10200901_112_dialog_content = "「마지막이다」",
  ui_story_1020_10200901_113_dialog_content = "이런, 율리시스를 제압해! 엔지니어가 강화 병사를 제어해 공격할 거야!",
  ui_story_1020_10200901_114_dialog_content = "율리시스는 제게 맡기세요!",
  ui_story_1020_10200901_115_dialog_content = "<color=#e8d9bb>지지직──</color>",
  ui_story_1020_10200901_116_dialog_content = "으아악! 간신히 구축한 방어 모듈이...!",
  ui_story_1020_10200901_117_dialog_content = "크오오오!",
  ui_story_1020_10201001_1_dialog_content = "PlayerName!",
  ui_story_1020_10201001_2_dialog_content = "여기서 정비공장까지는 거리가 좀 있어요! 밖은 너무 위험해요!",
  ui_story_1020_10201001_3_dialog_content = "...스카이워커가 떠나게 둘 순 없어!",
  ui_story_1020_10201001_4_dialog_content = "스카이워커호가 당신 명령도 없이 어떻게 혼자 가동한 거죠?",
  ui_story_1020_10201001_5_dialog_content = "......",
  ui_story_1020_10201001_6_dialog_content = "봤어...",
  ui_story_1020_10201001_7_dialog_content = "뭘 봤죠...?",
  ui_story_1020_10201001_8_dialog_content = "나도 봤어... 율리시스가 본 걸...",
  ui_story_1020_10201001_9_dialog_content = "그리고 목소리가 들렸어... 「엔지니어」가 나랑 스카이워커한테...\n「집으로 돌아오라」고 하는 목소리가...",
  ui_story_1020_10201001_10_dialog_content = "PlayerName...",
  ui_story_1020_10201001_11_dialog_content = "힘들게 스카이워커를 되찾아서, 다시 만난 지 얼마 되지도 않았는데...",
  ui_story_1020_10201001_12_dialog_content = "그러니까 절대로... 절대로 이런 일이 벌어지게 둘 순 없어!",
  ui_story_1020_10201001_13_dialog_content = "지금 내가 뭘 할 수 있지...? 뭘 해야...",
  ui_story_1020_10201001_14_option_content = "(감응 연결!)",
  ui_story_1020_10201001_15_dialog_content = "......",
  ui_story_1020_10201001_16_option_content = "(감응 연결!)",
  ui_story_1020_10201001_17_dialog_content = "......",
  ui_story_1020_10201001_18_dialog_content = "스카이워커... 벌써 가 버린 거야?",
  ui_story_1020_10201001_19_dialog_content = "오늘 실험동을 나설 때 뭐라고 설명하기 힘든 느낌을 받았었어.",
  ui_story_1020_10201001_20_dialog_content = "내 머리 위 천장에 난 거대한 구멍에서 한 줄이 빛이 내려오더니,\n내 모든 희망을 앗아가 버리는 것 같은 느낌이었어...",
  ui_story_1020_10201001_21_dialog_content = "그리고... 자꾸만 스카이워커가 그 구멍으로 날아가 버릴지도 모른단 생각이 들었어...",
  ui_story_1020_10201001_22_dialog_content = "그때... 왜 그런 생각이 든 건진 나도 잘 모르겠어...!",
  ui_story_1020_10201001_23_dialog_content = "전에 꿨던 그 꿈들도 그렇고, 진작 눈치챘어야 했는데...",
  ui_story_1020_10201001_24_option_content = "(감응 연결!)",
  ui_story_1020_10201001_25_dialog_content = "......",
  ui_story_1020_10201001_26_option_content = "(감응 연결!)",
  ui_story_1020_10201001_27_dialog_content = "......",
  ui_story_1020_10201001_28_option_content = "(감응 연결!)",
  ui_story_1020_10201001_29_dialog_content = "......",
  ui_story_1020_10201001_30_dialog_content = "으아아악──!",
  ui_story_1020_10201001_31_dialog_content = "어서 멈춰요, PlayerName!",
  ui_story_1020_10201001_32_dialog_content = "당신 오늘 감응 능력을 이미 너무 많이 썼어요. 안색이 안 좋아요!",
  ui_story_1020_10201001_33_dialog_content = "바이스랑 연락도 안 되는 상황인데... 스카이워커하고도 연락이 끊겨 버리면,\n나한테 남은 건 아무것도 없잖아...",
  ui_story_1020_10201001_34_dialog_content = "...대체 스카이워커를 어디로 보낸 거야? 엔지니어는 뭘 하려는 거냐고?!",
  ui_story_1020_10201001_35_dialog_content = "그 문제의 답이라면, 내게 물어도 좋다.",
  ui_story_1020_10201001_36_dialog_content = "「발도!」",
  ui_story_1020_10201001_37_dialog_content = "비비안 씨!",
  ui_story_1020_10201001_38_dialog_content = "...피제로?",
  ui_story_1020_10201001_39_dialog_content = "가볍군. 아니지, 무르군...",
  ui_story_1020_10201001_40_dialog_content = "너무 무른 나머지 차마 손도 못 대겠단 말이다!",
  ui_story_1020_10201001_41_dialog_content = "하하, 역시 타인이 소중한 무언가를 잃는 모습을 지켜보는 건 참으로 달콤한 일이란 말이지.",
  ui_story_1020_10201001_42_dialog_content = "...넌 스카이워커가 날아갈 걸 알고 있었어?!",
  ui_story_1020_10201001_43_dialog_content = "차라리 내가 스카이워커호에 뭘 했는지 묻는 건 어떤가?",
  ui_story_1020_10201001_44_dialog_content = "이 자식...!",
  ui_story_1020_10201001_45_dialog_content = "잠깐 기다려요, PlayerName. 저 녀석 어딘가 좀 이상해요...",
  ui_story_1020_10201001_46_dialog_content = "구금실에 갇혀 움직이지도 못했을 텐데, 어떻게 탈출해 나온 걸까요...?",
  ui_story_1020_10201001_47_dialog_content = "믿기지 않나? 이게 바로 그분의 힘이다.",
  ui_story_1020_10201001_48_dialog_content = "그 사슬은 날 비참하게 묶어 두었지만, 난 나를 묶은 쓰레기들의 숨통이 끊어질 때,\n절망의 아름다움을 최대한 음미할 수 있게 해 주었지.",
  ui_story_1020_10201001_49_dialog_content = "다만 그 맛은... 아이테르와 비교하면 한참이나 뒤떨어지더군.",
  ui_story_1020_10201001_50_dialog_content = "하하하, 선택해라, 아이테르. 애잔한 네 동포들처럼 덧없는 죽음을 맛보고 싶은가?",
  ui_story_1020_10201001_51_dialog_content = "아니면 내가 그분께 드릴 선물이 되어, 나와 함께 그분의 위엄을 목도할 테냐.",
  ui_story_1020_10201001_52_dialog_content = "아이테르에게 덧없는 죽음은 없어! 엔지니어는 어디 있어?!",
  ui_story_1020_10201001_53_dialog_content = "하하하하! 좋다! 후자를 선택한 모양이군.",
  ui_story_1020_10201001_54_dialog_content = "그렇다면 네 곁의 그 쓰레기는 이제 안심하고 죽어도 좋다.",
  ui_story_1020_10201001_55_dialog_content = "PlayerName에겐 손끝 하나 못 대요!",
  ui_story_1020_10201001_56_dialog_content = "내 힘을 맛보고 싶은 모양이지? 오로리안들의 선혈과 맞바꾼 이 다크매터를 말이야.",
  ui_story_1020_10201001_57_dialog_content = "PlayerName! 제 뒤로 피해 있어요.",
  ui_story_1020_10201001_58_dialog_content = "발악하는 꼴이 참 우습군...",
  ui_story_1020_10201001_59_dialog_content = "아직 고통을 느낄 수 있음을 행복으로 여겨라.\n이제 곧 위대한 시대가 임하면, 그분께서 널 해방해 주실 테니.",
  ui_story_1020_10201001_60_dialog_content = "까마귀여, 아이테르의 선혈을 맛보거라!",
  ui_story_1020_10201001_61_dialog_content = "이 암귀 녀석! PlayerName한테 손대지 마!",
  ui_story_1020_10201001_62_dialog_content = "안 늦어서 다행이에요!",
  ui_story_1020_10201001_63_dialog_content = "PlayerName! 비비안 참모장님! 다친 곳은 없으신가요?",
  ui_story_1020_10201001_64_dialog_content = "숀?! 빨리 피해! 녀석의 다크매터에 다칠 거야!",
  ui_story_1020_10201001_65_dialog_content = "알고 있어! 하지만 내가 널 지킬 거야, PlayerName!",
  ui_story_1020_10201001_66_dialog_content = "어때? 이 정도면 실망하진 않았지?",
  ui_story_1020_10201001_67_dialog_content = "실망이라니... 숀, 네 몸이... 녀석의 공격을 거뜬히 막아냈잖아!",
  ui_story_1020_10201001_68_dialog_content = "당연하지! 나도 잉겔, 악셀리아랑 똑같은 「슈퍼 솔저」니까!",
  ui_story_1020_10201001_69_dialog_content = "그리고... 심장이 뛰고 피가 흐르는 오로리안이야.",
  ui_story_1020_10201001_70_dialog_content = "PlayerName, 참모장님, 이 암귀는 저한테 맡겨 주세요!",
  ui_story_1020_10201001_71_dialog_content = "숀, 조심해요! 녀석은 비열한 수단을 쓸 거예요. 나머지 암귀는 우리가 맡을게요!",
  ui_story_1020_10201001_72_dialog_content = "네!",
  ui_story_1020_10201001_73_dialog_content = "흐흐... 무르군! 너무 물러!",
  ui_story_1020_10201101_1_dialog_content = "조무래기들이... 날 막겠다는 거냐?",
  ui_story_1020_10201101_2_dialog_content = "이번에야말로 난 반드시 사명을 완수해야 한단 말이다... 그러지 못하면...",
  ui_story_1020_10201101_3_dialog_content = "...너, 귀에 털 난 놈... 내 다크매터를 맞고도 멀쩡하다니...",
  ui_story_1020_10201101_4_dialog_content = "그, 그래서 뭐?! 절대 내 동료들을 해치게 두지 않아!",
  ui_story_1020_10201101_5_dialog_content = "흥, 그 모습도 이상할 건 없겠지...\n네놈들 순혈 아인족들은 이미 멸종했거늘, 넌 아직도 살아남았군.",
  ui_story_1020_10201101_6_dialog_content = "...하고 싶은 말이 뭐야?",
  ui_story_1020_10201101_7_dialog_content = "나 피제로는 아인족 섬멸이라는 위대한 계획에 참여할 수 있었다.\n그것은 내가 그분을 위해 한 일 중에서 가장 영광스러운 것이었지.",
  ui_story_1020_10201101_8_dialog_content = "하지만 그 교활하고 게으른 아인들이 존속을 위해 오로리안과 화친을 맺고,\n지금까지 살아남아 버린 모양이로군!",
  ui_story_1020_10201101_9_dialog_content = "바퀴벌레만큼 강한 생명력이라고 해야 맞겠지?",
  ui_story_1020_10201101_10_dialog_content = "닥쳐! 숀한테 그따위로 말하지 마!",
  ui_story_1020_10201101_11_dialog_content = "뭐냐, 화가 나는 것이냐? 날 죽이고 싶은가?",
  ui_story_1020_10201101_12_dialog_content = "아직도 스카이워커호가 어디로 갔는지 알고 싶나?\n그리고 늘 거머리처럼 네 옆에 붙어 다니던 일루미나의 그 계집도 말이야.",
  ui_story_1020_10201101_13_dialog_content = "그 계집은 아네모네를 만났으니, 아마 끔찍한 죽음을 맞이했겠지.",
  ui_story_1020_10201101_14_dialog_content = "...아네모네는 또 누구야?! ...말해! 바이스한테 대체 무슨 일이 생긴 거냐고!",
  ui_story_1020_10201101_15_dialog_content = "잠깐만... 분명히 그때...",
  ui_story_1020_10201101_16_dialog_content = "그래서 엔지니어는 어디 있어? 스카이워커호는 또 어디로 간 거야?! 대답해!",
  ui_story_1020_10201101_17_dialog_content = "......",
  ui_story_1020_10201101_18_dialog_content = "아아! 위대한 주인이시여! 부디 절 버리지 마십시오!",
  ui_story_1020_10201101_19_dialog_content = "......",
  ui_story_1020_10201101_20_dialog_content = "저 녀석 지금 누구랑 말하는 거죠? 「주인」이라니...?",
  ui_story_1020_10201101_21_dialog_content = "엔지니어랑 연결된 거야. 의식 속에서 말하고 있는 거겠지...",
  ui_story_1020_10201101_22_dialog_content = "단서를 알아내려면 기회는 지금뿐일지도 몰라...",
  ui_story_1020_10201101_23_dialog_content = "PlayerName, 뭘 하려는 거죠?",
  ui_story_1020_10201101_24_option_content = "(강제 감응!)",
  ui_story_1020_10201101_25_dialog_content = "(크윽... 괴로워...)",
  ui_story_1020_10201101_26_dialog_content = "(...그래도 지금 그런 거 따질 때가 아냐!)",
  ui_story_1020_10201101_27_dialog_content = "(바이스한테 무슨 일이 일어났고, 스카이워커가 어디로 갔는지...)",
  ui_story_1020_10201101_28_dialog_content = "(난 꼭... 그 답을 알아내야 해...)",
  ui_story_1020_10201101_29_dialog_content = "(육체는 여위고 허약하며, 몰골도 추하군.)",
  ui_story_1020_10201101_30_dialog_content = "저, 전 괜찮습니다! 당신의 인장만 있다면...\n그 비천한 오로리안과 암귀 모두 제게 머리를 조아릴 겁니다.",
  ui_story_1020_10201101_31_dialog_content = "(네게 머리를 조아린다? 그렇다면 내게는 누가 조아리지?)",
  ui_story_1020_10201101_32_dialog_content = "당신의 위엄은 저를 전율케 합니다... 제가 평생 당신의 날개가 되겠습니다!",
  ui_story_1020_10201101_33_dialog_content = "(네 신분을 인정하는 이 고리를 차겠나?)",
  ui_story_1020_10201101_34_dialog_content = "고리...",
  ui_story_1020_10201101_35_dialog_content = "차겠습니다! 그것은 당신께서 제게 내려 주시는 은총이자, 제 생명의 의미이고,\n고귀한 영혼에게만 주어지는 인장입니다!",
  ui_story_1020_10201101_36_dialog_content = "무릎을 꿇고 감사드립니다, 지고의 지배자시여!",
  ui_story_1020_10201101_37_dialog_content = "(좋다.)",
  ui_story_1020_10201101_38_dialog_content = "부디 제, 제게... 으아악!",
  ui_story_1020_10201101_39_dialog_content = "머, 머리가...! 너무나도... 고통스럽습니다...\n사, 살려 주십시오... 지고의, 지배자시여...",
  ui_story_1020_10201101_40_dialog_content = "(이건 피제로의 예전 기억이야... 저 목소리는 엔지니어고...)",
  ui_story_1020_10201101_41_dialog_content = "(이클립스의 팬텀이 족쇄를 상징하는 고리를 자발적으로 차다니...)",
  ui_story_1020_10201101_42_dialog_content = "(......)",
  ui_story_1020_10201101_43_dialog_content = "(내 감응 능력으로 이렇게 먼 과거까지 볼 수 있을 줄 몰랐어...\n엔지니어의 꿈속을 보고 나서부터 이렇게 된 건가?)",
  ui_story_1020_10201101_44_dialog_content = "(아니면 알골 씨랑 훈련하다가 부르와 감응한 뒤부터인가...?)",
  ui_story_1020_10201101_45_dialog_content = "(바이스랑 스카이워커에 관련된 단서를 찾으려면, 더 최근 기억을 감응해야 할 거야...)",
  ui_story_1020_10201101_46_option_content = "(감응 확장──)",
  ui_story_1020_10201101_47_dialog_content = "(으윽... 이 다크매터... 부르를 감응했을 때만큼 괴로워...)",
  ui_story_1020_10201101_48_dialog_content = "(그래도 한번 겪어 봐서... 이것도 참을 만한 것 같아...)",
  ui_story_1020_10201101_49_dialog_content = "(어...? 여긴... 어둠의 밑바닥인가?)",
  ui_story_1020_10201101_50_dialog_content = "(이런 거대한 구멍이... 게다가 바닥의 균열들이 아직도\n멀리까지 뻗어 나가고 있는 것 같아...)",
  ui_story_1020_10201101_51_dialog_content = "(설마 이게 엔지니어가 말했던 고대 전쟁의 유적인 건가?)",
  ui_story_1020_10201101_52_dialog_content = "(대제 무슨 일이 있었길래 이런 모습이 돼버린 거지?)",
  ui_story_1020_10201101_53_dialog_content = "(이 주변에... 콜로서스가 있을 것 같진 않은데...)",
  ui_story_1020_10201101_54_option_content = "(감응 확장──)",
  ui_story_1020_10201101_55_dialog_content = "(...이건... 콜로서스의 잔해 더미잖아?)",
  ui_story_1020_10201101_56_dialog_content = "(하나, 둘, 셋...)",
  ui_story_1020_10201101_57_dialog_content = "(......)",
  ui_story_1020_10201101_58_dialog_content = "(콜로서스의 정박지라는 게...)",
  ui_story_1020_10201101_59_dialog_content = "(평평해진 모래 언덕이었다니... 귀환의 탑하곤 완전히 다르네.)",
  ui_story_1020_10201101_60_dialog_content = "(바람에 깎여 거룡의 뼈 같은 모습밖에 남지 않은 이 콜로서스들은...\n무슨 일들을 겪었던 걸까...)",
  ui_story_1020_10201101_61_dialog_content = "(대체 이건 얼마나 오래전 장면이지? 생명의 숨결이라곤 티끌만큼도 안 느껴져...)",
  ui_story_1020_10201101_62_dialog_content = "(참, 「가디언 1호」의 코어...)",
  ui_story_1020_10201101_63_dialog_content = "(스카이워커의 데이터에 표시됐던 그 좌표가 단서가 돼 줄지도 몰라...)",
  ui_story_1020_10201101_64_dialog_content = "(좌표... 빛나는 기둥...)",
  ui_story_1020_10201101_65_option_content = "(감응 확장──)",
  ui_story_1020_10201101_66_dialog_content = "(여기야!)",
  ui_story_1020_10201101_67_dialog_content = "(틀림없어. 전에 율리시스의 의식에서 본 거랑 똑같아...)",
  ui_story_1020_10201101_68_dialog_content = "(이 빛나는 기둥들이 바로 「가디언 1호」의 코어구나.\n지금은 그때보다 더 선명하게 보여...)",
  ui_story_1020_10201101_69_dialog_content = "(바위가 위쪽으로 이동하고 있어. 분명히 위에 뭔가 있을 거야...)",
  ui_story_1020_10201101_70_dialog_content = "(준비는 되었나.)",
  ui_story_1020_10201101_71_dialog_content = "네. 마지막 <color=#FFB400>구동 링</color>은 이미 손에 넣었습니다.",
  ui_story_1020_10201101_72_dialog_content = "(좋다.)",
  ui_story_1020_10201101_73_dialog_content = "고귀하신 당신의 이름을 읊나니, 부디 지켜봐 주시옵소서──",
  ui_story_1020_10201101_74_dialog_content = "저희는 당신의 강림을 기다리나이다──",
  ui_story_1020_10201101_75_dialog_content = "너는 누구냐.",
  ui_story_1020_10201101_76_dialog_content = "......",
  ui_story_1020_10201101_77_dialog_content = "일루미나 계집입니다. 과학자이기도 하지요.",
  ui_story_1020_10201101_78_dialog_content = "(일루미나.)",
  ui_story_1020_10201101_79_dialog_content = "그 쓸모없는 까마귀도 일루미나에 있습니다.",
  ui_story_1020_10201101_80_dialog_content = "(일루미나, 참 그리운 이름이군.)",
  ui_story_1020_10201101_81_dialog_content = "<color=#e8d9bb>쿠구구구──</color>",
  ui_story_1020_10201101_82_dialog_content = "(아까 본 장면... 역시 꿈이 아니었어...)",
  ui_story_1020_10201101_83_dialog_content = "(하지만 저번엔 바이스를 봤는데, 이번엔 본 건... 바이스가 아니라 노라잖아...)",
  ui_story_1020_10201101_84_dialog_content = "(노라 옆에 있는 건... 팬텀들인 건가...?)",
  ui_story_1020_10201101_85_dialog_content = "다, 당신이셨군요... 지고의 지배자시여!",
  ui_story_1020_10201101_86_dialog_content = "당신의 충직한 종 피제로, 이곳에서 무릎을 꿇고 당신의 강림을 기다렸습니다.",
  ui_story_1020_10201101_87_dialog_content = "(너는 아무것도 이루지 못했다.)",
  ui_story_1020_10201101_88_dialog_content = "제게도 찬란히 빛나던 때가 있었습니다!\n위대하신 주인이시여! 전 과거에 아인족 학살 작전을 이끌어...",
  ui_story_1020_10201101_89_dialog_content = "(그것은 이미 몇백 년 전의 일이다.)",
  ui_story_1020_10201101_90_dialog_content = "(네게 준 것들은 내가 필요할 때 다시 가져갈 것이다.)",
  ui_story_1020_10201101_91_dialog_content = "그...그러지 않으시리라 믿습니다! 전 당신께서 직접 만드신 날개입니다!",
  ui_story_1020_10201101_92_dialog_content = "(너를 대신해 사슬을 끊어 주겠다.)",
  ui_story_1020_10201101_93_dialog_content = "(네가 아직 이클립스에 털끝만큼의 가치라도 있음을 증명하고 싶다면,\n아이테르를 내게 데려와라.)",
  ui_story_1020_10201101_94_dialog_content = "(내게는 콜로서스를 가동할 충분한 힘이 있다.)",
  ui_story_1020_10201101_95_dialog_content = "<color=#e8d9bb>철컹──</color>",
  ui_story_1020_10201101_96_dialog_content = "......",
  ui_story_1020_10201101_97_dialog_content = "...겨, 결코 당신의 뜻을 거스르지 않을 것입니다!",
  ui_story_1020_10201101_98_dialog_content = "(......)",
  ui_story_1020_10201101_99_dialog_content = "(엔지니어가 자난성에 온 건 팬텀을 불러들이기 위해서였어...)",
  ui_story_1020_10201101_100_dialog_content = "(그리고 나랑 스카이워커를 데려가기 위해서기도 했고...)",
  ui_story_1020_10201101_101_dialog_content = "(마음에 드나?)",
  ui_story_1020_10201101_102_dialog_content = "(날... 지켜보고 있었어?)",
  ui_story_1020_10201101_103_dialog_content = "(언제나 그랬지.)",
  ui_story_1020_10201101_104_dialog_content = "(너의 시야는 내가 내려준 것이다. 내게 감사해야 마땅하지.\n내가 탑의 전장의 웅장하고 아름다운 모습을 네게 보여주었으니 말이다.)",
  ui_story_1020_10201101_105_dialog_content = "(탑의 전장... 그게 진짜 있었던 일이었다고...?!)",
  ui_story_1020_10201101_106_dialog_content = "(가치 있는 것은 오직 진실뿐이다.)",
  ui_story_1020_10201101_107_dialog_content = "(땅에 균열이 가 있던 그곳은 한때 나의 고향이었다. 하지만 그 전쟁이 나를 산산이 부수었지.)",
  ui_story_1020_10201101_108_dialog_content = "(나는 파편을 찾아, 나의 대좌를 온전하게 되돌리고, 심장을 다시 가동할 것이다.)",
  ui_story_1020_10201101_109_dialog_content = "(그 콜로서스들은 나의 대업을 위해 코어를 불살랐다.)",
  ui_story_1020_10201101_110_dialog_content = "(...스카이워커도 당신 제물로 쓸 생각이야?! 설마 이 세상을 파괴할 거야...?)",
  ui_story_1020_10201101_111_dialog_content = "(그럴 생각은 없다.)",
  ui_story_1020_10201101_112_dialog_content = "(너는 이해할 것이다. 너와 나는 같기 때문이다.)",
  ui_story_1020_10201101_113_dialog_content = "(......)",
  ui_story_1020_10201101_114_dialog_content = "(...스카이워커는 대체 어디 있는 건데?)",
  ui_story_1020_10201101_115_dialog_content = "(...바이스한테는 대체 무슨 일이 생긴 거냐고!)",
  ui_story_1020_10201101_116_dialog_content = "(......)",
  ui_story_1020_10201101_117_dialog_content = "(점점 더 어두워지고 있어...)",
  ui_story_1020_10201101_118_dialog_content = "(기억해라. 빛은 네 두 눈을 가리기만 할 뿐, 오직 어둠이야말로 진정한 밑바탕인 것을.)",
  ui_story_1020_10201101_119_dialog_content = "(어둠을 받아들이고, 어둠에 녹아들어, 어둠이 너의 힘이 되게 만들어라.)",
  ui_story_1020_10201101_120_dialog_content = "싫어!",
  ui_story_1020_10201101_121_dialog_content = "(어둠이 너의 힘이 되게 만들어라.)",
  ui_story_1020_10201101_122_dialog_content = "(나는 족쇄 따윈 차지 않아!)",
  ui_story_1020_10201101_123_dialog_content = "(계속 이러다간 정말로 어둠이 날 집어삼키고 말 거야...)",
  ui_story_1020_10201102_1_dialog_content = "<color=#e8d9bb>스르르륵──</color>",
  ui_story_1020_10201102_2_dialog_content = "(어둠 속에서 피아노 소리가 들려...)",
  ui_story_1020_10201102_3_dialog_content = "(여긴... 정말 밝네...)",
  ui_story_1020_10201102_4_dialog_content = "(일렁이는 이 빛들은 아마 호수면이겠지...)",
  ui_story_1020_10201102_5_dialog_content = "(이건... 북방의... 오로라인가?)",
  ui_story_1020_10201102_6_dialog_content = "(어? 저건 뭐지...?)",
  ui_story_1020_10201102_7_dialog_content = "PlayerName.",
  ui_story_1020_10201102_8_dialog_content = "스카이워커?! 진짜 너야? 스카이워커──!",
  ui_story_1020_10201102_9_dialog_content = "조금 전, 피아노 소리가 들린 것 같았습니다.\n당신의 목소리를 듣게 될 줄은 몰랐습니다, PlayerName.",
  ui_story_1020_10201102_10_dialog_content = "피아노 소리...? 나도 들었어! 나도 널 감응할 수 있을 줄 몰랐어!",
  ui_story_1020_10201102_11_dialog_content = "스카이워커, 너 지금 어디야?!",
  ui_story_1020_10201102_12_dialog_content = "......",
  ui_story_1020_10201102_13_dialog_content = "모르겠습니다.",
  ui_story_1020_10201102_14_dialog_content = "......",
  ui_story_1020_10201102_15_dialog_content = "그 녀석이 너한테 명령을 내린 거구나. 그렇지?",
  ui_story_1020_10201102_16_dialog_content = "......",
  ui_story_1020_10201102_17_dialog_content = "스카이워커호... 안 가면... 안 될까?",
  ui_story_1020_10201102_18_dialog_content = "......",
  ui_story_1020_10201102_19_dialog_content = "죄송합니다, PlayerName.",
  ui_story_1020_10201102_20_dialog_content = "아이테르 일족은 평생 자유를 꿈꿔 왔습니다...",
  ui_story_1020_10201102_21_dialog_content = "짧은 시간 동안의 데이터를 통해, 제가 당신을 만나기 전,\n아이테르와 콜로서스가 겪었던 일들을 볼 수 있었습니다...",
  ui_story_1020_10201102_22_dialog_content = "그리고 저는 아이테르가 몇 세대에 거쳐, 콜로서스와 함께 족쇄를 벗어 던지기 위해\n노력하는 모습을 보았습니다.",
  ui_story_1020_10201102_23_dialog_content = "그러나 이번에는...",
  ui_story_1020_10201102_24_dialog_content = "저는 실패한 모양입니다.",
  ui_story_1020_10201102_25_dialog_content = "스카이워커... 가지 마...",
  ui_story_1020_10201102_26_dialog_content = "우리가 같이 족쇄를 벗어버리자... 응?",
  ui_story_1020_10201102_27_dialog_content = "......",
  ui_story_1020_10201102_28_dialog_content = "이 순간, 저는 스카이워커호이자, 「패스파인더호」...",
  ui_story_1020_10201102_29_dialog_content = "또는 「론울프호」, 「익스플로러호」, 「서머너호」, 「오버테이커호」입니다...",
  ui_story_1020_10201102_30_dialog_content = "제가 할 수 있는 일은 선대 콜로서스들이 그러했듯,\n최선을 다해 그들의 조종사를 보호하는 것입니다.",
  ui_story_1020_10201102_31_dialog_content = "당신과 함께 지내며, 우리가 함께 하늘을 누비던 모든 순간이,\n제게는 생에 가장 아름다운 순간들이었습니다.",
  ui_story_1020_10201102_32_dialog_content = "제가 만약 이 족쇄를 벗어 던질 수 있다면, 우리는 분명 다시 만나게 될 겁니다.",
  ui_story_1020_10201102_33_dialog_content = "스카이워커...",
  ui_story_1020_10201102_34_dialog_content = "확신할 수 있습니다.\n아무리 많은 신호를 받게 되더라도, 만약 스카이워커호에 「마음」이 있다면...",
  ui_story_1020_10201102_35_dialog_content = "그 「마음」에 닿을 수 있는 것은 오직 PlayerName의 목소리뿐일 것이기 때문입니다.",
  ui_story_1020_10201102_36_dialog_content = "......",
  ui_story_1020_10201102_37_dialog_content = "스카이워커...",
  ui_story_1020_10201102_38_dialog_content = "스카이워커?!",
  ui_story_1020_10201102_39_dialog_content = "...PlayerName...",
  ui_story_1020_10201102_40_option_content = "(감응 연결!)",
  ui_story_1020_10201102_41_dialog_content = "......",
  ui_story_1020_10201102_42_option_content = "(감응 연결──)",
  ui_story_1020_10201102_43_dialog_content = "......",
  ui_story_1020_10201102_44_option_content = "(감응 연결──!)",
  ui_story_1020_10201102_45_dialog_content = "......",
  ui_story_1020_10201102_46_option_content = "(감응 연결──!)",
  ui_story_1020_10201102_47_dialog_content = "PlayerName!",
  ui_story_1020_10201102_48_dialog_content = "......",
  ui_story_1020_10201102_49_dialog_content = "감응이 안 돼...",
  ui_story_1020_10201102_50_dialog_content = "아무것도 안 느껴진다고──!",
  ui_story_1020_10201102_51_dialog_content = "PlayerName... 정신이 들어? 좀 괜찮아?",
  ui_story_1020_10201102_52_dialog_content = "악셀리아는 PlayerName의 상태에 가슴이 아픕니다.",
  ui_story_1020_10201102_53_dialog_content = "방금 전엔 계속 혼잣말로 중얼거려서 정말 놀랐다고요.\n다행히 숀이 피제로를 제압했더니, 당신도 눈을 떴어요!",
  ui_story_1020_10201102_54_dialog_content = "사실 우리 다 같이 녀석을 쓰러트렸어!",
  ui_story_1020_10201102_55_dialog_content = "......?",
  ui_story_1020_10201102_56_dialog_content = "녀석이 다크매터 덩어리로 변하더니 소멸하는 걸 봤어...",
  ui_story_1020_10201102_57_dialog_content = "그런 다크매터를 버틸 수 있는 건 숀뿐이었어요.",
  ui_story_1020_10201102_58_dialog_content = "(피제로가... 정말 모두의 손에 쓰러진 걸까?)",
  ui_story_1020_10201102_59_dialog_content = "(끝없는 어둠에 빠지기 전에 들렸던 피아노 소리,\n그리고 빛나던 호수면은 또 어떻게 된 거지...)",
  ui_story_1020_10201102_60_dialog_content = "대체 무슨 일이 있었던 건가요, PlayerName?\n조금 전에 강제로 피제로를 감응하더니, 이상한 소리까지 내고...",
  ui_story_1020_10201102_61_dialog_content = "스카이워커랑 감응했어...",
  ui_story_1020_10201102_62_dialog_content = "스카이워커호요?! 지금 어디 있죠?",
  ui_story_1020_10201102_63_dialog_content = "스카이워커는 날 지키려고 떠난 거야...",
  ui_story_1020_10201102_64_dialog_content = "......",
  ui_story_1020_10201102_65_dialog_content = "PlayerName, 스카이워커호 일은 잠시 후에 다시 해결하는 게 어떨까요?\n우선 저하고 같이 대원수님과 합류해요.",
  ui_story_1020_10201102_66_dialog_content = "당신 혼자 여기 있으면 너무 위험해요. 저 세 사람이 제때 와 주지 않았다면,\n당신과 전 이미 피제로의 손아귀에 떨어졌을 거예요.",
  ui_story_1020_10201102_67_dialog_content = "다들 고마워...",
  ui_story_1020_10201102_68_dialog_content = "자, 가죠. 위기를 넘기고 나면, 스카이워커호를 반드시 되찾을 수 있을 거예요!",
  ui_story_1020_10201102_69_dialog_content = "응...",
  ui_story_1020_10201102_70_dialog_content = "(엔지니어... 난 피제로의 의식을 통해서 봤어...)",
  ui_story_1020_10201102_71_dialog_content = "(단서를 찾아야 해...)",
  ui_story_1020_10201102_72_dialog_content = "PlayerName, 방금 전엔 정말 위험했어요.\n저 세 사람이 제때 와 주지 않았다면, 당신과 전 지금쯤...",
  ui_story_1020_10201102_73_dialog_content = "알겠어...",
  ui_story_1020_10201102_74_dialog_content = "PlayerName! 먼저 대원수님 쪽과 합류해요!",
  ui_story_1020_10201201_1_dialog_content = "부부!",
  ui_story_1020_10201201_2_dialog_content = "부르 말은... 이번 방어 모듈은 아마 괜찮을 거란 얘기지?",
  ui_story_1020_10201201_3_dialog_content = "아마도? 하하... 하하하하하하!",
  ui_story_1020_10201201_4_dialog_content = "으으읏── 손가락이랑 어깨가 벌써 뻐근해졌잖아...",
  ui_story_1020_10201201_5_dialog_content = "그래도 다들 도와준 덕분에 예상보다 빨리 마무리됐어...\n두뇌 싸움만으로도 이렇게 힘들 줄이야...",
  ui_story_1020_10201201_6_dialog_content = "이 고대의 기계는 역시 만만치 않아!",
  ui_story_1020_10201201_7_dialog_content = "<color=#e8d9bb>지지직──</color>",
  ui_story_1020_10201201_8_dialog_content = "뭐야? 새 프로그램도 여전히 오류가 난다고...?",
  ui_story_1020_10201201_9_dialog_content = "...그 엔지니어란 녀석이 아직도 어디선가 우리를 공격하고 있는 건가...?\n아니면 「가디언」의 모듈이 원래부터 문제가 있던 거야?!",
  ui_story_1020_10201201_10_dialog_content = "<size=45>부부부부──!</size>",
  ui_story_1020_10201201_11_dialog_content = "어디... 어디 보자...",
  ui_story_1020_10201201_12_dialog_content = "어? 율리시스는? 나 율리시스랑 말 좀 하게 해 줘!\n그동안 대체 이 기계에 무슨 짓을 한 거냐고...",
  ui_story_1020_10201201_13_dialog_content = "나 설마... 복잡한 계산을 처리해 줄 코어가 하나 더 필요한 건가...?",
  ui_story_1020_10201201_14_dialog_content = "부부?",
  ui_story_1020_10201201_15_dialog_content = "율리시스는 조금 전 뭔가 자극을 받았는지, 저쪽에서 눈을 감은 채 미동도 없습니다.",
  ui_story_1020_10201201_16_dialog_content = "라인하르트, 이 기계가 안정되고 나니까, 강화 병사들의 공격도 멈췄어...",
  ui_story_1020_10201201_17_dialog_content = "지금 당장 남은 강화 병사 문제를 해결해야 해. 그냥 두었다간 아까처럼 기습당할지도 몰라.",
  ui_story_1020_10201201_18_dialog_content = "같은 의견이에요. 게다가 이 강화 병사들은 어쨌거나 우리 병사들이니까요...\n어쩌면 블랙 엄브렐라 연구소에서 치료가 가능할 수도 있어요.",
  ui_story_1020_10201201_19_dialog_content = "...하지만 결국 이 강화 병사들을 조종하는 건 프로토타입으로 보인다.\n그러니 알골 박사 쪽에서 모듈 구축을 끝낼 때까지 기다리는 수밖에 없겠지.",
  ui_story_1020_10201201_20_dialog_content = "알골 박사, 우리가 지금 할 수 있는 일들은 뭐가 있지?",
  ui_story_1020_10201201_21_dialog_content = "강화 병사들을 제압하는 건 확실히 쉽지 않을 거야.",
  ui_story_1020_10201201_22_dialog_content = "이 케이블들은 아주 깊게 묻혀 있을지도 몰라.\n인력을 동원해서 제거하더라도 적어도 열흘에서 보름은 걸리겠지.",
  ui_story_1020_10201201_23_dialog_content = "그리고 도중에 다른 문제에 맞닥뜨릴 가능성도 있어...\n아무래도 「가디언」의 모듈을 역컴파일해 코어를 보완하는 방식은 안 될 것 같아...",
  ui_story_1020_10201201_24_dialog_content = "엔지니어나 「가디언」이랑은 완전히 별개인 방어 시스템을 하나 구축하고,\n자난성의 방어 시스템 허점을 보완하는 방법밖에 없어!",
  ui_story_1020_10201201_25_dialog_content = "그러니까 다른 기술은 일절 쓰지 않고, 일루미나가 자체적으로 연구개발한 기술만 써서\n방어 시스템을 구축하겠단 거야?",
  ui_story_1020_10201201_26_dialog_content = "맞아. 그렇지만 아직 코어의 연산 능력이 부족하니까,\n공격을 막으면서 새 시스템 구축까지 하려면... 더 어렵긴 하겠지.",
  ui_story_1020_10201201_27_dialog_content = "데이터 처리를 도와 줄 계산 코어가 더 있었으면 좋겠는데...",
  ui_story_1020_10201201_28_dialog_content = "알골 박사, 자난성의 다른 컴퓨터 장치까지 사용한다면 도움이 될 것 같나?",
  ui_story_1020_10201201_29_dialog_content = "지금 휴면 상태인 컴퓨터는 몇 대 없어. 그 정도로는 별 도움이 안 될 거야.",
  ui_story_1020_10201201_30_dialog_content = "휴면 상태인 컴퓨터가 아니라, 자난성에 있는 컴퓨터 전부를 말하는 거다!",
  ui_story_1020_10201201_31_dialog_content = "전부? 모든 컴퓨터의 코어의 연산 능력이라면... 당연히 꽤 도움이 되겠지.",
  ui_story_1020_10201201_32_dialog_content = "하지만 그럼 모든 공학 기기가 가동을 정지할 거야.\n성문도 열리고, 생명 유지 시스템도 다운될 텐데...",
  ui_story_1020_10201201_33_dialog_content = "이 거대한 자난성에서 그런 중요 설비를 단 1분이라도 사용하지 않는 상황이 가능하긴 할까?",
  ui_story_1020_10201201_34_dialog_content = "......",
  ui_story_1020_10201201_35_dialog_content = "사실 새 방어 시스템을 구축한다 하더라도 검증이 필요해.\n복잡한 연산을 처리할 수 있는 코어가 아니라면, 새로 구축한 시스템 역시 금방 붕괴할 거야.",
  ui_story_1020_10201201_36_dialog_content = "내가 지금 하는 일들도, 기껏해야 엔지니어의 행동을 추측해서 녀석과 도박을 하는 것밖에 안 돼.",
  ui_story_1020_10201201_37_dialog_content = "부! 부! 부!",
  ui_story_1020_10201201_38_dialog_content = "그건 안 돼.",
  ui_story_1020_10201201_39_dialog_content = "부부!",
  ui_story_1020_10201201_40_dialog_content = "너도 프로토타입의 일부잖아.",
  ui_story_1020_10201201_41_dialog_content = "부! 부! 부!",
  ui_story_1020_10201201_42_dialog_content = "부르가 방법을 생각해 낸 건가?",
  ui_story_1020_10201201_43_dialog_content = "자기가 자난성 방어 시스템의 코어가 되고 싶대.",
  ui_story_1020_10201201_44_dialog_content = "부르가...? 그게 가능하긴 해?",
  ui_story_1020_10201201_45_dialog_content = "가능해. 부르는 원래 프로토타입의 일부였으니까. 뭐, 나한테는 귀찮게 구는 조수일 뿐이지만.",
  ui_story_1020_10201201_46_dialog_content = "부부!",
  ui_story_1020_10201201_47_dialog_content = "너무해! 부르가 알골 박사를 그렇게나 많이 도와줬는데!",
  ui_story_1020_10201201_48_dialog_content = "부우!",
  ui_story_1020_10201201_49_dialog_content = "띠릭──",
  ui_story_1020_10201201_50_dialog_content = "알골, 1호의 <color=#FFB400>메인터넌스 룸</color>을 개방해 주세요.",
  ui_story_1020_10201201_51_dialog_content = "1호의 <color=#FFB400>코어</color>로 자난성을 지키는 것입니다.",
  ui_story_1020_10201201_52_dialog_content = "뭐...?",
  ui_story_1020_10201201_53_dialog_content = "1호는 이제 인공지능 부분을 포기하고, 데이터 공격 처리를 담당하는 기계가 되고 싶습니다.",
  ui_story_1020_10201201_54_dialog_content = "난 네가 지혜를 포기하고 기계가 되겠다는 소리나 들으려고 지금까지 너한테\n그 많은 프로그램을 깔아 준 게 아니야, 1호.",
  ui_story_1020_10201201_55_dialog_content = "알고 있습니다. 알골은 1호가 오로리안 간의 복잡한 대화 정보를 처리하는 방법을 배우고,\n1호가 알골의 친구가 되기를 바랐습니다.",
  ui_story_1020_10201201_56_dialog_content = "하지만 알골은 1호가 필요합니다. 1호의 코어로 자난성을 지켜 주세요.",
  ui_story_1020_10201201_57_dialog_content = "안 돼.",
  ui_story_1020_10201201_58_dialog_content = "부디 1호의 코어로 자난성을 지켜 주세요, 알골.",
  ui_story_1020_10201201_59_dialog_content = "안 된다고 했잖아!",
  ui_story_1020_10201201_60_dialog_content = "띠릭── 부디 1호의 코어로 자난성을 지켜 주세요, 알골.",
  ui_story_1020_10201201_61_dialog_content = "안 된다면 안 되는 줄 알아!",
  ui_story_1020_10201201_62_dialog_content = "안 된다면 안 되는 줄 알아!",
  ui_story_1020_10201201_63_dialog_content = "......",
  ui_story_1020_10201201_64_dialog_content = "너... 그런 식으로 넘어가려 드는 건 언제 배웠어...?",
  ui_story_1020_10201201_65_dialog_content = "「띠릭, 띠릭, 띠리릭.」, 1호는 한참을 생각한 후에야 알았습니다.\n사실 그때 알골은 아무 말도 하지 않았다는 것을 말입니다.",
  ui_story_1020_10201201_66_dialog_content = "......",
  ui_story_1020_10201201_67_dialog_content = "그런 말을 하면 내가 널 놔주기 더 힘들어져, 알아?",
  ui_story_1020_10201201_68_dialog_content = "1호도 알고 있습니다. 하지만 이것은 1호의 부탁입니다.\n1호의 코어로 자난성을 지켜 주세요, 알골.",
  ui_story_1020_10201201_69_dialog_content = "자난성을 지키기 위해서 네가 어떤 일들을 마주하게 될지 알고 있어?",
  ui_story_1020_10201201_70_dialog_content = "여긴 복잡한 케이블만 있는 게 아니야. 사악한 데이터들도 네 생각에 침투할 거라고...",
  ui_story_1020_10201201_71_dialog_content = "그 데이터들은 네 사고 능력을 봉쇄하고, 심지어는 네가 암귀처럼\n일루미나를 공격하게 만들 수도 있어!",
  ui_story_1020_10201201_72_dialog_content = "이건 단순한 마이그레이션이 아냐. 네 창조성과 적응성을 모두 버리고,\n2진법 명령을 실행하는 것밖에 못 하는 수많은 논리 회로 중 하나가 되는 거라고!",
  ui_story_1020_10201201_73_dialog_content = "1호는 허튼 생각은 하지 않습니다.\n알골은 전에 1호에게 생각은 오로리안의 특기라고 알려 주었기 때문입니다.",
  ui_story_1020_10201201_74_dialog_content = "알골처럼 지혜로운 선생님이 있었던 덕분에, 1호는 생각을 포기하고\n자난성을 지키는 일에 집중할 수 있습니다.",
  ui_story_1020_10201201_75_dialog_content = "선생님은 무슨... 나한테는 커피 한 잔도 타 주기 싫어했으면서...",
  ui_story_1020_10201201_76_dialog_content = "1호는 알고 있습니다. 알골이 바라는 것은 1호가 단순한 집사 로봇이 아니라,\n서로 장난도 치고 다투기도 하는 동료였습니다.",
  ui_story_1020_10201201_77_dialog_content = "1호는 조건이 있습니다. 나중에 1호가 이곳에 살게 된다면,\n이곳도 알골의 사무실처럼 꾸미고, 녹색 식물들을 놓아 주세요.",
  ui_story_1020_10201201_78_dialog_content = "그리고 2호, 3호가 생긴다면, 그들에게는 움직이기 편한 케이스를 설계해 주세요.\n1호 같은 케이스 대신 말입니다...",
  ui_story_1020_10201201_79_dialog_content = "알골은 자주 1호가 우체통처럼 생겨 입에 편지를 넣어 주고 싶다고 했습니다.",
  ui_story_1020_10201201_80_dialog_content = "......",
  ui_story_1020_10201201_81_dialog_content = "참, 그리고 알골에게 알려 줄 것이 한 가지 더 남아 있습니다.",
  ui_story_1020_10201201_82_dialog_content = "1호와 PlayerName 사이의 의식 소통이 진행되는 과정에서,\n1호는 독단적으로 알골이 모르는 일을 저질렀습니다.",
  ui_story_1020_10201201_83_dialog_content = "......?",
  ui_story_1020_10201201_84_dialog_content = "하지만 그 소통 덕분에 1호는 믿을 수 있었습니다.\n1호는 모든 의식을 PlayerName에게 맡길 수 있습니다.",
  ui_story_1020_10201201_85_dialog_content = "만약 알골에게 친구가 필요하다면, 1호의 추천은 PlayerName입니다.",
  ui_story_1020_10201201_86_dialog_content = "......",
  ui_story_1020_10201201_87_dialog_content = "그럼 안녕히, 알골.",
  ui_story_1020_10201201_88_dialog_content = "1호는 알골이 만들어 준 새 표정이 정말 마음에 듭니다.",
  ui_story_1020_10201201_89_dialog_content = "띠릭── 띠릭── 띠──리──릭──",
  ui_story_1020_10201201_90_dialog_content = "<color=#e8d9bb>철컹──</color>",
  ui_story_1020_10201201_91_dialog_content = "부우...",
  ui_story_1020_10201201_92_dialog_content = "띠릭, 띠릭, 띠리릭.",
  ui_story_1020_10201201_93_dialog_content = "......",
  ui_story_1020_10201201_94_dialog_content = "대원수, 우리 진짜 다른 방법은 없는 거야?",
  ui_story_1020_10201201_95_dialog_content = "......",
  ui_story_1020_10201201_96_dialog_content = "지금으로선 이게 유일한 방법일지도 몰라. 엔지니어가 나타났을 때부터 난 생각했었어.",
  ui_story_1020_10201201_97_dialog_content = "알골 박사, 저들이 당신에게 친구였다는 것은 나도 알고 있다.",
  ui_story_1020_10201201_98_dialog_content = "단 하나밖에 없는 친구야.",
  ui_story_1020_10201201_99_dialog_content = "그렇지만... 이 세상에 어느 누가 자기 친구 목숨을 이렇게 손에 쥐고 있는데? 하하하...!",
  ui_story_1020_10201201_100_dialog_content = "잘난 척하는 망할 우체통 같으니라고...",
  ui_story_1020_10201201_101_dialog_content = "재수없어...!",
  ui_story_1020_10201201_102_dialog_content = "알골 박사, 「중요 시설 설비를 단 1분이라도 사용하지 않는 상황」이라는 그 전제,\n코어가 있어도 마찬가지인가?",
  ui_story_1020_10201201_103_dialog_content = "......?",
  ui_story_1020_10201201_104_dialog_content = "자난성의 모든 컴퓨터 코어의 연산 능력을 집중해서 네가 코어 교체를 완료할 수 있게 돕겠다.",
  ui_story_1020_10201201_105_dialog_content = "부! 부! 부!",
  ui_story_1020_10201201_106_dialog_content = "1분 가지곤 못 해.",
  ui_story_1020_10201201_107_dialog_content = "그럼 10분으로 하자고! 자난성의 컴퓨터를 모두 동원하고,\n부족한 설비는 인력으로 보충하겠다. 이러면 도움이 되겠나?",
  ui_story_1020_10201201_108_dialog_content = "그거... 진심이야?",
  ui_story_1020_10201201_109_dialog_content = "진심이다.",
  ui_story_1020_10201201_110_dialog_content = "알골 박사, 일루미나인들은 오로리안 개조에 의존해 살아남은 게 아냐.",
  ui_story_1020_10201201_111_dialog_content = "그리고 고대 기계에 의존해 살아남은 것도 아닙니다.",
  ui_story_1020_10201201_112_dialog_content = "그렇다. 비록 율리시스는 일루미나가 「가디언」에 600여 년을 의존해 왔다고 여기지만...",
  ui_story_1020_10201201_113_dialog_content = "나는 일루미나의 철옹성을 세운 것은 군인들이라고 늘 믿고 있다.",
  ui_story_1020_10201201_114_dialog_content = "고작 이 10분조차 버티지 못한다면, 아스트라 대륙에 일루미나가 설 자리는 영원히 없을 거다.\n그러니 설령 모험이라 해도 시도는 해 봐야겠지!",
  ui_story_1020_10201201_115_dialog_content = "알골 박사, 원한다면 내 목숨도 함께 그 손에 쥐어도 좋다.\n나 역시 널 믿어주는 친구가 되길 원하니까.",
  ui_story_1020_10201201_116_dialog_content = "......",
  ui_story_1020_10201201_117_dialog_content = "나도 있어.",
  ui_story_1020_10201201_118_dialog_content = "나도 있다구!",
  ui_story_1020_10201201_119_dialog_content = "...자신을 믿어주는 「친구」들과 함께, 혼자서는 해낼 수 없는 일을 하는 건가.",
  ui_story_1020_10201201_120_dialog_content = "학교 다닐 때나 했던 장난 같은걸, 하하.",
  ui_story_1020_10201201_121_dialog_content = "그래도 해 보고 싶어.",
  ui_story_1020_10201201_122_dialog_content = "이예~ 친구들이랑 같이 게임하는 게 제일 좋아!",
  ui_story_1020_10201201_123_dialog_content = "그럼, 시작하지! 히이로, 지금 즉시 전 지역의 전시 긴급 채널에 연결하도록.\n명령을 하달하겠다.",
  ui_story_1020_10201201_124_dialog_content = "예!",
  ui_story_1020_10201201_125_dialog_content = "<color=#e8d9bb>삑삑──</color>",
  ui_story_1020_10201201_126_dialog_content = "대원수님.",
  ui_story_1020_10201201_127_dialog_content = "아, 이 채널은 영원히 쓸 일이 없을 줄 알았는데 말이야.",
  ui_story_1020_10201201_128_dialog_content = "지금 즉시 자난성의 모든 컴퓨터를 긴급 동원하고, 부족한 설비는 인력으로 보충한다.\n본 조치는 10분간 실시하겠다.",
  ui_story_1020_10201201_129_dialog_content = "이와 동시에, 자난성의 방어는 우리 각자가 책임져야 한다.",
  ui_story_1020_10201201_130_dialog_content = "명령만 하라고, 대원수!",
  ui_story_1020_10201201_131_dialog_content = "지면과 가까운 격리 구역, 수비층, 완충층은 직접적으로 암귀에게 노출되겠지.\n바튼, 이 구역들은 네가 맡아라.",
  ui_story_1020_10201201_132_dialog_content = "수신 양호!",
  ui_story_1020_10201201_133_dialog_content = "시로나, 신속히 복귀해 자난성을 지원하고, 외부에서 암귀 소탕을 실시하라.\n지금쯤 작업반은 주민들의 이송 작업을 마쳤을 것이다.",
  ui_story_1020_10201201_134_dialog_content = "알겠습니다.",
  ui_story_1020_10201201_135_dialog_content = "히이로, 농업 구역, 광산 구역, 공업 구역, 창고 관리 구역은 네게 맡기겠다.",
  ui_story_1020_10201201_136_dialog_content = "일부 군인과 주민들이 아직 기계를 작동하느라 이송되지 않았을 것이다.\n언제든지 상층과 하층 구역을 지원할 수 있도록 준비해라.",
  ui_story_1020_10201201_137_dialog_content = "네, 문제없습니다.",
  ui_story_1020_10201201_138_dialog_content = "난?",
  ui_story_1020_10201201_139_dialog_content = "연구동에는 실험용 암귀가 많다. 레이스, 부하들에게 암귀가 있는 모든 창고를 찾게 하고,\n무슨 일이 있어도 암귀가 상층으로 오는 것을 막아라.",
  ui_story_1020_10201201_140_dialog_content = "알겠어!",
  ui_story_1020_10201201_141_dialog_content = "부부! 부부! 부부!",
  ui_story_1020_10201201_142_dialog_content = "「가디언」 시스템을 우회해서 새로운 우리를 만들고,\n계속해서 이 지하성에 몸을 가두겠다는 것입니까...",
  ui_story_1020_10201201_143_dialog_content = "당신들은 모두 어둠에 익숙한 사람들로군요...",
  ui_story_1020_10201201_144_dialog_content = "...율리시스의 몸이...?! 어째서...",
  ui_story_1020_10201201_145_dialog_content = "제 실수입니다... 강화 병사들을 처리하는 데 집중하느라,\n율리시스가 스스로 수술대에 오르는 것을 발견하지 못했습니다.",
  ui_story_1020_10201201_146_dialog_content = "이렇게 짧은 시간 만에... 신체 개조를 완료했단 말입니까?",
  ui_story_1020_10201201_147_dialog_content = "...개조는 방금 한 게 아니라, 이미 오래전에 해 뒀을 가능성이 높다.",
  ui_story_1020_10201201_148_dialog_content = "방어로는 끝이 나지 않습니다. 오직 정면으로 맞서는 것만이 답입니다...\n이 육체가 있다면... 더는 가디언의 코어도 필요하지 않습니다!",
  ui_story_1020_10201201_149_dialog_content = "율리시스, 조금이라도 경거망동한다면 당신의 목을 베겠습니다!",
  ui_story_1020_10201201_150_dialog_content = "잠깐! 다들 우선 물러나!",
  ui_story_1020_10201201_151_dialog_content = "말했을 텐데요, 전 지금까지 단 한 번도 「어둠의 밑바닥의 공포」를\n두려워한 적이 없었습니다...",
  ui_story_1020_10201201_152_dialog_content = "저들이 모두 실패했다면...",
  ui_story_1020_10201201_153_dialog_content = "제가 직접 나서겠습니다!",
  ui_story_1020_10201201_154_dialog_content = "<color=#e8d9bb>지지직──</color>",
  ui_story_1020_10201201_155_dialog_content = "...! 데이터 과부하?! 설마 율리시스 때문인가?",
  ui_story_1020_10201201_156_dialog_content = "......",
  ui_story_1020_10201201_157_dialog_content = "대원수, 계속 임무를 진행할 건가?",
  ui_story_1020_10201201_158_dialog_content = "「부르, 명령, 점프!」",
  ui_story_1020_10201201_159_dialog_content = "부부부부!",
  ui_story_1020_10201201_160_dialog_content = "전원, 본래의 계획대로 진행한다. 반드시 알골 박사가 코어 교체에 성공할 수 있도록 돕는다!\n이곳은 내게 맡겨라!",
  ui_story_1020_10201201_161_dialog_content = "예!",
  ui_story_1020_10201201_162_dialog_content = "알겠습니다!",
  ui_story_1020_10201201_163_dialog_content = "알겠다고, 대원수!",
  ui_story_1020_10201201_164_dialog_content = "<color=#e8d9bb>쿠르르릉──!</color>",
  ui_story_1020_10201201_165_dialog_content = "모두 조심해! 강화 병사 창고의 문이 또 열렸어!",
  ui_story_1020_10201201_166_dialog_content = "율리시스를 향해 달려오고 있는 건가...",
  ui_story_1020_10201201_167_dialog_content = "이 육체를 손에 넣은 이상, 더는 코어를 지킬 필요는 없습니다!",
  ui_story_1020_10201201_168_dialog_content = "멍청하긴! 육체만 강화하면 무적인 줄 아는 거야...?!",
  ui_story_1020_10201201_169_dialog_content = "그 정도 개조는 엔지니어가 마음만 먹으면 케이블만 하나 뻗어서 당신을 조종할 수도 있어!",
  ui_story_1020_10201201_170_dialog_content = "창고 안은 온통 케이블이라고...",
  ui_story_1020_10201201_171_dialog_content = "라인하르트! 남은 사람들한테도 이곳에서 떠나라고 해!\n이 케이블들은 누구든 조종해 버릴지도 몰라!",
  ui_story_1020_10201201_172_dialog_content = "여기 남는 건 나 하나면 충분해! 난 새로 구축한 방어 시스템의 안전을 확보해야 해!",
  ui_story_1020_10201201_173_dialog_content = "모두 알골 박사의 말대로 해라!",
  ui_story_1020_10201201_174_dialog_content = "넌 대체 날 뭐로 보는 거야? 내가 너희만 놈들을 상대하게 남겨 놓고 갈 것 같아?",
  ui_story_1020_10201201_175_dialog_content = "저도 엄호할게요, 대원수님!",
  ui_story_1020_10201201_176_dialog_content = "나도 있어!",
  ui_story_1020_10201201_177_dialog_content = "그럼 강화 병사는 당신들한테 맡길게! 율리시스를 잘 보고 있어!",
  ui_story_1020_10201201_178_dialog_content = "부르, 단자를 찾고 강화 병사들과 프로토타입의 연결을 끊어! 그리고 코어를 교체하는 거야!",
  ui_story_1020_10201201_179_dialog_content = "부부부부!",
  ui_story_1020_10201301_1_dialog_content = "부부!",
  ui_story_1020_10201301_2_dialog_content = "성공했어... 성공했다고! 아하하하하하!",
  ui_story_1020_10201301_3_dialog_content = "1호! 1호! 정말 대단했어, 1호!",
  ui_story_1020_10201301_4_dialog_content = "부우!",
  ui_story_1020_10201301_5_dialog_content = "대원수님, 조금 전에 거대한 진동음이 들렸어요. 무사하신...",
  ui_story_1020_10201301_6_dialog_content = "쉿... 다들 들려?",
  ui_story_1020_10201301_7_dialog_content = "『1011X.』",
  ui_story_1020_10201301_8_dialog_content = "『01X11.』",
  ui_story_1020_10201301_9_dialog_content = "『X1010.』",
  ui_story_1020_10201301_10_dialog_content = "율리시스 교수가... 왜 저러는 거죠?",
  ui_story_1020_10201301_11_dialog_content = "......",
  ui_story_1020_10201301_12_dialog_content = "『0111X.』",
  ui_story_1020_10201301_13_dialog_content = "『0X111.』",
  ui_story_1020_10201301_14_dialog_content = "...이클립스어?",
  ui_story_1020_10201301_15_dialog_content = "???",
  ui_story_1020_10201301_16_dialog_content = "율리시스가 이클립스어를 구사한다는 건 이상한 일이지만, 틀림없다.\n저건 암귀들이 서로 소통할 때 사용하는 언어다.",
  ui_story_1020_10201301_17_dialog_content = "...조금 전에 피제로에게 감응 능력을 사용했을 때,\nPlayerName도 저런 혼잣말을 했었어요...",
  ui_story_1020_10201301_18_dialog_content = "1011X.",
  ui_story_1020_10201301_19_dialog_content = "이렇게...요?",
  ui_story_1020_10201301_20_dialog_content = "잠깐만, 방금 뭐라고 했어? 천천히 말해 봐.",
  ui_story_1020_10201301_21_dialog_content = "1...... 0...... 1...... 1...... X......",
  ui_story_1020_10201301_22_dialog_content = "부부! 부부! 부부!",
  ui_story_1020_10201301_23_dialog_content = "PlayerName, 당신 이클립스어를 알아듣는 건가요?!",
  ui_story_1020_10201301_24_dialog_content = "이렇게 말하면 되게 이상할 것 같지만...\n알아듣는 건 아니고, 따라서 소리 내 읽긴 쉬운 것 같아.",
  ui_story_1020_10201301_25_dialog_content = "어쩐지... 네가 부르를 감응했을 때 기록해 뒀던 데이터들과 비슷한 부분이 있었어!",
  ui_story_1020_10201301_26_dialog_content = "이클립스어와 프로토타입의 언어 사이에 관계가 있었던 거야...",
  ui_story_1020_10201301_27_dialog_content = "대부분의 암귀는 평소에 앞뒤 생각 없이 지내다가, 공격을 할 때만 통일된 명령을 따라.",
  ui_story_1020_10201301_28_dialog_content = "명령... 언어... 왠지 모든 단서가 하나로 연결된 것 같아!",
  ui_story_1020_10201301_29_dialog_content = "『2355X11874......』",
  ui_story_1020_10201301_30_dialog_content = "『32456901X14361......』",
  ui_story_1020_10201301_31_dialog_content = "(만약 율리시스가 엔지니어랑 교류하고 있는 거라면...)",
  ui_story_1020_10201301_32_dialog_content = "어쩌면 감응 능력을 써 볼 수 있을 것 같아요...",
  ui_story_1020_10201301_33_dialog_content = "PlayerName, 지금 뭐 하려는 거야?\n율리시스는 수많은 사람을 죽였어! 죽어 마땅한 녀석이라고!",
  ui_story_1020_10201301_34_dialog_content = "하지만 이게 스카이워커호 바이스의 행방을 알아낼 수 있는 유일한 방법일지도 몰라요...",
  ui_story_1020_10201301_35_dialog_content = "PlayerName!",
  ui_story_1020_10201301_36_dialog_content = "더는 감응 능력을 사용해선 안 돼요... 당신의 몸은 이미 한계예요.",
  ui_story_1020_10201301_37_dialog_content = "정말 이게 내 한계인 걸까...?",
  ui_story_1020_10201301_38_dialog_content = "하지만 내가 할 수 있는 게 이것뿐이라면...",
  ui_story_1020_10201301_39_option_content = "(감응 연결──)",
  ui_story_1020_10201301_40_dialog_content = "(고리를 차거나, 나의 연료가 되어라.)",
  ui_story_1020_10201301_41_dialog_content = "전 당신에게 굴복하지 않습니다. 이미 수없이 말하지 않았습니까...",
  ui_story_1020_10201301_42_dialog_content = "지금 제 모습을 보십시오. 전 이미 오래전에 죽음의 공포를 뛰어넘었습니다...",
  ui_story_1020_10201301_43_dialog_content = "죽은 자를 연구하는 것부터 시작해, 산 자를 죽은 자로 만드는 것까지...\n전 이미 두렵지 않습니다.",
  ui_story_1020_10201301_44_dialog_content = "(넌 보통 사람들의 담력과 식견을 뛰어넘었다, 율리시스.)",
  ui_story_1020_10201301_45_dialog_content = "(과거의 나처럼 말이지.)",
  ui_story_1020_10201301_46_dialog_content = "하하... 하하하하... 어디 닮기만 했겠습니까?",
  ui_story_1020_10201301_47_dialog_content = "그때는 라빌까지 무너지고 말았습니다...\n그 거대한 실험실 안에서, 오직 저만이 과학의 길을 걸었던 우리의 초심을 기억하고...",
  ui_story_1020_10201301_48_dialog_content = "암귀가 강한 이유를 밝히고, 오로리안이 생존할 수 있는 방법을 모색했습니다.",
  ui_story_1020_10201301_49_dialog_content = "자료를 열람하던 저는 당신의 이름을 발견했습니다...\n당신은 제가 먼지투성이의 역사서를 뒤지며 몰래 「가디언」에 대해 연구하게 했지요.",
  ui_story_1020_10201301_50_dialog_content = "전 그때부터 보게 된 것입니다. 기계적으로 암귀를 생산하는 공장과,\n콜로서스로 아스트라 대륙에 폭격을 퍼붓는 아이테르...",
  ui_story_1020_10201301_51_dialog_content = "그리고 지하성에 몸을 숨긴 오로리안들까지 말입니다.",
  ui_story_1020_10201301_52_dialog_content = "푸른 행성이었던 아이올리아는 새빨갛게 물들었고,\n또 순식간에 잿빛이 감도는 죽음의 별로 변해 있었지요...",
  ui_story_1020_10201301_53_dialog_content = "오로라가 하늘을 뒤덮었고, 행성의 궤적은 틀어져 버리고 말았습니다...",
  ui_story_1020_10201301_54_dialog_content = "과학, 전쟁, 증오, 생명...",
  ui_story_1020_10201301_55_dialog_content = "제게 세상의 잔혹함을 보여 준 건, 그리고 공포를 안고 굳게 살아가게 만든 건 당신이었습니다.",
  ui_story_1020_10201301_56_dialog_content = "(내가 뭐라고 했었지?)",
  ui_story_1020_10201301_57_dialog_content = "「암귀에게 승리하려면, 반드시 더 대담해져야 한다!」",
  ui_story_1020_10201301_58_dialog_content = "「더 대담해져야 한다!」",
  ui_story_1020_10201301_59_dialog_content = "그 소리를 듣고 있으면, 제가 과거에 있는 것인지, 아니면 미래에 있는 것인지,\n그리고 제가 누구인 건지 알 수 없어질 때가 많았습니다.",
  ui_story_1020_10201301_60_dialog_content = "심지어는 왜 하필 저였냐는 생각까지 들었지요.",
  ui_story_1020_10201301_61_dialog_content = "하지만 그 공포를 넘어서고 났을 때, 전 깨달았습니다.\n이 율리시스, 이제 아무것도 두렵지 않았다는 것을 말입니다.",
  ui_story_1020_10201301_62_dialog_content = "마주하게 될 것이 이 잔혹한 세상이든, 당신이든 두렵지 않았습니다.",
  ui_story_1020_10201301_63_dialog_content = "(너는 공포를 넘어섰지만, 새로운 공포를 가지게 되었다.)",
  ui_story_1020_10201301_64_dialog_content = "새로운 공포라니, 뭘 말하는 겁니까?",
  ui_story_1020_10201301_65_dialog_content = "(보겠나?)",
  ui_story_1020_10201301_66_dialog_content = "......",
  ui_story_1020_10201301_67_dialog_content = "드니에르.",
  ui_story_1020_10201301_68_dialog_content = "선생님.",
  ui_story_1020_10201301_69_dialog_content = "당신이 연구회에서 제기한 다크매터에 관한 가설은 연구 가치가 상당히 높더군요.",
  ui_story_1020_10201301_70_dialog_content = "감사합니다. 하지만 현재로서는 일루미나가 제 연구를 지원해 줄 방법이 없다고 생각해요.",
  ui_story_1020_10201301_71_dialog_content = "전쟁이 끝나면 일부 연구 물자가 회수될 것입니다.\n그때가 되면 자난성 주변에 당신 실험실을 세우고, 하고 싶은 실험을 할 수 있을 겁니다.",
  ui_story_1020_10201301_72_dialog_content = "...감사합니다, 선생님.",
  ui_story_1020_10201301_73_dialog_content = "드니에르, 진행 상황은 어떻습니까?",
  ui_story_1020_10201301_74_dialog_content = "이게 제가 재배 중인 씨앗이에요, 선생님.",
  ui_story_1020_10201301_75_dialog_content = "나쁘지 않군요... 정말 아름답네요...",
  ui_story_1020_10201301_76_dialog_content = "우리 병사들에게 씨앗을 이식할 수 있다면...",
  ui_story_1020_10201301_77_dialog_content = "선생님! 이건 그냥 연구일 뿐이에요.\n그랬다간 씨앗 속의 다크매터가 오로리안을 삼키고 말 거예요.",
  ui_story_1020_10201301_78_dialog_content = "그저 오로리안을 집어삼킬 뿐이지 않습니까...\n당신은 암귀가 어떻게 이 세상을 집어삼켰는지 알고 있습니까?",
  ui_story_1020_10201301_79_dialog_content = "......?",
  ui_story_1020_10201301_80_dialog_content = "당신의 연구는 무척 훌륭합니다, 드니에르.\n시기는 이미 무르익었으니, 오로리안이 마침내 변화를 맞이할 수 있겠군요.",
  ui_story_1020_10201301_81_dialog_content = "...뭘 하시려는 건가요?",
  ui_story_1020_10201301_82_dialog_content = "씨앗을 제게 주세요.",
  ui_story_1020_10201301_83_dialog_content = "......",
  ui_story_1020_10201301_84_dialog_content = "달라고 했습니다.",
  ui_story_1020_10201301_85_dialog_content = "거절하겠어요.",
  ui_story_1020_10201301_86_dialog_content = "일루미나를 적으로 돌리고 싶은 겁니까?",
  ui_story_1020_10201301_87_dialog_content = "아니에요... 선생님.",
  ui_story_1020_10201301_88_dialog_content = "잊지 마세요. 제가 없으면, 당신도 없습니다.",
  ui_story_1020_10201301_89_dialog_content = "......",
  ui_story_1020_10201301_90_dialog_content = "(기억이 나는군. 드니에르라는 일루미나인이었지. 넌 줄곧 그 사람이 되고 싶었고 말이야.)",
  ui_story_1020_10201301_91_dialog_content = "...그렇지 않습니다.",
  ui_story_1020_10201301_92_dialog_content = "(네 자랑스러운 최고의 걸작, 「인공 태양 프로젝트」라고 했던가.)",
  ui_story_1020_10201301_93_dialog_content = "(나는 이미 네 재능을 인정했다, 율리시스. 너에 대한 인정이 담긴 이 고리를 차라.)",
  ui_story_1020_10201301_94_dialog_content = "당신의 인정 따위는 필요 없습니다! 전 영원히 복종하지 않을 겁니다!",
  ui_story_1020_10201301_95_dialog_content = "(그렇게 많은 사람을 해치고, 잔인한 실험을 했던 사람이...\n엔지니어에겐 절대 굴복하지 않고 있어...)",
  ui_story_1020_10201301_96_dialog_content = "(대체 이유가 뭐지?)",
  ui_story_1020_10201301_97_dialog_content = "(의외인가? 아이테르?)",
  ui_story_1020_10201301_98_dialog_content = "(역시 내가 감응 능력을 쓰면... 당신도 날 볼 수 있었구나...)",
  ui_story_1020_10201301_99_dialog_content = "(어떻게 그게 가능한 거지...?)",
  ui_story_1020_10201301_100_dialog_content = "(콜로서스가 나를 「포착」했기 때문에, 나 역시 너를 「포착」한 것이다.)",
  ui_story_1020_10201301_101_dialog_content = "(자아의식의 「자아」는 상상적 레퍼런스의 일종일 뿐이다.\n지혜로워 보이는 무언가도 사실은 다른 지혜의 매개체에 불과할 수도 있는 법이지.)",
  ui_story_1020_10201301_102_dialog_content = "(이는 후자가 더 지혜롭기 때문이다.)",
  ui_story_1020_10201301_103_dialog_content = "(고대의 기계는 나의 매채체였고, 저 팬텀도 마찬가지였다. 그리고 이자도 곧 그렇게 되겠지.)",
  ui_story_1020_10201301_104_dialog_content = "...율리시스! 고리를 차면 안 돼!",
  ui_story_1020_10201301_105_dialog_content = "(그에게는 네 목소리가 들리지 않는다.)",
  ui_story_1020_10201301_106_dialog_content = "......",
  ui_story_1020_10201301_107_dialog_content = "(난 반드시 스카이워커호랑 바이스를 찾아낼 거야...!)",
  ui_story_1020_10201301_108_dialog_content = "(좋다.)",
  ui_story_1020_10201301_109_dialog_content = "(일전에 어떤 빛 하나가 우리를 잠시 갈라놓았었지.\n그곳이라면 내가 「포착」하고 싶은 것이 존재할지도 모르겠군.)",
  ui_story_1020_10201301_110_dialog_content = "투명하게 빛나는 호수...",
  ui_story_1020_10201301_111_dialog_content = "제 말 들었습니까? 전 고리를 차지 않을 겁니다.\n그리고 이렇게 순순히 죽을 생각도 없습니다...",
  ui_story_1020_10201301_112_dialog_content = "(네 모습을 봐라. 발악해 봐야 아무런 의미도 없다.)",
  ui_story_1020_10201301_113_dialog_content = "제가 어떤 모습이 되든 상관없습니다.\n하지만 전 저들에게 오로리안이 어떻게 살아남아야 하는지 알려 줄 것입니다.",
  ui_story_1020_10201301_114_dialog_content = "(이 세상에서 너의 이해자는 오직 나뿐이다. 그러나 나는 너를 존중한다.)",
  ui_story_1020_10201301_115_dialog_content = "(당신... 율리시스한테 뭘 하려는 거야?)",
  ui_story_1020_10201301_116_dialog_content = "(그를 완성시킬 것이다.)",
  ui_story_1020_10201301_117_dialog_content = "(일루미나에는 어느 시대건 우수한 과학자가 탄생했다.)",
  ui_story_1020_10201301_118_dialog_content = "(그러나 프로토타입과 과학자들이 없더라도, 우리는 다른 곳에서 만나게 될 것이다.\n너는 이미 내 좌표를 알고 있으니 말이다.)",
  ui_story_1020_10201301_119_dialog_content = "......",
  ui_story_1020_10201301_120_dialog_content = "(기억해라. 빛은 기만으로 가득 차 있고,\n빛이 덮어씌우려 하는 어둠이야말로 이 세상의 진정한 밑바탕이다.)",
  ui_story_1020_10201301_121_dialog_content = "(어둠을 받아들이고, 어둠에 녹아들어, 어둠이 너의 힘이 되게 만들어라.)",
  ui_story_1020_10201301_122_dialog_content = "으윽──!",
  ui_story_1020_10201301_123_dialog_content = "부부! 부부! 부부!",
  ui_story_1020_10201301_124_dialog_content = "머리 안 다쳤어, PlayerName?",
  ui_story_1020_10201301_125_dialog_content = "전 괜찮아요! 하지만 율리시스가...",
  ui_story_1020_10201301_126_dialog_content = "크아아아아──!",
  ui_story_1020_10201301_127_dialog_content = "부부! 부부! 부부!",
  ui_story_1020_10201301_128_dialog_content = "교수님, 더는 다가오지 마세요! 아니면...",
  ui_story_1020_10201301_129_dialog_content = "<color=#e8d9bb>철컥──</color>",
  ui_story_1020_10201301_130_dialog_content = "......",
  ui_story_1020_10201301_131_dialog_content = "날 쏘겠다는 거냐...? 내가 너희를 창조했다... 너희는 날 이해하겠지. 그렇지?",
  ui_story_1020_10201301_132_dialog_content = "지금 율리시스의 상태는 피제로와 똑같아요!",
  ui_story_1020_10201301_133_dialog_content = "...아니야.",
  ui_story_1020_10201301_134_dialog_content = "율리시스는 엔지니어한테 굴복하지 않았어.\n그래서 엔지니어가 저 사람을 없애려고 하는 거야... 저 사람은 지금 저항하고 있어.",
  ui_story_1020_10201301_135_dialog_content = "......",
  ui_story_1020_10201301_136_dialog_content = "대원수님... 어떻게 처분하는 게 좋을까요?",
  ui_story_1020_10201301_137_dialog_content = "...멈춰라, 율리시스! 아직도 모르겠나?",
  ui_story_1020_10201301_138_dialog_content = "넌 자신이 오로리안을 구원하고, 이클립스에 맞서고 있단 착각에 빠져 있지만,\n사실 넌 자신도 모르는 새 놈들의 일원이 되어 버렸단 말이다!",
  ui_story_1020_10201301_139_dialog_content = "그들에게 전하세요... 아이테르...",
  ui_story_1020_10201301_140_dialog_content = "10011000...... 오로리안이 어떻게 살아가야 하는지...... 00!",
  ui_story_1020_10201301_141_dialog_content = "오직 사력을 다해...... 12933...... 매진해야만...... 11012......\n비로소...... 103001111......",
  ui_story_1020_10201301_142_dialog_content = "가능성이......",
  ui_story_1020_10201301_143_dialog_content = "01100......",
  ui_story_1020_10201301_144_dialog_content = "아니야...",
  ui_story_1020_10201301_145_dialog_content = "당신은 특별합니다...... 당신은 자신만의 방식으로...... 운명과 맞서야 합니다......",
  ui_story_1020_10201301_146_dialog_content = "하...... 10011001X0...... 하지만......",
  ui_story_1020_10201301_147_dialog_content = "으윽... 으아아악──!",
  ui_story_1020_10201301_148_dialog_content = "1001X1000...... 제가 바꾼 세계는......",
  ui_story_1020_10201301_149_dialog_content = "분명...... 10102099...... 당신들의 미래가 되겠지요...... 1X120......",
  ui_story_1020_10201301_150_dialog_content = "부르!",
  ui_story_1020_10201301_151_dialog_content = "율리시스의 몸에 있는 관에 케이블을 연결해.\n우리가 연결부를 찾아내서 율리시스랑 엔지니어의 연결을 끊는 거야!",
  ui_story_1020_10201301_152_dialog_content = "크어어──!",
  ui_story_1020_10201301_153_dialog_content = "이미 늦었어요...",
  ui_story_1020_10201301_154_dialog_content = "......",
  ui_story_1020_10201301_155_dialog_content = "한때 율리시스가 일루미나를 위해 무엇을 했든,\n율리시스는 이제 더는 오로리안이 아니며, 일루미나인은 더더욱 아니다.",
  ui_story_1020_10201301_156_dialog_content = "율리시스는 자난성을 수차례 위험에 빠트렸고, 동포들의 목숨을 빼앗았다.",
  ui_story_1020_10201301_157_dialog_content = "이에 나 라인하르트는 일루미나 대원수의 이름으로, 이 자리에서 율리시스에게 사형을 선고한다.",
  ui_story_1020_10201301_158_dialog_content = "크아아아아──!",
  ui_story_1020_10201301_159_dialog_content = "죽여라!",
  ui_story_1020_10201402_1_dialog_content = "제가 죽으면... 당신들이 구원을 받을 수 있을까요...?",
  ui_story_1020_10201402_2_dialog_content = "정말 이게 최선이란 말이냐, 라빌...",
  ui_story_1020_10201402_3_dialog_content = "<color=#e8d9bb>어둠의 위기, 일루미나 전시 요양원</color>",
  ui_story_1020_10201402_4_dialog_content = "음... 오랜만이야, 율리.",
  ui_story_1020_10201402_5_dialog_content = "이런 곳에서 만나게 될 줄은 몰랐네... 라빌...",
  ui_story_1020_10201402_6_dialog_content = "라빌, 잘 지...",
  ui_story_1020_10201402_7_dialog_content = "오늘은 또 어떤 새로운 문제가 떠올랐지?",
  ui_story_1020_10201402_8_dialog_content = "......",
  ui_story_1020_10201402_9_dialog_content = "내 실험은 또 실패했어. <color=#FFB400>77호 지하성</color>에서 되돌아온 거라곤 불타 버린 실험체 몇 구뿐이야...",
  ui_story_1020_10201402_10_dialog_content = "오늘은 방송에서 우리가 예전에 실험실에서 항상 듣던 노래가 나오더라고...\n아, 방금 뭐라고 했지?",
  ui_story_1020_10201402_11_dialog_content = "......",
  ui_story_1020_10201402_12_dialog_content = "그 브로치... 아직도 달고 있었네.",
  ui_story_1020_10201402_13_dialog_content = "맞아... 어젠 밤새도록 찾았다니까. 알고 보니 우리 샤샤가 숨겨 뒀더라고.\n정말 개구쟁이라니까.",
  ui_story_1020_10201402_14_dialog_content = "......",
  ui_story_1020_10201402_15_dialog_content = "샤샤는 요즘 시 쓰는 법을 배웠어. 내가 읽어 줄게, 율리. 어떤지 한번 들어 봐...",
  ui_story_1020_10201402_16_dialog_content = "라빌...",
  ui_story_1020_10201402_17_dialog_content = "넌 이미 우리가 함께 실험과 연구에 몰두하며,\n엔지니어의 단서에 대해 조사하던 날들을 잊은 모양이구나.",
  ui_story_1020_10201402_18_dialog_content = "기억하는 건 이미 오래전에 세상을 떠난 가족뿐인 거냐...",
  ui_story_1020_10201402_19_dialog_content = "사실, 차라리 잘됐다 싶어. 하하...",
  ui_story_1020_10201402_20_dialog_content = "내가 엔지니어라는 이름을 단 한 번도 보지 못하고, 그 장면들도 보지 못했다면...",
  ui_story_1020_10201402_21_dialog_content = "우리가 아직도 예전처럼 실험실에서 서로의 이상을 이야기할 수 있었다면...",
  ui_story_1020_10201402_22_dialog_content = "매일 얼굴을 보자마자 넌 이렇게 말했겠지...",
  ui_story_1020_10201402_23_dialog_content = "율리, 오늘은 또 어떤 새로운 문제가 떠올랐지?",
  ui_story_1020_10201402_24_dialog_content = "......",
  ui_story_1020_10201402_25_dialog_content = "율리.",
  ui_story_1020_10201402_26_dialog_content = "음?",
  ui_story_1020_10201402_27_dialog_content = "믿음이 무너지는 경험을 해 본 적 있나?",
  ui_story_1020_10201402_28_dialog_content = "......",
  ui_story_1020_10201402_29_dialog_content = "없어.",
  ui_story_1020_10201402_30_dialog_content = "그럼 넌...",
  ui_story_1020_10201402_31_dialog_content = "믿음이 무너지는 것과 이상이 실현되지 않는 것 중, 어느 쪽이 더 슬플 것 같지?",
  ui_story_1020_10201402_32_dialog_content = "......",
  ui_story_1020_10201402_33_dialog_content = "믿음이 무너지는 것과 이상이 실현되지 않는 것 중에...",
  ui_story_1020_10201402_34_dialog_content = "대체 어느 쪽이 더 슬픈 일일까.",
  ui_story_1020_10201402_35_dialog_content = "......",
  ui_story_1020_10201501_1_dialog_content = "...꼭 캔버스 같아!",
  ui_story_1020_10201501_2_dialog_content = "정말이네... 그것도 민치의 캔버스 말이야.\n아무렇게나 그린 다음에 물감을 뿌린 것처럼 보여!",
  ui_story_1020_10201501_3_dialog_content = "...오히려 독특한 아름다움이 있군요.",
  ui_story_1020_10201501_4_dialog_content = "둘 다 무슨 뜻이야?!",
  ui_story_1020_10201501_5_dialog_content = "날 비웃으라고 빅토리아 님이 우릴 여기로 데려오신 게 아니거든!",
  ui_story_1020_10201501_6_dialog_content = "아! 잊을 뻔했군요. 감사합니다, 빅토리아 님!",
  ui_story_1020_10201501_7_dialog_content = "감사합니다, 빅토리아 님!",
  ui_story_1020_10201501_8_dialog_content = "감사해요, 빅토리아 님!",
  ui_story_1020_10201501_9_dialog_content = "진리의 주인께서 굽어살펴 주신 거지, 내 덕분이 아니야.",
  ui_story_1020_10201501_10_dialog_content = "여긴 뭐 하는 곳이죠?",
  ui_story_1020_10201501_11_dialog_content = "......",
  ui_story_1020_10201501_12_dialog_content = "<color=#FFB400>원시의 강</color>은 시간과 공간의 제약을 받지 않아.\n이곳과 바깥 세계의 유일한 차이점은 흐르고 있다는 거야.",
  ui_story_1020_10201501_13_dialog_content = "계속 이대로 가면 우리 목숨도 우리 뜻대로 할 수 없게 되는 건가?",
  ui_story_1020_10201501_14_dialog_content = "왜 우릴 이곳으로 데려왔지?",
  ui_story_1020_10201501_15_dialog_content = "우리의 시공에 대응하는 표지점을 찾아,\n진리의 주인께서 우리와 함께 강림하시도록 하기 위해서야.",
  ui_story_1020_10201501_16_dialog_content = "터무니없는 소리로군...",
  ui_story_1020_10201501_17_dialog_content = "빅토리아 씨, 저흰 아직 어둠의 밑바닥 정찰 임무가 안 끝났어요.\n여기서 좌표를 보내면 일루미나에서 정말 수신할 수 있을까요?",
  ui_story_1020_10201501_18_dialog_content = "진리의 주인께서는 의지만 있다면 알 수 있다고 말씀하셨어.\n그건 전적으로 당신 선택에 달려 있어.",
  ui_story_1020_10201501_19_dialog_content = "<color=#e8d9bb>풍덩──</color>",
  ui_story_1020_10201501_20_dialog_content = "어? 바이스, 너 뭐 떨어뜨렸어?",
  ui_story_1020_10201501_21_dialog_content = "앗... 내 일루미나 휘장!",
  ui_story_1020_10201501_22_dialog_content = "어, 어떡하지...? 전혀 찾을 수가 없잖아...",
  ui_story_1020_10201501_23_dialog_content = "어라? 작은 휘장 하나가 떨어졌을 뿐인데, 갑자기 강 전체가 빛나는 것 같은데요?",
  ui_story_1020_10201501_24_dialog_content = "황야는 고요하지만, 강물 아래에는 또 다른 풍경이 존재한단다.",
  ui_story_1020_10201501_25_dialog_content = "호수면... 으으, 쌀쌀하네요. 왠지 현실감이 전혀 없는데요...",
  ui_story_1020_10201501_26_dialog_content = "호수면...",
  ui_story_1020_10201501_27_dialog_content = "PlayerName, 정신이 들었구나.",
  ui_story_1020_10201501_28_dialog_content = "여긴...",
  ui_story_1020_10201501_29_dialog_content = "카렌? 라인하르트 씨랑 비비안 씨까지... 제가 왜 여기 있죠?",
  ui_story_1020_10201501_30_dialog_content = "아무것도 기억나지 않는 건가?",
  ui_story_1020_10201501_31_dialog_content = "꿈에서 맑고 반짝이는 호수면을 본 것 같은데...\n자세히 생각해 보려니까 기억이 잘 안 나요...",
  ui_story_1020_10201501_32_dialog_content = "참! 일루미나는 괜찮은 건가요?!",
  ui_story_1020_10201501_33_dialog_content = "음, 목소리에 기운이 넘치는 걸 보면 별문제는 없는 것 같군.",
  ui_story_1020_10201501_34_dialog_content = "3일 동안 잠을 자서 그런지 회복 상태가 괜찮네요. 역시 젊다는 건 참 좋은 일이라니까요.",
  ui_story_1020_10201501_35_dialog_content = "3일?!",
  ui_story_1020_10201501_36_dialog_content = "맞아요. 카렌 호위대장도 이번이 세 번째 방문이에요.",
  ui_story_1020_10201501_37_dialog_content = "너무 자주 연락하면 당신을 번거롭게 만들 것 같다고 생각했을 뿐이야...",
  ui_story_1020_10201501_38_dialog_content = "애초에 <color=#FFB400>연합 회의</color>는 일루미나가 제안한 것이다.\n미리 시간을 상의하지 못한 점은 양해해 주길 바란다.",
  ui_story_1020_10201501_39_dialog_content = "PlayerName, 너도 정신을 차렸고, 마침 호위대장도 이 자리에 있으니,\n오늘 당장 하는 건 어떠냐.",
  ui_story_1020_10201501_40_dialog_content = "음, 난 문제 없어.",
  ui_story_1020_10201501_41_dialog_content = "연합 회의라니... 무슨 일이 있었던 거죠? 율리시스... 그 사람은 어떻게 됐어요?",
  ui_story_1020_10201501_42_dialog_content = "그자는 죽었다. 엔지니어와 관련된 일들 역시 일단락된 상태다.",
  ui_story_1020_10201501_43_dialog_content = "사태가 마무리된 후, 이번 건을 처음부터 되돌아보았다.\n그리고 난 PlayerName 네가 율리시스의 의식 속에서 뭘 봤는지 짐작이 가더군.",
  ui_story_1020_10201501_44_dialog_content = "이번에 율리시스의 실험실을 조사하면서, 그곳에 있던 대량의 일기 속에서도\n많은 핵심 정보를 확인할 수 있었다.",
  ui_story_1020_10201501_45_dialog_content = "예상하지 못했던 부분이라면, 엔지니어가 그렇게 오랜 시간 주시해 왔는데도,\n율리시스가 지금까지 버텨냈다는 점이었다.",
  ui_story_1020_10201501_46_dialog_content = "하지만 대원수님 말씀대로, 율리시스가 어둠의 밑바닥을 응시하는 동안,\n어둠의 밑바닥도 율리시스를 침식하기 시작했죠...",
  ui_story_1020_10201501_47_dialog_content = "그리고 율리시스는 자기도 모르는 사이에 이클립스의 일원이 돼 버렸던 거예요.",
  ui_story_1020_10201501_48_dialog_content = "음, 자난성이 겪은 이번 위기는 600여 년 전 미증유의 사건이 다시 재현되는 것만 같았다.",
  ui_story_1020_10201501_49_dialog_content = "하지만 이번에도 그때처럼 모두가 힘을 합쳐 자난성을 지켜낼 수 있었지.\n그리고 이 결과에는 너와 알골 박사의 공을 빼놓을 수 없다.",
  ui_story_1020_10201501_50_dialog_content = "알골 씨는요?",
  ui_story_1020_10201501_51_dialog_content = "휴, 그 사람도 당신처럼 며칠은 푹 잘 줄 알았는데 말이에요.",
  ui_story_1020_10201501_52_dialog_content = "상황이 종료되고 나니까 아무 일도 없었던 것처럼 계속 연구하기 시작했어요.",
  ui_story_1020_10201501_53_dialog_content = "오늘은 1호 수리에 쓸 부품을 찾으러 간다고 했던 것 같으니까, 아마 외출했을 거예요...",
  ui_story_1020_10201501_54_dialog_content = "벌써 1호를 수리할 준비가 끝났구나... 알골 씨가 외출을 하다니, 별일이네.",
  ui_story_1020_10201501_55_dialog_content = "아마 일루미나의 새로운 운송 수단에 탑승할 수 있어서 그런 거겠죠.",
  ui_story_1020_10201501_56_dialog_content = "일루미나의 새로운 운송 수단? 그게 뭐야?",
  ui_story_1020_10201501_57_dialog_content = "율리시스는 수년간 콜로서스를 연구했다.\n그리고 작업반은 그의 연구 자료를 바탕으로 콜로서스와 유사한 소형 탈것을 제작했다.",
  ui_story_1020_10201501_58_dialog_content = "이번 사태에서 이 소형 탈것들은 일부 주민들을 다른 곳으로 이송하는 데 도움이 됐다.\n게다가 이제 연합 탐색에서도 활용될 예정이지.",
  ui_story_1020_10201501_59_dialog_content = "......",
  ui_story_1020_10201501_60_option_content = "율리시스...",
  ui_story_1020_10201501_61_option_content = "소형 탈것...",
  ui_story_1020_10201501_62_dialog_content = "...율리시스의 연구 성과가 정말로 계속 사용되는 건가요?",
  ui_story_1020_10201501_63_dialog_content = "네가 뭘 걱정하는지는 알고 있다.",
  ui_story_1020_10201501_64_dialog_content = "소형 탈것 이외에도, 숀처럼 어둠의 밑바닥 탐색에 있어 자질을 갖춘\n오로리안에 대한 관심 역시...",
  ui_story_1020_10201501_65_dialog_content = "율리시스의 연구에 기반을 두고 있다는 건 부정할 수 없는 사실이다.",
  ui_story_1020_10201501_66_dialog_content = "나는 이러한 결정을 내린 것 또한 어둠의 위기 당시 「가디언」 시스템의\n연구 권한을 개방한 것 못지않게 힘든 것이었다고 믿는다.",
  ui_story_1020_10201501_67_dialog_content = "이번에 우리는 과학 수석 의회와 연구실의 모든 책임자를 대상으로,\n율리시스의 연구 성과에 대한 평가와 투표를 진행했다...",
  ui_story_1020_10201501_68_dialog_content = "그 결과 여전히 찬성과 반대 모두 저마다 합당한 근거를 제시했지.",
  ui_story_1020_10201501_69_dialog_content = "하지만 내 입장은 오직 일루미나 동포들의 생존이 가장 중요했다.",
  ui_story_1020_10201501_70_dialog_content = "그래서 라인하르트 씨는 반대하는 쪽이셨나요?",
  ui_story_1020_10201501_71_dialog_content = "정반대였지.",
  ui_story_1020_10201501_72_dialog_content = "리스크 감소는 생존을 보장하는 주요 조건 중 하나다.\n우리는 위험을 철저히 파악해야 할 뿐만 아니라, 위험을 역이용해야 하지.",
  ui_story_1020_10201501_73_dialog_content = "우리는 앞으로도 계속 우리의 적을 연구하고, 우리의 한계를 시험해야 한다.\n그리고 끊임없이 오로리안의 생존 환경을 개선하기 위해 전진하며 탐색해야 한다.",
  ui_story_1020_10201501_74_dialog_content = "그래서 연합 탐색을 진행하려는 건가요... 그럼 백야성도 위기에 빠진 거예요?",
  ui_story_1020_10201501_75_dialog_content = "위기에 빠지지는 않았지만, 여러 성물에 루미나 교란 현상이 발생해서,\n성주님께서 사태를 주목하고 계셔.",
  ui_story_1020_10201501_76_dialog_content = "자난성의 위기 이후, 위원회도 마침내 대륙의 각 세력과 공동으로\n연합 탐색대를 조직하는 방안을 논의해 볼 마음이 생겼더군.",
  ui_story_1020_10201501_77_dialog_content = "백야성 연합 탐색대 대장은 카렌이 맡기로 했고,\n북방과 움브라톤에서도 특사를 보내 회의에 참석할 거다.",
  ui_story_1020_10201501_78_dialog_content = "참, 대원수님! 레디젤 사막의 어중이떠중이들도 어디서 소문을 들은 건지,\n자기들도 참가하겠다고 하고 있대요.",
  ui_story_1020_10201501_79_dialog_content = "PlayerName, 난 네 생각을 듣고 싶다.",
  ui_story_1020_10201501_80_dialog_content = "제 생각...",
  ui_story_1020_10201501_81_dialog_content = "그동안 전 왠지 스스로 뭔가 생각해 본 적이 없었던 것 같아요.\n그저 아이테르가 남긴 흔적을 뒤쫓기만 했죠.",
  ui_story_1020_10201501_82_dialog_content = "그런데 스카이워커를 고치는 과정에서...\n전 그런 흔적들이 꼭 다 좋은 것만은 아니란 걸 알았어요...",
  ui_story_1020_10201501_83_dialog_content = "심지어는 저 자신이 좋은 사람인지, 나쁜 사람인지도 확신할 수 없었죠...",
  ui_story_1020_10201501_84_dialog_content = "하지만 바이스와 스카이워커의 일을 겪고 난 뒤로는,\n늘 뜻밖의 상황에서 느꼈던 놀라움과 기쁨이 모두 사라져 버렸어요.",
  ui_story_1020_10201501_85_dialog_content = "전 이미 그 둘을 잃었잖아요. 그래서 꼭 되찾고 싶어요... 너무나도 절박한 느낌이에요...",
  ui_story_1020_10201501_86_dialog_content = "참... 그리고 요즘은 제가 자꾸 과거나 미래를 보는 것 같다는 느낌이 들어요...",
  ui_story_1020_10201501_87_dialog_content = "그리고 그곳들은 왠지 전부 제가 꼭 가서 찾아야 할 곳들 같고요.",
  ui_story_1020_10201501_88_dialog_content = "어쩌면 어둠의 밑바닥이거나, 어둠의 밑바닥보다 더 멀고...\n더 가기 힘든 곳일 수도 있겠죠.",
  ui_story_1020_10201501_89_dialog_content = "왠지 「숙명」처럼 들리네요.",
  ui_story_1020_10201501_90_dialog_content = "그런가... 근데 동방에서 온 친구가 점을 봐 준 적이 있는데,\n내 운명은 「명부에도 적혀 있지 않다」고 했었어...",
  ui_story_1020_10201501_91_dialog_content = "아이테르는 선천적 족쇄를 벗어 던질 수 있으니까, 난 숙명은 안 믿어.",
  ui_story_1020_10201501_92_dialog_content = "자신의 뜻과 용기, 지혜가 충분하다면, 당신이 잃은 것들은 반드시 되찾아올 수 있을 거예요.",
  ui_story_1020_10201501_93_dialog_content = "응!",
  ui_story_1020_10201501_94_dialog_content = "네가 그렇게 생각할 수 있다면 정말 다행이군.",
  ui_story_1020_10201501_95_dialog_content = "물론, 난 일루미나의 대원수로서 우리 일루미나의 우수한 군인인 카론과 바이스,\n그리고 그 휘하의 대원들을 되찾아야 할 의무가 있다.",
  ui_story_1020_10201501_96_dialog_content = "네가 원한다면 일루미나는 네가 스카이워커호를 되찾을 수 있도록\n네 어둠의 밑바닥 탐색에 협조하겠다.",
  ui_story_1020_10201501_97_dialog_content = "음, 이번에 백야성이 연합 탐색대에 참가한 건 너 때문이기도 해.",
  ui_story_1020_10201501_98_dialog_content = "다들 고마워요...",
  ui_story_1020_10201501_99_dialog_content = "이렇게 전 항상 모두의 믿음과 도움을 받고 있잖아요?\n그럼 이번 연합 탐색대엔 저도 꼭 참가하겠어요!",
  ui_story_1020_10201501_100_dialog_content = "근데 탐색을 어디서부터 시작하는데요?",
  ui_story_1020_10201501_101_dialog_content = "사실 탐색을 시작하기 좋은 장소는 꽤 많이 있지.",
  ui_story_1020_10201501_102_dialog_content = "이게 뭐예요?",
  ui_story_1020_10201501_103_dialog_content = "「헬리오스의 회고록」이다.",
  ui_story_1020_10201501_104_dialog_content = "굉장히 두껍네요... 이렇게 빨리 완성된 건가요?\n역시 찬드라는 일 처리가 정말 빠르다니까요.",
  ui_story_1020_10201501_105_dialog_content = "그 오랜 시간을 불청객에게 시달리면서도 죽어라 매달린 일이니 말이야.",
  ui_story_1020_10201501_106_dialog_content = "어쨌거나 네가 괜찮은 걸 확인했으니, 이제 우리도 드디어 푹 잘 수 있겠군.",
  ui_story_1020_10201501_107_dialog_content = "참, PlayerName. 아까 꿈에서 맑고 반짝이는 호수면을 봤다고 하지 않았나요?",
  ui_story_1020_10201501_108_dialog_content = "맞아... 맑고 반짝이는 호수면...",
  ui_story_1020_10201501_109_dialog_content = "그리고 눈에 익은 휘장도 하나 있었어...",
  ui_story_1020_10201501_110_dialog_content = "다들 이런 경험을 해 본 적 있을진 모르겠는데...",
  ui_story_1020_10201501_111_dialog_content = "자신이 곧 어둠에 집어삼켜질 것 같은 순간에, 갑자기 들려온 피아노 소리가 어둠을 가르고,\n빛이 흘러 들어오는 거야...",
  ui_story_1020_10201501_112_dialog_content = "<color=#e8d9bb>풍덩──</color>",
  ui_story_1020_10201501_113_dialog_content = "지금 어디서 피아노 소리 들리지 않아?",
  ui_story_1020_10201501_114_dialog_content = "들려!",
  ui_story_1020_10201501_115_dialog_content = "어?",
  ui_story_1020_10201501_116_dialog_content = "음... 메리가 크게 소리친 순간 사라졌습니다...",
  ui_story_1020_10201501_117_dialog_content = "진리의 주인께 감사드립니다!",
  ui_story_1020_10201501_118_dialog_content = "바이스 양, 당신은 이미 그 표지점을 발견했어. 부디 당신의 방식으로 우리를 인도해 줘.",
  ui_story_1020_10201501_119_dialog_content = "제, 제가요?",
  ui_story_1020_10201501_120_dialog_content = "당신과 아이테르가 함께 그 콜로서스를 가동했을 때,\n깊은 잠에 빠져 있던 이 원시의 강도 눈을 떴어.",
  ui_story_1020_10201501_121_dialog_content = "그리고 그때부터, 아이올리아의 역사는 당신에 의해 새로운 페이지로 넘어가게 된 거야.",
  ui_story_1020_10201501_122_dialog_content = "다시 한번 당신의 방식으로 우리를 인도해 줘.",
  ui_story_1020_10201501_123_dialog_content = "다시 한번 당신의 방식으로 저희를 인도해 주세요.",
  ui_story_1020_10201501_124_dialog_content = "......?",
  ui_story_1020_10201501_125_dialog_content = "......",
  ui_story_1020_10201501_126_dialog_content = "그럼 아까 그 피아노 소리... 설마...",
  ui_story_1020_10201501_127_dialog_content = "그러니까 이 「피아노」처럼 생긴 게 콜로서스의 컨트롤러인 거지?",
  ui_story_1020_10201501_128_dialog_content = "나랑 같이 콜로서스를 가동해 보자, 조종사.",
  ui_story_1020_10201501_129_dialog_content = "같이...? 바이스, 넌 오로리안이잖아. 감응 능력이 없다고...",
  ui_story_1020_10201501_130_dialog_content = "하지만 너한테 힘이 될 순 있을 거야. 내가... 도와줄게.",
  ui_story_1020_10201501_131_dialog_content = "......?",
  ui_story_1020_10201501_132_dialog_content = "날 믿어, PlayerName. 나와 넌 사실... 비슷한 점들이 있거든.",
  ui_story_1020_10201501_133_dialog_content = "말하자면 길어. 나중에 기회가 되면 얘기해 줄게!",
  ui_story_1020_10201501_134_dialog_content = "내가 어떻게 「연주」하는지 알려줄게.",
  ui_story_1020_10201501_135_dialog_content = "빅토리아 씨 얘길 들으니까 예전 일이 생각났어요...",
  ui_story_1020_10201501_136_dialog_content = "......",
  ui_story_1020_10201501_137_dialog_content = "간단해. 피아노를 연주하듯이 하면 돼.",
  ui_story_1020_10201501_138_dialog_content = "......",
  ui_story_1020_10201501_139_dialog_content = "하지만 내 눈엔 악보가 보이지 않는걸. 내가 눌러야 할 건반을 알려줄래?",
  ui_story_1020_10201501_140_dialog_content = "......",
  ui_story_1020_10201501_141_dialog_content = "느껴져... 에너지가 요동치는 게...",
  ui_story_1020_10201501_142_dialog_content = "마치 대화하는 것처럼. 비록 콜로서스의 언어는 이해할 수 없지만 말이야.",
  ui_story_1020_10201501_143_dialog_content = "건반의 언어가 바로 콜로서스의 언어야.",
  ui_story_1020_10201501_144_dialog_content = "이제 콜로서스의 가동 명령을 완성하자, 바이스.",
  ui_story_1020_10201501_145_dialog_content = "......",
  ui_story_1020_10201501_146_dialog_content = "만약 그게 모두를 인도하는 방식이라면... 어떻게 해야 할지 알겠어요.",
  ui_story_1020_10201501_147_dialog_content = "다 같이 듣자! 피아노 연주곡이야!",
  ui_story_1020_10201501_148_dialog_content = "신비로운 빛이 반짝이는 이 강은 주의 은총이 있는 곳이니.",
  ui_story_1020_10201501_149_dialog_content = "주께서 저 신비로운 선율을 들으사, 끝없는 진리를 보여 주시리라.",
  ui_story_1020_10201501_150_dialog_content = "바라옵건대 진리의 주인께서 저희의 탐색을 증명하여 주시고, 동행하사 저희에게 임하소서.",
  ui_story_1021_10210100_1_dialog_content = "<color=#e8d9bb>수년 전, 북방의 변경 지대...</color>",
  ui_story_1021_10210100_2_dialog_content = "여왕 폐하, 이 앞에 보이는 산을 넘으면 북방의 경계를 벗어나시게 됩니다.",
  ui_story_1021_10210100_3_dialog_content = "......",
  ui_story_1021_10210100_4_dialog_content = "설원은 넓고, 이 앞에도 북방의 백성들이 살고 있다.",
  ui_story_1021_10210100_5_dialog_content = "먼저 돌아가라, 노비오 선생. 이것은 내가 원해서 하려는 일이다.",
  ui_story_1021_10210100_6_dialog_content = "역대 선왕들과 이 끝없는 얼음과 눈의 대지가 폐하께서 행하신 모든 일을\n마음에 깊이 새길 것입니다.",
  ui_story_1021_10210100_7_dialog_content = "북방을 지키는 힘은 나 자신의 힘이 아니다. 그 근원은 북방 자신에 있다.",
  ui_story_1021_10210100_8_dialog_content = "그 힘을 얻어 마음에 빚을 진 이상, 전력을 다해 보답함이 마땅하다.",
  ui_story_1021_10210100_9_dialog_content = "겨울이 지나면 새 생명이 오리니.\n우리는 북방을 지키기 위해 살아갈 것입니다.",
  ui_story_1021_10210100_10_dialog_content = "<color=#e8d9bb>부스럭부스럭...</color>",
  ui_story_1021_10210100_11_dialog_content = "으음? 눈이 그쳤구나...",
  ui_story_1021_10210100_12_dialog_content = "이 눈소나무 숲에 이런 맑은 날씨는 드물었던 것으로 기억하거늘.",
  ui_story_1021_10210100_13_dialog_content = "...에잇!",
  ui_story_1021_10210100_14_dialog_content = "?",
  ui_story_1021_10210100_15_dialog_content = "외지인! 경고하는데 빨리 여기서 나가!\n안 그러면 부족의 리더 티아라의 무서움을 맛보게 될 테니까!",
  ui_story_1021_10210100_16_dialog_content = "...티아라는 그대의 이름인가.",
  ui_story_1021_10210100_17_dialog_content = "뭐...?! 어떻게 내 이름을...",
  ui_story_1021_10210100_18_dialog_content = "크흠... 이 몸의 이름을 몰래 들었다고 해서 눈여우 부락에 들여보내 줄 생각은 전혀 없어!",
  ui_story_1021_10210100_19_dialog_content = "눈여우 부족의 아이로구나. 부모는 어디 있느냐.",
  ui_story_1021_10210100_20_dialog_content = "아버님과 어머님은 북방을 지키느라 바쁘시거든?! 말 돌리지 마! 그것보다 당신 여기 뭐 하러 왔어?",
  ui_story_1021_10210100_21_dialog_content = "티아라! 이 할미가 뭘 가져왔는지 보려무나.",
  ui_story_1021_10210100_22_dialog_content = "우와! 티아라가 제일 좋아하는 향긋한 소나무 가지네!",
  ui_story_1021_10210100_23_dialog_content = "허면 말해 보거라. 왜 제단에 안 가고 여기서 장난을 치고 있는 게냐?",
  ui_story_1021_10210100_24_dialog_content = "으음... 그치만 장로님이 제단은 어린애들이 가도 되는 곳이 아니랬어...",
  ui_story_1021_10210100_25_dialog_content = "그 노친네, 갈수록 치매가 심해지는 모양이구나.",
  ui_story_1021_10210100_26_dialog_content = "증조할머니! 티아라 오늘 좋은 일 했어!\n봐, 내가 외지인한테 겁을 줘서 부락에 못 들어오게 했어!",
  ui_story_1021_10210100_27_dialog_content = "......",
  ui_story_1021_10210100_28_dialog_content = "역시 티아라는 대단하구나!",
  ui_story_1021_10210100_29_dialog_content = "그럼 이 할미가 시험을 하나 해 보자꾸나.「세 그루 소나무」의 전설을 기억하고 있느냐?",
  ui_story_1021_10210100_30_dialog_content = "기억나!",
  ui_story_1021_10210100_31_dialog_content = "티아라는 영리한 아이다. 그 전설 같은 건 이제 그만 말할 때도 되었다.",
  ui_story_1021_10210100_32_dialog_content = "내가 말해주지 않으면 이제 더는 기억할 사람도 없지 않겠나.\n곧 이 아이도 다른 이의 이야기를 배우고 전승하게 될 게야.",
  ui_story_1021_10210100_33_dialog_content = "......",
  ui_story_1021_10210100_34_dialog_content = "베들레헴이 그대들의 평안을 바란다.",
  ui_story_1021_10210100_35_dialog_content = "북방을 지켜 온 일족의 선조들에게 감사하지. 하면 먼저 실례하겠다.",
  ui_story_1021_10210100_36_dialog_content = "......",
  ui_story_1021_10210100_37_dialog_content = "<color=#e8d9bb>부스럭부스럭...</color>",
  ui_story_1021_10210100_38_dialog_content = "그대는 등대가 이곳을 비출 것이라고 했었지.",
  ui_story_1021_10210100_39_dialog_content = "......",
  ui_story_1021_10210100_40_dialog_content = "그러나 눈여우 부락에는 이미 오랫동안 아기의 울음소리가 들리지 않았다.",
  ui_story_1021_10210100_41_dialog_content = "그대들이 북방을 위해 배출한 모든 호위에게 감사의 뜻을 표한다.",
  ui_story_1021_10210100_42_dialog_content = "이 아이들은 태어날 때부터 장엄하고 높은 궁전이 아니라,\n언제 암귀의 습격을 받을지 모르는 설원의 숲에서 살고 있다.",
  ui_story_1021_10210100_43_dialog_content = "저들의 선조 또한 대를 이어 북방을 지키기 위해 이 땅에서 목숨을 잃었지.",
  ui_story_1021_10210100_44_dialog_content = "내가 저 아이를 윈터 팰리스로 데려가 줄 수 있다.",
  ui_story_1021_10210100_45_dialog_content = "만약 북방이 암귀에 의해 멸망한다면, 그대는 이곳을 떠나 다른 곳으로 갈 셈인가.",
  ui_story_1021_10210100_46_dialog_content = "가지 않는다.",
  ui_story_1021_10210100_47_dialog_content = "북방은 우리를 기르고 지켜주었다. 그러므로 우리도 대대로 이곳을 지켜나가야 마땅하지.",
  ui_story_1021_10210100_48_dialog_content = "(어째서... 그날의 일이 떠올랐단 말이냐...)",
  ui_story_1021_10210100_49_dialog_content = "폐하, 변방의 날씨에 이상이 있었습니다. 등대의 불빛에도 미미하지만 변화가 발생했습니다.",
  ui_story_1021_10210100_50_dialog_content = "역시 우연이 아니었나... 이미 예감했던 일이다.",
  ui_story_1021_10210100_51_dialog_content = "폐하께서 예견하신 대로 지난번 일루미나의 위기는 결코 독립된 사건이 아닙니다.\n거점의 건설도 그리 순조롭지 않습니다...",
  ui_story_1021_10210100_52_dialog_content = "어둠의 밑바닥의 동향을 주시할 필요가 있겠습니다.",
  ui_story_1021_10210100_53_dialog_content = "연합 탐색은 매우 중요하다. 그것은 오로리안의 미래가 달린 일이다.\n게다가 연합 회의까지도 이제 며칠 남지 않았지.",
  ui_story_1021_10210100_54_dialog_content = "가서 살펴봐야겠다.",
  ui_story_1021_10210100_55_dialog_content = "지금 말씀이십니까?",
  ui_story_1021_10210100_56_dialog_content = "그렇다, 티아라는 보았는가.",
  ui_story_1021_10210100_57_dialog_content = "티아라는...",
  ui_story_1021_10210100_58_dialog_content = "여왕 폐하... 출행이신가요? 제가 모시겠습니다.",
  ui_story_1021_10210100_59_dialog_content = "......",
  ui_story_1021_10210100_60_dialog_content = "나 홀로 며칠간 다녀올 것이다.\n윈터 팰리스의 일은 노비오에게 맡길 테니, 내가 없는 동안 그대는 단련에 힘쓰도록 해라.",
  ui_story_1021_10210100_61_dialog_content = "네, 여왕 폐하!",
  ui_story_1021_10210100_62_dialog_content = "(왜 저렇게 서두르시지...?)",
  ui_story_1021_10210100_63_dialog_content = "창틀의 발자국을 좀 닦아야겠구나.",
  ui_story_1021_10210100_64_dialog_content = "...네!",
  ui_story_1021_10210100_65_dialog_content = "<color=#e8d9bb>아우우──!</color>",
  ui_story_1021_10210100_66_dialog_content = "......",
  ui_story_1021_10210100_67_dialog_content = "역시 아무 응답도 없어...",
  ui_story_1021_10210100_68_dialog_content = "여왕 폐하께서 출궁하신 지도 벌써 며칠이 지났는데...",
  ui_story_1021_10210100_69_dialog_content = "호위로서 폐하의 곁에 있을 수 없다니, 어떻게 「단련」에 힘써야 하는 걸까...",
  ui_story_1021_10210100_70_dialog_content = "<color=#e8d9bb>아우우──</color>",
  ui_story_1021_10210100_71_dialog_content = "너희들이구나...",
  ui_story_1021_10210100_72_dialog_content = "아우우...",
  ui_story_1021_10210100_73_dialog_content = "뭐라고...?",
  ui_story_1021_10210100_74_dialog_content = "아우우──!",
  ui_story_1021_10210100_75_dialog_content = "어떻게 그런...?!",
  ui_story_1021_10210100_76_dialog_content = "폐하께서 출궁하시기 전에 다녀왔을 땐 장로님이 수확이 풍성하다고 기뻐하셨는데...",
  ui_story_1021_10210100_77_dialog_content = "하지만 나는 여왕 폐하의 호위야... 마음대로 자리를 비우는 건...",
  ui_story_1021_10210100_78_dialog_content = "아우우우!",
  ui_story_1021_10210100_79_dialog_content = "...알겠어! 지금 바로 같이 돌아갈게!",
  ui_story_1021_10210100_80_dialog_content = "우와! 눈여우다! 눈여우야!",
  ui_story_1021_10210100_81_dialog_content = "자꾸 안토니 선생님 수업 방해할래? 어디 눈여우가 있다는 거야?!",
  ui_story_1021_10210100_82_dialog_content = "잘 봐, 그냥 토끼가 깡총깡총 뛰고 있을 뿐이잖아!",
  ui_story_1021_10210100_83_dialog_content = "근데 방금 진짜 봤다구... 글자공부 책에 나온 눈여우랑 똑같이 생겼다니까!",
  ui_story_1021_10210100_84_dialog_content = "눈여우가 마을에 나타난다는 건 분명히 이상하긴 한데... 안토니 선생님! 선생님은 믿어 줄 거지?",
  ui_story_1021_10210100_85_dialog_content = "전설에 따르면, 이곳이 아직 북방으로 불리지 않았을 시절에는\n눈여우와 오로리안이 좋은 친구였고, 함께 이 땅을 지켰다고 해.",
  ui_story_1021_10210100_86_dialog_content = "그럼 북방엔 지금도 눈여우가 있어?",
  ui_story_1021_10210100_87_dialog_content = "있을 거야. 눈여우는 신성한 동물이야.\n그중에는 수백, 수천 년을 사는 눈여우도 있다는 전설도 있어...",
  ui_story_1021_10210100_88_dialog_content = "수천 년이라니... 그건 대체 얼마나 오래된 시간이야?",
  ui_story_1021_10210100_89_dialog_content = "북방에서 가장 오래된 눈소나무의 수령보다 긴 시간이야.\n전에 말했던 「세 그루 소나무」 이야기 기억나니?",
  ui_story_1021_10210100_90_dialog_content = "기억나!",
  ui_story_1021_10210100_91_dialog_content = "이곳에 북방이 세워지기 전, 세 그루의 위대한 눈소나무가 있었어.\n그 눈소나무들은 북방을 지키는 게 꿈이었고...",
  ui_story_1021_10210100_92_dialog_content = "하지만 다른 생물들은 그 생각을 비웃었어.\n고작 눈소나무가 어떻게 북방을 지키겠냐면서 말이야.",
  ui_story_1021_10210100_93_dialog_content = "그 후 전쟁 기간에, 벌목꾼이 그 세 그루의 눈소나무를 베어버렸어.",
  ui_story_1021_10210100_94_dialog_content = "하나는 건초를 기다리는 가축우리 신세가 됐고...",
  ui_story_1021_10210100_95_dialog_content = "하나는 테이블이 돼서 가난한 가정에 팔렸어...",
  ui_story_1021_10210100_96_dialog_content = "그리고 마지막 하나는 아무도 원하지 않아서 창고에 보관됐고,\n그 후 다시는 태양을 볼 수 없었어.",
  ui_story_1021_10210100_97_dialog_content = "오랜 시간이 지나고, 한 임신한 여자가 그 가축우리를 지나다가 거기서 한 아기를 낳았는데...",
  ui_story_1021_10210100_98_dialog_content = "그 눈소나무 위에서 태어난 아기가 바로 우리 북방의 위대한 첫 여왕님이었어!",
  ui_story_1021_10210100_99_dialog_content = "또 오랜 시간이 지나고, 여왕님은 그 가난한 가정 사람들을 도와주셨어.",
  ui_story_1021_10210100_100_dialog_content = "허름한 테이블 앞에서 가난한 가정의 사형제는 여왕님께 맹세했어.\n앞으로 대대로 왕실을 지켜나가겠다고...",
  ui_story_1021_10210100_101_dialog_content = "그리고 그 사형제의 자손이 바로 우리 북방 왕실의 호위야!",
  ui_story_1021_10210100_102_dialog_content = "아... 미안해, 안토니 선생님. 세 번째 눈소나무 이야기는 잊어버렸어...",
  ui_story_1021_10210100_103_dialog_content = "그 후 여왕님은 창고에서 그 눈소나무를 발견하고 지팡이를 만들었어...",
  ui_story_1021_10210100_104_dialog_content = "그렇게 북방의 모든 생명을 호령하고, 함께 북방을 지킬 수 있는 지팡이가 됐던 거야.",
  ui_story_1021_10210100_105_dialog_content = "눈소나무는 북방의 수호신이야.\n그들이 있기 때문에 우리의 터전은 대대로 평화롭고, 행복하게 살 수 있었던 거지...",
  ui_story_1021_10210100_106_dialog_content = "......",
  ui_story_1021_10210100_107_dialog_content = "어째서 이런...!",
  ui_story_1021_10210100_108_dialog_content = "여우들... 장로님... 여기 대체 무슨 일이 벌어졌던 거야?!",
  ui_story_1021_10210100_109_dialog_content = "......",
  ui_story_1021_10210100_110_dialog_content = "<color=#e8d9bb>아우우──!</color>",
  ui_story_1021_10210201_1_dialog_content = "<color=#e8d9bb>아스트라 연합 탐색 위원회 임시 지휘부</color>",
  ui_story_1021_10210201_2_dialog_content = "오랜만이야, PlayerName!",
  ui_story_1021_10210201_3_dialog_content = "오랜만이네, 웬디! 넌 역시 늘 정확한 시간에 온다니까!",
  ui_story_1021_10210201_4_dialog_content = "어, 엉켰잖아... 이 목도리 너무 귀찮아...",
  ui_story_1021_10210201_5_dialog_content = "헤에! 페피도 시간 맞춰 왔잖아? 그 트위티라는 재미있는 후배는?",
  ui_story_1021_10210201_6_dialog_content = "음... 솔직히 난 걔 좀 아닌 것 같아. 어엿한 쿠리어가 되려면 아직 멀었다고.",
  ui_story_1021_10210201_7_dialog_content = "네가 매번 빨리 오라고 하면 「하모예! 퍼뜩 갑니데이!」라고 하지만,\n사실은 어디서 떨어트린 편지를 줍고 있는지 누가 아냐고!",
  ui_story_1021_10210201_8_dialog_content = "휴! 하지만 걔가 성급하거나, 덜렁거리는 거나, 가끔 책임감이 부족해서 잘못하는 것도\n물론 선배로서 용서해 줄 수 없는 건 아냐...",
  ui_story_1021_10210201_9_dialog_content = "내가 보기엔 트위티는 널 닮은 것 같은데... 잠깐만, 그거 다 자기 얘기 아냐...?",
  ui_story_1021_10210201_10_dialog_content = "아, 아무튼 내가 선배로서 당연히 잘 챙겨줄 거야!",
  ui_story_1021_10210201_11_dialog_content = "저기, 누가 나한테 관심 좀 주지 않을래? 휴가 끝나자마자 비비안 님이 나한테\n더스크 타운인가 뭔가 하는 데 가서 연합 탐색 거점을 확인하고 오라고 하셨어...",
  ui_story_1021_10210201_12_dialog_content = "거긴 대체 뭐 하는 곳이냐고!\n조금만 쉬어도 모래바람에 다크매터가 섞여 있고, 주변이 온통 깜깜해서...",
  ui_story_1021_10210201_13_dialog_content = "하루 종일 멍하게 돼버려서 일할 기운이 전혀 안 났다니까...",
  ui_story_1021_10210201_14_dialog_content = "휴! 이 일도 진짜 못 해 먹겠어... 다음 달엔 꼭 새 일거리를 찾아야지...",
  ui_story_1021_10210201_15_option_content = "비비안 씨! 오셨어요?",
  ui_story_1021_10210201_16_dialog_content = "......!",
  ui_story_1021_10210201_17_dialog_content = "...라, 라고 주변 사람들이 자주 말하긴 하지만!\n난 비비안 님이 우리한테 잘해주시는 거라고 늘 말하고 있어!",
  ui_story_1021_10210201_18_dialog_content = "업무 분배도 합리적이고, 보수도 넉넉하고... 다양한 임무를 주니까 단련도 되고...\n이렇게 좋은 직업이 어디 있어...?",
  ui_story_1021_10210201_19_dialog_content = "...태세 전환 한번 빠르네.",
  ui_story_1021_10210201_20_option_content = "어둠의 밑바닥 탐색대에 온 걸 환영해.",
  ui_story_1021_10210201_21_dialog_content = "어둠의 밑바닥?! 제발 한 번만 봐줘... 어둠의 밑바닥 탐색을 가느니 쿠리어 일이 몇만 배는 나으니까!",
  ui_story_1021_10210201_22_dialog_content = "잘 생각해 보니까... 난 배달 시간도 유연하게 정할 수 있고, 활동도 자유롭고, 잘릴 걱정도 안 해도 돼...",
  ui_story_1021_10210201_23_dialog_content = "그러니까... 초대는 고맙지만, 이대로 쿠리어 일이나 해먹을... 아니, 최선을 다할게!",
  ui_story_1021_10210201_24_dialog_content = "...나 왠지 비비안 씨한테 「근로의욕 증진 감사패」 같은 거 하나 받을 수 있을 것 같은데?",
  ui_story_1021_10210201_25_dialog_content = "대원수님, 약속 시간이 되었는데 북방 측 대표가 아직 도착하지 않았어요.",
  ui_story_1021_10210201_26_dialog_content = "오전에 이미 북방에서 보낸 서신을 받았다. 먼저 정상적으로 회의를 진행하라더군.",
  ui_story_1021_10210201_27_dialog_content = "네, 대원수님.",
  ui_story_1021_10210201_28_dialog_content = "각 진영 대표 여러분, 아스트라 대륙 연합 탐색 제1차 회의에 참석해 주셔서 감사합니다.",
  ui_story_1021_10210201_29_dialog_content = "저는 일루미나 연방 참모장 비비안이에요.\n특별한 문제가 없다면 지금부터 회의를 시작하려고 해요.",
  ui_story_1021_10210201_30_dialog_content = "네, 문제없어요.",
  ui_story_1021_10210201_31_dialog_content = "섀도우마스터의 대리 자격으로 왔습니다. 저도 문제없습니다.",
  ui_story_1021_10210201_32_dialog_content = "아무래도 먼저 시작하는 수밖에 없겠군.",
  ui_story_1021_10210201_33_dialog_content = "그럼 정식으로 회의를 시작하도록 하지.",
  ui_story_1021_10210201_34_dialog_content = "이번에 이렇게 탁 트인 곳을 회의 장소로 선택한 건,\n우리가 햇빛 아래에서 함께 오로리안의 미래를 이야기할 수 있길 바라서예요.",
  ui_story_1021_10210201_35_dialog_content = "우선 거점 건설 작업에 도움을 제공해 주신 쿠리어 길드 여러분께 감사드립니다.",
  ui_story_1021_10210201_36_dialog_content = "각 진영이 신속하게 어둠의 밑바닥 탐색대의 동향에 호응할 수 있도록,\n쿠리어 길드는 앞으로도 다방면에 걸쳐 지원을 제공할 것이며...",
  ui_story_1021_10210201_37_dialog_content = "거점 간 정보 교환, 어둠의 밑바닥에 관한 단서 전달, 또한 감독 및 확인이라는\n중요한 책무를 쿠리어 길드가 담당하게 될 거예요.",
  ui_story_1021_10210201_38_dialog_content = "헤헤! 쿠리어 길드, 사명은 반드시 완수합니다!",
  ui_story_1021_10210201_39_dialog_content = "지금부터는 일루미나 연방 대원수님께서 여러분께 연합 탐색 계획을 소개하고,\n여러분의 의견을 듣는 시간을 가지겠습니다.",
  ui_story_1021_10210201_40_dialog_content = "이번 탐색 경로는 일전에 서신을 통해 이미 전달했던 내용대로다.",
  ui_story_1021_10210201_41_dialog_content = "우리는 어둠의 밑바닥 부근에 복수의 <color=#FFB400>전초 거점</color>을 구축하여,\n탐색 지원 및 정보 수집을 실시하고자 한다.",
  ui_story_1021_10210201_42_dialog_content = "각 진영의 지리적 분포를 고려해서, 아스트라 북부에 <color=#FFB400>세 개의 거점</color>을 설치할 예정이다.",
  ui_story_1021_10210201_43_dialog_content = "첫 번째 거점은 북서부의 <color=#FFB400>더스크 타운</color>에 설치한다.\n그곳의 규모와 세력은 탐색대의 어둠의 밑바닥 진입을 지원하는 후방 기지로 적합하다.",
  ui_story_1021_10210201_44_dialog_content = "일전에 백야성 성주와 나는 더스크 타운의 공동 통치에 있어 인식을 같이했고,\n이번 거점 건설은 그 합의에 대한 실질적 조치의 일환이다.",
  ui_story_1021_10210201_45_dialog_content = "더스크 타운에는 전략 집행 사령부를 창설해 탐색대에 필요한 지원을 담당하게 될 것이다.",
  ui_story_1021_10210201_46_dialog_content = "해당 거점의 책임자는 레오가 맡고, 총사령부에 탐색대의 동향을 정기적으로 보고한다.",
  ui_story_1021_10210201_47_dialog_content = "나머지 두 거점은 <color=#FFB400>헤븐즈 밸리</color>와 <color=#FFB400>북방</color>에 설치될 것이다.",
  ui_story_1021_10210201_48_dialog_content = "다만, 헤븐즈 밸리 지하 유적의 영향을 고려해서, 현재는 거점 건설 타당성을 평가하는 중이다.",
  ui_story_1021_10210201_49_dialog_content = "북방의 거점 건설은 환경의 특수성으로 인해 적지 않은 시간이 걸릴 것이다.\n북방의 여왕을 통해 확인을 진행하고 여러분에게 통지해 주도록 하겠다.",
  ui_story_1021_10210201_50_dialog_content = "마지막으로...",
  ui_story_1021_10210201_51_dialog_content = "어둠의 밑바닥 탐색 경로와 좌표 정보는 일루미나 연방 과학자 알골과\n우리의 핵심 정보원이 공동으로 완성한 것이다.",
  ui_story_1021_10210201_52_dialog_content = "정보의 신빙성과 안전성은 이미 여러 차례의 검증을 통해 확인이 끝났다.\n정보는 여러분에게 공유할 것이며, 여러분도 이를 활용하고 보완할 수 있길 바란다.",
  ui_story_1021_10210201_53_dialog_content = "이상의 내용에 대한 질문이 있나?",
  ui_story_1021_10210201_54_dialog_content = "이 정보를 수집하기 위해 일루미나도 적지 않은 대가를 치렀을 것이다.",
  ui_story_1021_10210201_55_dialog_content = "일루미나 연방에는 야심가도 적지 않지. 허나 이번 탐색은 오로리안의 미래가 달린 일이다.\n그대들은 정말 어둠의 밑바닥으로 향할 인선을 결정할 수 있는가?",
  ui_story_1021_10210201_56_dialog_content = "물론이지. 우리 일루미나는 야심으로 개인을 판단하지 않는다.\n오직 어려움을 이겨낼 용기와 결심이 있는지를 볼 뿐이다.",
  ui_story_1021_10210201_57_dialog_content = "이미 우리의 정예 인원으로 이루어진 <color=#FFB400>「탐색 소대」</color>가 어둠의 밑바닥에 선두로 전진하고 있다.\n그들이 후속 탐색을 위한 노선을 개척할 것이다.",
  ui_story_1021_10210201_58_dialog_content = "그리고 이번 탐색의 작전고문은 <color=#FFB400>바렛 박사</color>가 맡는다.\n이번에 사용할 비행기는 박사의 연구진이 개발한 것이다.",
  ui_story_1021_10210201_59_dialog_content = "정보부장 <color=#FFB400>필리시 중위</color>는 탐색대의 일상 및 통신 지원을 담당할 것이다.",
  ui_story_1021_10210201_60_dialog_content = "또한 우리의 지원 부대가 최종 테스트를 진행하고 있다.\n저들이 탐색대의 강력한 뒷받침이 되어줄 것이다.",
  ui_story_1021_10210201_61_dialog_content = "그대들이 제공한 정보를 바탕으로, 백야성도 정예 부대를 파견하여\n후속 부대를 위해 장애물을 제거하도록 하지.",
  ui_story_1021_10210201_62_dialog_content = "......",
  ui_story_1021_10210201_63_dialog_content = "(정예 부대를...? 백야성도 연합 탐색에서 주도권을 잡으려고 하는 건가?\n왠지 카렌도 성주님의 생각을 몰랐던 것 같은데...)",
  ui_story_1021_10210201_64_dialog_content = "백야성 부대는 여러분과 함께 싸우고, 탐색 작전에 전력으로 협조하겠어.",
  ui_story_1021_10210201_65_dialog_content = "음, 군사 물자는 이미 준비를 마쳤고, 출발 명령만 기다리고 있다.",
  ui_story_1021_10210201_66_dialog_content = "크흠... 흠흠... 움브라톤 총상회에서도 충분한 물자를 준비했어요.\n물자는 저희 상회가 순차적으로 출발 지점에 전달할 예정이에요.",
  ui_story_1021_10210201_67_dialog_content = "움브라톤은 탐색에 대한 경험은 부족하지만, 저희가 준비한 물자라면 <color=#FFB400>탐색대</color>가\n1년은 충분히 사용할 수 있을 거예요.",
  ui_story_1021_10210201_68_dialog_content = "움브라톤의 아낌없는 쾌척에 감사하지.",
  ui_story_1021_10210201_69_dialog_content = "이건 움브라톤에 있어서도 유익한 거래니까요.",
  ui_story_1021_10210201_70_dialog_content = "구체적인 출발 일시에 대해서는 최대한 빠르게 통지하도록 하겠다.",
  ui_story_1021_10210201_71_dialog_content = "(이게 바로 「저마다 각자의 강점」을 살린다는 건가...)",
  ui_story_1021_10210201_72_dialog_content = "PlayerName, 뭔가 하고 싶은 말이 있어 보이는군.",
  ui_story_1021_10210201_73_dialog_content = "으앗... 음... 전 여러분한테 제공할 수 있는 물자는 없지만,\n대신 동료를 지키겠다는 마음은 가지고 있어요!",
  ui_story_1021_10210201_74_dialog_content = "이번에 탐색하려는 곳은 무척 위험해요. 부대의 안전은 제가 꼭 지킬게요.",
  ui_story_1021_10210201_75_dialog_content = "제 동료들이 다치거나, 갑자기 사라지는 일이 없게 말이에요...",
  ui_story_1021_10210201_76_dialog_content = "......",
  ui_story_1021_10210201_77_dialog_content = "(...내가 뭔가 말실수를 했나...?)",
  ui_story_1021_10210201_78_dialog_content = "PlayerName 씨, 상회의 도움이 필요하면 언제든지 말씀해 주세요.",
  ui_story_1021_10210201_79_dialog_content = "고마워, 베델. 그렇게 할게.",
  ui_story_1021_10210201_80_dialog_content = "주요 의제는 논의를 마친 것 같군. 그렇다면 한담 몇 마디를 하도록 하지.",
  ui_story_1021_10210201_81_dialog_content = "내가 젊을 적에, 나는 성주가 된 후 내가 가고자 하는 곳을 직접 순시할 수 있길 원했다.",
  ui_story_1021_10210201_82_dialog_content = "허나 이제 보니, 백야성을 잘 다스리는 데 힘쓰는 것만으로 이미 이 나이가 되어 버렸더군.",
  ui_story_1021_10210201_83_dialog_content = "백야성의 성주로서, 나는 내 여생 중에 그대들 젊은이들의 눈을 통하여\n한층 더 먼 세계를 볼 수 있길 바란다.",
  ui_story_1021_10210201_84_dialog_content = "또한 개인으로서, 비록 이번 탐색이 어려울지라도, 카렌이 그대들과 함께\n새로운 시대의 탄생을 목도할 수 있길 바란다.",
  ui_story_1021_10210201_85_dialog_content = "성주님...",
  ui_story_1021_10210201_86_dialog_content = "우리의 이번 탐색이 새로운 시대를 열 거라고 믿으시나요?",
  ui_story_1021_10210201_87_dialog_content = "물론이다. 오히려 그대가 아스트라 대륙에 나타나 수수께끼를 하나씩 풀어나갔을 때부터,\n이미 새로운 시대가 시작되고 있었다고 말할 수 있겠지.",
  ui_story_1021_10210201_88_dialog_content = "우리도 탐색을 전력으로 지원할 것이다.\n아스트라 대륙의 미래는 이미 그대들의 손안에 있으니 말이야.",
  ui_story_1021_10210201_89_dialog_content = "로이 오빠도 와서 좀 도와줘! 나 혼자서는 너무 힘들다구!",
  ui_story_1021_10210201_90_dialog_content = "다들 나이가 들면 쓰레기가 줍고 싶어진다고들 하던데,\n이 아저씨는 오늘 저녁 스테이크에 무슨 소스가 좋을지만 생각하고 있다고...",
  ui_story_1021_10210201_91_dialog_content = "에──엣취!",
  ui_story_1021_10210201_92_dialog_content = "이 비행기, 새롭긴 한데, 이 코를 찌르는 공업화의 냄새... 꼭 후추를 뿌린 것 같잖아. 으엣취──!",
  ui_story_1021_10210201_93_dialog_content = "역시 사메야마 대장은 늘 철두철미하다니까. 아이테르 쪽 이번 탐색에도 흥미가 있는 모양이야.\n헤에, 이 비행기, 우리도 제대로 연구해 보는 게 좋겠어. 뭔가 쓸모가 있을지도 모르니까!",
  ui_story_1021_10210201_94_dialog_content = "사메야마 녀석도 참, 귀찮은 일에 끼어들기 좋아하는 건 변하질 않는다니까... 야, 타이니, 가자!",
  ui_story_1021_10210201_95_dialog_content = "새 기계들은 냄새가 빠지려면 시간이 좀 걸릴 거예요. 카렌 씨가 너무 불편해하진 않았으면 좋겠네요.",
  ui_story_1021_10210201_96_dialog_content = "아, 괜찮아. 냄새엔 민감하지도 않고.",
  ui_story_1021_10210201_97_dialog_content = "오늘 아침 북방 여왕의 서신을 받았다. 거점 건설을 며칠 늦춰야 한다고 하더군.\n구체적인 원인은 밝히지 않았지만, 맹우 관계로서 더 캐묻는 것도 좋지 않겠지.",
  ui_story_1021_10210201_98_dialog_content = "하지만 탐색은 각 거점 간의 협조가 필요하다. 지금 일루미나는 별도로 차출할 인력이 없다.",
  ui_story_1021_10210201_99_dialog_content = "따라서 이번에는 두 사람이 대신 수고해 주었으면 한다.",
  ui_story_1021_10210201_100_dialog_content = "좋아. 그동안 일이 있어서 나도 북방에 안 가본 지 꽤 됐으니까.",
  ui_story_1021_10210201_101_dialog_content = "그럼 마침 잘 됐군.\n카렌 공주는 이참에 PlayerName에게 비행기 조작을 배워두는 것도 좋을 거다.",
  ui_story_1021_10210201_102_dialog_content = "맡겨 주세요. 스카이워커와는 조금 다르지만... 꽤 많은 곳의 설계에 익숙한 느낌이 들거든요.",
  ui_story_1021_10210201_103_dialog_content = "요즘은 혼자서 아스트라를 반 바퀴 정도 돌 수 있게 됐어요.",
  ui_story_1021_10210201_104_dialog_content = "그럼 부탁한다. 무슨 일 있으면 언제든지 연락해라. 통신 설비는 이미 체크해 뒀으니까.",
  ui_story_1021_10210201_105_dialog_content = "잘 다녀오세요!",
  ui_story_1021_10210201_106_dialog_content = "응!",
  ui_story_1021_10210201_107_dialog_content = "대원수님, PlayerName한테 레디젤 렌치의 두 녀석도 있다고 언질을 줘야 할까요?",
  ui_story_1021_10210201_108_dialog_content = "괜찮다. 탐색 중엔 흔히 있는 일이니까, 스스로 대처할 수 있을 거다.",
  ui_story_1021_10210201_109_dialog_content = "게다가 레디젤 렌치도 이번 탐색에 참가하겠다고 떠들었었잖아?",
  ui_story_1021_10210301_1_dialog_content = "<color=#e8d9bb>얼마 후...</color>",
  ui_story_1021_10210301_2_dialog_content = "저번엔 일루미나의 비행기는 익숙하지 않을 것 같다고 조금 걱정했었는데.",
  ui_story_1021_10210301_3_dialog_content = "공간이 많이 좁아진 것만 제외하면 스카이워커호와 비슷한 느낌이야.\n어느새 곧 북방에 도착하겠어.",
  ui_story_1021_10210301_4_dialog_content = "거 봐, 내가 괜찮을 거라고 했지?",
  ui_story_1021_10210301_5_dialog_content = "그럼 하강하기 전에 카렌 너도 한번 조종해 볼래?\n아까 이륙했을 때도 봤겠지만 사실 꽤 간단하거든.",
  ui_story_1021_10210301_6_dialog_content = "그...그럼 알려줘. 해 볼게.",
  ui_story_1021_10210301_7_dialog_content = "응, 일단 여기 컨트롤러에 전부 표시가...",
  ui_story_1021_10210301_8_dialog_content = "<color=#e8d9bb>쿠구구구──!</color>",
  ui_story_1021_10210301_9_dialog_content = "으앗──!",
  ui_story_1021_10210301_10_dialog_content = "무, 무슨 일이야? 나 아직 아무것도 안 만졌어!",
  ui_story_1021_10210301_11_dialog_content = "괘, 괜찮아...! 아마 난기류 때문일 거야...",
  ui_story_1021_10210301_12_dialog_content = "이런 급강하 느낌은... 일단 조종 레버부터 올리고, 그리고...",
  ui_story_1021_10210301_13_dialog_content = "<color=#e8d9bb>삐익── 삐익── 삐익── 삐익──</color>",
  ui_story_1021_10210301_14_dialog_content = "이런──!",
  ui_story_1021_10210301_15_dialog_content = "<color=#e8d9bb>삐익── 삐익── 삐익── 삐익──</color>",
  ui_story_1021_10210301_16_dialog_content = "로이 오빠! 찾았어?! 아니면... 그냥 우리가 떳떳하게 나가서 조종하자!",
  ui_story_1021_10210301_17_dialog_content = "지금 나가도 오해만 커지고 귀찮아질 뿐이야. 내가 알아서... 이제 거의...\n에이, 안 되겠어. 너무 어두워서 힘이 안 들어가...",
  ui_story_1021_10210301_18_dialog_content = "여기 불빛 있어!",
  ui_story_1021_10210301_19_dialog_content = "...거 되게 눈부시네... 그나저나 우리 어디까지 온 거야?",
  ui_story_1021_10210301_20_dialog_content = "레디젤 사막에서 최소 몇백 킬로미터는 오지 않았을까?\n밖이 점점 하얘지고 있는데, 설마 북방까지 온 건 아니겠지...?",
  ui_story_1021_10210301_21_dialog_content = "그럼 이런 심한 난기류가 이상할 것도 없지...",
  ui_story_1021_10210301_22_dialog_content = "쳇... 이 구조, 내가 생각했던 거랑 다르잖아. 아무래도 못 고치겠어.",
  ui_story_1021_10210301_23_dialog_content = "생각했던 거랑 다르다는 게 지금 할 말이야? 목숨이 달린 일이라구! 내가 해 볼게!",
  ui_story_1021_10210301_24_dialog_content = "...방금 승강키가 이상하다고 했지?",
  ui_story_1021_10210301_25_dialog_content = "뭐, 대충 그런 셈이야. 일루미나의 비행기는 애초에 등속 조인트 같은 건 전혀 없다고...",
  ui_story_1021_10210301_26_dialog_content = "...그거야 등속 조인트가 부러져 버렸으니까 그렇지!",
  ui_story_1021_10210301_27_dialog_content = "그런가... 그럼 뭔가 쓸 만한 게 없는지 주머니 좀 뒤져 볼까. 일단 렌치로 버티고 좀 있어 봐.",
  ui_story_1021_10210301_28_dialog_content = "로이 오빠... 위기감이란 걸 좀 가져 봐!",
  ui_story_1021_10210301_29_dialog_content = "<color=#e8d9bb>쿠르릉──!</color>",
  ui_story_1021_10210301_30_dialog_content = "으앗...!",
  ui_story_1021_10210301_31_dialog_content = "사, 살았다! 카렌, 괜찮아?",
  ui_story_1021_10210301_32_dialog_content = "카렌? 어라, 왜 바닥에 피가... 설마... 카렌!!",
  ui_story_1021_10210301_33_dialog_content = "......!",
  ui_story_1021_10210301_34_dialog_content = "다시는... 비행기 같은 건 안 탈 거야!",
  ui_story_1021_10210301_35_dialog_content = "(괜찮은 모양이네...)",
  ui_story_1021_10210301_36_dialog_content = "응... 그래... 타지 말자... 다 내 탓이야...",
  ui_story_1021_10210301_37_dialog_content = "그나저나 북방에서 이런 격렬한 난기류를 맞을 거란 생각은 못 했어...",
  ui_story_1021_10210301_38_dialog_content = "......",
  ui_story_1021_10210301_39_dialog_content = "모, 모험엔 이런 일도 흔히 따르는 법이니까...",
  ui_story_1021_10210301_40_dialog_content = "아무튼 마지막에 조종 레버가 다시 반응해 줘서 다행이야...",
  ui_story_1021_10210301_41_dialog_content = "어라...?! 꼬리날개가 이런 각도가 돼버렸는데 무사히 착륙하다니...",
  ui_story_1021_10210301_42_dialog_content = "네 조종 기술을 칭찬해 줬으면 좋겠다는 거야?",
  ui_story_1021_10210301_43_dialog_content = "아, 아니... 뭐, 뭐라고 말해야 할지...",
  ui_story_1021_10210301_44_dialog_content = "<color=#e8d9bb>아우우──!</color>",
  ui_story_1021_10210301_45_dialog_content = "여긴... 맹수의 영역인가...? 주변이 온통 핏자국이야...",
  ui_story_1021_10210301_46_dialog_content = "확실히 최근에 벌어진 듯한 싸움의 흔적이 있어...\n여긴 윈터 팰리스에서 꽤 거리가 될 텐데, 어쩌면 암귀일지도 몰라...",
  ui_story_1021_10210301_47_dialog_content = "암귀라... 그럼 여긴 등대의 힘이 미치지 않는 곳인 거네...",
  ui_story_1021_10210301_48_dialog_content = "등대 바깥의 북방은 네가 생각하는 것보다 훨씬 넓어. 특히 북부는 암귀가 활개 치고 있고...",
  ui_story_1021_10210301_49_dialog_content = "전에 듣긴 했었지만, 직접 보니까 이렇게 무서운 광경일 줄은 몰랐어...",
  ui_story_1021_10210301_50_dialog_content = "......",
  ui_story_1021_10210301_51_dialog_content = "...저쪽에서 사람 목소리가 들려!",
  ui_story_1021_10210301_52_dialog_content = "보러 가 보자.",
  ui_story_1021_10210301_53_dialog_content = "흥!",
  ui_story_1021_10210301_54_dialog_content = "아가씨, 그렇게 쳐다본다고 답이 나오는 것도 아니라니까.\n우리도 어쩔 수 없이 오게 된 거라고 했잖아.",
  ui_story_1021_10210301_55_dialog_content = "비행기 안에 내 파일럿 명찰이 있어. 못 믿겠으면 기다려 봐. 가져와서 보여줄 테니까...",
  ui_story_1021_10210301_56_dialog_content = "로이 오빠, 우리가 파일럿 명찰이 어디 있어?",
  ui_story_1021_10210301_57_dialog_content = "쓰읍... 꼬맹이들 데리고 나올 때마다 꼭 귀찮은 일이 생긴다니까.\n명찰 또 잃어버렸지? 내가 찾아올게!",
  ui_story_1021_10210301_58_dialog_content = "거기 서!",
  ui_story_1021_10210301_59_dialog_content = "가게 두어라.",
  ui_story_1021_10210301_60_dialog_content = "장로님! 어, 어떻게 여기 계시죠?! 장로님은...",
  ui_story_1021_10210301_61_dialog_content = "걱정할 필요 없다.",
  ui_story_1021_10210301_62_dialog_content = "하지만 부락이 하룻밤 사이에 이렇게 변했는데, 제가 어떻게 걱정을 안 해요?!\n검은 피를 흘린 여우들 못 보셨어요?!",
  ui_story_1021_10210301_63_dialog_content = "그대는 이곳에 오지 말았어야 한다.",
  ui_story_1021_10210301_64_dialog_content = "장로님은 늘 저보고 가라고만 하시지만... 여긴 제 고향이라구요...!",
  ui_story_1021_10210301_65_dialog_content = "...티아라?",
  ui_story_1021_10210301_66_dialog_content = "자, 내가 펼친 보호막 안으로 몸을 피하도록 해라.",
  ui_story_1021_10210301_67_dialog_content = "저는 여왕 폐하의 호위로서 정말 실격입니다!",
  ui_story_1021_10210301_68_dialog_content = "저를 버려두고 여왕 폐하 혼자서 암귀와 맞서지 말아 주세요!",
  ui_story_1021_10210301_69_dialog_content = "티아라가 여왕 폐하를 위해 적진에 돌격하겠습니다!",
  ui_story_1021_10210301_70_dialog_content = "여왕 폐하의 호위...?",
  ui_story_1021_10210301_71_dialog_content = "당신들...",
  ui_story_1021_10210301_72_dialog_content = "당신은 왜 여기 있지? 여기서... 무슨 일이 있었던 거야?",
  ui_story_1021_10210301_73_dialog_content = "......",
  ui_story_1021_10210301_74_dialog_content = "(...그 전설의 눈여우인가? 저 눈빛... 왠지 나보고 가라고 말하고 있는 것 같아...)",
  ui_story_1021_10210301_75_dialog_content = "우린... 여왕 폐하를 알현하러 왔어.\n하지만 비행기가 난기류에 휘말려서 여기 불시착할 수밖에 없었어.",
  ui_story_1021_10210301_76_dialog_content = "......",
  ui_story_1021_10210301_77_dialog_content = "...방해가 되었다면 미안해.",
  ui_story_1021_10210301_78_dialog_content = "그럼 다른 두 사람도 당신들이랑 같이 온 거야?",
  ui_story_1021_10210301_79_dialog_content = "어떤 두 사람?",
  ui_story_1021_10210301_80_dialog_content = "...방금까지 여기 있었다고!",
  ui_story_1021_10210301_81_dialog_content = "손에 이상한 걸 들고, 내 친구들을 가리키고 있었어.\n자기들이 비행기 파일럿이라고 했고 말이야.",
  ui_story_1021_10210301_82_dialog_content = "비행기엔 나랑 카렌 둘밖에 없었는데...",
  ui_story_1021_10210301_83_dialog_content = "그럴 리 없어!",
  ui_story_1021_10210301_84_dialog_content = "티아라, 일단 진정해.",
  ui_story_1021_10210301_85_dialog_content = "만약 그 두 사람이 당신이나 당신 친구에게 상처를 줬다면,\n나도 PlayerName도 결코 그 사람들을 용서하지 않을 거야.",
  ui_story_1021_10210301_86_dialog_content = "그런데 방금 여기가 당신 고향이라고 했지...?",
  ui_story_1021_10210301_87_dialog_content = "...여긴 북방의 변경 지대야. 여기 암귀가 출몰했다고 해서...",
  ui_story_1021_10210301_88_dialog_content = "난... 여왕 폐하의 명을 받고 이 눈소나무 숲을 순찰하고 있었어.",
  ui_story_1021_10210301_89_dialog_content = "그렇구나... 그럼 순찰이 끝나면 우릴 여왕 폐하께 데려다 줄 수 있을까?",
  ui_story_1021_10210301_90_dialog_content = "우리도 지금은 윈터 팰리스로 가는 길을 모르겠거든.\n만약 암귀랑 싸워야 한다면 우리도 도울 수 있어!",
  ui_story_1021_10210301_91_dialog_content = "<color=#e8d9bb>아우우──!</color>",
  ui_story_1021_10210301_92_dialog_content = "안 돼!",
  ui_story_1021_10210301_93_dialog_content = "음, 내 말은 그러니까... 여긴 무척 위험한 곳이고, 윈터 팰리스까지 많이 멀기도 해.\n아무튼 일단 여길 빨리 떠나는 게 좋을 거야.",
  ui_story_1021_10210301_94_dialog_content = "(어라... 저건...)",
  ui_story_1021_10210301_95_dialog_content = "(티아라, 뭔가 이상해...)",
  ui_story_1021_10210301_96_dialog_content = "저기, 여기서 대체 무슨 일이 있었는지 말해줄 수 있을까?",
  ui_story_1021_10210301_97_dialog_content = "......",
  ui_story_1021_10210301_98_dialog_content = "여왕 폐하를 알현하러 가겠다는 거 아니었어...?",
  ui_story_1021_10210301_99_dialog_content = "저기 저 토끼 발자국을 따라가. 그럼 뵐 수 있을 거야.",
  ui_story_1021_10210301_100_dialog_content = "만약 여왕 폐하를 뵈면 나 대신 말씀 좀 전해드려 줘...\n발자국은 깨끗이 청소하겠지만, 그게 지금은 아니라고.",
  ui_story_1021_10210301_101_dialog_content = "......",
  ui_story_1021_10210301_102_dialog_content = "엄청 빨리 가버렸네...",
  ui_story_1021_10210301_103_dialog_content = "북방에 정말 눈여우 부락이 있을 줄은 몰랐어...",
  ui_story_1021_10210301_104_dialog_content = "전에 북방에서 유학할 때 현지인에게서 이야기를 하나 들은 적 있어...",
  ui_story_1021_10210301_105_dialog_content = "북방 북서쪽엔 한때 눈소나무 숲에 의지해서 모여 사는 눈여우 부락이 있었다고.",
  ui_story_1021_10210301_106_dialog_content = "저들은 눈소나무 숲과 그 아래에 잠들어 있는 유적을 지켜왔다고 해.",
  ui_story_1021_10210301_107_dialog_content = "하지만 아무도 본 적이 없었기 때문에, 그 전설이 진짜인지 아는 사람도 없었지.\n대신 오로리안을 배척한다는 점은 왠지 진짜인 것 같네...",
  ui_story_1021_10210301_108_dialog_content = "너도 티아라가 다친 눈여우를 감싸듯 가로막은 모습 봤지?",
  ui_story_1021_10210301_109_dialog_content = "응... 그리고 그 나이 든 눈여우가 우릴 보는 눈은... 마치 오랜 원수를 보는 것만 같았어...",
  ui_story_1021_10210301_110_dialog_content = "저 혈흔들은 아마 눈여우가 흘린 피일 거야.",
  ui_story_1021_10210301_111_dialog_content = "핏자국이 검은 것도 있고, 붉은 것도 있고... 보고 있으면 왠지 머리가 아파져...",
  ui_story_1021_10210301_112_dialog_content = "눈여우 중에는 자연의 힘을 가지고 태어난 「산의 정령」이 있는데,\n자연이 다크매터에 침식되면 저들의 몸도 병에 걸린다고 해.",
  ui_story_1021_10210301_113_dialog_content = "네가 지금 느낌이 불편해진 건 아마 저 혈흔 속에 남은 다크매터 때문일지도 몰라.",
  ui_story_1021_10210301_114_dialog_content = "다크매터... 그럼 티아라가 여왕 폐하한테 전하라고 한 말도 그렇게 간단한 일이 아니겠네...",
  ui_story_1021_10210301_115_dialog_content = "지금까지의 상황으로 보면, 아무래도 암귀가 북방에 침입해서 눈여우를 해쳤고,\n거점까지 파괴한 것 같아...",
  ui_story_1021_10210301_116_dialog_content = "그래서 여왕 폐하는 사절을 보내지 않으신 거구나...",
  ui_story_1021_10210301_117_dialog_content = "그럼 티아라도 위험해!",
  ui_story_1021_10210301_118_dialog_content = "쫓아가자! 혹시라도 무슨 일이 생기면 우리도 도와줄 수 있잖아.",
  ui_story_1021_10210301_119_dialog_content = "혈흔을 따라가 보자! 변경 지대는 암귀가 많으니까, 우리도 조심해야 해!",
  ui_story_1021_10210401_1_dialog_content = "핏자국이 사라졌잖아...? 혈흔을 너무 많이 봐서 그런가... 머리가 점점 더 어지러워...",
  ui_story_1021_10210401_2_dialog_content = "감응 능력으로... 단서를 찾아볼게...",
  ui_story_1021_10210401_3_dialog_content = "PlayerName, 너 저번 일 이후로 한 번도 감응 능력을 안 쓴 거 알아. 이제... 무섭지 않아?",
  ui_story_1021_10210401_4_option_content = "으음...",
  ui_story_1021_10210401_5_dialog_content = "확실히 꽤 오랫동안... 감응 능력만 생각하면 복잡한 기분이 들긴 했어...",
  ui_story_1021_10210401_6_option_content = "아직 조금 무서워.",
  ui_story_1021_10210401_7_dialog_content = "그동안 난 감응 능력만 생각하면 마음이 복잡해지곤 했어...",
  ui_story_1021_10210401_8_dialog_content = "또 아득한 과거의 장면이 보이거나, 엔지니어에게 다시 주시당할까 걱정인 거지?",
  ui_story_1021_10210401_9_dialog_content = "응. 바이스나 스카이워커에 대한 안 좋은 소식이 보이거나 들리지 않을까도 걱정돼...",
  ui_story_1021_10210401_10_dialog_content = "그 둘이 너한테 미치는 영향이 아주 크다는 건 나도 알아. 하지만...",
  ui_story_1021_10210401_11_dialog_content = "...아니, 지금은 제쳐둘 수밖에 없어.\n감응 능력은 내가 싸울 수 있는 유일한 힘이고, 그게 곧 모두를 지키는 방법이니까.",
  ui_story_1021_10210401_12_dialog_content = "그러니까 무슨 일이 있어도 공포를 이겨내고, 감응 능력을 더 잘 쓸 수 있도록 연습해야지!",
  ui_story_1021_10210401_13_dialog_content = "걱정해 줘서 고마워, 카렌. 이젠 괜찮아.",
  ui_story_1021_10210401_14_dialog_content = "PlayerName 네가 빨리 기운을 낼 수 있어서 나도 기뻐.",
  ui_story_1021_10210401_15_dialog_content = "잊지 마, 내가 계속 곁에 있을 거야. 감응 중에 뭔가 위험한 일이 생기면 나도 같이 맞설게.",
  ui_story_1021_10210401_16_dialog_content = "응!",
  ui_story_1021_10210401_17_option_content = "(감응 연결──)",
  ui_story_1021_10210401_18_dialog_content = "(텅 빈 동굴...)",
  ui_story_1021_10210401_19_dialog_content = "(여기 얼음은... 생긴 지 꽤 오래된 것 같아.)",
  ui_story_1021_10210401_20_dialog_content = "...만약 레디젤 랠리에 참가한다면 분명히 우승할걸...",
  ui_story_1021_10210401_21_dialog_content = "발로 어떻게 네 바퀴랑 겨뤄? 어라? 잠깐만... 이 냄새 느꼈어?",
  ui_story_1021_10210401_22_dialog_content = "(...이 목소리... 어디서 들려오는 거지?)",
  ui_story_1021_10210401_23_dialog_content = "(...검은색이랑 붉은색 핏자국이야! 땅에 있던 거랑 같아!)",
  ui_story_1021_10210401_24_dialog_content = "(적어도 아직은 내 의식을 제어할 수 있어...)",
  ui_story_1021_10210401_25_dialog_content = "(참, 티아라는 여기 왔었어... 이 동굴은 눈소나무 숲 아래에 있는 건가...?)",
  ui_story_1021_10210401_26_dialog_content = "이 썩은 냄새... 레디젤 오일의 향기가 그리워지게 만든단 말이지...",
  ui_story_1021_10210401_27_dialog_content = "...얼른 조명 꺼. 이따가 무슨 이상한 괴물이라도 끌어들였다간\n우리가 이 추운 곳까지 온 것도 전부 헛고생이 될 테니까.",
  ui_story_1021_10210401_28_dialog_content = "왜 설원으로 안 걷고 이런 곳에 숨어 있어야 하는 거냐고...\n이젠 길을 물어볼 사람조차 없잖아.",
  ui_story_1021_10210401_29_dialog_content = "로이 오빠가 제일 싫어하는 곳이 「지하」라고 그러지 않았어?",
  ui_story_1021_10210401_30_dialog_content = "(이 두 사람이 왜 여기 있어?!)",
  ui_story_1021_10210401_31_dialog_content = "(여긴 갈림길이 많아... 두 사람은 어디서 들어온 거지...?)",
  ui_story_1021_10210401_32_option_content = "(감응 확장──)",
  ui_story_1021_10210401_33_dialog_content = "......",
  ui_story_1021_10210401_34_dialog_content = "뭐가 보였어?",
  ui_story_1021_10210401_35_dialog_content = "티아라가 말했던 불순한 침입자는 내가 아는 레디젤 렌치의 친구들이었어...",
  ui_story_1021_10210401_36_dialog_content = "...그리고 시야를 넓혔을 때 왠지 증기처럼 팽창하는 다크매터를 본 것 같았어...",
  ui_story_1021_10210401_37_dialog_content = "여기서 아주 가까워...",
  ui_story_1021_10210401_38_dialog_content = "......!",
  ui_story_1021_10210401_39_dialog_content = "게다가 동굴 안엔 설원에서 본 거랑 똑같은 혈흔이 있었어... 티아라도 분명히 거기 있을 거야...",
  ui_story_1021_10210401_40_dialog_content = "그럼 서두르자! 어느 방향으로 가야 해?",
  ui_story_1021_10210401_41_dialog_content = "핏자국은 여기서 끊겼어. 그럼 동굴은 이 눈소나무 숲 뒤일 거야. 따라와!",
  ui_story_1021_10210401_42_dialog_content = "(티아라, 그리고 로이 씨랑 타이니... 제발 무사해야 해...)",
  ui_story_1021_10210401_43_dialog_content = "<color=#e8d9bb>아우우...</color>",
  ui_story_1021_10210401_44_dialog_content = "위대하신 옛 신령이시여, 당신께서 우리를 영원히 지켜봐 주시듯이,\n티아라는 영원토록 당신을 삼가 우러러볼 것입니다.",
  ui_story_1021_10210401_45_dialog_content = "검은 그림자가 다시 드리우고, 포식자처럼 우리의 몸을 갉아먹으며,\n우리의 몸에 결코 지워지지 않는 낙인을 남기고 있습니다.",
  ui_story_1021_10210401_46_dialog_content = "윈터 팰리스에서는 저는 여왕 폐하의 호위이나...",
  ui_story_1021_10210401_47_dialog_content = "이곳에서는 부락을 지키겠노라 맹세한 부족의 우두머리입니다.",
  ui_story_1021_10210401_48_dialog_content = "당신께서는 부족을 기르시고, 신성한 혈맥을 내려주사 우리가 당신과 이어지게 하셨습니다.",
  ui_story_1021_10210401_49_dialog_content = "그러나 지금 남겨진 제 일족들은 밤낮으로 고통에 신음하고, 육체는 궤멸해 버렸습니다...\n우리가 언젠가 당신의 품으로 돌아갈 날이 오리라는 것은 알고 있습니다.",
  ui_story_1021_10210401_50_dialog_content = "다만 당신께서 우리의 선조와 그 부족에 가호를 베푸셨듯이,\n다시 한번 그 자애를 우리에게 베풀어 주시길 간청하나이다.",
  ui_story_1021_10210401_51_dialog_content = "<color=#e8d9bb>아우우──!</color>",
  ui_story_1021_10210401_52_dialog_content = "실수로 이 땅에 들어선 그 오로리안들이 위험에 처했다.\n그러나 나는 이제 저들을 몰아낼 힘이 없다...",
  ui_story_1021_10210401_53_dialog_content = "장로님, 그건 애초에 제 의무잖아요...",
  ui_story_1021_10210401_54_dialog_content = "티아라! 그대의 손에 쥔 창을 보아라!\n그대는 북방의 호위... 더는 이곳에 마음을 두지 마라...",
  ui_story_1021_10210401_55_dialog_content = "...콜록, 콜록콜록...",
  ui_story_1021_10210401_56_dialog_content = "장로님... 제발 부탁이에요... 일족이 멸망하는 걸 보고만 있을 순 없어요...!",
  ui_story_1021_10210401_57_dialog_content = "그대는... 돌아와서는 아니 된다...",
  ui_story_1021_10210401_58_dialog_content = "대체... 제가 어떻게 해야...",
  ui_story_1021_10210401_59_dialog_content = "<color=#e8d9bb>똑── 똑──</color>",
  ui_story_1021_10210401_60_dialog_content = "으앗──!",
  ui_story_1021_10210401_61_dialog_content = "길이 얼어서 미끄러우니까 조심해. 아니지... 여긴 왜 물방울이 떨어지고 있는 거지?",
  ui_story_1021_10210401_62_dialog_content = "이미 오면서 웅덩이를 여러 개 밟았어.\n아까 삐끗한 건 아마 이 괴로운 냄새에 머리가 어지러워서 그런 것 같아...",
  ui_story_1021_10210401_63_dialog_content = "잠깐만! 뭔가 부드러운 걸 밟은 느낌인데... 뭔지 좀 봐 줘...",
  ui_story_1021_10210401_64_dialog_content = "왠지... 눈여우 같아...",
  ui_story_1021_10210401_65_dialog_content = "아직... 살아 있어...?",
  ui_story_1021_10210401_66_dialog_content = "......",
  ui_story_1021_10210401_67_dialog_content = "아, 안 되겠어... 갑자기 눈앞이 하얘진 것 같아...",
  ui_story_1021_10210401_68_dialog_content = "정신 차려. 앞에 정말 뭔가 하얀빛이 있어...",
  ui_story_1021_10210401_69_dialog_content = "<color=#e8d9bb>똑── 똑──</color>",
  ui_story_1021_10210401_70_dialog_content = "타이니, 내 착각인가? 이렇게 걷다가 왠지 집까지 갈 것 같은 느낌인데...",
  ui_story_1021_10210401_71_dialog_content = "점점 더워지고 있다고... 근육이 나도 모르는 새에 풀어졌다니까.",
  ui_story_1021_10210401_72_dialog_content = "그럼 이 보석 받아.",
  ui_story_1021_10210401_73_dialog_content = "그게 무슨 소리야... 공짜로 주운 것도 안 가질 셈이야? 그러면 안 되지...",
  ui_story_1021_10210401_74_dialog_content = "으아아! 머리 만지지 마! 로이 오빠 손에 땀 잔뜩 났잖아!",
  ui_story_1021_10210401_75_dialog_content = "어, 어이...! 갑자기 눈에다 빛 쏘지 마! 나 그런 거 못 참는다고...\n그리고 말했잖아. 괜히 불을 켜면 귀찮은 녀석이 꼬일 거라니까.",
  ui_story_1021_10210401_76_dialog_content = "어이, 거기 둘!",
  ui_story_1021_10210401_77_dialog_content = "거 봐, 내가 뭐랬어...",
  ui_story_1021_10210401_78_dialog_content = "아, 안녕...",
  ui_story_1021_10210401_79_dialog_content = "여어, PlayerName, 너희도 보물찾기 중이냐?",
  ui_story_1021_10210401_80_dialog_content = "보물찾기?! 당신들, 왜 우리 비행기에 숨어들었지?",
  ui_story_1021_10210401_81_dialog_content = "사메야마 그 자식, 명단 제출을 까먹은 모양인데?\n우린 레디젤 렌치 대표로 아스트라 대륙 연합 탐색 회의에 참가하러 왔어.",
  ui_story_1021_10210401_82_dialog_content = "근데 너네 회의가 그렇게 지루할 줄은 몰랐지.\n그래서 좀 자다가 일어났더니 이런 곳에 오게 됐지 뭐야...",
  ui_story_1021_10210401_83_dialog_content = "당신들 그 큰 가방! 북방의 보석을 훔치려고 준비한 거지?!\n충고하는데, 어디서 손댄 게 있다면 제자리에 돌려놔!",
  ui_story_1021_10210401_84_dialog_content = "여...여기가 북방이었어?\n허허, 이 아저씨는 레디젤 사막에서 나와본 적도 없는데 보석이 어디 있는지 어떻게 알겠어?!",
  ui_story_1021_10210401_85_dialog_content = "뭐, 우리가 아까 겸사겸사 너희 기계를 고쳤는데, 답례로 이걸 준다면 사양 안 할게.",
  ui_story_1021_10210401_86_dialog_content = "당신들──!",
  ui_story_1021_10210401_87_dialog_content = "카렌, 잠깐만... 어떻게 된 건지 알 것 같아.",
  ui_story_1021_10210401_88_dialog_content = "이 사람들은 레디젤 렌치에서도 무척 우수한 엔지니어들이야.\n비행기 안에서 제어실과 먼 곳이라면 꼬리날개 근처의 수리실밖에 없어.",
  ui_story_1021_10210401_89_dialog_content = "꼬리날개가 그 지경이 됐는데도 우리가 안전하게 착륙할 수 있었던 건...\n아마 두 사람이 거기 숨어 있다가 비행기를 수리해 줘서일 거야...",
  ui_story_1021_10210401_90_dialog_content = "그게... 정말이야?",
  ui_story_1021_10210401_91_dialog_content = "저기... 비행기 일은 고마워요...",
  ui_story_1021_10210401_92_dialog_content = "뭐 그런 걸 가지고. 같이 탐색도 하는 사이잖아. 당연히 서로 도와야지~",
  ui_story_1021_10210401_93_dialog_content = "<color=#e8d9bb>똑── 똑──</color>",
  ui_story_1021_10210401_94_dialog_content = "그건 그거고, 이건 이거야. 북방의 보석은 가지고 갈 수 없어.\n대신 돌아가면 내가 나이티움을 줄게.",
  ui_story_1021_10210401_95_dialog_content = "나이티움이라... 뭐, 그것도 괜찮지.",
  ui_story_1021_10210401_96_dialog_content = "지금 이 주변은 위험해요. 혹시 눈여우랑 같이 있던 여자애가 어디 갔는지 아세요?",
  ui_story_1021_10210401_97_dialog_content = "알지. 근데 발이 엄청 빠르더라고! 전혀 따라잡을 수가 없더라니까!",
  ui_story_1021_10210401_98_dialog_content = "우린 그냥 피해서 숨어 있었을 뿐이잖아...",
  ui_story_1021_10210401_99_dialog_content = "PlayerName, 이 동굴 안엔 여우 시체가 많아.\n그리고 걔가 데리고 다니던 여우들도 크게 다친 것 같았어.",
  ui_story_1021_10210401_100_dialog_content = "그럼 빨리 찾아야 해...",
  ui_story_1021_10210401_101_dialog_content = "당신들이 길을 아는 이상, 안내를 부탁해야겠어.",
  ui_story_1021_10210401_102_dialog_content = "...여기야 그나마 괜찮지만 안쪽은 꿈 깨. 갈림길이 엄청 많거든...\n나랑 타이니도 길을 잃을 뻔했다고.",
  ui_story_1021_10210401_103_dialog_content = "로이 오빠! 내 라이트가...",
  ui_story_1021_10210401_104_dialog_content = "빛이 약해졌잖아?",
  ui_story_1021_10210401_105_dialog_content = "그럼 다크매터가 짙어졌다는 뜻이야...",
  ui_story_1021_10210401_106_dialog_content = "내가 따뜻한 곳을 좋아하긴 하지만, 그래도 미안하게 됐어.\nPlayerName, 나이티움 아가씨. 우린 먼저 실례할게!",
  ui_story_1021_10210401_107_dialog_content = "저 사람들... 서로 돕는 게 당연하다고 말한 지 얼마나 됐다고...\n그럼 이제 우린 어느 쪽으로 가지?",
  ui_story_1021_10210401_108_dialog_content = "감응 능력으로 찾아볼게.",
  ui_story_1021_10210401_109_option_content = "(감응 확장──)",
  ui_story_1021_10210401_110_dialog_content = "탐욕... 원망... 어리석음... 그것은 심신을 괴롭게 만드는 허무.",
  ui_story_1021_10210401_111_dialog_content = "그렇기 때문에 분노가 생기고, 그로 인해 병을 얻는 것입니다.",
  ui_story_1021_10210401_112_dialog_content = "그렇습니다... 바로 그것입니다...",
  ui_story_1021_10210401_113_dialog_content = "오만이... 또 조금 줄어들었군요...",
  ui_story_1021_10210401_114_dialog_content = "(암귀?!)",
  ui_story_1021_10210401_115_dialog_content = "(잘 보이지는 않지만... 아까 느꼈던 그 느낌이야...)",
  ui_story_1021_10210401_116_dialog_content = "(녀석 주변의 다크매터... 으, 머리가... 주먹으로 맞은 느낌이야...)",
  ui_story_1021_10210401_117_dialog_content = "『주인님──!』",
  ui_story_1021_10210401_118_dialog_content = "으음...?",
  ui_story_1021_10210401_119_dialog_content = "키에엑──!",
  ui_story_1021_10210401_120_dialog_content = "(......!)",
  ui_story_1021_10210401_121_dialog_content = "......",
  ui_story_1021_10210401_122_dialog_content = "억제... 억제...",
  ui_story_1021_10210401_123_dialog_content = "『...주, 주인님...』",
  ui_story_1021_10210401_124_dialog_content = "『걱정하지 마십시오. 가까이 와도 좋습니다. 해치지 않습니다.』",
  ui_story_1021_10210401_125_dialog_content = "『예...』",
  ui_story_1021_10210401_126_dialog_content = "『주인님... 역겨운 오로리안들이 근처에 있습니다...』",
  ui_story_1021_10210401_127_dialog_content = "『......』",
  ui_story_1021_10210401_128_dialog_content = "『녀, 녀석들이... 수행에 주인님의 방해가 될까 걱정이 돼서...』",
  ui_story_1021_10210401_129_dialog_content = "『지금 이곳은 어디입니까.』",
  ui_story_1021_10210401_130_dialog_content = "『이미 그 「성채」를 넘어오셨습니다.』",
  ui_story_1021_10210401_131_dialog_content = "『<color=#FFB400>설국</color>도... 참으로 많이 달라졌습니다...』",
  ui_story_1021_10210401_132_dialog_content = "『모습이 변해버린 이후로는 돌아온 적이 없었지요.』",
  ui_story_1021_10210401_133_dialog_content = "『변한다라...』",
  ui_story_1021_10210401_134_dialog_content = "『변한다는 것은 참으로 잔인한 박탈인 것입니다!』",
  ui_story_1021_10210401_135_dialog_content = "『주, 주인님...』",
  ui_story_1021_10210401_136_dialog_content = "『좋습니다, 잘 환기해 주었습니다... 억제... 억제해야 합니다...』",
  ui_story_1021_10210401_137_dialog_content = "<color=#e8d9bb>똑── 똑──</color>",
  ui_story_1021_10210401_138_dialog_content = "여기 얼음이 녹고 있는 건... 그 암귀의 다크매터 때문이야...",
  ui_story_1021_10210401_139_dialog_content = "PlayerName... 이번엔 뭘 본 거야? 왜 그런 표정인 건데?",
  ui_story_1021_10210401_140_dialog_content = "방금 그 암귀가 보였어...",
  ui_story_1021_10210401_141_dialog_content = "생각 좀 해 봤는데! 역시 같이 움직이자!",
  ui_story_1021_10210401_142_dialog_content = "뻔뻔하게 잘도 돌아오네.",
  ui_story_1021_10210401_143_dialog_content = "PlayerName! 앞에 갑자기 암귀가 잔뜩 나타났어!",
  ui_story_1021_10210401_144_dialog_content = "크아아──!",
  ui_story_1021_10210401_145_dialog_content = "카렌! 위험해!",
  ui_story_1021_10210401_146_dialog_content = "당신들이 끌어들인 거지?!",
  ui_story_1021_10210401_147_dialog_content = "...타이니, 내 뒤에 있어!",
  ui_story_1021_10210401_148_dialog_content = "이렇게 가까운데... 역시 아니야. 이건 그냥 보통 다크매터야. 아까 그 팽창하는 느낌이랑은 달라...",
  ui_story_1021_10210401_149_dialog_content = "PlayerName! 멍하니 있지 말고 전투 지휘를 부탁해!",
  ui_story_1021_10210401_150_dialog_content = "응!",
  ui_story_1021_10210402_1_dialog_content = "「얼음이 녹으면 그것으로 끝이다.」",
  ui_story_1021_10210402_2_dialog_content = "다 사라졌어!",
  ui_story_1021_10210402_3_dialog_content = "모두 무사한 것이냐.",
  ui_story_1021_10210402_4_dialog_content = "여왕 폐하! 왜 여기 계신 거죠?",
  ui_story_1021_10210402_5_dialog_content = "간헐천 근처에서 그대의 루미나틱스를 느꼈다.",
  ui_story_1021_10210402_6_dialog_content = "<color=#e8d9bb>얼마 전...</color>",
  ui_story_1021_10210402_7_dialog_content = "<color=#e8d9bb>보글보글── 퍼엉!</color>",
  ui_story_1021_10210402_8_dialog_content = "여왕 폐하, 저건...",
  ui_story_1021_10210402_9_dialog_content = "경계선상의 <color=#FFB400>간헐천</color>이다. 오랜 시간 활동을 멈추었으나 최근 다시 분출하기 시작했지.\n마치 역사의 시계처럼, 북방의 상처를 공교로운 시기에 드러내고 있구나...",
  ui_story_1021_10210402_10_dialog_content = "저 솟아나는 검은 물속에는 다크매터가 섞여 있다.\n저것은 우리의 초목과 건물, 그리고 무고한 부락을 멸망시켰지...",
  ui_story_1021_10210402_11_dialog_content = "거울 속에서 저도 봤습니다. 최근 어둠의 밑바닥 쪽 에너지의 이상 현상이 빈번합니다.\n여왕 폐하, 어떻게 하실 생각이신가요?",
  ui_story_1021_10210402_12_dialog_content = "다음 분출이 끝나면 내가 안으로 들어가 저 암귀를 상대할 것이다.",
  ui_story_1021_10210402_13_dialog_content = "네 북쪽 나라의 거울 속에는 왕성한 루미나가 담겨 있다.\n내가 들어가고 나면 이 다크매터가 퍼지지 않도록 네게 부탁하마.",
  ui_story_1021_10210402_14_dialog_content = "네, 여왕 폐하.",
  ui_story_1021_10210402_15_dialog_content = "<color=#e8d9bb>보글보글── 퍼엉!</color>",
  ui_story_1021_10210402_16_dialog_content = "으음...?",
  ui_story_1021_10210402_17_dialog_content = "여왕 폐하, 왜 그러시는지요?",
  ui_story_1021_10210402_18_dialog_content = "루미나가 느껴지는구나. 저 아이의 방식이라면 내가 가장 잘 알고 있다.",
  ui_story_1021_10210402_19_dialog_content = "기다리지 않고 바로 가야겠다. 그럼 여기는 네게 맡기마.",
  ui_story_1021_10210402_20_dialog_content = "...네, 여왕 폐하.",
  ui_story_1021_10210402_21_dialog_content = "저 끔찍한 광경은... 간헐천의 분출이 원인이었던 건가요...",
  ui_story_1021_10210402_22_dialog_content = "수많은 암귀도 다크매터를 찾아 모여들었고, 저 연약한 눈여우들을 해쳤지.\n그대들도 동굴 속에서 보았을 것이다.",
  ui_story_1021_10210402_23_dialog_content = "다음 분출 전까지 서둘러 이곳을 떠나거라.",
  ui_story_1021_10210402_24_dialog_content = "근데... 아까 이 근처에서 강력한 암귀의 존재를 감응했어요...",
  ui_story_1021_10210402_25_dialog_content = "저흰 원래 북방의 거점 일을 확인하러 왔는데요.\n예상 밖의 상황이 벌어져서 이 부근에 불시착했어요.",
  ui_story_1021_10210402_26_dialog_content = "그러다 다친 눈여우들을 데리고 온 티아라를 만났는데, 다들 상태가 안 좋았어요...",
  ui_story_1021_10210402_27_dialog_content = "저흰 그들이 걱정이 돼서 여기까지 따라와 보았습니다...\n...어라? 레디젤 렌치 녀석들은 어디 갔어?!",
  ui_story_1021_10210402_28_dialog_content = "......",
  ui_story_1021_10210402_29_dialog_content = "여왕 폐하, 이곳은 왕실이 수호하는 범위가 아닙니다...",
  ui_story_1021_10210402_30_dialog_content = "그래서 이곳의 암귀를 조사하도록 호위 티아라를 보내신 겁니까?",
  ui_story_1021_10210402_31_dialog_content = "「여왕 폐하의 호위」라는 것은 티아라가 「왕실의 호위」를 모방해 스스로 자칭하는 칭호입니다.",
  ui_story_1021_10210402_32_dialog_content = "「왕실의 호위」가 되려면 북방을 지킨다는 의미를 이해해야 합니다.\n그리고 그것은 북방의 백성들에게 있어 영원한 물음이기도 하지요.",
  ui_story_1021_10210402_33_dialog_content = "노비오 선생님!",
  ui_story_1021_10210402_34_dialog_content = "카렌 전하, PlayerName 님, 안녕하십니까.",
  ui_story_1021_10210402_35_dialog_content = "선생이 온 것을 보면, 나도 답을 알겠구나.",
  ui_story_1021_10210402_36_dialog_content = "폐하께서는 티아라가 윈터 팰리스를 떠나 부락으로 돌아갈 것을 진작에 예견하셨지요.",
  ui_story_1021_10210402_37_dialog_content = "역시... 티아라는 전설의 눈여우 부족 출신이었군요. 게다가 왠지...",
  ui_story_1021_10210402_38_dialog_content = "티아라는 눈여우 부족의 우두머리입니다.",
  ui_story_1021_10210402_39_dialog_content = "우두머리요?!",
  ui_story_1021_10210402_40_dialog_content = "설마 부족엔 이제 티아라보다 나이가 많은 사람이 없는 건가요...",
  ui_story_1021_10210402_41_dialog_content = "......",
  ui_story_1021_10210402_42_dialog_content = "아 참, 여왕 폐하... 티아라가 말씀을 전해달라고 부탁했어요.\n발자국은 깨끗이 청소하겠지만, 그게 지금은 아니라고 말이에요...",
  ui_story_1021_10210402_43_dialog_content = "그게 무슨 뜻일까요?",
  ui_story_1021_10210402_44_dialog_content = "영원한 물음이다... 나 자신조차도 해내지 못한 것이지...",
  ui_story_1021_10210402_45_dialog_content = "폐하께서는 북방을 순시하시면서 이 땅을 소홀히 하신 적은 단 한 번도 없었습니다.",
  ui_story_1021_10210402_46_dialog_content = "이는 나의 책임이다. 노비오, 이들을 데리고 먼저 떠나거라. 나는 티아라를 찾으러 가겠다.",
  ui_story_1021_10210402_47_dialog_content = "폐하, 제가 이미 찾았습니다.",
  ui_story_1021_10210402_48_dialog_content = "그러한가.",
  ui_story_1021_10210402_49_dialog_content = "...여왕 폐하! 아까 감응했던 강렬한 다크매터가 다가오고 있어요...",
  ui_story_1021_10210402_50_dialog_content = "저 말입니까?",
  ui_story_1021_10210402_51_dialog_content = "...! 「극광의 칼날이여!」",
  ui_story_1021_10210402_52_dialog_content = "어서 내 방벽 안으로 들어오거라!",
  ui_story_1021_10210402_53_dialog_content = "바로 당신이 설국의 여왕을 자칭하는 그 사람입니까?\n제가 못 본 사이에 많은 일이 있었군요.",
  ui_story_1021_10210402_54_dialog_content = "(...어떻게 갑자기 이렇게 가까이서 나타난 거지?!)",
  ui_story_1021_10210402_55_dialog_content = "당신은...",
  ui_story_1021_10210402_56_dialog_content = "<color=#FFB400>나다스</color>가 당신의 뇌로 좋은 술을 빚어 당신의 동포들에게 맛보게 할 것입니다.",
  ui_story_1021_10210402_57_dialog_content = "동포들...?! 무슨 소리야?!",
  ui_story_1021_10210402_58_dialog_content = "술이라...",
  ui_story_1021_10210402_59_dialog_content = "술 이야기가 나왔으니...",
  ui_story_1021_10210402_60_dialog_content = "으, 으윽... 괴로워...",
  ui_story_1021_10210402_61_dialog_content = "(놈의 다크매터가... 여왕 폐하의 방벽을 압도하려 하고 있어...!)",
  ui_story_1021_10210402_62_dialog_content = "...혹한의 힘이여, 가호를!",
  ui_story_1021_10210402_63_dialog_content = "폐하, 우리가 이곳에 있으면 폐하께 방해가 될 뿐입니다. 이들은 제게 맡겨 주시지요.",
  ui_story_1021_10210402_64_dialog_content = "...부탁한다, 노비오.",
  ui_story_1021_10210402_65_dialog_content = "여왕 폐하, 저희도 함께 싸우게 해 주십시오!",
  ui_story_1021_10210402_66_dialog_content = "이는 명령이다.",
  ui_story_1021_10210402_67_dialog_content = "......",
  ui_story_1021_10210402_68_dialog_content = "카렌 전하, PlayerName 님, 제 지팡이의 인도를 따라 지상으로 향하십시오.",
  ui_story_1021_10210402_69_dialog_content = "당신의 인도가 어디에 있습니까?",
  ui_story_1021_10210402_70_dialog_content = "......",
  ui_story_1021_10210402_71_dialog_content = "노비오 선생님!",
  ui_story_1021_10210402_72_dialog_content = "안심하고 어둠 속에 머무르십시오.",
  ui_story_1021_10210402_73_dialog_content = "극광이 비추는 북방에 어둠이란 결코 존재하지 않는다! 「극광의 칼날이여──!」",
  ui_story_1021_10210402_74_dialog_content = "당신, 그 여자에 비하면 아직 멀었군요.",
  ui_story_1021_10210402_75_dialog_content = "너 따위가 여왕 폐하를 평가할 자격은 없어!",
  ui_story_1021_10210402_76_dialog_content = "<color=#e8d9bb>휘익──!</color>",
  ui_story_1021_10210402_77_dialog_content = "티아라! 돌아와라──!",
  ui_story_1021_10210402_78_dialog_content = "여왕 폐하의 호위로서 전 반드시 폐하의 앞에 서야만 해요!",
  ui_story_1021_10210402_79_dialog_content = "<color=#e8d9bb>챙──!</color>",
  ui_story_1021_10210402_80_dialog_content = "여왕 폐하께는 손가락 하나 대지 못한다! 이건 여왕의 호위가 네놈에게 주는 일격이다!",
  ui_story_1021_10210402_81_dialog_content = "오만한 머리... 순백의 힘찬 다리...",
  ui_story_1021_10210402_82_dialog_content = "알겠습니다, 한번 들어 봅시다. 당신의 그 눈에는... 무엇이 담겨 있습니까?",
  ui_story_1021_10210402_83_dialog_content = "널 죽일 각오야!",
  ui_story_1021_10210402_84_dialog_content = "생각이 나는군요...",
  ui_story_1021_10210402_85_dialog_content = "그 여자는 검은 치맛자락을 걷어 올려 옷을 짧게 찢고,\n병사들을 지휘해서 가장 빠른 속도로 돌격해 왔었지요.",
  ui_story_1021_10210402_86_dialog_content = "한눈팔지 마! 내 창도 똑같이 가장 빠른 속도로 네 두 눈을 찌를 테니까!",
  ui_story_1021_10210402_87_dialog_content = "이 얼마나 매력적인 눈빛입니까. 하지만 너무 느립니다...",
  ui_story_1021_10210402_88_dialog_content = "「얼음이 녹으면 그것으로 끝이다!」",
  ui_story_1021_10210402_89_dialog_content = "...여왕 폐하?!",
  ui_story_1021_10210402_90_dialog_content = "이것은 그대의 싸움이 아니다. 지금 당장 내가 날린 얼음을 따라 이곳을 떠나라!",
  ui_story_1021_10210402_91_dialog_content = "하지만... 폐하는요?",
  ui_story_1021_10210402_92_dialog_content = "그대들의 뒤에 있을 것이다! 노비오, 부탁하마!",
  ui_story_1021_10210402_93_dialog_content = "「산천의 지팡이여, 힘을 주소서!」",
  ui_story_1021_10210402_94_dialog_content = "『주인님... 왜 놈들을 죽이지 않으셨습니까?』",
  ui_story_1021_10210402_95_dialog_content = "『저 여우의 눈 속에서 제 자신의 분노를 보았기 때문입니다...』",
  ui_story_1021_10210402_96_dialog_content = "『분노는 나약함의 표상입니다. 저는 분노의 노예가 되지 않겠다고 맹세했습니다.』",
  ui_story_1021_10210402_97_dialog_content = "『설국의 여왕...』",
  ui_story_1021_10210402_98_dialog_content = "『제 불꽃 속에서도 저들의 얼음은 녹지 않고 견고하군요...』",
  ui_story_1021_10210501_1_dialog_content = "......",
  ui_story_1021_10210501_2_dialog_content = "여왕 폐하...? 왜 멈추시는 거죠?",
  ui_story_1021_10210501_3_dialog_content = "지나온 길의 얼음층은 다크매터의 영향을 받아 본래의 암석층을 드러내고 있다...",
  ui_story_1021_10210501_4_dialog_content = "허나 이곳은 아무렇지도 않다... 게다가 이곳에서 무언가 특별한 힘이 느껴지는구나.",
  ui_story_1021_10210501_5_dialog_content = "무엇을 해야 할지 알겠다. 노비오, 이들과 함께 조심해서 돌아가라.",
  ui_story_1021_10210501_6_dialog_content = "하지만... 여왕 폐하...",
  ui_story_1021_10210501_7_dialog_content = "...저도 따라가게 해 주세요!",
  ui_story_1021_10210501_8_dialog_content = "......",
  ui_story_1021_10210501_9_dialog_content = "당신이 여기에 지키러 온 것은 폐하가 아닌 부족이지 않습니까.",
  ui_story_1021_10210501_10_dialog_content = "그, 그건...",
  ui_story_1021_10210501_11_dialog_content = "우리 부족은 지금 멸망의 위기에 처해 있어요. 이제 남은 피난처는 이 제단 하나뿐이라구요...",
  ui_story_1021_10210501_12_dialog_content = "내가 느꼈던 힘은 제단의 가호였던 것이냐.",
  ui_story_1021_10210501_13_dialog_content = "폐하... 제단엔... 가시면 안 돼요!",
  ui_story_1021_10210501_14_dialog_content = "감히 폐하의 앞길을 막는 거야?! 티아라 당신, 지금 자기가 뭘 하고 있는지 알고 있어?",
  ui_story_1021_10210501_15_dialog_content = "...폐하께서 그 어떤 위험한 곳을 가시든지, 전 항상 폐하를 모실 거예요. 하지만 제단만큼은...",
  ui_story_1021_10210501_16_dialog_content = "죄송해요... 보내드릴 수 없어요!",
  ui_story_1021_10210501_17_dialog_content = "이건 눈여우 부족의 리더로서 선조들에게 한 맹세예요!",
  ui_story_1021_10210501_18_dialog_content = "나를 보내주지 않는 것은 원한 때문이냐.",
  ui_story_1021_10210501_19_dialog_content = "원한인지 뭔지는... 사실 전 잘 모르겠어요...",
  ui_story_1021_10210501_20_dialog_content = "......",
  ui_story_1021_10210501_21_dialog_content = "그대가 부족과 왕실의 관계에 대해 의문을 품고 있다면,\n그 의문이 사라지도록 스스로 확인해야 마땅하다.",
  ui_story_1021_10210501_22_dialog_content = "그러나 지금 내가 제단으로 가서 그녀를 만나는 것은 북방을 위해서다.\n티아라, 나를 믿어라.",
  ui_story_1021_10210501_23_dialog_content = "여왕 폐하!",
  ui_story_1021_10210501_24_dialog_content = "티아라, 들어오게 해라.",
  ui_story_1021_10210501_25_dialog_content = "...누가... 말하는 거지?",
  ui_story_1021_10210501_26_dialog_content = "장로님?! 하...하지만...!",
  ui_story_1021_10210501_27_dialog_content = "괜찮다.",
  ui_story_1021_10210501_28_dialog_content = "잘 지내셨는지요?",
  ui_story_1021_10210501_29_dialog_content = "산의 정령이 마음 써 준 덕분인지, 이 늙은 몸이 아직도 살아 있군.",
  ui_story_1021_10210501_30_dialog_content = "저 눈여우야...! 카렌, 아까 그 나이 많은 눈여우가 말을 하고 있어!",
  ui_story_1021_10210501_31_dialog_content = "그렇게 놀랄 것까진 없잖아... 근데 꽤 회복된 것 같아 보여...",
  ui_story_1021_10210501_32_dialog_content = "저 목소리, 왠지 여자 같네.",
  ui_story_1021_10210501_33_dialog_content = "......",
  ui_story_1021_10210501_34_dialog_content = "저들은 북방의 백성이 아니다. 그러나 장로를 존중하고 곧 이 땅을 떠날 것이다.",
  ui_story_1021_10210501_35_dialog_content = "필요 없다. 나를 존중하는 이는 이제 이 세상에 없다.\n그대들의 존중은 그저 빚을 진 자의 미안함이 아니던가.",
  ui_story_1021_10210501_36_dialog_content = "여왕 폐하께 실례되는 태도는 삼가주시죠!",
  ui_story_1021_10210501_37_dialog_content = "카렌, 물러서라!",
  ui_story_1021_10210501_38_dialog_content = "......",
  ui_story_1021_10210501_39_dialog_content = "이 늙은 몸은 이미 오래전 기력을 다했다.\n그저 지난 시대의 육신을 끌고, 겨우 지금까지 목숨을 부지해 왔을 뿐이다.",
  ui_story_1021_10210501_40_dialog_content = "부족이 그대들의 왕을 존중하지 않은 것은 아니다.\n그러나 이 동굴의 황량한 모습은 그대들의 의심에 대한 답이 될 것이다.",
  ui_story_1021_10210501_41_dialog_content = "장로님, 정말 여왕 폐하가 제단에 가셔도...",
  ui_story_1021_10210501_42_dialog_content = "티아라. 나는 결코 그대에게 이런 것들을 짊어지게 만들고 싶지 않았다.",
  ui_story_1021_10210501_43_dialog_content = "......",
  ui_story_1021_10210501_44_dialog_content = "장로여, 북방에 침입한 암귀가 가까이 다가오고 있다...",
  ui_story_1021_10210501_45_dialog_content = "비록 미약하다고는 하나, 「자연의 힘」의 가호가 있다면 암귀는 제단에 접근할 수 없다.\n날 따라와라.",
  ui_story_1021_10210501_46_dialog_content = "......",
  ui_story_1021_10210501_47_dialog_content = "<color=#e8d9bb>아우우...</color>",
  ui_story_1021_10210501_48_dialog_content = "이게 바로... 티아라의 부족이 지키고 있는 제단인가?",
  ui_story_1021_10210501_49_dialog_content = "동굴 안에 이런 곳이 있었다니...",
  ui_story_1021_10210501_50_dialog_content = "이것은 북방이 세워졌을 때 부족의 선조들이 세운 제단이다.",
  ui_story_1021_10210501_51_dialog_content = "여기서... 뭘 모시는 거죠?",
  ui_story_1021_10210501_52_dialog_content = "북방을 지키는 세 그루의 눈소나무, 그리고 눈소나무 숲을 지켜온 선조들이다.",
  ui_story_1021_10210501_53_dialog_content = "세 그루의 눈소나무라는 건... 여기 이 세 그루터기 말인가요...?",
  ui_story_1021_10210501_54_dialog_content = "북방을 지키려는 이상을 품었으면서도, 베어지는 운명을 피할 순 없었지.\n허나 신들의 힘은 결코 사라지지 않는다.",
  ui_story_1021_10210501_55_dialog_content = "만약 이 세 그루 눈소나무가 땅에서 일어나려 한다면, 뭇 산들조차 길을 내줄 것이다.\n하늘은 이들을 잊지 않기에, 틈 사이로 영원히 빛이 비쳐 들어온다.",
  ui_story_1021_10210501_56_dialog_content = "이 비석에 새겨져 있는 건... 고대 문자인가?",
  ui_story_1021_10210501_57_dialog_content = "뭐라고 쓰여 있는 거지?",
  ui_story_1021_10210501_58_dialog_content = "「신은 이 세상에 평화를 가져오는 국왕의 고단함을 없애준다.」",
  ui_story_1021_10210501_59_dialog_content = "「신의 약속은 어둠을 빛으로 바꾼다.」",
  ui_story_1021_10210501_60_dialog_content = "「사람들은 신의 모습을 보면 안녕과 행복을 얻을 것이다.」",
  ui_story_1021_10210501_61_dialog_content = "그거, 설마...",
  ui_story_1021_10210501_62_dialog_content = "그것은 「세 그루 소나무」의 전설을 기록한 가장 오래된 비문이다...",
  ui_story_1021_10210501_63_dialog_content = "왠지 제가 북방에 있을 때 배운 이야기와는 조금 다른 것 같습니다...",
  ui_story_1021_10210501_64_dialog_content = "첫 번째 소나무는 북방의 초대 여왕을 받들었고, 두 번째 소나무는 왕실 호위의 충성을 목도했고...",
  ui_story_1021_10210501_65_dialog_content = "세 번째 소나무는 북방을 다스리는 여왕의 지팡이가 되었다고 들었습니다...",
  ui_story_1021_10210501_66_dialog_content = "하하하하... 그대들의 전설은 왕실 후계자의 허영으로 가득하군...",
  ui_story_1021_10210501_67_dialog_content = "그 녀석이 못 들어서 다행이군. 아니었으면 그대들은 이가 부러질 때까지 두들겨 맞았을 것이다.",
  ui_story_1021_10210501_68_dialog_content = "허나 이해할 수 없는 것도 아니다.\n어떤 왕조든지 자신에게 찬란한 기원을 만들고 싶어 하니 말이야.",
  ui_story_1021_10210501_69_dialog_content = "<color=#e8d9bb>파앗──!</color>",
  ui_story_1021_10210501_70_dialog_content = "...!!!",
  ui_story_1021_10210501_71_dialog_content = "장로님──!",
  ui_story_1021_10210501_72_dialog_content = "미, 미안... 방해했네... 타이니, 너 그 스포트라이트 갑자기 왜 그래?",
  ui_story_1021_10210501_73_dialog_content = "나...나도 모르겠어...",
  ui_story_1021_10210501_74_dialog_content = "당신들 계속 거기 숨어 있었어?!",
  ui_story_1021_10210501_75_dialog_content = "외세의... 물건인가...",
  ui_story_1021_10210501_76_dialog_content = "PlayerName, 빨리 친구에게 저거 치우라고 해! 장로님은 몸이 약하시다고!",
  ui_story_1021_10210501_77_dialog_content = "타이니!!",
  ui_story_1021_10210501_78_dialog_content = "그, 근데... 안 꺼진다니까!",
  ui_story_1021_10210501_79_dialog_content = "<color=#e8d9bb>휘이잉── 휘이──</color>",
  ui_story_1021_10210501_80_dialog_content = "...뭐지? 장창에서 왠지 힘이 솟아나는 것 같아...",
  ui_story_1021_10210501_81_dialog_content = "이게... 대체...",
  ui_story_1021_10210501_82_dialog_content = "<color=#e8d9bb>휘이잉── 휘이──</color>",
  ui_story_1021_10210501_83_dialog_content = "지팡이와 제단이 공명하고 있습니다...",
  ui_story_1021_10210501_84_dialog_content = "......",
  ui_story_1021_10210501_85_dialog_content = "다만 신의 선택은 폐하의 「늦겨울의 힘」인 듯합니다...",
  ui_story_1021_10210501_86_dialog_content = "...뭐, 뭐라?",
  ui_story_1021_10210501_87_dialog_content = "나는 이 세상에 평화를 가져오는 국왕의 곁을 따르고 싶다!",
  ui_story_1021_10210501_88_dialog_content = "(이 목소리...)",
  ui_story_1021_10210501_89_dialog_content = "나는 암흑의 세계에 빛을 가져다주고 싶다!",
  ui_story_1021_10210501_90_dialog_content = "나는 사람들이 우리를 볼 때 안녕과 행복을 얻을 수 있다면 그것으로 족하다...",
  ui_story_1021_10210501_91_dialog_content = "하하하... 정말 오만한 녀석들이로군...",
  ui_story_1021_10210501_92_dialog_content = "그대도 마찬가지 아닌가? 하하...",
  ui_story_1021_10210501_93_dialog_content = "세 개의 목소리가 제단에 울려 퍼지고 있어...",
  ui_story_1021_10210501_94_dialog_content = "나도 들었어...",
  ui_story_1021_10210501_95_dialog_content = "이건... 신의 목소리인가?",
  ui_story_1021_10210501_96_dialog_content = "......",
  ui_story_1021_10210501_97_dialog_content = "신이... 그대의 힘을 인정했다...",
  ui_story_1021_10210501_98_dialog_content = "눈앞에 많은 광경이 스쳐 지나갔다...",
  ui_story_1021_10210501_99_dialog_content = "신은 자신이 인정하는 자가 부리는 힘을 분간할 수 있다...",
  ui_story_1021_10210501_100_dialog_content = "그렇다면 그 말은...",
  ui_story_1021_10210501_101_dialog_content = "그대와... 그대들의 첫 여왕은... 진정 신의 축복을 누렸던 것이란 말인가...",
  ui_story_1021_10210501_102_dialog_content = "......",
  ui_story_1021_10210501_103_dialog_content = "세상을 떠난 선조들은 생각지도 못했을 것이다...",
  ui_story_1021_10210501_104_dialog_content = "<color=#e8d9bb>죽여라──!</color>",
  ui_story_1021_10210501_105_dialog_content = "너희가 나아가서 약속을 지킨다면, 북방에는 너희의 안식처가 생길 것이다!",
  ui_story_1021_10210501_106_dialog_content = "그러나 물러난다면, 내가 너희의 목을 베어 소나무 위에 걸고, 너희 후손들의 수치가 되게 할 것이다!",
  ui_story_1021_10210501_107_dialog_content = "이...이건 누구의 의식이지? 난 감응 능력도 안 썼는데...?",
  ui_story_1021_10210501_108_dialog_content = "다들 제단 앞에 있었을 때 위치 그대로야...",
  ui_story_1021_10210501_109_dialog_content = "이곳은... 북방의 변경에 일찍이 존재했던 견고한 보루다...",
  ui_story_1021_10210501_110_dialog_content = "그 보루의 지금 위치가 설마...",
  ui_story_1021_10210501_111_dialog_content = "제단은 그 성채의 정원 안에 세워졌던 것이다.",
  ui_story_1021_10210501_112_dialog_content = "......",
  ui_story_1021_10210501_113_dialog_content = "얼음성에서 온 자여, 어서 떠나라.",
  ui_story_1021_10210501_114_dialog_content = "......",
  ui_story_1021_10210501_115_dialog_content = "우...우리 말하는 건가?",
  ui_story_1021_10210501_116_dialog_content = "아마 우리 옷차림이 저들과 달라서 그런 거겠지...",
  ui_story_1021_10210501_117_dialog_content = "너희는 신의 힘을 빼앗았다. 이제 우리는 가호를 받을 수 없다.",
  ui_story_1021_10210501_118_dialog_content = "그러나 우리는 신과의 약속을 잊지 않는다!",
  ui_story_1021_10210501_119_dialog_content = "설령 우리가 자라 온 숲에서 끝내 죽게 되더라도, 설령 이 불합리한 하늘에 짓눌리더라도...",
  ui_story_1021_10210501_120_dialog_content = "나는 나의 왕만을 따를 것이다.",
  ui_story_1021_10210501_121_dialog_content = "......",
  ui_story_1021_10210501_122_dialog_content = "로데 님...",
  ui_story_1021_10210501_123_dialog_content = "하겐! 가서 왕이 주신 갑옷을 가져와라. 그것으로 싸움에 앞장선 부하를 격려할 것이다!",
  ui_story_1021_10210501_124_dialog_content = "로데 님... 갑옷을 입으십시오.",
  ui_story_1021_10210501_125_dialog_content = "이건 내 마지막 싸움이 아니다, 하겐! 내 갑옷은 너 하나로 충분하다!",
  ui_story_1021_10210501_126_dialog_content = "......",
  ui_story_1021_10210501_127_dialog_content = "간다, 하겐.",
  ui_story_1021_10210501_128_dialog_content = "저는 항상 당신의 뒤를 따를 것입니다, 로데 님...",
  ui_story_1021_10210501_129_dialog_content = "......",
  ui_story_1021_10210501_130_dialog_content = "우리는 강한 힘과 위엄을 가지고, 부하를 진심으로 아끼는 로데 님이야말로,\n북방의 다음 왕이 될 것이라고 생각하고 있었다.",
  ui_story_1021_10210501_131_dialog_content = "형제들이여! 우리의 왕을 위하여! 북방을 위하여! 가자──!",
  ui_story_1021_10210501_132_dialog_content = "죽여라──!",
  ui_story_1021_10210501_133_dialog_content = "죽여라──!",
  ui_story_1021_10210501_134_dialog_content = "<color=#e8d9bb>휘이잉── 휘이──</color>",
  ui_story_1021_10210501_135_dialog_content = "사라져 버렸어... 이게 바로 「자연의 힘」인 건가...?",
  ui_story_1021_10210501_136_dialog_content = "......",
  ui_story_1021_10210501_137_dialog_content = "장로님은 로데 님의 호위였군요.",
  ui_story_1021_10210501_138_dialog_content = "그분은 그대의 선조이자, 그대가 어릴 적부터 자랑으로 여겨 온 동족이다.",
  ui_story_1021_10210501_139_dialog_content = "부족은 이제 이 지경이 되고 말았다. 나는 이제 로데 님을 뵐 면목도 없다.",
  ui_story_1021_10210501_140_dialog_content = "장로님 얼굴의 상처는... 그때 암귀에게 당하신 건가요...?",
  ui_story_1021_10210501_141_dialog_content = "그 잔혹한 싸움의 날들에 유감을 품을 필요는 없다, 티아라.",
  ui_story_1021_10210501_142_dialog_content = "그대에게는 우리의 상처밖에 보이지 않겠지만, 암귀를 물리친 후 우리는\n눈소나무 숲에서 모닥불을 에워싸고 함께 축하했다.",
  ui_story_1021_10210501_143_dialog_content = "...왜 말 안 해 주셨어요?",
  ui_story_1021_10210501_144_dialog_content = "알았다면 그대는 분명히 윈터 팰리스를 떠나, 그대와 선조들이 맹세했듯\n이곳을 지키고자 했을 것이다.",
  ui_story_1021_10210501_145_dialog_content = "나는 그대의 성품을 알고 있다. 여왕의 호위가 되더라도 그 몸에는\n우리 선조들의 피가 흐르고 있지 않느냐.",
  ui_story_1021_10210501_146_dialog_content = "그러나 오늘날 우리 일족은 이미 몰락해 버렸다. 알게 된다고 해도 의미는 없을 것이다.",
  ui_story_1021_10210501_147_dialog_content = "게다가 그대에게는 이미 그대가 섬기는 왕이 있다.",
  ui_story_1021_10210501_148_dialog_content = "......",
  ui_story_1021_10210501_149_dialog_content = "그대가 충성을 바치는 대상은... 진정으로 신에게 인정받은 자였다.\n이제 부락에 남아 우리를 지킬 이유가 더 있겠느냐.",
  ui_story_1021_10210501_150_dialog_content = "......",
  ui_story_1021_10210501_151_dialog_content = "하지만... 「신의 힘을 빼앗았다」는 로데 님 말씀은 무슨 뜻이죠?",
  ui_story_1021_10210501_152_dialog_content = "등대다...",
  ui_story_1021_10210501_153_dialog_content = "등대...? 북방의 등대 말씀이신가요?",
  ui_story_1021_10210501_154_dialog_content = "「사람들은 신의 모습을 보면 안녕과 행복을 얻을 것이다.」",
  ui_story_1021_10210501_155_dialog_content = "......",
  ui_story_1021_10210501_156_dialog_content = "암귀를 몰아내고, 북방 전역을 빛으로 두루 비추고자...",
  ui_story_1021_10210501_157_dialog_content = "왕실의 선인들은 「자연의 힘」을 품은 눈소나무 한 그루를 얻었다.",
  ui_story_1021_10210501_158_dialog_content = "눈소나무는 자신을 꺾어 「불씨」를 받아내는 버팀목이 되었고, 그것이 바로 북방 최초의 등대다.",
  ui_story_1021_10210501_159_dialog_content = "그 후 북방의 대지는 빛을 받게 되었으나... 눈소나무의 수호를 받던 눈소나무 숲은\n서서히 암귀에 맞설 힘을 잃어간 것이었다.",
  ui_story_1021_10210501_160_dialog_content = "......",
  ui_story_1021_10210501_161_dialog_content = "그것이 그대가 조금 전 보았던 광경인가.",
  ui_story_1021_10210501_162_dialog_content = "그렇다. 신은 왕실을 인정했고, 북방의 등대가 되는 것을 선택했다.",
  ui_story_1021_10210501_163_dialog_content = "오직 그것만이 북방을 지킨다는 자신의 이상을 실현할 수 있기 때문이었다...",
  ui_story_1021_10210501_164_dialog_content = "그런 것이었나...",
  ui_story_1021_10210501_165_dialog_content = "그럼 왕실은 신의 힘을 빼앗아 간 게 아닌 거네요. 그렇죠?",
  ui_story_1021_10210501_166_dialog_content = "......",
  ui_story_1021_10210501_167_dialog_content = "......",
  ui_story_1021_10210501_168_dialog_content = "신은 북방의 등대가 되기 전 우리를 지켜주었다. 그때는 신의 힘이 아직 이곳에 있었지.",
  ui_story_1021_10210501_169_dialog_content = "선조들은 제단을 쌓고, 매일 기도하며 저들의 희망과 신앙을 신에게 바쳤다.",
  ui_story_1021_10210501_170_dialog_content = "혹한의 겨울에는 소나무 기름으로 불을 밝혀, 부족의 안녕과 번영을 지켜 왔다.",
  ui_story_1021_10210501_171_dialog_content = "하지만 세월의 흐름은 헤아릴 수 없는 변고를 가져왔지.\n어느 순간 부락이 곤경에 빠져, 질병이 만연하고, 작물은 말라죽었다...",
  ui_story_1021_10210501_172_dialog_content = "눈소나무는 베어지고, 원한과 절망만이 부락의 하늘을 뒤덮고 말았다.",
  ui_story_1021_10210501_173_dialog_content = "훗날, 왕은 우리를 이끌고, 밤낮으로 제단에서 기도를 올려 신의 가호를 빌었다...",
  ui_story_1021_10210501_174_dialog_content = "그러나 암귀가 횡행하고, 나는 일생 중 수없이 많은 일족의 탄생과 죽음을 보았으나,\n신은 결코 우리의 기도에 응답하지 않았다...",
  ui_story_1021_10210501_175_dialog_content = "심지어 우리 일족이 증오 속에서 생명의 끝을 향해 나아가는 것을 묵인하고 있었지.",
  ui_story_1021_10210501_176_dialog_content = "그것이 바로 우리 일족의 역사다.\n그대가 태어나기 전까지는 나 또한 같은 결말을 맞으리라 생각했었지...",
  ui_story_1021_10210501_177_dialog_content = "장로님...",
  ui_story_1021_10210501_178_dialog_content = "티아라, 나는 이미 너무 늙었다.\n이제 이런 이야기를 회상하며 나날을 보낼 수밖에 없는 몸이 되었다.",
  ui_story_1021_10210501_179_dialog_content = "그러나 그대는 자신이 해야 할 일을 결정하고, 일생을 바쳐 해내겠다고 각오하였느냐.",
  ui_story_1021_10210501_180_dialog_content = "전 부족을 지키고 싶어요, 장로님... 하지만 여왕 폐하도 돕고 싶어요.",
  ui_story_1021_10210501_181_dialog_content = "부족과 왕실 사이에 갈등이 있다면, 전부 저한테 얘기해 주셔도 돼요.\n저도 일족의 역사를 이해하고, 그 틈을 메울 수 있도록 노력할 거예요.",
  ui_story_1021_10210501_182_dialog_content = "대신 지금은 북방의 안녕을 위해 서로를 믿었으면 좋겠어요.\n그리고 이 땅을 침범한 암귀에 먼저 함께 맞서는 건 어떨까요?",
  ui_story_1021_10210501_183_dialog_content = "......",
  ui_story_1021_10210501_184_dialog_content = "장로여, 내게는 줄곧 「원시의 성역」에 대한 기억이 존재했다.",
  ui_story_1021_10210501_185_dialog_content = "그리고 조금 전, 나는 눈앞에 펼쳐진 광경 속에서 볼 수 있었다...",
  ui_story_1021_10210501_186_dialog_content = "북방 등대의 첫 번째 몸, 다시 말해 이곳에 뿌리내리고 있는 눈소나무는\n태고의 영력에 의해 그 무엇보다 단단한 몸을 갖게 되었지.",
  ui_story_1021_10210501_187_dialog_content = "그리고 이 제단 주위에는 「원시의 성역」이 존재한다.",
  ui_story_1021_10210501_188_dialog_content = "「원시의 성역」을 깨워 북방에 가호를 가져오려면 어떻게 해야 하는지 알고 있는가.",
  ui_story_1021_10210501_189_dialog_content = "「원시의 성역」을 깨운다고? 하하하...",
  ui_story_1021_10210501_190_dialog_content = "그대는 북방 등대의 불을 끄고, 이 베어진 나무뿌리에서 다시\n세 그루의 눈소나무가 자라게 할 수 있는가?",
  ui_story_1021_10210501_191_dialog_content = "......",
  ui_story_1021_10210501_192_dialog_content = "등대 외의 나머지 눈소나무 두 그루도 제단으로 돌아가야 한다는 말이겠지.",
  ui_story_1021_10210501_193_dialog_content = "그렇다.",
  ui_story_1021_10210501_194_dialog_content = "장로님... 지금 그 말이 사실인가요?",
  ui_story_1021_10210501_195_dialog_content = "......",
  ui_story_1021_10210501_196_dialog_content = "북방 등대의 불을 끈다니... 그런 짓을 하면 윈터 팰리스도, 마을 사람들도...",
  ui_story_1021_10210501_197_dialog_content = "그대는 늘 「여왕 폐하의 호위」라고 말하고 있지 않은가.",
  ui_story_1021_10210501_198_dialog_content = "그대가 섬기는 여왕이 「원시의 성역」을 깨우고, 부족에 진 빚을 갚으려 하는데,\n설마 도울 마음이 없는 것이냐.",
  ui_story_1021_10210501_199_dialog_content = "물론 돕고 싶죠! 전 영원히 여왕 폐하를 따를 거예요! 하지만...",
  ui_story_1021_10210501_200_dialog_content = "티아라, 고개를 들고 날 보아라.",
  ui_story_1021_10210501_201_dialog_content = "......",
  ui_story_1021_10210501_202_dialog_content = "믿어라. 저 힘을 받아들인 건 나다. 어떻게 돌려줄지는 물론 알고 있다.",
  ui_story_1021_10210501_203_dialog_content = "나는 그대가 나의 호위로서, 함께 「원시의 성역」을 깨우고, 북방을 지켜주길 바란다.",
  ui_story_1021_10210501_204_dialog_content = "나머지 두 그루의 눈소나무를 찾는 일을 그대에게 맡겨도 되겠느냐.",
  ui_story_1021_10210501_205_dialog_content = "여왕 폐하...",
  ui_story_1021_10210501_206_dialog_content = "얼음과 눈으로 뒤덮인 모든 땅이 곧 내가 생명을 바쳐 지켜야 할 북방이다.\n그것이 내가 나의 백성들에게 한 약속이다.",
  ui_story_1021_10210501_207_dialog_content = "등대의 불빛은 이 땅을 비추지 않았다.\n설령 그대들의 고향을 짓밟은 것이 암귀라 해도, 그대들을 지켜주지 못한 것은 나 베들레헴인 것이다.",
  ui_story_1021_10210501_208_dialog_content = "......",
  ui_story_1021_10210501_209_dialog_content = "노비오, 그대는 눈소나무가 어디에 있는지 알고 있겠지.",
  ui_story_1021_10210501_210_dialog_content = "네, 여왕 폐하. 안심하고 저 암귀를 상대해 주십시오. 여러분은 저와 함께 갑시다.",
  ui_story_1021_10210501_211_dialog_content = "......",
  ui_story_1021_10210501_212_dialog_content = "장로님, 그럼 전 일단 노비오 님을 따라 다녀올게요...",
  ui_story_1021_10210501_213_dialog_content = "그대의 등대를 따라라. 가서 그대가 섬기는 왕을 향한 약속을 지키는 것이다.",
  ui_story_1021_10210501_214_dialog_content = "네!",
  ui_story_1021_10210601_1_dialog_content = "여왕 폐하는 홀로 암귀와 싸우러 가셨는데... 우린 정말 아무것도 도울 수 없는 건가요?",
  ui_story_1021_10210601_2_dialog_content = "폐하께선 전에 절 구해주셨을 때 제게 특별한 힘을 주셨어요.\n근데 전 지금 곁에서 같이 싸울 수조차 없어요...",
  ui_story_1021_10210601_3_dialog_content = "동굴에서 마주쳤을 때 두 분도 그 암귀의 힘을 깨달았을 것입니다.",
  ui_story_1021_10210601_4_dialog_content = "그리고 티아라 당신은 물건을 되찾아 오는 것이 곧 여왕 폐하의 싸움을 돕는 것입니다.",
  ui_story_1021_10210601_5_dialog_content = "저 간헐천에서 뿜어져 나오는 다크매터는 지금도 북방의 설원을 계속 침식하고 있습니다...",
  ui_story_1021_10210601_6_dialog_content = "폐하께서 장로를 찾아 제단으로 향하신 것은, 다크매터의 더러움을 정화하는 방법,\n즉 「원시의 성역」을 깨우는 방법을 찾기 위해서입니다.",
  ui_story_1021_10210601_7_dialog_content = "노비오 님, 나머지 눈소나무 두 그루는 대체 어디 있는 건가요?",
  ui_story_1021_10210601_8_dialog_content = "저 절벽의 등대 외에도, 두 그루의 소나무 역시 다른 장소에서 줄곧 북방을 지켜 왔습니다.",
  ui_story_1021_10210601_9_dialog_content = "계속 지켜왔다고요...?",
  ui_story_1021_10210601_10_dialog_content = "그렇습니다. 그중 하나는 윈터 팰리스에 있고, 다른 하나는 당신이 태어난 곳에 있습니다.",
  ui_story_1021_10210601_11_dialog_content = "그러나 세월이 흐르면서 눈소나무의 모습도 달라졌습니다.\n어쩌면 「세 그루 소나무」의 전설에서 답을 찾아야 할지도 모르겠군요.",
  ui_story_1021_10210601_12_dialog_content = "비록 눈소나무 속 「자연의 힘」은 이미 침묵에 빠졌지만,\n당신이 신들과 가까워지면 여왕 폐하께서 당신에게 주신 힘이 그들과 공명할 것입니다.",
  ui_story_1021_10210601_13_dialog_content = "알겠어요, 노비오 님!",
  ui_story_1021_10210601_14_dialog_content = "여왕 폐하도, 당신들의 장로도, 「지킨다」는 것의 의미는 자신의 생명보다\n무겁다는 것을 잘 알고 있습니다.",
  ui_story_1021_10210601_15_dialog_content = "티아라, 부디 당신도 북방의 호위로서 「지킨다」는 사명을 짊어질 수 있길 바랍니다.",
  ui_story_1021_10210601_16_dialog_content = "네. 맡겨주세요. 절대 실망시키지 않을 테니까요!",
  ui_story_1021_10210601_17_dialog_content = "티아라, 잠깐만! 나도 같이 갈게!",
  ui_story_1021_10210601_18_dialog_content = "네가?",
  ui_story_1021_10210601_19_dialog_content = "나도 도울게!",
  ui_story_1021_10210601_20_dialog_content = "근데... 다들 날 따라올 수 있겠어? 아니면 내가 어깨에 메고 달릴까?",
  ui_story_1021_10210601_21_dialog_content = "어깨에 멘다고...?",
  ui_story_1021_10210601_22_dialog_content = "...내가 도움을 줄 수 있다면, 그것도 괜찮을 것 같아!",
  ui_story_1021_10210601_23_dialog_content = "PlayerName 님의 감응 능력은 아마 큰 힘이 될 것입니다.",
  ui_story_1021_10210601_24_dialog_content = "그렇군요... 알겠어요. 그럼 노비오 님! 여긴 부탁드릴게요!",
  ui_story_1021_10210601_25_dialog_content = "저희도 금방 다녀올게요!",
  ui_story_1021_10210601_26_dialog_content = "으, 으아앗──!",
  ui_story_1021_10210601_27_dialog_content = "정말 순식간에 사라져 버렸잖아...",
  ui_story_1021_10210601_28_dialog_content = "다크매터가 섞인 검은 물이 벌써 윈터 팰리스 쪽으로 퍼지기 시작했군요...",
  ui_story_1021_10210601_29_dialog_content = "아무래도 강력한 루미나를 가진 나시리스조차 저것을 억제할 수 없는 모양입니다.",
  ui_story_1021_10210601_30_dialog_content = "부디 티아라가 눈소나무를 찾아서 돌아올 수 있길 빌어야겠군요.\n그래야만 부족의 존속을 보장할 수 있을 테니 말입니다...",
  ui_story_1021_10210601_31_dialog_content = "노비오 선생님, 저도 북방의 호위라고 생각해 주세요. 북방을 지키기 위해 힘을 보태고 싶어요.",
  ui_story_1021_10210601_32_dialog_content = "<color=#e8d9bb>한편, 숲의 어딘가</color>",
  ui_story_1021_10210601_33_dialog_content = "휴, 이거 우리끼리 레디젤 렌치로 돌아가는 건 역시 무리일 것 같아.\nPlayerName 쪽이랑 같이 위기를 해결하는 게 좀 더 현실적이겠어.",
  ui_story_1021_10210601_34_dialog_content = "그거 진심이야?",
  ui_story_1021_10210601_35_dialog_content = "뭐, 결국 따지고 보면 레디젤 렌치를 위해서라고 해야겠지.",
  ui_story_1021_10210601_36_dialog_content = "PlayerName한테는 이브 일로 사메야마가 신세를 꽤 졌잖아.",
  ui_story_1021_10210601_37_dialog_content = "그것만 가지고도 사메야마 녀석은 PlayerName한테 위험한 일이 생기면\n언제든지 나설 테고 말이야.",
  ui_story_1021_10210601_38_dialog_content = "연합 탐색 일도 그래. 사메야마는 그냥 모르는 척하고 있을 뿐이야.",
  ui_story_1021_10210601_39_dialog_content = "그럼 이참에 내가 선심 좀 써서 레디젤 렌치 대신 보답을 해야 되지 않겠어?",
  ui_story_1021_10210601_40_dialog_content = "역시 로이 오빠는 대단하다니까!\n어쩐지 사메야마 대장이 맨날 우리한테 로이 오빠 보고 많이 배우라는 이유가 있었네!",
  ui_story_1021_10210601_41_dialog_content = "자, 그럼 가자. 저 검은 물줄기를 따라가면서 주변의 암귀 놈들이나 해치우자고!",
  ui_story_1021_10210601_42_dialog_content = "<color=#e8d9bb>북방의 변경 지대</color>",
  ui_story_1021_10210601_43_dialog_content = "『주인님... 더는 가셔서는 안 됩니다...』",
  ui_story_1021_10210601_44_dialog_content = "『이 앞엔 사악한 등대가 있어서 저희의 몸을 산산조각 낸다고 합니다...』",
  ui_story_1021_10210601_45_dialog_content = "『얼음은 가려울 뿐이고, 화산도 열풍이 부는 정도일 뿐. 등대 역시 그 정도에 지나지 않습니다.』",
  ui_story_1021_10210601_46_dialog_content = "<color=#e8d9bb>아우우──!</color>",
  ui_story_1021_10210601_47_dialog_content = "『저 하얀 짐승들이 왔습니다.』",
  ui_story_1021_10210601_48_dialog_content = "『오랜 세월이 흘러 성채도 호위도 없어졌건만, 저 짐승들은 아직도 사라지지 않았군요.』",
  ui_story_1021_10210601_49_dialog_content = "『역시 북방이란 참 매력적인 곳입니다.』",
  ui_story_1021_10210601_50_dialog_content = "얼음의 칼날이여──!",
  ui_story_1021_10210601_51_dialog_content = "북방에 침입한 자, 얼음 속에서 끝을 맞이하라.",
  ui_story_1021_10210601_52_dialog_content = "놓아 주었는데도 굳이 쫓아오다니요.",
  ui_story_1021_10210601_53_dialog_content = "그 얼음의 장벽으로... 다시 우릴 막을 셈입니까?",
  ui_story_1021_10210601_54_dialog_content = "...그대는 <color=#FFB400>그 전쟁</color>에 대해 무엇을 알고 있지?",
  ui_story_1021_10210601_55_dialog_content = "아무래도 당신은 아직 젊은 모양이로군요.",
  ui_story_1021_10210601_56_dialog_content = "『자, 가서 그녀와 놀아 주십시오.』",
  ui_story_1021_10210601_57_dialog_content = "『예, 주인님!』",
  ui_story_1021_10210700_1_dialog_content = "...여왕 폐하께서 지한테 고마 뭔 수를 쓰든 여 와가꼬 단디 말씀드리라 캤심더.",
  ui_story_1021_10210700_2_dialog_content = "그라이까네... 요래 된 일이었심더...",
  ui_story_1021_10210700_3_dialog_content = "어둠의 밑바닥에 들어서기도 전에 연합 탐색이 먼저 시작되었군.",
  ui_story_1021_10210700_4_dialog_content = "그렇다면 우리도 어떻게든 북방의 거점을 지켜야 한다. 비비안, 우린 즉시 북방으로 출발한다.",
  ui_story_1021_10210700_5_dialog_content = "네, 대원수님.",
  ui_story_1021_10210700_6_dialog_content = "미즈 블랑, 내 출정에 동행하도록.",
  ui_story_1021_10210700_7_dialog_content = "네, 성주님.",
  ui_story_1021_10210700_8_dialog_content = "회장, 우리도 가는 거지?",
  ui_story_1021_10210700_9_dialog_content = "저런 자리에 우리 움브라톤이 빠져서야 되겠어요?",
  ui_story_1021_10210700_10_dialog_content = "근데 거긴 해발고도가 높은 북방이라고...",
  ui_story_1021_10210700_11_dialog_content = "북방은 확실히 움브라톤과는 다르죠. 베델 씨, 우리 비행기를 타고 같이 가도록 해요.",
  ui_story_1021_10210700_12_dialog_content = "네, 고마워요.",
  ui_story_1021_10210700_13_dialog_content = "티, 티아라... 좀 걷게 해 주면 안 될까?! 허리가 아파서 못 참겠어...",
  ui_story_1021_10210700_14_dialog_content = "<color=#e8d9bb>콰당──</color>",
  ui_story_1021_10210700_15_dialog_content = "진짜로 날 업고... 이렇게 한참 달릴 줄은 몰랐다고!",
  ui_story_1021_10210700_16_dialog_content = "네가 된다고 하니까 그랬지. 설마 외지인들은 다 큰소리 치길 좋아하는 거야?",
  ui_story_1021_10210700_17_dialog_content = "그런 건 아닌데... 난 또 네가 그냥 해 본 말인 줄 알았지...",
  ui_story_1021_10210700_18_dialog_content = "이제 네가 눈여우 부족의 리더라는 걸 납득할 수 있을 것 같아!",
  ui_story_1021_10210700_19_dialog_content = "...휴! 아무튼 드디어 윈터 팰리스가 보이네...",
  ui_story_1021_10210700_20_dialog_content = "아우우──!",
  ui_story_1021_10210700_21_dialog_content = "어? 뭐 하는 거야...?",
  ui_story_1021_10210700_22_dialog_content = "<color=#e8d9bb>아우우──</color>",
  ui_story_1021_10210700_23_dialog_content = "답이 왔잖아...?!",
  ui_story_1021_10210700_24_dialog_content = "방금 그건 내가 여우들이랑 정보를 전달하는 방식이야.",
  ui_story_1021_10210700_25_dialog_content = "...방금 뭘 얘기했는데?",
  ui_story_1021_10210700_26_dialog_content = "여우들한테 이 근처는 검은 물의 영향을 안 받았다고 전했어.\n그랬더니 노비오 님한테 전해드리겠다고 답이 왔어.",
  ui_story_1021_10210700_27_dialog_content = "그냥 한 번 외친 건데 그렇게 많은 정보를 전달할 수 있는 거야?",
  ui_story_1021_10210700_28_dialog_content = "너도 한번 해 봐도 돼!",
  ui_story_1021_10210700_29_option_content = "내가? 난 됐어...",
  ui_story_1021_10210700_30_dialog_content = "너 이게 창피해?",
  ui_story_1021_10210700_31_dialog_content = "그, 그런 건 아냐... 왜 그렇게 생각하는데?",
  ui_story_1021_10210700_32_dialog_content = "윈터 팰리스에 들어간 지 얼마 안 됐을 때, 왕실 호위들이 종종 날 따라 했거든...",
  ui_story_1021_10210700_33_dialog_content = "처음엔 시끄러워서 그러는 건가 했는데, 나중에야 소리가 문제가 아니었다는 걸 알게 됐어.",
  ui_story_1021_10210700_34_dialog_content = "뭐, 알 게 뭐야. 그러면 그런 거지!\n그 뒤로 난 윈터 팰리스에서는 이 습관을 없애려고 노력했어...",
  ui_story_1021_10210700_35_dialog_content = "그래도 혼자 숲을 순찰할 때나, 다들 잠이 든 밤에는 지금처럼 여우들이랑 교류하고 있어.",
  ui_story_1021_10210700_36_dialog_content = "그거 하나도 창피할 거 없어! 봐──!",
  ui_story_1021_10210700_37_dialog_content = "으아아아──!",
  ui_story_1021_10210700_38_option_content = "으아아아──",
  ui_story_1021_10210700_39_dialog_content = "어때?",
  ui_story_1021_10210700_40_dialog_content = "......",
  ui_story_1021_10210700_41_dialog_content = "그 표정 뭔데... 그렇게 듣기 불편했어?",
  ui_story_1021_10210700_42_dialog_content = "아니, 네가 전한 뜻을 생각하고 있었어.\n「맛있다」인지, 「멋있다」인지, 아니면 「매섭다」인지...",
  ui_story_1021_10210700_43_dialog_content = "한 번 더 울어 봐.",
  ui_story_1021_10210700_44_dialog_content = "어... 역시 하지 말자.",
  ui_story_1021_10210700_45_dialog_content = "울 때는 이렇게 고개를 들고, 목을 잘 펴야 돼.",
  ui_story_1021_10210700_46_dialog_content = "고개를 들고... 목을 펴고...",
  ui_story_1021_10210700_47_dialog_content = "그리고 입을 크게 벌리고, 마음속으로 하고 싶은 말을 전부 한숨에 내뱉는 거야!",
  ui_story_1021_10210700_48_dialog_content = "아우우──!",
  ui_story_1021_10210700_49_dialog_content = "<color=#e8d9bb>아우우──</color>",
  ui_story_1021_10210700_50_dialog_content = "어때? 잘됐지?",
  ui_story_1021_10210700_51_dialog_content = "우와! 제대로 전달됐을진 잘 모르겠지만, 그래도 대답이 돌아오니까 정말 뿌듯하네!",
  ui_story_1021_10210700_52_dialog_content = "네 축복을 받아서 여우들도 분명히 행복할 거야.",
  ui_story_1021_10210700_53_dialog_content = "자, 그럼 충분히 쉰 것 같으니까, 단번에 윈터 팰리스까지 메고 가 줄게!",
  ui_story_1021_10210700_54_dialog_content = "자, 잠깐만! 적어도 머리를 앞쪽으로 메 줘야지──!",
  ui_story_1021_10210700_55_dialog_content = "어? 자리야 씨잖아? 오늘도 광석을 많이 캤네~",
  ui_story_1021_10210700_56_dialog_content = "여왕 폐하께서 처음으로 맡겨주신 일인걸. 당연히 잘 해내야지!",
  ui_story_1021_10210700_57_dialog_content = "자리야 씨는 엄청 강한 루미나틱스를 다룰 수 있다고 들었어.\n그럼 일도 분명히 쉽게 해낼 수 있겠네!",
  ui_story_1021_10210700_58_dialog_content = "그건 딱히 그렇지도 않아... 지금도 여전히 내가 날 얼어버릴 때가 있거든...",
  ui_story_1021_10210700_59_dialog_content = "그나마 일부분이라서 다행이지만 말이야! 아무튼 그러니까 연습을 많이 해야 돼!\n그럼 난 여왕 폐하를 만나러 윈터 팰리스에 가야 하니까 다음에 봐!",
  ui_story_1021_10210700_60_dialog_content = "어... 여왕 폐하는 윈터 팰리스에 안 계신다던데...",
  ui_story_1021_10210700_61_dialog_content = "<color=#e8d9bb>휘익──!</color>",
  ui_story_1021_10210700_62_dialog_content = "으앗?!",
  ui_story_1021_10210700_63_dialog_content = "방금 그거... PlayerName? 그리고 티아라까지... 왜 여기 있는 거지?",
  ui_story_1021_10210700_64_dialog_content = "거의 다 돌아본 것 같은데, 네 창이 딱히 변하는 것 같진 않네...",
  ui_story_1021_10210700_65_dialog_content = "역시 너무 오랜 시간이 흘러서 태고의 힘도 잠들어 버린 걸까...",
  ui_story_1021_10210700_66_dialog_content = "노비오 씨는 전설 속에서 단서를 찾아야 한다고 했어. 뭐 떠오르는 거 있어?",
  ui_story_1021_10210700_67_dialog_content = "첫 번째 전설은 「신은 이 세상에 평화를 가져오는 국왕의 고단함을 없애준다」야.\n어쩌면 윈터 팰리스의 눈소나무는 이 첫 번째 전설이랑 대응할지도 몰라.",
  ui_story_1021_10210700_68_dialog_content = "여왕 폐하는 평소에 피로를 어떻게 푸시는데?",
  ui_story_1021_10210700_69_dialog_content = "폐하께선 윈터 팰리스에 오래 안 계셔. 평소엔 침전이나 정원, 아니면 식당에 계실 때가 많아.",
  ui_story_1021_10210700_70_dialog_content = "그럼 여왕님의 피로 회복법도 사실 나랑 별로 다를 게 없는 거였구나.\n잠을 자거나, 멍하니 있거나, 맛있는 걸 먹거나...",
  ui_story_1021_10210700_71_dialog_content = "근데 여왕 폐하는 네가 말한 그런 일은 거의 안 하시던데...",
  ui_story_1021_10210700_72_dialog_content = "너희 뭐가 그렇게 급해? 여왕 폐하 찾는 거야? 무슨 일 있어?",
  ui_story_1021_10210700_73_dialog_content = "...?! 너 그 광석...",
  ui_story_1021_10210700_74_dialog_content = "아, 오해하지 마! 이건 네 고향 근처에서 가져온 거 아니니까!",
  ui_story_1021_10210700_75_dialog_content = "자리야, 네가 여긴 웬일이야?",
  ui_story_1021_10210700_76_dialog_content = "아까 나 못 봤어? 너희가 엄청나게 빨리 달려가는 걸 봤거든.\n여왕 폐하한테 급한 볼일 있는 거 맞지?",
  ui_story_1021_10210700_77_dialog_content = "근데 여왕 폐하는 지금 윈터 팰리스에 안 계신대. 그래서 알려주러 온 거야.",
  ui_story_1021_10210700_78_dialog_content = "그건 이미 알고 있어.",
  ui_story_1021_10210700_79_dialog_content = "그럼 여기서 뭐 하는 건데...?",
  ui_story_1021_10210700_80_dialog_content = "물건을 찾고 있어.",
  ui_story_1021_10210700_81_dialog_content = "물건...? 뭔지 말해 볼래? 내가 도와줄 수 있을지도 모르잖아.",
  ui_story_1021_10210700_82_dialog_content = "우린 지금... 여왕 폐하의 피로를 풀 수 있는 걸 찾고 있어.",
  ui_story_1021_10210700_83_dialog_content = "그거 왠지... 아이들이 전설을 따라 모험 놀이를 하는 것처럼 들리네...",
  ui_story_1021_10210700_84_dialog_content = "그런 놀이가 많아?",
  ui_story_1021_10210700_85_dialog_content = "물론이지, 폐하의 정원엔 늘 모험 놀이를 즐기는 아이들이 있어.",
  ui_story_1021_10210700_86_dialog_content = "여왕님의 궁전인데 애들이 막 들어가서 놀 수 있는 거야?",
  ui_story_1021_10210700_87_dialog_content = "폐하는 윈터 팰리스를 한 번도 자신의 것으로 여기신 적 없으셨어.",
  ui_story_1021_10210700_88_dialog_content = "그분은 정말 근면하신 분이거든. 그러고 보니까 난 그분이 쉬는 것도 본 적 없어...",
  ui_story_1021_10210700_89_dialog_content = "여긴 의자나 소파도 있고, 심지어 정원엔 아름다운 흔들의자도 있지만,\n폐하는 한 번도 앉으신 적 없어.",
  ui_story_1021_10210700_90_dialog_content = "그럼 피로를 풀 수 있는 건... 설마... 티아라, 이쪽으로 와 봐!",
  ui_story_1021_10210700_91_dialog_content = "......",
  ui_story_1021_10210700_92_dialog_content = "어머?! 네 창이 빛나고 있어!",
  ui_story_1021_10210700_93_dialog_content = "역시... 맞았어!",
  ui_story_1021_10210700_94_dialog_content = "이건... 여왕 폐하의 왕좌잖아...?",
  ui_story_1021_10210700_95_dialog_content = "이게 너희가 찾던 물건이야?",
  ui_story_1021_10210700_96_dialog_content = "국왕의 피로를 풀 수 있는 물건이라면, 왕좌도 딱 맞겠네. 게다가 국왕을 상징하기도 하고...",
  ui_story_1021_10210700_97_dialog_content = "첫번째 눈소나무는 여왕 폐하의 왕좌가 된 거였구나...\n하지만 난 폐하가 앉아계시는 걸 본 적이 없는데...",
  ui_story_1021_10210700_98_dialog_content = "설마... 이 왕좌가 눈소나무와 관계가 있는 걸 알고 계셔서... 여기서 쉬지 않으신 걸까...?",
  ui_story_1021_10210700_99_dialog_content = "......",
  ui_story_1021_10210700_100_dialog_content = "의자가... 왠지 변하고 있는 것 같아...!",
  ui_story_1021_10210700_101_dialog_content = "충성을 맹세한 그 부족이 보낸 물건입니다. 이는 오직 폐하만을 위한 북방 여왕의 옥좌입니다.",
  ui_story_1021_10210700_102_dialog_content = "앞으로 폐하께서는 이 옥좌에 앉아 백성들을 다스리실 것입니다.",
  ui_story_1021_10210700_103_dialog_content = "북방의 설원과 숲을 전부 돌려면 얼마나 시간이 걸리느냐.",
  ui_story_1021_10210700_104_dialog_content = "그건... 폐하, 그것은 어찌 물으시는 것인지요.",
  ui_story_1021_10210700_105_dialog_content = "저 차가운 왕좌에 앉아 있어서는 북방을 지킬 수 없다.\n나는 저 얼음과 눈으로 뒤덮인 대지를 내 행동으로 한 곳도 빠짐없이 지킬 것이다.",
  ui_story_1021_10210700_106_dialog_content = "눈이 내리면서, 폐하께서 걸으셨던 길은 이미 새로운 길이 되었습니다.",
  ui_story_1021_10210700_107_dialog_content = "봄이 찾아올 무렵에는 산과 숲도 작년과는 다른 모습을 하고 있을 것입니다.",
  ui_story_1021_10210700_108_dialog_content = "그럼 계속 걸으마. 북방의 대지가 남김없이 등대의 가호를 받는 그때까지,\n는 걸음을 멈추지 않을 것이다.",
  ui_story_1021_10210700_109_dialog_content = "방금... 그건...",
  ui_story_1021_10210700_110_dialog_content = "설마 여왕 폐하께서 막 즉위하셨을 때의 모습인가...",
  ui_story_1021_10210700_111_dialog_content = "감응 능력을 사용하지 않고도 볼 수 있었다면... 아마 더 오래전 일일 거야...",
  ui_story_1021_10210700_112_dialog_content = "충성을 맹세한 부족이 소나무로 된 옥좌를 보냈지만, 여왕은 앉지 않았어.",
  ui_story_1021_10210700_113_dialog_content = "그리고 여왕 폐하도 저분의 의지를 이어, 늘 멈추지 않고 걷고 계셔...",
  ui_story_1021_10210700_114_dialog_content = "이것 좀 봐!",
  ui_story_1021_10210700_115_dialog_content = "왕좌가... 작은 소나무 가지가 돼버렸어...",
  ui_story_1021_10210700_116_dialog_content = "이게 바로 그 첫 번째 눈소나무인 모양이네.",
  ui_story_1021_10210700_117_dialog_content = "정말 신기한 힘이야...!",
  ui_story_1021_10210700_118_dialog_content = "이 눈소나무가 있으면 여왕 폐하를 도울 수 있어...",
  ui_story_1021_10210700_119_dialog_content = "응, 그럼 다음은 네가 살던 곳이야!",
  ui_story_1021_10210700_120_dialog_content = "가자!",
  ui_story_1021_10210700_121_dialog_content = "야, 너희들──! 다음에 또 모험 놀이 할 땐 나도 끼워줘...!",
  ui_story_1021_10210700_122_dialog_content = "<color=#e8d9bb>이렇게 하여 북방의 여왕은 옥좌가 없게 되었다.</color>",
  ui_story_1021_10210801_1_dialog_content = "<color=#e8d9bb>휘이잉──</color>",
  ui_story_1021_10210801_2_dialog_content = "갑자기 날씨가 안 좋아졌네...",
  ui_story_1021_10210801_3_dialog_content = "등대가 눈보라로 뒤덮여 버렸어... 폐하 쪽은 지금 상황이 어떨까...",
  ui_story_1021_10210801_4_dialog_content = "네 고향의 눈소나무에 대해선 뭔가 떠오르는 게 있어?",
  ui_story_1021_10210801_5_dialog_content = "「신의 약속은 어둠을 빛으로 바꾼다」, 그게 마지막 전설이야.",
  ui_story_1021_10210801_6_dialog_content = "왠지 증조할머니가 말씀해 주셨던 기억이 나...",
  ui_story_1021_10210801_7_dialog_content = "한때 북방엔 암흑의 시대가 있었다고 해. 하지만 신께서 약속하셨고, 끝내 북방에 빛을 전해 주셨어.",
  ui_story_1021_10210801_8_dialog_content = "「약속」이라... 좀 추상적인데 말이지...",
  ui_story_1021_10210801_9_dialog_content = "하지만 그 약속을 기억하고, 그걸 지키는 사람이 있는 한, 약속은 현실로 존재해.",
  ui_story_1021_10210801_10_dialog_content = "뭐, 이것도 증조할머니한테 들은 거지만 말이야...",
  ui_story_1021_10210801_11_dialog_content = "왠지 방법이 생각난 것 같아...",
  ui_story_1021_10210801_12_dialog_content = "너희 증조할머니는 분명히 그 「약속」을 기억하고, 지키셨을 거야.\n그럼 어쩌면 네 기억 속에 뭔가 단서가 있을지도 몰라...",
  ui_story_1021_10210801_13_dialog_content = "진짜?",
  ui_story_1021_10210801_14_dialog_content = "하지만 증조할머니는... 돌아가신 지 이미 오래됐고,\n게다가 내 기억 속에 정말 단서가 있을지도 잘 모르겠어...",
  ui_story_1021_10210801_15_dialog_content = "왜 그렇게 생각하는데?",
  ui_story_1021_10210801_16_dialog_content = "...보면 알 거야.",
  ui_story_1021_10210801_17_dialog_content = "응, 걱정 마. 아무튼 한번 시도해 보자!",
  ui_story_1021_10210801_18_option_content = "(감응 연결──)",
  ui_story_1021_10210801_19_dialog_content = "됐으니까 더는 말하지 마라!",
  ui_story_1021_10210801_20_dialog_content = "어차피 이제 곧 죽을 몸인데... 몇 마디 좀 더 하면 안 되는 겐가?",
  ui_story_1021_10210801_21_dialog_content = "증조할머니... 티아라랑 안 놀아줄 거야?",
  ui_story_1021_10210801_22_dialog_content = "티아라, 착하지... 이 할미에게 약속해 다오. 얼른 무럭무럭 자라는 게야...",
  ui_story_1021_10210801_23_dialog_content = "얼른 자라거라, 티아라...",
  ui_story_1021_10210801_24_dialog_content = "어찌 그리도 늦게 와 주었을꼬... 네가 다 크는 걸 이 할미가 볼 수도 없게 말이야...",
  ui_story_1021_10210801_25_dialog_content = "앞으로 몇 년 뒤면, 할미는 밤낮으로 늘 생각하던 그 사람을 만나러 가야 한단다...",
  ui_story_1021_10210801_26_dialog_content = "티아라, 이 할미를... 그리고 부족을 기억해 다오... 그리고...",
  ui_story_1021_10210801_27_dialog_content = "듣는 사람들 괴로울 말은 이제 그만해라.\n결국 아무도 기억하지 못할 것이고, 그 누구도 남지 않을 테니 말이다.",
  ui_story_1021_10210801_28_dialog_content = "티아라, 저쪽에서 여우들이랑 놀고 있거라.",
  ui_story_1021_10210801_29_dialog_content = "으앗... 이건 티아라 꼬리야...",
  ui_story_1021_10210801_30_dialog_content = "이건... 으음... 티아라가 직접 맞힐 거니까 알려주지 마!",
  ui_story_1021_10210801_31_dialog_content = "앞으로 더는 티아라를 이곳으로 데려오지 마라.",
  ui_story_1021_10210801_32_dialog_content = "티아라는 부족의 아이야. 저 아이는 반드시 부족의 영광을 기억해야 해.\n자신이 선조들의 축복을 받으며 태어났다는 것을 기억해야만 하는 게야.",
  ui_story_1021_10210801_33_dialog_content = "나는 티아라가 부족의 장을 계승하고, 북방의 호위를 배출하게 할 것이야...",
  ui_story_1021_10210801_34_dialog_content = "그 약속은 저 아이가 맡게 되겠지.",
  ui_story_1021_10210801_35_dialog_content = "한때는 여러 부족이 뜻을 모아 북쪽으로 향했으나,\n이제는 우리 눈여우 부족만이 이곳에 남아 이 대지를 지키고 있다.",
  ui_story_1021_10210801_36_dialog_content = "우리는 신의 약속이 이루어질 때까지 기다릴 수 없을 것이다.\n어쩌면 저 <color=#FFB400>석판</color>도 진작 신에게 잊힌 것일지도 모른다.",
  ui_story_1021_10210801_37_dialog_content = "노친네야, 만에 하나라도 티아라에게 그렇게 말하거든 절대 용서하지 않을 것이야.",
  ui_story_1021_10210801_38_dialog_content = "신은 결코 잊지 않아. 티아라가 있는 한, 저 석판은 계속 전해지겠지.",
  ui_story_1021_10210801_39_dialog_content = "...티아라가 그것들을 알기 전에 내가 석판을 부숴버릴 것이다.",
  ui_story_1021_10210801_40_dialog_content = "그 누구보다 저 석판을 아끼면서 무슨 소릴 하는 게야? 안 그럴 거 다 안다.",
  ui_story_1021_10210801_41_dialog_content = "다른 선택지는 없다.",
  ui_story_1021_10210801_42_dialog_content = "이런 것을 티아라에게 물려 줄 필요는 없다.\n저 모습을 좀 봐라. 여느 아이처럼 천진난만하게 키울 순 없는 것이냐.",
  ui_story_1021_10210801_43_dialog_content = "저 아이가 지켜야 할 것은 부족이다! 저 차디찬 왕궁이 아니란 말이다!",
  ui_story_1021_10210801_44_dialog_content = "왕실은 신의 힘을 빼앗았어. 그 은혜에 보답하지도 않았을 뿐만 아니라,\n목숨 걸고 변방을 지킨 호위를 침입자와 함께 성채에 얼음으로 봉인했지...",
  ui_story_1021_10210801_45_dialog_content = "천 년이 지났거늘... 저 얼음이 어디 녹은 적이 있었다더냐...",
  ui_story_1021_10210801_46_dialog_content = "저 잔혹한 세월을 알게 되고도, 티아라가 지금처럼 즐겁게 살아갈 수 있다고 생각하나?",
  ui_story_1021_10210801_47_dialog_content = "약속, 가호... 그것들도 이제는 그저 잔인한 처사에 지나지 않는다.",
  ui_story_1021_10210801_48_dialog_content = "그 잔인함이 어떤 것인지 나는 이미 그대를 통해 깨달았다.\n그대가 태어났을 때부터... 마지막 순간까지...",
  ui_story_1021_10210801_49_dialog_content = "그런 소리 마라. 티아라는 반드시 그 잔인함과도 싸울 수 있는 강한 아이로 자랄 게야.\n저 아이의 선조들이 그랬던 것처럼 말이야.",
  ui_story_1021_10210801_50_dialog_content = "......",
  ui_story_1021_10210801_51_dialog_content = "증조할머니──! 여우가 증조할머니한테 무서운 할멈이래! 아하하하... 간지럽다니까!",
  ui_story_1021_10210801_52_dialog_content = "으앗...! 티아라는 지지 않아!",
  ui_story_1021_10210801_53_dialog_content = "......",
  ui_story_1021_10210801_54_dialog_content = "왜 그래? 그 표정은 뭐야?",
  ui_story_1021_10210801_55_dialog_content = "...증조할머니랑 장로님이 말다툼하시는 게 보였어?",
  ui_story_1021_10210801_56_dialog_content = "응, 네가 부족의 우두머리가 되는 걸 두고 두 사람의 의견이 엇갈리는 걸 봤어.",
  ui_story_1021_10210801_57_dialog_content = "장로님이 널 우두머리로 세우는 걸 원하지 않으셨다는 건 처음 알았어...",
  ui_story_1021_10210801_58_dialog_content = "맞아... 장로님은 외지인이 오는 것만 싫어하시는 게 아니라,\n사실 내가 부족에 돌아오는 것조차 원하지 않으셔...",
  ui_story_1021_10210801_59_dialog_content = "어쩌면 장로님은 내가 리더가 되면 부족이 이렇게 될 걸 진작에 예상하셨을지도 몰라.",
  ui_story_1021_10210801_60_dialog_content = "장로님이 걱정하신 건 그게 아냐. 네가 앞으로 즐겁게 살지 못하고,\n증조할머니처럼 증오 속에서 일생을 보내게 될까 걱정하셨던 거야.",
  ui_story_1021_10210801_61_dialog_content = "즐겁게...?",
  ui_story_1021_10210801_62_dialog_content = "...그래서 내가 부족에 대한 생각을 끊고, 항상 여왕 폐하의 호위로서\n직분을 다하라고 말씀하셨던 거야...?",
  ui_story_1021_10210801_63_dialog_content = "근데 그런 내색은 조금도 안 하셨어...",
  ui_story_1021_10210801_64_dialog_content = "어렸을 땐 내가 제단에 못 가게 하셨고...",
  ui_story_1021_10210801_65_dialog_content = "전설을 말씀해 주지도 않으셨어...",
  ui_story_1021_10210801_66_dialog_content = "부족이 위기에 빠졌을 땐 오히려 날 쫓아내셨고...",
  ui_story_1021_10210801_67_dialog_content = "장로님은 부족을 진심으로 사랑해. 하지만 그보다 널 더 소중하게 생각하셨던 거야...",
  ui_story_1021_10210801_68_dialog_content = "......",
  ui_story_1021_10210801_69_dialog_content = "그럼 나 티아라는 눈여우 부족의 리더로서 더더욱 맹세를 어길 순 없어...!",
  ui_story_1021_10210801_70_dialog_content = "난 여왕 폐하를 믿어. 「원시의 성역」을 깨우기만 한다면... 분명히 부족을 구할 수 있을 거야!",
  ui_story_1021_10210801_71_dialog_content = "그렇게 되면 장로님도 더는 날 쫓아내지 않으시겠지!",
  ui_story_1021_10210801_72_dialog_content = "응, 티아라 너라면 분명히 할 수 있어!",
  ui_story_1021_10210801_73_dialog_content = "그나저나... 결국 내 기억 속에 눈소나무에 대한 단서는 없었던 거지?",
  ui_story_1021_10210801_74_dialog_content = "아니, 두 분이 했던 얘기 중에 석판에 관한 내용이 있었어...\n왠지 신이 눈여우 부족에게 했던 약속을 적어놓은 석판이라던 것 같아.",
  ui_story_1021_10210801_75_dialog_content = "석판이라면...",
  ui_story_1021_10210801_76_dialog_content = "너희 증조할머니 말로는 장로님이 그 석판을 누구보다 아꼈었다고 해.",
  ui_story_1021_10210801_77_dialog_content = "하지만 그 석판은 어쩌면 장로님이 이미 부숴버렸을 수도 있어...",
  ui_story_1021_10210801_78_dialog_content = "......",
  ui_story_1021_10210801_79_dialog_content = "잘 생각해 봐. 소중하게 생각한 석판이라면 분명히 자주 보러 가셨을 거야.",
  ui_story_1021_10210801_80_dialog_content = "장로님이 자주 가시는 곳이라면... 동굴, 제단, 산, 그리고...",
  ui_story_1021_10210801_81_dialog_content = "설마...",
  ui_story_1021_10210801_82_dialog_content = "내가 부족을 떠나기 전에, 장로님은 항상 이 근처에서 등대를 보고 계셨어.\n한 번 보기 시작하면 하루 종일 보셨고 말이야...",
  ui_story_1021_10210801_83_dialog_content = "근데 여긴 나무 말고는 아무것도 없어 보이는데...",
  ui_story_1021_10210801_84_dialog_content = "...누구냐! 어딜 도망치려고?!",
  ui_story_1021_10210801_85_dialog_content = "이, 이런... 또 꼬마 아가씨한테 잡혔네...",
  ui_story_1021_10210801_86_dialog_content = "두 사람이 왜 또 여기 있어요?",
  ui_story_1021_10210801_87_dialog_content = "모처럼 좋은 마음으로 주변의 암귀를 청소해 줬는데,\n여기 리더님은 원래 은인한테 보답을 이렇게 하시나?",
  ui_story_1021_10210801_88_dialog_content = "당신들처럼 수상한 자들이 그럴 리가 없어! 또 보석을 훔치고 있었던 거 아냐?!",
  ui_story_1021_10210801_89_dialog_content = "저 동굴에서 살아 나온 것만으로도 행운이라고. 보석 같은 거 신경 쓸 겨를도 없었다니까.",
  ui_story_1021_10210801_90_dialog_content = "크흠... 로이 오빠, 좀 더 진지하게 말할 순 없어?",
  ui_story_1021_10210801_91_dialog_content = "레디젤 렌치도 연합 탐색의 멤버니까 동료의 목숨을 저버릴 순 없다고 그랬었잖아!",
  ui_story_1021_10210801_92_dialog_content = "그래서 우린 동굴에서 나온 뒤에 너희가 안 보이니까,\n여기서 보이는 암귀를 닥치는 대로 없애고 있었던 거야!",
  ui_story_1021_10210801_93_dialog_content = "그러고 보니까 확실히 오는 길에 암귀는 하나도 없었어... 정말 고마워!",
  ui_story_1021_10210801_94_dialog_content = "그건... 여기가 등대의 빛이 닿는 가장 먼 경계선이라서 그래!",
  ui_story_1021_10210801_95_dialog_content = "...그, 그걸 우리가 어떻게 알아? 여긴 뭐 경계석도 없고... 아니, 그럼 우린 쓸데없이 고생한 거야?",
  ui_story_1021_10210801_96_dialog_content = "로이 오빠, 나 왠지 아까 경계석을 본 것 같긴 해...",
  ui_story_1021_10210801_97_dialog_content = "티아라! 설마 타이니가 말한 경계석이...",
  ui_story_1021_10210801_98_dialog_content = "석판이야!",
  ui_story_1021_10210801_99_dialog_content = "얼른 창이 공명하는지 확인해 봐!",
  ui_story_1021_10210801_100_dialog_content = "「자연의 힘이여, 얼음 끝에 모여라!」",
  ui_story_1021_10210801_101_dialog_content = "아까도 이 정도로 밝았으면 쓸데없이 힘쓸 일도 없었을 텐데 말이야...",
  ui_story_1021_10210801_102_dialog_content = "이 빛나는 글씨... 아마 눈소나무의 기름으로 썼을 거야.",
  ui_story_1021_10210801_103_dialog_content = "증조할머니가 그러셨어. 우리의 눈소나무 기름등은 북방의 눈이라고.",
  ui_story_1021_10210801_104_dialog_content = "밤에 보면 되게 밝을 것 같아...",
  ui_story_1021_10210801_105_dialog_content = "설마 눈소나무가 등대 빛의 경계를 나타내는 경계석 역할을 하게 됐을 줄은 몰랐네.",
  ui_story_1021_10210801_106_dialog_content = "어?! 이게 뭐야...?",
  ui_story_1021_10210801_107_dialog_content = "위대한 북방의 호위들이여. 전쟁은 끝이 났고, 등대도 세워졌다.",
  ui_story_1021_10210801_108_dialog_content = "얼음에 갇힌 저 우뚝 선 고성은 변방에서 희생된 전사들을 기리고,\n적에게 두려움을 주며, 또한 나를 일깨우고 있다.",
  ui_story_1021_10210801_109_dialog_content = "이에 나는 이 땅에서 그대들에게 약속하겠다.",
  ui_story_1021_10210801_110_dialog_content = "내가 선 곳은 결코 빛과 어둠의 경계로 남지는 않을 것이다.\n등대의 빛은 반드시 이곳을 비출 것이다!",
  ui_story_1021_10210801_111_dialog_content = "그대들의 가족은 이 광활한 북방에서 생업에 힘쓰며 평안한 삶을 누릴 것이다.",
  ui_story_1021_10210801_112_dialog_content = "뭇 산과 강이여, 부디 내 맹세의 증인이 되어 등대에 힘을 주고 우리의 북방을 지키소서.",
  ui_story_1021_10210801_113_dialog_content = "그대들 또한 신과 더불어 내 맹세의 증인이 되도록 하라.",
  ui_story_1021_10210801_114_dialog_content = "나는 북방의 첫 여왕이요, 나의 자손과 후세는 반드시 북방을 지키는 마지막 호위가 되겠노라!",
  ui_story_1021_10210801_115_dialog_content = "나는 북방을 지키고, 나의 자손과 후세는 북방을 지키는 마지막 호위가 되기를 바라노라!",
  ui_story_1021_10210801_116_dialog_content = "북방의 초대 여왕은 정말 비범한 사람이었구나...!",
  ui_story_1021_10210801_117_dialog_content = "...석판에 적혀있던 「약속」은 신이 너희 부족에 한 약속이 아니었던 거야...",
  ui_story_1021_10210801_118_dialog_content = "당시의 여왕과 변방의 호위들이 서로 나눈 약속이었어...",
  ui_story_1021_10210801_119_dialog_content = "그래서 내 선조님들은 줄곧 이곳에서 북방을 지켰어...\n하지만 여왕의 약속은 아무리 기다려도 이루어지지 않았고, 부족은 서서히 쇠락해 갔어...",
  ui_story_1021_10210801_120_dialog_content = "그래서 결국 왕실에 원한을 가지게 됐던 거지...",
  ui_story_1021_10210801_121_dialog_content = "그치만 등대의 빛이 부락까지 닿는 건 거의 불가능한 일이잖아...",
  ui_story_1021_10210801_122_dialog_content = "맞아... 하지만 여왕 폐하는 그동안 계속 쉬지 않고 변방의 순시를 계속해 오셨어.",
  ui_story_1021_10210801_123_dialog_content = "그러니까 난 믿어... 부족이나 왕실이나, 그 누구도 약속을 어기지 않았던 거야.",
  ui_story_1021_10210801_124_dialog_content = "그리고 지금은 함께 「원시의 성역」을 깨우려 하고, 북방을 지키는 중임은 내게 맡겨졌어...",
  ui_story_1021_10210801_125_dialog_content = "그게 바로 노비오 님이 말씀하셨던, 내가 이해해야 할 나의 사명이었어!",
  ui_story_1021_10210801_126_dialog_content = "너랑 같이 눈소나무를 찾으면서, 왠지 난 북방에 대해 다시 인식하게 된 것 같아.",
  ui_story_1021_10210801_127_dialog_content = "석판도 왕좌처럼 원래 모습으로 돌아가고 있는 것 같아...",
  ui_story_1021_10210801_128_dialog_content = "이게 두 번째 눈소나무야.",
  ui_story_1021_10210801_129_dialog_content = "그럼 세 번째 눈소나무만 남았는데... 여왕 폐하가 정말 등대의 불을 끄실까...?",
  ui_story_1021_10210801_130_dialog_content = "이제 난 더는 여왕 폐하께 그 어떤 의문도 없어.\n폐하께서 무엇을 하시든, 난 그분 곁에서 힘이 되어드릴 거야!",
  ui_story_1021_10210801_131_dialog_content = "얼른 눈소나무를 가지고 가자!",
  ui_story_1021_10210801_132_dialog_content = "응!",
  ui_story_1021_10210801_133_dialog_content = "아 참, 그리고... 당신들도 고마워!",
  ui_story_1021_10210801_134_dialog_content = "하하, 별것 아냐.",
  ui_story_1021_10210801_135_dialog_content = "로이 오빠, 기왕 찾아서 만났으니까, 우리도 따라가서 도와주자.",
  ui_story_1021_10210801_136_dialog_content = "휴, 정말 못 말린다니까. 그래, 가자.",
  ui_story_1021_10210801_137_dialog_content = "<color=#e8d9bb>이렇게 하여 부족과 왕실 간 약속의 석판은 없게 되었다.</color>",
  ui_story_1021_10210801_138_dialog_content = "장로님! 노비오 님! 저희 돌아왔어요! 소나무를 가지고...",
  ui_story_1021_10210801_139_dialog_content = "제단에... 무슨...?!",
  ui_story_1021_10210801_140_dialog_content = "저것은 여왕 폐하가 자신의 몸에서 나눠주신 「불씨」의 힘입니다.\n지금 힘을 응축해서 등불의 「심지」가 되려는 중입니다.",
  ui_story_1021_10210801_141_dialog_content = "「심지」... 그럼 그 절벽에 있는 등대의 빛이 꺼지게 되는 건가요?",
  ui_story_1021_10210801_142_dialog_content = "아닙니다. 여왕 폐하는 아주 오래전 북방의 등대가 되셨습니다. 저것은 폐하의 생명의 힘입니다.",
  ui_story_1021_10210801_143_dialog_content = "생명의 힘이라니... 그럼 폐하의 몸이 약해지게 되시는 건가요?!",
  ui_story_1021_10210801_144_dialog_content = "비록 약해지신다 해도, 폐하는 이미 암귀를 북방의 변경까지 몰아내셨습니다...",
  ui_story_1021_10210801_145_dialog_content = "폐하께서 그렇게까지 하시다니...",
  ui_story_1021_10210801_146_dialog_content = "비록 오랜 시간이 흘렀지만, 약속했던 등대는 여러분의 도움 덕분에 곧 세워질 것입니다.",
  ui_story_1021_10210801_147_dialog_content = "그럼 이제 제가 뭘 해야 하죠?",
  ui_story_1021_10210801_148_dialog_content = "가져온 소나무 가지를 제단에 두고, 그 창의 힘으로 신께 돌려드리는 것이다.",
  ui_story_1021_10210801_149_dialog_content = "나와 함께 신께 기도해라...",
  ui_story_1021_10210801_150_dialog_content = "눈여우 부족의 장로이자, 북방의 위대한 전사 로데의 호위 하겐이 신의 도움을 청하나이다.",
  ui_story_1021_10210801_151_dialog_content = "눈여우 부족의 우두머리이자, 북방의 여왕 베들레헴 폐하의 호위 티아라가\n신의 도움을 청하나이다!",
  ui_story_1021_10210801_152_dialog_content = "북방의 여왕은 이미 그 약속을 지켰고, 「심지」와 소나무 가지 또한 당신의 힘을 취한 것입니다.",
  ui_story_1021_10210801_153_dialog_content = "당신의 것을 다시 돌려 드리오니 거두어 주시고, 만물을 기르는 힘으로 생명을 부어 주소서.",
  ui_story_1021_10210801_154_dialog_content = "원컨대 거친 환란 속에서 살아가는 북방에 오래도록 이어질 가호를 주소서──",
  ui_story_1021_10210801_155_dialog_content = "「산천의 지팡이여, 힘을 주소서!」",
  ui_story_1021_10210801_156_dialog_content = "<color=#e8d9bb>휘이잉── 휘이──!</color>",
  ui_story_1021_10210801_157_dialog_content = "...!!!",
  ui_story_1021_10210801_158_dialog_content = "세 그루터기가... 순식간에 하늘까지 닿을 커다란 나무가 됐어!",
  ui_story_1021_10210801_159_dialog_content = "이게 바로... 「원시의 성역」이 지닌 힘인가...?",
  ui_story_1021_10210801_160_dialog_content = "......",
  ui_story_1021_10210801_161_dialog_content = "창의 힘은 사라지지 않았어... 오히려 더 강한 힘이 들어오는 게 느껴져!",
  ui_story_1021_10210801_162_dialog_content = "번개처럼 반짝이는 건... 눈소나무 속에서 흘러 들어오는 에너지인 건가...?",
  ui_story_1021_10210801_163_dialog_content = "......",
  ui_story_1021_10210801_164_dialog_content = "세계의 등마루에서 선조들은 따뜻한 냇물을 발견했다.",
  ui_story_1021_10210801_165_dialog_content = "그 냇물은 마치 하늘이 내린 은혜처럼, 늘 얼음에 잠긴 북방을 유유히 흘러\n아스트라의 심장부 깊은 곳까지 이어졌지...",
  ui_story_1021_10210801_166_dialog_content = "그것이 바로 「원시의 성역」의 기원이다. 냇물은 우거진 눈소나무 숲을 적셨고,\n우리의 선조들도 이 숲에 뿌리를 내리고 싹을 틔웠다.",
  ui_story_1021_10210801_167_dialog_content = "이제 「원시의 성역」의 가호 아래, 눈소나무와 「심지」의 힘이 모였고,\n함께 이 새로운 「등대」를 세웠다.",
  ui_story_1021_10210801_168_dialog_content = "등대의 빛은 기나긴 겨울을 꿰뚫고, 아득히 이어지는 설산을 넘어 어둠을 몰아내어,\n생령들이 사랑하는 대지를 비출 것이다.",
  ui_story_1021_10210801_169_dialog_content = "그리고 티아라, 그대는 이제 신이 인정하는 북방의 호위가 된 것이다.",
  ui_story_1021_10210801_170_dialog_content = "신이 저를요...? 그래서 힘을 주신 거군요!",
  ui_story_1021_10210801_171_dialog_content = "제 손안의 얼음창이... 마치 타오르는 횃불 같아요!",
  ui_story_1021_10210801_172_dialog_content = "이로써 그대는 신이 내린 힘과 사명을 짊어지게 되었다...",
  ui_story_1021_10210801_173_dialog_content = "티아라, 그대의 용기와 지혜로 우리의 북방을 지켜라.",
  ui_story_1021_10210802_1_dialog_content = "지금 눈소나무 숲에서 솟아오른 저 빛... 설마 또 다른 고대의 유적인 건가...",
  ui_story_1021_10210802_2_dialog_content = "아니지, 저게 지금 나타났다는 건... 모종의 신호일지도 몰라!",
  ui_story_1021_10210802_3_dialog_content = "전설 속 등대는 인도와 가호의 역할을 해 왔어. 그렇다면 북방엔 여러 개의 등대가 있지 않았을까?",
  ui_story_1021_10210802_4_dialog_content = "어떻게 분포돼 있었던 거지?",
  ui_story_1021_10210802_5_dialog_content = "그 빛은 또 어떻게 이 대지를 비추고 있었던 거지...?",
  ui_story_1021_10210802_6_dialog_content = "<color=#e8d9bb>어느 비밀스러운 장소</color>",
  ui_story_1021_10210802_7_dialog_content = "역시 북방에 저 힘이 잠들어 있었어.",
  ui_story_1021_10210802_8_dialog_content = "수맥이 회복된 이상, 곧 바다로 흘러 들어가게 되겠지.",
  ui_story_1021_10210802_9_dialog_content = "우리가 이걸 본 걸 아시면 빅토리아 님도 분명히 기뻐하실 거야.",
  ui_story_1021_10210802_10_dialog_content = "그럼 우리도 슬슬 출발해 볼까.",
  ui_story_1021_10210802_11_dialog_content = "<color=#e8d9bb>일루미나의 비행기 안</color>",
  ui_story_1021_10210802_12_dialog_content = "...마치 설산에서 해가 뜬 것 같네요... 저런 빛은 정말 처음 봐요.",
  ui_story_1021_10210802_13_dialog_content = "저 방향을 향해 가속 전진한다!",
  ui_story_1021_10210802_14_dialog_content = "네!",
  ui_story_1021_10210901_1_dialog_content = "아무래도... 새로운 「등대」가 세워진 모양이로구나.",
  ui_story_1021_10210901_2_dialog_content = "여왕 폐하, 괜찮으십니까?! 아까 그 모습을 보고 제가 얼마나...",
  ui_story_1021_10210901_3_dialog_content = "이제 괜찮다, 카렌. 이제는 내게도, 그리고 북방에게도 더 강대한 방패가 생겼으니 말이다.",
  ui_story_1021_10210901_4_dialog_content = "캬아악──!",
  ui_story_1021_10210901_5_dialog_content = "『주인님... 너무... 괴롭습니다...』",
  ui_story_1021_10210901_6_dialog_content = "『아...아파...!』",
  ui_story_1021_10210901_7_dialog_content = "『이 감각... 생각이 나는군요...』",
  ui_story_1021_10210901_8_dialog_content = "『눈이 오던 날, 순록을 타고 온 여자...』",
  ui_story_1021_10210901_9_dialog_content = "『전부 떠올랐습니다.』",
  ui_story_1021_10210901_10_dialog_content = "『이번 수행은 가치가 있었습니다.』",
  ui_story_1021_10210901_11_dialog_content = "「힘이여, 얼음 끝에 모여라!」",
  ui_story_1021_10210901_12_dialog_content = "......",
  ui_story_1021_10210901_13_dialog_content = "캬아악──!",
  ui_story_1021_10210901_14_dialog_content = "여왕 폐하! 늦어서 죄송합니다!",
  ui_story_1021_10210901_15_dialog_content = "티아라, 방금 그 공격, 정말 정밀하고 강했어!",
  ui_story_1021_10210901_16_dialog_content = "왠지 그 창도, 당신 자신도 전보다 훨씬 더 강해진 것 같네!",
  ui_story_1021_10210901_17_dialog_content = "장로님은 이게 내가 신의 인정을 받은 증거라고 하셨어. 이제 난 여왕 폐하의 어엿한 호위야!",
  ui_story_1021_10210901_18_dialog_content = "북방의 호위인 거지!",
  ui_story_1021_10210901_19_dialog_content = "응, 북방의 호위!",
  ui_story_1021_10210901_20_dialog_content = "네게도 그대의 변화와 성장이 전해지는구나. 티아라, 잘했다.",
  ui_story_1021_10210901_21_dialog_content = "또한 나와 함께 새로운 등대를 만들어 주어서 고맙구나.",
  ui_story_1021_10210901_22_dialog_content = "여왕 폐하! 윈터 팰리스의 왕좌에 대한 일도, 왕실과 부족 사이의 약속도 이제 다 알았어요...",
  ui_story_1021_10210901_23_dialog_content = "그리고... 폐하께 말씀드리고 싶은 게 많습니다!\n하지만 지금 무엇보다 말씀드리고 싶은 건...",
  ui_story_1021_10210901_24_dialog_content = "앞으로도 저는 폐하를 따라가겠습니다! 이제 두 번 다시 혼자서 싸우시는 일은 없게 만들게요!",
  ui_story_1021_10210901_25_dialog_content = "「눈 녹은 물은 산천을 타고 풍요를 선사하고, 초목은 생명의 힘을 축복의 땅으로 이끄리라」...",
  ui_story_1021_10210901_26_dialog_content = "죽을 준비나 해! 암귀!",
  ui_story_1021_10210901_27_dialog_content = "기다려라, 티아라!",
  ui_story_1021_10210901_28_dialog_content = "폐하...?",
  ui_story_1021_10210901_29_dialog_content = "그대는 어째서 그 전쟁만이 아니라... 북방의 축복까지 알고 있는 것이냐.",
  ui_story_1021_10210901_30_dialog_content = "그 시절의 설국은 온통 고요했습니다.",
  ui_story_1021_10210901_31_dialog_content = "하늘에는 칠흑의 태양이 떠오르고, 그분께선 우리의 가까이에 계셨습니다...",
  ui_story_1021_10210901_32_dialog_content = "그러나 그때 그 여자가 나타났습니다...",
  ui_story_1021_10210901_33_dialog_content = "......",
  ui_story_1021_10210901_34_dialog_content = "북방의 초대 여왕을 만난 적이 있나?",
  ui_story_1021_10210901_35_dialog_content = "그 여자는 손에 쥔 빛으로 이 지붕을 부수었고, 우리를 그분과 영원히 떨어지게 만들었습니다.",
  ui_story_1021_10210901_36_dialog_content = "전 그 칠흑의 태양을 다시 한번 보고 싶다고 생각했습니다.",
  ui_story_1021_10210901_37_dialog_content = "그러나 여자의 손에 쥔 물건은 제 두 눈을 찢었지요.",
  ui_story_1021_10210901_38_dialog_content = "이번 수행에서 저는 모든 것을 떠올렸습니다...",
  ui_story_1021_10210901_39_dialog_content = "그러나 제 두 눈에 담겼던 마지막 불꽃은 분노가 아니었습니다...",
  ui_story_1021_10210901_40_dialog_content = "...애초에 분노가 아니었단 말입니다!",
  ui_story_1021_10210901_41_dialog_content = "그 빛이 다시 흔들리며 제 세계를 분노의 빛으로 물들였던 것입니다!",
  ui_story_1021_10210901_42_dialog_content = "『나는 얼음도, 불꽃도 두려워하지 않는다...』",
  ui_story_1021_10210901_43_dialog_content = "『그러나 저 흔들리며 다가오는 하얀 것은... 대체 뭐냐...』",
  ui_story_1021_10210901_44_dialog_content = "등대다! 여왕 폐하의 등대다──!",
  ui_story_1021_10210901_45_dialog_content = "여왕 폐하께서 등대와 함께 우릴 구하러 오셨다!",
  ui_story_1021_10210901_46_dialog_content = "『등대...』",
  ui_story_1021_10210901_47_dialog_content = "캬아악──!",
  ui_story_1021_10210901_48_dialog_content = "전부 생각났습니다.",
  ui_story_1021_10210901_49_dialog_content = "전부...",
  ui_story_1021_10210901_50_dialog_content = "이제 수행은 끝났습니다. 당신들은 보내줄 테니 도망치십시오.",
  ui_story_1021_10210901_51_dialog_content = "......",
  ui_story_1021_10210901_52_dialog_content = "미안한데 난 널 놔줄 생각이 없어!",
  ui_story_1021_10210901_53_dialog_content = "네가 부족과 여우들에게 한 짓을 열 배로 갚아 주겠어!",
  ui_story_1021_10210901_54_dialog_content = "도망치지 않겠다면... 이쪽으로 오십시오.",
  ui_story_1021_10210901_55_dialog_content = "티아라!",
  ui_story_1021_10210901_56_dialog_content = "「힘이여, 얼음 끝에 모여라!」",
  ui_story_1021_10210901_57_dialog_content = "<color=#e8d9bb>콰콰쾅──!</color>",
  ui_story_1021_10210901_58_dialog_content = "아, 암귀... 절대 안 놓칠 거야... 콜록... 콜록콜록...",
  ui_story_1021_10210901_59_dialog_content = "티아라!",
  ui_story_1021_10210901_60_dialog_content = "조심해! 널 어둠의 밑바닥 쪽으로 끌어들이려는 거야!",
  ui_story_1021_10210901_61_dialog_content = "방금 그건... 폭탄인가?",
  ui_story_1021_10210901_62_dialog_content = "PlayerName, 위를 봐──",
  ui_story_1021_10210901_63_dialog_content = "목표엔 명중하지 않았어요... 하지만 PlayerName 일행이 암귀의 영지에 진입할 생각인 것 같아요.",
  ui_story_1021_10210901_64_dialog_content = "고도를 낮추고 엄호하라!",
  ui_story_1021_10210901_65_dialog_content = "네, 대원수님!",
  ui_story_1021_10210901_66_dialog_content = "회장, 거점에서... 싸우고 있어! 우리도...",
  ui_story_1021_10210901_67_dialog_content = "일루미나와 백야성 군대가 지원할 거예요. 괜히 가서 곤란하게 만들지 마세요.",
  ui_story_1021_10210901_68_dialog_content = "우린 갑판으로 가서 연합 탐색대의 깃발을 펼쳐요!",
  ui_story_1021_10210901_69_dialog_content = "전 부대 준비를 마쳤습니다. 언제든지 착륙할 수 있습니다!",
  ui_story_1021_10210901_70_dialog_content = "경계선을 따라 암귀를 소탕하고, 북방의 호위들을 지원하도록. 주요 전장은 저 젊은이들의 무대다.",
  ui_story_1021_10210901_71_dialog_content = "예, 성주 전하!",
  ui_story_1021_10210901_72_dialog_content = "일루미나의 비행기야...",
  ui_story_1021_10210901_73_dialog_content = "백야성의 비공정도... 다들 여길 주목하고 있어.",
  ui_story_1021_10210901_74_dialog_content = "하지만 저 암귀는 티아라를 도발해서 우릴 저쪽으로 끌어들이려는 것 같아...",
  ui_story_1021_10210901_75_dialog_content = "티아라가 너무 빨라! 이미 곧 저 「벽」을 넘어버릴 것 같아!",
  ui_story_1021_10210901_76_dialog_content = "저 「벽」을 넘으면 우리는 돌아올 수 없다.",
  ui_story_1021_10210901_77_dialog_content = "그러나 등대의 불빛은 이미 저편까지 비추고 있다. 따라오거라.",
  ui_story_1021_10210901_78_dialog_content = "내가 얼음으로 길을 열어 그대들을 산마루로 인도하마.\n티아라와 함께 우리가 저 암귀를 북방에서 쫓아내는 것이다!",
  ui_story_1021_10210901_79_dialog_content = "네!",
  ui_story_1021_10210901_80_dialog_content = "티아라──!",
  ui_story_1021_10210901_81_dialog_content = "더는 우릴 제쳐두지 마! 이건 우리가 함께 나설 싸움이야!",
  ui_story_1021_10210901_82_dialog_content = "여왕 폐하, 다들...\n뭐야, 당신들까지?",
  ui_story_1021_10210901_83_dialog_content = "말했잖아, 레디젤 렌치도 연합 탐색대의 일원이라구!",
  ui_story_1021_10210901_84_dialog_content = "그래, 너희라면 탐색을 시작하기 전에 분명히 뭔가 기운을 북돋는\n화합의 전통 의식 같은 걸 하겠지?",
  ui_story_1021_10210901_85_dialog_content = "전통 의식이니 뭐니 그런 건 잘 모르겠는데...",
  ui_story_1021_10210901_86_dialog_content = "그래도 북방 호위 티아라의 이름으로 맹세하겠어!\n이 암귀들은 절대 한 마리도 빠짐없이 몰아내겠다고!",
  ui_story_1021_10210901_87_dialog_content = "어느덧 오로리안의 연합 탐색이 이미 첫발을 내디디게 되었구나.",
  ui_story_1021_10210901_88_dialog_content = "이 앞은 암귀들이 「영지」라고 부르는 영역이다.\n그러나 살육을 수단으로 살아가는 암귀에게 생존의 기반 따위가 있어서는 아니 될 일이다.",
  ui_story_1021_10210901_89_dialog_content = "우리는 등대의 불빛을 따라 저들을 모조리 없애야만 할 것이다!",
  ui_story_1021_10210901_90_dialog_content = "여왕 폐하가 그런 말씀을 하실 줄은...",
  ui_story_1021_10210901_91_dialog_content = "티아라와 같은 이의 호위를 받으면, 나 또한 모르는 사이에 영향을 받게 되는 모양이구나.",
  ui_story_1021_10210901_92_dialog_content = "나는 그대들이 서로를 격려하고, 각자의 마음에 서로를, 북방을, 오로리안의 미래를 담길 바란다.",
  ui_story_1021_10210901_93_dialog_content = "그대들 모두가 서로의 등대가 될 때, 그대들의 힘은 비로소 눈앞의 공포를 초월할 것이다!",
  ui_story_1021_10210901_94_dialog_content = "......!",
  ui_story_1021_10210901_95_dialog_content = "오! 저기 산산조각난 돌 좀 봐! 저 암귀 아직 떠날 생각이 없는 것 같아!",
  ui_story_1021_10210901_96_dialog_content = "그렇다면 없애 버려라! 나도 그대들과 함께 어둠의 밑바닥을 향해 전진하겠다!",
  ui_story_1021_10210901_97_dialog_content = "전진──!",
  ui_story_1021_10210902_1_dialog_content = "좋습니다. 제 예상을 아득히 뛰어넘는군요...",
  ui_story_1021_10210902_2_dialog_content = "경지에 도달하기 위해, 저는 반드시 저 자신을 억제해야 합니다.",
  ui_story_1021_10210902_3_dialog_content = "저는 이제 가야겠습니다. 다만 당신들에게 해 둘 말이 있습니다...",
  ui_story_1021_10210902_4_dialog_content = "어둠의 향기를 맡으며 우리의 세계로 오십시오...",
  ui_story_1021_10210902_5_dialog_content = "당신들은 가는 곳마다 산을 이룬 선조들의 시체를 지나며,\n그들이 당신들의 이름을 외치는 것을 듣게 될 것입니다.",
  ui_story_1021_10210902_6_dialog_content = "저, 왕의 호위 아이라, 영원한 밤의 땅에서 당신들을 기다리고 있겠습니다.",
  ui_story_1021_10210902_7_dialog_content = "당신들이라면... 기대가 되는군요...",
  ui_story_1021_10211001_1_dialog_content = "암귀는 북방에서 퇴각했고, 등대의 광원도 안정을 되찾았습니다.",
  ui_story_1021_10211001_2_dialog_content = "지원 부대는 돌아갔는가.",
  ui_story_1021_10211001_3_dialog_content = "일루미나의 참모장이 아직 소나무 계곡에서 PlayerName 님과 일행을 기다리고 있습니다.",
  ui_story_1021_10211001_4_dialog_content = "거점을 세우기도 전에 어둠의 밑바닥 탐색이 시작되었군요.\n게다가 이런 방식으로 시작될 줄은 몰랐습니다.",
  ui_story_1021_10211001_5_dialog_content = "저 새로운 등대가 생겼으니, 적어도 저들이 어둠의 밑바닥 깊은 곳으로\n나아가기 전까지는 가호를 얻을 수 있을 것이다.",
  ui_story_1021_10211001_6_dialog_content = "그렇다면 연합 탐색대는 이곳에서부터 출발하는 것입니까?",
  ui_story_1021_10211001_7_dialog_content = "그렇다. 그러니 거점 건설을 서둘러야 할 것이다.",
  ui_story_1021_10211001_8_dialog_content = "여왕 폐하, 작별 인사를 드리러 왔습니다. 저흰 이제 돌아갈 준비를 하겠습니다.",
  ui_story_1021_10211001_9_dialog_content = "카렌은 얼른 돌아가서 비행 훈련을 받고 싶다네요.",
  ui_story_1021_10211001_10_dialog_content = "그, 그런 거 아니거든...\n크흠, 사실 아직 준비해야 할 일이 많아서 그렇습니다...",
  ui_story_1021_10211001_11_dialog_content = "그래, 그렇다면 서둘러 돌아가는 것이 좋겠구나. 그대들의 이번 도움에 감사하마.\n그대들 덕분에 새로운 등대를 세울 수 있었던 것이다.",
  ui_story_1021_10211001_12_dialog_content = "그건 티아라의 공인걸요! 참, 티아라는요?",
  ui_story_1021_10211001_13_dialog_content = "티아라는 다른 일이 있다.",
  ui_story_1021_10211001_14_dialog_content = "연합 탐색대의 일원들에게는 조만간 좋은 소식이 있을 것이니,\n거점 건설 건은 걱정하지 말라고 전해 주거라.",
  ui_story_1021_10211001_15_dialog_content = "성주 전하께서도 백야성 호위대를 파견해 거점 건설을 돕겠다고 하셨습니다.\n다만 며칠 늦을 수 있다고 하시더군요.",
  ui_story_1021_10211001_16_dialog_content = "잠깐만, 밖에 마침 기계 전문가가 둘 있잖아? 건설은 오늘부터 시작할 수 있어!",
  ui_story_1021_10211001_17_dialog_content = "그렇구나! 안 그래도 보석에 눈독 들이고 있던 것 같으니까,\n이미 챙긴 건 선불로 치면 되겠네.",
  ui_story_1021_10211001_18_dialog_content = "그렇게 큰 소리로 일 시킨다고 말할 건 없잖아...",
  ui_story_1021_10211001_19_dialog_content = "그 보석은 진작에 어디서 떨어트렸어... 공짜로 일해주면 사메야마 대장한테 혼난다구.",
  ui_story_1021_10211001_20_dialog_content = "그리고 난 역시 뜨끈뜨끈한 사막에서 보급 지원을 맡는 쪽이 좋을 것 같아.\n북방엔 곳곳에 보물이 널렸지만, 여기 다시 오고 싶진 않아.",
  ui_story_1021_10211001_21_dialog_content = "그럼 같이 탐색하자고 했던 건요?",
  ui_story_1021_10211001_22_dialog_content = "그거야 상황 봐서 정해야지. 아저씨는 바쁜 사람이라고.",
  ui_story_1021_10211001_23_dialog_content = "(나는 이날을 예견했으나, 손이 닿지 않을 머나먼 일처럼 느껴졌다...\n그것이 지금은 현실이 되었구나.)",
  ui_story_1021_10211001_24_dialog_content = "(지금까지 저들은 각자의 진영과 입장만을 견지해 왔고,\n연합 탐색 같은 일은 허울뿐인 정치적 수사에 불과했다.)",
  ui_story_1021_10211001_25_dialog_content = "(그러나 지금은 마치 동료처럼 서로를 위해 앞으로 나서고 있다...)",
  ui_story_1021_10211001_26_dialog_content = "(부디 저들이 어둠의 밑바닥으로 나아갈 때, 지난날의 동료들이 어둠 속에서\n저들의 버팀목이 되어주기를.)",
  ui_story_1021_10211001_27_dialog_content = "<color=#e8d9bb>소나무 계곡 근처</color>",
  ui_story_1021_10211001_28_dialog_content = "PlayerName! 잠깐만!",
  ui_story_1021_10211001_29_dialog_content = "티아라? 왜 여기까지 온 거야?",
  ui_story_1021_10211001_30_dialog_content = "줄 선물이 있거든! 근데 나도 모르게... 같이 선물 가지고 오는 사람을 뒤에 따돌려 버렸지 뭐야... 헤헷!",
  ui_story_1021_10211001_31_dialog_content = "계속 그랬다간 너랑 같이 놀고 싶은 사람이 없어질걸...",
  ui_story_1021_10211001_32_dialog_content = "참, 앞으로 어떻게 할 생각이야? 너도 알겠지만 우린 네가 연합 탐색에 참여해 줬으면 좋겠어.",
  ui_story_1021_10211001_33_dialog_content = "당신은 민첩하고 용감하니까, 위험이 닥쳤을 때 분명히 모두에게 큰 힘이 될 거야.",
  ui_story_1021_10211001_34_dialog_content = "초대해 줘서 기쁘지만, 잊은 모양이네. 내 마음속엔 이미 더 중요한 게 담겨 있거든!",
  ui_story_1021_10211001_35_dialog_content = "이번에 함께 다양한 일을 겪으면서, 나도 내가 아직 책임을 다하지 못했다는 걸 깨달았어.",
  ui_story_1021_10211001_36_dialog_content = "그러니까 앞으로도 노력해서 어엿한 북방의 호위가 되고 말겠어!",
  ui_story_1021_10211001_37_dialog_content = "그래서 정했어! 난 북방에 남아서 눈여우 부족의 선조님들과 역대 여왕님의 위업을 계승할 거야!",
  ui_story_1021_10211001_38_dialog_content = "증조할머니한테 못 들은 이야기도 장로님한테 제대로 배울 거고!",
  ui_story_1021_10211001_39_dialog_content = "그건 정말 의미 있는 일이라고 생각해! 나도 눈여우나 북방 여왕의 위업을 더 알고 싶어.\n너도 잊으면 안 돼. 나도 역사의 증인 중 한 사람이란 거.",
  ui_story_1021_10211001_40_dialog_content = "새로운 이야기를 알게 되면 나한테도 꼭 편지 써서 들려줘!",
  ui_story_1021_10211001_41_dialog_content = "아니지... 그 방법으로!",
  ui_story_1021_10211001_42_dialog_content = "아우우──!",
  ui_story_1021_10211001_43_dialog_content = "아우우──!",
  ui_story_1021_10211001_44_dialog_content = "누군 무거운 짐 끈다고 힘들어 죽겠는데, 너흰 여기서 울음소리나 내고 있었어?!",
  ui_story_1021_10211001_45_dialog_content = "저 사람은...?",
  ui_story_1021_10211001_46_dialog_content = "아, 자리야라고 해. 북방에서 알게 된 친구야.",
  ui_story_1021_10211001_47_dialog_content = "티아라와 함께 선물 가지고 온다는 사람이 너였구나...",
  ui_story_1021_10211001_48_dialog_content = "쟨 발이 너무 빨라서 순식간에 안 보이게 된다구!",
  ui_story_1021_10211001_49_dialog_content = "티아라랑 같이 다니면 따돌려지는 것도 이상할 건 없으니까...",
  ui_story_1021_10211001_50_dialog_content = "아니거든! 분명히 아직도 나한테 화가 나서 그런 거지?!",
  ui_story_1021_10211001_51_dialog_content = "흥! 그러게 누가 여우들한테 얼음을 날리래?",
  ui_story_1021_10211001_52_dialog_content = "네가 안 알려줘서 그런 거잖아! 너네 고향에 가면 하얀 여우들한테... 손등을 핥여야 한다고...!",
  ui_story_1021_10211001_53_dialog_content = "북방엔 그런 풍습 없단 말이야!",
  ui_story_1021_10211001_54_dialog_content = "......",
  ui_story_1021_10211001_55_dialog_content = "...그 빛나는 게 선물이야?",
  ui_story_1021_10211001_56_dialog_content = "설마... 루미나 광석...?!",
  ui_story_1021_10211001_57_dialog_content = "정답! 내가 엄청 고생해서 겨우 티아라네 고향에서 가지고 온 거라구!",
  ui_story_1021_10211001_58_dialog_content = "그런 귀한 건 받을 수 없어!",
  ui_story_1021_10211001_59_dialog_content = "어째서? 난 지금 눈여우 부족의 리더로서, 특별히 부족의 은인한테 광석을 선물하는 건데...",
  ui_story_1021_10211001_60_dialog_content = "그리고 이건 장로님의 뜻이기도 해.",
  ui_story_1021_10211001_61_dialog_content = "여왕 폐하도 말씀하셨어. 이 광석은 어둠의 밑바닥에서 앞길을 밝히고, 암귀도 몰아낼 수 있대.\n너희 탐색에 분명히 도움이 될 거야.",
  ui_story_1021_10211001_62_dialog_content = "하지만 북방의 변경에도 암귀들이 못 다가오게 하려면 이게 필요하잖아...",
  ui_story_1021_10211001_63_dialog_content = "...아무튼! 부족이 주는 선물이니까! 이 리더님의 마음이 변하기 전에 얼른 받아!",
  ui_story_1021_10211001_64_dialog_content = "으... 알았어, 받을게!",
  ui_story_1021_10211001_65_dialog_content = "(휴... 벌써부터 여왕님의 호위로서의 티아라가 그리워지기 시작했어...)",
  ui_story_1021_10211001_66_dialog_content = "......",
  ui_story_1021_10211001_67_dialog_content = "그대도 마침내 마음 놓고 티아라에게 자신이 원하는 일을 하도록 보낼 수 있게 된 모양이군.",
  ui_story_1021_10211001_68_dialog_content = "설령 나의 호위가 아니더라도 티아라는 이 북방에서 자신의 자리를 찾을 수 있을 것이다.",
  ui_story_1021_10211001_69_dialog_content = "그러나 그날 눈사태 이후로, 그대는 저 아이의 영원한 등대가 되었다.",
  ui_story_1021_10211001_70_dialog_content = "<color=#e8d9bb>부족이 습격당한 날...</color>",
  ui_story_1021_10211001_71_dialog_content = "여왕의 호위는 힘들지 않느냐.",
  ui_story_1021_10211001_72_dialog_content = "폐하께서는 정말 강한 분이세요... 위험이 닥치면 폐하 스스로 모두를 지켜주세요.\n그래서 힘들다고 느낀 적은 없어요.",
  ui_story_1021_10211001_73_dialog_content = "오히려 제가 위험에 처할 때마다 절 구해 주셨어요. 몇 번이나...",
  ui_story_1021_10211001_74_dialog_content = "눈여우 부족은 반드시 은혜를 갚잖아요.\n그래서 폐하께서 눈사태 속에서 절 구해 주셨을 때부터, 전 폐하를 지키겠다고 맹세했어요.",
  ui_story_1021_10211001_75_dialog_content = "그대는 정말 그자를 이해하고 있는 것이냐.",
  ui_story_1021_10211001_76_dialog_content = "당연하죠! 여왕 폐하께서 우리 영지로 순시를 오셨을 때부터... 전 늘 몰래 폐하를 지켜봤어요...",
  ui_story_1021_10211001_77_dialog_content = "폐하의 모든 행동 하나하나, 그 분위기, 심지어 그 호흡까지도... 전 모두 이해하고 있어요.",
  ui_story_1021_10211001_78_dialog_content = "부족이 외지인을 환영하지 않는 건 알아요. 하지만 여왕 폐하는 달라요...",
  ui_story_1021_10211001_79_dialog_content = "폐하가 절 보시는 눈은 마치 매년 저를 봐 주러 오는 가족 같은 느낌이에요...",
  ui_story_1021_10211001_80_dialog_content = "폐하가 오실 때면 마치 온 부락이 환하게 빛나고, 제 세상도 빛나는 것 같아요...",
  ui_story_1021_10211001_81_dialog_content = "티아라, 그대가 어떤 선택을 내릴지에 대한 답은 줄곧 그대의 마음속에 있었다.",
  ui_story_1021_10211001_82_dialog_content = "그대의 세상을 환하게 밝힐 수 있는 자는 곧 그대의 등대인 것이다.",
  ui_story_1021_10211001_83_dialog_content = "부디 그대가 자신의 등대를 따라 그 빛과 열을 자신의 힘으로 삼길 바라마.",
  ui_story_1021_10211001_84_dialog_content = "그리고 스스로를 비출 등대가 되고 나면, 그때는 분명히 우리의 부락도 밝혀줄 수 있을 것이다.",
  ui_story_1021_10211001_85_dialog_content = "......",
  ui_story_1021_10211001_86_dialog_content = "눈사태 때의... 진실을 저 아이에게 말해줄 생각은 없는가.",
  ui_story_1021_10211001_87_dialog_content = "이야기해 봤자 이제 차이는 없을 것이다.",
  ui_story_1021_10211001_88_dialog_content = "......",
  ui_story_1021_10211001_89_dialog_content = "그러나 내가 보기에 그대 또한 저 아이의 등대다.",
  ui_story_1021_10211001_90_dialog_content = "<color=#e8d9bb>수년 전...</color>",
  ui_story_1021_10211001_91_dialog_content = "<color=#e8d9bb>부스럭부스럭...</color>",
  ui_story_1021_10211001_92_dialog_content = "......?",
  ui_story_1021_10211001_93_dialog_content = "(그때 내게 눈을 던졌던 소녀가 어느덧 저렇게 자란 것인가.)",
  ui_story_1021_10211001_94_dialog_content = "(홀로 이 눈소나무 숲에서 살아가면서 분명히 늘 외로움을 느끼고 있겠지.)",
  ui_story_1021_10211001_95_dialog_content = "<color=#e8d9bb>후두둑──</color>",
  ui_story_1021_10211001_96_dialog_content = "......",
  ui_story_1021_10211001_97_dialog_content = "......",
  ui_story_1021_10211001_98_dialog_content = "(참으로 성급한 아이로구나...)",
  ui_story_1021_10211001_99_dialog_content = "(전에는 멀리서 따라오기만 했거늘, 이번에는 스스로 모습을 드러낸 것이냐.)",
  ui_story_1021_10211001_100_dialog_content = "......",
  ui_story_1021_10211001_101_dialog_content = "매년 이때가 되면 그대는 늘 찾아왔지.",
  ui_story_1021_10211001_102_dialog_content = "......",
  ui_story_1021_10211001_103_dialog_content = "그러나 등대가 이곳을 비출 것이라는 약속은 여전히 지키지 못했다.",
  ui_story_1021_10211001_104_dialog_content = "......",
  ui_story_1021_10211001_105_dialog_content = "나는 그대들에게 감사한다. 그대들이 없었다면, 오늘날 북방의 안녕은 없었을 것이다.",
  ui_story_1021_10211001_106_dialog_content = "비록 선조들은 이 땅에 머무르다 전쟁의 철퇴 아래 목숨을 잃었으나...",
  ui_story_1021_10211001_107_dialog_content = "우리는 스스로를 인정하고, 계속해서 이곳을 지켜나갈 것이다.",
  ui_story_1021_10211001_108_dialog_content = "......",
  ui_story_1021_10211001_109_dialog_content = "티아라를 데리고 가라.",
  ui_story_1021_10211001_110_dialog_content = "......?",
  ui_story_1021_10211001_111_dialog_content = "내게 남은 시간은 많지 않다. 저 아이가 조금 더 자라고 나면,\n아마 「지킨다」는 것의 대가가 얼마나 무거운지를 알게 되겠지.",
  ui_story_1021_10211001_112_dialog_content = "나는 티아라가 저 아이의 증조모처럼 집념과 고독을 품은 채 이 숲을 지키는 것은 원치 않는다.",
  ui_story_1021_10211001_113_dialog_content = "...티아라는 고집이 센 아이다.",
  ui_story_1021_10211001_114_dialog_content = "그러나 그대에게는 호기심과 동경을 품고 있다.",
  ui_story_1021_10211001_115_dialog_content = "......",
  ui_story_1021_10211001_116_dialog_content = "<color=#e8d9bb>장로는 숲을 향해 발을 휘둘렀고, 거대한 눈덩이가 티아라를 향해 굴러갔다...</color>",
  ui_story_1021_10211001_117_dialog_content = "으아아앗──!",
  ui_story_1021_10211001_118_dialog_content = "「얼음이 녹으면 그걸로 끝이다──」",
  ui_story_1021_10211001_119_dialog_content = "...당신이 절 구해 주셨군요.",
  ui_story_1021_10211001_120_dialog_content = "게다가...",
  ui_story_1021_10211001_121_dialog_content = "이로써 그대의 창은 더 단단해질 것이다.",
  ui_story_1021_10211001_122_dialog_content = "우와... 엄청난 빛까지 내뿜고 있어...!",
  ui_story_1021_10211001_123_dialog_content = "마치 등대 같아...",
  ui_story_1021_10211001_124_dialog_content = "...잠깐만요!",
  ui_story_1021_10211001_125_dialog_content = "......",
  ui_story_1021_10211001_126_dialog_content = "저, 저는 티아라라고 해요!",
  ui_story_1021_10211001_127_dialog_content = "......",
  ui_story_1021_10211001_128_dialog_content = "오늘부터 당신이 어디로 향하든 제가 지키겠어요! 눈여우 부족은 반드시 은혜를 갚으니까요!",
  ui_story_1021_10211001_129_dialog_content = "......",
  ui_story_1021_10211001_130_dialog_content = "그대들이 북방을 위해 행한 모든 일에 감사한다.",
  ui_story_1021_10211001_131_dialog_content = "맹세란 비록 무거우나, 나는 계속해서 꿋꿋하게 걸어갈 것이다...",
  ui_story_1021_10211001_132_dialog_content = "그대들에게 약속하겠다. 북방의 등대는 반드시 이 땅을 비추고...",
  ui_story_1021_10211001_133_dialog_content = "또한 더욱 먼 곳까지 비출 것이다.",
  ui_story_1022_10220100_1_dialog_content = "(여긴... 어디야?)",
  ui_story_1022_10220100_2_dialog_content = "<color=#e8d9bb>어둠에 휩싸인 세계는 방향조차 분간할 수 없었고, 느껴지는 것은 오직 추위뿐이었다.</color>",
  ui_story_1022_10220100_3_dialog_content = "(내가 왜 이런 곳에 있지?)",
  ui_story_1022_10220100_4_dialog_content = "(점점 추워지고 있어... 이런, 가만히 있으면 안 되겠어. 움직여야 돼!)",
  ui_story_1022_10220100_5_dialog_content = "(하지만... 대체 어디로 가야 되는 거야? 너무 어두워서 안 보여... 어? 저건... 뭐지?)",
  ui_story_1022_10220100_6_dialog_content = "<color=#e8d9bb>짓누르는 어둠과 매서운 추위 속, 머나먼 곳에서 한 점의 빛이 반짝이고 있었다.</color>",
  ui_story_1022_10220100_7_dialog_content = "<color=#e8d9bb>그 빛은 꺼지지 않고 오히려 점점 더 밝아졌고, 사방을 눈부시게 비추기 시작했다.</color>",
  ui_story_1022_10220100_8_dialog_content = "<color=#e8d9bb>마치 극야에 해가 솟아오른 것처럼.</color>",
  ui_story_1022_10220100_9_dialog_content = "(엄청나게 방대한 루미나네! 게다가 정말 순수해...\n마치 날 지켜보면서 이끌어주고 있는 것 같아...)",
  ui_story_1022_10220100_10_dialog_content = "...잊게 될 거야. 시간이 얼마나 흐르고, 네가 앞으로 만나는 사람이\n얼마나 더 잊기 어려운 존재일지에 달렸겠지만.",
  ui_story_1022_10220100_11_dialog_content = "...누구야? 누가 말하고 있는 거지?",
  ui_story_1022_10220100_12_dialog_content = "(추, 추워... 온몸이 덜덜 떨려...)",
  ui_story_1022_10220100_13_dialog_content = "...감기다냥!",
  ui_story_1022_10220100_14_dialog_content = "너...너무 추워...",
  ui_story_1022_10220100_15_dialog_content = "담요를 걷어차서 그렇다냥~ 게다가 깔고 뭉개서 필리시가 다시 덮어줄 수가 없었다냥.",
  ui_story_1022_10220100_16_dialog_content = "감기 걸리기 싫으면 얼른 일어나라냥.",
  ui_story_1022_10220100_17_dialog_content = "어? 나 잠들었어? 그럼 방금 그건 꿈인가...?",
  ui_story_1022_10220100_18_dialog_content = "으으 추워! 고마워, 필리시. 네가 깨워줘서 망정이지...",
  ui_story_1022_10220100_19_dialog_content = "답례 따위는 필요없다냥~\n아무튼 너도 일어났으니까, 그럼 이 편안한 잠자리는 필리시가 넘겨받겠다냥...",
  ui_story_1022_10220100_20_dialog_content = "어? 자, 잠깐만! 벌써 잠들지 마!",
  ui_story_1022_10220100_21_dialog_content = "지금 무슨 상황인데? 우린 어디쯤이야?",
  ui_story_1022_10220100_22_dialog_content = "창밖을 보면 알 수 있다냥~",
  ui_story_1022_10220100_23_dialog_content = "창밖...? 아.",
  ui_story_1022_10220100_24_dialog_content = "<color=#e8d9bb>비행기 밖에서는 끈적끈적한 액체가 흐르듯, 검은 밤이 온 하늘을 뒤덮으며\n끝없이 이어지고 있었다.</color>",
  ui_story_1022_10220100_25_dialog_content = "<color=#e8d9bb>마치 꿈속의 그 어둠처럼.</color>",
  ui_story_1022_10220100_26_dialog_content = "우리... 이미 어둠의 밑바닥에 들어온 거야?",
  ui_story_1022_10220100_27_dialog_content = "맞다냥. 방금 그거 말해주러 왔던 거다냥.\n근데 네가 웅크리고 자면서 춥다고 하고 있었다냥~",
  ui_story_1022_10220100_28_dialog_content = "콜록콜록!",
  ui_story_1022_10220100_29_dialog_content = "(그럼 내가 꿈에서 어둠을 본 것도... 우리가 어둠의 밑바닥에 들어왔기 때문일 지도 모르겠네.)",
  ui_story_1022_10220100_30_dialog_content = "(하지만 꿈엔 거대한 루미나도 나왔어... 그럼 설마 그것도 현실에 존재하는 건가...?)",
  ui_story_1022_10220100_31_option_content = "[감응 확장]",
  ui_story_1022_10220100_32_dialog_content = "......!",
  ui_story_1022_10220100_33_dialog_content = "(...진짜 있잖아? 저건 대체 뭐지?)",
  ui_story_1022_10220100_34_dialog_content = "다만... 상황이 그리 좋지는 않다냥...",
  ui_story_1022_10220100_35_dialog_content = "원래 난 두 쪽의 좌표를 받을 수 있었다냥.",
  ui_story_1022_10220100_36_dialog_content = "하나는 일루미나가 먼저 파견했던 「정예 탐색 소대」, 다른 하나는 카론 님과 바이스의 좌표다냥.",
  ui_story_1022_10220100_37_dialog_content = "...바이스한테 무슨 일이라도 생긴 거야?!",
  ui_story_1022_10220100_38_dialog_content = "진정하라냥~ 뭐, 말은 이렇게 해도 네가 걱정하는 건 이해한다냥...\n두 좌표의 신호에 전부 이상이 생겼으니 말이다냥.",
  ui_story_1022_10220100_39_dialog_content = "「탐색 소대」의 신호는 점점 약해지고 있다냥.\n아마 그쪽 환경의 영향 때문에 통신 기기에 문제가 생겼을 거다냥.",
  ui_story_1022_10220100_40_dialog_content = "근데 일루미나의 기계는 어둠의 밑바닥에서도 쓸 수 있을 거잖아?",
  ui_story_1022_10220100_41_dialog_content = "어둠의 밑바닥의 환경이 변하기 쉽다냥.\n지형, 날씨, 거리, 다크매터의 분포까지, 모두 기계에 영향을 준다냥.",
  ui_story_1022_10220100_42_dialog_content = "그렇구나... 그, 그래서 바이스가 어떻게 된 건데?",
  ui_story_1022_10220100_43_dialog_content = "...카론 님이랑 바이스의 좌표는 계속 깡충깡충 뛰고 있다냥.",
  ui_story_1022_10220100_44_dialog_content = "깡충깡충?",
  ui_story_1022_10220100_45_dialog_content = "고양이 장난감 같은 거 말이다냥. 여기 있다가 휙 저기로 갔다가 하는 그거.\n필리시는 눈이 어지럽다냥!",
  ui_story_1022_10220100_46_dialog_content = "필리시가 아는 「피안호」의 정보대로라면 그 기차는 그런 식으로 움직일 수 없다냥...",
  ui_story_1022_10220100_47_dialog_content = "하지만 발신기 고장도 아닌 것 같단 말이지... 너무 이상하다냥~",
  ui_story_1022_10220100_48_dialog_content = "설마 그것도 어둠의 밑바닥의 영향인가... 계속 연락이 안 돼?",
  ui_story_1022_10220100_49_dialog_content = "히이로 님이 시도해 봤지만, 소용없었다냥... 이젠 어디로 갔는지조차 판단할 수가 없다냥.",
  ui_story_1022_10220100_50_dialog_content = "대체 어떻게 이런 현상이 발생하는 거냐앙! 너무 수수께끼다냥!\n필리시가 진지하게 정보를 검색해도 답을 못 찾겠다냥! 이번엔 진짜로 열심히 일했는데냥!",
  ui_story_1022_10220100_51_dialog_content = "...설마... 팬텀을 만난 건 아니겠지...",
  ui_story_1022_10220100_52_dialog_content = "히익?!",
  ui_story_1022_10220100_53_dialog_content = "그 팬텀들이 어떤 능력이 있는지는 전혀 알 수 없잖아!\n공간 도약 같은 말도 안 되는 능력도 불가능하단 보장은 없어...",
  ui_story_1022_10220100_54_dialog_content = "게다가 바이스는 「어썰트호」를 조종할 잠재력이 있어.\n콜로서스를 노리는 팬텀들한테는 이용 가치가 있을 거야...",
  ui_story_1022_10220100_55_dialog_content = "만약 어떤 팬텀이 바이스를 납치해서 이리저리 돌아다니고 있는 거라면...?!",
  ui_story_1022_10220100_56_dialog_content = "우냐아앙! 그, 그럼...",
  ui_story_1022_10220100_57_dialog_content = "카론과 「피안호」가 있는 한, 그런 상황이 벌어질 가능성은 거의 없을 겁니다.",
  ui_story_1022_10220100_58_dialog_content = "히이로 님!",
  ui_story_1022_10220100_59_dialog_content = "히이로 씨... 정말 그럴까요? 하지만 만약... 정말 만에 하나라도...",
  ui_story_1022_10220100_60_dialog_content = "<color=#e8d9bb>콩!</color>",
  ui_story_1022_10220100_61_dialog_content = "아얏!",
  ui_story_1022_10220100_62_dialog_content = "(딱밤을 맞다니...)",
  ui_story_1022_10220100_63_dialog_content = "「만에 하나」라는 확률은 누구도 배제할 수 없습니다. 그러니 걱정해도 의미가 없죠.",
  ui_story_1022_10220100_64_dialog_content = "출발 전에 감정적으로 대하지 않겠다고 약속한 걸 잊었습니까?",
  ui_story_1022_10220100_65_dialog_content = "그거야 물론 기억하죠...\n하지만 바이스가 무슨 상황인지 알 수가 없다고 하니까 저도 모르게...",
  ui_story_1022_10220100_66_dialog_content = "(으으, 머리야... 히이로 씨, 너무 아프잖아요!)",
  ui_story_1022_10220100_67_dialog_content = "당신 심정은 이해할 수 있습니다.\n하지만 어둠의 밑바닥은 위험으로 가득한 곳이니, 정신을 집중해 주세요.",
  ui_story_1022_10220100_68_dialog_content = "바이스도 이 점을 주의했으면 좋겠는데 말입니다.\n그 아이도 당신처럼 위기 앞에서 남을 더 신경 쓰니까요.",
  ui_story_1022_10220100_69_dialog_content = "그런 점은 군인으로서 단련이 더 필요합니다.",
  ui_story_1022_10220100_70_dialog_content = "설마... 히이로 씨도 사실 바이스가 걱정이 되시는 거죠?",
  ui_story_1022_10220100_71_dialog_content = "당연하지 않습니까?",
  ui_story_1022_10220100_72_dialog_content = "바이스, 카론 님, 그로누 연구원장...\n사람 걱정하게 만드는 아기 고양이가 점점 늘어나고 있다냥.",
  ui_story_1022_10220100_73_dialog_content = "그로누? 그로누가 왜?",
  ui_story_1022_10220100_74_dialog_content = "...「어썰트호」가 발견된 뒤부터 연구원장은 게임까지 접고 매일 수리에 몰두하고 있다냥.",
  ui_story_1022_10220100_75_dialog_content = "당시 「어썰트호」 실험의 책임자니까, 분명히 바이스랑 대원수님한테 미안해하고 있는 거다냥.",
  ui_story_1022_10220100_76_dialog_content = "남 걱정 할 시간은 없습니다. 지금은 우리도 매우 어려운 상황에 놓여 있으니까요.",
  ui_story_1022_10220100_77_dialog_content = "원래 이 비행기는 다른 2개 조와 협력해서 공동 작전을 진행할 계획이었습니다.",
  ui_story_1022_10220100_78_dialog_content = "하지만 지금은 2개 조 모두 행방이 묘연합니다. 따라서 우린 반드시 계획을 변경해야 합니다.",
  ui_story_1022_10220100_79_dialog_content = "필리시는 카론 님 쪽 상황이 무척 신경이 쓰입니다냥. 그치만 지금은 합류하기 어려울 텐데...",
  ui_story_1022_10220100_80_dialog_content = "(마지막으로 보낸 좌표로 얼른 가 본다고 해도,\n그땐 이미 다른 먼 곳으로 이동했을 거야... 쳇!)",
  ui_story_1022_10220100_81_dialog_content = "「탐색 소대」의 좌표 신호가 수신되지 않은 지도 꽤 시간이 지났습니다.",
  ui_story_1022_10220100_82_dialog_content = "이대로는 아무 목적 없이 시간만 낭비할 뿐입니다. 아무것도 이룰 수 없겠죠.",
  ui_story_1022_10220100_83_dialog_content = "...거대한 루미나가 있었어요.",
  ui_story_1022_10220100_84_dialog_content = "네?",
  ui_story_1022_10220100_85_dialog_content = "정체를 알 수 없는 거대한 루미나 덩어리가... 어둠의 밑바닥 깊은 곳에 있는 걸 감응했어요.\n어쩌면 극야 지대에 무척 가까운 곳일지도 몰라요...",
  ui_story_1022_10220100_86_dialog_content = "...그, 그런 게 있었단 말이다냥?!",
  ui_story_1022_10220100_87_dialog_content = "응집된 루미나는 어둠의 밑바닥에서 매우 보기 드문 것입니다.\n만약 다른 부대도 그걸 찾았다면 조사를 하러 가고 있을지도 모릅니다.",
  ui_story_1022_10220100_88_dialog_content = "합류할 수 있는 절호의 기회일지도 모르겠군요...",
  ui_story_1022_10220100_89_dialog_content = "보고드립니다! 후방 거점의 통신 요청입니다!",
  ui_story_1022_10220100_90_dialog_content = "연결하세요.",
  ui_story_1022_10220100_91_dialog_content = "예!",
  ui_story_1022_10220100_92_dialog_content = "...응답 바란다. 들리나?",
  ui_story_1022_10220100_93_dialog_content = "라인하르트 씨! 연락이 돼서 다행이에요...",
  ui_story_1022_10220100_94_dialog_content = "잘 들립니다, 대원수님. 아무래도 후방과의 통신은 영향을 받지 않는 모양이군요.",
  ui_story_1022_10220100_95_dialog_content = "「탐색 소대」의 좌표는 아직 못 찾은 건가? 역시 거긴 참 골치 아픈 곳이란 말이지.",
  ui_story_1022_10220100_96_dialog_content = "히이로, 수고가 많다. 이번 임무는 쉽지 않겠어.",
  ui_story_1022_10220100_97_dialog_content = "탐색에 나선 부하들의 행방이 불분명한 상황이니, 저들을 데려오는 것은 제 책무입니다.",
  ui_story_1022_10220100_98_dialog_content = "게다가 연합 탐색 부대가 결성된 뒤로는 백야성 군대가 지상에 주둔하고 있습니다.\n덕분에 후방 걱정은 덜었습니다.",
  ui_story_1022_10220100_99_dialog_content = "그것보다 대원수님, 위원회와의 대화는 순조로우셨습니까? 또 트집을 잡진 않았습니까?",
  ui_story_1022_10220100_100_dialog_content = "하하하, 놈들이 트집을 안 잡으면 오히려 내가 맞게 가고 있는지가 의심이 된다고.",
  ui_story_1022_10220100_101_dialog_content = "뭐, 대체로 순조롭다고 할 수 있겠군. 그리고 난 서서히 알게 됐다.\n위원회는 마치 자기 꼬리를 물고 있는 뱀 같은 존재다.",
  ui_story_1022_10220100_102_dialog_content = "그게 어떤 의미입니까?",
  ui_story_1022_10220100_103_dialog_content = "벨리사리아든, 아직 얼굴을 비추지 않은 놈들이든...\n으음, 과거의 율리시스도 일단 그렇다고 쳐 두고.",
  ui_story_1022_10220100_104_dialog_content = "놈들의 처음 목표는 과학 기술로 오로리안의 생존 문제를 해결하는 것이었다.",
  ui_story_1022_10220100_105_dialog_content = "그 점은 저도 인정합니다.",
  ui_story_1022_10220100_106_dialog_content = "하지만 기술은 냉혹한 것이고, 위원회는 그 기술에 가장 가까운 사람들이다.\n따라서 받는 영향도 가장 크지.",
  ui_story_1022_10220100_107_dialog_content = "놈들은 기술을 추구하는 과정에서 기술이 지닌 잔혹함의 화신이 되고 말았다.",
  ui_story_1022_10220100_108_dialog_content = "이성, 효율, 실용성... 그것들을 추구하면서 놈들은 인간성을 잃었고,\n오히려 처음의 목적을 해치고 말았다.",
  ui_story_1022_10220100_109_dialog_content = "오로리안이 행복하게 살 수 있는 세상을 만들겠다던 목적 말이다.",
  ui_story_1022_10220100_110_dialog_content = "(율리시스 교수조차도 처음 목적은 암귀와 맞서기 위해 오로리안을 강화하는 거였으니까...)",
  ui_story_1022_10220100_111_dialog_content = "...효율만을 추구하고, 사고의 여지를 제거한다면, 팬텀에 복종하는 암귀들과 무슨 차이가 있죠?",
  ui_story_1022_10220100_112_dialog_content = "그래서 젊은 세대는 자신들의 길을 찾고 있는 것이다. 잉겔이나 숀을 봐라.",
  ui_story_1022_10220100_113_dialog_content = "나도 그들보다 못해선 안 되겠지. 전에는 이루지 못했던 것을 무언가 해야만 한다.",
  ui_story_1022_10220100_114_dialog_content = "라인하르트 씨가 이루지 못했던 게 또 뭐가 있죠...?",
  ui_story_1022_10220100_115_dialog_content = "하하하! 그렇게 말하니 꼭 내가 악당 같군.",
  ui_story_1022_10220100_116_dialog_content = "...대원수로서 내가 해낸 일은 아직도 많지 않다.\n과거에는 전쟁에 집중하느라 어둠 속의 위기는 무시하고 말았지.",
  ui_story_1022_10220100_117_dialog_content = "위원회가 일루미나라는 큰 배의 방향을 조종하고 있음을 알면서도,\n나는 전임자와 마찬가지로 타협을 택했다.",
  ui_story_1022_10220100_118_dialog_content = "대원수님! 전 대원수님께서 결코 그런 분이 아니라는 걸...",
  ui_story_1022_10220100_119_dialog_content = "진정해라, 히이로. 나는 그저 내게 새로운 과제를 주고 있을 뿐이다.",
  ui_story_1022_10220100_120_dialog_content = "이제는 다르다. 나는 한때 생각했던 개혁을 실행에 옮길 것이다.",
  ui_story_1022_10220100_121_dialog_content = "어쩌면 위원회의 존재에도 의미가 있을지도 모른다.\n하지만 나는 일루미나의 힘이 잘못된 길로 이끌리는 것을 허락하지 않을 것이다.",
  ui_story_1022_10220100_122_dialog_content = "나는 놈들의 철가면을 벗기고, 그 아래 일말의 인간성이 남아있는지 확인할 생각이다.",
  ui_story_1022_10220100_123_dialog_content = "지금은 아직 확실하지 않은 점도 있지만, 조만간 모두에게 답을 줄 수 있을 것이다.\n그때까지는 나를 기다려 주길 바란다.",
  ui_story_1022_10220100_124_dialog_content = "<color=#e8d9bb>한편, 일루미나 위원회</color>",
  ui_story_1022_10220100_125_dialog_content = "라인하르트는 실각했다가 돌아왔고, 율리시스의 인체실험도 만천하에 드러났네요...",
  ui_story_1022_10220100_126_dialog_content = "저 부유섬을 위해 준비했던 무기도 폭로되었을지도 모르죠.",
  ui_story_1022_10220100_127_dialog_content = "당신이 지지한 모든 일이 당신의 머리를 관통하는 탄환이 되고 말았어요.",
  ui_story_1022_10220100_128_dialog_content = "벨리사리아, 어떻게 책임질 생각인가요?",
  ui_story_1022_10220100_129_dialog_content = "이 일들을 제대로 해결하지 못하면 위원회의 위신은 땅에 떨어지고 말 겁니다!",
  ui_story_1022_10220100_130_dialog_content = "이제 와서 돌려 말할 필요가 있을까?",
  ui_story_1022_10220100_131_dialog_content = "그냥 책임지고 사임하고, 당신들한테 자리를 내놓으라고 말해.",
  ui_story_1022_10220100_132_dialog_content = "...설마 아직도 불복하겠다는 겁니까?",
  ui_story_1022_10220100_133_dialog_content = "불복이고 자시고의 문제가 아냐. 지금 상황에서 그게 필요한지 아닌지를 따지는 거지.",
  ui_story_1022_10220100_134_dialog_content = "필요한 상황이라면 난 언제든지 사임해 줄 수 있어.\n모든 책임과 오명을 짊어지고 위원회를 떠나줄게.",
  ui_story_1022_10220100_135_dialog_content = "그게 내 존재 의의잖아?",
  ui_story_1022_10220100_136_dialog_content = "...흥.",
  ui_story_1022_10220100_137_dialog_content = "대신 당신들도 잘 생각해.\n라인하르트가 어떤 사람인지, 그 실력과 호소력이 얼마나 큰지를 말이야.",
  ui_story_1022_10220100_138_dialog_content = "게다가 그 대원수 휘하의 군대가 지금 위원회에 어떤 태도를 취하고 있는지도.",
  ui_story_1022_10220100_139_dialog_content = "......",
  ui_story_1022_10220100_140_dialog_content = "당시의 일루미나는 분권을 전제로 한 권위주의 정치를 선택했고, 그 결과 지금의 모습이 되었어.",
  ui_story_1022_10220100_141_dialog_content = "위원회와 군부는 서로를 견제하고, 오랜 경쟁과 마찰을 거쳐 오늘의 찬란한 영광을 이룩했지.",
  ui_story_1022_10220100_142_dialog_content = "다만 충돌이 발생하면, 저쪽의 「대원수」가 유능할수록, 국면을 수습하기가 어려워져.",
  ui_story_1022_10220100_143_dialog_content = "당시 난 군부와의 교섭을 떠맡았지. 그리고 이번엔 군부와의 충돌을 이유로 쫓겨나는 신세가 됐고.",
  ui_story_1022_10220100_144_dialog_content = "하지만 그 뒤에는?",
  ui_story_1022_10220100_145_dialog_content = "지금 벌어진 이 판을 누가 이어받고 싶어? 아니, 누가 이어받을 수 있지?",
  ui_story_1022_10220100_146_dialog_content = "<color=#e8d9bb>기나긴 침묵이 회의실을 메웠다.</color>",
  ui_story_1022_10220100_147_dialog_content = "아직 수습하지 못한 일이 하나 더 있으니까, 그동안 다시 한번 잘들 생각해 봐.",
  ui_story_1022_10220100_148_dialog_content = "「무력」이 「이성」의 제어를 잃게 된다면, 앞으로 어떻게 될까요?",
  ui_story_1022_10220100_149_dialog_content = "하지만 만약 우리가 다시 개입한다면, 진짜 「전쟁」이 시작될 겁니다.",
  ui_story_1022_10220100_150_dialog_content = "위원회는 애초에 견제를 위해 존재했어요. 지금 싸움을 두려워하는 건가요?",
  ui_story_1022_10220100_151_dialog_content = "그렇다고 무의미한 내분이 우리의 목표에 무슨 도움이 됩니까?",
  ui_story_1022_10220100_152_dialog_content = "일루미나의 방향타를 잠깐 <color=#FFB400>그 여자</color>에게 맡기는 건 원래 수용 가능한 범위였어요.\n하지만 <color=#FFB400>그 여자</color>는 아직 불확정 요소를 지니고 있어요.",
  ui_story_1022_10220100_153_dialog_content = "언쟁은 그만합시다. 지금은 일치단결해서 어려움을 극복해야 합니다.",
  ui_story_1022_10220100_154_dialog_content = "단결? 지금의 「일루미나인」에게 우린 그저 불쾌한 존재일 뿐일 텐데요.\n훗, 아마 위원회 따위는 적폐라고 생각하고 있겠죠.",
  ui_story_1022_10220100_155_dialog_content = "결론이 나왔을까?",
  ui_story_1022_10220100_156_dialog_content = "<color=#FFB400>우리</color>가 나설 차례군요.",
  ui_story_1022_10220100_157_dialog_content = "......!",
  ui_story_1022_10220100_158_dialog_content = "「일루미나」는 분열을 통해 탄생했으나, 결코 분열에 의해 망해서는 안 됩니다.",
  ui_story_1022_10220100_159_dialog_content = "누가 실권을 잡느냐는 중요하지 않습니다. 중요한 것은 잘못된 전철을 밟지 않는 것입니다.",
  ui_story_1022_10220100_160_dialog_content = "일루미나에 반역은 다시는 없어야 합니다.",
  ui_story_1022_10220201_1_dialog_content = "<color=#e8d9bb>어둠의 밑바닥 깊은 곳 어딘가</color>",
  ui_story_1022_10220201_2_dialog_content = "대장님, 어쩌죠? 신호가 여전히 안 갑니다.",
  ui_story_1022_10220201_3_dialog_content = "본대와 다시는 연락을 못 하게 되는 건 아니겠죠...?",
  ui_story_1022_10220201_4_dialog_content = "안 되면 좋지 뭐. 자유롭게 움직일 수 있잖아.",
  ui_story_1022_10220201_5_dialog_content = "연락이 되는 게 더 귀찮아. 목줄 채운 개처럼 불편하다구.",
  ui_story_1022_10220201_6_dialog_content = "대장님! 그런 말씀을 막 하시면 안 됩니다...",
  ui_story_1022_10220201_7_dialog_content = "뭘 겁내고 그래? 누가 듣는다고? 저 얼음이? 아니면 저 돌멩이가?",
  ui_story_1022_10220201_8_dialog_content = "...크흠!",
  ui_story_1022_10220201_9_dialog_content = "대장님! 바...방금 왠지 이상한 기침 소리가 들린 것 같은데요...",
  ui_story_1022_10220201_10_option_content = "뭐가 이상하다는 거야?!",
  ui_story_1022_10220201_11_dialog_content = "그래, 그냥 평범한 기침이잖아.",
  ui_story_1022_10220201_12_option_content = "자신 있게 말해. 「왠지」가 아니고.",
  ui_story_1022_10220201_13_dialog_content = "그래, 누가 봐도 눈치 주려고 일부러 한 헛기침이잖아.",
  ui_story_1022_10220201_14_dialog_content = "거기 누구야? 설마 「본대」는 아니겠지?",
  ui_story_1022_10220201_15_dialog_content = "꽤 침착하군요, 「정예 탐색 소대」 대장 페피타.",
  ui_story_1022_10220201_16_dialog_content = "그 침착함을 봐서라도 방금 그 발언은 못 들은 것으로 해 주죠. 대신 다음은 없습니다.",
  ui_story_1022_10220201_17_dialog_content = "...3군단장님?!",
  ui_story_1022_10220201_18_dialog_content = "여긴 깜깜하고 조용하다냥. 낮잠 자기 아주 아주 좋겠다냥~",
  ui_story_1022_10220201_19_dialog_content = "정보부장님까지?!",
  ui_story_1022_10220201_20_dialog_content = "...제, 제가 차라도 한잔 끓여 오겠습니다!",
  ui_story_1022_10220201_21_dialog_content = "차가 어디 있다는 거야? 그쪽들 때문에 얘들이 놀라서 환각이 보이나 봐.",
  ui_story_1022_10220201_22_dialog_content = "......",
  ui_story_1022_10220201_23_dialog_content = "거기 기침한 친구는 아직 소개를 못 받았는데, 왜 뒤에서 웅크리고 있어? 지위가 낮아서 그래?",
  ui_story_1022_10220201_24_dialog_content = "난 일루미나 군인이 아니라 아이테르야...",
  ui_story_1022_10220201_25_dialog_content = "그럼 더 이상하잖아. 부하도 아닌데 왜 쫄따구처럼 굴고 있어?",
  ui_story_1022_10220201_26_dialog_content = "아니거든?! 우린 그냥 자연스럽게 동행하게 된 거라고...",
  ui_story_1022_10220201_27_dialog_content = "자연스럽게 쫄따구가 됐다고?",
  ui_story_1022_10220201_28_dialog_content = "야!",
  ui_story_1022_10220201_29_dialog_content = "...수다는 여기까지 합시다. 어쨌든 겨우 합류한 이상, 우선 정보부터 교환합시다.",
  ui_story_1022_10220201_30_dialog_content = "으음... 그러니까 그 거대한 루미나 쪽으로 가다가, 도중에 우연히 우릴 발견했다는 거야?",
  ui_story_1022_10220201_31_dialog_content = "우연이 너무 심한 거 아냐? 나 놀리는 거 아니지?",
  ui_story_1022_10220201_32_dialog_content = "우리가 왜 그래야 합니까?",
  ui_story_1022_10220201_33_dialog_content = "그 이유야 뭐 그쪽들만 알겠지? 나한테 사실대로 말하고 싶지 않다든가,\n그냥 장난이 재미있다든가...",
  ui_story_1022_10220201_34_dialog_content = "장난? 지금 대체 무슨...",
  ui_story_1022_10220201_35_dialog_content = "...좀 진지하게 굴어!",
  ui_story_1022_10220201_36_dialog_content = "PlayerName?",
  ui_story_1022_10220201_37_dialog_content = "나랑 히이로 씨는 소중한 동료를 찾으러 어둠의 밑바닥에 왔어.",
  ui_story_1022_10220201_38_dialog_content = "그 루미나를 향해 가면 찾을 수 있을까 했는데, 결국 못 찾았어...",
  ui_story_1022_10220201_39_dialog_content = "그런 우리가 장난이나 칠 기분일 것 같아?",
  ui_story_1022_10220201_40_dialog_content = "동료...?!",
  ui_story_1022_10220201_41_dialog_content = "그래, 만약 「찾은 게 나라서 실망했어?」 같은 소릴 할 거면 진짜로 화낼 거야!",
  ui_story_1022_10220201_42_dialog_content = "......",
  ui_story_1022_10220201_43_dialog_content = "......",
  ui_story_1022_10220201_44_dialog_content = "아하하하하하!",
  ui_story_1022_10220201_45_dialog_content = "가, 갑자기 뭘 웃는 건데...?",
  ui_story_1022_10220201_46_dialog_content = "너 그거 진짜로 화낸 게 아니었구나?\n오히려 궁금해졌어. 네가 진짜로 화를 내면 어떨지 말이야.",
  ui_story_1022_10220201_47_dialog_content = "너 정말...!",
  ui_story_1022_10220201_48_dialog_content = "근데 아마 못 볼 것 같네. 난 그런 말 할 생각이 전혀 없었거든.",
  ui_story_1022_10220201_49_dialog_content = "내가 오해했었나 봐. 장난이 심했어, 미안.",
  ui_story_1022_10220201_50_dialog_content = "오해...?",
  ui_story_1022_10220201_51_dialog_content = "그게, 너흰 일루미나 사람이잖아?\n그러니까 당연히 상부 명령대로 아무 생각 없이 여기까지 온 바보일 줄 알았지.",
  ui_story_1022_10220201_52_dialog_content = "근데... 「소중한 동료」를 위해서라고? 아하하!",
  ui_story_1022_10220201_53_dialog_content = "특히 너, 3군단장 앞에서 큰소리를 치다니, 배짱도 좋네.",
  ui_story_1022_10220201_54_dialog_content = "나 너 마음에 들어.",
  ui_story_1022_10220201_55_dialog_content = "?!",
  ui_story_1022_10220201_56_dialog_content = "너, 너! 무슨 소릴 하는 거야...?!",
  ui_story_1022_10220201_57_dialog_content = "난 원래 농담할 땐 눈 하나 깜빡이지 않아. 근데 방금 전엔 안 그랬어.",
  ui_story_1022_10220201_58_dialog_content = "난 자기 의지가 있는 사람을 좋아해.",
  ui_story_1022_10220201_59_dialog_content = "그런 건 누구나 있잖아...",
  ui_story_1022_10220201_60_dialog_content = "거기까지 하세요. 또 이야기가 다른 길로 샜습니다.",
  ui_story_1022_10220201_61_dialog_content = "페피타, 그래도 대화할 생각은 있는 모양인데, 이젠 당신 탐색 진척을 보고하세요.",
  ui_story_1022_10220201_62_dialog_content = "어둠의 밑바닥에 들어온 지도 한참 됐는데, 뭔가 파악한 상황이 있습니까?",
  ui_story_1022_10220201_63_dialog_content = "「탐색 진전」이라... 하아, 진짜 싫은 일을 억지로 시켜놓고, 여긴 뭘 해도 힘들다고.",
  ui_story_1022_10220201_64_dialog_content = "주둔지만 해도 그래. 여기 벽지는 내가 여기저기서 주워 온 지명수배서를 붙인 거야.",
  ui_story_1022_10220201_65_dialog_content = "<color=#FFB400>그것도 「내 지명수배서」 말이야.</color>",
  ui_story_1022_10220201_66_dialog_content = "네 지명수배서...? 설마 내가 잘못 이해한 건 아니겠지...? 아하하...",
  ui_story_1022_10220201_67_dialog_content = "음... 우냐앙... 이상하다냥. 필리시, 꿈에서 어떤 아가씨를 봤다냥...",
  ui_story_1022_10220201_68_dialog_content = "아주 아주 낯이 익은 아가씨였다냥~",
  ui_story_1022_10220201_69_dialog_content = "역시 일루미나의 정보부장답네!",
  ui_story_1022_10220201_70_dialog_content = "<color=#e8d9bb>콰아앙!</color>",
  ui_story_1022_10220201_71_dialog_content = "PlayerName! 엎드려요!",
  ui_story_1022_10220201_72_dialog_content = "<color=#e8d9bb>굉음이 얼음 동굴을 뒤흔들었고, 무수한 얼음 조각이 머리 위에서 떨어져 내렸다.</color>",
  ui_story_1022_10220201_73_dialog_content = "<color=#e8d9bb>혼란 속 페피타의 쾌활한 웃음소리가 울려 퍼졌다.</color>",
  ui_story_1022_10220201_74_dialog_content = "그쪽들은 동료 찾으러 가. 방해 안 할 테니까. 그러니까 나도 방해하지 마!",
  ui_story_1022_10220201_75_dialog_content = "냐앙, 대체 왜 낯이 익은 걸까?",
  ui_story_1022_10220201_76_dialog_content = "어, 어떻게 된 거야? 동굴이 갑자기 무너지다니... 페피타는 또 어디 갔어?",
  ui_story_1022_10220201_77_dialog_content = "...아마 도망갔겠죠.",
  ui_story_1022_10220201_78_dialog_content = "네? 도망이라뇨? 왜요?",
  ui_story_1022_10220201_79_dialog_content = "냐앙! 생각났다냥! 저 여자애는 탈주범이다냥!",
  ui_story_1022_10220201_80_dialog_content = "탈주범? 하지만 페피타는 일루미나가 어둠의 밑바닥으로 파견했습니다.\n게다가 일루미나의 병사도 지휘하고 있잖아요.",
  ui_story_1022_10220201_81_dialog_content = "나중에 잡혀서 그런 겁니다냥. 그 뒤엔 계속 일루미나의 감옥에 갇혀있었죠~",
  ui_story_1022_10220201_82_dialog_content = "그렇다면 우리가 저 사람의 약점을 잡고, 억지로 우릴 위해 일하게 하고 있는 겁니까?\n왜 그렇게까지 해서 저 사람을 쓰는 거죠?",
  ui_story_1022_10220201_83_dialog_content = "필리시, 페피타가 투옥된 이유를 알고 있습니까?",
  ui_story_1022_10220201_84_dialog_content = "모릅니다냥...",
  ui_story_1022_10220201_85_dialog_content = "조사와 체포의 책임자는 네메시스입니다냥. 위원회와 직접 논의했다고 들었습니다냥.",
  ui_story_1022_10220201_86_dialog_content = "꽤 큰 사건인 모양이군요.",
  ui_story_1022_10220201_87_dialog_content = "저기... 저도 잠깐 좀 끼어들어도 될까요?",
  ui_story_1022_10220201_88_dialog_content = "페피타가 탈주범이고, 틈을 타 도망쳤다는 것까진 이해했어요. 근데 왜 하필 지금일까요?",
  ui_story_1022_10220201_89_dialog_content = "페피타는 우리랑 합류하기 전부터 부대를 데리고 단독으로 정찰 중이었잖아요.\n도망칠 기회는 언제든지 있었던 거 아닌가요?",
  ui_story_1022_10220201_90_dialog_content = "굳이 히이로 씨 앞에서 도망친 건... 아무리 생각해도 일부러 난이도를 올린 것 같잖아요!",
  ui_story_1022_10220201_91_dialog_content = "......",
  ui_story_1022_10220201_92_dialog_content = "무슨 일입니까...? 방금 그거... 대장님이 암귀용 함정을 터트리신 겁니까?\n암귀는 어디 있습니까?",
  ui_story_1022_10220201_93_dialog_content = "어라...? 대장님은 어디 가셨습니까?!",
  ui_story_1022_10220201_94_dialog_content = "냐앙?! 암귀용 함정?",
  ui_story_1022_10220201_95_dialog_content = "... 어둠의 밑바닥에 들어온 뒤부터 대원들의 감각이 무뎌져서...\n대장님은 거점을 만들 때마다 각종 암귀용 함정을 설치하고 계십니다.",
  ui_story_1022_10220201_96_dialog_content = "특히 「그 장소」를 발견한 뒤부터는 각별히 경계를 엄격하게 하셨습니다.",
  ui_story_1022_10220201_97_dialog_content = "겉보기엔 좀 그래도 대장님은 저흴 무척 잘 챙겨주셨습니다. 헤헤...",
  ui_story_1022_10220201_98_dialog_content = "......",
  ui_story_1022_10220201_99_dialog_content = "그럼 설마... 이제 와서 도망친 건 그러니까...",
  ui_story_1022_10220201_100_dialog_content = "대원들을 우리에게 맡기기 위해서였을까요? 페피타... 정말 알 수 없는 아이로군요...",
  ui_story_1022_10220201_101_dialog_content = "<color=#e8d9bb>어둠의 밑바닥, 백야성 부대 주둔지</color>",
  ui_story_1022_10220201_102_dialog_content = "페피타── 이번 타깃의 이름이야.",
  ui_story_1022_10220201_103_dialog_content = "매우 교활한 녀석이고, 도망치기 위해서라면 무엇이든 할 거야. 모두 신중하게 행동하도록 해.",
  ui_story_1022_10220201_104_dialog_content = "결코 과거의 전철을 밟아서는 안 돼.",
  ui_story_1022_10220201_105_dialog_content = "응, 조장!",
  ui_story_1022_10220201_106_dialog_content = "저번엔... 내가 너무 방심해서 현혹당하는 바람에...",
  ui_story_1022_10220201_107_dialog_content = "네 잘못이 아냐, 에리카.",
  ui_story_1022_10220201_108_dialog_content = "일루미나의 위원회는 그 녀석과 오랜 시간을 싸워왔어.\n그쪽이 먼저 선수를 친 건 어쩔 수 없었던 일이야.",
  ui_story_1022_10220201_109_dialog_content = "하지만 이번엔 우리가 유리해!",
  ui_story_1022_10220201_110_dialog_content = "그 이야기, 나도 자세히 들려줄 수 있을까?",
  ui_story_1022_10220201_111_dialog_content = "저, 전하...!",
  ui_story_1022_10220202_1_dialog_content = "자, 주문하신 「심연의 시선」입니다.",
  ui_story_1022_10220202_2_dialog_content = "환상적인 색채, 죄악의 향기, 왜곡된 문양...\n그렇구나, 이게 바로 사신의 저주가 걸린 음료인 거야?",
  ui_story_1022_10220202_3_dialog_content = "으음...! 이 단맛, 내 위장과 영혼을 사로잡고 있어! 역시 사신... 두려운 존재야...",
  ui_story_1022_10220202_4_dialog_content = "내가 지옥에 안 가면 누가 가겠어? 자, 한 잔 더...!",
  ui_story_1022_10220202_5_dialog_content = "아하하하! 고작 한 잔 마시고도 그렇게 감수성이 풍부해지는 거야? 너 꽤 재밌네.",
  ui_story_1022_10220202_6_dialog_content = "누구야...? 어떤 말할 수 없는 존재가 나한테 속삭이고 있는 거야?",
  ui_story_1022_10220202_7_dialog_content = "말할 수 없는 존재가 아니라 나라고. 아까부터 네 옆에 앉아 있던 손님.",
  ui_story_1022_10220202_8_dialog_content = "너도 이거 좋아해? 취미가 비슷한 것 같으니까 내가 몇 개 더 추천해 줄게.",
  ui_story_1022_10220202_9_dialog_content = "추천이라... 으음, 가끔은 흐름에 몸을 맡기는 것도 나쁘진 않겠지.",
  ui_story_1022_10220202_10_dialog_content = "대신 무알코올로 부탁할게, 고마워....",
  ui_story_1022_10220202_11_dialog_content = "하아?",
  ui_story_1022_10220202_12_dialog_content = "<size=30>...별로 마시지도 않았으면서, 이건 또 무슨 정신 상태야?</size>",
  ui_story_1022_10220202_13_dialog_content = "넌 여기 메뉴를 잘 아는구나... 너도 죄악을 느끼러 자주 와?",
  ui_story_1022_10220202_14_dialog_content = "내가 느끼는 건 죄악만이 아냐. 환희, 스릴, 열광, 기만... 전부 이 몸의 인생 메뉴라고.",
  ui_story_1022_10220202_15_dialog_content = "거짓된 세계를 메뉴로 삼아서 내려다보는 거야?\n어쩌면 너도 미지의 존재에 대항할 잠재력이 있을지도 모르겠네...",
  ui_story_1022_10220202_16_dialog_content = "자, 그럼 함께 죄악에 빠져드는 의식을 치르자. 건배.",
  ui_story_1022_10220202_17_dialog_content = "건배!",
  ui_story_1022_10220202_18_dialog_content = "으으... 이것도 정말 두근거리는 맛이야. 네가 추천하는 건 전부 맛있는 것 같아.",
  ui_story_1022_10220202_19_dialog_content = "그거야 당연하지.",
  ui_story_1022_10220202_20_dialog_content = "그나저나 왜 무알코올에 집착하는 거야? 딱히 겉으로만 성실한 척하는 타입도 아닌 것 같은데.",
  ui_story_1022_10220202_21_dialog_content = "사실... 난 지금 임무 수행 중이거든. 그래서 자제해야 돼...",
  ui_story_1022_10220202_22_dialog_content = "헤에, 분명히 엄청 대단한 일이겠지?",
  ui_story_1022_10220202_23_dialog_content = "백야성의 이단조사단... 확실히 훌륭한 일이지... 이 세계에 무척 중요한 일이라구...",
  ui_story_1022_10220202_24_dialog_content = "이단조사단이 움브라톤에 왔어?!",
  ui_story_1022_10220202_25_dialog_content = "움브라톤은 악마에게 지배당하는 땅이야. 혼란스럽고, 무질서해.\n그래서 우리 「타깃」도 여기로 도망쳤어.",
  ui_story_1022_10220202_26_dialog_content = "그 사람은 백야성의 성전을 훔쳐서 움브라톤에 잠입했는데, 그 뒤로는 행적이 묘연해...",
  ui_story_1022_10220202_27_dialog_content = "(내 얘기잖아...?)",
  ui_story_1022_10220202_28_dialog_content = "반드시 잡아서 성전을 되찾아야 해... 어? 마음의 친구, 어디 가?",
  ui_story_1022_10220202_29_dialog_content = "나... 찬 걸 너무 많이 마셔서 머리가 아프네. 잠깐 화장실 좀!",
  ui_story_1022_10220202_30_dialog_content = "...제길! 절호의 기회였는데, 놓쳐버리다니!",
  ui_story_1022_10220202_31_dialog_content = "마음의 친구가 흉악 탈주범 페피타...? 어떻게 그런...",
  ui_story_1022_10220202_32_dialog_content = "어서 쫓아! 아직 기회가 있어!",
  ui_story_1022_10220202_33_dialog_content = "일루미나가 선수 치게 두지만 않으면...",
  ui_story_1022_10220202_34_dialog_content = "(...여기 숨으면 괜찮겠지.)",
  ui_story_1022_10220202_35_dialog_content = "(나무가 숨기 가장 적합한 곳은 숲, 오로리안 숨기 가장 적합한 곳은 당연히──)",
  ui_story_1022_10220202_36_dialog_content = "(장례식 현장이지!)",
  ui_story_1022_10220202_37_dialog_content = "(뒷사람들은 구덩이를 파기 시작했고, 관 속의 「사망자」가 나라고 누가 생각하겠어? 아하하!)",
  ui_story_1022_10220202_38_dialog_content = "이제 그만 누워 있으세요. 직접 나오세요.",
  ui_story_1022_10220202_39_dialog_content = "역시 여기 숨어 있었군요. 정말 당신답습니다.",
  ui_story_1022_10220202_40_dialog_content = "시체를 깔고 누워도 전혀 꺼림칙한 게 없는 겁니까?",
  ui_story_1022_10220202_41_dialog_content = "!!!",
  ui_story_1022_10220202_42_dialog_content = "(어디서 들킨 거지...? 아, 옷!)",
  ui_story_1022_10220202_43_dialog_content = "(실수다... 누가 관에 들어갈 때 이런 옷을 입겠냐고...)",
  ui_story_1022_10220202_44_dialog_content = "(아...앞으로는 꼭 옷을 잘 입어야지!)",
  ui_story_1022_10220202_45_dialog_content = "그 페피타라는 자가 백야성의 성전을 훔쳤다고?",
  ui_story_1022_10220202_46_dialog_content = "그렇습니다, 전하. 다만 그자가 훔친 것은 진짜가 아닙니다.\n따라서 절도 사건 자체는 그다지 중요하지 않습니다.",
  ui_story_1022_10220202_47_dialog_content = "문제는 페피타가 그 가짜 성전을 가지고 아스트라에서 가장 가증스러운 이단 조직...\n진리의 결사에 투신했다는 것입니다!",
  ui_story_1022_10220202_48_dialog_content = "...도둑맞은 게 가짜라면, 진짜 성전은 어디 있지?",
  ui_story_1022_10220202_49_dialog_content = "그것이 바로 핵심 문제입니다.\n진짜 성전은 몇 년 전에 유실되었는데, 여러 가지 단서에 따르면...",
  ui_story_1022_10220202_50_dialog_content = "이미 진작에 진리의 결사 녀석들의 손에 들어간 것으로 보입니다.",
  ui_story_1022_10220202_51_dialog_content = "이해했어. 진리의 결사의 본거지는 아무도 모르고, 결사의 일원도 행적을 종잡을 수 없겠지.",
  ui_story_1022_10220202_52_dialog_content = "마침 페피타가 나타나서 가짜 성전을 훔쳤고, 에리카와 술을 마시는 등,\n기고만장한 태도를 보이고 있어.",
  ui_story_1022_10220202_53_dialog_content = "당신들은 그자를 단서로 삼아 진리의 결사를 찾고, 진짜 성전을 되찾을 생각이구나.",
  ui_story_1022_10220202_54_dialog_content = "역시 전하께서는 영명하십니다. 저희의 당초 계획은 전하 말씀대로였습니다.",
  ui_story_1022_10220202_55_dialog_content = "그러나 괘씸하게도 일루미나의 위원회가 보낸 「집행자」가 선수를 써서,\n페피타를 일루미나로 압송했습니다...",
  ui_story_1022_10220202_56_dialog_content = "그럼 이번에 페피타가 어둠의 밑바닥에 나타난 건 일루미나가 파견한 것이겠지.\n그렇다면 우리가 그자에게 손을 쓰는 건 쉽지 않을 거야.",
  ui_story_1022_10220202_57_dialog_content = "전하, 그 점이라면 안심하셔도 좋습니다.",
  ui_story_1022_10220202_58_dialog_content = "저희 이단심문조의 이번 작전은 성주님과 일루미나 대원수의 허가를 받았습니다.",
  ui_story_1022_10220202_59_dialog_content = "성주님께서는 일루미나 대원수 라인하르트와 각서를 교환하신 후,\n저희가 페피타를 추적하고 기존 직무를 수행하는 것을 허락하셨습니다.",
  ui_story_1022_10220202_60_dialog_content = "이번에는 절대로 도망칠 수 없을 겁니다!",
  ui_story_1022_10220202_61_dialog_content = "...그렇다면 우리도 일단은 일루미나의 탐색대와 함께 움직여야겠네.",
  ui_story_1022_10220202_62_dialog_content = "얼마 전에 페피타와 조우했다고 하거든.",
  ui_story_1022_10220301_1_dialog_content = "카렌! 여기야! 진짜 빨리 왔네!",
  ui_story_1022_10220301_2_dialog_content = "백야성의 성전이 걸린 일이니까, 소홀히 해선 안 되지.",
  ui_story_1022_10220301_3_dialog_content = "넌 어때? 흉악 탈주범과 조우했으니 뭔가 해를 입었겠지?",
  ui_story_1022_10220301_4_dialog_content = "크흠... 확실히 장난에 꼴 좋게 당해버리긴 했지...",
  ui_story_1022_10220301_5_dialog_content = "그래도 걱정 마! 계속 감응하면서 왔거든. 페피타는 분명히 이 근처에 있을 거야.",
  ui_story_1022_10220301_6_dialog_content = "......",
  ui_story_1022_10220301_7_dialog_content = "필리시는 페피타가 이끌던 대원을 데리고 먼저 비행기로 돌아가기로 했어.\n나랑 히이로 씨가 너희랑 같이 움직일 거야.",
  ui_story_1022_10220301_8_dialog_content = "페피타는 일루미나에서 어둠의 밑바닥 정찰에 파견한 인원입니다.\n전 그자의 신병과 정찰 성과를 확보할 의무가 있습니다.",
  ui_story_1022_10220301_9_dialog_content = "이번엔 우리에게 양보해 줘야 할 것 같은데.",
  ui_story_1022_10220301_10_dialog_content = "당신은?",
  ui_story_1022_10220301_11_dialog_content = "이쪽은 백야성 이단심문조의 조장이야. 지금 상황을 설명하자면...",
  ui_story_1022_10220301_12_dialog_content = "...대원수님께서 백야성의 체포 작전을 허락하셨다는 겁니까?",
  ui_story_1022_10220301_13_dialog_content = "알겠습니다. 신병은 당신들에게 넘기겠습니다. 단, 그 전에 그자에게 질문 몇 가지를 하겠습니다.",
  ui_story_1022_10220301_14_dialog_content = "「그 장소」를 발견했을 때 대장님은 처음에 무척 흥분한 모습이었습니다.\n하지만 저희의 안전을 고려해서인지 저흴 데리고 바로 그곳을 떠나셨습니다.",
  ui_story_1022_10220301_15_dialog_content = "제가 보기엔 대장님은 그 기괴한 광경을 낯설게 느끼지 않으시는 듯했습니다...",
  ui_story_1022_10220301_16_dialog_content = "페피타는 분명히 뭔가 알고 있었습니다.",
  ui_story_1022_10220301_17_dialog_content = "흥, 일루미나인들은 여전히 무례하네.\n한 번 선수를 친 것도 모자라서, 아직도 욕심을 못 버린 모양이지?!",
  ui_story_1022_10220301_18_dialog_content = "제가 신병은 넘기겠다고 했을 텐...",
  ui_story_1022_10220301_19_dialog_content = "내가 뭐 스테이크인 줄 알아? 나누고 주고 하게? 내 동의는 받았어?",
  ui_story_1022_10220301_20_dialog_content = "페피타!",
  ui_story_1022_10220301_21_dialog_content = "제 발로 나온 거냐?!",
  ui_story_1022_10220301_22_dialog_content = "마음의 친구... 아, 아니지... 더는 현혹되선 안 돼...",
  ui_story_1022_10220301_23_dialog_content = "누가 누굴 현혹해? 그럼 같이 마시고 즐거웠던 건 현실이 아니란 소리야?\n그건 다 네가 실제로 느낀 감정이잖아.",
  ui_story_1022_10220301_24_dialog_content = "자신의 본심을 솔직하게 마주하고, 진실하게 맞서 싸워, 에리카!",
  ui_story_1022_10220301_25_dialog_content = "내 감정... 허구의 세계 속 진실...",
  ui_story_1022_10220301_26_dialog_content = "더는 에리카를 속이지 마!",
  ui_story_1022_10220301_27_dialog_content = "(엄청나게 빠른 몸놀림이야!)",
  ui_story_1022_10220301_28_dialog_content = "어딜 도망치려고?",
  ui_story_1022_10220301_29_dialog_content = "산화적멸──!",
  ui_story_1022_10220301_30_dialog_content = "<color=#e8d9bb>연이어 계속되는 공격이 페피타를 휘감았다.\n그러나 그녀는 이따금 장난처럼 몇 번 반격할 뿐, 도약이나 회피가 대부분의 움직임이었다.</color>",
  ui_story_1022_10220301_31_dialog_content = "<color=#e8d9bb>혼자서 여럿을 상대하면서도 결코 열세에 빠진 모습 같지 않았다.</color>",
  ui_story_1022_10220301_32_dialog_content = "이 녀석, 설마 어둠의 밑바닥의 영향을 받지 않는 건가?!",
  ui_story_1022_10220301_33_dialog_content = "역시 보통이 아니네...",
  ui_story_1022_10220301_34_dialog_content = "(보통의 오로리안이라면 어둠의 밑바닥에선 힘이 억제될 텐데,\n페피타는 전혀 아무렇지도 않은 것 같아...)",
  ui_story_1022_10220301_35_dialog_content = "아하하하, 이제 이 페피타 님의 대단함을 알겠어?",
  ui_story_1022_10220301_36_dialog_content = "자, 이제 튜토리얼은 끝났어~ 지금부터는 메인 빌런 페피타 님의 광폭화 시간이야!",
  ui_story_1022_10220301_37_dialog_content = "페디, 페디── 커져라!",
  ui_story_1022_10220301_38_dialog_content = "뭐야... 이 에너지...!",
  ui_story_1022_10220301_39_dialog_content = "어떻게 된 거지? 갑자기 호흡이 힘들어지다니...",
  ui_story_1022_10220301_40_dialog_content = "다크매터가... 짙어졌어...",
  ui_story_1022_10220301_41_dialog_content = "(틀림없어... 페피타가 들고 있는 인형에서 암귀의 기운이 느껴져... 대체 어떻게 된 거지?)",
  ui_story_1022_10220301_42_dialog_content = "커져라! 커져! 더! 더 크게──!",
  ui_story_1022_10220301_43_dialog_content = "<color=#e8d9bb>하늘을 찌르는 페피타의 웃음소리와 함께 인형은 점점 팽창했고,\n육중한 몸이 연거푸 지면에 충격을 가했다.</color>",
  ui_story_1022_10220301_44_dialog_content = "<color=#e8d9bb>심지어 녀석의 그림자조차 마치 실체가 있는 것처럼 느껴졌다.\n검고 커다란 어둠은 주변의 모든 오로리안의 신체와 정신을 압도했다.</color>",
  ui_story_1022_10220301_45_dialog_content = "이대로 가면 내 부하들이 못 버텨...!",
  ui_story_1022_10220301_46_dialog_content = "어떻게 저런 기괴한 인형을 가지고 있는 거죠?!",
  ui_story_1022_10220301_47_dialog_content = "페디는 내 <color=#FFB400>마수</color>야. 마수라고 하면 당연히 마성 정도는 있어야지~",
  ui_story_1022_10220301_48_dialog_content = "자, 마음껏 맛보라구! 마수랑 제대로 놀 수 있는 시간은...",
  ui_story_1022_10220301_49_dialog_content = "많지. 않을. 테니까.",
  ui_story_1022_10220301_50_dialog_content = "......!",
  ui_story_1022_10220301_51_dialog_content = "뭐, 뭐야... 저건...?",
  ui_story_1022_10220301_52_dialog_content = "PlayerName, 왜 그래? 갑자기 두리번거리고.",
  ui_story_1022_10220301_53_dialog_content = "<color=#e8d9bb>그녀가 왔다.</color>",
  ui_story_1022_10220301_54_dialog_content = "뭔가가 오고 있어... 엄청난 다크매터가... 빨리 피해!",
  ui_story_1022_10220301_55_dialog_content = "<color=#e8d9bb>빠르게 몸을 피한 사람들의 눈앞에, 하늘에서 떨어지는 한 방울의 유백색 눈물이 비쳤다.</color>",
  ui_story_1022_10220301_56_dialog_content = "<color=#e8d9bb>눈물은 그대로 땅에 떨어지고──</color>",
  ui_story_1022_10220301_57_dialog_content = "<color=#e8d9bb>엄청난 에너지를 내뿜으며 폭발했다.</color>",
  ui_story_1022_10220301_58_dialog_content = "누가 제 친구를 괴롭히는 거죠?",
  ui_story_1022_10220301_59_dialog_content = "<color=#FFB400>우르슬라</color>, 역시 왔구나~",
  ui_story_1022_10220301_60_dialog_content = "<color=#e8d9bb>모래 먼지가 가라앉고, 폭발의 중심부에 나타난 모습은 자리에 있던 모두가 숨을 멈추게 만들었다.</color>",
  ui_story_1022_10220301_61_dialog_content = "이 「파장」... <color=#FFB400>팬텀</color>이야!",
  ui_story_1022_10220301_62_dialog_content = "페피타! 이단의 결사에 투신하는 것도 모자라서, 암귀와 결탁했던 거냐?!",
  ui_story_1022_10220301_63_dialog_content = "저 몸... 마치 짙은 안개에 감싸인 것 같아서 파악할 수가 없어...",
  ui_story_1022_10220301_64_dialog_content = "결탁이라니, 말도 안 되는 트집이에요! 페피타와 저는 오랜 친구예요.\n당신들보다 더 먼저 안 사이라구요! 결탁한 건 오히려 당신들이겠죠!",
  ui_story_1022_10220301_65_dialog_content = "?!",
  ui_story_1022_10220301_66_dialog_content = "아하하하, 다들 그 표정 뭐야? 진짜 웃기네!\n그 표정들만으로도 내가 위험을 무릅쓰고 나타난 보람이 있었어!",
  ui_story_1022_10220301_67_dialog_content = "...팬텀이 올 줄 알고 있었던 거야?",
  ui_story_1022_10220301_68_dialog_content = "그걸 말이라고. 우르슬라가 근처에 있는 걸 몰랐으면, 내가 뭐 하러 너희한테 싸움을 걸었겠어?\n바보도 아니고.",
  ui_story_1022_10220301_69_dialog_content = "두 번이나 내 「손바닥 위에서 가지고 놀아진」 기분이 어때? 아이테르?",
  ui_story_1022_10220301_70_dialog_content = "제길...!",
  ui_story_1022_10220301_71_dialog_content = "페피타, 제가 준 페디는요? 전 그 아이의 기운이 느껴져서 특별히 찾으러 와 준 거예요.\n보세요. 제가 당신을 얼마나 잘 대해주는지 말이에요.",
  ui_story_1022_10220301_72_dialog_content = "잘 있어, 보라고... 근데 왜? 도로 달라고 하진 마. 모처럼 친해졌는데.",
  ui_story_1022_10220301_73_dialog_content = "(내가 잘못 들은 거 아니지...? 지금 저 대화, 왠지 진짜로 좀 「친구」 같잖아...)",
  ui_story_1022_10220301_74_dialog_content = "페피타, 팬텀을 끌어들였다고 해서 뜻대로 될 거라 생각하지 마.",
  ui_story_1022_10220301_75_dialog_content = "백야성의 성전을 훔친 죄는 반드시 대가를 치르게 될 테니까!",
  ui_story_1022_10220301_76_dialog_content = "훔치다니? 그거 원래 진리의 결사 거잖아.",
  ui_story_1022_10220301_77_dialog_content = "뭐라고?!",
  ui_story_1022_10220301_78_dialog_content = "그러니까 난 너네 백야성한테 빚진 게 전혀 없어.",
  ui_story_1022_10220301_79_dialog_content = "일루미나는 더 말할 것도 없고.\n내가 찾아가서 책임을 추궁하지 않은 것만으로도 다행인 줄 알라구.",
  ui_story_1022_10220301_80_dialog_content = "아, 오해하지 마. 물론 추궁할 거거든. 눈곱만큼도 그냥 안 넘어갈 테니까!",
  ui_story_1022_10220301_81_dialog_content = "......",
  ui_story_1022_10220301_82_dialog_content = "벨리사리아 그 아줌마는 「심장」으로 협박하면 날 부려 먹을 수 있다고 생각했나 본데,\n꿈 깨라고 해.",
  ui_story_1022_10220301_83_dialog_content = "이 페피타 님은 더는 같이 놀아 줄 생각 없으니까, 아하하하!",
  ui_story_1022_10220301_84_dialog_content = "우르슬라, 가자.",
  ui_story_1022_10220301_85_dialog_content = "같이 밤새도록 노는 거야!",
  ui_story_1022_10220301_86_dialog_content = "페피타...",
  ui_story_1022_10220301_87_dialog_content = "거기 서라!",
  ui_story_1022_10220301_88_dialog_content = "당신들... 귀찮네요! 전부 죽어버려요!",
  ui_story_1022_10220301_89_dialog_content = "크아아아──!",
  ui_story_1022_10220301_90_dialog_content = "조심해!",
  ui_story_1022_10220302_1_dialog_content = "(페디, 가서 빅토리아 님한테 내가 있는 곳을 알려드려.)",
  ui_story_1022_10220302_2_dialog_content = "얼른 가요, 페피타. 뭘 꾸물대고 있는 거죠? 같이 놀자고 한 건 당신이잖아요?",
  ui_story_1022_10220302_3_dialog_content = "네네~ 갑니다~",
  ui_story_1022_10220302_4_dialog_content = "아하하하! 그 오로리안들 모습 봤어요?\n제가 때리는데 반격도 못 하고, 그저 무능하게 화만 내고 말이에요.",
  ui_story_1022_10220302_5_dialog_content = "아니, 그 전의 내 활약을 네가 봤어야 돼.\n걔들이 방심했을 땔 노려서 단숨에 함정을 터트렸거든.",
  ui_story_1022_10220302_6_dialog_content = "진짜 엄청 화려했다구~",
  ui_story_1022_10220302_7_dialog_content = "왜 그런 재미있는 일에 절 안 부른 거죠! 너무해요!",
  ui_story_1022_10220302_8_dialog_content = "흐아아앙! 저한테도 더 화려하고 미친 모습을 보여달란 말이에요!",
  ui_story_1022_10220302_9_dialog_content = "에이, 울지 마. 우리 둘이라면 그런 건 얼마든지 할 수 있잖아?",
  ui_story_1022_10220302_10_dialog_content = "『보고드립니다. 멀리서 한 움직이는 「물건」을 발견했습니다.\n왠지 도망치는 중인 것 같았습니다.』",
  ui_story_1022_10220302_11_dialog_content = "『저건... 우르슬라 님께서 그 오로리안에게 주셨던 마수다!』",
  ui_story_1022_10220302_12_dialog_content = "『그 오로리안, 뭘 꾸미고 있는 거지? 역시 오로리안은 모두 교활한 놈들이다.』",
  ui_story_1022_10220302_13_dialog_content = "『어떻게 하면 좋겠습니까? 그냥 가게 놔둡니까?』",
  ui_story_1022_10220302_14_dialog_content = "『멍청한 소리! 얼른 저 마수를 잡아서 우르슬라 님께 드려라!』",
  ui_story_1022_10220302_15_dialog_content = "『예!』",
  ui_story_1022_10220302_16_dialog_content = "빌어먹을!",
  ui_story_1022_10220302_17_dialog_content = "또 놓쳐버리다니... 겨우 몰아붙였는데!",
  ui_story_1022_10220302_18_dialog_content = "페피타가 팬텀을 불러들일 줄 누가 알았겠어요? 너무 속상해하지 마세요.",
  ui_story_1022_10220302_19_dialog_content = "하지만 제 의문은 풀렸습니다.",
  ui_story_1022_10220302_20_dialog_content = "방금 그 팬텀의 몸에는 산호 같은 게 자라고 있었습니다...",
  ui_story_1022_10220302_21_dialog_content = "아마 페피타는 「그 장소」를 발견했을 때 팬텀이 근처에 있다는 걸 알았을 겁니다.\n그래서 기회를 노려 팬텀에게 의탁하기로 결정했겠지요.",
  ui_story_1022_10220302_22_dialog_content = "대체 왜 팬텀한테... 팬텀이 뭘 해 줄 수 있는데?",
  ui_story_1022_10220302_23_dialog_content = "그러니까 녀석이 이미 철저히 타락했다는 거야! 에리카, 더는 녀석에게 현혹당해선 안 돼!",
  ui_story_1022_10220302_24_dialog_content = "......",
  ui_story_1022_10220302_25_dialog_content = "아무도 이상하다고 생각하지 않아?",
  ui_story_1022_10220302_26_dialog_content = "어떤 점 말인데? 카렌.",
  ui_story_1022_10220302_27_dialog_content = "그 우르슬라라는 팬텀은 상당한 힘을 지니고 있었어.\n하지만 우릴 공격하는 데는 그다지 흥미를 보이지 않았지.",
  ui_story_1022_10220302_28_dialog_content = "두 번의 공격은 전부 페피타를 지키기 위한 것이었고.",
  ui_story_1022_10220302_29_option_content = "설마 우정의 힘인가?!",
  ui_story_1022_10220302_30_dialog_content = "...지금 농담하는 거야?",
  ui_story_1022_10220302_31_dialog_content = "미, 미안!",
  ui_story_1022_10220302_32_option_content = "확실히 그 둘은 친구처럼 보였어.",
  ui_story_1022_10220302_33_dialog_content = "페피타는 우르슬라가 와줄 거라고 믿었으니까 거리낌 없이 모습을 드러낸 거겠지.",
  ui_story_1022_10220302_34_dialog_content = "오로리안과 팬텀 사이에 정말 우정이란 게 존재할 수 있을까?",
  ui_story_1022_10220302_35_dialog_content = "확실히 우르슬라의 행동은 이해하기 어렵습니다.",
  ui_story_1022_10220302_36_dialog_content = "우리에게 적의는 없으면서, 반면에 페피타를 구했다...?\n무엇을 위해서일까요? 두 사람은 대체 뭘 하려는 걸까요?",
  ui_story_1022_10220302_37_dialog_content = "어쩌면 그냥 놀고 싶어서일지도 몰라.",
  ui_story_1022_10220302_38_dialog_content = "......",
  ui_story_1022_10220302_39_dialog_content = "농담은 집어치워!",
  ui_story_1022_10220302_40_dialog_content = "에리카, 루미나 스톤 잘 챙겨. 출발하자.",
  ui_story_1022_10220302_41_dialog_content = "어?! 페피타를 계속 쫓아갈 건가요?",
  ui_story_1022_10220302_42_dialog_content = "당연하지! 팬텀 따위가 내 길을 막을 순 없어.",
  ui_story_1022_10220302_43_dialog_content = "페피타가 백야성 성전에 대한 정보를 가지고 있는 한, 우리에겐 다른 선택지도 없으니까.",
  ui_story_1022_10220302_44_dialog_content = "...궁금한 게 있다면 그자를 만난 다음에 물어봐.",
  ui_story_1022_10220302_45_dialog_content = "(카렌이 궁금한 건 「백야성의 성전이 진리의 결사의 것」이라는 부분이겠지...)",
  ui_story_1022_10220302_46_dialog_content = "(카렌 말대로라면 페피타는 진리의 결사 멤버야.)",
  ui_story_1022_10220302_47_dialog_content = "(근데 왜 일루미나의 죄수가 됐을까? 페피타가 일루미나에 추궁한다는 책임은 또 뭐지?)",
  ui_story_1022_10220302_48_dialog_content = "(수수께끼가 점점 더 늘어가고 있어...)",
  ui_story_1022_10220401_1_dialog_content = "어서 오세요~ 빙원의 산호 숲이랍니다!",
  ui_story_1022_10220401_2_dialog_content = "예쁘죠? 이상하죠? 정말 새로운 모습이죠? 우후후, 마음껏 감탄해도 좋아요!",
  ui_story_1022_10220401_3_dialog_content = "응, 아름다우면서도 일그러진 게 너랑 정말 잘 어울려.",
  ui_story_1022_10220401_4_dialog_content = "뭐예요, 페피타, 하나도 안 신났잖아요. 재미없게!",
  ui_story_1022_10220401_5_dialog_content = "진짜야, 정말 특별한 풍경이라 깜짝 놀랐다구.",
  ui_story_1022_10220401_6_dialog_content = "(뭐, 사실은 저번에 처음 봤을 때 느낀 기분이었지만.)",
  ui_story_1022_10220401_7_dialog_content = "알았으면 됐어요. 자, 얼른 오세요. 재미있는 건 아직 많이 있으니까요.",
  ui_story_1022_10220401_8_dialog_content = "헤에~ 이렇게 기대하게 만들어 버렸으니까, 절대 실망시키면 안 돼?",
  ui_story_1022_10220401_9_dialog_content = "<color=#e8d9bb>원래라면 살풍경이었을 얼음 벌판에는 왜인지 이끼와 산호, 아름다운 나무가 있었고,\n마치 암흑의 동화 속 같은 광경이 펼쳐져 있었다.</color>",
  ui_story_1022_10220401_10_dialog_content = "<color=#e8d9bb>그리고 그 산호의 숲 속에는──</color>",
  ui_story_1022_10220401_11_dialog_content = "?!",
  ui_story_1022_10220401_12_dialog_content = "(저건... 오로리안? 하지만 눈에 생기가 없고, 오히려 암귀 같아...\n근데 겉모습은 암귀랑 전혀 다른걸.)",
  ui_story_1022_10220401_13_dialog_content = "<color=#e8d9bb>오로리안을 닮은 생물이 산호 숲 속에서 멍한 표정으로 움직이고 있었다.\n그들은 기계적인 동작으로 무성한 이끼와 산호를 정리하고 있었다.</color>",
  ui_story_1022_10220401_14_dialog_content = "<color=#e8d9bb>아름다운 식물들과 대조되는 그 움직임은, 보는 이들을 소름 돋게 만드는 모습이었다.</color>",
  ui_story_1022_10220401_15_dialog_content = "우르슬라, 저건...?",
  ui_story_1022_10220401_16_dialog_content = "보면 모르겠어요? 산호잖아요!",
  ui_story_1022_10220401_17_dialog_content = "그게 아니라 산호를 정리하고 있는 쟤들 말이야... 오로리안? 암귀? 아니면 수수께끼의 생물?",
  ui_story_1022_10220401_18_dialog_content = "아... 저런 건 뭐 하러 보는 건데요? 재미도 없는걸.",
  ui_story_1022_10220401_19_dialog_content = "저것들은 오로리안이 아니에요. 오로리안의 재미있는 점을 조금도 물려받지 못했거든요.",
  ui_story_1022_10220401_20_dialog_content = "(「물려받지 않았다」...? 그럼 어쨌든 오로리안과 관계가 있다는 건가?)",
  ui_story_1022_10220401_21_dialog_content = "그저 여기 오래 있으면서 튼튼해졌고, <color=#FFB400>우리</color> 대신 허드렛일이나 해 주는 것들이에요.",
  ui_story_1022_10220401_22_dialog_content = "시키는 일은 뭐든지 하고, 그 외엔 아무 쓸모도 없어요.",
  ui_story_1022_10220401_23_dialog_content = "말도 안 통하고, 살짝 놀기만 해도 그냥 죽어버리니까 재미도 없고,\n오로리안이랑은 비교도 안 된다구요!",
  ui_story_1022_10220401_24_dialog_content = "(소통도 안 되고, 전투력도 높지 않다... 그런 뜻이겠지?)",
  ui_story_1022_10220401_25_dialog_content = "저런 건 신경 쓰지 마요. 저야말로 여기 주인이니까요. 당신은 저만 따라오면 돼요!",
  ui_story_1022_10220401_26_dialog_content = "......",
  ui_story_1022_10220402_1_dialog_content = "휴... 오늘 실험도 드디어 끝났네.",
  ui_story_1022_10220402_2_dialog_content = "요즘 테스트가 점점 더 힘들어지는 거 같지 않아?",
  ui_story_1022_10220402_3_dialog_content = "응... 솔직히 말하면, 나 이제 좀 무리인 거 같아...",
  ui_story_1022_10220402_4_dialog_content = "온몸이 아프고... 밤에도 나쁜 꿈만 꾸고...",
  ui_story_1022_10220402_5_dialog_content = "나도 그래...",
  ui_story_1022_10220402_6_dialog_content = "역시 페피타는 대단하네.\n심장도 안 좋고, 하는 테스트도 제일 힘든 건데 한 번도 뭐라 한 적 없잖아.",
  ui_story_1022_10220402_7_dialog_content = "이 정도는 아무것도 아냐~",
  ui_story_1022_10220402_8_dialog_content = "아버지가 맞서고 있는 위험에 비하면, 내가 하는 건 누워서 쉬는 수준이니까.",
  ui_story_1022_10220402_9_dialog_content = "너희 아빠... 어둠의 밑바닥을 탐색하고 계신다 그랬지?",
  ui_story_1022_10220402_10_dialog_content = "맞아! 아버지는 일루미나 어둠의 밑바닥 탐색대의 일원이야. 아주 대단한 일을 하신다구!",
  ui_story_1022_10220402_11_dialog_content = "나도 크면 어둠의 밑바닥을 탐색하러 갈 거야. 그럼 아버지도 분명히 기뻐하실 거라구. 헤헷.",
  ui_story_1022_10220402_12_dialog_content = "정말 멋져, 페피타. 힘내! 우리가 응원할 테니까!",
  ui_story_1022_10220402_13_dialog_content = "근데 그럼 다음 면담일 때 너희 아빠는 안 오시는 거지?",
  ui_story_1022_10220402_14_dialog_content = "...어, 어쩔 수 없잖아. 아버지는 바쁘니까...",
  ui_story_1022_10220402_15_dialog_content = "갖고 싶은 거 있으면 우리 엄마한테 갖다 달라고 할게!",
  ui_story_1022_10220402_16_dialog_content = "으, 응... 그래, 고마워.",
  ui_story_1022_10220402_17_dialog_content = "...아버지가 돌아오면 날 보러 와 주실 거야... 분명히.",
  ui_story_1022_10220402_18_dialog_content = "<color=#e8d9bb>몇 년 후──</color>",
  ui_story_1022_10220402_19_dialog_content = "그 아이는 요즘 어떻지?",
  ui_story_1022_10220402_20_dialog_content = "예전 그대로입니다. 먹기 싫은 건 전부 남기고, 좋아하는 건 2인분을 달라고 합니다.",
  ui_story_1022_10220402_21_dialog_content = "그리고 저희한테 음악을 틀라고 시끄럽게 외치고, 무시하면 큰 소리로 노래를 부릅니다...",
  ui_story_1022_10220402_22_dialog_content = "그렇게 오래 감시했으면 취향 정도는 파악할 때도 됐잖아? 싫어하는 건 주지 마.",
  ui_story_1022_10220402_23_dialog_content = "...예!",
  ui_story_1022_10220402_24_dialog_content = "너무 응석을 받아주는 거 아닙니까? 어쨌든 죄수 신분이잖습니까.",
  ui_story_1022_10220402_25_dialog_content = "저 아이의 체질은 특별해.\n게다가 「심장」도 저 상태인데, 영양 부족으로 쓰러지기라도 하면 손해 보는 건 우리야.",
  ui_story_1022_10220402_26_dialog_content = "그리고 음식은 낭비하면 안 되잖아?",
  ui_story_1022_10220402_27_dialog_content = "...그럼 저 아이가 당신에게 협력해 주길 바라겠습니다.",
  ui_story_1022_10220402_28_dialog_content = "야, 어떻게 됐어? 음반은 언제 가져올 건데?\n내가 계속 노래 불러야 되는 건 아니지? 혹시 내 노래에 중독됐어?",
  ui_story_1022_10220402_29_dialog_content = "어쩔 수 없지, 그럼 팬서비스 차원에서 조금 더 들려줄게. 크흠! 아름다운 초원~ 나의 집~♪",
  ui_story_1022_10220402_30_dialog_content = "넌 초원 같은 건 본 적 없을 텐데, 페피타.",
  ui_story_1022_10220402_31_dialog_content = "뭐야? 또 그쪽이야? 아줌마 얼굴은 이미 지겹거든? 저리 가.",
  ui_story_1022_10220402_32_dialog_content = "지겨워? 옛날에 실험실에 있을 땐 날 보면 꽤 기뻐했었는데.",
  ui_story_1022_10220402_33_dialog_content = "나 말고는 아무도 널 보러 오는 사람이 없었으니까.",
  ui_story_1022_10220402_34_dialog_content = "그쪽은 날 보러 온 게 아니잖아. 그냥 귀중한 실험체가 어떻게 돼가고 있나 확인하러 온 거였지.",
  ui_story_1022_10220402_35_dialog_content = "실험체의 가치는 절대적이고, 측정 가능해.",
  ui_story_1022_10220402_36_dialog_content = "하지만 「감정」은 설령 「가족애」라 해도 불확실해. 쉽게 속일 수 있고 말이야.",
  ui_story_1022_10220402_37_dialog_content = "그건 오히려 네가 가장 잘 알고 있을 거야.",
  ui_story_1022_10220402_38_dialog_content = "......",
  ui_story_1022_10220402_39_dialog_content = "만약 단순한 반항기가 아니라 정말로 가식이나 거짓을 증오하고 있다면...",
  ui_story_1022_10220402_40_dialog_content = "너라는 「실험체」에 대한 내 중시를 긍정적으로 생각해야 할 거야.",
  ui_story_1022_10220402_41_dialog_content = "율리시스, 가져와.",
  ui_story_1022_10220402_42_dialog_content = "......",
  ui_story_1022_10220402_43_dialog_content = "...그 장치...!",
  ui_story_1022_10220402_44_dialog_content = "(틀림없어... 일루미나의 연구원이 내 망가진 심장을 인공 심장으로 바꿨던 그 당시...)",
  ui_story_1022_10220402_45_dialog_content = "(이식 수술이 끝나고 눈을 떴을 때 침대 곁에 있었던 그 장치야...)",
  ui_story_1022_10220402_46_dialog_content = "(저 안에... 분명히 내 진짜 심장이 들어 있어!)",
  ui_story_1022_10220402_47_dialog_content = "이 안에 뭐가 들어 있는지 알고 있나 보구나.",
  ui_story_1022_10220402_48_dialog_content = "...뭘 어쩔 생각이야?",
  ui_story_1022_10220402_49_dialog_content = "간단해. 넌 네 능력을 발휘해서 어둠의 밑바닥에 있는 「가디언 1호」의 코어를 되찾아 와.",
  ui_story_1022_10220402_50_dialog_content = "성공하면 이 안에 있는 걸 줄게.",
  ui_story_1022_10220402_51_dialog_content = "아니면 더 개선된 기술로 네 불완전한 인공 심장을 온전하게 만들어 줄 수도 있어.\n선택은 네 몫이야.",
  ui_story_1022_10220402_52_dialog_content = "날 멋대로 조종할 수 있을 거라 생각해?!",
  ui_story_1022_10220402_53_dialog_content = "방금 말했을 텐데, 페피타. 일을 감정적으로 대하지 마.",
  ui_story_1022_10220402_54_dialog_content = "네가 뭘 원하는지, 그걸 위해 어떤 대가를 치를 수 있는지 잘 생각해 봐.",
  ui_story_1022_10220402_55_dialog_content = "......",
  ui_story_1022_10220402_56_dialog_content = "<color=#e8d9bb>어둠의 밑바닥, 산호의 숲</color>",
  ui_story_1022_10220402_57_dialog_content = "<color=#e8d9bb>우르슬라는 자신의 친구를 접대하기 위해 목소리를 높이며\n암귀들의 연회석 준비를 지휘하고 있었다.</color>",
  ui_story_1022_10220402_58_dialog_content = "<color=#e8d9bb>정신을 차린 페피타는 자신이 회상에 잠겨 있었음을 자각했다.</color>",
  ui_story_1022_10220402_59_dialog_content = "<color=#e8d9bb>그리고 아름다운 산호 숲을 바라보며, 그녀는 자신이 왜 벨리사리아와의 거래를 저버리고\n이곳에 왔는지 떠올렸다.</color>",
  ui_story_1022_10220402_60_dialog_content = "우르슬라.",
  ui_story_1022_10220402_61_dialog_content = "멍청이! 적산호와 청산호를 한 접시에 담다니, 역시 천한 벌레다운 미적 감각이군요!",
  ui_story_1022_10220402_62_dialog_content = "그러니까 고귀한 혈통은 정말 중요한 거라구요...\n페피타, 방금 저 불렀나요?",
  ui_story_1022_10220402_63_dialog_content = "우리 처음 만났을 때, 같이 내 「심장」 얘기했던 거 기억나?",
  ui_story_1022_10220402_64_dialog_content = "놈들이 내 진짜 심장을 빼앗았다는 그...",
  ui_story_1022_10220402_65_dialog_content = "아, 귀찮네요! 저 오로리안들이 불량품을 줘서 당신이 툭하면\n「심장」이 뜯기는 고통을 견디고 있다는 얘기잖아요.",
  ui_story_1022_10220402_66_dialog_content = "당신에 대한 일은 전부 기억하고 있어요... 시시콜콜 일일이 말할 거 없다구요.",
  ui_story_1022_10220402_67_dialog_content = "그때 네가 「심장」을 만들 수 있다고 했었잖아?",
  ui_story_1022_10220402_68_dialog_content = "<color=#e8d9bb>페피타의 시선은 우르슬라의 가슴으로 향했다.\n그곳에는 산호 가지들이 일정한 리듬으로 물결치듯 움직이고 있었다.</color>",
  ui_story_1022_10220402_69_dialog_content = "<color=#e8d9bb>우르슬라의 심장은 산호로 이루어진 것이었다.</color>",
  ui_story_1022_10220402_70_dialog_content = "당연히 할 수 있죠! 전 가장 순수하고 가장 고귀한 힘이 있으니까요.",
  ui_story_1022_10220402_71_dialog_content = "당신한테 산호로 강한 심장을 만들어 주는 일 같은 건,\n고귀한 제겐 숨 쉬는 것만큼 쉬운 일이라구요.",
  ui_story_1022_10220402_72_dialog_content = "...언제 시작할 수 있어?",
  ui_story_1022_10220402_73_dialog_content = "드디어 결심이 선 건가요?",
  ui_story_1022_10220402_74_dialog_content = "...훗, 대신 그 전에 먼저 제 조건에 약속해 줘야 해요!",
  ui_story_1022_10220501_1_dialog_content = "냐앙! 필리시가 없는 동안 그렇게 많은 일이 있었던 거다냥?!",
  ui_story_1022_10220501_2_dialog_content = "뭐, 그래도 좋은 소식이 있다냥. 필리시가 귀중한 정보를 가져왔다냥~",
  ui_story_1022_10220501_3_dialog_content = "페피타에 대한 거야?!",
  ui_story_1022_10220501_4_dialog_content = "그렇다냥, 그 아가씨에 대해 우린 아는 게 너무 없었다냥.",
  ui_story_1022_10220501_5_dialog_content = "그래서 잉겔한테 연락했다냥. 그랬더니 잉겔이 특별히 위원회 자료를 알아봐 줬다냥.",
  ui_story_1022_10220501_6_dialog_content = "역시나 복잡한 내력이 있었군요.",
  ui_story_1022_10220501_7_dialog_content = "자료에 따르면 위원회는 전에도 어둠의 밑바닥에 탐색대를 보낸 적이 있었고...",
  ui_story_1022_10220501_8_dialog_content = "페피타의 아빠도 그 탐색 소대의 일원이었습니다냥.",
  ui_story_1022_10220501_9_dialog_content = "어? 어둠의 밑바닥 탐색대는 세습제야?",
  ui_story_1022_10220501_10_dialog_content = "아니요, 그렇지 않습니다. 그것보다는 페피타와의 교전 때를 떠올려 보세요.",
  ui_story_1022_10220501_11_dialog_content = "그자는 아무 장비 없이도 다크매터의 영향을 받지 않고 움직일 수 있었죠.",
  ui_story_1022_10220501_12_dialog_content = "만약 그게 일종의 유전적 체질이라면 전후 사정도 이해하기 쉬워질 겁니다.",
  ui_story_1022_10220501_13_dialog_content = "...일리가 있네요.\n그럼 페피타의 아버지도 어둠의 밑바닥에서 자유롭게 행동할 수 있는 체질이었을지도 모르죠.",
  ui_story_1022_10220501_14_dialog_content = "그럼 그 탐색대는 꽤 성과를 거뒀겠네요?",
  ui_story_1022_10220501_15_dialog_content = "그 탐색대는 거의 전멸이었다냥...",
  ui_story_1022_10220501_16_dialog_content = "전멸?!",
  ui_story_1022_10220501_17_dialog_content = "생환자는 페피타의 아빠 한 사람뿐이었다냥.",
  ui_story_1022_10220501_18_dialog_content = "그 사람이 살아서 돌아온 건 체질 덕도 있었지만,\n그다지 좋지 못한 수단을 썼기 때문이기도 하다냥...",
  ui_story_1022_10220501_19_dialog_content = "일루미나로 돌아오자마자 그 사람은 친권 양도 동의서에 서명하고,\n페피타를 일루미나의 연구소에 넘겨버렸다냥.",
  ui_story_1022_10220501_20_dialog_content = "자기 딸을 버렸단 말입니까?!",
  ui_story_1022_10220501_21_dialog_content = "그럼 실험체 신세가 되는 거잖아?",
  ui_story_1022_10220501_22_dialog_content = "그렇다냥... 그래서 잉겔도 페피타의 아빠가 뭔가 죄를 지어서,\n그걸 모면하려고 딸을 팔았을 거라 추측했다냥.",
  ui_story_1022_10220501_23_dialog_content = "...믿을 수가 없군요.",
  ui_story_1022_10220501_24_dialog_content = "일루미나에게 그런 겁쟁이가 있다니...",
  ui_story_1022_10220501_25_dialog_content = "그 뒤로 어둠의 밑바닥 탐색의 빈도가 큰 폭으로 떨어졌다냥.\n근데 페피타에 대한 연구는 계속 이어졌다냥.",
  ui_story_1022_10220501_26_dialog_content = "그리고 위원회는 페피타가 충분한 행동력과 전투력을 가질 수 있도록,\n선천적으로 결함이 있던 페피타의 심장을 인공 심장으로 대체했다냥.",
  ui_story_1022_10220501_27_dialog_content = "어? 인공 심장이라고?",
  ui_story_1022_10220501_28_dialog_content = "그렇다면 위원회는 어둠의 밑바닥 탐색 계획을 포기한 게 아니라,\n페피타를 차기 탐색대원으로 키우려 했던 것이군요.",
  ui_story_1022_10220501_29_dialog_content = "아마 그럴 겁니다냥~ 다만...",
  ui_story_1022_10220501_30_dialog_content = "인공 심장 기술은 아직 완전하지 않습니다냥.\n그러니까 페피타를 가지고 인체 실험을 하는 목적도 있었을 겁니다냥...",
  ui_story_1022_10220501_31_dialog_content = "어떻게 그런... 페피타도 너무 불쌍하네.",
  ui_story_1022_10220501_32_dialog_content = "그렇다냥. 나중에 페피타도 아빠가 위원회와 한 거래를 알고 엄청난 반발심을 갖게 됐다냥...",
  ui_story_1022_10220501_33_dialog_content = "그렇게 기회를 노려 일루미나에서 도망치고, 이곳저곳에서 지내다가\n지금은 진리의 결사에 가입하게 된 거다냥~",
  ui_story_1022_10220501_34_dialog_content = "왠지 알 것 같아... 거긴 페피타의 마지막 안식처였던 거였어...",
  ui_story_1022_10220501_35_dialog_content = "그리고 하나 더, 페피타는 도망친 뒤에 또 몰래 일루미나로 돌아갔었다냥.",
  ui_story_1022_10220501_36_dialog_content = "꽤 대담하군요. 무슨 목적이었습니까?",
  ui_story_1022_10220501_37_dialog_content = "아마 자기 원래 심장을 되찾으려고 했던 것 같습니다냥.",
  ui_story_1022_10220501_38_dialog_content = "물론 바로 들켜서 또 도망쳤지만 말입니다냥.",
  ui_story_1022_10220501_39_dialog_content = "일루미나한테도, 백야성한테도 쫓기다가 결국 일루미나로 잡혀 와서,\n또 어둠의 밑바닥으로 보내진 건가...",
  ui_story_1022_10220501_40_dialog_content = "뭐라고 해야 되나... 정말 파란만장한 경력이네.",
  ui_story_1022_10220501_41_dialog_content = "(어쩐지, 권위를 무시하고 뭐든지 반발하는 성격인 이유가 있었어...)",
  ui_story_1022_10220501_42_dialog_content = "게다가 이제는 팬텀과도 결탁하고 있습니다.",
  ui_story_1022_10220501_43_dialog_content = "필리시, 수고했습니다. 지금 즉시 대원수님께 보고하도록 하죠.",
  ui_story_1022_10220502_1_dialog_content = "...이런 상황입니다.\n페피타는 어둠의 밑바닥에서도 자유롭게 활동할 수 있고, 그 실력도 확실합니다.",
  ui_story_1022_10220502_2_dialog_content = "대원수님, 이제 어떻게 하면 좋겠습니까?",
  ui_story_1022_10220502_3_dialog_content = "다음에 또 페피타와 마주친다면, 정말 백야성이 연행하게 둬도 되는 겁니까?",
  ui_story_1022_10220502_4_dialog_content = "페피타는 백야성 보물 절도 사건의 단서를 가지고 있을 가능성이 높다.",
  ui_story_1022_10220502_5_dialog_content = "일루미나는 지금 백야성과 함께 연합 탐색 부대를 전개하고 있다.\n그러니 상대의 이익을 무시할 순 없겠지.",
  ui_story_1022_10220502_6_dialog_content = "하지만...",
  ui_story_1022_10220502_7_dialog_content = "물론 우리도 한없이 양보만 할 순 없을 것이다.",
  ui_story_1022_10220502_8_dialog_content = "페피타의 경력에 대한 잉겔의 보고를 들었다.\n페피타는 아마 어둠의 밑바닥 탐색에 재능이 있는 인재일 것이다.",
  ui_story_1022_10220502_9_dialog_content = "그래서 나는 즉시 이 정보를 백야성 성주와 공유했다.",
  ui_story_1022_10220502_10_dialog_content = "...! 성주의 반응은... 어땠습니까?",
  ui_story_1022_10220502_11_dialog_content = "조금이라도 식견이 있다면, 페피타를 어둠의 밑바닥에서 활동하게 하는 쪽이\n감옥에 가두는 것보다 더 유용하다는 것을 알 수 있을 것이다.",
  ui_story_1022_10220502_12_dialog_content = "솔라드는 암군이 아니다.",
  ui_story_1022_10220502_13_dialog_content = "만약 페피타가 우리에게 협력하고, 그 재능을 충분히 발휘한다면, 모든 이에게 이로울 것이다.",
  ui_story_1022_10220502_14_dialog_content = "당장의 상황뿐만 아니라, 장기적으로는 더 그렇겠지.",
  ui_story_1022_10220502_15_dialog_content = "그자를 통해 더 많은 정보를 확보하고, 앞으로 있을 암귀와의 전쟁에서 기선을 제압한다...\n그것이 그대의 주장인가?",
  ui_story_1022_10220502_16_dialog_content = "아무래도 같은 생각인 모양이네.",
  ui_story_1022_10220502_17_dialog_content = "흥... 일개 도적에 불과한 자가 아닌가.\n성전에 대한 단서만 실토한다면, 백야성도 더는 추궁하지 않도록 하지.",
  ui_story_1022_10220502_18_dialog_content = "과연... 역시 대원수님이십니다!",
  ui_story_1022_10220502_19_dialog_content = "그러니 너희도 안심하고 임무를 수행하면 된다.",
  ui_story_1022_10220502_20_dialog_content = "오히려 백야성보다 페피타 쪽이 더 상대하기 어렵지 않겠어? 하하하!",
  ui_story_1022_10220502_21_dialog_content = "그렇지 않습니다! 모두 대원수님께서 제때 담판을 지어주신 덕분입니다.\n아니었다면 백야성은 분명히 페피타를 감옥에 보냈을 것입니다.",
  ui_story_1022_10220502_22_dialog_content = "...그 백야성 이단심문조의 조장은 진리의 결사 일원에게 이상할 정도로 집착하고 있었습니다.",
  ui_story_1022_10220502_23_dialog_content = "예? 페피타를 벌하지 않겠다는 겁니까?!",
  ui_story_1022_10220502_24_dialog_content = "페피타가 진리의 결사 일원이라는 것은 성주님께서도 알고 계시지 않습니까?!",
  ui_story_1022_10220502_25_dialog_content = "성주님께선 모든 오로리안의 장기적 이익을 고려하셨어.",
  ui_story_1022_10220502_26_dialog_content = "게다가 우린 여전히 성전의 행방을 조사할 권한이 있어.",
  ui_story_1022_10220502_27_dialog_content = "그것뿐입니까... 결국 그자를 놓아줘야 한다는 겁니까...",
  ui_story_1022_10220502_28_dialog_content = "...당신이 진리의 결사를 얼마나 증오하고 있는지는 알고 있어.\n그래서 이단조사단에 들어가 지금까지 많은 활약을 해왔고 말이야.",
  ui_story_1022_10220502_29_dialog_content = "하지만 당신 원수가 정말 진리의 결사 사람인지는 그동안 줄곧 결론이 나지 않았어.",
  ui_story_1022_10220502_30_dialog_content = "이대로 놓아줘야 한다니... 안 됩니다... 말도 안 된다고요...",
  ui_story_1022_10220502_31_dialog_content = "냉정하게 현실을 직시해!",
  ui_story_1022_10220502_32_dialog_content = "지금 우린 어둠의 밑바닥에 있어.\n감정에 지배당하면 당신만이 아니라 동료의 목숨까지 저버리게 돼!",
  ui_story_1022_10220502_33_dialog_content = "...죄송합니다, 전하. 추태를 보였습니다...",
  ui_story_1022_10220502_34_dialog_content = "가서 머리를 좀... 식히고 오겠습니다.",
  ui_story_1022_10220502_35_dialog_content = "......",
  ui_story_1022_10220601_1_dialog_content = "안 돼... 이대로 놓칠 순 없어... 나 혼자서라도... 대가를 치르게 해 주겠어...",
  ui_story_1022_10220601_2_dialog_content = "진리의 결사는... 전부 죽어야 해!",
  ui_story_1022_10220601_3_dialog_content = "역시나 어리석은 짓을 할 생각이었네.",
  ui_story_1022_10220601_4_dialog_content = "전하...!",
  ui_story_1022_10220601_5_dialog_content = "손에 든 건 뭐지?",
  ui_story_1022_10220601_6_dialog_content = "이건... 「백야의 지침」입니다.\n백야성 신전에서 보관하던 것인데, 축복을 받은 물건과 공명할 수 있습니다.",
  ui_story_1022_10220601_7_dialog_content = "어둠의 밑바닥에 들어온 뒤부터 줄곧 격렬한 반응을 보였습니다...",
  ui_story_1022_10220601_8_dialog_content = "어쩌면 이 근처에 백야성의 잃어버린 보물이 있을지도 모릅니다.",
  ui_story_1022_10220601_9_dialog_content = "지침은 어딜 가리키고 있지? 설마 공교롭게도 우르슬라가 사라졌던 방향은 아니겠지?",
  ui_story_1022_10220601_10_dialog_content = "그건...",
  ui_story_1022_10220601_11_dialog_content = "당신 혼자 그 팬텀과 페피타를 쫓고, 잃어버린 백야성의 보물도 되찾으시겠다?",
  ui_story_1022_10220601_12_dialog_content = "그건 정말 극도로 오만하고, 동료들을 얕보는 처사야!",
  ui_story_1022_10220601_13_dialog_content = "당신 혼자 모든 걸 해낼 수 있었으면, 연합 탐색 부대가 존재할 이유가 있나?!",
  ui_story_1022_10220601_14_dialog_content = "사실... 말할지 말지 고민했는데, 내가 감응했던 거대한 루미나도 같은 방향에 있어.",
  ui_story_1022_10220601_15_dialog_content = "?!",
  ui_story_1022_10220601_16_dialog_content = "팬텀은 우리 모두의 적입니다. 그 외엔 딱히 할 말이 없군요.",
  ui_story_1022_10220601_17_dialog_content = "...흥.",
  ui_story_1022_10220601_18_dialog_content = "조장님, 저도 페피타를 만나러 가고 싶어요... 벌을 주기 위해서가 아니라 돕기 위해서요.",
  ui_story_1022_10220601_19_dialog_content = "미지의 힘으로부터 우리의 세계와... 친구를 구하는 것이야말로 이단 조사의 목적이라고...\n전 그렇게 생각해요.",
  ui_story_1022_10220601_20_dialog_content = "에리카... 넌 내가 생각한 것보다 더 성숙하고 지혜롭구나. 반면에 난...",
  ui_story_1022_10220601_21_dialog_content = "...죄송합니다, 전하.\n그리고... 이 자리의 다른 일행에게도 사과할게. 사적인 증오 때문에 이성을 잃고 말았어.",
  ui_story_1022_10220601_22_dialog_content = "...하지만... 진리의 결사에 대해 생각만 하면 난...!",
  ui_story_1022_10220601_23_dialog_content = "아무도 그 원한을 버리라고 말하진 않았어요.\n그게 절대 쉬운 일이 아니란 건 누구나 알고 있고요.",
  ui_story_1022_10220601_24_dialog_content = "다만 적어도 자기 목숨은 소중하게 여겨야죠...\n그래서 우리가 함께 부대를 만들어 서로를 돕고 있는 거잖아요.",
  ui_story_1022_10220601_25_dialog_content = "......",
  ui_story_1022_10220601_26_dialog_content = "다 같이 가요. 우르슬라의 소굴로!",
  ui_story_1022_10220601_27_dialog_content = "<color=#e8d9bb>일행은 「백야의 지침」이 가리키는 방향으로 나아갔다.\n그리고 얼마 후, 아름다우면서도 일그러진 식물이 가득한 땅에 도달했다.</color>",
  ui_story_1022_10220601_28_dialog_content = "우와... 여긴...",
  ui_story_1022_10220601_29_dialog_content = "예쁘지만 기괴하고, 영혼을 빼앗을 것처럼... 불길한 곳이네...",
  ui_story_1022_10220601_30_dialog_content = "아무래도 방향은 맞았던 모양이군요.\n탐색대원 말로는 페피타가 그들을 데리고 발견했던 것도 산호 숲이었다고 합니다.",
  ui_story_1022_10220601_31_dialog_content = "이 기괴한 환경도 어쩌면 우르슬라의 영향일지도 모릅니다.",
  ui_story_1022_10220601_32_dialog_content = "...「<color=#FFB400>미지의 구역 44호</color>」로 등록하도록 하죠.",
  ui_story_1022_10220601_33_dialog_content = "PlayerName, 날 따라 와. 물어보고 싶은 게 있어.",
  ui_story_1022_10220601_34_dialog_content = "무슨 일이야? 카렌.",
  ui_story_1022_10220601_35_dialog_content = "거대한 루미나를 감응했다고 했었지?",
  ui_story_1022_10220601_36_dialog_content = "그 루미나, 백야성이 잃어버린 보물 중 하나일 가능성이 있을까?",
  ui_story_1022_10220601_37_dialog_content = "뭐?! 「백야의 지침」이 가리키는 거 말이야?",
  ui_story_1022_10220601_38_dialog_content = "음... 가능성은 완전히 부정할 순 없겠지만, 그래도 왠지 아닐 것 같아...",
  ui_story_1022_10220601_39_dialog_content = "그냥 직감일 뿐이고 뭐라 설명하긴 힘들지만...\n그 루미나, 왠지 따뜻하면서 친근한 느낌이 들었거든...",
  ui_story_1022_10220601_40_dialog_content = "...알겠어, 신경 쓰지 마. 그냥 한번 물어본 것뿐이니까. 자, 돌아가자.",
  ui_story_1022_10220601_41_dialog_content = "카렌... 괜찮아? 걱정이 많아 보여.",
  ui_story_1022_10220601_42_dialog_content = "넌 백야성을 대표해서 왔으니까, 분명히 여러 가지로 힘들겠지...",
  ui_story_1022_10220601_43_dialog_content = "...어쩌면 조금 초조해하고 있는 걸지도 모르겠네.\n최근에 여러 일을 겪으면서, 난 뭔가 이뤄야 한다는 조급함이 생겼거든.",
  ui_story_1022_10220601_44_dialog_content = "사로잡힌 짐승처럼 능력을 발휘할 수 없는 건 싫어.",
  ui_story_1022_10220601_45_dialog_content = "뭐, 하지만 네 말이 맞아. 조바심을 내선 안 돼.",
  ui_story_1022_10220601_46_option_content = "나 아직 말 안 했는데...",
  ui_story_1022_10220601_47_dialog_content = "어쨌든 말할 생각이었잖아?!",
  ui_story_1022_10220601_48_dialog_content = "크흠! 그, 그건 그래.",
  ui_story_1022_10220601_49_option_content = "되고 안 되는 게 어딨어.",
  ui_story_1022_10220601_50_dialog_content = "네 기분은 나도 이해해. 왜냐면... 나도 똑같은 기분이니까.",
  ui_story_1022_10220601_51_dialog_content = "...고마워. 어떤 위로의 말보다 도움이 됐어.",
  ui_story_1022_10220601_52_dialog_content = "음? 저쪽에서 뭔가 떠들고 있는데? 어서 가 보자.",
  ui_story_1022_10220601_53_dialog_content = "불길한 기운이 점점 짙어지고 있어... 사악한 신이 한때 이곳에 강림했어...",
  ui_story_1022_10220601_54_dialog_content = "시체?! 이건... 오로리안인가?",
  ui_story_1022_10220601_55_dialog_content = "근데 왠지 오로리안의 얼굴 같진 않아... 그렇다고 암귀도 아니고, 대체 뭐지?",
  ui_story_1022_10220601_56_dialog_content = "...오로리안에 가까운 어떤 생물이겠지. 육체에 루미나의 흔적이 남아 있어.",
  ui_story_1022_10220601_57_dialog_content = "다만 루미나는 거의 다 뽑혀버렸어.",
  ui_story_1022_10220601_58_dialog_content = "누가 이런 잔인한 짓을 한 거죠?! 그런 방식으로 저들을 죽였단 말인가요...?",
  ui_story_1022_10220601_59_dialog_content = "처음엔 나도 그렇게 생각했어. 하지만 조사해 본 결과 그건 아니었어.",
  ui_story_1022_10220601_60_dialog_content = "이들은 루미나가 뽑혀서 죽은 게 아니라, 이미 장기간 루미나가 고갈된 상태로 살고 있었어.",
  ui_story_1022_10220601_61_dialog_content = "어떻게 그게 가능하죠...? 오로리안이 그렇게도 생존할 수 있나요?",
  ui_story_1022_10220601_62_dialog_content = "죽은 오로리안, 뽑힌 루미나, 잃어버린 백야성의 보물...",
  ui_story_1022_10220601_63_dialog_content = "...빌어먹을! 더러운 암귀 놈들, 대체 어디까지 오로리안을 짓밟을 작정인 거지?!",
  ui_story_1022_10220601_64_dialog_content = "당신들 오로리안이 「이클립스」의 물건을 빼앗았을 가능성은 없을까요?",
  ui_story_1022_10220601_65_dialog_content = "당신들이 편안하게 살고 있는 땅조차도 어쩌면...",
  ui_story_1022_10220601_66_dialog_content = "!!!",
  ui_story_1022_10220601_67_dialog_content = "왜 그래? PlayerName.",
  ui_story_1022_10220601_68_dialog_content = "...아무것도 아냐.",
  ui_story_1022_10220601_69_dialog_content = "(방금 희미하게 들린 목소리... 내 착각인가...?)",
  ui_story_1022_10220701_1_dialog_content = "많은 시신이 같은 시간대에 사망한 것으로 보입니다.",
  ui_story_1022_10220701_2_dialog_content = "게다가 산호 숲 곳곳에 이상한 금속 파편이 떨어져 있습니다...\n대체 여기서 무슨 일이 있었던 걸까요?",
  ui_story_1022_10220701_3_dialog_content = "어쩌면... 제가 답을 찾을 수 있을 것 같아요.",
  ui_story_1022_10220701_4_dialog_content = "...아무래도 당신에게 의지할 수밖에 없을 것 같네요.",
  ui_story_1022_10220701_5_dialog_content = "대신 조심하세요, PlayerName. 절대 무리하면 안 됩니다.",
  ui_story_1022_10220701_6_option_content = "[감응한다]",
  ui_story_1022_10220701_7_dialog_content = "?! 이...이건...",
  ui_story_1022_10220701_8_dialog_content = "<color=#e8d9bb>귓가에는 윙윙거리는 기계음이 울려 퍼졌다.</color>",
  ui_story_1022_10220701_9_dialog_content = "<color=#e8d9bb>대지도 기계의 진동으로 희미하게 흔들리고 있었다.</color>",
  ui_story_1022_10220701_10_dialog_content = "<color=#e8d9bb>무수히 많은 기묘한 기계들이 하늘을 향해 솟아 있었고,\n그 사이에는 일그러진 아름다운 산호와 식물들이 자라고 있었다.</color>",
  ui_story_1022_10220701_11_dialog_content = "<color=#e8d9bb>그것은 산호의 빙원보다 더 소름 끼치는 광경이었다.</color>",
  ui_story_1022_10220701_12_dialog_content = "(히이로 씨가 발견한 금속 파편은 이 무수한 기계들의 잔해인 것 같아.)",
  ui_story_1022_10220701_13_dialog_content = "(여긴... 산호 숲의 <color=#FFB400>과거</color>인가?)",
  ui_story_1022_10220701_14_dialog_content = "(앗! 기계를 관리하고 있는 건... 오로리안을 닮은 그 생물들이야.\n계속 여기서 살고 있었던 건가?)",
  ui_story_1022_10220701_15_dialog_content = "<color=#e8d9bb>생물의 존재를 의식했을 때, 당신은 이 장소가 무척이나 고요하다는 것을 깨달았다.</color>",
  ui_story_1022_10220701_16_dialog_content = "<color=#e8d9bb>기계의 윙윙거리는 가동음만 제외하면 거의 아무 소리도 존재하지 않았다.</color>",
  ui_story_1022_10220701_17_dialog_content = "(저 생물들은 서로 어떤 교류도 없어. 표정이나 움직임도 딱딱해.\n그저 정해진 대로 일만 하고 있어.)",
  ui_story_1022_10220701_18_dialog_content = "(그 점은 왠지 하급 암귀 같은 느낌이지만... 겉모습은 분명 오로리안이잖아.)",
  ui_story_1022_10220701_19_dialog_content = "아아... 이렇게 오랜 시간이 지났는데, 말을 할 수 있는 사람은 여전히 우리 몇 명뿐인가.",
  ui_story_1022_10220701_20_dialog_content = "(으아악! 깜짝 놀랐잖아... 말을 할 수 있는 개체도 있었구나.)",
  ui_story_1022_10220701_21_dialog_content = "내가 태어날 때부터 여긴 이랬다.\n있는 거라곤 기계, 그리고 아무 사고나 감정도 없고, 말도 하지 않는 동족들뿐...",
  ui_story_1022_10220701_22_dialog_content = "이러다간 곧 어떤 게 동족이고, 어떤 게 기계인지도 구분이 어려울 지경이다.",
  ui_story_1022_10220701_23_dialog_content = "신이시여, 왜 우리가 이런 생활을 계속해야 한단 말입니까?",
  ui_story_1022_10220701_24_dialog_content = "이 생기 없는 갑갑한 곳을 떠나 바깥으로 갈 순 없는 건가?",
  ui_story_1022_10220701_25_dialog_content = "절대 안 돼!",
  ui_story_1022_10220701_26_dialog_content = "내가 젊었을 때도 그런 말을 했던 동족들이 밖으로 도망쳤었지...",
  ui_story_1022_10220701_27_dialog_content = "그리고?! 그 뒤엔 어떻게 됐지?",
  ui_story_1022_10220701_28_dialog_content = "죽었다...",
  ui_story_1022_10220701_29_dialog_content = "?!",
  ui_story_1022_10220701_30_dialog_content = "바깥 세계엔 용광로처럼 뜨거운 장소가 있었고,\n도망친 동족들은 순식간에 타버려 재가 되고 말았다.",
  ui_story_1022_10220701_31_dialog_content = "그 후 다시는 누구도 이곳을 감히 떠나려 하지 못했다.\n우연히 밖에 나간 자들도 누구 하나 돌아오지 않았다.",
  ui_story_1022_10220701_32_dialog_content = "어째서... 설마 우리에겐 이제 그 어떤 희망조차 없다는 건가? 이대로 갇혀서 죽어야만 한다고?",
  ui_story_1022_10220701_33_dialog_content = "그건 너무 잔혹하잖아...",
  ui_story_1022_10220701_34_dialog_content = "?!",
  ui_story_1022_10220701_35_dialog_content = "(으앗! 갑자기 다들 날 쳐다보잖아?!)",
  ui_story_1022_10220701_36_dialog_content = "아, 하하... 안녕하세요...?",
  ui_story_1022_10220701_37_dialog_content = "외지인인가? 정말 부럽군, 바깥으로 나갈 수 있다니.",
  ui_story_1022_10220701_38_dialog_content = "이따위 곳엔 왜 온 거지? 여긴 기계와 산호 외엔 아무것도 없다.",
  ui_story_1022_10220701_39_dialog_content = "참, 산호는 절대 먹지 마라. 먹으면 네 피가 역겨운 흰색으로 변할 테니까.",
  ui_story_1022_10220701_40_dialog_content = "우리처럼 말이야.",
  ui_story_1022_10220701_41_dialog_content = "<color=#e8d9bb>오로리안을 닮은 생물의 얼굴에 자학적인 미소가 떠올랐다.</color>",
  ui_story_1022_10220701_42_dialog_content = "산호를 먹으면... 피가 흰색이 된다고요...? 아, 알겠어요. 알려줘서 고마워요.",
  ui_story_1022_10220701_43_dialog_content = "그럼 여기 산호 말고 다른 음식은 없나요?",
  ui_story_1022_10220701_44_dialog_content = "없다. 여기도 산호, 저기도 산호, 산호... 빌어먹을 산호뿐이라고...!",
  ui_story_1022_10220701_45_dialog_content = "이곳은 마치 저주가 걸린 것처럼, 매일 수없이 많은 이끼와 산호가 자라고 있지.",
  ui_story_1022_10220701_46_dialog_content = "그걸 제때 정리하지 않으면 기계가 제대로 가동하질 않는다.",
  ui_story_1022_10220701_47_dialog_content = "특히 저 「용광로」는 절대 멈춰선 안 된다.",
  ui_story_1022_10220701_48_dialog_content = "평생 저 용광로와 잡초에 붙들려 살아가야만 하고, 존엄이라고는 찾아볼 수도 없지...\n우린 분명히 저주받은 거다.",
  ui_story_1022_10220701_49_dialog_content = "...저 말고 여기 누가 또 온 적 있나요? 암귀...라든지 말이에요.",
  ui_story_1022_10220701_50_dialog_content = "한 팬텀이 가끔 오곤 했었지, 그렇지 않나?",
  ui_story_1022_10220701_51_dialog_content = "그래, 「우두」라는 팬텀이었지.",
  ui_story_1022_10220701_52_dialog_content = "팬텀?!",
  ui_story_1022_10220701_53_dialog_content = "놈은... 우릴 죽일 거다.",
  ui_story_1022_10220701_54_dialog_content = "놈은 우릴 죽일 거다.",
  ui_story_1022_10220701_55_dialog_content = "놈은 우릴 죽일 거다!",
  ui_story_1022_10220701_56_dialog_content = "?!",
  ui_story_1022_10220701_57_dialog_content = "어느 날 우두는 우리가 더는 가치가 없다고 여겨 우리 모두를 죽였다.",
  ui_story_1022_10220701_58_dialog_content = "우린 이미 진작에 죽었고, 평생 이곳에 사로잡혀 있다...",
  ui_story_1022_10220701_59_dialog_content = "평생 이곳에 사로잡혀 있다.",
  ui_story_1022_10220701_60_dialog_content = "평생 이곳에 사로잡혀 있다!",
  ui_story_1022_10220701_61_dialog_content = "...!!!",
  ui_story_1022_10220701_62_dialog_content = "PlayerName! 왜 그러죠? 안색이 창백합니다.",
  ui_story_1022_10220701_63_dialog_content = "시신에 남아 있던... 생전의 생각을 감응했어요.",
  ui_story_1022_10220701_64_dialog_content = "......",
  ui_story_1022_10220701_65_dialog_content = "영혼이 아직까지 여기 잡혀 있었다는 거야...? 부디 그들이 안식을 얻기를.",
  ui_story_1022_10220701_66_dialog_content = "그 「우두」라는 팬텀이 저들을 전부 죽였단 말이야?! 그런 끔찍한 짓을 벌이다니...!",
  ui_story_1022_10220701_67_dialog_content = "그렇게 보면 우르슬라 쪽은 상대적으로 공격성이 낮은 것 같네요.",
  ui_story_1022_10220701_68_dialog_content = "그런 생각은 위험합니다. 팬텀의 본성은 모두 같습니다. 쉽게 경계심을 풀어서는 안 됩니다.",
  ui_story_1022_10220701_69_dialog_content = "아... 죄송해요!",
  ui_story_1022_10220701_70_dialog_content = "화를 낸 건 아닙니다. 그저 경계를 게을리해선 안 된다는 점을 상기시켜 주고 싶었을 뿐입니다.",
  ui_story_1022_10220701_71_dialog_content = "당신이 감응한 내용으로 판단해 본다면, 이 장소는 모종의 과학 기지였던 것으로 보입니다.",
  ui_story_1022_10220701_72_dialog_content = "오로리안을 닮은 정체불명의 생물이 이곳에서 일하고 있었고,\n감독자는 그 우두라는 팬텀이었겠죠.",
  ui_story_1022_10220701_73_dialog_content = "네... 저도 같은 생각이에요.",
  ui_story_1022_10220701_74_dialog_content = "저들은 대부분 감정도, 사고도 없고, 말도 못 했지만, 극소수의 예외도 있었어요.",
  ui_story_1022_10220701_75_dialog_content = "주로 하는 건 산호나 이끼를 제거해서 기계의 가동을 유지하는 일이었고요.",
  ui_story_1022_10220701_76_dialog_content = "그 기계들 중에 제일 중요한 건 「용광로」라고 했던 것 같아요.",
  ui_story_1022_10220701_77_dialog_content = "왜 산호와 이끼가 계속 자라고 있었을까? 우르슬라와 뭔가 관계가 있는 건가?",
  ui_story_1022_10220701_78_dialog_content = "그럴 가능성도 있겠죠. 어쩌면 우르슬라가 있는 곳엔 반드시 산호가 자랄지도 모릅니다.",
  ui_story_1022_10220701_79_dialog_content = "그럼 우르슬라는 예전부터 과학 기지 주변에 있었다는 얘기가 되잖아요?\n그 우두랑도 뭔가 관계가 있을 수도 있겠네요.",
  ui_story_1022_10220701_80_dialog_content = "그렇게 생각하면 역시 우르슬라도 위험한 존재네요...",
  ui_story_1022_10220701_81_dialog_content = "하지만 우르슬라는 페피타랑 친구가 됐어. 그럼 페피타한테 손을 대는 일은 없을 거야...",
  ui_story_1022_10220701_82_dialog_content = "...게다가 행운인지 불행인지, 페피타는 어둠의 밑바닥에 들어가자마자 산호의 숲을 발견했어.",
  ui_story_1022_10220701_83_dialog_content = "저도 한마디 해도 되겠습니까.",
  ui_story_1022_10220701_84_dialog_content = "뭐지?",
  ui_story_1022_10220701_85_dialog_content = "이곳은 어둠의 밑바닥이라고는 생각되지 않을 정도로 다크매터가 매우 희박합니다.",
  ui_story_1022_10220701_86_dialog_content = "어쩌면 「백야의 지침」이 가리키는 보물이 다크매터를 차단할 수 있을지도 모릅니다.\n저희의 <color=#FFB400>루미나 스톤</color>처럼 말입니다.",
  ui_story_1022_10220701_87_dialog_content = "...! 정말 그런 거라면 추측만 하기보다는 서둘러 확인하는 게 좋겠어.",
  ui_story_1022_10220701_88_dialog_content = "우르슬라는 멀지 않은 곳에 있을 겁니다. 경계를 늦추지 않도록 합시다.",
  ui_story_1022_10220800_1_dialog_content = "<color=#e8d9bb>산호의 숲 깊은 곳, 페피타는 일그러진 풍경을 바라보며 생각에 잠겨 있었다.</color>",
  ui_story_1022_10220800_2_dialog_content = "페피타, 「조건」은 좀 생각해 봤나요?",
  ui_story_1022_10220800_3_dialog_content = "...왔구나. 바깥은 어땠어?",
  ui_story_1022_10220800_4_dialog_content = "별것 없었어요. 벌레 몇 마리뿐이었죠.\n이 고귀한 우르슬라 님은 그런 데 신경 쓸 생각은 없어요.",
  ui_story_1022_10220800_5_dialog_content = "그것보다는 당신 대답이나 얼른 해 달란 말이에요.",
  ui_story_1022_10220800_6_dialog_content = "조건만 동의한다면 지금 바로 산호로 심장을 만들어 줄 수 있어요.",
  ui_story_1022_10220800_7_dialog_content = "...「영원히 네 곁에서 같이 놀아주기」, 그게 조건이지?",
  ui_story_1022_10220800_8_dialog_content = "「놀아주기」가 아니라 「같이 놀기」라구요!\n당신도 나랑 같이 놀고 싶잖아요. 같이 놀면 즐겁고 말이에요!",
  ui_story_1022_10220800_9_dialog_content = "응, 진짜 즐거워. 나랑 취향이 맞는 경우는 진짜 드물었거든.",
  ui_story_1022_10220800_10_dialog_content = "그렇죠? 그러니까 약속해 주세요. 바로 심장을 만들어 줄 테니까요.",
  ui_story_1022_10220800_11_dialog_content = "그럼 당신 피도 고귀한 흰색으로 변해서, 다시는 절 미치게 만들 일도 없고,\n영원히 제 곁에 남을 수 있을 거예요.",
  ui_story_1022_10220800_12_dialog_content = "...우르슬라.",
  ui_story_1022_10220800_13_dialog_content = "약속할 건가요?!",
  ui_story_1022_10220800_14_dialog_content = "우리 처음 만났을 때 기억나?",
  ui_story_1022_10220800_15_dialog_content = "...왜 갑자기 그 꺼림칙한 지난 일을 끄집어내는 거죠?",
  ui_story_1022_10220800_16_dialog_content = "......",
  ui_story_1022_10220800_17_dialog_content = "(나... 어떻게 된 거야? 여긴...?)",
  ui_story_1022_10220800_18_dialog_content = "캬아악!",
  ui_story_1022_10220800_19_dialog_content = "하, 하하... 아하하하! 고작 그 정도야? 덤벼!",
  ui_story_1022_10220800_20_dialog_content = "그어어어──!",
  ui_story_1022_10220800_21_dialog_content = "(으윽! 「심장」이 또 아프기 시작했어... 이런... 젠장!)",
  ui_story_1022_10220800_22_dialog_content = "(심장만 멀쩡했어도... 분명히... 이런 일은...)",
  ui_story_1022_10220800_23_dialog_content = "(...아, 생각났어. 난 결사 사람들이랑 어둠의 밑바닥을 탐색하러 왔었지.\n그러다 노는 데 정신이 팔려서 암귀 무리랑 마주쳤고.)",
  ui_story_1022_10220800_24_dialog_content = "(전력으로 맞섰지만, 「심장」의 힘이 부족해서 결국 붙잡혔어...)",
  ui_story_1022_10220800_25_dialog_content = "(역시 나라니까, 죽을 때도 정말 터무니없게 죽네. 아하하, 하...)",
  ui_story_1022_10220800_26_dialog_content = "...아하하하하!",
  ui_story_1022_10220800_27_dialog_content = "정말, 간만에 오로리안이 나타나서 아주 아주 아주 오랜만에 깨어났는데...",
  ui_story_1022_10220800_28_dialog_content = "비몽사몽으로 겨우 와 봤더니 미친 애였잖아요.",
  ui_story_1022_10220800_29_dialog_content = "누구야?!",
  ui_story_1022_10220800_30_dialog_content = "뭐, 미치면 어때요, 당신 피와 심장은...",
  ui_story_1022_10220800_31_dialog_content = "<color=#FFB400>이제 제 거니까요~</color>",
  ui_story_1022_10220800_32_dialog_content = "<color=#e8d9bb>어린 소녀의 모습을 한 암귀가 미소를 짓자, 날카로운 송곳니가 모습을 드러냈다.</color>",
  ui_story_1022_10220800_33_dialog_content = "<color=#e8d9bb>그 천진난만하면서도 잔혹한 미소는 보는 이가 오한을 느끼게 만들었다.</color>",
  ui_story_1022_10220800_34_dialog_content = "아하하...",
  ui_story_1022_10220800_35_dialog_content = "또 웃어요?! 뭘 웃는 거죠? 뭐가 웃긴데요? 당신은 이제 곧 끝장이에요.\n이 우르슬라 님한테 깔끔하게 먹힐 거라구요. 알겠어요?",
  ui_story_1022_10220800_36_dialog_content = "너 같은 송곳니가 난 괴물이 나한테 미쳤다고 하는데, 그게 안 웃기겠어?",
  ui_story_1022_10220800_37_dialog_content = "흥, 이 송곳니는 고귀한 혈족의 상징이에요. 당신이 뭘 안다고 그래요?",
  ui_story_1022_10220800_38_dialog_content = "혈족? 이름만 멋있으면 뭐 해? 그래봤자 사람 피 빨아먹는 녀석이잖아?",
  ui_story_1022_10220800_39_dialog_content = "지금 감히 절 깔본 건가요?!\n그 피를 한 방울도 안 남기고 껍질만 남게 해 줄 테니 각오하세요!",
  ui_story_1022_10220800_40_dialog_content = "아하하하! 진짜 별일이네.",
  ui_story_1022_10220800_41_dialog_content = "이 페피타 님은 누구한테나 사랑받고, 어딜 가든지 실컷 먹고 마시면서 친구가 끊이질 않았어.",
  ui_story_1022_10220800_42_dialog_content = "근데 내 피를 마시겠다는 사람은 처음이네? 설마 그거 삐뚤어진 애정표현인 거야?",
  ui_story_1022_10220800_43_dialog_content = "헛소리! 제가 당신을 사랑할 리가 없잖아요! 제가 사랑하는 건 제 할아버지 한 분뿐이에요!",
  ui_story_1022_10220800_44_dialog_content = "당신 피를 마시는 건 당신을 노예로 만들어서 평생 부려 먹기 위해서라구요.\n다시는 그런 눈으로 절 못 보게 해 주겠어요!",
  ui_story_1022_10220800_45_dialog_content = "부려 먹어...?",
  ui_story_1022_10220800_46_dialog_content = "흥, 이제야 무서운가요? 마음껏 두려워하고, 용서를 구걸하는 표정을 지어 보세요.",
  ui_story_1022_10220800_47_dialog_content = "음... 싫어.",
  ui_story_1022_10220800_48_dialog_content = "뭐죠?! 언제 그걸 손에... 당장 내려놔요!",
  ui_story_1022_10220800_49_dialog_content = "날 죽이는 건 괜찮지만, 부려 먹는 건 안 돼.",
  ui_story_1022_10220800_50_dialog_content = "<color=#FFB400>자유가 아니면 죽음을!</color>",
  ui_story_1022_10220800_51_dialog_content = "<color=#e8d9bb>페피타는 산호 가지 한 개를 쥐고 가슴을 찔렀고, 선홍빛 피가 뿜어져 나왔다.</color>",
  ui_story_1022_10220800_52_dialog_content = "......!",
  ui_story_1022_10220800_53_dialog_content = "으아... 피... 빨간... 피가... 으아아아아아아아──!",
  ui_story_1022_10220800_54_dialog_content = "키이익!",
  ui_story_1022_10220800_55_dialog_content = "살려줘!",
  ui_story_1022_10220800_56_dialog_content = "가, 가주님 제발 용서해 주세요... 제발 살려주세요! 으아아악!",
  ui_story_1022_10220800_57_dialog_content = "피... 끔찍한 피...! 당신들! 죽일 땐 피가 안 나오게 죽이세요!",
  ui_story_1022_10220800_58_dialog_content = "『예!』",
  ui_story_1022_10220800_59_dialog_content = "으아아아악!",
  ui_story_1022_10220800_60_dialog_content = "으앗! 피 안 나게 하라고 했잖아요!\n당신들은 제 「새로운 친구」죠? 그러니까 제 말을 들어야 해요!",
  ui_story_1022_10220800_61_dialog_content = "『예, 우르슬라 님! 최대한 노력하겠습니다...』",
  ui_story_1022_10220800_62_dialog_content = "대답만 잘하지 쓸모없는 녀석들이네요...",
  ui_story_1022_10220800_63_dialog_content = "하지만 참아야만 해요...\n제 「새로운 신」은 「진리의 주인」 같은 것보다 더 위대하신 분이니까요...",
  ui_story_1022_10220800_64_dialog_content = "자! 강림해서 정화시켜 주세요! 저의 신이시여!",
  ui_story_1022_10220800_65_dialog_content = "으으... 너무 오래 자서 잊고 있었네요...",
  ui_story_1022_10220800_66_dialog_content = "전 이미 「이클립스」의 고리를 받았으니까, 이제 피 같은 건 필요가 없었죠.\n보고 싶지도 않아요!",
  ui_story_1022_10220800_67_dialog_content = "피의 젖을 마시고, 피의 물에 몸을 담그던 즐거운 어린 시절은 이미 끝났다구요...\n으아아아앙! 할아버지... 할아버지!",
  ui_story_1022_10220800_68_dialog_content = "(갑자기 히스테리를 부리더니 울어버렸어... 「할아버지」를 부르는 모습이 왠지 불쌍하네.)",
  ui_story_1022_10220800_69_dialog_content = "(그 할아버지가 얘를 두고 가 버린 건가? 아마 내 아버지라는 인간과 마찬가지로 쓰레기였겠지.)",
  ui_story_1022_10220800_70_dialog_content = "야, 너 괜찮아? 크, 크으... 맞다, 괜찮은지 물어볼 건 내 쪽이었네. 아하하...",
  ui_story_1022_10220800_71_dialog_content = "전 당연히 괜찮죠. 고귀한 제가 괜찮지 않을 리가 없잖아요?",
  ui_story_1022_10220800_72_dialog_content = "으악! 너 또 뭘 할 생각인 건데...?",
  ui_story_1022_10220800_73_dialog_content = "피로 절 제압할 생각은 마세요. 피 같은 건... 아, 아무렇지도 않으니까요.\n마실 수도 있다구요!",
  ui_story_1022_10220800_74_dialog_content = "우와, 미친! 갑자기 내 상처를 핥는다고? 너 좀 변태 아냐...?",
  ui_story_1022_10220800_75_dialog_content = "으으, 괴로워...",
  ui_story_1022_10220800_76_dialog_content = "<color=#e8d9bb>우르슬라의 눈에 유백색의 눈물이 맺혔다.</color>",
  ui_story_1022_10220800_77_dialog_content = "괴로우면 가까이 안 오면 되잖아...",
  ui_story_1022_10220800_78_dialog_content = "으, 으으── 으아아아아!",
  ui_story_1022_10220800_79_dialog_content = "<color=#e8d9bb>갑자기 마치 모종의 원초적 힘의 영향을 받은 듯 우르슬라는 경련을 일으키고 비명을 질렀다.\n그녀의 눈에서는 유백색의 눈물이 쏟아져 나왔다.</color>",
  ui_story_1022_10220800_80_dialog_content = "이, 이거 상태 엄청 안 좋은 거 아냐?!",
  ui_story_1022_10220800_81_dialog_content = "으아아악!",
  ui_story_1022_10220800_82_dialog_content = "(우와, 제어가 안 되는 건가?! 이참에 얼른 도망쳐야...\n아... 젠장... 피를 너무 흘렸어!)",
  ui_story_1022_10220800_83_dialog_content = "페...디... 페디, 커지세요...!",
  ui_story_1022_10220800_84_dialog_content = "봉제인형...? 으앗...!",
  ui_story_1022_10220800_85_dialog_content = "<color=#e8d9bb>우르슬라는 경련하는 몸을 억지로 움직여 먼지투성이 인형 하나를 소환했고,\n다짜고짜 페피타를 끌고 움직였다.</color>",
  ui_story_1022_10220800_86_dialog_content = "<color=#e8d9bb>굉음과 함께 유백색의 눈물이 땅에 떨어져 폭발했고,\n페피타가 있던 자리는 순식간에 연기와 먼지로 휩싸였다.</color>",
  ui_story_1022_10220800_87_dialog_content = "(뭐야... 날 구해준 거야...?)",
  ui_story_1022_10220800_88_dialog_content = "(그럼 자기는...? 설마 폭발에 휘말렸나? 이런, 눈이 안 떠져...\n나 진짜 독하게 찔렀구나...)",
  ui_story_1022_10220800_89_dialog_content = "(아무래도... 오늘이 내 기일인 건가?)",
  ui_story_1022_10220800_90_dialog_content = "<color=#e8d9bb>얼마 후</color>",
  ui_story_1022_10220800_91_dialog_content = "......",
  ui_story_1022_10220800_92_dialog_content = "(「역시 나라니까」...라고 해야 하나... 아직 살아있잖아...)",
  ui_story_1022_10220800_93_dialog_content = "당신 「심장」, 어떻게 된 거죠?",
  ui_story_1022_10220800_94_dialog_content = "우르슬라...?",
  ui_story_1022_10220800_95_dialog_content = "그거 일루미나의 기술이죠? 당신 원래 심장이 아니던데요.",
  ui_story_1022_10220800_96_dialog_content = "...왜 날 구해줬어?",
  ui_story_1022_10220800_97_dialog_content = "흥, 전 원래 「이클립스」에 들어가면 영원히 거역하지 않는 「새로운 친구」가 생길 줄 알았어요.",
  ui_story_1022_10220800_98_dialog_content = "하지만 녀석들은 너무 무능해요. 그냥 벌레들일 뿐이죠. 고귀한 제겐 어울리지 않어요.",
  ui_story_1022_10220800_99_dialog_content = "...반면에, 당신은 나쁘지 않네요.",
  ui_story_1022_10220800_100_dialog_content = "<size=30>절 신경 써 주기도 했고요.</size>",
  ui_story_1022_10220800_101_dialog_content = "아하하...",
  ui_story_1022_10220800_102_dialog_content = "또 웃어요?!",
  ui_story_1022_10220800_103_dialog_content = "너 지금 내가 마음에 든다는 거야?",
  ui_story_1022_10220800_104_dialog_content = "안 되나요? 이건 당신한테 영광인 거라구요. 환희와 흥분으로 춤을 추도록 하세요!",
  ui_story_1022_10220800_105_dialog_content = "일루미나가 만든 「심장」이 아무리 좋든, 결국 당신을 조종당하는 신세로 만들 뿐이에요.",
  ui_story_1022_10220800_106_dialog_content = "저라면 새로운 심장을 만들어 줄 수 있어요. 전 그만한 능력이 있으니까요!",
  ui_story_1022_10220800_107_dialog_content = "그때 내가 뭐라고 대답했었는지 기억나?",
  ui_story_1022_10220800_108_dialog_content = "물론이죠! 거절했잖아요. 「필요 없어, 난 내 힘으로 더 발버둥 쳐보고 싶어」라면서요.",
  ui_story_1022_10220800_109_dialog_content = "하지만 결과는 어떻게 됐죠? 결국 순순히 제 곁으로 돌아왔잖아요?",
  ui_story_1022_10220800_110_dialog_content = "당신이 그 「심장」으로 발버둥 쳐봤자, 이룰 수 있는 건 아무것도 없어요.",
  ui_story_1022_10220800_111_dialog_content = "그러게, 정말 거지 같은 「심장」이지.",
  ui_story_1022_10220800_112_dialog_content = "<color=#e8d9bb>나는 내 심장을 수없이 미워해 왔다. 「제대로 된 심장만 있었더라면」 같은 생각과 함께.</color>",
  ui_story_1022_10220800_113_dialog_content = "<color=#e8d9bb>강하고, 건강하고, 내가 누구의 지시도 받지 않게 해 줄,\n그리고 힘이 다할 때까지 싸울 수 있게 해 줄 그런 심장이 있길 나는 원했다.</color>",
  ui_story_1022_10220800_114_dialog_content = "<color=#e8d9bb>그래서 우르슬라가 조건을 걸 것이라는 사실을 알면서도 여기까지 왔다.</color>",
  ui_story_1022_10220800_115_dialog_content = "<color=#e8d9bb>나를 내려다보는 벨리사리아에 비하면, 우르슬라는 적어도 나를 평등하게 대해준다...</color>",
  ui_story_1022_10220800_116_dialog_content = "<color=#e8d9bb>하지만 그 조건은──</color>",
  ui_story_1022_10220800_117_dialog_content = "<color=#FFB400>「영원히 내 곁에 있어줘.」</color>",
  ui_story_1022_10220800_118_dialog_content = "<color=#e8d9bb>그 말을 듣고, 끝없는 빙원과 일그러진 아름다운 산호 숲을 다시 바라보자,\n내 감정은 이전과는 전혀 달라졌다.</color>",
  ui_story_1022_10220800_119_dialog_content = "<color=#e8d9bb>앞으로는 이것들만이 나의 전부가 되는 것일까.</color>",
  ui_story_1022_10220800_120_dialog_content = "<color=#e8d9bb>...그런 것은 싫다.</color>",
  ui_story_1022_10220800_121_dialog_content = "<color=#e8d9bb>세상은 저렇게 넓은데.</color>",
  ui_story_1022_10220800_122_dialog_content = "<color=#e8d9bb>나는 아직 초원을 못 봤는데.</color>",
  ui_story_1022_10220800_123_dialog_content = "오늘 내 대답도 똑같을 거야.",
  ui_story_1022_10220800_124_dialog_content = "필요 없어, 우르슬라.",
  ui_story_1022_10220800_125_dialog_content = "역시 난 내 힘으로 더 발버둥 쳐보고 싶어.",
  ui_story_1022_10220901_1_dialog_content = "감히 절 놀린 건가요?!",
  ui_story_1022_10220901_2_dialog_content = "미안, 친구. 너랑 같이 있을 때 즐거웠던 건 맞아.",
  ui_story_1022_10220901_3_dialog_content = "그래도 매일 껌딱지처럼 붙어 있어야 되는 건 싫어~\n그런 말도 있잖아. 「인간관계엔 적당한 거리가 필요하다」고, 몰라?",
  ui_story_1022_10220901_4_dialog_content = "......",
  ui_story_1022_10220901_5_dialog_content = "데려오세요.",
  ui_story_1022_10220901_6_dialog_content = "『예!』",
  ui_story_1022_10220901_7_dialog_content = "응? 뭘? 나한텐 네가 인질로 삼을 만한 친한 존재는 없을 텐데?",
  ui_story_1022_10220901_8_dialog_content = "...페디?! 우르슬라 너... 진작에 페디를 붙잡아 두고 있었던 거야?",
  ui_story_1022_10220901_9_dialog_content = "맞아요. 그래도 전 지금까지 참아줬죠. 이걸로 제가 당신한테 얼마나 잘해주는지 알겠어요?",
  ui_story_1022_10220901_10_dialog_content = "이렇게까지... 해줬는데... 왜 계속 떠나려고 하는 거죠?!",
  ui_story_1022_10220901_11_dialog_content = "...그 질문이라면, 그때 이미 대답했잖아?",
  ui_story_1022_10220901_12_dialog_content = "<color=#FFB400>자유가 아니면 죽음을...!</color>",
  ui_story_1022_10220901_13_dialog_content = "그어어...",
  ui_story_1022_10220901_14_dialog_content = "붙잡아요!",
  ui_story_1022_10220901_15_dialog_content = "『우르슬라 님의 명령에 따르겠습니다!』",
  ui_story_1022_10220901_16_dialog_content = "캬아악!",
  ui_story_1022_10220901_17_dialog_content = "고작 너희가?",
  ui_story_1022_10220901_18_dialog_content = "크오오!",
  ui_story_1022_10220901_19_dialog_content = "바, 바보 같은 짓은 그만해요! 그건 자살이나 다름없다구요!",
  ui_story_1022_10220901_20_dialog_content = "그럼 날 놔주면 되잖아.",
  ui_story_1022_10220901_21_dialog_content = "크오오오!",
  ui_story_1022_10220901_22_dialog_content = "하아... 하, 하하, 우르슬라... 네 부하들, 꼭두각시 같아서 재미없어.",
  ui_story_1022_10220901_23_dialog_content = "그럼 이만 실례할게, 안녕!",
  ui_story_1022_10220901_24_dialog_content = "기다려요!",
  ui_story_1022_10220901_25_dialog_content = "으윽...",
  ui_story_1022_10220901_26_dialog_content = "「심장」이 아프기 시작하죠? 그 쓰레기는 당신 뜻대로 따라주지 못한다구요.",
  ui_story_1022_10220901_27_dialog_content = "자기 한계를 직시하세요!",
  ui_story_1022_10220901_28_dialog_content = "싫거든?!",
  ui_story_1022_10220901_29_dialog_content = "으윽...!",
  ui_story_1022_10220901_30_dialog_content = "전부 공격하세요!",
  ui_story_1022_10220901_31_dialog_content = "...방해하지 마!",
  ui_story_1022_10220901_32_dialog_content = "미쳤어요?! 그렇게 격렬한 공격이라니, 죽고 싶은 건가요?",
  ui_story_1022_10220901_33_dialog_content = "이대로는 제가 진지하게 상대하기도 전에 당신 스스로 불타서 재가 될 거라구요!",
  ui_story_1022_10220901_34_dialog_content = "죽더라도... 불태워보고 죽어야지!",
  ui_story_1022_10220901_35_dialog_content = "피...? 제가 피를... 흘린 건가요?",
  ui_story_1022_10220901_36_dialog_content = "당신... 정말... 최악이네요! 감히 절 다치게 하다니!\n알겠어요! 그렇게나 죽고 싶다면 제가 소원을 이뤄주면 되잖아요!",
  ui_story_1022_10220901_37_dialog_content = "으악──!",
  ui_story_1022_10220901_38_dialog_content = "<color=#e8d9bb>두근, 두근, 두근, 두근──</color>",
  ui_story_1022_10220901_39_dialog_content = "<color=#e8d9bb>가슴 속 박동이 점점 빨라졌다.</color>",
  ui_story_1022_10220901_40_dialog_content = "<color=#e8d9bb>「심장」의 움직임은 이미 박동이 아닌 경련으로 변했고,\n브레이크가 듣지 않아 곧 탈선할 열차처럼 달리고 있었다.</color>",
  ui_story_1022_10220901_41_dialog_content = "<color=#e8d9bb>차례차례로 덮쳐오는 극심한 통증이 이성을 찢어 가른다.</color>",
  ui_story_1022_10220901_42_dialog_content = "<color=#e8d9bb>이미 아무것도 모르고, 아무것도 느끼지 않게 되었다.</color>",
  ui_story_1022_10220901_43_dialog_content = "<color=#e8d9bb>그리고 그 유일한 생각만이 그 어느 때보다 또렷해졌다.</color>",
  ui_story_1022_10220901_44_dialog_content = "찬란하게 불타볼 수만 있다면... 죽는 게... 대수야?",
  ui_story_1022_10220901_45_dialog_content = "난 그 누구의 애완동물도 아냐... 누구에게도 굴복하지 않아...",
  ui_story_1022_10220901_46_dialog_content = "<color=#FFB400>내 주인은... 오직 나뿐이라고!</color>",
  ui_story_1022_10220902_1_dialog_content = "「백야의 지침」의 반응이 강해지고 있어. 보물은 이 근처에 있을 거야.",
  ui_story_1022_10220902_2_dialog_content = "저...",
  ui_story_1022_10220902_3_dialog_content = "반응이 더 강해졌어! 잘 찾아봐. 목표물은 아주 작을지도 몰라.",
  ui_story_1022_10220902_4_dialog_content = "때로는 힘들게 찾던 답이 의외로 눈앞에 있을 때도 있죠...",
  ui_story_1022_10220902_5_dialog_content = "에리카, 감상이라면 나중에 말해. 지금은 탐색에 집중해.",
  ui_story_1022_10220902_6_dialog_content = "감상이 아니에요, 전하. 제 말은... 전하 앞쪽에 신성한 빛이 보여서요. 혹시...",
  ui_story_1022_10220902_7_dialog_content = "뭐?!",
  ui_story_1022_10220902_8_dialog_content = "풉...",
  ui_story_1022_10220902_9_dialog_content = "뭘 웃어?! 너도 못 본 건 마찬가지잖아?",
  ui_story_1022_10220902_10_dialog_content = "크흠, 우리 둘 다 지침만 봤으니까 그렇지...\n아무튼! 진짜 백야성이 잃어버린 보물인지 얼른 확인해 보자.",
  ui_story_1022_10220902_11_dialog_content = "되게 순수한 루미나네... 마음이 평온해져.",
  ui_story_1022_10220902_12_dialog_content = "찾았습니까?!",
  ui_story_1022_10220902_13_dialog_content = "확실해. 이 빛이 다크매터를 차단하고 있었던 거야.",
  ui_story_1022_10220902_14_dialog_content = "그렇다면 그게 바로 진리의 결사가 오래전 잃어버렸던 성물이겠네.",
  ui_story_1022_10220902_15_dialog_content = "어라? 이 목소리...",
  ui_story_1022_10220902_16_dialog_content = "오늘 성물은 주인에게 돌아오고, 만물은 모두 정해진 궤적으로 돌아가니,\n주의 신비한 인도가 이곳에 이르렀구나.",
  ui_story_1022_10220902_17_dialog_content = "누구냐! 그건 백야성의 소유다! 당장 내려놔!",
  ui_story_1022_10220902_18_dialog_content = "빅토리아, 당신 정말 막무가내네.\n성전 일도 아직 담판을 못 지었는데, 또다시 강탈을 일삼을 작정인가?!",
  ui_story_1022_10220902_19_dialog_content = "빅토리아...? 서, 설마... 그 이단 결사의 우두머리가... 바로 당신...?",
  ui_story_1022_10220902_20_dialog_content = "후훗... 진리의 추구는 우매한 나라에서는 확실히 「이단」으로 간주되겠지.",
  ui_story_1022_10220902_21_dialog_content = "이 성물은 이 땅의 주인이 한때 왈라지 마을에서 빼앗아 간 거야.\n난 한 번도 내 것이 아닌 물건을 건드린 적 없어.",
  ui_story_1022_10220902_22_dialog_content = "심지어 날 이곳에 인도한 단서조차 진리의 결사 일원인 페피타의 손에서 나온 것이고.",
  ui_story_1022_10220902_23_dialog_content = "그런 내 어디가 막무가내라는 걸까? 우리 카렌 공주님?",
  ui_story_1022_10220902_24_dialog_content = "...닥쳐!",
  ui_story_1022_10220902_25_dialog_content = "이단의 수괴... 방자한 말로 듣는 귀를 더럽히다니...",
  ui_story_1022_10220902_26_dialog_content = "죽어라──!",
  ui_story_1022_10220902_27_dialog_content = "하, 하아...",
  ui_story_1022_10220902_28_dialog_content = "(산호... 또 산호... 아직도 못 벗어난 건가?)",
  ui_story_1022_10220902_29_dialog_content = "(방금 전엔 우르슬라가 순간적으로 마음이 약해져서 힘을 풀었지만,\n생각하다 보면 또 화가 나서 쫓아올지도 몰라... 그땐 진짜로 끝이야...)",
  ui_story_1022_10220902_30_dialog_content = "(어라? 무슨 소리지?)",
  ui_story_1022_10220902_31_dialog_content = "으윽! 빌어먹을... 이단의 사악한 힘이 이렇게나 강하다니...",
  ui_story_1022_10220902_32_dialog_content = "하는 말마다 「사악」을 꺼내는데, 주의 신도에게 무슨 원한이라도 있는 거니?",
  ui_story_1022_10220902_33_dialog_content = "이 발소리... 온다!",
  ui_story_1022_10220902_34_dialog_content = "에리카...? 빅토리아 님?! 어떻게 알고 오셨어요? 심부름 보낸 페디는 잡혀 버렸는데...",
  ui_story_1022_10220902_35_dialog_content = "주의 인도 아래 운명은 자신의 길을 찾게 되거든.",
  ui_story_1022_10220902_36_dialog_content = "페피타, 역시 다쳤구나. 누가 널 그렇게까지 아프게 한 거니?\n...어머, 아무래도 물어볼 필요는 없을 것 같네.",
  ui_story_1022_10220902_37_dialog_content = "페피타! 여기까지 오는 동안 흘린 피로 당신은 이미 열 번도 더 죽었어요!\n아직도 도망칠 생각인가요?",
  ui_story_1022_10220902_38_dialog_content = "계속 도망치면 저 진짜로 화낼 거예요. 지금 당장 여길 쑥대밭으로 만들 거라구요!",
  ui_story_1022_10220902_39_dialog_content = "......!",
  ui_story_1022_10220902_40_dialog_content = "페피타, 내 뒤로 오렴.",
  ui_story_1022_10220902_41_dialog_content = "누구죠? 감히 절 방해하다니!\n...아! 다, 당신...?!",
  ui_story_1022_10220902_42_dialog_content = "널 방해하는 건 내가 아냐. 난 여기 그대로 서서 조금도 움직이지 않았거든.",
  ui_story_1022_10220902_43_dialog_content = "페피타는 자기 발로 널 떠나서 내 뒤로 왔어.",
  ui_story_1022_10220902_44_dialog_content = "그리고 페피타를 그렇게 만든 건 다른 사람이 아니라 너잖니?",
  ui_story_1022_10220902_45_dialog_content = "처음부터 끝까지 방해한 건 너 자신뿐이란다.",
  ui_story_1022_10220902_46_dialog_content = "......",
  ui_story_1022_10220902_47_dialog_content = "당신... 아니, 틀렸어요. 페피타는 제 거예요. 다, 당신 게 아니라구요...",
  ui_story_1022_10220902_48_dialog_content = "진리란 심오한 거야. 당장은 이해가 안 되는 것도 당연해.",
  ui_story_1022_10220902_49_dialog_content = "다만 생각지도 않고 어리석음이나 무지, 잔인함을 자신의 표식으로 삼는다면...",
  ui_story_1022_10220902_50_dialog_content = "언젠가는 반드시 진리의 빛이 다시는 닿지 않을 극야에 떨어지게 될 거야.",
  ui_story_1022_10220902_51_dialog_content = "다, 당신... 정말... 으, 으아아아앙──!",
  ui_story_1022_10220902_52_dialog_content = "<color=#e8d9bb>방금 전까지만 해도 기세가 사납던 팬텀이 갑자기 입을 삐죽 내밀고는 푸념하며 도망쳤다.\n멀리서 「할아버지」라고 외치며 우는 소리가 들려왔다.</color>",
  ui_story_1022_10220902_53_dialog_content = "지금... 울면서 도망간 거야...?",
  ui_story_1022_10220902_54_dialog_content = "후훗... 나쁜 아이를 혼내는 것도 오랜만이네. 우스운 꼴을 보였구나.",
  ui_story_1022_10220902_55_dialog_content = "저 팬텀은 왈라키아 가문과 조금 인연이 있거든.\n게다가 페피타를 심하게 해친 걸 보니까 나도 참을 수 없었어.",
  ui_story_1022_10220902_56_dialog_content = "(또 왈라키아야?!)",
  ui_story_1022_10220902_57_dialog_content = "페피타, 치료해 줄게.",
  ui_story_1022_10220902_58_dialog_content = "이 휘장... 빅토리아 님, 혹시 휘장으로 절 찾으신 건가요?",
  ui_story_1022_10220902_59_dialog_content = "그 휘장엔 내 술식이 담겨 있어.\n인공 심장의 힘을 끌어낼 수 있고, 네 생명과도 긴밀하게 연결돼 있는 거야.",
  ui_story_1022_10220902_60_dialog_content = "그래서 네가 위험에 처하면 난 바로 알 수 있어.",
  ui_story_1022_10220902_61_dialog_content = "그러니까 네 말이 맞아. 네가 날 여기까지 이끈 거야.\n그리고 우연히도 결사의 성물을 발견할 수 있었고.",
  ui_story_1022_10221001_1_dialog_content = "참! 빅토리아 씨! 카론 씨랑 아는 사이지?",
  ui_story_1022_10221001_2_dialog_content = "바이스가 어디 갔는지 알아? 그리고 왜 피안호의 좌표가 여기저기 날아다니는 거야?",
  ui_story_1022_10221001_3_dialog_content = "설마 팬텀이랑 마주치거나 한 건 아니지?!",
  ui_story_1022_10221001_4_dialog_content = "그 일이라면... 음? 당신은 무슨 볼일일까?",
  ui_story_1022_10221001_5_dialog_content = "...! 그건 내가 묻고 싶은 말이다! 이자는 백야성의 성전을 훔쳤다. 죄인을 비호할 생각이냐?",
  ui_story_1022_10221001_6_dialog_content = "그러고 보면 훔친 성전은 이제 너희 결사의 수중에 있겠지...\n이 얼마나 사악한 도적의 소굴이란 말인가!",
  ui_story_1022_10221001_7_dialog_content = "야, 너 아까부터 말이 좀 듣기 거북하네?",
  ui_story_1022_10221001_8_dialog_content = "양측이 서로 도발하고, 긴장이 점점 고조되고 있어... 난 어떻게 하면 좋을까...",
  ui_story_1022_10221001_9_dialog_content = "페피타에게 못 들었을까? 그 「성전」은 이 성물과 마찬가지로 원래부터 진리의 결사의 것이었어.",
  ui_story_1022_10221001_10_dialog_content = "헛소리! 이것도 자기들 거고, 저것도 자기들 거라니, 아스트라도 너희가 만든 거야?!",
  ui_story_1022_10221001_11_dialog_content = "말이 안 통한다면... 검으로 말을 듣게 하는 수밖에.",
  ui_story_1022_10221001_12_dialog_content = "에리카, 간다!",
  ui_story_1022_10221001_13_dialog_content = "네!",
  ui_story_1022_10221001_14_dialog_content = "잠깐만!",
  ui_story_1022_10221001_15_dialog_content = "...PlayerName, 네가 나설 자리가 아니야.",
  ui_story_1022_10221001_16_dialog_content = "우린 어떻게 해서든 성전의 행방을 알아내야 해.",
  ui_story_1022_10221001_17_dialog_content = "「알아낼」 거면 말로 하면 되잖아? 검이 아니라! 다들 성주님의 뜻을 잊은 건 아니겠지?",
  ui_story_1022_10221001_18_dialog_content = "......",
  ui_story_1022_10221001_19_dialog_content = "문제는 최대한 평화적인 방법으로 해결하자.\n연합 탐색 부대의 활동에 차질이 생기면 안 되잖아...",
  ui_story_1022_10221001_20_dialog_content = "연합? 그게 누구와의 연합이지?",
  ui_story_1022_10221001_21_dialog_content = "?!",
  ui_story_1022_10221001_22_dialog_content = "오는 동안 당신을 어느 정도는 신뢰하고 있었는데, 중요한 순간에 당신은 이단 조직 편에 섰어.",
  ui_story_1022_10221001_23_dialog_content = "그런데도 뭐? 연합 탐색으로 서로를 도와? 결국 허울 좋은 말일 뿐이었어!",
  ui_story_1022_10221001_24_dialog_content = "비켜, 안 비킨다면...",
  ui_story_1022_10221001_25_dialog_content = "어쩔 생각이죠?",
  ui_story_1022_10221001_26_dialog_content = "...당신까지 그렇게 나오는 거야?!",
  ui_story_1022_10221001_27_dialog_content = "PlayerName의 말이 맞습니다.\n어둠의 밑바닥 탐색이 가장 중요한 문제라는 건 대원수님과 백야성 성주의 공통된 인식입니다.",
  ui_story_1022_10221001_28_dialog_content = "질문이 있다면 검부터 거두고 하세요.",
  ui_story_1022_10221001_29_dialog_content = "......",
  ui_story_1022_10221001_30_dialog_content = "조장님...",
  ui_story_1022_10221001_31_dialog_content = "...이단은... 전부 죽어야 해!",
  ui_story_1022_10221002_1_dialog_content = "으윽...! 하, 하아...",
  ui_story_1022_10221002_2_dialog_content = "(제길... 이 녀석, 너무 강해... 하필 어둠의 밑바닥이 힘을 억제하는 상황에서...)",
  ui_story_1022_10221002_3_dialog_content = "도망치게... 둘 줄 알고?!",
  ui_story_1022_10221002_4_dialog_content = "주께선 이미 계시를 내리셨어. 페피타에겐 아직 찬란한 미래가 기다리고 있어.",
  ui_story_1022_10221002_5_dialog_content = "다시 만나자, 부디 진리의 빛의 인도가 있기를.",
  ui_story_1022_10221002_6_dialog_content = "...빌어먹을!",
  ui_story_1022_10221002_7_dialog_content = "잠깐만! 빅토리아 씨! 바이스는 어디 있어? 아직 대답 안 해 줬잖아!",
  ui_story_1022_10221002_8_dialog_content = "으앗, 히이로 씨? 뭐 하는 거예요? 으아아앗! 날았다아아!",
  ui_story_1022_10221002_9_dialog_content = "조용히 하세요. 나는 게 아니라 빨리 달리고 있을 뿐이니까요.",
  ui_story_1022_10221002_10_dialog_content = "이래야 빅토리아를 따라잡을 수 있어요.",
  ui_story_1022_10221002_11_dialog_content = "으음?",
  ui_story_1022_10221002_12_dialog_content = "빅토리아 님, 왜 그러세요?",
  ui_story_1022_10221002_13_dialog_content = "페피타, 먼저 가렴. 계속 여기 있다간 또 귀찮은 일에 휘말릴 거야.",
  ui_story_1022_10221002_14_dialog_content = "어서.",
  ui_story_1022_10221002_15_dialog_content = "...네!",
  ui_story_1022_10221002_16_dialog_content = "저기 있습니다!",
  ui_story_1022_10221002_17_dialog_content = "빅토리아 씨! 바이스가 어디 갔는지 알고 있는 거지?!",
  ui_story_1022_10221002_18_dialog_content = "조급해할 것 없어. 책에서 알려준 때가 오면 저절로 다시 만나게 될 테니까.",
  ui_story_1022_10221002_19_dialog_content = "하지만 지금은 아직 때가 아니야... 그럼 다음에 봐.",
  ui_story_1022_10221002_20_dialog_content = "(역시 바이스의 상황에 대해 알고 있었어!)",
  ui_story_1022_10221002_21_option_content = "(강제 감응!)",
  ui_story_1022_10221002_22_dialog_content = "후훗...",
  ui_story_1022_10221002_23_dialog_content = "이, 이건...",
  ui_story_1022_10221002_24_dialog_content = "<color=#e8d9bb>극야는 마치 점도 높은 유체 같았고, 그 사이로 거대한 얼음 기둥이 하늘을 찌르듯 솟아있었다.</color>",
  ui_story_1022_10221002_25_dialog_content = "<color=#e8d9bb>그리고 그 얼음 기둥 안에 갇혀있는 것은──</color>",
  ui_story_1022_10221002_26_dialog_content = "...바이스!",
  ui_story_1022_10221002_27_dialog_content = "(어째서... 바이스가 왜 저런 곳에 있는 건데...?)",
  ui_story_1022_10221002_28_option_content = "[다시 한번 감응한다]",
  ui_story_1022_10221002_29_dialog_content = "이 음색이야말로 진정한 예술이다! 마치 시공의 경계선을 관통하는 듯하지 않은가!",
  ui_story_1022_10221002_30_dialog_content = "바이스 양, 뭐 하는 거야?",
  ui_story_1022_10221002_31_dialog_content = "PlayerName... 조종사가 위험해요!\n이대로는 엔지니어의 어둠에 휩쓸려 버릴 거예요... 어떻게든 해야 돼요!",
  ui_story_1022_10221002_32_dialog_content = "피아노의 음색으로 PlayerName의 의식을 깨운다면...",
  ui_story_1022_10221002_33_dialog_content = "엔지니어는 지금 저 아이를 주시하고 있어. 저들의 의식은 지금 연결돼 있는 거야.",
  ui_story_1022_10221002_34_dialog_content = "섣불리 손을 댄다면, 엔지니어가 당신 존재를 알아챌 거야.",
  ui_story_1022_10221002_35_dialog_content = "하지만...!",
  ui_story_1022_10221002_36_dialog_content = "빅토리아 여사, 분위기를 깨는 것도 정도가 있어야 하지 않나?",
  ui_story_1022_10221002_37_dialog_content = "이 아름다운 음색을 멈추고, 나의 친구를 어둠 속에 내버려두라니,\n과연 당신의 그 「주」가 그런 행위를 찬미할까?",
  ui_story_1022_10221002_38_dialog_content = "어머, 네 입에서 주의 이름을 들을 줄은 몰랐네.\n게다가 엔지니어와 싸울 준비도 돼 있는 것 같고 말이야.",
  ui_story_1022_10221002_39_dialog_content = "설마, 마침내 오랜 반항기를 끝내고, 진리를 품에 안고 혈통에 각성한 걸까?",
  ui_story_1022_10221002_40_dialog_content = "대체 어디서 그런 결론에 이르게 되는 거냐!\n난 당신들이 찬양하는 진리 따위에 아무 흥미도 없다.",
  ui_story_1022_10221002_41_dialog_content = "그거 정말 유감이구나.",
  ui_story_1022_10221002_42_dialog_content = "...성공했어요! 조종사가 어둠을 떨쳐냈어요!",
  ui_story_1022_10221002_43_dialog_content = "근데 스카이워커호가... 가버렸어요...",
  ui_story_1022_10221002_44_dialog_content = "걱정 마라, 바이스. 녀석은 절대 그 콜로서스를 버리지 않을 거다.\n우리도 그를 버리지 않을 테고 말이야.",
  ui_story_1022_10221002_45_dialog_content = "그럼 좀 곤란하겠네.",
  ui_story_1022_10221002_46_dialog_content = "또 무슨 찬물 끼얹는 말을 하려는 거지?",
  ui_story_1022_10221002_47_dialog_content = "진리의 결사의 일원은 모두 진리의 가호를 받고 있어.\n하지만 일루미나 사람들은 부름을 받지 못했지.",
  ui_story_1022_10221002_48_dialog_content = "당신들이 굳이 자기 몸을 위험에 던질 생각이라면... 이렇게 하는 수밖에 없겠지.",
  ui_story_1022_10221002_49_dialog_content = "<color=#e8d9bb>휘이익──</color>",
  ui_story_1022_10221002_50_dialog_content = "으앗!",
  ui_story_1022_10221002_51_dialog_content = "뭐, 뭐냐?!",
  ui_story_1022_10221002_52_dialog_content = "<color=#e8d9bb>빅토리아가 손을 휘두르자, 원시의 강의 흐름이 갑자기 갈라졌다.</color>",
  ui_story_1022_10221002_53_dialog_content = "<color=#e8d9bb>카론과 바이스는 강의 흐름을 뚫고, 그대로 아래를 향해 한없이 추락했다.</color>",
  ui_story_1022_10221002_54_dialog_content = "<color=#e8d9bb>귓가에는 신비한 속삭임이 울려 퍼지고 있었다──</color>",
  ui_story_1022_10221002_55_dialog_content = "원시의 강물을 한 방울만 부으면, 아무리 강력한 다크매터도 그걸 녹일 수 없어.",
  ui_story_1022_10221002_56_dialog_content = "으아아아아── 어? 안 떨어지네?",
  ui_story_1022_10221002_57_dialog_content = "...여긴 또 어디지...?",
  ui_story_1022_10221002_58_dialog_content = "<color=#e8d9bb>눈을 깜빡이자, 주변에는 또 다른 광경이 펼쳐져 있었다.</color>",
  ui_story_1022_10221002_59_dialog_content = "<color=#e8d9bb>끈적끈적하고 칠흑 같은 하늘은 희미하게 일그러져 있었고,\n마치 울퉁불퉁하고 두툼한 유리를 통해 하늘을 보고 있는 듯했다.</color>",
  ui_story_1022_10221002_60_dialog_content = "<color=#e8d9bb>하지만 그것은 유리가 아니라──</color>",
  ui_story_1022_10221002_61_dialog_content = "...얼음? 내, 내가 왜 얼음 속에 갇혀 있는 거야?!",
  ui_story_1022_10221002_62_dialog_content = "응? 이 소리는...",
  ui_story_1022_10221002_63_dialog_content = "<color=#e8d9bb>우르르르──</color>",
  ui_story_1022_10221002_64_dialog_content = "부서져라, 얼음이여! 나의 이 타오르는 열정은 얼어붙는 추위로도 막을 수 없다!",
  ui_story_1022_10221002_65_dialog_content = "카론 님! 카론 님도 얼음 속에 갇히셨나요?",
  ui_story_1022_10221002_66_dialog_content = "<color=#e8d9bb>콰르르르르──</color>",
  ui_story_1022_10221002_67_dialog_content = "<color=#e8d9bb>얼음기둥이 「피안호」의 충격으로 부서지기 시작했다.</color>",
  ui_story_1022_10221002_68_dialog_content = "바이스, 내 손을 잡아라!",
  ui_story_1022_10221002_69_dialog_content = "네!",
  ui_story_1022_10221002_70_dialog_content = "바이스 양.",
  ui_story_1022_10221002_71_dialog_content = "(착각인가? 방금 빅토리아 씨가 날 부른 것 같은데...)",
  ui_story_1022_10221002_72_dialog_content = "바이스 양, 잘 들어.",
  ui_story_1022_10221002_73_dialog_content = "PlayerName 그 아이는 이제 곧 가혹한 시련을 맞이하게 될 거야.",
  ui_story_1022_10221002_74_dialog_content = "<color=#e8d9bb>마치 귓가에 대고 말하는 듯, 빅토리아의 목소리는 한 글자, 한 마디 또렷하게 들렸다.</color>",
  ui_story_1022_10221002_75_dialog_content = "!!!",
  ui_story_1022_10221002_76_dialog_content = "바이스? 뭘 멍하니 있는 것이냐! 어서 이쪽으로 와라!",
  ui_story_1022_10221002_77_dialog_content = "......",
  ui_story_1022_10221002_78_dialog_content = "카론 님, 먼저 가세요.",
  ui_story_1022_10221002_79_dialog_content = "전 여기 남겠어요.",
  ui_story_1022_10221002_80_dialog_content = "뭐라고?!",
  ui_story_1022_10221002_81_dialog_content = "PlayerName 그 애한테는 제가 필요해요...",
  ui_story_1022_10221002_82_dialog_content = "여기 있으면 제가 분명히 힘이 될 수 있을 거예요.",
  ui_story_1022_10221002_83_dialog_content = "<color=#FFB400>바이스──!</color>",
  ui_story_1022_10221002_84_dialog_content = "<color=#e8d9bb>나는 소리를 지르고 손을 뻗어 소녀의 미소를 지켜주고 싶었다.\n차라리 지금 당장 그 곁으로 날아가고 싶었다.</color>",
  ui_story_1022_10221002_85_dialog_content = "<color=#e8d9bb>그러나 감응으로 보이는 광경은 점점 어두워질 뿐이었다.</color>",
  ui_story_1022_10221002_86_dialog_content = "<color=#e8d9bb>어둠이 점점 더 깊어져간다.</color>",
  ui_story_1022_10221002_87_dialog_content = "<color=#e8d9bb>마치 극야가 찾아온 것처럼.</color>",
  ui_story_1022_10221002_88_dialog_content = "<color=#e8d9bb>그리고 오직 그녀가 있는 곳만이 빛을 발하고 있었다.</color>",
  ui_story_1022_10221002_89_dialog_content = "<color=#e8d9bb>짓누르는 어둠과 매서운 추위 속──</color>",
  ui_story_1022_10221002_90_dialog_content = "<color=#e8d9bb>빛은 사방을 눈부시게 비추기 시작했다.</color>",
  ui_story_1022_10221002_91_dialog_content = "<color=#e8d9bb>마치 극야에 해가 솟아오른 것처럼.</color>",
  ui_story_1022_10221002_92_dialog_content = "(내가 감응한 그 루미나는... 바이스였어...)",
  ui_story_1022_10221002_93_dialog_content = "(바이스가 영혼으로 만들어 준 이정표 덕분에, 난 어둠 속에서 길을 잃지 않았어.)",
  ui_story_1022_10221002_94_dialog_content = "(다들 날 조종사라고 불러. 내가 전장에서 모두를 이끌었으니까.)",
  ui_story_1022_10221002_95_dialog_content = "(하지만 날 인도하는 빛은... 줄곧 바이스였던 거야.)",
  ui_story_1022_10221002_96_dialog_content = "(처음 만났던 그날부터...)",
  ui_story_1022_10221101_1_dialog_content = "...PlayerName.",
  ui_story_1022_10221101_2_dialog_content = "PlayerName, 정신 차리세요!",
  ui_story_1022_10221101_3_dialog_content = "히이로 씨...",
  ui_story_1022_10221101_4_dialog_content = "...아, 바이스! 바이스가 얼음 기둥 안에 갇혀 있어요!\n제가 감응한 그 루미나가 바로 바이스였어요! 구하러 가야 해요!",
  ui_story_1022_10221101_5_dialog_content = "우선 진정하세요. 물부터 좀 마시고 천천히 말해 보세요.",
  ui_story_1022_10221101_6_dialog_content = "네, 고마워요...",
  ui_story_1022_10221101_7_dialog_content = "그 전에 먼저 전할 일이 있습니다. 빅토리아가 갑자기 사라졌습니다.",
  ui_story_1022_10221101_8_dialog_content = "갑자기요?",
  ui_story_1022_10221101_9_dialog_content = "어쩌면 처음부터 실제 본인이 아니었을지도 모릅니다.",
  ui_story_1022_10221101_10_dialog_content = "으아아앙── 할아버지, 할아버지...",
  ui_story_1022_10221101_11_dialog_content = "훌쩍, 할아버지 미워! 왜 저만 놔두고 돌아가셨어요?\n할아버지가 있었으면 저 <color=#FFB400>대가주</color>한테 괴롭힘을 당할 일도 없었을 텐데...!",
  ui_story_1022_10221101_12_dialog_content = "할아버지...",
  ui_story_1022_10221101_13_dialog_content = "......",
  ui_story_1022_10221101_14_dialog_content = "뭐, 됐어요... 이미 죽은 사람인데 그리워해 봤자 무슨 소용이 있겠어요.",
  ui_story_1022_10221101_15_dialog_content = "제겐 페피타가 있잖아요. 페피타는 진심으로 절 아껴준다구요!",
  ui_story_1022_10221101_16_dialog_content = "근데 그 페피타도 대가주한테 빼앗겨 버렸잖아요...",
  ui_story_1022_10221101_17_dialog_content = "<size=50>흐아아아앙!</size>",
  ui_story_1022_10221101_18_dialog_content = "내가 이미 말했잖니. 페피타가 떠난 건 너 자신 때문이라고.",
  ui_story_1022_10221101_19_dialog_content = "?!",
  ui_story_1022_10221101_20_dialog_content = "가끔은 머리를 좀 쓰는 게 어떠니?\n날 때부터 머리를 쓸 기회가 그리 많지 않았겠지만 말이야...",
  ui_story_1022_10221101_21_dialog_content = "그렇다고 이대로 녹슬게 만들면 너무 낭비 아니니?",
  ui_story_1022_10221101_22_dialog_content = "제명됐던 <color=#FFB400>열세 번째 가주 「아이」</color>야.",
  ui_story_1022_10221101_23_dialog_content = "...가, 감히... 그걸 입에 담다니!",
  ui_story_1022_10221101_24_dialog_content = "어리석은 놈, 천민의 피를 내 소중한 손녀에게 먹이려는 것이냐!",
  ui_story_1022_10221101_25_dialog_content = "우르슬라는 천함과 어리석음의 맛을 가리는 아이다! 네놈들은 이 아이를 죽일 작정이냐?!",
  ui_story_1022_10221101_26_dialog_content = "죄, 죄송합니다!",
  ui_story_1022_10221101_27_dialog_content = "으앙! 으아아아앙!",
  ui_story_1022_10221101_28_dialog_content = "착하지? 뚝 그치거라, 할아비가 지금 바로 너한테 맞는 먹잇감을 찾아주마.",
  ui_story_1022_10221101_29_dialog_content = "가장 감미로운 피로 네 그 찬란한 재능을 채워줄 것이야...",
  ui_story_1022_10221101_30_dialog_content = "<color=#e8d9bb>쨍그랑── 테이블 위에 있던 식기가 날카로운 소리와 함께 바닥에 떨어져 산산조각 났다.</color>",
  ui_story_1022_10221101_31_dialog_content = "가주님! 왜 그러시죠? 뭔가 마음에 안 드는 일이 있으신가요?",
  ui_story_1022_10221101_32_dialog_content = "어째서죠? 왜 오늘 제 「사냥감」은 고작 이것뿐이냐구요!\n할아버지가 살아계셨다면 당신들도 절대 이런 식으로 절 푸대접하진 못했을 거예요!",
  ui_story_1022_10221101_33_dialog_content = "하...하지만... 평민의 「감소」가 너무 빠르면 생산이 끊겨서...\n사람들이 먹을 밥이 없게 됩니다...",
  ui_story_1022_10221101_34_dialog_content = "밥이 없으면 케이크를 먹으면 되잖아요? 그런 사소한 것까지 제가 가르쳐 줘야 하나요?",
  ui_story_1022_10221101_35_dialog_content = "아, 알겠습니다... 지금 바로 다시 준비하겠습니다...",
  ui_story_1022_10221101_36_dialog_content = "도망쳐...!",
  ui_story_1022_10221101_37_dialog_content = "아하하하! 역시 이래야죠. 사냥은 사냥감이 많아야 재미있다니까요.",
  ui_story_1022_10221101_38_dialog_content = "자, 어서 도망치세요. 더 빨리, 더 멀리요. 하지만 걱정 마세요...",
  ui_story_1022_10221101_39_dialog_content = "전~부 남김없이 찾아내서 실컷 놀아줄 테니까요.",
  ui_story_1022_10221101_40_dialog_content = "누구 하나... 외롭게 빠트리지 않을 거라구요.",
  ui_story_1022_10221101_41_dialog_content = "그땐 얼마나 좋았는데... 누구나 제 말을 듣고, 누구든지 저랑 놀아줬어요...",
  ui_story_1022_10221101_42_dialog_content = "이게 다 왈라키아 당신들 때문이에요! 「대가주」가... 다 망친 거라구요!",
  ui_story_1022_10221101_43_dialog_content = "당신들이 절 몰아붙여서 「이클립스」로 가게 만든 거예요.\n온종일 잠만 자고, 아무도 상대 안 해 주고, 모두가 제 말을 거역하고...",
  ui_story_1022_10221101_44_dialog_content = "전부 당신들 때문이라구요!",
  ui_story_1022_10221101_45_dialog_content = "또 남 탓을 하는 거니?",
  ui_story_1022_10221101_46_dialog_content = "네가 제명된 건 네 잔학함과 배신 때문이야.",
  ui_story_1022_10221101_47_dialog_content = "넌 암귀 무리를 이끌고 왈라지 마을에 쳐들어와 무수한 신도를 잔혹하게 해치고,\n결사의 성물을 빼앗았어. 왈라키아의 역사에 전대미문의 참상을 남겼지.",
  ui_story_1022_10221101_48_dialog_content = "나도 오래된 서적에서 알게 된 것뿐이었지만, 네 행적엔 나조차도 전율했어.",
  ui_story_1022_10221101_49_dialog_content = "닥쳐요! 그 입 닥치라구요! 오로리안 좀 죽였다고 그게 뭐가 대수죠?\n그러는 당신은 죽인 적 없어요?",
  ui_story_1022_10221101_50_dialog_content = "할아버지가 있을 땐 내가 신나게 놀면 할아버지도 좋아하셨는데... 꼭 당신들만 귀찮게 굴잖아요!",
  ui_story_1022_10221101_51_dialog_content = "「대가주」라고 해서 절 가르칠 수 있다고 생각하지 말라구요...",
  ui_story_1022_10221101_52_dialog_content = "찬란하게 불타볼 수만 있다면... 죽는 게... 대수야?",
  ui_story_1022_10221101_53_dialog_content = "난 그 누구의 애완동물도 아냐... 누구에게도 굴복하지 않아...",
  ui_story_1022_10221101_54_dialog_content = "<color=#FFB400>내 주인은... 오직 나뿐이라고!</color>",
  ui_story_1022_10221101_55_dialog_content = "...제 주인은 오직 저뿐이고, 절대 당신한테 굴복하지 않을 거라구요!",
  ui_story_1022_10221101_56_dialog_content = "네가 페피타의 신념을 그렇게 오해하는 걸 알면, 그 애가 참 난처할 거야.",
  ui_story_1022_10221101_57_dialog_content = "다시는... 페피타의 이름을 꺼내지 마세요!",
  ui_story_1022_10221101_58_dialog_content = "<color=#e8d9bb>히스테릭한 외침과 함께 짙은 다크매터가 뿜어져 나왔다.</color>",
  ui_story_1022_10221101_59_dialog_content = "<color=#e8d9bb>다크매터는 우르슬라를 감쌌고, 부글대며 사방으로 쏟아져 나와 검은 얼음층을 뒤덮었다.</color>",
  ui_story_1022_10221101_60_dialog_content = "<color=#e8d9bb>그 위로 수많은 싹들이 넘실거리며 얼음층을 뚫고 나왔고, 찢기고 갈라져,\n거대하고 기이한 형태의 산호 숲을 만들어냈다.</color>",
  ui_story_1022_10221101_61_dialog_content = "<color=#e8d9bb>산호의 가지는 서로 엉켜 마치 변형된 혈관처럼 변했고, 악성 근육처럼 보이기도 했다.</color>",
  ui_story_1022_10221101_62_dialog_content = "<color=#e8d9bb>두근, 두근.</color>",
  ui_story_1022_10221101_63_dialog_content = "<color=#e8d9bb>산호 숲의 모습을 한 거대한 생명체는 검은 안개 속 심장에 맞추어 고동치고 있었다.</color>",
  ui_story_1022_10221101_64_dialog_content = "<color=#e8d9bb>그리고 박동마다 끈적한 다크매터를 내뿜었고, 영역 안에 있는\n모든 오로리안의 생명을 부패시킬 기세였다.</color>",
  ui_story_1022_10221101_65_dialog_content = "크아아아──!",
  ui_story_1022_10221102_1_dialog_content = "<color=#e8d9bb>콰직──</color>",
  ui_story_1022_10221102_2_dialog_content = "<color=#e8d9bb>우르슬라를 감싸던 다크매터의 껍질이 부서졌다.\n하지만 빅토리아 또한 그로 인한 대가를 치러야 했다.</color>",
  ui_story_1022_10221102_3_dialog_content = "크윽──!",
  ui_story_1022_10221102_4_dialog_content = "하, 하아, 하하하하! 대가주라더니 고작 이 정도인가요?",
  ui_story_1022_10221102_5_dialog_content = "제가 조금만 진지하게 상대했더니, 금방 쓰러져 버렸네요.",
  ui_story_1022_10221102_6_dialog_content = "뭐, 그럴 수밖에요. 전 아~주 어릴 때 혈통을 각성했으니까요.\n할아버지도 저만큼 천부적인 재능을 가진 사람은 본 적 없었다고 하셨죠.",
  ui_story_1022_10221102_7_dialog_content = "아줌마는요? 설마 관짝에 반쯤 들어갔을 때 겨우 각성한 건 아니죠? 아하하하!",
  ui_story_1022_10221102_8_dialog_content = "...훗.",
  ui_story_1022_10221102_9_dialog_content = "뭐가 웃기는데요?!",
  ui_story_1022_10221102_10_dialog_content = "전 혈족 역사상 각성이 가장 빨랐던 사람이에요. 그건 제가 최고의 재능을 가졌고,\n힘도 가장 순수하다는 뜻이죠. 당신은 그 어떤 것도 저보다 나은 게 없다구요.",
  ui_story_1022_10221102_11_dialog_content = "아니면 차라리 대가주 자리를 저한테 양보하는 게 어때요? 아하하하!",
  ui_story_1022_10221102_12_dialog_content = "<color=#e8d9bb>우르슬라의 광기 어린 웃음이 갑자기 멈추었다.</color>",
  ui_story_1022_10221102_13_dialog_content = "<color=#e8d9bb>경악하는 우르슬라의 시선 끝, 빅토리아의 상처는 하나하나 아물어가고 있었고,\n심지어 찢어졌던 옷조차 원래 상태로 돌아갔다.</color>",
  ui_story_1022_10221102_14_dialog_content = "어, 어떻게...",
  ui_story_1022_10221102_15_dialog_content = "물어볼 필요가 있을까? 네 재능이라면 이 정도 상황 파악은 할 수 있을 텐데.",
  ui_story_1022_10221102_16_dialog_content = "......! 대, 대부분의 힘을 나눠서 다른 곳에...? 대체 뭘 하고 있었죠?",
  ui_story_1022_10221102_17_dialog_content = "저들을 원시의 강에서 떨어트렸어.\n어둠의 밑바닥은 아무래도 위험하니까, 내가 챙겨줘야지 어쩌겠니.",
  ui_story_1022_10221102_18_dialog_content = "...너도 한때 잘못된 길로 나아가지만 않았다면, 우린 함께 주의 가호를 받고 있었을 텐데.",
  ui_story_1022_10221102_19_dialog_content = "저랑 싸우는 동안 남을 챙겨줬다고요...? 말도 안 돼... 그럴 수 있을 리가 없잖아요!",
  ui_story_1022_10221102_20_dialog_content = "저야말로 최강이에요... 가장 빨리 각성하고, 재능도 가장 뛰어나고...\n힘도 가장 순수하다구요... 부, 분명히 당신이 무슨 수작을 부린 거겠죠!",
  ui_story_1022_10221102_21_dialog_content = "그게 네가 생각 끝에 낼 수 있는 유일한 해답이니? 넌 확실히 각성이 <color=#FFB400>너무 빨랐구나</color>.",
  ui_story_1022_10221102_22_dialog_content = "뭐...라고요?",
  ui_story_1022_10221102_23_dialog_content = "각성이 너무 빨랐어. 그래서 너무 순수하고, 단순하며, 원시적이지.\n네 힘에는 일말의 이성을 거친 단련이 없었어.",
  ui_story_1022_10221102_24_dialog_content = "우르슬라, 넌 강해. 하지만 네가 대표하는 건 혈족의 가장 원시적인 욕망이야.",
  ui_story_1022_10221102_25_dialog_content = "그리고 난 너와 아주 머나먼 반대편에 있어.",
  ui_story_1022_10221102_26_dialog_content = "무, 무슨 뜻이죠...?",
  ui_story_1022_10221102_27_dialog_content = "난 너보다 훨씬 늦게 각성했어.",
  ui_story_1022_10221102_28_dialog_content = "하지만 난 진리를 깨닫기 위해 목도하고, 사색하고, 이해하며, 먼 길을 걸어왔어.",
  ui_story_1022_10221102_29_dialog_content = "그건 네가 경험해 본 적도, 상상도 해본 적 없는 길이란다.",
  ui_story_1022_10221102_30_dialog_content = "그럼 내 비술이 얼마나 심오하고 복잡한지는... 직접 상상해 보라고 할 수밖에 없겠구나.",
  ui_story_1022_10221102_31_dialog_content = "왜냐면 넌 영원히 이해할 수 없을 테니까.",
  ui_story_1022_10221102_32_dialog_content = "그, 그럴 리가 없어요! 저야말로 최강이라구요...!",
  ui_story_1022_10221102_33_dialog_content = "<color=#e8d9bb>아무리 고함을 질러도 우르슬라는 공포를 억누를 수 없었다.\n그녀는 천부적인 재능이 있었고, 그 재능은 너무나도 풍족했다.</color>",
  ui_story_1022_10221102_34_dialog_content = "<color=#e8d9bb>때문에 그녀의 마음과, 눈, 영혼 모두 같은 깨달음이 일으키는 극심한 고통에 시달리고 있었다.\n그것은 바로──</color>",
  ui_story_1022_10221102_35_dialog_content = "<color=#FFB400>「법칙」</color>...",
  ui_story_1022_10221102_36_dialog_content = "<color=#e8d9bb>그것은 진리를 위해 온 심혈을 다한 오로리안이 도달한 경지.</color>",
  ui_story_1022_10221102_37_dialog_content = "<color=#e8d9bb>원시를 초월하고, 순수함을 초월하여, 간절히 탐구하는 마음으로 진리를 향해 바친 찬가였다.</color>",
  ui_story_1022_10221102_38_dialog_content = "잘 대답했어, 우르슬라. 지금부터는 실습 시간이란다.",
  ui_story_1022_10221102_39_dialog_content = "그 눈을 부릅뜨고, 확실히 봐 두렴── 나의 비술을.",
  ui_story_1022_10221102_40_dialog_content = "그리고 이건 주께 바치는 것이기도 해.",
  ui_story_1022_10221102_41_dialog_content = "으아아아아아아악──",
  ui_story_1022_10221102_42_dialog_content = "어, 어째서죠...? 전 이미 오래전에 「이클립스」의 표식을 받았는데, 왜...",
  ui_story_1022_10221102_43_dialog_content = "...제가 오로리안으로 돌아가고 있는 거냐구요!",
  ui_story_1022_10221102_44_dialog_content = "시, 싫어... 싫다구요... 죽고싶지 않아... 사라지기 싫어...",
  ui_story_1022_10221102_45_dialog_content = "싫어어어!",
  ui_story_1022_10221102_46_dialog_content = "이 얼마나 무서운 비술이란 말인가... 과연, 그것이 바로 「구원」이었군.",
  ui_story_1022_10221102_47_dialog_content = "그대는 그 「허구」의 물질을 부정하고, 순수한 「본질」을 「의식」의 주께 바친 것인가.",
  ui_story_1022_10221102_48_dialog_content = "훗, 아니지, 무서운 건 비술이 아니라 너 자신이로군, 빅토리아.",
  ui_story_1022_10221102_49_dialog_content = "나조차도 이용하다니, 이제 네 시선에 담기지 않은 게 과연 무엇이 있을지 모르겠군.",
  ui_story_1022_10221102_50_dialog_content = "<color=#e8d9bb>반짝이는 강물이 끝없이 이어지고 있었고, 이 강물 속에서는 시간이 의미를 가지지 않았다.</color>",
  ui_story_1022_10221102_51_dialog_content = "<color=#e8d9bb>무수한 과거와 미래가 은둔자의 눈앞에 나란히 나열되어 있었고,\n그 안에는 심지어 「평행 속 자신」의 모습도 있었다.</color>",
  ui_story_1022_10221102_52_dialog_content = "뭐, 좋다... 이쪽으로 와라.",
  ui_story_1022_10221102_53_dialog_content = "<color=#e8d9bb>은둔자가 손뼉을 치자 공중에 균열이 생겨났고, 기관차 한 대가 허공 속에서 끄집어내졌다.</color>",
  ui_story_1022_10221102_54_dialog_content = "으아아아아──",
  ui_story_1022_10221102_55_dialog_content = "조용히 해라. 나는 오래도록 홀로 지내서 큰 소리는 귀가 못 견딘다.",
  ui_story_1022_10221102_56_dialog_content = "왜 또 이 강인 거냐! 당신은 또 누구지? ...잠깐만... 당신, 본 적 있어.",
  ui_story_1022_10221102_57_dialog_content = "...설마 진작에 사망했던 아버지의 사촌이자 빅토리아의 숙부... <color=#FFB400>빌헬름 왈라키아</color>?",
  ui_story_1022_10221102_58_dialog_content = "말이 길다. 「당숙」이라고 부르면 뭐가 덧난단 말이더냐.",
  ui_story_1022_10221102_59_dialog_content = "이런 해괴한 곳에서 이미 세상을 떠난 사람을 만나서 친근하게 안부나 묻는 게 더 이상하잖아!",
  ui_story_1022_10221102_60_dialog_content = "...머리가 아프다. 빅토리아와 마찬가지로 귀찮은 녀석이로구나.",
  ui_story_1022_10221102_61_dialog_content = "뭐라는 거야? 난 그 정신 나간 여자와는 다르다.",
  ui_story_1022_10221102_62_dialog_content = "형님의 아이를 다 돌보고 나니, 이번에는 친구의 아이인가.\n내 가문 휘장을 젖병과 요람으로 바꿔야 할 지경이로군.",
  ui_story_1022_10221102_63_dialog_content = "카론, 네 이름은 기억하고 있다. 너는 네가 왜 이곳에 왔는지 아느냐.",
  ui_story_1022_10221102_64_dialog_content = "당신이 벌인 짓 아니었나?",
  ui_story_1022_10221102_65_dialog_content = "빅토리아는 네가 나에게 비술을 배우고, 진리를 깨닫기를 원한다.\n그녀는 네게서 그러한 소질이 있음을 보았다.",
  ui_story_1022_10221102_66_dialog_content = "뭐라고?! 그 일이라면 이미 진작에 흥미 없다고 그 여자에게 말했다만.",
  ui_story_1022_10221102_67_dialog_content = "빅토리아에게 그렇게 답했을 때의 너는 확실히 흥미가 없었지.",
  ui_story_1022_10221102_68_dialog_content = "허나 강의 흐름은 이미 앞으로 나아갔고, 다시 강물 속으로 돌아온 너는 이전의 네가 아니다.\n지금의 네 생각은 어떠한가.",
  ui_story_1022_10221102_69_dialog_content = "......",
  ui_story_1022_10221102_70_dialog_content = "<color=#e8d9bb>「당연히 지금도 흥미는 없다」는 대답은 이미 카론의 목구멍까지 올라와 있었다.</color>",
  ui_story_1022_10221102_71_dialog_content = "<color=#e8d9bb>그러나 그 순간 그의 머릿속에는 얼음 기둥 속 바이스의 모습이 떠올랐다.\n그의 부하는 지금 암귀가 꿈틀대는 극야 속에 있는 것이었다.</color>",
  ui_story_1022_10221102_72_dialog_content = "<color=#e8d9bb>그녀는 아이테르를 위해 남겠다고 했다. 이는 아이테르와 행동을 함께하고 있는\n일루미나의 동료들 또한 위험에 처해 있을 가능성이 높다는 의미였다.</color>",
  ui_story_1022_10221102_73_dialog_content = "<color=#e8d9bb>이러한 상황에서 그는...</color>",
  ui_story_1022_10221102_74_dialog_content = "...아무래도 이젠 정말 반항기를 졸업해야 할 시기가 온 모양이군.",
  ui_story_1022_10221102_75_dialog_content = "훗, 누구와는 달리 자신의 반항기를 인지하고 있다니, 가망이 있도다.",
  ui_story_1022_10221102_76_dialog_content = "이번에는 있지도 않은 나의 목숨을 또 걸어야 할 필요는 없겠지.",
  ui_story_1022_10221200_1_dialog_content = "......",
  ui_story_1022_10221200_2_dialog_content = "(얼음 동굴...? 아, 그랬지... 난 처음 주둔했던 임시 기지까지 도망쳤고,\n힘이 빠져서 곯아떨어졌었지.)",
  ui_story_1022_10221200_3_dialog_content = "(빅토리아 님은 아마 우르슬라를 쫓아가셨겠지. 나도 가야 해...)",
  ui_story_1022_10221200_4_dialog_content = "빌어먹을... 보물도, 탈주범도, 전부 눈앞에 두고 이런 실수를 하다니!",
  ui_story_1022_10221200_5_dialog_content = "(어이쿠, 왜 쟤도 여기 있대? 냅다 안 나가서 다행이다.)",
  ui_story_1022_10221200_6_dialog_content = "조장님... 움직이지 마세요... 상처가 벌어질 거예요.",
  ui_story_1022_10221200_7_dialog_content = "(에리카... 내가 다쳤을 때도 걱정하는 표정을 지었었지.)",
  ui_story_1022_10221200_8_dialog_content = "내 상처는 괜찮아. 그것보다 그쪽의 불청객은 무슨 용무일까?",
  ui_story_1022_10221200_9_dialog_content = "이미 전달을 받았을 텐데요. 도움을 드리러 왔습니다.",
  ui_story_1022_10221200_10_dialog_content = "(한 명 더 있었다고...? 아무 기척도 못 느꼈는데...)",
  ui_story_1022_10221200_11_dialog_content = "도움? 우리 전부 페피타를 포위하고도 놓쳤는데, 당신이 어떻게 도울 수 있지?",
  ui_story_1022_10221200_12_dialog_content = "(뭐야, 내 얘기 하는 거야?)",
  ui_story_1022_10221200_13_dialog_content = "물론 가장 확실한 방법을 사용해야겠죠.",
  ui_story_1022_10221200_14_dialog_content = "받으세요.",
  ui_story_1022_10221200_15_dialog_content = "...조종 장치? 설마 이걸 누르면 페피타의 움직임을 멈출 수 있다고 말하려는 건 아니겠지?",
  ui_story_1022_10221200_16_dialog_content = "맞아요.",
  ui_story_1022_10221200_17_dialog_content = "...지금 장난하는 거야?",
  ui_story_1022_10221200_18_dialog_content = "아니요, 거짓말이 아닙니다. 지금 그 장치는 벨리사리아가 당시 보험으로 남겨뒀던 겁니다.",
  ui_story_1022_10221200_19_dialog_content = "그걸로 페피타의 인공 심장을 조종할 수 있죠.",
  ui_story_1022_10221200_20_dialog_content = "!!!",
  ui_story_1022_10221200_21_dialog_content = "페피타의 심장이... 인공 심장이었어?",
  ui_story_1022_10221200_22_dialog_content = "그 버튼만 누르면 인공 심장은 즉시 가동을 멈추게 됩니다.\n그 결과라면... 말씀드릴 필요는 없겠죠.",
  ui_story_1022_10221200_23_dialog_content = "이것보다 더 확실하게, 영구적으로 「움직임을 멈출」 수 있는 방법이 또 있습니까?",
  ui_story_1022_10221200_24_dialog_content = "헛소리 집어치워! 그게 뭐가 움직임을 멈추는 거야? 그건 살인이잖아!",
  ui_story_1022_10221200_25_dialog_content = "죽은 자가 결백한 경우에만 목숨을 빼앗는 것을 살인이라고 할 수 있습니다.",
  ui_story_1022_10221200_26_dialog_content = "하지만 죽은 자가 죄인이라면, 그건 「처형」입니다.",
  ui_story_1022_10221200_27_dialog_content = "그게 무슨 차이라고...",
  ui_story_1022_10221200_28_dialog_content = "당시 페피타가 일루미나를 배반하고 도망쳤을 때, 벨리사리아는 손에 그 장치를 쥐고 있었습니다.",
  ui_story_1022_10221200_29_dialog_content = "하지만 그 사람은 죄인의 뒷모습이 사라지는 것을 바라만 볼 뿐, 손을 쓰지 못했습니다.\n정말... 실망스러웠죠.",
  ui_story_1022_10221200_30_dialog_content = "(벨리사리아...)",
  ui_story_1022_10221200_31_dialog_content = "하지만 당신은 그 이름뿐인 「철가면」과는 다를 거라 믿습니다.",
  ui_story_1022_10221200_32_dialog_content = "백야성의 죄인을 대하는 당신의 각오는 진실하니까요.",
  ui_story_1022_10221200_33_dialog_content = "......",
  ui_story_1022_10221200_34_dialog_content = "안 돼요!",
  ui_story_1022_10221200_35_dialog_content = "조장님, 이런 방식은... 틀린 거잖아요!\n페피타가 잘못을 좀 했을지도 모르지만, 악한 사람은 아니에요!",
  ui_story_1022_10221200_36_dialog_content = "마음의 친구로서... 전 그 애의 눈을 보고 알 수 있었어요.",
  ui_story_1022_10221200_37_dialog_content = "평생 한 번도 잘못을 안 하는 사람이 어딨어요? 게다가 신의 가르침에도 있잖아요?\n설령 죄인이라도 회개할 기회는 줘야 한다고 말이에요!",
  ui_story_1022_10221200_38_dialog_content = "에리카...!",
  ui_story_1022_10221200_39_dialog_content = "...거기 누굽니까?!",
  ui_story_1022_10221200_40_dialog_content = "페피타?! 왜 여기에...",
  ui_story_1022_10221200_41_dialog_content = "잘못 본 거 아냐? 나 없으니까 하던 얘기 마저 해.",
  ui_story_1022_10221200_42_dialog_content = "...잡아라!",
  ui_story_1022_10221200_43_dialog_content = "페피타! 도망치지 마! 멈춰!",
  ui_story_1022_10221200_44_dialog_content = "네 상사가 리모컨 버리면 멈출게!",
  ui_story_1022_10221200_45_dialog_content = "페피타! 널 해치지 않게 내가 막을게! 기다려──",
  ui_story_1022_10221200_46_dialog_content = "그런 말은 승진하고 나서 해.",
  ui_story_1022_10221200_47_dialog_content = "페피타! 그 앞은──",
  ui_story_1022_10221200_48_dialog_content = "소리 그만 질러. 안 멈출 거...야악!",
  ui_story_1022_10221200_49_dialog_content = "<color=#e8d9bb>매서운 찬바람이 발밑을 휘감았고, 하마터면 페피타를 날려버릴 뻔했다.</color>",
  ui_story_1022_10221200_50_dialog_content = "<color=#e8d9bb>한 발짝 너머에는 바닥이 보이지 않는 절벽이 놓여 있었다.</color>",
  ui_story_1022_10221200_51_dialog_content = "페피타! 조심해!",
  ui_story_1022_10221200_52_dialog_content = "...가까이 오지 마.",
  ui_story_1022_10221200_53_dialog_content = "알았어, 안 갈게. 그러니까 너도 움직이지 말고 내 말 들어.",
  ui_story_1022_10221200_54_dialog_content = "성주님이 널 벌하지 않겠다고 동의하셨어. 약속할게, 우리한테 성전에 대한 단서만 알려주면...",
  ui_story_1022_10221200_55_dialog_content = "그 약속을 하는 건 너야? 아니면 성주야?",
  ui_story_1022_10221200_56_dialog_content = "그건...",
  ui_story_1022_10221200_57_dialog_content = "에리카, 넌 아무것도 보장할 수 없지?\n네가 할 수 있는 건 그저 성주가 약속을 지키길 바라는 것뿐이잖아.",
  ui_story_1022_10221200_58_dialog_content = "뭐, 그래도 고마워. 근데 미안해. 난 윗사람 호의를 기대하며 살 생각은 전혀 없거든.",
  ui_story_1022_10221200_59_dialog_content = "<color=#FFB400>자유가 아니면 죽음을!</color>",
  ui_story_1022_10221200_60_dialog_content = "<color=#e8d9bb>페피타는 조금의 망설임도 없이 절벽으로 달려가 뛰어내렸다.</color>",
  ui_story_1022_10221200_61_dialog_content = "페피타──!",
  ui_story_1022_10221200_62_dialog_content = "<color=#e8d9bb>에리카는 재빨리 절벽까지 달려갔지만, 아래에는 구름과 안개가 소용돌이칠 뿐,\n그 어디에도 페피타의 모습은 보이지 않았다.</color>",
  ui_story_1022_10221200_63_dialog_content = "......",
  ui_story_1022_10221200_64_dialog_content = "마지막까지 버튼을 누르지 않고, 눈앞에서 절호의 기회를 놓쳤군요.",
  ui_story_1022_10221200_65_dialog_content = "두 번이나 사람을 잘못 보다니, 저도 반성할 필요가 있겠네요.",
  ui_story_1022_10221200_66_dialog_content = "...에리카 말이 맞아. 녀석은 잘못을 저질렀지만, 죽어 마땅한 사람은 아냐...\n난... 사적인 원한 때문에 사람을 죽이진 않아!",
  ui_story_1022_10221200_67_dialog_content = "당신... 대체 누구야?",
  ui_story_1022_10221200_68_dialog_content = "각오는 부족해도 호기심은 오히려 왕성하네요. 백야성의 이단심문조도 결국 그 정도였군요.",
  ui_story_1022_10221200_69_dialog_content = "페피타 일은 이제 당신들이 신경 쓰지 않아도 돼요.",
  ui_story_1022_10221200_70_dialog_content = "이번 일은 일루미나의 <color=#FFB400>「집행자」</color> 조직이 정식으로 인계하겠습니다.",
  ui_story_1022_10221200_71_dialog_content = "<color=#e8d9bb>어둠의 밑바닥 깊은 곳, 어느 얼음 동굴 앞에서 번개 같은 불꽃이 번뜩였다.</color>",
  ui_story_1022_10221200_72_dialog_content = "무슨 일이... 벌어진 거냐... 내가 어떻게... 「재구성」된 거지?",
  ui_story_1022_10221200_73_dialog_content = "검은 밤, 매서운 추위, 다크매터... 아아, 「이클립스」여... 내가 돌아왔다!\n감사합니다, 나의 신이시여...",
  ui_story_1022_10221200_74_dialog_content = "그분의 자비 덕분에 돌아올 수 있었던 건 당신도 아는 모양이네요.",
  ui_story_1022_10221200_75_dialog_content = "......",
  ui_story_1022_10221200_76_dialog_content = "흥, 다들 여기 있었군.",
  ui_story_1022_10221200_77_dialog_content = "당연하죠, 한참 기다렸어요. 다만 당신이 조금만 더 능력이 있었다면,\n우리가 이렇게 많은 시간을 허비하지도 않았을 텐데 말이에요.",
  ui_story_1022_10221200_78_dialog_content = "큰소리는 잘도 치는군, 아스모데우스. 나는 그분을 위해 적진으로 달려들었는데, 넌 뭘 했지?",
  ui_story_1022_10221200_79_dialog_content = "지금 당장 자난성으로 다시 가야 한대도 나는 두말없이 향할 것이다.",
  ui_story_1022_10221200_80_dialog_content = "당신이 가진 거라곤 이제 그 알량한 만용뿐이네요.",
  ui_story_1022_10221200_81_dialog_content = "...무슨 말을 하려는 거냐.",
  ui_story_1022_10221200_82_dialog_content = "그건 그렇고, 왜 저 녀석이 여기 있는 것이냐. 여덟 팬텀의 회의에 참석할 자격은 없을 텐데.",
  ui_story_1022_10221200_83_dialog_content = "......",
  ui_story_1022_10221200_84_dialog_content = "알고 있잖아요? 피제로, 「이클립스」의 일원이 더 높은 지위를 얻는 방법은 하나뿐인걸요.",
  ui_story_1022_10221200_85_dialog_content = "새로운 사람을 발탁하려면, 오래된 자리 중에서 반드시 누군가는 사라져야 해요.",
  ui_story_1022_10221200_86_dialog_content = "「이클립스」에서 팬텀의 자리는 오직 여덟 개뿐, 일곱 개도, 아홉 개도 아니에요.",
  ui_story_1022_10221200_87_dialog_content = "그, 그 말을 왜 지금 하는 거냐? 내가 묻는 건 왜 노라가 여기 있냐는 거다!",
  ui_story_1022_10221200_88_dialog_content = "어리석은 자에게 총명한 부하는 필요하지 않은 법이죠. 노라가 이룬 일은 당신보다 훨씬 중요해요.",
  ui_story_1022_10221200_89_dialog_content = "「승진」의 <color=#FFB400>재료</color>를 맛보는 건 노라가 마땅히 얻어야 할 포상이에요.",
  ui_story_1022_10221200_90_dialog_content = "!!!",
  ui_story_1022_10221200_91_dialog_content = "뭐, 뭐냐! 감히 날 속박하다니, 누구냐! 놔라!",
  ui_story_1022_10221200_92_dialog_content = "...이런 장면은 보고 싶지 않네요. 먼저 들어갈게요.",
  ui_story_1022_10221200_93_dialog_content = "훗, 저도 딱히 여기 죽치고 있을 필요는 없는걸요.\n노라, 끝나면 들어오세요. 회의 시작해야 하니까요.",
  ui_story_1022_10221200_94_dialog_content = "......",
  ui_story_1022_10221200_95_dialog_content = "......",
  ui_story_1022_10221200_96_dialog_content = "흐, 흐하하하하! 전부 가서 죽여라!",
  ui_story_1022_10221200_97_dialog_content = "그어어어!",
  ui_story_1022_10221200_98_dialog_content = "......",
  ui_story_1022_10221200_99_dialog_content = "강해졌군... 하지만 네가 할 수 있겠나? 각오는 했나? 그만한 배짱이 있냔 말이다.",
  ui_story_1022_10221200_100_dialog_content = "오늘 날 잡아먹는다는 건 앞으로 너도 삼켜지게 될 운명을 받아들인다는 것이다...",
  ui_story_1022_10221200_101_dialog_content = "너보다 더 강하고, 더 인정받는 암귀가 나타나는 순간,\n넌 그의 승진을 위한 먹이가 될 것이다...",
  ui_story_1022_10221200_102_dialog_content = "할 수 있겠나? 이 바닥으로 떨어지는 순간, 다시는 되돌릴 수 없을 거다.",
  ui_story_1022_10221200_103_dialog_content = "...네 마음속엔 아직 미련을 버리지 못한 오로리안이 있을 텐데?!",
  ui_story_1022_10221200_104_dialog_content = "......",
  ui_story_1022_10221200_105_dialog_content = "잡소리는 드디어 다 끝난 거지?",
  ui_story_1022_10221200_106_dialog_content = "우르슬라가... 움직임이 없네요.",
  ui_story_1022_10221200_107_dialog_content = "그래도 공을 세웠다고 할 수 있겠죠.\n목숨을 반쯤 걸어준 덕에 우리도 「그자」의 비술을 볼 수 있었으니까요.",
  ui_story_1022_10221200_108_dialog_content = "진짜 볼거리는 이제부터라구요.",
  ui_story_1022_10221200_109_dialog_content = "...왔어요.",
  ui_story_1022_10221200_110_dialog_content = "어머?",
  ui_story_1022_10221200_111_dialog_content = "<color=#e8d9bb>그림자 속에서 서서히 걸어 나온 모습은 자리에 있는 모든 이의 시선을 사로잡았다.</color>",
  ui_story_1022_10221200_112_dialog_content = "......",
  ui_story_1022_10221200_113_dialog_content = "역시나 특급 신인답다니까요. 후훗... 피제로보다 훨씬 뛰어나잖아요.",
  ui_story_1022_10221200_114_dialog_content = "아뇨... 우르슬라 말이에요.",
  ui_story_1022_10221200_115_dialog_content = "......",
  ui_story_1022_10221200_116_dialog_content = "「<color=#FFB400>X물질</color>」은 추출당하고, 심장은 사라졌고, 신체도 거의 부서졌지만...\n아직 살아 있네요. 심지어 서서히 회복하고 있어요.",
  ui_story_1022_10221200_117_dialog_content = "아무래도 혈족이었기 때문일까요?\n애초에 한번 오염됐던 「본질」, 순수하지 않은 「<color=#FFB400>N물질</color>」이었으니까요.",
  ui_story_1022_10221200_118_dialog_content = "그러니 나중에 주입된 「허구」를 빼앗기고도 여전히 살아있을 수 있는 거겠죠.",
  ui_story_1022_10221200_119_dialog_content = "우르슬라가 만들었던 산호 가지만 돌려주면, 「허구」의...\n「<color=#FFB400>X</color>」의 힘은 돌아오고, 심장은 다시 뛰기 시작할 거예요.",
  ui_story_1022_10221200_120_dialog_content = "<color=#e8d9bb>끽, 끼긱! 끼기긱!</color>",
  ui_story_1022_10221200_121_dialog_content = "페디, 조용히 좀 해... 조금만 더 잘래...",
  ui_story_1022_10221200_122_dialog_content = "...어? 페디?!",
  ui_story_1022_10221200_123_dialog_content = "네가 날 구해준 거야? 넌 어떻게 도망쳤어? 우르슬라는...? 설마 죽은 건 아니겠지?!",
  ui_story_1022_10221200_124_dialog_content = "(아니지, 진정하자, 페디가 아직 움직인다는 건 우르슬라가 살아있다는 거야.\n근데 페디가 도망칠 수 있었다는 건 우르슬라에게 무슨 일이 생겼다는 거잖아...)",
  ui_story_1022_10221200_125_dialog_content = "(...잠깐만, 내가 왜 아직도 걜 걱정하는 건데?!)",
  ui_story_1022_10221200_126_dialog_content = "(휴, 생사불명의 우르슬라, 죽었다 살아난 페피타... 사고뭉치들끼리 꽤 잘 어울리네.)",
  ui_story_1022_10221200_127_dialog_content = "<color=#e8d9bb>끼기긱!\n페디는 페피타의 다리를 붙잡았고, 이상하게 흥분해 있었다.</color>",
  ui_story_1022_10221200_128_dialog_content = "그래그래, 너네 주인이 걱정되는 거지? 어? 아니라고? 그럼 왜── 으아아아!",
  ui_story_1022_10221200_129_dialog_content = "<color=#e8d9bb>허공에 균열이 생기더니, 틈 사이로 기관차가 굉음과 함께 튀어나왔다.</color>",
  ui_story_1022_10221200_130_dialog_content = "기, 기기기, 기차?!",
  ui_story_1022_10221200_131_dialog_content = "이 황량한 어둠의 밑바닥에서, 손님을 잘 모시는 열차장은\n홀로 남겨진 오로리안의 위기를 외면하지 않는다.",
  ui_story_1022_10221200_132_dialog_content = "어떠한가, 아가씨. 이 화려한 기차에 함께 오르지 않겠나?"
}
